--
-- Name: generar_lorem_ajustado(integer); Type: FUNCTION; Schema: anon; Owner: postgres
--

CREATE FUNCTION anon.generar_lorem_ajustado(largo_objetivo integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    palabras_estimadas INT;
    texto_crudo TEXT;
BEGIN
    IF largo_objetivo <= 0 THEN RETURN ''; END IF;
    palabras_estimadas := (largo_objetivo / 5) + 5;
    texto_crudo := anon.lorem_ipsum(palabras_estimadas);
    WHILE length(texto_crudo) < largo_objetivo LOOP
        texto_crudo := texto_crudo || ' ' || anon.lorem_ipsum(5);
    END LOOP;
    RETURN substring(initcap(texto_crudo), 1, largo_objetivo);
END;
$$;


ALTER FUNCTION anon.generar_lorem_ajustado(largo_objetivo integer) OWNER TO postgres;

--
-- Name: html_math_aware_mask(text); Type: FUNCTION; Schema: anon; Owner: postgres
--

CREATE FUNCTION anon.html_math_aware_mask(input_text text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    fragment RECORD;
    output_text TEXT := '';
    in_math_block BOOLEAN := false;
    is_tag BOOLEAN;
    clean_content TEXT;
    fragment_length INT;
BEGIN
    IF input_text IS NULL THEN RETURN NULL; END IF;
    FOR fragment IN SELECT match[1] AS token FROM regexp_matches(input_text, '(<[^>]+>|[^<]+)', 'g') AS match LOOP
        is_tag := (substring(fragment.token, 1, 1) = '<');
        IF is_tag THEN
            IF fragment.token ILIKE '<math%' THEN in_math_block := true; END IF;
            output_text := output_text || fragment.token;
            IF fragment.token ILIKE '</math>' THEN in_math_block := false; END IF;
        ELSE
            clean_content := regexp_replace(fragment.token, '\s+', '', 'g');
            fragment_length := length(fragment.token);
            IF in_math_block THEN
                output_text := output_text || fragment.token;
            ELSIF length(clean_content) > 0 THEN
                output_text := output_text || anon.generar_lorem_ajustado(fragment_length);
            ELSE
                output_text := output_text || fragment.token;
            END IF;
        END IF;
    END LOOP;
    RETURN output_text;
END;
$$;


ALTER FUNCTION anon.html_math_aware_mask(input_text text) OWNER TO postgres;

--
-- Name: fn_audit_trigger(); Type: FUNCTION; Schema: audit; Owner: postgres
--

CREATE FUNCTION audit.fn_audit_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    DECLARE
        v_old_data       JSONB;
        v_new_data       JSONB;
        v_old_clean      JSONB;
        v_new_clean      JSONB;
        v_record         JSONB;
        v_transaction_id UUID;
        v_changed_by     BIGINT;
        v_company_id     INTEGER;
        v_key            TEXT;
    BEGIN
        -- Verifica si la tabla tiene auditoría activa
        IF NOT EXISTS (
            SELECT 1 FROM audit.audit_config
            WHERE table_name = TG_TABLE_NAME
            AND fl_active = true
        ) THEN
            RETURN COALESCE(NEW, OLD);
        END IF;

        -- Reutiliza transaction_id si ya existe en la sesión, sino genera uno nuevo
        IF current_setting('app.transaction_audit_id', true) IS NULL
            OR current_setting('app.transaction_audit_id', true) = '' THEN
            PERFORM set_config(
                'app.transaction_audit_id',
                gen_random_uuid()::text,
                true
            );
        END IF;

        v_transaction_id := NULLIF(current_setting('app.transaction_audit_id', true), '')::UUID;

        IF TG_OP = 'DELETE' THEN
            v_old_data   := row_to_json(OLD)::JSONB;
            v_new_data   := NULL;
            v_record     := v_old_data;

        ELSIF TG_OP = 'UPDATE' THEN
            v_old_data  := row_to_json(OLD)::JSONB;
            v_record    := row_to_json(NEW)::JSONB;

            -- Excluir updated_by y updated_at de ambos lados antes de comparar
            v_old_clean := v_old_data - 'updated_by' - 'updated_at';
            v_new_clean := v_record   - 'updated_by' - 'updated_at';

            -- Si no hubo cambios reales, no registrar
            IF v_old_clean = v_new_clean THEN
                RETURN NEW;
            END IF;

            -- Guardar solo los campos que cambiaron
            v_new_data := '{}'::JSONB;
            FOR v_key IN SELECT key FROM jsonb_object_keys(v_new_clean) AS key
            LOOP
                IF (v_new_clean -> v_key) IS DISTINCT FROM (v_old_clean -> v_key) THEN
                    v_new_data := v_new_data || jsonb_build_object(v_key, v_new_clean -> v_key);
                END IF;
            END LOOP;

            IF v_new_data = '{}'::JSONB THEN
                RETURN NEW;
            END IF;
        END IF;

        -- Leer changed_by según operación y tabla
        IF TG_OP = 'DELETE' THEN
            IF TG_TABLE_NAME = 'users_roles' THEN
                v_changed_by := (v_old_data ->> 'updated_by')::BIGINT;
            ELSE
                v_changed_by := (v_old_data ->> 'deleted_by')::BIGINT;
            END IF;
        ELSIF TG_OP = 'UPDATE' THEN
            v_changed_by := (v_record ->> 'updated_by')::BIGINT;
        END IF;
        v_company_id := (v_record ->> 'company_id')::INTEGER;

        INSERT INTO audit.audit_log (
            transaction_id,
            table_name,
            record_id,
            action,
            old_data,
            new_data,
            changed_by,
            changed_at,
            company_id
        )
        VALUES (
            v_transaction_id,
            TG_TABLE_NAME,
            CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END::VARCHAR,
            TG_OP,
            v_old_data,
            v_new_data,
            v_changed_by,
            NOW(),
            v_company_id
        );

        RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
    END;
    $$;


ALTER FUNCTION audit.fn_audit_trigger() OWNER TO postgres;

--
-- Name: on_function_event(); Type: FUNCTION; Schema: audit; Owner: postgres
--

CREATE FUNCTION audit.on_function_event() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN
        INSERT INTO audit.function_log (datetime, schema_name, function_name, tag, function_body)
        SELECT
            NOW(),
            nspname,
            proname,
            command_tag,
            pg_get_functiondef(p.oid)
        FROM pg_event_trigger_ddl_commands() e
        JOIN pg_proc p      ON p.oid = e.objid
        JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE nspname = 'odiseo';
    END;
    $$;


ALTER FUNCTION audit.on_function_event() OWNER TO postgres;

--
-- Name: change_status_verified_question(integer, character varying, character varying, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.change_status_verified_question(p_question_id integer, p_status character varying, p_observations character varying, p_user_id integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_exit_question BOOLEAN;
            v_message TEXT := '';
            v_user_name VARCHAR;
            v_new_status VARCHAR;
            v_old_status VARCHAR;
        BEGIN

            -- Obtener nombre del usuario
            SELECT CASE
                    WHEN e.id IS NOT NULL
                    THEN CONCAT(e.first_name, ' ', LEFT(e.first_surname, 1), '. ', e.second_surname)
                    ELSE 'Admin'
                END AS user
            INTO v_user_name
            FROM users u
            LEFT JOIN employees e ON u.id = e.user_id
            WHERE u.id = p_user_id;

            -- Validación: Verificar si la pregunta existe y cumple las condiciones
            SELECT COUNT(*) > 0
            INTO v_exit_question
            FROM question
            WHERE status IN ('APRB', 'VERI', 'PEND', 'RESV')
            AND fl_status = TRUE
            AND id = p_question_id;

            IF NOT v_exit_question THEN
                RETURN json_build_object(
                        'status', 409,
                        'message', 'No existe la pregunta o no se encuentra en estado VERIFICADO o STAND BY con el id: ' || p_question_id
                    );
            END IF;

            -- Actualización según el estado deseado
            CASE p_status
                WHEN 'PEND' THEN
                    UPDATE question
                    SET status = p_status
                    WHERE id = p_question_id;

                    UPDATE question_status
                    SET fl_active = false
                    WHERE question_id = p_question_id;

                    INSERT INTO question_status (question_id, status, fl_active, process, description, created_by, created_at)
                            VALUES (p_question_id, 'PEND', true, 'PENDIENTE',
                                'La pregunta fue cambiado al estado stand by por el usuario <span class=''text-user''>' || v_user_name || '</span>',
                                p_user_id, NOW());

                    -- Añadir observaciones en la tabla question_observation
                    IF p_observations IS NOT NULL THEN
                        INSERT INTO question_observation (question_id, description, type, created_by, created_at)
                                VALUES (p_question_id, p_observations, 'PEND', p_user_id, NOW());
                    END IF;
                    v_message := 'Se cambio el estado de la pregunta a Stand By exitosamente';

                WHEN 'RESV' THEN
                    UPDATE question
                    SET status = p_status,
                        resv_to_veri_at = NOW() + INTERVAL '4 weeks'
                    WHERE id = p_question_id;

                    UPDATE question_status
                    SET fl_active = false
                    WHERE question_id = p_question_id;

                    INSERT INTO question_status (question_id, status, fl_active, process, description, created_by, created_at)
                    VALUES (p_question_id, 'RESV', true, 'RESERVA',
                                'La pregunta fue cambiado al estado reserva  por el usuario <span class=''text-user''>' || v_user_name || '</span>', 
                                p_user_id, NOW());

                    -- Añadir observaciones en la tabla question_observation
                    IF p_observations IS NOT NULL THEN
                        INSERT INTO question_observation (question_id, description, type, created_by, created_at)
                                VALUES (p_question_id, p_observations, 'RESV', p_user_id, NOW());
                    END IF;

                    v_message := 'Se cambio el estado de la pregunta a Reserva exitosamente';

                WHEN 'VERI' THEN
                    SELECT status
                    INTO v_old_status
                    FROM question
                    WHERE id = p_question_id;

                    IF v_old_status = 'PEND' OR v_old_status = 'RESV' THEN
                        UPDATE question
                        SET status = p_status
                        WHERE id = p_question_id;

                        UPDATE question_status
                        SET fl_active = false
                        WHERE question_id = p_question_id;

                        INSERT INTO question_status (question_id, status, fl_active, process, description, created_by, created_at)
                        VALUES (p_question_id, 'VERI', true, 'VERIFICADO',
                        'La pregunta fue cambiado al estado verificado por el usuario <span class=''text-user''>' || v_user_name || '</span>',
                        p_user_id, NOW());

                        -- Quitando la observación de la tabla question_observation
                        UPDATE question_observation
                        SET fl_status = false
                        WHERE question_id = p_question_id AND type = v_old_status;

                        v_message := 'Se cambio el estado de la pregunta a Verificado exitosamente';

                    END IF;

                WHEN 'APRB' THEN
                    SELECT status
                    INTO v_old_status
                    FROM question
                    WHERE id = p_question_id;

                    -- Si el estado anterior es VERI continua
                    IF v_old_status = 'VERI' THEN

                        -- Actualiza el estado de la pregunta a APRB
                        UPDATE question
                        SET status = p_status
                        WHERE id = p_question_id;

                        -- Inserta data para que se visualice en el historial
                        INSERT INTO question_status (question_id, status, fl_active, process, description, created_by, created_at)
                        VALUES (p_question_id, 'APRB', true, 'APROBADO',
                        'La pregunta fue cambiado al estado aprobado por el usuario <span class=''text-user''>' || v_user_name || '</span>',
                        p_user_id, NOW());

                        -- Quitando la observación de la tabla question_observation
                        UPDATE question_observation
                        SET fl_status = false
                        WHERE question_id = p_question_id AND type = v_old_status;
                    END IF;

                    v_message := 'Se cambio el estado de la pregunta a Aprobado exitosamente';

                ELSE
                    RETURN json_build_object(
                            'status', 409,
                            'message', 'El parámetro del estado de la pregunta no coincide : ' || p_status
                        );
            END CASE;

            SELECT status
            INTO v_new_status
            FROM question
            WHERE id = p_question_id;

            -- Retorno exitoso
            RETURN json_build_object(
                    'status', 200,
                    'message', v_message,
                    'question_status', v_new_status
                );

        END;
        $$;


ALTER FUNCTION odiseo.change_status_verified_question(p_question_id integer, p_status character varying, p_observations character varying, p_user_id integer) OWNER TO postgres;

