--
-- Name: fn_activate_schema_origin_university(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_activate_schema_origin_university(p_id bigint, p_updated_by bigint) RETURNS TABLE(v_validated boolean, v_id bigint)
    LANGUAGE plpgsql
    AS $$
    DECLARE
        v_exists_id BIGINT;
        v_material_id BIGINT;
    BEGIN
        SELECT id INTO v_exists_id
        FROM origin_university
        WHERE id = p_id
        AND deleted_by IS NULL
        LIMIT 1;

        SELECT id INTO v_material_id FROM material
        WHERE university_id = p_id
        AND fl_status = true
        LIMIT 1;

        IF v_exists_id IS NOT NULL AND v_material_id IS NULL THEN
            UPDATE origin_university
            SET fl_active = NOT fl_active,
                updated_by = p_updated_by,
                updated_at = now()
            WHERE id = p_id
            RETURNING id INTO v_id;
            RETURN QUERY SELECT TRUE, v_id;
        ELSE
            RETURN QUERY SELECT FALSE, 0::BIGINT;
        END IF;
    END;
    $$;


ALTER FUNCTION odiseo.fn_activate_schema_origin_university(p_id bigint, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_add_question_bank_ia(bigint, bigint, smallint, bigint, character varying, text, character varying, character varying, integer, text, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_add_question_bank_ia(p_question_ia_id bigint, p_config_alternative_id bigint, p_columns smallint, p_created_by bigint, p_observation character varying, p_similary text, p_status character varying, p_status_text character varying, p_level_id integer, p_description_level text, p_diagram_params jsonb) RETURNS TABLE(question_id bigint, code character varying, status character varying, teacher text, date_revised timestamp without time zone, code_course character varying, course character varying, nq_question_key uuid, level character varying, old_level character varying)
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_question_id       BIGINT;
                v_answer_id         BIGINT;
                v_teacher           TEXT;
                v_employee_neuro_id BIGINT;
                v_course_id         BIGINT;
                v_new_number        TEXT;
                v_new_code          TEXT;
            BEGIN
                SELECT e.id INTO v_employee_neuro_id
                FROM employees e
                WHERE e.first_name = 'NEURO'
                  AND e.first_surname = 'QUEST';

                -- 2.1 GENERACION DE CODIGO
                SELECT qtia.course_id INTO v_course_id
                FROM question_teacher_ia qtia
                WHERE qtia.id = p_question_ia_id;

                SELECT full_code, number_str INTO v_new_code, v_new_number
                FROM fn_generate_question_code(v_course_id::INTEGER,'P'::VARCHAR);

                WITH tbl_question_teacher_ia AS ( -- Se trae la data de pregunta IA
                    SELECT
                        qtia.id,
                        qtia.description,
                        qtia.description_short,
                        qtia.course_id,
                        qtia.topic_id,
                        qtia.subtopic_id,
                        qtia.level_id,
                        qtia.answer_id,
                        qtia.answer_description,
                        qtia.theoretical_basis,
                        qtia.argumentation,
                        CASE
                            WHEN qtia.type = 'DECO' THEN 'D'
                            WHEN qtia.type = 'TRADICIONAL' THEN 'T'
                            ELSE null
                        END AS type,
                        qtia.teacher_id
                    FROM question_teacher_ia qtia
                    INNER JOIN alternative_questions_ia aqia ON qtia.id = aqia.question_ia_id
                        AND qtia.answer_id = aqia.id
                    WHERE qtia.id = p_question_ia_id
                        AND qtia.status_revised = false
                ), get_teacher_exists AS ( -- Si no tiene docente se usa el docente GPT
                    SELECT
                        e.id AS teacher_id,
                        TRIM(CONCAT(e.first_name, ' ', e.first_surname, ' ', e.second_surname)) AS teacher
                    FROM employees e
                    WHERE id = COALESCE(
                        (SELECT tqtia.teacher_id FROM tbl_question_teacher_ia tqtia),
                        136
                    )
                    LIMIT 1
                ), update_question_ia_revised AS ( -- Se actualiza el estado y se asigna el docente GPT si no lo tiene
                    UPDATE question_teacher_ia qtia
                    SET
                        status_revised  = true,
                        teacher_id      = COALESCE(tqti.teacher_id, 136),
                        level_id        = COALESCE(p_level_id, tqti.level_id),
                        level_old_id    = tqti.level_id,
                        level_description = p_description_level,
                        updated_by      = p_created_by,
                        updated_at      = NOW()
                    FROM tbl_question_teacher_ia tqti
                    WHERE qtia.id = p_question_ia_id
                        AND tqti.id = p_question_ia_id
                    RETURNING qtia.level_id
                ), generate_code AS ( -- Genera el código de la pregunta
                    SELECT
                        LPAD((COALESCE(MAX(q.number::INT), 0) + 1)::TEXT, 7, '0') AS number,
                        CONCAT(c.code, '-', LPAD((COALESCE(MAX(q.number::INT), 0) + 1)::TEXT, 7, '0')) AS code_course
                    FROM question q
                    INNER JOIN course c ON q.course_id = c.id
                    WHERE q.course_id = (SELECT tqt.course_id FROM tbl_question_teacher_ia tqt)
                    GROUP BY c.code
                ), insert_question AS ( -- Inserta la pregunta en la base de datos
                    INSERT INTO question (
                        code, description, short_description, number,
                        course_id, topic_id, level_id, type, columns,
                        status, config_alternative_id, fl_diagrammed,
                        ia_generated, created_by, created_at
                    )
                    SELECT
                        v_new_code, tqtia.description, tqtia.description_short, v_new_number,
                        tqtia.course_id, tqtia.topic_id, uqir.level_id, tqtia.type, p_columns,
                        p_status, p_config_alternative_id, true, true, p_created_by, NOW()
                    FROM tbl_question_teacher_ia tqtia,
                        generate_code gc,
                        update_question_ia_revised uqir
                    RETURNING id AS question_id
                ), get_alternatives AS ( -- Se lista las alternativas
                    SELECT aqia.description, aqia.option, qtia.answer_id
                    FROM alternative_questions_ia aqia
                    LEFT JOIN question_teacher_ia qtia ON aqia.id = qtia.answer_id
                    WHERE aqia.question_ia_id = p_question_ia_id
                ), insert_alternatives AS ( -- Se inserta las alternativas
                    INSERT INTO alternative AS a (description, question_id, created_by, created_at)
                    SELECT ga.description, iq.question_id, p_created_by, NOW()
                    FROM get_alternatives ga, insert_question iq
                    ORDER BY ga.option
                    RETURNING a.id, a.description, a.question_id
                ), get_alternative_correct AS ( -- Se lista la alternativa correcta
                    SELECT a.id, a.description, a.question_id, gte.teacher
                    FROM insert_alternatives a, get_teacher_exists gte
                    WHERE TRIM(a.description) = (SELECT TRIM(ga.description) FROM get_alternatives ga WHERE ga.answer_id IS NOT NULL LIMIT 1)
                        AND a.question_id = (SELECT iq.question_id FROM insert_question iq)
                    LIMIT 1
                ), get_images_description AS (
                    SELECT qiai.code, qiai.extension, qiai.image
                    FROM question_ia_images qiai
                    WHERE qiai.question_ia_id = p_question_ia_id AND qiai.fl_status = true
                ), insert_images_description AS (
                    INSERT INTO question_image (code, extension, image, question_id)
                    SELECT gid.code, gid.extension, gid.image, iq.question_id
                    FROM get_images_description gid, insert_question iq
                ), get_images_alternatives AS (
                    SELECT aiai.code, aiai.extension, aiai.image
                    FROM alternative_ia_images aiai
                    INNER JOIN alternative_questions_ia aqia ON aiai.alternative_ia_id = aqia.id
                    WHERE aqia.question_ia_id = p_question_ia_id AND aiai.fl_status = true
                ), insert_images_alternatives AS (
                    INSERT INTO question_image (code, extension, image, question_id)
                    SELECT gia.code, gia.extension, gia.image, iq.question_id
                    FROM get_images_alternatives gia, insert_question iq
                ), insert_teacher_question AS ( -- Se asigna la pregunta al docente
                    INSERT INTO employee_question (teacher_id, question_id, week, year, solved, created_by, created_at)
                    SELECT gte.teacher_id, iq.question_id,
                        EXTRACT(WEEK FROM CURRENT_DATE)::INT,
                        EXTRACT(YEAR FROM CURRENT_DATE)::INT,
                        true, p_created_by, NOW()
                    FROM get_teacher_exists gte, insert_question iq
                ), insert_subtopic_question AS ( -- Se inserta el subtema de la pregunta
                    INSERT INTO question_subtopic (question_id, subtopic_id, created_by, created_at)
                    SELECT iq.question_id, tqtia.subtopic_id, p_created_by, NOW()
                    FROM tbl_question_teacher_ia tqtia, insert_question iq
                ), insert_didi_question AS ( -- Se asigna al didi la pregunta
                    INSERT INTO employee_didi_question AS edq (
                        employee_id, question_id, week, year, diagrammed, created_by, created_at
                    )
                    SELECT v_employee_neuro_id, iq.question_id,
                        EXTRACT(WEEK FROM CURRENT_DATE)::INT,
                        EXTRACT(YEAR FROM CURRENT_DATE)::INT,
                        true, p_created_by, NOW()
                    FROM insert_question iq
                    RETURNING edq.id AS employee_didi_question_id
                ), insert_origin_nq AS ( -- Se inserta la relación de la pregunta ia con la pregunta banco
                    INSERT INTO origin_question_nq (question_ia_id, question_id, date_revised, created_by, created_at)
                    SELECT p_question_ia_id, iq.question_id, NOW(), p_created_by, NOW()
                    FROM insert_question iq
                ), tbl_rol_user AS ( -- Se obtiene el rol del usuario que creó
                    SELECT
                        r.name AS rol,
                        CASE
                            WHEN e.user_id IS NOT NULL THEN
                                CONCAT(split_part(e.first_name, ' ', 1), ' ', upper(left(e.first_surname, 1)), '. ', e.second_surname)
                            ELSE 'admin-odiseo'
                        END AS user_name
                    FROM users_roles ur
                    INNER JOIN roles r ON ur.rol_id = r.id
                    LEFT JOIN users u ON ur.user_id = u.id
                    LEFT JOIN employees e ON u.id = e.user_id
                    WHERE ur.user_id = p_created_by
                ), insert_status_question AS ( -- Se inserta el estado de la pregunta
                    INSERT INTO question_status (question_id, status, process, description, fl_active, created_by, created_at)
                    SELECT
                        ia.question_id, p_status, p_status_text,
                        CONCAT('La pregunta generada de NQ ha sido ', LOWER(p_status_text), ' por el ', tru.rol,
                            ' <span class="text-teacher">', tru.user_name, '</span>'),
                        true, p_created_by, NOW()
                    FROM insert_question ia, tbl_rol_user tru
                ), get_setting_diagrammed AS ( -- Se obtiene los nombres de diagramación del curso
                    SELECT sdc.id, sdc.course_id, sdc.field_diagram_id
                    FROM setting_diagrammed_courses sdc
                    WHERE sdc.fl_status = true
                        AND sdc.course_id = (SELECT tqtia.course_id FROM tbl_question_teacher_ia tqtia)
                ), insert_diagram_params AS ( -- Se inserta los parámetros de diagramación desde p_diagram_params
                    INSERT INTO employee_didi_question_field (
                        employee_didi_question_id,
                        setting_diagrammed_course_id,
                        value,
                        created_by,
                        created_at
                    )
                    SELECT
                        edq.employee_didi_question_id,
                        sdc.id,
                        (param->>'cleanedHtml'),
                        p_created_by,
                        NOW()
                    FROM insert_didi_question edq,
                        get_setting_diagrammed sdc,
                        jsonb_array_elements(p_diagram_params) AS param
                    WHERE sdc.field_diagram_id = (param->>'fieldSolutionId')::BIGINT
                ), get_images_solution AS (
                    SELECT siai.code, siai.extension, siai.image
                    FROM solution_ia_images siai
                    WHERE siai.solution_ia_id = p_question_ia_id AND siai.fl_status = true
                ), insert_images_solution AS (
                    INSERT INTO employee_didi_question_field_image(code, extension, image, employee_didi_question_id)
                    SELECT gis.code, gis.extension, gis.image, edq.employee_didi_question_id
                    FROM get_images_solution gis, insert_didi_question edq
                )
                SELECT gac.question_id, gac.id, gac.teacher
                INTO v_question_id, v_answer_id, v_teacher
                FROM get_alternative_correct gac;

                UPDATE question q
                SET answer_id = v_answer_id
                WHERE q.id = v_question_id;

                -- Registrar preguntas compartidas si el subtema está configurado como compartido
                PERFORM fn_insert_question_shares(
                    v_question_id,
                    (SELECT tqtia.subtopic_id FROM question_teacher_ia tqtia WHERE tqtia.id = p_question_ia_id)::SMALLINT,
                    v_course_id::INTEGER,
                    p_created_by
                );

                IF p_observation IS NOT NULL AND p_observation <> '' THEN
                    INSERT INTO question_observation (
                        description, similitaries, question_id, type, fl_status, created_by, created_at
                    )
                    VALUES (p_observation, p_similary, v_question_id, 'DUPL', true, p_created_by, NOW());
                END IF;

                RETURN QUERY
                SELECT DISTINCT
                    q.id AS question_id,
                    q.code,
                    q.status,
                    v_teacher,
                    oqnq.date_revised,
                    c.code AS code_course,
                    c.name AS course,
                    qti.nq_question_key,
                    l.name level,
                    l2.name old_level
                FROM question q
                INNER JOIN origin_question_nq oqnq ON oqnq.question_id = q.id
                INNER JOIN question_teacher_ia qti ON qti.id = oqnq.question_ia_id
                INNER JOIN course c ON q.course_id = c.id
                INNER JOIN level l ON l.id = qti.level_id
                INNER JOIN level l2 ON l2.id = qti.level_old_id
                WHERE q.id = v_question_id
                    AND oqnq.question_ia_id = p_question_ia_id;
            END;
            $$;


ALTER FUNCTION odiseo.fn_add_question_bank_ia(p_question_ia_id bigint, p_config_alternative_id bigint, p_columns smallint, p_created_by bigint, p_observation character varying, p_similary text, p_status character varying, p_status_text character varying, p_level_id integer, p_description_level text, p_diagram_params jsonb) OWNER TO postgres;

--
-- Name: fn_amount_parent_question_category(bigint, smallint, smallint, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_amount_parent_question_category(p_material_id bigint, p_type_material_id smallint, p_week smallint, p_courses jsonb) RETURNS TABLE(category_id bigint, subcategory_id bigint, type_material_id smallint, course_id bigint, course_name character varying, material character varying, category character varying, subcategory character varying, topic_subquestions jsonb, position_initial bigint, position_text smallint)
    LANGUAGE plpgsql
    AS $$
    DECLARE
            v_cycle_id BIGINT;
            v_university_id SMALLINT;
    BEGIN
    SELECT m.cycle_id, m.university_id INTO v_cycle_id, v_university_id
    FROM odiseo.material m WHERE m.id = p_material_id LIMIT 1;

    RETURN QUERY
    SELECT 
    tt.id AS category_id,
    tts.id AS subcategory_id,
    tm.id AS type_material_id,
    s.course_id,
    c."name" AS course_name,
    tm.description AS material,
    tt.name AS category,
    tts.name AS subcategory,
    (
        SELECT jsonb_agg(
            jsonb_build_object(
                'topic_id', t.id,
                'subtopic_id', stc.subtopic_id,
                'quantity', stc.quantity
            )
        ) AS topic_subquestions
        FROM syllabus_text_content stc
        JOIN subtopic sub ON sub.id = stc.subtopic_id
        JOIN topic t ON t.id = sub.topic_id
        WHERE stc.syllabus_text_id = st.id AND stc.fl_status = true
    ) AS topic_subquestions,
    (ROW_NUMBER() OVER (ORDER BY tt.position, tts.id) - 1) AS position_initial,
    tt.position position_text
    FROM syllabus s
    JOIN course c 
        ON c.id = s.course_id

    JOIN syllabus_text_weeks stw 
        ON stw.syllabus_id = s.id 
        AND stw.fl_status = true

    JOIN syllabus_text_distributions std 
        ON std.syllabus_text_week_id = stw.id 
        AND std.fl_status = true

    JOIN type_material tm 
        ON tm.id = std.type_material_id

    JOIN syllabus_texts st 
        ON st.syllabus_text_distribution_id = std.id 
        AND st.fl_status = true

    JOIN type_text tt 
        ON tt.id = st.type_text_id

    JOIN type_text_subcategories tts 
        ON tts.id = st.type_text_subcategory_id

    WHERE std.type_material_id = p_type_material_id
        AND s.university_id = v_university_id
        AND s.cycle_id = v_cycle_id
        AND stw.week = p_week
        AND s.course_id IN (
            SELECT jsonb_array_elements_text(p_courses)::BIGINT
        )
    ORDER BY tt.id, tts.id;

    END;
$$;


ALTER FUNCTION odiseo.fn_amount_parent_question_category(p_material_id bigint, p_type_material_id smallint, p_week smallint, p_courses jsonb) OWNER TO postgres;

--
-- Name: fn_amount_parent_question_level(bigint, smallint, smallint, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_amount_parent_question_level(p_material_id bigint, p_type_material_id smallint, p_week smallint, p_courses jsonb) RETURNS TABLE(number_of_passages integer, level_id bigint, level_name character varying, description character varying, course_id bigint)
    LANGUAGE plpgsql
    AS $$
	DECLARE
            v_cycle_id BIGINT;
            v_university_id SMALLINT;
            v_headquarte_id BIGINT;
	BEGIN
		SELECT m.cycle_id, m.university_id, m.headquarte_id
		INTO v_cycle_id, v_university_id, v_headquarte_id 
		FROM odiseo.material m WHERE m.id = p_material_id LIMIT 1;

		RETURN QUERY
		SELECT 
			dlswp.number_of_passages,
			dlswp.level_id,
			l."name" level_name,
			l.description,
			ls.course_id
		FROM detail_level_syllabus_weeks_parents dlswp 
		JOIN level_syllabus_weeks lsw ON lsw.id = dlswp.level_syllabus_weeks_id
		JOIN level_syllabus ls on ls.id = lsw.level_syllabus_id
		JOIN "level" l ON l.id = dlswp.level_id
		WHERE dlswp.fl_status = TRUE
		AND dlswp.type_material_id = p_type_material_id
		AND ls.fl_status = TRUE
		AND ls.headquarter_id = v_headquarte_id
		AND ls.cycle_id = v_cycle_id
        AND ls.university_id = v_university_id
		AND ls.course_id IN (SELECT JSONB_ARRAY_ELEMENTS_TEXT(p_courses)::SMALLINT)
		AND lsw.week = p_week;

	END;
$$;


ALTER FUNCTION odiseo.fn_amount_parent_question_level(p_material_id bigint, p_type_material_id smallint, p_week smallint, p_courses jsonb) OWNER TO postgres;

--
-- Name: fn_archived_parent_questions(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_archived_parent_questions(p_parent_question_id bigint, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
            BEGIN
                WITH archived_parent_question AS (
                    UPDATE parent_question pq
                    SET status = 'ARCH'
                    WHERE pq.id = p_parent_question_id
                ), user_created AS (
                    SELECT
                        CASE WHEN e.id IS NULL
                            THEN 'Administrador'
                            ELSE concat(
                                split_part(e.first_name, ' ', 1),
                                ' ',
                                upper(left(e.first_surname, 1)),
                                '. ',
                                e.second_surname
                            )
                            END user_name,
                            COALESCE(r.name, 'usuario') rol
                    FROM users u
                    JOIN users_roles ur ON u.id = ur.user_id
                        AND ur.fl_status = true
                    JOIN roles r ON ur.rol_id = r.id
                    LEFT JOIN employees e ON u.id = e.user_id
                    WHERE u.id = p_updated_by
                ), desription_archived AS (
                    SELECT
                        CONCAT(
                            'La pregunta ha sido archivada por el ',
                            uc.rol,
                            ' <span class="text-user">',
                            uc.user_name,
                            '</span>'
                        )::VARCHAR description,
                        'ARCHIVADO'::VARCHAR process,
                        'ARCH'::VARCHAR "status"
                    FROM user_created uc
                    LIMIT 1
                ), subquestion AS (
                    SELECT
                        q.id,
                        da.description,
                        da.process,
                        da.status
                    FROM question q, desription_archived da
                    WHERE q.parent_id = p_parent_question_id
                    AND q.fl_status = true
                ), desactive_status AS (
                    UPDATE question_status
                    SET fl_active = false
                    WHERE question_id IN (
                        SELECT id
                        FROM subquestion
                    )
                )
                INSERT INTO question_status (
                    question_id,
                    status,
                    process,
                    description,
                    created_by,
                    created_at
                )
                SELECT
                    q.id,
                    q.status,
                    q.process,
                    q.description,
                    p_updated_by,
                    NOW()
                FROM subquestion q;

                RETURN;
            END;
            $$;


ALTER FUNCTION odiseo.fn_archived_parent_questions(p_parent_question_id bigint, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_archived_question(integer, integer, integer, character varying, integer, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_archived_question(p_perpage integer, p_npage integer, p_employee_id integer, p_name_text character varying, f_course_id integer, f_type character varying) RETURNS TABLE(key_question text, id bigint, code character varying, short_description text, number_question character varying, number character varying, course_id smallint, code_course character varying, course character varying, status character varying, fl_status boolean, parent_id bigint, type_question text, subquestions jsonb, created_by bigint, date_status timestamp without time zone, observation text, similitaries text, user_name character varying, user_email odiseo.email_citext, total bigint)
    LANGUAGE plpgsql
    AS $$
                                        DECLARE
                                            offset_val INTEGER := p_perpage * (p_npage - 1);
                                        BEGIN
                                            RETURN QUERY
                                            WITH employee_course AS (
                                                    SELECT ec.course_id
                                                    FROM employee_course ec
                                                    WHERE (p_employee_id IS NULL OR ec.teacher_id = p_employee_id)
                                                ),questions AS (
                                                select
                                                    concat('p_',q.id) as  key_question,
                                                    q.id,
                                                    q.code,
                                                    q.short_description,
                                                    q.number_question,
                                                    q.number,
                                                    q.course_id,
                                                    c.code AS code_course,
                                                    c.name AS course,
                                                    q.status,
                                                    q.fl_status,
                                                    q.parent_id,
                                                    CASE
                                                        WHEN q.parent_id IS NULL THEN 'P'
                                                        ELSE 'S'
                                                    END AS type_question,
                                                    q.created_by,
                                                    qs.created_at as date_status,
                                                    qo.description as observation,
                                                    qo.similitaries,
                                                    u.user AS user_name,
                                                    u.email AS user_email
                                                FROM question q
                                                INNER JOIN course c ON q.course_id = c.id
                                                LEFT JOIN users u ON q.created_by = u.id
                                                LEFT JOIN question_status qs ON q.id = qs.question_id AND q.status = qs.status AND qs.fl_active = true
                                                LEFT JOIN question_observation qo ON q.id = qo.question_id AND q.status = qo.type AND qo.fl_status = true
                                                WHERE q.status = 'ARCH'
                                                AND q.deleted_at IS NULL
                                            ),
                                            sub_questions AS (
                                                SELECT
                                                    pq.id AS parent_id,
                                                    jsonb_agg(
                                                        jsonb_build_object(
                                                            'key_question', concat('s_', q.id),
                                                            'id', q.id,
                                                            'code', q.code,
                                                            'short_description', q.short_description,
                                                            'number_question', q.number_question,
                                                            'number', q.number,
                                                            'course_id', q.course_id,
                                                            'code_course', c.code,
                                                            'course', c.name,
                                                            'status', q.status,
                                                            'fl_status', q.fl_status,
                                                            'parent_id',q.parent_id,
                                                            'type_question', 'S',
                                                            'created_by', q.created_by,
                                                            'date_status', qs.created_at,
                                                            'observation',qo.description,
                                                            'similitaries',qo.similitaries,
                                                            'user_name', u.user,
                                                            'user_email', u.email
                                                        )
                                                    ) AS subquestions
                                                FROM question q
                                                INNER JOIN course c ON q.course_id = c.id
                                                LEFT JOIN users u ON q.created_by = u.id
                                                LEFT JOIN question_status qs ON q.id = qs.question_id AND q.status = qs.status AND qs.fl_active = true
                                                LEFT JOIN question_observation qo ON q.id = qo.question_id AND q.status = qo.type AND qo.fl_status = true
                                                INNER JOIN parent_question pq ON q.parent_id = pq.id
                                                WHERE q.deleted_at IS null
                                                AND q.status = 'ARCH'
                                                GROUP BY pq.id
                                            ),
                                            tbl_question AS (
                                                SELECT
                                                    concat('p_', q.id) AS key_question,
                                                    q.id,
                                                    q.code,
                                                    q.short_description,
                                                    q.number_question,
                                                    q.number,
                                                    q.course_id,
                                                    q.code_course,
                                                    q.course,
                                                    q.status,
                                                    q.fl_status,
                                                    q.parent_id,
                                                    q.type_question,
                                                    COALESCE(sq.subquestions, '[]'::jsonb) AS subquestions,
                                                    q.created_by,
                                                    q.date_status,
                                                    q.observation,
                                                    q.similitaries,
                                                    q.user_name,
                                                    q.user_email
                                                FROM questions q
                                                LEFT JOIN sub_questions sq ON q.parent_id = sq.parent_id
                                                WHERE q.parent_id IS NULL
                                                UNION ALL
                                                SELECT DISTINCT
                                                    concat('t_', pq.id) AS key_question,
                                                    pq.id,
                                                    pq.code,
                                                    pq.short_description,
                                                    pq.number_question,
                                                    pq.number,
                                                    pq.course_id,
                                                    c.code AS code_course,
                                                    c.name AS course,
                                                    pq.status,
                                                    pq.fl_status,
                                                    pq.id as parent_id,
                                                    'T' AS type_question,
                                                    COALESCE(sq.subquestions, '[]'::jsonb) AS subquestions,
                                                    pq.created_by,
                                                    pq.created_at as date_status,
                                                    po.description  as observation,
                                                    po.similitaries,
                                                    u.user AS user_name,
                                                    u.email AS user_email
                                                FROM parent_question pq
                                                INNER JOIN course c ON pq.course_id = c.id
                                                LEFT JOIN users u ON pq.created_by = u.id
                                                LEFT JOIN sub_questions sq ON pq.id = sq.parent_id
                                                left join parent_observation po  on pq.id = po.parent_id
                                                WHERE pq.id = sq.parent_id
                                                AND pq.deleted_at IS NULL
                                            ),
                                            filtered_questions AS (
                                                SELECT *
                                                FROM tbl_question
                                                WHERE(f_course_id IS NULL OR tbl_question.course_id = f_course_id)
                                                AND (f_type IS NULL OR tbl_question.type_question = f_type)
                                                AND (p_employee_id IS NULL OR tbl_question.course_id IN (SELECT * FROM employee_course))
                                                AND (
                                                    p_name_text IS NULL
                                                    OR LOWER(unaccent(tbl_question.short_description)) ILIKE '%' || LOWER(p_name_text) || '%'
                                                    OR LOWER(tbl_question.number_question) LIKE '%' || LOWER(p_name_text) || '%'
                                                    OR LOWER(tbl_question.number) LIKE '%' || LOWER(p_name_text) || '%'
                                                    OR LOWER(tbl_question.code) LIKE '%' || LOWER(p_name_text) || '%'
                                                    OR EXISTS (
                                                        SELECT 1
                                                        FROM jsonb_array_elements(tbl_question.subquestions) AS sq
                                                        WHERE
                                                            LOWER(sq->>'short_description') ILIKE '%' || LOWER(p_name_text) || '%'
                                                            OR LOWER(sq->>'number_question') LIKE '%' || LOWER(p_name_text) || '%'
                                                            OR LOWER(sq->>'number') LIKE '%' || LOWER(p_name_text) || '%'
                                                            OR LOWER(sq->>'code') LIKE '%' || LOWER(p_name_text) || '%'
                                                    )
                                                )
                                            ),
                                            counted_questions AS (
                                                SELECT *, count(*) OVER () AS total
                                                FROM filtered_questions
                                            )
                                            SELECT *
                                            FROM counted_questions cq
                                            ORDER BY cq.date_status ASC, key_question ASC
                                            LIMIT p_perpage
                                            OFFSET offset_val;
                                        END;
                                    $$;


ALTER FUNCTION odiseo.fn_archived_question(p_perpage integer, p_npage integer, p_employee_id integer, p_name_text character varying, f_course_id integer, f_type character varying) OWNER TO postgres;

--
-- Name: fn_area(integer, integer, character varying, character varying, character varying, character varying, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_area(p_perpage integer, p_npage integer, p_search character varying, p_code character varying, p_slug character varying, p_description character varying, f_status boolean) RETURNS TABLE(id bigint, code character varying, slug character varying, description character varying, fl_status boolean, agreement_url character varying, agreement_file_name character varying, created_by bigint, updated_by bigint, deleted_by bigint, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone, total integer)
    LANGUAGE plpgsql
    AS $$
            DECLARE
                total_count INTEGER;
                offset_val INTEGER;
            BEGIN
                offset_val := p_perpage * (p_npage - 1);

                SELECT COUNT(*)
                INTO total_count
                FROM area a
                WHERE a.fl_status = f_status
                AND a.deleted_at IS NULL
                AND (p_code IS NULL OR LOWER(a.code) LIKE '%' || LOWER(p_code) || '%')
                AND (p_slug IS NULL OR LOWER(a.slug) LIKE '%' || LOWER(p_slug) || '%')
                AND (p_description IS NULL OR LOWER(a.description) LIKE '%' || LOWER(p_description) || '%')
                AND (p_search IS NULL OR (LOWER(a.code) LIKE '%' || LOWER(p_search) || '%' OR LOWER(a.description) LIKE '%' || LOWER(p_search) || '%'));

                RETURN QUERY
                SELECT
                    a.id,
                    a.code,
                    a.slug,
                    a.description,
                    a.fl_status,
                    a.agreement_url,
                    a.agreement_file_name,
                    a.created_by,
                    a.updated_by,
                    a.deleted_by,
                    a.created_at,
                    a.updated_at,
                    a.deleted_at,
                    total_count AS total
                FROM area a
                WHERE a.fl_status = f_status
                AND a.deleted_at IS NULL
                AND (p_code IS NULL OR LOWER(a.code) LIKE '%' || LOWER(p_code) || '%')
                AND (p_slug IS NULL OR LOWER(a.slug) LIKE '%' || LOWER(p_slug) || '%')
                AND (p_description IS NULL OR LOWER(a.description) LIKE '%' || LOWER(p_description) || '%')
                AND (p_search IS NULL OR (LOWER(a.code) LIKE '%' || LOWER(p_search) || '%' OR LOWER(a.description) LIKE '%' || LOWER(p_search) || '%'))
                ORDER BY a.id ASC
                LIMIT p_perpage
                OFFSET offset_val;

            END;  
    $$;


ALTER FUNCTION odiseo.fn_area(p_perpage integer, p_npage integer, p_search character varying, p_code character varying, p_slug character varying, p_description character varying, f_status boolean) OWNER TO postgres;

--
-- Name: fn_area_all(character varying, character varying, character varying, character varying, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_area_all(p_search character varying, p_code character varying, p_slug character varying, p_description character varying, f_status boolean) RETURNS TABLE(id bigint, code character varying, slug character varying, description character varying, fl_status boolean, created_by bigint, updated_by bigint, deleted_by bigint, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone, user_name character varying, user_email odiseo.email_citext)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    a.id,
                    a.code,
                    a.slug,
                    a.description,
                    a.fl_status,
                    a.created_by,
                    a.updated_by,
                    a.deleted_by,
                    a.created_at,
                    a.updated_at,
                    a.deleted_at,
                    u.user as user_name,
                    u.email as user_email
                FROM area a
                LEFT JOIN users u ON a.created_by = u.id
                WHERE a.fl_status = f_status
                AND a.deleted_at IS NULL
                AND (p_code IS NULL OR LOWER(a.code) LIKE '%' || LOWER(p_code) || '%')
                AND (p_slug IS NULL OR LOWER(a.slug) LIKE '%' || LOWER(p_slug) || '%')
                AND (p_description IS NULL OR LOWER(a.description) LIKE '%' || LOWER(p_description) || '%')
                AND (p_search IS NULL OR (LOWER(a.code) LIKE '%' || LOWER(p_search) || '%' OR LOWER(a.description) LIKE '%' || LOWER(p_search) || '%'))
                ORDER BY a.id ASC;
            END;     
    $$;


ALTER FUNCTION odiseo.fn_area_all(p_search character varying, p_code character varying, p_slug character varying, p_description character varying, f_status boolean) OWNER TO postgres;

--
-- Name: fn_assign_questions_didi(integer, jsonb, integer, integer, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_assign_questions_didi(p_employee_id integer, p_question_ids jsonb, p_week integer, p_year integer, p_created_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
            BEGIN
                INSERT INTO odiseo.employee_didi_question (employee_id, question_id, week, year, created_by, created_at)
                SELECT p_employee_id, value::bigint, p_week, p_year, p_created_by, now()
                FROM jsonb_array_elements(p_question_ids) AS value;
            END;
            $$;


ALTER FUNCTION odiseo.fn_assign_questions_didi(p_employee_id integer, p_question_ids jsonb, p_week integer, p_year integer, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_assign_questions_docente(bigint, jsonb, smallint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_assign_questions_docente(p_teacher_id bigint, p_question_ids jsonb, p_week smallint, p_year smallint, p_created_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
    BEGIN
        -- Insertar registros en employee_question
        INSERT INTO employee_question (
            teacher_id,
            question_id,
            week,
            year,
            created_by,
            created_at
        )
        SELECT
            p_teacher_id,
            value::BIGINT,
            p_week,
            p_year,
            p_created_by,
            now()
        FROM jsonb_array_elements(p_question_ids) AS value;

        -- Actualizar el estado de las preguntas
        UPDATE question
        SET
            "status" = 'ASIG',
            updated_by = p_created_by,
            updated_at = now()
        WHERE id IN (
            SELECT value::BIGINT FROM jsonb_array_elements(p_question_ids)
        );

    END;
    $$;


ALTER FUNCTION odiseo.fn_assign_questions_docente(p_teacher_id bigint, p_question_ids jsonb, p_week smallint, p_year smallint, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_assigned_question(integer, integer, character varying, character varying, integer, character varying, integer, integer, smallint, smallint, smallint, integer, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_assigned_question(p_perpage integer, p_npage integer, p_name_text character varying, p_status character varying, p_course_id integer, p_type character varying, p_teacher_id integer, p_user_id integer, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_version integer, p_year character varying) RETURNS TABLE(key_question text, id bigint, code character varying, short_description text, number_question character varying, number character varying, course_id smallint, code_course character varying, course character varying, status character varying, fl_status boolean, parent_id bigint, teacher_id bigint, code_teacher character varying, teacher text, type_question text, subquestions jsonb, created_by bigint, date_status timestamp without time zone, user_name character varying, user_email odiseo.email_citext, total_refuzed bigint, origin_question jsonb, priority integer, is_missing_question boolean, total bigint)
    LANGUAGE plpgsql
    AS $$
                        DECLARE
                            C_MORE_RECENT_VERSION SMALLINT DEFAULT 1;
                            offset_val INTEGER := p_perpage * (p_npage - 1);
                            status_array varchar[];
                        begin
                            IF p_status IS NULL OR p_status = '' OR p_status NOT IN ('ASIG', 'RESO', 'SSOL') THEN
                                status_array := ARRAY['ASIG', 'RESO', 'SSOL'];
                            ELSE
                                status_array := ARRAY[p_status];
                            END IF;
                            RETURN QUERY
                            WITH questions AS (
                                select
                                    concat('p_',q.id) as  key_question,
                                    q.id,
                                    q.code,
                                    q.short_description,
                                    q.number_question,
                                    q.number,
                                    q.course_id,
                                    c.code AS code_course,
                                    c.name AS course,
                                    q.status,
                                    q.fl_status,
                                    q.parent_id,
                                    e.id as teacher_id,
                                    e.code AS code_teacher,
                                    CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name) AS teacher,
                                    CASE
                                        WHEN q.parent_id IS NULL THEN 'P'
                                        ELSE 'S'
                                    END AS type_question,
                                    qs.created_by,
                                    qs.created_at as date_status,
                                    u.user AS user_name,
                                    u.email AS user_email,
                                    (
                                        SELECT COUNT(*)
                                        FROM question_refuzed qr2
                                        WHERE qr2.question_id = q.id
                                        AND qr2.fl_status = true
                                    ) AS total_refuzed,
                                    qn.question_origin,
                                    q.priority,
                                    CASE
                                        WHEN mmqd.question_id IS NOT NULL THEN true
                                        ELSE false
                                    END AS is_missing_question
                                from employee_question eq
                                inner join question q  on eq.question_id = q.id
                                LEFT JOIN v_all_question_origins qn ON qn.question_id = q.id
                                left join course c on q.course_id = c.id
                                left join employees e on eq.teacher_id = e.id
                                LEFT JOIN users u ON eq.created_by = u.id
                                LEFT JOIN users usercreated ON q.created_by = usercreated.id
                                LEFT JOIN question_status qs ON q.id = qs.question_id AND q.status = qs.status AND qs.fl_active = true
                                LEFT JOIN material_missing_question_detail mmqd ON mmqd.question_id = q.id
                                where q.deleted_at IS null
                                AND q.fl_status = true
                                and eq.fl_status = true
                                AND q.status = ANY(ARRAY[status_array])
                                AND (p_teacher_id IS NULL OR e.id = p_teacher_id)
                                AND (p_user_id IS NULL OR usercreated.id = p_user_id)
                                AND ( p_university_id IS NULL OR qn.university_id = p_university_id )
                                AND ( p_option_id IS NULL OR qn.option_id = p_option_id )
                                AND ( p_modality_id IS NULL OR qn.modality_id = p_modality_id )
                                AND ( p_version IS NULL OR qn."version" = p_version )
                                AND ( p_year IS NULL OR qn."year" = p_year )
                            ), sub_questions AS (
                                SELECT
                                    pq.id AS parent_id,
                                    jsonb_agg(
                                        jsonb_build_object(
                                            'key_question', concat('s_', q.id),
                                            'id', q.id,
                                            'code', q.code,
                                            'short_description', q.short_description,
                                            'number_question', q.number_question,
                                            'number', q.number,
                                            'course_id', q.course_id,
                                            'code_course', c.code,
                                            'course', c.name,
                                            'status', q.status,
                                            'fl_status', q.fl_status,
                                            'parent_id',q.parent_id,
                                            'teacher_id',e.id,
                                            'code_teacher',e.code,
                                            'teacher', CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name),
                                            'type_question', 'S',
                                            'created_by', qs.created_by,
                                            'date_status', qs.created_at,
                                            'user_name', u.user,
                                            'user_email', u.email,
                                            'origin_question', qn.question_origin,
                                            'total_refuzed', (
                                                SELECT COUNT(*)
                                                FROM question_refuzed qr
                                                WHERE qr.question_id = q.id
                                                AND qr.fl_status = true
                                            )
                                        )
                                    ) AS subquestions
                                from employee_question eq
                                inner join question q  on eq.question_id = q.id
                                LEFT JOIN v_all_question_origins qn ON qn.question_id = q.id
                                left join course c on q.course_id = c.id
                                left join employees e on eq.teacher_id = e.id
                                LEFT JOIN users u ON eq.created_by = u.id
                                LEFT JOIN users usercreated ON q.created_by = usercreated.id
                                LEFT JOIN question_status qs ON q.id = qs.question_id AND q.status = qs.status AND qs.fl_active = true
                                INNER JOIN parent_question pq ON q.parent_id = pq.id AND pq.status <> 'DUPL'
                                WHERE q.deleted_at IS null
                                and eq.fl_status = true
                                AND q.status = ANY(ARRAY[status_array])
                                AND (p_teacher_id IS NULL OR e.id = p_teacher_id)
                                AND (p_user_id IS NULL OR usercreated.id = p_user_id)
                                AND ( p_university_id IS NULL OR qn.university_id = p_university_id )
                                AND ( p_option_id IS NULL OR qn.option_id = p_option_id )
                                AND ( p_modality_id IS NULL OR qn.modality_id = p_modality_id )
                                AND ( p_version IS NULL OR qn."version" = p_version )
                                AND ( p_year IS NULL OR qn."year" = p_year )
                                GROUP BY pq.id
                            ), tbl_question AS (
                                SELECT
                                    concat('p_', q.id) AS key_question,
                                    q.id,
                                    q.code,
                                    q.short_description,
                                    q.number_question,
                                    q.number,
                                    q.course_id,
                                    q.code_course,
                                    q.course,
                                    q.status,
                                    q.fl_status,
                                    q.parent_id,
                                    q.teacher_id,
                                    q.code_teacher,
                                    q.teacher,
                                    q.type_question,
                                    COALESCE(sq.subquestions, '[]'::jsonb) AS subquestions,
                                    q.created_by,
                                    q.date_status,
                                    q.user_name,
                                    q.user_email,
                                    q.total_refuzed,
                                    q.question_origin,
                                    q.priority,
                                    q.is_missing_question
                                FROM questions q
                                LEFT JOIN sub_questions sq ON q.parent_id = sq.parent_id
                                WHERE q.parent_id IS NULL
                                UNION ALL
                                SELECT DISTINCT
                                    concat('t_', pq.id) AS key_question,
                                    pq.id,
                                    pq.code,
                                    pq.short_description,
                                    pq.number_question,
                                    pq.number,
                                    pq.course_id,
                                    c.code AS code_course,
                                    c.name AS course,
                                    pq.status,
                                    pq.fl_status,
                                    pq.id AS parent_id,
                                    -1 AS teacher_id,
                                    '' AS code_teacher,
                                    '' AS teacher,
                                    'T' AS type_question,
                                    COALESCE(sq.subquestions, '[]'::jsonb) AS subquestions,
                                    pq.created_by,
                                    pq.created_at  as date_status,
                                    u.user AS user_name,
                                    u.email AS user_email,
                                    0::BIGINT AS total_refuzed,
                                    opq.question_origin,
                                    pq.priority,
                                    false AS is_missing_question
                                FROM parent_question pq
                                INNER JOIN course c ON pq.course_id = c.id
                                LEFT JOIN users u ON pq.created_by = u.id
                                INNER JOIN sub_questions sq ON pq.id = sq.parent_id and sq.parent_id is not  null
                                LEFT JOIN v_all_parent_origins opq ON opq.parent_id = pq.id
                                WHERE pq.id = sq.parent_id
                                AND pq.deleted_at IS NULL
                                AND pq.status <> 'DUPL'
                                AND (sq.subquestions <> '[]')
                                AND ( p_university_id IS NULL OR opq.university_id = p_university_id )
                                AND ( p_option_id IS NULL OR opq.option_id = p_option_id )
                                AND ( p_modality_id IS NULL OR opq.modality_id = p_modality_id )
                                AND ( p_version IS NULL OR opq."version" = p_version )
                                AND ( p_year IS NULL OR opq."year" = p_year )
                            ), filtered_questions AS (
                                SELECT *
                                FROM tbl_question
                                WHERE(p_course_id IS NULL OR tbl_question.course_id = p_course_id)
                                AND (p_type IS NULL OR tbl_question.type_question = p_type)
                                AND (
                                    p_name_text IS NULL
                                    OR unaccent(LOWER(tbl_question.short_description)) LIKE '%' || LOWER(p_name_text) || '%'
                                    OR LOWER(tbl_question.number_question) LIKE '%' || LOWER(p_name_text) || '%'
                                    OR LOWER(tbl_question.number) LIKE '%' || LOWER(p_name_text) || '%'
                                    OR LOWER(tbl_question.code) LIKE '%' || LOWER(p_name_text) || '%'
                                    OR EXISTS (
                                        SELECT 1
                                        FROM jsonb_array_elements(tbl_question.subquestions) AS sq
                                        WHERE
                                            unaccent(LOWER(sq->>'short_description')) LIKE '%' || LOWER(p_name_text) || '%'
                                            OR LOWER(sq->>'number_question') LIKE '%' || LOWER(p_name_text) || '%'
                                            OR LOWER(sq->>'number') LIKE '%' || LOWER(p_name_text) || '%'
                                            OR LOWER(sq->>'code') LIKE '%' || LOWER(p_name_text) || '%'
                                        )
                                    )
                            ), counted_questions AS (
                                SELECT *, count(*) OVER () AS total
                                FROM filtered_questions
                            )
                            SELECT
                                *
                            FROM counted_questions AS cq
                            ORDER BY
                                priority DESC,
                                CASE
                                    WHEN cq.status = 'RESO' THEN 2
                                    WHEN cq.status = 'SSOL' THEN 3
                                    WHEN cq.status = 'ASIG' THEN 4
                                    ELSE 5
                                END,
                                CASE
                                    WHEN cq.status = 'RESO' THEN cq.date_status
                                    ELSE NULL
                                END ASC,
                                CASE
                                    WHEN cq.status = 'SSOL' THEN cq.date_status
                                    ELSE NULL
                                END ASC,
                                CASE
                                    WHEN cq.status = 'ASIG' THEN cq.date_status
                                    ELSE NULL
                                END ASC,
                                id ASC,
                                date_status ASC, key_question ASC
                            LIMIT p_perpage
                            OFFSET offset_val;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_assigned_question(p_perpage integer, p_npage integer, p_name_text character varying, p_status character varying, p_course_id integer, p_type character varying, p_teacher_id integer, p_user_id integer, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_version integer, p_year character varying) OWNER TO postgres;

--
-- Name: fn_assigned_question_teacher(integer, integer, character varying, character varying, integer[], character varying, integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_assigned_question_teacher(p_perpage integer, p_npage integer, p_name_text character varying, f_status character varying, f_course_ids integer[], f_type character varying, f_teacher_id integer, f_user_id integer, f_week_id integer) RETURNS TABLE(key_question text, id bigint, code character varying, short_description text, number_question character varying, number character varying, course_id smallint, code_course character varying, course character varying, status character varying, fl_status boolean, parent_id bigint, teacher_id bigint, code_teacher character varying, teacher text, type_question text, subquestions jsonb, created_by bigint, date_status timestamp without time zone, user_name character varying, user_email odiseo.email_citext, total_refuzed bigint, question_temporary jsonb, total bigint)
    LANGUAGE plpgsql
    AS $$
                                DECLARE
                                    offset_val INTEGER := p_perpage * (p_npage - 1);
                                    status_array varchar[];
                                BEGIN
                                    -- Manejo del parámetro f_status
                                    IF f_status IS NULL OR f_status = '' OR f_status NOT IN ('ASIG', 'RESO', 'SSOL', 'RECH') THEN
                                        status_array := ARRAY['ASIG', 'RESO', 'SSOL', 'RECH'];
                                    ELSE
                                        status_array := ARRAY[f_status];
                                    END IF;

                                    RETURN QUERY
                                    WITH questions AS (
                                        SELECT
                                            concat('p_', q.id) AS key_question,
                                            q.id,
                                            q.code,
                                            q.short_description,
                                            q.number_question,
                                            q.number,
                                            q.course_id,
                                            c.code AS code_course,
                                            c.name AS course,
                                            q.status,
                                            q.fl_status,
                                            q.parent_id,
                                            e.id AS teacher_id,
                                            e.code AS code_teacher,
                                            CONCAT(e.first_surname, ' ', e.second_surname, ' ', e.first_name) AS teacher,
                                            CASE
                                                WHEN q.parent_id IS NULL THEN 'P'
                                                ELSE 'S'
                                            END AS type_question,
                                            qs.created_by,
                                            qs.created_at AS date_status,
                                            u.user AS user_name,
                                            u.email AS user_email,
                                            (
                                                SELECT COUNT(*)
                                                FROM question_refuzed qr2
                                                WHERE qr2.question_id = q.id
                                                AND qr2.fl_status = true
                                            ) AS total_refuzed,
                                            JSONB_BUILD_OBJECT(
                                                'cycle', cy.description,
                                                'week', w.description,
                                                'type_material', tm.description
                                            ) AS question_temporary
                                        FROM employee_question eq
                                        INNER JOIN question q ON eq.question_id = q.id
                                        LEFT JOIN course c ON q.course_id = c.id
                                        LEFT JOIN employees e ON eq.teacher_id = e.id
                                        LEFT JOIN users u ON eq.created_by = u.id
                                        LEFT JOIN users usercreated ON q.created_by = usercreated.id
                                        LEFT JOIN question_status qs ON q.id = qs.question_id AND q.status = qs.status AND qs.fl_active = true
                                        LEFT JOIN question_temporary qt ON q.id = qt.question_id
                                        LEFT JOIN cycle cy ON qt.cycle_id = cy.id
                                        LEFT JOIN week w ON qt.week_id = w.id
                                        LEFT JOIN type_material tm ON qt.type_material_id = tm.id
                                        WHERE q.deleted_at IS NULL
                                        AND q.fl_status = true
                                        AND eq.fl_status = true
                                        AND q.status = ANY(ARRAY[status_array])
                                        AND (f_teacher_id IS NULL OR e.id = f_teacher_id)
                                        AND (f_user_id IS NULL OR usercreated.id = f_user_id)
                                        AND (f_week_id IS NULL OR (qt.week_id = f_week_id AND qt.week_id IS NOT NULL))
                                        AND (f_course_ids IS NULL OR q.course_id = ANY(f_course_ids)) -- Cambio: Filtrado por array de course_ids
                                    ),
                                    sub_questions AS (
                                        SELECT
                                            pq.id AS parent_id,
                                            jsonb_agg(
                                                jsonb_build_object(
                                                    'key_question', concat('s_', q.id),
                                                    'id', q.id,
                                                    'code', q.code,
                                                    'short_description', q.short_description,
                                                    'number_question', q.number_question,
                                                    'number', q.number,
                                                    'course_id', q.course_id,
                                                    'code_course', c.code,
                                                    'course', c.name,
                                                    'status', q.status,
                                                    'fl_status', q.fl_status,
                                                    'parent_id', q.parent_id,
                                                    'teacher_id', e.id,
                                                    'code_teacher', e.code,
                                                    'teacher', CONCAT(e.first_surname, ' ', e.second_surname, ' ', e.first_name),
                                                    'type_question', 'S',
                                                    'created_by', qs.created_by,
                                                    'date_status', qs.created_at,
                                                    'user_name', u.user,
                                                    'user_email', u.email,
                                                    'total_refuzed', (
                                                        SELECT COUNT(*)
                                                        FROM question_refuzed qr
                                                        WHERE qr.question_id = q.id
                                                        AND qr.fl_status = true
                                                    ),
                                                    'question_temporary', JSONB_BUILD_OBJECT(
                                                        'cycle', cy.description,
                                                        'week', w.description,
                                                        'type_material', tm.description
                                                    )
                                                )
                                            ) AS subquestions
                                        FROM employee_question eq
                                        INNER JOIN question q ON eq.question_id = q.id
                                        LEFT JOIN course c ON q.course_id = c.id
                                        LEFT JOIN employees e ON eq.teacher_id = e.id
                                        LEFT JOIN users u ON eq.created_by = u.id
                                        LEFT JOIN users usercreated ON q.created_by = usercreated.id
                                        LEFT JOIN question_status qs ON q.id = qs.question_id AND q.status = qs.status AND qs.fl_active = true
                                        INNER JOIN parent_question pq ON q.parent_id = pq.id AND pq.status <> 'DUPL'
                                        LEFT JOIN question_temporary qt ON q.id = qt.question_id
                                        LEFT JOIN cycle cy ON qt.cycle_id = cy.id
                                        LEFT JOIN week w ON qt.week_id = w.id
                                        LEFT JOIN type_material tm ON qt.type_material_id = tm.id
                                        WHERE q.deleted_at IS NULL
                                        AND eq.fl_status = true
                                        AND q.status = ANY(ARRAY[status_array])
                                        AND (f_teacher_id IS NULL OR e.id = f_teacher_id)
                                        AND (f_user_id IS NULL OR usercreated.id = f_user_id)
                                        AND (f_week_id IS NULL OR (qt.week_id = f_week_id AND qt.week_id IS NOT NULL))
                                        AND (f_course_ids IS NULL OR q.course_id = ANY(f_course_ids)) -- Cambio: Filtrado por array de course_ids
                                        GROUP BY pq.id
                                    ),
                                    tbl_question AS (
                                        SELECT
                                            concat('p_', q.id) AS key_question,
                                            q.id,
                                            q.code,
                                            q.short_description,
                                            q.number_question,
                                            q.number,
                                            q.course_id,
                                            q.code_course,
                                            q.course,
                                            q.status,
                                            q.fl_status,
                                            q.parent_id,
                                            q.teacher_id,
                                            q.code_teacher,
                                            q.teacher,
                                            q.type_question,
                                            COALESCE(sq.subquestions, '[]'::jsonb) AS subquestions,
                                            q.created_by,
                                            q.date_status,
                                            q.user_name,
                                            q.user_email,
                                            q.total_refuzed,
                                            q.question_temporary
                                        FROM questions q
                                        LEFT JOIN sub_questions sq ON q.parent_id = sq.parent_id
                                        WHERE q.parent_id IS NULL
                                        UNION ALL
                                        SELECT DISTINCT
                                            concat('t_', pq.id) AS key_question,
                                            pq.id,
                                            pq.code,
                                            pq.short_description,
                                            pq.number_question,
                                            pq.number,
                                            pq.course_id,
                                            c.code AS code_course,
                                            c.name AS course,
                                            pq.status,
                                            pq.fl_status,
                                            pq.id AS parent_id,
                                            -1 AS teacher_id,
                                            '' AS code_teacher,
                                            '' AS teacher,
                                            'T' AS type_question,
                                            COALESCE(sq.subquestions, '[]'::jsonb) AS subquestions,
                                            pq.created_by,
                                            pq.created_at AS date_status,
                                            u.user AS user_name,
                                            u.email AS user_email,
                                            0::BIGINT AS total_refuzed,
                                            null::jsonb AS question_temporary
                                        FROM parent_question pq
                                        INNER JOIN course c ON pq.course_id = c.id
                                        LEFT JOIN users u ON pq.created_by = u.id
                                        INNER JOIN sub_questions sq ON pq.id = sq.parent_id AND sq.parent_id IS NOT NULL
                                        WHERE pq.id = sq.parent_id
                                        AND pq.deleted_at IS NULL
                                        AND pq.status <> 'DUPL'
                                        AND (sq.subquestions <> '[]')
                                    ),
                                    filtered_questions AS (
                                        SELECT *
                                        FROM tbl_question
                                        WHERE (f_course_ids IS NULL OR tbl_question.course_id = ANY(f_course_ids)) -- Cambio: Filtrado por array de course_ids
                                        AND (f_type IS NULL OR tbl_question.type_question = f_type)
                                        AND (
                                            p_name_text IS NULL
                                            OR unaccent(LOWER(tbl_question.short_description)) LIKE '%' || LOWER(p_name_text) || '%'
                                            OR LOWER(tbl_question.number_question) LIKE '%' || LOWER(p_name_text) || '%'
                                            OR LOWER(tbl_question.number) LIKE '%' || LOWER(p_name_text) || '%'
                                            OR LOWER(tbl_question.code) LIKE '%' || LOWER(p_name_text) || '%'
                                            OR EXISTS (
                                                SELECT 1
                                                FROM jsonb_array_elements(tbl_question.subquestions) AS sq
                                                WHERE
                                                    unaccent(LOWER(sq->>'short_description')) LIKE '%' || LOWER(p_name_text) || '%'
                                                    OR LOWER(sq->>'number_question') LIKE '%' || LOWER(p_name_text) || '%'
                                                    OR LOWER(sq->>'number') LIKE '%' || LOWER(p_name_text) || '%'
                                                    OR LOWER(sq->>'code') LIKE '%' || LOWER(p_name_text) || '%'
                                            )
                                        )
                                    ),
                                    counted_questions AS (
                                        SELECT *, count(*) OVER () AS total
                                        FROM filtered_questions
                                    )
                                    SELECT *
                                    FROM counted_questions AS cq
                                    ORDER BY
                                        CASE
                                            WHEN cq.status = 'RECH' THEN 1
                                            WHEN cq.status = 'RESO' THEN 2
                                            WHEN cq.status = 'SSOL' THEN 3
                                            WHEN cq.status = 'ASIG' THEN 4
                                            ELSE 5
                                        END,
                                        CASE
                                            WHEN cq.status = 'RECH' THEN cq.date_status
                                            ELSE NULL
                                        END ASC,
                                        CASE
                                            WHEN cq.status = 'RESO' THEN cq.date_status
                                            ELSE NULL
                                        END ASC,
                                        CASE
                                            WHEN cq.status = 'SSOL' THEN cq.date_status
                                            ELSE NULL
                                        END ASC,
                                        CASE
                                            WHEN cq.status = 'ASIG' THEN cq.date_status
                                            ELSE NULL
                                        END ASC,
                                        id ASC,
                                        date_status ASC,
                                        key_question ASC
                                    LIMIT p_perpage
                                    OFFSET offset_val;
                                END;
                                $$;


ALTER FUNCTION odiseo.fn_assigned_question_teacher(p_perpage integer, p_npage integer, p_name_text character varying, f_status character varying, f_course_ids integer[], f_type character varying, f_teacher_id integer, f_user_id integer, f_week_id integer) OWNER TO postgres;

--
-- Name: fn_auto_assign_missing_questions_to_teacher(bigint, bigint, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_auto_assign_missing_questions_to_teacher(p_employee_id bigint, p_course_id bigint, p_limit integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_assigned_count INTEGER;
BEGIN
    WITH available_questions AS (
        SELECT mmqd.id
        FROM material_missing_question_detail mmqd
        JOIN material_ballot_question mdbq
            ON mmqd.material_ballot_question_id = mdbq.id
        JOIN material_missing_question mmq
            ON mmqd.material_missing_question_id = mmq.id
        WHERE mmqd.employee_id IS NULL
          AND mmqd.question_id IS NULL
          AND mmqd.status = 'pending'
          AND mmqd.deleted_at IS NULL
          AND mmq.deleted_at IS NULL
          AND mdbq.course_id = p_course_id
          AND mdbq.fl_status = true
          AND mdbq.deleted_at IS NULL
        ORDER BY
            mmq.request_date ASC,
            mmqd.id ASC
        LIMIT p_limit
        FOR UPDATE OF mmqd SKIP LOCKED
    ),
    -- Solo asignar si se cumple la cantidad exacta del límite
    validated_questions AS (
        SELECT id 
        FROM available_questions
        WHERE (SELECT COUNT(*) FROM available_questions) = p_limit
    ),
    -- Actualizar el detalle
    assigned_questions AS (
        UPDATE material_missing_question_detail mmqd
        SET employee_id = p_employee_id,
            assignment_type = 'auto',
            status = 'assigned',
            updated_at = now()
        FROM validated_questions vq
        WHERE mmqd.id = vq.id
        RETURNING mmqd.id
    )
    -- Registrar en tracking
    INSERT INTO material_missing_question_tracking (
        material_missing_question_detail_id,
        employee_id,
        action,
        assignment_type,
        created_at,
        updated_at
    )
    SELECT
        aq.id,
        p_employee_id,
        'assigned',
        'auto',
        now(),
        now()
    FROM assigned_questions aq;

    GET DIAGNOSTICS v_assigned_count = ROW_COUNT;
    RETURN v_assigned_count;
END;
$$;


ALTER FUNCTION odiseo.fn_auto_assign_missing_questions_to_teacher(p_employee_id bigint, p_course_id bigint, p_limit integer) OWNER TO postgres;

--
-- Name: fn_ballot_questions_to_order(integer, integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_ballot_questions_to_order(p_material_id integer, p_type_material_id integer, p_start_week integer, p_end_week integer) RETURNS TABLE(id bigint, material_ballot_question_id bigint, course_id bigint, topic_id bigint, code_topic character varying, subtopic_id bigint, code_subtopic character varying, level_id bigint, level character varying, question_id bigint, parent_question_id bigint, category_id bigint, subcategory_id bigint, subquestion jsonb, "position" smallint, position_initial smallint, absolute_position smallint, "order" smallint, course_position smallint, type_material_id smallint, week smallint)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY
                    WITH prepare_type_material_ids AS (
                        SELECT
                        CASE WHEN EXISTS (
                            SELECT 1 FROM type_material tm
                            WHERE tm.parent_id = p_type_material_id) THEN
                            ARRAY (
                                SELECT tm.id FROM type_material tm WHERE tm.parent_id = p_type_material_id
                            )
                        ELSE
                            ARRAY[p_type_material_id]
                        END AS ids
                    ), type_material_ids AS (
                        SELECT UNNEST(ids) AS id FROM prepare_type_material_ids
                    ), template_type_material AS (
                        SELECT
                            tmt.id
                        FROM type_material tm
                        JOIN type_material_template tmt ON tmt.id = tm.type_material_template_id
                        WHERE 1 = 1
                            AND tm.type_material_template_id IS NOT NULL
                            AND tm.id = p_type_material_id
                    ), courses_ordering AS (
                        SELECT
                            ttmco.course_id,
                            ttmco.position AS course_position,
                            ttmco.university_id
                        FROM template_type_material_courses_order ttmco
                        WHERE 1 = 1
                            AND ttmco.deleted_by IS NULL
                            AND ttmco.template_type_material_id IN (SELECT ttm.id FROM template_type_material ttm)
                    ), type_material_valid_weeks AS (
                        SELECT tdt.week
                        FROM type_material_detail_template tdt
                        WHERE 1 = 1
                            AND tdt.type_material_id = p_type_material_id
                            AND tdt.fl_status IS TRUE
                    ), detail_week_type_mat_ids AS (
                        SELECT
                            dtm.id,
                            dtm.type_material_id,
                            dtm.week,
                            dtm.material_id
                        FROM detail_week_type_mat dtm
                        WHERE dtm.material_id = p_material_id
                            AND dtm.type_material_id IN (SELECT tmi.id FROM type_material_ids tmi)
                            AND dtm.week BETWEEN p_start_week AND p_end_week
                            AND dtm.week IN (SELECT tmvw.week FROM type_material_valid_weeks tmvw)
                            AND dtm.fl_status IS TRUE
                    )
                    SELECT
                        mdbq.id,
                        CASE 
                            WHEN mdbq.question_id IS NOT NULL OR mdbq.parent_question_id IS NOT NULL THEN mdbq.id 
                            ELSE NULL 
                        END AS material_ballot_question_id,
                        mdbq.course_id::BIGINT AS course_id,
                        mdbq.topic_id::BIGINT AS topic_id,
                        t.code AS code_topic,
                        mdbq.subtopic_id::BIGINT AS subtopic_id,
                        s.code AS code_subtopic,
                        mdbq.level_id AS level_id,
                        l.name AS level,
                        COALESCE(mdbq.question_id, mdbq.id * -1) AS question_id,
                        mdbq.parent_question_id::BIGINT,
                        mdbq.type_text_id AS category_id,
                        mdbq.type_text_subcategory_id AS subcategory_id,
                        (
                            SELECT
                                JSONB_AGG(JSONB_BUILD_OBJECT(
                                    'question_id', sub.question_id,
                                    'position', sub.position,
                                    'course_id', q_sub.course_id,
                                    'topic_id', q_sub.topic_id,
                                    'subtopic_id', q_sub.subtopic_id,
                                    'removed_in_completion', FALSE,
                                    'added_in_completion', FALSE,
                                    'updated_at', sub.created_at,
                                    'fl_is_manual', FALSE
                                ) ORDER BY sub.position)
                            FROM
                                material_ballot_subquestions sub
                                JOIN question q_sub ON sub.question_id = q_sub.id
                            WHERE sub.material_ballot_question_id = mdbq.id
                        ) AS subquestion,
                        mdbq.position,
                        mdbq.position_initial,
                        mdbq.absolute_position,
                        mdbq.position AS "order",
                        ccor.course_position,
                        mdbq.type_material_id,
                        dwtmi.week
                    FROM odiseo.material_ballot_question mdbq
                    JOIN detail_week_type_mat_ids dwtmi ON mdbq.week_type_material_id = dwtmi.id
                    JOIN material m ON dwtmi.material_id = m.id
                    LEFT JOIN courses_ordering ccor ON ccor.course_id = mdbq.course_id
                        AND ccor.university_id IS NULL
                    JOIN level l ON mdbq.level_id = l.id
                    LEFT JOIN topic t ON t.id = mdbq.topic_id
                    LEFT JOIN subtopic s ON s.id = mdbq.subtopic_id
                    WHERE mdbq.fl_status IS TRUE
                    ORDER BY
                        dwtmi.week ASC,
                        mdbq.type_material_id ASC,
                        ccor.course_position ASC,
                        mdbq.absolute_position ASC,
                        mdbq.position ASC;
                END;
                $$;


ALTER FUNCTION odiseo.fn_ballot_questions_to_order(p_material_id integer, p_type_material_id integer, p_start_week integer, p_end_week integer) OWNER TO postgres;

