--
-- Name: fn_change_assigned_question(integer, integer, integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_change_assigned_question(p_id integer, p_employee_id integer, p_week integer, p_year integer, p_updated_by integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_question_id INTEGER;
            v_teacher_id INTEGER;
            v_employee_question_id INTEGER;
        BEGIN
            UPDATE odiseo.question
            SET
                status = 'ASIG',
                teacher_id = p_employee_id,
                updated_by = p_updated_by,
                updated_at = now()
            WHERE
                id = p_id
            RETURNING id INTO v_question_id;

            SELECT teacher_id INTO v_teacher_id
            FROM odiseo.employee_question
            WHERE question_id = p_id
            AND fl_status = true;

            IF v_teacher_id <> p_employee_id OR v_teacher_id IS NULL THEN
                UPDATE odiseo.employee_question
                SET
                    fl_status = false,
                    deleted_by = p_updated_by,
                    deleted_at = now()
                WHERE question_id = p_id
                AND fl_status = true
                RETURNING id INTO v_employee_question_id;

                UPDATE odiseo.employee_question_document
                SET
                    fl_status = false,
                    deleted_by = p_updated_by,
                    deleted_at = now()
                WHERE employee_question_id = v_employee_question_id
                AND fl_status = true;

                INSERT INTO odiseo.employee_question (teacher_id, question_id, week, year, created_by, created_at)
                VALUES (p_employee_id, p_id, p_week, p_year, p_updated_by, now());

                RETURN v_question_id;
            ELSE
                RETURN NULL;
            END IF;
        END;
        $$;


ALTER FUNCTION odiseo.fn_change_assigned_question(p_id integer, p_employee_id integer, p_week integer, p_year integer, p_updated_by integer) OWNER TO postgres;

--
-- Name: fn_change_assigned_question_didi(bigint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_change_assigned_question_didi(p_id bigint, p_employee_id bigint, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_employee_id BIGINT;
BEGIN
    UPDATE question
    SET
        status = 'DASI',
        updated_by = p_updated_by,
        updated_at = now()
    WHERE
        id = p_id;

    PERFORM fn_sync_parent_question_with_subquestions_status(p_id, 'DASI', p_updated_by);

    SELECT
        employee_id
    INTO v_employee_id
    FROM employee_didi_question
    WHERE 1 = 1
      AND question_id = p_id
      AND fl_status = true
    ORDER BY employee_id
    LIMIT 1;

    IF v_employee_id IS NOT NULL AND ( v_employee_id <> p_employee_id ) THEN
        UPDATE employee_didi_question
            SET
                employee_id = p_employee_id,
                updated_by = p_updated_by
            WHERE 1 = 1
              AND question_id = p_id
              AND fl_status IS TRUE;
    ELSE
        INSERT INTO employee_didi_question (employee_id, question_id, week, year, created_by, created_at)
        VALUES (p_employee_id, p_id, date_part('week', now()), date_part('year', now()), p_updated_by, now());
    END IF;
END;
$$;


ALTER FUNCTION odiseo.fn_change_assigned_question_didi(p_id bigint, p_employee_id bigint, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_change_index_question(bigint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_change_index_question(p_question_id bigint, p_answer_id bigint, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_employee_question_id BIGINT;
        BEGIN
            UPDATE question
            SET
                status = 'DASI',
                updated_by = p_updated_by,
                updated_at = NOW()
            WHERE id = p_question_id;

            PERFORM fn_sync_parent_question_with_subquestions_status(p_question_id, 'DASI', p_updated_by);

            UPDATE question_refuzed
            SET
                fl_active = FALSE,
                deleted_by = p_updated_by,
                deleted_at = NOW()
            WHERE question_id = p_question_id
              AND fl_status = TRUE;

            SELECT eq.id
            INTO v_employee_question_id
            FROM employee_question eq
            WHERE eq.question_id = p_question_id
              AND eq.fl_status = TRUE
            LIMIT 1;

            UPDATE employee_question
            SET
                board_refuzed = NULL,
                fl_refuzed = FALSE,
                url_pdf_question_solution = NULL,
                updated_by = p_updated_by,
                updated_at = NOW()
            WHERE question_id = p_question_id
              AND fl_status = TRUE;

            IF v_employee_question_id IS NOT NULL THEN
                UPDATE employee_question_document
                SET
                    document_refuzed = NULL,
                    fl_refuzed = FALSE,
                    updated_by = p_updated_by,
                    updated_at = NOW()
                WHERE employee_question_id = v_employee_question_id;
            END IF;

            UPDATE question
            SET
                answer_id = p_answer_id,
                updated_by = p_updated_by,
                updated_at = NOW()
            WHERE id = p_question_id;
        END;
        $$;


ALTER FUNCTION odiseo.fn_change_index_question(p_question_id bigint, p_answer_id bigint, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_change_status_admin(bigint, character varying, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_change_status_admin(p_id bigint, p_status character varying, p_status_old character varying, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
            BEGIN
                UPDATE odiseo.question
                SET status = p_status, updated_by = p_updated_by, updated_at = now()
                WHERE id = p_id;

                IF p_status = 'DASI' THEN

                    PERFORM odiseo.fn_delete_exception_question(p_id, p_status_old, p_updated_by); -- Eliminar excepciones
                    PERFORM odiseo.fn_delete_diagram_question(p_id, p_updated_by); -- Eliminar diagramación
                ELSIF p_status = 'INDE' THEN

                    PERFORM odiseo.fn_delete_exception_question(p_id, p_status_old, p_updated_by); -- Eliminar excepciones
                    PERFORM odiseo.fn_delete_diagram_question(p_id, p_updated_by); -- Eliminar diagramación

                    UPDATE odiseo.employee_didi_question SET fl_status = false, deleted_by = p_updated_by, deleted_at = now()
                    WHERE question_id = p_id AND fl_status = true; -- Eliminar asignación de didi
                ELSIF p_status = 'ASIG' THEN

                    PERFORM odiseo.fn_delete_exception_question(p_id, p_status_old, p_updated_by); -- Eliminar excepciones
                    PERFORM odiseo.fn_delete_diagram_question(p_id, p_updated_by); -- Eliminar diagramación

                    UPDATE odiseo.employee_didi_question SET fl_status = false, deleted_by = p_updated_by, deleted_at = now()
                    WHERE question_id = p_id AND fl_status = true; -- Eliminar asignación de didi

                    PERFORM odiseo.fn_delete_index_question(p_id, p_updated_by); -- Eliminar asignación de didi
                ELSIF p_status = 'SASI' THEN

                    PERFORM odiseo.fn_delete_exception_question(p_id, p_status_old, p_updated_by); -- Eliminar excepciones
                    PERFORM odiseo.fn_delete_diagram_question(p_id, p_updated_by); -- Eliminar diagramación

                    UPDATE odiseo.employee_didi_question SET fl_status = false, deleted_by = p_updated_by, deleted_at = now()
                    WHERE question_id = p_id AND fl_status = true; -- Eliminar asignación de didi

                    PERFORM odiseo.fn_delete_index_question(p_id, p_updated_by); -- Eliminar asignación de didi

                    UPDATE odiseo.employee_question SET fl_status = false, deleted_by = p_updated_by, deleted_at = now()
                    WHERE question_id = p_id AND fl_status = true; -- Eliminar asignación de docente
                END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_change_status_admin(p_id bigint, p_status character varying, p_status_old character varying, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_change_status_parent(bigint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_change_status_parent(p_question_id bigint, p_status character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    UPDATE parent_question pq
                    SET status = p_status
                    WHERE 
                    pq.id = (SELECT parent_id FROM question WHERE id = p_question_id) 
                    AND NOT EXISTS (
                        SELECT 1
                        FROM question q
                        WHERE q.parent_id = pq.id
                        AND q.status IS DISTINCT FROM p_status
                    );
                END;
            $$;


ALTER FUNCTION odiseo.fn_change_status_parent(p_question_id bigint, p_status character varying) OWNER TO postgres;

--
-- Name: fn_change_status_parent_question(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_change_status_parent_question(p_parent_question_id bigint, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
            BEGIN
                WITH subquestion_status AS (
                    SELECT
                        q.id,
                        q.parent_id,
                        qs.status,
                        qs.description,
                        qs.process
                    FROM question q
                    JOIN parent_question pq ON q.parent_id = pq.id
                        AND pq.status = 'DUPL'
                    JOIN (
                        SELECT DISTINCT ON (question_id) *
                        FROM question_status
                        WHERE fl_active = false
                            AND status <> 'DUPL'
                        ORDER BY question_id, created_at DESC
                    ) qs ON qs.question_id = q.id
                    WHERE q.parent_id = p_parent_question_id
                    ORDER BY qs.status ASC
                ), get_status_to_change AS (
                    SELECT
                        qs.status,
                        qs.process
                    FROM subquestion_status qs
                    LIMIT 1
                ), change_status_parent_question AS (
                    UPDATE parent_question pq
                    SET status = (select gstc.status from get_status_to_change gstc)
                    WHERE pq.id = p_parent_question_id
                ), delete_observation_parent AS (
                    UPDATE parent_observation po
                    SET fl_status = false,
                        deleted_at = now(),
                        deleted_by = p_updated_by
                    WHERE po.parent_id = p_parent_question_id
                        AND po.type = 'DUPL'
                        AND po.fl_status = true
                ), user_created AS (
                    SELECT
                        CASE WHEN e.id IS NULL
                            THEN 'Administrador'
                            ELSE concat(
                                split_part(e.first_name, ' ', 1),
                                ' ',
                                upper(left(e.first_surname, 1)),
                                '. ',
                                e.second_surname
                            )
                            END user_name,
                            COALESCE(r.name, 'usuario') rol
                    FROM users u
                    JOIN users_roles ur ON u.id = ur.user_id
                        AND ur.fl_status = true
                    JOIN roles r ON ur.rol_id = r.id
                    LEFT JOIN employees e ON u.id = e.user_id
                    WHERE u.id = p_updated_by
                ), desription_archived AS (
                    SELECT
                        CONCAT(
                            'La pregunta se cambió a',
                            LOWER(gstc.process),
                            ' por el ',
                            uc.rol,
                            ' <span class="text-user">',
                            uc.user_name,
                            '</span>'
                        )::VARCHAR description,
                        gstc.process,
                        gstc.status
                    FROM user_created uc, get_status_to_change gstc
                    LIMIT 1
                ), subquestion AS (
                    SELECT
                        q.id,
                        da.description,
                        da.process,
                        da.status
                    FROM question q, desription_archived da
                    WHERE q.parent_id = p_parent_question_id
                    AND q.fl_status = true
                ), desactive_status AS (
                    UPDATE question_status
                    SET fl_active = false
                    WHERE question_id IN (
                        SELECT id
                        FROM subquestion
                    )
                ), delete_observations_subquestion AS (
                    UPDATE question_observation qo
                    SET fl_status = false,
                        deleted_at = now(),
                        deleted_by = p_updated_by
                    WHERE qo.question_id IN (
                        SELECT sq.id
                        FROM subquestion sq
                    )
                        AND qo.type = 'DUPL'
                        AND qo.fl_status = true
                )
                INSERT INTO question_status (
                    question_id,
                    status,
                    process,
                    description,
                    created_by,
                    created_at
                )
                SELECT
                    q.id,
                    q.status,
                    q.process,
                    q.description,
                    p_updated_by,
                    NOW()
                FROM subquestion q;

                RETURN;
            END;
            $$;


ALTER FUNCTION odiseo.fn_change_status_parent_question(p_parent_question_id bigint, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_change_status_question(integer, character varying, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_change_status_question(p_id integer, p_status character varying, p_updated_by integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_question_id INTEGER;
            BEGIN
                UPDATE odiseo.question
                SET
                    status = p_status,
                    teacher_id = CASE
                                    WHEN p_status = 'SASI' THEN NULL
                                    ELSE teacher_id
                                END,
                    updated_by = p_updated_by,
                    updated_at = now()
                WHERE
                    id = p_id
                RETURNING id INTO v_question_id;

                IF p_status = 'SASI' THEN
                    UPDATE odiseo.employee_question
                    SET
                        fl_status = false,
                        deleted_by = p_updated_by,
                        deleted_at = now()
                    WHERE
                        question_id = p_id;
                END IF;

                RETURN v_question_id;
            END;
            $$;


ALTER FUNCTION odiseo.fn_change_status_question(p_id integer, p_status character varying, p_updated_by integer) OWNER TO postgres;

--
-- Name: fn_change_status_reserved_to_verified(integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_change_status_reserved_to_verified(p_question_id integer, p_user_id integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_exist_question BOOL;
            BEGIN
                -- Verificar si la pregunta con estado 'RESV' y fl_status = TRUE existe
                SELECT COUNT(*) > 0
                INTO v_exist_question
                FROM odiseo.question q
                WHERE q.status = 'RESV'
                AND q.fl_status = TRUE
                AND q.id = p_question_id;

                -- Si la pregunta existe, actualizar el estado a 'VERI'
                IF v_exist_question THEN
                    -- Actualizar el estado de la pregunta
                    UPDATE odiseo.question
                    SET status = 'VERI', resv_to_veri_at = NULL
                    WHERE id = p_question_id
                    AND fl_status = TRUE;

                    -- Desactivar estado previo en question_status
                    UPDATE odiseo.question_status
                    SET fl_active = FALSE
                    WHERE question_id = p_question_id;

                    -- Insertar un nuevo registro en question_status
                    INSERT INTO odiseo.question_status (
                        question_id, status, fl_active, process, description, created_by, created_at
                    ) VALUES (
                        p_question_id, 'VERI', TRUE, 'VERIFICADO',
                        'La pregunta fue cambiada al estado verificado por el usuario <span class=''text-user''> Admin </span>',
                        p_user_id, NOW()
                    );

                    -- Quitando la observación de la tabla question_observation
                        UPDATE odiseo.question_observation
                        SET fl_status = false
                        WHERE question_id = p_question_id AND type = 'RESV';

                    -- Retornar TRUE porque se realizó la actualización
                    RETURN TRUE;
                END IF;

                -- Si no se encontró la pregunta, retornar FALSE
                RETURN FALSE;
            END;
            $$;


ALTER FUNCTION odiseo.fn_change_status_reserved_to_verified(p_question_id integer, p_user_id integer) OWNER TO postgres;

--
-- Name: fn_change_subtopic_frequent_status(integer, integer, integer, boolean, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_change_subtopic_frequent_status(p_university_id integer, p_subtopic_id integer, p_updated_by integer, p_is_frequent boolean, p_method character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
                        BEGIN
                            INSERT INTO frequent_university_subtopic ( university_id, subtopic_id, method, created_at, updated_by )
                            VALUES (p_university_id, p_subtopic_id, p_method, NOW(), p_updated_by)
                            ON CONFLICT (university_id, subtopic_id)
                            DO UPDATE SET
                                    is_frequent = p_is_frequent,
                                    fl_status = p_is_frequent,
                                    updated_at = NOW(),
                                    updated_by = p_updated_by;
                        END;
                        $$;


ALTER FUNCTION odiseo.fn_change_subtopic_frequent_status(p_university_id integer, p_subtopic_id integer, p_updated_by integer, p_is_frequent boolean, p_method character varying) OWNER TO postgres;

--
-- Name: fn_change_topic_subtopics(smallint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_change_topic_subtopics(p_topic_id smallint, p_subtopic_id smallint, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_code VARCHAR;
                v_before_topic_id SMALLINT;
                v_question RECORD;
                v_case_subtopic SMALLINT;
                v_total INTEGER;
                v_max_code_item RECORD;
            BEGIN
                SELECT s.topic_id INTO v_before_topic_id FROM odiseo.subtopic s
                WHERE s.id = p_subtopic_id  AND s.fl_status = true LIMIT 1;

                IF p_topic_id <> v_before_topic_id THEN

                -- Obtener todas las preguntas que tienen este subtema
                    FOR v_question IN
                        SELECT * FROM odiseo.fn_get_question_by_subtopic(p_subtopic_id)
                    LOOP

                        -- Comprobar si 'subtopics' está vacío o es NULL
                        IF v_question.subtopics IS NULL OR jsonb_array_length(v_question.subtopics) = 0 THEN
                            -- Si no hay subtemas, saltar a la siguiente pregunta
                            CONTINUE;
                        END IF;

                        -- Obtener los subtemas asociados a la pregunta
                        v_total := jsonb_array_length(v_question.subtopics);

                        -- Caso 1: Pregunta con un solo subtema
                        IF v_total = 1 THEN
                            v_case_subtopic := 1;

                        -- Modificando el tema de la pregunta
                        UPDATE odiseo.question  SET topic_id = p_topic_id  WHERE id =  v_question.id AND fl_status = TRUE;

                        -- Caso 2: Pregunta con varios subtemas
                        ELSE
                            -- Extraer y analizar los códigos dentro de 'subtopics' (arreglo JSON)
                            -- Asumimos que v_question.subtopics es un JSON
                            WITH subtopics_data AS (
                                SELECT jsonb_array_elements(v_question.subtopics) AS subtopic
                            )
                            -- Encontrar el subtema con el código más alto
                            SELECT subtopic->>'code' AS code, subtopic->>'id' AS id
                            INTO v_max_code_item
                            FROM subtopics_data
                            ORDER BY CAST(subtopic->>'code' AS INTEGER) DESC
                            LIMIT 1;

                            RAISE NOTICE 'Comparando v_max_code_item.id: %, p_subtopic_id: %', v_max_code_item.id, p_subtopic_id;

                            -- Si el subtema actual tiene el código más alto, es el mayor
                            IF v_max_code_item.id = CAST(p_subtopic_id AS TEXT) THEN

                                RAISE NOTICE 'El tema es mayor';
                                -- Modificando el tema de la pregunta
                                UPDATE odiseo.question  SET topic_id = p_topic_id  WHERE id =  v_question.id AND fl_status = TRUE;

                                -- Modificando el subtema de la pregunta en la tabla question_subtopic
                                UPDATE odiseo.question_subtopic  SET fl_status = false, deleted_by = p_updated_by, deleted_at = now() WHERE question_id =  v_question.id AND subtopic_id != p_subtopic_id; 

                                v_case_subtopic := 3;  -- Es el subtema mayor
                            ELSE
                                RAISE NOTICE 'El tema es menor %,p_question_id : %, p_topic_id', v_question.id, p_topic_id ;
                                -- Modificando el subtema de la pregunta en la tabla question_subtopic
                                UPDATE odiseo.question_subtopic  SET fl_status = false, deleted_by = p_updated_by, deleted_at = now() WHERE question_id =  v_question.id AND subtopic_id = p_subtopic_id; 
                                v_case_subtopic := 2;  -- No es el subtema mayor
                            END IF;
                        END IF;
                    END LOOP;

                    -- Generar codigo para el subtema
                    SELECT LPAD(CAST(COALESCE(MAX(CAST(su.code AS INTEGER)), 0) + 1 AS TEXT), 2, '0')::VARCHAR INTO v_code FROM odiseo.subtopic su WHERE su.topic_id = p_topic_id LIMIT 1;

                    -- Actualiza el tema a al subtema seleccionado
                    UPDATE odiseo.subtopic SET code = v_code, topic_id = p_topic_id, updated_by = p_updated_by, updated_at = now()
                    WHERE id = p_subtopic_id;

                -- Llamar al procedimiento para actualizar los subtemas en los templates del syllabus
                    CALL odiseo.sp_change_syllabus_template_subtopics(p_topic_id, p_subtopic_id, p_updated_by);

                    -- Actualiza el subtema del syllabus
                    UPDATE odiseo.syllabus_detail_subtopic SET is_topic_modified = TRUE WHERE subtopic_id = p_subtopic_id AND fl_status = true;

                -- Registrar el cambio en el historial
                    INSERT INTO odiseo.subtopic_history (subtopic_id, topic_id, created_by, created_at)
                    VALUES (p_subtopic_id, v_before_topic_id, p_updated_by, now());
                END IF;
            END;
        $$;


ALTER FUNCTION odiseo.fn_change_topic_subtopics(p_topic_id smallint, p_subtopic_id smallint, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_change_user_courses(bigint, jsonb, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_change_user_courses(p_employee_id bigint, p_courses jsonb, p_company_id bigint, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
    BEGIN
        WITH get_courses AS (
            SELECT
                course::BIGINT AS course_id
            FROM jsonb_array_elements(p_courses) course
        ), rol_user_edit AS (
            SELECT
                r.name AS rol,
                CASE
                    WHEN e.user_id IS NOT NULL THEN
                        CONCAT(split_part(e.first_name, ' ', 1), ' ', upper(left(e.first_surname, 1)), '. ', e.second_surname)
                    ELSE 'admin-odiseo'
                END AS user_name
            FROM users_roles ur
            INNER JOIN roles r ON ur.rol_id = r.id
            LEFT JOIN users u ON ur.user_id = u.id
            LEFT JOIN employees e ON u.id = e.user_id
            WHERE ur.user_id = p_updated_by
        ), get_employees AS (
            SELECT
                e.id,
                concat(
                    split_part(e.first_name, ' ', 1),
                    ' ',
                    upper(left(e.first_surname, 1)),
                    '. ',
                    e.second_surname
                ) AS employee_name,
                e.charge_id
            FROM employees e
            WHERE e.id = p_employee_id
                AND e.company_id = p_company_id
        ), deleted_courses AS (
            UPDATE employee_course ec
            SET fl_status = false,
                deleted_by = p_updated_by,
                deleted_at = now()
            WHERE ec.teacher_id = p_employee_id
                AND ec.fl_status IS TRUE
                AND NOT EXISTS (
                    SELECT 1
                    FROM get_courses gc
                    WHERE gc.course_id = ec.course_id
                )
            RETURNING ec.course_id
        ), insert_courses AS (
            INSERT INTO employee_course AS ec(
                teacher_id,
                course_id,
                created_by,
                created_at
            )
            SELECT
                p_employee_id,
                gc.course_id,
                p_updated_by,
                now()
            FROM get_courses gc
            WHERE NOT EXISTS (
                SELECT 1
                FROM employee_course ec
                WHERE ec.teacher_id = p_employee_id
                    AND ec.course_id = gc.course_id
                    AND ec.fl_status IS TRUE
            )
            RETURNING ec.course_id
        ), deleted_questions_is_teacher AS (
            UPDATE employee_question AS eq
            SET fl_status = false,
                deleted_by = p_updated_by,
                deleted_at = NOW()
            FROM question q,
                get_employees ge
            WHERE ge.id = eq.teacher_id
                AND ge.charge_id = 2
                AND eq.fl_status = true
                AND eq.question_id = q.id
                AND q.fl_status = true
                AND q.status IN ('ASIG', 'RESO')
                AND q.course_id IN (SELECT dc.course_id FROM deleted_courses dc)
            RETURNING eq.question_id
        ), change_status_question AS (
            UPDATE question AS q
            SET status = 'SASI',
                updated_by = p_updated_by,
                updated_at = NOW()
            WHERE q.id IN (SELECT eq.question_id FROM deleted_questions_is_teacher eq)
            RETURNING q.id, q.parent_id
        ), inactive_history_status AS (
            UPDATE question_status qs
            SET fl_active = false,
                updated_at = NOW()
            WHERE qs.question_id IN (SELECT csq.id FROM change_status_question csq)
                AND qs.fl_active = true
        ), save_history_question AS (
            INSERT INTO question_status (
                question_id,
                status,
                process,
                description,
                fl_active,
                created_by,
                created_at
            )
            SELECT
                csq.id,
                'SASI',
                'SIN ASIGNACIÓN',
                CONCAT(
                    'La pregunta se le ha quitado al Docente <span class="text-teacher">',
                    ge.employee_name,
                    '</span> por el ',
                    rue.user_name,
                    ' <span class="text-user">',
                    rue.rol,
                    '</span>'
                ),
                true,
                p_updated_by,
                NOW()
            FROM change_status_question csq,
                get_employees ge,
                rol_user_edit rue
        )
        UPDATE parent_question pq
        SET status = 'SASI',
            updated_by = p_updated_by,
            updated_at = NOW()
        WHERE pq.id IN (
            SELECT
                csq.parent_id
            FROM change_status_question csq
            WHERE csq.parent_id IS NOT NULL
        );
    END;
    $$;


ALTER FUNCTION odiseo.fn_change_user_courses(p_employee_id bigint, p_courses jsonb, p_company_id bigint, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_check_if_teacher_question_amount_exceed_limit(character varying, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_check_if_teacher_question_amount_exceed_limit(p_question_status character varying, p_teacher_id integer, p_question_amount_limit integer) RETURNS TABLE(exceed_limit boolean, question_amount_to_fill integer)
    LANGUAGE plpgsql
    AS $$

            DECLARE question_amount INTEGER;
            DECLARE exceed_limit BOOLEAN;
            DECLARE question_amount_to_fill INTEGER;

            BEGIN
                SELECT
                    COUNT(*)
                INTO question_amount
                FROM odiseo.employee_question eq
                JOIN odiseo.question q ON eq.question_id = q.id
                JOIN odiseo.employees e ON e.id = eq.teacher_id
                WHERE 1 = 1
                  AND e.user_id = p_teacher_id
                  AND eq.fl_status IS TRUE
                  AND eq.deleted_at IS NULL
                  AND q.fl_status IS TRUE
                  And q.deleted_at IS NULL
                  AND q.status = p_question_status;

                exceed_limit := question_amount >= p_question_amount_limit;
                question_amount_to_fill := p_question_amount_limit - question_amount;

                RETURN QUERY
                SELECT exceed_limit, question_amount_to_fill;
            END;
            $$;


ALTER FUNCTION odiseo.fn_check_if_teacher_question_amount_exceed_limit(p_question_status character varying, p_teacher_id integer, p_question_amount_limit integer) OWNER TO postgres;

--
-- Name: fn_child_parent_question(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_child_parent_question(p_parent_id bigint) RETURNS TABLE(id bigint, code character varying, parent_id bigint, status character varying, fl_status boolean)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            SELECT
                q.id,
                q.code,
                q.parent_id,
                q.status,
                q.fl_status
            FROM odiseo.question q
            WHERE q.parent_id = p_parent_id
            AND q.fl_status = true
            ORDER BY q.id ASC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_child_parent_question(p_parent_id bigint) OWNER TO postgres;

--
-- Name: fn_classroom_cycle(integer, integer, smallint, smallint, bigint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_classroom_cycle(p_perpage integer, p_npage integer, f_university_id smallint, f_headquarters_id smallint, f_cycle_id bigint, f_classroom_id smallint) RETURNS TABLE(cycle_id bigint, code_cycle character varying, description_cycle character varying, university_id smallint, university character varying, headquarters_id smallint, code_headquarters character varying, headquarters character varying, slug_headquarters character varying, classroom_id smallint, code_classroom character varying, classroom character varying, total bigint)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            offset_val INTEGER;
        BEGIN
            -- Calculate the offset
            offset_val := p_perpage * (p_npage - 1);

            RETURN QUERY
            WITH tbl_university AS (
                SELECT
                    u.id AS university_id,
                    u.name AS university,
                    uh.headquarters_id,
                    h.code AS code_headquarters,
                    h.name AS headquarters,
                    h.slug AS slug_headquarters,
                    hc.classroom_id,
                    c.code AS code_classroom,
                    c.number AS classroom
                FROM odiseo.origin_university u
                INNER JOIN odiseo.university_headquarters uh ON u.id = uh.university_id AND uh.fl_status = true
                INNER JOIN odiseo.headquarters h ON uh.headquarters_id = h.id
                INNER JOIN odiseo.headquarters_classroom hc ON h.id = hc.headquarters_id
                INNER JOIN odiseo.classroom c ON hc.classroom_id = c.id AND c.id = 1
                WHERE (f_university_id IS NULL OR u.id = f_university_id)
                AND (f_headquarters_id IS NULL OR uh.headquarters_id = f_headquarters_id)
                AND (f_classroom_id IS NULL OR hc.classroom_id = f_classroom_id)
            ),
            tbl_cycle_university AS (
                SELECT
                    cy.id AS cycle_id,
                    cy.code AS code_cycle,
                    cy.description AS description_cycle,
                    u.university_id,
                    u.university,
                    u.headquarters_id,
                    u.code_headquarters,
                    u.headquarters,
                    u.slug_headquarters,
                    u.classroom_id,
                    u.code_classroom,
                    u.classroom
                FROM odiseo.cycle cy
                CROSS JOIN tbl_university u
                WHERE (f_cycle_id IS NULL OR cy.id = f_cycle_id)
            ),
            counted_cycle_university AS (
                SELECT *, COUNT(*) OVER () AS total
                FROM tbl_cycle_university
                ORDER BY cycle_id ASC, university ASC, headquarters_id ASC, classroom_id ASC
            )

            SELECT * FROM counted_cycle_university
            LIMIT p_perpage
            OFFSET offset_val;
        END;
        $$;


ALTER FUNCTION odiseo.fn_classroom_cycle(p_perpage integer, p_npage integer, f_university_id smallint, f_headquarters_id smallint, f_cycle_id bigint, f_classroom_id smallint) OWNER TO postgres;

--
-- Name: fn_clean_ballor_url_period(bigint, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_clean_ballor_url_period(p_material_per_period_ballot_id bigint, p_type character varying, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
    BEGIN
        WITH clean_urls_per_period_ballot AS (
            UPDATE material_per_period_ballot_url mppbu
            SET job_url = NULL,
                job_id = NULL,
                file_name = NULL,
                fl_job_process = 'unprocessed',
                number_pages = null,
                retries = 0,
                updated_by = p_updated_by,
                updated_at = now()
            WHERE mppbu.material_per_period_ballot_id = p_material_per_period_ballot_id
                AND (p_type IS NULL OR mppbu.type_url = p_type)
        ), clean_week_courses AS (
            UPDATE material_per_period_week_course mppwc
            SET url = NULL,
                job_id = NULL,
                updated_at = NOW(),
                updated_by = p_updated_by,
                job_status = 'unprocessed'
            WHERE mppwc.material_per_period_ballot_id = p_material_per_period_ballot_id
            AND (p_type IS NULL OR mppwc.type = p_type)
        )
        UPDATE material_per_period_course mppc
        SET url = NULL,
            job_id = NULL,
            updated_at = NOW(),
            updated_by = p_updated_by,
            job_status = 'unprocessed',
            pages = 0,
            retries = 0
        WHERE mppc.material_per_period_ballot_id = p_material_per_period_ballot_id
        AND (p_type IS NULL OR mppc.type = p_type);
    END;
    $$;


ALTER FUNCTION odiseo.fn_clean_ballor_url_period(p_material_per_period_ballot_id bigint, p_type character varying, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_clean_cycle_posterior_weeks(bigint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_clean_cycle_posterior_weeks(p_cycle_id bigint, p_weeks smallint) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- type_material (Query 3)
    UPDATE type_material_detail_text_subquestions tmdts
    SET deleted_at = now()
    FROM type_material_detail_course_texts tmdct
    JOIN type_material_detail_template tmdt ON tmdt.id = tmdct.type_material_detail_template_id
    JOIN type_material tm ON tm.id = tmdt.type_material_id
    WHERE tmdts.type_material_detail_course_text_id = tmdct.id
      AND tm.cycle_id = p_cycle_id
      AND tmdt.week > p_weeks
      AND tmdts.deleted_at IS NULL;

    UPDATE type_material_detail_course_texts tmdct
    SET deleted_at = now(), fl_status = false
    FROM type_material_detail_template tmdt
    JOIN type_material tm ON tm.id = tmdt.type_material_id
    WHERE tmdct.type_material_detail_template_id = tmdt.id
      AND tm.cycle_id = p_cycle_id
      AND tmdt.week > p_weeks
      AND tmdct.fl_status IS TRUE;

    -- type_material (Query 1)
    UPDATE type_material_detail_courses tmdc
    SET deleted_at = now(), fl_status = false
    FROM type_material tm
    JOIN type_material_detail_template tmdt ON tmdt.type_material_id = tm.id
    WHERE tmdc.type_material_detail_template_id = tmdt.id
      AND tm.cycle_id = p_cycle_id 
      AND tmdt.week > p_weeks
      AND tmdc.fl_status IS TRUE;

    UPDATE type_material_detail_template tmdt
    SET deleted_at = now(), fl_status = false
    FROM type_material tm
    WHERE tmdt.type_material_id = tm.id
      AND tm.cycle_id = p_cycle_id
      AND tmdt.week > p_weeks
      AND tmdt.fl_status IS TRUE;

    -- type_text_material_type_course (only deleted_at, as requested)
    UPDATE type_text_material_type_course ttmtc
    SET deleted_at = now()
    FROM type_material_course tmc
    JOIN type_material tm ON tm.id = tmc.type_material_id
    JOIN type_material_detail_template tmdt ON tmdt.type_material_id = tm.id
    WHERE ttmtc.type_material_id = tm.id  
      AND tmc.course_id = ttmtc.course_id
      AND tm.cycle_id = p_cycle_id
      AND tmdt.week > p_weeks
      AND ttmtc.deleted_at IS NULL;

    -- syllabus (Query 4)
    UPDATE syllabus_subtopic_type_material sstm
    SET deleted_at = now(), fl_status = false
    FROM syllabus_detail_subtopic sds
    JOIN syllabus_topic_week stw ON stw.id = sds.syllabus_topic_week_id
    JOIN syllabus_topic st ON st.id = stw.syllabus_topic_id
    JOIN syllabus s ON s.id = st.syllabus_id
    WHERE sstm.syllabus_detail_subtopic_id = sds.id
      AND s.cycle_id = p_cycle_id
      AND stw.week > p_weeks
      AND sstm.fl_status IS TRUE;

    UPDATE syllabus_detail_subtopic sds
    SET deleted_at = now(), fl_status = false
    FROM syllabus_topic_week stw
    JOIN syllabus_topic st ON st.id = stw.syllabus_topic_id
    JOIN syllabus s ON s.id = st.syllabus_id
    WHERE sds.syllabus_topic_week_id = stw.id
      AND s.cycle_id = p_cycle_id
      AND stw.week > p_weeks
      AND sds.fl_status IS TRUE;

    UPDATE syllabus_topic_week stw
    SET deleted_at = now(), fl_status = false
    FROM syllabus_topic st
    JOIN syllabus s ON s.id = st.syllabus_id
    WHERE stw.syllabus_topic_id = st.id
      AND s.cycle_id = p_cycle_id
      AND stw.week > p_weeks
      AND stw.fl_status IS TRUE;

    -- syllabus_week_titles (Added as requested)
    UPDATE syllabus_week_titles swt
    SET deleted_at = now(), fl_status = false
    FROM syllabus s
    WHERE swt.syllabus_id = s.id
      AND s.cycle_id = p_cycle_id
      AND swt.week > p_weeks
      AND swt.fl_status IS TRUE;

    -- syllabus_text (Query 5)
    UPDATE syllabus_text_content stc
    SET fl_status = false
    FROM syllabus_text_distributions std
    JOIN syllabus_text_weeks stw ON stw.id = std.syllabus_text_week_id
    JOIN syllabus s ON s.id = stw.syllabus_id
    WHERE stc.syllabus_text_id = std.id
      AND s.cycle_id = p_cycle_id
      AND stw.week > p_weeks
      AND stc.fl_status IS TRUE;

    UPDATE syllabus_text_distributions std
    SET fl_status = false
    FROM syllabus_text_weeks stw
    JOIN syllabus s ON s.id = stw.syllabus_id
    WHERE std.syllabus_text_week_id = stw.id
      AND s.cycle_id = p_cycle_id
      AND stw.week > p_weeks
      AND std.fl_status IS TRUE;

    UPDATE syllabus_text_weeks stw
    SET fl_status = false
    FROM syllabus s
    WHERE stw.syllabus_id = s.id
      AND s.cycle_id = p_cycle_id
      AND stw.week > p_weeks
      AND stw.fl_status IS TRUE;

    -- level_syllabus (Query 6 & 7)
    UPDATE detail_level_syllabus_weeks dlsw
    SET deleted_at = now(), fl_status = false
    FROM level_syllabus_weeks lsw
    JOIN level_syllabus ls ON ls.id = lsw.level_syllabus_id
    WHERE dlsw.level_syllabus_weeks_id = lsw.id
      AND ls.cycle_id = p_cycle_id
      AND lsw.week > p_weeks
      AND dlsw.fl_status IS TRUE;

    UPDATE detail_level_syllabus_weeks_parents dlswp
    SET deleted_at = now(), fl_status = false
    FROM level_syllabus_weeks lsw
    JOIN level_syllabus ls ON ls.id = lsw.level_syllabus_id
    WHERE dlswp.level_syllabus_weeks_id = lsw.id
      AND ls.cycle_id = p_cycle_id
      AND lsw.week > p_weeks
      AND dlswp.fl_status IS TRUE;

    UPDATE level_syllabus_weeks lsw
    SET deleted_at = now(), fl_status = false
    FROM level_syllabus ls
    WHERE lsw.level_syllabus_id = ls.id
      AND ls.cycle_id = p_cycle_id
      AND lsw.week > p_weeks
      AND lsw.fl_status IS TRUE;

END;
$$;


ALTER FUNCTION odiseo.fn_clean_cycle_posterior_weeks(p_cycle_id bigint, p_weeks smallint) OWNER TO postgres;

--
-- Name: fn_clean_material_per_period_course(bigint, jsonb, bigint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_clean_material_per_period_course(p_material_per_period_ballot_id bigint, p_courses jsonb, p_updated_by bigint, p_type character varying DEFAULT NULL::character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
    BEGIN
        WITH clean_material_per_period_course AS (
            UPDATE material_per_period_course mppc
            SET url = NULL,
                job_id = NULL,
                updated_at = NOW(),
                updated_by = p_updated_by,
                job_status = 'unprocessed'
            WHERE mppc.material_per_period_ballot_id = p_material_per_period_ballot_id
            AND (p_type IS NULL OR mppc.type = p_type)
            AND (
                mppc.course_id IS NULL
                OR mppc.course_id = ANY (
                    SELECT (jsonb_array_elements_text(p_courses))::SMALLINT
                )
            )
        )
        UPDATE material_per_period_week_course mppwc
        SET url = NULL,
            job_id = NULL,
            updated_at = NOW(),
            updated_by = p_updated_by,
            job_status = 'unprocessed'
        WHERE mppwc.material_per_period_ballot_id = p_material_per_period_ballot_id
        AND (p_type IS NULL OR mppwc.type = p_type)
        AND (
            mppwc.course_id IS NULL
            OR mppwc.course_id = ANY (
                SELECT (jsonb_array_elements_text(p_courses))::SMALLINT
            )
        );
    END;
    $$;


ALTER FUNCTION odiseo.fn_clean_material_per_period_course(p_material_per_period_ballot_id bigint, p_courses jsonb, p_updated_by bigint, p_type character varying) OWNER TO postgres;

--
-- Name: fn_clean_material_url_per_period(bigint, bigint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_clean_material_url_per_period(p_material_id bigint, p_type_material_id bigint, p_week smallint, p_updated_by bigint) RETURNS TABLE(id bigint, material_id bigint, type_material_id smallint, start_week smallint, end_week smallint)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        WITH get_parent_type_material AS (
            SELECT CASE
                WHEN EXISTS (SELECT 1 FROM type_material tm WHERE tm.id = p_type_material_id AND tm.parent_id IS NOT NULL)
                THEN ARRAY(SELECT tm.parent_id FROM type_material tm WHERE tm.id = p_type_material_id AND tm.parent_id IS NOT NULL)
                ELSE ARRAY[p_type_material_id]
            END AS parent_type_material_id
        ), get_material_per_period_ballot AS (
            SELECT
                mppb.id
            FROM odiseo.material_per_period_ballot mppb
            JOIN material_per_period mpp ON mpp.id = mppb.material_per_period_id
            WHERE mpp.material_id = p_material_id
                AND mpp.type_material_id IN (SELECT unnest(gptm.parent_type_material_id) FROM get_parent_type_material gptm)
                AND p_week BETWEEN mppb.start_week AND mppb.end_week
                AND mppb.deleted_by IS NULL
            LIMIT 1
        ), clean_urls_per_period_ballot AS (
            UPDATE material_per_period_ballot_url mppbu
            SET job_url = null,
                job_id = null,
                file_name = null,
                fl_job_process = 'unprocessed',
                number_pages = null,
                retries = 0,
                updated_by = p_updated_by,
                updated_at = now()
            WHERE mppbu.material_per_period_ballot_id = (SELECT gmpb.id FROM get_material_per_period_ballot gmpb)
            AND mppbu.deleted_by IS NULL
        ), clean_week_courses AS (
            UPDATE material_per_period_week_course mppwc
            SET url = NULL,
                job_id = NULL,
                updated_by = p_updated_by,
                updated_at = NOW(),
                job_status = 'unprocessed'
            WHERE mppwc.material_per_period_ballot_id = (SELECT gmpb.id FROM get_material_per_period_ballot gmpb)
        ), clean_courses AS (
            UPDATE material_per_period_course mppc
            SET url = NULL,
                job_id = NULL,
                updated_by = p_updated_by,
                updated_at = NOW(),
                job_status = 'unprocessed',
                pages = 0,
                retries = 0
            WHERE mppc.material_per_period_ballot_id = (SELECT gmpb.id FROM get_material_per_period_ballot gmpb)
        )
        SELECT
            mppb.id,
            mpp.material_id,
            mpp.type_material_id,
            mppb.start_week,
            mppb.end_week
        FROM material_per_period_ballot mppb
        JOIN material_per_period mpp ON mpp.id = mppb.material_per_period_id
        WHERE mppb.id = (SELECT gmpb.id FROM get_material_per_period_ballot gmpb)
            AND mppb.deleted_by IS NULL;
    END;
    $$;


ALTER FUNCTION odiseo.fn_clean_material_url_per_period(p_material_id bigint, p_type_material_id bigint, p_week smallint, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_clear_exam_urls_by_material(bigint, bigint, integer, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_clear_exam_urls_by_material(p_material_id bigint, p_type_material_id bigint, p_week integer, p_areas jsonb, p_deleted_by bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_week_type_material_id bigint;
BEGIN
    -- Limpia URLs y estados del detalle semana - tipo material
    UPDATE detail_week_type_mat detm
    SET url_solution               = NULL,
        url_without_solution       = NULL,
        fl_process_status          = 1,
        fl_process_status_without  = 1,
        fl_process_class_mat       = 1,
        url_zip_class_mat           = NULL,
        url_quality                = NULL,
        url_without_quality        = NULL,
        fl_process_quality         = 1,
        fl_process_without_quality = 1,
        updated_by                 = p_deleted_by,
        updated_at                 = now()
    WHERE detm.material_id = p_material_id
    AND detm.week = p_week
    AND detm.type_material_id = p_type_material_id
    AND detm.fl_status = true
    RETURNING detm.id
    INTO v_week_type_material_id;

    -- Si existe el registro, limpia URLs de los exámenes por área
    IF v_week_type_material_id IS NOT NULL THEN
        UPDATE material_exam_area_week meaw
        SET url_solution               = NULL,
            url_without_solution       = NULL,
            fl_process_status          = 1,
            fl_process_status_without  = 1,
            url_quality                = NULL,
            url_without_quality        = NULL,
            fl_process_quality         = 1,
            fl_process_without_quality = 1,
            data_missing_course_config = NULL,
            missing_config_message     = NULL,
            updated_by                 = p_deleted_by,
            updated_at                 = now()
        WHERE meaw.week_type_material_id = v_week_type_material_id
        AND meaw.area_id = ANY (
            SELECT jsonb_array_elements_text(p_areas)::bigint
        )
        AND meaw.fl_status = true;
    END IF;

    RETURN v_week_type_material_id;
END;
$$;


ALTER FUNCTION odiseo.fn_clear_exam_urls_by_material(p_material_id bigint, p_type_material_id bigint, p_week integer, p_areas jsonb, p_deleted_by bigint) OWNER TO postgres;

--
-- Name: fn_companies(integer, integer, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_companies(p_perpage integer, p_npage integer, p_text character varying) RETURNS TABLE(id bigint, uuid uuid, social_reason character varying, commercial_name character varying, type_company character varying, document_number character varying, domain_email character varying, schema character varying, address character varying, city character varying, state character varying, main_number character varying, other_number character varying, prospect_id bigint, plan_id bigint, plan character varying, plan_description character varying, plan_cost numeric, fl_status boolean, total integer)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            total_count INTEGER;
            offset_val INTEGER;
        begin

            offset_val := p_perpage * (p_npage - 1);

            SELECT COUNT(*)
            INTO total_count
            FROM odiseo.companies c
            LEFT JOIN odiseo.plans p ON c.plan_id = p.id
            WHERE
                (p_text IS NULL
                OR unaccent(c.social_reason) ILIKE '%' || unaccent(p_text) || '%'
                OR unaccent(c.commercial_name) ILIKE '%' || unaccent(p_text) || '%'
                OR unaccent(c.document_number) ILIKE '%' || unaccent(p_text) || '%');

            RETURN QUERY
            SELECT
                c.id,
                c.uuid,
                c.social_reason,
                c.commercial_name,
                c.type_company,
                c.document_number,
                c.domain_email,
                c."schema",
                c.address,
                c.city,
                c.state,
                c.main_number,
                c.other_number,
                c.prospect_id,
                c.plan_id,
                p.name AS plan,
                p.description AS plan_description,
                p.cost AS plan_cost,
                c.fl_status,
                total_count AS total
            FROM odiseo.companies c
            LEFT JOIN odiseo.plans p ON c.plan_id = p.id
            WHERE
                (p_text IS NULL
                OR unaccent(c.social_reason) ILIKE '%' || unaccent(p_text) || '%'
                OR unaccent(c.commercial_name) ILIKE '%' || unaccent(p_text) || '%'
                OR unaccent(c.document_number) ILIKE '%' || unaccent(p_text) || '%')
            ORDER by c.social_reason ASC, c.document_number ASC
            LIMIT p_perpage
            OFFSET offset_val;
        END;
        $$;


ALTER FUNCTION odiseo.fn_companies(p_perpage integer, p_npage integer, p_text character varying) OWNER TO postgres;

--
-- Name: fn_completed_questions_ballot(bigint, smallint, boolean, boolean, boolean, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_completed_questions_ballot(p_material_per_period_ballot_id bigint, p_week_type_material_id smallint, p_fl_missing_questions boolean, p_fl_missing_courses boolean, p_fl_missing_text boolean, p_distribution_questions jsonb, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_material_id bigint;
    v_week smallint;
    v_cycle_id bigint;
    v_university_id smallint;
    v_headquarters_id bigint;
    v_type_material_id smallint;
    v_parent_type_material_id smallint;
    v_record_found boolean;
BEGIN
    -- 1. Obtener datos de contexto
    SELECT
        m.id,
        dwtm.week,
        m.cycle_id,
        m.university_id,
        m.headquarte_id,
        dwtm.type_material_id,
        dwtm.parent_type_material_id
        INTO 
        v_material_id,
        v_week,
        v_cycle_id,
        v_university_id,
        v_headquarters_id,
        v_type_material_id,
        v_parent_type_material_id
    FROM detail_week_type_mat dwtm
    JOIN material m ON dwtm.material_id = m.id
    WHERE dwtm.id = p_week_type_material_id;

    GET DIAGNOSTICS v_record_found = ROW_COUNT;
    IF NOT v_record_found THEN
        RAISE EXCEPTION 'No hay data en la tabla week_type_material_id: %', p_week_type_material_id;
    END IF;

    -- 2. Actualizar las flags del balotario.
    UPDATE material_per_period_ballot mppb
    SET fl_missing_questions = CASE WHEN p_fl_missing_questions = TRUE AND mppb.fl_missing_questions = FALSE THEN mppb.fl_missing_questions ELSE p_fl_missing_questions END,
        fl_missing_courses = CASE WHEN p_fl_missing_courses = TRUE AND mppb.fl_missing_courses = FALSE THEN mppb.fl_missing_courses ELSE p_fl_missing_courses END,
        fl_missing_text = CASE WHEN p_fl_missing_text = TRUE AND mppb.fl_missing_text = FALSE THEN mppb.fl_missing_text ELSE p_fl_missing_text END
    WHERE mppb.id = p_material_per_period_ballot_id;

    -- 3. MERGE en question_history_cycle (insertar solo si no existe)
    MERGE INTO question_history_cycle AS target
    USING (
        SELECT DISTINCT
            (q ->> 'question_id')::bigint AS question_id,
            (q ->> 'parent_question_id')::bigint AS parent_question_id
        FROM jsonb_array_elements(p_distribution_questions) AS q
        WHERE (q ->> 'question_id') IS NOT NULL OR (q ->> 'parent_question_id') IS NOT NULL
    ) AS source 
    ON COALESCE(target.question_id, target.parent_question_id) = COALESCE(source.question_id, source.parent_question_id)
        AND target.cycle_id = v_cycle_id
        AND target.university_id = v_university_id
        AND target.headquarters_id = v_headquarters_id
        AND target.fl_status = TRUE
    WHEN NOT MATCHED THEN
        INSERT (question_id, cycle_id, university_id, headquarters_id, created_by, created_at, parent_question_id)
        VALUES (source.question_id, v_cycle_id, v_university_id, v_headquarters_id, p_updated_by, NOW(), source.parent_question_id);

    -- 4. CTE-Based Arquitectura Declarativa (Set-Based) para máximo rendimiento
    WITH parsed_json AS (
        SELECT
            (q ->> 'id')::bigint AS mbq_id,
            (q ->> 'question_id')::bigint AS question_id,
            (q ->> 'course_id')::smallint AS course_id,
            (q ->> 'topic_id')::smallint AS topic_id,
            (q ->> 'subtopic_id')::smallint AS subtopic_id,
            (q ->> 'level_id')::bigint AS level_id,
            (q ->> 'type')::varchar AS type,
            (q ->> 'position')::bigint AS position,
            (q ->> 'parent_question_id')::bigint AS parent_question_id,
            (q ->> 'subquestion')::jsonb AS subquestion,
            (q ->> 'usage_level_id')::bigint AS usage_level_id,
            (q ->> 'position_initial')::bigint AS position_initial,
            (q ->> 'status_usage')::boolean AS usage_status,
            (q ->> 'absolute_position')::smallint AS absolute_position,
            (q ->> 'is_complete')::boolean AS is_complete,
            (q ->> 'completed_subquestion')::boolean AS completed_subquestion
        FROM jsonb_array_elements(p_distribution_questions) AS q
    ),
    history_lookups AS (
        SELECT pj.course_id, pj.absolute_position, qhc.id AS q_history_id
        FROM parsed_json pj
        LEFT JOIN question_history_cycle qhc 
          ON COALESCE(qhc.question_id, qhc.parent_question_id) = COALESCE(pj.question_id, pj.parent_question_id)
          AND qhc.cycle_id = v_cycle_id
          AND qhc.university_id = v_university_id
          AND qhc.headquarters_id = v_headquarters_id
          AND qhc.fl_status = TRUE
    ),
    updated_mbq AS (
        UPDATE odiseo.material_ballot_question mbq
        SET 
            course_id = pj.course_id,
            absolute_position = pj.absolute_position,
            topic_id = pj.topic_id,
            subtopic_id = pj.subtopic_id,
            level_id = pj.level_id,
            usage_level_id = pj.usage_level_id,
            type = pj.type,
            question_id = pj.question_id,
            parent_question_id = pj.parent_question_id,
            question_history_id = hl.q_history_id,
            position = pj.position,
            position_initial = pj.position_initial,
            usage_status = pj.usage_status,
            fl_status = TRUE,
            state = CASE 
                WHEN pj.question_id IS NULL AND pj.parent_question_id IS NULL THEN 'MISSING' 
                WHEN COALESCE(pj.is_complete, FALSE) = TRUE THEN 'AUTO_COMPLETED'
                ELSE 'GENERATED' 
            END,
            added_in_completion = pj.is_complete,
            completed_subquestion = COALESCE(pj.completed_subquestion, FALSE),
            deleted_at = NULL,
            updated_at = CASE WHEN pj.is_complete IS TRUE THEN NOW() ELSE updated_at END,
            updated_by = p_updated_by
        FROM parsed_json pj
        LEFT JOIN history_lookups hl ON hl.course_id = pj.course_id AND hl.absolute_position = pj.absolute_position
        WHERE mbq.id = pj.mbq_id
        RETURNING mbq.id, pj.course_id, pj.absolute_position
    ),
    inserted_mbq AS (
        INSERT INTO odiseo.material_ballot_question (
            week_type_material_id, material_id, week, type_material_id, course_id, 
            topic_id, subtopic_id, level_id, usage_level_id, type, question_id, 
            parent_question_id, question_history_id, position, position_initial, 
            absolute_position, usage_status, state, fl_status, fl_is_manual, 
            added_in_completion, completed_subquestion, created_by, created_at, updated_at
        )
        SELECT 
            p_week_type_material_id, v_material_id, v_week, v_type_material_id, pj.course_id,
            pj.topic_id, pj.subtopic_id, pj.level_id, pj.usage_level_id, pj.type, pj.question_id,
            pj.parent_question_id, hl.q_history_id, pj.position, pj.position_initial,
            pj.absolute_position, pj.usage_status, 
            CASE 
                WHEN pj.question_id IS NULL AND pj.parent_question_id IS NULL THEN 'MISSING' 
                WHEN COALESCE(pj.is_complete, FALSE) = TRUE THEN 'AUTO_COMPLETED'
                ELSE 'GENERATED' 
            END, 
            TRUE, FALSE, pj.is_complete, COALESCE(pj.completed_subquestion, FALSE), p_updated_by, NOW(),
            CASE WHEN pj.is_complete IS TRUE THEN NOW() ELSE NULL END
        FROM parsed_json pj
        LEFT JOIN history_lookups hl ON hl.course_id = pj.course_id AND hl.absolute_position = pj.absolute_position
        WHERE pj.mbq_id IS NULL
        RETURNING id, course_id, absolute_position
    ),
    all_upserted_mbq AS (
        SELECT id, course_id, absolute_position FROM updated_mbq
        UNION ALL
        SELECT id, course_id, absolute_position FROM inserted_mbq
    ),
    deleted_subquestions AS (
        UPDATE material_ballot_subquestions mbs
        SET fl_status = FALSE, deleted_at = NOW()
        FROM all_upserted_mbq u
        WHERE mbs.material_ballot_question_id = u.id AND mbs.fl_status = TRUE
        RETURNING mbs.id
    )
    INSERT INTO material_ballot_subquestions (material_ballot_question_id, question_id, position, state, topic_id, course_id, subtopic_id, added_in_completion, created_by)
    SELECT 
        u.id,
        (sub.obj->>'question_id')::bigint,
        sub.ord::int,
        CASE WHEN (sub.obj->>'question_id') IS NOT NULL THEN 'AUTO_COMPLETED' ELSE 'MISSING' END,
        (sub.obj->>'topic_id')::smallint,
        (sub.obj->>'course_id')::smallint,
        (sub.obj->>'subtopic_id')::smallint,
        TRUE,
        p_updated_by
    FROM parsed_json pj
    JOIN all_upserted_mbq u ON pj.course_id = u.course_id AND pj.absolute_position = u.absolute_position
    CROSS JOIN jsonb_array_elements(CASE WHEN jsonb_typeof(pj.subquestion) = 'array' THEN pj.subquestion ELSE '[]'::jsonb END) WITH ORDINALITY AS sub(obj, ord);

END;
$$;


ALTER FUNCTION odiseo.fn_completed_questions_ballot(p_material_per_period_ballot_id bigint, p_week_type_material_id smallint, p_fl_missing_questions boolean, p_fl_missing_courses boolean, p_fl_missing_text boolean, p_distribution_questions jsonb, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_configuration_alternative_create(character varying, smallint, text, boolean, boolean, bigint, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_configuration_alternative_create(p_name character varying, p_columns smallint, p_styles text, p_fl_image boolean, p_fl_default boolean, p_company_id bigint, p_user_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
                DECLARE
                    v_new_id integer;
                BEGIN
                    INSERT INTO odiseo.configuration_alternative (name, columns, styles, fl_image, fl_default, fl_status, company_id, created_by, created_at)
                    VALUES (
                        p_name,
                        p_columns,
                        p_styles,
                        p_fl_image,
                        p_fl_default,
                        true,
                        p_company_id,
                        p_user_id,
                        now()
                    )
                    RETURNING id INTO v_new_id;

                    IF p_fl_default = true THEN
                        UPDATE odiseo.configuration_alternative
                        SET fl_default = false
                        WHERE id <> v_new_id AND company_id = p_company_id;
                    END IF;

                    RETURN v_new_id;
                END;
            $$;


ALTER FUNCTION odiseo.fn_configuration_alternative_create(p_name character varying, p_columns smallint, p_styles text, p_fl_image boolean, p_fl_default boolean, p_company_id bigint, p_user_id integer) OWNER TO postgres;

--
-- Name: fn_configuration_alternative_delete(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_configuration_alternative_delete(p_id bigint, p_user_id bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
                DECLARE
                    v_delete_id integer;
                BEGIN
                    UPDATE odiseo.configuration_alternative
                    SET
                        fl_status = false,
                        deleted_by = p_user_id,
                        deleted_at = now()
                    WHERE
                        id = p_id
                    RETURNING id INTO v_delete_id;

                    RETURN v_delete_id;
                END;
            $$;


ALTER FUNCTION odiseo.fn_configuration_alternative_delete(p_id bigint, p_user_id bigint) OWNER TO postgres;

--
-- Name: fn_configuration_alternative_update(bigint, character varying, smallint, text, boolean, boolean, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_configuration_alternative_update(p_id bigint, p_name character varying, p_columns smallint, p_styles text, p_fl_image boolean, p_fl_default boolean, p_company_id bigint, p_user_id bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
    DECLARE
            v_edit_id integer;
        BEGIN
            UPDATE configuration_alternative
            SET
                name = p_name,
                columns = p_columns,
                styles = p_styles,
                fl_image = p_fl_image,
                fl_default = p_fl_default,
                updated_by = p_user_id,
                updated_at = now()
            WHERE
                id = p_id
            RETURNING id INTO v_edit_id;

            IF p_fl_default = true THEN
                UPDATE configuration_alternative
                SET fl_default = false
                WHERE id <> p_id;
            END IF;

            RETURN v_edit_id;
        END;
    $$;


ALTER FUNCTION odiseo.fn_configuration_alternative_update(p_id bigint, p_name character varying, p_columns smallint, p_styles text, p_fl_image boolean, p_fl_default boolean, p_company_id bigint, p_user_id bigint) OWNER TO postgres;

--
-- Name: fn_configuration_alternative_validate_exists_default(integer, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
