--
-- Name: fn_course_all(boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_course_all(f_fl_pseudo_course boolean) RETURNS TABLE(id smallint, code character varying, name character varying, name_course character varying, area_id bigint, area_code character varying, area character varying, setting_diagrammed_course boolean, fl_pseudo_course boolean)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    c.id,
                    c.code,
                    CONCAT(c.code, ' - ', c.name)::VARCHAR AS name,
                    c.name AS name_course,
                    c.area_id,
                    a.code AS area_code,
                    a.description AS area,
                    CASE WHEN COUNT(sdc.course_id) > 0 THEN false ELSE true END AS setting_diagrammed_course,
                    c.fl_pseudo_course
                FROM odiseo.course c
                LEFT JOIN odiseo.area a ON c.area_id = a.id
                LEFT JOIN odiseo.setting_diagrammed_courses sdc ON c.id = sdc.course_id
                WHERE c.fl_status = true
                AND (f_fl_pseudo_course IS NULL OR c.fl_pseudo_course = f_fl_pseudo_course)
                GROUP BY
                    c.id,
                    c.code,
                    c.name,
                    c.area_id,
                    a.code,
                    a.description
                ORDER BY c.id ASC;
            END;
            $$;


ALTER FUNCTION odiseo.fn_course_all(f_fl_pseudo_course boolean) OWNER TO postgres;

--
-- Name: fn_courses_complete_management(boolean, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_courses_complete_management(p_fl_pseudo_course boolean, p_employee_id bigint) RETURNS TABLE(course_id smallint, code character varying, name character varying, area_id bigint, count_questions bigint, fl_pseudo_course boolean, children jsonb, type_text_template_id smallint)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY
                    WITH tbl_question_veri AS (
                        SELECT
                            q.course_id,
                            count(q.id) AS count_questions
                        FROM question q
                        WHERE q.status IN ('VERI', 'APRB') AND q.fl_status
                        GROUP BY q.course_id
                    ), 
                    tbl_children_courses AS (
                        SELECT
                            cpc.course_id,
                            cpc.pseudo_course_id,
                            ch.code,
                            ch.name,
                            ch.area_id
                        FROM course_pseudo_courses cpc
                        INNER JOIN course ch ON ch.id = cpc.course_id
                        WHERE cpc.fl_status IS TRUE
                        AND ch.fl_status IS TRUE
                    ), 
                    courses_assigned AS (
                        SELECT DISTINCT ec.course_id
                        FROM employee_course ec
                        WHERE ec.fl_status = true
                        AND (p_employee_id IS NULL OR ec.teacher_id = p_employee_id) 
                    ),
                    tbl_children_json AS (
                        SELECT
                            tcc.pseudo_course_id,
                            jsonb_agg(
                                jsonb_build_object(
                                    'id', tcc.course_id,
                                    'code', tcc.code,
                                    'name', tcc.name,
                                    'area_id', tcc.area_id,
                                    'count_questions', COALESCE(tqvs.count_questions, 0)
                                )
                            ) as children_json
                        FROM tbl_children_courses tcc
                        LEFT JOIN tbl_question_veri tqvs ON tqvs.course_id = tcc.course_id
                        GROUP BY tcc.pseudo_course_id
                    )
                    SELECT
                        c.id AS course_id,
                        c.code,
                        c.name,
                        c.area_id,
                        COALESCE(tqv.count_questions, 0) AS count_questions,
                        c.fl_pseudo_course,
                        COALESCE(tcj.children_json, '[]'::jsonb) as children,
                        c.type_text_template_id
                    FROM course c
                    LEFT JOIN tbl_question_veri tqv ON tqv.course_id = c.id
                    LEFT JOIN tbl_children_json tcj ON tcj.pseudo_course_id = c.id
                    LEFT JOIN type_text_templates ttt on ttt.id = c.type_text_template_id
                    WHERE c.fl_status IS TRUE
                    AND (p_employee_id IS NULL OR c.id IN (SELECT ca.course_id FROM courses_assigned ca))
                    AND (p_fl_pseudo_course IS NULL OR c.fl_pseudo_course = p_fl_pseudo_course)
                    ORDER BY c.id ASC;
                END;
                $$;


ALTER FUNCTION odiseo.fn_courses_complete_management(p_fl_pseudo_course boolean, p_employee_id bigint) OWNER TO postgres;

--
-- Name: fn_courses_diagram_settings(); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_courses_diagram_settings() RETURNS TABLE(id smallint, code character varying, name character varying, apply_text boolean)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                    RETURN QUERY
                    WITH all_course_text_category AS (
                        SELECT c.id, tt.id category_text_id, c.apply_text FROM course c 
                        CROSS JOIN type_text tt 
                        WHERE c.apply_text = true AND c.fl_status = true
                    ),
                    courses_text_diagramm AS (
                        SELECT
                            c.id,
                            c.apply_text
                        FROM all_course_text_category c
                        LEFT JOIN setting_diagrammed_courses sdc ON c.id = sdc.course_id
                            AND sdc.fl_status = true AND c.category_text_id = sdc.category_text_id 
                        WHERE
                            c.apply_text IS TRUE
                            AND sdc.category_text_id IS NULL
                        GROUP BY c.id, c.apply_text 
                    ), courses_diagramm AS (
                        SELECT
                            c.id,
                            false
                        FROM course c
                        LEFT JOIN setting_diagrammed_courses sdc ON c.id = sdc.course_id AND sdc.category_text_id IS NULL
                            AND sdc.fl_status = true
                        WHERE c.fl_status = true
                            AND sdc.course_id IS NULL
                        GROUP BY c.id
                    ), union_courses_diagramm AS (
                        SELECT * FROM courses_text_diagramm
                        UNION ALL
                        SELECT * FROM courses_diagramm
                    )
                    SELECT ucd.id, c.code, c."name", ucd.apply_text
                    FROM union_courses_diagramm ucd
                    JOIN course c ON c.id = ucd.id
                    ORDER BY c.id;

            END;
            $$;


ALTER FUNCTION odiseo.fn_courses_diagram_settings() OWNER TO postgres;

--
-- Name: fn_courses_order_and_amount(smallint, bigint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_courses_order_and_amount(p_type_material_id smallint, p_area_id bigint, p_university_id smallint) RETURNS TABLE(course_id bigint, course character varying, amount_question integer, "position" smallint, initial bigint)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            C_TYPE_EXAM_ONE BIGINT DEFAULT 2;
            C_TYPE_EXAM_TWO BIGINT DEFAULT 3;
            C_TYPE_EXAM_THREE BIGINT DEFAULT 4;

            v_type_material_template_id BIGINT;
            v_type_exam_id BIGINT;
            v_university_id SMALLINT;
        BEGIN
            SELECT type_material_template_id INTO v_type_material_template_id FROM type_material WHERE id = p_type_material_id LIMIT 1;
            SELECT type_exam_id INTO v_type_exam_id FROM type_material_template WHERE id = v_type_material_template_id;

            SELECT
                CASE
                    WHEN p_university_id = 16 THEN p_university_id
                    ELSE NULL
                END AS university_id
            INTO v_university_id;

            RETURN QUERY
            WITH tbl_course_ordering AS (
                SELECT
                    ttmco.course_id,
                    tm.id AS type_material_id,
                    ttmco.position
                FROM template_type_material_courses_order ttmco
                INNER JOIN type_material tm ON tm.type_material_template_id = ttmco.template_type_material_id
                WHERE ttmco.template_type_material_id = v_type_material_template_id
                    AND tm.id = p_type_material_id
                    AND ttmco.university_id IS NOT DISTINCT FROM v_university_id
            ), tbl_course_area_text AS ( -- <-- Cantidad de textos
                SELECT
                    ttmtca.course_id,
                    SUM(ttmtca.subquestion_amount)::INTEGER AS amount_question,
                    ttmtca.type_material_id,
                    ttmtca.exam_area_id
                FROM type_text_material_type_course_area ttmtca
                WHERE 1 = 1
                AND ttmtca.type_material_id = p_type_material_id
                AND ttmtca.exam_area_id = p_area_id
                AND ttmtca.deleted_at IS NULL
                AND v_type_exam_id IN (C_TYPE_EXAM_ONE, C_TYPE_EXAM_TWO, C_TYPE_EXAM_THREE)
                GROUP BY
                    ttmtca.type_material_id,
                    ttmtca.course_id,
                    ttmtca.exam_area_id
            ), tbl_course_area AS (
                SELECT
                    tmc.course_id,
                    ( tmc.amount_question + COALESCE(cat.amount_question, 0)) AS amount_question, -- <-- Se suma la cantidad de textos a las cantidad de preguntas
                    tmc.type_material_id,
                    tma.area_id
                FROM type_material_course tmc
                INNER JOIN type_material_area_courses tmac ON tmc.id = tmac.type_material_course_id AND tmac.fl_status = true
                INNER JOIN type_material_area tma ON tmac.type_material_area_id = tma.id AND tma.fl_status = TRUE
                LEFT JOIN tbl_course_area_text cat ON cat.type_material_id = tmc.type_material_id AND cat.exam_area_id = tma.area_id AND tmc.course_id = cat.course_id -- Se une la cantidad de textos
                WHERE tmc.fl_status = true
                AND tma.area_id = p_area_id
                AND tma.type_material_id = p_type_material_id
                AND ( tmc.amount_question > 0 OR cat.amount_question > 0 )
            ), tbl_courses AS (
                SELECT
                    tca.course_id,
                    c.name AS course,
                    tca.amount_question,
                    tco.position
                FROM tbl_course_area tca
                LEFT JOIN tbl_course_ordering tco ON tca.course_id = tco.course_id
                INNER JOIN course c ON tca.course_id = c.id
            )
            SELECT
                tc.course_id::BIGINT,
                tc.course,
                tc.amount_question,
                tc.position,
                COALESCE(
                    SUM(tc.amount_question) OVER (
                        ORDER BY tc.position ASC, tc.course_id ASC
                        ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
                    ), 0
                ) + 1 AS initial
            FROM tbl_courses tc
            ORDER BY tc.position ASC, tc.course_id ASC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_courses_order_and_amount(p_type_material_id smallint, p_area_id bigint, p_university_id smallint) OWNER TO postgres;

--
-- Name: fn_create_and_update_employee_university(bigint, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_and_update_employee_university(p_employee_id bigint, p_universities_id jsonb, p_created_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_university_id SMALLINT;
            v_validate_university_id BIGINT;
        BEGIN
			-- Eliminar los que no se manda
			UPDATE odiseo.employee_university eud
			SET fl_status = false, deleted_by = p_created_by, deleted_at = NOW()
			WHERE eud.university_id NOT IN (SELECT value::SMALLINT FROM jsonb_array_elements_text(p_universities_id))
			AND eud.employee_id = p_employee_id;

            FOR v_university_id IN
                SELECT * FROM jsonb_array_elements(p_universities_id)
            LOOP
                SELECT eu.id INTO v_validate_university_id
                FROM odiseo.employee_university eu
                WHERE eu.university_id = v_university_id
                AND eu.employee_id = p_employee_id
                AND eu.fl_status IS TRUE LIMIT 1;

                IF v_validate_university_id IS NULL THEN
                    INSERT INTO odiseo.employee_university
                    (university_id, employee_id, created_by, created_at)
                    VALUES (v_university_id, p_employee_id, p_created_by, now());
                END IF;
            END LOOP;
        END;
        $$;


ALTER FUNCTION odiseo.fn_create_and_update_employee_university(p_employee_id bigint, p_universities_id jsonb, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_create_area(character varying, character varying, character varying, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_area(p_code character varying, p_slug character varying, p_description character varying, p_created_by integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_new_area_id INTEGER;
                v_count INTEGER;
            BEGIN
                SELECT COUNT(*)
                INTO v_count
                FROM odiseo.area
                WHERE LOWER(description) = LOWER(p_description)
                AND fl_status = true;

                IF v_count = 0 THEN
                    INSERT INTO odiseo.area (code, slug, description, created_by, created_at)
                    VALUES (p_code, p_slug, p_description, p_created_by, now())
                    RETURNING id INTO v_new_area_id;

                    RETURN v_new_area_id;
                ELSE
                    RETURN NULL;
                END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_create_area(p_code character varying, p_slug character varying, p_description character varying, p_created_by integer) OWNER TO postgres;

--
-- Name: fn_create_company(uuid, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, bigint, bigint, bigint, uuid, character varying, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_company(p_uuid uuid, p_social_reason character varying, p_commercial_name character varying, p_type_company character varying, p_document_number character varying, p_domain_email character varying, p_schema character varying, p_address character varying, p_city character varying, p_state character varying, p_main_number character varying, p_other_number character varying, p_prospect_id bigint, p_plan_id bigint, p_created_by bigint, p_uuid_user uuid, p_user character varying, p_password character varying) RETURNS TABLE(v_validated boolean, v_type integer, v_id bigint)
    LANGUAGE plpgsql
    AS $$
			DECLARE
				v_exists_social_reason BIGINT;
				v_exists_document_number BIGINT;
				v_exists_prospect BIGINT;
				v_exists_plan BIGINT;
				v_prospect_id BIGINT;
				v_schema BIGINT;
				v_exists_user BIGINT;
				v_new_id BIGINT;
            BEGIN
                -- Validar si existe la misma razon social
                SELECT id INTO v_exists_social_reason
                FROM odiseo.companies
                WHERE social_reason = p_social_reason
                AND fl_status = true
                LIMIT 1;

                IF v_exists_social_reason IS NULL THEN
                    -- Validar si existe el mismo nro de documento
                    SELECT id INTO v_exists_document_number
                    FROM odiseo.companies
                    WHERE document_number = p_document_number
                    AND fl_status = true
                    LIMIT 1;

                    IF v_exists_document_number IS NULL THEN
                        -- Validar si existe el prospecto
                        IF p_prospect_id IS NOT NULL THEN
                            SELECT id INTO v_exists_prospect
                            FROM odiseo.prospect
                            WHERE id = p_prospect_id
                            AND fl_status = true
                            AND fl_validate = false
                            LIMIT 1;

                            IF v_exists_prospect IS NULL THEN
                                RETURN QUERY SELECT FALSE, 3, 0::BIGINT;
                                RETURN;
                            END IF;
                        END IF;

                        -- Validar schema
                        SELECT COUNT(*) INTO v_schema
                        FROM pg_namespace
                        WHERE nspname = p_schema;

                        IF v_schema > 0 THEN
                            RETURN QUERY SELECT FALSE, 4, 0::BIGINT;
                            RETURN;
                        END IF;

                        -- Validar si existe el usuario
                        SELECT u.id INTO v_exists_user
                        FROM odiseo.users u
                        WHERE LOWER(u.user) = LOWER(p_user)
                        AND u.fl_status = true
                        LIMIT 1;

                        IF v_exists_user IS NOT NULL THEN
                            RETURN QUERY SELECT FALSE, 5, 0::BIGINT;
                            RETURN;
                        END IF;

                        INSERT INTO odiseo.companies
                        (uuid, social_reason, commercial_name, type_company, document_number, domain_email, "schema", address, city, state, main_number, other_number, prospect_id, plan_id , created_by, created_at)
                        VALUES (p_uuid, p_social_reason, p_commercial_name, p_type_company, p_document_number, p_domain_email, p_schema, p_address, p_city, p_state, p_main_number, p_other_number, p_prospect_id, p_plan_id, p_created_by, now())
                        RETURNING id INTO v_new_id;

                        -- Cambiar estado de prospecto
                        UPDATE odiseo.prospect
                        SET fl_validate = true
                        WHERE id = p_prospect_id
                        AND fl_status = true;

                        -- Crear usuario admin
                        INSERT INTO odiseo.users (uuid, "user", password, status_session, company_id, created_by, created_at)
                        VALUES (p_uuid_user, p_user, p_password, 1001, v_new_id, p_created_by, now());

                        RETURN QUERY SELECT TRUE, 0, v_new_id;
                        RETURN;
                    ELSE
                        RETURN QUERY SELECT FALSE, 2, 0::BIGINT;
                        RETURN;
                    END IF;
                ELSE
					RETURN QUERY SELECT FALSE, 1, 0::BIGINT;
                    RETURN;
                END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_create_company(p_uuid uuid, p_social_reason character varying, p_commercial_name character varying, p_type_company character varying, p_document_number character varying, p_domain_email character varying, p_schema character varying, p_address character varying, p_city character varying, p_state character varying, p_main_number character varying, p_other_number character varying, p_prospect_id bigint, p_plan_id bigint, p_created_by bigint, p_uuid_user uuid, p_user character varying, p_password character varying) OWNER TO postgres;

--
-- Name: fn_create_configuration_diagram_course(smallint, jsonb, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_configuration_diagram_course(p_course_id smallint, p_field_diagram jsonb, p_category_text_id bigint, p_created_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
            BEGIN
                    IF NOT EXISTS (
                        SELECT 1
                        FROM setting_diagrammed_courses sdc
                        WHERE sdc.course_id = p_course_id
                            AND (
                                (p_category_text_id IS NULL AND sdc.category_text_id IS NULL) OR
                                (p_category_text_id IS NOT NULL AND sdc.category_text_id = p_category_text_id)
                            )
                            AND sdc.fl_status = true
                    ) THEN
                        INSERT INTO setting_diagrammed_courses (
                            course_id,
                            field_diagram_id,
                            "position",
                            category_text_id,
                            fl_active,
                            fl_optional,
                            created_by,
                            created_at
                        )
                        SELECT
                            p_course_id BIGINT,
                            (fd.value->>'field_diagram_id')::SMALLINT,
                            (fd.value->>'position')::SMALLINT,
                            p_category_text_id,
                            (fd.value->>'fl_active')::BOOL,
                            (fd.value->>'fl_optional')::BOOL,
                            p_created_by,
                            now()
                        FROM jsonb_array_elements(p_field_diagram) AS fd;
                    END IF;

            END;
                    $$;


ALTER FUNCTION odiseo.fn_create_configuration_diagram_course(p_course_id smallint, p_field_diagram jsonb, p_category_text_id bigint, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_create_course(character varying, bigint, boolean, jsonb, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_course(p_name character varying, p_area_id bigint, p_fl_pseudo_course boolean, p_courses jsonb, p_type_text_template_id bigint, p_created_by bigint) RETURNS TABLE(v_validated boolean, v_id bigint)
    LANGUAGE plpgsql
    AS $$
    DECLARE
        v_exists_id BIGINT;
        v_code VARCHAR;
        v_new_id BIGINT;
        v_course_id SMALLINT;
        v_count SMALLINT := 1;
        v_type_text_template_id BIGINT;
    BEGIN
        SELECT id INTO v_exists_id
        FROM course
        WHERE LOWER(
                REGEXP_REPLACE(
                    TRIM(unaccent(name)),
                    '\s+',
                    ' ',
                    'g'
                )
            ) = LOWER(
                REGEXP_REPLACE(
                    TRIM(unaccent(p_name)),
                    '\s+',
                    ' ',
                    'g'
                )
            )
        AND fl_status = true
        LIMIT 1;

        IF v_exists_id IS NULL THEN
            SELECT COALESCE(MAX(CAST(code AS INTEGER) + 1), 0) INTO v_code FROM course;

            INSERT INTO course (code, name, area_id, fl_pseudo_course, created_by, created_at, type_text_template_id,apply_text)
            VALUES (v_code, REGEXP_REPLACE(p_name,'\s+',
                    ' ',
                    'g'
                ), p_area_id, p_fl_pseudo_course, p_created_by, now(), p_type_text_template_id, CASE 
                WHEN p_type_text_template_id IS NULL THEN false
                ELSE true
            END)
            RETURNING id,type_text_template_id INTO v_new_id,v_type_text_template_id;

            INSERT INTO question_correlative(
                course_id,
                correlative,
                created_at,
                apply_text
            )VALUES (
                v_new_id,
                0,
                now(),
                CASE WHEN p_type_text_template_id IS NULL THEN false ELSE true END
            );


            if p_fl_pseudo_course THEN
                FOR v_course_id IN
                    SELECT * FROM jsonb_array_elements(p_courses)
                LOOP
                    INSERT INTO course_pseudo_courses
                    (pseudo_course_id, course_id, "order", created_by, created_at)
                    VALUES (v_new_id, v_course_id, v_count, p_created_by, now());

                    -- Incrementa el contador
                    v_count := v_count + 1;
                END LOOP;
            END IF;

            RETURN QUERY SELECT TRUE, v_new_id;
        ELSE
            RETURN QUERY SELECT FALSE, 0::BIGINT;
        END IF;
    END;
    $$;


ALTER FUNCTION odiseo.fn_create_course(p_name character varying, p_area_id bigint, p_fl_pseudo_course boolean, p_courses jsonb, p_type_text_template_id bigint, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_create_cycle(character varying, character varying, smallint, smallint, date, date, smallint, bigint, smallint, bigint, jsonb, boolean, integer, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_cycle(p_code character varying, p_description character varying, p_month smallint, p_year smallint, p_start_date date, p_end_date date, p_weeks smallint, p_cycle_type_id bigint, p_days smallint, p_type_template_id bigint, p_cycle_weeks jsonb, p_active boolean, p_company_id integer, p_user bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
                    DECLARE
                        v_cycle_id BIGINT;
                    BEGIN

                        INSERT INTO cycle(
                            code, description, year, month, start_date, end_date,
                            weeks, cycle_type_id, days,
                            active, type_template_id, company_id, created_by, created_at
                        )
                        VALUES (
                            p_code, p_description, p_year, p_month, p_start_date, p_end_date,
                            p_weeks, p_cycle_type_id, p_days,
                            p_active, p_type_template_id, p_company_id, p_user, NOW()
                        )
                        RETURNING id INTO v_cycle_id;

                        -- 3. Insertar Semanas (Mapeo directo desde JSON)
                        INSERT INTO cycle_weeks (
                            week, type_week_id, cycle_id, start_date, end_date,
                            created_by, created_at
                        )
                        SELECT
                            w.week,
                            w.type_week_id,
                            v_cycle_id,
                            w.start_date,
                            w.end_date,
                            p_user,
                            NOW()
                        FROM jsonb_to_recordset(p_cycle_weeks) AS w(
                            week SMALLINT,
                            type_week_id BIGINT,
                            start_date DATE,
                            end_date DATE
                        );

                        RETURN;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_create_cycle(p_code character varying, p_description character varying, p_month smallint, p_year smallint, p_start_date date, p_end_date date, p_weeks smallint, p_cycle_type_id bigint, p_days smallint, p_type_template_id bigint, p_cycle_weeks jsonb, p_active boolean, p_company_id integer, p_user bigint) OWNER TO postgres;

--
-- Name: fn_create_employee(uuid, bigint, character varying, character varying, character varying, integer, character varying, character varying, character varying, jsonb, integer, jsonb, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_employee(p_uuid uuid, p_charge_id bigint, p_first_name character varying, p_first_surname character varying, p_second_surname character varying, p_type_document_id integer, p_document character varying, p_email character varying, p_phone character varying, p_course_ids jsonb, p_created_by integer, p_data_docente jsonb, p_company_id integer, p_user_id integer) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_new_employee_id BIGINT;
                v_course_id TEXT;
                v_limit_assigned_questions INTEGER;
            BEGIN
                v_limit_assigned_questions := (p_data_docente->>'goal')::smallint + ((p_data_docente->>'goal')::smallint) / 2;

                INSERT INTO employees (
                    "uuid", first_name, first_surname, second_surname, type_document_id,
                    "document", email, phone, created_by, created_at, charge_id,
                    code, limit_assigned_questions, limit_assigned_questions_initial, fl_unlimit_questions,
                    goal, lot, level_id, company_id, user_id,
                    fl_resolve_missing_questions,
                    limit_missing_questions
                )
                VALUES (
                    p_uuid, p_first_name, p_first_surname, p_second_surname,
                    p_type_document_id, p_document, p_email, p_phone,
                    p_created_by, now(), p_charge_id,
                    p_data_docente->>'code',
                    v_limit_assigned_questions,
                    COALESCE((p_data_docente->>'limit_assigned_questions_initial')::smallint, 0),
                    (p_data_docente->>'fl_unlimit_questions')::boolean,
                    (p_data_docente->>'goal')::smallint,
                    (p_data_docente->>'lot')::smallint,
                    (p_data_docente->>'level')::smallint,
                    p_company_id,
                    p_user_id,
                    (p_data_docente->>'fl_resolve_missing_questions')::boolean,
                    (p_data_docente->>'missing_questions_lot')::smallint
                )
                RETURNING id INTO v_new_employee_id;

                FOR v_course_id IN
                    SELECT id
                    FROM course
                    WHERE id IN (
                        SELECT jsonb_array_elements_text(p_course_ids)::bigint
                    )
                LOOP
                    INSERT INTO employee_course (teacher_id, course_id, created_by, created_at)
                    VALUES (v_new_employee_id, v_course_id::bigint, p_created_by, now());
                END LOOP;

                RETURN v_new_employee_id;
            END;
            $$;


ALTER FUNCTION odiseo.fn_create_employee(p_uuid uuid, p_charge_id bigint, p_first_name character varying, p_first_surname character varying, p_second_surname character varying, p_type_document_id integer, p_document character varying, p_email character varying, p_phone character varying, p_course_ids jsonb, p_created_by integer, p_data_docente jsonb, p_company_id integer, p_user_id integer) OWNER TO postgres;

--
-- Name: fn_create_essential_knowledge(character varying, character varying, boolean, bigint, bigint, text, text, text, character varying, bigint, timestamp without time zone); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_essential_knowledge(p_code character varying, p_name character varying, p_is_active boolean, p_topic_id bigint, p_course_id bigint, p_editor_content text, p_thumbnail text, p_filename text, p_extension character varying, p_created_by bigint, p_created_at timestamp without time zone) RETURNS TABLE(topic_id bigint, course_id bigint, name character varying, file_name text, code character varying, id bigint)
    LANGUAGE plpgsql
    AS $$
        DECLARE 
            v_essential_knowledge_id BIGINT;
        BEGIN
        INSERT INTO essential_knowledges (
            code,
            name,
            is_active,
            topic_id,
            course_id,
            editor_content,
            thumbnail,
            created_by,
            created_at
        )
        VALUES (
            p_code,
            p_name,
            p_is_active,
            p_topic_id,
            p_course_id,
            p_editor_content,
            p_thumbnail,
            p_created_by,
            p_created_at
        )
        returning essential_knowledges.id into v_essential_knowledge_id;

        insert into essential_knowledge_image (
            essential_knowledge_id,
            image,
            extension,
            created_by,
            created_at
        )
        values (
            v_essential_knowledge_id,
            p_filename,
            p_extension,
            p_created_by,
            p_created_at
        );

        RETURN QUERY
        SELECT
            p_topic_id,
            p_course_id,
            p_name,
            p_filename,
            p_code,
            v_essential_knowledge_id;

end;
$$;


ALTER FUNCTION odiseo.fn_create_essential_knowledge(p_code character varying, p_name character varying, p_is_active boolean, p_topic_id bigint, p_course_id bigint, p_editor_content text, p_thumbnail text, p_filename text, p_extension character varying, p_created_by bigint, p_created_at timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_create_headquarter(character varying, character varying, character varying, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_headquarter(p_name character varying, p_slug character varying, p_address character varying, p_company_id bigint, p_created_by bigint) RETURNS TABLE(id smallint, name character varying, slug character varying, address character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH inserted_headquarter AS (
        INSERT INTO headquarters AS h (name, slug, address, created_by, created_at)
        VALUES (
            p_name,
            p_slug,
            p_address,
            p_created_by,
            NOW()
        )
        RETURNING
            h.id,
            h.name,
            h.slug,
            h.address
    ), inserted_headquarter_company AS (
        INSERT INTO company_headquarters as ch (headquarter_id, company_id, created_by, created_at)
        SELECT ih.id, p_company_id, p_created_by, NOW()
        FROM inserted_headquarter ih
        RETURNING ch.id
    )
    SELECT
        ih.id,
        ih.name,
        ih.slug,
        ih.address
    FROM inserted_headquarter ih;
END;
$$;


ALTER FUNCTION odiseo.fn_create_headquarter(p_name character varying, p_slug character varying, p_address character varying, p_company_id bigint, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_create_level(character varying, character varying, jsonb, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_level(p_name character varying, p_description character varying, p_courses jsonb, p_created_by integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
        BEGIN
            WITH insert_level AS (
                INSERT INTO level (name, description, created_by, created_at)
                VALUES (p_name, p_description, p_created_by, NOW())
                RETURNING id
            ), courses AS (
                SELECT
                    (jsonb_array_elements_text(p_courses))::SMALLINT AS course_id
            ), course_codes AS (
                SELECT
                    c.course_id,
                    CONCAT(
                        co.code,
                        '-',
                        LPAD((COUNT(cl.id) + 1)::TEXT, 3, '0')
                    ) AS code
                FROM courses c
                JOIN course co ON co.id = c.course_id
                LEFT JOIN course_level cl ON cl.course_id = c.course_id
                GROUP BY c.course_id, co.code
            )
            INSERT INTO course_level (code, level_id, course_id, created_by, created_at)
            SELECT
                cc.code,
                il.id,
                cc.course_id,
                p_created_by,
                now()
            FROM course_codes cc
            CROSS JOIN insert_level il;
        END;
        $$;


ALTER FUNCTION odiseo.fn_create_level(p_name character varying, p_description character varying, p_courses jsonb, p_created_by integer) OWNER TO postgres;

--
-- Name: fn_create_material(bigint, smallint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_material(p_cycle_id bigint, p_university_id smallint, p_headquearters_id smallint, p_created_by bigint) RETURNS TABLE(material_id bigint, v_validated integer)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_validate BIGINT;
            v_material_id BIGINT;
            v_headquarters_classroom_id BIGINT;
        BEGIN
            SELECT id INTO v_headquarters_classroom_id FROM odiseo.headquarters_classroom
            WHERE headquarters_id = p_headquearters_id AND classroom_id = 1 AND fl_status = true LIMIT 1;

            IF v_headquarters_classroom_id IS NOT NULL THEN
                SELECT id INTO v_validate FROM odiseo.material
                WHERE cycle_id = p_cycle_id
                AND university_id = p_university_id
                AND headquarte_id = p_headquearters_id
                AND headquarters_classroom_id = v_headquarters_classroom_id
                AND fl_status = true LIMIT 1;

                IF v_validate IS NULL THEN
                    -- Creación del material
                    INSERT INTO odiseo.material (cycle_id, university_id, headquarte_id, headquarters_classroom_id, created_by, created_at)
                    VALUES (p_cycle_id, p_university_id, p_headquearters_id, v_headquarters_classroom_id, p_created_by, now())
                    RETURNING id INTO v_material_id;

                    RETURN QUERY SELECT v_material_id, 0::INT;
                ELSE
                    RETURN QUERY SELECT 0::BIGINT, 1::INT;
                END IF;
            ELSE
                RETURN QUERY SELECT 0::BIGINT, 2::INT;
            END IF;
        END;
        $$;


ALTER FUNCTION odiseo.fn_create_material(p_cycle_id bigint, p_university_id smallint, p_headquearters_id smallint, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_create_material(bigint, smallint, smallint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_material(p_cycle_id bigint, p_university_id smallint, p_headquearters_id smallint, p_created_by bigint, p_company_id bigint) RETURNS TABLE(material_id bigint, v_validated integer)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_validate BIGINT;
            v_material_id BIGINT;
            v_headquarters_classroom_id BIGINT;
        BEGIN
            SELECT id INTO v_headquarters_classroom_id FROM headquarters_classroom
            WHERE headquarters_id = p_headquearters_id AND classroom_id = 1 AND fl_status = true LIMIT 1;

            IF v_headquarters_classroom_id IS NOT NULL THEN
                SELECT id INTO v_validate FROM material
                WHERE cycle_id = p_cycle_id
                AND university_id = p_university_id
                AND headquarte_id = p_headquearters_id
                AND headquarters_classroom_id = v_headquarters_classroom_id
                AND fl_status = true LIMIT 1;

                IF v_validate IS NULL THEN
                    -- Creación del material
                    INSERT INTO material (cycle_id, university_id, headquarte_id, headquarters_classroom_id, created_by, created_at, company_id)
                    VALUES (p_cycle_id, p_university_id, p_headquearters_id, v_headquarters_classroom_id, p_created_by, now(), p_company_id)
                    RETURNING id INTO v_material_id;

                    RETURN QUERY SELECT v_material_id, 0::INT;
                ELSE
                    RETURN QUERY SELECT 0::BIGINT, 1::INT;
                END IF;
            ELSE
                RETURN QUERY SELECT 0::BIGINT, 2::INT;
            END IF;
        END;
        $$;


ALTER FUNCTION odiseo.fn_create_material(p_cycle_id bigint, p_university_id smallint, p_headquearters_id smallint, p_created_by bigint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_create_material_notification(bigint, integer, smallint, integer, integer, bigint, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_material_notification(p_material_id bigint, p_type_material_id integer, p_week smallint, p_user_to_notify_id integer, p_trigger_by integer, p_notification_type bigint, p_prefix_title character varying, p_suffix_title character varying, p_web_route character varying, p_request_status character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
                DECLARE v_notification_type_name VARCHAR;
                
                BEGIN
                    SELECT name
                    INTO v_notification_type_name 
                    FROM odiseo.material_generation_notification_types
                    WHERE id = p_notification_type;
                
                    WITH type_material_name AS (
                        SELECT
                            description
                        FROM odiseo.type_material tm
                        WHERE tm.id = p_type_material_id
                    ), cycle_name AS (
                        SELECT
                            c.description,
                            h.name
                        FROM odiseo.material m
                        JOIN odiseo.cycle c ON m.cycle_id = c.id
                        JOIN odiseo.headquarters h ON h.id = m.headquarte_id
                        WHERE m.id = p_material_id
                    ), notification_info AS (
                        SELECT
                            tmn.description AS type_material_name,
                            cm.description AS cycle_name,
                            cm.name AS headquarter_name
                        FROM cycle_name cm
                        LEFT JOIN type_material_name tmn ON 1 = 1
                    )
                    INSERT INTO odiseo.material_generation_notifications(
                        title,
                        message,
                        user_id,
                        created_by,
                        type,
                        url_internal,
                        request_status
                    )
                    SELECT
                        p_prefix_title || ' ' || v_notification_type_name || ' ' || p_suffix_title,
                        ni.cycle_name || ' (' || ni.type_material_name || ') ' || ' Semana ' || p_week,
                        p_user_to_notify_id,
                        p_trigger_by,
                        p_notification_type,
                        p_web_route,
                        p_request_status
                    FROM notification_info ni;
                END;
            $$;


ALTER FUNCTION odiseo.fn_create_material_notification(p_material_id bigint, p_type_material_id integer, p_week smallint, p_user_to_notify_id integer, p_trigger_by integer, p_notification_type bigint, p_prefix_title character varying, p_suffix_title character varying, p_web_route character varying, p_request_status character varying) OWNER TO postgres;

--
-- Name: fn_create_material_per_period_ballot(bigint, smallint, smallint, smallint, boolean, smallint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_material_per_period_ballot(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint, p_fl_config_type boolean, p_lower_level_limit smallint, p_upper_level_limit smallint, p_created_by bigint) RETURNS TABLE(id bigint, material_per_period_ballot_id bigint, week smallint, cycle_id bigint, start_date date, type_material_id smallint, type_material character varying, parent_type_material_id smallint, fl_exam boolean, has_questions boolean, exists_per_period boolean, courses jsonb, courses_for_text jsonb, university_id smallint, headquarte_id smallint)
    LANGUAGE plpgsql
    AS $$
                    DECLARE
                        v_ids_children INT[];
                        v_exists BOOLEAN = TRUE;
                        v_material_per_period_id BIGINT;
                        v_material_per_period_ballot_id BIGINT;
                        v_week SMALLINT;
                        v_son_tm_id SMALLINT;
                        v_parent_tm_id SMALLINT;
                        v_detail_week_type_mat_id BIGINT;
                        v_details_id bigint[] := '{}';
                        v_period_has_missing_questions BOOLEAN := FALSE;
                        v_period_has_missing_courses BOOLEAN := FALSE;
                        v_period_has_missing_text BOOLEAN := FALSE;
                        v_week_has_missing_questions BOOLEAN := FALSE;
                        v_week_has_missing_courses BOOLEAN := FALSE;
                        v_week_has_missing_text BOOLEAN := FALSE;
                    BEGIN
                        -- Obtener todos los IDs de los hijos en un array
                        SELECT CASE
                            WHEN EXISTS (SELECT 1 FROM type_material tm WHERE tm.parent_id = p_type_material_id AND tm.fl_status = true)
                            THEN ARRAY(SELECT tm.id FROM type_material tm WHERE tm.parent_id = p_type_material_id AND tm.fl_status = true)
                            ELSE ARRAY[p_type_material_id]
                        END INTO v_ids_children;

                        -- Obtener el id del material por period
                        SELECT
                            mpp.id INTO v_material_per_period_id
                        FROM material_per_period mpp
                        WHERE 1 = 1
                        AND mpp.material_id = p_material_id
                        AND mpp.type_material_id = p_type_material_id
                        AND mpp.deleted_by IS NULL
                        LIMIT 1;

                        -- Insertar si no lo encuentra
                        IF v_material_per_period_id IS NULL THEN
                            INSERT INTO material_per_period AS mpp2 (
                                material_id,
                                type_material_id,
                                created_by,
                                created_at
                            )
                            VALUES (
                                p_material_id,
                                p_type_material_id,
                                p_created_by,
                                NOW()
                            )
                            RETURNING mpp2.id INTO v_material_per_period_id;
                        END IF;

                        -- Verificar si hay registro de periodo en el material
                        SELECT
                            mppb.id INTO v_material_per_period_ballot_id
                        FROM material_per_period_ballot mppb
                        WHERE 1 = 1
                        AND mppb.material_per_period_id = v_material_per_period_id
                        AND mppb.start_week = p_start_week
                        AND mppb.end_week = p_end_week
                        AND mppb.deleted_by IS NULL
                        LIMIT 1;

                        -- Si ya existe se retorna sin agregar nada
                        IF v_material_per_period_ballot_id IS NOT NULL THEN
                            RETURN QUERY
                            SELECT
                                NULL::BIGINT,
                                NULL::BIGINT,
                                NULL::SMALLINT,
                                NULL::BIGINT,
                                NULL::DATE,
                                NULL::SMALLINT,
                                NULL::VARCHAR,
                                NULL::SMALLINT,
                                NULL::BOOLEAN,
                                NULL::BOOLEAN,
                                v_exists AS exists_per_period,
                                '[]'::JSONB,
                                '[]'::JSONB,
                                NULL::SMALLINT,
                                NULL::SMALLINT
                            ;
                        ELSE
                            v_exists := FALSE;

                            WITH remove_overlapping_periods_in_ballot AS ( -- Se elimina los periodos del tipo material que estén dentro del rango para evitar duplicados
                                UPDATE material_per_period_ballot mppb
                                SET
                                    deleted_by = p_created_by,
                                    deleted_at = NOW()
                                WHERE 1 = 1
                                AND mppb.material_per_period_id = v_material_per_period_id
                                AND ( mppb.start_week BETWEEN p_start_week AND p_end_week OR mppb.end_week BETWEEN p_start_week AND p_end_week )
                                AND NOT ( mppb.start_week = p_start_week AND mppb.end_week = p_end_week )
                                RETURNING mppb.id AS material_period_id
                            ), remove_material_per_period_ballot_url AS ( -- Se remueven las urls asociadas
                                UPDATE material_per_period_ballot_url mbppbu
                                    SET
                                        deleted_by = p_created_by,
                                        deleted_at = NOW()
                                WHERE mbppbu.material_per_period_ballot_id IN ( SELECT rmv.material_period_id FROM remove_overlapping_periods_in_ballot rmv )
                                RETURNING mbppbu.id
                            ) UPDATE material_per_period_ballot_class class_urls -- Se remueven las urls de los cursos individuales del material de clases
                                SET
                                    deleted_by = p_created_by,
                                    deleted_at = NOW()
                            WHERE class_urls.material_per_period_ballot_url_id IN (SELECT cls.id FROM remove_material_per_period_ballot_url cls);

                            -- Se inserta material por periodo
                            INSERT INTO material_per_period_ballot AS mppx (
                                material_per_period_id,
                                start_week,
                                end_week,
                                fl_config_type,
                                lower_level_limit,
                                upper_level_limit,
                                created_by,
                                created_at
                            )
                            VALUES (
                                v_material_per_period_id,
                                p_start_week,
                                p_end_week,
                                p_fl_config_type,
                                p_lower_level_limit,
                                p_upper_level_limit,
                                p_created_by,
                                NOW()
                            ) RETURNING mppx.id INTO v_material_per_period_ballot_id;

                            FOR v_week, v_son_tm_id, v_parent_tm_id IN
                                SELECT
                                    tmdt.week,
                                    ttm.id AS son_type_material_id,
                                    ttm.parent_id AS parent_type_material_id
                                FROM type_material_detail_template tmdt
                                LEFT JOIN (
                                    SELECT * FROM type_material tm
                                    WHERE tm.id IN (SELECT unnest(v_ids_children) AS type_material_id)
                                ) ttm ON 1 = 1
                                WHERE 1 = 1
                                AND tmdt.type_material_id = p_type_material_id
                                AND tmdt.week BETWEEN p_start_week AND p_end_week
                                AND tmdt.fl_status = true
                                ORDER BY tmdt.week ASC, ttm.id ASC
                            LOOP
                                WITH insert_new_detail_week_type AS ( -- Insertar o actualizar uno desactivado
                                    INSERT INTO detail_week_type_mat AS dwtm(
                                        material_id,
                                        week,
                                        type_material_id,
                                        parent_type_material_id,
                                        fl_config_type,
                                        limit_lower_question,
                                        limit_upper_question,
                                        created_by,
                                        created_at
                                    )
                                    VALUES(
                                        p_material_id,
                                        v_week,
                                        v_son_tm_id,
                                        v_parent_tm_id,
                                        p_fl_config_type,
                                        p_lower_level_limit,
                                        p_upper_level_limit,
                                        p_created_by,
                                        NOW()
                                    )
                                    ON CONFLICT ON CONSTRAINT ux_detail_week_type_mat
                                    DO UPDATE
                                        SET
                                            parent_type_material_id = EXCLUDED.parent_type_material_id,
                                            fl_config_type = EXCLUDED.fl_config_type,
                                            limit_lower_question = EXCLUDED.limit_lower_question,
                                            limit_upper_question = EXCLUDED.limit_upper_question,
                                            updated_by = p_created_by,
                                            updated_at = NOW(),
                                            fl_status = TRUE,
                                            deleted_by = NULL,
                                            deleted_at = NULL
                                    RETURNING dwtm.id, dwtm.data_incomplete_questions, dwtm.data_missing_course_config, dwtm.data_missing_text
                                ) SELECT -- Se ingresa data que corresponde a la semana en cuestión
                                    iwt.id,
                                    iwt.data_incomplete_questions IS NOT NULL,
                                    iwt.data_missing_course_config IS NOT NULL,
                                    iwt.data_missing_text IS NOT NULL
                                INTO
                                    v_detail_week_type_mat_id,
                                    v_week_has_missing_questions,
                                    v_week_has_missing_courses,
                                    v_week_has_missing_text
                                FROM insert_new_detail_week_type AS iwt
                                LIMIT 1;

                                v_period_has_missing_questions := v_period_has_missing_questions OR v_week_has_missing_questions;
                                v_period_has_missing_courses := v_period_has_missing_courses OR v_week_has_missing_courses;
                                v_period_has_missing_text := v_period_has_missing_text OR v_week_has_missing_text;

                                v_details_id := ARRAY_APPEND(v_details_id, v_detail_week_type_mat_id);
                            END LOOP;

                            -- Se actualiza los campos de faltantes si es que los hay
                            UPDATE material_per_period_ballot mb
                            SET
                                fl_missing_questions = v_period_has_missing_questions,
                                fl_missing_courses = v_period_has_missing_courses,
                                fl_missing_text = v_period_has_missing_text
                            WHERE mb.id = v_material_per_period_ballot_id;

                            RETURN QUERY
                            WITH get_courses_generic AS (
                                SELECT DISTINCT
                                    tmc.course_id,
                                    tmc.type_material_id
                                FROM type_material_course tmc
                                WHERE tmc.type_material_id IN (SELECT unnest(v_ids_children) AS type_material_id)
                                    AND tmc.is_generic = true
                                    AND tmc.fl_status = true
                                    AND tmc.amount_question > 0
                            ), get_courses_text_generic AS (
                                SELECT DISTINCT
                                    tmc.course_id,
                                    tmc.type_material_id
                                FROM type_material_course tmc
                                WHERE tmc.type_material_id IN (SELECT unnest(v_ids_children) AS type_material_id)
                                    AND tmc.is_generic_text = true
                                    AND tmc.amount_text > 0
                                    AND tmc.fl_status = true
                            ), get_courses_not_generic AS (
                                SELECT DISTINCT
                                    tmc.course_id,
                                    tm.id AS type_material_id
                                FROM odiseo.type_material tm
                                JOIN odiseo.type_material_detail_template tmdt ON tmdt.type_material_id = tm.id
                                    AND tmdt.fl_status = true
                                JOIN odiseo.type_material_course tmc ON tmc.type_material_id = tm.id
                                LEFT JOIN odiseo.type_material_detail_courses tmdc ON tmdc.type_material_course_id = tmc.id
                                    AND tmdc.type_material_detail_template_id = tmdt.id
                                WHERE tm.id IN (SELECT unnest(v_ids_children) AS type_material_id)
                                    AND tmc.is_generic = false
                                    AND tmdt.week BETWEEN p_start_week AND p_end_week
                                    AND tmdc.amount_question > 0
                            ), get_courses_text_not_generic AS (
                                SELECT DISTINCT
                                    tmc.course_id,
                                    tm.id AS type_material_id
                                FROM odiseo.type_material tm
                                JOIN odiseo.type_material_detail_template tmdt ON tmdt.type_material_id = tm.id
                                    AND tmdt.fl_status = true
                                JOIN odiseo.type_material_course tmc ON tmc.type_material_id = tm.id
                                LEFT JOIN odiseo.type_material_detail_course_texts tmdct ON tmdct.type_material_course_id = tmc.id
                                    AND tmdct.type_material_detail_template_id = tmdt.id
                                WHERE tm.id IN (SELECT unnest(v_ids_children) AS type_material_id)
                                    AND tmc.is_generic_text = false
                                    AND tmdt.week BETWEEN p_start_week AND p_end_week
                                    AND tmdct.amount_text > 0
                            ), get_courses AS (
                                SELECT
                                    gcg.course_id,
                                    gcg.type_material_id
                                FROM get_courses_generic gcg
                                UNION ALL
                                SELECT
                                    gcng.course_id,
                                    gcng.type_material_id
                                FROM get_courses_not_generic gcng
                            ), get_courses_text AS (
                                SELECT
                                    gcg.course_id,
                                    gcg.type_material_id
                                FROM get_courses_text_generic gcg
                                UNION ALL
                                SELECT
                                    gcng.course_id,
                                    gcng.type_material_id
                                FROM get_courses_text_not_generic gcng
                            )
                            SELECT
                                dwtm.id,
                                v_material_per_period_ballot_id,
                                dwtm.week,
                                m.cycle_id,
                                c.start_date,
                                dwtm.type_material_id,
                                tm.description AS type_material,
                                dwtm.parent_type_material_id,
                                tm.fl_exam,
                                CASE
                                    WHEN mbqg.total > 0 THEN TRUE
                                    ELSE FALSE
                                END AS has_questions,
                                v_exists AS exists_per_period,
                                COALESCE((
                                    SELECT jsonb_agg(gc.course_id ORDER BY gc.course_id ASC)
                                    FROM get_courses gc
                                    WHERE gc.type_material_id = dwtm.type_material_id
                                ), '[]'::JSONB) AS courses,
                                COALESCE((
                                    SELECT jsonb_agg(gc.course_id ORDER BY gc.course_id ASC)
                                    FROM get_courses_text gc
                                    WHERE gc.type_material_id = dwtm.type_material_id
                                ), '[]'::JSONB) AS courses_for_text,
                                m.university_id,
                                m.headquarte_id
                            FROM detail_week_type_mat dwtm
                            INNER JOIN material m ON dwtm.material_id = m.id
                            INNER JOIN type_material tm ON dwtm.type_material_id = tm.id
                            LEFT JOIN cycle c ON m.cycle_id = c.id
                            LEFT JOIN (
                                SELECT
                                    mbq.week_type_material_id, COUNT(mbq.*) AS total
                                FROM material_ballot_question mbq
                                WHERE mbq.fl_status = true
                                  AND (mbq.question_id IS NOT NULL OR mbq.parent_question_id IS NOT NULL)
                                GROUP BY week_type_material_id
                            ) mbqg ON mbqg.week_type_material_id = dwtm.id
                            WHERE dwtm.id = ANY (v_details_id)
                            ORDER BY
                                dwtm.week ASC,
                                LEFT(tm.description, 1);
                        END IF;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_create_material_per_period_ballot(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint, p_fl_config_type boolean, p_lower_level_limit smallint, p_upper_level_limit smallint, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_create_material_per_period_level_limit_config(bigint, smallint, smallint, smallint, smallint, smallint, boolean, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_material_per_period_level_limit_config(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint, p_lower_level_limit smallint DEFAULT 1, p_upper_level_limit smallint DEFAULT 1, p_fl_use_question_type boolean DEFAULT true, p_created_by bigint DEFAULT NULL::bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_material_per_period_id BIGINT;
    v_material_per_period_level_limit_config_id BIGINT;
BEGIN
    WITH get_material_per_period AS (
        SELECT
            mpp.id
        FROM material_per_period AS mpp
        WHERE mpp.material_id = p_material_id
            AND mpp.type_material_id = p_type_material_id
            AND mpp.deleted_by IS NULL
    ), insert_material_per_period AS (
        INSERT INTO material_per_period AS mpp (
            material_id,
            type_material_id,
            created_by,
            created_at
        )
        SELECT
            p_material_id,
            p_type_material_id,
            p_created_by,
            NOW()
        WHERE NOT EXISTS (
            SELECT 1
            FROM get_material_per_period
        )
        RETURNING mpp.id
    )
    SELECT COALESCE(
        (SELECT id FROM insert_material_per_period),
        (SELECT id FROM get_material_per_period)
    )
    INTO v_material_per_period_id;

    UPDATE material_per_period_level_limit_config AS mppllc
    SET
        lower_level_limit = COALESCE(p_lower_level_limit, 1),
        upper_level_limit = COALESCE(p_upper_level_limit, 1),
        fl_use_question_type = COALESCE(p_fl_use_question_type, TRUE),
        updated_by = p_created_by,
        updated_at = NOW()
    WHERE mppllc.material_per_period_id = v_material_per_period_id
        AND mppllc.start_week = p_start_week
        AND mppllc.end_week = p_end_week
    RETURNING mppllc.id
    INTO v_material_per_period_level_limit_config_id;

    IF v_material_per_period_level_limit_config_id IS NULL THEN
        INSERT INTO material_per_period_level_limit_config (
            material_per_period_id,
            start_week,
            end_week,
            lower_level_limit,
            upper_level_limit,
            fl_use_question_type,
            created_by,
            created_at
        )
        VALUES (
            v_material_per_period_id,
            p_start_week,
            p_end_week,
            COALESCE(p_lower_level_limit, 1),
            COALESCE(p_upper_level_limit, 1),
            COALESCE(p_fl_use_question_type, TRUE),
            p_created_by,
            NOW()
        );
    END IF;
END;
$$;


ALTER FUNCTION odiseo.fn_create_material_per_period_level_limit_config(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint, p_lower_level_limit smallint, p_upper_level_limit smallint, p_fl_use_question_type boolean, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_create_material_revision(bigint, smallint, smallint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_material_revision(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint, p_created_by bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_revision_id  bigint;
    v_root_type_id smallint;
    v_final_start  smallint;
    v_final_end    smallint;
    v_course_id    smallint;
    v_detail_id    bigint;
    v_resolved_courses smallint[];
    v_fl_revision  boolean;
    v_delivery_date    timestamp(0);
BEGIN
    -- 0. Resolución del tipo raíz y validación de soporte para revisión
    -- -------------------------------------------------------------------------
    SELECT 
        COALESCE(tm.parent_id, tm.id),
        tmt.fl_revision
    INTO v_root_type_id, v_fl_revision
    FROM type_material tm
    JOIN type_material_template tmt ON tmt.id = tm.type_material_template_id
    WHERE tm.id = p_type_material_id;

    -- Si la plantilla del material no tiene activa la revisión, no se crea nada.
    IF NOT COALESCE(v_fl_revision, false) THEN
        RETURN NULL;
    END IF;

    -- -------------------------------------------------------------------------
    -- 1. Resolución del rango real según periodicidad
    -- -------------------------------------------------------------------------
    -- Si p_start_week y p_end_week son iguales, buscamos si hay una agrupación (ej. 1-2)
    IF p_start_week = p_end_week THEN
        SELECT 
            tmp.start_week,
            (tmp.start_week + COALESCE(tmp.quantity_week, 1) - 1)
        INTO v_final_start, v_final_end
        FROM type_material_periodicity tmp
        WHERE tmp.type_material_id = v_root_type_id
          AND p_start_week BETWEEN tmp.start_week AND (tmp.start_week + COALESCE(tmp.quantity_week, 1) - 1)
          AND tmp.fl_status = true
        LIMIT 1;
        
        v_final_start := COALESCE(v_final_start, p_start_week);
        v_final_end   := COALESCE(v_final_end, p_end_week);
    ELSE
        v_final_start := p_start_week;
        v_final_end   := p_end_week;
    END IF;

    -- -------------------------------------------------------------------------
    -- 2. Idempotencia: Buscar revisión activa existente
    -- -------------------------------------------------------------------------
    SELECT id INTO v_revision_id
    FROM material_revisions
    WHERE material_id      = p_material_id
      AND type_material_id = v_root_type_id
      AND start_week       = v_final_start
      AND end_week         = v_final_end
      AND deleted_at       IS NULL
      AND status NOT IN ('verified', 'material_delivered')
    LIMIT 1;

    IF v_revision_id IS NOT NULL THEN
        PERFORM fn_sync_material_revision_status(v_revision_id, p_created_by);
        RETURN v_revision_id;
    END IF;

    -- -------------------------------------------------------------------------
    -- 3. Validaciones y resolución de parámetros
    -- -------------------------------------------------------------------------

    -- Resolver y filtrar cursos: Solo se incluyen cursos que tengan registros en el balotario para este material/tipo/rango
    SELECT array_agg(DISTINCT mdbq.course_id)::smallint[]
    INTO v_resolved_courses
    FROM material_ballot_question mdbq
    INNER JOIN detail_week_type_mat dwtm ON mdbq.week_type_material_id = dwtm.id
    WHERE mdbq.material_id = p_material_id
      AND mdbq.week BETWEEN v_final_start AND v_final_end
      AND mdbq.fl_status = true
      AND (dwtm.type_material_id = v_root_type_id OR dwtm.parent_type_material_id = v_root_type_id);


    -- -------------------------------------------------------------------------
    -- 3.1 Resolviendo fecha de entrega
    -- -------------------------------------------------------------------------
    SELECT 
        mppb.created_at + interval '1 week'
    INTO v_delivery_date
    FROM material_per_period mpp
    JOIN material_per_period_ballot mppb ON mppb.material_per_period_id = mpp.id
    WHERE mpp.material_id = p_material_id
      AND mpp.type_material_id = p_type_material_id
      AND mppb.deleted_at IS NULL
      AND mppb.start_week = p_start_week
      AND mppb.end_week = p_end_week
    LIMIT 1;

    -- -------------------------------------------------------------------------
    -- 4. Cabecera
    -- -------------------------------------------------------------------------
    INSERT INTO material_revisions (
        material_id,
        type_material_id,
        start_week,
        end_week,
        delivery_date,
        status,
        created_at,
        updated_at,
        created_by
    ) VALUES (
        p_material_id,
        v_root_type_id,
        v_final_start,
        v_final_end,
        v_delivery_date,
        'generating',
        NOW(),
        NOW(),
        p_created_by
    )
    RETURNING id INTO v_revision_id;

    -- -------------------------------------------------------------------------
    -- 4.1 Historial
    -- -------------------------------------------------------------------------
    INSERT INTO material_revision_histories (
        material_revision_id,
        new_status,
        changed_at,
        changed_by
    ) VALUES (
        v_revision_id,
        'generating',
        NOW(),
        p_created_by
    );

    -- -------------------------------------------------------------------------
    -- 5. Cursos
    -- -------------------------------------------------------------------------
    IF v_resolved_courses IS NOT NULL THEN
        FOREACH v_course_id IN ARRAY v_resolved_courses
        LOOP
            INSERT INTO material_revision_courses (
                material_revision_id,
                course_id,
                status,
                created_at,
                created_by
            ) VALUES (
                v_revision_id,
                v_course_id,
                'pending_verification',
                NOW(),
                p_created_by
            )
            ON CONFLICT (material_revision_id, course_id) DO NOTHING;
        END LOOP;
    END IF;

    -- -------------------------------------------------------------------------
    -- 6. Items del pivote
    -- -------------------------------------------------------------------------
    FOR v_detail_id IN
        SELECT id
        FROM detail_week_type_mat
        WHERE material_id = p_material_id
          AND (type_material_id = v_root_type_id OR parent_type_material_id = v_root_type_id)
          AND week BETWEEN v_final_start AND v_final_end
          AND deleted_at IS NULL
          AND fl_status  = true
        ORDER BY week, parent_type_material_id NULLS FIRST, id
    LOOP
        INSERT INTO material_revision_items (
            material_revision_id,
            detail_week_type_mat_id,
            created_at,
            created_by
        ) VALUES (
            v_revision_id,
            v_detail_id,
            NOW(),
            p_created_by
        )
        ON CONFLICT (material_revision_id, detail_week_type_mat_id) DO NOTHING;
    END LOOP;

    -- 7. Sincronizar estado (automático por completitud de preguntas)
    PERFORM fn_sync_material_revision_status(v_revision_id, p_created_by);

    RETURN v_revision_id;
END;
$$;


ALTER FUNCTION odiseo.fn_create_material_revision(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_create_or_update_url_material_ballot_per_period(bigint, character varying, character varying, character varying, character varying, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_or_update_url_material_ballot_per_period(p_material_per_period_ballot_id bigint, p_type_url character varying, p_job_id character varying, p_fl_job_process character varying, p_job_url character varying, p_file_name character varying, p_created_by bigint) RETURNS TABLE(id bigint)
    LANGUAGE plpgsql
    AS $$
    DECLARE
        v_material_ballot_url_id BIGINT;
        v_number_pages SMALLINT;
    BEGIN
        SELECT
            mppbu.id INTO v_material_ballot_url_id
        FROM material_per_period_ballot_url mppbu
        WHERE mppbu.material_per_period_ballot_id = p_material_per_period_ballot_id
            AND mppbu.type_url = p_type_url
            AND mppbu.deleted_by IS NULL
        LIMIT 1;

        -- Obtener la cantidad de paginas
        SELECT
            COALESCE(MAX(mppb.pages), 0) INTO v_number_pages
        FROM material_per_period_course mppb
        WHERE mppb.material_per_period_ballot_id = p_material_per_period_ballot_id
            AND mppb.type = p_type_url
            AND mppb.deleted_by IS NULL;

        IF v_material_ballot_url_id IS NULL THEN
            INSERT INTO material_per_period_ballot_url AS mppbuc (
                material_per_period_ballot_id,
                type_url,
                job_id,
                fl_job_process,
                job_url,
                file_name,
                number_pages,
                created_by,
                created_at
            )
            VALUES (
                p_material_per_period_ballot_id,
                p_type_url,
                p_job_id,
                p_fl_job_process,
                p_job_url,
                p_file_name,
                v_number_pages,
                p_created_by,
                NOW()
            )
            RETURNING mppbuc.id INTO v_material_ballot_url_id;
        ELSE
            UPDATE material_per_period_ballot_url mppbu1
            SET type_url = p_type_url,
                job_id = p_job_id,
                fl_job_process = p_fl_job_process,
                job_url = p_job_url,
                file_name = p_file_name,
                number_pages = v_number_pages,
                updated_by = p_created_by,
                updated_at = NOW()
            WHERE mppbu1.id = v_material_ballot_url_id
            RETURNING mppbu1.id INTO v_material_ballot_url_id;
        END IF;

        RETURN QUERY
        SELECT v_material_ballot_url_id;
    END;
    $$;


ALTER FUNCTION odiseo.fn_create_or_update_url_material_ballot_per_period(p_material_per_period_ballot_id bigint, p_type_url character varying, p_job_id character varying, p_fl_job_process character varying, p_job_url character varying, p_file_name character varying, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_create_or_update_url_material_class_course(bigint, smallint, character varying, character varying, character varying, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_or_update_url_material_class_course(p_material_per_period_ballot_url_id bigint, p_course_id smallint, p_job_id character varying, p_fl_job_process character varying, p_job_url character varying, p_file_name character varying, p_created_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_material_ballot_class_url_id BIGINT;
        BEGIN
            SELECT
                mppbc.id INTO v_material_ballot_class_url_id
            FROM material_per_period_ballot_class mppbc
            WHERE mppbc.material_per_period_ballot_url_id = p_material_per_period_ballot_url_id
                AND mppbc.course_id = p_course_id
                AND mppbc.deleted_by IS NULL
            LIMIT 1;

            IF v_material_ballot_class_url_id IS NULL THEN
                INSERT INTO material_per_period_ballot_class (
                    material_per_period_ballot_url_id,
                    course_id,
                    job_id,
                    fl_job_process,
                    job_url,
                    file_name,
                    created_by,
                    created_at
                )
                VALUES (
                    p_material_per_period_ballot_url_id,
                    p_course_id,
                    p_job_id,
                    p_fl_job_process,
                    p_job_url,
                    p_file_name,
                    p_created_by,
                    NOW()
                );
            ELSE
                UPDATE material_per_period_ballot_class mppbc1
                SET course_id = p_course_id,
                    job_id = p_job_id,
                    fl_job_process = p_fl_job_process,
                    job_url = p_job_url,
                    file_name = p_file_name,
                    updated_by = p_created_by,
                    updated_at = NOW()
                WHERE mppbc1.id = v_material_ballot_class_url_id;
            END IF;
        END;
        $$;


ALTER FUNCTION odiseo.fn_create_or_update_url_material_class_course(p_material_per_period_ballot_url_id bigint, p_course_id smallint, p_job_id character varying, p_fl_job_process character varying, p_job_url character varying, p_file_name character varying, p_created_by bigint) OWNER TO postgres;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: origin_parent_question; Type: TABLE; Schema: odiseo; Owner: postgres
--

CREATE TABLE odiseo.origin_parent_question (
    id bigint NOT NULL,
    parent_id bigint NOT NULL,
    year character varying(4) NOT NULL,
    region_id bigint NOT NULL,
    university_id smallint,
    option_id smallint,
    modality_id smallint,
    areas character varying(255),
    version smallint,
    fl_status boolean DEFAULT true NOT NULL,
    created_by bigint,
    updated_by bigint,
    deleted_by bigint,
    created_at timestamp(0) without time zone,
    updated_at timestamp(0) without time zone,
    deleted_at timestamp(0) without time zone,
    modality_option_id integer
);


ALTER TABLE odiseo.origin_parent_question OWNER TO postgres;

--
-- Name: fn_create_origin_parent_question(bigint, character varying, bigint, smallint, smallint, smallint, jsonb, smallint, bigint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_origin_parent_question(p_parent_question_id bigint, p_year character varying, p_region_id bigint, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_areas jsonb, p_version smallint, p_user_id bigint, p_method_system character varying) RETURNS SETOF odiseo.origin_parent_question
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_new_id bigint;
    v_allows_frequent boolean;
    v_subtopic_id bigint;
BEGIN
    INSERT INTO origin_parent_question (
        parent_id, 
        year, 
        region_id,
        modality_option_id, 
        areas, 
        version, 
        created_by, 
        created_at
    ) VALUES (
        p_parent_question_id, 
        p_year, 
        p_region_id, 
        p_modality_id, 
        p_areas, 
        p_version, 
        p_user_id, 
        NOW()
    ) RETURNING id INTO v_new_id;

    SELECT fl_allows_mark_frequent_topic INTO v_allows_frequent 
    FROM modality_options
    WHERE id = p_modality_id;

    IF v_allows_frequent THEN
        FOR v_subtopic_id IN 
            SELECT DISTINCT qs.subtopic_id 
            FROM question q
            LEFT JOIN question_subtopic qs ON q.id = qs.question_id
            WHERE q.parent_id = p_parent_question_id 
              AND qs.subtopic_id IS NOT NULL 
              AND qs.fl_status = true
        LOOP
            PERFORM fn_change_subtopic_frequent_status(
                p_university_id::int, 
                v_subtopic_id::int, 
                p_user_id::int, 
                true, 
                p_method_system
            );
        END LOOP;
    END IF;

    RETURN QUERY SELECT * FROM origin_parent_question WHERE id = v_new_id;
END;
$$;


ALTER FUNCTION odiseo.fn_create_origin_parent_question(p_parent_question_id bigint, p_year character varying, p_region_id bigint, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_areas jsonb, p_version smallint, p_user_id bigint, p_method_system character varying) OWNER TO postgres;

--
-- Name: origin_question; Type: TABLE; Schema: odiseo; Owner: postgres
--

CREATE TABLE odiseo.origin_question (
    id bigint NOT NULL,
    question_id bigint NOT NULL,
    year character varying(4) NOT NULL,
    region_id bigint NOT NULL,
    university_id smallint,
    option_id smallint,
    modality_id smallint,
    areas character varying(255),
    fl_status boolean DEFAULT true NOT NULL,
    created_by bigint,
    updated_by bigint,
    deleted_by bigint,
    created_at timestamp(0) without time zone,
    updated_at timestamp(0) without time zone,
    deleted_at timestamp(0) without time zone,
    version smallint,
    modality_option_id integer
);


ALTER TABLE odiseo.origin_question OWNER TO postgres;

--
-- Name: fn_create_origin_question(bigint, character varying, bigint, smallint, smallint, smallint, jsonb, smallint, bigint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_origin_question(p_question_id bigint, p_year character varying, p_region_id bigint, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_areas jsonb, p_version smallint, p_user_id bigint, p_method_system character varying) RETURNS SETOF odiseo.origin_question
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_new_id bigint;
    v_allows_frequent boolean;
    v_subtopic_id bigint;
BEGIN
        INSERT INTO origin_question (
            question_id, 
            year, 
            region_id,
            modality_option_id, 
            areas, 
            version, 
            created_by, 
            created_at
        ) VALUES (
            p_question_id, 
            p_year, 
            p_region_id, 
            p_modality_id, 
            p_areas, 
            p_version, 
            p_user_id, 
            NOW()
        ) RETURNING id INTO v_new_id;


    SELECT fl_allows_mark_frequent_topic INTO v_allows_frequent 
    FROM modality_options 
    WHERE id = p_modality_id;

    IF v_allows_frequent THEN
        FOR v_subtopic_id IN 
            SELECT DISTINCT subtopic_id 
            FROM question_subtopic
            WHERE question_id = p_question_id 
              AND subtopic_id IS NOT NULL 
              AND fl_status = true
        LOOP
            PERFORM fn_change_subtopic_frequent_status(
                p_university_id::int, 
                v_subtopic_id::int, 
                p_user_id::int, 
                true, 
                p_method_system
            );
        END LOOP;
    END IF;

    RETURN QUERY SELECT * FROM origin_question WHERE id = v_new_id;
    
END;
$$;


ALTER FUNCTION odiseo.fn_create_origin_question(p_question_id bigint, p_year character varying, p_region_id bigint, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_areas jsonb, p_version smallint, p_user_id bigint, p_method_system character varying) OWNER TO postgres;

--
-- Name: fn_create_permission(character varying, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_permission(p_name character varying, p_created_by integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_new_permission_id INTEGER;
                v_count INTEGER;
            BEGIN
                -- Comprobar si ya existe un registro con el mismo nombre
                SELECT COUNT(*)
                INTO v_count
                FROM odiseo.permissions
                WHERE LOWER(name) = LOWER(p_name);
            
                -- Si no existe un registro con el mismo nombre, proceder con la inserción
                IF v_count = 0 THEN
                    INSERT INTO odiseo.permissions (name, created_by, created_at)
                    VALUES (p_name, p_created_by, now())
                    RETURNING id INTO v_new_permission_id;
            
                    RETURN v_new_permission_id;
                ELSE
                    -- Si ya existe un registro con el mismo nombre, devolver NULL
                    RETURN NULL;
                END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_create_permission(p_name character varying, p_created_by integer) OWNER TO postgres;

--
-- Name: fn_create_question_refuzed(bigint, smallint, smallint, character varying, text, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_question_refuzed(p_question_id bigint, p_category_id smallint, p_importance_id smallint, p_observation character varying, p_images text, p_created_by bigint) RETURNS TABLE(v_id bigint)
    LANGUAGE plpgsql
    AS $$
			DECLARE
				v_new_id BIGINT;
            BEGIN
                INSERT INTO odiseo.question_refuzed (category_rejected_id, importance_rejected, observation, images, question_id, created_by, created_at)
                VALUES (p_category_id, p_importance_id, p_observation, p_images, p_question_id, p_created_by, now())
                RETURNING id INTO v_new_id;

                UPDATE odiseo.question SET status = 'RECH', updated_by = p_created_by, updated_at = now() WHERE id = p_question_id;

                RETURN QUERY SELECT v_new_id;
            END;
            $$;


ALTER FUNCTION odiseo.fn_create_question_refuzed(p_question_id bigint, p_category_id smallint, p_importance_id smallint, p_observation character varying, p_images text, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_create_rol(character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_rol(p_name character varying, p_slug character varying, p_description character varying, p_created_by integer, p_company_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
    DECLARE
        v_new_rol_id INTEGER;
        v_count INTEGER;
    BEGIN
        -- Comprobar si ya existe un registro con el mismo nombre
        SELECT COUNT(*)
        INTO v_count
        FROM roles
        WHERE LOWER(name) = LOWER(p_name) AND company_id = p_company_id;
    
        -- Si no existe un registro con el mismo nombre, proceder con la inserción
        IF v_count = 0 THEN
            INSERT INTO roles (name, slug, description, created_by, created_at, company_id)
            VALUES (p_name, p_slug, p_description, p_created_by, now(), p_company_id)
            RETURNING id INTO v_new_rol_id;
    
            RETURN v_new_rol_id;
        ELSE
            -- Si ya existe un registro con el mismo nombre, devolver NULL
            RETURN NULL;
        END IF;
    END;
    $$;


ALTER FUNCTION odiseo.fn_create_rol(p_name character varying, p_slug character varying, p_description character varying, p_created_by integer, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_create_rol_permission(integer, integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_rol_permission(p_rol_id integer, p_permission_id integer, p_created_by integer, p_company_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
    DECLARE
        v_new_rol_permission_id INTEGER;
    BEGIN
        INSERT INTO roles_permissions (rol_id, permission_id, created_by,company_id, created_at)
        VALUES (p_rol_id, p_permission_id, p_created_by,p_company_id, now())
        RETURNING id AS rol_permission_id INTO v_new_rol_permission_id;
    
        RETURN v_new_rol_permission_id;
    END;
    $$;


ALTER FUNCTION odiseo.fn_create_rol_permission(p_rol_id integer, p_permission_id integer, p_created_by integer, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_create_rol_with_permission(character varying, character varying, character varying, jsonb, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_rol_with_permission(p_name character varying, p_slug character varying, p_description character varying, p_permissions jsonb, p_created_by bigint, p_company_id bigint) RETURNS TABLE(id bigint)
    LANGUAGE plpgsql
    AS $$
    DECLARE
        v_count INTEGER;
    BEGIN
        -- Comprobar si ya existe un registro con el mismo nombre
        SELECT COUNT(*)
        INTO v_count
        FROM roles r
        WHERE LOWER(r.name) = LOWER(p_name)
            AND r.company_id = p_company_id;

        IF v_count > 0 THEN
            RAISE EXCEPTION 'El rol % ya existe.', p_name;
        END IF;

        RETURN QUERY
        WITH create_rol AS (
            INSERT INTO roles as r (
                name,
                slug,
                description,
                created_by,
                company_id
            )
            VALUES (
                p_name,
                p_slug,
                p_description,
                p_created_by,
                p_company_id
            )
            RETURNING r.id
        ), insert_permissions AS (
            INSERT INTO roles_permissions (
                rol_id,
                permission_id,
                created_by,
                company_id
            )
            SELECT
                create_rol.id,
                (p.value)::BIGINT,
                p_created_by,
                p_company_id
            FROM create_rol
            CROSS JOIN jsonb_array_elements(p_permissions) p(value)
        )
        SELECT cr.id FROM create_rol cr;

    END;
    $$;


ALTER FUNCTION odiseo.fn_create_rol_with_permission(p_name character varying, p_slug character varying, p_description character varying, p_permissions jsonb, p_created_by bigint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_create_topic(character varying, character varying, integer, jsonb, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_topic(p_code character varying, p_name character varying, p_course_id integer, p_subtopics jsonb, p_created_by integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_new_topic_id INTEGER;
            BEGIN
                -- Insertar el tema principal
                INSERT INTO odiseo.topic (code, name, course_id, created_by, created_at)
                VALUES (p_code, p_name, p_course_id, p_created_by, now())
                RETURNING id INTO v_new_topic_id;

                -- Insertar los subtemas en lote
                INSERT INTO odiseo.subtopic (topic_id, code, name, created_by, created_at)
                SELECT v_new_topic_id, subtopic->>'code', subtopic->>'name', p_created_by, now()
                FROM jsonb_array_elements(p_subtopics) AS subtopic;

                RETURN v_new_topic_id;
            END;
            $$;


ALTER FUNCTION odiseo.fn_create_topic(p_code character varying, p_name character varying, p_course_id integer, p_subtopics jsonb, p_created_by integer) OWNER TO postgres;

--
-- Name: fn_create_type_material(jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_type_material(p_payload jsonb) RETURNS TABLE(result_id bigint)
    LANGUAGE plpgsql
    AS $$
                    DECLARE
                        v_parent_id     BIGINT;
                        v_child_id      BIGINT;
                        v_area_id       BIGINT;
                        v_code          VARCHAR;
                        v_header        JSONB;
                        
                        v_created_by    BIGINT;
                        v_company_id    BIGINT;
                        v_cycle_id BIGINT;
                        
                        r_child         JSONB;
                        r_area          JSONB;
                        r_course        RECORD;
                        r_sub           RECORD;
                    BEGIN
                        v_header        := p_payload -> 'header';
                        v_created_by    := (v_header->>'created_by')::BIGINT;
                        v_company_id    := (v_header->>'company_id')::BIGINT;
                        v_cycle_id := (v_header->>'cycle_id')::BIGINT;

                        -- Generar Código
                        SELECT LPAD(CAST(COUNT(id) + 1 AS TEXT), 3, '0') INTO v_code FROM type_material WHERE company_id = v_company_id;

                        -- 2. INSERTAR PADRE (RAÍZ)
                        INSERT INTO type_material (
                            code, description, created_by, created_at, cycle_id,
                            fl_exam, type_material_template_id, fl_class_material,
                            thread, level_order, percentage, amount_question, company_id,
                            order_date
                        )
                        SELECT
                            v_code,
                            tmt.name,
                            v_created_by,
                            NOW(),
                            v_cycle_id,
                            (v_header->>'is_exam')::BOOLEAN,
                            (v_header->>'template_id')::BIGINT,
                            (v_header->>'fl_class_material')::BOOLEAN,
                            (v_header->>'thread')::SMALLINT,
                            (v_header->>'level_order')::BOOLEAN,
                            (v_header->>'percentage')::NUMERIC,
                            (v_header->>'amount_question')::INT,
                            v_company_id,
                            NOW()
                        FROM type_material_template tmt
                        WHERE tmt.id = (v_header->>'template_id')::BIGINT
                        RETURNING id INTO v_parent_id;

                        -- 3. INSERTAR SEMANAS
                        IF jsonb_array_length(p_payload -> 'weeks') > 0 THEN
                            INSERT INTO type_material_detail_template (type_material_id, week, created_at, created_by)
                            SELECT v_parent_id, value::INT, NOW(), v_created_by
                            FROM jsonb_array_elements(p_payload -> 'weeks');
                        END IF;

                        -- A. CASO: TIENE HIJOS
                        IF jsonb_array_length(p_payload -> 'children') > 0 THEN
                            FOR r_child IN SELECT * FROM jsonb_array_elements(p_payload -> 'children')
                            LOOP
                                -- Insertar Hijo
                                INSERT INTO type_material (
                                    code, description, created_by, created_at, cycle_id,
                                    fl_exam, type_material_template_id, parent_id, amount_question, company_id,
                                    order_date
                                )
                                SELECT 
                                    v_code,
                                    tmt.name,
                                    v_created_by,
                                    NOW(),
                                    v_cycle_id,
                                    (v_header->>'is_exam')::BOOLEAN,
                                    (r_child->>'template_id')::BIGINT,
                                    v_parent_id, -- Link al padre
                                    (r_child->>'amount_question')::INT,
                                    v_company_id,
                                    NOW()
                                FROM type_material_template tmt
                                WHERE tmt.id = (r_child->>'template_id')::BIGINT
                                RETURNING id INTO v_child_id;

                                -- Insertar Semanas del Hijo
                                IF jsonb_array_length(r_child -> 'weeks') > 0 THEN
                                    INSERT INTO type_material_detail_template (type_material_id, week, created_at, created_by)
                                    SELECT v_child_id, value::INT, NOW(), v_created_by
                                    FROM jsonb_array_elements(r_child -> 'weeks');
                                END IF;

                                -- Insertar Cursos del Hijo
                                INSERT INTO type_material_course (type_material_id, course_id, created_by, created_at, amount_question, amount_text)
                                SELECT 
                                    v_child_id, 
                                    (c->>'course_id')::BIGINT, 
                                    v_created_by, 
                                    NOW(), 
                                    (c->>'amount_question')::INT, 
                                    (c->>'amount_text')::INT
                                FROM jsonb_array_elements(r_child -> 'courses') c;

                                -- Insertar Subpreguntas del Hijo (Texto)
                                INSERT INTO type_text_material_type_course (type_material_id, course_id, subquestion_amount, position, created_by, created_at)
                                SELECT 
                                    v_child_id,
                                    (c->>'course_id')::BIGINT,
                                    (sq->>'subquestion_amount')::SMALLINT,
                                    (sq->>'position')::SMALLINT,
                                    v_created_by,
                                    NOW()
                                FROM jsonb_array_elements(r_child -> 'courses') c
                                CROSS JOIN jsonb_array_elements(c -> 'subquestions') sq;
                            END LOOP;
                        END IF;

                        -- B. CASO: EXAMEN (Areas -> Courses)
                        IF jsonb_array_length(p_payload -> 'exam_areas') > 0 THEN
                            FOR r_area IN SELECT * FROM jsonb_array_elements(p_payload -> 'exam_areas')
                            LOOP
                                -- 1. Insertar Area
                                INSERT INTO type_material_area (type_material_id, area_id, created_by, created_at)
                                VALUES (v_parent_id, (r_area->>'area_id')::BIGINT, v_created_by, NOW())
                                RETURNING id INTO v_area_id;

                                -- 2. Recorrer Cursos del Area
                                FOR r_course IN SELECT * FROM jsonb_to_recordset(r_area -> 'courses') AS x(course_id BIGINT, amount_question INT, amount_text INT, subquestions JSONB)
                                LOOP
                                    DECLARE v_tm_course_id BIGINT;
                                    BEGIN
                                        -- Insertar Curso
                                        INSERT INTO type_material_course (type_material_id, course_id, created_by, created_at, amount_question, amount_text)
                                        VALUES (v_parent_id, r_course.course_id, v_created_by, NOW(), r_course.amount_question, r_course.amount_text)
                                        RETURNING id INTO v_tm_course_id;

                                        -- Relacionar Curso con Area
                                        INSERT INTO type_material_area_courses (type_material_course_id, type_material_area_id, created_by, created_at)
                                        VALUES (v_tm_course_id, v_area_id, v_created_by, NOW());

                                        -- Insertar Subpreguntas (Examen)
                                        IF r_course.subquestions IS NOT NULL THEN
                                            INSERT INTO type_text_material_type_course_area (type_material_id, course_id, exam_area_id, subquestion_amount, position, created_by, created_at)
                                            SELECT 
                                                v_parent_id, 
                                                r_course.course_id, 
                                                (r_area->>'area_id')::BIGINT, 
                                                (sq->>'subquestion_amount')::SMALLINT, 
                                                (sq->>'position')::SMALLINT, 
                                                v_created_by, 
                                                NOW()
                                            FROM jsonb_array_elements(r_course.subquestions) sq;
                                        END IF;
                                    END;
                                END LOOP;
                            END LOOP;
                        END IF;

                        -- C. CASO: MATERIAL ESTÁNDAR (Cursos directos)
                        IF jsonb_array_length(p_payload -> 'courses') > 0 THEN
                            -- Aquí el insert masivo está bien porque no hay jerarquía compleja dependiente de IDs generados
                            WITH raw_courses AS (
                                SELECT * FROM jsonb_to_recordset(p_payload -> 'courses') AS x(
                                    course_id BIGINT, amount_question INT, amount_text INT, subquestions JSONB
                                )
                            )
                            INSERT INTO type_material_course (type_material_id, course_id, created_by, created_at, amount_question, amount_text)
                            SELECT v_parent_id, course_id, v_created_by, NOW(), amount_question, amount_text
                            FROM raw_courses;

                            -- Insertar subpreguntas
                            INSERT INTO type_text_material_type_course (type_material_id, course_id, subquestion_amount, position, created_by, created_at)
                            SELECT 
                                v_parent_id, 
                                (c->>'course_id')::BIGINT, 
                                (sq->>'subquestion_amount')::SMALLINT,
                                (sq->>'position')::SMALLINT, 
                                v_created_by, 
                                NOW()
                            FROM jsonb_array_elements(p_payload -> 'courses') c
                            CROSS JOIN jsonb_array_elements(c->'subquestions') sq;
                        END IF;

                        -- 4. Periodicidad
                        IF (p_payload ->> 'periodicity') IS NOT NULL THEN
                            INSERT INTO type_material_periodicity (
                                type_material_id, periodicity_id, quantity_week, start_week,
                                group_previous_week, group_remaining_week, created_by, company_id,
                                created_at
                            )
                            VALUES (
                                v_parent_id, 
                                (p_payload->'periodicity'->>'id')::INT, 
                                (p_payload->'periodicity'->>'quantity_week')::INT,
                                (p_payload->'periodicity'->>'start_week')::INT,
                                (p_payload->'periodicity'->>'group_previous')::BOOL,
                                (p_payload->'periodicity'->>'group_remaining')::BOOL,
                                v_created_by,
                                v_company_id,
                                NOW()
                            );
                        END IF;

                        RETURN QUERY SELECT v_parent_id;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_create_type_material(p_payload jsonb) OWNER TO postgres;

--
-- Name: fn_create_type_material_course(smallint, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_type_material_course(p_type_material_id smallint, p_data_courses jsonb, p_created_by bigint) RETURNS smallint
    LANGUAGE plpgsql
    AS $$
			DECLARE
                v_type_matertial_course JSONB;
                v_type_material_course BIGINT;
                v_amount_question INT;
            BEGIN
                FOR v_type_matertial_course IN SELECT jsonb_array_elements(p_data_courses) LOOP
                    UPDATE odiseo.type_material_course SET amount_question = (v_type_matertial_course->>'amount_question')::INT, updated_by = p_created_by, updated_at = now()
                    WHERE course_id = (v_type_matertial_course->>'course_id')::SMALLINT AND type_material_id = p_type_material_id AND fl_status = true
                    RETURNING id INTO v_type_material_course;
                END LOOP;

                SELECT SUM(amount_question) INTO v_amount_question FROM odiseo.type_material_course WHERE type_material_id = p_type_material_id AND fl_status = true;

                IF v_amount_question <> 0 THEN
                    UPDATE odiseo.type_material SET amount_question = v_amount_question, updated_by = p_created_by, updated_at = now()
                    WHERE id = p_type_material_id;
                END IF;

                RETURN p_type_material_id;

            END;
            $$;


ALTER FUNCTION odiseo.fn_create_type_material_course(p_type_material_id smallint, p_data_courses jsonb, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_create_user(uuid, character varying, character varying, character varying, integer, character varying, integer, integer, character varying, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_user(p_uuid uuid, p_user_name character varying, p_email character varying, p_password character varying, p_status_session integer, p_image character varying, p_company integer, p_role_id integer, p_employee_uuid character varying, p_created_by integer) RETURNS TABLE(status boolean, data integer)
    LANGUAGE plpgsql
    AS $$
            DECLARE
				v_exists_username_id INT;
				v_exists_email_id INT;
				v_exists_employee_id INT;
                v_new_user_id INT;
            BEGIN
				IF p_user_name IS NOT NULL THEN
					SELECT id
					INTO v_exists_username_id
					FROM users
					WHERE LOWER("user") = LOWER(p_user_name)
                	AND fl_status = true
					LIMIT 1;
                END IF;

				IF p_email IS NOT NULL THEN
					SELECT id
					INTO v_exists_email_id
					FROM users
					WHERE LOWER(email) = LOWER(p_email)
                	AND fl_status = true
					LIMIT 1;
                END IF;

				IF v_exists_username_id IS NOT NULL THEN
					RETURN QUERY SELECT false, 1;
				ELSIF v_exists_email_id IS NOT NULL THEN
					RETURN QUERY SELECT false, 2;
				ELSE
					INSERT INTO users (uuid, "user", email, password, status_session, image, company_id, created_by, created_at)
					VALUES (p_uuid, p_user_name, p_email, p_password, p_status_session, p_image, p_company, p_created_by, now())
					RETURNING id INTO v_new_user_id;

					INSERT INTO users_roles (user_id, rol_id, created_by, created_at)
					VALUES (v_new_user_id, p_role_id, p_created_by, now());

					IF p_employee_uuid IS NOT NULL THEN
						SELECT id
						INTO v_exists_employee_id
						FROM employees
						WHERE uuid = p_employee_uuid::UUID
						AND user_id IS NULL
						AND fl_status = true
						LIMIT 1;

						IF v_exists_employee_id IS NOT NULL THEN
							UPDATE employees
							SET user_id = v_new_user_id
							WHERE id = v_exists_employee_id;
						END IF;
					END IF;

					RETURN QUERY SELECT true, v_new_user_id;
				END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_create_user(p_uuid uuid, p_user_name character varying, p_email character varying, p_password character varying, p_status_session integer, p_image character varying, p_company integer, p_role_id integer, p_employee_uuid character varying, p_created_by integer) OWNER TO postgres;

--
-- Name: fn_create_user_from_contributor(uuid, character varying, character varying, character varying, boolean, bigint, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_create_user_from_contributor(p_uuid uuid, p_user character varying, p_email character varying, p_password character varying, p_status boolean, p_company bigint, p_created_by integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_new_user_id INTEGER;
                BEGIN
                    INSERT INTO users("uuid", "user", email, "password", fl_status, status_session, company_id, created_by, created_at)
                    VALUES (p_uuid, p_user, p_email, p_password, p_status,1001, p_company, p_created_by, NOW())
                    RETURNING id AS user_id INTO v_new_user_id;

                    RETURN v_new_user_id;
                END;
            $$;


ALTER FUNCTION odiseo.fn_create_user_from_contributor(p_uuid uuid, p_user character varying, p_email character varying, p_password character varying, p_status boolean, p_company bigint, p_created_by integer) OWNER TO postgres;

--
-- Name: fn_cycle_all(character varying, character varying, character varying, boolean, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_cycle_all(p_search character varying, p_code character varying, p_description character varying, f_status boolean, p_company_id integer) RETURNS TABLE(id bigint, description character varying, cycle_template_id bigint, weeks smallint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    /*
        ------------------------------------------------------------------------------------
        -- HISTORIAL DE CAMBIOS
        ------------------------------------------------------------------------------------

        Versión: 1.1
        Fecha: 2025-11-14
        Autor: Junior Alcarraz
        Descripción:
            Se filtra por el id de la compañia del usuario logueado
    */

    RETURN QUERY
    SELECT
        c.id,
        c.description,
        c.cycle_template_id,
        c.weeks
    FROM cycle c
    WHERE c.fl_status = f_status
        AND (p_code IS NULL OR c.code ILIKE '%' || p_code || '%')
        AND (p_description IS NULL OR c.description ILIKE '%' || p_description || '%')
        AND (p_search IS NULL OR (c.code ILIKE '%' || p_search || '%' OR c.description ILIKE '%' || p_search || '%'))
        AND c.cycle_template_id IS NOT NULL
        AND c.company_id = p_company_id
        ORDER BY c.id ASC;
END;
$$;


ALTER FUNCTION odiseo.fn_cycle_all(p_search character varying, p_code character varying, p_description character varying, f_status boolean, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_cycle_paginated(character varying, character varying, character varying, boolean, boolean, integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_cycle_paginated(p_search character varying, p_code character varying, p_description character varying, f_status boolean, p_active boolean, p_perpage integer, p_npage integer, p_company_id integer) RETURNS TABLE(id bigint, description character varying, cycle_template_id bigint, weeks smallint, created_at timestamp without time zone, total bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    offset_val INT;
BEGIN
    /*
        ------------------------------------------------------------------------------------
        -- HISTORIAL DE CAMBIOS
        ------------------------------------------------------------------------------------

        Versión: 1.2
        Fecha: 2025-11-14
        Autor: Junior Alcarraz
        Descripción:
            Se filtra por el id de la compañia del usuario logueado
    */

    -- Calcular el offset para la paginación
    offset_val := p_perpage * (p_npage - 1);

    RETURN QUERY
    WITH cycles AS (
        SELECT
            c.id,
            c.description,
            c.cycle_template_id,
            c.weeks,
            c.created_at
        FROM cycle c
        WHERE c.fl_status = f_status
            AND (p_active IS NULL OR c.active = p_active)
            AND c.deleted_at IS NULL
            AND (p_code IS NULL OR c.code ILIKE '%' || p_code || '%')
            AND (p_description IS NULL OR c.description ILIKE '%' || p_description || '%')
            AND (p_search IS NULL OR (c.code ILIKE '%' || p_search || '%' OR c.description ILIKE '%' || p_search || '%'))
            AND c.company_id = p_company_id
    ), counted_cycles AS (
        SELECT
            *,
            COUNT(*) OVER () AS total_count
        FROM cycles
    )
    SELECT
        *
    FROM counted_cycles
    ORDER BY created_at DESC
    LIMIT p_perpage
    OFFSET offset_val;
END;
$$;


ALTER FUNCTION odiseo.fn_cycle_paginated(p_search character varying, p_code character varying, p_description character varying, f_status boolean, p_active boolean, p_perpage integer, p_npage integer, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_data_material_pdf(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_data_material_pdf(p_material_id bigint) RETURNS TABLE(id bigint, code_cycle character varying, start_date date, end_date date, code_cycle_template character varying, cycle_name character varying, alias_cycle_template character varying, university_id smallint, university character varying, slug_university character varying, headquarters character varying, slug_headquarters character varying, code_classroom character varying, classroom character varying)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY
                    SELECT
                        m.id,
                        c.code as code_cycle,
                        c.start_date,
                        c.end_date,
                        c.code AS code_cycle_template,
                        c.description AS cycle_name,
                        c.code AS alias_cycle_template,
                        m.university_id,
                        u.name AS university,
                        u.slug AS slug_university,
                        h.name AS headquarters,
                        h.slug AS slug_headquarters,
                        cl.code AS code_classroom,
                        cl.number AS classroom
                    FROM material m
                    INNER JOIN cycle c ON m.cycle_id = c.id
                    INNER JOIN origin_university u ON m.university_id = u.id
                    INNER JOIN headquarters h ON m.headquarte_id = h.id
                    INNER JOIN headquarters_classroom hc ON m.headquarters_classroom_id = hc.id
                    INNER JOIN classroom cl ON hc.classroom_id = cl.id
                    WHERE m.id = p_material_id;
                END;
                $$;


ALTER FUNCTION odiseo.fn_data_material_pdf(p_material_id bigint) OWNER TO postgres;

--
-- Name: fn_deactivate_material_distribution(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_deactivate_material_distribution(p_distribution_id bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rows_affected int;
BEGIN
    -- CTEs para actualizar en bloque material_ballot_question, question_history_cycle y soft-delete de subpreguntas
    WITH original_data AS (
        SELECT
            mbq1.week_type_material_id,
            mbq1.course_id,
            mbq1.parent_question_id
        FROM odiseo.material_ballot_question AS mbq1
        WHERE mbq1.id = p_distribution_id AND mbq1.fl_status = TRUE AND mbq1.parent_question_id IS NOT NULL
        LIMIT 1
    ),
    update_ballot AS (
        UPDATE odiseo.material_ballot_question AS mbq
        SET parent_question_id = NULL,
            state = 'MISSING',
            removed_in_completion = CASE WHEN mbq.id = p_distribution_id THEN TRUE ELSE mbq.removed_in_completion END,
            updated_at = NOW()
        FROM original_data d
        WHERE mbq.week_type_material_id = d.week_type_material_id
            AND mbq.course_id = d.course_id
            AND mbq.parent_question_id = d.parent_question_id
            AND mbq.fl_status = TRUE
        RETURNING mbq.id, mbq.question_history_id
    ),
    update_history AS (
        UPDATE odiseo.question_history_cycle qhc
        SET fl_status = FALSE,
            updated_at = NOW()
        FROM update_ballot ab
        WHERE qhc.id = ab.question_history_id
            AND qhc.fl_status = TRUE
        RETURNING qhc.id
    ),
    delete_subquestions AS (
        UPDATE odiseo.material_ballot_subquestions mbs
        SET question_id = NULL,
            state = 'MISSING',
            added_in_completion = FALSE,
            fl_is_manual = FALSE,
            updated_at = NOW()
        FROM update_ballot ab
        WHERE mbs.material_ballot_question_id = ab.id
          AND mbs.fl_status = TRUE
        RETURNING mbs.id
    )
    SELECT COUNT(*) INTO v_rows_affected
    FROM update_ballot;

    -- Verificar si la operación tuvo efecto
    IF COALESCE(v_rows_affected, 0) = 0 THEN
        RAISE EXCEPTION 'Distribution ID % not found or already inactive.', p_distribution_id;
    END IF;

END;
$$;


ALTER FUNCTION odiseo.fn_deactivate_material_distribution(p_distribution_id bigint) OWNER TO postgres;

--
-- Name: fn_deactive_and_retrieve_questions_for_registering(bigint, boolean, smallint, smallint, smallint, boolean, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_deactive_and_retrieve_questions_for_registering(p_material_id bigint, p_fl_validate_code boolean, p_type_material_id smallint, p_start_week smallint, p_end_week smallint, p_fetch_all_courses boolean, p_courses jsonb, p_updated_by bigint) RETURNS TABLE(id bigint, code character varying, course_id smallint, topic_id smallint, level_id smallint, level smallint, type character varying, status character varying, subtopic_id integer, frequent_subtopic boolean, cycle_id integer, week smallint, type_material_id smallint, history jsonb)
    LANGUAGE plpgsql
    AS $$
            BEGIN
            WITH type_materials AS (
                SELECT CASE
                    WHEN EXISTS (SELECT 1 FROM type_material tm WHERE tm.parent_id = p_type_material_id)
                    THEN ARRAY(SELECT tm.id FROM type_material tm WHERE tm.parent_id = p_type_material_id)
                    ELSE ARRAY[p_type_material_id]
                END v_ids_children
            ), get_type_materias AS ( -- Se trae el id de tipo material hijo si los tiene, sino se manda el normal
                SELECT unnest(tm.v_ids_children) AS type_material_id FROM type_materials tm
            ), get_detail_week_type_ids AS (
                SELECT
                    mt.id AS detail_week_type_mat_id
                FROM odiseo.detail_week_type_mat mt
                WHERE material_id = p_material_id
                AND mt.week BETWEEN p_start_week AND p_end_week
                AND mt.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
            ),deactive_material_ballot_distributions AS (
                    UPDATE material_ballot_question mdbq
                        SET fl_status = FALSE,
                            deleted_by = p_updated_by,
                            deleted_at = NOW()
                    WHERE mdbq.week_type_material_id IN (SELECT detail_week_type_mat_id FROM get_detail_week_type_ids )
                        AND (
                            p_fetch_all_courses = TRUE
                            OR mdbq.course_id = ANY(
                                SELECT value::SMALLINT FROM jsonb_array_elements(p_courses) value
                            )
                        )
                ), deactive_material_ballot_questions AS (
                    UPDATE material_ballot_question mbq
                        SET fl_status = FALSE,
                            deleted_by = p_updated_by,
                            deleted_at = NOW()
                    WHERE mbq.week_type_material_id IN (SELECT detail_week_type_mat_id FROM get_detail_week_type_ids )
                        AND (
                            p_fetch_all_courses = TRUE
                            OR mbq.course_id = ANY(
                                SELECT value::SMALLINT FROM jsonb_array_elements(p_courses) value
                            )
                        )
                    RETURNING mbq.question_history_id
                ) UPDATE question_history_cycle qhc
                    SET
                        fl_status = FALSE,
                        deleted_by = p_updated_by,
                        deleted_at = NOW()
                    WHERE 1 = 1
                    AND qhc.id IN ( SELECT question_history_id FROM deactive_material_ballot_questions )
                    AND NOT EXISTS(
                        SELECT 1 FROM material_ballot_question mqq
                        WHERE 1 = 1
                        AND mqq.fl_status IS TRUE
                        AND mqq.question_history_id = qhc.id
                        AND ( qhc.id NOT IN ( SELECT question_history_id FROM deactive_material_ballot_questions ) )
                    )
                    AND NOT EXISTS(
                        SELECT 1 FROM material_exam_question meq
                        WHERE 1 = 1
                        AND meq.fl_status IS TRUE
                        AND meq.question_history_id = qhc.id
                        AND ( qhc.id NOT IN ( SELECT question_history_id FROM deactive_material_ballot_questions ) )
                    );

                RETURN QUERY
                SELECT
                    *
                FROM fn_get_questions_register_ballot(
                    p_material_id,
                    p_fl_validate_code,
                    p_type_material_id,
                    p_start_week,
                    p_end_week
                );
            END;
            $$;


ALTER FUNCTION odiseo.fn_deactive_and_retrieve_questions_for_registering(p_material_id bigint, p_fl_validate_code boolean, p_type_material_id smallint, p_start_week smallint, p_end_week smallint, p_fetch_all_courses boolean, p_courses jsonb, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_deactive_ballot_per_course_url(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_deactive_ballot_per_course_url(p_material_revision_course_id bigint, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_material_id BIGINT;
    v_type_material_id BIGINT;
    v_start_week SMALLINT;
    v_end_week SMALLINT;
    v_course_id SMALLINT;
    v_period_ballot_id BIGINT;
BEGIN
    -- 1. Obtener datos de la revisión del curso y del material
    SELECT 
        mr.material_id,
        mr.type_material_id,
        mr.start_week,
        mr.end_week,
        mrc.course_id
    INTO 
        v_material_id,
        v_type_material_id,
        v_start_week,
        v_end_week,
        v_course_id
    FROM material_revision_courses mrc
    JOIN material_revisions mr ON mr.id = mrc.material_revision_id
    WHERE mrc.id = p_material_revision_course_id;

    -- 2. Obtener el material_per_period_ballot_id
    SELECT mppb.id INTO v_period_ballot_id
    FROM material_per_period mpp
    JOIN material_per_period_ballot mppb ON mpp.id = mppb.material_per_period_id
    WHERE mpp.type_material_id = v_type_material_id
      AND mpp.material_id = v_material_id
      AND mppb.start_week = v_start_week
      AND mppb.end_week = v_end_week;

    IF v_period_ballot_id IS NOT NULL THEN
        -- 3. Limpiar url general del balotario
        UPDATE material_per_period_ballot_url
        SET job_url = null,
            job_id = null,
            file_name = null,
            fl_job_process = 'unprocessed',
            number_pages = null,
            updated_by = p_updated_by,
            updated_at = now()
        WHERE material_per_period_ballot_id = v_period_ballot_id
          AND deleted_by IS NULL;

        -- 4. Limpiar la url y resetear páginas/reintentos a nivel del curso específico
        UPDATE material_per_period_course
        SET pages = 0,
            retries = 0,
            url = null,
            job_id = null,
            job_status = 'unprocessed',
            updated_by = p_updated_by,
            updated_at = now()
        WHERE material_per_period_ballot_id = v_period_ballot_id
          AND course_id = v_course_id
          AND deleted_by IS NULL;
    END IF;
END;
$$;


ALTER FUNCTION odiseo.fn_deactive_ballot_per_course_url(p_material_revision_course_id bigint, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_deactive_ballot_per_period_url(bigint, bigint, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_deactive_ballot_per_period_url(p_material_id bigint, p_type_material_id bigint, p_start_week smallint, p_end_week smallint) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    WITH material_per_period_ballot_id AS (
        SELECT
            mppb.id AS period_ballot_id
        FROM odiseo.material_per_period mpp
        JOIN odiseo.material_per_period_ballot mppb ON mpp.id = mppb.material_per_period_id
        WHERE 1 = 1
          AND mpp.type_material_id = p_type_material_id
          AND material_id = p_material_id
          AND mppb.start_week = p_start_week
          AND mppb.end_week = p_end_week
    ), update_unprocesses_ballot_url AS (
        UPDATE material_per_period_ballot_url mppbu
        SET job_url = null,
            job_id = null,
            file_name = null,
            fl_job_process = 'unprocessed',
            number_pages = null,
            updated_by = 1,
            updated_at = now()
        WHERE mppbu.material_per_period_ballot_id IN (SELECT period_ballot_id FROM material_per_period_ballot_id)
        AND mppbu.deleted_by IS NULL
    )
    UPDATE material_per_period_course mppc
    SET pages = 0,
        retries = 0
    WHERE mppc.material_per_period_ballot_id IN (SELECT period_ballot_id FROM material_per_period_ballot_id)
    AND mppc.deleted_by IS NULL;
END;
$$;


ALTER FUNCTION odiseo.fn_deactive_ballot_per_period_url(p_material_id bigint, p_type_material_id bigint, p_start_week smallint, p_end_week smallint) OWNER TO postgres;

--
-- Name: fn_deactive_parent_questions_exams(bigint, bigint, smallint, smallint, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_deactive_parent_questions_exams(p_material_id bigint, p_type_material_id bigint, p_course_id smallint, p_week smallint, p_area_ids jsonb, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
    BEGIN
        WITH material_exam_area_weeks_ids AS (
            SELECT
                meaw.id AS material_exam_area_week_id
            FROM material_exam_area_week meaw
            JOIN detail_week_type_mat dwtm ON meaw.week_type_material_id = dwtm.id
            WHERE 1 = 1
              AND dwtm.type_material_id = p_type_material_id
              AND dwtm.fl_status IS TRUE
              AND meaw.fl_status IS TRUE
              AND dwtm.material_id = p_material_id
              AND dwtm.week = p_week
              AND meaw.area_id IN ( SELECT JSONB_ARRAY_ELEMENTS_TEXT(p_area_ids)::SMALLINT )
        ), deactive_previous_parents AS (
            UPDATE material_exam_parent_question mpp
            SET
                deleted_at = NOW(),
                deleted_by = p_updated_by
            WHERE 1 =  1
              AND material_exam_area_week_id IN ( SELECT material_exam_area_week_id w FROM material_exam_area_weeks_ids w )
              AND course_id = p_course_id
        )
        UPDATE question_history_usage_exam_parent_question qhuepq
        SET
            updated_at = NOW(),
            updated_by = p_updated_by
        WHERE 1 = 1
          AND updated_at IS NULL
          AND course_id = p_course_id
          AND material_exam_area_week_id IN ( SELECT material_exam_area_week_id w FROM material_exam_area_weeks_ids w );
    END;
    $$;


ALTER FUNCTION odiseo.fn_deactive_parent_questions_exams(p_material_id bigint, p_type_material_id bigint, p_course_id smallint, p_week smallint, p_area_ids jsonb, p_updated_by bigint) OWNER TO postgres;

