CREATE FUNCTION odiseo.fn_delete_area(p_id integer, p_deleted_by integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_area_id INTEGER;
            BEGIN
                UPDATE odiseo.area
                SET
                    fl_status = false,
