--
-- Name: fn_delete_diagram_question(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_delete_diagram_question(p_question_id bigint, p_deleted_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_exists_edq BIGINT;
        BEGIN
            SELECT id INTO v_exists_edq
            FROM odiseo.employee_didi_question
            WHERE question_id = p_question_id
            AND fl_status = true
            LIMIT 1;

            UPDATE odiseo.employee_didi_question
            SET theory_base = null, data_unknown = null, "development " = null, answer = null, url_file = null, deleted_by = p_deleted_by, deleted_at = now()
            WHERE question_id = p_question_id
            AND fl_status = true;

            IF v_exists_edq IS NOT NULL THEN
                UPDATE odiseo.employee_didi_question_image
                SET fl_status = false, deleted_by = p_deleted_by, deleted_at = now()
                WHERE employee_didi_question_id = v_exists_edq;

                UPDATE odiseo.employee_didi_question_field
                SET fl_status = false, deleted_by = p_deleted_by, deleted_at = now()
                WHERE employee_didi_question_id = v_exists_edq;

                UPDATE odiseo.employee_didi_question_field_image
                SET fl_status = false, deleted_by = p_deleted_by, deleted_at = now()
                WHERE employee_didi_question_id = v_exists_edq;
            END IF;
        END;
        $$;


ALTER FUNCTION odiseo.fn_delete_diagram_question(p_question_id bigint, p_deleted_by bigint) OWNER TO postgres;

--
-- Name: fn_delete_distribution_ballot_questions(bigint, smallint, smallint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_delete_distribution_ballot_questions(p_material_id bigint, p_week smallint, p_type_material_id smallint, p_week_type_material_id bigint, p_deleted_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        BEGIN
            UPDATE material_ballot_subquestions
            SET fl_status = false,
                deleted_at = NOW()
            WHERE material_ballot_question_id IN (
                SELECT id 
                FROM material_ballot_question 
                WHERE material_id = p_material_id 
                  AND week = p_week 
                  AND type_material_id = p_type_material_id 
                  AND week_type_material_id = p_week_type_material_id
            );

            UPDATE material_ballot_question
            SET fl_status = false,
                deleted_at = NOW(),
                deleted_by = p_deleted_by
            WHERE material_id = p_material_id AND week = p_week AND type_material_id = p_type_material_id AND week_type_material_id = p_week_type_material_id;
        END;
        $$;


ALTER FUNCTION odiseo.fn_delete_distribution_ballot_questions(p_material_id bigint, p_week smallint, p_type_material_id smallint, p_week_type_material_id bigint, p_deleted_by bigint) OWNER TO postgres;

--
-- Name: fn_delete_exception_question(bigint, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_delete_exception_question(p_question_id bigint, p_status_old character varying, p_deleted_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_employee_question BIGINT;
        BEGIN
            IF p_status_old = 'OBSE' THEN
                UPDATE odiseo.question_observation SET fl_status = false, deleted_by = p_deleted_by, deleted_at = now()
                WHERE question_id = p_question_id AND type = 'OBSE' AND fl_status = true;
            ELSIF p_status_old = 'RECH' THEN
                UPDATE odiseo.question_refuzed SET fl_status = false, deleted_by = p_deleted_by, deleted_at = now()
                WHERE question_id = p_question_id AND fl_status = true;

                SELECT id INTO v_employee_question FROM odiseo.employee_question
                WHERE question_id = p_question_id AND fl_status = true LIMIT 1;

                UPDATE odiseo.employee_question SET board_refuzed = null, fl_refuzed = false, url_pdf_question_solution = null, updated_by = p_deleted_by, updated_at = now() WHERE question_id = p_question_id AND fl_status = true;

                IF v_employee_question IS NOT NULL THEN
                    UPDATE odiseo.employee_question_document SET document_refuzed = null, fl_refuzed = false, updated_by = p_deleted_by, updated_at = now() WHERE employee_question_id = v_employee_question AND fl_status = true;
                END IF;
            END IF;
        END;
        $$;


ALTER FUNCTION odiseo.fn_delete_exception_question(p_question_id bigint, p_status_old character varying, p_deleted_by bigint) OWNER TO postgres;

--
-- Name: fn_delete_headquarter(bigint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_delete_headquarter(p_headquarter_id bigint, p_company_id bigint, p_deleted_by bigint) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_company_count BIGINT;
BEGIN
    SELECT COUNT(*) INTO v_company_count
    FROM company_headquarters
    WHERE headquarter_id = p_headquarter_id AND deleted_at IS NULL;

    UPDATE company_headquarters
    SET deleted_by = p_deleted_by,
        deleted_at = NOW()
    WHERE headquarter_id = p_headquarter_id
      AND company_id = p_company_id
      AND deleted_at IS NULL;

    IF v_company_count <= 1 THEN
        UPDATE headquarters
        SET fl_status = false,
            deleted_by = p_deleted_by,
            deleted_at = NOW()
        WHERE id = p_headquarter_id;
    END IF;

    RETURN FOUND;
END;
$$;


ALTER FUNCTION odiseo.fn_delete_headquarter(p_headquarter_id bigint, p_company_id bigint, p_deleted_by bigint) OWNER TO postgres;

