--
-- Name: fn_delete_materials_pdfs(bigint, smallint, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_delete_materials_pdfs(p_material_id bigint, p_week smallint, p_type_material_ids jsonb, p_deleted_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_fl_exam BOOLEAN;
            v_type_material_id SMALLINT;
            v_week_type_material_id BIGINT;
            v_material_exam_area_week_id BIGINT;
        BEGIN
            -- Estado de examen o balotario
            FOR v_type_material_id IN SELECT jsonb_array_elements(p_type_material_ids) LOOP
                -- Obtener si el tipo de material es balotario o examen
                SELECT tm.fl_exam INTO v_fl_exam FROM odiseo.type_material tm WHERE tm.id = v_type_material_id LIMIT 1;

                -- Obtener el id del material de la semana y tipo material mandado y eliminar las rutas de los materiales
                UPDATE odiseo.detail_week_type_mat detm
                SET url_solution = null, url_without_solution = null, fl_process_status = 1, fl_process_status_without = 1, fl_process_class_mat = 1, url_zip_class_mat = null,
                    url_quality = null, url_without_quality = null, fl_process_quality = 1, fl_process_without_quality = 1,
                    updated_by = p_deleted_by, updated_at = now()
                WHERE detm.material_id = p_material_id
                AND detm.week = p_week
                AND detm.type_material_id = v_type_material_id
                AND detm.fl_status = true
                RETURNING detm.id INTO v_week_type_material_id;

                IF v_week_type_material_id IS NOT NULL THEN
                    IF v_fl_exam IS TRUE THEN
                        FOR v_material_exam_area_week_id IN
                            SELECT meaw.id
                            FROM odiseo.material_exam_area_week meaw
                            WHERE meaw.week_type_material_id = v_week_type_material_id
                            AND meaw.fl_status = true
                        LOOP
                            -- Eliminar las rutas de los materiales por area
                            UPDATE odiseo.material_exam_area_week meaw1
                            SET url_solution = null, url_without_solution = null, fl_process_status = 1, fl_process_status_without = 1,
                                url_quality = null, url_without_quality = null, fl_process_quality = 1, fl_process_without_quality = 1,
                                updated_by = p_deleted_by, updated_at = now()
                            WHERE meaw1.id = v_material_exam_area_week_id;
                        END LOOP;
                    END IF;
                END IF;
            END LOOP;
        END;
        $$;


ALTER FUNCTION odiseo.fn_delete_materials_pdfs(p_material_id bigint, p_week smallint, p_type_material_ids jsonb, p_deleted_by bigint) OWNER TO postgres;

--
-- Name: fn_delete_origin_question(integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_delete_origin_question(p_origin_question_id integer, p_user_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_university_id INT;
                v_question_id INT;
                v_subtopic_id INT;
                v_has_active_questions BOOLEAN;
            BEGIN

                UPDATE origin_question
                SET fl_status = false,
                    deleted_by = p_user_id,
                    deleted_at = NOW()
                WHERE id = p_origin_question_id
                RETURNING university_id, question_id INTO v_university_id, v_question_id;

                IF NOT FOUND THEN
                    RETURN;
                END IF;

                SELECT subtopic_id INTO v_subtopic_id
                FROM question_subtopic
                WHERE question_id = v_question_id
                AND fl_status = true
                LIMIT 1;

                IF v_subtopic_id IS NULL THEN
                    RETURN;
                END IF;

                SELECT EXISTS (
                    SELECT 1
                    FROM origin_question oq
                    JOIN modality m ON m.id = oq.modality_id
                    JOIN question_subtopic qs ON qs.question_id = oq.question_id
                    WHERE oq.university_id = v_university_id
                    AND qs.subtopic_id = v_subtopic_id
                    AND oq.fl_status = true
                    AND m.fl_allows_mark_frequent_topic = true
                ) INTO v_has_active_questions;

                IF NOT v_has_active_questions THEN
                    UPDATE frequent_university_subtopic
                    SET is_frequent = false,
                        updated_by = p_user_id,
                        updated_at = NOW(),
                        method = 'system' 
                    WHERE university_id = v_university_id
                    AND subtopic_id = v_subtopic_id;
                END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_delete_origin_question(p_origin_question_id integer, p_user_id integer) OWNER TO postgres;

--
-- Name: fn_delete_origin_university(smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_delete_origin_university(p_id smallint, p_deleted_by bigint) RETURNS TABLE(v_validated boolean, v_id smallint)
    LANGUAGE plpgsql
    AS $$
    DECLARE
        v_exits_id BIGINT;
        v_material_id BIGINT;
    BEGIN
        SELECT id INTO v_exits_id FROM origin_question
        WHERE university_id = p_id
        AND fl_status = true
        LIMIT 1;

        SELECT id INTO v_material_id FROM material
        WHERE university_id = p_id
        AND fl_status = true
        LIMIT 1;

        IF v_exits_id IS NULL AND v_material_id IS NULL THEN
            UPDATE origin_university
            SET deleted_by = p_deleted_by, deleted_at = now()
            WHERE id = p_id
            RETURNING id INTO v_id;

            UPDATE "option" SET university_ids = array_remove(university_ids, p_id);
            UPDATE modality SET university_ids = array_remove(university_ids, p_id);

            RETURN QUERY SELECT TRUE, v_id;
        ELSE
            RETURN QUERY SELECT FALSE, 0::SMALLINT;
        END IF;
    END;
    $$;


ALTER FUNCTION odiseo.fn_delete_origin_university(p_id smallint, p_deleted_by bigint) OWNER TO postgres;

