    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_cycle_id BIGINT;
                v_week_type_material_id BIGINT;
                v_material_exam_question RECORD;
                v_material_ballot_question RECORD;
                v_type_material RECORD;
                v_updated_week_ids BIGINT[];
                v_updated_history_ids BIGINT[];
                meaw BIGINT;
                v_count_questions_ballot int;
                v_count_questions_exam int;
                v_count_total int;
            BEGIN
                -- Obtener ciclo del material
                SELECT m.cycle_id INTO v_cycle_id FROM material m WHERE m.id = p_material_id LIMIT 1;

                -- Se recorre los tipos de materiales
                FOR v_type_material IN
                    SELECT tm.id, tm.fl_exam
                    FROM type_material tm
                    WHERE tm.id = ANY(SELECT (jsonb_array_elements_text(p_type_material_ids)::SMALLINT))
                LOOP
                    --Se limpia las rutas de los materiales generados, se obtiene el id de la semana de material
                    UPDATE detail_week_type_mat detm
                        SET url_solution = null,
                        url_without_solution = null,
                        fl_process_status = 1,
                        fl_process_status_without = 1,
                        fl_process_class_mat = 1,
                        url_zip_class_mat = null,
                        url_quality = null,
                        url_without_quality = null,
                        fl_process_quality = 1,
                        fl_process_without_quality = 1,
                        updated_by = p_deleted_by,
                        updated_at = now()
                    WHERE detm.material_id = p_material_id
                        AND detm.week = p_week
                        AND detm.type_material_id = v_type_material.id
                        AND detm.fl_status = true
                    RETURNING detm.id INTO v_week_type_material_id;

                    IF v_week_type_material_id IS NOT NULL THEN
                        -- Se valida si es examen el material
                        IF v_type_material.fl_exam IS TRUE THEN

                            -- Se limpia las rutas de los examenes generados con sus areas
                            WITH updated_meaw AS (
                                UPDATE material_exam_area_week meaw
                                SET url_solution = null,
                                    url_without_solution = null,
                                    fl_process_status = 1,
                                    fl_process_status_without = 1,
                                    url_quality = null,
                                    url_without_quality = null,
                                    fl_process_quality = 1,
                                    fl_process_without_quality = 1,
                                    data_missing_course_config = null,
                                    missing_config_message = null,
                                    number_pages = null,
                                    updated_by = p_deleted_by,
                                    updated_at = now()
                                WHERE meaw.week_type_material_id = v_week_type_material_id
                                AND meaw.fl_status = true
                                RETURNING meaw.id
                            )
                            SELECT array_agg(updated_meaw.id) FROM updated_meaw INTO v_updated_week_ids;

                            -- Elimina las preguntas de los examenes
                            WITH updated_meq AS (
                                UPDATE material_exam_question meq
                                SET fl_status = false,
                                    deleted_by = p_deleted_by,
                                    deleted_at = now()
                                WHERE meq.material_exam_area_week_id = ANY(v_updated_week_ids)
                                RETURNING meq.question_history_id
                            )
                            SELECT array_agg(DISTINCT updated_meq.question_history_id) FROM updated_meq INTO v_updated_history_ids;
                        ELSE
                            -- Elimina las preguntas de los balotarios
                            WITH updated_mbq AS (
                                UPDATE material_ballot_question mbq
                                SET fl_status = false,
                                    deleted_by = p_deleted_by,
                                    deleted_at = now()
                                WHERE mbq.week_type_material_id = v_week_type_material_id
                                    AND mbq.fl_status = true
                                RETURNING mbq.question_history_id
                            )
                            SELECT array_agg(DISTINCT updated_mbq.question_history_id) FROM updated_mbq INTO v_updated_history_ids;
                        END IF;

                        -- Elimina el historial siempre y cuando no haya mas data en balotario y examen
                        UPDATE question_history_cycle qhc
                        SET fl_status = false,
                            deleted_by = p_deleted_by,
                            deleted_at = now()
                        WHERE qhc.id = ANY(v_updated_history_ids)
                        AND NOT EXISTS (
                            SELECT 1 FROM material_ballot_question mbq
                            WHERE mbq.question_history_id = qhc.id AND mbq.fl_status = true
                        )
                        AND NOT EXISTS (
                            SELECT 1 FROM material_exam_question meq
                            WHERE meq.question_history_id = qhc.id AND meq.fl_status = true
                        )
                        AND qhc.fl_status = true;
                    END IF;
                END LOOP;

                RETURN QUERY
                SELECT
                    qnew.id,
                    qnew.code,
                    qnew.course_id,
                    qnew.topic_id,
                    qnew.level_id,
                    qnew.level,
                    qnew.type,
                    qnew.status,
                    qnew.subtopic_id,
                    qnew.frequent_subtopic,
                    qnew.cycle_id,
                    qnew.week,
                    qnew.type_material_id,
                    qnew.history
                FROM fn_list_questions_verified_and_not_excluded(p_material_id) qnew;
            END;
            $$;


ALTER FUNCTION odiseo.fn_delete_question_materials_get_questions_not_excluded(p_material_id bigint, p_week smallint, p_type_material_ids jsonb, p_deleted_by bigint, p_fl_validate_code boolean) OWNER TO postgres;

--
-- Name: fn_delete_rol(integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_delete_rol(p_rol_id integer, p_deleted_by integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
            DECLARE
                user_count INT;
            BEGIN
                SELECT COUNT(*)
                INTO user_count
                FROM odiseo.users_roles ur
                WHERE ur.rol_id = p_rol_id AND ur.fl_status = TRUE;
            
                IF user_count = 0 THEN
                    UPDATE odiseo.roles
                    SET
                        fl_status = FALSE,
                        deleted_by = p_deleted_by,
                        deleted_at = now()
                    WHERE id = p_rol_id;
                    RETURN TRUE;
                ELSE
                    RETURN FALSE;
                END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_delete_rol(p_rol_id integer, p_deleted_by integer) OWNER TO postgres;

--
-- Name: fn_delete_subtopic(smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_delete_subtopic(p_subtopic_id smallint, p_deleted_by bigint) RETURNS TABLE(r_subtopic_id smallint, question_codes jsonb, has_no_siblings boolean)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_topic_id odiseo.subtopic.topic_id%TYPE;
            v_question_codes VARCHAR[] := '{}';
            v_count_subtopics INTEGER;
        BEGIN
            SELECT
                COALESCE(array_agg(q.code), '{}'::VARCHAR[])
            INTO v_question_codes
            FROM odiseo.question q
            INNER JOIN odiseo.question_subtopic qs
            ON q.id = qs.question_id AND qs.fl_status = true
            WHERE
                qs.subtopic_id = p_subtopic_id
                AND q.deleted_at IS NULL AND q.fl_status
                AND qs.deleted_at IS NULL AND qs.fl_status;

            SELECT sb.topic_id INTO v_topic_id FROM odiseo.subtopic as sb WHERE sb.id = p_subtopic_id;
            SELECT count(id) INTO v_count_subtopics
            FROM odiseo.subtopic WHERE topic_id = v_topic_id AND fl_status AND deleted_at IS NULL;

            IF v_count_subtopics <= 1 THEN
                RETURN QUERY SELECT NULL::SMALLINT, '[]'::jsonb, TRUE;
            END IF;

            IF (array_length(v_question_codes, 1) IS NULL) OR (array_length(v_question_codes, 1) = 0) THEN
                UPDATE odiseo.subtopic SET fl_status = false, deleted_by = p_deleted_by, deleted_at = now()
                WHERE id = p_subtopic_id;

                -- Eliminacion del subtema en el template syllabus
                UPDATE odiseo.syllabus_template_topic_subtopic SET fl_status = false, deleted_by =  p_deleted_by, deleted_at  = now() WHERE  subtopic_id =  p_subtopic_id;

                  -- Eliminar el subtema del detail_syllabus_subtopic
                UPDATE odiseo.syllabus_detail_subtopic SET is_subtopic_deleted = TRUE WHERE subtopic_id = p_subtopic_id AND fl_status = true;

                RETURN QUERY SELECT p_subtopic_id, '[]'::jsonb, FALSE;
            ELSE
                RETURN QUERY SELECT NULL::SMALLINT, to_jsonb(v_question_codes), FALSE;
            END IF;
        END;
        $$;


ALTER FUNCTION odiseo.fn_delete_subtopic(p_subtopic_id smallint, p_deleted_by bigint) OWNER TO postgres;

--
-- Name: fn_delete_subtopic_syllabus(bigint, bigint, boolean, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_delete_subtopic_syllabus(p_syllabus_id bigint, p_subtopic_id bigint, p_is_deleted boolean, p_user bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_syllabus_detail_subtopics_ids BIGINT[];
        BEGIN
            -- Obtener los IDs de los subtemas del syllabus
            SELECT ARRAY(
                SELECT sds.id
                FROM odiseo.syllabus s
                LEFT JOIN odiseo.syllabus_topic st ON st.syllabus_id = s.id
                LEFT JOIN odiseo.syllabus_topic_week stw ON stw.syllabus_topic_id = st.id
                LEFT JOIN odiseo.syllabus_detail_subtopic sds ON sds.syllabus_topic_week_id = stw.id
                WHERE st.fl_status = TRUE
                AND stw.fl_status = TRUE
                AND sds.fl_status = TRUE
                AND s.id = p_syllabus_id
                AND sds.subtopic_id = p_subtopic_id
            ) INTO v_syllabus_detail_subtopics_ids;
            -- Actualizar el estado de los subtemas relacionados
            IF p_is_deleted THEN
                UPDATE odiseo.syllabus_detail_subtopic
                SET is_subtopic_deleted = FALSE
                WHERE id = ANY(v_syllabus_detail_subtopics_ids);
            ELSE
                UPDATE odiseo.syllabus_detail_subtopic
                SET fl_status = FALSE,
                    is_subtopic_deleted = FALSE,
                    deleted_by = p_user,
                    deleted_at = NOW()
                WHERE id = ANY(v_syllabus_detail_subtopics_ids);
            END IF;
        END;
        $$;


ALTER FUNCTION odiseo.fn_delete_subtopic_syllabus(p_syllabus_id bigint, p_subtopic_id bigint, p_is_deleted boolean, p_user bigint) OWNER TO postgres;

--
-- Name: fn_delete_syllabus(integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_delete_syllabus(p_syllabus_id integer, p_company_id integer, p_deleted_by integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
                    DECLARE
                        verify_delet_syllabus BOOLEAN;
                    BEGIN
                        SELECT fn_has_ballot_questions_syllabus
                        INTO verify_delet_syllabus
                        FROM fn_has_ballot_questions_syllabus(p_syllabus_id,p_company_id);
                    
                        IF verify_delet_syllabus is null or verify_delet_syllabus = FALSE THEN
                            UPDATE syllabus
                            SET
                                deleted_by = p_deleted_by,
                                deleted_at = now(),
                                fl_status = FALSE
                            WHERE id = p_syllabus_id;
                            RETURN TRUE;
                        ELSE
                            UPDATE syllabus
                            SET
                                is_deleteable = false
                            WHERE id = p_syllabus_id;
                            RETURN FALSE;
                        END IF;
                    END;
                    
        $$;


ALTER FUNCTION odiseo.fn_delete_syllabus(p_syllabus_id integer, p_company_id integer, p_deleted_by integer) OWNER TO postgres;

--
-- Name: fn_delete_topic(smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_delete_topic(p_topic_id smallint, p_deleted_by bigint) RETURNS TABLE(r_topic_id smallint)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_count_questions BIGINT;
        BEGIN
            SELECT
                count(q.id) INTO v_count_questions
            FROM odiseo.question q
            WHERE q.topic_id = p_topic_id;

            IF v_count_questions = 0 THEN
                UPDATE odiseo.topic SET fl_status = false, deleted_by = p_deleted_by, deleted_at = now()
                WHERE id = p_topic_id;
                -- Eliminando el tema en el template syllabus
                UPDATE odiseo.syllabus_template_topic SET fl_status = false, deleted_by =  p_deleted_by, deleted_at  = now() WHERE  topic_id =  p_topic_id;

                -- Eliminando el tema de syllabus_topic
                UPDATE odiseo.syllabus_topic SET is_topic_deleted = true WHERE  id IN  (SELECT st.id FROM odiseo.syllabus_topic st
                JOIN odiseo.syllabus_topic_week stw
                ON stw.syllabus_topic_id = st.id
                WHERE st.topic_id = p_topic_id  AND st.fl_status = true AND stw.fl_status = TRUE );

                RETURN QUERY SELECT p_topic_id;
            ELSE
                RETURN QUERY SELECT NULL::SMALLINT;
            END IF;
        END;
        $$;


ALTER FUNCTION odiseo.fn_delete_topic(p_topic_id smallint, p_deleted_by bigint) OWNER TO postgres;

--
-- Name: fn_delete_topic_syllabus(bigint, bigint, boolean, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_delete_topic_syllabus(p_syllabus_id bigint, p_topic_id bigint, p_is_deleted boolean, p_user bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_syllabus_topic_ids BIGINT[];
        BEGIN
            -- Obtener los IDs de los subtemas del syllabus
            SELECT ARRAY(
                SELECT st.id
                FROM odiseo.syllabus s
                LEFT JOIN odiseo.syllabus_topic st ON st.syllabus_id = s.id
                WHERE st.fl_status = TRUE
                AND s.id = p_syllabus_id
                AND st.topic_id = p_topic_id
            ) INTO v_syllabus_topic_ids;
            -- Actualizar el estado de los subtemas relacionados
            IF p_is_deleted THEN
                UPDATE odiseo.syllabus_topic
                SET is_topic_deleted = FALSE
                WHERE id = ANY(v_syllabus_topic_ids);
            ELSE
                UPDATE odiseo.syllabus_topic
                SET fl_status = FALSE,
                    is_topic_deleted = FALSE,
                    deleted_by = p_user,
                    deleted_at = NOW()
                WHERE id = ANY(v_syllabus_topic_ids);
            END IF;
        END;
        $$;


