--
-- Name: fn_delete_type_material(smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_delete_type_material(p_id smallint, p_deleted_by bigint) RETURNS TABLE(deleted_id smallint)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY
                    UPDATE odiseo.type_material 
                    SET fl_status = false, deleted_by = p_deleted_by, deleted_at = now()
                    WHERE id = p_id OR parent_id = p_id
                    RETURNING id;
                END;
                $$;


ALTER FUNCTION odiseo.fn_delete_type_material(p_id smallint, p_deleted_by bigint) OWNER TO postgres;

--
-- Name: fn_delete_url_pds_question(bigint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_delete_url_pds_question(p_question_id bigint, p_type smallint, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        BEGIN
            PERFORM id FROM question WHERE id = p_question_id FOR UPDATE;
            PERFORM question_id FROM employee_question WHERE question_id = p_question_id AND fl_status = true FOR UPDATE;
            PERFORM question_id FROM employee_didi_question WHERE question_id = p_question_id AND fl_status = true FOR UPDATE;
            
            IF p_type IN (1, 2, 3) THEN
                UPDATE employee_didi_question
                    SET
                        url_file_digitalized_solution = null,
                        url_file_digitalized_solution_updated_at = NOW(),
                        url_file_digitalized_images = null,
                        updated_by = p_updated_by,
                        updated_at = now()
                WHERE 1 = 1 
                  AND question_id = p_question_id
                  AND fl_status = true;
            END IF;

            IF p_type IN (1, 2) THEN
                UPDATE employee_question
                    SET
                        url_pdf_question_solution = null,
                        url_pdf_question_solution_updated_at = NOW(),
                        updated_by = p_updated_by,
                        updated_at = now() 
                WHERE 1 = 1
                  AND question_id = p_question_id
                  AND fl_status = true;
            END IF;

            IF p_type = 1 THEN
                UPDATE question
                    SET
                        url_pdf = null,
                        url_pdf_updated_at = NOW(),
                        updated_by = p_updated_by,
                        updated_at = now()
                    WHERE 1 = 1
                      AND id = p_question_id;
            END IF;
        END;
        $$;


ALTER FUNCTION odiseo.fn_delete_url_pds_question(p_question_id bigint, p_type smallint, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_deleted_user(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_deleted_user(p_user_id bigint, p_deleted_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        begin
            UPDATE odiseo.users  
            SET fl_status  = FALSE,
                deleted_by = p_deleted_by,
                deleted_at = now() 
            WHERE id = p_user_id;
            
               
           
           update odiseo.employees    
                   SET fl_status  = FALSE,
                deleted_by = p_deleted_by,
                deleted_at = now() 
            WHERE user_id  = p_user_id;
           
        END;
        $$;


ALTER FUNCTION odiseo.fn_deleted_user(p_user_id bigint, p_deleted_by bigint) OWNER TO postgres;

--
-- Name: fn_detail_diagrammed(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_detail_diagrammed(p_id bigint) RETURNS TABLE(id bigint, employee_id bigint, question_id bigint, theory_base text, data_unknown text, development text, answer text, images jsonb)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    dq.id,
                    dq.employee_id,
                    dq.question_id,
                    dq.theory_base,
                    dq.data_unknown,
                    dq."development ",
                    dq.answer,
                    COALESCE(
                        jsonb_agg(
                            CASE
                                WHEN edq.id IS NOT NULL THEN json_build_object(
                                    'id', edq.id,
                                    'code', edq.code,
                                    'image', edq.image,
                                    'fl_status', edq.fl_status
                                )
                                ELSE NULL
                            END
                        ) FILTER (WHERE edq.id IS NOT NULL),
                        '[]'::jsonb
                    ) AS images
                FROM odiseo.employee_didi_question dq
				LEFT JOIN odiseo.employee_didi_question_image edq ON dq.id = edq.employee_didi_question_id AND edq.fl_status = true
                WHERE dq.question_id = p_id
                AND dq.fl_status = true
				GROUP BY dq.id, dq.employee_id, dq.question_id, dq.theory_base, dq.data_unknown, dq."development ", dq.answer;
            END;
            $$;


ALTER FUNCTION odiseo.fn_detail_diagrammed(p_id bigint) OWNER TO postgres;

--
-- Name: fn_detail_template_by_material(bigint, bigint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_detail_template_by_material(p_material_id bigint, p_cycle_id bigint, p_week smallint) RETURNS TABLE(id bigint, uuid uuid, type_material_id smallint, fl_process_status integer, fl_process_without integer, fl_process_quality integer, fl_process_without_quality integer, fl_process_class_mat integer, fl_exam boolean, fl_frequent boolean, fl_complete_questions boolean, data_incomplete_questions character varying, fl_config_level boolean, fl_config_type boolean, limit_lower_question smallint, limit_upper_question smallint, material character varying, fl_class_material boolean, questions_generation_process character varying, type_exam_id bigint)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            SELECT
                dwtm.id,
                dwtm.uuid,
                typematedetatemp.type_material_id,
                COALESCE(dwtm.fl_process_status, 0) as fl_process_status,
                COALESCE(dwtm.fl_process_status_without, 0) as fl_process_status_without,
                COALESCE(dwtm.fl_process_quality, 0) as fl_process_quality,
                COALESCE(dwtm.fl_process_without_quality, 0) as fl_process_without_quality,
                COALESCE(dwtm.fl_process_class_mat, 0) as fl_process_class_mat,
                tm.fl_exam,
                CASE
                    WHEN typematetemp.type_exam_id = '4' THEN TRUE
                    ELSE FALSE
                END AS fl_frequent,
                dwtm.fl_complete_questions,
                dwtm.data_incomplete_questions,
                CASE
                    WHEN dwtm.fl_config_level IS NOT NULL THEN dwtm.fl_config_level -- Si no es NULL, conserva su valor
                    WHEN subquery.array_data IS NULL THEN TRUE -- Si el array está vacío, retorna TRUE
                    WHEN subquery.all_true THEN true -- Si todos son true, retorna true
                    ELSE false -- Si hay al menos un false, retorna false
                END AS fl_config_level,
                dwtm.fl_config_type,
                dwtm.limit_lower_question,
                dwtm.limit_upper_question,
                tm.description as material,
                tm.fl_class_material,
                dwtm.questions_generation_process AS questions_generation_process,
                typematetemp.type_exam_id
            FROM type_material_detail_template typematedetatemp
            LEFT JOIN detail_week_type_mat dwtm ON (
                dwtm.type_material_id = typematedetatemp.type_material_id AND
                dwtm.week = typematedetatemp.week AND
                dwtm.fl_status IS TRUE AND
                dwtm.material_id = p_material_id
            )
            LEFT JOIN type_material tm ON tm.id = typematedetatemp.type_material_id AND tm.fl_status = true
            LEFT JOIN type_material_template typematetemp ON tm.type_material_template_id = typematetemp.id
            LEFT JOIN LATERAL (
                SELECT
                    array_agg(json_build_object(
                        'id', d.id,
                        'type_material_id', d.type_material_id,
                        'fl_config_level', d.fl_config_level
                    )) AS array_data,
                    bool_and(d.fl_config_level) AS all_true
                FROM detail_week_type_mat d 
                WHERE 1 = 1
                    ANd d.parent_type_material_id = typematedetatemp.type_material_id
                    AND d.week = p_week
                    AND d.fl_status IS TRUE
            ) subquery ON true
            WHERE 1 = 1
                AND tm.cycle_id = p_cycle_id
                AND typematedetatemp.week = p_week
                AND NOT EXISTS (
                    SELECT 1
                    FROM type_material_bound tmb
                    WHERE tmb.type_material_template_extra_id = tm.type_material_template_id  AND tmb.fl_status = true
                )
                AND typematedetatemp.fl_status = true;
        END;
        $$;


ALTER FUNCTION odiseo.fn_detail_template_by_material(p_material_id bigint, p_cycle_id bigint, p_week smallint) OWNER TO postgres;

--
-- Name: fn_diagrammed_by_course_category(smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_diagrammed_by_course_category(p_course_id smallint, p_category_id bigint) RETURNS TABLE(id bigint, name character varying, fl_optional boolean)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            WITH tbl_diagrammed_course AS (
                SELECT
                    sdc.id,
                    fd.name,
                    sdc.fl_optional
                FROM setting_diagrammed_courses sdc
                JOIN field_diagrammed fd ON sdc.field_diagram_id = fd.id
                WHERE sdc.course_id = p_course_id
                    AND sdc.category_text_id = p_category_id
                    AND sdc.fl_status = true
	            ORDER BY sdc.position ASC
            ), tbl_diagrammed_null AS (
                SELECT
                    sdc.id,
                    fd.name,
                    sdc.fl_optional
                FROM setting_diagrammed_courses sdc
                JOIN field_diagrammed fd ON sdc.field_diagram_id = fd.id
                WHERE sdc.course_id = p_course_id
                    AND sdc.category_text_id IS NULL
                    AND sdc.fl_status = true
	            ORDER BY sdc.position ASC
            ), tbl_diagrammed_all AS (
                SELECT * FROM tbl_diagrammed_course
                UNION ALL
                SELECT * FROM tbl_diagrammed_null
                    WHERE NOT EXISTS (SELECT * FROM tbl_diagrammed_course)

            )
            SELECT * FROM tbl_diagrammed_all;
        END;
        $$;


ALTER FUNCTION odiseo.fn_diagrammed_by_course_category(p_course_id smallint, p_category_id bigint) OWNER TO postgres;

--
-- Name: fn_didi_questions_totals_v2(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_didi_questions_totals_v2(f_didi_id bigint) RETURNS TABLE(assigned_to_didi bigint, observed_digitalized bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        SUM(
            CASE
                WHEN q.status = 'DASI' THEN 1
                ELSE 0
            END
        ) AS assigned_to_didi,
            SUM(
                CASE
                    WHEN q.status = 'OBSE' THEN 1
                    ELSE 0
                END
        ) AS observed_digitalized
    FROM odiseo.employee_didi_question edq
    JOIN odiseo.question q
      ON edq.question_id = q.id
     AND q.fl_status IS TRUE
     AND edq.fl_status IS TRUE
     AND ( f_didi_id IS NULL OR edq.employee_id = f_didi_id );
END;
$$;


ALTER FUNCTION odiseo.fn_didi_questions_totals_v2(f_didi_id bigint) OWNER TO postgres;

--
-- Name: fn_digitalized_teacher_question(integer, integer, character varying, integer, integer, integer[], character varying, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_digitalized_teacher_question(p_perpage integer, p_npage integer, p_name_text character varying, p_teacher_id integer, f_employee_didi_id integer, f_course_id integer[], f_status character varying, f_type character varying) RETURNS TABLE(id bigint, key_question text, type_question text, code character varying, parent_id bigint, short_description text, subquestions jsonb, course_id smallint, course character varying, status character varying, teacher_id bigint, teacher text, url_pdf_index character varying, didi_id bigint, didi text, url_pdf_digitalized character varying, date_status timestamp without time zone, observation text, priority integer, is_missing_question boolean, total_count bigint)
    LANGUAGE plpgsql
    AS $$
            DECLARE
                offset_val INTEGER;
            BEGIN
                -- Calcular el offset
                offset_val := p_perpage * (p_npage - 1);

                RETURN QUERY
                -- Obtiene todas las preguntas de tipo P Y T
                WITH all_digitalized_questions AS (
                    SELECT
                        dq.id,
                        dq.code,
                        dq.status,
                        dq.short_description,
                        dq.parent_id,
                        dq.course_id,
                        c.name as course,
                        dq.priority
                    FROM question dq
                    LEFT JOIN course c ON dq.course_id = c.id
                    WHERE 1 = 1
                    AND dq.fl_status = TRUE
                    AND dq.deleted_at IS NULL
                    AND (
                        f_type IS NULL OR
                        (f_type = 'T' AND dq.parent_id IS NOT NULL) OR
                        (f_type = 'P' AND dq.parent_id IS NULL)
                    )
                    AND (f_course_id IS NULL OR dq.course_id = ANY(f_course_id)) -- Modificado para manejar una lista de IDs
                    AND (
                        (f_status IS NULL OR f_status = '') AND dq.status IN ('DIGI', 'OBSE')
                        OR (f_status IS NOT NULL AND f_status <> '' AND dq.status = f_status)
                    )
                    AND (
                        p_name_text IS NULL
                        OR LOWER(dq.code) LIKE '%' || LOWER(p_name_text) || '%'
                        OR unaccent(LOWER(dq.short_description)) LIKE '%' || LOWER(p_name_text) || '%'
                    )
                ),
                -- Creando una tabla con los registros de preguntas de tipo S
                digitalzied_s_subquestions AS (
                    SELECT
                        oq.parent_id AS parent_id,
                        JSONB_AGG(
                            JSONB_BUILD_OBJECT(
                                'id', oq.id,
                                'key_question', 's_' || oq.id,
                                'type_question', 'S',
                                'code', oq.code,
                                'parent_id', oq.parent_id,
                                'short_description', oq.short_description,
                                'course_id', oq.course_id,
                                'course', oq.course,
                                'status', oq.status,
                                'teacher_id', es1.id,
                                'teacher', CONCAT(es1.first_surname, ' ', es1.second_surname, ' ', es1.first_name),
                                'url_pdf_index', eoq.url_pdf_question_solution,
                                'didi_id', es2.id,
                                'didi', CONCAT(es2.first_surname, ' ', es2.second_surname, ' ', es2.first_name),
                                'url_pdf_digitalized', edq.url_file_digitalized_solution,
                                'date_status', qs1.created_at,
                                'observation', qo.description
                            )
                        ) AS subquestions
                    FROM all_digitalized_questions oq
                    LEFT JOIN question_status qs1 ON oq.id = qs1.question_id
                        AND oq.status = qs1.status AND qs1.fl_active = TRUE
                    LEFT JOIN employee_question eoq ON eoq.question_id = oq.id AND eoq.fl_status = true
                    LEFT JOIN employees es1 ON eoq.teacher_id = es1.id
                    LEFT JOIN employee_didi_question edq ON edq.question_id = oq.id AND edq.fl_status = true
                    LEFT JOIN employees es2 ON edq.employee_id = es2.id
                    LEFT JOIN question_observation qo ON qo.question_id = oq.id
                        AND qo.fl_status = true AND qo.type IN ('DIGI', 'OBSE')
                    WHERE 1 = 1
                    AND oq.parent_id IS NOT NULL
                    AND (p_teacher_id IS NULL OR es1.id = p_teacher_id)
                    AND (f_employee_didi_id IS NULL OR es2.id = f_employee_didi_id)
                    GROUP BY oq.parent_id
                ),
                tbl_questions AS (
                    SELECT -- preguntas digitalizadas de tipo P
                        q.id AS id,
                        'p_' || q.id AS key_question,
                        'P' AS type_question,
                        q.code AS code,
                        q.parent_id AS parent_id,
                        q.short_description AS short_description,
                        NULL AS subquestions,
                        q.course_id,
                        q.course,
                        q.status AS status,
                        e1.id AS teacher_id,
                        CONCAT(e1.first_surname, ' ', e1.second_surname, ' ', e1.first_name) AS teacher,
                        eq.url_pdf_question_solution AS url_pdf_index,
                        e2.id AS didi_id,
                        CONCAT(e2.first_surname, ' ', e2.second_surname, ' ', e2.first_name) AS didi,
                        edq.url_file_digitalized_solution AS url_pdf_digitalized,
                        qs.created_at AS date_status,
                        qo.description AS observation,
                        q.priority,
                        CASE WHEN mmqd.id IS NOT NULL THEN true ELSE false END AS is_missing_question
                    FROM all_digitalized_questions q
                    LEFT JOIN employee_question eq ON eq.question_id = q.id
                    LEFT JOIN question_status qs ON q.id = qs.question_id
                        AND q.status = qs.status AND qs.fl_active = true
                    LEFT JOIN employees e1 ON eq.teacher_id = e1.id
                    LEFT JOIN employee_didi_question edq ON edq.question_id = q.id AND edq.fl_status = true
                    LEFT JOIN employees e2 ON edq.employee_id = e2.id
                    LEFT JOIN question_observation qo ON qo.question_id = q.id
                        AND qo.fl_status = true AND qo.type IN ('DIGI', 'OBSE')
                    LEFT JOIN material_missing_question_detail mmqd ON mmqd.question_id = q.id
                    WHERE 1 = 1
                    AND q.parent_id IS NULL
                    AND eq.fl_status = true
                    AND (p_teacher_id IS NULL OR e1.id = p_teacher_id)
                    AND (f_employee_didi_id IS NULL OR e2.id = f_employee_didi_id)
                    UNION ALL
                    SELECT -- Preguntas digitalizadas de tipo T
                        pq.id AS id,
                        't_' || pq.id AS key_question,
                        'T' AS type_question,
                        pq.code AS code,
                        pq.id AS parent_id,
                        pq.short_description AS short_description,
                        COALESCE(dq.subquestions, '[]'::jsonb) AS subquestions,
                        pq.course_id,
                        c.name AS course,
                        pq.status AS status,
                        0::BIGINT AS teacher_id,
                        '' AS teacher,
                        '' AS url_pdf_index,
                        0::BIGINT AS didi_id,
                        '' AS didi,
                        '' AS url_pdf_digitalized,
                        pq.created_at AS date_status,
                        '' AS observation,
                        pq.priority,
                        false AS is_missing_question
                    FROM parent_question pq
                    INNER JOIN digitalzied_s_subquestions dq ON dq.parent_id = pq.id
                    INNER JOIN course c ON pq.course_id = c.id
                ),
                counted_questions AS (
                    SELECT *, count(*) OVER () AS total_count
                    FROM tbl_questions fq
                )
                SELECT *
                FROM counted_questions AS cq
                ORDER BY 
                cq.priority DESC NULLS LAST,
                cq.date_status ASC,
                CASE
                    WHEN cq.status = 'OBSE' THEN 1
                    WHEN cq.status = 'DIGI' THEN 2
                    ELSE 3
                END,
                CASE
                    WHEN cq.status = 'OBSE' THEN cq.date_status
                    ELSE NULL
                END ASC,
                CASE
                    WHEN cq.status = 'DIGI' THEN cq.date_status
                    ELSE NULL
                END ASC,
                cq.id ASC
                LIMIT p_perpage
                OFFSET offset_val;
            END;
            $$;


ALTER FUNCTION odiseo.fn_digitalized_teacher_question(p_perpage integer, p_npage integer, p_name_text character varying, p_teacher_id integer, f_employee_didi_id integer, f_course_id integer[], f_status character varying, f_type character varying) OWNER TO postgres;

--
-- Name: fn_disable_outdated_frequent_subtopics(); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_disable_outdated_frequent_subtopics() RETURNS void
    LANGUAGE plpgsql
    AS $$
    BEGIN
        WITH universities_without_san_marcos AS (
            SELECT *
            FROM origin_question oq
            WHERE oq.university_id <> 1
            AND oq.fl_status = TRUE
        ),
        ranked_questions AS (
            SELECT
                question_id,
                university_id,
                year,
                created_at,
                id,
                -- Ranking para elegir al "ganador"
                ROW_NUMBER() OVER (
                    PARTITION BY question_id
                    ORDER BY 
                        year::integer DESC,  -- Prioridad: Año numérico mayor
                        created_at DESC,     -- Desempate: Creación más reciente
                        id DESC
                ) as rn
            FROM universities_without_san_marcos
        ),
        questions_to_disable AS (
            -- Identifica los pares University-Subtopic que deben desactivarse
            SELECT DISTINCT
                rq.university_id,
                qs.subtopic_id
            FROM ranked_questions rq
            INNER JOIN question_subtopic qs ON rq.question_id = qs.question_id
            WHERE rq.rn = 1 
            AND qs.fl_status = TRUE
            -- Validación de antigüedad (> 10 años)
            AND (EXTRACT(YEAR FROM CURRENT_DATE) - rq.year::integer) > 10
        )
        -- EJECUCIÓN DEL UPDATE
        UPDATE frequent_university_subtopic fus
        SET is_frequent = FALSE
        FROM questions_to_disable qtd
        WHERE 
            fus.university_id = qtd.university_id 
            AND fus.subtopic_id = qtd.subtopic_id;
    END;
    $$;


ALTER FUNCTION odiseo.fn_disable_outdated_frequent_subtopics() OWNER TO postgres;

--
-- Name: fn_edit_alternative_ia(bigint, text, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_edit_alternative_ia(p_id bigint, p_description text, p_images jsonb, p_updated_by bigint) RETURNS TABLE(alternative_ia_id bigint)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            WITH update_alternative AS ( -- Editar descripción de la alternativa IA
                UPDATE alternative_questions_ia aqia
                SET
                    description = p_description,
                    updated_by = p_updated_by,
                    updated_at = NOW()
                FROM question_teacher_ia qtia
                WHERE aqia.question_ia_id = qtia.id
                    AND aqia.id = p_id
                    AND aqia.fl_status = true
                    AND qtia.fl_status = true
                    AND qtia.status_revised = false
                RETURNING aqia.id AS alternative_ia_id
            ), delete_images_alternatives AS ( -- Se elimina las imagenes de la pregunta IA
                UPDATE alternative_ia_images aiai
                SET
                    fl_status = false,
                    deleted_by = p_updated_by,
                    deleted_at = NOW()
                WHERE
                    aiai.alternative_ia_id = (SELECT ud.alternative_ia_id FROM update_alternative ud)
            ), get_new_images AS ( -- Se lista las nuevas imagenes de la pregunta IA
                SELECT
                    pimg->>'code' AS code,
                    pimg->>'image' AS image,
                    pimg->>'extension' AS extension
                FROM jsonb_array_elements(p_images) AS pimg
                WHERE EXISTS (SELECT 1 FROM update_alternative)
            ), insert_new_images AS ( -- Se inserta las nuevas imagenes
                INSERT INTO alternative_ia_images (
                    code,
                    extension,
                    image,
                    alternative_ia_id
                )
                SELECT
                    gni.code,
                    gni.extension,
                    gni.image,
                    ua.alternative_ia_id
                FROM get_new_images gni,
                    update_alternative ua
            )
            SELECT ua.alternative_ia_id FROM update_alternative ua;
        END;
        $$;


ALTER FUNCTION odiseo.fn_edit_alternative_ia(p_id bigint, p_description text, p_images jsonb, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_edit_description_ia(bigint, text, text, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_edit_description_ia(p_id bigint, p_description text, p_description_short text, p_images jsonb, p_updated_by bigint) RETURNS TABLE(question_ia_id bigint)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            WITH update_description AS ( -- Editar descripción de la pregunta IA
                UPDATE question_teacher_ia qtia
                SET
                    description = p_description,
                    description_short = p_description_short,
                    updated_by = p_updated_by,
                    updated_at = NOW()
                WHERE qtia.id = p_id
                    AND qtia.status_revised = false
                    AND qtia.fl_status = true
                RETURNING qtia.id AS question_ia_id
            ), delete_images_description AS ( -- Se elimina las imagenes de la pregunta IA
                UPDATE question_ia_images qiai
                SET
                    fl_status = false,
                    deleted_by = p_updated_by,
                    deleted_at = NOW()
                WHERE
                    qiai.question_ia_id = (SELECT ud.question_ia_id FROM update_description ud)
            ), get_new_images AS ( -- Se lista las nuevas imagenes de la pregunta IA
                SELECT
                    pimg->>'code' AS code,
                    pimg->>'image' AS image,
                    pimg->>'extension' AS extension
                FROM jsonb_array_elements(p_images) AS pimg
                WHERE EXISTS (SELECT 1 FROM update_description)
            ), insert_new_images AS ( -- Se inserta las nuevas imagenes
                INSERT INTO question_ia_images (
                    code,
                    extension,
                    image,
                    question_ia_id
                )
                SELECT
                    gni.code,
                    gni.extension,
                    gni.image,
                    ud.question_ia_id
                FROM get_new_images gni,
                    update_description ud
            )
            SELECT ud.question_ia_id FROM update_description ud;
        END;
        $$;


ALTER FUNCTION odiseo.fn_edit_description_ia(p_id bigint, p_description text, p_description_short text, p_images jsonb, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_edit_origin_parent_question(bigint, bigint, character varying, bigint, smallint, smallint, smallint, jsonb, smallint, bigint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_edit_origin_parent_question(p_id bigint, p_parent_question_id bigint, p_year character varying, p_region_id bigint, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_areas jsonb, p_version smallint, p_user_id bigint, p_method_system character varying) RETURNS SETOF odiseo.origin_parent_question
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_allows_frequent boolean;
    v_subtopic_id bigint;
BEGIN
    -- 1. Actualizamos el registro existente
    UPDATE origin_parent_question 
    SET 
        parent_id = p_parent_question_id,
        year = p_year,
        region_id = p_region_id,
        modality_option_id = p_modality_id, 
        areas = p_areas,
        version = p_version,
        updated_by = p_user_id,
        updated_at = NOW()
    WHERE id = p_id;

    -- 2. Verificamos si la (nueva) modalidad permite marcar temas frecuentes
    SELECT fl_allows_mark_frequent_topic INTO v_allows_frequent 
    FROM modality_options 
    WHERE id = p_modality_id;

    -- 3. Si lo permite, iteramos sobre los subtemas para actualizarlos
    IF v_allows_frequent THEN
        FOR v_subtopic_id IN 
            SELECT DISTINCT qs.subtopic_id 
            FROM question q
            LEFT JOIN question_subtopic qs ON q.id = qs.question_id
            WHERE q.parent_id = p_parent_question_id 
              AND qs.subtopic_id IS NOT NULL 
              AND qs.fl_status = true
        LOOP
            -- Ejecutamos la función por cada subtema
            PERFORM fn_change_subtopic_frequent_status(
                p_university_id::int, 
                v_subtopic_id::int, 
                p_user_id::int, 
                true, 
                p_method_system
            );
        END LOOP;
    END IF;

    -- 4. Retornamos la fila recién actualizada
    RETURN QUERY SELECT * FROM origin_parent_question WHERE id = p_id;
END;
$$;


ALTER FUNCTION odiseo.fn_edit_origin_parent_question(p_id bigint, p_parent_question_id bigint, p_year character varying, p_region_id bigint, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_areas jsonb, p_version smallint, p_user_id bigint, p_method_system character varying) OWNER TO postgres;

--
-- Name: fn_edit_origin_question(bigint, character varying, bigint, smallint, smallint, smallint, jsonb, smallint, bigint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_edit_origin_question(p_id bigint, p_year character varying, p_region_id bigint, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_areas jsonb, p_version smallint, p_user_id bigint, p_method_system character varying) RETURNS SETOF odiseo.origin_question
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_question_id bigint;
    v_allows_frequent boolean;
    v_subtopic_id bigint;
BEGIN
    -- 1. Obtenemos el question_id original antes de cualquier cambio
    SELECT question_id INTO v_question_id 
    FROM origin_question 
    WHERE id = p_id;

    -- 2. Actualizamos el registro (sin tocar el question_id por seguridad)
    UPDATE origin_question 
    SET 
        year = p_year,
        region_id = p_region_id,
        modality_option_id = p_modality_id, 
        areas = p_areas,
        version = p_version,
        updated_by = p_user_id,
        updated_at = NOW()
    WHERE id = p_id;

    -- 3. Verificamos si la nueva configuración de modalidad permite temas frecuentes
    SELECT mo.fl_allows_mark_frequent_topic INTO v_allows_frequent 
    FROM modality_options mo
    WHERE mo.id = p_modality_id;

    -- 4. Si lo permite, ejecutamos la lógica de temas frecuentes
    IF v_allows_frequent THEN
        FOR v_subtopic_id IN 
            SELECT DISTINCT subtopic_id 
            FROM question_subtopic
            WHERE question_id = v_question_id -- Usamos la variable capturada arriba
              AND subtopic_id IS NOT NULL 
              AND fl_status = true
        LOOP
            PERFORM fn_change_subtopic_frequent_status(
                p_university_id::int, 
                v_subtopic_id::int, 
                p_user_id::int, 
                true, 
                p_method_system
            );
        END LOOP;
    END IF;

    -- 5. Retornamos el registro editado
    RETURN QUERY SELECT * FROM origin_question WHERE id = p_id;
END;
$$;


ALTER FUNCTION odiseo.fn_edit_origin_question(p_id bigint, p_year character varying, p_region_id bigint, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_areas jsonb, p_version smallint, p_user_id bigint, p_method_system character varying) OWNER TO postgres;

--
-- Name: fn_edit_origin_university(smallint, character varying, character varying, smallint, smallint, jsonb, text, text, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_edit_origin_university(p_id smallint, p_name character varying, p_slug character varying, p_type smallint, p_region_id smallint, p_options jsonb, p_areas text, p_versions text, p_updated_by bigint) RETURNS TABLE(v_validated boolean, v_type integer, v_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_university_exists_id SMALLINT;
    v_option_json_item    JSONB;
    v_modality_json_item  JSONB;
    v_option_university_id INT;
    v_modality_option_id   INT;
BEGIN
    v_validated := TRUE;
    v_type      := 0;
    v_id        := p_id::BIGINT;

    -- 2. Validar nombre duplicado
    SELECT id INTO v_university_exists_id 
    FROM origin_university
    WHERE LOWER(name) = LOWER(p_name) 
      AND id <> p_id 
      AND deleted_at IS NULL 
    LIMIT 1;

    IF v_university_exists_id IS NOT NULL THEN
        v_validated := FALSE;
        v_type      := 1;
        v_id        := 0;
        RETURN NEXT; 
        RETURN;
    END IF;

    -- 3. Actualizar Universidad principal
    UPDATE origin_university
    SET name       = p_name,
        slug       = p_slug,
        type       = p_type,
        region_id  = p_region_id,
        areas      = p_areas,
        versions   = p_versions::jsonb,
        updated_by = p_updated_by,
        updated_at = now()
    WHERE id = p_id
    RETURNING id INTO v_id;

    -- 4. Soft delete preventivo de opciones
    UPDATE option_university
    SET deleted_at = now(), 
        deleted_by = p_updated_by
    WHERE university_id = v_id 
      AND deleted_at IS NULL;

    -- 5. Procesar Opciones
    FOR v_option_json_item IN SELECT * FROM jsonb_array_elements(p_options) LOOP
        v_option_university_id := NULL; 

        -- A. Buscar por ID
        IF (v_option_json_item->>'id') IS NOT NULL AND (v_option_json_item->'id') <> 'null'::jsonb THEN
            UPDATE option_university
            SET name       = v_option_json_item->>'name',
                updated_at = now(),
                updated_by = p_updated_by,
                deleted_at = NULL,
                deleted_by = NULL
            WHERE id = (v_option_json_item->>'id')::INT
              AND university_id = v_id
            RETURNING id INTO v_option_university_id;
        END IF;

        -- C. Insertar si no existe
        IF v_option_university_id IS NULL THEN
            INSERT INTO option_university (university_id, name, created_at, created_by)
            VALUES (v_id, v_option_json_item->>'name', now(), p_updated_by)
            RETURNING id INTO v_option_university_id;
        END IF;

        -- 6. Soft delete preventivo de modalidades
        UPDATE modality_options
        SET deleted_at = now(), 
            deleted_by = p_updated_by
        WHERE option_university_id = v_option_university_id 
          AND deleted_at IS NULL;

        -- 7. Procesar Modalidades
        FOR v_modality_json_item IN SELECT * FROM jsonb_array_elements(v_option_json_item->'modalities') LOOP
            v_modality_option_id := NULL; 

            -- A. Buscar modalidad por ID
            IF (v_modality_json_item->>'id') IS NOT NULL AND (v_modality_json_item->'id') <> 'null'::jsonb THEN
                UPDATE modality_options
                SET name                          = v_modality_json_item->>'name',
                    fl_allows_mark_frequent_topic = COALESCE((v_modality_json_item->>'fl_allows_mark_frequent_topic')::BOOLEAN, false),
                    updated_at                    = now(),
                    updated_by                    = p_updated_by,
                    deleted_at                    = NULL,
                    deleted_by                    = NULL
                WHERE id = (v_modality_json_item->>'id')::INT
                  AND option_university_id = v_option_university_id
                RETURNING id INTO v_modality_option_id;
            END IF;

            -- B. Buscar modalidad por nombre
            IF v_modality_option_id IS NULL THEN
                SELECT id INTO v_modality_option_id 
                FROM modality_options
                WHERE LOWER(name) = LOWER(v_modality_json_item->>'name') 
                  AND option_university_id = v_option_university_id 
                LIMIT 1;

                IF v_modality_option_id IS NOT NULL THEN
                    UPDATE modality_options
                    SET fl_allows_mark_frequent_topic = COALESCE((v_modality_json_item->>'fl_allows_mark_frequent_topic')::BOOLEAN, false),
                        updated_at                    = now(),
                        updated_by                    = p_updated_by,
                        deleted_at                    = NULL,
                        deleted_by                    = NULL
                    WHERE id = v_modality_option_id;
                END IF;
            END IF;

            -- C. Insertar modalidad nueva
            IF v_modality_option_id IS NULL THEN
                INSERT INTO modality_options (
                    option_university_id, name, fl_allows_mark_frequent_topic, created_at, created_by
                )
                VALUES (
                    v_option_university_id,
                    v_modality_json_item->>'name',
                    COALESCE((v_modality_json_item->>'fl_allows_mark_frequent_topic')::BOOLEAN, false),
                    now(),
                    p_updated_by
                );
            END IF;
        END LOOP;
    END LOOP;

    RETURN NEXT;
END;
$$;


ALTER FUNCTION odiseo.fn_edit_origin_university(p_id smallint, p_name character varying, p_slug character varying, p_type smallint, p_region_id smallint, p_options jsonb, p_areas text, p_versions text, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_edit_position_subtopics(smallint, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_edit_position_subtopics(p_topic_id smallint, p_subtopics jsonb, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_subtopics JSONB;
            v_validate_subtopic_id SMALLINT;
            v_subtopic_id SMALLINT;
        BEGIN
            FOR v_subtopics IN SELECT jsonb_array_elements(p_subtopics) LOOP
                SELECT s.id INTO v_validate_subtopic_id FROM odiseo.subtopic s
                WHERE s.id = (v_subtopics->>'id')::SMALLINT AND s.topic_id = p_topic_id AND s.fl_status = true LIMIT 1;

                IF v_validate_subtopic_id IS NOT NULL THEN
                    SELECT st.id INTO v_subtopic_id FROM odiseo.subtopic st WHERE st.code = (v_subtopics->>'code')::VARCHAR AND st.id = (v_subtopics->>'id')::SMALLINT AND st.topic_id = p_topic_id LIMIT 1;

                    IF v_subtopic_id IS NULL THEN
                        UPDATE odiseo.subtopic SET code = (v_subtopics->>'code')::VARCHAR, updated_by = p_updated_by, updated_at = now() WHERE id = (v_subtopics->>'id')::SMALLINT;
                    END IF;
                END IF;

            END LOOP;
        END;
        $$;


ALTER FUNCTION odiseo.fn_edit_position_subtopics(p_topic_id smallint, p_subtopics jsonb, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_edit_position_topics(smallint, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_edit_position_topics(p_course_id smallint, p_topics jsonb, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_topics JSONB;
            v_validate_topic_id SMALLINT;
            v_topic_id SMALLINT;
        BEGIN
            FOR v_topics IN SELECT jsonb_array_elements(p_topics) LOOP
                SELECT t.id INTO v_validate_topic_id FROM odiseo.topic t
                WHERE t.id = (v_topics->>'id')::SMALLINT AND t.course_id = p_course_id AND t.fl_status = true LIMIT 1;

                IF v_validate_topic_id IS NOT NULL THEN
                    SELECT top.id INTO v_topic_id FROM odiseo.topic top WHERE top.code = (v_topics->>'code')::VARCHAR AND top.id = (v_topics->>'id')::SMALLINT AND top.course_id = p_course_id LIMIT 1;

                    IF v_topic_id IS NULL THEN
                        UPDATE odiseo.topic SET code = (v_topics->>'code')::VARCHAR, updated_by = p_updated_by, updated_at = now() WHERE id = (v_topics->>'id')::SMALLINT;
                    END IF;
                END IF;

            END LOOP;
        END;
        $$;


ALTER FUNCTION odiseo.fn_edit_position_topics(p_course_id smallint, p_topics jsonb, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_edit_rol(integer, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_edit_rol(p_id integer, p_name character varying, p_slug character varying, p_description character varying, p_updated_by integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_rol_id INTEGER;
                v_count INTEGER;
            BEGIN
                -- Comprobar si ya existe otro registro con el mismo nombre
                SELECT COUNT(*)
                INTO v_count
                FROM odiseo.roles
                WHERE name = p_name AND id <> p_id;
            
                -- Si no existe otro registro con el mismo nombre, proceder con la actualización
                IF v_count = 0 THEN
                    UPDATE odiseo.roles
                    SET
                        name = p_name,
                        slug = p_slug,
                        description = p_description,
                        updated_by = p_updated_by,
                        updated_at = now()
                    WHERE
                        id = p_id
                    RETURNING id INTO v_rol_id;
            
                    RETURN v_rol_id;
                ELSE
                    -- Si ya existe otro registro con el mismo nombre, devolver NULL
                    RETURN NULL;
                END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_edit_rol(p_id integer, p_name character varying, p_slug character varying, p_description character varying, p_updated_by integer) OWNER TO postgres;

