--
-- Name: fn_edit_syllabus(bigint, jsonb, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_edit_syllabus(p_syllabus_id bigint, p_syllabus jsonb, p_company_id bigint, p_updated_by bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_syllabus JSONB;
            v_syllabus_topic_id BIGINT;
            v_weeks JSONB;
            v_syllabus_topic_week_id BIGINT;
            v_subtopics JSONB;
            v_syllabus_detail_subtopic_id BIGINT;
            v_type_materials JSONB;
            v_syllabus_subtopic_type_material BIGINT;
            v_total_type_material_amount INT;
            v_total_questions_amount INT;
        BEGIN
            -- Se eliminan todos los temas del temario que no se mandaron
            UPDATE syllabus_topic
            SET fl_status = false, deleted_by = p_updated_by, deleted_at = now()
            WHERE syllabus_id = p_syllabus_id
            AND company_id = p_company_id
            AND topic_id NOT IN (
                SELECT (jsonb_array_elements(p_syllabus)->>'topic_id')::SMALLINT
            );

            -- Se recorre todos los temas
            FOR v_syllabus IN SELECT jsonb_array_elements(p_syllabus) LOOP
                -- Se busca el tema para ver si existe
                SELECT id INTO v_syllabus_topic_id FROM syllabus_topic
                WHERE syllabus_id = p_syllabus_id AND topic_id = (v_syllabus->>'topic_id')::SMALLINT
                AND company_id = p_company_id
                AND fl_status = true LIMIT 1;

                -- Si no existe se crea
                IF v_syllabus_topic_id IS NULL THEN
                    INSERT INTO syllabus_topic (syllabus_id, topic_id, created_by, created_at , company_id)
                    VALUES (p_syllabus_id, (v_syllabus->>'topic_id')::SMALLINT, p_updated_by, now(), p_company_id)
                    RETURNING id INTO v_syllabus_topic_id;
                END IF;

                -- Se eliminan todos las semanas del temario que no se mandaron
                UPDATE syllabus_topic_week
                SET fl_status = false, deleted_by = p_updated_by, deleted_at = now()
                WHERE syllabus_topic_id = v_syllabus_topic_id
                AND company_id = p_company_id
                AND week NOT IN (
                    SELECT (jsonb_array_elements(v_syllabus->'weeks')->>'week_id')::SMALLINT
                );

                -- Se recorre todos las semanas
                FOR v_weeks IN SELECT jsonb_array_elements(v_syllabus->'weeks') LOOP
                    IF jsonb_typeof(v_weeks->'subtopics') = 'array' AND jsonb_array_length(v_weeks->'subtopics') > 0 THEN
                        -- Se busca la semana de un temario para ver si existe
                        SELECT id INTO v_syllabus_topic_week_id FROM syllabus_topic_week
                        WHERE syllabus_topic_id = v_syllabus_topic_id AND company_id = p_company_id AND week = (v_weeks->>'week_id')::SMALLINT AND fl_status = true LIMIT 1;

                        -- Si no existe se crea
                        IF v_syllabus_topic_week_id IS NULL THEN
                            INSERT INTO syllabus_topic_week (syllabus_topic_id, week, created_by, created_at, company_id)
                            VALUES (v_syllabus_topic_id, (v_weeks->>'week_id')::SMALLINT, p_updated_by, now(), p_company_id)
                            RETURNING id INTO v_syllabus_topic_week_id;
                        END IF;

                        -- Se eliminan todos los subtemas de la semana del temario que no se mandaron
                        UPDATE syllabus_detail_subtopic
                        SET fl_status = false, deleted_by = p_updated_by, deleted_at = now()
                        WHERE syllabus_topic_week_id = v_syllabus_topic_week_id
                        AND company_id = p_company_id
                        AND subtopic_id NOT IN (
                            SELECT (jsonb_array_elements(v_weeks->'subtopics')->>'id')::SMALLINT
                        );

                        FOR v_subtopics IN SELECT jsonb_array_elements(v_weeks->'subtopics') LOOP
                            -- Se busca el subtema de una semana de un temario para ver si existe
                            SELECT id INTO v_syllabus_detail_subtopic_id FROM syllabus_detail_subtopic WHERE syllabus_topic_week_id = v_syllabus_topic_week_id
                            AND company_id = p_company_id
                            AND subtopic_id = (v_subtopics->>'id')::SMALLINT AND fl_status = true LIMIT 1;

                            -- Si no existe se crea
                            IF v_syllabus_detail_subtopic_id IS NULL THEN
                                INSERT INTO syllabus_detail_subtopic (syllabus_topic_week_id, subtopic_id, questions_amount, created_by, created_at, company_id)
                                VALUES (v_syllabus_topic_week_id, (v_subtopics->>'id')::SMALLINT, 0, p_updated_by, now(), p_company_id)
                                RETURNING id INTO v_syllabus_detail_subtopic_id;
                            END IF;

                            -- Se eliminan todos los tipos de material del temario que no se mandaron
                            UPDATE syllabus_subtopic_type_material
                            SET fl_status = false, deleted_by = p_updated_by, deleted_at = now()
                            WHERE syllabus_detail_subtopic_id = v_syllabus_detail_subtopic_id
                            AND company_id = p_company_id
                            AND type_material_id NOT IN (
                                SELECT (elem->>'type_material_id')::SMALLINT
                                FROM jsonb_array_elements(v_subtopics->'questions_amount') AS elem
                            );

                            FOR v_type_materials IN SELECT jsonb_array_elements(v_subtopics->'questions_amount') LOOP
                                -- Se busca el tipo de material de un subtema del temario para ver si existe
                                SELECT id INTO v_syllabus_subtopic_type_material FROM syllabus_subtopic_type_material
                                WHERE syllabus_detail_subtopic_id = v_syllabus_detail_subtopic_id AND company_id = p_company_id AND type_material_id = (v_type_materials->>'type_material_id')::SMALLINT AND fl_status = true LIMIT 1;

                                -- Si no existe se crea
                                IF v_syllabus_subtopic_type_material IS NULL THEN
                                    INSERT INTO syllabus_subtopic_type_material (syllabus_detail_subtopic_id, type_material_id, questions_amount, created_by, created_at, company_id)
                                    VALUES (v_syllabus_detail_subtopic_id, (v_type_materials->>'type_material_id')::SMALLINT, (v_type_materials->>'amount')::SMALLINT, p_updated_by, now(), p_company_id);
                                ELSE
                                    UPDATE syllabus_subtopic_type_material SET questions_amount = (v_type_materials->>'amount')::SMALLINT, updated_by = p_updated_by, updated_at = now()
                                    WHERE id = v_syllabus_subtopic_type_material AND company_id = p_company_id;
                                END IF;
                            END LOOP;

                            SELECT COALESCE(SUM(questions_amount), 0) INTO v_total_type_material_amount FROM syllabus_subtopic_type_material WHERE syllabus_detail_subtopic_id = v_syllabus_detail_subtopic_id AND fl_status = true AND company_id = p_company_id;

                            UPDATE syllabus_detail_subtopic SET questions_amount = v_total_type_material_amount WHERE id = v_syllabus_detail_subtopic_id AND company_id = p_company_id;
                        END LOOP;

                        SELECT COALESCE(SUM(questions_amount), 0) INTO v_total_questions_amount FROM syllabus_detail_subtopic WHERE syllabus_topic_week_id = v_syllabus_topic_week_id AND fl_status = true AND company_id = p_company_id;

                        UPDATE syllabus_topic_week SET total_questions_amount = v_total_questions_amount WHERE id = v_syllabus_topic_week_id AND company_id = p_company_id;
                    ELSE
                        UPDATE syllabus_topic_week SET fl_status = false, deleted_by = p_updated_by, deleted_at = now()
                        WHERE syllabus_topic_id = v_syllabus_topic_id AND week >= (v_weeks->>'week_id')::SMALLINT AND company_id = p_company_id;
                    END IF;
                END LOOP;
            END LOOP;
            RETURN p_syllabus_id;
        END;
        $$;


ALTER FUNCTION odiseo.fn_edit_syllabus(p_syllabus_id bigint, p_syllabus jsonb, p_company_id bigint, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_edit_syllabus_texts(bigint, jsonb, bigint, boolean, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_edit_syllabus_texts(p_syllabus_id bigint, p_payload jsonb, p_user_id bigint, p_is_partial_update boolean, p_company_id bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_week_config    RECORD;
    v_text_week_id   BIGINT;
    v_distribution   RECORD;
    v_distribution_id BIGINT;
    v_text           RECORD;
    v_text_id        BIGINT;
    v_subtopic       RECORD;
    v_content_id     BIGINT;
    v_syllabus_text_detail_id BIGINT;
BEGIN

    -- ----------------------------------------------------------------
    -- Soft-delete de semanas que no vienen en el payload
    -- ----------------------------------------------------------------
    IF NOT p_is_partial_update THEN
        UPDATE syllabus_text_weeks
           SET fl_status  = false,
               updated_by = p_user_id,
               updated_at = now()
         WHERE syllabus_id = p_syllabus_id
           AND company_id  = p_company_id
           AND week NOT IN (
               SELECT (w ->> 'week')::int
               FROM jsonb_array_elements(p_payload) w
           );
    END IF;

    -- ----------------------------------------------------------------
    -- Iterar semanas del payload
    -- ----------------------------------------------------------------
    FOR v_week_config IN
        SELECT *
        FROM jsonb_to_recordset(p_payload) AS w(week INT, distributions JSONB)
    LOOP

        -- Upsert semana
        SELECT id INTO v_text_week_id
          FROM syllabus_text_weeks
         WHERE syllabus_id = p_syllabus_id
           AND week        = v_week_config.week
           AND company_id  = p_company_id;

        IF v_text_week_id IS NULL THEN
            INSERT INTO syllabus_text_weeks (syllabus_id, week, created_by, created_at, company_id)
            VALUES (p_syllabus_id, v_week_config.week, p_user_id, now(), p_company_id)
            RETURNING id INTO v_text_week_id;
        ELSE
            UPDATE syllabus_text_weeks
               SET fl_status  = true,
                   updated_by = p_user_id,
                   updated_at = now()
             WHERE id         = v_text_week_id
               AND company_id = p_company_id;
        END IF;

        -- Soft-delete de distributions que no vienen en el payload de esta semana
        UPDATE syllabus_text_distributions
           SET fl_status  = false,
               updated_by = p_user_id,
               updated_at = now()
         WHERE syllabus_text_week_id = v_text_week_id
           AND company_id            = p_company_id
           AND type_material_id NOT IN (
               SELECT (d ->> 'material_id')::int
               FROM jsonb_array_elements(v_week_config.distributions) d
           );

        -- Iterar distributions de la semana
        FOR v_distribution IN
            SELECT *
            FROM jsonb_to_recordset(v_week_config.distributions) AS d(material_id INT, texts JSONB)
        LOOP

            -- Upsert distribution
            SELECT id INTO v_distribution_id
              FROM syllabus_text_distributions
             WHERE syllabus_text_week_id = v_text_week_id
               AND type_material_id      = v_distribution.material_id
               AND company_id            = p_company_id;

            IF v_distribution_id IS NULL THEN
                INSERT INTO syllabus_text_distributions (syllabus_text_week_id, type_material_id, created_at, created_by, company_id)
                VALUES (v_text_week_id, v_distribution.material_id, now(), p_user_id, p_company_id)
                RETURNING id INTO v_distribution_id;
            ELSE
                UPDATE syllabus_text_distributions
                   SET fl_status  = true,
                       updated_by = p_user_id,
                       updated_at = now()
                 WHERE id         = v_distribution_id
                   AND company_id = p_company_id;
            END IF;

            -- Soft-delete de todos los textos de esta distribution (se reactivan abajo)
            UPDATE syllabus_texts
               SET fl_status  = false,
                   updated_by = p_user_id,
                   updated_at = now()
             WHERE syllabus_text_distribution_id = v_distribution_id
               AND company_id                    = p_company_id;

            -- Iterar textos de la distribution
            FOR v_text IN
                SELECT *
                FROM jsonb_to_recordset(v_distribution.texts) AS t(
                    category_id    INT,
                    subcategory_id INT,
                    position       INT,
                    style_type     VARCHAR, 
                    quantity       INT,
                    subtopics      JSONB
                )
            LOOP

                -- Upsert texto
                SELECT id INTO v_text_id
                  FROM syllabus_texts
                 WHERE syllabus_text_distribution_id = v_distribution_id
                   AND position                      = v_text.position
                   AND type_text_id                  = v_text.category_id
                   AND type_text_subcategory_id      = v_text.subcategory_id
                   AND company_id                    = p_company_id;

                IF v_text_id IS NULL THEN
                    INSERT INTO syllabus_texts (
                        syllabus_text_distribution_id, type_text_id, type_text_subcategory_id,
                        position, created_at, created_by, company_id
                    )
                    VALUES (
                        v_distribution_id, v_text.category_id, v_text.subcategory_id,
                        v_text.position, now(), p_user_id, p_company_id
                    )
                    RETURNING id INTO v_text_id;
                ELSE
                    UPDATE syllabus_texts
                       SET fl_status               = true,
                           type_text_id            = v_text.category_id,
                           type_text_subcategory_id = v_text.subcategory_id,
                           updated_by              = p_user_id,
                           updated_at              = now()
                     WHERE id         = v_text_id
                       AND company_id = p_company_id;
                END IF;

                IF v_text.quantity IS NOT NULL 
                    AND v_text.style_type IS NOT NULL 
                    AND TRIM(v_text.style_type) <> '' THEN
                    
                        SELECT id INTO v_syllabus_text_detail_id FROM syllabus_text_detail WHERE syllabus_text_id = v_text_id;

                        IF v_syllabus_text_detail_id IS NOT NULL THEN
                            UPDATE syllabus_text_detail 
                            SET 
                                quantity = v_text.quantity,
                                style_type = v_text.style_type,
                                updated_at = now(),
                                updated_by = p_user_id
                            WHERE syllabus_text_id = v_text_id;

                        ELSE 

                            INSERT INTO syllabus_text_detail 
                            (   syllabus_text_id,
                                quantity,
                                style_type,
                                created_at,
                                created_by
                            )
                            VALUES (
                                v_text_id,
                                v_text.quantity,
                                v_text.style_type,
                                now(),
                                p_user_id
                            );

                        END IF;

                END IF;

                -- Soft-delete de todos los subtopics de este texto (se reactivan abajo)
                UPDATE syllabus_text_content
                   SET fl_status  = false,
                       updated_by = p_user_id,
                       updated_at = now()
                 WHERE syllabus_text_id = v_text_id
                   AND company_id       = p_company_id;

                -- Iterar subtopics del texto
                FOR v_subtopic IN
                    SELECT *
                    FROM jsonb_to_recordset(v_text.subtopics) AS s(subtopic_id INT, quantity INT)
                LOOP

                    -- Upsert subtopic
                    SELECT id INTO v_content_id
                      FROM syllabus_text_content
                     WHERE syllabus_text_id = v_text_id
                       AND subtopic_id      = v_subtopic.subtopic_id
                       AND company_id       = p_company_id;

                    IF v_content_id IS NULL THEN
                        INSERT INTO syllabus_text_content (syllabus_text_id, subtopic_id, quantity, created_at, created_by, company_id)
                        VALUES (v_text_id, v_subtopic.subtopic_id, v_subtopic.quantity, now(), p_user_id, p_company_id);
                    ELSE
                        UPDATE syllabus_text_content
                           SET fl_status  = true,
                               quantity   = v_subtopic.quantity,
                               updated_by = p_user_id,
                               updated_at = now()
                         WHERE id         = v_content_id
                           AND company_id = p_company_id;
                    END IF;

                END LOOP; -- subtopics
            END LOOP; -- textos
        END LOOP; -- distributions
    END LOOP; -- semanas

    RETURN 'Configuración de textos actualizada para el syllabus ' || p_syllabus_id;
END;
$$;


ALTER FUNCTION odiseo.fn_edit_syllabus_texts(p_syllabus_id bigint, p_payload jsonb, p_user_id bigint, p_is_partial_update boolean, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_edit_zip_material_class(jsonb, smallint, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_edit_zip_material_class(p_detail_week_type_mat_ids jsonb, p_fl_process_class_mat smallint, p_url_zip_class_mat character varying, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_fl_process_validate SMALLINT;
        BEGIN
            IF p_fl_process_class_mat = 3 THEN
                UPDATE detail_week_type_mat
                SET
                    fl_process_class_mat = p_fl_process_class_mat,
                    url_zip_class_mat = p_url_zip_class_mat,
                    updated_by = p_updated_by,
                    updated_at = NOW()
                WHERE 1 = 1
                  AND fl_status IS TRUE
                  AND id IN ( SELECT value::BIGINT FROM jsonb_array_elements_text(p_detail_week_type_mat_ids));
            ELSE
                SELECT dwtm.fl_process_class_mat
                  INTO v_fl_process_validate
                FROM detail_week_type_mat dwtm
                WHERE 1 = 1
                  AND dwtm.fl_status IS TRUE
                  AND dwtm.id IN ( SELECT value::BIGINT FROM jsonb_array_elements_text(p_detail_week_type_mat_ids) )
                LIMIT 1;

                IF p_fl_process_class_mat = 2 AND v_fl_process_validate <> p_fl_process_class_mat THEN
                    UPDATE detail_week_type_mat
                    SET
                        fl_process_class_mat = p_fl_process_class_mat,
                        updated_by = p_updated_by,
                        updated_at = NOW()
                    WHERE 1 = 1
                      AND fl_status IS TRUE
                      AND id IN ( SELECT value::BIGINT FROM jsonb_array_elements_text(p_detail_week_type_mat_ids) );
                END IF;
            END IF;
        END;
        $$;


ALTER FUNCTION odiseo.fn_edit_zip_material_class(p_detail_week_type_mat_ids jsonb, p_fl_process_class_mat smallint, p_url_zip_class_mat character varying, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_employee_not_user(character varying, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_employee_not_user(p_name_text character varying, p_company_id integer) RETURNS TABLE(id bigint, uuid uuid, user_id bigint, first_name character varying, first_surname character varying, second_surname character varying, charge_id bigint, charge character varying, type_document_id bigint, type_document character varying, document character varying, email odiseo.email_citext)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    e.id,
                    e.uuid,
                    e.user_id,
                    e.first_name,
                    e.first_surname,
                    e.second_surname,
                    e.charge_id,
                    c.name AS charge,
                    e.type_document_id,
                    t.name as type_document,
                    e.document,
                    e.email
                FROM employees e
                INNER JOIN charge c ON e.charge_id = c.id
                INNER JOIN public.type_documents t ON e.type_document_id = t.id
                WHERE e.fl_status = true
                AND e.user_id IS NULL
                AND (
                    p_name_text IS NULL 
                    OR LOWER(e.first_name) LIKE '%' || LOWER(p_name_text) || '%' 
                    OR LOWER(e.first_surname) LIKE '%' || LOWER(p_name_text) || '%' 
                    OR LOWER(e.second_surname) LIKE '%' || LOWER(p_name_text) || '%' 
                    OR e.document LIKE '%' || p_name_text || '%'
                    OR CONCAT(LOWER(e.first_name), ' ', LOWER(e.first_surname)) LIKE '%' || LOWER(p_name_text) || '%'
                )
                AND e.company_id = p_company_id
                ORDER BY e.id ASC;
            END;
            $$;


ALTER FUNCTION odiseo.fn_employee_not_user(p_name_text character varying, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_employee_question(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_employee_question(p_question_id integer) RETURNS TABLE(id bigint, teacher_id bigint, question_id bigint, alternative_id bigint, fl_status boolean, created_by bigint, updated_by bigint, deleted_by bigint, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone, type character varying, document_solution text, board_json text, board_refuzed text, fl_refuzed boolean, week integer, year integer, solved boolean, url_pdf_question_solution character varying, user_name character varying, user_email odiseo.email_citext)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY
                    SELECT
                        eq.id,
                        eq.teacher_id,
                        eq.question_id,
                        eq.alternative_id,
                        eq.fl_status,
                        eq.created_by,
                        eq.updated_by,
                        eq.deleted_by,
                        eq.created_at,
                        eq.updated_at,
                        eq.deleted_at,
                        eq.type,
                        eq.document_solution,
                        eq.board_json,
                        eq.board_refuzed,
                        eq.fl_refuzed,
                        eq.week,
                        eq.year,
                        eq.solved,
                        eq.url_pdf_question_solution,
                        u.user as user_name,
                        u.email as user_email
                    FROM employee_question eq
                    LEFT JOIN users u ON eq.created_by = u.id
                    WHERE eq.fl_status = TRUE
                    AND eq.deleted_at IS NULL
                    AND eq.question_id = p_question_id
                    ORDER BY eq.id ASC;
                END;
                $$;


ALTER FUNCTION odiseo.fn_employee_question(p_question_id integer) OWNER TO postgres;

--
-- Name: fn_employee_question_document(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_employee_question_document(p_question_id integer) RETURNS TABLE(id bigint, employee_question_id bigint, type_archive_id smallint, document text, document_refuzed text, fl_refuzed boolean, fl_status boolean, created_by bigint, updated_by bigint, deleted_by bigint, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone, type_archive character varying, extension character varying, teacher_id bigint, question_id bigint, user_name character varying, user_email odiseo.email_citext)
    LANGUAGE plpgsql
    AS $$
                        BEGIN
                            RETURN QUERY
                            SELECT
                                d.id,
                                d.employee_question_id,
                                d.type_archive_id,
                                d.document,
                                d.document_refuzed,
                                d.fl_refuzed,
                                d.fl_status,
                                d.created_by,
                                d.updated_by,
                                d.deleted_by,
                                d.created_at,
                                d.created_at,
                                d.created_at,
                                t.name as type_archive,
                                t.extension,
                                eq.teacher_id,
                                eq.question_id,
                                u.user as user_name,
                                u.email as user_email
                            FROM employee_question_document d
                            INNER JOIN employee_question eq ON d.employee_question_id = eq.id AND eq.fl_status = TRUE
                            LEFT JOIN type_archive t ON d.type_archive_id = t.id
                            LEFT JOIN users u ON d.created_by = u.id
                            WHERE d.fl_status = TRUE
                            AND d.deleted_at IS NULL
                            AND eq.question_id = p_question_id
                            ORDER BY d.id ASC;
                        END;
                        $$;


ALTER FUNCTION odiseo.fn_employee_question_document(p_question_id integer) OWNER TO postgres;

