--
-- Name: fn_exam_key_generation(integer, integer, integer, integer, jsonb, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_exam_key_generation(p_perpage integer, p_npage integer, p_cycle_id integer, p_exam_area_id integer, p_week jsonb, p_cycle_type_id integer, p_cycle_active integer, p_university_id integer, p_exam_type_template_id integer, p_company_id integer) RETURNS TABLE(id bigint, integer_date integer, cycle character varying, cycle_name character varying, formated_date character varying, week smallint, area character varying, exam_type character varying, cycle_type character varying, code character varying, total_count bigint)
    LANGUAGE plpgsql
    AS $$
                DECLARE
                    offset_val INTEGER;
                BEGIN
                    offset_val := p_perpage * (p_npage - 1);

                    RETURN QUERY
                    WITH tbl_exams AS(
                        SELECT
                            meaw.id,
                            (EXTRACT(DAY FROM meaw.created_at - '1900-01-01'::timestamp) + 2)::integer AS integer_date,
                            c.code AS cycle,
                            c.description AS cycle_name,
                            TO_CHAR(meaw.created_at, 'DD/MM/YYYY HH24:MI:SS')::varchar AS formated_date,
                            dwtm.week,
                            COALESCE(ea.short_description, '') AS area,
                            COALESCE(UPPER(CASE 
                                WHEN POSITION(' ' IN tm.description) > 0 THEN 
                                    SUBSTRING(split_part(tm.description, ' ', 1) FROM length(split_part(tm.description, ' ', 1)) - 1 FOR 2)
                                ELSE 
                                    SUBSTRING(tm.description FROM length(tm.description) - 1 FOR 2)
                            END), '')::varchar AS exam_type,
                            COALESCE(ct.name, '') AS cycle_type
                        FROM material_exam_area_week meaw
                        LEFT JOIN exam_area ea
                            ON meaw.area_id = ea.id
                        LEFT JOIN detail_week_type_mat dwtm
                            ON meaw.week_type_material_id = dwtm.id AND dwtm.fl_status IS TRUE
                        INNER JOIN material m ON m.id = dwtm.material_id
                        LEFT JOIN type_material tm
                            ON dwtm.type_material_id = tm.id
                        INNER JOIN type_material_template tmt
                            ON tm.type_material_template_id = tmt.id AND tmt.fl_status = TRUE
                        LEFT JOIN exam_material_configurations emc
                            ON tm.id = emc.type_material_id AND emc.cycle_id = m.cycle_id
                        LEFT JOIN cycle c
                            ON m.cycle_id = c.id
                        LEFT JOIN cycle_types ct
                            ON c.cycle_type_id = ct.id
                        WHERE meaw.fl_status = TRUE
                            AND m.company_id = p_company_id
                            AND (p_cycle_id IS NULL OR c.id = p_cycle_id)
                            AND (
                            p_cycle_active IS NULL
                            OR c.active = CASE WHEN p_cycle_active = 1 THEN TRUE ELSE FALSE END
                            )
                            AND (p_cycle_type_id IS NULL OR ct.id = p_cycle_type_id)
                            AND (p_exam_area_id IS NULL OR ea.id = p_exam_area_id)
                            AND (p_week IS NULL OR dwtm.week = ANY(SELECT (jsonb_array_elements_text(p_week))::bigint))
                            AND (p_university_id IS NULL OR m.university_id = p_university_id)
                            AND (p_exam_type_template_id IS NULL OR tmt.id = p_exam_type_template_id)
                        GROUP BY meaw.id, meaw.created_at, c.code, c.description, dwtm.week, ea.short_description, tm.description, ct.name
                        ORDER BY meaw.created_at DESC
                    )
                    SELECT 
                        tbl.*, 
                        CONCAT(tbl.integer_date, tbl.exam_type, tbl.cycle_type, tbl.area)::varchar as code,
                        count(*) OVER () AS total_count
                    FROM tbl_exams as tbl
                    LIMIT p_perpage
                    OFFSET offset_val;
                END;
            $$;


ALTER FUNCTION odiseo.fn_exam_key_generation(p_perpage integer, p_npage integer, p_cycle_id integer, p_exam_area_id integer, p_week jsonb, p_cycle_type_id integer, p_cycle_active integer, p_university_id integer, p_exam_type_template_id integer, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_exam_material_list_cycle(character varying, boolean, integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_exam_material_list_cycle(p_search character varying, p_active boolean, p_perpage integer, p_npage integer, p_company_id integer) RETURNS TABLE(id bigint, cycle_id bigint, description character varying, created_at timestamp without time zone, total bigint)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            offset_val INT;
        BEGIN
            /*
                ------------------------------------------------------------------------------------
                -- HISTORIAL DE CAMBIOS
                ------------------------------------------------------------------------------------

                Versión: 1.3
                Fecha: 2025-11-14
                Autor: Junior Alcarraz
                Descripción:
                    Se filtra por el id de la compañia del usuario logueado
            */

            -- Calcular el offset para la paginación
            offset_val := p_perpage * (p_npage - 1);

            RETURN QUERY
            WITH cycles AS (
                SELECT DISTINCT
                    c.id,
                    c.id AS cycle_id,
                    c.description,
                    c.created_at
                FROM cycle c
                INNER JOIN type_material tm ON c.id = tm.cycle_id
                WHERE (p_active IS NULL OR c.active = p_active)
                AND c.deleted_at IS NULL
                AND (p_search IS NULL OR (c.code ILIKE '%' || p_search || '%' OR c.description ILIKE '%' || p_search || '%'))
                AND c.company_id = p_company_id
            ), counted_cycles AS (
                SELECT
                    *,
                    COUNT(*) OVER () AS total_count
                FROM cycles
            )
            SELECT
                *
            FROM counted_cycles
            ORDER BY created_at DESC
            LIMIT p_perpage
            OFFSET offset_val;
        END;
        $$;


ALTER FUNCTION odiseo.fn_exam_material_list_cycle(p_search character varying, p_active boolean, p_perpage integer, p_npage integer, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_exam_type(character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_exam_type(p_description character varying) RETURNS TABLE(id bigint, name character varying)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY
                    SELECT
                        tmt.id,
                        tmt.name
                    FROM odiseo.type_material tm

                    INNER JOIN odiseo.detail_week_type_mat AS dwtm
                        ON tm.id = dwtm.type_material_id AND dwtm.fl_status = TRUE

                    INNER JOIN odiseo.material_exam_area_week meaw
                        ON dwtm.id = meaw.week_type_material_id AND meaw.fl_status = TRUE

                    INNER JOIN odiseo.type_material_template tmt
                        ON tm.type_material_template_id = tmt.id AND tmt.fl_status = TRUE

                    WHERE tm.fl_status = true
                    AND (
                        p_description IS NULL
                        OR LOWER(tm.description) LIKE '%' || LOWER(p_description) || '%'
                    )
                    GROUP BY tmt.id, tmt.name
                    ORDER BY tmt.id ASC;
                END;
            $$;


ALTER FUNCTION odiseo.fn_exam_type(p_description character varying) OWNER TO postgres;

--
-- Name: fn_field_diagramm_by_course(smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_field_diagramm_by_course(p_course_id smallint, p_question_id bigint) RETURNS TABLE(id bigint, name character varying, fl_optional boolean)
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                        RETURN QUERY
                        WITH tbl_parent_question AS (
                            SELECT
                                pq.type_text_id
                            FROM question q
                            LEFT JOIN parent_question pq ON q.parent_id = pq.id
                            WHERE q.id = p_question_id
                        ), tbl_diagrammed_course AS (
                            SELECT
                                sdc.id,
                                fd.name,
                                sdc.fl_optional 
                            FROM setting_diagrammed_courses sdc
                            JOIN field_diagrammed fd ON sdc.field_diagram_id = fd.id
                            WHERE sdc.course_id = p_course_id
                                AND sdc.category_text_id = (SELECT tpq.type_text_id FROM tbl_parent_question tpq)
                                AND sdc.fl_status = true
                            ORDER BY sdc.position ASC
                        ), tbl_diagrammed_null AS (
                            SELECT
                                sdc.id,
                                fd.name,
                                sdc.fl_optional 
                            FROM setting_diagrammed_courses sdc
                            JOIN field_diagrammed fd ON sdc.field_diagram_id = fd.id
                            WHERE sdc.course_id = p_course_id
                                AND sdc.category_text_id IS NULL
                                AND sdc.fl_status = true
                            ORDER BY sdc.position ASC
                        ), tbl_diagrammed_all AS (
                            SELECT * FROM tbl_diagrammed_course
                            UNION ALL
                            SELECT * FROM tbl_diagrammed_null
                            WHERE NOT EXISTS (SELECT * FROM tbl_diagrammed_course)
                        )
                        SELECT * FROM tbl_diagrammed_all;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_field_diagramm_by_course(p_course_id smallint, p_question_id bigint) OWNER TO postgres;

--
-- Name: fn_find_approved_question_for_word_download(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_approved_question_for_word_download(p_question_id integer) RETURNS TABLE(id bigint, description text, number character varying, parent_id bigint, config_alternative smallint, code_course character varying, name_course character varying, answer_id bigint, alternatives jsonb, question_image jsonb, theory_base text, data_unknown text, development text, answer text, url_file_digitalized_solution character varying, question_image_digitalized jsonb)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    q.id as question_id,
                    q.description,
                    q.number,
                    q.parent_id,
                    ca."columns" as config_alternative,
                    c.code  as code_course,
                    c.name as name_course,
                    q.answer_id,
                    (
                        SELECT jsonb_agg(jsonb_build_object('id_anwer', a.id, 'alternative_description', a.description))
                        FROM odiseo.alternative a
                        WHERE a.question_id = q.id
                    ) as alternatives,
                    (
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'id', qi.id,
                                'code', qi.code,
                                'image', qi.image
                            )
                        )
                        FROM odiseo.question_image qi
                        WHERE qi.question_id = q.id
                    ) as question_image,
                    edq.theory_base,
                    edq.data_unknown,
                    edq."development " as development,
                    edq.answer,
                    edq.url_file_digitalized_solution,
                    COALESCE(
                        jsonb_agg(
                            jsonb_build_object(
                                'code', edqi.code,
                                'image', edqi.image
                            )
                        ) FILTER (WHERE edqi.employee_didi_question_id IS NOT NULL),
                        '[]'::jsonb
                    ) as question_image_digitalized
                FROM
                    odiseo.question q
                    left join odiseo.configuration_alternative ca on q.config_alternative_id = ca.id
                    LEFT JOIN odiseo.course c ON q.course_id = c.id
                    LEFT JOIN odiseo.employee_didi_question edq ON edq.question_id = q.id
                    LEFT JOIN odiseo.employee_didi_question_image edqi ON edqi.employee_didi_question_id = edq.id
                WHERE  q.id = p_question_id
                GROUP BY
                    q.id,
                    q.description,
                    q.number,
                    q.parent_id,
                    ca."columns",
                    c.code,
                    c.name,
                    q.answer_id,
                    alternatives,
                    question_image,
                    edq.theory_base,
                    edq.data_unknown,
                    edq."development ",
                    edq.url_file_digitalized_solution,
                    edq.answer;
            END;
            $$;


ALTER FUNCTION odiseo.fn_find_approved_question_for_word_download(p_question_id integer) OWNER TO postgres;

