--
-- Name: fn_find_cycle(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_cycle(f_cycle_id bigint, f_company_id bigint) RETURNS TABLE(id bigint, code character varying, description character varying, created_by text, created_at timestamp without time zone, year smallint, month smallint, weeks smallint, start_date date, end_date date, active boolean, days smallint, type_template_id bigint, cycle_type_id bigint, weeks_data jsonb)
    LANGUAGE plpgsql
    AS $$
                        BEGIN
                            RETURN QUERY
                            WITH tbl_cycle AS (
                                SELECT
                                    c.id,
                                    c.code,
                                    c.description,
                                    CASE
                                        WHEN e.first_name IS NOT NULL AND e.first_surname IS NOT NULL THEN
                                            CONCAT(initcap(split_part(e.first_name, ' ', 1)), ' ', upper(left(e.first_surname, 1)), '. ', initcap(e.second_surname))
                                        ELSE
                                            NULL
                                    END AS created_by,
                                    c.created_at,
                                    c.year,
                                    c.month,
                                    c.weeks,
                                    c.start_date,
                                    c.end_date,
                                    c.active,
                                    c.days,
                                    c.type_template_id,
                                    c.cycle_type_id,
                                    COALESCE((
                                        SELECT json_agg(json_build_object(
                                            'id', wk.id,
                                            'week', wk.week,
                                            'type_week_id', wk.type_week_id,
                                            'type_week_name', tw.description,
                                            'start_date', wk.start_date,
                                            'end_date', wk.end_date,
                                            'cycle_id', wk.cycle_id,
                                            'color', tw.color
                                        ) ORDER BY wk.start_date)
                                        FROM cycle_weeks wk
                                        LEFT JOIN type_week tw ON wk.type_week_id = tw.id
                                        WHERE wk.cycle_id = c.id
                                        AND wk.fl_status = true
                                    ), '[]')::JSONB AS weeks_data
                                FROM cycle c
                                LEFT JOIN users u ON c.created_by = u.id
                                LEFT JOIN employees e ON u.id = e.user_id
                                WHERE c.fl_status = true
                                    AND c.id = f_cycle_id
                                    AND c.company_id = f_company_id
                                GROUP BY
                                    c.id,
                                    c.code,
                                    c.description,
                                    e.first_name,
                                    e.first_surname,
                                    e.second_surname,
                                    c.created_at,
                                    c.year,
                                    c.month,
                                    c.weeks,
                                    c.start_date,
                                    c.end_date,
                                    c.active,
                                    c.days,
                                    c.type_template_id
                            )
                            SELECT * FROM tbl_cycle;
                        END;
                        $$;


ALTER FUNCTION odiseo.fn_find_cycle(f_cycle_id bigint, f_company_id bigint) OWNER TO postgres;

--
-- Name: fn_find_detail_parent_question(integer, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_detail_parent_question(p_question_id integer, p_status boolean) RETURNS TABLE(id bigint, code character varying, description text, short_description text, text_traduction text, short_text_traduction text, description_b text, short_description_b text, number_question character varying, number character varying, course_id smallint, code_course character varying, course character varying, status character varying, url_pdf character varying, observation text, similitaries text, type_text_id bigint, level_id bigint, type_text_subcategory_id bigint, subquestions jsonb, question_columns smallint, type_text_template_id smallint, type_text_template_name character varying, description_text character varying, text_attributes character varying, subquestion_attributes character varying, priority integer, category_assigned_id bigint)
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                        RETURN QUERY
                        SELECT
                            pq.id,
                            pq.code,
                            pq.description,
                            pq.short_description,
                            pq.text_traduction,
                            pq.short_text_traduction,
                            pq.description_b,
                            pq.short_description_b,
                            pq.number_question,
                            pq.number,
                            pq.course_id,
                            c.code AS code_course,
                            c.name AS course,
                            pq.status,
                            pq.url_pdf,
                            po.description  as observation,
                            po.similitaries  as similitaries,
                            pq.type_text_id,
                            pq.level_id,
                            pq.type_text_subcategory_id,
                            (SELECT jsonb_agg(
                                (SELECT to_jsonb(fnp.*)
                                FROM fn_find_question_for_previewer(q.id::integer, qs.id::integer) fnp)
                            )
                            FROM question q 
                            LEFT JOIN question_subtopic qs ON q.id = qs.question_id
                            WHERE q.parent_id = pq.id) AS subquestions,
                            pq.columns,
                            ttt.id,
                            ttt.name as type_text_template_name,
                            ttt.description_text as description_text,
                            ttt.text_attributes,
                            ttt.subquestion_attributes,
                            pq.priority,
                            cac.id as category_assigned_id 
                        FROM parent_question pq
                        LEFT JOIN parent_observation po ON pq.id = po.parent_id AND po.fl_status = true AND po.type = pq.status
                        LEFT JOIN course c ON pq.course_id = c.id
                        LEFT JOIN users u ON pq.created_by = u.id
                        LEFT JOIN type_text_templates ttt on c.type_text_template_id = ttt.id
                        LEFT JOIN course_assigned_categories cac on cac.course_id = c.id AND cac.type_text_id = pq.type_text_id AND cac.deleted_at IS NULL
                        WHERE pq.id = p_question_id
                        AND pq.fl_status = p_status
                        AND pq.deleted_at IS NULL;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_find_detail_parent_question(p_question_id integer, p_status boolean) OWNER TO postgres;

--
-- Name: fn_find_details_in_diagrammed_question(integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_details_in_diagrammed_question(p_question_id integer, p_subtopic_id integer) RETURNS TABLE(code character varying, description text, question_columns smallint, columns smallint, answer_id bigint, topic_id bigint, topic character varying, status character varying, subtopics json, images json, alternatives json, topic_code character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH context_data AS (
        SELECT
            q.id AS question_id,
            COALESCE(qsh.course_id, q.course_id) AS course_id,
            COALESCE(qsh.topic_id, q.topic_id) AS topic_id,
            qsh.subtopic_id,
            (qsh.id IS NOT NULL) AS has_share
        FROM question q
        LEFT JOIN question_shares qsh
            ON qsh.question_id = q.id
            AND qsh.subtopic_id = p_subtopic_id
            AND qsh.deleted_at IS NULL
        WHERE q.id = p_question_id
    )

    SELECT
        q.code,
        q.description,
        q.columns AS question_columns,
        ca.columns,
        q.answer_id,
        cd.topic_id::BIGINT,
        t.name AS topic,
        q.status,

        CASE
            WHEN cd.has_share THEN
                (
                    SELECT json_agg(
                        json_build_object(
                            'name', s2.name,
                            'code', s2.code
                        )
                    )
                    FROM subtopic s2
                    WHERE s2.id = cd.subtopic_id
                )
            ELSE
                COALESCE((
                    SELECT json_agg(
                        DISTINCT jsonb_build_object(
                            'name', st.name,
                            'code', st.code
                        )
                    )
                    FROM subtopic st
                    JOIN question_subtopic qst
                        ON qst.subtopic_id = st.id
                    WHERE qst.question_id = q.id
                      AND qst.fl_status = true
                      AND st.fl_status = true
                ), '[]'::json)
        END AS subtopics,

        COALESCE((
            SELECT json_agg(json_build_object(
                'id', qi.id,
                'code', qi.code,
                'extension', qi.extension,
                'image', qi.image,
                'question_id', qi.question_id
            ))
            FROM question_image qi
            WHERE qi.question_id = q.id
              AND qi.fl_status = true
        ), '[]'::json) AS images,

        COALESCE((
            SELECT json_agg(json_build_object(
                'id', alt.id,
                'description', alt.description,
                'question_id', alt.question_id,
                'value', CASE WHEN q.answer_id = alt.id THEN true ELSE false END
            ))
            FROM (
                SELECT
                    alt.id,
                    alt.description,
                    alt.question_id
                FROM alternative alt
                WHERE alt.question_id = q.id
                  AND alt.fl_status = true
                ORDER BY alt.id ASC
            ) AS alt
        ), '[]'::json) AS alternatives,

        t.code AS topic_code

    FROM context_data cd
    JOIN question q ON q.id = cd.question_id

    LEFT JOIN topic t ON t.id = cd.topic_id
    LEFT JOIN configuration_alternative ca ON q.config_alternative_id = ca.id

    WHERE q.fl_status = true
      AND q.deleted_at IS NULL;
END;
$$;


ALTER FUNCTION odiseo.fn_find_details_in_diagrammed_question(p_question_id integer, p_subtopic_id integer) OWNER TO postgres;

--
-- Name: fn_find_employee_university(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_employee_university(p_employee_id bigint) RETURNS TABLE(id bigint, code character varying, employee_id bigint, first_name character varying, first_surname character varying, second_surname character varying, document character varying, charge_id bigint, charge character varying, university_id smallint, university character varying, slug character varying)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            SELECT
                eu.id,
                e.code,
                eu.employee_id,
                e.first_name,
                e.first_surname,
                e.second_surname,
                e.document,
                e.charge_id,
                c.name AS charge,
                eu.university_id,
                u.name AS university,
                u.slug
            FROM odiseo.employee_university eu
            INNER JOIN odiseo.employees e ON eu.employee_id = e.id
            INNER JOIN odiseo.charge c ON c.id = e.charge_id
            INNER JOIN odiseo.origin_university u ON eu.university_id = u.id
            WHERE 1 = 1
            AND e.fl_status IS TRUE
            AND eu.employee_id = p_employee_id
            ORDER BY UNACCENT(u.name) ASC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_find_employee_university(p_employee_id bigint) OWNER TO postgres;

--
-- Name: fn_find_employee_user(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_employee_user(p_user_id integer) RETURNS TABLE(id bigint, uuid uuid, first_name character varying, first_surname character varying, second_surname character varying, charge_id bigint, name_charge character varying, courses jsonb)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            SELECT
                e.id AS employee_id,
                e."uuid",
                e.first_name,
                e.first_surname,
                e.second_surname,
                e.charge_id,
                c."name" AS name_charge,
                JSONB_AGG(
                    emplcour.course_id
                ) AS courses
            FROM odiseo.employees e
            LEFT JOIN odiseo.charge c ON e.charge_id = c.id
            LEFT JOIN odiseo.employee_course emplcour ON emplcour.teacher_id = e.id AND emplcour.fl_status = true
            WHERE 1 = 1
            AND e.user_id = p_user_id
            group by e.id,c.name;
        END;
        $$;


ALTER FUNCTION odiseo.fn_find_employee_user(p_user_id integer) OWNER TO postgres;

--
-- Name: fn_find_images_maths_question(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_images_maths_question(p_question_id integer) RETURNS TABLE(question_id bigint, question_maths json, alternative_maths json, didi_maths json, column_question smallint)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                WITH tbl_question_math AS (
                    SELECT 
                        qm.question_id,
                        jsonb_agg(json_build_object(
                            'id', qm.id,
                            'code', qm.code,
                            'path', qm.path,
                            'properties', qm.properties
                        ))::TEXT AS question_maths
                    FROM odiseo.question_maths qm 
                    JOIN odiseo.question q ON q.id = qm.question_id
                    WHERE 1 = 1
                    AND q.fl_status = TRUE 
                    AND q.id = p_question_id
                    AND qm.fl_status = TRUE
                    GROUP BY qm.question_id
                ), tbl_alternative_maths AS (
                    SELECT 
                        a.question_id,
                        jsonb_agg(json_build_object(
                            'id', am.id,
                            'code', am.code,
                            'path', am.path,
                            'properties', am.properties
                        ))::TEXT AS alternative_maths
                    FROM odiseo.alternative_maths am 
                    JOIN odiseo.alternative a on a.id = am.alternative_id 
                    JOIN odiseo.question q on q.id = a.question_id 
                    WHERE q.id = p_question_id
                    GROUP BY a.question_id
                ), tbl_didi_maths AS (
                    SELECT
                        edq.question_id,
                        jsonb_agg(json_build_object(
                            'id', dm.id,
                            'code', dm.code,
                            'path', dm.path,
                            'properties', dm.properties
                        ))::TEXT AS didi_maths
                    FROM odiseo.didi_maths dm 
                    LEFT JOIN odiseo.employee_didi_question_field edqf on edqf.id = dm.didi_question_id
                    LEFT JOIN odiseo.employee_didi_question edq on edq.id = edqf.employee_didi_question_id 
                    LEFT JOIN odiseo.question q on q.id = edq.question_id
                    WHERE q.id = p_question_id
                    GROUP BY edq.question_id
                ), tbl_question AS (
                    SELECT
                        q.id,
                        tqma.question_maths::JSON,
                        tam.alternative_maths::JSON,
                        tdm.didi_maths::JSON,
                        q.columns column_question
                    FROM odiseo.question q
                    LEFT JOIN tbl_question_math tqma ON tqma.question_id = q.id
                    LEFT JOIN tbl_alternative_maths tam ON tam.question_id = q.id
                    LEFT JOIN tbl_didi_maths tdm ON tdm.question_id = q.id
                    WHERE q.id = p_question_id
                )

                SELECT tq.* FROM tbl_question tq;
                END;
            $$;


ALTER FUNCTION odiseo.fn_find_images_maths_question(p_question_id integer) OWNER TO postgres;

--
-- Name: fn_find_level(integer, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_level(f_level_id integer, f_status boolean) RETURNS TABLE(id bigint, name character varying, description character varying, courses json, fl_status boolean, created_by bigint, updated_by bigint, deleted_by bigint, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone, user_name character varying, user_email odiseo.email_citext)
    LANGUAGE plpgsql
    AS $$
                        BEGIN
                            RETURN QUERY
                            SELECT
                                l.id,
                                l.name,
                                l.description,
                                CASE
                                    WHEN count(cl.id) > 0 THEN json_agg(cl.*)
                                    ELSE '[]'::json
                                END AS courses,
                                l.fl_status,
                                l.created_by,
                                l.updated_by,
                                l.deleted_by,
                                l.created_at,
                                l.updated_at,
                                l.deleted_at,
                                u.user as user_name,
                                u.email as user_email
                            FROM level l
                            LEFT JOIN users u ON l.created_by = u.id
                            LEFT JOIN (
                                SELECT cl.id, cl.level_id, cl.code, cl.course_id, c.code AS code_course, c.name
                                FROM course_level cl
                                INNER JOIN course c ON cl.course_id = c.id
                                WHERE cl.fl_status = true
                            ) cl ON l.id = cl.level_id
                            WHERE l.fl_status = f_status
                            AND l.deleted_at IS NULL
                            AND l.id = f_level_id
                            GROUP BY
                                l.id,
                                l.name,
                                l.description,
                                l.fl_status,
                                l.created_by,
                                l.updated_by,
                                l.deleted_by,
                                l.created_at,
                                l.updated_at,
                                l.deleted_at,
                                u.user,
                                u.email;
                        END;
                        $$;


ALTER FUNCTION odiseo.fn_find_level(f_level_id integer, f_status boolean) OWNER TO postgres;

--
-- Name: fn_find_material_per_period_level_limit_config(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_material_per_period_level_limit_config(p_id bigint) RETURNS TABLE(id bigint, material_per_period_id bigint, material_id bigint, type_material_id smallint, period_start_week smallint, period_end_week smallint, start_week smallint, end_week smallint, lower_level_limit smallint, upper_level_limit smallint, created_by integer, created_by_name character varying, updated_by integer, updated_by_name character varying, deleted_by integer, deleted_by_name character varying, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        mpllc.id,
        mpllc.material_per_period_id,
        mpp.material_id,
        mpp.type_material_id,
        mpp.start_week AS period_start_week,
        mpp.end_week AS period_end_week,
        mpllc.start_week,
        mpllc.end_week,
        mpllc.lower_level_limit,
        mpllc.upper_level_limit,
        mpllc.created_by,
        uc."user" AS created_by_name,
        mpllc.updated_by,
        uu."user" AS updated_by_name,
        mpllc.deleted_by,
        ud."user" AS deleted_by_name,
        mpllc.created_at,
        mpllc.updated_at,
        mpllc.deleted_at
    FROM material_per_period_level_limit_config mpllc
    JOIN material_per_period mpp ON mpp.id = mpllc.material_per_period_id
    LEFT JOIN users uc ON uc.id = mpllc.created_by
    LEFT JOIN users uu ON uu.id = mpllc.updated_by
    LEFT JOIN users ud ON ud.id = mpllc.deleted_by
    WHERE mpllc.id = p_id
      AND mpllc.deleted_at IS NULL;
END;
$$;


ALTER FUNCTION odiseo.fn_find_material_per_period_level_limit_config(p_id bigint) OWNER TO postgres;

--
-- Name: fn_find_parent_question(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_parent_question(p_parent_question_id bigint) RETURNS TABLE(subquestion jsonb, parent_id bigint, category_id bigint, category character varying, subcategory_id bigint, subcategory character varying, level_id bigint, course_id smallint)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            WITH cte_question_verified AS (
                SELECT  
                    pq.id AS parent_id,
                    q.id question_id,
                    ROW_NUMBER () OVER (
                        PARTITION BY 
                            q.parent_id, 
                            CASE 
                                WHEN q.status = 'APRB' THEN 'VERI'
                                ELSE q.status 
                            END
                    ) AS total_veri,
                    pq.type_text_id,
                    pq.type_text_subcategory_id,
                    pq.level_id,
                    pq.course_id,
                    pq.code,
                    tt.name category,
                    tts.name subcategory
                FROM parent_question pq 
                JOIN question q ON q.parent_id = pq.id
                JOIN type_text tt ON tt.id = pq.type_text_id
                JOIN type_text_subcategories tts ON tts.id = pq.type_text_subcategory_id
                WHERE q.status IN ('VERI', 'APRB')
                AND pq.status NOT IN ('ARCH', 'DUPL')
                ORDER BY pq.id
            ), cte_validate_min_verified AS (
            SELECT 
                cqv.parent_id,
                cqv.type_text_id category_id,
                cqv.type_text_subcategory_id subcategory_id,
                cqv.level_id,
                cqv.course_id,
                cqv.code,
                cqv.category,
                cqv.subcategory
            FROM cte_question_verified cqv
            WHERE cqv.total_veri >= 2
            AND cqv.type_text_id IS NOT NULL
            AND cqv.type_text_subcategory_id IS NOT NULL
            GROUP BY 
            cqv.parent_id,
            cqv.type_text_id,
            cqv.type_text_subcategory_id,
            cqv.level_id,
            cqv.course_id,
            cqv.code,
            cqv.category,
            cqv.subcategory
            ), subtopics_agg AS (
                SELECT
                    qs.question_id,
                    JSONB_AGG(JSONB_BUILD_OBJECT('id', qs.subtopic_id)) AS subtopics_json
                FROM question_subtopic qs
                WHERE qs.fl_status = true
                GROUP BY qs.question_id
            )
            SELECT
                JSONB_AGG(
                    JSONB_BUILD_OBJECT(
                        'code', q.code,
                        'question_id', q.id,
                        'topic_id', q.topic_id,
                        'course_id', q.course_id,
                        'level_id', q.level_id,
                        'subtopics', COALESCE(sa.subtopics_json, '[]'::jsonb)
                    )
                ) AS subquestion,
                cvmv.parent_id,
                cvmv.category_id,
                cvmv.category,
                cvmv.subcategory_id,
                cvmv.subcategory,
                cvmv.level_id,
                cvmv.course_id
            FROM cte_validate_min_verified cvmv
            JOIN question q ON q.parent_id = cvmv.parent_id
            LEFT JOIN subtopics_agg sa ON q.id = sa.question_id
            WHERE q.status IN ('VERI', 'APRB')
            AND cvmv.parent_id = p_parent_question_id
            GROUP BY 
                cvmv.parent_id,
                cvmv.category_id,
                cvmv.subcategory_id,
                cvmv.level_id,
                cvmv.course_id,
                cvmv.code,
                cvmv.category, 
                cvmv.subcategory;
        END;
    $$;


ALTER FUNCTION odiseo.fn_find_parent_question(p_parent_question_id bigint) OWNER TO postgres;

--
-- Name: fn_find_parent_question_detail(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_parent_question_detail(p_parent_id bigint) RETURNS TABLE(id bigint, code character varying, course_id smallint, status character varying, fl_status boolean, questions json)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    pq.id,
                    pq.code,
					pq.course_id,
                    pq.status,
                    pq.fl_status,
                    CASE
                        WHEN count(q.id) > 0 THEN json_agg(q.*)
                        ELSE '[]'::json
                    END AS questions
                FROM odiseo.parent_question pq
                LEFT JOIN (
                    SELECT q.id, q.code, q.course_id, q.status, q.parent_id, q.fl_status
                    FROM odiseo.question q
                    WHERE q.status IN ('SASI', 'DUPL')
                    AND q.fl_status IS TRUE
                ) q ON pq.id = q.parent_id
                WHERE pq.fl_status IS TRUE
                AND pq.status IN ('SASI', 'DUPL')
                AND pq.id = p_parent_id
                GROUP BY
                    pq.id,
                    pq.code,
                    pq.status,
                    pq.fl_status
                ORDER BY pq.id ASC;
            END;
            $$;


ALTER FUNCTION odiseo.fn_find_parent_question_detail(p_parent_id bigint) OWNER TO postgres;

