--
-- Name: fn_find_permission(boolean, integer, boolean, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_permission(p_administrator boolean, f_permission_id integer, f_status boolean, p_company_id integer) RETURNS TABLE(id bigint, name character varying, fl_status boolean, created_by bigint, updated_by bigint, deleted_by bigint, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone, module character varying, fl_administrator boolean, roles json, user_name character varying, user_email odiseo.email_citext)
    LANGUAGE plpgsql
    AS $$
                        BEGIN

                            RETURN QUERY
                            SELECT
                                p.id,
                                p.name,
                                p.fl_status,
                                p.created_by,
                                p.updated_by,
                                p.deleted_by,
                                p.created_at,
                                p.updated_at,
                                p.deleted_at,
                                p.module,
                                p.fl_administrator,
                                CASE
                                    WHEN count(r.id) > 0 THEN json_agg(r.*)
                                    ELSE '[]'::json
                                END AS roles,
                                u.user as user_name,
                                u.email as user_email
                            FROM permissions p
                            LEFT JOIN (
                                SELECT rp.id, rp.rol_id, rp.permission_id, rp.fl_status, rp.company_id
                                FROM roles_permissions rp
                                WHERE rp.fl_status = true
                            ) rp ON p.id = rp.permission_id AND rp.company_id = p_company_id
                            LEFT JOIN (
                                SELECT r.id, r.name, r.slug, r.fl_status, r.company_id
                                FROM roles r
                                WHERE r.fl_status = true
                            ) r ON rp.rol_id = r.id AND r.company_id = p_company_id
                            LEFT JOIN users u ON p.created_by = u.id
                            WHERE p.fl_status = f_status
                            AND p.deleted_at IS NULL
                            AND (f_permission_id IS NULL OR p.id = f_permission_id)
                            AND (p_administrator = true or p.fl_administrator = false)
                            GROUP BY
                                p.id,
                                p.name,
                                p.fl_status,
                                p.created_by,
                                p.updated_by,
                                p.deleted_by,
                                p.created_at,
                                p.updated_at,
                                p.deleted_at,
                                p.module,
                                p.fl_administrator,
                                user_name,
                                user_email
                            ORDER BY p.id ASC;
                        END;
                        $$;


ALTER FUNCTION odiseo.fn_find_permission(p_administrator boolean, f_permission_id integer, f_status boolean, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_find_permission_rol(integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_permission_rol(f_permission_id integer, f_company_id integer) RETURNS TABLE(id bigint, name character varying, fl_status boolean, created_by bigint, updated_by bigint, deleted_by bigint, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone, module character varying, fl_administrator boolean, roles json, user_name character varying, user_email odiseo.email_citext)
    LANGUAGE plpgsql
    AS $$
            BEGIN

            RETURN QUERY
            SELECT
                p.id,
                p.name,
                p.fl_status,
                p.created_by,
                p.updated_by,
                p.deleted_by,
                p.created_at,
                p.updated_at,
                p.deleted_at,
                p.module,
                p.fl_administrator,
                COALESCE(json_agg(r.*) FILTER (WHERE r.id IS NOT NULL), '[]'::json) AS roles,
                u.user as user_name,
                u.email as user_email
            FROM permissions p
            LEFT JOIN (
                SELECT rp.id, rp.rol_id, rp.permission_id, rp.fl_status, rp.company_id
                FROM roles_permissions rp
                WHERE rp.fl_status = true
            ) rp ON p.id = rp.permission_id AND rp.company_id = f_company_id
            LEFT JOIN users u ON p.created_by = u.id
            LEFT JOIN (
                SELECT r.id, r.name, r.slug, r.fl_status
                FROM roles r
                WHERE r.fl_status = true
            ) r ON rp.rol_id = r.id
            WHERE rp.rol_id = f_permission_id
            GROUP BY
                p.id,
                p.name,
                p.fl_status,
                p.created_by,
                p.updated_by,
                p.deleted_by,
                p.created_at,
                p.updated_at,
                p.deleted_at,
                p.fl_administrator,
                p.module,
                u.user,
                u.email
            ORDER BY p.id ASC;
            END;
            $$;


ALTER FUNCTION odiseo.fn_find_permission_rol(f_permission_id integer, f_company_id integer) OWNER TO postgres;

--
-- Name: fn_find_question(integer, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_question(f_question_id integer, f_status boolean) RETURNS TABLE(id bigint, code character varying, description text, short_description text, number_question character varying, number character varying, parent_id bigint, course_id smallint, code_course character varying, course character varying, topic_id smallint, code_topic character varying, topic character varying, subtopic_id smallint, code_subtopic character varying, subtopic character varying, level_id smallint, level character varying, teacher_id bigint, code_teacher character varying, first_name character varying, first_surname character varying, second_surname character varying, answer_id bigint, status character varying, fl_status boolean, observation text, similitaries text, created_by bigint, updated_by bigint, deleted_by bigint, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone, url_pdf character varying, config_alternative_id bigint, columns smallint, question_columns smallint, user_name character varying, user_email odiseo.email_citext, shared_status text)
    LANGUAGE plpgsql
    AS $$
                                    BEGIN
                                        RETURN QUERY
                                        SELECT
                                            q.id,
                                            q.code,
                                            q.description,
                                            q.short_description,
                                            q.number_question,
                                            q.number,
                                            q.parent_id,
                                            q.course_id,
                                            c.code AS code_course,
                                            c.name AS course,
                                            q.topic_id,
                                            t.code AS code_topic,
                                            t.name AS topic,
                                            s.id as subtopic_id,
                                            s.code AS code_subtopic,
                                            s.name AS subtopic,
                                            q.level_id,
                                            l.description AS level,
                                            q.teacher_id,
                                            e.code AS code_teacher,
                                            e.first_name,
                                            e.first_surname,
                                            e.second_surname,
                                            q.answer_id,
                                            q.status,
                                            q.fl_status,
                                            qo.description as observation,
                                            qo.similitaries,
                                            q.created_by,
                                            q.updated_by,
                                            q.deleted_by,
                                            q.created_at,
                                            q.updated_at,
                                            q.deleted_at,
                                            q.url_pdf,
                                            q.config_alternative_id,
                                            ca.columns,
                                            q.columns AS question_columns,
                                            u.user as user_name,
                                            u.email as user_email,
                                            get_shared_status(q.id, qs.subtopic_id) AS shared_status
                                        FROM question q
                                        LEFT JOIN course c ON q.course_id = c.id
                                        LEFT JOIN question_observation qo ON q.id = qo.question_id AND q.status = qo.type AND qo.fl_status = true
                                        LEFT JOIN topic t ON q.topic_id = t.id
                                        LEFT JOIN question_subtopic qs on qs.question_id = q.id
                                        LEFT JOIN subtopic s ON qs.subtopic_id = s.id
                                        LEFT JOIN level l ON q.level_id = l.id
                                        LEFT JOIN employees e ON q.teacher_id = e.id
                                        LEFT JOIN users u ON q.created_by = u.id
                                        LEFT JOIN configuration_alternative ca ON q.config_alternative_id = ca.id
                                        WHERE q.id = f_question_id
                                        AND q.fl_status = f_status
                                        AND q.deleted_at IS NULL;
                                    END;
                                    $$;


ALTER FUNCTION odiseo.fn_find_question(f_question_id integer, f_status boolean) OWNER TO postgres;

--
-- Name: fn_find_question_by_id(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_question_by_id(p_question_id integer) RETURNS TABLE(id bigint, question_id bigint, code character varying, number character varying, description text, answer_id bigint, column_question smallint, parent_id bigint, parent_description text, parent_description_b text, parent_traduction text, config_alternative smallint, course_id smallint, code_course character varying, course character varying, course_agreement_url character varying, area_agreement_url character varying, topic_id smallint, status character varying, url_pdf character varying, alternatives json, images json, parent_images json, question_maths json, alternative_maths json, type_question character varying)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        WITH tbl_alternative AS (
            SELECT
                a.question_id,
                jsonb_agg(
                    jsonb_build_object(
                        'id', a.id,
                        'description', a.description,
                        'created_ar', created_at
                    ) ORDER BY a.created_at ASC, a.id ASC
                ) FILTER (WHERE a.id IS NOT NULL)::TEXT AS alternatives
            FROM
                alternative AS a
            WHERE 1 = 1
            AND a.question_id = p_question_id
            AND a.fl_status = true
            GROUP BY a.question_id
        ), tbl_question_images AS (
            SELECT
                qi.question_id,
                jsonb_agg(
                    jsonb_build_object(
                        'id', qi.id,
                        'code', qi.code,
                        'image', qi.image
                    )
                ) FILTER (WHERE qi.id IS NOT NULL)::TEXT AS images
            FROM
                question_image qi
            WHERE 1 = 1
            AND qi.question_id = p_question_id
            AND qi.fl_status = true
            GROUP BY qi.question_id
        ), tbl_question_math AS (
            SELECT
                qm.question_id,
                jsonb_agg(
                    json_build_object(
                        'id', qm.id,
                        'code', qm.code,
                        'path', qm.path,
                        'properties', qm.properties
                    )
                )::TEXT AS question_maths
            FROM
                question_maths qm
            JOIN question q ON q.id = qm.question_id
            WHERE 1 = 1
            AND q.fl_status = true 
            AND q.id = p_question_id
            AND qm.fl_status = true
            GROUP BY qm.question_id
        ), tbl_alternative_math AS (
            SELECT
                a.question_id,
                jsonb_agg(
                    json_build_object(
                        'id', am.id,
                        'code', am.code,
                        'path', am.path,
                        'properties', am.properties
                    )
                )::TEXT AS alternative_maths
            FROM
                alternative_maths am
            JOIN alternative a on a.id = am.alternative_id
            JOIN question q on q.id = a.question_id
            WHERE q.id = p_question_id
            GROUP BY a.question_id
        ), tbl_parent_img AS (
            SELECT
                q.id,
                pq.description AS parent_description,
                pq.text_traduction AS parent_traduction,
                pq.description_b AS parent_description_b,
                jsonb_agg(
                    jsonb_build_object(
                        'id', pi2.id,
                        'code', pi2.code,
                        'image', pi2.image
                    )
                ) FILTER (WHERE pi2.id IS NOT NULL AND pi2.fl_status = TRUE)::TEXT AS parent_images
            FROM
                parent_question pq
            LEFT JOIN parent_image pi2 ON pi2.parent_id = pq.id AND pi2.fl_status = TRUE
            LEFT JOIN question q ON q.parent_id = pq.id
            WHERE q.id = p_question_id
            AND pq.fl_status = TRUE
            GROUP BY q.id, pq.description, pq.text_traduction, pq.description_b
        )

        SELECT
            q.id AS id,
            q.id AS question_id,
            q.code,
            q.number,
            q.description,
            q.answer_id,
            q.columns AS column_question,
            q.parent_id,
            tbl_pi.parent_description::text,
            tbl_pi.parent_description_b::text,
            tbl_pi.parent_traduction::text,
            ca.columns AS config_alternative,
            c.id AS course_id,
            c.code AS code_course,
            c.name AS course,
            c.agreement_url as course_agreement_url,
            a.agreement_url as area_agreement_url,
            q.topic_id,
            q.status,
            q.url_pdf,
            -- Alternativas
            COALESCE(tbl_a.alternatives::JSON, '[]'::JSON) AS alternatives,
            -- Imágenes de la pregunta
            COALESCE(tbl_qi.images::JSON, '[]'::JSON) AS images,
            COALESCE(tbl_pi.parent_images::JSON, '[]'::JSON) AS parent_images,
            -- Maths de pregunta y alternativas
            COALESCE(tbl_qm.question_maths::JSON, '[]'::JSON) AS question_maths,
            COALESCE(tbl_am.alternative_maths::JSON, '[]'::JSON) AS alternative_maths,
            CASE WHEN q.parent_id IS NOT NULL THEN 'S'::character varying ELSE 'P'::character varying END AS type_question
        FROM
            question q
        LEFT JOIN course c ON q.course_id = c.id
        LEFT JOIN area a ON c.area_id = a.id
        LEFT JOIN configuration_alternative ca ON q.config_alternative_id = ca.id
        LEFT JOIN tbl_alternative tbl_a ON tbl_a.question_id = q.id
        LEFT JOIN tbl_question_images tbl_qi ON tbl_qi.question_id = q.id
        LEFT JOIN tbl_parent_img AS tbl_pi ON tbl_pi.id = q.id
        LEFT JOIN tbl_question_math tbl_qm ON tbl_qm.question_id = q.id
        LEFT JOIN tbl_alternative_math tbl_am ON tbl_am.question_id = q.id
        WHERE 1 = 1 
        AND q.id = p_question_id;
        END;
$$;


ALTER FUNCTION odiseo.fn_find_question_by_id(p_question_id integer) OWNER TO postgres;

--
-- Name: fn_find_question_digitalized_by_id(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_question_digitalized_by_id(p_question_id integer) RETURNS TABLE(question_id bigint, code character varying, number character varying, description text, answer_id bigint, column_question smallint, parent_id bigint, parent_description text, parent_traduction text, parent_description_b text, config_alternative smallint, code_course character varying, name_course character varying, url_file_digitalized_solution character varying, url_file_digitalized_images text, alternatives json, images json, diagrammed json, diagrammed_images json, question_maths json, alternative_maths json, didi_maths json, parent_images json)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                WITH tbl_alternative AS (
                    SELECT
                        a.question_id,
                        jsonb_agg(
                            jsonb_build_object(
                                'id', a.id,
                                'description', a.description,
                                'created_ar', created_at
                            ) ORDER BY a.created_at ASC, a.id ASC
                        ) FILTER (WHERE a.id IS NOT NULL)::TEXT AS alternatives
                    FROM
                        alternative AS a
                    WHERE 1 = 1
                    AND a.question_id = p_question_id
                    AND a.fl_status = true
                    GROUP BY a.question_id
                ), tbl_question_images AS (
                    SELECT
                        qi.question_id,
                        jsonb_agg(
                            jsonb_build_object(
                                'id', qi.id,
                                'code', qi.code,
                                'image', qi.image
                            )
                        ) FILTER (WHERE qi.id IS NOT NULL)::TEXT AS images
                    FROM
                        question_image qi
                    WHERE 1 = 1
                    AND qi.question_id = p_question_id
                    AND qi.fl_status = true
                    GROUP BY qi.question_id
                ), tbl_question_math AS (
                    SELECT
                        qm.question_id,
                        jsonb_agg(
                            json_build_object(
                                'id', qm.id,
                                'code', qm.code,
                                'path', qm.path,
                                'properties', qm.properties
                            )
                        )::TEXT AS question_maths
                    FROM
                        question_maths qm
                    JOIN question q ON q.id = qm.question_id
                    WHERE 1 = 1
                    AND q.fl_status = true 
                    AND q.id = p_question_id
                    AND qm.fl_status = true
                    GROUP BY qm.question_id
                ), tbl_alternative_math AS (
                    SELECT
                        a.question_id,
                        jsonb_agg(
                            json_build_object(
                                'id', am.id,
                                'code', am.code,
                                'path', am.path,
                                'properties', am.properties
                            )
                        )::TEXT AS alternative_maths
                    FROM
                        alternative_maths am
                    JOIN alternative a on a.id = am.alternative_id
                    JOIN question q on q.id = a.question_id
                    WHERE q.id = p_question_id
                    GROUP BY a.question_id
                ), tbl_field_diagrammed AS (
                    SELECT
                        edq.question_id,
                        jsonb_agg(
                            json_build_object(
                                'field', fd.name,
                                'value', edqf.value,
                                'created_at', edqf.created_at,
                                'position', sdc.position, 
                                'field_digrammed_id', edqf.id
                            ) ORDER BY sdc.position ASC
                        )::TEXT AS diagrammed
                    FROM employee_didi_question edq
                    LEFT JOIN employee_didi_question_field edqf ON edqf.employee_didi_question_id = edq.id
                    LEFT JOIN setting_diagrammed_courses sdc ON edqf.setting_diagrammed_course_id = sdc.id
                    LEFT JOIN field_diagrammed fd ON sdc.field_diagram_id = fd.id
                    WHERE 1 = 1
                    AND edq.fl_status IS TRUE
                    AND edqf.fl_status = true
                    AND edq.question_id = p_question_id
                    GROUP BY edq.question_id
                ), tbl_field_diagrammed_images AS (
                    SELECT
                        edq.question_id,
                        jsonb_agg(
                            jsonb_build_object(
                                'id', edqfi.id,
                                'code', edqfi.code,
                                'image', edqfi.image
                            )
                        ) FILTER (WHERE edqfi.id IS NOT NULL AND edqfi.fl_status = true)::TEXT AS diagrammed_images
                    FROM employee_didi_question edq
                    LEFT JOIN employee_didi_question_field_image edqfi ON edqfi.employee_didi_question_id = edq.id
                    WHERE 1 = 1
                      AND edq.fl_status IS TRUE
                      AND edqfi.fl_status = true
                      AND edq.question_id = p_question_id
                    GROUP BY edq.question_id
                ), tbl_didi_math AS (
                    SELECT
                        edq.question_id,
                        jsonb_agg(json_build_object(
                            'id', dm.id,
                            'code', dm.code,
                            'path', dm.path,
                            'properties', dm.properties
                        ))::TEXT AS didi_maths
                    FROM
                        didi_maths dm
                    LEFT JOIN employee_didi_question_field edqf on edqf.id = dm.didi_question_id
                    LEFT JOIN employee_didi_question edq on edq.id = edqf.employee_didi_question_id 
                    LEFT JOIN question q on q.id = edq.question_id
                    WHERE 1 = 1
                    AND q.id = p_question_id
                    --AND dm.fl_status = true
                    GROUP BY edq.question_id
                ), tbl_parent_img AS (
                    SELECT
                        q.id,
                        pq.description AS parent_description,
                        pq.text_traduction AS parent_traduction,
						pq.description_b AS parent_description_b,
                        jsonb_agg(
                            jsonb_build_object(
                                'id', pi2.id,
                                'code', pi2.code,
                                'image', pi2.image
                            )
                        ) FILTER (WHERE pi2.id IS NOT NULL AND pi2.fl_status = TRUE)::TEXT AS parent_images
					FROM
                        parent_question pq
					LEFT JOIN parent_image pi2 ON pi2.parent_id = pq.id AND pi2.fl_status = TRUE
					LEFT JOIN question q ON q.parent_id = pq.id
					WHERE q.id = p_question_id
					AND pq.fl_status = TRUE
					GROUP BY q.id, pq.description, pq.text_traduction, pq.description_b
                )

                SELECT
                    q.id as question_id,
                    q.code,
                    q.number,
                    q.description,
                    q.answer_id,
                    q.columns AS column_question,
                    q.parent_id,
                    tbl_pi.parent_description,
                    tbl_pi.parent_traduction,
					tbl_pi.parent_description_b,
                    ca.columns AS config_alternative,
                    c.code AS code_course,
                    c.name AS name_course,
                    edq.url_file_digitalized_solution,
                    edq.url_file_digitalized_images,
                    -- Alternativas
                    COALESCE(tbl_a.alternatives::JSON, '[]'::JSON) AS alternatives,
                    -- Imágenes de la pregunta
                    COALESCE(tbl_qi.images::JSON, '[]'::JSON) AS images,
                    -- Campos de diagramacion
                    COALESCE(tbl_fd.diagrammed::JSON, '[]'::JSON) AS diagrammed,
                    -- Imágenes de diagramacion
                    COALESCE(tbl_fdi.diagrammed_images::JSON, '[]'::JSON) AS diagrammed_images,
                    -- Maths de pregunta, alternativas y diagramaccion
                    COALESCE(tbl_qm.question_maths::JSON, '[]'::JSON) AS question_maths,
                    COALESCE(tbl_am.alternative_maths::JSON, '[]'::JSON) AS alternative_maths,
                    COALESCE(tbl_dm.didi_maths::JSON, '[]'::JSON) AS didi_maths,
                    COALESCE(tbl_pi.parent_images::JSON, '[]'::JSON) AS parent_images
                FROM employee_didi_question edq
                LEFT JOIN question q ON q.id = edq.question_id
                LEFT JOIN course c ON q.course_id = c.id
                LEFT JOIN configuration_alternative ca ON q.config_alternative_id = ca.id
                LEFT JOIN tbl_alternative tbl_a ON tbl_a.question_id = q.id
                LEFT JOIN tbl_question_images tbl_qi ON tbl_qi.question_id = q.id
                LEFT JOIN tbl_field_diagrammed tbl_fd ON tbl_fd.question_id = q.id
                LEFT JOIN tbl_field_diagrammed_images tbl_fdi ON tbl_fdi.question_id = q.id
                LEFT JOIN tbl_question_math tbl_qm ON tbl_qm.question_id = q.id
                LEFT JOIN tbl_alternative_math tbl_am ON tbl_am.question_id = q.id
                LEFT JOIN tbl_didi_math tbl_dm ON tbl_dm.question_id = q.id
                LEFT JOIN tbl_parent_img AS tbl_pi ON tbl_pi.id = q.id
                WHERE 1 = 1 
                AND q.id = p_question_id 
                AND edq.fl_status = true
                GROUP BY
                    q.id,
                    q.code,
                    q.number,
                    q.description,
                    q.answer_id,
                    q.columns,
                    q.parent_id,
                    tbl_pi.parent_description,
                    tbl_pi.parent_traduction,
					tbl_pi.parent_description_b,
                    ca.columns,
                    c.code,
                    c.name,
                    edq.url_file_digitalized_solution,
                    edq.url_file_digitalized_images,
                    tbl_qi.images,
                    tbl_a.alternatives,
                    tbl_fd.diagrammed,
                    tbl_fdi.diagrammed_images,
                    tbl_qm.question_maths,
                    tbl_am.alternative_maths,
                    tbl_dm.didi_maths,
                    tbl_pi.parent_images;
                END;
            $$;


ALTER FUNCTION odiseo.fn_find_question_digitalized_by_id(p_question_id integer) OWNER TO postgres;

--
-- Name: fn_find_question_digitalized_for_download(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_question_digitalized_for_download(p_question_id integer) RETURNS TABLE(question_id bigint, code character varying, description text, number character varying, parent_id bigint, config_alternative smallint, code_course character varying, name_course character varying, url_file_digitalized_solution character varying, url_file_digitalized_images text, answer_id bigint, alternatives jsonb, question_images jsonb, diagram_fields jsonb, field_images jsonb, column_question smallint)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            SELECT
                q.id as question_id,
                q.code,
                q.description,
                q.number,
                q.parent_id,
                ca."columns" AS config_alternative,
                c.code AS code_course,
                c.name AS name_course,
                edq.url_file_digitalized_solution,
                edq.url_file_digitalized_images,
                q.answer_id,
                -- Alternativas
                COALESCE(
			            jsonb_agg(
			                DISTINCT jsonb_build_object(
			                    'id_anwer', sub_a.id,
			                    'alternative_description', sub_a.description
			                )
			            )
			            FILTER (WHERE sub_a.id IS NOT NULL),
			            '[]'::jsonb
			        ) AS alternatives,

                -- Imágenes de la pregunta
                COALESCE(
                    jsonb_agg(DISTINCT jsonb_build_object('id', qi.id, 'code', qi.code, 'image', qi.image))
                    FILTER (WHERE qi.id IS NOT NULL),
                    '[]'::jsonb
                ) AS question_images,

                -- Campos de diagramar
			    COALESCE(
			        jsonb_agg(
			            DISTINCT jsonb_build_object('field', tbl_field_diagrammed.field, 'value', tbl_field_diagrammed.field_value, 'created_at', tbl_field_diagrammed.created_at, 'field_digrammed_id',tbl_field_diagrammed.id)
			        )
			        FILTER (WHERE tbl_field_diagrammed.field IS NOT NULL),
			        '[]'::jsonb
			    ) AS diagram_fields,

                -- Imágenes adicionales
                COALESCE(
                    jsonb_agg(
                        DISTINCT jsonb_build_object('id', edqfi.id, 'code', edqfi.code, 'image', edqfi.image)
                    )
                    FILTER (WHERE edqfi.id IS NOT NULL AND edqfi.fl_status = true),
                    '[]'::jsonb
                ) AS field_images,
                q.columns AS column_question
            FROM
                odiseo.employee_didi_question edq
            LEFT JOIN
                odiseo.employee_didi_question_field_image edqfi ON edqfi.employee_didi_question_id = edq.id AND edqfi.fl_status = true
	       LEFT JOIN (
	        SELECT  DISTINCT
	            edqf.employee_didi_question_id,
	            fd."name" AS field,
	            edqf.value AS field_value,
	            edqf.created_at,
	            edqf.id
	        FROM
	            odiseo.employee_didi_question_field edqf
	        LEFT JOIN
	            odiseo.setting_diagrammed_courses sdc ON edqf.setting_diagrammed_course_id = sdc.id
	        LEFT JOIN
	            odiseo.field_diagrammed fd ON sdc.field_diagram_id = fd.id
	        where edqf.fl_status = true
	        ORDER BY
	            edqf.created_at ASC, edqf.id ASC
	    ) AS tbl_field_diagrammed ON edq.id = tbl_field_diagrammed.employee_didi_question_id
            JOIN
                odiseo.question q ON q.id = edq.question_id
            LEFT JOIN
                odiseo.course c ON q.course_id = c.id
            LEFT JOIN
                odiseo.configuration_alternative ca ON q.config_alternative_id = ca.id
            LEFT JOIN (
		        SELECT *
		        FROM odiseo.alternative AS a
		        ORDER BY a.created_at ASC, a.id ASC  -- Cambia el criterio de orden si es necesario
		    ) AS sub_a ON sub_a.question_id = q.id
            LEFT JOIN
                odiseo.question_image qi ON qi.question_id = q.id

            WHERE q.id = p_question_id AND edq.fl_status = true
            GROUP BY
                q.id,
                q.code,
                q.description,
                q.number,
                q.parent_id,
                ca."columns",
                c.code,
                c.name,
                edq.url_file_digitalized_solution,
                edq.url_file_digitalized_images,
                q.answer_id;
        END;
        $$;


ALTER FUNCTION odiseo.fn_find_question_digitalized_for_download(p_question_id integer) OWNER TO postgres;

--
-- Name: fn_find_question_for_previewer(integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_question_for_previewer(p_question_id integer, p_subtopic_id integer) RETURNS TABLE(id bigint, code character varying, description text, columns smallint, config_alternative smallint, answer_id bigint, parent_id bigint, parent_description text, parent_traduction text, parent_description_b text, alternatives json, images json, parent_images json, diagrammed json, diagrammed_images json, type_question text)
    LANGUAGE plpgsql
    AS $$
                                                BEGIN
                                                    RETURN QUERY
                                                    WITH tbl_alternative AS (
                                                        SELECT
                                                            a.question_id,
                                                            jsonb_agg(
                                                                jsonb_build_object(
                                                                    'id', a.id,
                                                                    'description', a.description,
                                                                    'created_ar', created_at
                                                                ) ORDER BY a.created_at ASC, a.id ASC
                                                            ) FILTER (WHERE a.id IS NOT NULL)::TEXT AS alternatives
                                                        FROM
                                                            alternative AS a
                                                        WHERE 1 = 1
                                                        AND a.question_id = p_question_id
                                                        AND a.fl_status = true
                                                        GROUP BY a.question_id
                                                    ), tbl_question_images AS (
                                                        SELECT
                                                            qi.question_id,
                                                            jsonb_agg(
                                                                jsonb_build_object(
                                                                    'id', qi.id,
                                                                    'code', qi.code,
                                                                    'image', qi.image
                                                                )
                                                            ) FILTER (WHERE qi.id IS NOT NULL)::TEXT AS images
                                                        FROM
                                                            question_image qi
                                                        WHERE 1 = 1
                                                        AND qi.question_id = p_question_id
                                                        AND qi.fl_status = true
                                                        GROUP BY qi.question_id
                                                    ), tbl_field_diagrammed AS (
                                                        SELECT
                                                            edq.question_id,
                                                            jsonb_agg(
                                                                json_build_object(
                                                                    'field', fd.name,
                                                                    'value', edqf.value,
                                                                    'created_at', edqf.created_at,
                                                                    'position', sdc.position, 
                                                                    'field_digrammed_id', edqf.id,
                                                                    'fl_optional', sdc.fl_optional
                                                                ) ORDER BY sdc.position ASC
                                                            )::TEXT AS diagrammed
                                                        FROM
                                                            employee_didi_question edq
                                                        LEFT JOIN employee_didi_question_field edqf ON edqf.employee_didi_question_id = edq.id
                                                        LEFT JOIN setting_diagrammed_courses sdc ON edqf.setting_diagrammed_course_id = sdc.id
                                                        LEFT JOIN field_diagrammed fd ON sdc.field_diagram_id = fd.id
                                                        WHERE 1 = 1
                                                        AND edqf.fl_status = true
                                                        AND edq.question_id = p_question_id
                                                        AND edqf.value IS NOT NULL
                                                        GROUP BY edq.question_id
                                                    ), tbl_field_diagrammed_images AS (
                                                        SELECT
                                                            edq.question_id,
                                                            jsonb_agg(
                                                                jsonb_build_object(
                                                                    'id', edqfi.id, 
                                                                    'code', edqfi.code, 
                                                                    'image', edqfi.image
                                                                )
                                                            ) FILTER (WHERE edqfi.id IS NOT NULL AND edqfi.fl_status = true)::TEXT AS diagrammed_images
                                                        FROM
                                                            employee_didi_question edq
                                                        LEFT JOIN employee_didi_question_field_image edqfi ON edqfi.employee_didi_question_id = edq.id
                                                        WHERE 1 = 1
                                                        AND edq.fl_status IS TRUE
                                                        AND edqfi.fl_status = true
                                                        AND edq.question_id = p_question_id
                                                        GROUP BY edq.question_id
                                                    ), tbl_parent_img AS (
                                                        SELECT
                                                            q.id,
                                                            pq.description AS parent_description,
                                                            pq.text_traduction AS parent_traduction,
                                                            pq.description_b AS parent_description_b,
                                                            jsonb_agg(
                                                                jsonb_build_object(
                                                                    'id', pi2.id,
                                                                    'code', pi2.code,
                                                                    'image', pi2.image
                                                                )
                                                            ) FILTER (WHERE pi2.id IS NOT NULL AND pi2.fl_status = TRUE)::TEXT AS parent_images
                                                        FROM
                                                            parent_question pq
                                                        LEFT JOIN parent_image pi2 ON pi2.parent_id = pq.id AND pi2.fl_status = TRUE
                                                        LEFT JOIN question q ON q.parent_id = pq.id
                                                        WHERE q.id = p_question_id
                                                        AND pq.fl_status = TRUE
                                                        GROUP BY q.id, pq.description, pq.text_traduction, pq.description_b
                                                    )

                                                    SELECT
                                                        q.id as question_id,
                                                        COALESCE(qs.code, q.code) AS code,
                                                        q.description,
                                                        q.columns,
                                                        ca.columns AS config_alternative,
                                                        q.answer_id,
                                                        q.parent_id,
                                                        tbl_pi.parent_description,
                                                        tbl_pi.parent_traduction,
                                                        tbl_pi.parent_description_b,
                                                        -- Alternativas
                                                        COALESCE(tbl_a.alternatives::JSON, '[]'::JSON) AS altern,
                                                        -- Imágenes de la pregunta
                                                        COALESCE(tbl_qi.images::JSON, '[]'::JSON) AS images,
                                                        COALESCE(tbl_pi.parent_images::JSON, '[]'::JSON) AS parent_images,
                                                        -- Campos de diagramacion
                                                        COALESCE(tbl_fd.diagrammed::JSON, '[]'::JSON) AS diagrammed,
                                                        -- Imágenes de diagramacion
                                                        COALESCE(tbl_fdi.diagrammed_images::JSON, '[]'::JSON) AS diagrammed_images,
                                                        CASE
                                                            WHEN q.parent_id IS NULL THEN 'P'
                                                            ELSE 'S'
                                                        END AS type_question
                                                    FROM 
                                                        question q
                                                    LEFT JOIN employee_didi_question edq ON q.id = edq.question_id
                                                    LEFT JOIN configuration_alternative ca ON q.config_alternative_id = ca.id
                                                    LEFT JOIN tbl_question_images tbl_qi ON tbl_qi.question_id = q.id
                                                    LEFT JOIN tbl_alternative tbl_a ON tbl_a.question_id = q.id
                                                    LEFT JOIN tbl_field_diagrammed tbl_fd ON tbl_fd.question_id = q.id
                                                    LEFT JOIN tbl_field_diagrammed_images tbl_fdi ON tbl_fdi.question_id = q.id
                                                    LEFT JOIN tbl_parent_img AS tbl_pi ON tbl_pi.id = q.id
                                                    LEFT JOIN question_shares qs ON qs.question_id = q.id AND qs.subtopic_id = p_subtopic_id AND qs.deleted_at IS NULL
                                                    WHERE 1 = 1
                                                    AND q.id = p_question_id;
                                                END;
                                            $$;


ALTER FUNCTION odiseo.fn_find_question_for_previewer(p_question_id integer, p_subtopic_id integer) OWNER TO postgres;

--
-- Name: fn_find_question_refuzed(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_question_refuzed(p_id bigint) RETURNS TABLE(id bigint, category_rejected_id smallint, category_rejected character varying, importance_rejected_id smallint, level_importance smallint, importance character varying, observation text, images text, question_id bigint, fl_status boolean, employee_documents jsonb, board_image text, fl_board_refuzed boolean)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            SELECT
                qr.id,
                qr.category_rejected_id,
                cr.name AS category_rejected,
                qr.importance_rejected AS importance_rejected_id,
                ir.level AS level_importance,
                ir.name AS importance,
                qr.observation,
                qr.images,
                qr.question_id,
                qr.fl_status,
                tbl_employee_images.employee_documents,
                tbl_employee_images.board_image,
				tbl_employee_images.fl_refuzed as fl_board_refuzed
            FROM odiseo.question_refuzed qr
            INNER JOIN odiseo.category_rejected cr ON qr.category_rejected_id = cr.id
            INNER JOIN odiseo.importance_rejected ir ON qr.importance_rejected = ir.id
            LEFT JOIN (
            	SELECT
            		eq.question_id as question_id,
            		eq.document_solution as board_image,
            		eq.fl_refuzed as fl_refuzed,
                        COALESCE(
                        JSONB_AGG(
                            JSONB_BUILD_OBJECT(
                                'employee_question_document_id', eqd.id,
                                'employee_question_id', eqd.employee_question_id,
                                'type_archive_id', eqd.type_archive_id,
                                'document_solution', eqd.document
                            )
                        ) FILTER (WHERE eqd.id IS NOT NULL),
                        '[]'::jsonb
                    ) AS employee_documents
            	FROM odiseo.employee_question eq
            	LEFT  JOIN odiseo.employee_question_document eqd
            	on eqd.employee_question_id = eq.id  and eqd.fl_status = true
            	where eq.fl_status = true
            	group by eq.question_id,eq.document_solution, eq.fl_refuzed
            ) tbl_employee_images on tbl_employee_images.question_id = qr.question_id
            WHERE qr.fl_active IS TRUE
            AND qr.question_id = p_id
            AND qr.fl_status IS TRUE;
      END;
    $$;


ALTER FUNCTION odiseo.fn_find_question_refuzed(p_id bigint) OWNER TO postgres;

--
-- Name: fn_find_question_subtopics(integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_question_subtopics(p_question_id integer, p_subtopic_id integer) RETURNS TABLE(id bigint, code character varying, description text, short_description text, number character varying, parent_id bigint, course_id smallint, code_course character varying, course character varying, question_columns smallint, code_topic character varying, topic character varying, level_id smallint, level character varying, teacher_id bigint, code_teacher character varying, answer_id bigint, status character varying, observation text, similitaries text, url_pdf character varying, config_alternative_id bigint, columns smallint, subtopics json, images json, alternatives json, priority integer, topic_code character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH context_data AS (
        SELECT
            q.id AS question_id,
            COALESCE(qsh.course_id, q.course_id) AS course_id,
            COALESCE(qsh.topic_id, q.topic_id) AS topic_id,
            qsh.subtopic_id,
            (qsh.id IS NOT NULL) AS has_share
        FROM question q
        LEFT JOIN question_shares qsh 
            ON qsh.question_id = q.id
            AND qsh.subtopic_id = p_subtopic_id
            AND qsh.deleted_at IS NULL
        WHERE q.id = p_question_id
    )

    SELECT
        q.id,
        q.code,
        q.description,
        q.short_description,
        q.number,
        q.parent_id,

        cd.course_id::SMALLINT,
        c.code AS code_course,
        c.name AS course,

        q.columns AS question_columns,

        t.code AS code_topic,
        t.name AS topic,

        q.level_id::SMALLINT,
        l.description AS level,

        q.teacher_id,
        e.code AS code_teacher,

        q.answer_id,
        q.status,

        qo.description as observation,
        qo.similitaries,

        q.url_pdf,
        q.config_alternative_id,
        ca.columns,

        CASE 
            WHEN cd.has_share THEN
                (
                    SELECT json_agg(
                        json_build_object(
                            'name', s2.name,
                            'code', s2.code
                        )
                    )
                    FROM subtopic s2
                    WHERE s2.id = cd.subtopic_id
                )
            ELSE
                COALESCE((
                    SELECT json_agg(
                        DISTINCT jsonb_build_object(
                            'name', st.name,
                            'code', st.code
                        )
                    )
                    FROM subtopic st
                    JOIN question_subtopic qst 
                        ON qst.subtopic_id = st.id
                    WHERE qst.question_id = q.id
                    AND qst.fl_status = true
                    AND st.fl_status = true
                ), '[]'::json)
        END AS subtopics,

        COALESCE((
            SELECT json_agg(json_build_object(
                'id', qi.id,
                'code', qi.code,
                'extension', qi.extension,
                'image', qi.image,
                'question_id', qi.question_id
            ))
            FROM question_image qi
            WHERE qi.question_id = q.id
            AND qi.fl_status = true
        ), '[]'::json) AS images,

        COALESCE((
            SELECT json_agg(json_build_object(
                'id', alt.id,
                'description', alt.description,
                'question_id', alt.question_id,
                'value', CASE WHEN q.answer_id = alt.id THEN true ELSE false END
            ))
            FROM (
                SELECT 
                    alt.id,
                    alt.description,
                    alt.question_id
                FROM alternative alt
                WHERE alt.question_id = q.id
                AND alt.fl_status = true
                ORDER BY alt.id ASC
            ) AS alt
        ), '[]'::json) AS alternatives,

        q.priority,
        t.code AS topic_code

    FROM context_data cd
    JOIN question q ON q.id = cd.question_id

    LEFT JOIN course c ON c.id = cd.course_id
    LEFT JOIN topic t ON t.id = cd.topic_id
    LEFT JOIN level l ON l.id = q.level_id
    LEFT JOIN employees e ON q.teacher_id = e.id
    LEFT JOIN question_observation qo 
        ON q.id = qo.question_id 
        AND q.status = qo.type 
        AND qo.fl_status = true
    LEFT JOIN configuration_alternative ca 
        ON q.config_alternative_id = ca.id

    WHERE q.fl_status = true
    AND q.deleted_at IS NULL;

END;
$$;


ALTER FUNCTION odiseo.fn_find_question_subtopics(p_question_id integer, p_subtopic_id integer) OWNER TO postgres;

--
-- Name: fn_find_rol(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_rol(p_rol_id integer) RETURNS TABLE(id bigint, name character varying, slug character varying, description text, fl_status boolean, created_by bigint, updated_by bigint, deleted_by bigint, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone, permissions json)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    r.id,
                    r.name,
                    r.slug,
                    r.description,
                    r.fl_status,
                    r.created_by,
                    r.updated_by,
                    r.deleted_by,
                    r.created_at,
                    r.updated_at,
                    r.deleted_at,
                    CASE 
                        WHEN count(p.id) > 0 THEN json_agg(p.*)
                        ELSE '[]'::json
                    END AS permissions
                FROM odiseo.roles r
                LEFT JOIN (SELECT rp.id, rp.rol_id, rp.permission_id FROM odiseo.roles_permissions rp WHERE rp.fl_status = TRUE) rp ON r.id = rp.rol_id
                LEFT JOIN (SELECT p.id, p.name, p.fl_status FROM odiseo.permissions p WHERE p.fl_status = TRUE ORDER BY p.id) p ON rp.permission_id = p.id
                WHERE r.id = p_rol_id
                GROUP BY
                    r.id,
                    r.name,
                    r.slug,
                    r.description,
                    r.fl_status,
                    r.created_by,
                    r.updated_by,
                    r.deleted_by,
                    r.created_at,
                    r.updated_at,
                    r.deleted_at;
            END;
            $$;


ALTER FUNCTION odiseo.fn_find_rol(p_rol_id integer) OWNER TO postgres;

--
-- Name: fn_find_rol(integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_rol(p_rol_id integer, p_company_id integer) RETURNS TABLE(id bigint, name character varying, slug character varying, description text, fl_status boolean, created_by bigint, updated_by bigint, deleted_by bigint, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone, permissions json)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        SELECT
            r.id,
            r.name,
            r.slug,
            r.description,
            r.fl_status,
            r.created_by,
            r.updated_by,
            r.deleted_by,
            r.created_at,
            r.updated_at,
            r.deleted_at,
            CASE 
                WHEN count(p.id) > 0 THEN json_agg(p.*)
                ELSE '[]'::json
            END AS permissions
        FROM roles r
        LEFT JOIN (SELECT rp.id, rp.rol_id, rp.permission_id FROM roles_permissions rp WHERE rp.fl_status = TRUE) rp ON r.id = rp.rol_id
        LEFT JOIN (SELECT p.id, p.name, p.fl_status FROM permissions p WHERE p.fl_status = TRUE ORDER BY p.id) p ON rp.permission_id = p.id
        WHERE r.id = p_rol_id
        and r.company_id = p_company_id
        GROUP BY
            r.id,
            r.name,
            r.slug,
            r.description,
            r.fl_status,
            r.created_by,
            r.updated_by,
            r.deleted_by,
            r.created_at,
            r.updated_at,
            r.deleted_at;
    END;
    $$;


ALTER FUNCTION odiseo.fn_find_rol(p_rol_id integer, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_find_rol_permission(integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_rol_permission(p_rol_id integer, p_permission_id integer, p_company_id integer) RETURNS TABLE(id bigint, rol_id bigint, permission_id bigint, fl_status boolean, created_by bigint, updated_by bigint, created_at timestamp without time zone, updated_at timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        IF p_company_id IS NULL THEN
            RAISE EXCEPTION 'El parámetro p_company_id es requerido para encontrar el permiso del rol.';
        END IF;

        RETURN QUERY
        SELECT
            rp.id,
            rp.rol_id,
            rp.permission_id,
            rp.fl_status,
            rp.created_by,
            rp.updated_by,
            rp.created_at,
            rp.updated_at
        FROM roles_permissions rp
        WHERE rp.rol_id = p_rol_id
        AND rp.permission_id = p_permission_id
        AND rp.company_id = p_company_id;
    END;
    $$;


ALTER FUNCTION odiseo.fn_find_rol_permission(p_rol_id integer, p_permission_id integer, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_find_rol_user(integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_rol_user(p_user_id integer, p_company_id integer) RETURNS TABLE(id bigint, name character varying, slug character varying, fl_administrator boolean, permissions json, courses jsonb)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_can_see_all BOOLEAN;
            v_company_base BOOLEAN;
        BEGIN
            -- Verificamos si el usuario tiene el permiso 'admin.filtrar-empresas'
            SELECT EXISTS (
                SELECT 1
                FROM users_roles ur
                JOIN roles r ON ur.rol_id = r.id AND r.fl_status = TRUE
                JOIN roles_permissions rp ON r.id = rp.rol_id AND rp.fl_status = TRUE
                JOIN permissions p ON rp.permission_id = p.id AND p.fl_status = TRUE
                WHERE ur.user_id = p_user_id
                AND p.name = 'admin.filtrar-empresas'
            ) INTO v_can_see_all;

            -- Verificar si p_company_id es igual a 1 (Vonex)
            v_company_base := p_company_id = 1;

            RETURN QUERY
            WITH validate_admin_user AS (
                SELECT
                    u.id,
                    r.fl_administrator,
                    rp.permission_id
                FROM users u
                JOIN users_roles ur ON u.id = ur.user_id
                JOIN roles r ON ur.rol_id = r.id
                LEFT JOIN roles_permissions rp ON r.id = rp.rol_id
                    AND rp.permission_id = 133 -- 'admin.admin'
                WHERE u.id = p_user_id
            ), get_courses_employees AS (
                SELECT DISTINCT
                    ec.course_id
                FROM employees e
                JOIN employee_course ec ON e.id = ec.teacher_id
                WHERE e.user_id = p_user_id
                    AND ec.fl_status = true
                    AND NOT EXISTS (
                        SELECT 1
                        FROM validate_admin_user vau
                        WHERE vau.permission_id = 133
                    )

                UNION ALL

                SELECT DISTINCT
                    c.id AS course_id
                FROM course c
                WHERE c.fl_status = true
                AND EXISTS (
                        SELECT 1
                        FROM validate_admin_user vau
                        WHERE vau.permission_id = 133
                    )
            )
            SELECT
                r.id,
                r.name,
                r.slug,
                r.fl_administrator,
                COALESCE(
                    JSON_AGG(
                        JSON_BUILD_OBJECT('name', p.name)
                    ) FILTER ( -- Filtramos si el permiso es diferente de NULL, y si tiene el permiso 'admin.filtrar-empresas' o si es de Vonex para solo mostrar los permisos fl_to_use_client
                        WHERE p.id IS NOT NULL
                        AND (
                            v_can_see_all IS TRUE OR
                            v_company_base IS TRUE OR (
                                v_company_base IS FALSE AND p.fl_to_use_client IS TRUE
                            )
                        )
                    ),
                    '[]'::json
                ) AS permissions,
                gce.courses
            FROM users_roles ur
            LEFT JOIN roles r ON ur.rol_id = r.id AND r.fl_status = TRUE
            LEFT JOIN roles_permissions rp ON r.id = rp.rol_id AND rp.fl_status = TRUE
            LEFT JOIN permissions p ON rp.permission_id = p.id AND p.fl_status = TRUE
            LEFT JOIN LATERAL (
                SELECT JSONB_AGG(DISTINCT course_id) AS courses
                FROM get_courses_employees
            ) gce ON TRUE
            WHERE ur.user_id = p_user_id
            GROUP BY r.id, r.name, r.slug, r.fl_administrator, gce.courses;
        END;
        $$;


ALTER FUNCTION odiseo.fn_find_rol_user(p_user_id integer, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_find_sub_question_parent_question(integer, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_sub_question_parent_question(p_parent_question_id integer, p_status boolean) RETURNS TABLE(id bigint, code character varying, description text, short_description text, number_question character varying, number character varying, parent_id bigint, course_id smallint, code_course character varying, course character varying, topic_id smallint, code_topic character varying, topic character varying, subtopics jsonb, level_id smallint, level character varying, answer_id bigint, status character varying, fl_status boolean, observation text, similitaries text, created_by bigint, updated_by bigint, deleted_by bigint, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone, url_pdf character varying, user_name character varying, user_email odiseo.email_citext)
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                    RETURN QUERY
                    WITH subtopics_cte AS (
                        SELECT 
                            qs.question_id,
                            jsonb_agg(
                                jsonb_build_object(
                                    'id', s.id,
                                    'code', s.code,
                                    'name', s.name
                                )
                            ) subtopics
                        FROM question_subtopic qs
                        JOIN question q ON q.id = qs.question_id
                        JOIN subtopic s ON s.id = qs.subtopic_id 
                        WHERE q.parent_id = p_parent_question_id AND qs.fl_status = TRUE
                        GROUP BY qs.question_id
                    )
                    SELECT
                        q.id,
                        q.code,
                        q.description,
                        q.short_description,
                        q.number_question,
                        q.number,
                        q.parent_id,
                        q.course_id,
                        c.code AS code_course,
                        c.name AS course,
                        q.topic_id,
                        t.code AS code_topic,
                        t.name AS topic,
                        sc.subtopics,
                        q.level_id,
                        l.description AS level,
                        q.answer_id,
                        q.status,
                        q.fl_status,
                        qo.description as observation,
                        qo.similitaries,
                        q.created_by,
                        q.updated_by,
                        q.deleted_by,
                        q.created_at,
                        q.updated_at,
                        q.deleted_at,
                        q.url_pdf,
                        u.user as user_name,
                        u.email as user_email
                    FROM question q
                    LEFT JOIN course c ON q.course_id = c.id
                    LEFT JOIN question_observation qo ON q.id = qo.question_id AND q.status = qo.type
                    LEFT JOIN topic t ON q.topic_id = t.id
                    LEFT JOIN question_subtopic qs ON q.id = qs.question_id AND qs.fl_status = true
                    LEFT JOIN level l ON q.level_id = l.id
                    LEFT JOIN users u ON q.created_by = u.id
                    LEFT JOIN subtopics_cte sc ON sc.question_id = q.id
                    WHERE q.parent_id = p_parent_question_id
                    AND q.fl_status = p_status
                    AND q.deleted_at IS NULL;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_find_sub_question_parent_question(p_parent_question_id integer, p_status boolean) OWNER TO postgres;

--
-- Name: fn_find_syllabus(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_syllabus(p_syllabus_id bigint, p_company_id bigint) RETURNS TABLE(id bigint, university_id smallint, code_university character varying, slug_university character varying, university character varying, course_id bigint, apply_text_on_syllabus boolean, pseudo_course_id bigint, code_course character varying, course character varying, cycle_id bigint, code_cycle character varying, cycle character varying, weeks smallint, start_date date, end_date date, syllabus jsonb, syllabus_week_titles jsonb, cycle_template_id bigint, type_text_template_id smallint)
    LANGUAGE plpgsql
    AS $$
                    DECLARE
                        v_university_id SMALLINT;
                        v_course_id BIGINT;
                        v_pseudo_course_id BIGINT;
                    BEGIN
                        SELECT syl.university_id, syl.course_id, syl.pseudo_course_id
                        INTO v_university_id, v_course_id, v_pseudo_course_id
                        FROM syllabus syl
                        WHERE syl.id = p_syllabus_id
                        AND syl.company_id = p_company_id
                        LIMIT 1;


                        RETURN QUERY
                        WITH tbl_syllabus_all_topic AS (
                            SELECT DISTINCT
                                NULL::BIGINT AS syllabus_topic_id,
                                p_syllabus_id AS syllabus_id,
                                st.university_id,
                                st.course_id,
                                st.pseudo_course_id,
                                stt.topic_id,
                                t.code,
                                t.name
                            FROM syllabus_template st
                            INNER JOIN syllabus_template_topic stt ON st.id = stt.syllabus_template_id AND stt.fl_status IS TRUE
                            INNER JOIN topic t ON stt.topic_id = t.id AND t.fl_status = true
                            WHERE st.university_id = v_university_id
                            AND (v_course_id IS NULL OR st.course_id = v_course_id)
                            AND (v_pseudo_course_id IS NULL OR st.pseudo_course_id = v_pseudo_course_id)
                            AND st.company_id = p_company_id
                            AND st.fl_status = true
                            UNION ALL
                            SELECT DISTINCT
                                st.id AS syllabus_topic_id,
                                st.syllabus_id,
                                v_university_id AS university_id,
                                v_course_id AS course_id,
                                null::bigint AS pseudo_course_id,
                                st.topic_id,
                                t.code,
                                t.name
                            FROM syllabus_topic st
                            JOIN syllabus_template_topic stp ON stp.topic_id = st.topic_id AND stp.fl_status IS TRUE
                            INNER JOIN syllabus_topic_week stw ON st.id = stw.syllabus_topic_id AND stw.fl_status = true
                            LEFT JOIN topic t ON st.topic_id = t.id
                            WHERE st.syllabus_id = p_syllabus_id
                            AND st.company_id = p_company_id
                            AND st.fl_status = true
                        ), 
                        tbl_syllabus_topic AS (
                            SELECT *,
                                ROW_NUMBER() OVER (PARTITION BY tsat.topic_id ORDER BY syllabus_topic_id ASC NULLS LAST) AS row_num
                            FROM tbl_syllabus_all_topic tsat
                        ), 
                        tbl_syllabus_duplicate AS (
                            SELECT DISTINCT tstd.*
                            FROM tbl_syllabus_topic tstd
                            WHERE tstd.row_num = 1
                            ORDER BY tstd.code ASC
                        )
                        SELECT
                            s.id,
                            s.university_id,
                            u.code AS code_university,
                            u.slug AS slug_university,
                            u.name AS university,
                            s.course_id,
                            co.apply_text AS apply_text_on_syllabus,
                            s.pseudo_course_id,
                            CASE WHEN s.pseudo_course_id IS NULL THEN co.code ELSE pco.code END AS course_code,
                            CASE WHEN s.pseudo_course_id IS NULL THEN co.name ELSE pco.name END AS course,
                            s.cycle_id,
                            cy.code AS code_cycle,
                            cy.description AS cycle,
                            cy.weeks,
                            cy.start_date,
                            cy.end_date,
                            COALESCE(sub_topics.syllabus_json, '[]'::jsonb) AS syllabus,
                            COALESCE(sub_weeks.weeks_json, '[]'::jsonb) AS syllabus_week_titles,
                            cy.cycle_template_id,
                            co.type_text_template_id
                        FROM syllabus s
                        INNER JOIN origin_university u ON s.university_id = u.id
                        LEFT JOIN course co ON s.course_id = co.id
                        LEFT JOIN pseudo_course pco ON s.pseudo_course_id = pco.id
                        INNER JOIN cycle cy ON s.cycle_id = cy.id
                        LEFT JOIN LATERAL (
                            SELECT jsonb_agg(
                                jsonb_build_object(
                                    'id', tst.syllabus_topic_id,
                                    'syllabus_id', tst.syllabus_id,
                                    'topic_id', tst.topic_id,
                                    'code_topic', tst.code,
                                    'topic', tst.name,
                                    'weeks', ''
                                )
                            ) AS syllabus_json
                            FROM tbl_syllabus_duplicate tst
                            WHERE tst.syllabus_id = s.id
                        ) sub_topics ON true
                        LEFT JOIN LATERAL (
                            SELECT 
                                jsonb_agg(
                                    jsonb_build_object(
                                        'week_id', cw.week,
                                        'title', swt.title,
                                        'type_week', tw.description,
                                        'short_week_name', CONCAT_WS('-', cw.week, LEFT(tw.description, 1)),
                                        'week_name', CONCAT_WS('-', cw.week, tw.description),
                                        'type_week_id', tw.id
                                    ) ORDER BY cw.week
                                ) AS weeks_json
                            FROM cycle_weeks cw
                            JOIN type_week tw 
                                ON tw.id = cw.type_week_id 
                                AND tw.fl_status = true AND tw.id != 5
                            LEFT JOIN syllabus_week_titles swt 
                                ON swt.week = cw.week
                                AND swt.syllabus_id = s.id
                                AND swt.fl_status = true
                            WHERE cw.cycle_id = s.cycle_id
                            AND cw.fl_status = true
                        ) sub_weeks ON true
                        WHERE s.id = p_syllabus_id
                        AND s.company_id = p_company_id;

                    END;
                    $$;


ALTER FUNCTION odiseo.fn_find_syllabus(p_syllabus_id bigint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_find_syllabus_detail_text(integer, integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_syllabus_detail_text(p_syllabus_id integer, p_category_id integer, p_week integer, p_company_id integer) RETURNS TABLE(material_name character varying, subcategories jsonb)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                WITH base_data AS (
                    SELECT
                        tm.description AS material_name,
                        tts.name AS subcategory_name,
                        t.name AS topic_name,
                        t.id AS topic_id,
                        s2.name AS subtopic_name,
                        stc.quantity AS quantity,
                        st.position,
                        t.code topic_code,
                        s2.code subtopic_code
                    FROM syllabus s
                    JOIN syllabus_text_weeks stw ON stw.syllabus_id = s.id
                        AND stw.fl_status = TRUE
                        AND stw.company_id = p_company_id
                    JOIN syllabus_text_distributions std ON std.syllabus_text_week_id = stw.id
                        AND std.fl_status = TRUE
                        AND std.company_id = p_company_id
                    JOIN type_material tm ON tm.id = std.type_material_id
                    JOIN syllabus_texts st ON st.syllabus_text_distribution_id = std.id
                        AND st.fl_status = TRUE
                        AND st.company_id = p_company_id
                    JOIN type_text_subcategories tts ON tts.id = st.type_text_subcategory_id
                    JOIN syllabus_text_content stc ON stc.syllabus_text_id = st.id
                        AND stc.company_id = p_company_id
                    JOIN subtopic s2 ON s2.id = stc.subtopic_id
                    JOIN topic t ON t.id = s2.topic_id
                    WHERE
                        stw.week = p_week
                        AND st.type_text_id = p_category_id
                        AND s.company_id = p_company_id
                        AND s.id = p_syllabus_id
                ),
                topics_by_instance AS (
                    SELECT
                        bd.material_name,
                        bd.subcategory_name,
                        bd.position,
                        jsonb_build_object(
                            'id', bd.topic_id,
                            'name', CONCAT(bd.topic_code, ' - ', bd.topic_name),
                            'subtopics', jsonb_agg(
                                jsonb_build_object(
                                    'name', CONCAT(bd.subtopic_code, ' - ', bd.subtopic_name),
                                    'quantity', bd.quantity,
                                    'topicName', CONCAT(bd.topic_code, ' - ', bd.topic_name)
                                )
                            )
                        ) AS topic_object
                    FROM base_data bd
                    GROUP BY
                        bd.material_name,
                        bd.subcategory_name,
                        bd.position,
                        bd.topic_id,
                        bd.topic_name,
                        bd.topic_code
                ),
                instances_by_subcategory AS (
                    SELECT
                        tbi.material_name,
                        tbi.subcategory_name,
                        jsonb_build_object(
                            'name', tbi.subcategory_name || ' #' || tbi.position,
                            'topics', jsonb_agg(tbi.topic_object)
                        ) AS instance_object
                    FROM topics_by_instance tbi
                    GROUP BY
                        tbi.material_name,
                        tbi.subcategory_name,
                        tbi.position
                ),
                subcategories_by_material AS (
                    SELECT
                        ibi.material_name,
                        jsonb_build_object(
                            'name', ibi.subcategory_name,
                            'instances', jsonb_agg(ibi.instance_object ORDER BY ibi.instance_object->>'name')
                        ) AS subcategory_object
                    FROM instances_by_subcategory ibi
                    GROUP BY
                        ibi.material_name,
                        ibi.subcategory_name
                ),
                final_structure AS (
                    SELECT
                        sbm.material_name,
                        jsonb_agg(sbm.subcategory_object) AS subcategories
                    FROM subcategories_by_material sbm
                    GROUP BY
                        sbm.material_name
                ) SELECT fs.material_name, fs.subcategories as subcategories FROM final_structure as fs;

            END;
        $$;


ALTER FUNCTION odiseo.fn_find_syllabus_detail_text(p_syllabus_id integer, p_category_id integer, p_week integer, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_find_syllabus_text(bigint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_syllabus_text(p_syllabus_id bigint, p_course_id bigint, p_company_id bigint) RETURNS TABLE(category character varying, category_id integer, weeks jsonb)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY
                    WITH
                    distribution_counts AS (
                        SELECT
                            stw.week,
                            st.type_text_id category_id,
                            st.type_text_subcategory_id subcategory_id,
                            std.type_material_id,
                            COALESCE(SUM(stds.quantity), count(st.id)) AS total
                        FROM
                            syllabus_texts st
                        JOIN
                            syllabus_text_distributions std ON std.id = st.syllabus_text_distribution_id
                        JOIN
                            syllabus_text_weeks stw ON stw.id = std.syllabus_text_week_id
                        LEFT JOIN 
                            syllabus_text_detail stds ON st.id = stds.syllabus_text_id AND stds.deleted_by IS NULL
                        WHERE
                            stw.syllabus_id = p_syllabus_id
                            AND st.fl_status = true
                            AND std.fl_status = true
                            AND stw.fl_status = true
                            AND st.company_id = p_company_id
                        GROUP BY
                            stw.week, st.type_text_id, st.type_text_subcategory_id, std.type_material_id
                    ),
                    subcategories_with_distributions AS (
                        SELECT
                            dc.week,
                            dc.category_id,
                            dc.subcategory_id,
                            jsonb_agg(
                                jsonb_build_object('name', tm.description, 'total', dc.total)
                                ORDER BY tm.id
                            ) AS distributions_json
                        FROM
                            distribution_counts dc
                        JOIN
                            type_material tm ON tm.id = dc.type_material_id
                        GROUP BY
                            dc.week, dc.category_id, dc.subcategory_id
                    ),
                    weeks_with_subcategories AS (
                        SELECT
                            swd.week,
                            swd.category_id,
                            jsonb_agg(
                                jsonb_build_object(
                                    'name', tts.name,
                                    'distributions', swd.distributions_json,
                                    'id', tts.id
                                )
                                ORDER BY tts.id
                            ) AS subcategories_json
                        FROM
                            subcategories_with_distributions swd
                        JOIN
                            type_text_subcategories tts ON tts.id = swd.subcategory_id
                        GROUP BY
                            swd.week, swd.category_id
                    ),
                    course_assigned_categories_cte as (
                        SELECT 
                            cac.type_text_id, 
                            tt.name 
                        FROM course_assigned_categories cac
                        LEFT JOIN  type_text tt on tt.id = cac.type_text_id
                        WHERE cac.course_id = p_course_id
                            AND cac.deleted_at is null
                            and tt.fl_status = true
                    )
                    SELECT
                        cats.name AS category,
                        cats.type_text_id AS category_id,
                        jsonb_agg(
                            jsonb_build_object(
                                'week', all_weeks.week,
                                'subcategories', COALESCE(wws.subcategories_json, '[]'::jsonb)
                            ) ORDER BY all_weeks.week
                        ) AS weeks
                    FROM
                        (SELECT type_text_id, name FROM course_assigned_categories_cte) AS cats
                    CROSS JOIN
                        (SELECT generate_series(1, (SELECT cy.weeks FROM syllabus s JOIN cycle cy ON s.cycle_id = cy.id WHERE s.id = p_syllabus_id)) AS week) AS all_weeks
                    LEFT JOIN
                        weeks_with_subcategories wws ON wws.category_id = cats.type_text_id AND wws.week = all_weeks.week
                    GROUP BY
                        cats.type_text_id, cats.name
                    ORDER BY
                        cats.type_text_id;

                END;
            $$;


ALTER FUNCTION odiseo.fn_find_syllabus_text(p_syllabus_id bigint, p_course_id bigint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_find_university_by_id(smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_university_by_id(p_id smallint) RETURNS TABLE(id smallint, code character varying, name character varying, slug character varying, type smallint, region_id smallint, region character varying, options jsonb, areas text, versions jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        u.id, u.code, u.name, u.slug, u.type, u.region_id,
        r.name AS region,
        (
            -- Subconsulta de Opciones
            SELECT COALESCE(jsonb_agg(option_data), '[]'::jsonb)
            FROM (
                -- Usamos option_id para que el frontend reciba el ID correcto
                SELECT ou.id AS id, ou.name,
                    (
                        -- Subconsulta de Modalidades
                        SELECT COALESCE(jsonb_agg(modality_data), '[]'::jsonb)
                        FROM (
                            -- Usamos modality_id para que el frontend reciba el ID correcto
                            SELECT mo.id AS id, mo.name
                            FROM modality_options mo
                            WHERE mo.option_university_id = ou.id
                                AND mo.deleted_at IS NULL
                            ORDER BY mo.id ASC
                        ) modality_data
                    ) AS modalities
                FROM option_university ou
                WHERE ou.university_id = u.id
                    AND ou.deleted_at IS NULL
                ORDER BY ou.id ASC
            ) option_data
        ) AS options,
        u.areas,
        (
            SELECT JSONB_AGG(JSONB_BUILD_OBJECT('order', e->>'order', 'version', fn_number_to_roman((e->>'version')::SMALLINT)))
            FROM JSONB_ARRAY_ELEMENTS(u.versions::JSONB) e
        ) AS versions
    FROM origin_university u
    LEFT JOIN region r ON u.region_id = r.id
    WHERE u.deleted_by IS NULL
        AND u.fl_active = true
        AND u.id = p_id;
END;
$$;


ALTER FUNCTION odiseo.fn_find_university_by_id(p_id smallint) OWNER TO postgres;

--
-- Name: fn_find_user(character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_user(p_uuid character varying) RETURNS TABLE(id bigint, uuid uuid, user_name character varying, email odiseo.email_citext, typ_document_id bigint, document character varying, employee_email odiseo.email_citext, employee_uuid uuid, employee text, first_name character varying, first_surname character varying, second_surname character varying, role_id bigint, company_id integer)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    u.id,
                    u.uuid,
                    u.user,
                    u.email,
                    e.type_document_id,
                    e.document,
                    e.email AS employee_email,
                    e.uuid AS employee_uuid,
                    CONCAT(e.first_name,' ',e.first_surname,' ',e.second_surname) AS employee,
                    e.first_name,
                    e.first_surname,
                    e.second_surname,
                    ur.rol_id AS role_id,
                    u.company_id
                FROM users u
                LEFT JOIN employees e ON u.id = e.user_id
                LEFT JOIN users_roles ur ON u.id = ur.user_id
                WHERE u.uuid = p_uuid::UUID;
            END;
            $$;


ALTER FUNCTION odiseo.fn_find_user(p_uuid character varying) OWNER TO postgres;

--
-- Name: fn_find_weeks_type_material(smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_find_weeks_type_material(p_type_material_id smallint, p_week smallint) RETURNS TABLE(id bigint, type_material_id smallint, week smallint, weeks_detail text)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            WITH previous_week AS (
                SELECT COALESCE(MAX(tmdt.week), 0) AS last_week
                FROM odiseo.type_material_detail_template tmdt
                WHERE tmdt.type_material_id = p_type_material_id
                AND tmdt.fl_status = true
                AND tmdt.week < p_week
            ), first_week AS (
                SELECT MIN(tmdt2.week) AS first_week
                FROM odiseo.type_material_detail_template tmdt2
                WHERE tmdt2.type_material_id = p_type_material_id
                AND tmdt2.fl_status = true
            )
            SELECT
                tmdt.id,
                tmdt.type_material_id,
                tmdt.week,
                STRING_AGG(gs.week::TEXT, ', ') AS weeks_detail
            FROM  odiseo.type_material_detail_template tmdt
            JOIN previous_week pw ON true
            JOIN first_week fw ON true
            JOIN LATERAL (
                SELECT generate_series(
                    CASE WHEN pw.last_week = 0 THEN 1 ELSE pw.last_week + 1 END,
                    tmdt.week
                ) AS week
            ) gs ON true
            WHERE tmdt.type_material_id = p_type_material_id
            AND tmdt.fl_status = true
            AND tmdt.week = p_week
            GROUP BY tmdt.id, tmdt.type_material_id, tmdt.week, pw.last_week, fw.first_week;
        END;
        $$;


ALTER FUNCTION odiseo.fn_find_weeks_type_material(p_type_material_id smallint, p_week smallint) OWNER TO postgres;

--
-- Name: fn_frequent_subtopics_list(bigint, integer, integer, jsonb, smallint, smallint, integer, bigint, integer, integer, character varying, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_frequent_subtopics_list(p_option_id bigint, p_start_year integer, p_end_year integer, p_areas jsonb, p_university_id smallint, p_course_id smallint, p_company_id integer, p_user_id bigint, p_perpage integer, p_npage integer, p_order_column character varying, p_order_direction character varying) RETURNS TABLE(course text, topic text, subtopic text, years jsonb, version text, frequency text, frecuency_value bigint, areas jsonb, total bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH valid_modality_options AS (
        SELECT
            mo.id,
            mo.fl_allows_mark_frequent_topic,
            ou.id as option_university_id
        FROM modality_options mo
        INNER JOIN option_university ou ON mo.option_university_id = ou.id AND ou.university_id = p_university_id
        WHERE mo.deleted_at IS NULL
        AND (
            p_option_id IS NULL
            OR ou.id = p_option_id
        )
    ),
    raw_filtered_questions AS (
        SELECT
            oq.year,
            oq.version,
            oq.areas,
            qs.subtopic_id,
            COALESCE(
                NULLIF(ou_legacy.versions, '')::jsonb,
                '[]'::jsonb
            ) AS versions
        FROM origin_question oq
        JOIN question_subtopic qs ON qs.question_id = oq.question_id AND qs.fl_status = true
        JOIN subtopic s ON s.id = qs.subtopic_id
        JOIN topic t ON t.id = s.topic_id
        LEFT JOIN modality_options mo2 ON mo2.id = oq.modality_option_id
        LEFT JOIN option_university ou2 ON ou2.id = mo2.option_university_id
        LEFT JOIN origin_university ou_legacy ON ou_legacy.id = oq.university_id
        WHERE oq.fl_status = true
          AND (
            (
                oq.modality_option_id IS NOT NULL
                AND oq.modality_option_id IN (SELECT id FROM valid_modality_options)
                AND ou2.university_id = p_university_id
            )
            OR
            (
                oq.modality_option_id IS NULL
                AND oq.university_id IS NOT NULL
                AND oq.university_id = p_university_id
                AND (p_option_id IS NULL OR p_option_id = 0)
            )
          )
          AND (p_course_id IS NULL OR t.course_id = p_course_id)
          AND (p_start_year IS NULL OR oq.year::int >= p_start_year)
          AND (p_end_year IS NULL OR oq.year::int <= p_end_year)
          AND (
            p_areas IS NULL OR p_areas = '[]'::jsonb
            OR oq.areas::jsonb ?| array(SELECT jsonb_array_elements_text(p_areas))
          )
    ),

    user_allowed_courses AS (
        SELECT DISTINCT allowed.id
        FROM fn_list_courses_user(p_user_id) allowed
        WHERE allowed.id IS NOT NULL
    ),

    enriched_subtopic_data AS (
        SELECT
            raw.subtopic_id,
            s.name::text AS subtopic_name,
            t.name::text AS topic_name,
            c.name::text AS course_name,
            raw.year::int AS exam_year,
            (raw.year::text || '-' || fn_number_to_roman(raw.version)::text) AS year_version_label,
            fn_number_to_roman(raw.version)::text AS roman_version,
            COALESCE(
                (
                    SELECT (version_item->>'order')::int
                    FROM jsonb_array_elements(raw.versions) AS version_item
                    WHERE (version_item->>'version')::int = raw.version::int
                    ORDER BY (version_item->>'order')::int ASC
                    LIMIT 1
                ),
                raw.version::int
            ) AS version_order,
            raw.areas::jsonb AS areas_json,
            s.code AS subtopic_code,
            t.code AS topic_code,
            c.code AS course_code,
            raw.versions AS versions
        FROM raw_filtered_questions raw
        JOIN subtopic s ON s.id = raw.subtopic_id
        JOIN topic t ON t.id = s.topic_id
        JOIN course c ON c.id = t.course_id
        JOIN user_allowed_courses allowed_courses ON allowed_courses.id = c.id
    ),

    subtopic_frequency_calculation AS (
        SELECT
            *,
            COUNT(*) OVER (PARTITION BY subtopic_id) AS total_occurrence_count
        FROM enriched_subtopic_data
    ),

    final_grouped_results AS (
        SELECT
            calc.course_name,
            calc.topic_name,
            calc.subtopic_name,
            (
                SELECT jsonb_agg(distinct_years.year_version_label
                    ORDER BY
                        CASE
                            WHEN p_order_column = 'year' AND p_order_direction = 'asc'
                            THEN distinct_years.exam_year
                        END ASC,
                        CASE
                            WHEN p_order_column = 'year' AND p_order_direction = 'asc'
                            THEN distinct_years.version_order
                        END ASC,
                        CASE
                            WHEN NOT (p_order_column = 'year' AND p_order_direction = 'asc')
                            THEN distinct_years.exam_year
                        END DESC,
                        CASE
                            WHEN NOT (p_order_column = 'year' AND p_order_direction = 'asc')
                            THEN distinct_years.version_order
                        END DESC
                )
                FROM (
                    SELECT DISTINCT
                        c2.exam_year,
                        c2.version_order,
                        c2.year_version_label
                    FROM subtopic_frequency_calculation c2
                    WHERE c2.subtopic_id = calc.subtopic_id
                ) AS distinct_years
            ) AS list_of_years,
            (
                SELECT distinct_years.exam_year
                FROM (
                    SELECT DISTINCT
                        c2.exam_year,
                        c2.version_order
                    FROM subtopic_frequency_calculation c2
                    WHERE c2.subtopic_id = calc.subtopic_id
                ) AS distinct_years
                ORDER BY distinct_years.exam_year ASC, distinct_years.version_order ASC
                LIMIT 1
            ) AS sort_year_asc,
            (
                SELECT distinct_years.version_order
                FROM (
                    SELECT DISTINCT
                        c2.exam_year,
                        c2.version_order
                    FROM subtopic_frequency_calculation c2
                    WHERE c2.subtopic_id = calc.subtopic_id
                ) AS distinct_years
                ORDER BY distinct_years.exam_year ASC, distinct_years.version_order ASC
                LIMIT 1
            ) AS sort_version_asc,
            (
                SELECT distinct_years.exam_year
                FROM (
                    SELECT DISTINCT
                        c2.exam_year,
                        c2.version_order
                    FROM subtopic_frequency_calculation c2
                    WHERE c2.subtopic_id = calc.subtopic_id
                ) AS distinct_years
                ORDER BY distinct_years.exam_year DESC, distinct_years.version_order DESC
                LIMIT 1
            ) AS sort_year_desc,
            (
                SELECT distinct_years.version_order
                FROM (
                    SELECT DISTINCT
                        c2.exam_year,
                        c2.version_order
                    FROM subtopic_frequency_calculation c2
                    WHERE c2.subtopic_id = calc.subtopic_id
                ) AS distinct_years
                ORDER BY distinct_years.exam_year DESC, distinct_years.version_order DESC
                LIMIT 1
            ) AS sort_version_desc,
            MAX(calc.roman_version) AS latest_version_text,
            CASE
                WHEN calc.total_occurrence_count BETWEEN 1 AND 2 THEN 'low_frequency'
                WHEN calc.total_occurrence_count BETWEEN 3 AND 4 THEN 'medium_frequency'
                ELSE 'high_frequency'
            END AS frequency_label,
            jsonb_agg(DISTINCT area_tags.item) FILTER (WHERE area_tags.item IS NOT NULL) AS list_of_areas,
            calc.total_occurrence_count,
            calc.course_code,
            calc.topic_code,
            calc.subtopic_code
        FROM subtopic_frequency_calculation calc
        LEFT JOIN LATERAL jsonb_array_elements_text(calc.areas_json) AS area_tags(item) ON TRUE
        GROUP BY 
            calc.subtopic_id,
            calc.course_name, calc.topic_name, calc.subtopic_name, 
            calc.total_occurrence_count,
            calc.course_code, calc.topic_code, calc.subtopic_code
    )

    SELECT 
        (COALESCE(final.course_code, '') || '-' || final.course_name) AS course,
        (COALESCE(final.topic_code, '') || '-' || final.topic_name) AS topic,
        (COALESCE(final.subtopic_code, '') || '-' || final.subtopic_name) AS subtopic,
        final.list_of_years AS years,
        final.latest_version_text AS version,
        final.frequency_label AS frequency,
        final.total_occurrence_count AS frecuency_value,
        final.list_of_areas AS areas,
        COUNT(*) OVER() AS total
    FROM final_grouped_results final
    ORDER BY 

    CASE 
        WHEN p_order_column = 'course' AND p_order_direction = 'asc' 
        THEN unaccent(lower(final.course_name)) 
    END ASC,
    CASE 
        WHEN p_order_column = 'course' AND p_order_direction = 'desc' 
        THEN unaccent(lower(final.course_name)) 
    END DESC,

    CASE 
        WHEN p_order_column = 'topic' AND p_order_direction = 'asc' 
        THEN unaccent(lower(final.topic_name)) 
    END ASC,
    CASE 
        WHEN p_order_column = 'topic' AND p_order_direction = 'desc' 
        THEN unaccent(lower(final.topic_name)) 
    END DESC,

    CASE 
        WHEN p_order_column = 'subtopic' AND p_order_direction = 'asc' 
        THEN unaccent(lower(final.subtopic_name)) 
    END ASC,
    CASE 
        WHEN p_order_column = 'subtopic' AND p_order_direction = 'desc' 
        THEN unaccent(lower(final.subtopic_name)) 
    END DESC,

    CASE 
        WHEN p_order_column = 'year' AND p_order_direction = 'asc' 
        THEN final.sort_year_asc
    END ASC,
    CASE 
        WHEN p_order_column = 'year' AND p_order_direction = 'asc' 
        THEN final.sort_version_asc
    END ASC,
    CASE 
        WHEN p_order_column = 'year' AND p_order_direction = 'desc' 
        THEN final.sort_year_desc
    END DESC,
    CASE 
        WHEN p_order_column = 'year' AND p_order_direction = 'desc' 
        THEN final.sort_version_desc
    END DESC,

    unaccent(lower(final.course_name)) ASC,
    unaccent(lower(final.topic_name)) ASC,
    unaccent(lower(final.subtopic_name)) ASC
    LIMIT p_perpage
    OFFSET (COALESCE(p_npage, 1) - 1) * p_perpage;

END;
$$;


ALTER FUNCTION odiseo.fn_frequent_subtopics_list(p_option_id bigint, p_start_year integer, p_end_year integer, p_areas jsonb, p_university_id smallint, p_course_id smallint, p_company_id integer, p_user_id bigint, p_perpage integer, p_npage integer, p_order_column character varying, p_order_direction character varying) OWNER TO postgres;

--
-- Name: fn_generate_code_parent_question(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_generate_code_parent_question(p_course_id bigint) RETURNS TABLE(number_question character varying, code_course character varying)
    LANGUAGE plpgsql
    AS $$
			DECLARE
				v_number VARCHAR;
				v_code VARCHAR;
            BEGIN
				SELECT code INTO v_code
				FROM odiseo.course
				WHERE id = p_course_id
				AND fl_status = true
				LIMIT 1;

				SELECT number INTO v_number
				FROM odiseo.parent_question
				WHERE course_id = p_course_id
				AND fl_status = true
				ORDER BY number DESC
				LIMIT 1;

				IF v_number IS NOT NULL THEN
					RETURN QUERY SELECT v_number, v_code;
				ELSE
					RETURN QUERY SELECT 0::VARCHAR, v_code;
				END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_generate_code_parent_question(p_course_id bigint) OWNER TO postgres;

--
-- Name: fn_generate_code_question(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_generate_code_question(p_course_id bigint) RETURNS TABLE(number_question character varying, code_course character varying)
    LANGUAGE plpgsql
    AS $$
			DECLARE
				v_number VARCHAR;
				v_code VARCHAR;
            BEGIN
				SELECT code INTO v_code
				FROM odiseo.course
				WHERE id = p_course_id
				AND fl_status = true
				LIMIT 1;

				SELECT number INTO v_number
				FROM odiseo.question
				WHERE course_id = p_course_id
				AND fl_status = true
				ORDER BY number DESC
				LIMIT 1;

				IF v_number IS NOT NULL THEN
					RETURN QUERY SELECT v_number, v_code;
				ELSE
					RETURN QUERY SELECT 0::VARCHAR, v_code;
				END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_generate_code_question(p_course_id bigint) OWNER TO postgres;

--
-- Name: fn_generate_code_teacher(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_generate_code_teacher(p_company_id bigint) RETURNS TABLE(code text)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    COALESCE(
                        LPAD((MAX(NULLIF(e.code, '')::int) + 1)::text, 3, '0'),
                        '001'
                    ) AS code
                FROM employees e
                WHERE e.charge_id = 2
                AND e.company_id = p_company_id;
            END;
            $$;


ALTER FUNCTION odiseo.fn_generate_code_teacher(p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_generate_detail_week_type_mat(bigint, smallint, smallint, smallint, boolean, boolean, smallint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_generate_detail_week_type_mat(p_material_id bigint, p_week smallint, p_type_material_id smallint, p_parent_type_material smallint, p_fl_config_level boolean, p_fl_config_type boolean, p_limit_lower_question smallint, p_limit_upper_question smallint, p_created_by bigint) RETURNS TABLE(detail_id bigint, cycle_id bigint, fl_examen boolean, name_type_material character varying, name_type_material_template character varying, process_status smallint)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_detail_id BIGINT;
            v_parent_type_material_id SMALLINT;
            v_url_solution VARCHAR;
            v_fl_process_status SMALLINT;
            v_fl_exam BOOLEAN;
            v_name_type_material VARCHAR;
            v_name_type_material_template VARCHAR;
            v_cycle_id BIGINT;
            v_fl_class_material BOOLEAN;
            v_fl_process_class_mat SMALLINT;
        BEGIN
            -- Obtener ciclo del material
            SELECT m.cycle_id INTO v_cycle_id FROM material m WHERE m.id = p_material_id LIMIT 1;

            -- Tipo de material padre
            SELECT tmp.fl_class_material INTO v_fl_class_material FROM type_material tmp WHERE tmp.id = p_parent_type_material;

            IF v_fl_class_material IS TRUE THEN
                v_fl_process_class_mat := 1::SMALLINT;
            ELSE
                v_fl_process_class_mat := 0::SMALLINT;
            END IF;

            -- Estado de examen o balotario
            SELECT tm.fl_exam, tm.description, tmt.name INTO v_fl_exam, v_name_type_material, v_name_type_material_template
            FROM type_material tm
            LEFT JOIN type_material_template tmt ON tm.type_material_template_id = tmt.id
            WHERE tm.id = p_type_material_id LIMIT 1;

            SELECT
                id, url_solution, fl_process_status
                INTO v_detail_id, v_url_solution, v_fl_process_status
            FROM detail_week_type_mat
            WHERE material_id = p_material_id AND week = p_week
            AND type_material_id = p_type_material_id AND fl_status = true LIMIT 1;

            IF v_detail_id IS NULL THEN
                IF p_type_material_id <> p_parent_type_material THEN
                    INSERT INTO detail_week_type_mat (
                        material_id,
                        week,
                        type_material_id,
                        parent_type_material_id,
                        fl_process_class_mat,
                        fl_config_level,
                        fl_config_type,
                        limit_lower_question,
                        limit_upper_question,
                        created_by,
                        created_at
                    )
                    VALUES (
                        p_material_id,
                        p_week,
                        p_type_material_id,
                        p_parent_type_material,
                        v_fl_process_class_mat,
                        p_fl_config_level,
                        p_fl_config_type,
                        p_limit_lower_question,
                        p_limit_upper_question,
                        p_created_by,
                        now()
                    )
                    RETURNING id, fl_process_status INTO v_detail_id, v_fl_process_status;
                ELSE
                    INSERT INTO detail_week_type_mat (
                        material_id,
                        week,
                        type_material_id,
                        fl_process_class_mat,
                        fl_config_level,
                        fl_config_type,
                        limit_lower_question,
                        limit_upper_question,
                        created_by,
                        created_at
                    )
                    VALUES (
                        p_material_id,
                        p_week,
                        p_type_material_id,
                        v_fl_process_class_mat,
                        p_fl_config_level,
                        p_fl_config_type,
                        p_limit_lower_question,
                        p_limit_upper_question,
                        p_created_by,
                        now()
                    )
                    RETURNING id, fl_process_status INTO v_detail_id, v_fl_process_status;
                END IF;

                RETURN QUERY SELECT v_detail_id, v_cycle_id, v_fl_exam, v_name_type_material, v_name_type_material_template, v_fl_process_status;
            ELSE
                RETURN QUERY SELECT null::BIGINT, v_cycle_id, v_fl_exam, v_name_type_material, v_name_type_material_template, v_fl_process_status;
            END IF;
        END;
        $$;


ALTER FUNCTION odiseo.fn_generate_detail_week_type_mat(p_material_id bigint, p_week smallint, p_type_material_id smallint, p_parent_type_material smallint, p_fl_config_level boolean, p_fl_config_type boolean, p_limit_lower_question smallint, p_limit_upper_question smallint, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_generate_question_code(integer, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_generate_question_code(p_course_id integer, p_category character varying) RETURNS TABLE(full_code text, number_str text)
    LANGUAGE plpgsql
    AS $$
    DECLARE
        v_course_code VARCHAR;
        v_new_correlative BIGINT;
        v_formatted_number TEXT;
        v_apply_text BOOLEAN := false;
    BEGIN

        -- Definimos si aplica texto según la categoría
        IF p_category = 'T' THEN
            v_apply_text := true;
        END IF;
        -- Si es 'P' (o 'S'), v_apply_text se mantiene en false

        SELECT code INTO v_course_code 
        FROM course 
        WHERE id = p_course_id;

        -- Bloquea la fila específica del curso Y el tipo de texto, si existe
        PERFORM id 
        FROM question_correlative
        WHERE course_id = p_course_id AND apply_text = v_apply_text
        FOR NO KEY UPDATE; -- Lock a nivel de fila

        UPDATE question_correlative
        SET correlative = correlative + 1
        WHERE course_id = p_course_id AND apply_text = v_apply_text
        RETURNING correlative INTO v_new_correlative;

        IF NOT FOUND THEN
            -- Si no existe, lo insertamos con el valor correspondiente de apply_text
            INSERT INTO question_correlative (course_id, correlative, apply_text)
            VALUES (p_course_id, 1, v_apply_text)
            RETURNING correlative INTO v_new_correlative;
        END IF;

        IF LENGTH(v_new_correlative::TEXT) < 7 THEN
            v_formatted_number := LPAD(v_new_correlative::TEXT, 7, '0');
        ELSE
            v_formatted_number := '0' || v_new_correlative::TEXT;
        END IF;

        full_code := v_course_code || '-' || v_formatted_number;
        number_str := v_formatted_number;
        
        RETURN NEXT;
    END;
    $$;


ALTER FUNCTION odiseo.fn_generate_question_code(p_course_id integer, p_category character varying) OWNER TO postgres;

--
-- Name: fn_generated_courses_class_materials(integer, integer, bigint, bigint, smallint, boolean, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_generated_courses_class_materials(p_per_page integer, p_n_page integer, p_material_id bigint, p_type_material_id bigint, p_week smallint, p_solution boolean, p_quality boolean) RETURNS TABLE(id bigint, url_resource character varying, course_id smallint, course_name character varying, fl_course_active boolean, status_id smallint, status_name character varying, status_course character varying, total bigint, resource_name text)
    LANGUAGE plpgsql
    AS $$
                DECLARE offset_val INTEGER;
                BEGIN
                    offset_val := p_per_page * (p_n_page - 1);
                    RETURN QUERY
                    WITH courses AS (
                        SELECT
                          mcw.id AS id,
                          mcw.url_material_class url_resource,
                          mcw.course_id::SMALLINT course_id,
                          c.name course_name,
                          mcw.fl_course_active,
                          mcw.fl_process_status status_id,
                          CASE
                           WHEN mcw.fl_process_status = 2 THEN 'Por generar'::VARCHAR(15)
                           WHEN mcw.fl_process_status = 3 THEN 'Completado'::VARCHAR(15)
                           WHEN mcw.fl_process_status = 4 THEN 'Generando'::VARCHAR(15)
                           WHEN mcw.fl_process_status = 5 THEN 'Error'::VARCHAR(15)
                           ELSE 'DESCONOCIDO'::VARCHAR(15)
                          END AS status_name,
                          CASE
                            WHEN mcw.fl_course_active = TRUE THEN 'Activo'::VARCHAR(15)
                            ELSE 'Inactivo'::VARCHAR(15)
                          END AS status_course,
                          COUNT(*) OVER () AS total,
                          'Material de clases (' || tm.description || ' ) ' || c.name || ' - ' || w.description AS resource_name
                        FROM odiseo.material_class_week mcw
                        LEFT JOIN odiseo.course c ON c.id = mcw.course_id
                        LEFT JOIN odiseo.type_material tm ON tm.id = mcw.type_material_id
                        LEFT JOIN odiseo.week w ON w.id = mcw.week
                        WHERE 1 = 1
                          AND mcw.material_id = p_material_id
                          AND mcw.type_material_id = p_type_material_id
                          AND mcw.week = p_week
                          AND mcw.fl_status IS TRUE
                          AND mcw.deleted_at IS NULL
                        ORDER BY mcw.id
                    )
                    SELECT
                        *
                    FROM courses cs
                    LIMIT p_per_page
                    OFFSET offset_val;
                    END;
                $$;


ALTER FUNCTION odiseo.fn_generated_courses_class_materials(p_per_page integer, p_n_page integer, p_material_id bigint, p_type_material_id bigint, p_week smallint, p_solution boolean, p_quality boolean) OWNER TO postgres;

--
-- Name: fn_generated_courses_materials(integer, integer, bigint, bigint, smallint, boolean, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_generated_courses_materials(p_per_page integer, p_n_page integer, p_material_id bigint, p_type_material_id bigint, p_week smallint, p_solution boolean, p_quality boolean) RETURNS TABLE(id bigint, url_resource character varying, course_id smallint, course_name character varying, status_id smallint, status_name character varying, status_course character varying, total bigint, resource_name text)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            offset_val INTEGER;
        BEGIN
            offset_val := p_per_page * (p_n_page - 1);
            RETURN QUERY

            WITH courses AS (
                SELECT
                    smw.id AS id,
                    smw.url_material url_resource,
                    smw.course_id::SMALLINT course_id,
                    c.name course_name,
                    smw.fl_process_status status_id,
                    CASE
                        WHEN smw.fl_process_status = 2 THEN 'Por generar'::VARCHAR(15)
                        WHEN smw.fl_process_status = 3 THEN 'Completado'::VARCHAR(15)
                        WHEN smw.fl_process_status = 4 THEN 'Generando'::VARCHAR(15)
                        WHEN smw.fl_process_status = 5 THEN 'Error'::VARCHAR(15)
                    ELSE 'Desconocido'::VARCHAR(15)
                    END AS status_name,
                    CASE
                        WHEN smw.fl_course_active = TRUE THEN 'Activo'::VARCHAR(15)
                        ELSE 'Inactivo'::VARCHAR(15)
                    END AS status_course,
                    COUNT(*) OVER () AS total,
                    tm.description || ' - ' ||
                    c.name || ' - ' ||
                    w.description || ' - ' ||
                    CASE
                        WHEN smw.fl_solution THEN 'Con solución'
                    ELSE 'Sin solución'
                    END || ' - ' ||
                    CASE
                        WHEN smw.fl_quality THEN 'Revisión'
                    ELSE 'Oficial'
                    END AS resource_name
                FROM separated_material_week smw
                LEFT JOIN course c ON c.id = smw.course_id
                LEFT JOIN type_material tm ON tm.id = smw.type_material_id
                LEFT JOIN week w ON w.id = smw.week
                WHERE 1 = 1
                    AND smw.material_id = p_material_id
                    AND smw.type_material_id = p_type_material_id
                    AND smw.week = p_week
                    AND smw.fl_status IS TRUE
                    AND smw.fl_solution = p_solution
                    AND smw.fl_quality = p_quality
                ORDER BY smw.id
            )
            SELECT
                *
            FROM courses cs
            LIMIT p_per_page
            OFFSET offset_val;
        END;
        $$;


ALTER FUNCTION odiseo.fn_generated_courses_materials(p_per_page integer, p_n_page integer, p_material_id bigint, p_type_material_id bigint, p_week smallint, p_solution boolean, p_quality boolean) OWNER TO postgres;

--
-- Name: fn_generated_courses_materials_per_period(integer, character varying, boolean, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_generated_courses_materials_per_period(p_material_per_period_ballot_id integer, p_type character varying, p_has_permission_generar_por_cursos_asignados boolean, p_employee_id integer) RETURNS TABLE(id bigint, url_resource character varying, course_id smallint, course character varying, status_name text, resource_name text)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            SELECT
                mppc.id,
                mppc.url AS url_resource,
                c.id AS course_id,
                c.name AS course,
                CASE mppc.job_status
                    WHEN 'unprocessed' THEN 'Sin procesar'
                    WHEN 'pending'     THEN 'Por generar'
                    WHEN 'processing'  THEN 'Generando'
                    WHEN 'completed'   THEN 'Completado'
                    WHEN 'failed'      THEN 'Error'
                    WHEN 'canceled'    THEN 'Cancelado'
                    ELSE 'Desconocido'
                END AS status_name,
                CONCAT_WS(' - ',
                    tm.description,
                    c.name,
                    'Semana (' || mppb.start_week || ' - ' || mppb.end_week || ')',
                    CASE mppc.type
                        WHEN 'solution'              THEN 'Con solución - Oficial'
                        WHEN 'without_solution'      THEN 'Sin solución - Oficial'
                        WHEN 'review_solution'       THEN 'Con solución - Revisión'
                        WHEN 'review_without_solution' THEN 'Sin solución - Revisión'
                    END
                ) AS resource_name
            FROM material_per_period_course mppc
            JOIN material_per_period_ballot mppb ON mppb.id = mppc.material_per_period_ballot_id
            JOIN material_per_period mpp ON mpp.id = mppb.material_per_period_id
            JOIN type_material tm ON tm.id = mpp.type_material_id
            JOIN course c ON c.id = mppc.course_id
            LEFT JOIN template_type_material_courses_order ttmco
                ON ttmco.course_id = c.id
                AND ttmco.template_type_material_id = tm.type_material_template_id
                AND ttmco.university_id IS NULL
            WHERE mppc.material_per_period_ballot_id = p_material_per_period_ballot_id
            AND mppc.type = p_type
            AND mppc.deleted_at IS NULL
            AND (
                NOT COALESCE(p_has_permission_generar_por_cursos_asignados, FALSE)
                OR EXISTS (
                    SELECT 1
                    FROM employee_course ec
                    WHERE ec.course_id = mppc.course_id
                    AND ec.teacher_id = p_employee_id
                    AND ec.fl_status = TRUE
                )
            )
            ORDER BY ttmco.position NULLS LAST;
        END;
        $$;


ALTER FUNCTION odiseo.fn_generated_courses_materials_per_period(p_material_per_period_ballot_id integer, p_type character varying, p_has_permission_generar_por_cursos_asignados boolean, p_employee_id integer) OWNER TO postgres;

--
-- Name: fn_get_all_course_by_employee_and_university(bigint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_all_course_by_employee_and_university(p_employee_id bigint, p_university_id smallint, p_company_id bigint) RETURNS TABLE(id smallint, code character varying, name character varying, course text, quantity bigint, fl_template boolean, is_pseudo boolean, apply_text boolean, type_text_template_id smallint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT DISTINCT
        c.id,
        c.code,
        c.name,
        CONCAT(c.code, ' - ', c.name) AS course,
        COALESCE(syllab_count.quantity, 0) as quantity,
        CASE
            WHEN syllab_count.quantity > 0
                THEN true
                ELSE false
        END AS fl_template,
        c.fl_pseudo_course AS is_pseudo,
        c.apply_text,
        c.type_text_template_id
    FROM course c
    LEFT JOIN employee_course ec ON ec.course_id = c.id AND ec.fl_status IS true
    LEFT JOIN (
        SELECT course_id, COUNT(*) AS quantity
        FROM syllabus_template st
        WHERE (p_university_id IS null OR st.university_id = p_university_id)
        AND st.fl_status = true
        AND st.company_id = p_company_id
        GROUP BY course_id
    ) syllab_count ON syllab_count.course_id = c.id
    WHERE 1 = 1
    AND (p_employee_id IS null OR ec.teacher_id = p_employee_id)
    AND c.fl_status = true
    ORDER BY course ASC, c.id ASC;
END;
$$;


ALTER FUNCTION odiseo.fn_get_all_course_by_employee_and_university(p_employee_id bigint, p_university_id smallint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_get_all_courses_materials(integer, integer, text); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_all_courses_materials(p_type_material_id integer, p_material_per_period_ballot_id integer, p_type_url text) RETURNS TABLE(id bigint, course_id smallint, code character varying, material_per_period_ballot_id bigint, type character varying, job_status character varying, url character varying, course_name character varying, position_order smallint)
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_template_type_material_id INT;
            BEGIN

                -- 1) Obtener template_type_material_id
                SELECT tm.type_material_template_id
                INTO v_template_type_material_id
                FROM type_material tm
                WHERE tm.id = p_type_material_id;

                -- 2) Query principal
                RETURN QUERY
                WITH base AS (
                    SELECT 
                        mppc.id,
                        mppc.course_id,
                        c.code,
                        mppc.material_per_period_ballot_id,
                        mppc.type,
                        mppc.job_status,
                        mppc.url,
                        c.name AS course_name
                    FROM material_per_period_course mppc
                    INNER JOIN course c 
                        ON c.id = mppc.course_id
                    WHERE 
                        mppc.material_per_period_ballot_id = p_material_per_period_ballot_id
                        AND mppc.type = p_type_url
                        AND mppc.job_status = 'completed'
                        AND mppc.url IS NOT NULL
                ),

                template_base AS (
                    SELECT 
                        tm.parent_id,
                        tm.type_material_template_id AS template_id,
                        parent_tm.type_material_template_id AS template_parent_id
                    FROM type_material tm
                    LEFT JOIN type_material parent_tm 
                        ON tm.parent_id = parent_tm.id
                        WHERE tm.id = p_type_material_id
                ),

                ttmco_template AS (
                    SELECT 
                        ttmco.course_id,
                        ttmco.position
                    FROM template_type_material_courses_order ttmco
                    JOIN template_base tb 
                        ON ttmco.template_type_material_id = tb.template_id
                    WHERE ttmco.university_id IS NULL
                ),

                ttmco_parent AS (
                    SELECT 
                        ttmco.course_id,
                        ttmco.position
                    FROM template_type_material_courses_order ttmco
                    JOIN template_base tb 
                        ON ttmco.template_type_material_id = tb.template_parent_id
                    WHERE ttmco.university_id IS NULL
                ),

                final_result AS (
                    SELECT 
                        b.id,
                        b.course_id,
                        b.code,
                        b.material_per_period_ballot_id,
                        b.type,
                        b.job_status,
                        b.url,
                        b.course_name,
                        COALESCE(tt.position, tp.position) AS position_order
                    FROM base b
                    LEFT JOIN ttmco_template tt
                        ON tt.course_id = b.course_id
                    LEFT JOIN ttmco_parent tp
                        ON tp.course_id = b.course_id
                )

                SELECT 
                    fr.id,
                    fr.course_id,
                    fr.code,
                    fr.material_per_period_ballot_id,
                    fr.type,
                    fr.job_status,
                    fr.url,
                    fr.course_name,
                    fr.position_order
                FROM final_result fr
                ORDER BY 
                    fr.position_order IS NULL,
                    fr.position_order ASC,
                    fr.code ASC;

                -- 3) Fallback si base no devuelve nada
                IF NOT FOUND THEN
                    RETURN QUERY
                    SELECT 
                        tmc.id,
                        tmc.course_id,
                        c.code::VARCHAR AS code,
                        NULL::BIGINT AS material_per_period_ballot_id,
                        NULL::VARCHAR AS type,
                        NULL::VARCHAR AS job_status,
                        NULL::VARCHAR AS url,
                        c.name AS course_name,
                        NULL::SMALLINT AS position_order
                    FROM type_material_course tmc
                    INNER JOIN course c 
                        ON c.id = tmc.course_id
                    WHERE tmc.type_material_id = p_type_material_id
                    ORDER BY c.code ASC;
                END IF;

            END;
            $$;


ALTER FUNCTION odiseo.fn_get_all_courses_materials(p_type_material_id integer, p_material_per_period_ballot_id integer, p_type_url text) OWNER TO postgres;

--
-- Name: fn_get_all_university_by_employee(bigint, integer, integer, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_all_university_by_employee(p_employee_id bigint, p_perpage integer, p_npage integer, p_search character varying, p_company_id bigint) RETURNS TABLE(id smallint, name text, university character varying, quantity bigint, fl_template boolean, total bigint)
    LANGUAGE plpgsql
    AS $$
    DECLARE offset_val INTEGER;
    BEGIN
        offset_val := p_perpage * (p_npage - 1);
        RETURN QUERY
        WITH universities AS (
            SELECT DISTINCT
                originuniver.id,
                CONCAT('(', originuniver.slug, ') ', originuniver.name) AS name,
                originuniver.name AS university,
                COALESCE(syllab_count.quantity, 0) AS quantity,
                CASE WHEN COALESCE(syllab_count.quantity, 0) > 0 THEN true ELSE false END AS fl_template
            FROM origin_university originuniver
            LEFT JOIN employee_university employuniver
                ON employuniver.university_id = originuniver.id
                AND employuniver.fl_status IS true
            LEFT JOIN (
                SELECT university_id, COUNT(*) AS quantity
                FROM syllabus_template
                WHERE fl_status = true
                AND company_id = p_company_id
                GROUP BY university_id
            ) syllab_count
                ON syllab_count.university_id = originuniver.id
            WHERE originuniver.deleted_by IS NULL
            AND (p_employee_id IS NULL OR employuniver.employee_id = p_employee_id)
            AND originuniver.fl_active = true
            ORDER BY fl_template DESC, university ASC, originuniver.id ASC
        ),
        counted_universities AS (
            SELECT *, COUNT(*) OVER () AS total
            FROM universities
            WHERE (p_search IS NULL OR universities.university ILIKE '%' || p_search || '%')
        )
        SELECT * FROM counted_universities
        LIMIT p_perpage OFFSET offset_val;
    END;
    $$;


ALTER FUNCTION odiseo.fn_get_all_university_by_employee(p_employee_id bigint, p_perpage integer, p_npage integer, p_search character varying, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_get_amount_levels_required_per_text(bigint, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_amount_levels_required_per_text(p_type_material_id bigint, p_course_id smallint, p_area_id smallint) RETURNS TABLE(course_id bigint, area_id smallint, level smallint, amount smallint)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    tte.course_id,
                    tte.area_id,
                    ttl.level AS level_id,
                    tte.text_amount AS amount
                FROM type_text_exam_material_configuration tte
                JOIN course c ON c.id = tte.course_id AND c.apply_text IS TRUE
                JOIN exam_material_configurations emc 
                ON 1 = 1
                AND emc.id = tte.exam_material_config_id
                AND emc.type_material_id = p_type_material_id
                JOIN type_text_level ttl ON ttl.id = tte.type_text_level_id
                WHERE 1 = 1
                AND ( p_course_id IS NULL OR tte.course_id = p_course_id )
                AND ( p_area_id IS NULL OR tte.area_id = p_area_id )
                AND tte.deleted_at IS NULL
                AND emc.deleted_at IS NULL
                AND EXISTS(
                    SELECT 1
                    FROM type_text_material_type_course_area ty
                    WHERE 1 = 1
                    AND ty.type_material_id = emc.type_material_id
                    AND ty.course_id = tte.course_id
                    AND ty.exam_area_id = tte.area_id
                    AND ty.deleted_at IS NULL
                )
                ORDER BY tte.course_id, tte.area_id ASC;
            END;
            $$;


ALTER FUNCTION odiseo.fn_get_amount_levels_required_per_text(p_type_material_id bigint, p_course_id smallint, p_area_id smallint) OWNER TO postgres;

--
-- Name: fn_get_auth_user(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_auth_user(p_user_id bigint) RETURNS TABLE(id bigint, uuid uuid, "user" character varying, email character varying, company_id integer, fl_suspended boolean, employee_id bigint, first_name character varying, first_surname character varying, second_surname character varying, document character varying, email_employee character varying, code character varying, charge_id bigint, rol_id bigint, rol character varying, courses jsonb, permissions text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH get_rol AS (
        SELECT
            r.id AS rol_id,
            r.name AS rol,
            r.fl_admin,
            r.fl_administrator,
            ur.user_id
        FROM roles r
        JOIN users_roles ur ON r.id = ur.rol_id
        WHERE ur.user_id = p_user_id
            AND ur.fl_status = true
    ), validate_admin_user AS (
		SELECT
			u.id,
			r.fl_administrator,
			rp.permission_id
		FROM users u
		JOIN users_roles ur ON u.id = ur.user_id
		JOIN roles r ON ur.rol_id = r.id
		LEFT JOIN roles_permissions rp ON r.id = rp.rol_id
			AND rp.permission_id = 133 -- 'admin.admin'
		WHERE u.id = p_user_id
	), get_courses_employees AS (
		SELECT DISTINCT
			ec.course_id
		FROM employees e
		JOIN employee_course ec ON e.id = ec.teacher_id
		WHERE e.user_id = p_user_id
			AND ec.fl_status = true
			AND NOT EXISTS (
				SELECT 1
				FROM validate_admin_user vau
				WHERE vau.permission_id = 133
			)

		UNION ALL

		SELECT DISTINCT
			c.id AS course_id
		FROM course c
		WHERE c.fl_status = true
		AND EXISTS (
            SELECT 1
            FROM validate_admin_user vau
            WHERE vau.permission_id = 133
        )
    ), get_user AS (
        SELECT
            u.id,
            u.uuid,
            u.user,
            u.email,
            u.company_id,
            u.fl_suspended,
            e.id AS employee_id,
            e.first_name,
            e.first_surname,
            e.second_surname,
            e.document,
            e.email AS email_employee,
            e.code,
            e.charge_id,
            gr.rol_id,
            gr.rol,
			gce.courses
        FROM users u
        LEFT JOIN employees e ON u.id = e.user_id
            AND e.fl_status = true
        JOIN get_rol gr ON u.id = gr.user_id
		LEFT JOIN LATERAL (
			SELECT JSONB_AGG(DISTINCT course_id) AS courses
			FROM get_courses_employees
		) gce ON TRUE
        WHERE u.id = p_user_id
    ), get_permissions AS (
        SELECT
            rp.rol_id,
            jsonb_agg(json_build_object(
                'id', p.id,
                'name', p.name,
                'fl_administrator', p.fl_administrator,
                'fl_to_use_client', p.fl_to_use_client
            ))::TEXT AS permissions
        FROM roles_permissions rp
        JOIN get_rol gr ON rp.rol_id = gr.rol_id
        JOIN permissions p ON rp.permission_id = p.id
        WHERE rp.fl_status = true
        GROUP BY rp.rol_id
    )
    SELECT
        gu.id,
        gu.uuid,
        gu.user,
        gu.email::VARCHAR,
        gu.company_id,
        gu.fl_suspended,
        gu.employee_id,
        gu.first_name,
        gu.first_surname,
        gu.second_surname,
        gu.document,
        gu.email::VARCHAR AS email_employee,
        gu.code,
        gu.charge_id,
        gu.rol_id,
        gu.rol,
		gu.courses,
        gp.permissions
    FROM get_user gu
    JOIN get_permissions gp ON gu.rol_id = gp.rol_id;
    END;
$$;


ALTER FUNCTION odiseo.fn_get_auth_user(p_user_id bigint) OWNER TO postgres;

--
-- Name: fn_get_available_missing_questions_count(); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_available_missing_questions_count() RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN (
        SELECT COUNT(id)::integer
        FROM material_missing_question_detail
        WHERE employee_id IS NULL
          AND question_id IS NULL
          AND status = 'pending'
          AND deleted_at IS NULL
    );
END;
$$;


ALTER FUNCTION odiseo.fn_get_available_missing_questions_count() OWNER TO postgres;

--
-- Name: fn_get_available_parent_question_for_exam(bigint, smallint, smallint, bigint, bigint, integer, integer, integer, integer, integer, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_available_parent_question_for_exam(p_material_id bigint, p_course_id smallint, p_week smallint, p_material_exam_area_week_id bigint, p_type_material_id bigint, p_category_id integer, p_subcategory_id integer, p_level_id integer, p_perpage integer, p_npage integer, p_search character varying) RETURNS TABLE(parent_question_id bigint, course_id smallint, level smallint, level_id bigint, category_id bigint, category_name character varying, subcategory_id bigint, subcategory_name character varying, category_position smallint, code character varying, periods smallint[], subquestion jsonb, subquestion_amount smallint, total bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    C_MORE_RECENT_USAGE SMALLINT DEFAULT 1;
    C_DEFAULT_STARTING_WEEK SMALLINT DEFAULT 1;
    C_TYPE_TWO_EXAM VARCHAR DEFAULT 'Tipo 2';
    C_TYPE_THREE_EXAM VARCHAR DEFAULT 'Tipo 3';
    offset_val INTEGER := NULL;
BEGIN
    IF p_perpage IS NOT NULL AND p_npage IS NOT NULL THEN
        offset_val := p_perpage * (p_npage - 1);
    END IF;
    RETURN QUERY
    WITH cycle_and_university AS (
        SELECT
            m.cycle_id,
            m.university_id,
            c.start_date,
            m.id AS material_id
        FROM material m
        JOIN cycle c ON c.id = m.cycle_id
        WHERE m.id = p_material_id
    ), limit_months_questions AS (
        SELECT
            limit_months_questions AS months_limit
        FROM advanced_settings
        WHERE fl_status IS TRUE
        LIMIT 1
    ), used_in_exam_parent_question_history AS (
        SELECT
            DISTINCT ON ( qeq.parent_question_id, dwtm.material_id )
            qeq.parent_question_id AS parent_question_id,
            dwtm.material_id AS material_id,
            m.cycle_id AS cycle_id,
            COALESCE( dwtm.parent_type_material_id, dwtm.type_material_id ) AS type_material_id,
            dwtm.week AS week
        FROM question_history_usage_exam_parent_question qeq
        JOIN material_exam_area_week meak ON meak.id = qeq.material_exam_area_week_id AND qeq.updated_at IS NULL 
        JOIN detail_week_type_mat dwtm ON dwtm.id = meak.week_type_material_id
        JOIN material m ON m.id = dwtm.material_id
        WHERE 1 = 1
        AND m.university_id IN ( SELECT w.university_id FROM cycle_and_university w )
    ), text_lasts_times_used_in_question_history_cycle AS (
        SELECT
            DISTINCT ON ( qh.parent_question_id, m.id )
            qh.parent_question_id AS parent_question_id,
            m.id AS material_id,
            m.cycle_id AS cycle_id,
            COALESCE( ddm.parent_type_material_id, ddm.type_material_id ) AS type_material_id,
            ddm.week AS week
        FROM question_history_cycle qh
        JOIN material m
          ON 1 = 1
         AND m.university_id IN ( SELECT cuv.university_id FROM cycle_and_university cuv )
         AND qh.fl_status IS TRUE
         AND qh.parent_question_id IS NOT NULL
         AND m.university_id = qh.university_id
         AND m.cycle_id = qh.cycle_id
         AND m.headquarte_id = qh.headquarters_id
        JOIN material_ballot_question mbq
          ON 1 = 1
         AND mbq.question_history_id =  qh.id
         AND mbq.fl_status IS TRUE
        JOIN detail_week_type_mat ddm
          ON 1 = 1
         AND ddm.id = mbq.week_type_material_id
    ), unifify_histories AS (
        SELECT * FROM used_in_exam_parent_question_history
        UNION
        SELECT * FROM text_lasts_times_used_in_question_history_cycle
    ), texts_times_used_in_university AS (
        SELECT
            uh.parent_question_id AS parent_question_id,
            ROW_NUMBER() OVER ( PARTITION BY uh.parent_question_id ORDER BY c.start_date DESC ) AS last_time_used_position,
            c.start_date AS cycle_start_date,
            uh.material_id AS material_id,
            uh.type_material_id AS type_material_id,
            uh.week AS week
        FROM unifify_histories uh
        JOIN cycle c ON uh.cycle_id = c.id
    ), text_last_time_used_per_text AS (
        SELECT
            stu.parent_question_id,
            stu.last_time_used_position,
            stu.cycle_start_date,
            stu.material_id,
            stu.type_material_id,
            stu.week
        FROM texts_times_used_in_university stu
        WHERE stu.last_time_used_position = C_MORE_RECENT_USAGE
    ), find_exam_type AS (
        SELECT
            txs.name AS exam_type_name
        FROM type_material tm
        JOIN type_material_template tmm ON tmm.id = tm.type_material_template_id AND tm.id = p_type_material_id
        JOIN type_exams txs ON txs.id = tmm.type_exam_id
    ), available_periods_weeks AS (
        SELECT
            *
        FROM fn_get_periods_weeks_on_type_material(p_type_material_id, p_week)
    ),
    syllabus_last_week AS (
        SELECT
            MAX(stw.week) AS max_week
        FROM syllabus s
        JOIN syllabus_text_weeks stw ON stw.syllabus_id = s.id
        WHERE 1 = 1
          AND s.course_id = p_course_id
          AND s.university_id IN ( SELECT university_id FROM cycle_and_university )
          AND s.cycle_id IN ( SELECT cycle_id FROM cycle_and_university )
          AND stw.fl_status IS TRUE
    ),
    syllabus_full_configuration AS (
        SELECT
            tt.id AS category_id,
            tt.name AS category_name,
            st.type_text_subcategory_id AS subcategory_id,
            sts.name AS subcategory_name,
            stc.subtopic_id AS subtopic_id,
            stp.topic_id AS topic_id,
            tt.position AS position,
            aw.period_number AS period_number,
            stw.week AS week
        FROM syllabus s
        JOIN syllabus_text_weeks stw ON stw.syllabus_id = s.id AND stw.fl_status IS TRUE
        JOIN syllabus_text_distributions std ON std.syllabus_text_week_id = stw.id AND std.fl_status IS TRUE
        JOIN type_material tm ON tm.id = std.type_material_id
        JOIN type_material_template tmt ON tmt.id = tm.type_material_template_id AND tmt.fl_use_syllabus_exam IS TRUE
        JOIN syllabus_texts st ON st.syllabus_text_distribution_id = std.id AND st.fl_status IS TRUE
        JOIN type_text_subcategories sts ON sts.id = st.type_text_subcategory_id
        JOIN syllabus_text_content stc ON stc.syllabus_text_id = st.id AND stc.fl_status IS TRUE
        JOIN type_text tt ON tt.id = st.type_text_id
        JOIN subtopic stp ON stp.id = stc.subtopic_id
        LEFT JOIN available_periods_weeks aw ON ( stw.week BETWEEN aw.starting_week AND aw.ending_week )
        WHERE 1 = 1
          AND s.university_id IN ( SELECT university_id FROM cycle_and_university )
          AND s.cycle_id IN ( SELECT cycle_id FROM cycle_and_university )
          AND s.course_id = p_course_id
          AND s.fl_status = true
          AND (
                (EXISTS( SELECT 1 FROM find_exam_type WHERE exam_type_name = 'Tipo 3' ))
                OR
                (aw.period_number IS NOT NULL)
          )
          AND (
            ( EXISTS( SELECT 1 FROM find_exam_type WHERE exam_type_name = C_TYPE_TWO_EXAM ) AND stw.week BETWEEN C_DEFAULT_STARTING_WEEK AND p_week )
            OR (EXISTS( SELECT 1 FROM find_exam_type WHERE exam_type_name = C_TYPE_THREE_EXAM ) AND stw.week BETWEEN C_DEFAULT_STARTING_WEEK AND (SELECT max_week FROM syllabus_last_week))
            OR ( NOT EXISTS( SELECT 1 FROM find_exam_type WHERE exam_type_name = C_TYPE_TWO_EXAM ) AND stw.week = p_week )
          )
    ), categories_from_syllabus AS (
        SELECT
            slf.category_id AS category_id,
            slf.category_name AS category_name,
            slf.period_number AS category_period_number,
            slf.position AS position
        FROM syllabus_full_configuration slf
        GROUP BY
            slf.category_id,
            slf.category_name,
            slf.period_number,
            slf.position
    ), subcategories_from_syllabus AS (
        SELECT
        ssc.subcategory_id AS subcategory_id,
        ssc.subcategory_name AS subcategory_name,
        ssc.period_number AS subcategory_period_number
        FROM syllabus_full_configuration ssc
        GROUP BY
            ssc.subcategory_id,
            ssc.subcategory_name,
            ssc.period_number
    ), cross_category_subcategory_same_period AS (
        SELECT
            cgf.category_id,
            cgf.category_name,
            scs.subcategory_id,
            scs.subcategory_name,
            cgf.category_period_number AS period,
            cgf.position
        FROM categories_from_syllabus cgf
        CROSS JOIN subcategories_from_syllabus scs
        WHERE 1 = 1
           AND (EXISTS( SELECT 1 FROM find_exam_type WHERE exam_type_name = 'Tipo 3' ) OR cgf.category_period_number = scs.subcategory_period_number)
    ), categories_and_subcategories_with_periods AS (
        SELECT
            cpp.category_id,
            cpp.category_name,
            cpp.subcategory_id,
            cpp.subcategory_name,
            ARRAY_AGG( DISTINCT cpp.period ORDER BY cpp.period ) AS periods,
            cpp.position
        FROM cross_category_subcategory_same_period cpp
        GROUP BY
            cpp.category_id,
            cpp.category_name,
            cpp.subcategory_id,
            cpp.subcategory_name,
            cpp.position
    ), subtopics_choosen_in_syllabus AS (
        SELECT
            sfl.subtopic_id AS subtopic_id
        FROM syllabus_full_configuration sfl
        GROUP BY sfl.subtopic_id
    ), parent_questions_in_material_exam_area_week_id AS (
        SELECT
            mpn.parent_question_id
        FROM material_exam_parent_question mpn
        WHERE 1 = 1
          AND p_material_exam_area_week_id IS NOT NULL
          AND mpn.material_exam_area_week_id = p_material_exam_area_week_id
          AND mpn.deleted_at IS NULL
          AND mpn.parent_question_id IS NOT NULL
    ), parent_questions AS (
        SELECT
            pq.id AS parent_question_id,
            pq.course_id AS course_id,
            l.name::SMALLINT AS level,
            l.id AS level_id,
            csc.category_id,
            csc.category_name,
            csc.subcategory_id,
            csc.subcategory_name,
            csc.position,
            pq.code,
            csc.periods
        FROM parent_question pq
        JOIN level l ON l.id = pq.level_id AND pq.level_id IS NOT NULL
        JOIN categories_and_subcategories_with_periods csc ON csc.category_id = pq.type_text_id AND pq.type_text_subcategory_id = csc.subcategory_id AND pq.course_id = p_course_id
        JOIN course c ON c.id = pq.course_id AND c.apply_text IS TRUE
        LEFT JOIN text_last_time_used_per_text tlt ON tlt.parent_question_id = pq.id
        LEFT JOIN cycle_and_university cau ON 1 = 1
        LEFT JOIN limit_months_questions lmq ON 1 = 1
        WHERE 1 = 1
          AND ( p_category_id IS NULL OR csc.category_id = p_category_id )
          AND ( p_subcategory_id IS NULL OR csc.subcategory_id = p_subcategory_id )
          AND ( p_level_id IS NULL OR l.name = p_level_id::VARCHAR )
          AND ( p_search IS NULL OR pq.code ILIKE '%' || p_search || '%' )
          AND pq.status NOT IN ('ARCH', 'DUPL')
          AND ( p_material_exam_area_week_id IS NULL OR pq.id NOT IN ( SELECT wi.parent_question_id FROM parent_questions_in_material_exam_area_week_id wi ) )
          AND ( tlt.last_time_used_position IS NULL
            OR ( cau.start_date >= tlt.cycle_start_date AND ( tlt.cycle_start_date >= cau.start_date - (lmq.months_limit || ' months')::INTERVAL ) )
            OR ( cau.start_date > tlt.cycle_start_date AND ( cau.start_date >= tlt.cycle_start_date - (lmq.months_limit || ' months')::INTERVAL ) )
            OR ( cau.start_date >= tlt.cycle_start_date AND ( tlt.cycle_start_date >= cau.start_date - INTERVAL '21 days' ) )
            OR ( cau.start_date < tlt.cycle_start_date AND ( cau.start_date >= tlt.cycle_start_date - INTERVAL '21 days' ) ) 
          )
    ), sub_questions AS (
        SELECT
            pss.parent_question_id,
            JSONB_AGG(
                JSONB_BUILD_OBJECT(
                    'code', q.code,
                    'question_id', q.id,
                    'topic', t.name,
                    'topic_id', q.topic_id,
                    'subtopic', stp.name,
                    'subtopic_id', sq.subtopic_id
                )
            ) AS subquestions,
            COUNT(q.*) AS subquestions_amount
        FROM parent_questions pss
        JOIN question q ON q.parent_id = pss.parent_question_id
        LEFT JOIN question_subtopic sq ON sq.question_id = q.id AND sq.fl_status IS TRUE
        LEFT JOIN subtopic stp ON stp.id = sq.subtopic_id
        LEFT JOIN topic t ON t.id = stp.topic_id
        WHERE  1 = 1
          AND sq.subtopic_id IN ( SELECT subtopic_id FROM subtopics_choosen_in_syllabus )
          AND q.status IN ('VERI', 'APRB')
        GROUP BY pss.parent_question_id
    )
    SELECT
        pqs.*,
        ssq.subquestions,
        ssq.subquestions_amount::SMALLINT AS subquestions_amount,
        COUNT(pqs.*) OVER () AS total
    FROM parent_questions pqs
    JOIN sub_questions ssq ON pqs.parent_question_id = ssq.parent_question_id
    ORDER BY ssq.subquestions_amount DESC
    LIMIT
        CASE
            WHEN p_perpage IS NOT NULL THEN p_perpage
        END
    OFFSET
        CASE
            WHEN offset_val IS NOT NULL THEN offset_val
    END;
END;
$$;


ALTER FUNCTION odiseo.fn_get_available_parent_question_for_exam(p_material_id bigint, p_course_id smallint, p_week smallint, p_material_exam_area_week_id bigint, p_type_material_id bigint, p_category_id integer, p_subcategory_id integer, p_level_id integer, p_perpage integer, p_npage integer, p_search character varying) OWNER TO postgres;

--
-- Name: fn_get_available_weeks_per_period(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_available_weeks_per_period(p_material_per_period_id bigint) RETURNS TABLE(week smallint, detail_ids jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        dwtm.week,
        JSONB_AGG(DISTINCT dwtm.id) AS detail_ids
    FROM odiseo.material_per_period_ballot mppb
    JOIN odiseo.material_per_period mpp ON mpp.id = mppb.material_per_period_id
    JOIN odiseo.type_material_detail_template tmdt
      ON 1 = 1 
     AND tmdt.type_material_id = mpp.type_material_id
     AND tmdt.fl_status IS TRUE
     AND tmdt.week BETWEEN mppb.start_week AND mppb.end_week
    JOIN odiseo.detail_week_type_mat dwtm
      ON 1 = 1
     AND (
        ( dwtm.parent_type_material_id IS NOT NULL AND dwtm.parent_type_material_id = mpp.type_material_id ) OR
        ( dwtm.type_material_id = mpp.type_material_id ) )
     AND dwtm.material_id = mpp.material_id
     AND dwtm.fl_status IS TRUE
     AND dwtm.week = tmdt.week
    WHERE mppb.id = p_material_per_period_id
    GROUP BY dwtm.week
    ORDER BY dwtm.week;
END;
$$;


ALTER FUNCTION odiseo.fn_get_available_weeks_per_period(p_material_per_period_id bigint) OWNER TO postgres;

--
-- Name: fn_get_ballot_question_single_type_material(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_ballot_question_single_type_material(p_week_type_material_id integer) RETURNS TABLE(id bigint, material_ballot_question_id bigint, question_id bigint, week_type_material_id bigint, course_id smallint, topic_id smallint, subtopic_id smallint, level_id bigint, type character varying, random boolean, "position" smallint, valid_question boolean, absolute_position smallint, topic_code character varying, subtopic_code character varying, parent_question_id bigint, type_text_id bigint, level smallint)
    LANGUAGE plpgsql
    AS $$
        
        BEGIN
                 RETURN QUERY
            WITH material_ballot_questions AS (
                SELECT
                    mbq.id,
                    mbq.id AS material_ballot_question_id,
                    COALESCE(mbq.question_id, mbq.id * -1) AS question_id,
                    mbq.week_type_material_id::bigint,
                    mbq.course_id,
                    mbq.topic_id,
                    mbq.subtopic_id,
                    mbq.level_id,
                    mbq.type,
                    mbq.random,
                    mbq.position,
                    (mbq.question_id IS NOT NULL OR mbq.parent_question_id IS NOT NULL) AS valid_question,
                    mbq.absolute_position,
                    t.code AS topic_code,
                    s.code AS subtopic_code,
                    mbq.parent_question_id,
                    mbq.type_text_id
                FROM material_ballot_question mbq
                LEFT JOIN topic t ON t.id = mbq.topic_id
                LEFT JOIN subtopic s ON s.id = mbq.subtopic_id
                WHERE mbq.fl_status IS TRUE
                  AND mbq.deleted_at IS NULL
                  AND mbq.week_type_material_id = p_week_type_material_id
            )
           	SELECT
           	    mqs.id,
           	    mqs.material_ballot_question_id,
           	    mqs.question_id,
           	    mqs.week_type_material_id,
           	    mqs.course_id,
           	    mqs.topic_id,
           	    mqs.subtopic_id,
           	    mqs.level_id,
           	    mqs.type,
           	    mqs.random,
           	    mqs.position,
           	    mqs.valid_question,
           	    mqs.absolute_position,
           	    mqs.topic_code,
           	    mqs.subtopic_code,
           	    mqs.parent_question_id,
           	    mqs.type_text_id,
           	    l.name::SMALLINT AS level
           	FROM material_ballot_questions mqs
           	LEFT JOIN level l ON l.id = mqs.level_id
           	ORDER BY
           	    mqs.course_id,
           	    mqs.topic_code ASC,
           	    mqs.subtopic_code ASC,
           	    l.name::SMALLINT ASC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_get_ballot_question_single_type_material(p_week_type_material_id integer) OWNER TO postgres;

--
-- Name: fn_get_ballot_questions(integer, integer, character varying, integer, integer, integer, integer, integer, integer, boolean, smallint, smallint, smallint, smallint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_ballot_questions(p_perpage integer, p_npage integer, p_search character varying, p_type_material_id integer, p_material_id integer, p_week integer, p_course_id integer, p_topic_id integer, p_subtopic_id integer, p_show_missing_questions boolean, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_version smallint, p_year character varying) RETURNS TABLE(question_id bigint, material_distribution_id bigint, type_material_id smallint, type_material character varying, level_searched_id bigint, columns smallint, level_used_id bigint, level_id bigint, course_id bigint, topic_id bigint, subtopic_id bigint, "position" smallint, code character varying, type character varying, config_alternative_id bigint, random boolean, valid_question boolean, course_position smallint, absolute_position smallint, status character varying, fl_is_manual boolean, added_in_completion boolean, removed_in_completion boolean, updated_at timestamp without time zone, subquestion json, type_question text, category_id bigint, category character varying, subcategory_id bigint, subcategory character varying, origin_question jsonb, level_to_be_found smallint, level smallint, course_code character varying, topic_code character varying, subtopic_code character varying, course character varying, topic character varying, subtopic character varying, course_correlative bigint, correlativo text, total bigint)
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_week_type_material JSONB;
                offset_val INTEGER;
                C_MORE_RECENT_VERSION SMALLINT DEFAULT 1;
            BEGIN
                offset_val := p_perpage * (p_npage - 1);

                SELECT JSONB_AGG(dwtm.id) INTO v_week_type_material
                FROM detail_week_type_mat dwtm
                WHERE 1 = 1
                    AND dwtm.material_id = p_material_id
                    AND dwtm.parent_type_material_id = p_type_material_id
                    AND dwtm.week = p_week
                    AND dwtm.fl_status IS TRUE;

                IF v_week_type_material IS NULL THEN
                    SELECT JSONB_AGG(dwtm.id) INTO v_week_type_material
                    FROM detail_week_type_mat dwtm
                    WHERE 1 = 1
                        AND dwtm.material_id = p_material_id
                        AND dwtm.type_material_id = p_type_material_id
                        AND dwtm.week = p_week
                        AND dwtm.fl_status IS TRUE;
                END IF;

                RETURN QUERY
                WITH template_type_material_from_parent AS (
                    SELECT
                        tmt.id AS id,
                        m.university_id
                    FROM detail_week_type_mat dtt
                    JOIN material m ON m.id = dtt.material_id
                    JOIN type_material tm ON tm.id = dtt.parent_type_material_id
                    JOIN type_material_template tmt ON tmt.id = tm.type_material_template_id
                    WHERE 1 = 1
                    AND dtt.parent_type_material_id = p_type_material_id
                    AND dtt.fl_status IS TRUE
                    AND dtt.week = p_week
                    LIMIT 1
                ), template_type_material_if_is_not_parent AS (
                    SELECT
                        tmtt.id AS id
                    FROM type_material tmm
                    JOIN type_material_template tmtt ON tmtt.id = tmm.type_material_template_id
                    WHERE 1 = 1
                    AND tmm.type_material_template_id IS NOT NULL
                    AND tmm.id = p_type_material_id
                ), courses_ordering AS (
                    SELECT
                        cor.course_id,
                        cor.position AS course_position,
                        cor.university_id
                    FROM template_type_material_courses_order cor
                    WHERE 1 = 1
                    AND deleted_at IS NULL
                        AND CASE WHEN
                            ( SELECT COUNT(*) template_type_material_from_parent ) > 0
                            THEN cor.template_type_material_id IN (SELECT id FROM template_type_material_from_parent )
                            ELSE cor.template_type_material_id IN (SELECT id FROM template_type_material_if_is_not_parent )
                        END
                        AND (
                            (
                                (SELECT ttmfp.university_id FROM template_type_material_from_parent ttmfp LIMIT 1) = 16
                                AND cor.university_id = 16 -- UNHEVAL
                            )
                            OR
                            (
                                (SELECT ttmfp.university_id FROM template_type_material_from_parent ttmfp LIMIT 1) <> 16
                                AND cor.university_id IS NULL
                            )
                        )
                ), questions_origin AS (
                    SELECT
                        oq.question_id,
                        oq.year,
                        oq.version,
                        oq.modality_id,
                        oq.option_id,
                        oq.university_id,
                        u.slug AS university_name,
                        o.name AS option_name,
                        m.name AS modality_name,
                        ROW_NUMBER() OVER ( PARTITION BY oq.question_id ORDER BY oq.year DESC, oq."version" DESC, oq.created_at DESC ) AS absolute_version
                    FROM origin_question oq
                    JOIN question ssq ON ssq.status IN ('VERI', 'APRB') AND ssq.id = oq.question_id AND oq.fl_status IS TRUE
                    LEFT JOIN origin_university u ON u.id = oq.university_id
                    LEFT JOIN option o ON o.id = oq.option_id
                    LEFT JOIN modality m ON m.id = oq.modality_id
                ), more_recent_questions_origin AS (
                    SELECT
                        qon.question_id,
                        (
                            JSONB_AGG(
                                JSONB_BUILD_ARRAY(
                                    JSONB_BUILD_OBJECT('name', qon.university_name, 'type', 'university', 'id', qon.university_id ),
                                    JSONB_BUILD_OBJECT('name', qon.option_name, 'type', 'option', 'id', qon.option_id ),
                                    JSONB_BUILD_OBJECT('name', qon.modality_name, 'type', 'modality', 'id', qon.modality_id ),
                                    JSONB_BUILD_OBJECT('name', fn_number_to_roman(qon.version), 'type', 'version', 'id', NULL ),
                                    JSONB_BUILD_OBJECT('name', qon.year, 'type', 'year', 'id', NULL )
                                )
                            )->0
                        ) AS question_origin
                    FROM questions_origin qon
                    WHERE qon.absolute_version = C_MORE_RECENT_VERSION
                    GROUP BY qon.question_id
                ), material_question_distribution AS (
                    SELECT
                        COALESCE(mbq.question_id, mbq.id * -1) AS question_id,
                        mbq.id AS material_distribution_id,
                        mbq.type_material_id,
                        tm.description AS type_material,
                        mbq.level_id AS level_searched_id,
                        q.columns AS columns,
                        mbq.usage_level_id AS level_used_id,
                        COALESCE(mbq.usage_level_id, mbq.level_id) AS level_id,
                        mbq.course_id::BIGINT AS course_id,
                        mbq.topic_id::BIGINT AS topic_id,
                        mbq.subtopic_id::BIGINT AS subtopic_id,
                        mbq.position AS "position",
                        COALESCE(q.code, pq.code) AS code,
                        COALESCE(q.type, mbq.type) AS type,
                        q.config_alternative_id,
                        mbq.random AS random,
                        (mbq.question_id IS NOT NULL OR mbq.parent_question_id IS NOT NULL) AS valid_question,
                        ccor.course_position AS course_position,
                        mbq.absolute_position AS absolute_position,
                        q.status AS status,
                        COALESCE(mbq.fl_is_manual, FALSE) AS fl_is_manual,
                        mbq.added_in_completion AS added_in_completion,
                        mbq.removed_in_completion AS removed_in_completion,
                        COALESCE(mbq.updated_at, mbq.created_at) AS updated_at,
                        (
                            SELECT
                                json_agg(
                                    jsonb_build_object(
                                        'id', mbs.id,
                                        'topic', COALESCE(t_sub.name, t_expected.name),
                                        'subtopic', COALESCE(st_sub.name, st_expected.name),
                                        'question_id', q_sub.id,
                                        'columns', q_sub.columns,
                                        'code', q_sub.code,
                                        'course', COALESCE(c_sub.name, c_expected.name),
                                        'topic_code', COALESCE(t_sub.code, t_expected.code),
                                        'subtopic_code', COALESCE(st_sub.code, st_expected.code),
                                        'course_code', COALESCE(c_sub.code, c_expected.code),
                                        'description_question', q_sub.description,
                                        'valid_question', q_sub.id IS NOT NULL,
                                        'config_alternative_id', q_sub.config_alternative_id,
                                        'origin_question', qn_sub.question_origin,
                                        'course_id', COALESCE(q_sub.course_id, mbs.course_id),
                                        'topic_id', COALESCE(q_sub.topic_id, mbs.topic_id),
                                        'subtopic_id', COALESCE(q_sub.subtopic_id, mbs.subtopic_id),
                                        'type_question', 'S',
                                        'status', mbs.state
                                    ) ORDER BY mbs.position ASC
                                )
                            FROM material_ballot_subquestions mbs
                            LEFT JOIN question q_sub ON q_sub.id = mbs.question_id
                            LEFT JOIN more_recent_questions_origin qn_sub ON qn_sub.question_id = q_sub.id
                            LEFT JOIN course c_sub ON c_sub.id = q_sub.course_id
                            LEFT JOIN topic t_sub ON t_sub.id = q_sub.topic_id
                            LEFT JOIN subtopic st_sub ON st_sub.id = q_sub.subtopic_id
                            LEFT JOIN course c_expected ON c_expected.id = mbs.course_id
                            LEFT JOIN topic t_expected ON t_expected.id = mbs.topic_id
                            LEFT JOIN subtopic st_expected ON st_expected.id = mbs.subtopic_id
                            WHERE mbs.material_ballot_question_id = mbq.id
                              AND mbs.fl_status IS TRUE
                              AND mbs.deleted_at IS NULL
                        )::json AS subquestion,
                        CASE WHEN mbq.type_text_id IS NULL THEN 'P' ELSE 'T' END AS type_question,
                        mbq.type_text_id AS category_id,
                        tt.name AS category,
                        mbq.type_text_subcategory_id AS subcategory_id,
                        tts.name AS subcategory,
                        qn.question_origin
                    FROM material_ballot_question mbq
                    LEFT JOIN question q ON q.id = mbq.question_id AND q.fl_status IS TRUE
                    LEFT JOIN more_recent_questions_origin qn ON qn.question_id = q.id
                    LEFT JOIN parent_question pq ON pq.id = mbq.parent_question_id AND pq.fl_status IS TRUE
                    INNER JOIN detail_week_type_mat dwt ON dwt.id = mbq.week_type_material_id
                    INNER JOIN type_material tm ON tm.id = dwt.type_material_id
                    LEFT JOIN courses_ordering ccor ON ccor.course_id = mbq.course_id
                    LEFT JOIN type_text tt ON tt.id = mbq.type_text_id
                    LEFT JOIN type_text_subcategories tts ON tts.id = mbq.type_text_subcategory_id
                    WHERE mbq.fl_status IS TRUE
                    AND mbq.deleted_at IS NULL
                    AND mbq.week_type_material_id IN ( SELECT value::int FROM JSONB_ARRAY_ELEMENTS_TEXT(v_week_type_material) )
                    AND mbq.week = p_week
                    AND mbq.material_id = p_material_id
                    AND ( p_university_id IS NULL OR EXISTS (
                        SELECT 1
                        FROM JSONB_ARRAY_ELEMENTS(qn.question_origin) AS origin
                        WHERE 1 = 1
                        AND origin->>'type' = 'university'
                        AND (origin->>'id')::SMALLINT = p_university_id
                    ))
                    AND ( p_option_id IS NULL OR EXISTS (
                        SELECT 1
                        FROM JSONB_ARRAY_ELEMENTS(qn.question_origin) AS origin
                        WHERE 1 = 1
                        AND origin->>'type' = 'option'
                        AND (origin->>'id')::SMALLINT = p_option_id
                    ))
                    AND ( p_modality_id IS NULL OR EXISTS (
                        SELECT 1
                        FROM JSONB_ARRAY_ELEMENTS(qn.question_origin) AS origin
                        WHERE 1 = 1
                        AND origin->>'type' = 'modality'
                        AND (origin->>'id')::SMALLINT = p_modality_id
                    ))
                    AND ( p_version IS NULL OR EXISTS (
                        SELECT 1
                        FROM JSONB_ARRAY_ELEMENTS(qn.question_origin) AS origin
                        WHERE 1 = 1
                        AND origin->>'type' = 'version'
                        AND origin->>'name' = fn_number_to_roman(p_version)
                    ))
                    AND ( p_year IS NULL OR EXISTS (
                        SELECT 1
                        FROM JSONB_ARRAY_ELEMENTS(qn.question_origin) AS origin
                        WHERE 1 = 1
                        AND origin->>'type' = 'year'
                        AND origin->>'name' = p_year
                    ))
                ), material_questions_plus_correlatives AS (
                    SELECT
                        mqd.*,
                        l2.name::SMALLINT AS level_to_be_found,
                        l.name::SMALLINT AS "level",
                        c.code AS course_code,
                        t.code AS topic_code,
                        s.code AS subtopic_code,
                        c.name AS course,
                        t.name AS topic,
                        s.name AS subtopic,
                        CASE
                            WHEN mqd.valid_question THEN
                            SUM(
                                CASE
                                WHEN mqd.valid_question IS TRUE THEN 1
                                ELSE 0
                                END
                            ) OVER (
                            PARTITION BY
                                mqd.type_material_id,
                                mqd.course_position
                            ORDER BY
                                (mqd.question_id IS NULL),
                                mqd.type_material_id,
                                mqd.course_position,
                                mqd.absolute_position,
                                t.code,
                                mqd."position"
                                ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
                            )
                        ELSE NULL
                        END AS course_correlative
                    FROM material_question_distribution mqd
                    LEFT JOIN level l ON l.id = mqd.level_id
                    LEFT JOIN level l2 ON l2.id = mqd.level_searched_id
                    LEFT JOIN course c ON c.id = mqd.course_id
                    LEFT JOIN topic t ON t.id = mqd.topic_id
                    LEFT JOIN subtopic s ON s.id = mqd.subtopic_id
                    WHERE ( p_course_id IS NULL OR mqd.course_id = p_course_id )
                    ORDER BY
                        mqd.course_position,
                        LEFT(mqd.type_material, 1),
                        mqd.absolute_position ASC,
                        t.code,
                        mqd."position",
                        s.code,
                        l.name
                )
                SELECT
                    mmqp.question_id,
                    mmqp.material_distribution_id,
                    mmqp.type_material_id,
                    mmqp.type_material,
                    mmqp.level_searched_id,
                    mmqp.columns,
                    mmqp.level_used_id,
                    mmqp.level_id,
                    mmqp.course_id,
                    mmqp.topic_id,
                    mmqp.subtopic_id,
                    mmqp.position,
                    mmqp.code,
                    mmqp.type,
                    mmqp.config_alternative_id,
                    mmqp.random,
                    mmqp.valid_question,
                    mmqp.course_position,
                    mmqp.absolute_position,
                    mmqp.status,
                    mmqp.fl_is_manual,
                    mmqp.added_in_completion,
                    mmqp.removed_in_completion,
                    mmqp.updated_at,
                    mmqp.subquestion,
                    mmqp.type_question,
                    mmqp.category_id,
                    mmqp.category,
                    mmqp.subcategory_id,
                    mmqp.subcategory,
                    mmqp.origin_question,
                    mmqp.level_to_be_found,
                    mmqp.level,
                    mmqp.course_code,
                    mmqp.topic_code,
                    mmqp.subtopic_code,
                    mmqp.course,
                    mmqp.topic,
                    mmqp.subtopic,
                    mmqp.course_correlative,
                    CASE
                    WHEN mmqp.course_correlative IS NULL THEN UPPER(LEFT( mmqp.type_material, 4 ))
                    ELSE UPPER(LEFT( mmqp.type_material, 4 )) || '-' || COALESCE( mmqp.course_correlative::TEXT, '' )
                    END AS correlativo,
                    COUNT(*) OVER () AS total
                FROM material_questions_plus_correlatives mmqp
                WHERE 1 = 1
                    AND ( p_topic_id IS NULL OR mmqp.topic_id = p_topic_id )
                    AND ( p_subtopic_id IS NULL OR mmqp.subtopic_id = p_subtopic_id )
                    AND ( p_show_missing_questions IS NULL OR p_show_missing_questions IS FALSE OR mmqp.valid_question IS FALSE)
                    AND (p_search IS NULL OR mmqp.code ILIKE '%' || p_search || '%')
                LIMIT p_perpage OFFSET offset_val;
                END;
            $$;


ALTER FUNCTION odiseo.fn_get_ballot_questions(p_perpage integer, p_npage integer, p_search character varying, p_type_material_id integer, p_material_id integer, p_week integer, p_course_id integer, p_topic_id integer, p_subtopic_id integer, p_show_missing_questions boolean, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_version smallint, p_year character varying) OWNER TO postgres;

--
-- Name: fn_get_ballot_questions_per_period(integer, integer, character varying, integer, integer, integer, integer, integer, integer, integer, boolean, smallint, smallint, smallint, smallint, character varying, integer, character varying, boolean, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_ballot_questions_per_period(p_perpage integer, p_npage integer, p_search character varying, p_type_material_id integer, p_material_id integer, p_start_week integer, p_end_week integer, p_course_id integer, p_topic_id integer, p_subtopic_id integer, p_show_missing_questions boolean, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_version smallint, p_year character varying, p_week integer, p_question_status character varying, p_has_permission_generar_por_cursos_asignados boolean, p_employee_id bigint) RETURNS TABLE(question_id bigint, material_distribution_id bigint, type_material character varying, level_searched_id bigint, columns smallint, level_used_id bigint, level_id bigint, course_id bigint, topic_id bigint, subtopic_id bigint, code character varying, type character varying, expected_type character varying, config_alternative_id bigint, random boolean, valid_question boolean, status character varying, fl_is_manual boolean, added_in_completion boolean, removed_in_completion boolean, updated_at timestamp without time zone, subquestion json, type_question text, category character varying, category_id bigint, subcategory character varying, subcategory_id bigint, week smallint, type_material_id smallint, course_position smallint, absolute_position smallint, "position" smallint, origin_question jsonb, completed_subquestion boolean, level_to_be_found smallint, level smallint, course_code character varying, topic_code character varying, subtopic_code character varying, course character varying, topic character varying, subtopic character varying, course_correlative bigint, correlativo text, total bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    offset_val integer;
    DECLARE C_MORE_RECENT_VERSION smallint DEFAULT 1;
BEGIN
    offset_val := p_perpage * (p_npage - 1);
    RETURN QUERY WITH prepare_type_material_ids AS (
        SELECT
            CASE WHEN EXISTS (
                SELECT 1
                FROM type_material tm
                WHERE tm.parent_id = p_type_material_id
            ) THEN ARRAY (
                SELECT tm.id
                FROM type_material tm
                WHERE tm.parent_id = p_type_material_id
            )
            ELSE ARRAY[p_type_material_id]
            END AS ids
    ),
    type_material_ids AS (
        SELECT UNNEST(ids) FROM prepare_type_material_ids
    ),
    template_type_material AS (
        SELECT tmt.id AS id
        FROM type_material tm
        JOIN type_material_template tmt ON tmt.id = tm.type_material_template_id
        WHERE 1 = 1
        AND tm.type_material_template_id IS NOT NULL
        AND tm.id = p_type_material_id
    ),
    courses_ordering AS (
        SELECT
            ttmco.course_id,
            ttmco.position AS course_position,
            ttmco.university_id
        FROM template_type_material_courses_order ttmco
        WHERE 1 = 1
        AND ttmco.deleted_by IS NULL
        AND ttmco.template_type_material_id IN (
            SELECT id FROM template_type_material
        )
    ),
    type_material_valid_weeks AS (
        SELECT tdt.week
        FROM type_material_detail_template tdt
        WHERE 1 = 1
        AND tdt.type_material_id = p_type_material_id
        AND tdt.fl_status IS TRUE
    ),
    detail_week_type_mat_ids AS (
        SELECT
            dtm.id,
            dtm.type_material_id,
            dtm.week
        FROM detail_week_type_mat dtm
        WHERE dtm.material_id = p_material_id
        AND dtm.type_material_id IN (SELECT * FROM type_material_ids)
        AND dtm.week BETWEEN p_start_week AND p_end_week
        AND (p_week IS NULL OR dtm.week = p_week)
        AND dtm.week IN (SELECT * FROM type_material_valid_weeks)
        AND dtm.fl_status IS TRUE
    ),
    questions_with_distributions AS (
        SELECT
            COALESCE(q.id, mbq.id * -1) AS question_id,
            mbq.id AS material_distribution_id,
            tm.description AS type_material,
            mbq.level_id AS level_searched_id,
            q.columns AS columns,
            mbq.usage_level_id AS level_used_id,
            COALESCE(mbq.usage_level_id, mbq.level_id) AS level_id,
            mbq.course_id::bigint AS course_id,
            mbq.topic_id::bigint AS topic_id,
            mbq.subtopic_id::bigint AS subtopic_id,
            COALESCE(qsh.code, q.code, pq.code) AS code,
            COALESCE(q.type, mbq.type) AS type,
            COALESCE(mbq.type, CASE WHEN mbq.parent_question_id IS NOT NULL THEN 'T'::varchar ELSE 'D'::varchar END) AS expected_type,
            q.config_alternative_id,
            mbq.random AS random,
            COALESCE(q.id, pq.id) IS NOT NULL AS valid_question,
            q.status AS status,
            COALESCE(mbq.fl_is_manual, FALSE) AS fl_is_manual,
            mbq.added_in_completion AS added_in_completion,
            mbq.removed_in_completion AS removed_in_completion,
            COALESCE(mbq.updated_at, mbq.created_at) AS updated_at,
            (
                SELECT
                    JSON_AGG(JSON_BUILD_OBJECT(
                        'material_ballot_subquestion_id', sub.id,
                        'topic', COALESCE(t_sub.name, t_expected.name),
                        'subtopic', COALESCE(st_sub.name, st_expected.name),
                        'question_id', q_sub.id,
                        'columns', q_sub.columns,
                        'code', q_sub.code,
                        'course', COALESCE(c_sub.name, c_expected.name),
                        'topic_code', COALESCE(t_sub.code, t_expected.code),
                        'subtopic_code', COALESCE(st_sub.code, st_expected.code),
                        'course_code', COALESCE(c_sub.code, c_expected.code),
                        'description_question', q_sub.description,
                        'valid_question', q_sub.id IS NOT NULL,
                        'config_alternative_id', q_sub.config_alternative_id,
                        'origin_question', qn_sub.question_origin,
                        'course_id', COALESCE(q_sub.course_id, sub.course_id),
                        'topic_id', COALESCE(q_sub.topic_id, sub.topic_id),
                        'subtopic_id', COALESCE(q_sub.subtopic_id, sub.subtopic_id),
                        'type_question', 'S',
                        'parent_code', pq.code,
                        'category', tt.name,
                        'subcategory', tts.name,
                        'category_id', tt.id,
                        'subcategory_id', tts.id,
                        'parent_level', l.name,
                        'parent_question_id', pq.id,
                        'type_material_id', dwtmi.type_material_id,
                        'removed_in_completion', FALSE,
                        'added_in_completion', sub.added_in_completion,
                        'updated_at', sub.created_at,
                        'fl_is_manual', sub.fl_is_manual,
                        'level_id', l.id,
                        'material_distribution_id', mbq.id,
                        'correlativo', UPPER(LEFT (tm.description, 4)),
                        'status', sub.state
                    ) ORDER BY sub.position)
                FROM material_ballot_subquestions sub
                LEFT JOIN question q_sub ON sub.question_id = q_sub.id
                LEFT JOIN topic AS t_sub ON q_sub.topic_id = t_sub.id
                LEFT JOIN subtopic AS st_sub ON q_sub.subtopic_id = st_sub.id
                LEFT JOIN course c_sub ON q_sub.course_id = c_sub.id
                LEFT JOIN topic t_expected ON sub.topic_id = t_expected.id
                LEFT JOIN subtopic st_expected ON sub.subtopic_id = st_expected.id
                LEFT JOIN course c_expected ON sub.course_id = c_expected.id
                LEFT JOIN v_all_question_origins_by_university qn_sub ON q_sub.id = qn_sub.question_id
                    AND qn_sub.university_id = m.university_id
                WHERE sub.material_ballot_question_id = mbq.id
                  AND sub.fl_status = TRUE
            ) AS subquestion,
            CASE WHEN mbq.type_text_id IS NULL THEN 'P' ELSE 'T' END AS type_question,
            tt.name AS category,
            tt.id AS category_id,
            tts.name AS subcategory,
            tts.id AS subcategory_id,
            dwtmi.week,
            mbq.type_material_id,
            ccor.course_position AS course_position,
            mbq.absolute_position AS absolute_position,
            mbq.position AS "position",
            qn.question_origin,
            COALESCE(mbq.completed_subquestion, FALSE) AS completed_subquestion
        FROM material_ballot_question mbq
        JOIN detail_week_type_mat_ids dwtmi ON mbq.week_type_material_id = dwtmi.id
        JOIN detail_week_type_mat dwtm ON mbq.week_type_material_id = dwtm.id
        JOIN material m ON m.id = dwtm.material_id
        LEFT JOIN question q ON q.id = mbq.question_id
        -- Combinación: Se rescata el LATERAL JOIN de question_shares
        LEFT JOIN LATERAL (
            SELECT qs.code
            FROM question_shares qs
            WHERE qs.question_id = q.id
            AND qs.course_id = mbq.course_id
            AND qs.topic_id = mbq.topic_id
            AND qs.subtopic_id = mbq.subtopic_id
            AND qs.deleted_at IS NULL
            ORDER BY qs.updated_at DESC NULLS LAST
            LIMIT 1
        ) qsh ON TRUE
        LEFT JOIN parent_question pq ON pq.id = mbq.parent_question_id AND pq.fl_status IS TRUE
        LEFT JOIN type_material tm ON tm.id = mbq.type_material_id
        LEFT JOIN courses_ordering ccor ON ccor.course_id = mbq.course_id AND ccor.university_id IS NULL
        LEFT JOIN type_text tt ON tt.id = mbq.type_text_id
        LEFT JOIN type_text_subcategories tts ON tts.id = mbq.type_text_subcategory_id
        LEFT JOIN level l ON l.id = mbq.level_id
        LEFT JOIN v_all_question_origins_by_university qn ON q.id = qn.question_id AND qn.university_id = m.university_id
        WHERE 1 = 1
        AND mbq.fl_status IS TRUE
        AND (p_question_status IS NULL OR q.status = p_question_status)
        AND (p_university_id IS NULL OR EXISTS (
            SELECT 1 FROM JSONB_ARRAY_ELEMENTS(qn.question_origin) AS origin
            WHERE origin ->> 'type' = 'university' AND (origin ->> 'id')::smallint = p_university_id
        ))
        AND (p_option_id IS NULL OR EXISTS (
            SELECT 1 FROM JSONB_ARRAY_ELEMENTS(qn.question_origin) AS origin
            WHERE origin ->> 'type' = 'option' AND (origin ->> 'id')::smallint = p_option_id
        ))
        AND (p_modality_id IS NULL OR EXISTS (
            SELECT 1 FROM JSONB_ARRAY_ELEMENTS(qn.question_origin) AS origin
            WHERE origin ->> 'type' = 'modality' AND (origin ->> 'id')::smallint = p_modality_id
        ))
        AND (p_version IS NULL OR EXISTS (
            SELECT 1 FROM JSONB_ARRAY_ELEMENTS(qn.question_origin) AS origin
            WHERE origin ->> 'type' = 'version' AND origin ->> 'name' = fn_number_to_roman(p_version)
        ))
        AND (p_year IS NULL OR EXISTS (
            SELECT 1 FROM JSONB_ARRAY_ELEMENTS(qn.question_origin) AS origin
            WHERE origin ->> 'type' = 'year' AND origin ->> 'name' = p_year
        ))
    ),
    questions_with_distributions_with_additional_data AS (
        SELECT
            qwd.*,
            COALESCE(NULLIF(l2.name, ''), l2.description)::smallint AS level_to_be_found,
            COALESCE(NULLIF(l.name, ''), l.description)::smallint AS "level",
            c.code AS course_code,
            t.code AS topic_code,
            s.code AS subtopic_code,
            c.name AS course,
            t.name AS topic,
            s.name AS subtopic,
            CASE WHEN qwd.valid_question THEN
                SUM(CASE WHEN qwd.valid_question IS TRUE THEN 1 ELSE 0 END) OVER (
                    PARTITION BY qwd.week, qwd.type_material_id, qwd.course_position 
                    ORDER BY (qwd.question_id IS NULL), qwd.type_material_id, qwd.course_position, qwd.absolute_position, t.code, qwd."position" 
                    ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
                )
            ELSE NULL END AS course_correlative
        FROM questions_with_distributions qwd
        LEFT JOIN topic t ON t.id = qwd.topic_id
        LEFT JOIN subtopic s ON s.id = qwd.subtopic_id
        LEFT JOIN level l ON l.id = qwd.level_id
        LEFT JOIN level l2 ON l2.id = qwd.level_searched_id
        LEFT JOIN course c ON c.id = qwd.course_id
        WHERE 1 = 1
        AND (
            NOT COALESCE(p_has_permission_generar_por_cursos_asignados, FALSE)
            OR EXISTS (
                SELECT 1
                FROM employee_course ec
                WHERE ec.course_id = qwd.course_id
                AND ec.teacher_id = p_employee_id
                AND ec.fl_status IS TRUE
            )
        )
        AND (p_course_id IS NULL OR qwd.course_id = p_course_id)
        AND (p_topic_id IS NULL OR qwd.topic_id = p_topic_id)
        AND (p_subtopic_id IS NULL OR qwd.subtopic_id = p_subtopic_id)
        AND (p_show_missing_questions IS NULL OR p_show_missing_questions IS FALSE OR qwd.valid_question IS FALSE)
        AND (p_search IS NULL OR qwd.code ILIKE '%' || p_search || '%')
    )
    SELECT
        qwdw.*,
        CASE WHEN qwdw.course_correlative IS NULL THEN
            UPPER(LEFT(qwdw.type_material, 4))
        ELSE
            UPPER(LEFT(qwdw.type_material, 4)) || '-' || COALESCE(qwdw.course_correlative::text, '')
        END AS correlativo,
        COUNT(*) OVER () AS total
    FROM questions_with_distributions_with_additional_data qwdw
    WHERE 1 = 1
    AND (p_topic_id IS NULL OR qwdw.topic_id = p_topic_id)
    AND (p_subtopic_id IS NULL OR qwdw.subtopic_id = p_subtopic_id)
    AND (p_show_missing_questions IS NULL OR p_show_missing_questions IS FALSE OR qwdw.valid_question IS FALSE)
    AND (p_search IS NULL OR qwdw.code ILIKE '%' || p_search || '%')
    ORDER BY
        qwdw.week,
        qwdw.course_position,
        LEFT(qwdw.type_material, 1),
        qwdw.course_position,
        qwdw.absolute_position ASC,
        qwdw.topic_code,
        qwdw."position",
        qwdw.subtopic_code,
        qwdw.level
    LIMIT p_perpage OFFSET offset_val;
END;
$$;


ALTER FUNCTION odiseo.fn_get_ballot_questions_per_period(p_perpage integer, p_npage integer, p_search character varying, p_type_material_id integer, p_material_id integer, p_start_week integer, p_end_week integer, p_course_id integer, p_topic_id integer, p_subtopic_id integer, p_show_missing_questions boolean, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_version smallint, p_year character varying, p_week integer, p_question_status character varying, p_has_permission_generar_por_cursos_asignados boolean, p_employee_id bigint) OWNER TO postgres;

--
-- Name: fn_get_children_material_type_ids(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_children_material_type_ids(p_type_material_id bigint, p_cycle_id bigint) RETURNS TABLE(material_ids json)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY

                WITH find_type_material_template_id AS (
                    SELECT
                    type_material_template_id
                    FROM type_material
                    WHERE id = p_type_material_id
                ), children_type_material_ids AS (
                    SELECT 
                        JSON_AGG(DISTINCT tm.id) t_material_ids
                    FROM type_material_bound tmb
                    INNER JOIN type_material tm
                       ON tmb.type_material_template_extra_id = tm.type_material_template_id
                    WHERE 1 = 1
                      AND tmb.type_material_template_id = (SELECT * FROM find_type_material_template_id)
                      AND tmb.fl_status = true
                      AND tm.cycle_id = p_cycle_id
                )
                SELECT
                    COALESCE(t_material_ids, JSON_BUILD_ARRAY(p_type_material_id)) AS material_ids
                FROM children_type_material_ids;
            END;
        $$;


ALTER FUNCTION odiseo.fn_get_children_material_type_ids(p_type_material_id bigint, p_cycle_id bigint) OWNER TO postgres;

--
-- Name: fn_get_column_config_type_material_template(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_column_config_type_material_template(p_type_material_id bigint) RETURNS TABLE(number_columns integer, type_solution character varying, has_config_column boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_role TEXT;
    v_target_id BIGINT;
BEGIN

    -- Determinar rol
    SELECT 
        CASE
            WHEN EXISTS (
                select 1 from type_material tm
                where tm.id = p_type_material_id
                  and tm.parent_id IS NULL
                  and tm.fl_status = TRUE
            ) THEN 'PARENT'

            WHEN EXISTS (
                select 1 from type_material tm
                where tm.id = p_type_material_id
                  and tm.parent_id IS NOT NULL
                  and tm.fl_status = TRUE
            ) THEN 'CHILD'

            ELSE 'UNIQUE'
        END
    INTO v_role;

    -- Si es CHILD obtener el padre
    IF v_role = 'CHILD' THEN
        select tm_parent.type_material_template_id
        into v_target_id
        from type_material tm
        join type_material tm_parent on tm_parent.id = tm.parent_id and tm_parent.fl_status = TRUE
        where tm.id = p_type_material_id
        and tm.fl_status = TRUE;

    ELSE
        select tm.type_material_template_id
        into v_target_id
        from type_material tm
        where tm.id = p_type_material_id
        and tm.fl_status = TRUE;
    END IF;

    -- Retornar configuración
    RETURN QUERY
    SELECT
        tmc.number_columns,
        tmc.type_solution,
        tmt.has_config_column
    FROM type_material_template_configuration_columns tmc
    JOIN type_material_template tmt ON tmt.id = tmc.type_material_template_id AND tmt.fl_status IS TRUE
    WHERE tmc.type_material_template_id = v_target_id
      AND tmc.deleted_at IS NULL;

END;
$$;


ALTER FUNCTION odiseo.fn_get_column_config_type_material_template(p_type_material_id bigint) OWNER TO postgres;

--
-- Name: fn_get_config_level_complete_ballot_period(bigint, smallint, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_config_level_complete_ballot_period(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) RETURNS TABLE(id bigint, type_material_id bigint, amount_type_mat integer, level_id bigint, level_description character varying, level_name character varying, type_question character varying, week smallint, headquarter_id bigint, course_id bigint, code_course character varying, course character varying, course_position smallint)
    LANGUAGE plpgsql
    AS $$
                DECLARE
                    v_ids_children INT[];
                BEGIN
                    SELECT CASE
                        WHEN EXISTS (SELECT 1 FROM type_material tm WHERE tm.parent_id = p_type_material_id)
                        THEN ARRAY(SELECT tm.id FROM type_material tm WHERE tm.parent_id = p_type_material_id)
                        ELSE ARRAY[p_type_material_id]
                    END INTO v_ids_children;

                    RETURN QUERY
                    WITH tbl_material AS ( -- Se obtiene el ciclo y universidad del material
                        SELECT
                            m.cycle_id,
                            m.university_id
                        FROM material m
                        WHERE m.id = p_material_id
                    ), template_type_material AS (
                        SELECT
                            tm.type_material_template_id
                        FROM type_material tm
                        WHERE tm.id = p_type_material_id
                    ), courses_ordering AS (
                        SELECT
                            cor.course_id,
                            cor.position AS course_position
                        FROM template_type_material_courses_order cor
                        WHERE cor.deleted_at IS NULL
                            AND cor.template_type_material_id IN (SELECT tmt.type_material_template_id FROM template_type_material tmt)
                            AND cor.university_id IS NULL -- Se valida por el parametro university_id nulo como valor por defecto
                    ), get_type_materias AS ( -- Se trae el id de tipo material hijo si los tiene, sino se manda el normal
                        SELECT unnest(v_ids_children) AS type_material_id
                    ), get_type_material_courses_generic AS ( -- Se trae los cursos de tipo material
                        SELECT
                            tmc.type_material_id,
                            tmc.course_id
                        FROM type_material_course tmc
                        WHERE tmc.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
                            AND tmc.amount_question > 0
                            AND tmc.is_generic IS TRUE
                            AND tmc.fl_status = true
                    ), get_type_material_courses_not_generic AS (
                        SELECT DISTINCT
                            tmc.type_material_id,
                            tmc.course_id
                        FROM type_material_course tmc
                        JOIN type_material_detail_template tmdt ON tmc.type_material_id = tmdt.type_material_id
                            AND tmdt.fl_status = true
                        JOIN odiseo.type_material_detail_courses tmdc ON tmc.id = tmdc.type_material_course_id
                            AND tmdt.id = tmdc.type_material_detail_template_id
                            AND tmdc.fl_status = true
                        WHERE tmc.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
                            AND tmdc.amount_question > 0
                            AND tmc.is_generic IS FALSE
                            AND tmc.fl_status = true
                            AND tmdt.week BETWEEN p_start_week AND p_end_week
                    ), get_type_material_courses AS (
                        SELECT * FROM get_type_material_courses_generic
                        UNION ALL
                        SELECT * FROM get_type_material_courses_not_generic
                    ), get_type_material_week AS ( -- Se trae las semanas del tipo material
                        SELECT
                            tmdt.week
                        FROM type_material_detail_template tmdt
                        WHERE tmdt.type_material_id = p_type_material_id
                            AND tmdt.week BETWEEN p_start_week AND p_end_week
                            AND tmdt.fl_status = true
                        ORDER BY tmdt.week ASC
                    ), get_courses_not_register_ballot AS (
                        SELECT DISTINCT
                            gtmc.course_id
                        FROM get_type_material_courses gtmc
                        LEFT JOIN (
                            SELECT DISTINCT
                                mdbq.course_id
                            FROM detail_week_type_mat dwtm
                            JOIN material_ballot_question mdbq
                                ON dwtm.id = mdbq.week_type_material_id
                            WHERE mdbq.material_id = p_material_id
                                AND dwtm.week BETWEEN p_start_week AND p_end_week
                                AND dwtm.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
                                AND mdbq.fl_status = true
                                AND mdbq.type_text_id IS NULL
                        ) AS existing_courses
                        ON gtmc.course_id = existing_courses.course_id
                        WHERE existing_courses.course_id IS NULL
                    )
                    SELECT
                        dlsw.id,
                        dlsw.type_material_id,
                        dlsw.number_questions AS amount_type_mat,
                        dlsw.level_id,
                        l.description AS level_description,
                        l.name AS level_name,
                        dlsw.type_question,
                        lsw.week,
                        ls.headquarter_id,
                        ls.course_id,
                        c.code AS code_course,
                        c.name AS course,
                        ccor.course_position
                    FROM detail_level_syllabus_weeks dlsw
                    INNER JOIN level_syllabus_weeks lsw ON dlsw.level_syllabus_weeks_id = lsw.id
                        AND lsw.fl_status = true
                    INNER JOIN level_syllabus ls ON lsw.level_syllabus_id = ls.id
                    INNER JOIN course c ON ls.course_id = c.id
                    INNER JOIN level l ON dlsw.level_id = l.id
                    LEFT JOIN courses_ordering ccor ON ls.course_id = ccor.course_id
                    WHERE 1 = 1
                        AND dlsw.fl_status = true
                        AND ls.fl_status = true
                        AND dlsw.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
                        AND ls.cycle_id IN (SELECT tm.cycle_id FROM tbl_material tm)
                        AND ls.university_id IN (SELECT tm.university_id FROM tbl_material tm)
                        AND ls.course_id IN (SELECT gcnrb.course_id FROM get_courses_not_register_ballot gcnrb)
                        AND lsw.week IN (SELECT gtmw.week FROM get_type_material_week gtmw)
                    ORDER BY ccor.course_position ASC, ls.course_id ASC, dlsw.level_id ASC, dlsw.type_question ASC, lsw.week ASC;
                END;
                $$;


ALTER FUNCTION odiseo.fn_get_config_level_complete_ballot_period(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) OWNER TO postgres;

--
-- Name: fn_get_config_level_register_ballot_period(bigint, smallint, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_config_level_register_ballot_period(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) RETURNS TABLE(id bigint, type_material_id bigint, amount_type_mat integer, level_id bigint, level_description character varying, level_name character varying, type_question character varying, week smallint, headquarter_id bigint, course_id bigint, code_course character varying, course character varying)
    LANGUAGE plpgsql
    AS $$
                DECLARE
                    v_ids_children INT[];
                BEGIN
                    -- Obtener todos los IDs de los hijos en un array
                    SELECT CASE
                        WHEN EXISTS (SELECT 1 FROM type_material tm WHERE tm.parent_id = p_type_material_id)
                        THEN ARRAY(SELECT tm.id FROM type_material tm WHERE tm.parent_id = p_type_material_id)
                        ELSE ARRAY[p_type_material_id]
                    END INTO v_ids_children;

                    RETURN QUERY
                    WITH tbl_material AS ( -- Se obtiene el ciclo y universidad del material
                        SELECT
                            m.cycle_id,
                            m.university_id
                        FROM material m
                        WHERE m.id = p_material_id
                    ), get_type_materias AS ( -- Se trae el id de tipo material hijo si los tiene, sino se manda el normal
                        SELECT unnest(v_ids_children) AS type_material_id
                    ), get_type_material_courses_generic AS ( -- Se trae los cursos de tipo material
                        SELECT
                            tmc.type_material_id,
                            tmc.course_id
                        FROM type_material_course tmc
                        WHERE tmc.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
                            AND tmc.amount_question > 0
                            AND tmc.is_generic IS TRUE
                            AND tmc.fl_status = true
                    ), get_type_material_courses_not_generic AS (
                        SELECT DISTINCT
                            tmc.type_material_id,
                            tmc.course_id
                        FROM type_material_course tmc
                        JOIN type_material_detail_template tmdt ON tmc.type_material_id = tmdt.type_material_id
                            AND tmdt.fl_status = true
                        JOIN odiseo.type_material_detail_courses tmdc ON tmc.id = tmdc.type_material_course_id
                            AND tmdt.id = tmdc.type_material_detail_template_id
                            AND tmdc.fl_status = true
                        WHERE tmc.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
                            AND tmdc.amount_question > 0
                            AND tmc.is_generic IS FALSE
                            AND tmc.fl_status = true
                            AND tmdt.week BETWEEN p_start_week AND p_end_week
                    ), get_type_material_courses AS (
                        SELECT * FROM get_type_material_courses_generic
                        UNION
                        SELECT * FROM get_type_material_courses_not_generic
                    ), get_type_material_week AS ( -- Se trae las semanas del tipo material
                        SELECT
                            tmdt.week
                        FROM type_material_detail_template tmdt
                        WHERE tmdt.type_material_id = p_type_material_id
                            AND tmdt.week BETWEEN p_start_week AND p_end_week
                            AND tmdt.fl_status = true
                        ORDER BY tmdt.week ASC
                    )
                    SELECT
                        dlsw.id,
                        dlsw.type_material_id,
                        dlsw.number_questions AS amount_type_mat,
                        dlsw.level_id,
                        l.description AS level_description,
                        l.name AS level_name,
                        dlsw.type_question,
                        lsw.week,
                        ls.headquarter_id,
                        ls.course_id,
                        c.code AS code_course,
                        c.name AS course
                    FROM detail_level_syllabus_weeks dlsw
                    INNER JOIN level_syllabus_weeks lsw ON dlsw.level_syllabus_weeks_id = lsw.id
                        AND lsw.fl_status = true
                    INNER JOIN level_syllabus ls ON lsw.level_syllabus_id = ls.id
                    INNER JOIN course c ON ls.course_id = c.id
                    INNER JOIN level l ON dlsw.level_id = l.id
                    WHERE 1 = 1
                        AND dlsw.fl_status = true
                        AND ls.fl_status = true
                        AND dlsw.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
                        AND ls.cycle_id IN (SELECT tm.cycle_id FROM tbl_material tm)
                        AND ls.university_id IN (SELECT tm.university_id FROM tbl_material tm)
                        AND ls.course_id IN (SELECT gtmc.course_id FROM get_type_material_courses gtmc)
                        AND lsw.week IN (SELECT gtmw.week FROM get_type_material_week gtmw)
                    ORDER BY ls.course_id ASC, dlsw.level_id ASC, dlsw.type_question ASC, lsw.week ASC;
                END;
                $$;


ALTER FUNCTION odiseo.fn_get_config_level_register_ballot_period(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) OWNER TO postgres;

--
-- Name: fn_get_config_syllabus_complete_ballot_period(bigint, smallint, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_config_syllabus_complete_ballot_period(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) RETURNS TABLE(id bigint, type_material_id smallint, amount_type_mat smallint, subtopic_id smallint, code_subtopic character varying, subtopic character varying, week smallint, topic_id smallint, code_topic character varying, topic character varying, course_id bigint, code_course character varying, course character varying, course_position smallint, syllabus_id bigint)
    LANGUAGE plpgsql
    AS $$
                DECLARE
                    v_ids_children INT[];
                    v_university_id INT;
                BEGIN
                    SELECT CASE
                        WHEN EXISTS (SELECT 1 FROM type_material tm WHERE tm.parent_id = p_type_material_id)
                        THEN ARRAY(SELECT tm.id FROM type_material tm WHERE tm.parent_id = p_type_material_id)
                        ELSE ARRAY[p_type_material_id]
                    END INTO v_ids_children;

                    RETURN QUERY
                    WITH tbl_material AS ( -- Se obtiene el ciclo y universidad del material
                        SELECT
                            m.cycle_id,
                            m.university_id
                        FROM material m
                        WHERE m.id = p_material_id
                    ), template_type_material AS (
                        SELECT
                            tm.type_material_template_id
                        FROM type_material tm
                        WHERE tm.id = p_type_material_id
                    ), courses_ordering AS (
                        SELECT
                            cor.course_id,
                            cor.position AS course_position
                        FROM template_type_material_courses_order cor
                        WHERE 1 = 1
                        AND cor.deleted_at IS NULL
                        AND cor.template_type_material_id IN (SELECT tmt.type_material_template_id FROM template_type_material tmt)
                        AND cor.university_id IS NULL
                    ), get_type_materias AS ( -- Se trae el id de tipo material hijo si los tiene, sino se manda el normal
                        SELECT unnest(v_ids_children) AS type_material_id
                    ), get_type_material_courses_generic AS ( -- Se trae los cursos de tipo material
                        SELECT
                            tmc.type_material_id,
                            tmc.course_id
                        FROM type_material_course tmc
                        WHERE tmc.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
                            AND tmc.amount_question > 0
                            AND tmc.is_generic IS TRUE
                            AND tmc.fl_status = true
                    ), get_type_material_courses_not_generic AS (
                        SELECT DISTINCT
                            tmc.type_material_id,
                            tmc.course_id
                        FROM type_material_course tmc
                        JOIN type_material_detail_template tmdt ON tmc.type_material_id = tmdt.type_material_id
                            AND tmdt.fl_status = true
                        JOIN odiseo.type_material_detail_courses tmdc ON tmc.id = tmdc.type_material_course_id
                            AND tmdt.id = tmdc.type_material_detail_template_id
                            AND tmdc.fl_status = true
                        WHERE tmc.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
                            AND tmdc.amount_question > 0
                            AND tmc.is_generic IS FALSE
                            AND tmc.fl_status = true
                            AND tmdt.week BETWEEN p_start_week AND p_end_week
                    ), get_type_material_courses AS (
                        SELECT * FROM get_type_material_courses_generic
                        UNION ALL
                        SELECT * FROM get_type_material_courses_not_generic
                    ), get_type_material_week AS ( -- Se trae las semanas del tipo material
                        SELECT
                            tmdt.week
                        FROM type_material_detail_template tmdt
                        WHERE tmdt.type_material_id = p_type_material_id
                            AND tmdt.week BETWEEN p_start_week AND p_end_week
                            AND tmdt.fl_status = true
                        ORDER BY tmdt.week ASC
                    ), get_courses_not_register_ballot AS (
                        SELECT DISTINCT
                            gtmc.course_id
                        FROM get_type_material_courses gtmc
                        LEFT JOIN (
                            SELECT DISTINCT
                                mdbq.course_id
                            FROM detail_week_type_mat dwtm
                            JOIN material_ballot_question mdbq
                                ON dwtm.id = mdbq.week_type_material_id
                            WHERE mdbq.material_id = p_material_id
                                AND dwtm.week BETWEEN p_start_week AND p_end_week
                                AND dwtm.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
                                AND mdbq.fl_status = true
                                AND mdbq.type_text_id IS NULL
                        ) AS existing_courses
                        ON gtmc.course_id = existing_courses.course_id
                        WHERE existing_courses.course_id IS NULL
                    )
                    SELECT
                        stm.id,
                        stm.type_material_id,
                        stm.questions_amount AS amount_type_mat,
                        sds.subtopic_id,
                        su.code AS code_subtopic,
                        su.name AS subtopic,
                        stw.week,
                        st.topic_id,
                        top.code AS code_topic,
                        top.name AS topic,
                        s.course_id,
                        co.code AS code_course,
                        co.name AS course,
                        ccor.course_position,
                        s.id AS syllabus_id
                    FROM syllabus_subtopic_type_material stm
                    INNER JOIN syllabus_detail_subtopic sds ON stm.syllabus_detail_subtopic_id = sds.id AND sds.fl_status = true
                    INNER JOIN syllabus_topic_week stw ON sds.syllabus_topic_week_id = stw.id AND stw.fl_status = true
                    INNER JOIN syllabus_topic st ON stw.syllabus_topic_id = st.id AND st.fl_status = true
                    INNER JOIN syllabus s ON st.syllabus_id = s.id
                    INNER JOIN course co ON s.course_id = co.id
                    INNER JOIN topic top ON st.topic_id = top.id
                    INNER JOIN subtopic su ON sds.subtopic_id = su.id
                    LEFT JOIN courses_ordering ccor ON s.course_id = ccor.course_id
                    WHERE 1 = 1
                        AND stm.fl_status = true
                        AND s.fl_status = true
                        AND s.course_id IN (SELECT gcnrb.course_id FROM get_courses_not_register_ballot gcnrb)
                        AND stm.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
                        AND s.university_id IN (SELECT tm.university_id FROM tbl_material tm)
                        AND s.cycle_id IN (SELECT tm.cycle_id FROM tbl_material tm)
                        AND stw.week IN (SELECT gtmw.week FROM get_type_material_week gtmw)
                        AND stm.questions_amount > 0
                    ORDER BY ccor.course_position ASC, s.course_id ASC, st.topic_id ASC, sds.subtopic_id ASC, stw.week ASC;
                END;
                $$;


ALTER FUNCTION odiseo.fn_get_config_syllabus_complete_ballot_period(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) OWNER TO postgres;

--
-- Name: fn_get_config_syllabus_register_ballot_period(bigint, smallint, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_config_syllabus_register_ballot_period(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) RETURNS TABLE(id bigint, type_material_id smallint, amount_type_mat smallint, subtopic_id smallint, code_subtopic character varying, subtopic character varying, week smallint, topic_id smallint, code_topic character varying, topic character varying, course_id bigint, code_course character varying, course character varying, syllabus_id bigint)
    LANGUAGE plpgsql
    AS $$
                DECLARE
                    v_ids_children INT[];
                BEGIN
                    -- Obtener todos los IDs de los hijos en un array
                    SELECT CASE
                        WHEN EXISTS (SELECT 1 FROM type_material tm WHERE tm.parent_id = p_type_material_id)
                        THEN ARRAY(SELECT tm.id FROM type_material tm WHERE tm.parent_id = p_type_material_id)
                        ELSE ARRAY[p_type_material_id]
                    END INTO v_ids_children;

                    RETURN QUERY
                    WITH tbl_material AS ( -- Se obtiene el ciclo y universidad del material
                        SELECT
                            m.cycle_id,
                            m.university_id
                        FROM material m
                        WHERE m.id = p_material_id
                    ), get_type_materias AS ( -- Se trae el id de tipo material hijo si los tiene, sino se manda el normal
                        SELECT unnest(v_ids_children) AS type_material_id
                    ), get_type_material_courses_generic AS ( -- Se trae los cursos de tipo material
                        SELECT
                            tmc.type_material_id,
                            tmc.course_id
                        FROM type_material_course tmc
                        WHERE tmc.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
                            AND tmc.amount_question > 0
                            AND tmc.is_generic IS TRUE
                            AND tmc.fl_status = true
                    ), get_type_material_courses_not_generic AS (
                        SELECT DISTINCT
                            tmc.type_material_id,
                            tmc.course_id
                        FROM type_material_course tmc
                        JOIN type_material_detail_template tmdt ON tmc.type_material_id = tmdt.type_material_id
                            AND tmdt.fl_status = true
                        JOIN odiseo.type_material_detail_courses tmdc ON tmc.id = tmdc.type_material_course_id
                            AND tmdt.id = tmdc.type_material_detail_template_id
                            AND tmdc.fl_status = true
                        WHERE tmc.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
                            AND tmdc.amount_question > 0
                            AND tmc.is_generic IS FALSE
                            AND tmc.fl_status = true
                            AND tmdt.week BETWEEN p_start_week AND p_end_week
                    ), get_type_material_courses AS (
                        SELECT * FROM get_type_material_courses_generic
                        UNION
                        SELECT * FROM get_type_material_courses_not_generic
                    ), get_type_material_week AS ( -- Se trae las semanas del tipo material
                        SELECT
                            tmdt.week
                        FROM type_material_detail_template tmdt
                        WHERE tmdt.type_material_id = p_type_material_id
                            AND tmdt.week BETWEEN p_start_week AND p_end_week
                            AND tmdt.fl_status = true
                        ORDER BY tmdt.week ASC
                    )
                    SELECT
                        stm.id,
                        stm.type_material_id,
                        stm.questions_amount AS amount_type_mat,
                        sds.subtopic_id,
                        su.code AS code_subtopic,
                        su.name AS subtopic,
                        stw.week,
                        st.topic_id,
                        top.code AS code_topic,
                        top.name AS topic,
                        s.course_id,
                        co.code AS code_course,
                        co.name AS course,
                        s.id AS syllabus_id
                    FROM syllabus_subtopic_type_material stm
                    INNER JOIN syllabus_detail_subtopic sds ON stm.syllabus_detail_subtopic_id = sds.id AND sds.fl_status = true
                    INNER JOIN syllabus_topic_week stw ON sds.syllabus_topic_week_id = stw.id AND stw.fl_status = true
                    INNER JOIN syllabus_topic st ON stw.syllabus_topic_id = st.id AND st.fl_status = true
                    INNER JOIN syllabus s ON st.syllabus_id = s.id
                    INNER JOIN course co ON s.course_id = co.id
                    INNER JOIN topic top ON st.topic_id = top.id
                    INNER JOIN subtopic su ON sds.subtopic_id = su.id
                    WHERE 1 = 1
                        AND stm.fl_status = true
                        AND s.fl_status = true
                        AND s.course_id IN (SELECT gtmc.course_id FROM get_type_material_courses gtmc)
                        AND stm.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
                        AND s.university_id IN (SELECT tm.university_id FROM tbl_material tm)
                        AND s.cycle_id IN (SELECT tm.cycle_id FROM tbl_material tm)
                        AND stw.week IN (SELECT gtmw.week FROM get_type_material_week gtmw)
                        AND stm.questions_amount > 0
                    ORDER BY s.course_id ASC, st.topic_id ASC, sds.subtopic_id ASC, stw.week ASC;
                END;
                $$;


ALTER FUNCTION odiseo.fn_get_config_syllabus_register_ballot_period(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) OWNER TO postgres;

