ALTER FUNCTION odiseo.fn_get_config_text_level_register_ballot_period(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) OWNER TO postgres;

--
-- Name: fn_get_config_text_syllabus_complete_ballot_period(bigint, smallint, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_config_text_syllabus_complete_ballot_period(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) RETURNS TABLE(category_id bigint, subcategory_id bigint, type_material_id smallint, course_id bigint, course_name character varying, material character varying, category character varying, subcategory character varying, topic_subquestions jsonb, position_initial bigint, position_text smallint, week smallint)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY
                    WITH type_material_ids AS (
                        SELECT
                            CASE
                                WHEN EXISTS ( SELECT 1 FROM type_material tmx WHERE tmx.parent_id = p_type_material_id )
                                THEN ARRAY( SELECT tmy.id FROM type_material tmy WHERE tmy.parent_id = p_type_material_id )
                                ELSE ARRAY[p_type_material_id]
                            END AS ids
                    ), tbl_material AS ( -- Se obtiene el ciclo y universidad del material
                        SELECT
                            m.cycle_id,
                            m.university_id
                        FROM material m
                        WHERE m.id = p_material_id
                    ), get_type_material_courses_generic AS ( -- Se trae los cursos de tipo material
                        SELECT
                            tmc.type_material_id,
                            tmc.course_id
                        FROM type_material_course tmc
                        WHERE tmc.type_material_id IN ( SELECT UNNEST(ids) FROM type_material_ids )
                            AND tmc.amount_text > 0
                            AND tmc.is_generic_text IS TRUE
                            AND tmc.fl_status = true
                    ), get_type_material_courses_not_generic AS (
                        SELECT DISTINCT
                            tmc.type_material_id,
                            tmc.course_id
                        FROM type_material_course tmc
                        JOIN type_material_detail_template tmdt ON tmc.type_material_id = tmdt.type_material_id
                            AND tmdt.fl_status = true
                        JOIN odiseo.type_material_detail_course_texts tmdc ON tmc.id = tmdc.type_material_course_id
                            AND tmdt.id = tmdc.type_material_detail_template_id
                            AND tmdc.fl_status = true
                        WHERE tmc.type_material_id IN ( SELECT UNNEST(ids) FROM type_material_ids )
                            AND tmdc.amount_text > 0
                            AND tmc.is_generic_text IS FALSE
                            AND tmc.fl_status = true
                            AND tmdt.week BETWEEN p_start_week AND p_end_week
                    ), get_type_material_courses AS (
                        SELECT * FROM get_type_material_courses_generic
                        UNION ALL
                        SELECT * FROM get_type_material_courses_not_generic
                    ), get_type_material_week AS ( -- Se trae las semanas del tipo material
                        SELECT
                            tmdt.week
                        FROM type_material_detail_template tmdt
                        WHERE tmdt.type_material_id = p_type_material_id
                            AND tmdt.week BETWEEN p_start_week AND p_end_week
                            AND tmdt.fl_status = true
                        ORDER BY tmdt.week ASC
                    ), get_courses_not_register_ballot AS (
                        SELECT DISTINCT
                            gtmc.course_id
                        FROM get_type_material_courses gtmc
                        LEFT JOIN (
                            SELECT DISTINCT
                                mdbq.course_id
                            FROM detail_week_type_mat dwtm
                            JOIN material_ballot_question mdbq
                                ON dwtm.id = mdbq.week_type_material_id
                            WHERE mdbq.material_id = p_material_id
                                AND dwtm.week BETWEEN p_start_week AND p_end_week
                                AND dwtm.type_material_id IN ( SELECT UNNEST(ids) FROM type_material_ids )
                                AND mdbq.fl_status = true
                                AND mdbq.type_text_id IS NOT NULL
                        ) AS existing_courses
                        ON gtmc.course_id = existing_courses.course_id
                        WHERE existing_courses.course_id IS NULL
                    )
                    SELECT
                        tt.id AS category_id,
                        tts.id AS subcategory_id,
                        tm.id AS type_material_id,
                        s.course_id,
                        c.name AS course_name,
                        tm.description AS material,
                        tt.name AS category,
                        tts.name AS subcategory,
                        (
                            SELECT jsonb_agg(
                                jsonb_build_object(
                                    'topic_id', t.id,
                                    'code_topic', t.code,
                                    'subtopic_id', stc.subtopic_id,
                                    'code_subtopic', sub.code,
                                    'quantity', stc.quantity
                                )
                                ORDER BY t.code, sub.code
                            ) AS topic_subquestions
                            FROM syllabus_text_content stc
                            JOIN subtopic sub ON sub.id = stc.subtopic_id
                            JOIN topic t ON t.id = sub.topic_id
                            WHERE stc.syllabus_text_id = st.id
                                AND stc.fl_status = true
                        ) AS topic_subquestions,
                        (ROW_NUMBER() OVER (ORDER BY tt.position, tts.id) - 1) AS position_initial,
                        tt.position position_text,
                        stw.week
                    FROM syllabus s
                    JOIN course c ON c.id = s.course_id
                    JOIN syllabus_text_weeks stw ON stw.syllabus_id = s.id
                        AND stw.fl_status = true
                    JOIN syllabus_text_distributions std ON std.syllabus_text_week_id = stw.id
                        AND std.fl_status = true
                    JOIN type_material tm ON tm.id = std.type_material_id
                    JOIN syllabus_texts st ON st.syllabus_text_distribution_id = std.id
                        AND st.fl_status = true
                    JOIN type_text tt ON tt.id = st.type_text_id
                    JOIN type_text_subcategories tts ON tts.id = st.type_text_subcategory_id
                    WHERE std.type_material_id IN ( SELECT UNNEST(ids) FROM type_material_ids )
                        AND s.university_id IN (SELECT tm.university_id FROM tbl_material tm)
                        AND s.cycle_id IN (SELECT tm.cycle_id FROM tbl_material tm)
                        AND stw.week IN (SELECT gtmw.week FROM get_type_material_week gtmw)
                        AND s.course_id IN (SELECT gcnrb.course_id FROM get_courses_not_register_ballot gcnrb)
                    ORDER BY tt.id, tts.id;
                END;
                $$;


ALTER FUNCTION odiseo.fn_get_config_text_syllabus_complete_ballot_period(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) OWNER TO postgres;

--
-- Name: fn_get_config_text_syllabus_register_ballot_period(bigint, smallint, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_config_text_syllabus_register_ballot_period(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) RETURNS TABLE(category_id bigint, subcategory_id bigint, type_material_id smallint, course_id bigint, course_name character varying, material character varying, category character varying, subcategory character varying, topic_subquestions jsonb, position_initial bigint, position_text smallint, week smallint)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY
                    WITH type_materials AS (
                        SELECT CASE
                             WHEN EXISTS (SELECT 1 FROM type_material tm WHERE tm.parent_id = p_type_material_id)
                            THEN ARRAY(SELECT tm.id FROM type_material tm WHERE tm.parent_id = p_type_material_id)
                            ELSE ARRAY[p_type_material_id]
                        END v_ids_children
                    ), tbl_material AS ( -- Se obtiene el ciclo y universidad del material
                        SELECT
                            m.cycle_id,
                            m.university_id
                        FROM material m
                        WHERE m.id = p_material_id
                    ), get_type_materias AS ( -- Se trae el id de tipo material hijo si los tiene, sino se manda el normal
                        SELECT unnest(tm.v_ids_children) AS type_material_id FROM type_materials tm
                    ), get_type_material_courses_generic AS ( -- Se trae los cursos de tipo material
                        SELECT
                            tmc.type_material_id,
                            tmc.course_id
                        FROM type_material_course tmc
                        WHERE tmc.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
                            AND tmc.amount_text > 0
                            AND tmc.is_generic_text IS TRUE
                            AND tmc.fl_status = true
                    ), get_type_material_courses_not_generic AS (
                        SELECT DISTINCT
                            tmc.type_material_id,
                            tmc.course_id
                        FROM type_material_course tmc
                        JOIN type_material_detail_template tmdt ON tmc.type_material_id = tmdt.type_material_id
                            AND tmdt.fl_status = true
                        JOIN type_material_detail_course_texts tmdc ON tmc.id = tmdc.type_material_course_id
                            AND tmdt.id = tmdc.type_material_detail_template_id
                            AND tmdc.fl_status = true
                        WHERE tmc.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
                            AND tmdc.amount_text > 0
                            AND tmc.is_generic_text IS FALSE
                            AND tmc.fl_status = true
                            AND tmdt.week BETWEEN p_start_week AND p_end_week
                    ), get_type_material_courses AS (
                        SELECT * FROM get_type_material_courses_generic
                        UNION
                        SELECT * FROM get_type_material_courses_not_generic
                    ), get_type_material_week AS ( -- Se trae las semanas del tipo material
                        SELECT
                            tmdt.week
                        FROM type_material_detail_template tmdt
                        WHERE tmdt.type_material_id = p_type_material_id
                            AND tmdt.week BETWEEN p_start_week AND p_end_week
                            AND tmdt.fl_status = true
                        ORDER BY tmdt.week ASC
                    )
                    SELECT
                        tt.id AS category_id,
                        tts.id AS subcategory_id,
                        tm.id AS type_material_id,
                        s.course_id,
                        c."name" AS course_name,
                        tm.description AS material,
                        tt.name AS category,
                        tts.name AS subcategory,
                        (
                            SELECT jsonb_agg(
                                jsonb_build_object(
                                    'topic_id', t.id,
                                    'code_topic', t.code,
                                    'subtopic_id', stc.subtopic_id,
                                    'code_subtopic', sub.code,
                                    'quantity', stc.quantity
                                )
                                ORDER BY t.code, sub.code
                            ) AS topic_subquestions
                            FROM syllabus_text_content stc
                            JOIN subtopic sub ON sub.id = stc.subtopic_id
                            JOIN topic t ON t.id = sub.topic_id
                            WHERE stc.syllabus_text_id = st.id
                                AND stc.fl_status = true
                        ) AS topic_subquestions,
                        (ROW_NUMBER() OVER (ORDER BY tt.position, tts.id) - 1) AS position_initial,
                        tt.position position_text,
                        stw.week
                    FROM syllabus s
                    JOIN course c ON c.id = s.course_id
                    JOIN syllabus_text_weeks stw ON stw.syllabus_id = s.id
                        AND stw.fl_status = true
                    JOIN syllabus_text_distributions std ON std.syllabus_text_week_id = stw.id
                        AND std.fl_status = true
                    JOIN type_material tm ON tm.id = std.type_material_id
                    JOIN syllabus_texts st ON st.syllabus_text_distribution_id = std.id
                        AND st.fl_status = true
                    JOIN type_text tt ON tt.id = st.type_text_id
                    JOIN type_text_subcategories tts ON tts.id = st.type_text_subcategory_id
                    WHERE std.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
                        AND s.university_id IN (SELECT tm.university_id FROM tbl_material tm)
                        AND s.cycle_id IN (SELECT tm.cycle_id FROM tbl_material tm)
                        AND stw.week IN (SELECT gtmw.week FROM get_type_material_week gtmw)
                        AND s.course_id IN (SELECT gtmc.course_id FROM get_type_material_courses gtmc)
                    ORDER BY tt.id, tts.id;
                END;
                $$;


ALTER FUNCTION odiseo.fn_get_config_text_syllabus_register_ballot_period(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) OWNER TO postgres;

--
-- Name: fn_get_course_and_exam_area(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_course_and_exam_area(p_type_material_id bigint) RETURNS TABLE(course_id smallint, course_name character varying, apply_text boolean, exam_area jsonb, position_course smallint)
    LANGUAGE plpgsql
    AS $$
            BEGIN

                RETURN QUERY
                WITH course_ordering AS (
                SELECT DISTINCT
                    tmc.course_id,
                    tma.type_material_id,
                    course_ordering.position
                FROM type_material_area_courses tmac
                LEFT JOIN type_material_area tma ON tmac.type_material_area_id = tma.id
                LEFT JOIN type_material_course tmc ON tmac.type_material_course_id = tmc.id
                INNER JOIN type_material tm ON tma.type_material_id = tm.id
                LEFT JOIN (
                    SELECT
                        ttmco.course_id,
                        tm.id AS type_material_id,
                        tm.type_material_template_id,
                        ttmco.position
                    FROM template_type_material_courses_order ttmco
                    INNER JOIN type_material tm
                        ON tm.type_material_template_id = ttmco.template_type_material_id
                    WHERE ttmco.university_id IS NULL
                ) AS course_ordering
                    ON course_ordering.type_material_template_id = tm.type_material_template_id
                    AND course_ordering.course_id = tmc.course_id
                    WHERE tma.type_material_id = p_type_material_id
                    AND tmc.type_material_id = p_type_material_id
                    AND tmc.fl_status = TRUE AND tma.fl_status = TRUE
                ),
                configured_areas AS (
                    SELECT DISTINCT 
                        tma.area_id,
                        ea.description AS area_name
                    FROM type_material_area tma
                    JOIN exam_area ea ON ea.id = tma.area_id
                    WHERE tma.type_material_id = p_type_material_id
                    AND tma.fl_status = TRUE 
                    AND tma.deleted_at IS NULL
                    AND ea.fl_status = TRUE
                ),
                base_courses AS (
                    SELECT DISTINCT 
                        c.id, 
                        c.name,
                        c.apply_text
                    FROM type_material_course tmc
                    JOIN course c ON c.id = tmc.course_id
                    WHERE tmc.type_material_id = p_type_material_id 
                    AND tmc.fl_status = TRUE 
                    AND tmc.deleted_at IS NULL
                ),
                course_area_skeleton AS (
                    SELECT 
                        c.id AS course_id,
                        c.name AS course_name,
                        c.apply_text AS course_apply_text,
                        ca.area_id,
                        ca.area_name
                    FROM base_courses c
                    CROSS JOIN configured_areas ca
                ),
                questions_dataset AS (
                    SELECT 
                        cas.course_id,
                        cas.course_name,
                        FALSE AS apply_text,
                        cas.area_id,
                        cas.area_name,
                        COALESCE(MAX(tmc.amount_question), 0) AS total_amount
                    FROM course_area_skeleton cas
                    LEFT JOIN type_material_area tma 
                        ON tma.area_id = cas.area_id 
                        AND tma.type_material_id = p_type_material_id 
                        AND tma.fl_status = TRUE
                    LEFT JOIN type_material_area_courses tmac 
                        ON tmac.type_material_area_id = tma.id
                    LEFT JOIN type_material_course tmc 
                        ON tmc.id = tmac.type_material_course_id 
                        AND tmc.course_id = cas.course_id 
                        AND tmc.fl_status = TRUE
                    GROUP BY cas.course_id, cas.course_name, cas.area_id, cas.area_name
                ),
                texts_dataset AS (
                    SELECT 
                        cas.course_id,
                        cas.course_name,
                        TRUE AS apply_text,
                        cas.area_id,
                        cas.area_name,
                        COALESCE(MAX(
                            CASE 
                                WHEN ttmtca.type_material_id IS NOT NULL THEN tmc.amount_text
                                ELSE 0 
                            END
                        ), 0) AS total_amount
                    FROM course_area_skeleton cas
                    LEFT JOIN type_material_area tma 
                        ON tma.area_id = cas.area_id 
                        AND tma.type_material_id = p_type_material_id 
                        AND tma.fl_status = TRUE
                    LEFT JOIN type_material_area_courses tmac 
                        ON tmac.type_material_area_id = tma.id
                    LEFT JOIN type_material_course tmc 
                        ON tmc.id = tmac.type_material_course_id 
                        AND tmc.course_id = cas.course_id
                        AND tmc.fl_status = TRUE
                    LEFT JOIN type_text_material_type_course_area ttmtca 
                        ON ttmtca.type_material_id = p_type_material_id
                        AND ttmtca.course_id = cas.course_id
                        AND ttmtca.exam_area_id = cas.area_id
                        AND ttmtca.deleted_at IS NULL
                    WHERE cas.course_apply_text IS TRUE
                    GROUP BY cas.course_id, cas.course_name, cas.area_id, cas.area_name
                ),
                combined_data AS (
                    SELECT * FROM questions_dataset
                    UNION ALL
                    SELECT * FROM texts_dataset
                )
                SELECT
                    cd.course_id,
                    cd.course_name,
                    cd.apply_text,
                    jsonb_agg(
                        jsonb_build_object(
                            'exam_area_id', cd.area_id,
                            'exam_area_name', cd.area_name,
                            'total_question', cd.total_amount,
                            'levels', CASE 
                                WHEN cd.apply_text = FALSE THEN (
                                    SELECT jsonb_agg(
                                        jsonb_build_object(
                                            'id', l.id,
                                            'name', l.name,
                                            'description', l.description,
                                            'amount_question', 0
                                        ) ORDER BY l.description
                                    )
                                    FROM course_level cl
                                    JOIN level l ON cl.level_id = l.id
                                    WHERE cl.course_id = cd.course_id
                                        AND cl.fl_status = TRUE AND l.deleted_at IS NULL AND l.fl_status = TRUE
                                )
                                ELSE (
                                    SELECT jsonb_agg(
                                        jsonb_build_object(
                                            'id', tl.id,
                                            'name', tl.level,
                                            'description', tl.description,
                                            'amount_question', 0
                                        ) ORDER BY tl.description
                                    ) 
                                    FROM type_text_level tl
                                    WHERE tl.deleted_at IS NULL
                                )
                            END
                        ) ORDER BY cd.area_name
                    ) AS exam_area,
                    MAX(co.position) AS position_course
                FROM combined_data cd
                LEFT JOIN course_ordering co ON cd.course_id = co.course_id
                GROUP BY 
                    cd.course_id, 
                    cd.course_name, 
                    cd.apply_text
                ORDER BY 
                    MAX(co.position) ASC, 
                    UNACCENT(cd.course_name) ASC, 
                    cd.apply_text;
            END;
            $$;


ALTER FUNCTION odiseo.fn_get_course_and_exam_area(p_type_material_id bigint) OWNER TO postgres;

--
-- Name: fn_get_course_by_syllabus(smallint, bigint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_course_by_syllabus(p_university_id smallint, p_cycle_id bigint, p_company_id bigint, p_employee_id bigint DEFAULT NULL::bigint) RETURNS TABLE(id smallint, code character varying, name character varying, course text, quantity bigint, fl_template boolean, is_pseudo boolean, apply_text boolean, is_syllabus boolean, type_text_template_id smallint)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY
                    SELECT DISTINCT
                        c.id,
                        c.code,
                        c.name,
                        CONCAT(c.code, ' - ', c.name) AS course,
                        COALESCE(syllab_count.quantity, 0) as quantity,
                        CASE
                            WHEN syllab_count.quantity > 0
                                THEN true
                                ELSE false
                        END AS fl_template,
                        c.fl_pseudo_course AS is_pseudo,
                        c.apply_text,
                        CASE
                            WHEN syllab_course.course_id IS NOT NULL
                                THEN true
                                ELSE false
                        END AS is_syllabus,
                        c.type_text_template_id
                    FROM course c
                    LEFT JOIN employee_course ec ON ec.course_id = c.id AND ec.fl_status IS true
                    LEFT JOIN (
                        SELECT
                            course_id, COUNT(*) AS quantity
                        FROM syllabus_template st
                        WHERE (p_university_id IS null OR st.university_id = p_university_id)
                        AND st.fl_status = true
                        AND st.company_id = p_company_id
                        GROUP BY course_id
                    ) syllab_count ON syllab_count.course_id = c.id
                    LEFT JOIN (
                        SELECT
                            course_id, COUNT(*) AS quantity
                        FROM syllabus s
                        WHERE s.university_id = p_university_id
                            AND s.cycle_id = p_cycle_id
                            AND s.fl_status = true
                            AND s.company_id = p_company_id
                        GROUP BY course_id
                    ) syllab_course ON syllab_course.course_id = c.id
                    WHERE 1 = 1
                        AND (p_employee_id IS null OR ec.teacher_id = p_employee_id)
                        AND c.fl_status = true
                    ORDER BY course ASC, c.id ASC;
                END;
                $$;


ALTER FUNCTION odiseo.fn_get_course_by_syllabus(p_university_id smallint, p_cycle_id bigint, p_company_id bigint, p_employee_id bigint) OWNER TO postgres;

--
-- Name: fn_get_course_categories(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_course_categories(p_course_id bigint) RETURNS TABLE(id bigint, category_name character varying, category_assigned_id bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT t.id, t.name AS category_name, c.id AS category_assigned_id
    FROM course_assigned_categories c
    JOIN type_text t ON c.type_text_id = t.id
    WHERE c.course_id = p_course_id AND c.deleted_at IS NULL;
END;
$$;


ALTER FUNCTION odiseo.fn_get_course_categories(p_course_id bigint) OWNER TO postgres;

--
-- Name: fn_get_course_exam_areas_by_config_exam_material_id(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_course_exam_areas_by_config_exam_material_id(p_exam_material_config_id bigint, p_company_id bigint) RETURNS TABLE(course_id smallint, course_name character varying, apply_text boolean, exam_area jsonb, position_course smallint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH course_ordering AS (
        SELECT DISTINCT
            emc.type_material_id,
            tmc.course_id,
            course_ordering.position
        FROM exam_material_configurations emc
        LEFT JOIN type_material_course tmc ON emc.type_material_id = tmc.type_material_id
        INNER JOIN type_material tm ON emc.type_material_id = tm.id
        LEFT JOIN (
            SELECT
                ttmco.course_id,
                tm.id AS type_material_id,
                tm.type_material_template_id,
                ttmco.position,
                ttmco.university_id
            FROM template_type_material_courses_order ttmco
            INNER JOIN type_material tm
                ON tm.type_material_template_id = ttmco.template_type_material_id
            WHERE ttmco.university_id IS NULL
        ) AS course_ordering
            ON course_ordering.type_material_template_id = tm.type_material_template_id
            AND course_ordering.course_id = tmc.course_id
        WHERE emc.id =  p_exam_material_config_id
        AND emc.company_id = p_company_id
    ), get_type_material AS (
        SELECT
            DISTINCT type_material_id
        FROM course_ordering
    ), tbl_exam_material_configurations_level AS (
        SELECT
            emcac.course_id,
            emcac.exam_area_id,
            emcacl.level_id,
            emcacl.amount_question,
            emcacl.id config_id,
            emcac.amount_type_d
        FROM exam_material_configurations emc
        LEFT JOIN exam_material_config_area_courses emcac ON emcac.exam_material_config_id = emc.id
        LEFT JOIN exam_material_config_area_course_levels emcacl
            ON emcac.id = emcacl.exam_material_config_area_course_id AND emcacl.fl_status = true
        WHERE emc.id = p_exam_material_config_id
    ), type_text_levels AS (
            SELECT
                id,
                level AS name,
                description,
                0 AS amount_text
            FROM type_text_level WHERE deleted_at IS NULL
    ), type_material_area_with_courses AS (
        SELECT
            c.id AS course_id,
            c.name AS course_name,
            tma.area_id AS area_id,
            tma.type_material_id AS type_material_id
        FROM course c
        CROSS JOIN type_material_area tma
        WHERE 1 = 1
        AND c.apply_text IS TRUE
        AND tma.deleted_at IS NULL
        AND tma.fl_status IS TRUE
        AND tma.type_material_id IN ( SELECT we.type_material_id FROM get_type_material we )
    ), type_material_area_and_courses AS (
        SELECT
            tmc.course_id,
            tma.area_id,
            tmc.amount_question,
            tmc.amount_text
        FROM type_material_area_courses tmac
        LEFT JOIN type_material_course tmc ON tmac.type_material_course_id = tmc.id AND tmc.fl_status IS TRUE
        LEFT JOIN type_material_area tma ON tmac.type_material_area_id = tma.id
        JOIN course c ON c.id = tmc.course_id
        WHERE 1 = 1
        AND c.apply_text IS TRUE
        AND tmc.type_material_id IN ( SELECT gg.type_material_id FROM get_type_material gg )
    ), ultimate_type_material_area_courses AS (
        SELECT
            taw.course_id,
            taw.course_name,
            taw.area_id,
            COALESCE(tyc.amount_question, 0) AS amount_question,
            COALESCE(tyc.amount_text, 0) AS amount_text
        FROM type_material_area_with_courses taw
        LEFT JOIN type_material_area_and_courses tyc ON taw.area_id = tyc.area_id AND taw.course_id = tyc.course_id
    ), type_text_exam_course AS (
        SELECT
            ut.course_id,
            ut.course_name,
            TRUE AS apply_text,
            JSONB_AGG(
                JSONB_BUILD_OBJECT(
                    'exam_area_id', ut.area_id,
                    'exam_area_name', ea.description,
                    'total_question', ut.amount_text, -- Esta es la cantidad de textos
                    'levels', ( SELECT JSONB_AGG(
                        JSON_BUILD_OBJECT(
                            'id', tl.id,
                            'name', tl.name,
                            'description', tl.description,
                            'amount_question',
                                CASE
                                    WHEN ut.amount_text = 0 OR ut.amount_text IS NULL THEN 0
                                    WHEN emc.text_amount IS NULL THEN 0 
                                    ELSE emc.text_amount
                                END -- <-- Evita traer montos mayores a cero en niveles individuales cuando el monto total fue desactivado desde tipo de material
                        ) ORDER BY tl.description )
                        FROM type_text_levels tl
                        LEFT JOIN type_text_exam_material_configuration emc
                        ON 1 = 1
                        AND emc.exam_material_config_id = p_exam_material_config_id
                        AND emc.course_id = ut.course_id
                        AND emc.area_id = ut.area_id
                        AND emc.type_text_level_id = tl.id
                    )
                ) ORDER BY ea.description
            ) AS exam_area
        FROM ultimate_type_material_area_courses ut
        JOIN exam_area ea ON ea.id = ut.area_id
        GROUP BY ut.course_id, ut.course_name
    ), exam_course AS (
        SELECT
            c.id AS course_id,
            c.name AS course_name,
            FALSE AS apply_text,
            jsonb_agg(
                jsonb_build_object(
                    'exam_area_id', ea.id,
                    'exam_area_name', ea.description,
                    'amount_type_d', (
                        SELECT COALESCE((
                            SELECT emcac.amount_type_d
                            FROM exam_material_configurations emc
                            INNER JOIN exam_material_config_area_courses emcac ON emc.id = emcac.exam_material_config_id
                            WHERE emc.id = p_exam_material_config_id
                                AND emcac.exam_area_id = ea.id
                                AND emcac.fl_status = true
                                AND emcac.course_id = c.id
                            LIMIT 1
                        ), NULL::INT)
                    ),
                    'total_question', (
                        SELECT COALESCE((
                            SELECT tmc.amount_question
                            FROM type_material_area_courses tmac
                            LEFT JOIN type_material_area tma ON tmac.type_material_area_id = tma.id
                            LEFT JOIN type_material_course tmc ON tmac.type_material_course_id = tmc.id
                            LEFT JOIN exam_material_configurations emc ON emc.type_material_id = tma.type_material_id
                            WHERE emc.id = p_exam_material_config_id
                                AND tma.area_id = ea.id
                                AND tmc.course_id = c.id
                                AND tma.fl_status = TRUE
                                AND tmc.fl_status = TRUE
                                AND tmac.fl_status = TRUE
                                AND emc.fl_status = TRUE
                        ), 0)
                    ),
                    'levels', (
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'id', l.id,
                                'name', l.name,
                                'description', l.description,
                                'amount_question', COALESCE(emcacl.amount_question, 0),
                                'config_id', emcacl.config_id
                            ) ORDER BY l.description
                        )
                        FROM course_level cl
                        LEFT JOIN level l ON cl.level_id = l.id
                        LEFT JOIN tbl_exam_material_configurations_level emcacl ON emcacl.course_id = c.id
                            AND emcacl.level_id = l.id
                            AND emcacl.exam_area_id = ea.id
                        WHERE cl.course_id = c.id
                            AND cl.fl_status = TRUE
                            AND l.fl_status = TRUE
                    )
                ) ORDER BY ea.description
            ) AS exam_area
        FROM course c
        CROSS JOIN exam_area ea
        JOIN type_material_area tma ON tma.type_material_id IN ( SELECT type_material_id FROM get_type_material ) AND tma.area_id = ea.id AND tma.fl_status IS TRUE -- <-- Traer solo las areas activas en tipo de material
        WHERE ea.fl_status = TRUE
            AND ea.deleted_at IS NULL
            AND c.deleted_at IS NULL
            AND c.fl_status = TRUE
        GROUP BY
            c.id, c.name
    ), merge_text_amounts_and_question_amounts AS (
        SELECT * FROM type_text_exam_course
        UNION ALL
        SELECT * FROM exam_course
    ) SELECT
        ccem.*,
        co.position AS position_course
    FROM merge_text_amounts_and_question_amounts ccem
    LEFT JOIN course_ordering co ON ccem.course_id = co.course_id
    ORDER BY co.position ASC, UNACCENT(ccem.course_name) ASC, ccem.apply_text;
END;
$$;


ALTER FUNCTION odiseo.fn_get_course_exam_areas_by_config_exam_material_id(p_exam_material_config_id bigint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_get_course_material_details(smallint, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_course_material_details(p_course_id smallint, p_week integer, p_cycle_id integer) RETURNS TABLE(type_material_id smallint, type_material text, is_generic boolean, is_generic_text boolean, amount_question integer, amount_text integer, subquestions jsonb)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY
                    SELECT 
                        tm.id AS type_material_id,
                        tmt.name::TEXT AS type_material,
                        tmc.is_generic,
                        tmc.is_generic_text,
                        CASE 
                            WHEN tmc.is_generic = true THEN tmc.amount_question
                            ELSE COALESCE(tmdc.amount_question, 0)
                        END AS final_amount_question,
                        
                        CASE 
                            WHEN tmc.is_generic_text = true THEN tmc.amount_text
                            ELSE COALESCE(tmdct.amount_text, 0)
                        END AS final_amount_text,

                        CASE 
                            WHEN tmc.is_generic_text = true THEN (
                                SELECT jsonb_agg(
                                    jsonb_build_object(
                                        'position', ttmtc.position, 
                                        'subquestion_amount', ttmtc.subquestion_amount
                                    ) ORDER BY ttmtc.position
                                )
                                FROM type_text_material_type_course ttmtc 
                                WHERE ttmtc.type_material_id = tm.id 
                                AND ttmtc.course_id = tmc.course_id 
                                AND ttmtc.deleted_at IS NULL
                            )
                            ELSE (
                                SELECT jsonb_agg(
                                    jsonb_build_object(
                                        'position', sq.position, 
                                        'subquestion_amount', sq.subquestion_amount
                                    ) ORDER BY sq.position
                                )
                                FROM type_material_detail_text_subquestions sq
                                WHERE sq.type_material_detail_course_text_id = tmdct.id 
                                AND sq.deleted_at IS NULL
                            )
                        END AS subquestions

                    FROM type_material tm
                    JOIN type_material_template tmt ON tmt.id = tm.type_material_template_id
                    JOIN type_material_detail_template tmdt ON tmdt.type_material_id = tm.id
                    JOIN type_material_course tmc ON tmc.type_material_id = tm.id
                    LEFT JOIN type_material_detail_courses tmdc ON tmdc.type_material_course_id = tmc.id 
                        AND tmdc.type_material_detail_template_id = tmdt.id
                    LEFT JOIN type_material_detail_course_texts tmdct ON tmdct.type_material_course_id = tmc.id 
                        AND tmdct.type_material_detail_template_id = tmdt.id
                    WHERE tm.cycle_id = p_cycle_id
                    AND tmc.course_id = p_course_id
                    AND tmdt.week = p_week
                    AND tm.fl_exam = false
                    AND tm.fl_status = true
                    AND (
                        tm.parent_id IS NOT NULL
                        OR
                        tm.id NOT IN (SELECT parent_id FROM type_material WHERE cycle_id = p_cycle_id AND parent_id IS NOT NULL)
                    )
                    ORDER BY tmt.name
                    ;
                END;
                $$;


ALTER FUNCTION odiseo.fn_get_course_material_details(p_course_id smallint, p_week integer, p_cycle_id integer) OWNER TO postgres;

--
-- Name: fn_get_course_materials_by_type(smallint, boolean, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_course_materials_by_type(p_type_material_id smallint, p_is_text boolean, p_courses jsonb DEFAULT NULL::jsonb) RETURNS TABLE(configured_amount integer, type_material_id smallint, course_id smallint, course_name character varying, type_material_name character varying)
    LANGUAGE sql STABLE
    AS $$
        SELECT
            CASE
                WHEN p_is_text = TRUE THEN tmc.amount_text
                ELSE tmc.amount_question
            END AS configured_amount,
            tmc.type_material_id,
            c.id AS course_id,
            c.name AS course_name,
            tm.description AS type_material_name
        FROM type_material_course AS tmc
        INNER JOIN course AS c ON tmc.course_id = c.id
        INNER JOIN type_material AS tm ON tm.id = tmc.type_material_id
        WHERE
            tmc.type_material_id = p_type_material_id
            AND (p_is_text IS FALSE OR tmc.amount_text > 0)
            AND (
                p_courses IS NULL
                OR c.id IN (
                    SELECT value::BIGINT
                    FROM jsonb_array_elements_text(p_courses)
                )
            );
    $$;


ALTER FUNCTION odiseo.fn_get_course_materials_by_type(p_type_material_id smallint, p_is_text boolean, p_courses jsonb) OWNER TO postgres;

--
-- Name: fn_get_courses_by_employee_of_syllabus(smallint, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_courses_by_employee_of_syllabus(p_employee_id smallint, p_cycle_id smallint, p_university_id smallint) RETURNS TABLE(id smallint, code character varying, name character varying, fl_template boolean)
    LANGUAGE plpgsql
    AS $$
            BEGIN
            RETURN QUERY
            select tbl_courses.id,tbl_courses.code,tbl_courses.name,tbl_courses.fl_template
            FROM
            (
                SELECT DISTINCT
                c.id,
                c.code,
                c."name",
                CASE
                    WHEN COALESCE(tbl_syllabus.total, 0) > 0 THEN true
                    ELSE false
                END AS fl_template
            FROM
                odiseo.employee_course ec
            LEFT JOIN
                odiseo.course c ON ec.course_id = c.id
            LEFT JOIN (
                SELECT
                    s.course_id,
                    COUNT(*) AS total
                FROM
                    odiseo.syllabus s
                WHERE
                    s.fl_status = true
                    AND s.deleted_at IS null AND
                    s.cycle_id = p_cycle_id AND
                    s.university_id  = p_university_id
                GROUP BY
                    s.course_id
            ) AS tbl_syllabus ON c.id = tbl_syllabus.course_id
            WHERE
                ec.fl_status = true
                AND c.fl_status = true
                AND ec.deleted_at IS NULL
                AND c.deleted_at IS NULL
                AND (p_employee_id IS NULL OR ec.teacher_id = p_employee_id)
            ) as tbl_courses
            order by   tbl_courses.fl_template desc, unaccent(tbl_courses.name)
                ;
            END;
        $$;


ALTER FUNCTION odiseo.fn_get_courses_by_employee_of_syllabus(p_employee_id smallint, p_cycle_id smallint, p_university_id smallint) OWNER TO postgres;

--
-- Name: fn_get_courses_by_type_material(smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_courses_by_type_material(p_type_material_id smallint) RETURNS TABLE(course_id bigint, course_name character varying)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                -- 1. Verificamos si existe una configuración de ordenamiento personalizada
                IF EXISTS (
                    SELECT 1
                    FROM template_type_material_courses_order ttmco
                    JOIN type_material_template tmt ON ttmco.template_type_material_id = tmt.id
                    JOIN type_material tm ON tm.type_material_template_id = tmt.id
                    WHERE tm.id = p_type_material_id
                ) THEN
                    -- CASO A: Retornar cursos ordenados por la plantilla
                    RETURN QUERY
                    SELECT
                        c.id::BIGINT,
                        c.name::varchar
                    FROM template_type_material_courses_order ttmco
                    JOIN course c ON c.id = ttmco.course_id
                    JOIN type_material_template tmt ON ttmco.template_type_material_id = tmt.id
                    JOIN type_material tm ON tm.type_material_template_id = tmt.id
                    WHERE tm.id = p_type_material_id
                    AND ttmco.university_id IS NULL
                    ORDER BY ttmco.position ASC, c.id ASC;
                ELSE
                    -- Validar si el tipo material es padre
                    RETURN QUERY
                    WITH type_materials AS (
                        SELECT
                            CASE WHEN EXISTS (
                                SELECT 1 FROM type_material tm
                                WHERE tm.parent_id = p_type_material_id) THEN
                                ARRAY (
                                    SELECT tm.id FROM type_material tm WHERE tm.parent_id = p_type_material_id
                                )
                            ELSE
                                ARRAY[p_type_material_id]
                            END AS ids
                    ), type_material_ids AS (
                        SELECT UNNEST(tm.ids) AS id FROM type_materials tm
                    ), get_courses AS (
                        SELECT DISTINCT
                            c.id::BIGINT,
                            c.name::varchar
                        FROM type_material_course tmc
                        JOIN course c ON c.id = tmc.course_id
                        WHERE tmc.type_material_id IN (SELECT tmi.id FROM type_material_ids tmi)
                    )
                    SELECT * FROM get_courses ORDER BY id ASC;
                END IF;

            END;
            $$;


ALTER FUNCTION odiseo.fn_get_courses_by_type_material(p_type_material_id smallint) OWNER TO postgres;

--
-- Name: fn_get_courses_by_type_material_ballot(smallint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_courses_by_type_material_ballot(p_type_material_id smallint, p_company_id bigint, p_user_id bigint) RETURNS TABLE(id smallint, code_course character varying, course character varying)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                WITH tbl_type_material_template AS (
                    SELECT
                        tmt.type_material_template_id
                    FROM type_material tmt
                    WHERE tmt.id = p_type_material_id
                        AND tmt.company_id = p_company_id
                ), child_type_materials AS (
                    SELECT
                        tm.id
                    FROM type_material tm
                    WHERE tm.parent_id = p_type_material_id
                        AND tm.company_id = p_company_id
                ), get_type_material AS (
                    SELECT
                        ctm.id
                    FROM child_type_materials ctm

                    UNION ALL

                    SELECT tm.id
                    FROM type_material tm
                    WHERE tm.id = p_type_material_id
                        AND tm.company_id = p_company_id
                    AND NOT EXISTS (SELECT 1 FROM child_type_materials)
                ), get_courses AS (
                    -- cursos genericos
                    SELECT DISTINCT tmc.course_id
                    FROM odiseo.type_material_course tmc
                    WHERE tmc.type_material_id IN (SELECT gtm.id FROM get_type_material gtm)
                    AND tmc.is_generic IS TRUE
                    AND tmc.amount_question > 0
                    AND tmc.fl_status = TRUE

                    UNION ALL

                    -- cursos texto genericos
                    SELECT DISTINCT tmc.course_id
                    FROM odiseo.type_material_course tmc
                    WHERE tmc.type_material_id IN (SELECT gtm.id FROM get_type_material gtm)
                    AND tmc.is_generic_text IS TRUE
                    AND tmc.amount_text > 0
                    AND tmc.fl_status = TRUE

                    UNION ALL

                    -- cursos personalizados
                    SELECT DISTINCT tmdc.course_id
                    FROM odiseo.type_material_detail_courses tmdc
                    JOIN type_material_detail_template tmdt
                        ON tmdc.type_material_detail_template_id = tmdt.id
                    JOIN type_material_course tmc
                        ON tmdc.type_material_course_id = tmc.id
                    WHERE tmc.type_material_id IN (SELECT gtm.id FROM get_type_material gtm)
                    AND tmc.is_generic IS FALSE
                    AND tmdc.amount_question > 0
                    AND tmdc.fl_status = TRUE

                    UNION ALL

                    -- cursos textos personalizados
                    SELECT DISTINCT tmdct.course_id
                    FROM odiseo.type_material_detail_course_texts tmdct
                    JOIN type_material_detail_template tmdt
                        ON tmdct.type_material_detail_template_id = tmdt.id
                    JOIN type_material_course tmc
                        ON tmdct.type_material_course_id = tmc.id
                    WHERE tmc.type_material_id IN (SELECT gtm.id FROM get_type_material gtm)
                    AND tmc.is_generic_text IS FALSE
                    AND tmdct.amount_text > 0
                    AND tmdct.fl_status = TRUE
                ), get_courses_final AS (
                    SELECT DISTINCT
                        gc.course_id::SMALLINT AS id,
                        c.code AS code_course,
                        c.name AS course
                    FROM get_courses gc
                    JOIN course c ON gc.course_id = c.id
                ), validate_admin_user AS (
                    SELECT
                        u.id,
                        r.fl_administrator,
                        rp.permission_id
                    FROM users u
                    JOIN users_roles ur ON u.id = ur.user_id
                    JOIN roles r ON ur.rol_id = r.id
                    LEFT JOIN roles_permissions rp ON r.id = rp.rol_id
                        AND rp.permission_id = 133 -- 'admin.admin'
                    WHERE u.id = p_user_id
                ), get_courses_employees AS (
                    SELECT DISTINCT
                        ec.course_id
                    FROM employees e
                    JOIN employee_course ec ON e.id = ec.teacher_id
                    WHERE e.user_id = p_user_id
                        AND ec.fl_status = true
                        AND NOT EXISTS (
                            SELECT 1
                            FROM validate_admin_user vau
                            WHERE vau.permission_id = 133
                        )

                    UNION ALL

                    SELECT
                        c.id
                    FROM course c
                    WHERE c.fl_status = true
                    AND EXISTS (
                            SELECT 1
                            FROM validate_admin_user vau
                            WHERE vau.permission_id = 133
                        )
                )
                SELECT
                    gcf.id,
                    gcf.code_course,
                    gcf.course
                FROM get_courses_final gcf
                WHERE gcf.id IN (
                    SELECT
                        gce.course_id
                    FROM get_courses_employees gce
                )
                ORDER BY
                    gcf.code_course,
                    gcf.course;
            END;
            $$;


ALTER FUNCTION odiseo.fn_get_courses_by_type_material_ballot(p_type_material_id smallint, p_company_id bigint, p_user_id bigint) OWNER TO postgres;

--
-- Name: fn_get_courses_with_questions(bigint, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_courses_with_questions(p_material_per_period_ballot_id bigint, p_courses jsonb) RETURNS TABLE(id smallint, name character varying)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        WITH details_weeks AS (
            SELECT dw.week, dw.detail_ids
            FROM fn_get_available_weeks_per_period(p_material_per_period_ballot_id) dw
        ), courses_generate_material AS (
            SELECT DISTINCT
                mbq.course_id
            FROM detail_week_type_mat dwtm
            JOIN details_weeks dw
                ON dwtm.id = ANY (
                    SELECT value::BIGINT
                    FROM jsonb_array_elements_text(dw.detail_ids::jsonb) value
                )
            JOIN material_ballot_question mbq ON dwtm.id = mbq.week_type_material_id
                AND mbq.fl_status = true
        )
        SELECT
            cgm.course_id AS id,
            c.name
        FROM courses_generate_material cgm
        JOIN course c ON cgm.course_id = c.id
        WHERE (p_courses IS NULL OR
            cgm.course_id = ANY (
                SELECT value::SMALLINT FROM jsonb_array_elements_text(p_courses::jsonb)
            )
        );
    END;
    $$;


ALTER FUNCTION odiseo.fn_get_courses_with_questions(p_material_per_period_ballot_id bigint, p_courses jsonb) OWNER TO postgres;

--
-- Name: fn_get_cycle_by_material(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_cycle_by_material(p_material_id bigint, p_company_id bigint) RETURNS TABLE(id bigint, start_date date)
    LANGUAGE plpgsql STABLE
    AS $$
                BEGIN
                    RETURN QUERY
                    SELECT
                        c.id,
                        c.start_date
                    FROM material m
                    INNER JOIN cycle c ON c.id = m.cycle_id
                        AND c.company_id = p_company_id
                        AND c.fl_status = true
                    WHERE m.id = p_material_id
                        AND m.company_id = p_company_id
                    LIMIT 1;
                END;
                $$;


ALTER FUNCTION odiseo.fn_get_cycle_by_material(p_material_id bigint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_get_cycles_actives(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_cycles_actives(p_company_id bigint) RETURNS TABLE(id bigint, description character varying, weeks integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        c.id, 
        c.description, 
        COUNT(cw.id) FILTER (WHERE tw.description != 'Inactiva' AND cw.id IS NOT NULL)::int as weeks
    FROM cycle c
    LEFT JOIN cycle_weeks cw ON cw.cycle_id = c.id AND cw.fl_status = true AND cw.deleted_at IS NULL
    LEFT JOIN type_week tw ON tw.id = cw.type_week_id
    WHERE c.company_id = p_company_id
      AND c.fl_status = true
      AND c.active = true
    GROUP BY c.id, c.description, c.created_at
    ORDER BY c.created_at DESC;
END;
$$;


ALTER FUNCTION odiseo.fn_get_cycles_actives(p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_get_detail_course_diagram(smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_detail_course_diagram(p_course_id smallint, p_category_id smallint) RETURNS TABLE(id bigint, setting_diagrammed_courses_id bigint, name_field_diagram character varying, "position" smallint, fl_active boolean, fl_optional boolean, fl_show_in_material_without_solution boolean, fl_show_in_material_with_solution boolean)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                RETURN QUERY
                SELECT
                    fd.id,
                    sdc.id setting_diagrammed_courses_id,
                    fd."name" name_field_diagram,
                    sdc."position",
                    sdc.fl_active,
                    sdc.fl_optional,
                    ctcs.fl_show_in_material_without_solution,
                    ctcs.fl_show_in_material_with_solution
                FROM setting_diagrammed_courses sdc
                LEFT JOIN field_diagrammed fd ON fd.id = sdc.field_diagram_id
                LEFT JOIN course_text_category_settings ctcs ON ctcs.type_text_id = sdc.category_text_id 
                AND sdc.course_id = ctcs.course_id
                WHERE sdc.course_id = p_course_id
                AND CASE
                    WHEN p_category_id IS NULL THEN sdc.category_text_id IS NULL
                    ELSE sdc.category_text_id = p_category_id
                END
                AND sdc.fl_status = TRUE
                ORDER BY sdc."position";
                END;
            $$;


ALTER FUNCTION odiseo.fn_get_detail_course_diagram(p_course_id smallint, p_category_id smallint) OWNER TO postgres;

--
-- Name: fn_get_detail_exam_questions_by_area_courses(integer, integer, character varying, character varying, smallint, smallint, bigint, smallint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_detail_exam_questions_by_area_courses(p_perpage integer, p_npage integer, p_search character varying, p_source character varying, p_course_id smallint, p_type_material_id smallint, p_material_id bigint, p_week smallint, p_area character varying) RETURNS TABLE(area_name character varying, id bigint, description text, status character varying, course character varying, code character varying, source text, is_duplicated boolean, type_question text, exam_area character varying, exam_areas jsonb, total bigint)
    LANGUAGE plpgsql
    AS $$
                        DECLARE
                            offset_val INTEGER;
                            v_detail_id BIGINT;
                        BEGIN
                            offset_val := p_perpage * (p_npage - 1);

                            SELECT dwtm.id INTO v_detail_id
                            FROM detail_week_type_mat dwtm
                            WHERE dwtm.material_id = p_material_id
                            AND dwtm.type_material_id = p_type_material_id
                            AND dwtm.week = p_week
                            AND dwtm.fl_status IS TRUE
                            LIMIT 1;

                            RETURN QUERY
                            WITH exploded_questions AS (
                                SELECT
                                    mac.id AS material_exam_stat_course_id,
                                    mac.area_stats_id,
                                    ma.area_name,
                                    q.id AS question_id,
                                    q.short_description,
                                    q.code,
                                    q.status,
                                    c.name AS course,
                                    mac.course_id,
                                    'new_questions' AS source,
                                    FALSE AS is_duplicated,
                                    CASE
                                        WHEN q.parent_id IS NULL THEN 'P'
                                        ELSE 'S'
                                    END AS type_question,
                                    ea.description exam_area,
                                    NULL::jsonb AS exam_areas
                                FROM material_exam_stats_area_courses mac
                                JOIN material_exam_stats_areas ma ON ma.id = mac.area_stats_id
                                JOIN LATERAL jsonb_array_elements(mac.question_details->'questions_new_questions') qj ON TRUE
                                JOIN question q ON q.id = (qj->>'id')::BIGINT
                                JOIN exam_area ea ON ea.id = (qj->>'exam_area_id')::BIGINT
                                JOIN course c ON c.id = q.course_id
                                JOIN material_exam_stats_global mesg ON mesg.id = ma.material_exam_stats_global_id 
                                JOIN detail_week_type_mat dwtm ON dwtm.id = mesg.detail_week_type_mat_id
                                WHERE dwtm.id = v_detail_id

                                UNION ALL

                                -- REPETIDAS POR ÁREA
                                SELECT
                                    mac.id,
                                    mac.area_stats_id,
                                    ma.area_name,
                                    q.id AS question_id,
                                    q.short_description,
                                    q.code,
                                    q.status,
                                    c.name AS course,
                                    mac.course_id,
                                    'repeated_area',
                                    TRUE,
                                    CASE
                                        WHEN q.parent_id IS NULL THEN 'P'
                                        ELSE 'S'
                                    END AS type_question,
                                    NULL::varchar,
                                    (qj->>'exam_areas')::jsonb
                                FROM material_exam_stats_area_courses mac
                                JOIN material_exam_stats_areas ma ON ma.id = mac.area_stats_id
                                JOIN LATERAL jsonb_array_elements(mac.question_details->'questions_repeated_area') qj ON TRUE
                                JOIN question q ON q.id = (qj->>'id')::BIGINT
                                JOIN course c ON c.id = q.course_id
                                JOIN material_exam_stats_global mesg ON mesg.id = ma.material_exam_stats_global_id 
                                JOIN detail_week_type_mat dwtm ON dwtm.id = mesg.detail_week_type_mat_id
                                WHERE dwtm.id = v_detail_id

                                UNION ALL

                                -- REPETIDAS POR AÑO
                                SELECT
                                    mac.id,
                                    mac.area_stats_id,
                                    ma.area_name,
                                    q.id AS question_id,
                                    q.short_description,
                                    q.code,
                                    q.status,
                                    c.name AS course,
                                    mac.course_id,
                                    'repeated_year',
                                    TRUE,
                                    CASE
                                        WHEN q.parent_id IS NULL THEN 'P'
                                        ELSE 'S'
                                    END AS type_question,
                                    ea.description exam_area,
                                    NULL::jsonb AS exam_areas
                                FROM material_exam_stats_area_courses mac
                                JOIN material_exam_stats_areas ma ON ma.id = mac.area_stats_id
                                JOIN LATERAL jsonb_array_elements(mac.question_details->'questions_repeated_year') qj ON TRUE
                                JOIN question q ON q.id = (qj->>'id')::BIGINT
                                JOIN exam_area ea ON ea.id = (qj->>'exam_area_id')::BIGINT
                                JOIN course c ON c.id = q.course_id
                                JOIN material_exam_stats_global mesg ON mesg.id = ma.material_exam_stats_global_id 
                                JOIN detail_week_type_mat dwtm ON dwtm.id = mesg.detail_week_type_mat_id
                                WHERE dwtm.id = v_detail_id

                                UNION ALL

                                -- REPETIDAS HISTÓRICAS
                                SELECT
                                    mac.id,
                                    mac.area_stats_id,
                                    ma.area_name,
                                    q.id AS question_id,
                                    q.short_description,
                                    q.code,
                                    q.status,
                                    c.name AS course,
                                    mac.course_id,
                                    'repeated_history',
                                    TRUE,
                                    CASE
                                        WHEN q.parent_id IS NULL THEN 'P'
                                        ELSE 'S'
                                    END AS type_question,
                                    ea.description exam_area,
                                    NULL::jsonb AS exam_areas
                                FROM material_exam_stats_area_courses mac
                                JOIN material_exam_stats_areas ma ON ma.id = mac.area_stats_id
                                JOIN LATERAL jsonb_array_elements(mac.question_details->'questions_repeated_history') qj ON TRUE
                                JOIN question q ON q.id = (qj->>'id')::BIGINT
                                JOIN exam_area ea ON ea.id = (qj->>'exam_area_id')::BIGINT
                                JOIN course c ON c.id = q.course_id
                                JOIN material_exam_stats_global mesg ON mesg.id = ma.material_exam_stats_global_id 
                                JOIN detail_week_type_mat dwtm ON dwtm.id = mesg.detail_week_type_mat_id
                                WHERE dwtm.id = v_detail_id
                            ),
                            filtered AS (
                                SELECT *
                                FROM exploded_questions eq
                                WHERE
                                    (p_search IS NULL OR LOWER(eq.code) LIKE '%' || LOWER(p_search) || '%')
                                    AND CASE
                                        WHEN p_source IS NULL THEN eq.source != 'repeated_area'
                                        ELSE eq.source = p_source
                                    END
                                    AND (p_course_id IS NULL OR eq.course_id = p_course_id)
                                    AND eq.area_name = p_area
                                ORDER BY eq.exam_area, eq.course_id, eq.question_id
                            )
                            SELECT
                                f.area_name,
                                f.question_id id,
                                f.short_description description,
                                f.status,
                                f.course,
                                f.code,
                                f.source,
                                f.is_duplicated,
                                f.type_question,
                                f.exam_area,
                                f.exam_areas,
                                COUNT(*) OVER () AS total
                            FROM filtered f
                            LIMIT p_perpage OFFSET offset_val;

                        END;
                        $$;


ALTER FUNCTION odiseo.fn_get_detail_exam_questions_by_area_courses(p_perpage integer, p_npage integer, p_search character varying, p_source character varying, p_course_id smallint, p_type_material_id smallint, p_material_id bigint, p_week smallint, p_area character varying) OWNER TO postgres;

--
-- Name: fn_get_detail_exam_questions_by_areas(integer, integer, character varying, character varying, smallint, smallint, bigint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_detail_exam_questions_by_areas(p_perpage integer, p_npage integer, p_search character varying, p_source character varying, p_area_id smallint, p_type_material_id smallint, p_material_id bigint, p_week smallint) RETURNS TABLE(area character varying, area_id bigint, id bigint, description text, status character varying, course character varying, code character varying, source text, is_duplicated boolean, type_question text, exam_area character varying, exam_areas jsonb, total bigint)
    LANGUAGE plpgsql
    AS $$
                        DECLARE
                            offset_val INTEGER;
                            v_detail_id BIGINT;
                        BEGIN
                            offset_val := p_perpage * (p_npage - 1);

                            SELECT dwtm.id INTO v_detail_id
                            FROM detail_week_type_mat dwtm
                            WHERE dwtm.material_id = p_material_id
                            AND dwtm.type_material_id = p_type_material_id
                            AND dwtm.week = p_week
                            AND dwtm.fl_status IS TRUE
                            LIMIT 1;

                            RETURN QUERY
                            WITH exploded_questions AS (
                                -- 1. NEW QUESTIONS
                                SELECT
                                    m.id,
                                    m.area_name,
                                    m.area_id,
                                    q.id AS question_id,
                                    q.short_description,
                                    q.code,
                                    q.status,
                                    c.name course,
                                    c.id course_id,
                                    'new_questions' AS source,
                                    FALSE AS is_duplicated,
                                    CASE
                                        WHEN q.parent_id IS NULL THEN 'P'
                                        ELSE 'S'
                                    END AS type_question,
                                    ea.description::varchar AS exam_area, 
                                    NULL::jsonb AS exam_areas            
                                FROM material_exam_stats_areas m
                                JOIN LATERAL jsonb_array_elements(m.question_details->'questions_new_questions') qj ON TRUE
                                JOIN question q ON q.id = (qj->>'id')::BIGINT
                                JOIN exam_area ea ON ea.id = (qj->>'exam_area_id')::BIGINT
                                JOIN course c ON c.id = q.course_id
                                JOIN material_exam_stats_global mesg ON mesg.id = m.material_exam_stats_global_id 
                                JOIN detail_week_type_mat dwtm ON dwtm.id = mesg.detail_week_type_mat_id
                                WHERE dwtm.id = v_detail_id

                                UNION ALL

                                -- 2. REPETIDAS POR ÁREA
                                SELECT
                                    m.id,
                                    m.area_name,
                                    m.area_id,
                                    q.id AS question_id,
                                    q.short_description,
                                    q.code,
                                    q.status,
                                    c.name course,
                                    c.id course_id,
                                    'repeated_area',
                                    TRUE,
                                    CASE
                                        WHEN q.parent_id IS NULL THEN 'P'
                                        ELSE 'S'
                                    END AS type_question,
                                    NULL::varchar,          
                                    (qj->>'exam_areas')::jsonb  
                                FROM material_exam_stats_areas m
                                JOIN LATERAL jsonb_array_elements(m.question_details->'questions_repeated_area') qj ON TRUE
                                JOIN question q ON q.id = (qj->>'id')::BIGINT
                                JOIN course c ON c.id = q.course_id
                                JOIN material_exam_stats_global mesg ON mesg.id = m.material_exam_stats_global_id 
                                JOIN detail_week_type_mat dwtm ON dwtm.id = mesg.detail_week_type_mat_id
                                WHERE dwtm.id = v_detail_id

                                UNION ALL

                                -- 3. REPETIDAS POR AÑO
                                SELECT
                                    m.id,
                                    m.area_name,
                                    m.area_id,
                                    q.id AS question_id,
                                    q.short_description,
                                    q.code,
                                    q.status,
                                    c.name course,
                                    c.id course_id,
                                    'repeated_year',
                                    TRUE,
                                    CASE
                                        WHEN q.parent_id IS NULL THEN 'P'
                                        ELSE 'S'
                                    END AS type_question,
                                    ea.description::varchar,    
                                    NULL::jsonb                
                                FROM material_exam_stats_areas m
                                JOIN LATERAL jsonb_array_elements(m.question_details->'questions_repeated_year') qj ON TRUE
                                JOIN question q ON q.id = (qj->>'id')::BIGINT
                                JOIN exam_area ea ON ea.id = (qj->>'exam_area_id')::BIGINT
                                JOIN course c ON c.id = q.course_id
                                JOIN material_exam_stats_global mesg ON mesg.id = m.material_exam_stats_global_id 
                                JOIN detail_week_type_mat dwtm ON dwtm.id = mesg.detail_week_type_mat_id
                                WHERE dwtm.id = v_detail_id

                                UNION ALL

                                -- 4. REPETIDAS HISTÓRICAS
                                SELECT
                                    m.id,
                                    m.area_name,
                                    m.area_id,
                                    q.id AS question_id,
                                    q.short_description,
                                    q.code,
                                    q.status,
                                    c.name course,
                                    c.id course_id,
                                    'repeated_history',
                                    TRUE,
                                    CASE
                                        WHEN q.parent_id IS NULL THEN 'P'
                                        ELSE 'S'
                                    END AS type_question,
                                    ea.description::varchar,   
                                    NULL::jsonb     
                                FROM material_exam_stats_areas m
                                JOIN LATERAL jsonb_array_elements(m.question_details->'questions_repeated_history') qj ON TRUE
                                JOIN question q ON q.id = (qj->>'id')::BIGINT
                                JOIN exam_area ea ON ea.id = (qj->>'exam_area_id')::BIGINT
                                JOIN course c ON c.id = q.course_id
                                JOIN material_exam_stats_global mesg ON mesg.id = m.material_exam_stats_global_id 
                                JOIN detail_week_type_mat dwtm ON dwtm.id = mesg.detail_week_type_mat_id
                                WHERE dwtm.id = v_detail_id
                            ),
                            filtered AS (
                                SELECT 
                                    *
                                FROM exploded_questions eq
                                WHERE
                                    (p_search IS NULL OR LOWER(eq.code) LIKE '%' || LOWER(p_search) || '%')
                                    AND CASE
                                        WHEN p_source IS NULL THEN eq.source != 'repeated_area'
                                        ELSE eq.source = p_source
                                    END
                                    AND (p_area_id IS NULL OR eq.area_id = p_area_id)
                                ORDER BY eq.exam_area, eq.course_id, eq.id
                            )
                            SELECT
                                f.area_name area,
                                f.area_id,
                                f.question_id id,
                                f.short_description description,
                                f.status,
                                f.course,
                                f.code,
                                f.source,
                                f.is_duplicated,
                                f.type_question,
                                f.exam_area,
                                f.exam_areas,
                                COUNT(*) OVER () AS total
                            FROM filtered f
                            LIMIT p_perpage OFFSET offset_val;

                        END;
                        $$;


ALTER FUNCTION odiseo.fn_get_detail_exam_questions_by_areas(p_perpage integer, p_npage integer, p_search character varying, p_source character varying, p_area_id smallint, p_type_material_id smallint, p_material_id bigint, p_week smallint) OWNER TO postgres;

--
-- Name: fn_get_detail_level_parent_type_material_by_course(integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_detail_level_parent_type_material_by_course(p_cycle_id integer, p_week integer, p_course_id integer) RETURNS TABLE(course_id smallint, course character varying, level_course jsonb, material_course jsonb)
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                        RETURN QUERY
                                SELECT
                                    c.id as course_id,
                                    c.name as course,
                                    jsonb_agg(
                                        DISTINCT jsonb_build_object(
                                            'level_id', tbl_level.level_id,
                                            'level', tbl_level.level
                                        )
                                    ) AS level_course,
                                    (
                                        SELECT jsonb_agg(
                                        jsonb_build_object(
                                            'type_material_id', tbl_type_material.type_material_id,
                                            'type_material', tbl_type_material.type_material,
                                            'amount_text', tbl_type_material.amount_text
                                            )
                                        )   FROM fn_get_course_material_details(p_course_id::smallint, p_week, p_cycle_id) tbl_type_material
                                    )	 AS material_course
                                FROM course c
                                INNER JOIN
                                (
                                    SELECT DISTINCT
                                        l.id AS level_id,
                                        l.description AS level,
                                        cl.course_id AS course_id
                                    FROM course_level cl
                                    LEFT JOIN "level" l ON cl.level_id = l.id
                                    LEFT JOIN course c ON cl.course_id = c.id
                                    WHERE
                                        cl.fl_status = TRUE
                                        AND cl.deleted_at IS NULL
                                        AND c.fl_status = TRUE
                                        AND l.fl_status = TRUE
                                ) AS tbl_level ON tbl_level.course_id = c.id
                                WHERE
                                    c.id = p_course_id
                                    AND c.fl_status = TRUE
                                GROUP BY c.id;

                    END;
                    $$;


ALTER FUNCTION odiseo.fn_get_detail_level_parent_type_material_by_course(p_cycle_id integer, p_week integer, p_course_id integer) OWNER TO postgres;

--
-- Name: fn_get_detail_level_type_material_by_course(integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_detail_level_type_material_by_course(p_course_id integer, p_cycle_id integer, p_week integer) RETURNS TABLE(course_id smallint, course character varying, level_course jsonb, material_course jsonb)
    LANGUAGE plpgsql
    AS $$
                    DECLARE
                    BEGIN

                        RETURN QUERY
                        SELECT
                            c.id as course_id,
                            c.name as course,
                            jsonb_agg(
                                DISTINCT jsonb_build_object(
                                    'level_id', tbl_level.level_id,
                                    'level', tbl_level.level
                                )
                            ) AS level_course,
                            (
                                SELECT jsonb_agg(
                                jsonb_build_object(
                                    'type_material_id', tbl_type_material.type_material_id,
                                    'type_material', tbl_type_material.type_material,
                                    'amount_question', tbl_type_material.amount_question
                                    )
                                )   FROM fn_get_course_material_details(p_course_id::smallint, p_week, p_cycle_id) tbl_type_material
                            )	 AS material_course
                        FROM course c
                        INNER JOIN
                        (
                            SELECT DISTINCT
                                l.id AS level_id,
                                l.description AS level,
                                cl.course_id AS course_id
                            FROM course_level cl
                            LEFT JOIN "level" l ON cl.level_id = l.id
                            LEFT JOIN course c ON cl.course_id = c.id
                            WHERE
                                cl.fl_status = TRUE
                                AND cl.deleted_at IS NULL
                                AND c.fl_status = TRUE
                                AND l.fl_status = TRUE
                        ) AS tbl_level ON tbl_level.course_id = c.id
                        WHERE
                            c.id = p_course_id
                            AND c.fl_status = TRUE
                        GROUP BY c.id;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_get_detail_level_type_material_by_course(p_course_id integer, p_cycle_id integer, p_week integer) OWNER TO postgres;

--
-- Name: fn_get_detail_template_material(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_detail_template_material(p_material_id bigint) RETURNS TABLE(id bigint, uuid uuid, week smallint, type_week_id bigint, type_week character varying, cycle_id bigint, type_material_id smallint, fl_process_status integer, fl_process_without integer, fl_process_quality integer, fl_process_without_quality integer, fl_process_class_mat integer, fl_exam boolean, fl_frequent boolean, fl_complete_questions boolean, data_incomplete_questions character varying, fl_config_level boolean, fl_config_type boolean, limit_lower_question smallint, limit_upper_question smallint, material character varying, fl_class_material boolean, questions_generation_process character varying, type_exam_id bigint)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            WITH tbl_material AS (
                SELECT
                    m.id,
                    m.cycle_id
                FROM material m
                WHERE m.id = p_material_id
            ),tbl_cycle_weeks AS (
                SELECT
                    fdtm.id,
                    fdtm.uuid,
                    cw.week,
                    cw.type_week_id,
                    tw.description AS type_week,
                    cw.cycle_id,
                    fdtm.type_material_id,
                    fdtm.fl_process_status,
                    fdtm.fl_process_without,
                    fdtm.fl_process_quality,
                    fdtm.fl_process_without_quality,
                    fdtm.fl_process_class_mat,
                    fdtm.fl_exam,
                    fdtm.fl_frequent,
                    fdtm.fl_complete_questions,
                    fdtm.data_incomplete_questions,
                    fdtm.fl_config_level,
                    fdtm.fl_config_type,
                    fdtm.limit_lower_question,
                    fdtm.limit_upper_question,
                    fdtm.material,
                    fdtm.fl_class_material,
                    fdtm.questions_generation_process,
                    fdtm.type_exam_id
                FROM cycle_weeks cw
                INNER JOIN cycle c ON cw.cycle_id = c.id
                INNER JOIN type_week tw ON cw.type_week_id = tw.id
                LEFT JOIN fn_detail_template_by_material(p_material_id, c.id, cw.week) fdtm ON 1 = 1
                WHERE cw.cycle_id IN (SELECT tm.cycle_id FROM tbl_material tm)
                    AND cw.fl_status = true
            )
            SELECT * FROM tbl_cycle_weeks tcw
            ORDER BY tcw.week ASC, tcw.material ASC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_get_detail_template_material(p_material_id bigint) OWNER TO postgres;

--
-- Name: fn_get_detail_week_type_material(bigint, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_detail_week_type_material(p_material_id bigint, p_week smallint, p_type_material_id smallint) RETURNS TABLE(detail_id bigint, cycle_id bigint, fl_examen boolean, name_type_material character varying, name_type_material_template character varying, process_status smallint, process_status_without smallint, fl_complete_questions boolean, data_incomplete_questions character varying, missing_config_message character varying, data_missing_course_config character varying, data_missing_text json, university_id smallint)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        WITH tbl_type_material AS (
            SELECT
                tm.fl_exam,
                tm.description,
                tmt.name
            FROM type_material tm
            LEFT JOIN type_material_template tmt ON tmt.id = tm.type_material_template_id
            WHERE tm.id = p_type_material_id
        )
        SELECT
            dwtm.id AS detail_id,
            m.cycle_id,
            ttm.fl_exam,
            ttm.description AS name_type_material,
            ttm.name AS name_type_material_template,
            dwtm.fl_process_status,
            dwtm.fl_process_status_without,
            dwtm.fl_complete_questions,
            dwtm.data_incomplete_questions,
            dwtm.missing_config_message,
            dwtm.data_missing_course_config,
            dwtm.data_missing_text,
            m.university_id
        FROM detail_week_type_mat dwtm
        INNER JOIN material m ON dwtm.material_id = m.id
        JOIN tbl_type_material ttm ON 1 = 1
        WHERE dwtm.material_id = p_material_id
            AND dwtm.week = p_week
            AND dwtm.type_material_id = p_type_material_id
            AND dwtm.fl_status = true;
    END;
    $$;


ALTER FUNCTION odiseo.fn_get_detail_week_type_material(p_material_id bigint, p_week smallint, p_type_material_id smallint) OWNER TO postgres;

--
-- Name: fn_get_details_level_syllabus_by_id(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_details_level_syllabus_by_id(p_level_cycle_id bigint) RETURNS TABLE(cycle_id bigint, code_cycle character varying, name_cycle character varying, university_id smallint, name_university character varying, headquarter_id smallint, name_headquarter character varying, course_id smallint, code_course character varying, name_course character varying, total_weeks smallint, cycle_template_id bigint, weeks jsonb)
    LANGUAGE plpgsql
    AS $$
                            BEGIN
                            RETURN QUERY
                            WITH base_level AS (
                                    SELECT
                                        ls.id AS level_syllabus_id,
                                        c.id AS cycle_id,
                                        c.code AS code_cycle,
                                        c.description AS name_cycle,
                                        ou.id AS university_id,
                                        ou.name AS name_university,
                                        h.id AS headquarter_id,
                                        h.name AS name_headquarter,
                                        c2.id AS course_id,
                                        c2.code AS code_course,
                                        c2.name AS name_course,
                                        c.weeks AS total_weeks,
                                        c.cycle_template_id 
                                    FROM level_syllabus ls
                                    LEFT JOIN cycle c ON ls.cycle_id = c.id
                                    LEFT JOIN course c2 ON ls.course_id = c2.id
                                    LEFT JOIN origin_university ou ON ls.university_id = ou.id
                                    LEFT JOIN headquarters h ON ls.headquarter_id = h.id
                                    WHERE ls.id = p_level_cycle_id AND ls.fl_status = TRUE AND ls.deleted_at IS NULL
                                ),
                                expected_raw AS (
                                    SELECT 
                                        tmdt.week,
                                        tm.id AS material_type_id,
                                        SUM(CASE WHEN tmc.is_generic = true THEN tmc.amount_question ELSE COALESCE(tmdc.amount_question, 0) END) AS total_question,
                                        SUM(CASE WHEN tmc.is_generic_text = true THEN tmc.amount_text ELSE COALESCE(tmdct.amount_text, 0) END) AS total_text
                                    FROM type_material tm
                                    JOIN type_material_detail_template tmdt ON tmdt.type_material_id = tm.id
                                    JOIN type_material_template tmt ON tmt.id = tm.type_material_template_id 
                                    JOIN type_material_course tmc ON tmc.type_material_id = tm.id
                                    LEFT JOIN type_material_detail_courses tmdc ON tmdc.type_material_course_id = tmc.id AND tmdc.type_material_detail_template_id = tmdt.id
                                    LEFT JOIN type_material_detail_course_texts tmdct ON tmdct.type_material_course_id = tmc.id AND tmdct.type_material_detail_template_id = tmdt.id
                                    CROSS JOIN base_level bl
                                    WHERE tm.cycle_id = bl.cycle_id
                                    AND tmc.course_id = bl.course_id
                                    AND tm.fl_exam = false
                                    AND tm.fl_status = true
                                    AND (
                                            tm.parent_id IS NOT NULL
                                            OR 
                                            tm.id NOT IN (SELECT parent_id FROM type_material tm2 WHERE tm2.cycle_id = tm.cycle_id  AND parent_id IS NOT NULL)
                                        )
                                    GROUP BY tmdt.week, tm.id
                                ),
                                expected AS (
                                    SELECT week, material_type_id, 'P' AS type, total_question AS total
                                    FROM expected_raw 
                                    UNION ALL
                                    SELECT week, material_type_id, 'T' AS type, total_text AS total
                                    FROM expected_raw 
                                ),
                                actual_materials AS (
                                    SELECT 
                                        level_syllabus_weeks_id, 
                                        type_material_id, 
                                        'P' AS type, 
                                        COALESCE(number_questions, 0) AS total
                                    FROM detail_level_syllabus_weeks
                                    WHERE fl_status = true AND deleted_at IS NULL AND COALESCE(number_questions, 0) > 0
                                    
                                    UNION ALL
                                    
                                    SELECT 
                                        level_syllabus_weeks_id, 
                                        type_material_id, 
                                        'T' AS type, 
                                        COALESCE(number_of_passages, 0) AS total
                                    FROM detail_level_syllabus_weeks_parents
                                    WHERE fl_status = true AND deleted_at IS NULL AND COALESCE(number_of_passages, 0) > 0
                                ),
                                actual AS (
                                    SELECT 
                                        lsw.week, 
                                        am.type_material_id AS material_type_id, 
                                        am.type,
                                        SUM(am.total) AS total
                                    FROM level_syllabus_weeks lsw 
                                    CROSS JOIN base_level bl
                                    JOIN actual_materials am ON am.level_syllabus_weeks_id = lsw.id 
                                    WHERE 
                                        lsw.level_syllabus_id = bl.level_syllabus_id 
                                        AND lsw.fl_status = true 
                                    GROUP BY 
                                        lsw.id, lsw.week, am.type_material_id, am.type
                                ),
                                inconsistent_weeks AS (
                                    SELECT DISTINCT COALESCE(e.week, a.week) AS error_week 
                                    FROM expected e
                                    FULL OUTER JOIN actual a 
                                        ON e.week = a.week 
                                    AND e.material_type_id = a.material_type_id
                                    AND e.type = a.type
                                    WHERE 
                                        COALESCE(e.total, 0) != COALESCE(a.total, 0)
                                ),
                                list_weeks AS (
                                    SELECT 
                                        bl.level_syllabus_id,
                                        cw.week AS week_number 
                                    FROM base_level bl
                                    JOIN cycle_weeks cw ON cw.cycle_id = bl.cycle_id
                                    JOIN type_week tw ON cw.type_week_id = tw.id
                                    WHERE cw.fl_status = true 
                                      AND cw.deleted_at IS NULL
                                      AND tw.description != 'Inactiva'
                                      AND tw.fl_status = true
                                      AND tw.deleted_at IS NULL
                                ),
                                weeks_json_build AS (
                                    SELECT 
                                        lw.level_syllabus_id,
                                        jsonb_agg(
                                            jsonb_build_object(
                                                'week', lw.week_number,
                                                'name_week', 'Semana ' || lw.week_number,
                                                'exist_level_syllabus', CASE WHEN iw.error_week IS NOT NULL THEN false ELSE true END
                                            ) ORDER BY lw.week_number
                                        ) AS weeks_array
                                    FROM list_weeks lw
                                    LEFT JOIN inconsistent_weeks iw ON lw.week_number = iw.error_week
                                    GROUP BY lw.level_syllabus_id
                                )
                                SELECT 
                                    bl.cycle_id,
                                    bl.code_cycle,
                                    bl.name_cycle,
                                    bl.university_id,
                                    bl.name_university,
                                    bl.headquarter_id,
                                    bl.name_headquarter,
                                    bl.course_id,
                                    bl.code_course,
                                    bl.name_course,
                                    bl.total_weeks,
                                    bl.cycle_template_id,
                                    wjb.weeks_array AS weeks
                                FROM base_level bl
                                LEFT JOIN weeks_json_build wjb ON bl.level_syllabus_id = wjb.level_syllabus_id;
                        END;
                        $$;


ALTER FUNCTION odiseo.fn_get_details_level_syllabus_by_id(p_level_cycle_id bigint) OWNER TO postgres;

--
-- Name: fn_get_details_syllabus(jsonb, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_details_syllabus(p_course_ids jsonb, p_cycle_id integer) RETURNS TABLE(course_id smallint, course_name character varying, cycle_id smallint, cycle_description character varying, weeks smallint, detail_type_material jsonb, course_levels jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH filtered_courses AS (
        SELECT c.id AS course_id, c."name" AS course_name
        FROM course c
        WHERE c.id IN (SELECT value::INT FROM jsonb_array_elements_text(p_course_ids))
          AND c.fl_status = TRUE
          AND c.deleted_at IS NULL
    ),
    cycle_details AS (
        SELECT 
            c.id AS cycle_id, 
            c.description AS cycle_description, 
            MAX(cw.week) AS weeks
        FROM "cycle" c
        INNER JOIN "cycle_weeks" cw ON cw.cycle_id = c.id
        WHERE c.id = p_cycle_id 
        group by c.id
    ),
    course_materials AS (
        SELECT
            tmc.course_id,
            JSONB_AGG(
                JSONB_BUILD_OBJECT(
                    'type_material_id', tm.id,
                    'type_material', tm.description,
                    'total_question', COALESCE(tmc.amount_question, 0)
                )
            ) AS detail_type_material
        FROM type_material tm
        JOIN type_material_course tmc ON tmc.type_material_id = tm.id
        WHERE tm.cycle_id = p_cycle_id
          AND tm.fl_status = TRUE
          AND tm.deleted_at IS NULL
          AND tm.fl_exam = FALSE
          AND tmc.course_id IN (SELECT fc.course_id FROM filtered_courses fc)
        GROUP BY tmc.course_id
    ),
    course_levels_agg AS (
        SELECT
            cl.course_id,
            JSONB_AGG(
                JSONB_BUILD_OBJECT(
                    'level_id', l.id,
                    'level_name', l."name",
                    'level_description', l.description
                )
            ) AS course_levels
        FROM course_level cl
        JOIN "level" l ON cl.level_id = l.id
        WHERE cl.fl_status = TRUE
          AND cl.deleted_at IS NULL
          AND l.fl_status = TRUE
          AND l.deleted_at IS NULL
          AND cl.course_id IN (SELECT fc.course_id FROM filtered_courses fc)
        GROUP BY cl.course_id
    )
    SELECT
        fc.course_id::SMALLINT,
        fc.course_name,
        cd.cycle_id::SMALLINT,
        cd.cycle_description,
        cd.weeks::SMALLINT,
        COALESCE(cm.detail_type_material, '[]'::JSONB),
        COALESCE(cla.course_levels, '[]'::JSONB)
    FROM filtered_courses fc
    CROSS JOIN cycle_details cd
    LEFT JOIN course_materials cm ON cm.course_id = fc.course_id
    LEFT JOIN course_levels_agg cla ON cla.course_id = fc.course_id;
END;
$$;


ALTER FUNCTION odiseo.fn_get_details_syllabus(p_course_ids jsonb, p_cycle_id integer) OWNER TO postgres;

--
-- Name: fn_get_employee_university(integer, integer, bigint, smallint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_employee_university(p_per_page integer, p_n_page integer, p_employee_id bigint, p_university_id smallint, p_search character varying) RETURNS TABLE(id bigint, code character varying, employee_id bigint, first_name character varying, first_surname character varying, second_surname character varying, document character varying, charge_id bigint, charge character varying, university_id smallint, university character varying, slug character varying, total bigint)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            total_count INTEGER;
            offset_val INTEGER;
        BEGIN
            offset_val := p_per_page * (p_n_page - 1);

            RETURN QUERY
            WITH tbl_employee_university AS (
                SELECT
                    eu.id,
                    e.code,
                    eu.employee_id,
                    e.first_name,
                    e.first_surname,
                    e.second_surname,
                    e.document,
                    e.charge_id,
                    c.name AS charge,
                    eu.university_id,
                    u.name AS university,
                    u.slug
                FROM odiseo.employee_university eu
                INNER JOIN odiseo.employees e ON eu.employee_id = e.id
                INNER JOIN odiseo.charge c ON c.id = e.charge_id
                INNER JOIN odiseo.origin_university u ON eu.university_id = u.id
                WHERE 1 = 1
                AND e.fl_status IS TRUE
                AND (p_employee_id IS NULL OR eu.employee_id = p_employee_id)
                AND (p_university_id IS NULL OR eu.university_id = p_university_id)
                AND (p_search IS NULL OR
                    LOWER(e.first_name) ILIKE '%' || LOWER(p_search) || '%' OR
                    LOWER(e.first_surname) ILIKE '%' || LOWER(p_search) || '%' OR
                    LOWER(e.second_surname) ILIKE '%' || LOWER(p_search) || '%')
            )
            SELECT tbl.*,  COUNT(*) OVER () AS total
            FROM  tbl_employee_university tbl
            ORDER BY
                UNACCENT(tbl.first_name) ASC,
                UNACCENT(tbl.first_surname) ASC,
                UNACCENT(tbl.second_surname) ASC,
                UNACCENT(tbl.university) ASC
            LIMIT p_per_page
            OFFSET  offset_val;
        END;
        $$;


ALTER FUNCTION odiseo.fn_get_employee_university(p_per_page integer, p_n_page integer, p_employee_id bigint, p_university_id smallint, p_search character varying) OWNER TO postgres;

--
-- Name: fn_get_essential_knowledge_by_question_id(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_essential_knowledge_by_question_id(p_question_id bigint) RETURNS TABLE(course_id smallint, topic_id smallint, essential_knowledge jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN

    RETURN QUERY
    SELECT
        q.course_id,
        q.topic_id,

        COALESCE(
            jsonb_agg(
                DISTINCT jsonb_build_object(
                    'id', ek.id,
                    'code', ek.code,
                    'name', ek.name,
                    'course_id', ek.course_id,
                    'topic_id', ek.topic_id,
                    'image', eki.image
                )
            ) FILTER (WHERE ek.id IS NOT NULL),
            '[]'::jsonb
        ) AS essential_knowledge

    FROM question q

    LEFT JOIN essential_knowledge_questions ekq
        ON q.id = ekq.question_id
        AND ekq.deleted_at IS NULL

    LEFT JOIN essential_knowledges ek
        ON ek.id = ekq.essential_knowledge_id
        AND ek.is_active IS TRUE
        AND ek.deleted_at IS NULL

    LEFT JOIN essential_knowledge_image eki
        ON ek.id = eki.essential_knowledge_id
        AND eki.deleted_at IS NULL

    WHERE q.id = p_question_id

    GROUP BY q.course_id, q.topic_id;

END;
$$;


ALTER FUNCTION odiseo.fn_get_essential_knowledge_by_question_id(p_question_id bigint) OWNER TO postgres;

--
-- Name: fn_get_exam_configuration_inconsistencies(bigint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_exam_configuration_inconsistencies(p_cycle_id bigint, p_university_id bigint, p_company_id bigint) RETURNS TABLE(type_material_id smallint, type_material_name character varying, syllabus_id bigint, area_id smallint, area_name character varying, course_id smallint, course_name character varying, cycle_id bigint, university_id bigint, company_id bigint, cycle_description character varying, exam_week smallint, record_type text, is_text_record boolean, expected_amount integer, actual_level_amount integer, has_level_mismatch boolean, has_syllabus_mismatch boolean, has_inconsistencies boolean, period_detail jsonb)
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                        RETURN QUERY
                        WITH request_info AS (
                            SELECT c.id AS cycle_id, c.description AS cycle_description
                            FROM cycle c 
                            WHERE c.id = p_cycle_id
                        )
                        , expected_raw AS (
                            SELECT
                                tma.area_id::smallint, ea.description AS area_name,
                                tm.id::smallint AS type_material_id, tmt.name AS type_material_name,
                                tmt.type_exam_id, te.name type_exam,
                                tmc.course_id::smallint, c.name AS course_name,
                                v.is_text_record, v.type_str, v.expected_amount,
                                s.id AS syllabus_id
                            FROM type_material tm
                            JOIN request_info ri ON tm.cycle_id = ri.cycle_id
                            JOIN type_material_template tmt ON tmt.id = tm.type_material_template_id
                            JOIN type_exams te ON te.id = tmt.type_exam_id 
                            JOIN type_material_area tma ON tma.type_material_id = tm.id
                            JOIN exam_area ea ON ea.id = tma.area_id
                            JOIN type_material_area_courses tmac ON tmac.type_material_area_id = tma.id
                            JOIN type_material_course tmc ON tmc.id = tmac.type_material_course_id AND tmc.type_material_id = tm.id
                            JOIN course c ON c.id = tmc.course_id
                            LEFT JOIN syllabus s ON s.course_id = c.id AND s.cycle_id = p_cycle_id AND s.university_id = p_university_id AND s.company_id = p_company_id AND s.fl_status = true
                            CROSS JOIN LATERAL (
                                VALUES
                                    (FALSE, 'P'::text, tmc.amount_question),
                                    (TRUE, 'T'::text, COALESCE(tmc.amount_text, 0))
                            ) AS v(is_text_record, type_str, expected_amount)
                            WHERE tm.fl_exam = true AND tm.fl_status = true AND tma.fl_status = true AND tmc.fl_status = true AND tmac.fl_status = true
                            AND (v.is_text_record = FALSE OR c.apply_text = TRUE)
                            AND v.expected_amount > 0
                        )
                        , materials_type_2 AS (
                            SELECT DISTINCT er.type_material_id 
                            FROM expected_raw er
                            WHERE er.type_exam = 'Tipo 2'
                        )
                        , base_template_weeks AS (
                            SELECT tmdt.type_material_id, tmdt.week
                            FROM type_material_detail_template tmdt
                            JOIN materials_type_2 mt2 ON tmdt.type_material_id = mt2.type_material_id
                            WHERE tmdt.fl_status IS TRUE
                        )
                        , all_materials_periods_raw AS (
                            SELECT
                                btw.type_material_id, btw.week AS eval_week,
                                (COALESCE(LAG(btw.week) OVER (PARTITION BY btw.type_material_id ORDER BY btw.week), 0) + 1)::smallint AS current_starting_week,
                                btw.week::smallint AS current_ending_week,
                                (ROW_NUMBER() OVER (PARTITION BY btw.type_material_id ORDER BY btw.week))::smallint AS week_order
                            FROM base_template_weeks btw
                        ) 
                        , all_materials_periods_precalculated AS (
                            SELECT ampr.type_material_id, ampr.eval_week, 1::smallint AS period_number, ampr.current_starting_week AS starting_week, ampr.current_ending_week AS ending_week
                            FROM all_materials_periods_raw ampr
                            UNION ALL
                            SELECT ampr.type_material_id, ampr.eval_week, 2::smallint AS period_number, 1::smallint AS starting_week,
                                (ampr.current_starting_week - 1)::smallint AS ending_week
                            FROM all_materials_periods_raw ampr
                            WHERE ampr.week_order > 1 -- Evita crear el periodo duplicado en la semana 1
                        )
                        , actual_levels AS (
                            SELECT emcac.exam_area_id::smallint AS area_id, emc.type_material_id::smallint, emcac.course_id::smallint, FALSE AS is_text_record, COALESCE(SUM(emcacl.amount_question), 0)::INTEGER AS level_amount
                            FROM exam_material_configurations emc
                            JOIN exam_material_config_area_courses emcac ON emc.id = emcac.exam_material_config_id
                            JOIN exam_material_config_area_course_levels emcacl ON emcac.id = emcacl.exam_material_config_area_course_id AND emcacl.fl_status = true
                            JOIN course_level cl ON cl.level_id = emcacl.level_id AND cl.course_id = emcac.course_id AND cl.fl_status = true
                            WHERE emc.fl_status = true AND emcac.fl_status = true AND emc.cycle_id = p_cycle_id
                            GROUP BY emcac.exam_area_id, emc.type_material_id, emcac.course_id
                            UNION ALL
                            SELECT ttemc.area_id::smallint, emc.type_material_id::smallint, ttemc.course_id::smallint, TRUE AS is_text_record, COALESCE(SUM(ttemc.text_amount), 0)::INTEGER AS level_amount
                            FROM exam_material_configurations emc
                            JOIN type_text_exam_material_configuration ttemc ON emc.id = ttemc.exam_material_config_id
                            WHERE emc.fl_status = true AND ttemc.deleted_at IS NULL AND emc.cycle_id = p_cycle_id
                            GROUP BY ttemc.area_id, emc.type_material_id, ttemc.course_id
                        ) 
                        , cte_valid_syllabus_weeks AS (
                            SELECT distinct st.syllabus_id, stw.week, FALSE AS is_text_record
                            FROM syllabus_topic st
                            JOIN syllabus s ON s.id = st.syllabus_id 
                            JOIN syllabus_topic_week stw ON stw.syllabus_topic_id = st.id
                            WHERE st.fl_status IS TRUE AND stw.fl_status IS TRUE AND stw.total_questions_amount > 0 AND s.cycle_id = p_cycle_id 
                            UNION ALL
                            SELECT distinct stw.syllabus_id, stw.week, TRUE AS is_text_record
                            FROM syllabus_text_weeks stw
                            JOIN syllabus s ON s.id = stw.syllabus_id 
                            JOIN syllabus_text_distributions std ON std.syllabus_text_week_id = stw.id
                            JOIN type_material tm ON tm.id = std.type_material_id
                            WHERE stw.fl_status IS TRUE AND std.fl_status IS TRUE AND tm.fl_status IS TRUE AND tm.description <> 'ECO' AND s.cycle_id = p_cycle_id 
                        )
                        , syllabus_valid_weeks_agg AS (
                            SELECT cvsw.syllabus_id, cvsw.is_text_record, array_agg(cvsw.week) AS arr_weeks
                            FROM cte_valid_syllabus_weeks cvsw
                            GROUP BY cvsw.syllabus_id, cvsw.is_text_record
                        )
                        , course_type_base AS (
                            SELECT
                                er.area_id, er.area_name, er.type_material_id, er.type_material_name, er.type_exam,
                                er.course_id, er.course_name, er.syllabus_id,
                                er.is_text_record, er.type_str, er.expected_amount,
                                COALESCE(al.level_amount, 0) AS actual_level_amount
                            FROM expected_raw er
                            LEFT JOIN actual_levels al ON al.area_id = er.area_id AND al.type_material_id = er.type_material_id AND al.course_id = er.course_id AND al.is_text_record = er.is_text_record
                        )
                        , periods_evaluation AS (
                            SELECT
                                cb.area_id, cb.area_name, cb.type_material_id, cb.type_material_name, cb.course_id, cb.course_name, cb.syllabus_id,
                                cb.is_text_record, cb.type_str, cb.expected_amount, cb.actual_level_amount,
                                tmdt.week AS exam_week, p.period_number, p.starting_week, p.ending_week,
                                CASE 
                                    WHEN cb.syllabus_id IS NULL OR svw.arr_weeks IS NULL THEN FALSE
                                    WHEN cb.type_exam = 'Tipo 1' THEN tmdt.week = ANY(svw.arr_weeks)
                                    WHEN cb.type_exam = 'Tipo 2' THEN COALESCE((SELECT bool_or(w BETWEEN p.starting_week AND p.ending_week) FROM unnest(svw.arr_weeks) AS w), FALSE)
                                    WHEN cb.type_exam = 'Tipo 3' THEN array_length(svw.arr_weeks, 1) > 0
                                    ELSE FALSE 
                                END AS has_data
                            FROM course_type_base cb
                            JOIN type_material_detail_template tmdt ON tmdt.type_material_id = cb.type_material_id AND tmdt.fl_status = true
                            LEFT JOIN syllabus_valid_weeks_agg svw ON svw.syllabus_id = cb.syllabus_id AND svw.is_text_record = cb.is_text_record
                            LEFT JOIN all_materials_periods_precalculated p ON p.type_material_id = cb.type_material_id AND p.eval_week = tmdt.week AND cb.type_exam = 'Tipo 2'
                        )
                        , flat_week_level_agg AS (
                            SELECT
                                pe.area_id, pe.area_name, pe.type_material_id, pe.type_material_name, pe.course_id, pe.course_name, MAX(pe.syllabus_id) AS syllabus_id,
                                pe.exam_week, pe.type_str, pe.is_text_record, pe.expected_amount, pe.actual_level_amount,
                                bool_or(NOT pe.has_data) AS has_syllabus_mismatch,
                                (pe.expected_amount != pe.actual_level_amount) AS has_level_mismatch,
                                jsonb_agg(
                                    jsonb_build_object(
                                        'period_number', COALESCE(pe.period_number, 1),
                                        'start_week', COALESCE(pe.starting_week, pe.exam_week),
                                        'end_week', COALESCE(pe.ending_week, pe.exam_week),
                                        'has_data', pe.has_data,
                                        'has_error', NOT pe.has_data
                                    ) ORDER BY COALESCE(pe.starting_week, pe.exam_week) ASC
                                ) AS period_detail
                            FROM periods_evaluation pe
                            GROUP BY pe.area_id, pe.area_name, pe.type_material_id, pe.type_material_name, pe.course_id, pe.course_name, pe.exam_week, pe.type_str, pe.is_text_record, pe.expected_amount, pe.actual_level_amount
                        )
                        SELECT
                            fwa.type_material_id,
                            fwa.type_material_name::varchar,
                            fwa.syllabus_id,
                            fwa.area_id, 
                            fwa.area_name::varchar,
                            fwa.course_id, 
                            fwa.course_name::varchar,
                            p_cycle_id AS cycle_id, 
                            p_university_id AS university_id, 
                            p_company_id AS company_id,
                            r.cycle_description::varchar, 
                            fwa.exam_week::smallint,
                            fwa.type_str AS record_type,
                            fwa.is_text_record,
                            fwa.expected_amount,
                            fwa.actual_level_amount,
                            fwa.has_level_mismatch,
                            fwa.has_syllabus_mismatch,
                            (fwa.has_syllabus_mismatch OR fwa.has_level_mismatch) AS has_inconsistencies,
                            fwa.period_detail
                        FROM flat_week_level_agg fwa
                        CROSS JOIN request_info r
                        WHERE fwa.has_syllabus_mismatch = true OR fwa.has_level_mismatch = true
                        ORDER BY fwa.exam_week, fwa.type_material_id, fwa.course_id;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_get_exam_configuration_inconsistencies(p_cycle_id bigint, p_university_id bigint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_get_exam_generated_questions(uuid); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_exam_generated_questions(p_uuid uuid) RETURNS json
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_result json;
    v_university_id int;
    v_material_id int;
BEGIN
    -- Obtenemos el university_id y material_id
    SELECT m.university_id, m.id 
    INTO v_university_id, v_material_id
    FROM detail_week_type_mat dwtm
    JOIN material m ON m.id = dwtm.material_id
    WHERE dwtm.uuid = p_uuid;

    IF v_material_id IS NULL THEN
        RETURN NULL;
    END IF;

    WITH base_data AS (
        SELECT 
            dwtm.type_material_id, 
            tm.description AS type_material,
            c.description AS cycle,
            ea.description AS area,
            ea.id AS area_id,
            meaw.id AS material_exam_area_week_id
        FROM detail_week_type_mat dwtm 
        JOIN material m ON m.id = dwtm.material_id 
        JOIN "cycle" c ON c.id = m.cycle_id 
        JOIN material_exam_area_week meaw ON meaw.week_type_material_id = dwtm.id
        JOIN exam_area ea ON ea.id = meaw.area_id 
        JOIN type_material tm ON tm.id = dwtm.type_material_id 
        WHERE dwtm.uuid = p_uuid
        AND meaw.fl_status = true
    ),
    normal_questions AS (
        SELECT 
            meq.material_exam_area_week_id, 
            q.id,
            q.code,
            CASE WHEN co.id IS NOT NULL THEN json_build_object('id', co.id, 'name', co.name) ELSE NULL END AS course,
            CASE WHEN t.id IS NOT NULL THEN json_build_object('id', t.id, 'name', t.name) ELSE NULL END AS topic,
            CASE WHEN s.id IS NOT NULL THEN json_build_object('id', s.id, 'name', s.name, 'is_frequent', COALESCE(fus.is_frequent, false)) ELSE NULL END AS subtopic,
            CASE WHEN l.id IS NOT NULL THEN json_build_object('id', l.id, 'name', l.name) ELSE NULL END AS level,
            meq.position,
            q.ter
        FROM material_exam_question meq 
        JOIN base_data bd ON bd.material_exam_area_week_id = meq.material_exam_area_week_id
        JOIN question q ON q.id = meq.question_id 
        LEFT JOIN course co ON co.id = meq.course_id
        LEFT JOIN topic t ON t.id = meq.topic_id 
        LEFT JOIN subtopic s ON s.id = meq.subtopic_id
        LEFT JOIN frequent_university_subtopic fus ON fus.subtopic_id = meq.subtopic_id AND fus.university_id = v_university_id
        LEFT JOIN "level" l ON l.id = meq.level_id 
        WHERE meq.fl_status = true AND meq.deleted_at IS NULL AND meq.question_id IS NOT NULL
    ),
    text_subquestions_raw AS (
        SELECT 
            mepq.material_exam_area_week_id, 
            mepq.position,
            jsonb_array_elements(mepq.subquestion) AS subq_elem,
            mepq.current_level AS level_id, 
            mepq.course_id 
        FROM material_exam_parent_question mepq 
        JOIN base_data bd ON bd.material_exam_area_week_id = mepq.material_exam_area_week_id
        WHERE mepq.deleted_at IS NULL AND mepq.parent_question_id IS NOT NULL
    ),
    text_subquestions AS (
        SELECT
            ts.material_exam_area_week_id,
            q.id,
            q.code,
            CASE WHEN co.id IS NOT NULL THEN json_build_object('id', co.id, 'name', co.name) ELSE NULL END AS course,
            CASE WHEN t.id IS NOT NULL THEN json_build_object('id', t.id, 'name', t.name) ELSE NULL END AS topic,
            CASE WHEN s.id IS NOT NULL THEN json_build_object('id', s.id, 'name', s.name, 'is_frequent', COALESCE(fus.is_frequent, false)) ELSE NULL END AS subtopic,
            CASE WHEN l.id IS NOT NULL THEN json_build_object('id', l.id, 'name', l.name) ELSE NULL END AS level,
            ts.position,
            q.ter
        FROM text_subquestions_raw ts
        JOIN question q ON q.id = (ts.subq_elem->>'question_id')::int
        LEFT JOIN course co ON co.id = ts.course_id
        LEFT JOIN topic t ON t.id = (ts.subq_elem->>'topic_id')::int
        LEFT JOIN subtopic s ON s.id = (ts.subq_elem->>'subtopic_id')::int
        LEFT JOIN frequent_university_subtopic fus ON fus.subtopic_id = s.id AND fus.university_id = v_university_id::bigint
        LEFT JOIN "level" l ON l.id = ts.level_id
    ),
    all_questions AS (
        SELECT * FROM normal_questions
        UNION ALL
        SELECT * FROM text_subquestions
    ),
    questions_with_metadata AS (
        SELECT 
            aq.material_exam_area_week_id,
            aq.id,
            aq.code,
            aq.course,
            aq.topic,
            aq.subtopic,
            aq.level,
            aq.position,
            aq.ter,
            (
                SELECT json_strip_nulls(json_build_object(
                    'university', CASE WHEN vo.university_id IS NOT NULL THEN json_build_object('id', vo.university_id, 'name', u.slug) ELSE NULL END,
                    'option', CASE WHEN vo.option_id IS NOT NULL THEN json_build_object('id', vo.option_id, 'name', ou.name) ELSE NULL END,
                    'modality', CASE WHEN vo.modality_id IS NOT NULL THEN json_build_object('id', vo.modality_id, 'name', mo.name) ELSE NULL END,
                    'version', CASE WHEN vo.version IS NOT NULL THEN odiseo.fn_number_to_roman(vo.version::smallint) ELSE NULL END,
                    'year', vo.year
                ))
                FROM v_all_question_origins_by_university vo
                LEFT JOIN origin_university u ON u.id = vo.university_id
                LEFT JOIN option_university ou ON ou.id = vo.option_id
                LEFT JOIN modality_options mo ON mo.id = vo.modality_id
                WHERE vo.question_id = aq.id AND vo.university_id = v_university_id::bigint
                LIMIT 1
            ) AS origin
        FROM all_questions aq
    ),
    areas_json AS (
        SELECT 
            bd.area_id AS id,
            bd.area,
            COALESCE(
                (
                    SELECT json_agg(
                        json_strip_nulls(json_build_object(
                            'id', qm.id,
                            'code', qm.code,
                            'course', qm.course,
                            'topic', qm.topic,
                            'subtopic', qm.subtopic,
                            'level', qm.level,
                            'ter', qm.ter,
                            'origin', COALESCE(qm.origin, '{}'::json)
                        ))
                    )
                    FROM (
                        SELECT * 
                        FROM questions_with_metadata q_sub 
                        WHERE q_sub.material_exam_area_week_id = bd.material_exam_area_week_id 
                        ORDER BY q_sub.position
                    ) qm
                ), 
                '[]'::json
            ) AS questions
        FROM base_data bd
    )
    SELECT json_build_object(
        'type_material', (SELECT type_material FROM base_data LIMIT 1),
        'type_material_id', (SELECT type_material_id FROM base_data LIMIT 1),
        'cycle', (SELECT cycle FROM base_data LIMIT 1),
        'areas', COALESCE((
            SELECT json_agg(row_to_json(a)) 
            FROM (SELECT * FROM areas_json ORDER BY id ASC) a
        ), '[]'::json)
    ) INTO v_result;

    RETURN v_result;
END;
$$;


ALTER FUNCTION odiseo.fn_get_exam_generated_questions(p_uuid uuid) OWNER TO postgres;

--
-- Name: fn_get_exam_inconsistency_status(bigint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_exam_inconsistency_status(p_cycle_id bigint, p_university_id bigint, p_company_id bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
                    DECLARE
                        v_has_expected boolean;
                        v_has_error boolean;
                    BEGIN
                        SELECT EXISTS (
                            SELECT 1
                            FROM type_material tm
                            JOIN cycle c ON c.id = tm.cycle_id
                            WHERE c.id = p_cycle_id AND tm.fl_exam = true AND tm.fl_status = true
                        ) INTO v_has_expected;

                        IF NOT v_has_expected THEN
                            RETURN 'without-type-material';
                        END IF;

                        SELECT EXISTS (
                            WITH request_info AS (
                                SELECT c.id AS cycle_id
                                FROM cycle c WHERE c.id = p_cycle_id
                            )
                            , expected_raw AS (
                                SELECT
                                    tma.area_id::smallint, tm.id::smallint AS type_material_id,
                                    tmt.type_exam_id, te.name type_exam,
                                    tmc.course_id::smallint, s.id AS syllabus_id,
                                    v.is_text_record, v.expected_amount
                                FROM type_material tm
                                JOIN request_info ri ON tm.cycle_id = ri.cycle_id
                                JOIN type_material_template tmt ON tmt.id = tm.type_material_template_id
                                JOIN type_exams te ON te.id = tmt.type_exam_id 
                                JOIN type_material_area tma ON tma.type_material_id = tm.id
                                JOIN type_material_area_courses tmac ON tmac.type_material_area_id = tma.id
                                JOIN type_material_course tmc ON tmc.id = tmac.type_material_course_id AND tmc.type_material_id = tm.id
                                JOIN course c ON c.id = tmc.course_id
                                LEFT JOIN syllabus s ON s.course_id = c.id AND s.cycle_id = p_cycle_id AND s.university_id = p_university_id AND s.company_id = p_company_id AND s.fl_status = true
                                CROSS JOIN LATERAL (
                                    VALUES
                                        (FALSE, tmc.amount_question),
                                        (TRUE, COALESCE(tmc.amount_text, 0))
                                ) AS v(is_text_record, expected_amount)
                                WHERE tm.fl_exam = true AND tm.fl_status = true AND tma.fl_status = true AND tmc.fl_status = true AND tmac.fl_status = true
                                AND (v.is_text_record = FALSE OR c.apply_text = TRUE)
                                AND v.expected_amount > 0
                            )
                            , materials_type_2 AS (
                                SELECT DISTINCT er.type_material_id FROM expected_raw er WHERE er.type_exam = 'Tipo 2'
                            )
                            , base_template_weeks AS (
                                SELECT tmdt.type_material_id, tmdt.week
                                FROM type_material_detail_template tmdt
                                JOIN materials_type_2 mt2 ON tmdt.type_material_id = mt2.type_material_id
                                WHERE tmdt.fl_status IS TRUE
                            )
                            , all_materials_periods_raw AS (
                                SELECT
                                    btw.type_material_id, btw.week AS eval_week,
                                    (COALESCE(LAG(btw.week) OVER (PARTITION BY btw.type_material_id ORDER BY btw.week), 0) + 1)::smallint AS current_starting_week,
                                    btw.week::smallint AS current_ending_week,
                                    (ROW_NUMBER() OVER (PARTITION BY btw.type_material_id ORDER BY btw.week))::smallint AS week_order
                                FROM base_template_weeks btw
                            ) 
                            , all_materials_periods_precalculated AS (
                                SELECT ampr.type_material_id, ampr.eval_week, 1::smallint AS period_number, ampr.current_starting_week AS starting_week, ampr.current_ending_week AS ending_week
                                FROM all_materials_periods_raw ampr
                                UNION ALL
                                SELECT ampr.type_material_id, ampr.eval_week, 2::smallint AS period_number, 1::smallint AS starting_week, (ampr.current_starting_week - 1)::smallint AS ending_week
                                FROM all_materials_periods_raw ampr WHERE ampr.week_order > 1
                            )
                            , actual_levels AS (
                                SELECT emcac.exam_area_id::smallint AS area_id, emc.type_material_id::smallint, emcac.course_id::smallint, FALSE AS is_text_record, COALESCE(SUM(emcacl.amount_question), 0)::INTEGER AS level_amount
                                FROM exam_material_configurations emc
                                JOIN exam_material_config_area_courses emcac ON emc.id = emcac.exam_material_config_id
                                JOIN exam_material_config_area_course_levels emcacl ON emcac.id = emcacl.exam_material_config_area_course_id AND emcacl.fl_status = true
                                JOIN course_level cl ON cl.level_id = emcacl.level_id AND cl.course_id = emcac.course_id AND cl.fl_status = true
                                WHERE emc.fl_status = true AND emcac.fl_status = true AND emc.cycle_id = p_cycle_id  AND emc.company_id = p_company_id
                                GROUP BY emcac.exam_area_id, emc.type_material_id, emcac.course_id
                                UNION ALL
                                SELECT ttemc.area_id::smallint, emc.type_material_id::smallint, ttemc.course_id::smallint, TRUE AS is_text_record, COALESCE(SUM(ttemc.text_amount), 0)::INTEGER AS level_amount
                                FROM exam_material_configurations emc
                                JOIN type_text_exam_material_configuration ttemc ON emc.id = ttemc.exam_material_config_id
                                WHERE emc.fl_status = true AND ttemc.deleted_at IS NULL AND emc.cycle_id = p_cycle_id  AND emc.company_id = p_company_id
                                GROUP BY ttemc.area_id, emc.type_material_id, ttemc.course_id
                            ) 
                            , cte_valid_syllabus_weeks AS (
                                SELECT distinct st.syllabus_id, stw.week, FALSE AS is_text_record
                                FROM syllabus_topic st
                                JOIN syllabus s ON s.id = st.syllabus_id 
                                JOIN syllabus_topic_week stw ON stw.syllabus_topic_id = st.id
                                WHERE st.fl_status IS TRUE AND stw.fl_status IS TRUE AND stw.total_questions_amount > 0 AND s.cycle_id = p_cycle_id AND s.university_id = p_university_id AND s.company_id = p_company_id
                                UNION ALL
                                SELECT distinct stw.syllabus_id, stw.week, TRUE AS is_text_record
                                FROM syllabus_text_weeks stw
                                JOIN syllabus s ON s.id = stw.syllabus_id 
                                JOIN syllabus_text_distributions std ON std.syllabus_text_week_id = stw.id
                                JOIN type_material tm ON tm.id = std.type_material_id
                                WHERE stw.fl_status IS TRUE AND std.fl_status IS TRUE AND tm.fl_status IS TRUE AND tm.description <> 'ECO' AND s.cycle_id = p_cycle_id AND s.university_id = p_university_id AND s.company_id = p_company_id
                            )
                            , syllabus_valid_weeks_agg AS (
                                SELECT cvsw.syllabus_id, cvsw.is_text_record, array_agg(cvsw.week) AS arr_weeks
                                FROM cte_valid_syllabus_weeks cvsw
                                GROUP BY cvsw.syllabus_id, cvsw.is_text_record
                            )
                            SELECT 1
                            FROM expected_raw er
                            JOIN type_material_detail_template tmdt ON tmdt.type_material_id = er.type_material_id AND tmdt.fl_status = true
                            LEFT JOIN actual_levels al ON al.area_id = er.area_id AND al.type_material_id = er.type_material_id AND al.course_id = er.course_id AND al.is_text_record = er.is_text_record
                            LEFT JOIN syllabus_valid_weeks_agg svw ON svw.syllabus_id = er.syllabus_id AND svw.is_text_record = er.is_text_record
                            LEFT JOIN all_materials_periods_precalculated p ON p.type_material_id = er.type_material_id AND p.eval_week = tmdt.week AND er.type_exam = 'Tipo 2'
                            WHERE 
                                (er.expected_amount != COALESCE(al.level_amount, 0))
                                OR 
                                (
                                    CASE 
                                        WHEN er.syllabus_id IS NULL OR svw.arr_weeks IS NULL THEN FALSE
                                        WHEN er.type_exam = 'Tipo 1' THEN tmdt.week = ANY(svw.arr_weeks)
                                        WHEN er.type_exam = 'Tipo 2' THEN COALESCE((SELECT bool_or(w BETWEEN p.starting_week AND p.ending_week) FROM unnest(svw.arr_weeks) AS w), FALSE)
                                        WHEN er.type_exam = 'Tipo 3' THEN array_length(svw.arr_weeks, 1) > 0
                                        ELSE FALSE 
                                    END
                                ) = FALSE 
                        ) INTO v_has_error;

                        IF v_has_error THEN
                            RETURN 'with-observations';
                        ELSE
                            RETURN 'without-observations';
                        END IF;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_get_exam_inconsistency_status(p_cycle_id bigint, p_university_id bigint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_get_exam_questions(character varying, integer, integer, integer, integer, integer, integer, jsonb, smallint, smallint, smallint, smallint, character varying, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_exam_questions(p_search character varying, p_type_material_id integer, p_material_id integer, p_week integer, p_course_id integer, p_topic_id integer, p_subtopic_id integer, p_area_ids jsonb, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_version smallint, p_year character varying, p_show_missing_ones boolean) RETURNS TABLE(id bigint, material_exam_area_week_id bigint, order_course smallint, course character varying, course_id smallint, topic character varying, topic_id smallint, subtopic character varying, subtopic_id smallint, code character varying, level_to_be_found bigint, level_id bigint, level bigint, columns smallint, question_id bigint, config_alternative_id bigint, type_material_id smallint, type_material character varying, course_code character varying, topic_code character varying, subtopic_code character varying, type character varying, position_question smallint, status character varying, frequent_subtopic boolean, origin_question jsonb, type_question text, exam_area character varying, exam_area_id smallint, fl_is_manual boolean, category character varying, subcategory character varying, subquestion jsonb, correlativo text)
    LANGUAGE plpgsql
    AS $$
                DECLARE v_area_ids SMALLINT[];
                DECLARE v_week_type_material JSONB;
                DECLARE C_MORE_RECENT_VERSION SMALLINT DEFAULT 1;
                BEGIN
                    IF p_area_ids IS NOT NULL THEN
                        v_area_ids := ARRAY(SELECT JSONB_ARRAY_ELEMENTS_TEXT(p_area_ids)::SMALLINT);
                    END IF;

                    SELECT jsonb_agg(meaw.id)
                    INTO v_week_type_material
                    FROM detail_week_type_mat dwtm
                    JOIN material_exam_area_week meaw ON meaw.week_type_material_id = dwtm.id
                    WHERE 1 = 1
                        AND dwtm.material_id = p_material_id
                        AND dwtm.type_material_id = p_type_material_id
                        AND dwtm.week = p_week
                        AND ( p_area_ids IS NULL OR meaw.area_id = ANY(v_area_ids) )
                        AND dwtm.fl_status = true
                        AND meaw.fl_status = true;

                    RETURN QUERY
                    WITH tbl_material AS (
                        SELECT
                            m.id, m.university_id, m.cycle_id
                        FROM material m
                        WHERE m.id = p_material_id
                    ), area_ids AS (
                        SELECT JSONB_ARRAY_ELEMENTS_TEXT(v_week_type_material)::BIGINT AS exam_area_id
                    ), parents_questions_and_subquestions_to_extract AS ( 
                        SELECT
                            mepq.material_exam_area_week_id AS material_exam_area_week_id,
                            mepq.id AS material_exam_parent_question_id,
                            mepq.parent_question_id AS parent_question_id,
                            mepq.expected_level AS expected_level,
                            mepq.current_level AS current_level,
                            mepq.position AS text_position,
                            mepq.course_id AS course_id,
                            JSONB_ARRAY_ELEMENTS(mepq.subquestion) AS subquestion
                        FROM material_exam_parent_question mepq
                        WHERE 1 = 1
                        AND mepq.deleted_at IS NULL
                        AND mepq.material_exam_area_week_id IN ( SELECT xs.exam_area_id FROM area_ids xs )
                        AND ( p_show_missing_ones IS NULL OR p_show_missing_ones IS FALSE OR ( p_show_missing_ones IS TRUE AND mepq.parent_question_id IS NULL ) )
                    ), subquestions_extracted AS (
                        SELECT 
                            pet.material_exam_area_week_id,
                            pet.material_exam_parent_question_id,
                            pet.parent_question_id,
                            pet.expected_level,
                            pet.current_level,
                            pet.text_position, -- <-- Version 1.1
                            pet.course_id,
                            (pet.subquestion->>'question_id')::INTEGER AS question_id,
                            (pet.subquestion->>'topic_id')::INTEGER AS topic_id,
                            (pet.subquestion->>'subtopic_id')::INTEGER AS subtopic_id
                        FROM parents_questions_and_subquestions_to_extract pet
                    ), subquestions_and_parents AS (
                        SELECT
                            se.material_exam_area_week_id AS material_exam_area_week_id,
                            se.material_exam_parent_question_id AS material_exam_parent_question_id,
                            se.parent_question_id,
                            se.expected_level,
                            se.current_level,
                            se.text_position,
                            c.name AS course,
                            se.course_id,
                            c.code AS course_code,
                            pqn.code AS code,
                            tt.name AS category,
                            tts.name AS subcategory,
                            q.code AS question_code,
                            q.id AS question_id,
                            t.name AS topic,
                            t.code AS topic_code,
                            st.name AS subtopic,
                            st.code AS subtopic_code,
                            q.columns AS column_question,
                            q.config_alternative_id AS config_alternative_id,
                            pl.name AS parent_question_level
                        FROM subquestions_extracted se
                        LEFT JOIN parent_question pqn ON pqn.id = se.parent_question_id
                        LEFT JOIN level pl ON pl.id = pqn.level_id
                        LEFT JOIN question q ON q.id = se.question_id
                        LEFT JOIN type_text tt ON tt.id = pqn.type_text_id
                        LEFT JOIN type_text_subcategories tts ON tts.id = pqn.type_text_subcategory_id
                        LEFT JOIN course c ON c.id = se.course_id
                        LEFT JOIN topic t ON t.id = se.topic_id
                        LEFT JOIN subtopic st ON st.id = se.subtopic_id
                        WHERE 1 = 1
                        AND (p_course_id IS NULL OR se.course_id = p_course_id)
                        AND (p_topic_id IS NULL OR se.topic_id = p_topic_id)
                        AND (p_subtopic_id IS NULL OR se.subtopic_id = p_subtopic_id)
                        AND (p_search IS NULL OR pqn.code ILIKE '%' || p_search || '%')
                    ), group_parent_with_its_subquestions AS (
                        SELECT
                            sap.material_exam_area_week_id,
                            sap.material_exam_parent_question_id,
                            sap.parent_question_id,
                            sap.expected_level,
                            sap.current_level,
                            sap.text_position,
                            sap.code,
                            sap.category,
                            sap.subcategory,
                            sap.course,
                            sap.course_code,
                            sap.course_id,
                            sap.parent_question_level AS level,
                            JSONB_AGG(
                                JSONB_BUILD_OBJECT(
                                    'question_id', sap.question_id,
                                    'code', sap.question_code,
                                    'course', sap.course,
                                    'course_code', sap.course_code,
                                    'topic', sap.topic,
                                    'topic_code', sap.topic_code,
                                    'subtopic', sap.subtopic,
                                    'subtopic_code', sap.subtopic_code,
                                    'columns', sap.column_question,
                                    'config_alternative_id', sap.config_alternative_id
                                )
                            ) AS subquestions
                        FROM subquestions_and_parents sap
                        GROUP BY
                            sap.material_exam_parent_question_id,
                            sap.parent_question_id,
                            sap.expected_level,
                            sap.current_level,
                            sap.code,
                            sap.category,
                            sap.subcategory,
                            sap.course,
                            sap.course_code,
                            sap.course_id,
                            sap.parent_question_level,
                            sap.material_exam_area_week_id,
                            sap.text_position
                    ), add_ordering_by_course_in_text AS (
                        SELECT
                            gpw.*,
                            tml.id AS type_material_id,
                            tml.description AS type_material,
                            tor.position AS order_course,
                            mkk.area_id exam_area_id,
                            ea.description AS exam_area
                        FROM group_parent_with_its_subquestions gpw
                        JOIN material_exam_area_week mkk ON gpw.material_exam_area_week_id = mkk.id
                        JOIN detail_week_type_mat mtt ON mtt.id = mkk.week_type_material_id
                        JOIN material m ON m.id = mtt.material_id
                        JOIN type_material tml ON tml.id = COALESCE(mtt.parent_type_material_id, mtt.type_material_id)
                        JOIN template_type_material_courses_order tor ON tor.template_type_material_id = tml.type_material_template_id AND gpw.course_id = tor.course_id
                        JOIN exam_area ea ON ea.id = mkk.area_id
                        WHERE(
                            (m.university_id = 16 AND tor.university_id = m.university_id)
                            OR (m.university_id != 16 AND tor.university_id IS NULL)
                        )
                    ), questions_origin AS (
                        SELECT
                            oq.question_id,
                            oq.year,
                            oq.version,
                            oq.modality_id,
                            oq.option_id,
                            oq.university_id,
                            u.slug AS university_name,
                            o.name AS option_name,
                            m.name AS modality_name,
                            ROW_NUMBER() OVER ( PARTITION BY oq.question_id ORDER BY oq.year DESC, oq."version" DESC, oq.created_at DESC ) AS absolute_version
                        FROM origin_question oq
                        JOIN question ssq ON ssq.id = oq.question_id AND oq.fl_status IS TRUE
                        LEFT JOIN origin_university u ON u.id = oq.university_id
                        LEFT JOIN option o ON o.id = oq.option_id
                        LEFT JOIN modality m ON m.id = oq.modality_id
                    ), more_recent_questions_origin AS (
                        SELECT
                            qon.question_id,
                            (
                                JSONB_AGG(
                                    JSONB_BUILD_ARRAY(
                                        JSONB_BUILD_OBJECT('name', qon.university_name, 'type', 'university', 'id', qon.university_id ),
                                        JSONB_BUILD_OBJECT('name', qon.option_name, 'type', 'option', 'id', qon.option_id ),
                                        JSONB_BUILD_OBJECT('name', qon.modality_name, 'type', 'modality', 'id', qon.modality_id ),
                                        JSONB_BUILD_OBJECT('name', fn_number_to_roman(qon.version), 'type', 'version', 'id', NULL ),
                                        JSONB_BUILD_OBJECT('name', qon.year, 'type', 'year', 'id', NULL )
                                    )
                                )->0
                            ) AS question_origin
                        FROM questions_origin qon
                        WHERE qon.absolute_version = C_MORE_RECENT_VERSION
                        GROUP BY qon.question_id
                    ), tbl_questions AS (
                        SELECT
                            meq.id AS id,
                            course_ordering.position AS order_course,
                            c.name AS course,
                            meq.course_id,
                            t.name AS topic,
                            meq.topic_id,
                            s.name AS subtopic,
                            meq.subtopic_id,
                            COALESCE(qsh.code, q.code) as code,
                            meq.level_id,
                            l.name AS level,
                            q.columns AS column_question,
                            meq.question_id AS question_id,
                            q.config_alternative_id,
                            dwt.type_material_id,
                            tm.description AS type_material,
                            c.code AS course_code,
                            t.code AS topic_code,
                            s.code AS subtopic_code,
                            meq.position AS position,
                            q.status,
                            COALESCE(fus.is_frequent, false) AS frequent_subtopic,
                            qn.question_origin,
                            'P' AS type_question,
                            ea.description AS exam_area,
                            ea.id AS area_exam_id,
                            meq.fl_is_manual AS fl_is_manual
                        FROM detail_week_type_mat dwt
                        INNER JOIN material m ON dwt.material_id = m.id
                        INNER JOIN material_exam_area_week meaw ON dwt.id = meaw.week_type_material_id AND meaw.id IN (SELECT xd.exam_area_id FROM area_ids xd)
                        INNER JOIN material_exam_question meq ON meaw.id = meq.material_exam_area_week_id AND meq.fl_status = true
                        LEFT JOIN question_shares qsh ON qsh.question_id = meq.question_id AND qsh.deleted_at IS NULL
                        LEFT JOIN question q ON meq.question_id = q.id
                        LEFT JOIN more_recent_questions_origin qn ON qn.question_id = q.id
                        LEFT JOIN course c ON meq.course_id = c.id
                        LEFT JOIN topic t ON meq.topic_id = t.id
                        LEFT JOIN subtopic s ON meq.subtopic_id = s.id
                        INNER JOIN level l ON meq.level_id = l.id
                        INNER JOIN type_material tm ON dwt.type_material_id = tm.id
                        LEFT JOIN configuration_alternative ca ON q.config_alternative_id = ca.id
                        INNER JOIN area a ON c.area_id = a.id
                        LEFT JOIN material_column_configurations mcc ON meq.topic_id = mcc.topic_id
                        LEFT JOIN type_material tm_ordering ON tm_ordering.id = COALESCE(dwt.parent_type_material_id, dwt.type_material_id)
                        LEFT JOIN template_type_material_courses_order course_ordering
                        ON course_ordering.template_type_material_id = tm_ordering.type_material_template_id
                        AND course_ordering.course_id = meq.course_id
                        AND (
                            (m.university_id = 16 AND course_ordering.university_id = 16)
                            OR
                            (COALESCE(m.university_id, 0) != 16 AND course_ordering.university_id IS NULL)
                        )
                        LEFT JOIN alternative al ON q.id = al.question_id
                        LEFT JOIN exam_area ea ON ea.id = meaw.area_id AND ea.fl_status = true
                        LEFT JOIN frequent_university_subtopic fus
                            ON 1 = 1
                            AND fus.university_id IN (SELECT tm.university_id FROM tbl_material tm)
                            AND fus.subtopic_id = q.subtopic_id
                            AND fus.fl_status IS TRUE
                        WHERE 1 = 1
                        AND ( p_course_id IS NULL OR meq.course_id = p_course_id )
                        AND ( p_topic_id IS NULL OR meq.topic_id = p_topic_id )
                        AND ( p_subtopic_id IS NULL OR meq.subtopic_id = p_subtopic_id )
                        AND ( p_search IS NULL OR q.code ILIKE '%' || p_search || '%' )
                        AND ( p_area_ids IS NULL OR ea.id = ANY(v_area_ids) )
                        AND ( p_university_id IS NULL OR EXISTS (
                            SELECT 1
                            FROM JSONB_ARRAY_ELEMENTS(qn.question_origin) AS origin
                            WHERE 1 = 1
                            AND origin->>'type' = 'university'
                            AND (origin->>'id')::SMALLINT = p_university_id
                        ))
                        AND ( p_option_id IS NULL OR EXISTS (
                            SELECT 1
                            FROM JSONB_ARRAY_ELEMENTS(qn.question_origin) AS origin
                            WHERE 1 = 1
                            AND origin->>'type' = 'option'
                            AND (origin->>'id')::SMALLINT = p_option_id
                        ))
                        AND ( p_modality_id IS NULL OR EXISTS (
                            SELECT 1
                            FROM JSONB_ARRAY_ELEMENTS(qn.question_origin) AS origin
                            WHERE 1 = 1
                            AND origin->>'type' = 'modality'
                            AND (origin->>'id')::SMALLINT = p_modality_id
                        ))
                        AND ( p_version IS NULL OR EXISTS (
                            SELECT 1
                            FROM JSONB_ARRAY_ELEMENTS(qn.question_origin) AS origin
                            WHERE 1 = 1
                            AND origin->>'type' = 'version'
                            AND origin->>'name' = fn_number_to_roman(p_version)
                        ))
                        AND ( p_year IS NULL OR EXISTS (
                            SELECT 1
                            FROM JSONB_ARRAY_ELEMENTS(qn.question_origin) AS origin
                            WHERE 1 = 1
                            AND origin->>'type' = 'year'
                            AND origin->>'name' = p_year
                        ))
                        GROUP BY
                            meq.id,
                            dwt.type_material_id,
                            dwt.parent_type_material_id,
                            course_ordering.position,
                            tm.description,
                            c.area_id,
                            a.description,
                            meq.course_id,
                            c.name,
                            c.code,
                            meq.topic_id,
                            t.name,
                            meq.subtopic_id,
                            s.name,
                            meq.level_id,
                            meq.question_id,
                            COALESCE(qsh.code, q.code),
                            q.description,
                            q.answer_id,
                            q.parent_id,
                            q.config_alternative_id,
                            ca.columns,
                            ca.styles,
                            mcc.column_count,
                            mcc.column_width,
                            mcc.column_spacing,
                            mcc.layout_format,
                            mcc.number_format,
                            ca.fl_image,
                            t.code,
                            s.code,
                            l.name,
                            q.columns,
                            ea.id,
                            meq.position,
                            q.status,
                            fus.is_frequent,
                            qn.question_origin
                    ), all_questions_and_texts AS ( -- <-- Version 1.1
                    SELECT
                        gwi.material_exam_parent_question_id AS id,
                        gwi.material_exam_area_week_id AS material_exam_area_week_id,
                        gwi.order_course,
                        gwi.course,
                        gwi.course_id,
                        NULL AS topic,
                        NULL AS topic_id,
                        NULL AS subtopic,
                        NULL AS subtopic_id,
                        gwi.code,
                        gwi.expected_level AS level_to_be_found,
                        NULL AS level_id,
                        gwi.current_level AS level,
                        NULL AS column_question,
                        gwi.parent_question_id AS question_id,
                        NULL AS config_alternative_id,
                        gwi.type_material_id,
                        gwi.type_material AS type_material,
                        gwi.course_code AS course_code,
                        NULL AS topic_code,
                        NULL AS subtopic_code,
                        NULL AS type,
                        gwi.text_position AS position,
                        NULL AS status,
                        NULL AS frequent_subtopic,
                        NULL AS question_origin,
                        'T' AS type_question,
                        gwi.exam_area AS exam_area,
                        gwi.exam_area_id AS exam_area_id,
                        NULL AS fl_is_manual,
                        gwi.category AS category,
                        gwi.subcategory AS subcategory,
                        gwi.subquestions AS subquestions
                    FROM add_ordering_by_course_in_text gwi

                    UNION ALL

                    SELECT
                        qwt.id AS id,
                        NULL AS material_exam_area_week_id,
                        qwt.order_course,
                        qwt.course,
                        qwt.course_id,
                        qwt.topic,
                        qwt.topic_id,
                        qwt.subtopic,
                        qwt.subtopic_id,
                        qwt.code,
                        NULL::BIGINT AS level_to_be_found,
                        qwt.level_id,
                        qwt.level::BIGINT,
                        qwt.column_question,
                        qwt.question_id,
                        qwt.config_alternative_id,
                        qwt.type_material_id,
                        qwt.type_material,
                        qwt.course_code AS course_code,
                        qwt.topic_code AS topic_code,
                        qwt.subtopic_code AS subtopic_code,
                        NULL::CHARACTER VARYING AS type,
                        qwt.position::SMALLINT AS position,
                        qwt.status,
                        qwt.frequent_subtopic,
                        qwt.question_origin,
                        qwt.type_question,
                        qwt.exam_area,
                        qwt.area_exam_id,
                        qwt.fl_is_manual AS fl_is_manual,
                        NULL AS category,
                        NULL AS subcategory,
                        NULL::JSONB AS subquestions
                    FROM tbl_questions qwt
                    WHERE ( p_show_missing_ones IS NULL OR p_show_missing_ones IS FALSE OR ( p_show_missing_ones IS TRUE AND qwt.question_id IS NULL ) )
                    ),
                    with_row_counts AS (
                        SELECT 
                            qt.*,
                            CASE 
                                WHEN qt.type_question = 'P' THEN 1
                                WHEN qt.type_question = 'T' THEN jsonb_array_length(COALESCE(qt.subquestions, '[]'::jsonb))
                                ELSE 0
                            END as row_slots
                        FROM all_questions_and_texts qt
                    ),
                    with_running_totals AS (
                        SELECT 
                            wrc.*,
                            COALESCE(SUM(row_slots) OVER (
                                PARTITION BY wrc.exam_area_id 
                                ORDER BY 
                                    wrc.order_course,
                                    wrc.type_question DESC,
                                    wrc.fl_is_manual,
                                    wrc.topic_code,
                                    wrc.subtopic_code,
                                    wrc.level,
                                    CASE WHEN wrc.question_id IS NOT NULL THEN 0 ELSE 1 END,
                                    wrc.question_id
                                ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
                            ), 0) - row_slots AS start_counter
                        FROM with_row_counts wrc
                    )
                    SELECT
                        wrt.id,
                        wrt.material_exam_area_week_id,
                        wrt.order_course,
                        wrt.course,
                        wrt.course_id,
                        wrt.topic,
                        wrt.topic_id,
                        wrt.subtopic,
                        wrt.subtopic_id,
                        wrt.code,
                        wrt.level_to_be_found,
                        wrt.level_id,
                        wrt.level,
                        wrt.column_question,
                        wrt.question_id,
                        wrt.config_alternative_id,
                        wrt.type_material_id,
                        wrt.type_material,
                        wrt.course_code,
                        wrt.topic_code,
                        wrt.subtopic_code,
                        wrt.type,
                        wrt.position,
                        wrt.status,
                        wrt.frequent_subtopic,
                        wrt.question_origin,
                        wrt.type_question,
                        wrt.exam_area,
                        wrt.exam_area_id,
                        wrt.fl_is_manual,
                        wrt.category,
                        wrt.subcategory,
                        CASE
                            WHEN wrt.type_question = 'T' AND wrt.subquestions IS NOT NULL THEN (
                                SELECT jsonb_agg(
                                    sub.elem || jsonb_build_object(
                                        'correlativo',
                                        CASE
                                            WHEN (sub.elem->>'question_id') IS NOT NULL AND (sub.elem->>'question_id')::int > 0 
                                            THEN LEFT(UPPER(wrt.type_material), 4) || '-' || (wrt.start_counter + sub.ordinality)::text
                                            ELSE ''
                                        END
                                    )
                                )
                                FROM jsonb_array_elements(wrt.subquestions) WITH ORDINALITY AS sub(elem, ordinality)
                            )
                            ELSE wrt.subquestions
                        END as subquestions,
                        CASE
                            WHEN wrt.type_question = 'P' THEN
                                CASE
                                    WHEN wrt.question_id IS NOT NULL AND wrt.question_id > 0
                                    THEN LEFT(UPPER(wrt.type_material), 4) || '-' || (wrt.start_counter + 1)::text
                                    ELSE ''
                                END
                            ELSE ''
                        END AS correlativo
                    FROM with_running_totals wrt
                    ORDER BY
                        wrt.order_course,
                        wrt.type_question DESC,
                        wrt.fl_is_manual,
                        wrt.topic_code,
                        wrt.subtopic_code,
                        wrt.level,
                        CASE WHEN wrt.question_id IS NOT NULL THEN 0 ELSE 1 END,
                        wrt.question_id;
                END;
                $$;


ALTER FUNCTION odiseo.fn_get_exam_questions(p_search character varying, p_type_material_id integer, p_material_id integer, p_week integer, p_course_id integer, p_topic_id integer, p_subtopic_id integer, p_area_ids jsonb, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_version smallint, p_year character varying, p_show_missing_ones boolean) OWNER TO postgres;

--
-- Name: fn_get_exam_subquestions_per_text(bigint, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_exam_subquestions_per_text(p_type_material_id bigint, p_course_id smallint, p_exam_area_id smallint) RETURNS TABLE(course_id smallint, exam_area_id smallint, subquestion_amount smallint, text_number smallint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        ttma.course_id AS course_id,
        ttma.exam_area_id AS exam_area_id,
        ttma.subquestion_amount AS subquestion_amount,
        ttma.position AS text_number
    FROM type_material tm
    LEFT JOIN type_text_material_type_course_area ttma ON tm.id = ttma.type_material_id
    WHERE 1 = 1
      AND tm.id = p_type_material_id
      AND ( p_course_id IS NULL OR ttma.course_id = p_course_id )
      AND ( p_exam_area_id IS NULL OR ttma.exam_area_id = p_exam_area_id )
      AND ttma.deleted_at IS NULL
    ORDER BY
        ttma.exam_area_id,
        ttma.course_id,
        ttma.position ASC;
END;
$$;


ALTER FUNCTION odiseo.fn_get_exam_subquestions_per_text(p_type_material_id bigint, p_course_id smallint, p_exam_area_id smallint) OWNER TO postgres;

--
-- Name: fn_get_exam_usage_stats(smallint, bigint, smallint, bigint, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_exam_usage_stats(p_type_material_id smallint, p_material_id bigint, p_week smallint, p_user_id bigint, p_force_regenerate boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
                            DECLARE
                                v_result JSONB;
                                v_detail_id BIGINT;
                                v_global_stats_id BIGINT;
                                v_area_stats_id BIGINT;
                                v_area_json JSONB;
                            BEGIN

                                SELECT id INTO v_detail_id
                                FROM odiseo.detail_week_type_mat
                                WHERE material_id = p_material_id
                                AND type_material_id = p_type_material_id
                                AND week = p_week
                                AND fl_status IS TRUE
                                LIMIT 1;

                                IF v_detail_id IS NULL THEN
                                    RETURN '[]'::jsonb;
                                END IF;

                                SELECT id INTO v_global_stats_id
                                FROM material_exam_stats_global
                                WHERE detail_week_type_mat_id = v_detail_id
                                AND deleted_at IS NULL
                                LIMIT 1;

                                IF v_global_stats_id IS NOT NULL AND p_force_regenerate IS TRUE THEN
                                    DELETE FROM material_exam_stats_global WHERE id = v_global_stats_id;
                                    v_global_stats_id := NULL;
                                END IF;

                                -- Bloque de lectura de caché (Ya incluía los IDs en tu código original, se mantienen)
                                IF v_global_stats_id IS NOT NULL THEN
                                    SELECT jsonb_build_object(
                                        'number_pages', g.number_pages,
                                        'pages_exam_area', COALESCE(g.pages_details, '[]'::jsonb),
                                        'total_questions', g.total_questions,
                                        'new_questions', g.new_questions,
                                        'repeated_year', g.repeated_year,
                                        'repeated_history', g.repeated_history,
                                        'repeated_area', COALESCE(g.repeated_area, 0), 
                                        'details', COALESCE((
                                            SELECT jsonb_agg(
                                                jsonb_build_object(
                                                    'name', a.area_name,
                                                    'area_id', a.area_id,
                                                    'total_questions', a.total_questions,
                                                    'new_questions', a.new_questions,
                                                    'repeated_year', a.repeated_year,
                                                    'repeated_history', a.repeated_history,
                                                    'repeated_area', COALESCE(a.repeated_area, 0),
                                                    'questions_new_questions', COALESCE(a.question_details->'questions_new_questions', '[]'::jsonb),
                                                    'questions_repeated_year', COALESCE(a.question_details->'questions_repeated_year', '[]'::jsonb),
                                                    'questions_repeated_history', COALESCE(a.question_details->'questions_repeated_history', '[]'::jsonb),
                                                    'questions_repeated_area', COALESCE(a.question_details->'questions_repeated_area', '[]'::jsonb),

                                                    'details', COALESCE((
                                                        SELECT jsonb_agg(
                                                            jsonb_build_object(
                                                                'name', c.course_name,
                                                                'course_id', c.course_id,
                                                                'total_questions', c.total_questions,
                                                                'new_questions', c.new_questions,
                                                                'repeated_year', c.repeated_year,
                                                                'repeated_history', c.repeated_history,
                                                                'repeated_area', COALESCE(c.repeated_area, 0),
                                                                'questions_new_questions', COALESCE(c.question_details->'questions_new_questions', '[]'::jsonb),
                                                                'questions_repeated_year', COALESCE(c.question_details->'questions_repeated_year', '[]'::jsonb),
                                                                'questions_repeated_history', COALESCE(c.question_details->'questions_repeated_history', '[]'::jsonb),
                                                                'questions_repeated_area', COALESCE(c.question_details->'questions_repeated_area', '[]'::jsonb)
                                                            ) ORDER BY c.course_name ASC
                                                        )
                                                        FROM material_exam_stats_area_courses c
                                                        WHERE c.area_stats_id = a.id
                                                        AND c.deleted_at IS NULL
                                                    ), '[]'::jsonb)
                                                ) ORDER BY a.area_name ASC
                                            )
                                            FROM material_exam_stats_areas a
                                            WHERE a.material_exam_stats_global_id = g.id
                                            AND a.deleted_at IS NULL
                                        ), '[]'::jsonb)
                                    ) INTO v_result
                                    FROM material_exam_stats_global g
                                    WHERE g.id = v_global_stats_id;

                                    RETURN v_result;
                                END IF;

                                -- Inicio del cálculo
                                WITH material_details AS (
                                    SELECT cycle_id, university_id, company_id
                                    FROM material
                                    WHERE id = p_material_id AND fl_status IS TRUE
                                    LIMIT 1
                                ),
                                detail_target AS (
                                    SELECT v_detail_id AS id
                                ), pages_breakdown_calc AS (
                                    SELECT 
                                        COALESCE(MAX(meaw.number_pages), 0) as max_pages,
                                        COALESCE(
                                            jsonb_agg(
                                                jsonb_build_object(
                                                    'name', COALESCE(ga.description, 'General'),
                                                    'number_pages', COALESCE(meaw.number_pages, 0)
                                                ) ORDER BY ga.description ASC
                                            ), 
                                        '[]'::jsonb) as pages_json
                                    FROM material_exam_area_week meaw
                                    LEFT JOIN exam_area ga ON ga.id = meaw.area_id 
                                    WHERE meaw.week_type_material_id = (SELECT id FROM detail_target)
                                    AND meaw.fl_status = TRUE
                                ), year_cycle_material AS (
                                    SELECT year
                                    FROM cycle
                                    WHERE id = (SELECT cycle_id FROM material_details) AND fl_status IS TRUE
                                ), material_exam_question_data AS (
                                    SELECT
                                        meq.id,
                                        meq.material_exam_area_week_id,
                                        meq.course_id,
                                        c.name AS course_name,
                                        a.id AS area_id,
                                        UPPER(a.description) AS area_desc,
                                        meq.question_id,
                                        NULL::bigint as parent_question_id,
                                        ea.id exam_area_id,
                                        ea.description exam_area_description
                                    FROM material_exam_question meq 
                                    JOIN material_exam_area_week meaw ON meaw.id = meq.material_exam_area_week_id 
                                    JOIN exam_area ea ON ea.id = meaw.area_id 
                                    JOIN course c ON c.id = meq.course_id
                                    JOIN area a ON c.area_id = a.id
                                    WHERE meaw.week_type_material_id = (SELECT id FROM detail_target)
                                    AND meq.fl_status = true
                                    UNION ALL
                                    SELECT
                                        mepq.id,
                                        mepq.material_exam_area_week_id,
                                        mepq.course_id,
                                        c.name AS course_name,
                                        a.id AS area_id,
                                        UPPER(a.description) AS area_desc,
                                        expanded.question_id, 
                                        mepq.parent_question_id,
                                        ea.id exam_area_id,
                                        ea.description exam_area_description
                                    FROM material_exam_parent_question mepq 
                                    JOIN material_exam_area_week meaw ON meaw.id = mepq.material_exam_area_week_id
                                    JOIN exam_area ea ON ea.id = meaw.area_id 
                                    JOIN course c ON c.id = mepq.course_id
                                    JOIN area a ON c.area_id = a.id
                                    CROSS JOIN LATERAL jsonb_to_recordset(
                                        COALESCE(mepq.subquestion, '[]'::jsonb)
                                    ) AS expanded(question_id BIGINT)
                                    WHERE mepq.parent_question_id IS NOT NULL 
                                    AND mepq.deleted_at IS NULL
                                    AND meaw.week_type_material_id = (SELECT id FROM detail_target)
                                ), questions_history_questions AS (
                                    SELECT
                                        mbq.question_id,
                                        COUNT(qhc.id) AS total_history_count,
                                        MAX(EXTRACT(YEAR FROM qhc.start_date)) AS last_seen_year
                                    FROM material_exam_question_data mbq
                                    LEFT JOIN (
                                        SELECT
                                            qhc.id,
                                            c.id AS cycle_id,
                                            c.start_date,
                                            qhc.question_id
                                        FROM question_history_cycle qhc
                                        JOIN cycle c ON qhc.cycle_id = c.id
                                        WHERE c.company_id = (select company_id from material_details)
                                            AND qhc.fl_status IS TRUE
                                            AND qhc.cycle_id <> (SELECT cycle_id FROM material_details)
                                            AND c.fl_status IS TRUE
                                            AND EXTRACT(YEAR FROM c.start_date) <= (SELECT ycm.year FROM year_cycle_material ycm)
                                    ) qhc ON mbq.question_id = qhc.question_id
                                    WHERE mbq.parent_question_id IS NULL
                                    GROUP BY mbq.question_id
                                ), question_history_parent AS (
                                    SELECT
                                        mbq.question_id,
                                        COUNT(qhc.id) AS total_history_count,
                                        MAX(EXTRACT(YEAR FROM qhc.start_date)) AS last_seen_year
                                    FROM material_exam_question_data mbq
                                    LEFT JOIN (
                                        SELECT
                                            qhuepq.id,
                                            c.id AS cycle_id,
                                            c.start_date,
                                            qhuepq.question_id
                                        FROM question_history_usage_exam_parent_question qhuepq 
                                        JOIN material_exam_area_week meaw ON meaw.id = qhuepq.material_exam_area_week_id 
                                        JOIN detail_week_type_mat dwtm ON dwtm.id = meaw.week_type_material_id 
                                        JOIN material m ON m.id = dwtm.material_id 
                                        JOIN cycle c ON c.id = m.cycle_id 
                                        WHERE c.company_id = (select company_id from material_details)
                                        AND c.id <> (SELECT cycle_id FROM material_details)
                                        AND c.fl_status IS TRUE
                                        AND EXTRACT(YEAR FROM c.start_date) <= (SELECT ycm.year FROM year_cycle_material ycm)
                                    ) qhc ON mbq.question_id = qhc.question_id
                                    WHERE mbq.parent_question_id IS NOT NULL
                                    GROUP BY mbq.question_id
                                ),
                                questions_history_stats AS (
                                    SELECT * FROM questions_history_questions
                                    UNION ALL
                                    SELECT * FROM question_history_parent
                                ),
                                classified_questions AS (
                                    SELECT
                                        mbq.area_id,
                                        mbq.area_desc,
                                        mbq.course_id,
                                        mbq.course_name,
                                        mbq.question_id,
                                        q.code AS question_code,
                                        mbq.exam_area_id,
                                        mbq.exam_area_description,
                                        CASE
                                            WHEN stats.total_history_count = 0
                                                OR (ycm.year - stats.last_seen_year) > (select number_years_to_consider_question_repeated from advanced_settings LIMIT 1) THEN 'NUEVA'
                                            WHEN (ycm.year - stats.last_seen_year) = 0 THEN 'REPETIDA_LECTIVO'
                                            ELSE 'REPETIDA_ANTERIOR'
                                        END AS status_code,
                                        ROW_NUMBER() OVER(PARTITION BY mbq.area_desc, mbq.course_name, mbq.question_id ORDER BY mbq.id) as appearance_num
                                    FROM material_exam_question_data mbq
                                    JOIN questions_history_stats stats ON mbq.question_id = stats.question_id
                                    JOIN question q ON q.id = mbq.question_id
                                    CROSS JOIN year_cycle_material ycm
                                    WHERE q.status IN ('VERI', 'APRB')
                                ), repeated_questions_details AS (
                                    SELECT 
                                        course_id,
                                        jsonb_agg(
                                            jsonb_build_object(
                                                'id', question_id, 
                                                'code', question_code, 
                                                'exam_areas', area_names
                                            )
                                        ) AS list_rep_area_json
                                    FROM (
                                        SELECT 
                                            course_id,
                                            question_id,
                                            question_code,
                                            array_agg(exam_area_description) AS area_names
                                        FROM classified_questions
                                        GROUP BY course_id, question_id, question_code
                                        HAVING COUNT(*) > 1
                                    ) sub_grouped
                                    GROUP BY course_id
                                ), stats_by_course AS (
                                    SELECT
                                        cq.area_id,
                                        cq.area_desc,
                                        cq.course_id,
                                        cq.course_name,
                                        SUM(CASE WHEN status_code = 'NUEVA' THEN 1 ELSE 0 END) AS nuevas,
                                        SUM(CASE WHEN status_code = 'REPETIDA_LECTIVO' THEN 1 ELSE 0 END) AS rep_lectivo,
                                        SUM(CASE WHEN status_code = 'REPETIDA_ANTERIOR' THEN 1 ELSE 0 END) AS rep_anterior,
                                        COUNT(DISTINCT CASE WHEN appearance_num > 1 THEN question_id END) AS rep_area,
                                        COUNT(*) AS total_curso,
                                        COALESCE(jsonb_agg(jsonb_build_object('id', question_id, 'code', question_code, 'exam_area_id', exam_area_id, 'exam_area_description', exam_area_description)) FILTER (WHERE status_code = 'NUEVA'), '[]'::jsonb) AS list_nuevas,
                                        COALESCE(jsonb_agg(jsonb_build_object('id', question_id, 'code', question_code, 'exam_area_id', exam_area_id, 'exam_area_description', exam_area_description)) FILTER (WHERE status_code = 'REPETIDA_LECTIVO'), '[]'::jsonb) AS list_rep_lectivo,
                                        COALESCE(jsonb_agg(jsonb_build_object('id', question_id, 'code', question_code, 'exam_area_id', exam_area_id, 'exam_area_description', exam_area_description)) FILTER (WHERE status_code = 'REPETIDA_ANTERIOR'), '[]'::jsonb) AS list_rep_anterior,
                                        COALESCE(rqd.list_rep_area_json, '[]'::jsonb) AS list_rep_area
                                    FROM classified_questions cq
                                    LEFT JOIN repeated_questions_details rqd ON rqd.course_id = cq.course_id
                                    GROUP BY 
                                        cq.area_id, 
                                        cq.area_desc, 
                                        cq.course_id, 
                                        cq.course_name,
                                        rqd.list_rep_area_json
                                ), stats_by_area AS (
                                    SELECT
                                        s.area_id,
                                        s.area_desc,
                                        SUM(s.nuevas) AS area_nuevas,
                                        SUM(s.rep_lectivo) AS area_lectivo,
                                        SUM(s.rep_anterior) AS area_anterior,
                                        SUM(s.rep_area) AS area_rep_area,
                                        SUM(s.total_curso) AS area_total,
                                        jsonb_agg(
                                            jsonb_build_object(
                                                'name', s.course_name,
                                                'course_id', s.course_id,
                                                'total_questions', s.total_curso,
                                                'new_questions', s.nuevas,
                                                'repeated_year', s.rep_lectivo,
                                                'repeated_history', s.rep_anterior,
                                                'repeated_area', s.rep_area,
                                                'questions_new_questions', s.list_nuevas,
                                                'questions_repeated_year', s.list_rep_lectivo,
                                                'questions_repeated_history', s.list_rep_anterior,
                                                'questions_repeated_area', s.list_rep_area
                                            ) ORDER BY s.course_name ASC
                                        ) AS cursos_json
                                    FROM stats_by_course s
                                    GROUP BY s.area_id, s.area_desc
                                )
                                SELECT jsonb_build_object(
                                    'number_pages', (SELECT max_pages FROM pages_breakdown_calc),
                                    'pages_details', (SELECT pages_json FROM pages_breakdown_calc),
                                    'total_questions', COALESCE(SUM(area_total), 0),
                                    'new_questions', COALESCE(SUM(area_nuevas), 0),
                                    'repeated_year', COALESCE(SUM(area_lectivo), 0),
                                    'repeated_history', COALESCE(SUM(area_anterior), 0),
                                    'repeated_area', COALESCE(SUM(area_rep_area), 0),
                                    'details', COALESCE(
                                        jsonb_agg(
                                            jsonb_build_object(
                                                'name', area_desc,
                                                'area_id', area_id,
                                                'total_questions', area_total,
                                                'new_questions', area_nuevas,
                                                'repeated_year', area_lectivo,
                                                'repeated_history', area_anterior,
                                                'repeated_area', area_rep_area,
                                                'questions_new_questions', (SELECT jsonb_agg(elems) FROM (SELECT jsonb_array_elements(value->'questions_new_questions') as elems FROM jsonb_array_elements(cursos_json) as value) t),
                                                'questions_repeated_year', (SELECT jsonb_agg(elems) FROM (SELECT jsonb_array_elements(value->'questions_repeated_year') as elems FROM jsonb_array_elements(cursos_json) as value) t),
                                                'questions_repeated_history', (SELECT jsonb_agg(elems) FROM (SELECT jsonb_array_elements(value->'questions_repeated_history') as elems FROM jsonb_array_elements(cursos_json) as value) t),
                                                'questions_repeated_area', (SELECT jsonb_agg(elems) FROM (SELECT jsonb_array_elements(value->'questions_repeated_area') as elems FROM jsonb_array_elements(cursos_json) as value) t),
                                                'details', cursos_json
                                            ) ORDER BY area_desc ASC
                                        ), '[]'::jsonb
                                    )
                                ) INTO v_result
                                FROM stats_by_area;

                                INSERT INTO material_exam_stats_global (
                                    detail_week_type_mat_id,
                                    number_pages,
                                    pages_details,
                                    total_questions,
                                    new_questions,
                                    repeated_year,
                                    repeated_history,
                                    repeated_area, 
                                    created_by,
                                    updated_by,
                                    created_at,
                                    updated_at
                                ) VALUES (
                                    v_detail_id,
                                    COALESCE((v_result->>'number_pages')::SMALLINT, 0),
                                    COALESCE(v_result->'pages_details', '[]'::jsonb),
                                    COALESCE((v_result->>'total_questions')::SMALLINT, 0),
                                    COALESCE((v_result->>'new_questions')::SMALLINT, 0),
                                    COALESCE((v_result->>'repeated_year')::SMALLINT, 0),
                                    COALESCE((v_result->>'repeated_history')::SMALLINT, 0),
                                    COALESCE((v_result->>'repeated_area')::SMALLINT, 0),
                                    p_user_id,
                                    p_user_id,
                                    NOW(),
                                    NOW()
                                ) RETURNING id INTO v_global_stats_id;

                                FOR v_area_json IN SELECT * FROM jsonb_array_elements(v_result->'details')
                                LOOP
                                    INSERT INTO material_exam_stats_areas (
                                        material_exam_stats_global_id,
                                        area_name,
                                        area_id, 
                                        total_questions,
                                        new_questions,
                                        repeated_year,
                                        repeated_history,
                                        repeated_area, 
                                        question_details,
                                        created_at,
                                        updated_at
                                    ) VALUES (
                                        v_global_stats_id,
                                        v_area_json->>'name',
                                        (v_area_json->>'area_id')::BIGINT,
                                        (v_area_json->>'total_questions')::SMALLINT,
                                        (v_area_json->>'new_questions')::SMALLINT,
                                        (v_area_json->>'repeated_year')::SMALLINT,
                                        (v_area_json->>'repeated_history')::SMALLINT,
                                        (v_area_json->>'repeated_area')::SMALLINT,
                                        jsonb_build_object(
                                            'questions_new_questions', COALESCE(NULLIF(v_area_json->'questions_new_questions', 'null'::jsonb), '[]'::jsonb),
                                            'questions_repeated_year', COALESCE(NULLIF(v_area_json->'questions_repeated_year', 'null'::jsonb), '[]'::jsonb),
                                            'questions_repeated_history', COALESCE(NULLIF(v_area_json->'questions_repeated_history', 'null'::jsonb), '[]'::jsonb),
                                            'questions_repeated_area', COALESCE(NULLIF(v_area_json->'questions_repeated_area', 'null'::jsonb), '[]'::jsonb)
                                        ),
                                        NOW(),
                                        NOW()
                                    ) RETURNING id INTO v_area_stats_id;
                                
                                    INSERT INTO material_exam_stats_area_courses ( 
                                        area_stats_id,
                                        course_name,
                                        course_id, -- Insertando course_id
                                        total_questions,
                                        new_questions,
                                        repeated_year,
                                        repeated_history,
                                        repeated_area,
                                        question_details,
                                        created_at,
                                        updated_at
                                    )
                                    SELECT
                                        v_area_stats_id,
                                        value->>'name',
                                        (value->>'course_id')::BIGINT,
                                        (value->>'total_questions')::SMALLINT,
                                        (value->>'new_questions')::SMALLINT,
                                        (value->>'repeated_year')::SMALLINT,
                                        (value->>'repeated_history')::SMALLINT,
                                        (value->>'repeated_area')::SMALLINT,
                                        jsonb_build_object(
                                            'questions_new_questions', COALESCE(NULLIF(value->'questions_new_questions', 'null'::jsonb), '[]'::jsonb),
                                            'questions_repeated_year', COALESCE(NULLIF(value->'questions_repeated_year', 'null'::jsonb), '[]'::jsonb),
                                            'questions_repeated_history', COALESCE(NULLIF(value->'questions_repeated_history', 'null'::jsonb), '[]'::jsonb),
                                            'questions_repeated_area', COALESCE(NULLIF(value->'questions_repeated_area', 'null'::jsonb), '[]'::jsonb)
                                        ),
                                        NOW(),
                                        NOW()
                                    FROM jsonb_array_elements(v_area_json->'details') as value;
                                END LOOP;

                                RETURN v_result;
                            END;
                            $$;


ALTER FUNCTION odiseo.fn_get_exam_usage_stats(p_type_material_id smallint, p_material_id bigint, p_week smallint, p_user_id bigint, p_force_regenerate boolean) OWNER TO postgres;

--
-- Name: fn_get_failed_question_jobs(); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_failed_question_jobs() RETURNS TABLE(status character varying, process_type character varying, question_id bigint)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY
                    WITH latest_jobs AS (
                        SELECT
                            qpj.status,
                            qpj.process_type,
                            qpj.question_id,
                            qpj.updated_at,
                            ROW_NUMBER() OVER(PARTITION BY qpj.question_id ORDER BY qpj.updated_at DESC) as rn
                        FROM
                            question_pdf_jobs qpj
                    )
                    SELECT
                        lj.status,
                        lj.process_type,
                        lj.question_id
                    FROM
                        latest_jobs lj
                    JOIN question q ON q.id = lj.question_id
                    WHERE
                        lj.rn = 1 
                        AND lj.status = 'failed'
                        AND q.status NOT IN('ARCH', 'PEND')
                    ORDER BY
                        lj.updated_at ASC;
                END;
            $$;


ALTER FUNCTION odiseo.fn_get_failed_question_jobs() OWNER TO postgres;

--
-- Name: fn_get_group_material_periodicity(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_group_material_periodicity(p_material_id bigint) RETURNS TABLE(id smallint, description character varying, material_id bigint, fl_class_material boolean, fl_exam boolean, periodicity_id smallint, period character varying, quantity smallint, start_week smallint, group_previous_week boolean, group_remaining_week boolean, weeks jsonb, material_per_period jsonb, weeks_dates jsonb)
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                        RETURN QUERY
                        WITH tbl_material AS (
                            SELECT
                                m.id,
                                m.cycle_id,
                                m.university_id
                            FROM material m
                            JOIN cycle c ON m.cycle_id = c.id
                            WHERE m.id = p_material_id
                        ), tbl_material_per_period AS (
                            SELECT
                                mpp.material_id,
                                mpp.type_material_id,
                                COALESCE(mppb.start_week, mppe.start_week) AS start_week,
                                COALESCE(mppb.end_week, mppe.end_week) AS end_week
                            FROM material_per_period mpp
                            LEFT JOIN material_per_period_ballot mppb ON mpp.id = mppb.material_per_period_id
                            LEFT JOIN material_per_period_exam mppe ON mpp.id = mppe.material_per_period_id
                            WHERE mpp.material_id = p_material_id
                                AND mpp.deleted_by IS NULL
                                AND mppb.deleted_by IS NULL
                                AND mppe.deleted_by IS NULL
                        ), tbl_type_material AS (
                            SELECT
                                tm.id,
                                tm.description,
                                m.id AS material_id,
                                tm.fl_class_material,
                                tm.fl_exam,
                                COALESCE(tmp.periodicity_id, 1::SMALLINT) AS periodicity_id,
                                COALESCE(p.name, 'Semanal') AS period,
                                COALESCE(p.quantity, tmp.quantity_week, 1::SMALLINT) AS quantity,
                                COALESCE(tmp.start_week, 1::SMALLINT) AS start_week,
                                COALESCE(tmp.group_previous_week, false) AS group_previous_week,
                                COALESCE(tmp.group_remaining_week, false) AS group_remaining_week,
                                COALESCE((
                                    SELECT jsonb_agg(tmdt.week ORDER BY tmdt.week ASC)
                                    FROM type_material_detail_template tmdt
                                    WHERE tmdt.type_material_id = tm.id
                                        AND tmdt.fl_status = true
                                ), '[]'::JSONB) AS weeks,
                                COALESCE((
                                    SELECT jsonb_agg(jsonb_build_object(
                                        'type_material_id', tmpp.type_material_id,
                                        'start_week', tmpp.start_week,
                                        'end_week', tmpp.end_week
                                    )) AS per_period
                                    FROM tbl_material_per_period tmpp
                                    WHERE tmpp.type_material_id = tm.id
                                        AND tmpp.start_week IS NOT NULL
                                        AND tmpp.end_week IS NOT NULL
                                ), '[]'::JSONB) AS material_per_period,
                                COALESCE((
                                    SELECT jsonb_agg(
                                        jsonb_build_object(
                                            'week', tmdt.week,
                                            'start_date', cw.start_date,
                                            'end_date', cw.end_date
                                        ) ORDER BY tmdt.week ASC
                                    )
                                    FROM type_material_detail_template tmdt
                                    JOIN cycle_weeks cw ON tmdt.week = cw.week AND cw.cycle_id = m.cycle_id
                                    WHERE tmdt.type_material_id = tm.id
                                        AND tmdt.fl_status = true
                                ), '[]'::JSONB) AS weeks_dates

                            FROM type_material tm
                            JOIN tbl_material m ON tm.cycle_id = m.cycle_id
                            LEFT JOIN type_material_periodicity tmp ON tm.id = tmp.type_material_id
                                AND tmp.fl_status = true
                            LEFT JOIN periodicity p ON tmp.periodicity_id = p.id
                            WHERE tm.fl_status = true
                                AND tm.parent_id IS NULL
                        )
                        SELECT * FROM tbl_type_material ttm
                        ORDER BY
                            ttm.fl_exam ASC,
                            ttm.description ASC;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_get_group_material_periodicity(p_material_id bigint) OWNER TO postgres;

--
-- Name: fn_get_history_generated_questions(integer, integer, bigint, character varying, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_history_generated_questions(p_perpage integer, p_npage integer, p_question_id bigint, p_type_question character varying, p_shared_status character varying) RETURNS TABLE(cycle character varying, year integer, material character varying, exam_area character varying, created_at timestamp without time zone, week integer, status boolean, automatic boolean, histories jsonb, total bigint)
    LANGUAGE plpgsql
    AS $$
                DECLARE
                    C_MORE_RECENT_USAGE_ATTEMPT SMALLINT DEFAULT 1;
                    offset_val INTEGER;
                BEGIN
                    offset_val := p_perpage * (p_npage - 1);
                    RETURN QUERY
                    WITH text_history_exam AS (
                        SELECT
                            qhh.material_exam_area_week_id,
                            qhh.parent_question_id,
                            c.description AS cycle_description,
                            tm.description AS type_material_name,
                            ea.id AS exam_area_id,
                            ea.short_description AS exam_area_short_description,
                            ea.description AS exam_area,
                            dwtm.week AS week,
                            qhh.automatic AS automatic,
                            qhh.created_at,
                            CAST(EXTRACT(YEAR FROM qhh.created_at) AS INTEGER) AS year,
                            qhh.updated_at IS NULL AS fl_status
                        FROM question_history_usage_exam_parent_question qhh
                            JOIN material_exam_area_week meak ON meak.id = qhh.material_exam_area_week_id
                            JOIN exam_area ea ON ea.id = meak.area_id
                            JOIN detail_week_type_mat dwtm ON meak.week_type_material_id = dwtm.id
                            JOIN type_material tm ON tm.id = dwtm.type_material_id
                            JOIN material m ON m.id = dwtm.material_id
                            JOIN cycle c ON c.id = m.cycle_id
                            WHERE 1 = 1
                            AND (
                                ( p_type_question = 'T' AND parent_question_id = p_question_id ) OR
                                ( p_type_question = 'S' AND question_id = p_question_id )
                            )
                    ), get_last_attempt_to_used AS (
                        SELECT
                            the.cycle_description,
                            the.year AS year,
                            the.type_material_name,
                            the.exam_area_short_description,
                            the.exam_area_id,
                            the.exam_area,
                            the.week,
                            the.created_at,
                            the.fl_status,
                            the.automatic,
                            ROW_NUMBER() OVER (
                                PARTITION BY
                                    the.cycle_description,
                                    the.type_material_name,
                                    the.year,
                                    the.exam_area_id,
                                    the.week
                                ORDER BY the.created_at DESC
                            ) AS absolute_version
                        FROM text_history_exam the
                    ), exam_text_history AS (
                        SELECT
                            guu.cycle_description AS cycle,
                            MAX(guu.year) AS year,
                            MIN(guu.type_material_name) AS material,
                            STRING_AGG(DISTINCT guu.exam_area_short_description, '-') AS exam_area,
                            MAX(guu.created_at) AS created_at,
                            MAX(guu.week) AS week,
                            TRUE AS status,
                            TRUE AS automatic,
                            JSONB_AGG(
                                JSONB_BUILD_OBJECT(
                                    'exam_area', guu.exam_area,
                                    'created_at', guu.created_at,
                                    'fl_status', guu.fl_status,
                                    'automatic', guu.automatic,
                                    'area_id', guu.exam_area_id
                                )
                                ORDER BY guu.created_at
                            ) AS histories
                        FROM get_last_attempt_to_used guu
                        WHERE guu.absolute_version = 1
                        GROUP BY guu.cycle_description
                    ), latest_material_ballot AS (
                        SELECT
                            mbq.created_at,
                            mbq.fl_status,
                            mbq.question_history_id,
                            mbq.week_type_material_id,
                            ROW_NUMBER() OVER (PARTITION BY mbq.question_id, mbq.week_type_material_id ORDER BY mbq.created_at DESC) AS rn
                        FROM material_ballot_question mbq
                        LEFT JOIN question_subtopic qs ON qs.question_id = mbq.question_id
                        LEFT JOIN question_shares qsh ON qsh.subtopic_id = mbq.subtopic_id AND qsh.deleted_at IS NULL
                        LEFT JOIN LATERAL jsonb_array_elements(mbq.subquestion) AS subq_elem ON TRUE
                        WHERE CASE 
                                WHEN p_type_question = 'T' THEN mbq.parent_question_id = p_question_id
                                ELSE mbq.question_id = p_question_id 
                                OR (subq_elem->>'question_id')::int = p_question_id
                            END
                        AND (
                            CASE
                                WHEN p_shared_status = 'shared' THEN
                                    qsh.subtopic_id = mbq.subtopic_id

                                ELSE
                                    qs.subtopic_id = mbq.subtopic_id
                            END
                        )
                    ), cte_material_ballot_question AS (
                        SELECT
                            lmb.created_at,
                            lmb.fl_status,
                            lmb.question_history_id,
                            lmb.week_type_material_id
                        FROM latest_material_ballot lmb
                        WHERE rn = 1
                        ORDER BY week_type_material_id
                    ), latest_material_exam AS (
                        SELECT
                            meq.created_at,
                            meq.fl_status,
                            meq.question_history_id,
                            meq.material_exam_area_week_id,
                            meaw.area_id,
                            ea.description,
                            ea.short_description,
                            meaw.week_type_material_id,
                            ROW_NUMBER() OVER (PARTITION BY meq.question_id, meq.material_exam_area_week_id ORDER BY meq.created_at DESC) AS rn
                        FROM material_exam_question meq
                        JOIN material_exam_area_week meaw ON meq.material_exam_area_week_id = meaw.id
                        JOIN exam_area ea ON meaw.area_id = ea.id
                        WHERE meq.question_id = p_question_id
                    ), cte_material_exam_question AS (
                        SELECT
                            lme.created_at,
                            lme.fl_status,
                            lme.question_history_id,
                            lme.material_exam_area_week_id,
                            lme.area_id,
                            lme.description,
                            lme.short_description,
                            lme.week_type_material_id
                        FROM latest_material_exam lme
                        WHERE rn = 1
                        ORDER BY material_exam_area_week_id
                    ), group_material_exam_question AS (
                        SELECT
                        MAX(lme.created_at) AS created_at,
                        BOOL_OR(lme.fl_status) AS fl_status,
                        MAX(lme.question_history_id) AS question_history_id,
                        lme.week_type_material_id,
                        STRING_AGG(lme.short_description, '-') AS combined_areas
                        FROM latest_material_exam lme
                        WHERE lme.rn = 1
                        GROUP BY lme.week_type_material_id
                        ORDER BY lme.week_type_material_id
                    ), cte_history_question AS (
                        SELECT
                            c.description cycle,
                            COALESCE(CAST(EXTRACT(YEAR FROM mbq.created_at) AS INTEGER), CAST(EXTRACT(YEAR FROM meq.created_at) AS INTEGER)) as year,
                            (CASE
                                WHEN dwtm.parent_type_material_id is NOT NULL
                                    THEN CONCAT(tm3.description, '(', tm.description, ')')
                                ELSE COALESCE(tm.description, tm2.description)
                            END)::VARCHAR material,
                            (CASE
                                WHEN meq.combined_areas IS NOT NULL
                                    THEN meq.combined_areas
                                ELSE null
                            END)::VARCHAR AS exam_area,
                            COALESCE(mbq.created_at, meq.created_at) created_at,
                            COALESCE(dwtm.week, dwtm2.week)::integer week,
                            COALESCE(mbq.fl_status, meq.fl_status) status,
                            qhc.automatic,
                            COALESCE(
                                (SELECT jsonb_agg(row_to_json(h))
                                FROM (
                                    SELECT cmeq.created_at, cmeq.fl_status, cmeq.question_history_id, cmeq.area_id, cmeq.description AS exam_area, qhc2.automatic
                                    FROM cte_material_exam_question cmeq
                                    JOIN question_history_cycle qhc2 ON cmeq.question_history_id = qhc2.id
                                    WHERE cmeq.week_type_material_id =  meq.week_type_material_id
                                    ORDER BY cmeq.created_at DESC, cmeq.area_id ASC
                                ) AS h
                            ), '[]'::JSONB) AS histories
                        FROM question_history_cycle qhc
                        LEFT JOIN LATERAL jsonb_array_elements(qhc.subquestion) AS subq_elem ON
                        ( (subq_elem->>'question_id')::int = p_question_id OR 'T' != 'T' )
                        JOIN cycle c ON c.id = qhc.cycle_id
                        LEFT JOIN cte_material_ballot_question mbq ON mbq.question_history_id = qhc.id
                        LEFT JOIN group_material_exam_question meq on meq.question_history_id = qhc.id
                        LEFT JOIN detail_week_type_mat dwtm ON dwtm.id = mbq.week_type_material_id
                        LEFT JOIN detail_week_type_mat dwtm2 on dwtm2.id = meq.week_type_material_id
                        LEFT JOIN type_material tm ON tm.id = dwtm.type_material_id
                        LEFT JOIN type_material tm2 ON tm2.id = dwtm2.type_material_id
                        LEFT JOIN type_material tm3 ON tm3.id = dwtm.parent_type_material_id
                        WHERE 
                        CASE 
                            WHEN p_type_question = 'T' THEN qhc.parent_question_id = p_question_id
                            ELSE qhc.question_id = p_question_id OR (subq_elem->>'question_id')::int = p_question_id
                        END
                        AND (mbq.question_history_id IS NOT NULL OR meq.question_history_id IS NOT NULL)
                    ), cte_ballot_and_exam_test_history AS (
                        SELECT * FROM cte_history_question
                        UNION ALL
                        SELECT * FROM exam_text_history 
                    )
                    SELECT chq.*, COUNT(*) OVER() AS total
                    FROM cte_ballot_and_exam_test_history chq
                    ORDER BY chq.created_at DESC
                    LIMIT p_perpage
                    OFFSET offset_val;
                END;
                $$;


ALTER FUNCTION odiseo.fn_get_history_generated_questions(p_perpage integer, p_npage integer, p_question_id bigint, p_type_question character varying, p_shared_status character varying) OWNER TO postgres;

--
-- Name: fn_get_history_questions(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_history_questions(p_question_id integer) RETURNS TABLE(id bigint, status character varying, process character varying, description character varying, created_by text, created_at timestamp without time zone, image character varying)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    qs.id,
                    qs.status,
                    qs.process,
                    qs.description,
                    CASE
                        WHEN qs.created_by = 1 THEN 'SISTEMA'
                        ELSE concat(split_part(e.first_name, ' ', 1), ' ', upper(left(e.first_surname, 1)), '. ', e.second_surname)
                    END AS created_by,
                    qs.created_at,
                    u.image
                FROM
                    odiseo.question_status qs
                LEFT JOIN
                    odiseo.users u
                    ON qs.created_by = u.id
                LEFT JOIN
                    odiseo.employees e
                    ON e.user_id = u.id
                WHERE
                    qs.question_id = p_question_id
                ORDER BY qs.id DESC;
            END;
            $$;


ALTER FUNCTION odiseo.fn_get_history_questions(p_question_id integer) OWNER TO postgres;

--
-- Name: fn_get_history_syllabus(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_history_syllabus(p_syllabus_id bigint, p_company_id bigint) RETURNS TABLE(id bigint, syllabus_id bigint, user_id bigint, role_id bigint, correlative integer, description text, created_at timestamp without time zone, updated_at timestamp without time zone, token character varying, weeks json, user_name character varying, user_email odiseo.email_citext, role_name character varying)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY 
                    SELECT
                        s.id, 
                        s.syllabus_id,
                        s.user_id,
                        s.role_id,
                        s.correlative,
                        s.description, 
                        s.created_at, 
                        s.updated_at, 
                        s.token,
                        s.weeks,
                        u.user as user_name,
                        u.email as user_email,
                        r.name as role_name
                    FROM history_syllabus s
                    LEFT JOIN users u ON s.user_id = u.id
                    LEFT JOIN roles r ON s.role_id = r.id
                    WHERE s.syllabus_id = p_syllabus_id
                    AND s.company_id = p_company_id
                    ORDER BY s.correlative DESC;
                END;                    
            $$;


ALTER FUNCTION odiseo.fn_get_history_syllabus(p_syllabus_id bigint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_get_image_gallery_details(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_image_gallery_details(p_image_gallery_id integer) RETURNS TABLE(id bigint, description character varying, image character varying, path_full_version character varying, topics jsonb)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    ig.id,
                    ig.name AS description,
                    ig.image,
                    ig.path_full_version,
                    jsonb_agg(
                        json_build_object(
                            'id', t.id,
                            'name', t.name,
                            'code', t.code
                        )
                    ) AS topics
                FROM odiseo.image_gallery ig
                INNER JOIN odiseo.image_galery_topic igt
                    ON ig.id = igt.image_gallery_id
                LEFT JOIN odiseo.topic t
                    ON igt.topic_id = t.id
                WHERE ig.id = p_image_gallery_id AND ig.fl_status = true AND ig.deleted_at IS NULL AND igt.fl_status = true
                GROUP BY ig.id, ig.name, ig.image, ig.path_full_version;
            END;
            $$;


ALTER FUNCTION odiseo.fn_get_image_gallery_details(p_image_gallery_id integer) OWNER TO postgres;

--
-- Name: fn_get_level_syllabus_detail(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_level_syllabus_detail(p_level_syllabus_id bigint) RETURNS TABLE(cycle_id bigint, code_cycle character varying, name_cycle character varying, university_id smallint, name_university character varying, headquarter_id smallint, name_headquarter character varying, course_id smallint, code_course character varying, name_course character varying, total_weeks smallint, weeks jsonb)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    WITH base_level AS (
        SELECT
            ls.id AS level_syllabus_id,
            c.id AS cycle_id,
            c.code AS code_cycle,
            c.description AS name_cycle,
            ou.id AS university_id,
            ou.name AS name_university,
            h.id AS headquarter_id,
            h.name AS name_headquarter,
            c2.id AS course_id,
            c2.code AS code_course,
            c2.name AS name_course,
            c.weeks AS total_weeks
        FROM level_syllabus ls
        LEFT JOIN cycle c ON ls.cycle_id = c.id
        LEFT JOIN course c2 ON ls.course_id = c2.id
        LEFT JOIN origin_university ou ON ls.university_id = ou.id
        LEFT JOIN headquarters h ON ls.headquarter_id = h.id
        WHERE ls.id = p_level_syllabus_id AND ls.fl_status = TRUE AND ls.deleted_at IS NULL
    ),
    expected_raw AS (
        SELECT 
            tmdt.week,
            tm.id AS material_type_id,
            SUM(CASE WHEN tmc.is_generic = true THEN tmc.amount_question ELSE COALESCE(tmdc.amount_question, 0) END) AS total_question,
            SUM(CASE WHEN tmc.is_generic_text = true THEN tmc.amount_text ELSE COALESCE(tmdct.amount_text, 0) END) AS total_text
        FROM type_material tm
        JOIN type_material_detail_template tmdt ON tmdt.type_material_id = tm.id
        JOIN type_material_template tmt ON tmt.id = tm.type_material_template_id 
        JOIN type_material_course tmc ON tmc.type_material_id = tm.id
        LEFT JOIN type_material_detail_courses tmdc ON tmdc.type_material_course_id = tmc.id AND tmdc.type_material_detail_template_id = tmdt.id
        LEFT JOIN type_material_detail_course_texts tmdct ON tmdct.type_material_course_id = tmc.id AND tmdct.type_material_detail_template_id = tmdt.id
        CROSS JOIN base_level bl
        WHERE tm.cycle_id = bl.cycle_id
        AND tmc.course_id = bl.course_id
        AND tm.fl_exam = false
        AND tm.fl_status = true
        AND (
                tm.parent_id IS NOT NULL
                OR 
                tm.id NOT IN (SELECT parent_id FROM type_material tm2 WHERE tm2.cycle_id = tm.cycle_id  AND parent_id IS NOT NULL)
            )
        GROUP BY tmdt.week, tm.id
    ),
    expected AS (
        SELECT week, material_type_id, 'P' AS type, total_question AS total
        FROM expected_raw 
        UNION ALL
        SELECT week, material_type_id, 'T' AS type, total_text AS total
        FROM expected_raw 
    ),
    actual_materials AS (
        SELECT 
            level_syllabus_weeks_id, 
            type_material_id, 
            'P' AS type, 
            COALESCE(number_questions, 0) AS total
        FROM detail_level_syllabus_weeks
        WHERE fl_status = true AND deleted_at IS NULL AND COALESCE(number_questions, 0) > 0
        
        UNION ALL
        
        SELECT 
            level_syllabus_weeks_id, 
            type_material_id, 
            'T' AS type, 
            COALESCE(number_of_passages, 0) AS total
        FROM detail_level_syllabus_weeks_parents
        WHERE fl_status = true AND deleted_at IS NULL AND COALESCE(number_of_passages, 0) > 0
    ),
    actual AS (
        SELECT 
            lsw.week, 
            am.type_material_id AS material_type_id, 
            am.type,
            SUM(am.total) AS total
        FROM level_syllabus_weeks lsw 
        CROSS JOIN base_level bl
        JOIN actual_materials am ON am.level_syllabus_weeks_id = lsw.id 
        WHERE 
            lsw.level_syllabus_id = bl.level_syllabus_id 
            AND lsw.fl_status = true 
        GROUP BY 
            lsw.id, lsw.week, am.type_material_id, am.type
    ),
    inconsistent_weeks AS (
        SELECT DISTINCT COALESCE(e.week, a.week) AS error_week 
        FROM expected e
        FULL OUTER JOIN actual a 
            ON e.week = a.week 
        AND e.material_type_id = a.material_type_id
        AND e.type = a.type
        WHERE 
            COALESCE(e.total, 0) != COALESCE(a.total, 0)
    ),
    list_weeks AS (
        SELECT 
            bl.level_syllabus_id,
            cw.week AS week_number 
        FROM base_level bl
        JOIN cycle_weeks cw ON cw.cycle_id = bl.cycle_id
        JOIN type_week tw ON cw.type_week_id = tw.id
        WHERE cw.fl_status = true 
          AND cw.deleted_at IS NULL
          AND tw.description != 'Inactiva'
          AND tw.fl_status = true
          AND tw.deleted_at IS NULL
    ),
    weeks_json_build AS (
        SELECT 
            lw.level_syllabus_id,
            jsonb_agg(
                jsonb_build_object(
                    'week', lw.week_number,
                    'name_week', 'Semana ' || lw.week_number,
                    'exist_level_syllabus', CASE WHEN iw.error_week IS NOT NULL THEN false ELSE true END
                ) ORDER BY lw.week_number
            ) AS weeks_array
        FROM list_weeks lw
        LEFT JOIN inconsistent_weeks iw ON lw.week_number = iw.error_week
        GROUP BY lw.level_syllabus_id
    )
    SELECT 
        bl.cycle_id,
        bl.code_cycle,
        bl.name_cycle,
        bl.university_id,
        bl.name_university,
        bl.headquarter_id,
        bl.name_headquarter,
        bl.course_id,
        bl.code_course,
        bl.name_course,
        bl.total_weeks,
        wjb.weeks_array AS weeks
    FROM base_level bl
    LEFT JOIN weeks_json_build wjb ON bl.level_syllabus_id = wjb.level_syllabus_id;
END;
$$;


ALTER FUNCTION odiseo.fn_get_level_syllabus_detail(p_level_syllabus_id bigint) OWNER TO postgres;

--
-- Name: fn_get_list_cycles(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_list_cycles(p_company_id bigint) RETURNS TABLE(id bigint, code character varying, description character varying, weeks smallint, start_date date, end_date date, active boolean, week_types_descriptions jsonb, created_at timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY

                    WITH cycles AS (
                        SELECT
                            c.id,
                            c.code,
                            c.description,
                            c.weeks,
                            c.start_date,
                            c.end_date,
                            c.active,
                            COALESCE((
                                SELECT JSON_AGG(JSON_BUILD_OBJECT(
                                    'week', wk.week,
                                    'type_week_name',CASE
                                        WHEN wk.type_week_id = 1 THEN w.description
                                        ELSE tw.description
                                    END,
                                    'type_week_id' , tw.id,
                                    'type_week', tw.description
                                ) ORDER BY wk.week ASC)
                                FROM cycle_weeks wk
                                LEFT JOIN type_week tw ON wk.type_week_id = tw.id
                                LEFT JOIN week w ON w.id = wk.week
                                WHERE wk.cycle_id = c.id AND tw.id != 5
                                AND wk.fl_status = true
                            ), '[]')::JSONB AS week_types_descriptions,
                            c.created_at
                        FROM "cycle" c
                        WHERE c.active = true
                        AND c.deleted_at IS NULL
                        AND c.weeks IS NOT NULL
                        AND c.company_id = p_company_id
                        ORDER BY c.created_at DESC
                    ) SELECT * FROM cycles;
                END;
            $$;


ALTER FUNCTION odiseo.fn_get_list_cycles(p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_get_lock_status_on_material(integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_lock_status_on_material(p_material_id integer, p_type_material_id integer, p_week integer) RETURNS TABLE(is_locked boolean, locked_at timestamp without time zone, locked_by_id bigint, locked_by_name text)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY
                     SELECT
                        dwtm.locked AS is_locked,
                        dwtm.locked_at AS locked_at,
                        dwtm.locked_by AS locked_by,
                        CASE
                            WHEN locked_by IS NULL THEN 'Sin acciones registradas'
                            WHEN locked_by IN (1, 2) THEN 'Administrador'
                            ELSE CONCAT( e.first_surname, ' ', e.second_surname, ' ', e.first_name )
                        END AS locked_by_name
                    FROM odiseo.detail_week_type_mat dwtm
                    LEFT JOIN odiseo.employees e ON dwtm.locked_by = e.user_id
                    WHERE 1 = 1
                      AND dwtm.material_id = p_material_id
                      AND dwtm.type_material_id = p_type_material_id
                      AND dwtm.week = p_week;
                END;
            $$;


ALTER FUNCTION odiseo.fn_get_lock_status_on_material(p_material_id integer, p_type_material_id integer, p_week integer) OWNER TO postgres;

--
-- Name: fn_get_matching_type_material_weeks(integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_matching_type_material_weeks(p_course_id integer, p_week integer, p_cycle_id integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
                    DECLARE
                        v_matching_weeks JSONB;
                    BEGIN
                        WITH weekly_material_loads AS (
                        SELECT 
                            tmdt.week,
                            tmt.name AS material_name,
                            SUM(
                                CASE 
                                    WHEN tmc.is_generic = true THEN tmc.amount_question
                                    ELSE COALESCE(tmdc.amount_question, 0)
                                END
                            ) AS total_question,
                            SUM( 
                                CASE 
                                    WHEN tmc.is_generic_text = true THEN tmc.amount_text
                                    ELSE COALESCE(tmdct.amount_text, 0)
                                END
                            ) AS total_text
                        FROM type_material tm
                        JOIN type_material_detail_template tmdt ON tmdt.type_material_id = tm.id
                        JOIN type_material_template tmt ON tmt.id = tm.type_material_template_id 
                        JOIN type_material_course tmc ON tmc.type_material_id = tm.id
                        LEFT JOIN type_material_detail_courses tmdc ON tmdc.type_material_course_id = tmc.id 
                            AND tmdc.type_material_detail_template_id = tmdt.id
                        LEFT JOIN type_material_detail_course_texts tmdct ON tmdct.type_material_course_id = tmc.id 
                            AND tmdct.type_material_detail_template_id = tmdt.id
                        WHERE tm.cycle_id = p_cycle_id
                        AND tmc.course_id = p_course_id
                        AND tm.fl_exam = false
                        and tmdt.deleted_at IS NULL
                        GROUP BY tmdt.week, tmt.name
                    ),
                    week_signatures AS (
                        SELECT 
                            week,
                            jsonb_agg(
                                jsonb_build_object(
                                    'name', material_name,
                                    'q', total_question,
                                    't', total_text
                                ) ORDER BY material_name
                            ) AS signature
                        FROM weekly_material_loads
                        GROUP BY week
                    ),
                    target_signature AS (
                        SELECT signature 
                        FROM week_signatures 
                        WHERE week = p_week
                    )
                    SELECT COALESCE(jsonb_agg(ws.week ORDER BY ws.week), '[]'::jsonb)
                    INTO v_matching_weeks
                    FROM week_signatures ws
                    JOIN target_signature ts ON ws.signature = ts.signature
                    WHERE ws.week != p_week;

                    RETURN v_matching_weeks;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_get_matching_type_material_weeks(p_course_id integer, p_week integer, p_cycle_id integer) OWNER TO postgres;

--
-- Name: fn_get_material_configuration_inconsistencies(bigint, bigint, bigint, bigint, smallint, smallint, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_material_configuration_inconsistencies(p_headquarter_id bigint, p_cycle_id bigint, p_university_id bigint, p_company_id bigint, p_week smallint DEFAULT NULL::smallint, p_type_material_id smallint DEFAULT NULL::smallint, p_courses jsonb DEFAULT NULL::jsonb) RETURNS TABLE(level_id bigint, syllabus_id bigint, headquarter_id smallint, headquarter character varying, course_id smallint, course_name character varying, cycle_id bigint, cycle_description character varying, university_id smallint, company_id bigint, week_number smallint, type_material_id smallint, type_material_name character varying, record_type text, expected_amount integer, levels_actual_amount integer, syllabus_actual_amount integer, has_levels_mismatch boolean, has_syllabus_mismatch boolean, has_inconsistencies boolean, has_configuration boolean, has_levels_configuration boolean, has_syllabus_configuration boolean)
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                        RETURN QUERY
                        WITH request_info AS (
                            SELECT
                                c.id AS cycle_id,
                                c.description AS cycle_description,
                                c.weeks AS total_weeks,
                                (SELECT h.name FROM headquarters h WHERE h.id = p_headquarter_id) AS headquarter
                            FROM cycle c
                            WHERE c.id = p_cycle_id
                        ),
                        expected_raw AS (
                            SELECT
                                tmc.course_id,
                                c2.name AS course_name,
                                tmdt.week,
                                tm.id AS material_type_id,
                                tmt."name" AS type_material_name,
                                SUM(CASE WHEN tmc.is_generic = true THEN tmc.amount_question ELSE COALESCE(tmdc.amount_question, 0) END) AS total_question,
                                SUM(CASE WHEN tmc.is_generic_text = true THEN tmc.amount_text ELSE COALESCE(tmdct.amount_text, 0) END) AS total_text
                            FROM type_material tm
                            JOIN type_material_detail_template tmdt ON tmdt.type_material_id = tm.id AND tmdt.fl_status = true
                            JOIN type_material_template tmt ON tmt.id = tm.type_material_template_id
                            JOIN type_material_course tmc ON tmc.type_material_id = tm.id
                            LEFT JOIN type_material_detail_courses tmdc ON tmdc.type_material_course_id = tmc.id AND tmdc.type_material_detail_template_id = tmdt.id
                            LEFT JOIN type_material_detail_course_texts tmdct ON tmdct.type_material_course_id = tmc.id AND tmdct.type_material_detail_template_id = tmdt.id
                            JOIN course c2 ON c2.id = tmc.course_id
                            JOIN request_info r ON r.cycle_id = tm.cycle_id
                            WHERE tm.fl_exam = false AND tm.fl_status = true
                            AND (p_week IS NULL OR tmdt.week = p_week)
                            AND (
                                tm.parent_id IS NOT NULL
                                OR
                                tm.id NOT IN (
                                        SELECT sub_tm.parent_id
                                        FROM type_material sub_tm
                                        WHERE sub_tm.cycle_id = tm.cycle_id
                                        AND sub_tm.parent_id IS NOT NULL
                                    )
                            )
                            GROUP BY tmc.course_id, c2.name, tmdt.week, tm.id, tmt.name
                        ),
                        syllabus_ids AS (
                            SELECT DISTINCT
                                s.id AS syllabus_id,
                                s.cycle_id,
                                s.course_id,
                                s.university_id,
                                s.company_id
                            FROM syllabus s
                            WHERE fl_status = true AND deleted_at IS NULL
                            AND s.cycle_id = p_cycle_id AND s.university_id = p_university_id AND s.company_id = p_company_id
                        ),
                        expected AS (
                            SELECT
                                expected_raw.course_id,
                                expected_raw.course_name,
                                expected_raw.week,
                                expected_raw.material_type_id,
                                expected_raw.type_material_name,
                                'P'::text AS type,
                                expected_raw.total_question AS expected_amount
                            FROM expected_raw WHERE expected_raw.total_question > 0
                            UNION ALL
                            SELECT
                                expected_raw.course_id,
                                expected_raw.course_name,
                                expected_raw.week,
                                expected_raw.material_type_id,
                                expected_raw.type_material_name,
                                'T'::text AS type,
                                expected_raw.total_text AS expected_amount
                            FROM expected_raw WHERE expected_raw.total_text > 0
                        ),
                        active_levels AS (
                            SELECT
                                ls.id AS level_syllabus_id,
                                ls.course_id
                            FROM level_syllabus ls
                            WHERE 1 = 1
                            AND ls.cycle_id = p_cycle_id
                            AND ls.headquarter_id = p_headquarter_id
                            AND ls.university_id = p_university_id
                            AND ls.company_id = p_company_id
                            AND ls.fl_status = true
                            AND ls.deleted_at IS NULL
                        ),
                        actual_materials AS (
                            SELECT
                                detail_level_syllabus_weeks.level_syllabus_weeks_id,
                                detail_level_syllabus_weeks.type_material_id,
                                'P'::text AS type,
                                COALESCE(detail_level_syllabus_weeks.number_questions, 0) AS actual_amount
                            FROM detail_level_syllabus_weeks
                            WHERE 1 = 1
                            AND detail_level_syllabus_weeks.fl_status = true
                            AND detail_level_syllabus_weeks.deleted_at IS NULL
                            AND COALESCE(detail_level_syllabus_weeks.number_questions, 0) > 0

                            UNION ALL

                            SELECT
                                detail_level_syllabus_weeks_parents.level_syllabus_weeks_id,
                                detail_level_syllabus_weeks_parents.type_material_id,
                                'T'::text AS type,
                                COALESCE(detail_level_syllabus_weeks_parents.number_of_passages, 0) AS actual_amount
                            FROM detail_level_syllabus_weeks_parents
                            WHERE 1 = 1
                            AND detail_level_syllabus_weeks_parents.fl_status = true
                            AND detail_level_syllabus_weeks_parents.deleted_at IS NULL
                            AND COALESCE(detail_level_syllabus_weeks_parents.number_of_passages, 0) > 0
                        ),
                        actual_levels_agg AS (
                            SELECT
                                al.course_id,
                                lsw.week,
                                am.type_material_id,
                                am.type, SUM(am.actual_amount) AS actual_amount
                            FROM active_levels al
                            JOIN level_syllabus_weeks lsw ON lsw.level_syllabus_id = al.level_syllabus_id
                            JOIN actual_materials am ON am.level_syllabus_weeks_id = lsw.id
                            WHERE lsw.fl_status = true
                            AND (p_week IS NULL OR lsw.week = p_week)
                            GROUP BY al.course_id, lsw.week, am.type_material_id, am.type
                        ),
                        actual_syllabus_materials AS (
                            SELECT
                                s.course_id,
                                stw.week,
                                sstm.type_material_id,
                                'P'::text AS type,
                                SUM(sstm.questions_amount) AS total
                            FROM syllabus s
                            JOIN syllabus_topic st ON st.syllabus_id = s.id
                            JOIN syllabus_topic_week stw ON stw.syllabus_topic_id = st.id AND stw.fl_status = true
                            JOIN syllabus_detail_subtopic sds ON sds.syllabus_topic_week_id = stw.id AND sds.fl_status = true
                            JOIN syllabus_subtopic_type_material sstm ON sstm.syllabus_detail_subtopic_id = sds.id
                            WHERE 1 = 1
                            AND s.cycle_id = p_cycle_id
                            AND s.university_id = p_university_id
                            AND s.company_id = p_company_id
                            AND s.fl_status = true
                            AND s.deleted_at IS NULL
                            AND sstm.fl_status = true
                            AND sstm.deleted_at IS NULL
                            AND (p_week IS NULL OR stw.week = p_week)
                            GROUP BY s.course_id, stw.week, sstm.type_material_id

                            UNION ALL

                            SELECT
                                s.course_id,
                                stw.week,
                                std.type_material_id,
                                'T'::text AS type,
                                COUNT(stx.id) AS total
                            FROM syllabus s
                            JOIN syllabus_text_weeks stw ON stw.syllabus_id = s.id AND stw.fl_status = true
                            JOIN syllabus_text_distributions std ON std.syllabus_text_week_id = stw.id AND std.fl_status = true
                            JOIN syllabus_texts stx ON stx.syllabus_text_distribution_id = std.id AND stx.fl_status = true
                            WHERE 1 = 1
                            AND s.cycle_id = p_cycle_id
                            AND s.university_id = p_university_id
                            AND s.company_id = p_company_id
                            AND s.fl_status = true
                            AND s.deleted_at IS NULL
                            AND (p_week IS NULL OR stw.week = p_week)
                            GROUP BY s.course_id, stw.week, std.type_material_id
                        ),
                        cycle_active_weeks AS (
                            SELECT DISTINCT
                                cw.week
                            FROM cycle_weeks cw
                            JOIN type_week tw ON tw.id = cw.type_week_id
                            WHERE cw.cycle_id = p_cycle_id
                            AND cw.fl_status = true
                            AND tw.description != 'Inactiva'
                            AND cw.week IS NOT NULL
                            AND (p_week IS NULL OR cw.week = p_week)
                        ),
                        all_course_types AS (
                            SELECT DISTINCT
                                tmc.course_id,
                                c2.name AS course_name,
                                tm.id AS material_type_id,
                                tmt."name" AS type_material_name
                            FROM type_material tm
                            JOIN type_material_template tmt ON tmt.id = tm.type_material_template_id
                            JOIN type_material_course tmc ON tmc.type_material_id = tm.id
                            JOIN course c2 ON c2.id = tmc.course_id
                            WHERE tm.cycle_id = p_cycle_id
                            AND tm.fl_exam = false
                            AND tm.fl_status = true
                            AND (
                                tm.parent_id IS NOT NULL
                                OR tm.id NOT IN (
                                    SELECT sub_tm.parent_id
                                    FROM type_material sub_tm
                                    WHERE sub_tm.cycle_id = tm.cycle_id
                                    AND sub_tm.parent_id IS NOT NULL
                                )
                            )
                            AND (p_type_material_id IS NULL OR tm.id = p_type_material_id)
                            AND (p_courses IS NULL OR tmc.course_id IN (SELECT value::smallint FROM jsonb_array_elements_text(p_courses)))
                        ),
                        all_week_course_combinations AS (
                            SELECT
                                caw.week,
                                act.course_id,
                                act.course_name,
                                act.material_type_id,
                                act.type_material_name
                            FROM cycle_active_weeks caw
                            CROSS JOIN all_course_types act
                        )
                        SELECT
                            al.level_syllabus_id AS level_id,
                            sids.syllabus_id,
                            p_headquarter_id::smallint AS headquarter_id,
                            r.headquarter,
                            COALESCE(e.course_id, awcc.course_id)::smallint AS course_id,
                            COALESCE(e.course_name, awcc.course_name)::varchar AS course_name,
                            p_cycle_id AS cycle_id,
                            r.cycle_description::varchar,
                            p_university_id::smallint AS university_id,
                            p_company_id AS company_id,
                            COALESCE(e.week, awcc.week)::smallint AS week_number,
                            COALESCE(e.material_type_id, awcc.material_type_id) AS type_material_id,
                            COALESCE(e.type_material_name, awcc.type_material_name)::varchar AS type_material_name,
                            COALESCE(e.type, 'P')::text AS record_type,
                            COALESCE(e.expected_amount, 0)::integer AS expected_amount,
                            COALESCE(ala.actual_amount, 0)::integer AS levels_actual_amount,
                            COALESCE(sy.total, 0)::integer AS syllabus_actual_amount,
                            (COALESCE(e.expected_amount, 0) != COALESCE(ala.actual_amount, 0)) AS has_levels_mismatch,
                            (COALESCE(e.expected_amount, 0) != COALESCE(sy.total, 0)) AS has_syllabus_mismatch,
                            (COALESCE(e.expected_amount, 0) != COALESCE(ala.actual_amount, 0) OR COALESCE(e.expected_amount, 0) != COALESCE(sy.total, 0)) AS has_inconsistencies,
                            (e.expected_amount IS NOT NULL) AS has_configuration,
                            (ala.actual_amount IS NOT NULL) AS has_levels_configuration,
                            (sy.total IS NOT NULL) AS has_syllabus_configuration
                        FROM all_week_course_combinations awcc
                        LEFT JOIN expected e
                            ON awcc.course_id = e.course_id AND awcc.week = e.week AND awcc.material_type_id = e.material_type_id
                        LEFT JOIN actual_levels_agg ala
                            ON COALESCE(e.course_id, awcc.course_id) = ala.course_id
                            AND COALESCE(e.week, awcc.week) = ala.week
                            AND COALESCE(e.material_type_id, awcc.material_type_id) = ala.type_material_id
                            AND COALESCE(e.type, 'P') = ala.type
                        LEFT JOIN actual_syllabus_materials sy
                            ON COALESCE(e.course_id, awcc.course_id) = sy.course_id
                            AND COALESCE(e.week, awcc.week) = sy.week
                            AND COALESCE(e.material_type_id, awcc.material_type_id) = sy.type_material_id
                            AND COALESCE(e.type, 'P') = sy.type
                        LEFT JOIN syllabus_ids sids
                            ON sids.course_id = COALESCE(e.course_id, awcc.course_id)
                        LEFT JOIN active_levels al
                            ON al.course_id = COALESCE(e.course_id, awcc.course_id)
                        CROSS JOIN request_info r
                        WHERE 1 = 1
                        AND (p_type_material_id IS NULL OR COALESCE(e.material_type_id, awcc.material_type_id) = p_type_material_id)
                        AND (
                            p_courses IS NULL
                            OR COALESCE(e.course_id, awcc.course_id) IN (SELECT value::smallint FROM jsonb_array_elements_text(p_courses))
                        )
                        AND (COALESCE(e.expected_amount, 0) != COALESCE(ala.actual_amount, 0) OR COALESCE(e.expected_amount, 0) != COALESCE(sy.total, 0))
                        ORDER BY COALESCE(e.week, awcc.week), COALESCE(e.course_id, awcc.course_id);
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_get_material_configuration_inconsistencies(p_headquarter_id bigint, p_cycle_id bigint, p_university_id bigint, p_company_id bigint, p_week smallint, p_type_material_id smallint, p_courses jsonb) OWNER TO postgres;

--
-- Name: fn_get_material_configurations(bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_material_configurations(p_company_id bigint, p_area_id bigint, p_type_material_id bigint, p_type_template_id bigint) RETURNS TABLE(id bigint, category character varying, element character varying, material_detail jsonb)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_type_material_template_id BIGINT;
        BEGIN
            SELECT
                tm.type_material_template_id
            INTO v_type_material_template_id
            FROM type_material tm
            WHERE tm.id = p_type_material_id;

            RETURN QUERY
            SELECT
                mc.id,
                mc.category,
                mc.element,
                jsonb_agg(
                    json_build_object(
                        'id', mcd.id,
                        'material_configuration_id', mcd.material_configuration_id,
                        'name', mcd.name,
                        'value', (
                            SELECT a.value
                            FROM (
                                SELECT 
                                    a.value,
                                    ROW_NUMBER() OVER (
                                        PARTITION BY a.material_configuration_detail_id 
                                        ORDER BY 
                                            CASE 
                                                WHEN a.template_type_material_configuration_id IS NOT NULL THEN 1 
                                                ELSE 2 
                                            END,
                                            a.updated_at DESC
                                    ) AS rn
                                FROM odiseo.material_configuration_detail_value a
                                WHERE 
                                    (
                                        -- Registro válido (no nulo)
                                        a.template_type_material_configuration_id IN (
                                            SELECT ttmc1.id
                                            FROM odiseo.template_type_material_configurations ttmc1
                                            WHERE ttmc1.type_template_id = p_type_template_id
                                            AND ttmc1.type_material_template_id = v_type_material_template_id
                                            AND ttmc1.company_id = p_company_id
                                            AND ttmc1.fl_status = TRUE
                                            AND (p_area_id IS NULL OR ttmc1.exam_area_id = p_area_id)
                                        )
                                        -- Registro nulo, solo si no hay un par válido
                                        OR (
                                            a.template_type_material_configuration_id IS NULL
                                            AND a.material_configuration_detail_id NOT IN (
                                                SELECT material_configuration_detail_id
                                                FROM odiseo.material_configuration_detail_value mcdv3
                                                where mcdv3.template_type_material_configuration_id IN (
                                                    SELECT ttmc.id
                                                    FROM odiseo.template_type_material_configurations ttmc
                                                    WHERE ttmc.type_template_id = p_type_template_id
                                                    AND ttmc.type_material_template_id = v_type_material_template_id
                                                    AND ttmc.company_id = p_company_id
                                                    AND ttmc.fl_status = TRUE
                                                    AND (p_area_id IS NULL OR ttmc.exam_area_id = p_area_id)
                                                )
                                                and mcdv3.fl_status IS TRUE
                                            )
                                        )
                                    )
                                    AND a.material_configuration_detail_id = mcd.id
                                    AND a.fl_status = TRUE
                            ) a
                            WHERE a.rn = 1
                        )
                    )
                ) AS material_detail
            FROM
                material_configurations mc
            INNER JOIN
                material_configuration_details mcd
                ON mcd.material_configuration_id = mc.id
            WHERE
                mc.id <> 7
                AND mc.fl_status = TRUE
                AND mcd.fl_status = TRUE
            GROUP BY mc.id, mc.category, mc.element;
        END;
        $$;


ALTER FUNCTION odiseo.fn_get_material_configurations(p_company_id bigint, p_area_id bigint, p_type_material_id bigint, p_type_template_id bigint) OWNER TO postgres;

--
-- Name: fn_get_material_exam_parent_question(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_material_exam_parent_question(p_material_exam_parent_question_id bigint) RETURNS TABLE(subquestions_amount smallint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    /*
        Creación de función en base de datos
        Función para obtener informacion de una fila de
        la tabla material_exam_parent_question

        ------------------------------------------------------------------------------------
        -- HISTORIAL DE CAMBIOS
        ------------------------------------------------------------------------------------

        Versión: 1.0
        Fecha: 2025-10-15
        Autor: Anderson Vallejo
        Descripción:
            Traer la cantidad de subpreguntas de un texto faltante o existente
    */

        RETURN QUERY
        SELECT
            JSONB_ARRAY_LENGTH(subquestion)::SMALLINT AS subquestion_amount
        FROM material_exam_parent_question
        WHERE id = p_material_exam_parent_question_id;
    END;
$$;


ALTER FUNCTION odiseo.fn_get_material_exam_parent_question(p_material_exam_parent_question_id bigint) OWNER TO postgres;

--
-- Name: fn_get_material_incomplete_questions(bigint, smallint, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_material_incomplete_questions(p_material_id bigint, p_week smallint, p_type_material_ids jsonb) RETURNS TABLE(type_material_id bigint, type_material character varying, message text, issues character varying, missing_course_config character varying, missing_config_message character varying, missing_course_text json)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            SELECT
                dwtm.type_material_id::BIGINT AS type_material_id,
                tm.description AS type_material,
                'Faltan preguntas para el tipo de material '  || tm.description AS message, 
                dwtm.data_incomplete_questions AS issues,
                dwtm.data_missing_course_config  as missing_course_config,
                dwtm.missing_config_message  as missing_config_message,
				dwtm.data_missing_text as missing_course_text
            FROM odiseo.detail_week_type_mat dwtm
            LEFT JOIN odiseo.type_material tm ON dwtm.type_material_id = tm.id
            WHERE 1 = 1
              AND dwtm.material_id = p_material_id
              AND dwtm.week = p_week
              AND dwtm.type_material_id IN ( SELECT JSONB_ARRAY_ELEMENTS_TEXT(p_type_material_ids::JSONB)::INT )
              -- AND (dwtm.fl_complete_questions IS FALSE OR dwtm.missing_config_message IS NULL)
              AND dwtm.fl_status IS TRUE
              AND dwtm.deleted_at IS NULL;
        END;
        $$;


ALTER FUNCTION odiseo.fn_get_material_incomplete_questions(p_material_id bigint, p_week smallint, p_type_material_ids jsonb) OWNER TO postgres;

--
-- Name: fn_get_material_inconsistency_status(smallint, bigint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_material_inconsistency_status(p_headquarter_id smallint, p_cycle_id bigint, p_university_id smallint, p_company_id bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
                    DECLARE
                        v_has_expected boolean;
                        v_has_error boolean;
                    BEGIN
                        SELECT EXISTS (
                            SELECT 1
                            FROM type_material tm
                            JOIN cycle c ON c.id = tm.cycle_id
                            WHERE c.id = p_cycle_id
                            AND tm.fl_exam = false
                            AND tm.fl_status = true
                            AND (
                                tm.parent_id IS NOT NULL
                                OR tm.id NOT IN (
                                    SELECT sub_tm.parent_id 
                                    FROM type_material sub_tm 
                                    WHERE sub_tm.cycle_id = tm.cycle_id 
                                    AND sub_tm.parent_id IS NOT NULL
                                )
                            )
                        ) INTO v_has_expected;

                        IF NOT v_has_expected THEN
                            RETURN 'without-type-material';
                        END IF;

                        SELECT EXISTS (
                            WITH expected_raw AS (
                                SELECT 
                                    tmc.course_id, tmdt.week, tm.id AS material_type_id, 'P'::text AS type,
                                    SUM(CASE WHEN tmc.is_generic = true THEN tmc.amount_question ELSE COALESCE(tmdc.amount_question, 0) END) AS amount
                                FROM type_material tm
                                JOIN cycle c ON c.id = tm.cycle_id AND c.id = p_cycle_id
                                JOIN type_material_detail_template tmdt ON tmdt.type_material_id = tm.id AND tmdt.fl_status = true
                                JOIN type_material_course tmc ON tmc.type_material_id = tm.id
                                LEFT JOIN type_material_detail_courses tmdc ON tmdc.type_material_course_id = tmc.id AND tmdc.type_material_detail_template_id = tmdt.id
                                WHERE tm.fl_exam = false AND tm.fl_status = true
                                AND (tm.parent_id IS NOT NULL OR tm.id NOT IN (SELECT sub_tm.parent_id FROM type_material sub_tm WHERE sub_tm.cycle_id = tm.cycle_id AND sub_tm.parent_id IS NOT NULL))
                                GROUP BY tmc.course_id, tmdt.week, tm.id
                                HAVING SUM(CASE WHEN tmc.is_generic = true THEN tmc.amount_question ELSE COALESCE(tmdc.amount_question, 0) END) > 0
                                
                                UNION ALL
                                
                                SELECT 
                                    tmc.course_id, tmdt.week, tm.id AS material_type_id, 'T'::text AS type,
                                    SUM(CASE WHEN tmc.is_generic_text = true THEN tmc.amount_text ELSE COALESCE(tmdct.amount_text, 0) END) AS amount
                                FROM type_material tm
                                JOIN cycle c ON c.id = tm.cycle_id AND c.id = p_cycle_id
                                JOIN type_material_detail_template tmdt ON tmdt.type_material_id = tm.id AND tmdt.fl_status = true
                                JOIN type_material_course tmc ON tmc.type_material_id = tm.id
                                LEFT JOIN type_material_detail_course_texts tmdct ON tmdct.type_material_course_id = tmc.id AND tmdct.type_material_detail_template_id = tmdt.id
                                WHERE tm.fl_exam = false AND tm.fl_status = true
                                AND (tm.parent_id IS NOT NULL OR tm.id NOT IN (SELECT sub_tm.parent_id FROM type_material sub_tm WHERE sub_tm.cycle_id = tm.cycle_id AND sub_tm.parent_id IS NOT NULL))
                                GROUP BY tmc.course_id, tmdt.week, tm.id
                                HAVING SUM(CASE WHEN tmc.is_generic_text = true THEN tmc.amount_text ELSE COALESCE(tmdct.amount_text, 0) END) > 0
                            ),
                            actual_levels AS (
                                SELECT ls.course_id, lsw.week, dlsw.type_material_id, 'P'::text AS type, SUM(COALESCE(dlsw.number_questions, 0)) AS actual_amount
                                FROM level_syllabus ls
                                JOIN level_syllabus_weeks lsw ON lsw.level_syllabus_id = ls.id AND lsw.fl_status = true
                                JOIN detail_level_syllabus_weeks dlsw ON dlsw.level_syllabus_weeks_id = lsw.id AND dlsw.fl_status = true AND dlsw.deleted_at IS NULL
                                WHERE ls.fl_status = true AND ls.deleted_at IS NULL
                                AND ls.headquarter_id = p_headquarter_id AND ls.cycle_id = p_cycle_id AND ls.university_id = p_university_id AND ls.company_id = p_company_id
                                AND COALESCE(dlsw.number_questions, 0) > 0
                                GROUP BY ls.course_id, lsw.week, dlsw.type_material_id
                                
                                UNION ALL
                                
                                SELECT ls.course_id, lsw.week, dlswp.type_material_id, 'T'::text AS type, SUM(COALESCE(dlswp.number_of_passages, 0)) AS actual_amount
                                FROM level_syllabus ls
                                JOIN level_syllabus_weeks lsw ON lsw.level_syllabus_id = ls.id AND lsw.fl_status = true
                                JOIN detail_level_syllabus_weeks_parents dlswp ON dlswp.level_syllabus_weeks_id = lsw.id AND dlswp.fl_status = true AND dlswp.deleted_at IS NULL
                                WHERE ls.fl_status = true AND ls.deleted_at IS NULL
                                AND ls.headquarter_id = p_headquarter_id AND ls.cycle_id = p_cycle_id AND ls.university_id = p_university_id AND ls.company_id = p_company_id
                                AND COALESCE(dlswp.number_of_passages, 0) > 0
                                GROUP BY ls.course_id, lsw.week, dlswp.type_material_id
                            ),
                            actual_syllabus AS (
                                SELECT s.course_id, stw.week, sstm.type_material_id, 'P'::text AS type, SUM(sstm.questions_amount) AS actual_amount
                                FROM syllabus s
                                JOIN syllabus_topic st ON st.syllabus_id = s.id 
                                JOIN syllabus_topic_week stw ON stw.syllabus_topic_id = st.id AND stw.fl_status = true
                                JOIN syllabus_detail_subtopic sds ON sds.syllabus_topic_week_id = stw.id AND sds.fl_status = true
                                JOIN syllabus_subtopic_type_material sstm ON sstm.syllabus_detail_subtopic_id = sds.id
                                WHERE s.fl_status = true AND s.deleted_at IS NULL AND sstm.fl_status = true AND sstm.deleted_at IS NULL 
                                AND s.cycle_id = p_cycle_id AND s.university_id = p_university_id AND s.company_id = p_company_id
                                GROUP BY s.course_id, stw.week, sstm.type_material_id
                                
                                UNION ALL
                                
                                SELECT s.course_id, stw.week, std.type_material_id, 'T'::text AS type, COUNT(stx.id) AS actual_amount
                                FROM syllabus s 
                                JOIN syllabus_text_weeks stw ON stw.syllabus_id = s.id AND stw.fl_status = true
                                JOIN syllabus_text_distributions std ON std.syllabus_text_week_id = stw.id AND std.fl_status = true
                                JOIN syllabus_texts stx ON stx.syllabus_text_distribution_id = std.id AND stx.fl_status = true
                                WHERE s.fl_status = true AND s.deleted_at IS NULL
                                AND s.cycle_id = p_cycle_id AND s.university_id = p_university_id AND s.company_id = p_company_id
                                GROUP BY s.course_id, stw.week, std.type_material_id
                            )
                            -- LA COMPARACIÓN FINAL
                            SELECT 1
                            FROM expected_raw e
                            LEFT JOIN actual_levels al ON e.course_id = al.course_id AND e.week = al.week AND e.material_type_id = al.type_material_id AND e.type = al.type
                            LEFT JOIN actual_syllabus sy ON e.course_id = sy.course_id AND e.week = sy.week AND e.material_type_id = sy.type_material_id AND e.type = sy.type
                            WHERE e.amount != COALESCE(al.actual_amount, 0)
                            OR e.amount != COALESCE(sy.actual_amount, 0)
                        ) INTO v_has_error;

                        IF v_has_error THEN
                            RETURN 'with-observations';
                        ELSE
                            RETURN 'without-observations';
                        END IF;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_get_material_inconsistency_status(p_headquarter_id smallint, p_cycle_id bigint, p_university_id smallint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_get_material_missing_question(integer, integer, bigint[], text[]); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_material_missing_question(p_perpage integer, p_npage integer, p_course_ids bigint[], p_status text[]) RETURNS TABLE(id bigint, material_id bigint, week smallint, request_date timestamp without time zone, expiration_date timestamp without time zone, total_questions bigint, completed_questions bigint, course_id smallint, course character varying, status character varying, type_material character varying, cycle character varying, company character varying, total bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    offset_val integer;
BEGIN
    offset_val := p_perpage *(p_npage - 1);
    RETURN QUERY WITH summary_missing_question_detail AS (
        SELECT
            mmqd.material_missing_question_id,
            COUNT(mmqd.*) total_questions,
            COUNT(
                CASE WHEN mmqd.status = 'completed' THEN
                    1
                END) AS completed_questions
        FROM
            material_missing_question_detail mmqd
        WHERE mmqd.deleted_at IS NULL
        GROUP BY
            mmqd.material_missing_question_id
),
filtered_data AS (
    SELECT
        mmq.id,
        mmq.material_id,
        mmq.week,
        mmq.request_date,
        mmq.expiration_date,
        COALESCE(sqd.total_questions, 0) AS total_questions,
        COALESCE(sqd.completed_questions, 0) AS completed_questions,
        mmq.course_id,
        c."name" course,
        mmq.status,
        tm.description type_material,
        cy.description cycle,
        co.commercial_name company
    FROM
        material_missing_question mmq
        JOIN material m ON m.id = mmq.material_id
        JOIN companies co ON co.id = m.company_id
        JOIN cycle cy ON cy.id = m.cycle_id
        JOIN type_material tm ON tm.id = mmq.type_material_id
        JOIN course c ON c.id = mmq.course_id
        LEFT JOIN summary_missing_question_detail sqd ON sqd.material_missing_question_id = mmq.id
    WHERE (p_course_ids IS NULL
        OR mmq.course_id = ANY (p_course_ids))
    AND (p_status IS NULL
        OR mmq.status = ANY(p_status))
    AND sqd.total_questions > 0
    AND mmq.deleted_at IS NULL
    ORDER BY
        date_trunc('minute', mmq.request_date) DESC, mmq.course_id DESC, mmq.material_id DESC, mmq.type_material_id DESC, mmq.week DESC, mmq.id DESC
),
data_with_total AS (
    SELECT
        fd.id,
        fd.material_id,
        fd.week,
        fd.request_date,
        fd.expiration_date,
        fd.total_questions,
        fd.completed_questions,
        fd.course_id,
        fd.course,
        fd.status,
        fd.type_material,
        fd.cycle,
        fd.company,
        COUNT(*) OVER () AS total
    FROM
        filtered_data fd
)
SELECT
    *
FROM
    data_with_total
LIMIT p_perpage OFFSET offset_val;
END;
$$;


ALTER FUNCTION odiseo.fn_get_material_missing_question(p_perpage integer, p_npage integer, p_course_ids bigint[], p_status text[]) OWNER TO postgres;

--
-- Name: fn_get_material_per_period_ballot(bigint, smallint, smallint, smallint, bigint, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_material_per_period_ballot(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint, p_employee_id bigint, p_has_permission_generar_por_curso_asignado boolean DEFAULT false) RETURNS TABLE(id bigint, material_id bigint, type_material_id smallint, fl_created boolean, material_period_id bigint, start_week smallint, end_week smallint, fl_config_type boolean, lower_level_limit smallint, upper_level_limit smallint, fl_missing_questions boolean, questions_missing_url character varying, fl_missing_courses boolean, courses_missing_url character varying, fl_missing_text boolean, text_missing_url character varying, url jsonb, lock_status boolean, locked_by_id bigint, locked_at timestamp without time zone, locked_by_name text, date_completed timestamp without time zone, employee_completed character varying, order_date timestamp without time zone, order_by_user_id bigint, order_by_name character varying, has_config_column boolean)
    LANGUAGE plpgsql
    AS $$
            DECLARE
                C_ROOT_ADMIN INTEGER DEFAULT 1;
                C_SUPER_ADMIN INTEGER DEFAULT 2;
            BEGIN
                RETURN QUERY
                WITH tbl_type_url (id, name) AS (
                    VALUES
                        (1, 'solution'::VARCHAR),
                        (2, 'without_solution'::VARCHAR),
                        (3, 'review_solution'::VARCHAR),
                        (4, 'review_without_solution'::VARCHAR),
                        (5, 'material_class'::VARCHAR)
                ), tbl_type_material AS (
                    SELECT
                        tm.id,
                        tm.fl_class_material
                    FROM type_material tm
                    WHERE tm.id = p_type_material_id
                ), type_material_ids AS (
                    SELECT UNNEST(
                        CASE
                            WHEN EXISTS (SELECT 1 FROM type_material tm WHERE tm.parent_id = p_type_material_id)
                            THEN ARRAY(SELECT tm.id FROM type_material tm WHERE tm.parent_id = p_type_material_id)
                            ELSE ARRAY[p_type_material_id]
                        END
                    ) AS id
                ), locked_status AS (
                    SELECT 
                        BOOL_AND(dwtm.locked) AS locked,
                        MIN(dwtm.locked_at) AS locked_at,
                        MIN(dwtm.locked_by) AS locked_by,
                        dwtm.material_id
                    FROM odiseo.detail_week_type_mat dwtm 
                    LEFT JOIN odiseo.employees e ON e.user_id = dwtm.locked_by
                    WHERE 1 = 1
                      AND dwtm.type_material_id IN (SELECT * FROM type_material_ids)
                      AND dwtm.week BETWEEN p_start_week AND p_end_week
                      AND dwtm.material_id = p_material_id
                      AND dwtm.fl_status = TRUE
                    GROUP BY dwtm.material_id
                ), locked_status_by AS (
                    SELECT
                        ls.*,
                        CASE
                            WHEN locked_by IS NULL THEN 'Sin acciones registradas'
                            WHEN locked_by IN (C_ROOT_ADMIN, C_SUPER_ADMIN) THEN 'Administrador'
                            ELSE CONCAT( e.first_surname, ' ', e.second_surname, ' ', e.first_name )
                        END AS locked_by_name
                    FROM locked_status ls
                    LEFT JOIN odiseo.employees e ON e.user_id = ls.locked_by
                ), refresh_fl_job_process_per_course_week AS (
                    SELECT 
                        mppc.type,
                        BOOL_OR(mppc.job_status = 'completed') AS has_completed
                    FROM material_per_period mpp
                    JOIN material_per_period_ballot mppb 
                        ON mppb.material_per_period_id = mpp.id
                    JOIN material_per_period_course mppc 
                        ON mppc.material_per_period_ballot_id = mppb.id
                    JOIN employee_course ec ON mppc.course_id = ec.course_id AND ec.teacher_id = p_employee_id
                    WHERE mpp.material_id = p_material_id
                    AND mpp.type_material_id = p_type_material_id
                    AND mppb.start_week = p_start_week
                    AND mppb.end_week = p_end_week
                    AND mpp.deleted_at IS NULL
                    AND mppb.deleted_at IS NULL
                    AND mppc.deleted_at IS NULL
                    GROUP BY mppc.type
                ), tbl_material_per_period AS (
                    SELECT
                        mpp.id,
                        m.id,
                        COALESCE(mpp.type_material_id, p_type_material_id) AS p_type_material_id,
                        CASE
                            WHEN mppb.start_week IS NOT NULL THEN TRUE
                            ELSE FALSE
                        END AS fl_created,
                        mppb.id AS material_period_id,
                        COALESCE(mppb.start_week, p_start_week) AS p_start_week,
                        COALESCE(mppb.end_week, p_end_week) AS end_week,
                        COALESCE(mppllc.fl_use_question_type, mppb.fl_config_type, true) AS fl_config_type,
                        COALESCE(mppllc.lower_level_limit, mppb.lower_level_limit, 1::SMALLINT) AS lower_level_limit,
                        COALESCE(mppllc.upper_level_limit, mppb.upper_level_limit, 1::SMALLINT) AS upper_level_limit,
                        mppb.fl_missing_questions,
                        mppb.questions_missing_url,
                        mppb.fl_missing_courses,
                        mppb.courses_missing_url,
                        mppb.fl_missing_text,
                        mppb.text_missing_url,
                        COALESCE((
                            SELECT jsonb_agg(
                                jsonb_build_object(
                                    'id', mppbu.id,
                                    'material_per_period_ballot_id', COALESCE(mppbu.material_per_period_ballot_id, mppb.id),
                                    'type_url', COALESCE(mppbu.type_url, ttu.name),
                                    'fl_job_process', COALESCE(mppbu.fl_job_process, 'unprocessed'::VARCHAR),
                                    'job_url', mppbu.job_url,
                                    'job_id', mppbu.job_id,
                                    'file_name', mppbu.file_name
                                )
                                ||
                                CASE 
                                    WHEN p_has_permission_generar_por_curso_asignado THEN
                                        jsonb_build_object(
                                            'fl_job_process_completed_by_employee_course',
                                            COALESCE(rf.has_completed, false)
                                        )
                                    ELSE '{}'::jsonb
                                END
                                ORDER BY ttu.id ASC
                            )
                            FROM tbl_type_url ttu
                            LEFT JOIN tbl_type_material ttm ON 1 = 1
                            LEFT JOIN material_per_period_ballot_url mppbu 
                                ON ttu.name = mppbu.type_url
                                AND mppbu.deleted_by IS NULL
                                AND mppbu.material_per_period_ballot_id = mppb.id

                            LEFT JOIN refresh_fl_job_process_per_course_week rf
                                ON rf.type = COALESCE(mppbu.type_url, ttu.name)

                            WHERE (
                                ttm.fl_class_material = TRUE
                                OR (ttm.fl_class_material = FALSE AND ttu.name <> 'material_class')
                            )
                        ), '[]'::JSONB) AS url,
                        lsb.locked lock_status,
                        lsb.locked_by AS locked_by_id,
                        lsb.locked_at,
                        lsb.locked_by_name,
                        mppb.date_completed,
                        CASE
                            WHEN u.id IS NULL THEN NULL::VARCHAR
                            WHEN e.user_id IS NULL THEN 'Administrador'::VARCHAR
                            ELSE CONCAT(e.first_name, ' ', e.first_surname, ' ', e.second_surname)::VARCHAR
                        END AS employee_completed,
                        mppb.order_date,
                        mppb.order_by_user_id,
                        CASE
                            WHEN uorder.id IS NULL THEN NULL::VARCHAR
                            WHEN eorder.user_id IS NULL THEN 'Administrador'::VARCHAR
                            ELSE CONCAT(eorder.first_name, ' ', eorder.first_surname, ' ', eorder.second_surname)::VARCHAR
                        END AS order_name,
                        tmt.has_config_column
                    FROM material m
                    join type_material tm ON tm.id = p_type_material_id and tm.deleted_by IS NULL
                    join type_material_template tmt ON tmt.id = tm.type_material_template_id and tmt.deleted_by IS NULL
                    LEFT JOIN material_per_period mpp ON m.id = mpp.material_id
                        AND mpp.deleted_by IS NULL
                        AND mpp.type_material_id = p_type_material_id
                    LEFT JOIN material_per_period_ballot mppb ON mpp.id = mppb.material_per_period_id
                        AND mppb.deleted_by IS NULL
                        AND mppb.start_week = p_start_week
                        AND mppb.end_week = p_end_week
                    LEFT JOIN material_per_period_level_limit_config mppllc ON mpp.id = mppllc.material_per_period_id
                        AND mppllc.deleted_by IS NULL
                        AND mppllc.start_week = p_start_week
                        AND mppllc.end_week = p_end_week
                    LEFT JOIN users uorder ON mppb.order_by_user_id = uorder.id
                    LEFT JOIN employees eorder ON uorder.id = eorder.user_id
                    LEFT JOIN locked_status_by lsb ON lsb.material_id = m.id
                    LEFT JOIN users u ON mppb.user_completed_id = u.id
                    LEFT JOIN employees e ON u.id = e.user_id
                    WHERE m.id = p_material_id
                )
                SELECT * FROM tbl_material_per_period tmpp;
            END;
            $$;


ALTER FUNCTION odiseo.fn_get_material_per_period_ballot(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint, p_employee_id bigint, p_has_permission_generar_por_curso_asignado boolean) OWNER TO postgres;

--
-- Name: fn_get_material_per_period_ballot_complete(bigint, smallint, smallint, smallint, boolean, smallint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_material_per_period_ballot_complete(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint, p_fl_config_type boolean, p_lower_level_limit smallint, p_upper_level_limit smallint, p_created_by bigint) RETURNS TABLE(id bigint, material_per_period_ballot_id bigint, week smallint, cycle_id bigint, start_date date, type_material_id smallint, type_material character varying, exists_per_period boolean, has_questions boolean, parent_type_material_id smallint, fl_exam boolean, courses jsonb, courses_for_text jsonb, courses_missing jsonb, courses_for_text_missing jsonb, university_id smallint, headquarte_id smallint)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    /*
                        ------------------------------------------------------------------------------------
                        -- HISTORIAL DE CAMBIOS
                        ------------------------------------------------------------------------------------
                        Versión: 1.0
                        Fecha: 2025-10-28
                        Autor: Junior Alcarraz
                        Descripción:
                            Se trae configuracion del tipo material seleccionado por periodo
                    */

                    RETURN QUERY
                    WITH type_material_ids AS (
                        SELECT
                            CASE
                                WHEN EXISTS ( SELECT 1 FROM type_material tmx WHERE tmx.parent_id = p_type_material_id )
                                THEN ARRAY( SELECT tmy.id FROM type_material tmy WHERE tmy.parent_id = p_type_material_id )
                                ELSE ARRAY[p_type_material_id]
                            END AS ids
                    ), insert_material_per_period AS (
                        INSERT INTO material_per_period AS plmm ( material_id, type_material_id, created_at, created_by )
                        VALUES( p_material_id, p_type_material_id, NOW(), p_created_by )
                        ON CONFLICT ON CONSTRAINT per_material_and_type_id
                        DO UPDATE
                            SET
                                updated_by = p_created_by,
                                deleted_by = NULL,
                                updated_at = NOW(),
                                deleted_at = NULL
                        RETURNING plmm.id, plmm.updated_at IS NULL AS is_new
                    ), insert_material_per_period_ballot AS (
                        INSERT INTO material_per_period_ballot AS mpt(
                            material_per_period_id,
                            start_week,
                            end_week,
                            fl_config_type,
                            lower_level_limit,
                            upper_level_limit,
                            date_completed,
                            user_completed_id,
                            created_by,
                            created_at
                        )
                        VALUES(
                            ( SELECT im.id FROM insert_material_per_period AS im ),
                            p_start_week,
                            p_end_week,
                            p_fl_config_type,
                            p_lower_level_limit,
                            p_upper_level_limit,
                            NOW(),
                            p_created_by,
                            p_created_by,
                            NOW()
                        )
                        ON CONFLICT (material_per_period_id, start_week, end_week) WHERE deleted_at IS NULL
                            DO UPDATE
                                SET
                                    fl_config_type = p_fl_config_type,
                                    lower_level_limit = p_lower_level_limit,
                                    upper_level_limit = p_upper_level_limit,
                                    date_completed = NOW(),
                                    user_completed_id = p_created_by,
                                    updated_by = p_created_by,
                                    deleted_by = NULL,
                                    updated_at = NOW(),
                                    deleted_at = NULL
                            RETURNING mpt.id, mpt.updated_at IS NULL AS is_new
                    ), remove_overlapping_periods_in_ballot AS (
                        UPDATE material_per_period_ballot mppb
                        SET
                            deleted_by = p_created_by,
                            deleted_at = NOW()
                        WHERE 1 = 1
                        AND mppb.material_per_period_id IN ( SELECT ip.id FROM insert_material_per_period AS ip WHERE is_new IS FALSE )
                        AND ( mppb.start_week BETWEEN p_start_week AND p_end_week OR mppb.end_week BETWEEN p_start_week AND p_end_week )
                        AND NOT ( mppb.start_week = p_start_week AND mppb.end_week = p_end_week )
                        RETURNING mppb.id AS material_period_id
                    ), remove_urls_in_overlapping AS (
                        UPDATE material_per_period_ballot_url mbppbu
                            SET
                            deleted_by = p_created_by,
                            deleted_at = NOW()
                        WHERE mbppbu.material_per_period_ballot_id IN ( SELECT rmv.material_period_id FROM remove_overlapping_periods_in_ballot rmv )
                        RETURNING mbppbu.id AS material_period_url_id
                    ), remove_class_urls_in_overlapping AS (
                        UPDATE material_per_period_ballot_class class_urls
                            SET
                                deleted_by = p_created_by,
                                deleted_at = NOW()
                        WHERE class_urls.material_per_period_ballot_url_id IN ( SELECT rmu.material_period_url_id FROM remove_urls_in_overlapping rmu )
                    ), weeks_in_type_material_ids AS (
                        SELECT
                            tmdt.week,
                            ttm.id AS child_type_material_id,
                            ttm.parent_id AS parent_type_material_id
                        FROM type_material_detail_template tmdt
                        LEFT JOIN (
                            SELECT tm.id, tm.parent_id FROM type_material tm
                            WHERE tm.id IN ( SELECT UNNEST(ids) FROM type_material_ids )
                        ) ttm ON 1 = 1
                        WHERE 1 = 1
                        AND tmdt.type_material_id = p_type_material_id
                        AND tmdt.week BETWEEN p_start_week AND p_end_week
                        AND tmdt.fl_status = true
                        ORDER BY tmdt.week ASC, ttm.id ASC
                    ), insert_or_update_detail_week_type AS (
                        INSERT INTO detail_week_type_mat AS dwtm (
                            material_id,
                            week,
                            type_material_id,
                            parent_type_material_id,
                            fl_config_type,
                            limit_lower_question,
                            limit_upper_question,
                            created_by,
                            created_at
                        )
                        SELECT
                            p_material_id,
                            wt.week,
                            wt.child_type_material_id,
                            wt.parent_type_material_id,
                            p_fl_config_type,
                            p_lower_level_limit,
                            p_upper_level_limit,
                            p_created_by,
                            NOW()
                        FROM weeks_in_type_material_ids wt
                        ON CONFLICT ON CONSTRAINT ux_detail_week_type_mat
                        DO UPDATE
                            SET
                                parent_type_material_id = EXCLUDED.parent_type_material_id,
                                fl_config_type = EXCLUDED.fl_config_type,
                                limit_lower_question = EXCLUDED.limit_lower_question,
                                limit_upper_question = EXCLUDED.limit_upper_question,
                                updated_by = p_created_by,
                                updated_at = NOW(),
                                fl_status = TRUE,
                                deleted_by = NULL,
                                deleted_at = NULL
                        RETURNING
                            dwtm.id,
                            dwtm.week,
                            dwtm.type_material_id,
                            dwtm.parent_type_material_id,
                            dwtm.data_incomplete_questions IS NOT NULL AS incomplete_questions,
                            dwtm.data_missing_course_config IS NOT NULL AS incomplete_course_config,
                            dwtm.data_missing_text IS NOT NULL AS incomplete_missing_text,
                            dwtm.updated_at IS NULL AS is_new
                    ), incomplete_fields_in_material_per_period AS (
                        UPDATE material_per_period_ballot mb
                            SET
                                fl_missing_questions = EXISTS( SELECT 1 FROM insert_or_update_detail_week_type WHERE incomplete_questions IS TRUE ),
                                fl_missing_courses = EXISTS( SELECT 1 FROM insert_or_update_detail_week_type WHERE incomplete_course_config IS TRUE ),
                                fl_missing_text = EXISTS( SELECT 1 FROM insert_or_update_detail_week_type WHERE incomplete_missing_text IS TRUE )
                        WHERE mb.id IN ( SELECT pp.id FROM insert_material_per_period_ballot AS pp )
                    ), get_type_material_courses AS ( -- Se trae los cursos de tipo material
                        SELECT
                            tmc.type_material_id,
                            tmc.course_id
                        FROM type_material_course tmc
                        WHERE tmc.type_material_id IN ( SELECT UNNEST(ids) FROM type_material_ids )
                            AND amount_question > 0
                            AND fl_status = true
                    ), get_type_material_courses_text AS ( -- Se trae los cursos de tipo material
                        SELECT
                            tmc.type_material_id,
                            tmc.course_id
                        FROM type_material_course tmc
                        WHERE tmc.type_material_id IN ( SELECT UNNEST(ids) FROM type_material_ids )
                            AND amount_text > 0
                            AND fl_status = true
                    ), get_courses_not_register_ballot AS (
                        SELECT DISTINCT
                            gtmc.course_id
                        FROM get_type_material_courses gtmc
                        LEFT JOIN (
                            SELECT DISTINCT
                                mdbq.course_id
                            FROM detail_week_type_mat dwtm
                            JOIN material_ballot_question mdbq
                                ON dwtm.id = mdbq.week_type_material_id
                            WHERE mdbq.material_id = p_material_id
                                AND dwtm.week BETWEEN p_start_week AND p_end_week
                                AND dwtm.type_material_id IN ( SELECT UNNEST(ids) FROM type_material_ids )
                                AND mdbq.fl_status = true
                                AND mdbq.type_text_id IS NULL
                        ) AS existing_courses
                        ON gtmc.course_id = existing_courses.course_id
                        WHERE existing_courses.course_id IS NULL
                    ), get_courses_not_register_ballot_text AS (
                        SELECT DISTINCT
                            gtmc.course_id
                        FROM get_type_material_courses_text gtmc
                        LEFT JOIN (
                            SELECT DISTINCT
                                mdbq.course_id
                            FROM detail_week_type_mat dwtm
                            JOIN material_ballot_question mdbq
                                ON dwtm.id = mdbq.week_type_material_id
                            WHERE mdbq.material_id = p_material_id
                                AND dwtm.week BETWEEN p_start_week AND p_end_week
                                AND dwtm.type_material_id IN ( SELECT UNNEST(ids) FROM type_material_ids )
                                AND mdbq.fl_status = true
                                AND mdbq.type_text_id IS NOT NULL
                        ) AS existing_courses
                        ON gtmc.course_id = existing_courses.course_id
                        WHERE existing_courses.course_id IS NULL
                    ), get_courses_generic AS (
                        SELECT DISTINCT
                            tmc.course_id,
                            tmc.type_material_id
                        FROM type_material_course tmc
                        WHERE tmc.type_material_id IN ( SELECT UNNEST(ids) FROM type_material_ids )
                            AND tmc.is_generic = true
                            AND tmc.fl_status = true
                            AND tmc.amount_question > 0
                    ), get_courses_text_generic AS (
                        SELECT DISTINCT
                            tmc.course_id,
                            tmc.type_material_id
                        FROM type_material_course tmc
                        WHERE tmc.type_material_id IN ( SELECT UNNEST(ids) FROM type_material_ids )
                            AND tmc.is_generic_text = true
                            AND tmc.amount_text > 0
                            AND tmc.fl_status = true
                    ), get_courses_not_generic AS (
                        SELECT DISTINCT
                            tmc.course_id,
                            tm.id AS type_material_id
                        FROM odiseo.type_material tm
                        JOIN odiseo.type_material_detail_template tmdt ON tmdt.type_material_id = tm.id
                            AND tmdt.fl_status = true
                        JOIN odiseo.type_material_course tmc ON tmc.type_material_id = tm.id
                        LEFT JOIN odiseo.type_material_detail_courses tmdc ON tmdc.type_material_course_id = tmc.id
                            AND tmdc.type_material_detail_template_id = tmdt.id
                        WHERE tm.id IN ( SELECT UNNEST(ids) FROM type_material_ids )
                            AND tmc.is_generic = false
                            AND tmdt.week BETWEEN p_start_week AND p_end_week
                            AND tmdc.amount_question > 0
                    ), get_courses_text_not_generic AS (
                        SELECT DISTINCT
                            tmc.course_id,
                            tm.id AS type_material_id
                        FROM odiseo.type_material tm
                        JOIN odiseo.type_material_detail_template tmdt ON tmdt.type_material_id = tm.id
                            AND tmdt.fl_status = true
                        JOIN odiseo.type_material_course tmc ON tmc.type_material_id = tm.id
                        LEFT JOIN odiseo.type_material_detail_course_texts tmdct ON tmdct.type_material_course_id = tmc.id
                            AND tmdct.type_material_detail_template_id = tmdt.id
                        WHERE tm.id IN ( SELECT UNNEST(ids) FROM type_material_ids )
                            AND tmc.is_generic_text = false
                            AND tmdt.week BETWEEN p_start_week AND p_end_week
                            AND tmdct.amount_text > 0
                    ), get_courses AS (
                        SELECT
                            gcg.course_id,
                            gcg.type_material_id
                        FROM get_courses_generic gcg
                        UNION ALL
                        SELECT
                            gcng.course_id,
                            gcng.type_material_id
                        FROM get_courses_not_generic gcng
                    ), get_courses_text AS (
                        SELECT
                            gcg.course_id,
                            gcg.type_material_id
                        FROM get_courses_text_generic gcg
                        UNION ALL
                        SELECT
                            gcng.course_id,
                            gcng.type_material_id
                        FROM get_courses_text_not_generic gcng
                    ), tbl_get_material_per_period AS (
                        SELECT
                            io.id,
                            ( SELECT z.id FROM insert_material_per_period_ballot AS z ) AS material_per_period_ballot_id,
                            io.week,
                            m.cycle_id,
                            c.start_date,
                            io.type_material_id,
                            tm.description AS type_material,
                            FALSE AS exists_per_period,
                            FALSE AS has_questions,
                            io.parent_type_material_id,
                            FALSE AS fl_exam,
                            COALESCE((
                                SELECT jsonb_agg(gc.course_id ORDER BY gc.course_id ASC)
                                FROM get_courses gc
                                WHERE gc.type_material_id = io.type_material_id
                            ), '[]'::JSONB) AS courses,
                            COALESCE((
                                SELECT jsonb_agg(gct.course_id ORDER BY gct.course_id ASC)
                                FROM get_courses_text gct
                                WHERE gct.type_material_id = io.type_material_id
                            ), '[]'::JSONB) AS courses_for_text,
                            COALESCE((
                                SELECT jsonb_agg(gc.course_id ORDER BY gc.course_id ASC)
                                FROM get_courses gc
                                WHERE gc.type_material_id = io.type_material_id
                                    AND gc.course_id IN (SELECT gcnrb.course_id FROM get_courses_not_register_ballot gcnrb)
                            ), '[]'::JSONB) AS courses_missing,
                            COALESCE((
                                SELECT jsonb_agg(gct.course_id ORDER BY gct.course_id ASC)
                                FROM get_courses_text gct
                                WHERE gct.type_material_id = io.type_material_id
                                    AND gct.course_id IN (SELECT gcnrbt.course_id FROM get_courses_not_register_ballot_text gcnrbt)
                            ), '[]'::JSONB) AS courses_for_text_missing,
                            m.university_id,
                            m.headquarte_id
                        FROM insert_or_update_detail_week_type io
                        LEFT JOIN material m ON m.id = p_material_id
                        LEFT JOIN type_material tm ON io.type_material_id = tm.id
                        LEFT JOIN cycle c ON c.id = m.cycle_id
                    )
                    SELECT
                        tgmpp.*
                    FROM tbl_get_material_per_period tgmpp;
                END;
                $$;


ALTER FUNCTION odiseo.fn_get_material_per_period_ballot_complete(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint, p_fl_config_type boolean, p_lower_level_limit smallint, p_upper_level_limit smallint, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_get_material_per_period_exam(bigint, smallint, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_material_per_period_exam(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) RETURNS TABLE(id bigint, material_id bigint, type_material_id smallint, exam_area_id bigint, fl_created boolean, start_week smallint, end_week smallint, questions_missing_url character varying, courses_missing_url character varying, text_missing_url character varying, url jsonb)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            WITH tbl_type_url (id, name) AS (
                VALUES
                    (1, 'solution'::VARCHAR),
                    (2, 'without_solution'::VARCHAR)
            ), tbl_type_material AS (
                SELECT
                    tm.id,
                    tm.fl_class_material,
                    tma.area_id AS exam_area_id,
                    ea.description
                FROM type_material tm
                LEFT JOIN type_material_area tma ON tm.id = tma.type_material_id
                LEFT JOIN exam_area ea ON tma.area_id = ea.id
                WHERE tm.id = p_type_material_id
            ), tbl_material_per_period AS (
                SELECT DISTINCT
                    mpp.id,
                    m.id,
                    COALESCE(mpp.type_material_id, ttm.id) AS type_material_id,
					COALESCE(mppe.exam_area_id, ttm.exam_area_id) AS exam_area_id,
                    CASE
                        WHEN mppe.start_week IS NOT NULL THEN TRUE
                        ELSE FALSE
                    END AS fl_created,
                    COALESCE(mppe.start_week, p_start_week) AS start_week,
                    COALESCE(mppe.end_week, p_end_week) AS end_week,
                    mppe.questions_missing_url,
                    mppe.courses_missing_url,
                    mppe.text_missing_url,
                    COALESCE((
                        SELECT jsonb_agg(jsonb_build_object(
                            'id', mppeu.id,
                            'material_per_period_exam_id', COALESCE(mppeu.material_per_period_exam_id, mppe.id),
                            'type_url', COALESCE(mppeu.type_url, ttu.name),
                            'fl_job_process',COALESCE(mppeu.fl_job_process, 'unprocessed'::VARCHAR),
                            'job_url', mppeu.job_url,
                            'job_id', mppeu.job_id
                        ) ORDER BY ttu.id ASC) AS urls
                        FROM tbl_type_url ttu
                        LEFT JOIN material_per_period_exam_url mppeu ON ttu.name = mppeu.type_url
                            AND mppeu.deleted_by IS NULL
                            AND mppeu.material_per_period_exam_id = mppe.id
                    ), '[]'::JSONB) AS url
                FROM material m
				LEFT JOIN tbl_type_material ttm ON 1 = 1
                LEFT JOIN material_per_period mpp ON m.id = mpp.material_id
                    AND mpp.deleted_by IS NULL
                    AND mpp.type_material_id = p_type_material_id
                LEFT JOIN material_per_period_exam mppe ON mpp.id = mppe.material_per_period_id
                    AND mppe.deleted_by IS NULL
                    AND mppe.start_week = p_start_week
                    AND mppe.end_week = p_end_week
                WHERE m.id = p_material_id
            )
            SELECT * FROM tbl_material_per_period tmpp;
        END;
        $$;


ALTER FUNCTION odiseo.fn_get_material_per_period_exam(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) OWNER TO postgres;

--
-- Name: fn_get_material_per_period_urls(integer, integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_material_per_period_urls(p_material_id integer, p_parent_type_id integer, p_start_week integer, p_end_week integer) RETURNS TABLE(type_material_id integer, type_material character varying, id bigint, material_per_period_ballot_id bigint, type_url character varying, fl_job_process character varying, job_url character varying, job_id character varying, file_name character varying)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                WITH tbl_type_url (id, name) AS (
                    VALUES
                        (1, 'solution'::VARCHAR),
                        (3, 'review_solution'::VARCHAR)
                ), 
                type_material_ids AS (
                    SELECT UNNEST(
                        CASE
                            WHEN EXISTS (SELECT 1 FROM type_material tm WHERE tm.parent_id = p_parent_type_id)
                            THEN ARRAY(SELECT tm.id FROM type_material tm WHERE tm.parent_id = p_parent_type_id)
                            ELSE ARRAY[p_parent_type_id]
                        END
                    ) AS type_material_id
                )
                SELECT 
                    tmi.type_material_id,
                    tm.description type_material,
                    mppbu.id,
                    mppbu.material_per_period_ballot_id,
                    ttu.name AS type_url,
                    COALESCE(mppbu.fl_job_process, 'unprocessed'::VARCHAR) AS fl_job_process,
                    mppbu.job_url,
                    mppbu.job_id::VARCHAR,
                    mppbu.file_name
                FROM type_material_ids tmi
                JOIN type_material tm ON tm.id = tmi.type_material_id AND tm.parent_id IS NOT NULL
                CROSS JOIN tbl_type_url ttu
                LEFT JOIN material_per_period mpp 
                    ON mpp.type_material_id = tmi.type_material_id
                    AND mpp.material_id = p_material_id
                LEFT JOIN material_per_period_ballot mppb 
                    ON mppb.material_per_period_id = mpp.id 
                    AND mppb.start_week = p_start_week 
                    AND mppb.end_week = p_end_week
                LEFT JOIN material_per_period_ballot_url mppbu 
                    ON mppbu.material_per_period_ballot_id = mppb.id 
                    AND mppbu.type_url = ttu.name 
                    AND mppbu.deleted_by IS NULL
                ORDER BY tm.description;
            END;
            $$;


ALTER FUNCTION odiseo.fn_get_material_per_period_urls(p_material_id integer, p_parent_type_id integer, p_start_week integer, p_end_week integer) OWNER TO postgres;

--
-- Name: fn_get_material_periodicity_courses_pages(bigint, character varying, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_material_periodicity_courses_pages(p_material_per_period_ballot_id bigint, p_type character varying, p_course_id smallint) RETURNS TABLE(course_id smallint, pages smallint, previous_course_pages smallint)
    LANGUAGE plpgsql
    AS $$
    DECLARE
        v_type_material_id BIGINT;
        v_has_custom_order BOOLEAN;
        v_university_id SMALLINT;
    BEGIN
        ------------------------------------------------------------------
        -- 1. Obtener type_material y universidad
        ------------------------------------------------------------------
        SELECT
            mpp.type_material_id,
            m.university_id
        INTO
            v_type_material_id,
            v_university_id
        FROM material_per_period_ballot mppb
        JOIN material_per_period mpp ON mpp.id = mppb.material_per_period_id
        JOIN material m ON m.id = mpp.material_id
        WHERE mppb.id = p_material_per_period_ballot_id;

        ------------------------------------------------------------------
        -- 2. Verificar si existe ordenamiento personalizado por template
        ------------------------------------------------------------------
        SELECT EXISTS (
            SELECT 1
            FROM type_material tm
            JOIN type_material_template tmt ON tmt.id = tm.type_material_template_id
            JOIN template_type_material_courses_order ttmco
                ON ttmco.template_type_material_id = tmt.id
            WHERE tm.id = v_type_material_id
            AND ttmco.university_id IS NULL
        )
        INTO v_has_custom_order;

        ------------------------------------------------------------------
        -- 3. Selección según tipo de orden
        ------------------------------------------------------------------
        IF v_has_custom_order THEN

            ------------------------------------------------------------------
            -- OPCIÓN A: Orden por Template (position)
            ------------------------------------------------------------------
            RETURN QUERY
            WITH all_courses AS (
                SELECT
                    mppc.course_id,
                    mppc.pages,
                    ttmco.position
                FROM material_per_period_course mppc
                JOIN material_per_period_ballot mppb
                    ON mppb.id = mppc.material_per_period_ballot_id
                JOIN material_per_period mpp
                    ON mpp.id = mppb.material_per_period_id
                JOIN type_material tm
                    ON tm.id = mpp.type_material_id
                JOIN type_material_template tmt
                    ON tmt.id = tm.type_material_template_id
                JOIN template_type_material_courses_order ttmco
                    ON ttmco.template_type_material_id = tmt.id
                AND ttmco.course_id = mppc.course_id
                WHERE mppc.material_per_period_ballot_id = p_material_per_period_ballot_id
                AND mppc.type = p_type
                AND mppc.deleted_at IS NULL
                AND ttmco.university_id IS NULL
            ),
            calc_prev AS (
                SELECT
                    ac.course_id,
                    ac.pages,
                    (
                        SELECT ac2.pages
                        FROM all_courses ac2
                        WHERE ac2.position < ac.position
                        AND ac2.pages IS NOT NULL
                        AND ac2.pages > 0
                        ORDER BY ac2.position DESC
                        LIMIT 1
                    ) AS prev_pages
                FROM all_courses ac
            )
            SELECT
                cp.course_id::SMALLINT,
                cp.pages::SMALLINT,
                COALESCE(cp.prev_pages, 0)::SMALLINT
            FROM calc_prev cp
            WHERE cp.course_id = p_course_id;

        ELSE

            ------------------------------------------------------------------
            -- OPCIÓN B: Fallback por course_id
            ------------------------------------------------------------------
            RETURN QUERY
            WITH type_materials AS (
                SELECT
                    CASE WHEN EXISTS (
                        SELECT 1 FROM type_material tm
                        WHERE tm.parent_id = v_type_material_id) THEN
                        ARRAY (
                            SELECT tm.id FROM type_material tm WHERE tm.parent_id = v_type_material_id
                        )
                    ELSE
                        ARRAY[v_type_material_id]
                    END AS ids
            ), type_material_ids AS (
                SELECT UNNEST(tm.ids) AS id FROM type_materials tm
            ), courses_type_material AS (
                SELECT DISTINCT
                    c.id AS course_id
                FROM type_material_course tmc
                JOIN course c ON c.id = tmc.course_id
                WHERE tmc.type_material_id IN (SELECT tmi.id FROM type_material_ids tmi)
            ), all_courses AS (
                SELECT
                    mppc.course_id,
                    mppc.pages
                FROM material_per_period_course mppc
                JOIN material_per_period_ballot mppb
                    ON mppb.id = mppc.material_per_period_ballot_id
                JOIN material_per_period mpp
                    ON mpp.id = mppb.material_per_period_id
                JOIN courses_type_material ctm
                    ON ctm.course_id = mppc.course_id
                WHERE mppc.material_per_period_ballot_id = p_material_per_period_ballot_id
                AND mppc.type = p_type
                AND mppc.deleted_at IS NULL
            ),
            calc_prev AS (
                SELECT
                    ac.course_id,
                    ac.pages,
                    (
                        SELECT ac2.pages
                        FROM all_courses ac2
                        WHERE ac2.course_id < ac.course_id
                        AND ac2.pages IS NOT NULL
                        AND ac2.pages > 0
                        ORDER BY ac2.course_id DESC
                        LIMIT 1
                    ) AS prev_pages
                FROM all_courses ac
            )
            SELECT
                cp.course_id::SMALLINT,
                cp.pages::SMALLINT,
                COALESCE(cp.prev_pages, 0)::SMALLINT
            FROM calc_prev cp
            WHERE cp.course_id = p_course_id;

        END IF;
    END;
    $$;


ALTER FUNCTION odiseo.fn_get_material_periodicity_courses_pages(p_material_per_period_ballot_id bigint, p_type character varying, p_course_id smallint) OWNER TO postgres;

--
-- Name: fn_get_material_questions_change_position(integer, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_material_questions_change_position(p_week_type_material_id integer, p_topic_ids jsonb) RETURNS TABLE(week_type_material_id bigint, course_id smallint, topic_id smallint, subtopic_id smallint, level_id bigint, level smallint, question_id bigint, type character varying)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    mbq.week_type_material_id,
                    mbq.course_id,
                    mbq.topic_id,
                    mbq.subtopic_id,
                    mbq.level_id,
                    l."name"::SMALLINT  AS level,
                    mbq.question_id, 
                    mbq."type"
                FROM odiseo.material_ballot_question mbq
                LEFT JOIN odiseo."level" l
                    ON mbq.level_id = l.id
                WHERE mbq.fl_status = TRUE
                    AND mbq.week_type_material_id = p_week_type_material_id
                    AND mbq.topic_id = ANY (
                        SELECT jsonb_array_elements_text(p_topic_ids)::BIGINT
                    );
            END;
            $$;


ALTER FUNCTION odiseo.fn_get_material_questions_change_position(p_week_type_material_id integer, p_topic_ids jsonb) OWNER TO postgres;

--
-- Name: fn_get_material_questions_detail(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_material_questions_detail(p_material_missing_question_id bigint) RETURNS TABLE(id bigint, topic_id smallint, topic character varying, subtopic_id smallint, subtopic character varying, level_id bigint, level character varying, question_id bigint, question_code character varying, question_status character varying, type_question character varying, status character varying, course_id smallint, course character varying, employee text, employee_id bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        mmqd.id,
        mdbq.topic_id,
        t."name" topic,
        mdbq.subtopic_id,
        s."name" subtopic,
        mdbq.level_id,
        l.name level,
        q.id question_id,
        q.code question_code,
        q.status question_status,
        mdbq.type type_question,
        mmqd.status,
        mdbq.course_id,
        c."name" course,
        CONCAT_WS(' ', e.first_name, e.first_surname, e.second_surname) as employee,
        e.id as employee_id
    FROM
        material_missing_question_detail mmqd
        JOIN material_ballot_question mdbq ON mdbq.id = mmqd.material_ballot_question_id
        JOIN topic t ON t.id = mdbq.topic_id
        JOIN subtopic s ON s.id = mdbq.subtopic_id
        JOIN "level" l ON l.id = mdbq.level_id
        LEFT JOIN question q ON q.id = mmqd.question_id
        JOIN course c ON c.id = mdbq.course_id
        LEFT JOIN employees e ON e.id = mmqd.employee_id
    WHERE
        mmqd.material_missing_question_id = p_material_missing_question_id
        AND mmqd.deleted_at IS NULL
    ORDER BY
        mdbq.topic_id,
        mdbq.subtopic_id,
        mdbq.level_id;
END;
$$;


ALTER FUNCTION odiseo.fn_get_material_questions_detail(p_material_missing_question_id bigint) OWNER TO postgres;

--
-- Name: fn_get_material_revision_detail(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_material_revision_detail(p_revision_id bigint, p_user_id bigint) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_employee_id bigint;
    v_result      json;
BEGIN
    -- 1. Obtener el employee_id asociado al user_id
    SELECT id INTO v_employee_id
    FROM employees
    WHERE user_id = p_user_id
      AND deleted_at IS NULL;

    -- 2. Construir la estructura jerárquica
    SELECT json_build_object(
        'id', mr.id,
        'status', mr.status,
        'weeks', ARRAY[mr.start_week, mr.end_week],
        'cycle', cyc.description,
        'last_date', mr.delivery_date,
        'limit_questions_to_change', adv.limit_questions_to_change,
        'detail_courses', COALESCE((
            SELECT json_agg(json_build_object(
                'id', mrc.id,
                'course', crs.name,
                'course_id', mrc.course_id,
                'date_verified', mrc.verify_date,
                'status', mrc.status,
                'amount_questions_changed', mrc.amount_questions_changed,
                'materials', (
                    SELECT json_agg(json_build_object(
                        'id', mppc.id,
                        'material_name', CONCAT_WS(' - ',
                            'Material',
                            CASE v.type_name
                                WHEN 'without_solution'        THEN 'Sin Solución - Oficial'
                                WHEN 'review_without_solution' THEN 'Sin Solución - Revisión'
                            END,
                            'Semana (' || mr.start_week || ' - ' || mr.end_week || ')'
                        ),
                        'status', COALESCE(mppc.job_status, 'unprocessed'),
                        'url_pdf', mppc.url,
                        'material_id', mat.id,
                        'type_material_id', mr.type_material_id,
                        'type_url', v.type_name
                    ) ORDER BY v.type_name DESC)
                    FROM (
                        VALUES ('without_solution'), ('review_without_solution')
                    ) AS v(type_name)
                    LEFT JOIN (
                        SELECT mppc.*, mpp.material_id, mpp.type_material_id
                        FROM material_per_period_course mppc
                        JOIN material_per_period_ballot mppb ON mppb.id = mppc.material_per_period_ballot_id
                        JOIN material_per_period mpp ON mpp.id = mppb.material_per_period_id
                        WHERE mpp.material_id = mr.material_id
                          AND mpp.type_material_id = mr.type_material_id
                          AND mppb.start_week = mr.start_week
                          AND mppb.end_week = mr.end_week
                          AND mppc.course_id = mrc.course_id
                          AND mppc.deleted_at IS NULL
                    ) mppc ON mppc.type = v.type_name
                )
            ) ORDER BY crs.name)
            FROM material_revision_courses mrc
            JOIN course crs ON crs.id = mrc.course_id
            LEFT JOIN employee_course ec ON ec.course_id = mrc.course_id
                                              AND ec.teacher_id = v_employee_id
                                              AND ec.fl_status = true
            WHERE mrc.material_revision_id = mr.id
              AND (p_user_id IS NULL OR ec.id IS NOT NULL)
              AND mrc.deleted_at IS NULL
        ), '[]'::json)
    ) INTO v_result
    FROM material_revisions mr
    JOIN material mat ON mat.id = mr.material_id
    JOIN cycle cyc ON cyc.id = mat.cycle_id
    JOIN advanced_settings adv ON adv.company_id = 1 -- odiseo
    WHERE mr.id = p_revision_id
      AND mr.deleted_at IS NULL;

    RETURN v_result;
END;
$$;


ALTER FUNCTION odiseo.fn_get_material_revision_detail(p_revision_id bigint, p_user_id bigint) OWNER TO postgres;

--
-- Name: fn_get_material_revision_list(integer, integer, bigint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_material_revision_list(p_perpage integer, p_npage integer, p_user_id bigint, p_cycle_id bigint DEFAULT NULL::bigint, p_company_id bigint DEFAULT NULL::bigint) RETURNS TABLE(id bigint, cycle_id bigint, cycle character varying, type_material_id smallint, type_material_description character varying, weeks json, delivery_date timestamp without time zone, verify_date timestamp without time zone, status character varying, course_total bigint, course_amount_verified bigint, total bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    offset_val INTEGER;
BEGIN
    offset_val := p_perpage * (p_npage - 1);

    RETURN QUERY
    WITH cte_revision AS (
        SELECT
            mr.id,
            c.id                                          AS cycle_id,
            c.description                                 AS cycle,
            tm.id                                         AS type_material_id,
            tm.description                                AS type_material_description,
            json_build_object(
                'start_week', mr.start_week,
                'end_week',   mr.end_week
            )                                             AS weeks,
            mr.delivery_date,
            mr.verify_date,
            mr.status,
            COUNT(mrc.id)                                 AS course_total,
            SUM(CASE WHEN mrc.status = 'verified' THEN 1 ELSE 0 END) AS course_amount_verified
        FROM material_revisions mr
        JOIN material mat         ON mat.id = mr.material_id
        JOIN cycle c              ON c.id = mat.cycle_id
        JOIN type_material tm     ON tm.id = mr.type_material_id
        JOIN material_revision_courses mrc
                                         ON mr.id = mrc.material_revision_id
        LEFT JOIN employees emp    ON emp.user_id = p_user_id
                                        AND emp.deleted_at IS NULL
        LEFT JOIN employee_course ec ON ec.teacher_id = emp.id
                                        AND ec.course_id = mrc.course_id
                                        AND ec.fl_status = true
                                        AND ec.deleted_at IS NULL
        WHERE mr.deleted_at  IS NULL
          AND mrc.deleted_at IS NULL
          AND mr.status != 'queued'
          AND (p_user_id IS NULL OR ec.id IS NOT NULL)
          AND (p_cycle_id IS NULL OR c.id = p_cycle_id)
          AND (p_company_id IS NULL OR c.company_id = p_company_id)
        GROUP BY mr.id, c.id, c.description, tm.id, tm.description, mr.start_week, mr.end_week,
                 mr.delivery_date, mr.verify_date, mr.status
    )
    SELECT chq.*, COUNT(*) OVER() AS total
    FROM cte_revision chq
    ORDER BY chq.delivery_date DESC
    LIMIT  p_perpage
    OFFSET offset_val;
END;
$$;


ALTER FUNCTION odiseo.fn_get_material_revision_list(p_perpage integer, p_npage integer, p_user_id bigint, p_cycle_id bigint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_get_material_week_type_mat(bigint, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_material_week_type_mat(p_material_id bigint, p_week smallint, p_type_material smallint) RETURNS TABLE(id bigint, material_id bigint, week smallint, type_material_id smallint, area_id smallint, url_solution character varying, url_without_solution character varying, url_quality character varying, url_without_quality character varying, parent_type_material_id smallint, fl_process_status smallint, fl_process_status_without smallint, fl_process_quality smallint, fl_process_without_quality smallint, job_solution_id character varying, job_without_solution_id character varying, job_quality_id character varying, job_without_quality_id character varying, fl_process_class_mat smallint, url_zip_class_mat character varying)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_type_materials SMALLINT[] := ARRAY[]::SMALLINT[];
            v_p_type_material_template_id SMALLINT;
            v_type_material_id SMALLINT;
            v_cycle_id BIGINT;
            v_fl_exam BOOLEAN;
        BEGIN
            -- Obtener plantilla de ciclo por medio del material
            SELECT m.cycle_id INTO v_cycle_id
            FROM material m
            WHERE m.id = p_material_id LIMIT 1;

            -- Obtener el estado de examen
            SELECT tym.fl_exam INTO v_fl_exam FROM type_material tym WHERE tym.id = p_type_material LIMIT 1;

            SELECT tmp.type_material_template_id INTO v_p_type_material_template_id
            FROM type_material tmp
            WHERE tmp.id = p_type_material LIMIT 1;

            FOR v_type_material_id IN
                SELECT tm.id
                FROM type_material_bound tmbo
                INNER JOIN type_material_template tmt ON tmbo.type_material_template_extra_id = tmt.id
                INNER JOIN type_material tm ON tmt.id = tm.type_material_template_id
                WHERE tmbo.type_material_template_id = v_p_type_material_template_id
                AND tm.cycle_id = v_cycle_id
                AND tmbo.fl_status = true
            LOOP
                v_type_materials := array_append(v_type_materials, v_type_material_id);
            END LOOP;

            IF v_type_materials = '{}' THEN
                v_type_materials := array_append(v_type_materials, p_type_material);
            END IF;

            IF v_fl_exam IS TRUE THEN
                RETURN QUERY
                SELECT
                    meaw.id,
                    dwt.material_id,
                    dwt.week,
                    dwt.type_material_id,
                    meaw.area_id,
                    meaw.url_solution,
                    meaw.url_without_solution,
                    meaw.url_quality,
                    meaw.url_without_quality,
                    dwt.parent_type_material_id,
                    meaw.fl_process_status,
                    meaw.fl_process_status_without,
                    meaw.fl_process_quality,
                    meaw.fl_process_without_quality,
                    meaw.job_solution_id,
                    meaw.job_without_solution_id,
                    meaw.job_quality_id,
                    meaw.job_without_quality_id,
                    0::SMALLINT AS fl_process_class_mat,
                    NULL::VARCHAR AS url_zip_class_mat
                FROM material_exam_area_week meaw
                INNER JOIN detail_week_type_mat dwt ON meaw.week_type_material_id = dwt.id AND meaw.fl_status = true AND dwt.fl_status IS TRUE
                WHERE dwt.material_id = p_material_id
                AND dwt.week = p_week
                AND dwt.type_material_id = ANY(v_type_materials)
                AND dwt.fl_status = true
                AND meaw.fl_status = true;
            ELSE
                RETURN QUERY
                SELECT
                    dwt.id,
                    dwt.material_id,
                    dwt.week,
                    dwt.type_material_id,
                    NULL::SMALLINT,
                    dwt.url_solution,
                    dwt.url_without_solution,
                    dwt.url_quality,
                    dwt.url_without_quality,
                    dwt.parent_type_material_id,
                    dwt.fl_process_status,
                    dwt.fl_process_status_without,
                    dwt.fl_process_quality,
                    dwt.fl_process_without_quality,
                    dwt.job_solution_id,
                    dwt.job_without_solution_id,
                    dwt.job_quality_id,
                    dwt.job_without_quality_id,
                    dwt.fl_process_class_mat,
                    dwt.url_zip_class_mat
                FROM detail_week_type_mat dwt
                WHERE dwt.material_id = p_material_id
                AND dwt.week = p_week
                AND dwt.type_material_id = ANY(v_type_materials)
                AND dwt.fl_status = true;
            END IF;
        END;
        $$;


ALTER FUNCTION odiseo.fn_get_material_week_type_mat(p_material_id bigint, p_week smallint, p_type_material smallint) OWNER TO postgres;

--
-- Name: fn_get_missing_ballot_questions_per_period(integer, integer, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_missing_ballot_questions_per_period(p_material_id integer, p_type_material_id integer, p_start_week smallint, p_end_week smallint) RETURNS TABLE(week smallint, material character varying, course character varying, course_id smallint, topic character varying, subtopic character varying, level character varying, type character varying)
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                        RETURN QUERY
                        WITH type_material_ids AS (
                            SELECT UNNEST(
                                CASE
                                    WHEN EXISTS (SELECT 1 FROM type_material tm WHERE tm.parent_id = p_type_material_id)
                                    THEN ARRAY(SELECT tm.id FROM type_material tm WHERE tm.parent_id = p_type_material_id)
                                    ELSE ARRAY[p_type_material_id]
                                END
                            ) AS id
                        )
                        SELECT 
                            mdbq.week,
                            tm.description AS material,
                            c.name AS course,
                            c.id as course_id,
                            t.name AS topic,
                            s.name AS subtopic,
                            l.name AS level,
                            mdbq."type"
                        FROM material_ballot_question mdbq 
                        JOIN "level" l ON l.id = mdbq.level_id
                        JOIN course c ON c.id = mdbq.course_id
                        JOIN type_material tm ON tm.id = mdbq.type_material_id
                        JOIN topic t ON t.id = mdbq.topic_id 
                        JOIN subtopic s ON s.id = mdbq.subtopic_id 
                        WHERE mdbq.material_id = p_material_id
                        AND mdbq.fl_status = TRUE
                        AND mdbq.type_material_id IN (SELECT * FROM type_material_ids)
                        AND mdbq.week BETWEEN p_start_week AND p_end_week
                        AND mdbq.type_text_id IS NULL
                        AND mdbq.question_id IS NULL;
                    END;
                $$;


ALTER FUNCTION odiseo.fn_get_missing_ballot_questions_per_period(p_material_id integer, p_type_material_id integer, p_start_week smallint, p_end_week smallint) OWNER TO postgres;

--
-- Name: fn_get_missing_questions(integer, integer, integer[]); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_missing_questions(p_material_id integer, p_week integer, p_type_material_ids integer[]) RETURNS TABLE(material character varying, course character varying, topic character varying, subtopic character varying, level character varying, type character varying)
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                    RETURN QUERY
                    SELECT 
                        tm.description AS material,
                        c.name AS course,
                        t.name AS topic,
                        s.name AS subtopic,
                        l.name AS level,
                        mdbq."type"
                    FROM 
                        material_ballot_question mdbq
                    JOIN "level" l ON l.id = mdbq.level_id
                    JOIN course c ON c.id = mdbq.course_id
                    JOIN type_material tm ON tm.id = mdbq.type_material_id
                    JOIN topic t ON t.id = mdbq.topic_id 
                    JOIN subtopic s ON s.id = mdbq.subtopic_id 
                    WHERE 
                    mdbq.material_id = p_material_id
                    AND mdbq.week = p_week
                    AND mdbq.type_material_id = ANY(p_type_material_ids)
                    AND mdbq.fl_status = TRUE
                    AND mdbq.type_text_id IS NULL
                    AND mdbq.question_id IS NULL;

                    END;
                $$;


ALTER FUNCTION odiseo.fn_get_missing_questions(p_material_id integer, p_week integer, p_type_material_ids integer[]) OWNER TO postgres;

--
-- Name: fn_get_missing_questions_search(bigint, smallint, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_missing_questions_search(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) RETURNS TABLE(id bigint, type_material_id smallint, amount_type_mat smallint, course_position smallint, course_id smallint, code_course character varying, course character varying, topic_id smallint, code_topic character varying, topic character varying, subtopic_id smallint, code_subtopic character varying, subtopic character varying, week smallint, level_id bigint, level_description character varying, level_name character varying, usage_level_id bigint, type_question character varying, "position" smallint, position_initial smallint, question_id bigint, usage_status boolean, absolute_position smallint)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY
                    WITH type_material_ids AS (
                        SELECT
                            CASE
                                WHEN EXISTS ( SELECT 1 FROM type_material tmx WHERE tmx.parent_id = p_type_material_id )
                                THEN ARRAY( SELECT tmy.id FROM type_material tmy WHERE tmy.parent_id = p_type_material_id )
                                ELSE ARRAY[p_type_material_id]
                            END AS ids
                    ), template_type_material AS (
                        SELECT
                            tm.type_material_template_id
                        FROM type_material tm
                        WHERE tm.id = p_type_material_id
                    ), courses_ordering AS (
                        SELECT
                            cor.course_id,
                            cor.position AS course_position
                        FROM template_type_material_courses_order cor
                        WHERE 1 = 1
                            AND cor.university_id IS NULL
                            AND cor.deleted_at IS NULL
                            AND cor.template_type_material_id IN (SELECT tmt.type_material_template_id FROM template_type_material tmt)
                    ), weeks_in_type_material_ids AS (
                        SELECT
                            tmdt.week,
                            ttm.id AS child_type_material_id,
                            ttm.parent_id AS parent_type_material_id
                        FROM type_material_detail_template tmdt
                        LEFT JOIN (
                            SELECT tm.id, tm.parent_id FROM type_material tm
                            WHERE tm.id IN ( SELECT UNNEST(ids) FROM type_material_ids )
                        ) ttm ON 1 = 1
                        WHERE 1 = 1
                        AND tmdt.type_material_id = p_type_material_id
                        AND tmdt.week BETWEEN p_start_week AND p_end_week
                        AND tmdt.fl_status = true
                        ORDER BY tmdt.week ASC, ttm.id ASC
                    )
                    SELECT DISTINCT
                        mbq.id,
                        dwtm.type_material_id,
                        1::SMALLINT AS amount_type_mat,
                        ccor.course_position,
                        mbq.course_id,
                        c.code AS code_course,
                        c.name AS course,
                        mbq.topic_id,
                        t.code AS code_topic,
                        t.name AS topic,
                        mbq.subtopic_id,
                        s.code AS code_subtopic,
                        s.name AS subtopic,
                        mbq.week,
                        mbq.level_id,
                        l.description AS level_description,
                        l.name AS level_name,
                        mbq.usage_level_id,
                        mbq.type AS type_question,
                        mbq.position,
                        mbq.position_initial,
                        mbq.question_id,
                        mbq.usage_status,
                        mbq.absolute_position
                    FROM material_ballot_question mbq
                    JOIN detail_week_type_mat dwtm ON mbq.week_type_material_id = dwtm.id
                    JOIN weeks_in_type_material_ids witmi ON dwtm.week = witmi.week
                        AND dwtm.type_material_id = witmi.child_type_material_id
                    JOIN subtopic s ON mbq.subtopic_id = s.id
                    JOIN topic t ON mbq.topic_id = t.id
                    JOIN course c ON mbq.course_id = c.id
                    JOIN level l ON mbq.level_id = l.id
                    LEFT JOIN courses_ordering ccor ON mbq.course_id = ccor.course_id
                    WHERE 1 = 1
                        AND dwtm.fl_status IS TRUE
                        AND mbq.fl_status IS TRUE
                        AND dwtm.material_id = p_material_id
                        AND dwtm.type_material_id IN (SELECT UNNEST(ids) FROM type_material_ids)
                        AND mbq.type_text_id IS NULL
                    ORDER BY
                        ccor.course_position ASC,
                        mbq.course_id ASC,
                        mbq.position ASC,
                        mbq.position_initial ASC;
                END;
                $$;


ALTER FUNCTION odiseo.fn_get_missing_questions_search(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) OWNER TO postgres;

--
-- Name: fn_get_missing_questions_text_search(bigint, smallint, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_missing_questions_text_search(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) RETURNS TABLE(id bigint, type_material_id smallint, material character varying, number_of_passages smallint, course_id smallint, code_course character varying, course_name character varying, category_id bigint, category character varying, subcategory_id bigint, subcategory character varying, week smallint, parent_question_id bigint, subquestion jsonb, level_id bigint, level character varying, position_initial bigint, position_text smallint, absolute_position smallint)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    /*
                        ------------------------------------------------------------------------------------
                        -- HISTORIAL DE CAMBIOS
                        ------------------------------------------------------------------------------------
                        Versión: 1.1
                        Fecha: 2025-11-28
                        Autor: Junior Alcarraz
                        Descripción:
                            Trae preguntas texto a buscar para completar en material por periodo

                            Cambios:
                            - Se agrega la columna subquestion

                    */

                    RETURN QUERY
                    WITH type_material_ids AS (
                        SELECT
                            CASE
                                WHEN EXISTS ( SELECT 1 FROM type_material tmx WHERE tmx.parent_id = p_type_material_id )
                                THEN ARRAY( SELECT tmy.id FROM type_material tmy WHERE tmy.parent_id = p_type_material_id )
                                ELSE ARRAY[p_type_material_id]
                            END AS ids
                    ), weeks_in_type_material_ids AS (
                        SELECT
                            tmdt.week,
                            ttm.id AS child_type_material_id,
                            ttm.parent_id AS parent_type_material_id
                        FROM type_material_detail_template tmdt
                        LEFT JOIN (
                            SELECT tm.id, tm.parent_id FROM type_material tm
                            WHERE tm.id IN ( SELECT UNNEST(ids) FROM type_material_ids )
                        ) ttm ON 1 = 1
                        WHERE 1 = 1
                        AND tmdt.type_material_id = p_type_material_id
                        AND tmdt.week BETWEEN p_start_week AND p_end_week
                        AND tmdt.fl_status = true
                        ORDER BY tmdt.week ASC, ttm.id ASC
                    )
                    SELECT
                        mdbq.id,
                        dwtm.type_material_id,
                        tm.description AS material,
                        1::SMALLINT AS number_of_passages,
                        mdbq.course_id,
                        c.code AS code_course,
                        c.name AS course_name,
                        mdbq.type_text_id AS category_id,
                        tt.name AS category,
                        mdbq.type_text_subcategory_id AS subcategory_id,
                        tts.name AS subcategory,
                        mdbq.week,
                        mdbq.parent_question_id::BIGINT,
                        (SELECT JSONB_AGG(
                            JSONB_BUILD_OBJECT(
                                'question_id', mbs.question_id,
                                'position', mbs.position,
                                'topic_id', mbs.topic_id,
                                'course_id', mbs.course_id,
                                'subtopic_id', mbs.subtopic_id,
                                'status', CASE WHEN mbs.state = 'MISSING' THEN 'faltante' ELSE 'encontrado' END
                            ) ORDER BY mbs.position ASC
                        ) FROM material_ballot_subquestions mbs
                        WHERE mbs.material_ballot_question_id = mdbq.id AND mbs.fl_status = TRUE) AS subquestion,
                        mdbq.level_id,
                        l.name AS level,
                        (ROW_NUMBER() OVER (ORDER BY tt.position, tts.id) - 1) AS position_initial,
                        tt.position position_text,
                        mdbq.absolute_position
                    FROM material_ballot_question mdbq
                    JOIN detail_week_type_mat dwtm ON mdbq.week_type_material_id = dwtm.id
                    JOIN weeks_in_type_material_ids witmi ON dwtm.week = witmi.week
                        AND dwtm.type_material_id = witmi.child_type_material_id
                    JOIN type_material tm ON tm.id = dwtm.type_material_id
                    JOIN course c ON mdbq.course_id = c.id
                    JOIN type_text tt ON mdbq.type_text_id = tt.id
                    JOIN type_text_subcategories tts ON mdbq.type_text_subcategory_id = tts.id
                    JOIN level l ON mdbq.level_id = l.id
                    WHERE 1 = 1
                        AND dwtm.fl_status IS TRUE
                        AND mdbq.fl_status IS TRUE
                        AND dwtm.material_id = p_material_id
                        AND dwtm.type_material_id IN (SELECT UNNEST(ids) FROM type_material_ids)
                        AND mdbq.type_text_id IS NOT NULL
                    ORDER BY
                        dwtm.week ASC,
                        dwtm.type_material_id ASC,
                        mdbq.absolute_position ASC;
                END;
                $$;


ALTER FUNCTION odiseo.fn_get_missing_questions_text_search(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) OWNER TO postgres;

--
-- Name: fn_get_missing_questions_to_regenerate(date, text[]); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_missing_questions_to_regenerate(p_since_date date, p_excluded_statuses text[]) RETURNS TABLE(question_id bigint, question_status character varying)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            SELECT
 	            q.id AS question_id,
 	            q.status AS question_status
            FROM odiseo.question q
            LEFT JOIN odiseo.employee_question eq ON q.id = eq.question_id AND eq.fl_status IS TRUE
            LEFT JOIN odiseo.employee_didi_question ed ON q.id = ed.question_id AND ed.fl_status IS TRUE
            WHERE 1 = 1
              AND q.status NOT IN (SELECT UNNEST(p_excluded_statuses))
              AND q.fl_status IS TRUE
              AND (
                    CASE
                        WHEN
                            q.status IN ('SASI', 'ASIG', 'DUPL', 'RESO')
                            AND (
                                q.url_pdf_updated_at IS NULL OR
                                q.url_pdf_updated_at::DATE < p_since_date
                            )
                            THEN TRUE
                        WHEN
                            q.status IN ('INDE', 'RECH', 'DASI')
                            AND (
                                q.url_pdf_updated_at IS NULL OR
                                eq.url_pdf_question_solution_updated_at IS NULL OR
                                q.url_pdf_updated_at::DATE < p_since_date OR
                                eq.url_pdf_question_solution_updated_at::DATE < p_since_date
                            )
                            THEN TRUE
                        WHEN
                            q.status IN ('DIGI', 'OBSE')
                            AND (
                                q.url_pdf_updated_at IS NULL OR
                                eq.url_pdf_question_solution_updated_at IS NULL OR
                                ed.url_file_digitalized_solution_updated_at IS NULL OR
                                q.url_pdf_updated_at::DATE < p_since_date OR
                                eq.url_pdf_question_solution_updated_at::DATE < p_since_date OR
                                ed.url_file_digitalized_solution_updated_at::DATE < p_since_date
                            ) THEN TRUE
                        WHEN
                            q.status IN ('VERI', 'PEND', 'RESV')
                            AND (
                                ed.url_file_digitalized_solution_updated_at IS NULL OR
                                ed.url_file_digitalized_solution_updated_at::DATE < p_since_date
                            )
                            THEN TRUE
                        ELSE FALSE
                    END
                )
            ORDER BY
                CASE
                    WHEN q.status IN ('DIGI', 'OBSE') THEN 0
                    WHEN q.status IN ('VERI', 'PEND', 'RESV') THEN 1
                    ELSE 2
                END
            LIMIT 1;
        END; $$;


ALTER FUNCTION odiseo.fn_get_missing_questions_to_regenerate(p_since_date date, p_excluded_statuses text[]) OWNER TO postgres;

--
-- Name: fn_get_missing_text_with_subquestions(integer, integer, integer[]); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_missing_text_with_subquestions(p_material_id integer, p_week integer, p_type_material_ids integer[]) RETURNS TABLE(material character varying, course character varying, category character varying, subcategory character varying, level character varying, topic character varying, subtopic character varying, distribution_id bigint)
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                        RETURN QUERY
                        SELECT 
                            tm.description AS material,
                            c.name AS course,
                            tt.name AS category,
                            tts.name AS subcategory,
                            l.name AS level,
                            t.name AS topic,
                            st.name AS subtopic,
                            mdbq.id AS distribution_id
                        FROM 
                            material_ballot_question mdbq
                        JOIN material_ballot_subquestions mbs ON mbs.material_ballot_question_id = mdbq.id AND mbs.fl_status = TRUE
                        JOIN type_text tt ON tt.id = mdbq.type_text_id 
                        JOIN type_text_subcategories tts ON tts.id = mdbq.type_text_subcategory_id
                        JOIN "level" l ON l.id = mdbq.level_id
                        JOIN course c ON c.id = mdbq.course_id
                        JOIN type_material tm ON tm.id = mdbq.type_material_id 
                        JOIN topic t ON t.id = mbs.topic_id
                        JOIN subtopic st ON st.id = mbs.subtopic_id
                        WHERE 
                            mdbq.material_id = p_material_id
                            AND mdbq.week = p_week
                            AND mdbq.type_material_id = ANY(p_type_material_ids)
                            AND mdbq.fl_status = TRUE
                            AND mdbq.type_text_id IS NOT NULL
                            AND mbs.state = 'MISSING';

                    END;
                $$;


ALTER FUNCTION odiseo.fn_get_missing_text_with_subquestions(p_material_id integer, p_week integer, p_type_material_ids integer[]) OWNER TO postgres;

--
-- Name: fn_get_nq_courses_by_user_uuid(uuid); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_nq_courses_by_user_uuid(p_uuid uuid) RETURNS TABLE(username character varying, email character varying, first_name character varying, last_name character varying, courses jsonb, role_id bigint, role_name character varying)
    LANGUAGE plpgsql
    AS $$
    DECLARE C_SUPER_ADMIN SMALLINT DEFAULT 1;
    DECLARE C_ADMIN SMALLINT DEFAULT 2;
            
    BEGIN
        RETURN QUERY
        WITH nq_courses AS (
            SELECT
                c.id,
                c.code,
                c.name,
                c.alias_nq
            FROM odiseo.course c
            WHERE 1 = 1
              AND c.fl_status IS TRUE
              AND c.deleted_at IS NULL
              AND c.alias_nq IS NOT NULL
        ) SELECT
            u.user::CHARACTER VARYING username,
            u.email::CHARACTER VARYING email,
            CASE
                WHEN u.id IN (C_SUPER_ADMIN, C_ADMIN) THEN 'admin'::CHARACTER VARYING
                ELSE  COALESCE(e.first_surname, 'admin')::CHARACTER VARYING
            END AS first_name,
            CASE
                WHEN u.id IN (C_SUPER_ADMIN, C_ADMIN) THEN 'admin'::CHARACTER VARYING
                ELSE CONCAT(e.first_surname, ' ', e.second_surname)::CHARACTER VARYING
            END AS last_name,
            COALESCE(
                JSONB_AGG(
                    JSONB_BUILD_OBJECT(
                        'course_id', nc.id,
                        'course_code', nc.code,
                        'course_name', nc.name,
                        'alias_nq', nc.alias_nq
                    )
                    ORDER BY nc.alias_nq
                ) FILTER (WHERE nc.id IS NOT NULL),
                '[]'::JSONB
            ) AS courses,
            r.id AS role_id,
            r.name::CHARACTER VARYING AS role_name
        FROM odiseo.users u
        LEFT JOIN odiseo.employees e ON u.id = e.user_id
        LEFT JOIN odiseo.users_roles ur ON ur.user_id = e.user_id
        LEFT JOIN odiseo.roles r ON r.id = ur.rol_id
        LEFT JOIN odiseo.employee_course ec ON ec.teacher_id = e.id AND ec.deleted_at IS NULL AND ec.fl_status IS TRUE
        LEFT JOIN nq_courses nc ON ( nc.id = ec.course_id OR u.id IN (C_SUPER_ADMIN, C_ADMIN)) AND nc.alias_nq IS NOT NULL
        WHERE u.uuid = p_uuid
        GROUP BY e.id, u.id, r.id;
    END;
    $$;


ALTER FUNCTION odiseo.fn_get_nq_courses_by_user_uuid(p_uuid uuid) OWNER TO postgres;

--
-- Name: fn_get_nq_user_token(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_nq_user_token(p_user_id bigint) RETURNS TABLE(token character varying, "user" character varying)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        SELECT
            nut.nq_token,
            nut.nq_user
        FROM nq_user_token nut
        WHERE 1 = 1
          AND nut.user_id = p_user_id
          AND nut.deleted_at IS NULL
        ORDER BY nut.created_at DESC
        LIMIT 1;
    END;
    $$;


ALTER FUNCTION odiseo.fn_get_nq_user_token(p_user_id bigint) OWNER TO postgres;

--
-- Name: fn_get_parent_question_avalilable_to_add(integer, integer, character varying, smallint, integer[], integer[], smallint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_parent_question_avalilable_to_add(p_perpage integer, p_npage integer, p_search character varying, p_course_id smallint, p_category_id integer[], p_subcategory_id integer[], p_level_id smallint, p_material_id bigint, p_distribution_id bigint) RETURNS TABLE(code character varying, subquestion jsonb, id bigint, category_id bigint, category character varying, subcategory_id bigint, subcategory character varying, level_id bigint, level smallint, course_id smallint, course text, history jsonb, expected_subquestion jsonb, type_question text, total_count bigint)
    LANGUAGE plpgsql
    AS $$
                        DECLARE
                            offset_val INTEGER;
                        BEGIN
                            offset_val := p_perpage * (p_npage - 1);
                            
                            RETURN QUERY
                            WITH 
                            base_data_cte AS (
                                SELECT 
                                    fpqvm.code, fpqvm.subquestion, fpqvm.parent_id AS id, fpqvm.category_id, fpqvm.category,
                                    fpqvm.subcategory_id, fpqvm.subcategory, fpqvm.level_id, l.name::SMALLINT AS level,
                                    fpqvm.course_id, CONCAT(c.code, '-', c.name) AS course, fpqvm.history,
                                    COALESCE(
                                        (SELECT JSONB_AGG(
                                            JSONB_BUILD_OBJECT(
                                                'question_id', mbs.question_id,
                                                'topic_id', mbs.topic_id,
                                                'course_id', mbs.course_id,
                                                'subtopic_id', mbs.subtopic_id
                                            ) ORDER BY mbs.position ASC
                                        ) FROM material_ballot_subquestions mbs
                                        WHERE mbs.material_ballot_question_id = p_distribution_id AND mbs.fl_status = TRUE),
                                        '[]'::jsonb
                                    ) AS expected_subquestion
                                FROM fn_parent_question_verified_material(p_material_id, 'T') fpqvm
                                JOIN course c ON fpqvm.course_id = c.id
                                JOIN level l ON l.id = fpqvm.level_id
                            ),
                            question_verified_cte AS (
                                SELECT *
                                FROM base_data_cte AS bdc
                                WHERE 
                                    (p_search IS NULL OR bdc.code ILIKE '%' || p_search || '%') AND
                                    (p_course_id IS NULL OR bdc.course_id = p_course_id) AND
                                    (p_category_id IS NULL OR bdc.category_id = ANY(p_category_id)) AND
                                    (p_subcategory_id IS NULL OR bdc.subcategory_id = ANY(p_subcategory_id)) AND
                                    (p_level_id IS NULL OR bdc.level_id = p_level_id)
                                    AND EXISTS (
                                        SELECT 1 FROM jsonb_array_elements(bdc.expected_subquestion) AS expected(item)
                                        WHERE EXISTS (
                                            SELECT 1 FROM jsonb_array_elements(bdc.subquestion) AS available(item)
                                            WHERE (expected.item ->> 'topic_id')::INTEGER = (available.item ->> 'topic_id')::INTEGER
                                            AND (expected.item ->> 'course_id')::INTEGER = (available.item ->> 'course_id')::INTEGER
                                            AND EXISTS (
                                                SELECT 1 FROM jsonb_array_elements(available.item -> 'subtopics') AS sub(item)
                                                WHERE (sub.item ->> 'id')::INTEGER = (expected.item ->> 'subtopic_id')::INTEGER
                                            )
                                        )
                                    )
                            ),
                            question_with_subquestion AS (
                                SELECT 
                                    qvc.id, qvc.code, qvc.category_id, qvc.category, qvc.subcategory_id, qvc.subcategory, qvc.level_id, qvc.level, qvc.course_id, qvc.course, qvc.history,
                                    ( SELECT jsonb_agg( sq.item || jsonb_build_object( 'topic', COALESCE(t.name, '-'), 'level', COALESCE(l.name, '-') ) )
                                        FROM jsonb_array_elements(qvc.subquestion) AS sq(item)
                                        LEFT JOIN topic t ON (sq.item ->> 'topic_id')::INTEGER = t.id
                                        LEFT JOIN level l ON (sq.item ->> 'level_id')::INTEGER = l.id
                                    ) AS subquestion,
                                    ( SELECT jsonb_agg( sq.item || jsonb_build_object('topic', COALESCE(t.name, '-'), 'level', COALESCE(l.name, '-'), 'subtopic', COALESCE(s.name, '-')) )
                                        FROM jsonb_array_elements(qvc.expected_subquestion) AS sq(item)
                                        LEFT JOIN topic t ON (sq.item ->> 'topic_id')::INTEGER = t.id
                                        LEFT JOIN level l ON (sq.item ->> 'level_id')::INTEGER = l.id
                                        LEFT JOIN subtopic s ON (sq.item ->> 'subtopic_id')::INTEGER = s.id
                                    ) AS expected_subquestion,
                                    'T' AS type_question
                                FROM question_verified_cte qvc
                            ),
                            counted_questions AS (
                                SELECT *, COUNT(*) OVER () as total_count
                                FROM question_with_subquestion
                            )
                            SELECT
                                cq.code, cq.subquestion, cq.id, cq.category_id, cq.category, cq.subcategory_id, cq.subcategory,
                                cq.level_id, cq.level, cq.course_id, cq.course, cq.history, cq.expected_subquestion,
                                cq.type_question, cq.total_count
                            FROM counted_questions cq
                            ORDER BY cq.id, cq.code
                            LIMIT p_perpage
                            OFFSET offset_val;
                        END;
                        $$;


ALTER FUNCTION odiseo.fn_get_parent_question_avalilable_to_add(p_perpage integer, p_npage integer, p_search character varying, p_course_id smallint, p_category_id integer[], p_subcategory_id integer[], p_level_id smallint, p_material_id bigint, p_distribution_id bigint) OWNER TO postgres;

--
-- Name: fn_get_parent_questions_missing_ballot(bigint, smallint, smallint, smallint, boolean, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_parent_questions_missing_ballot(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint, p_has_permission_filter_per_course boolean, p_employee_id integer) RETURNS TABLE(subquestion jsonb, parent_id bigint, category_id bigint, category character varying, subcategory_id bigint, subcategory character varying, level_id bigint, course_id smallint, history jsonb, code character varying, registered boolean)
    LANGUAGE plpgsql
    AS $$
                DECLARE
                    v_ids_children INT[];
                    v_course_ids INT[];
                BEGIN
                    /*
                        ------------------------------------------------------------------------------------
                        -- HISTORIAL DE CAMBIOS
                        ------------------------------------------------------------------------------------
                        Versión: 1.1
                        Fecha: 2025-11-28
                        Autor: Junior Alcarraz
                        Descripción:
                            Trae preguntas texto de la distribucion de un rango por periodo
                            Se modifica para que traiga preguntas que esten registradas
                    */

                    -- Obtener todos los IDs de los hijos en un array
                    SELECT CASE
                        WHEN EXISTS (SELECT 1 FROM type_material tm WHERE tm.parent_id = p_type_material_id)
                        THEN ARRAY(SELECT tm.id FROM type_material tm WHERE tm.parent_id = p_type_material_id)
                        ELSE ARRAY[p_type_material_id]
                    END INTO v_ids_children;

                    IF p_has_permission_filter_per_course THEN
                        SELECT array_agg(DISTINCT ec.course_id) INTO v_course_ids
                        FROM employee_course ec
                        WHERE ec.teacher_id = p_employee_id
                        AND ec.deleted_by IS NULL
                        AND ec.fl_status = true;
                    END IF;

                    RETURN QUERY
                    WITH get_type_materias AS ( -- Se trae el id de tipo material hijo si los tiene, sino se manda el normal
                        SELECT unnest(v_ids_children) AS type_material_id
                    ), get_config_syllabus AS ( -- Se trae la configuración de sílabos
                        SELECT
                            DISTINCT
                            csrb.category_id,
                            csrb.subcategory_id,
                            csrb.course_id
                        FROM fn_get_config_text_syllabus_complete_ballot_period(
                            p_material_id,
                            p_type_material_id,
                            p_start_week,
                            p_end_week
                        ) csrb
                    ), get_config_level AS ( -- Se trae la configuración de niveles
                        SELECT
                            DISTINCT
                            clrb.level_id,
                            clrb.course_id
                        FROM fn_get_config_text_level_complete_ballot_period(
                            p_material_id,
                            p_type_material_id,
                            p_start_week,
                            p_end_week
                        ) clrb
                    ), get_courses_missing_ballot AS (
                        SELECT DISTINCT
                            mdbq.course_id,
                            mdbq.type_text_id AS category_id,
                            mdbq.type_text_subcategory_id AS subcategory_id,
                            mdbq.level_id
                        FROM detail_week_type_mat dwtm
                        JOIN material_ballot_question mdbq ON dwtm.id = mdbq.week_type_material_id
                        WHERE mdbq.material_id = p_material_id
                            AND dwtm.week BETWEEN p_start_week AND p_end_week
                            AND dwtm.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
                            AND mdbq.fl_status = true
                            AND mdbq.parent_question_id IS NULL
                            AND mdbq.type_text_id IS NOT NULL
                            AND (NOT p_has_permission_filter_per_course OR mdbq.course_id = ANY(v_course_ids))
                    ), get_subcategories_search AS (
                        SELECT
                            gcs.course_id,
                            gcs.category_id,
                            gcs.subcategory_id
                        FROM get_config_syllabus gcs
                        UNION ALL
                        SELECT DISTINCT
                            gcmb.course_id,
                            gcmb.category_id,
                            gcmb.subcategory_id
                        FROM get_courses_missing_ballot gcmb
                    ), get_levels_search AS (
                        SELECT
                            gcl.course_id,
                            gcl.level_id
                        FROM get_config_level gcl
                        UNION ALL
                        SELECT DISTINCT
                            gcmb.course_id,
                            gcmb.level_id
                        FROM get_courses_missing_ballot gcmb
                    ), limit_config_level AS ( -- Obtener los intervalos de niveles
                        SELECT
                            mppb.lower_level_limit,
                            mppb.upper_level_limit
                        FROM material_per_period mpp
                        INNER JOIN material_per_period_ballot mppb ON mpp.id = mppb.material_per_period_id
                            AND mppb.deleted_by IS NULL
                        WHERE mpp.material_id = p_material_id
                            AND mpp.type_material_id = p_type_material_id
                            AND mppb.start_week = p_start_week
                            AND mppb.end_week = p_end_week
                    ), course_ranges_by_level AS (
                        SELECT
                            gls.course_id,
                            MIN(gls.level_id) as min_existing_level,
                            MAX(gls.level_id) as max_existing_level
                        FROM get_levels_search gls
                        GROUP BY gls.course_id
                    ), get_config_level_with_range AS (
                        SELECT
                            cr.course_id,
                            generate_series(
                                cr.min_existing_level - lcl.lower_level_limit,
                                cr.max_existing_level + lcl.upper_level_limit
                            ) AS level_id
                        FROM
                            course_ranges_by_level cr,
                            limit_config_level lcl
                        ORDER BY
                            cr.course_id,
                            level_id
                    ), subtopics_agg AS (
                        SELECT
                            qs.question_id,
                            JSONB_AGG(JSONB_BUILD_OBJECT('id', qs.subtopic_id)) AS subtopics_json
                        FROM question_subtopic qs
                        WHERE qs.fl_status = true
                        GROUP BY qs.question_id
                    ), get_questions_text_search AS (-- Se obtienen los textos filtrados segun las configuraciones
                        SELECT
                            fpqvm.subquestion,
                            fpqvm.parent_id,
                            fpqvm.category_id,
                            fpqvm.category,
                            fpqvm.subcategory_id,
                            fpqvm.subcategory,
                            fpqvm.level_id,
                            fpqvm.course_id,
                            fpqvm.history,
                            fpqvm.code,
                            FALSE AS registered
                        FROM fn_parent_question_verified_material(p_material_id, 'T') fpqvm
                        JOIN get_subcategories_search gss ON gss.course_id = fpqvm.course_id
                            AND gss.category_id = fpqvm.category_id
                            AND gss.subcategory_id = fpqvm.subcategory_id
                        JOIN get_config_level_with_range gclwr ON gclwr.course_id = fpqvm.course_id
                        AND gclwr.level_id = fpqvm.level_id
                    ), get_questions_register AS (
                        SELECT
                            JSONB_AGG(
                                JSONB_BUILD_OBJECT(
                                    'code', q.code,
                                    'question_id', q.id,
                                    'topic_id', q.topic_id,
                                    'course_id', q.course_id,
                                    'level_id', q.level_id,
                                    'subtopics', COALESCE(sa.subtopics_json, '[]'::jsonb)
                                )
                            ) AS subquestion,
                            mdbq.parent_question_id::BIGINT,
                            mdbq.type_text_id AS category_id,
                            tt.name AS category,
                            mdbq.type_text_subcategory_id AS subcategory_id,
                            tts.name AS subcategory,
                            mdbq.level_id,
                            mdbq.course_id,
                            '[]'::JSONB AS history,
                            pq.code,
                            TRUE AS registered
                        FROM material_ballot_question mdbq
                        JOIN question q ON q.parent_id = mdbq.parent_question_id
                        JOIN parent_question pq ON pq.id = mdbq.parent_question_id
                        JOIN detail_week_type_mat dwtm ON mdbq.week_type_material_id = dwtm.id
                        JOIN type_text tt ON mdbq.type_text_id = tt.id
                        JOIN type_text_subcategories tts ON mdbq.type_text_subcategory_id = tts.id
                        JOIN level l ON mdbq.level_id = l.id
                        LEFT JOIN subtopics_agg sa ON q.id = sa.question_id
                        WHERE 1 = 1
                            AND dwtm.fl_status IS TRUE
                            AND mdbq.fl_status IS TRUE
                            AND dwtm.material_id = p_material_id
                            AND dwtm.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
                            AND mdbq.parent_question_id IS NOT NULL
                            AND mdbq.type_text_id IS NOT NULL
                        GROUP BY
                            mdbq.parent_question_id,
                            pq.code,
                            mdbq.type_text_id,
                            tt.name,
                            mdbq.type_text_subcategory_id,
                            tts.name,
                            mdbq.level_id,
                            mdbq.course_id
                    )
                    SELECT * FROM get_questions_text_search
                    UNION ALL
                    SELECT * FROM get_questions_register;
                END;
                $$;


ALTER FUNCTION odiseo.fn_get_parent_questions_missing_ballot(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint, p_has_permission_filter_per_course boolean, p_employee_id integer) OWNER TO postgres;

--
-- Name: fn_get_parent_questions_register_ballot(bigint, smallint, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_parent_questions_register_ballot(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) RETURNS TABLE(subquestion jsonb, parent_id bigint, category_id bigint, category character varying, subcategory_id bigint, subcategory character varying, level_id bigint, course_id smallint, history jsonb, code character varying)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                    WITH get_config_syllabus AS ( -- Se trae la configuración de sílabos
                        SELECT
                            DISTINCT
                            csrb.category_id,
                            csrb.subcategory_id,
                            csrb.course_id
                        FROM fn_get_config_text_syllabus_register_ballot_period(
                            p_material_id,
                            p_type_material_id,
                            p_start_week,
                            p_end_week
                        ) csrb
                    ),
                    get_config_level AS ( -- Se trae la configuración de niveles
                        SELECT
                            DISTINCT
                            clrb.level_id,
                            clrb.course_id
                        FROM fn_get_config_text_level_register_ballot_period(
                            p_material_id,
                            p_type_material_id,
                            p_start_week,
                            p_end_week
                        ) clrb
                    ), limit_config_level AS ( -- Obtener los intervalos de niveles
                        SELECT 
                            dwtm.limit_lower_question,
                            dwtm.limit_upper_question 
                        FROM detail_week_type_mat dwtm
                        JOIN type_material tm on tm.id = dwtm.type_material_id 
                        WHERE dwtm.material_id = p_material_id
                        AND (tm.parent_id = p_type_material_id OR tm.id = p_type_material_id)
                        AND dwtm.fl_status = TRUE
                        AND dwtm.week BETWEEN p_start_week AND p_end_week
                        ORDER BY dwtm.id
                        LIMIT 1
                    ), course_ranges_by_level AS (
                        SELECT 
                            gcl.course_id,
                            MIN(gcl.level_id) as min_existing_level,
                            MAX(gcl.level_id) as max_existing_level
                        FROM get_config_level gcl
                        GROUP BY gcl.course_id
                    ), get_config_level_with_range AS (
                        SELECT
                            cr.course_id,
                            generate_series(
                                cr.min_existing_level - lcl.limit_lower_question,
                                cr.max_existing_level + lcl.limit_upper_question
                            ) AS level_id
                        FROM
                            course_ranges_by_level cr,
                            limit_config_level lcl
                        ORDER BY
                            cr.course_id,
                            level_id
                    )
                    SELECT -- Se obtienen los textos filtrados segun las configuraciones
                        fpqvm.subquestion,
                        fpqvm.parent_id,
                        fpqvm.category_id,
                        fpqvm.category,
                        fpqvm.subcategory_id,
                        fpqvm.subcategory,
                        fpqvm.level_id,
                        fpqvm.course_id,
                        fpqvm.history,
                        fpqvm.code
                    FROM fn_parent_question_verified_material(p_material_id, 'T') fpqvm
                    JOIN get_config_syllabus gcs ON
                        gcs.course_id = fpqvm.course_id AND
                        gcs.category_id = fpqvm.category_id AND
                        gcs.subcategory_id = fpqvm.subcategory_id
                    JOIN get_config_level_with_range gclwr ON
                        gclwr.course_id = fpqvm.course_id AND
                        gclwr.level_id = fpqvm.level_id;
            END;
        $$;


ALTER FUNCTION odiseo.fn_get_parent_questions_register_ballot(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) OWNER TO postgres;

--
-- Name: fn_get_parent_type_material(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_parent_type_material(p_type_material_id bigint, p_material_id bigint) RETURNS TABLE(material_ids json)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_cycle_id BIGINT;
        BEGIN
            SELECT
                m.cycle_id INTO v_cycle_id
            FROM material m
            WHERE m.id = p_material_id
            LIMIT 1;

            RETURN QUERY
            WITH find_type_material_template_id AS (
                SELECT
                type_material_template_id
                FROM type_material
                WHERE id = p_type_material_id
            ), parent_type_material_ids AS (
                SELECT 
                    DISTINCT tm.id AS t_material_ids
                FROM type_material_bound tmb
                INNER JOIN type_material tm
                    ON tmb.type_material_template_id = tm.type_material_template_id
                WHERE 1 = 1
                    AND tmb.type_material_template_extra_id = (SELECT * FROM find_type_material_template_id)
                    AND tmb.fl_status = true
                    AND tm.cycle_id = v_cycle_id
            ), tbl_type_material AS (
				SELECT
                	COALESCE(t_material_ids, p_type_material_id) AS type_material_id
            	FROM parent_type_material_ids
			)
            SELECT *
			FROM fn_get_children_material_type_ids(
			    (SELECT type_material_id FROM tbl_type_material LIMIT 1),
			    v_cycle_id
			);
        END;
        $$;


ALTER FUNCTION odiseo.fn_get_parent_type_material(p_type_material_id bigint, p_material_id bigint) OWNER TO postgres;

--
-- Name: fn_get_periods_weeks_on_type_material(bigint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_periods_weeks_on_type_material(p_type_material_id bigint, p_week smallint) RETURNS TABLE(starting_week smallint, ending_week smallint, period_number smallint)
    LANGUAGE plpgsql
    AS $$
    DECLARE C_DEFAULT_STARTING_WEEK SMALLINT DEFAULT 1;
    BEGIN
        RETURN QUERY
        WITH get_periods_of_weeks AS (
            SELECT
                *
            FROM type_material_detail_template
            WHERE 1 = 1
              AND type_material_id = p_type_material_id
              AND fl_status IS TRUE
            ORDER BY week ASC
        ), periods AS (
            SELECT
                COALESCE(LAG(per.week) OVER (ORDER BY per.week), 0) + 1 AS starting_week,
                per.week AS ending_week
            FROM get_periods_of_weeks per
            WHERE 1 = 1
              AND per.week <= p_week
        ), get_current_period AS (
            SELECT
                ps.starting_week AS starting_week,
                ps.ending_week AS ending_week
            FROM periods ps
            ORDER BY
                ps.starting_week DESC
            LIMIT 1
        ), set_review_period AS (
            SELECT
                C_DEFAULT_STARTING_WEEK AS starting_week,
                CASE
                    WHEN ( SELECT COUNT(*) FROM periods ) > 1 THEN ( SELECT gp.starting_week - 1 FROM get_current_period gp )
                    ELSE p_week
                END AS ending_week
        ), join_periods AS (
            SELECT * FROM get_current_period 
            UNION
            SELECT * FROM set_review_period
        ), assign_period_number AS (
            SELECT
                ar.starting_week::SMALLINT,
                ar.ending_week::SMALLINT,
                (ROW_NUMBER() OVER (ORDER BY ar.ending_week DESC))::SMALLINT AS period_number
            FROM join_periods AS ar 
        ) SELECT * FROM assign_period_number;
    END;
$$;


ALTER FUNCTION odiseo.fn_get_periods_weeks_on_type_material(p_type_material_id bigint, p_week smallint) OWNER TO postgres;

--
-- Name: fn_get_question_all_maths(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_question_all_maths(p_question_id bigint) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
            DECLARE
                result jsonb;
            BEGIN
                SELECT jsonb_agg(obj)
                INTO result
                FROM (
                    -- formulas de alternative_maths
                    SELECT jsonb_build_object(
                            'id', am.id,
                            'path', am.path,
                            'properties', am.properties
                        ) AS obj
                    FROM alternative_maths am
                    JOIN alternative a ON a.id = am.alternative_id
                    WHERE a.question_id = p_question_id
                    AND am.fl_status = true

                    UNION ALL

                    -- formulas de didi_maths
                    SELECT jsonb_build_object(
                            'id', dm.id,
                            'path', dm.path,
                            'properties', dm.properties
                        ) AS obj
                    FROM didi_maths dm
                    JOIN employee_didi_question_field edqf ON edqf.id = dm.didi_question_id AND edqf.math_migration_status NOT IN ('TO_BE_MIGRATED', 'MIGRATING')
                    JOIN employee_didi_question edq ON edq.id = edqf.employee_didi_question_id
                    WHERE edq.question_id = p_question_id
                    AND dm.fl_status = true

                    UNION ALL

                    -- formulas de question_maths
                    SELECT jsonb_build_object(
                            'id', qm.id,
                            'path', qm.path,
                            'properties', qm.properties
                        ) AS obj
                    FROM question_maths qm
                    WHERE qm.question_id = p_question_id
                    AND qm.fl_status = true
                ) t;

                RETURN COALESCE(result, '[]'::jsonb);
            END;
        $$;


ALTER FUNCTION odiseo.fn_get_question_all_maths(p_question_id bigint) OWNER TO postgres;

--
-- Name: fn_get_question_by_subtopic(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_question_by_subtopic(p_subtopic_id bigint) RETURNS TABLE(id bigint, subtopics jsonb)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_question_ids BIGINT[] := '{}'; -- Inicializar como un arreglo vacío
        BEGIN
            -- Obtener IDs de las preguntas asociadas al subtema
            SELECT ARRAY (
                SELECT qs.question_id
                FROM question_subtopic qs
                WHERE qs.subtopic_id = p_subtopic_id AND qs.fl_status = TRUE
            ) INTO v_question_ids;

            -- Manejar el caso donde no haya resultados
            IF v_question_ids IS NULL OR cardinality(v_question_ids) = 0 THEN
                RETURN QUERY SELECT NULL::BIGINT, '[]'::JSONB; -- Especificar el tipo explícitamente
                RETURN;
            END IF;

            -- Retornar las preguntas y sus subtemas en formato JSONB
            RETURN QUERY
            SELECT
                q.id,
                jsonb_agg(
                    jsonb_build_object(
                        'id', s.id,
                        'code', s.code,
                        'name', s.name
                    )
                ) AS subtopics
            FROM
                question q
            LEFT JOIN question_subtopic qs
                ON q.id = qs.question_id
            LEFT JOIN subtopic s
                ON qs.subtopic_id = s.id
            WHERE
                q.id = ANY (v_question_ids)
            AND
				qs.fl_status = true
            GROUP BY
                q.id;
            END;
        $$;


ALTER FUNCTION odiseo.fn_get_question_by_subtopic(p_subtopic_id bigint) OWNER TO postgres;

--
-- Name: fn_get_question_id_simple(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_question_id_simple(p_id bigint) RETURNS TABLE(id bigint, code character varying, description text, short_description text, parent_id bigint, status character varying, course_id smallint, area_id bigint, url_pdf character varying, type_question text, type_text_template_id smallint, text_attributes character varying, subquestion_attributes character varying, shared_status text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        q.id,
        q.code,
        q.description,
        q.short_description,
        q.parent_id,
        q.status,
        q.course_id,
        c.area_id,
        q.url_pdf,
        CASE
            WHEN q.parent_id IS NOT NULL THEN 'S'
            ELSE 'P'
        END AS type_question,
        c.type_text_template_id,
        ttt.text_attributes,
        ttt.subquestion_attributes,
        get_shared_status(q.id, qs.subtopic_id) AS shared_status
    FROM question q
    LEFT JOIN course c ON q.course_id = c.id
    LEFT JOIN type_text_templates ttt ON c.type_text_template_id = ttt.id
    LEFT JOIN question_subtopic qs ON qs.question_id = q.id
    WHERE q.id = p_id
      AND q.fl_status = TRUE;
END;
$$;


ALTER FUNCTION odiseo.fn_get_question_id_simple(p_id bigint) OWNER TO postgres;

--
-- Name: fn_get_question_urls(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_question_urls(p_question_id bigint) RETURNS TABLE(id bigint, url_pdf character varying, employee_question_didi bigint, url_pdf_question_solution character varying, employee_didi_question_didi bigint, url_file character varying, url_file_digitalized_solution character varying, status character varying)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            SELECT
                q.id,
                q.url_pdf,
                eq.id AS employee_question_id,
                eq.url_pdf_question_solution,
                ed.id AS employee_didi_question_id,
                ed.url_file,
                ed.url_file_digitalized_solution,
                q.status
            FROM odiseo.question q
            LEFT JOIN odiseo.employee_question eq ON q.id = eq.question_id AND eq.fl_status = true
            LEFT JOIN odiseo.employee_didi_question ed ON q.id = ed.question_id AND ed.fl_status = true
            WHERE q.id = p_question_id;
        END;
        $$;


ALTER FUNCTION odiseo.fn_get_question_urls(p_question_id bigint) OWNER TO postgres;

--
-- Name: fn_get_question_usage_stats(smallint, bigint, smallint, smallint, bigint, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_question_usage_stats(p_type_material_id smallint, p_material_id bigint, p_start_week smallint, p_end_week smallint, p_user_id bigint, p_force_regenerate boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_result JSONB;
                v_ballot_id BIGINT;
                v_global_stats_id BIGINT;
                v_area_stats_id BIGINT;
                v_area_json JSONB;
            BEGIN
                -- =================================================================================
                -- PASO 0: Obtener dinámicamente el material_per_period_ballot_id
                -- =================================================================================
                SELECT b.id INTO v_ballot_id
                FROM material_per_period mp
                JOIN material_per_period_ballot b ON b.material_per_period_id = mp.id
                WHERE mp.material_id = p_material_id
                  AND mp.type_material_id = p_type_material_id
                  AND b.start_week = p_start_week
                  AND b.end_week = p_end_week
                  AND mp.deleted_at IS NULL
                  AND b.deleted_at IS NULL
                LIMIT 1;

                IF v_ballot_id IS NULL THEN
                    RETURN '[]'::jsonb;
                END IF;

                -- =================================================================================
                -- PASO 1: Verificar si ya existe data guardada
                -- =================================================================================
                SELECT id INTO v_global_stats_id
                FROM material_ballot_stats_global
                WHERE material_per_period_ballot_id = v_ballot_id
                LIMIT 1;

                -- =================================================================================
                -- PASO 2: Lógica de Regeneración (Borrar padre borra hijos por CASCADE)
                -- =================================================================================
                IF v_global_stats_id IS NOT NULL AND p_force_regenerate IS TRUE THEN
                    DELETE FROM material_ballot_stats_global WHERE id = v_global_stats_id;
                    v_global_stats_id := NULL;
                END IF;

                -- =================================================================================
                -- PASO 3: Si existe Data, retornar estructura JSON desde las tablas
                -- =================================================================================
                IF v_global_stats_id IS NOT NULL THEN
                    SELECT jsonb_build_object(
                        'number_pages', g.number_pages,
                        'total_questions', g.total_questions,
                        'new_questions', g.new_questions,
                        'repeated_year', g.repeated_year,
                        'repeated_history', g.repeated_history,
                        'details', COALESCE((
                            SELECT jsonb_agg(
                                jsonb_build_object(
                                    'name', a.area_name,
                                    'total_questions', a.total_questions,
                                    'new_questions', a.new_questions,
                                    'repeated_year', a.repeated_year,
                                    'repeated_history', a.repeated_history,
                                    'details', COALESCE((
                                        SELECT jsonb_agg(
                                            jsonb_build_object(
                                                'name', c.course_name,
                                                'total_questions', c.total_questions,
                                                'new_questions', c.new_questions,
                                                'repeated_year', c.repeated_year,
                                                'repeated_history', c.repeated_history
                                            ) ORDER BY c.course_name ASC
                                        )
                                        FROM material_ballot_stats_area_courses c
                                        WHERE c.area_stats_id = a.id
                                    ), '[]'::jsonb)
                                ) ORDER BY a.area_name ASC
                            )
                            FROM material_ballot_stats_areas a
                            WHERE a.global_stats_id = g.id
                        ), '[]'::jsonb)
                    ) INTO v_result
                    FROM material_ballot_stats_global g
                    WHERE g.id = v_global_stats_id;

                    RETURN v_result;
                END IF;

                -- =================================================================================
                -- PASO 4: CALCULAR (Si no existe data guardada - Lógica Original)
                -- =================================================================================

                WITH prepare_type_material_ids AS (
                    SELECT
                    CASE WHEN EXISTS (
                        SELECT 1 FROM type_material tm
                        WHERE tm.parent_id = p_type_material_id) THEN
                        ARRAY (
                            SELECT tm.id FROM type_material tm WHERE tm.parent_id = p_type_material_id
                        )
                    ELSE
                        ARRAY[p_type_material_id]
                    END AS ids
                ), type_material_ids AS (
                    SELECT UNNEST(ids) AS id FROM prepare_type_material_ids
                ), material_details AS (
                    SELECT cycle_id, university_id, company_id
                    FROM material
                    WHERE id = p_material_id AND fl_status IS TRUE
                ),
                total_pages_calc AS (
                    SELECT COALESCE(SUM(mppbu.number_pages), 0) as pages_count
                    FROM material_per_period mpp
                    JOIN material_per_period_ballot mppb ON mppb.material_per_period_id = mpp.id
                    JOIN material_per_period_ballot_url mppbu ON mppbu.material_per_period_ballot_id = mppb.id
                    WHERE mpp.material_id = p_material_id
                    AND mpp.type_material_id = p_type_material_id
                    AND mppb.start_week >= p_start_week
                    AND mppb.end_week <= p_end_week
                    AND mppbu.type_url = 'without_solution'
                    AND mppb.deleted_at IS NULL
                    AND mpp.deleted_at IS NULL
                    AND mppbu.deleted_at IS NULL
                ),
                year_cycle_material AS (
                    SELECT year
                    FROM cycle
                    WHERE id = (SELECT cycle_id FROM material_details) AND fl_status IS TRUE
                ),
                detail_week_type_materia_ids AS (
                    SELECT dwtm.id
                    FROM detail_week_type_mat dwtm
                    WHERE dwtm.material_id = p_material_id
                    AND dwtm.type_material_id IN (SELECT tmi.id FROM type_material_ids tmi)
                    AND dwtm.week BETWEEN p_start_week AND p_end_week
                    AND dwtm.fl_status IS TRUE
                ),
                material_balot_question_data AS (
                    SELECT
                        mbq.id,
                        mbq.week_type_material_id,
                        mbq.course_id,
                        c.name AS course_name,
                        UPPER(a.description) AS area_desc,
                        COALESCE(mbq.question_id, mbs.question_id) AS question_id,
                        mbq.parent_question_id
                    FROM material_ballot_question AS mbq
                    INNER JOIN course c ON c.id = mbq.course_id
                    INNER JOIN area a ON c.area_id = a.id
                    LEFT JOIN material_ballot_subquestions mbs 
                        ON mbs.material_ballot_question_id = mbq.id AND mbs.fl_status IS TRUE
                    WHERE mbq.week_type_material_id IN (SELECT id FROM detail_week_type_materia_ids)
                    AND mbq.fl_status IS TRUE
                    AND c.fl_status IS TRUE
                    AND a.fl_status IS TRUE
                    AND (mbq.question_id IS NOT NULL OR mbs.question_id IS NOT NULL)
                ),
                questions_history_questions AS (
                    SELECT
                        mbq.question_id,
                        COUNT(qhc.id) AS total_history_count,
                        MAX(EXTRACT(YEAR FROM qhc.start_date)) AS last_seen_year
                    FROM material_balot_question_data mbq
                    LEFT JOIN (
                        SELECT
                            qhc.id,
                            c.id AS cycle_id,
                            c.description,
                            c.start_date,
                            qhc.question_id
                        FROM question_history_cycle qhc
                        JOIN cycle c ON qhc.cycle_id = c.id
                        WHERE c.company_id =(select company_id from material_details)
                            AND qhc.fl_status IS TRUE
                            AND qhc.cycle_id <> (SELECT cycle_id FROM material_details)
                            AND c.fl_status IS TRUE
                            AND EXTRACT(YEAR FROM c.start_date) <= (SELECT ycm.year FROM year_cycle_material ycm)
                    ) qhc ON mbq.question_id = qhc.question_id
                    WHERE mbq.parent_question_id IS NULL
                    GROUP BY mbq.question_id
                ),
                question_history_parent AS (
                    SELECT
                        mbq.question_id,
                        COUNT(qhc.id) AS total_history_count,
                        MAX(EXTRACT(YEAR FROM qhc.start_date)) AS last_seen_year
                    FROM material_balot_question_data mbq
                    LEFT JOIN (
                        SELECT
                            qhc.id,
                            c.id AS cycle_id,
                            c.description,
                            c.start_date,
                            qhc.question_id
                        FROM question_history_cycle qhc
                        JOIN cycle c ON qhc.cycle_id = c.id
                        WHERE c.company_id =(select company_id from material_details)
                            AND qhc.fl_status IS TRUE
                            AND qhc.cycle_id <> (SELECT cycle_id FROM material_details)
                            AND c.fl_status IS TRUE
                            AND EXTRACT(YEAR FROM c.start_date) <= (SELECT ycm.year FROM year_cycle_material ycm)
                    ) qhc ON mbq.question_id = qhc.question_id
                    WHERE mbq.parent_question_id IS NOT NULL
                    GROUP BY mbq.question_id
                ),
                questions_history_stats AS (
                    SELECT * FROM questions_history_questions
                    UNION ALL
                    SELECT * FROM question_history_parent
                ),
                classified_questions AS (
                    SELECT
                        mbq.area_desc,
                        mbq.course_name,
                        CASE
                            WHEN stats.total_history_count = 0
                                OR (ycm.year - stats.last_seen_year) > (select number_years_to_consider_question_repeated from advanced_settings LIMIT 1) THEN 'NUEVA'
                            WHEN (ycm.year - stats.last_seen_year) = 0 THEN 'REPETIDA_LECTIVO'
                            ELSE 'REPETIDA_ANTERIOR'
                        END AS status_code
                    FROM material_balot_question_data mbq
                    JOIN questions_history_stats stats ON mbq.question_id = stats.question_id
                    CROSS JOIN year_cycle_material ycm
                ),
                stats_by_course AS (
                    SELECT
                        area_desc,
                        course_name,
                        SUM(CASE WHEN status_code = 'NUEVA' THEN 1 ELSE 0 END) AS nuevas,
                        SUM(CASE WHEN status_code = 'REPETIDA_LECTIVO' THEN 1 ELSE 0 END) AS rep_lectivo,
                        SUM(CASE WHEN status_code = 'REPETIDA_ANTERIOR' THEN 1 ELSE 0 END) AS rep_anterior,
                        COUNT(*) AS total_curso
                    FROM classified_questions
                    GROUP BY area_desc, course_name
                ),
                stats_by_area AS (
                    SELECT
                        area_desc,
                        SUM(nuevas) AS area_nuevas,
                        SUM(rep_lectivo) AS area_lectivo,
                        SUM(rep_anterior) AS area_anterior,
                        SUM(total_curso) AS area_total,
                        jsonb_agg(
                            jsonb_build_object(
                                'name', course_name,
                                'total_questions', total_curso,
                                'new_questions', nuevas,
                                'repeated_year', rep_lectivo,
                                'repeated_history', rep_anterior
                            ) ORDER BY course_name ASC
                        ) AS cursos_json
                    FROM stats_by_course
                    GROUP BY area_desc
                )
                SELECT jsonb_build_object(
                    'number_pages', (SELECT pages_count FROM total_pages_calc),
                    'total_questions', COALESCE(SUM(area_total), 0),
                    'new_questions', COALESCE(SUM(area_nuevas), 0),
                    'repeated_year', COALESCE(SUM(area_lectivo), 0),
                    'repeated_history', COALESCE(SUM(area_anterior), 0),
                    'details', COALESCE(
                        jsonb_agg(
                            jsonb_build_object(
                                'name', area_desc,
                                'total_questions', area_total,
                                'new_questions', area_nuevas,
                                'repeated_year', area_lectivo,
                                'repeated_history', area_anterior,
                                'details', cursos_json
                            ) ORDER BY area_desc ASC
                        ), '[]'::jsonb
                    )
                ) INTO v_result
                FROM stats_by_area;

                -- =================================================================================
                -- PASO 5: INSERTAR EL RESULTADO CALCULADO (Persistencia)
                -- =================================================================================

                INSERT INTO material_ballot_stats_global (
                    material_per_period_ballot_id,
                    number_pages,
                    total_questions,
                    new_questions,
                    repeated_year,
                    repeated_history,
                    created_by,
                    updated_by
                ) VALUES (
                    v_ballot_id,
                    COALESCE((v_result->>'number_pages')::SMALLINT, 0),
                    COALESCE((v_result->>'total_questions')::SMALLINT, 0),
                    COALESCE((v_result->>'new_questions')::SMALLINT, 0),
                    COALESCE((v_result->>'repeated_year')::SMALLINT, 0),
                    COALESCE((v_result->>'repeated_history')::SMALLINT, 0),
                    p_user_id,
                    p_user_id
                ) RETURNING id INTO v_global_stats_id;

                FOR v_area_json IN SELECT * FROM jsonb_array_elements(v_result->'details')
                LOOP
                    INSERT INTO material_ballot_stats_areas (
                        global_stats_id,
                        area_name,
                        total_questions,
                        new_questions,
                        repeated_year,
                        repeated_history
                    ) VALUES (
                        v_global_stats_id,
                        v_area_json->>'name',
                        (v_area_json->>'total_questions')::SMALLINT,
                        (v_area_json->>'new_questions')::SMALLINT,
                        (v_area_json->>'repeated_year')::SMALLINT,
                        (v_area_json->>'repeated_history')::SMALLINT
                    ) RETURNING id INTO v_area_stats_id;

                    INSERT INTO material_ballot_stats_area_courses ( 
                        area_stats_id,
                        course_name,
                        total_questions,
                        new_questions,
                        repeated_year,
                        repeated_history
                    )
                    SELECT
                        v_area_stats_id,
                        value->>'name',
                        (value->>'total_questions')::SMALLINT,
                        (value->>'new_questions')::SMALLINT,
                        (value->>'repeated_year')::SMALLINT,
                        (value->>'repeated_history')::SMALLINT
                    FROM jsonb_array_elements(v_area_json->'details');
                END LOOP;

                RETURN v_result;
            END;
            $$;


ALTER FUNCTION odiseo.fn_get_question_usage_stats(p_type_material_id smallint, p_material_id bigint, p_start_week smallint, p_end_week smallint, p_user_id bigint, p_force_regenerate boolean) OWNER TO postgres;

--
-- Name: fn_get_questions_by_didi_status(integer, integer, integer, integer, character varying, timestamp without time zone, timestamp without time zone, character varying, character varying, character varying, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_questions_by_didi_status(p_per_page integer, p_n_page integer, p_course_id integer, p_employee_id integer, p_initial_status character varying, p_start_date timestamp without time zone, p_end_date timestamp without time zone, p_short_description character varying, p_code character varying, p_type_question character varying, p_is_ia_generated boolean DEFAULT NULL::boolean) RETURNS TABLE(id bigint, short_description text, question_code character varying, initial_status character varying, current_status character varying, status_created_at timestamp without time zone, type_question character varying, total bigint)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        WITH 
        TargetUser AS (
            SELECT e.id AS employee_id, e.user_id, e.charge_id
            FROM employees e
            WHERE e.id = p_employee_id
            LIMIT 1
        ),
        -- 1. UPLOADS
        Logic_Uploads AS (
            SELECT 
                q.id AS question_id,
                'UPLOADS'::VARCHAR AS derived_status,
                q.created_at AS derived_date
            FROM question q
            INNER JOIN TargetUser tu ON q.created_by = tu.user_id
            INNER JOIN employee_course ec ON tu.employee_id = ec.teacher_id AND ec.fl_status = TRUE
            WHERE 
                p_initial_status = 'UPLOADS'
                AND q.status NOT IN ('ARCH', 'DUPL')
                AND q.course_id = p_course_id
                AND ec.course_id = p_course_id
                AND q.created_at BETWEEN p_start_date AND p_end_date
                AND tu.charge_id IN (3, 4)
        ),
        -- 2. ESTADOS SIMPLES (Solo DIGI y DUPL)
        -- Se retiró DASI de aquí
        FirstStatusEver AS (
            SELECT 
                qs.question_id,
                qs.status,
                MIN(qs.created_at) AS first_date
            FROM question_status qs
            INNER JOIN question q ON q.id = qs.question_id
            WHERE 
                p_initial_status IN ('DIGI', 'DUPL') 
                AND qs.status = p_initial_status
                AND q.course_id = p_course_id
                AND q.fl_status IS TRUE
                AND (p_is_ia_generated IS NULL OR q.ia_generated = p_is_ia_generated)
            GROUP BY qs.question_id, qs.status
        ),
        Logic_Simple_Status AS (
            SELECT 
                fse.question_id,
                fse.status AS derived_status,
                fse.first_date AS derived_date
            FROM FirstStatusEver fse
            INNER JOIN question_status qs ON qs.question_id = fse.question_id 
                AND DATE_TRUNC('second', qs.created_at) = DATE_TRUNC('second', fse.first_date)
            INNER JOIN TargetUser tu ON qs.created_by = tu.user_id
            WHERE 
                DATE_TRUNC('minute', fse.first_date) BETWEEN DATE_TRUNC('minute', p_start_date) AND DATE_TRUNC('minute', p_end_date)
                AND tu.charge_id IN (3, 4)
        ),
        -- 3. LOGICA VERIFICADOS (Cuenta al Digitalizador)
        FirstVeriEver AS (
            SELECT 
                qs.question_id,
                MIN(qs.created_at) AS first_veri_date
            FROM question_status qs
            INNER JOIN question q ON q.id = qs.question_id
            WHERE 
                p_initial_status = 'VERI'
                AND qs.status IN ('VERI', 'APRB')
                AND q.course_id = p_course_id
                AND q.fl_status IS TRUE
                AND (p_is_ia_generated IS NULL OR q.ia_generated = p_is_ia_generated)
            GROUP BY qs.question_id
        ),
        FirstDigiForVeri AS (
            SELECT 
                qs.question_id,
                MIN(qs.created_at) AS first_digi_date
            FROM question_status qs
            WHERE 
                p_initial_status = 'VERI'
                AND qs.status = 'DIGI'
                AND qs.question_id IN (SELECT question_id FROM FirstVeriEver)
            GROUP BY qs.question_id
        ),
        Logic_Veri AS (
            SELECT 
                fve.question_id,
                'VERI'::VARCHAR AS derived_status,
                fve.first_veri_date AS derived_date
            FROM FirstVeriEver fve
            INNER JOIN question_status qs_veri ON qs_veri.question_id = fve.question_id
                AND DATE_TRUNC('second', qs_veri.created_at) = DATE_TRUNC('second', fve.first_veri_date)
                AND qs_veri.status IN ('VERI', 'APRB')
            INNER JOIN FirstDigiForVeri fdfv ON fdfv.question_id = fve.question_id
            INNER JOIN question_status qs_digi ON qs_digi.question_id = fdfv.question_id
                AND DATE_TRUNC('second', qs_digi.created_at) = DATE_TRUNC('second', fdfv.first_digi_date)
            INNER JOIN TargetUser tu ON qs_digi.created_by = tu.user_id -- Filtra por Digitalizador
            WHERE 
                DATE_TRUNC('minute', fve.first_veri_date) BETWEEN DATE_TRUNC('minute', p_start_date) AND DATE_TRUNC('minute', p_end_date)
                AND tu.charge_id IN (3, 4)
        ),
        -- 4. LOGICA OBSERVADOS (Cuenta al Digitalizador)
        FirstObseEver AS (
            SELECT 
                qs.question_id,
                MIN(qs.created_at) AS first_obse_date
            FROM question_status qs
            INNER JOIN question q ON q.id = qs.question_id
            WHERE 
                p_initial_status = 'OBSE'
                AND qs.status = 'OBSE'
                AND q.course_id = p_course_id
                AND q.fl_status IS TRUE
                AND (p_is_ia_generated IS NULL OR q.ia_generated = p_is_ia_generated)
            GROUP BY qs.question_id
        ),
        FirstDigiForObse AS (
            SELECT 
                qs.question_id,
                MIN(qs.created_at) AS first_digi_date
            FROM question_status qs
            WHERE 
                p_initial_status = 'OBSE'
                AND qs.status = 'DIGI'
                AND qs.question_id IN (SELECT question_id FROM FirstObseEver)
            GROUP BY qs.question_id
        ),
        Logic_Obse AS (
            SELECT 
                foe.question_id,
                'OBSE'::VARCHAR AS derived_status,
                foe.first_obse_date AS derived_date
            FROM FirstObseEver foe
            INNER JOIN question_status qs_obse ON qs_obse.question_id = foe.question_id
                AND DATE_TRUNC('second', qs_obse.created_at) = DATE_TRUNC('second', foe.first_obse_date)
            INNER JOIN FirstDigiForObse fdfo ON fdfo.question_id = foe.question_id
            INNER JOIN question_status qs_digi ON qs_digi.question_id = fdfo.question_id
                AND DATE_TRUNC('second', qs_digi.created_at) = DATE_TRUNC('second', fdfo.first_digi_date)
            INNER JOIN TargetUser tu ON qs_digi.created_by = tu.user_id -- Filtra por Digitalizador
            WHERE 
                DATE_TRUNC('minute', foe.first_obse_date) BETWEEN DATE_TRUNC('minute', p_start_date) AND DATE_TRUNC('minute', p_end_date)
                AND tu.charge_id IN (3, 4)
        ),
        FirstDasiEver AS (
            SELECT 
                eq.question_id,
                MIN(eq.created_at) AS first_dasi_date
            FROM employee_didi_question eq
            INNER JOIN question q ON q.id = eq.question_id
            INNER JOIN question_status qs ON qs.question_id = eq.question_id
            WHERE 
                p_initial_status = 'DASI'
                AND q.course_id = p_course_id
                AND q.fl_status IS TRUE
                AND (p_is_ia_generated IS NULL OR q.ia_generated = p_is_ia_generated)
            GROUP BY eq.question_id
        ),
        Logic_Dasi AS (
            SELECT 
                edq.question_id,
                'DASI'::VARCHAR AS derived_status,
                MIN(edq.created_at) AS derived_date -- Tomamos la primera vez en ESTE rango
            FROM employee_didi_question edq
            INNER JOIN question q ON q.id = edq.question_id
            INNER JOIN question_status qs ON qs.question_id = edq.question_id
            INNER JOIN employees e ON e.id = edq.employee_id
            INNER JOIN TargetUser tu ON e.user_id = tu.user_id
            WHERE 
                p_initial_status = 'DASI'
                AND qs.status = 'DASI'
                AND qs.created_at BETWEEN p_start_date AND p_end_date -- Filtro directo de fecha
                AND q.course_id = p_course_id
                AND q.fl_status IS TRUE
                AND (p_is_ia_generated IS NULL OR q.ia_generated = p_is_ia_generated)
                AND tu.charge_id IN (3, 4)
            GROUP BY edq.question_id
        ),
        -- UNIFICACIÓN
        All_Ids AS (
            SELECT * FROM Logic_Uploads
            UNION ALL
            SELECT * FROM Logic_Simple_Status
            UNION ALL
            SELECT * FROM Logic_Veri
            UNION ALL
            SELECT * FROM Logic_Obse
            UNION ALL
            SELECT * FROM Logic_Dasi
        ),
        FinalResult AS (
            SELECT 
                DISTINCT
                q.id,
                q.short_description,
                q.code AS question_code,
                ids.derived_status AS initial_status,
                q.status AS current_status,
                ids.derived_date AS status_created_at,
                q.type::VARCHAR AS type_question
            FROM All_Ids ids
            INNER JOIN question q ON ids.question_id = q.id
            WHERE 
                (p_short_description IS NULL OR p_short_description = '' OR q.short_description ILIKE '%' || p_short_description || '%')
                AND (p_code IS NULL OR p_code = '' OR q.code ILIKE '%' || p_code || '%')
                AND (p_type_question IS NULL OR q.type::VARCHAR = p_type_question)
                AND (p_is_ia_generated IS NULL OR q.ia_generated = p_is_ia_generated)
        ),
        TotalCount AS (
            SELECT COUNT(*) AS total FROM FinalResult
        )
        SELECT 
            fr.id,
            fr.short_description,
            fr.question_code,
            fr.initial_status,
            fr.current_status,
            fr.status_created_at,
            fr.type_question,
            tc.total
        FROM FinalResult fr, TotalCount tc
        ORDER BY fr.status_created_at DESC
        LIMIT p_per_page
        OFFSET (p_n_page - 1) * p_per_page;

    END;
    $$;


ALTER FUNCTION odiseo.fn_get_questions_by_didi_status(p_per_page integer, p_n_page integer, p_course_id integer, p_employee_id integer, p_initial_status character varying, p_start_date timestamp without time zone, p_end_date timestamp without time zone, p_short_description character varying, p_code character varying, p_type_question character varying, p_is_ia_generated boolean) OWNER TO postgres;

--
-- Name: fn_get_questions_by_teacher_status(integer, integer, integer, integer, character varying, timestamp without time zone, timestamp without time zone, character varying, character varying, character varying, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_questions_by_teacher_status(p_per_page integer, p_n_page integer, p_course_id integer, p_employee_id integer, p_status character varying, p_start_date timestamp without time zone, p_end_date timestamp without time zone, p_short_description character varying, p_code character varying, p_type_question character varying, p_is_ia_generated boolean DEFAULT NULL::boolean) RETURNS TABLE(question_code character varying, current_status character varying, id bigint, initial_status character varying, status_created_at timestamp without time zone, type_question character varying, short_description text, total bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_real_status VARCHAR := CASE WHEN p_status = 'VERI_NQ' THEN 'VERI' ELSE p_status END;
BEGIN
    RETURN QUERY
    WITH

    -- PASO 1: Preguntas candidatas del empleado en el rango de fechas
    -- Partimos desde el empleado, no desde toda la tabla
    tbl_first_status_ever AS (
        SELECT
            qs.question_id,
            MIN(qs.created_at) AS first_status_date
        FROM question_status qs
        INNER JOIN question q ON q.id = qs.question_id
        WHERE qs.status = v_real_status
        AND q.fl_status IS TRUE
        AND q.status <> 'ARCH'
        AND (p_status = 'VERI_NQ' AND q.ia_generated IS TRUE
             OR p_status = 'VERI' AND (q.ia_generated IS FALSE OR q.ia_generated IS NULL)
             OR p_status NOT IN ('VERI', 'VERI_NQ'))
        AND (p_course_id IS NULL OR q.course_id = p_course_id)
        AND p_status <> 'ASIG'
        GROUP BY qs.question_id
    ),

    tbl_candidate_questions AS (
        SELECT 
            question_id, 
            first_status_date
        FROM tbl_first_status_ever
        WHERE DATE_TRUNC('minute', first_status_date) BETWEEN DATE_TRUNC('minute', p_start_date) AND DATE_TRUNC('minute', p_end_date)
    ),

    -- PASO 2: Para esas preguntas candidatas, quién ejecutó el estado
    tbl_executor AS (
        SELECT DISTINCT ON (cq.question_id)
            cq.question_id,
            cq.first_status_date,
            e.id AS employee_id
        FROM tbl_candidate_questions cq
        INNER JOIN question_status qs ON qs.question_id = cq.question_id
            AND qs.created_at = cq.first_status_date
            AND qs.status = v_real_status
        INNER JOIN users u ON qs.created_by = u.id
        INNER JOIN employees e ON e.user_id = u.id
        ORDER BY cq.question_id
    ),

    -- PASO 3: Para esas preguntas candidatas, quién fue el indexador original
    tbl_indexador AS (
        SELECT DISTINCT ON (qs.question_id)
            qs.question_id,
            e.id AS employee_id
        FROM question_status qs
        INNER JOIN users u ON qs.created_by = u.id
        INNER JOIN employees e ON e.user_id = u.id
        WHERE qs.status = 'INDE'
        -- Solo para las preguntas candidatas, no toda la BD
        AND qs.question_id IN (SELECT question_id FROM tbl_candidate_questions)
        ORDER BY qs.question_id, qs.created_at ASC
    ),

    tbl_normal_status AS (
        SELECT
            ex.question_id,
            ex.first_status_date,
            v_real_status AS found_status
        FROM tbl_executor ex
        LEFT JOIN tbl_indexador io ON io.question_id = ex.question_id
        WHERE ex.employee_id = p_employee_id
        AND (
            (p_status IN ('VERI', 'VERI_NQ') AND io.employee_id = ex.employee_id)
            OR p_status NOT IN ('VERI', 'VERI_NQ')
        )
    ),

    -- PASO 5: Flujo DIGI→VERI filtrado por employee_id
    tbl_digi_veri_status AS (
        SELECT DISTINCT ON (cq.question_id)
            cq.question_id,
            cq.first_status_date,
            v_real_status AS found_status
        FROM tbl_candidate_questions cq
        INNER JOIN employee_question eq ON eq.question_id = cq.question_id
            AND eq.fl_status IS TRUE
            AND eq.teacher_id = p_employee_id
        -- El asignado debe ser quien verificó
        INNER JOIN tbl_executor ex ON ex.question_id = cq.question_id
            AND ex.employee_id = p_employee_id
        -- Sin INDE
        LEFT JOIN tbl_indexador io ON io.question_id = cq.question_id
        -- Sin tbl_normal_status
        LEFT JOIN tbl_normal_status ns ON ns.question_id = cq.question_id
        WHERE p_status IN ('VERI', 'VERI_NQ')
        AND io.question_id IS NULL
        AND ns.question_id IS NULL
        ORDER BY cq.question_id, eq.created_at DESC
    ),

    -- PASO 6: ASIG
    tbl_asig_status AS (
        SELECT
            qs.question_id,
            qs.created_at   AS first_status_date,
            qs.status       AS found_status
        FROM employee_question eq
        INNER JOIN question q ON eq.question_id = q.id
            AND q.fl_status IS TRUE
            AND q.status <> 'ARCH'
        INNER JOIN question_status qs ON eq.question_id = qs.question_id
            AND qs.created_at >= eq.created_at
            AND qs.status = 'ASIG'
            AND qs.created_at BETWEEN DATE_TRUNC('minute', p_start_date)
                                   AND DATE_TRUNC('minute', p_end_date)
        WHERE p_status = 'ASIG'
        AND eq.fl_status IS TRUE
        AND eq.teacher_id = p_employee_id
        AND (p_course_id IS NULL OR q.course_id = p_course_id)
    ),

    -- PASO 7: Union y join final
    tbl_filtered_history AS (
        SELECT
            sd.question_id,
            sd.found_status      AS status_history,
            sd.first_status_date AS create_status,
            q.type               AS type_question,
            q.code               AS question_code,
            q.short_description
        FROM (
            SELECT * FROM tbl_normal_status    WHERE p_status <> 'ASIG'
            UNION ALL
            SELECT * FROM tbl_digi_veri_status
            UNION ALL
            SELECT * FROM tbl_asig_status      WHERE p_status = 'ASIG'
        ) sd
        INNER JOIN question q ON q.id = sd.question_id
        AND (p_code              IS NULL OR p_code = ''
             OR q.code ILIKE '%' || p_code || '%')
        AND (p_type_question     IS NULL OR p_type_question = ''
             OR q.type = p_type_question)
        AND (p_short_description IS NULL OR p_short_description = ''
             OR q.short_description ILIKE '%' || p_short_description || '%')
    )

    SELECT
        fh.question_code,
        qs_curr.status      AS current_status,
        fh.question_id      AS id,
        fh.status_history   AS initial_status,
        fh.create_status    AS status_created_at,
        fh.type_question,
        fh.short_description,
        COUNT(*) OVER ()    AS total
    FROM tbl_filtered_history fh
    LEFT JOIN question_status qs_curr ON qs_curr.question_id = fh.question_id
        AND qs_curr.fl_active = TRUE
    ORDER BY fh.create_status ASC
    LIMIT p_per_page
    OFFSET (p_n_page - 1) * p_per_page;

END;
$$;


ALTER FUNCTION odiseo.fn_get_questions_by_teacher_status(p_per_page integer, p_n_page integer, p_course_id integer, p_employee_id integer, p_status character varying, p_start_date timestamp without time zone, p_end_date timestamp without time zone, p_short_description character varying, p_code character varying, p_type_question character varying, p_is_ia_generated boolean) OWNER TO postgres;

--
-- Name: fn_get_questions_ia(boolean, text, integer, character varying, integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_questions_ia(p_status_revised boolean, p_search_term text DEFAULT NULL::text, p_course_id integer DEFAULT NULL::integer, p_status character varying DEFAULT NULL::character varying, p_teacher_id integer DEFAULT NULL::integer, p_page integer DEFAULT 1, p_per_page integer DEFAULT 15) RETURNS TABLE(id bigint, description text, course_id smallint, course character varying, course_code character varying, topic_id smallint, topic_code character varying, topic character varying, subtopic_id smallint, subtopic_code character varying, subtopic character varying, level_id bigint, level character varying, description_level character varying, teacher_id bigint, teacher text, status_revised boolean, created_at timestamp without time zone, date_revised timestamp without time zone, question_id bigint, code character varying, status character varying, verification_time character varying, total_records bigint)
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                        RETURN QUERY
                        SELECT
                            qtia.id,
                            qtia.description_short AS description,
                            qtia.course_id,
                            c.name AS course,
                            c.code AS course_code,
                            qtia.topic_id,
                            t.code AS topic_code,
                            t.name AS topic,
                            qtia.subtopic_id,
                            st.code AS subtopic_code,
                            st.name AS subtopic,
                            qtia.level_id,
                            l.name AS level,
                            l.description AS description_level,
                            qtia.teacher_id,
                            CASE
                                WHEN qtia.teacher_id IS NOT NULL THEN
                                    e.first_name || ' ' || e.first_surname || ' ' || e.second_surname
                                ELSE NULL
                            END AS teacher,
                            qtia.status_revised,
                            qtia.created_at,
                            oqnq.date_revised,
                            q.id AS question_id,
                            q.code,
                            q.status,
                            (LPAD(
                                FLOOR(
                                    EXTRACT(EPOCH FROM (
                                        qtia.verification_finished_at - qtia.verification_started_at
                                    )) / 60
                                )::TEXT,
                                2,
                                '0'
                            ) || ':' ||
                            LPAD(
                                MOD(
                                    FLOOR(EXTRACT(EPOCH FROM (
                                        qtia.verification_finished_at - qtia.verification_started_at
                                    ))),
                                    60
                                )::TEXT,
                                2,
                                '0'
                            ))::VARCHAR AS verification_time,
                            COUNT(*) OVER() AS total_records
                        FROM
                            question_teacher_ia AS qtia
                        JOIN course AS c ON c.id = qtia.course_id
                        JOIN topic AS t ON t.id = qtia.topic_id
                        JOIN subtopic AS st ON st.id = qtia.subtopic_id
                        JOIN level AS l ON l.id = qtia.level_id
                        LEFT JOIN employees AS e ON e.id = qtia.teacher_id
                        LEFT JOIN origin_question_nq AS oqnq ON qtia.id = oqnq.question_ia_id
                        LEFT JOIN question AS q ON oqnq.question_id = q.id
                        WHERE
                            qtia.fl_status = true
                            AND qtia.status_revised = p_status_revised
                            AND (p_search_term IS NULL
                                OR unaccent(qtia.description) ILIKE '%' || unaccent(p_search_term) || '%'
                                OR q.code ILIKE '%' || p_search_term || '%')
                            AND (p_course_id IS NULL OR qtia.course_id = p_course_id)
                            AND (p_teacher_id IS NULL OR qtia.teacher_id = p_teacher_id)
                            AND (p_status IS NULL OR q.status = p_status)
                        ORDER BY
                            qtia.created_at ASC
                        LIMIT
                            p_per_page
                        OFFSET
                            (p_page - 1) * p_per_page;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_get_questions_ia(p_status_revised boolean, p_search_term text, p_course_id integer, p_status character varying, p_teacher_id integer, p_page integer, p_per_page integer) OWNER TO postgres;

--
-- Name: fn_get_questions_missing_ballot(bigint, boolean, smallint, smallint, smallint, boolean, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_questions_missing_ballot(p_material_id bigint, p_fl_validate_code boolean, p_type_material_id smallint, p_start_week smallint, p_end_week smallint, p_has_permission_filter_per_course boolean, p_employee_id integer) RETURNS TABLE(id bigint, code character varying, course_id smallint, topic_id smallint, level_id smallint, level smallint, type character varying, status character varying, subtopic_id integer, frequent_subtopic boolean, cycle_id integer, week smallint, type_material_id smallint, history jsonb)
    LANGUAGE plpgsql
    AS $$
                DECLARE
                    v_course_ids INT[];
                BEGIN
                    /*
                        ------------------------------------------------------------------------------------
                        -- HISTORIAL DE CAMBIOS
                        ------------------------------------------------------------------------------------
                        Versión: 1.0
                        Fecha: 2025-10-28
                        Autor: Junior Alcarraz
                        Descripción:
                            Trae preguntas de la distribucion de un rango por periodo
                    */

                    IF p_has_permission_filter_per_course THEN
                        SELECT array_agg(DISTINCT ec.course_id) INTO v_course_ids
                        FROM employee_course ec
                        WHERE ec.teacher_id = p_employee_id
                        AND ec.deleted_by IS NULL
                        AND ec.fl_status = true;
                    END IF;

                    RETURN QUERY
                    WITH type_materias AS (
                        SELECT
                            CASE
                                WHEN EXISTS ( SELECT 1 FROM type_material tmx WHERE tmx.parent_id = p_type_material_id )
                                THEN ARRAY( SELECT tmy.id FROM type_material tmy WHERE tmy.parent_id = p_type_material_id )
                                ELSE ARRAY[p_type_material_id]
                            END AS ids
                    ), get_type_materias AS ( -- Se trae el id de tipo material hijo si los tiene, sino se manda el normal
                        SELECT unnest(tm.ids) AS type_material_id FROM type_materias tm
                    ), get_config_syllabus AS ( -- Se trae la configuración de niveles
                        SELECT
                            csrb.subtopic_id,
                            csrb.course_id
                        FROM fn_get_config_syllabus_complete_ballot_period(
                            p_material_id,
                            p_type_material_id,
                            p_start_week,
                            p_end_week
                        ) csrb
                    ), get_config_level AS ( -- Se trae la configuración de niveles
                        SELECT
                            clrb.level_id,
                            clrb.course_id
                        FROM fn_get_config_level_complete_ballot_period(
                            p_material_id,
                            p_type_material_id,
                            p_start_week,
                            p_end_week
                        ) clrb
                    ), get_courses_missing_ballot AS (
                        SELECT DISTINCT
                            mdbq.course_id,
                            mdbq.subtopic_id,
                            mdbq.level_id
                        FROM detail_week_type_mat dwtm
                        JOIN material_ballot_question mdbq ON dwtm.id = mdbq.week_type_material_id
                        WHERE mdbq.material_id = p_material_id
                            AND dwtm.week BETWEEN p_start_week AND p_end_week
                            AND dwtm.type_material_id IN (SELECT gtm.type_material_id FROM get_type_materias gtm)
                            AND mdbq.fl_status = true
                            AND mdbq.question_id IS NULL
                            AND mdbq.type_text_id IS NULL
                    ), get_subtopics_search AS (
                        SELECT
                            gcs.course_id,
                            gcs.subtopic_id
                        FROM get_config_syllabus gcs
                        UNION ALL
                        SELECT DISTINCT
                            gcmb.course_id,
                            gcmb.subtopic_id
                        FROM get_courses_missing_ballot gcmb
                    ), get_levels_search AS (
                        SELECT
                            gcl.course_id,
                            gcl.level_id
                        FROM get_config_level gcl
                        UNION ALL
                        SELECT DISTINCT
                            gcmb.course_id,
                            gcmb.level_id
                        FROM get_courses_missing_ballot gcmb
                    ), limit_config_level AS (
                        SELECT
                            mppb.lower_level_limit,
                            mppb.upper_level_limit
                        FROM material_per_period mpp
                        INNER JOIN material_per_period_ballot mppb ON mpp.id = mppb.material_per_period_id
                            AND mppb.deleted_by IS NULL
                        WHERE mpp.material_id = p_material_id
                            AND mpp.type_material_id = p_type_material_id
                            AND mppb.start_week = p_start_week
                            AND mppb.end_week = p_end_week
                    ), course_ranges_by_level AS (
                        SELECT
                            gls.course_id,
                            MIN(gls.level_id) as min_existing_level,
                            MAX(gls.level_id) as max_existing_level
                        FROM get_levels_search gls
                        GROUP BY gls.course_id
                    ), get_config_level_with_range AS (
                        SELECT
                            cr.course_id,
                            generate_series(
                                cr.min_existing_level - lcl.lower_level_limit,
                                cr.max_existing_level + lcl.upper_level_limit
                            ) AS level_id
                        FROM
                            course_ranges_by_level cr,
                            limit_config_level lcl
                        ORDER BY
                            cr.course_id,
                            level_id
                    )
                    SELECT
                        fqvm.id,
                        fqvm.code,
                        fqvm.course_id,
                        fqvm.topic_id,
                        fqvm.level_id,
                        fqvm.level,
                        fqvm.type,
                        fqvm.status,
                        fqvm.subtopic_id,
                        fqvm.frequent_subtopic,
                        fqvm.cycle_id,
                        fqvm.week,
                        fqvm.type_material_id,
                        fqvm.history
                    FROM fn_question_verified_material(p_material_id, p_fl_validate_code) fqvm
                    JOIN get_subtopics_search gss ON fqvm.course_id = gss.course_id
                        AND fqvm.subtopic_id = gss.subtopic_id
                    JOIN get_config_level_with_range gclwr ON fqvm.course_id = gclwr.course_id
                        AND fqvm.level_id = gclwr.level_id
                    WHERE 1 = 1
                    AND (p_has_permission_filter_per_course = false OR fqvm.course_id = ANY(v_course_ids))
                    ORDER BY fqvm.id DESC, fqvm.topic_id ASC, fqvm.subtopic_id ASC;
                END;
                $$;


ALTER FUNCTION odiseo.fn_get_questions_missing_ballot(p_material_id bigint, p_fl_validate_code boolean, p_type_material_id smallint, p_start_week smallint, p_end_week smallint, p_has_permission_filter_per_course boolean, p_employee_id integer) OWNER TO postgres;

--
-- Name: fn_get_questions_register_ballot(bigint, boolean, smallint, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_questions_register_ballot(p_material_id bigint, p_fl_validate_code boolean, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) RETURNS TABLE(id bigint, code character varying, course_id smallint, topic_id smallint, level_id smallint, level smallint, type character varying, status character varying, subtopic_id integer, frequent_subtopic boolean, cycle_id integer, week smallint, type_material_id smallint, history jsonb)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            WITH get_config_syllabus AS ( -- Se trae la configuración de niveles
                SELECT
                    csrb.subtopic_id,
                    csrb.course_id
                FROM fn_get_config_syllabus_register_ballot_period(
                    p_material_id,
                    p_type_material_id,
                    p_start_week,
                    p_end_week
                ) csrb
            ), get_config_level AS ( -- Se trae la configuración de niveles
                SELECT
                    clrb.level_id,
                    clrb.type_question,
                    clrb.course_id
                FROM fn_get_config_level_register_ballot_period(
                    p_material_id,
                    p_type_material_id,
                    p_start_week,
                    p_end_week
                ) clrb
            )
            SELECT
                fqvm.id,
                fqvm.code,
                fqvm.course_id,
                fqvm.topic_id,
                fqvm.level_id,
                fqvm.level,
                fqvm.type,
                fqvm.status,
                fqvm.subtopic_id,
                fqvm.frequent_subtopic,
                fqvm.cycle_id,
                fqvm.week,
                fqvm.type_material_id,
                fqvm.history
            FROM fn_question_verified_material(
                p_material_id,
                p_fl_validate_code
            ) fqvm
            WHERE 1 = 1
                AND fqvm.subtopic_id IN (SELECT gcs.subtopic_id FROM get_config_syllabus gcs)
                AND fqvm.level_id IN (SELECT gcl.level_id FROM get_config_level gcl)
                AND fqvm.type IN (SELECT gcl.type_question FROM get_config_level gcl)
            ORDER BY fqvm.id DESC, fqvm.topic_id ASC, fqvm.subtopic_id ASC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_get_questions_register_ballot(p_material_id bigint, p_fl_validate_code boolean, p_type_material_id smallint, p_start_week smallint, p_end_week smallint) OWNER TO postgres;

--
-- Name: fn_get_questions_to_assign_didi(); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_questions_to_assign_didi() RETURNS TABLE(type_question text, id bigint, course_id bigint, code text, status text, employee_id bigint, questions json, priority integer, created_at timestamp without time zone)
    LANGUAGE sql
    AS $$
                WITH question_p AS (
                    SELECT
                        q.id,
                        q.course_id,
                        q.code,
                        q.priority,
                        qs.created_at
                    FROM question q
                    JOIN question_status qs ON q.id = qs.question_id
                        AND qs.status = q.status
                        AND qs.fl_active = true
                    WHERE q.status = 'INDE'
                    AND q.fl_status IS TRUE
                    AND q.parent_id IS NULL
                    ORDER BY qs.created_at ASC
                ),
                question_t AS (
                    SELECT
                        pq.id,
                        pq.code,
                        pq.course_id,
                        pq.status,
                        pq.fl_status,
                        e.id AS employee_id,
                        json_agg(q.*) AS questions,
                        pq.priority,
                        pq.created_at,
	                    MAX(q.created_at) AS last_question_created_at
                    FROM parent_question pq
                    JOIN (
                        SELECT q.id, q.code, q.course_id, q.status, q.parent_id, q.fl_status, qs.created_at
                        FROM question q
                        JOIN question_status qs ON q.id = qs.question_id
                            AND qs.status = q.status
                            AND qs.fl_active = true
                        WHERE q.status = 'INDE' AND q.fl_status IS TRUE
                    ) q ON pq.id = q.parent_id
                    LEFT JOIN users u ON u.id = pq.created_by
                    LEFT JOIN employees e ON e.user_id = u.id
                    WHERE pq.fl_status IS TRUE
                    AND pq.status IN ('INDE')
                    AND NOT EXISTS (
                        SELECT 1
                        FROM question q2
                        WHERE q2.parent_id = pq.id
                        AND q2.status != 'INDE'
                        AND q2.fl_status IS TRUE
                    )
                    GROUP BY
                        pq.id,
                        pq.code,
                        pq.course_id,
                        u.id,
                        e.id,
                        pq.status,
                        pq.fl_status
                    HAVING count(q.id) > 0
	                ORDER BY last_question_created_at ASC
                ),
                resultado_union AS (
                    SELECT
                        'P'::text AS type_question,
                        id,
                        course_id,
                        code,
                        'INDE'::text AS status,
                        NULL::bigint AS employee_id,
                        NULL::json AS questions,
                        priority,
                        created_at
                    FROM question_p

                    UNION ALL

                    SELECT
                        'T'::text AS type_question,
                        id,
                        course_id,
                        code,
                        status,
                        employee_id,
                        questions,
                        priority,
                        created_at
                    FROM question_t
                )

                SELECT * FROM resultado_union ORDER BY priority DESC, created_at ASC, id ASC;
            $$;


ALTER FUNCTION odiseo.fn_get_questions_to_assign_didi() OWNER TO postgres;

--
-- Name: fn_get_questions_to_assign_teacher(); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_questions_to_assign_teacher() RETURNS TABLE(type_question text, id bigint, course_id bigint, questions json, priority integer, created_at timestamp without time zone)
    LANGUAGE sql
    AS $$
        WITH question_sasi_p AS (
            SELECT q.id, q.course_id, q.priority, q.created_at 
            FROM question AS q
            WHERE q.status = 'SASI'
            AND q.parent_id IS NULL
            AND (q.number_question IS NULL OR q.number_question NOT ILIKE 'D%')
        ),
        parent_question_sasi_t AS (
            SELECT
                pq.id,
                pq.course_id,
                CASE
                    WHEN count(q.id) > 0 THEN json_agg(q.* ORDER BY
                        CASE
                            WHEN q.type_material_id = 3 THEN 1
                            WHEN q.type_material_id = 2 THEN 2
                            WHEN q.type_material_id = 1 THEN 3
                            WHEN q.type_material_id IS NOT NULL THEN 4
                            ELSE 5
                        END ASC, q.type_material_id ASC, q.id ASC)
                    ELSE '[]'::json
                END AS questions,
                pq.priority,
                pq.created_at
            FROM parent_question pq
            LEFT JOIN (
                SELECT q_inner.id, q_inner.code, q_inner.course_id, q_inner.status, q_inner.parent_id, q_inner.fl_status, qt.type_material_id, t.description
                FROM question q_inner
                LEFT JOIN question_temporary qt ON qt.question_id = q_inner.id
                LEFT JOIN type_material t ON qt.type_material_id = t.id
                WHERE q_inner.status IN ('SASI', 'DUPL')
                AND q_inner.fl_status IS TRUE
                AND (q_inner.number_question IS NULL OR q_inner.number_question NOT ILIKE 'D%')
            ) q ON pq.id = q.parent_id
            WHERE pq.fl_status IS TRUE
            AND pq.status IN ('SASI', 'ASIG')
            AND (pq.number_question IS NULL OR pq.number_question NOT ILIKE 'D%')
            GROUP BY pq.id, pq.course_id, pq.priority, pq.created_at
            HAVING count(q.id) > 0
        ), result as (
            SELECT
                'P'::text AS type_question,
                p.id,
                p.course_id,
                NULL::json AS questions,
                p.priority,
                p.created_at
            FROM question_sasi_p p
            
            UNION ALL
            
            SELECT
                'T'::text AS type_question,
                t.id,
                t.course_id,
                t.questions,
                t.priority,
                t.created_at
            FROM parent_question_sasi_t t

        )
        SELECT * FROM result
        ORDER BY priority DESC, created_at ASC, id ASC;
    $$;


ALTER FUNCTION odiseo.fn_get_questions_to_assign_teacher() OWNER TO postgres;

--
-- Name: fn_get_questions_verified_and_not_excluded_material_filter(integer, integer, character varying, smallint, smallint, bigint, smallint, bigint, smallint, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_questions_verified_and_not_excluded_material_filter(p_perpage integer, p_npage integer, p_search character varying, p_course_id smallint, p_topic_id smallint, p_subtopic_id bigint, p_level_id smallint, p_material_id bigint, p_type_material_id smallint, p_week smallint, p_area_id smallint) RETURNS TABLE(id bigint, code character varying, course_id smallint, course text, topic_id smallint, topic text, level_id smallint, level smallint, type character varying, type_question character varying, status character varying, subtopic_id integer, subtopic text, frequent_subtopic boolean, cycle_id integer, week smallint, type_material_id smallint, history jsonb, shared_status text, total_count bigint)
    LANGUAGE plpgsql
    AS $$
                DECLARE
                    offset_val INTEGER;
                BEGIN
                    offset_val := p_perpage * (p_npage - 1);

                    RETURN QUERY
                    WITH tbl_material AS ( -- Se traen los datos del material
                        SELECT
                            m.cycle_id, m.university_id
                        FROM material m
                        LEFT JOIN cycle c ON m.cycle_id = c.id
                        WHERE m.id = p_material_id
                    ), tbl_type_material AS ( -- Se traen los datos del tipo de material
                        SELECT
                            tm.id, tmt.fl_exam, tmt.type_exam_id, tm.type_material_template_id
                        FROM type_material tm
                        INNER JOIN type_material_template tmt ON tm.type_material_template_id = tmt.id
                        WHERE tm.id = p_type_material_id
                    ), children_type_material AS ( -- Se lista los hijos del tipo material si es que los tiene
                        SELECT DISTINCT
                            tm.id,
                            tm.fl_exam
                        FROM type_material_bound tmb
                        INNER JOIN type_material tm
                        ON tmb.type_material_template_extra_id = tm.type_material_template_id
                        WHERE 1 = 1
                        AND tmb.fl_status = true
                        AND tmb.type_material_template_id IN (SELECT type_material_template_id FROM tbl_type_material)
                        AND tm.cycle_id IN (SELECT tm2.cycle_id FROM tbl_material tm2)
                    ), has_children AS ( -- Verifica si existen hijos del tipo material
                        SELECT COUNT(*) > 0 AS has_data FROM children_type_material
                    ), type_material_chosen AS ( -- Se selecciona el tipo material si tiene hijos o no
                        SELECT tmc.*
                        FROM (
                            SELECT ctm.id, ctm.fl_exam FROM children_type_material ctm
                            WHERE (SELECT has_data FROM has_children)
                            UNION ALL
                            SELECT ctm.id, ctm.fl_exam FROM tbl_type_material ctm
                            WHERE NOT (SELECT has_data FROM has_children)
                        ) tmc
                        WHERE tmc.fl_exam = FALSE
                    ), weeks AS ( -- Se seleccionan las semanas del tipo material
                        SELECT generate_series(1, p_week) AS week
                    ), week_chosen AS ( -- Se aplica validacion a usar las semanas
                        SELECT
                            ws.week,
                            ttm.fl_exam,
                            ttm.type_exam_id,
                            CASE
                                WHEN ttm.fl_exam IS FALSE AND ws.week = p_week THEN TRUE
                                WHEN ttm.fl_exam IS TRUE AND ttm.type_exam_id = 3 THEN TRUE
                                WHEN ttm.fl_exam IS TRUE AND ttm.type_exam_id <> 4 AND ws.week = p_week THEN TRUE
                                ELSE FALSE
                            END AS week_value
                        FROM weeks ws
                        LEFT JOIN tbl_type_material ttm ON 1 = 1
                    ), tbl_syllabus AS ( -- Se listar los subtemas del syllabus
                        SELECT DISTINCT
                            sds.subtopic_id
                        FROM syllabus_subtopic_type_material stm
                        INNER JOIN syllabus_detail_subtopic sds ON stm.syllabus_detail_subtopic_id = sds.id AND sds.fl_status = true
                        INNER JOIN syllabus_topic_week stw ON sds.syllabus_topic_week_id = stw.id AND stw.fl_status = true
                        INNER JOIN syllabus_topic st ON stw.syllabus_topic_id = st.id AND st.fl_status = true
                        INNER JOIN syllabus s ON st.syllabus_id = s.id
                        INNER JOIN course co ON s.course_id = co.id
                        INNER JOIN topic top ON st.topic_id = top.id
                        INNER JOIN subtopic su ON sds.subtopic_id = su.id
                        WHERE stm.fl_status = true
                        AND s.fl_status = true
                        AND (
                            NOT EXISTS (SELECT tmc.id FROM type_material_chosen tmc)
                            OR stm.type_material_id IN (SELECT tmc.id FROM type_material_chosen tmc)
                        )
                        AND s.university_id IN (SELECT tm.university_id FROM tbl_material tm)
                        AND s.cycle_id IN (SELECT tm.cycle_id FROM tbl_material tm)
                        AND (
                            NOT EXISTS (SELECT wc.week FROM week_chosen wc WHERE wc.week_value = TRUE)
                            OR stw.week IN (SELECT wc.week FROM week_chosen wc WHERE wc.week_value = TRUE)
                        )
                        AND stm.questions_amount > 0
                        ORDER BY sds.subtopic_id ASC
                    ), tbl_questions_verified_filter AS ( -- Se listan las preguntas verificadas a usar
                        SELECT
                            fqvm.id,
                            fqvm.code,
                            fqvm.course_id,
                            CONCAT(c.code, '-', c.name) AS course,
                            fqvm.topic_id,
                            CONCAT(t.code, '-', t.name) AS topic,
                            fqvm.level_id,
                            fqvm.level,
                            fqvm.type,
                            'P'::VARCHAR,
                            fqvm.status,
                            fqvm.subtopic_id,
                            CONCAT(s.code, '-', s.name) AS subtopic,
                            fqvm.frequent_subtopic,
                            fqvm.cycle_id,
                            fqvm.week,
                            fqvm.type_material_id,
                            fqvm.history,
                            get_shared_status(fqvm.id,fqvm.subtopic_id) AS shared_status
                        FROM fn_list_questions_verified_and_not_excluded(p_material_id) fqvm
                        INNER JOIN course c ON fqvm.course_id = c.id
                        INNER JOIN topic t ON fqvm.topic_id = t.id
                        INNER JOIN subtopic s ON fqvm.subtopic_id = s.id
                        WHERE fqvm.subtopic_id IN (SELECT tb.subtopic_id FROM tbl_syllabus tb)
                    ), tbl_questions_area_repeat AS ( -- Se listan las preguntas repetidas en otras areas
                        SELECT DISTINCT
                            meq.question_id
                        FROM material_exam_question meq
                        INNER JOIN material_exam_area_week meaw ON meq.material_exam_area_week_id = meaw.id AND meaw.fl_status = true
                        INNER JOIN detail_week_type_mat dwtm ON meaw.week_type_material_id = dwtm.id AND dwtm.fl_status = true
                        WHERE dwtm.material_id = p_material_id
                            AND dwtm.week = p_week
                            AND dwtm.type_material_id = p_type_material_id
                            AND meq.fl_status = true
                            AND (
                                p_area_id IS NULL
                                OR (
                                    meaw.area_id <> p_area_id
                                    AND NOT EXISTS (
                                        SELECT 1
                                        FROM material_exam_question meq2
                                        INNER JOIN material_exam_area_week meaw2
                                            ON meq2.material_exam_area_week_id = meaw2.id
                                            AND meaw2.fl_status = true
                                        INNER JOIN detail_week_type_mat dwtm2
                                            ON meaw2.week_type_material_id = dwtm2.id
                                            AND dwtm2.fl_status = true
                                        WHERE meq2.question_id = meq.question_id
                                        AND meaw2.area_id = p_area_id
                                        AND dwtm2.material_id = p_material_id
                                        AND dwtm2.week = p_week
                                        AND dwtm2.type_material_id = p_type_material_id
                                        AND meq2.fl_status = true
                                    )
                                )
                            )
                    ), tbl_questions_areas AS ( -- Se listan las preguntas de las areas seleccionadas
                        SELECT
                            q.id,
                            q.code,
                            q.course_id,
                            CONCAT(c.code, '-', c.name) AS course,
                            q.topic_id,
                            CONCAT(t.code, '-', t.name) AS topic,
                            q.level_id,
                            l.name::SMALLINT AS level,
                            q.type,
                            'P'::VARCHAR,
                            q.status,
                            qs.subtopic_id,
                            CONCAT(s.code, '-', s.name) AS subtopic,
                            COALESCE(fus.is_frequent, false) AS frequent_subtopic,
                            qt.cycle_id,
                            qt.week_id AS week,
                            qt.type_material_id,
                            '[]'::JSONB AS history,
                            get_shared_status(q.id,qs.subtopic_id) AS shared_status
                        FROM question q
                        INNER JOIN course c ON q.course_id = c.id
                        INNER JOIN topic t ON q.topic_id = t.id
                        LEFT JOIN question_subtopic qs ON qs.question_id = q.id AND qs.fl_status = true
                        LEFT JOIN question_temporary qt ON qt.question_id = q.id AND qt.fl_status = true
                        LEFT JOIN subtopic s ON qs.subtopic_id = s.id
                        LEFT JOIN level l ON l.id = q.level_id
                        LEFT JOIN frequent_university_subtopic fus ON fus.university_id = 1 AND fus.subtopic_id = qs.subtopic_id AND fus.fl_status = true
                        WHERE 1= 1
                            AND q.id IN (SELECT * FROM tbl_questions_area_repeat)
                            AND q.status IN ('VERI', 'APRB')
                            AND q.fl_status = true
                            AND l.fl_status = true
                        AND NOT EXISTS (
                            SELECT 1
                                FROM question_excluded_material qem
                                WHERE qem.question_id = q.id
                                AND qem.material_id = p_material_id
                                AND qem.deleted_at IS NULL
                        )
                        AND ( -- Filtra si es examen o tienen la validación en true deberia de no usar los codigos que empiezan con 'D'
                            -- Se quito la validación por codigo, ahora no toma en cuenta el codigo o que empiezan con 'D'
                            q.number_question IS NULL
                            OR q.number_question NOT LIKE 'D%'
                        )
                        ORDER BY q.id ASC
                    ), tbl_questions_union AS ( -- Se unen las preguntas verificadas y las de las areas
                        SELECT * FROM tbl_questions_verified_filter
                        UNION ALL
                        SELECT * FROM tbl_questions_areas
                    ), tbl_questions AS ( -- Se filtran las preguntas finales
                        SELECT tqu.* FROM tbl_questions_union tqu
                        WHERE 1 = 1
                            AND (p_search IS NULL OR tqu.code ILIKE '%' || p_search || '%')
                            AND (p_course_id IS NULL OR tqu.course_id = p_course_id)
                            AND (p_topic_id IS NULL OR tqu.topic_id = p_topic_id)
                            AND (p_subtopic_id IS NULL OR tqu.subtopic_id = p_subtopic_id)
                            AND (p_level_id IS NULL OR tqu.level_id = p_level_id)
                    )
                    SELECT tq.*, count(*) OVER () AS total_count
                    FROM tbl_questions as tq
                    ORDER BY tq.course_id ASC, tq.topic ASC, tq.subtopic ASC, tq.id ASC
                    LIMIT p_perpage
                    OFFSET offset_val;
                END;
                $$;


ALTER FUNCTION odiseo.fn_get_questions_verified_and_not_excluded_material_filter(p_perpage integer, p_npage integer, p_search character varying, p_course_id smallint, p_topic_id smallint, p_subtopic_id bigint, p_level_id smallint, p_material_id bigint, p_type_material_id smallint, p_week smallint, p_area_id smallint) OWNER TO postgres;

--
-- Name: fn_get_regeneration_pdfs_progress(date); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_regeneration_pdfs_progress(p_since_date date) RETURNS TABLE(digitalized_questions_completed bigint, digitalized_questions_uncompleted bigint, digitalized_regeneration_percentage numeric, verified_questions_completed bigint, verified_questions_uncompleted bigint, verified_regeneration_percentage numeric, completed bigint, uncompleted bigint, regeneration_percentage numeric)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            WITH question_pdf_migration_status AS (
                SELECT
                    q.status,
                    CASE
                        WHEN
                            q.status IN ('SASI', 'ASIG', 'DUPL', 'RESO')
                            AND q.url_pdf_updated_at IS NOT NULL
                            AND q.url_pdf_updated_at::DATE >= p_since_date THEN TRUE
                        WHEN 
                            q.status IN ('INDE', 'RECH', 'DASI')
                            AND q.url_pdf_updated_at IS NOT NULL
                            AND q.url_pdf_updated_at::DATE >= p_since_date
                            AND eq.url_pdf_question_solution_updated_at IS NOT NULL
                            AND eq.url_pdf_question_solution_updated_at::DATE >= p_since_date THEN TRUE
                        WHEN
                       		q.status IN ('DIGI', 'OBSE')
                       		AND q.url_pdf_updated_at IS NOT NULL
                            AND q.url_pdf_updated_at::DATE >= p_since_date
                            AND eq.url_pdf_question_solution_updated_at IS NOT NULL
                            AND eq.url_pdf_question_solution_updated_at::DATE >= p_since_date
                            AND ed.url_file_digitalized_solution_updated_at IS NOT NULL
                            AND ed.url_file_digitalized_solution_updated_at::DATE >= p_since_date THEN TRUE
                        WHEN
                            q.status IN ('VERI', 'PEND', 'RESV')
                            AND ed.url_file_digitalized_solution_updated_at IS NOT NULL
                            AND ed.url_file_digitalized_solution_updated_at::DATE >= p_since_date THEN TRUE
                        ELSE FALSE
                    END AS it_has_all_the_pdfs
                FROM odiseo.question q
                LEFT JOIN odiseo.employee_question eq ON q.id = eq.question_id AND eq.fl_status IS TRUE
                LEFT JOIN odiseo.employee_didi_question ed ON q.id = ed.question_id AND ed.fl_status IS TRUE
                WHERE 1 = 1
                  AND q.status <> 'ARCH'
                  AND q.fl_status IS TRUE
            ), regeneration_amount_by_status AS (
                SELECT
                    SUM(CASE WHEN status IN ('DIGI', 'OBSE') AND it_has_all_the_pdfs IS TRUE THEN 1 ELSE 0 END) digitalized_questions_completed,
                    SUM(CASE WHEN status IN ('DIGI', 'OBSE') AND it_has_all_the_pdfs IS FALSE THEN 1 ELSE 0 END) digitalized_questions_uncompleted,
                    SUM(CASE WHEN status IN ('VERI', 'PEND', 'RESV') AND it_has_all_the_pdfs IS TRUE THEN 1 ELSE 0 END) verified_questions_completed,
                    SUM(CASE WHEN status IN ('VERI', 'PEND', 'RESV') AND it_has_all_the_pdfs IS FALSE THEN 1 ELSE 0 END) verified_questions_uncompleted,
                    SUM(CASE WHEN it_has_all_the_pdfs IS TRUE THEN 1 ELSE 0 END) AS completed,
                    SUM(CASE WHEN it_has_all_the_pdfs IS FALSE THEN 1 ELSE 0 END) AS uncompleted
                FROM question_pdf_migration_status
            ) SELECT
                /* Digitalized questions */
                r.digitalized_questions_completed,
                r.digitalized_questions_uncompleted,
                ROUND((r.digitalized_questions_completed::DECIMAL / NULLIF(r.digitalized_questions_completed + r.digitalized_questions_uncompleted, 0) * 100), 2) AS digitalized_regeneration_percentage,
                /* Verified questions */
                r.verified_questions_completed,
                r.verified_questions_uncompleted,
                ROUND((r.verified_questions_completed::DECIMAL / NULLIF(r.verified_questions_completed + r.verified_questions_uncompleted, 0) * 100), 2) AS verified_regeneration_percentage,
                /* All questions */
                r.completed,
                r.uncompleted,
                ROUND((r.completed::DECIMAL / NULLIF(r.completed + r.uncompleted, 0) * 100), 2) AS regeneration_percentage
              FROM regeneration_amount_by_status r;
            END; $$;


ALTER FUNCTION odiseo.fn_get_regeneration_pdfs_progress(p_since_date date) OWNER TO postgres;

--
-- Name: fn_get_report_missing_question_exam(bigint, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_report_missing_question_exam(p_material_id bigint, p_type_material_id smallint, p_week smallint) RETURNS TABLE(material_id bigint, type_material character varying, url_excel character varying, missing jsonb)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            SELECT
                dwtm.id,
                tm.description AS type_material,
                NULL::VARCHAR AS url_excel_exam,
                jsonb_agg(
                    jsonb_build_object(
                        'area_id', meaw.area_id,
                        'data_incomplete_questions', meaw.data_incomplete_questions
                    )
                ) AS missing
            FROM detail_week_type_mat dwtm
            JOIN type_material tm ON dwtm.type_material_id = tm.id
            JOIN material_exam_area_week meaw ON meaw.week_type_material_id = dwtm.id
                AND meaw.fl_status = true
            WHERE dwtm.material_id = p_material_id
                AND dwtm.type_material_id = p_type_material_id
                AND dwtm.week = p_week
                AND dwtm.fl_status = true
            GROUP BY dwtm.id,
                tm.description;
        END;
        $$;


ALTER FUNCTION odiseo.fn_get_report_missing_question_exam(p_material_id bigint, p_type_material_id smallint, p_week smallint) OWNER TO postgres;

--
-- Name: fn_get_report_missing_text_exam(integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_report_missing_text_exam(p_material_id integer, p_type_material_id integer, p_week integer) RETURNS TABLE(course_id smallint, course character varying, material_exam_id integer, area character varying, type_text_id smallint, type_text_subcategory_id smallint, category character varying, subcategory character varying, topics jsonb)
    LANGUAGE plpgsql
    AS $$
                            BEGIN
                            RETURN QUERY
                            WITH material_data AS (
                                SELECT m.cycle_id, m.university_id 
                                FROM material m
                                WHERE m.id = p_material_id
                            ),
                            all_areas AS (
                                SELECT meaw.id material_exam_id, ea.description area, meaw.area_id FROM odiseo.detail_week_type_mat AS dwtm
                                JOIN material_exam_area_week meaw ON meaw.week_type_material_id = dwtm.id
                                JOIN exam_area ea ON ea.id = meaw.area_id 
                                WHERE dwtm.type_material_id = p_type_material_id and dwtm.week = p_week
                                AND dwtm.material_id = p_material_id
                            ),
                            type_exam AS (
                                SELECT DISTINCT te.name type  FROM material_exam_area_week meaw 
                                JOIN detail_week_type_mat dwtm ON dwtm.id = meaw.week_type_material_id 
                                JOIN type_material tm ON tm.id = dwtm.type_material_id 
                                JOIN type_material_template tmt ON tmt.id = tm.type_material_template_id 
                                JOIN type_exams te ON te.id = tmt.type_exam_id 
                                WHERE dwtm.type_material_id = p_type_material_id and dwtm.week = p_week
                                AND dwtm.material_id = p_material_id
                                LIMIT 1
                            ),
                            special_courses AS (
                                SELECT c.id FROM course c WHERE c.apply_text = TRUE
                            ),
                            syllabus_main AS (
                                SELECT s.id, s.course_id , c."name" course
                                FROM syllabus s 
                                JOIN course c ON c.id = s.course_id 
                                WHERE s.cycle_id = (SELECT cycle_id FROM material_data)
                                AND s.university_id = (SELECT university_id FROM material_data)
                                AND s.fl_status = true
                                AND s.course_id IN (select sc.id from special_courses sc)
                            ), 
                            syllabus_by_week AS (
                                SELECT 
                                    stw.*, 
                                    sm.course, 
                                    sm.course_id 
                                FROM syllabus_text_weeks stw
                                JOIN syllabus_main sm ON sm.id = stw.syllabus_id
                                CROSS JOIN type_exam te 
                                WHERE stw.fl_status = true
                                AND (
                                    (te.type = 'Tipo 1' AND stw.week = p_week)
                                    OR
                                    (te.type = 'Tipo 2' AND stw.week <= p_week)
                                )
                            ),
                            syllabus_by_categories AS (
                                SELECT DISTINCT 
                                    st.type_text_id, 
                                    st.type_text_subcategory_id, 
                                    tt."name" AS category,  
                                    tts."name" AS subcategory,
                                    sbw.course ,
                                    sbw.course_id 
                                FROM syllabus_text_distributions std 
                                JOIN syllabus_by_week sbw ON sbw.id = std.syllabus_text_week_id 
                                JOIN syllabus_texts st ON st.syllabus_text_distribution_id = std.id AND st.fl_status = true
                                JOIN type_text tt ON tt.id = st.type_text_id 
                                JOIN type_text_subcategories tts ON tts.id = st.type_text_subcategory_id 
                                ORDER BY sbw.course_id
                            ),
                            syllabus_topics_and_subtopics AS (
                                SELECT DISTINCT stc.subtopic_id, s."name" subtopic, t.id topic_id, t."name" topic, sbw.course , sbw.course_id 
                                FROM syllabus_text_distributions std 
                                JOIN syllabus_by_week sbw ON sbw.id = std.syllabus_text_week_id 
                                JOIN syllabus_texts st ON st.syllabus_text_distribution_id = std.id AND st.fl_status = true
                                JOIN type_text tt ON tt.id = st.type_text_id 
                                JOIN syllabus_text_content stc ON st.id = stc.syllabus_text_id AND stc.fl_status = true
                                JOIN subtopic s ON s.id = stc.subtopic_id 
                                JOIN topic t ON t.id = s.topic_id 
                            ),
                            unique_categories AS (
                                SELECT DISTINCT sbc.type_text_id, sbc.category, sbc.course_id, sbc.course 
                                FROM syllabus_by_categories sbc
                            ),
                            unique_subcategories AS (
                                SELECT DISTINCT sbc.type_text_subcategory_id, sbc.subcategory, sbc.course_id, sbc.course 
                                FROM syllabus_by_categories sbc
                            ),
                            full_matrix AS (
                                SELECT 
                                    c.type_text_id,
                                    s.type_text_subcategory_id,
                                    c.category,
                                    s.subcategory,
                                    c.course,
                                    c.course_id 
                                FROM unique_categories c
                                CROSS JOIN unique_subcategories s
                                WHERE c.course_id = s.course_id 
                            ),
                            selected_text AS (
                                SELECT 
                                    pq.type_text_id, 
                                    pq.type_text_subcategory_id,
                                    aa.material_exam_id,
                                    aa.area,
                                    aa.area_id
                                FROM material_exam_parent_question mepq 
                                JOIN parent_question pq ON pq.id = mepq.parent_question_id 
                                JOIN all_areas aa ON aa.material_exam_id = mepq.material_exam_area_week_id
                                WHERE mepq.deleted_at IS NULL
                            ),
                            all_mix_area AS (
                                SELECT * FROM full_matrix fm
                                CROSS JOIN all_areas aa
                            )
                            SELECT
                                ama.course_id::smallint,
                                ama.course,
                                ama.material_exam_id::integer,
                                ama.area,
                                ama.type_text_id::smallint, 
                                ama.type_text_subcategory_id::smallint,
                                ama.category,
                                ama.subcategory,
                                (SELECT jsonb_agg(
                                            json_build_object(
                                                'topic', stas.topic,
                                                'subtopic', stas.subtopic 
                                            )
                                        )
                                FROM syllabus_topics_and_subtopics stas
                                WHERE stas.course_id = ama.course_id) topics
                            FROM all_mix_area ama
                            WHERE NOT EXISTS (
                                SELECT 1 
                                FROM selected_text st 
                                WHERE st.type_text_id = ama.type_text_id 
                                AND st.type_text_subcategory_id = ama.type_text_subcategory_id
                                AND st.material_exam_id = ama.material_exam_id 
                            )
                            AND EXISTS (
                                SELECT 1
                                FROM material_exam_parent_question mepq_check
                                WHERE mepq_check.material_exam_area_week_id = ama.material_exam_id
                                AND mepq_check.course_id = ama.course_id
                                AND mepq_check.parent_question_id IS NULL
                                AND mepq_check.deleted_at IS NULL
                            )
                            ORDER BY ama.course_id, ama.area_id, ama.type_text_id, ama.type_text_subcategory_id;

                            END;
                        $$;


ALTER FUNCTION odiseo.fn_get_report_missing_text_exam(p_material_id integer, p_type_material_id integer, p_week integer) OWNER TO postgres;

--
-- Name: fn_get_search_employees(integer, integer, character varying, boolean, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_search_employees(p_perpage integer, p_npage integer, p_name_text character varying, f_status boolean, f_charge_id integer, p_company_id integer) RETURNS TABLE(id bigint, uuid uuid, charge_id bigint, name_charge character varying, type_document character varying, document character varying, courses json, code character varying, first_name text, last_name text, level_id bigint, level_name character varying, goal integer, cost_per_question numeric, email text, phone character varying, fl_status boolean, created_at timestamp without time zone, total_count bigint)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            offset_val INTEGER;
        BEGIN
            offset_val := p_perpage * (p_npage - 1);

            RETURN QUERY
            WITH tbl_employee as (
                SELECT
                    e.id,
                    e.uuid,
                    e.charge_id,
                    c.name as name_charge,
                    tp."name" as type_document,
                    e.document,
                    COALESCE(json_agg(c2.name) FILTER (WHERE c2.name IS NOT NULL), '[]') AS courses,
                    e.code AS code,
                    UPPER(e.first_name) AS first_name,
                    CONCAT(e.first_surname,' ', e.second_surname) AS last_name,
                    e.level_id,
                    lr.level_name as level_name,
                    e.goal,
                    lr.cost_per_question,
                    LOWER(e.email) as email,
                    e.phone,
                    e.fl_status,
                    e.created_at
                FROM
                    employees e
                LEFT JOIN public.type_documents tp ON e.type_document_id = tp.id
                LEFT JOIN charge c ON e.charge_id = c.id
                LEFT JOIN employee_course ec ON ec.teacher_id = e.id AND ec.fl_status = true
                LEFT JOIN course c2 ON ec.course_id = c2.id
                LEFT JOIN level_rates lr ON e.level_id = lr.id
                WHERE 1 = 1
                AND e.fl_status = true
                AND (p_company_id IS NULL OR e.company_id = p_company_id)
                AND (f_status IS NULL OR e.fl_status = f_status)
                AND (f_charge_id is NULL or e.charge_id = f_charge_id)
                AND (
                    p_name_text IS NULL
                    OR e.document ILIKE '%' || p_name_text || '%'
                    OR e.first_name ILIKE '%' || p_name_text || '%'
                    OR e.first_surname ILIKE '%' || p_name_text || '%'
                    OR COALESCE(e.second_surname, '') ILIKE '%' || p_name_text || '%'
                    OR CONCAT(e.first_name, ' ', e.first_surname) ILIKE '%' || p_name_text || '%'
                )
                GROUP BY
                    e.id,
                    e.uuid,
                    e.charge_id,
                    c.name,
                    tp.name,
                    e.document,
                    e.code,
                    e.first_name,
                    e.first_surname,
                    e.second_surname,
                    e.level_id,
                    lr.level_name,
                    e.goal,
                    lr.cost_per_question,
                    e.email,
                    e.phone,
                    e.fl_status,
                    e.created_at
            )
            SELECT *, count(*) OVER () AS total_count
            FROM tbl_employee as tbl
            ORDER by  tbl.first_name asc, CASE when tbl.fl_status THEN 0 ELSE 1 END asc, tbl.created_at desc
            LIMIT p_perpage
            OFFSET offset_val;
        END;
        $$;


ALTER FUNCTION odiseo.fn_get_search_employees(p_perpage integer, p_npage integer, p_name_text character varying, f_status boolean, f_charge_id integer, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_get_search_exam_areas(integer, integer, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_search_exam_areas(p_perpage integer, p_npage integer, p_search character varying) RETURNS TABLE(id smallint, exam_area character varying, description character varying, created_at timestamp without time zone, created_by text, total bigint)
    LANGUAGE plpgsql
    AS $$
                DECLARE
                    offset_val INTEGER;
                BEGIN
                    -- Calcula el offset para la paginación
                    offset_val := p_perpage * (p_npage - 1);

                    RETURN QUERY
                    WITH tbl_exam_area AS (
                        SELECT 
                            ea.id,
                            ea.description AS exam_area,
                            ea.short_description AS description,
                            ea.created_at,
                            CASE
                                WHEN e.first_name IS NOT NULL AND e.first_surname IS NOT NULL THEN
                                    CONCAT(
                                        e.first_name, ' ',
                                        upper(left(e.first_surname, 1)), '. ',
                                        e.second_surname
                                    )
                                ELSE 'Administrador'
                            END AS created_by
                        FROM
                            odiseo.exam_area ea
                        LEFT JOIN odiseo.users u
                            ON u.id = ea.created_by
                        LEFT JOIN odiseo.employees e
                            ON e.user_id = u.id
                        WHERE
                            ea.fl_status = TRUE
                            AND (
                                p_search IS NULL OR
                                LOWER(ea.description) LIKE '%' || LOWER(p_search) || '%'
                            )
                    )
                    SELECT
                        tbl_exam_area.id,
                        tbl_exam_area.exam_area,
                        tbl_exam_area.description,
                        tbl_exam_area.created_at,
                        tbl_exam_area.created_by,
                        COUNT(*) OVER () AS total
                    FROM
                        tbl_exam_area
                    ORDER BY
                        created_at DESC
                    LIMIT p_perpage
                    OFFSET offset_val;
                END;
            $$;


ALTER FUNCTION odiseo.fn_get_search_exam_areas(p_perpage integer, p_npage integer, p_search character varying) OWNER TO postgres;

--
-- Name: fn_get_structure_by_course_ids(jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_structure_by_course_ids(course_ids_json jsonb) RETURNS TABLE(unification json)
    LANGUAGE plpgsql
    AS $$
    DECLARE
        v_cid1 INTEGER;
        v_cid2 INTEGER;
    BEGIN
        SELECT value::int INTO v_cid1 FROM jsonb_array_elements_text(course_ids_json) WITH ORDINALITY WHERE ordinality = 1;
        SELECT value::int INTO v_cid2 FROM jsonb_array_elements_text(course_ids_json) WITH ORDINALITY WHERE ordinality = 2;

        RETURN QUERY
        SELECT 
            COALESCE(json_agg(
                json_build_object(
                    'uuid', n1.uuid,
                    
                    'first_course_id', n1.course_id,
                    'first_topic_id', n1.topic_id,
                    'first_last_name_topic', n1.last_name_topic,
                    'first_new_name_topic', n1.new_name_topic,
                    'first_subtopic_id', n1.subtopic_id,
                    'first_last_name_subtopic', n1.last_name_subtopic,
                    'first_new_name_subtopic', n1.new_name_subtopic,
                    
                    'second_course_id', n2.course_id,
                    'second_topic_id', n2.topic_id,
                    'second_last_name_topic', n2.last_name_topic,
                    'second_new_name_topic', n2.new_name_topic,
                    'second_subtopic_id', n2.subtopic_id,
                    'second_last_name_subtopic', n2.last_name_subtopic,
                    'second_new_name_subtopic', n2.new_name_subtopic
                )
            ), '[]'::json)
        
        FROM network_course_topic_subtopic n1
        INNER JOIN network_course_topic_subtopic n2 ON n1.uuid = n2.uuid
        WHERE n1.course_id = v_cid1
          AND n2.course_id = v_cid2;

    END;
    $$;


ALTER FUNCTION odiseo.fn_get_structure_by_course_ids(course_ids_json jsonb) OWNER TO postgres;

--
-- Name: fn_get_sub_question_verified_and_not_excluded_material_filter(integer, integer, integer, bigint, integer, integer, character varying, integer, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_sub_question_verified_and_not_excluded_material_filter(p_perpage integer, p_npage integer, p_parent_question_id integer, p_material_id bigint, p_topic_id integer, p_subtopic_id integer, p_search character varying, p_distribution_id integer, p_status character varying) RETURNS TABLE(code text, parent_id bigint, topic_id integer, topic character varying, question_id bigint, course_id smallint, course text, subtopics jsonb, history jsonb, status character varying, total_count bigint)
    LANGUAGE plpgsql
    AS $$
                    DECLARE
                        offset_val INTEGER;
                        v_fl_exam BOOLEAN;
                    BEGIN
                        offset_val := p_perpage * (p_npage - 1);

                        RETURN QUERY
                        WITH subquestion_cte AS (
                            SELECT 
                                subq->>'code' AS code,
                                fpqvm.parent_id,
                                (subq->>'topic_id')::int AS topic_id,
                                t.name AS topic_name,
                                (subq->>'question_id')::bigint AS question_id,
                                fpqvm.course_id AS course_id,
                                CONCAT(c.code, '-', c.name) AS course,
                                (
                                    SELECT jsonb_agg(
                                            jsonb_build_object(
                                                'id', (st_json->>'id')::int,
                                                'name', st.name
                                            )
                                        )
                                    FROM jsonb_array_elements(subq->'subtopics') st_json
                                    LEFT JOIN subtopic st ON (st_json->>'id')::int = st.id
                                ) AS subtopics,
                                fpqvm.history,
                                q.status
                            FROM fn_parent_question_verified_material(p_material_id, 'S') fpqvm
                            CROSS JOIN LATERAL jsonb_array_elements(fpqvm.subquestion::jsonb) subq
                            JOIN course c ON fpqvm.course_id = c.id
                            JOIN topic t ON (subq->>'topic_id')::int = t.id
                            JOIN question q ON q.id = (subq->>'question_id')::bigint
                            WHERE fpqvm.parent_id = p_parent_question_id
                            AND (p_topic_id IS NULL OR (subq->>'topic_id')::int = p_topic_id)
                                                AND (
                                p_subtopic_id IS NULL OR EXISTS (
                                    SELECT 1
                                    FROM jsonb_array_elements(subq->'subtopics') st_json
                                    WHERE (st_json->>'id')::int = p_subtopic_id
                                )
                            )
                            AND (p_search IS NULL OR subq->>'code' ILIKE '%' || p_search || '%')
                            AND (p_status IS NULL OR q.status = p_status)
                        ), question_found_cte AS (
                            SELECT 
                                mbs.question_id::int AS question_id
                            FROM material_ballot_subquestions mbs
                            WHERE mbs.material_ballot_question_id = p_distribution_id
                            AND mbs.state = 'GENERATED'
                            AND mbs.fl_status = TRUE
                        ), validate_subquestion_cte AS (
                            SELECT sc.*
                            FROM subquestion_cte sc
                            LEFT JOIN question_found_cte qfc 
                            ON sc.question_id = qfc.question_id
                            WHERE qfc.question_id IS NULL
                        )
                        SELECT vsc.*, COUNT(*) OVER () AS total_count
                        FROM validate_subquestion_cte as vsc
                        LIMIT p_perpage
                        OFFSET offset_val;

                    END;
                $$;


ALTER FUNCTION odiseo.fn_get_sub_question_verified_and_not_excluded_material_filter(p_perpage integer, p_npage integer, p_parent_question_id integer, p_material_id bigint, p_topic_id integer, p_subtopic_id integer, p_search character varying, p_distribution_id integer, p_status character varying) OWNER TO postgres;

--
-- Name: fn_get_subcategories_by_category(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_subcategories_by_category(p_assigned_cat_id bigint) RETURNS TABLE(id bigint, subcategory_name character varying, subcategory_assigned_id bigint)
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                        RETURN QUERY
                        SELECT tts.id, tts.name AS subcategory_name, s.id AS subcategory_assigned_id
                        FROM course_assigned_subcategories s
                        JOIN type_text_subcategories tts ON s.subcategory_id = tts.id
                        WHERE s.course_assigned_category_id = p_assigned_cat_id 
                        AND s.deleted_at IS NULL;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_get_subcategories_by_category(p_assigned_cat_id bigint) OWNER TO postgres;

--
-- Name: fn_get_subcategories_by_course(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_subcategories_by_course(p_course_id bigint, p_assigned_category_id bigint) RETURNS TABLE(id bigint, subcategory_name character varying)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                WITH excluded_subcategory_names AS (
                    SELECT tts."name"
                    FROM course_assigned_subcategories cas
                    JOIN type_text_subcategories tts ON tts.id = cas.subcategory_id 
                    WHERE cas.course_assigned_category_id = p_assigned_category_id
                    AND cas.deleted_at IS NULL
                ) 
                SELECT DISTINCT tts.id, tts."name" AS subcategory_name
                FROM course_assigned_categories cac
                JOIN course_assigned_subcategories cas ON cas.course_assigned_category_id = cac.id
                JOIN type_text_subcategories tts ON tts.id = cas.subcategory_id 
                WHERE cac.course_id = p_course_id
                AND cac.id != p_assigned_category_id
                AND cac.deleted_at IS NULL 
                AND cas.deleted_at IS NULL
                AND tts."name" NOT IN (SELECT "name" FROM excluded_subcategory_names)
                ORDER BY tts.id;
            END;
            $$;


ALTER FUNCTION odiseo.fn_get_subcategories_by_course(p_course_id bigint, p_assigned_category_id bigint) OWNER TO postgres;

--
-- Name: fn_get_syllabus(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_syllabus(p_syllabus_id bigint, p_company_id bigint) RETURNS TABLE(id bigint, university_id smallint, code_university character varying, slug_university character varying, university character varying, course_id bigint, apply_text_on_syllabus boolean, pseudo_course_id bigint, code_course character varying, course character varying, cycle_id bigint, code_cycle character varying, cycle character varying, weeks smallint, start_date date, end_date date, syllabus jsonb, syllabus_week_titles jsonb, type_text_template_id smallint)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_university_id SMALLINT;
    v_course_id BIGINT;
    v_pseudo_course_id BIGINT;
BEGIN
    SELECT syl.university_id, syl.course_id, syl.pseudo_course_id
    INTO v_university_id, v_course_id, v_pseudo_course_id
    FROM syllabus syl
    WHERE syl.id = p_syllabus_id
    AND syl.company_id = p_company_id
    LIMIT 1;

    RETURN QUERY
    WITH tbl_syllabus_all_topic AS (
        SELECT DISTINCT
            NULL::BIGINT AS syllabus_topic_id,
            p_syllabus_id AS syllabus_id,
            st.university_id,
            st.course_id,
            st.pseudo_course_id,
            stt.topic_id,
            t.code,
            t.name
        FROM syllabus_template st
        INNER JOIN syllabus_template_topic stt ON st.id = stt.syllabus_template_id AND stt.fl_status IS TRUE
        INNER JOIN topic t ON stt.topic_id = t.id AND t.fl_status = true
        WHERE st.university_id = v_university_id
        AND (v_course_id IS NULL OR st.course_id = v_course_id)
        AND (v_pseudo_course_id IS NULL OR st.pseudo_course_id = v_pseudo_course_id)
        AND st.company_id = p_company_id
        AND st.fl_status = true
        UNION ALL
        SELECT DISTINCT
            st.id AS syllabus_topic_id,
            st.syllabus_id,
            v_university_id AS university_id,
            v_course_id AS course_id,
            null::bigint AS pseudo_course_id,
            st.topic_id,
            t.code,
            t.name
        FROM syllabus_topic st
        JOIN syllabus_template_topic stp ON stp.topic_id = st.topic_id AND stp.fl_status IS TRUE
        INNER JOIN syllabus_topic_week stw ON st.id = stw.syllabus_topic_id AND stw.fl_status = true
        LEFT JOIN topic t ON st.topic_id = t.id
        WHERE st.syllabus_id = p_syllabus_id
        AND st.company_id = p_company_id
        AND st.fl_status = true
    ), 
    tbl_syllabus_topic AS (
        SELECT *,
            ROW_NUMBER() OVER (PARTITION BY tsat.topic_id ORDER BY syllabus_topic_id ASC NULLS LAST) AS row_num
        FROM tbl_syllabus_all_topic tsat
    ), 
    tbl_syllabus_duplicate AS (
        SELECT DISTINCT tstd.*
        FROM tbl_syllabus_topic tstd
        WHERE tstd.row_num = 1
        ORDER BY tstd.code ASC
    )
    SELECT
        s.id,
        s.university_id,
        u.code AS code_university,
        u.slug AS slug_university,
        u.name AS university,
        s.course_id,
        co.apply_text AS apply_text_on_syllabus,
        s.pseudo_course_id,
        CASE WHEN s.pseudo_course_id IS NULL THEN co.code ELSE pco.code END AS course_code,
        CASE WHEN s.pseudo_course_id IS NULL THEN co.name ELSE pco.name END AS course,
        s.cycle_id,
        cy.code AS code_cycle,
        cy.description AS cycle,
        cy.weeks,
        cy.start_date,
        cy.end_date,
        COALESCE(sub_topics.syllabus_json, '[]'::jsonb) AS syllabus,
        COALESCE(sub_weeks.weeks_json, '[]'::jsonb) AS syllabus_week_titles,
        co.type_text_template_id
    FROM syllabus s
    INNER JOIN origin_university u ON s.university_id = u.id
    LEFT JOIN course co ON s.course_id = co.id
    LEFT JOIN pseudo_course pco ON s.pseudo_course_id = pco.id
    INNER JOIN cycle cy ON s.cycle_id = cy.id
    LEFT JOIN LATERAL (
        SELECT jsonb_agg(
            jsonb_build_object(
                'id', tst.syllabus_topic_id,
                'syllabus_id', tst.syllabus_id,
                'topic_id', tst.topic_id,
                'code_topic', tst.code,
                'topic', tst.name,
                'weeks', ''
            )
        ) AS syllabus_json
        FROM tbl_syllabus_duplicate tst
        WHERE tst.syllabus_id = s.id
    ) sub_topics ON true
    LEFT JOIN LATERAL (
        SELECT 
            jsonb_agg(
                jsonb_build_object(
                    'week_id', cw.week,
                    'title', swt.title,
                    'type_week', tw.description,
                    'short_week_name', CONCAT_WS('-', cw.week, LEFT(tw.description, 1)),
                    'week_name', CONCAT_WS('-', cw.week, tw.description),
                    'type_week_id', tw.id
                ) ORDER BY cw.week
            ) AS weeks_json
        FROM cycle_weeks cw
        JOIN type_week tw 
            ON tw.id = cw.type_week_id 
            AND tw.fl_status = true AND tw.id != 5
        LEFT JOIN syllabus_week_titles swt 
            ON swt.week = cw.week
            AND swt.syllabus_id = s.id
            AND swt.fl_status = true
        WHERE cw.cycle_id = s.cycle_id
        AND cw.fl_status = true
    ) sub_weeks ON true
    WHERE s.id = p_syllabus_id
    AND s.company_id = p_company_id;
END;
$$;


ALTER FUNCTION odiseo.fn_get_syllabus(p_syllabus_id bigint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_get_syllabus_all_text_weeks(integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_syllabus_all_text_weeks(p_cycle_id integer, p_company_id integer, p_course_id integer) RETURNS TABLE(category character varying, category_id bigint, weeks jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH categories AS (
        SELECT tt.id, tt.name
        FROM course_assigned_categories cac
        JOIN type_text tt ON tt.id = cac.type_text_id AND cac.course_id = p_course_id
        WHERE cac.deleted_at IS NULL
        AND tt.fl_status = true
    ),
    cycle_weeks AS (
        SELECT cy.weeks
        FROM cycle cy
        WHERE cy.id = p_cycle_id
        AND cy.company_id = p_company_id
    ),
    weeks AS (
        SELECT generate_series(1, (SELECT cw.weeks FROM cycle_weeks cw)) AS week
    ),
    category_weeks AS (
        SELECT 
            c.id,
            c.name,
            w.week
        FROM categories c
        CROSS JOIN weeks w
    )

    SELECT
        cw.name AS category,
        cw.id AS category_id,
        jsonb_agg(
            jsonb_build_object(
                'week', cw.week,
                'subcategories', '[]'::jsonb
            )
            ORDER BY cw.week
        ) AS weeks
    FROM category_weeks cw
    GROUP BY cw.id, cw.name
    ORDER BY cw.id;
END;
$$;


ALTER FUNCTION odiseo.fn_get_syllabus_all_text_weeks(p_cycle_id integer, p_company_id integer, p_course_id integer) OWNER TO postgres;

--
-- Name: fn_get_syllabus_template_by_university_and_course(smallint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_syllabus_template_by_university_and_course(p_university_id smallint, p_course_id smallint, p_company_id bigint) RETURNS TABLE(id smallint)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            SELECT
                st.id
            FROM syllabus_template st
            WHERE 1 = 1
                AND st.university_id = p_university_id
                AND st.course_id = p_course_id
                AND st.fl_status IS TRUE
                AND st.company_id = p_company_id
            ORDER BY st.id DESC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_get_syllabus_template_by_university_and_course(p_university_id smallint, p_course_id smallint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_get_syllabus_template_subtopics(integer, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_syllabus_template_subtopics(p_syllabus_template_topic_id integer, p_company_id bigint) RETURNS TABLE(syllabus_template_topic_subtopic_id bigint, subtopic_id smallint, subtopic_code character varying, name text)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
                SELECT
                    stst.id,
                    stst.subtopic_id,
                    subtop.code AS subtopic_code,
                    CONCAT(subtop.code, ' - ', subtop.name) AS name
                FROM syllabus_template_topic stt
                INNER JOIN syllabus_template_topic_subtopic stst ON stst.syllabus_template_topic_id = stt.id
                    AND stst.fl_status IS true
                    AND stst.company_id = p_company_id
                INNER JOIN subtopic subtop ON subtop.id = stst.subtopic_id
                    AND subtop.fl_status IS true
                WHERE 1 = 1
                    AND stt.id = p_syllabus_template_topic_id
                    AND stt.company_id = p_company_id
                ORDER BY stst.id DESC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_get_syllabus_template_subtopics(p_syllabus_template_topic_id integer, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_get_syllabus_template_topics(integer, integer, boolean, integer, integer, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_syllabus_template_topics(p_university_id integer, p_course_id integer, p_fl_pseudo boolean, p_category_id integer, p_type_text_subcategory_id integer, p_company_id bigint) RETURNS TABLE(syllabus_template_topic_id integer, topic_id smallint, topic_code character varying, name text, category_id bigint, subcategory_id bigint)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY
                    WITH template_topics AS (
                        SELECT
                            stt.id AS syllabus_template_topic_id,
                            stt.topic_id as topic_id,
                            t.code AS topic_code,
                            CONCAT(t.code, ' - ', t.name) AS name,
                            ttt.type_text_id category_id,
                            cas.subcategory_id subcategory_id
                        FROM syllabus_template st
                        INNER JOIN syllabus_template_topic stt ON stt.syllabus_template_id = st.id
                            AND stt.fl_status IS true
                            AND stt.company_id = p_company_id
                        INNER JOIN topic t ON t.id = stt.topic_id
                        LEFT JOIN type_texts_topics ttt ON ttt.topic_id = stt.topic_id
                            AND ttt.type_text_id = p_category_id
                        LEFT JOIN course_assigned_categories cac ON cac.type_text_id = ttt.type_text_id
                            AND cac.course_id = p_course_id
                        LEFT JOIN course_assigned_subcategories cas ON cas.course_assigned_category_id = cac.id
                        WHERE st.university_id = p_university_id
                            AND (
                                (p_fl_pseudo = TRUE AND st.pseudo_course_id = p_course_id)
                                OR
                                (p_fl_pseudo = FALSE AND st.course_id = p_course_id)
                            )
                            AND (p_category_id IS NULL OR ttt.type_text_id = p_category_id)
                            AND (p_type_text_subcategory_id IS NULL OR cas.subcategory_id = p_type_text_subcategory_id)
                            AND st.fl_status IS true
                            AND CASE
                                    WHEN p_course_id NOT IN (6, 13) THEN cas.id IS NULL
                                    ELSE TRUE
                                END
                            AND st.company_id = p_company_id

                        UNION ALL

                        -- Segundo SELECT
                        SELECT
                            stt.id AS syllabus_template_topic_id,
                            stt.topic_id as topic_id,
                            t.code AS topic_code,
                            CONCAT(t.code, ' - ', t.name) AS name,
                            NULL::bigint  category_id,
                            NULL::bigint  subcategory_id
                        FROM syllabus_template st
                        INNER JOIN syllabus_template_topic stt ON st.id = stt.syllabus_template_id
                            AND stt.fl_status IS TRUE
                            AND stt.company_id = p_company_id
                        INNER JOIN topic t ON t.id = stt.topic_id
                        WHERE st.university_id = p_university_id
                            AND (
                                (p_fl_pseudo = TRUE AND st.pseudo_course_id = p_course_id)
                                OR
                                (p_fl_pseudo = FALSE AND st.course_id = p_course_id)
                            )
                            AND stt.topic_id IN (
                                SELECT
                                    st3.topic_id
                                FROM syllabus_topic st3
                                JOIN syllabus s ON st3.syllabus_id = s.id
                                WHERE st3.fl_status = TRUE
                                    AND st3.is_topic_deleted = TRUE
                                    AND s.university_id = p_university_id
                                    AND (
                                        (p_fl_pseudo = TRUE AND s.pseudo_course_id = p_course_id)
                                        OR
                                        (p_fl_pseudo = FALSE AND s.course_id = p_course_id)
                                    )
                            )
                            AND st.company_id = p_company_id
                    )
                    SELECT
                        *
                    FROM template_topics tt
                    ORDER BY CAST(tt.topic_code AS INTEGER);
                END;
                $$;


ALTER FUNCTION odiseo.fn_get_syllabus_template_topics(p_university_id integer, p_course_id integer, p_fl_pseudo boolean, p_category_id integer, p_type_text_subcategory_id integer, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_get_syllabus_week_title(integer, integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_syllabus_week_title(p_material_id integer, p_week_id integer, p_course_id integer, p_type_material_id integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $$

            DECLARE
                v_type_material_template_id INT;
                v_university_id INT;
                v_cycle_id INT;
                v_syllabus_week_title CHARACTER VARYING;
            BEGIN

                SELECT tm.type_material_template_id
                INTO v_type_material_template_id
                FROM odiseo.type_material tm
                WHERE tm.id = p_type_material_id AND tm.fl_status = TRUE;

                IF v_type_material_template_id = 4 THEN  -- 4  es el id del Material Template Boletin
                    SELECT m.university_id, m.cycle_id
                    INTO v_university_id, v_cycle_id
                    FROM odiseo.material m
                    WHERE m.id = p_material_id;
                    SELECT swt.title
                    INTO v_syllabus_week_title
                    FROM odiseo.syllabus s
                    JOIN odiseo.syllabus_week_titles swt
                    ON s.id = swt.syllabus_id
                    WHERE s.university_id = v_university_id
                    AND s.cycle_id = v_cycle_id
                    AND s.course_id = p_course_id
                    AND s.fl_status = TRUE
                    AND swt.fl_status = TRUE
                    AND swt.week = p_week_id;
                ELSE
                    v_syllabus_week_title := NULL;

                END IF ;

                RETURN v_syllabus_week_title;
            END;
        $$;


ALTER FUNCTION odiseo.fn_get_syllabus_week_title(p_material_id integer, p_week_id integer, p_course_id integer, p_type_material_id integer) OWNER TO postgres;

--
-- Name: fn_get_teacher_nq_list_course(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_teacher_nq_list_course(p_teacher_id integer) RETURNS TABLE(id smallint, code character varying, name text, name_course character varying)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT 
                    DISTINCT
                    c.id, 
                    c.code, 
                    CONCAT(c.code, ' - ', c.name) AS name, 
                    c.name AS name_course 
                FROM employee_course ec
                LEFT JOIN course c ON ec.course_id = c.id
                WHERE ec.fl_status = true
                AND c.alias_nq IS NOT NULL
                AND (p_teacher_id IS NULL OR ec.teacher_id = p_teacher_id)
                ORDER BY c.code ASC, c.name ASC;
            END;
        $$;


