CREATE FUNCTION odiseo.fn_get_token_user(p_user_id bigint) RETURNS TABLE(id bigint, tokenable_id bigint, token text, revoked boolean, expires_at timestamp without time zone, created_at timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
        BEGIN
