--
-- Name: fn_get_type_material(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_type_material(p_type_material_id integer) RETURNS TABLE(id smallint, code character varying, description character varying, type_material_template_id bigint, type_material_template character varying, amount_question integer, areas jsonb, cycle_id bigint, cycle_name character varying, fl_status boolean, fl_exam boolean, fl_class_material boolean, thread smallint, level_order boolean, percentage numeric, courses jsonb, weeks jsonb, children_ids jsonb, periodicity_id smallint, periodicity character varying, quantity_week smallint, start_week smallint, group_previous_week boolean, group_remaining_week boolean)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_ids_children INT[];
    v_fl_exam BOOLEAN;
BEGIN
    SELECT tm.fl_exam INTO v_fl_exam 
    FROM type_material tm 
    WHERE tm.id = p_type_material_id;

    SELECT ARRAY(SELECT tm.id FROM type_material tm WHERE tm.parent_id = p_type_material_id) INTO v_ids_children;
    
    IF array_length(v_ids_children, 1) IS NULL THEN
        v_ids_children := ARRAY[p_type_material_id];
    END IF;

    IF v_fl_exam THEN
        RETURN QUERY
        WITH tbl_area_exam_courses AS (
            SELECT
                tbl_area_courses.course_id,
                tbl_area_courses.course,
                tbl_area_courses.area_id,
                tbl_area_courses.type_material_id,
                COALESCE(tbl_courses.amount_question, 0) AS amount_question,
                COALESCE(tbl_courses.amount_text, 0) AS amount_text,
                tbl_area_courses.apply_text
            FROM (
                SELECT
                    c.code || ' - ' || c.name AS course,
                    c.id AS course_id,
                    tma.area_id,
                    tma.type_material_id,
                    c.apply_text
                FROM course c
                CROSS JOIN type_material_area tma
                WHERE tma.type_material_id = p_type_material_id 
                  AND c.fl_status = TRUE 
                  AND tma.fl_status = TRUE
                ORDER BY c.name, tma.area_id
            ) AS tbl_area_courses
            LEFT JOIN (
                SELECT tmc.course_id, tma.area_id, tmc.amount_question, tmc.amount_text
                FROM type_material_area_courses tmac
                LEFT JOIN type_material_course tmc
                    ON tmac.type_material_course_id = tmc.id AND tmc.fl_status = TRUE
                LEFT JOIN type_material_area tma
                    ON tmac.type_material_area_id = tma.id
                WHERE tmc.type_material_id = p_type_material_id
            ) AS tbl_courses
            ON tbl_area_courses.course_id = tbl_courses.course_id
            AND tbl_area_courses.area_id = tbl_courses.area_id
        )
        SELECT
            t.id,
            t.code,
            t.description,
            t.type_material_template_id,
            tmt.name AS type_material_template,
            t.amount_question,
            COALESCE(
                jsonb_agg(DISTINCT jsonb_build_object('id', tma.area_id, 'description', a.description))
                FILTER (WHERE tma.area_id IS NOT NULL AND tma.fl_status = TRUE AND a.description IS NOT NULL AND a.fl_status = TRUE),
                '[]'::jsonb
            ) AS areas,
            t.cycle_id,
            c.description AS cycle_name,
            t.fl_status,
            t.fl_exam,
            t.fl_class_material,
            t.thread,
            t.level_order,
            t.percentage,
            COALESCE(
                jsonb_agg(DISTINCT jsonb_build_object(
                    'id', tblexamcourse.course_id,
                    'name', tblexamcourse.course,
                    'amount', COALESCE(tblexamcourse.amount_question, 0),
                    'amount_text', COALESCE(tblexamcourse.amount_text, 0),
                    'area_id', tblexamcourse.area_id,
                    'apply_text', tblexamcourse.apply_text,
                    'subquestions', COALESCE(
                        (SELECT jsonb_agg(
                            jsonb_build_object(
                                'subquestion_amount', ttmtca.subquestion_amount,
                                'position', ttmtca.position
                            ) ORDER BY ttmtca.position
                        )
                        FROM type_text_material_type_course_area ttmtca
                        WHERE ttmtca.type_material_id = tblexamcourse.type_material_id
                        AND ttmtca.course_id = tblexamcourse.course_id
                        AND ttmtca.exam_area_id = tblexamcourse.area_id
                        AND ttmtca.deleted_at IS NULL
                        ), '[]'::jsonb
                    )
                )) FILTER (WHERE tblexamcourse.course_id IS NOT NULL),
                '[]'::jsonb
            ) AS courses,
            COALESCE(
                jsonb_agg(DISTINCT typematedetatemp.week) FILTER (WHERE typematedetatemp.fl_status = TRUE),
                '[]'::jsonb
            ) AS weeks,
            '[]'::jsonb children_ids,
            tmp.periodicity_id,
            p.name AS periodicity,
            tmp.quantity_week,
            tmp.start_week,
            tmp.group_previous_week,
            tmp.group_remaining_week
        FROM type_material t
        LEFT JOIN type_material_template tmt ON tmt.id = t.type_material_template_id
        LEFT JOIN type_material_detail_template typematedetatemp ON typematedetatemp.type_material_id = t.id
        LEFT JOIN tbl_area_exam_courses AS tblexamcourse ON tblexamcourse.type_material_id = t.id
        JOIN cycle c ON t.cycle_id = c.id
        LEFT JOIN type_material_area tma ON tma.type_material_id = t.id
        LEFT JOIN exam_area a ON a.id = tma.area_id
        LEFT JOIN type_material_periodicity tmp ON t.id = tmp.type_material_id AND tmp.fl_status = true
        LEFT JOIN periodicity p ON tmp.periodicity_id = p.id
        WHERE t.id = p_type_material_id
        GROUP BY
            t.id, t.code, t.description, t.type_material_template_id, tmt.name,
            t.amount_question, t.cycle_id, c.description, t.fl_status, t.fl_exam,
            t.fl_class_material, t.thread, t.level_order, t.percentage,
            tmp.periodicity_id, p.name, tmp.quantity_week, tmp.start_week,
            tmp.group_previous_week, tmp.group_remaining_week;
    ELSE
        RETURN QUERY
        WITH type_material_ids AS (
            SELECT unnest(v_ids_children) AS type_material_id
        ),
        tbl_material_courses_base AS (
            SELECT
                c.id AS course_id,
                c.code || ' - ' || c.name AS course,
                tmi.type_material_id,
                COALESCE(tmc.amount_question, 0) AS amount_question,
                COALESCE(tmc.amount_text, 0) AS amount_text,
                c.apply_text,
                COALESCE(tmt.id, tm_default.type_material_template_id) AS template_id,
                tmc.is_generic,
                tmc.is_generic_text,
                tmc.id AS type_material_course_id
            FROM course c
            CROSS JOIN type_material_ids tmi
            LEFT JOIN type_material_course tmc
                ON tmc.course_id = c.id AND tmc.type_material_id = tmi.type_material_id
            LEFT JOIN type_material tm
                ON tm.id = tmc.type_material_id
            LEFT JOIN type_material_template tmt
                ON tmt.id = tm.type_material_template_id
            LEFT JOIN type_material tm_default
                ON tm_default.id = tmi.type_material_id
            WHERE c.fl_status = true AND tm.fl_status = true
        )
        SELECT
            t.id,
            t.code,
            t.description,
            t.type_material_template_id,
            tmt.name AS type_material_template,
            t.amount_question,
            '[]'::jsonb AS areas,
            t.cycle_id,
            c.description AS cycle_name,
            t.fl_status,
            t.fl_exam,
            t.fl_class_material,
            t.thread,
            t.level_order,
            t.percentage,
            COALESCE(courses_data.json, '[]'::jsonb) AS courses,
            COALESCE(
                (SELECT jsonb_agg(week ORDER BY week)
                 FROM type_material_detail_template tmdt
                 WHERE tmdt.type_material_id = t.id AND tmdt.fl_status = TRUE),
                '[]'::jsonb
            ) AS weeks,
            (
                SELECT COALESCE(jsonb_agg(t2.id), '[]'::jsonb)
                FROM type_material t2
                WHERE t2.parent_id = t.id
            ) AS children_ids,
            tmp.periodicity_id,
            p.name AS periodicity,
            tmp.quantity_week,
            tmp.start_week,
            tmp.group_previous_week,
            tmp.group_remaining_week
        FROM type_material t
        LEFT JOIN type_material_template tmt ON tmt.id = t.type_material_template_id
        JOIN cycle c ON t.cycle_id = c.id
        LEFT JOIN type_material_periodicity tmp ON t.id = tmp.type_material_id AND tmp.fl_status = true
        LEFT JOIN periodicity p ON tmp.periodicity_id = p.id
        LEFT JOIN LATERAL (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id', mc.course_id,
                    'name', mc.course,
                    'amount', mc.amount_question,
                    'amount_text', mc.amount_text,
                    'area_id', NULL,
                    'apply_text', mc.apply_text,
                    'type_material_child_id', mc.template_id,
                    'type_material_id', mc.type_material_id,
                    'is_generic', mc.is_generic,
                    'is_generic_text', mc.is_generic_text,
                    'type_material_course_id', mc.type_material_course_id,
                    'subquestions', COALESCE(
                        (SELECT jsonb_agg(
                            jsonb_build_object(
                                'subquestion_amount', ttmtc.subquestion_amount,
                                'position', ttmtc.position
                            ) ORDER BY ttmtc.position
                        )
                        FROM type_text_material_type_course ttmtc
                        WHERE ttmtc.type_material_id = mc.type_material_id
                        AND ttmtc.course_id = mc.course_id
                        AND ttmtc.deleted_at IS NULL
                        ), '[]'::jsonb
                    )
                )
            ) as json
            FROM tbl_material_courses_base mc
        ) courses_data ON true
        WHERE t.id = p_type_material_id AND t.fl_status = true;
    END IF;
END;
$$;


ALTER FUNCTION odiseo.fn_get_type_material(p_type_material_id integer) OWNER TO postgres;

--
-- Name: fn_get_type_material_course_details(bigint, character); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_type_material_course_details(p_tmc_id bigint, p_type_question character) RETURNS TABLE(name character varying, course_id smallint, is_generic boolean, type_question text, type_material_child_id smallint, type_material_id bigint, weeks_detail jsonb)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY 
                SELECT 
                    c.name,
                    c.id AS course_id,
                    CASE 
                        WHEN p_type_question = 'P' THEN tmc.is_generic
                        WHEN p_type_question = 'T' THEN tmc.is_generic_text
                        ELSE true
                    END AS is_generic,
                    p_type_question::TEXT AS type_question,
                    tm.id AS type_material_child_id,
                    COALESCE(tm.parent_id, tm.id) AS type_material_id,
                    COALESCE(
                        (
                            SELECT jsonb_agg(
                                jsonb_build_object(
                                    'week', tmdt.week,
                                    'amount', COALESCE(d_p.amount_question, 0),
                                    'amount_text', COALESCE(d_t.amount_text, 0),
                                    'subquestions', CASE 
                                        WHEN p_type_question = 'T' THEN COALESCE(sub_q.data, '[]'::jsonb)
                                        ELSE '[]'::jsonb 
                                    END
                                ) ORDER BY tmdt.week
                            )
                            FROM type_material_detail_template tmdt
                            
                            -- JOIN PREGUNTAS (P)
                            LEFT JOIN odiseo.type_material_detail_courses d_p 
                                ON d_p.type_material_detail_template_id = tmdt.id 
                                AND d_p.type_material_course_id = tmc.id 
                                AND d_p.fl_status = true
                                AND p_type_question = 'P' 
                            
                            -- JOIN TEXTOS (T)
                            LEFT JOIN odiseo.type_material_detail_course_texts d_t 
                                ON d_t.type_material_detail_template_id = tmdt.id 
                                AND d_t.type_material_course_id = tmc.id 
                                AND d_t.fl_status = true
                                AND p_type_question = 'T'

                            -- JOIN SUBPREGUNTAS (Solo si es T)
                            LEFT JOIN LATERAL (
                                SELECT jsonb_agg(
                                    jsonb_build_object(
                                        'position', sq.position, 
                                        'subquestion_amount', sq.subquestion_amount
                                    ) ORDER BY sq.position
                                ) as data
                                FROM odiseo.type_material_detail_text_subquestions sq
                                WHERE sq.type_material_detail_course_text_id = d_t.id
                                AND sq.deleted_at IS NULL
                            ) sub_q ON p_type_question = 'T'

                            WHERE tmdt.type_material_id = tm.id 
                            AND tmdt.fl_status = true
                        ),
                        '[]'::jsonb
                    ) AS weeks_detail

                FROM type_material_course tmc
                JOIN type_material tm ON tm.id = tmc.type_material_id
                JOIN course c ON c.id = tmc.course_id
                WHERE tmc.id = p_tmc_id;
            END;
            $$;


ALTER FUNCTION odiseo.fn_get_type_material_course_details(p_tmc_id bigint, p_type_question character) OWNER TO postgres;

--
-- Name: fn_get_type_material_data(smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_type_material_data(p_type_material_id smallint, p_exam_area_id smallint) RETURNS TABLE(id smallint, code character varying, description character varying, amount_question integer, cycle_id bigint, fl_exam boolean, type_material_template_id bigint, fl_class_material boolean, type_exam_id bigint, exam_type character varying, type_template_id bigint, type_material_template character varying, total_number_questions integer, area_id smallint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH material_base AS (
        SELECT
            tm.id,
            tm.code,
            tm.description,
            tm.amount_question,
            tm.cycle_id,
            tm.fl_exam,
            tm.type_material_template_id,
            tm.fl_class_material,
            c.type_template_id,
            tmt.type_exam_id,
            tmt.name AS type_material_template,
            te.name AS exam_type
        FROM type_material tm
        LEFT JOIN type_material_template tmt ON tm.type_material_template_id = tmt.id
        LEFT JOIN cycle c ON tm.cycle_id = c.id
        LEFT JOIN type_exams te ON te.id = tmt.type_exam_id
        WHERE tm.id = p_type_material_id
    ), tbl_amount_course_exam_text AS (
        SELECT
            SUM(ttmtca.subquestion_amount)::INTEGER AS amount_question,
            ttmtca.type_material_id,
            ttmtca.exam_area_id
        FROM type_text_material_type_course_area ttmtca
        WHERE ttmtca.type_material_id = p_type_material_id
            AND ttmtca.exam_area_id = p_exam_area_id
            AND ttmtca.deleted_at IS NULL
            AND ttmtca.subquestion_amount > 0
        GROUP BY
            ttmtca.type_material_id,
            ttmtca.exam_area_id
    ), tbl_amount_course_exam AS (
        SELECT
            SUM(tmc.amount_question)::INTEGER AS amount_question, -- <-- Se suma la cantidad de textos a las cantidad de preguntas
            tmc.type_material_id,
            tma.area_id as exam_area_id
        FROM type_material_course tmc
        INNER JOIN type_material_area_courses tmac ON tmc.id = tmac.type_material_course_id
            AND tmac.fl_status = true
        INNER JOIN type_material_area tma ON tmac.type_material_area_id = tma.id
            AND tma.fl_status = TRUE
        WHERE tmc.fl_status = true
            AND tma.area_id = p_exam_area_id
            AND tma.type_material_id = p_type_material_id
            AND tmc.amount_question > 0
        GROUP BY
            tmc.type_material_id,
            tma.area_id
    ), tbl_amount_total AS (
        SELECT tace.*
        FROM tbl_amount_course_exam tace

        UNION ALL

        SELECT tacet.*
        FROM tbl_amount_course_exam_text tacet
    ), tbl_sum_total AS (
        SELECT
            SUM(tat.amount_question)::INTEGER AS total_number_questions,
            tat.type_material_id,
            tat.exam_area_id
        FROM tbl_amount_total tat
        GROUP BY
            tat.type_material_id,
            tat.exam_area_id
    )
    SELECT
        mb.id,
        mb.code,
        mb.description,
        mb.amount_question,
        mb.cycle_id,
        mb.fl_exam,
        mb.type_material_template_id,
        mb.fl_class_material,
        mb.type_exam_id,
        mb.exam_type,
        mb.type_template_id,
        mb.type_material_template,
        CASE
            WHEN p_exam_area_id IS NULL
                THEN mb.amount_question
            ELSE tst.total_number_questions
        END AS total_number_questions,
        tst.exam_area_id AS area_id
    FROM material_base mb
    LEFT JOIN tbl_sum_total tst ON tst.type_material_id = mb.id;
END;
$$;


ALTER FUNCTION odiseo.fn_get_type_material_data(p_type_material_id smallint, p_exam_area_id smallint) OWNER TO postgres;

--
-- Name: fn_get_university_by_employee_of_syllabus(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_university_by_employee_of_syllabus(p_employee_id bigint, p_company_id bigint) RETURNS TABLE(id smallint, name text, university character varying, quantity bigint, fl_template boolean)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        SELECT DISTINCT
            originuniver.id,
            CONCAT('(', originuniver.slug, ') ', originuniver.name),
            originuniver.name AS university,
            COALESCE(syllab_count.quantity, 0) AS quantity,
            CASE WHEN COALESCE(syllab_count.quantity, 0) > 0 THEN true ELSE false END AS fl_template
        FROM origin_university originuniver
        LEFT JOIN employee_university employuniver
            ON employuniver.university_id = originuniver.id
            AND employuniver.fl_status IS true
        LEFT JOIN (
            SELECT s.university_id, COUNT(*) AS quantity
            FROM syllabus s
            WHERE s.fl_status = true AND s.company_id = p_company_id
            GROUP BY s.university_id
        ) syllab_count ON syllab_count.university_id = originuniver.id
        WHERE originuniver.deleted_by IS NULL
        AND (p_employee_id IS NULL OR employuniver.employee_id = p_employee_id)
        AND originuniver.fl_active = true
        ORDER BY fl_template DESC, university ASC, originuniver.id ASC;
    END;
    $$;


ALTER FUNCTION odiseo.fn_get_university_by_employee_of_syllabus(p_employee_id bigint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_get_user_notifications(integer, integer, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_user_notifications(p_perpage integer, p_npage integer, p_user_id bigint) RETURNS TABLE(id bigint, title character varying, message character varying, url_internal character varying, type bigint, fl_status boolean, fl_read boolean, created_at timestamp without time zone, notification_type text, request_status text, created_by text, total_unread_notification bigint, total bigint)
    LANGUAGE plpgsql
    AS $$
            
            DECLARE offset_val INTEGER;
            
            BEGIN offset_val := p_perpage * ( p_npage - 1 );
                
                RETURN QUERY    
                WITH individual_nots AS (
                    SELECT
                        nf.id,
                        nf.title,
                        nf.message,
                        nf.url_internal,
                        nf.type,
                        nf.fl_status,
                        nf.fl_read,
                        nf.created_at,
                        'individual_notification' AS notification_type,
                        NULL::BIGINT AS created_by,
                        nf.user_id AS user_to_notify,
                        NULL AS request_status
                    FROM odiseo.individual_notifications nf
                    WHERE 1 = 1
                      AND nf.user_id = p_user_id
                      AND nf.fl_status IS TRUE
                ), material_nots AS (
                    SELECT
                        mf.id,
                        mf.title,
                        mf.message,
                        mf.url_internal,
                        mf.type,
                        mf.fl_status,
                        mf.fl_read,
                        mf.created_at,
                        'material_notification' AS notification_type,
                        mf.created_by AS created_by,
                        mf.user_id AS user_to_notify,
                        mf.request_status AS request_status
                    FROM odiseo.material_generation_notifications mf
                    WHERE 1 = 1
                      AND mf.user_id = p_user_id
                      AND mf.fl_status IS TRUE
                ), notifications AS (
                    SELECT * FROM individual_nots
                    UNION ALL
                    SELECT * FROM material_nots
                )
                SELECT
                    n.id,
                    n.title,
                    n.message,
                    n.url_internal,
                    n.type,
                    n.fl_status,
                    n.fl_read,
                    n.created_at,
                    n.notification_type,
                    n.request_status,
                    CASE
                        WHEN e.id IS NULL THEN 'Sistema'
                        ELSE CONCAT(e.first_surname, ' ', e.second_surname, ' ', e.first_name)
                    END AS created_by,
                    COUNT(*) FILTER ( WHERE n.fl_read IS FALSE ) OVER () AS total_unread_notification,
                    COUNT(*) OVER () AS total
                FROM notifications n
                LEFT JOIN odiseo.employees e ON e.user_id = n.created_by
                ORDER BY n.created_at DESC
                LIMIT p_perpage OFFSET offset_val;
            END;
        $$;


ALTER FUNCTION odiseo.fn_get_user_notifications(p_perpage integer, p_npage integer, p_user_id bigint) OWNER TO postgres;

--
-- Name: fn_get_validate_question_ia(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_validate_question_ia(p_question_ia_id bigint) RETURNS TABLE(id bigint)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            SELECT DISTINCT
                qtia.id
            FROM question_teacher_ia qtia
            INNER JOIN alternative_questions_ia aqia ON qtia.id = aqia.question_ia_id
            WHERE qtia.id = p_question_ia_id
                AND (qtia.description IS NULL AND TRIM(qtia.description) = '<p></p>')
                OR (qtia.theoretical_basis IS NULL OR TRIM(qtia.theoretical_basis) = '<p></p>')
                OR (qtia.argumentation IS NULL OR TRIM(qtia.argumentation) = '<p></p>')
                OR (aqia.description IS NULL OR TRIM(aqia.description) = '<p></p>')
            ;
        END;
        $$;


ALTER FUNCTION odiseo.fn_get_validate_question_ia(p_question_ia_id bigint) OWNER TO postgres;

--
-- Name: fn_get_verified_questions_summary_teacher(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_get_verified_questions_summary_teacher(f_teacher_id integer) RETURNS TABLE(start_date date, end_date date, statuses json)
    LANGUAGE plpgsql
    AS $$
                        DECLARE
                            v_cut_off_date INTEGER;
                        BEGIN
                            SELECT ads.cut_off_date INTO v_cut_off_date
                            FROM advanced_settings AS ads
                            WHERE ads.fl_status = TRUE
                            LIMIT 1;

                            RETURN QUERY
                            WITH date_range AS (
                                SELECT
                                    CURRENT_TIMESTAMP - INTERVAL '30 days' AS start_date,
                                    NOW() end_date
                            ),
                            first_verified_date AS (
                                SELECT
                                    qss.question_id,
                                    MIN(qss.created_at) created_at
                                FROM question_status qss
                                WHERE qss.status = 'VERI'
                                GROUP BY qss.question_id
                            ),
                            valid_questions_in_range AS (
                                SELECT
                                    vq.id,
                                    vq.parent_id,
                                    vq.status
                                FROM question vq
                                JOIN first_verified_date fvd ON fvd.question_id = vq.id
                                WHERE vq.fl_status = TRUE
                                AND vq.deleted_at IS NULL
                                AND fvd.created_at >= (SELECT dr.start_date FROM date_range dr)
                            ),
                            teacher_questions AS (
                                SELECT 
                                    vqr.id,
                                    vqr.parent_id,
                                    vqr.status
                                FROM valid_questions_in_range vqr
                                INNER JOIN employee_question eq ON eq.question_id = vqr.id
                                WHERE eq.teacher_id = f_teacher_id 
                                AND eq.fl_status = TRUE
                            ),
                            standalone_counts AS (
                                SELECT tq.status
                                FROM teacher_questions tq
                                WHERE tq.parent_id IS NULL
                                AND tq.status IN ('VERI','PEND','RESV', 'APRB')
                            ),
                            parent_counts AS (
                                SELECT pq.status
                                FROM parent_question pq
                                WHERE pq.id IN (SELECT DISTINCT parent_id FROM teacher_questions WHERE parent_id IS NOT NULL)
                                AND pq.status IN ('VERI','PEND','RESV', 'APRB')
                            ),
                            all_rows AS (
                                SELECT sc.status FROM standalone_counts sc
                                UNION ALL
                                SELECT pc.status FROM parent_counts pc
                            ),
                            base_statuses AS (
                                SELECT unnest(ARRAY['VERI', 'PEND', 'RESV', 'APRB']) AS status
                            ), result_status AS (
                                SELECT
                                    bs.status::varchar,
                                    COUNT(ar.status)::bigint AS total_count
                                FROM base_statuses bs
                                LEFT JOIN all_rows ar ON bs.status = ar.status
                                GROUP BY bs.status
                                ORDER BY bs.status
                            ) 
                            SELECT 
                                dr.start_date::date, 
                                dr.end_date::date, 
                                json_agg(
                                    json_build_object(
                                        'status', rs.status,
                                        'total_count', rs.total_count 
                                    )
                                ) AS statuses
                            FROM date_range dr, result_status rs
                            GROUP BY dr.start_date, dr.end_date;

                        END;
                        $$;


ALTER FUNCTION odiseo.fn_get_verified_questions_summary_teacher(f_teacher_id integer) OWNER TO postgres;

--
-- Name: fn_group_didi_question(integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_group_didi_question(p_week integer, p_year integer) RETURNS TABLE(employee_id bigint, employee_name text, question_total numeric, questions json)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    e.id AS employeee_id,
                    CONCAT(split_part(e.first_name, ' ', 1), ' ', upper(left(e.first_surname, 1)), '. ', e.second_surname)  as employee_name,
                    COALESCE(SUM(eq.question_total), 0) AS question_total,
                    CASE
                        WHEN count(eq.employee_id) > 0 THEN json_agg(eq.*)
                        ELSE '[]'::json
                    END AS questions
                FROM
                    odiseo.employees e
                LEFT JOIN (
                    SELECT
                        eq.employee_id,
                        q.course_id,
                        COUNT(eq.question_id) AS question_total,
                        COALESCE(SUM(CASE WHEN eq.diagrammed = true THEN 1 ELSE 0 END), 0) AS diagrammed_total,
                        COALESCE(SUM(CASE WHEN eq.diagrammed = false THEN 1 ELSE 0 END), 0) AS not_diagrammed_total
                    FROM
                        odiseo.employee_didi_question eq
                    INNER JOIN odiseo.question q
                    ON q.id = eq.question_id AND q.fl_status = TRUE
                    WHERE
                        eq.week = p_week AND eq.year = p_year AND eq.fl_status = TRUE AND eq.deleted_at IS NULL
                    GROUP BY
                        eq.employee_id, q.course_id
                    ORDER BY question_total ASC
                ) eq
                ON eq.employee_id = e.id
                WHERE e.charge_id = 3
                AND	e.fl_status = true
                AND e.gpt = false
                GROUP BY
                    e.id
                ORDER BY
                    question_total ASC,
                    e.id ASC;
            END;
            $$;


ALTER FUNCTION odiseo.fn_group_didi_question(p_week integer, p_year integer) OWNER TO postgres;

--
-- Name: fn_group_teacher_question(integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_group_teacher_question(p_week integer, p_year integer) RETURNS TABLE(teacher_id bigint, teacher_name text, question_total numeric, questions json, limit_assigned_questions smallint, fl_unlimit_questions boolean, lot smallint, past_unresolved_questions bigint)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
            WITH base_data (id, teacher_id, course_id, solved, parent_id) AS (
                SELECT
                    eq.id,
                    eq.teacher_id,
                    q.course_id,
                    eq.solved,
                    q.parent_id
                FROM employee_question AS eq
                INNER JOIN question AS q ON q.id = eq.question_id AND q.fl_status = TRUE
                WHERE
                    eq.week = p_week
                    AND eq.year = p_year
                    AND eq.fl_status = TRUE
                    AND eq.deleted_at IS NULL
                    AND q.status != 'DUPL'
            ), question_unresolved (teacher_id, past_unresolved_questions) AS (
                SELECT
                    eq.teacher_id,
                    COALESCE(COUNT(eq.*), 0) AS past_unresolved_questions
                FROM employee_question AS eq
                INNER JOIN question AS q ON q.id = eq.question_id AND q.fl_status = TRUE
                WHERE
                    eq.id NOT IN (SELECT bd.id FROM base_data bd)
                    AND (eq.solved = false OR q.status = 'RECH')
                    AND eq.fl_status = TRUE
                    AND eq.deleted_at IS NULL
                    AND q.status in ('ASIG','RESO','INDE','RECH')
                GROUP BY eq.teacher_id
            ), normal_questions (teacher_id, course_id, question_total, solved_total, unsolved_total) AS (
                SELECT
                    bd.teacher_id,
                    bd.course_id,
                    COUNT(*),
                    COALESCE(SUM(CASE WHEN bd.solved = true THEN 1 ELSE 0 END), 0),
                    COALESCE(SUM(CASE WHEN bd.solved = false THEN 1 ELSE 0 END), 0)
                FROM base_data AS bd
                WHERE bd.parent_id IS NULL
                GROUP BY
                    bd.teacher_id,
                    bd.course_id
            ), parent_question_logic (teacher_id, course_id, parent_id, sub_unsolved_count) AS (
                SELECT
                    bd.teacher_id,
                    bd.course_id,
                    bd.parent_id,
                    COALESCE(SUM(CASE WHEN bd.solved = false THEN 1 ELSE 0 END), 0)
                FROM base_data AS bd
                WHERE bd.parent_id IS NOT NULL
                GROUP BY
                    bd.teacher_id,
                    bd.course_id,
                    bd.parent_id
            ), parent_questions_agg (teacher_id, course_id, question_total, solved_total, unsolved_total) AS (
                SELECT
                    pql.teacher_id,
                    pql.course_id,
                    COUNT(pql.parent_id),
                    COALESCE(SUM(CASE WHEN pql.sub_unsolved_count = 0 THEN 1 ELSE 0 END), 0),
                    COALESCE(SUM(CASE WHEN pql.sub_unsolved_count > 0 THEN 1 ELSE 0 END), 0)
                FROM parent_question_logic AS pql
                GROUP BY
                    pql.teacher_id,
                    pql.course_id
            ), employee_question_summary (teacher_id, course_id, question_total, solved_total, unsolved_total) AS (
                SELECT
                    teacher_all.teacher_id,
                    teacher_all.course_id,
                    SUM(teacher_all.question_total),
                    SUM(teacher_all.solved_total),
                    SUM(teacher_all.unsolved_total)
                FROM (
                    SELECT nq.* FROM normal_questions AS nq
                    UNION ALL
                    SELECT pqa.* FROM parent_questions_agg AS pqa
                ) AS teacher_all
                GROUP BY
                    teacher_all.teacher_id,
                    teacher_all.course_id
            )
            SELECT
                e.id AS teacher_id,
                CONCAT(split_part(e.first_name, ' ', 1), ' ', upper(left(e.first_surname, 1)), '. ', e.second_surname) as teacher_name,
                COALESCE(SUM(eq.question_total), 0) AS question_total,
                CASE
                    WHEN count(eq.teacher_id) > 0 THEN json_agg(eq.* ORDER BY eq.course_id)
                    ELSE '[]'::json
                END AS questions,
                e.limit_assigned_questions,
                e.fl_unlimit_questions,
                e.lot,
                COALESCE(qi.past_unresolved_questions, 0) AS past_unresolved_questions
            FROM employees AS e
            LEFT JOIN employee_question_summary AS eq ON eq.teacher_id = e.id
            LEFT JOIN question_unresolved qi ON e.id = qi.teacher_id
            WHERE e.charge_id = 2
                AND e.fl_status = true
                AND e.gpt = false
            GROUP BY e.id, qi.past_unresolved_questions
            ORDER BY
                question_total ASC,
                e.id ASC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_group_teacher_question(p_week integer, p_year integer) OWNER TO postgres;

--
-- Name: fn_has_ballot_questions(integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_has_ballot_questions(p_material_id integer, p_cycle_id integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
        BEGIN
        RETURN EXISTS (
            WITH relevant_ids AS (
            SELECT d.id
            FROM detail_week_type_mat d
            JOIN material m
                ON m.id = d.material_id
            AND m.cycle_id = p_cycle_id
            WHERE d.material_id = p_material_id
                AND d.fl_status   IS TRUE
            )
            SELECT 1
            FROM relevant_ids r
            WHERE EXISTS (
            SELECT 1
            FROM material_ballot_question mbq
            WHERE mbq.week_type_material_id = r.id
                AND mbq.fl_status IS TRUE
            LIMIT 1
            )
            OR EXISTS (
            SELECT 1
            FROM material_ballot_question mdq
            WHERE mdq.week_type_material_id = r.id
                AND mdq.fl_status IS TRUE
            LIMIT 1
            )
            LIMIT 1
        );
        END;
        $$;


ALTER FUNCTION odiseo.fn_has_ballot_questions(p_material_id integer, p_cycle_id integer) OWNER TO postgres;

--
-- Name: fn_has_ballot_questions_syllabus(integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_has_ballot_questions_syllabus(p_syllabus_id integer, p_company_id integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
        DECLARE
            response boolean;
        BEGIN
            response:= FALSE;

        WITH tbl_syllabus AS (
            SELECT
                id,
                cycle_id,
                university_id
            FROM syllabus
            WHERE deleted_at IS NULL
            AND company_id = p_company_id
            AND id = p_syllabus_id
        ),
        materiales AS (
            SELECT
                s.id AS syllabus_id,
                m.id AS material_id,
                s.cycle_id
            FROM material m
            JOIN tbl_syllabus s
                ON m.cycle_id = s.cycle_id
                AND m.university_id = s.university_id
        ),
        resumen AS (
        SELECT 
        * ,
        fn_has_ballot_questions(
            materiales.material_id::integer,
            materiales.cycle_id::integer
        )
        FROM materiales )

        SELECT TRUE INTO response
        WHERE EXISTS (SELECT 1 FROM resumen where fn_has_ballot_questions = true);

        return response;

        END;
        $$;


ALTER FUNCTION odiseo.fn_has_ballot_questions_syllabus(p_syllabus_id integer, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_has_user_nq_courses(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_has_user_nq_courses(p_user_id bigint) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN EXISTS(
        SELECT 1
        FROM odiseo.employee_course ec
        JOIN odiseo.employees e ON e.id = ec.teacher_id AND e.user_id = p_user_id
        JOIN odiseo.course c ON c.id = ec.course_id AND ec.fl_status IS TRUE AND c.alias_nq IS NOT NULL
    );
END;
$$;


ALTER FUNCTION odiseo.fn_has_user_nq_courses(p_user_id bigint) OWNER TO postgres;

