CREATE FUNCTION odiseo.fn_importance_rejected(p_search character varying) RETURNS TABLE(id smallint, level smallint, name character varying, fl_status boolean)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    i.id,
                    i.level,
                    i.name,
                    i.fl_status
