--
-- Name: fn_index_essential_knowledge(integer, integer, character varying, bigint, bigint[], bigint, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_index_essential_knowledge(p_npage integer, p_perpage integer, p_name_text character varying, p_course_id bigint, p_user_course_ids bigint[], p_topic_id bigint, p_is_active boolean) RETURNS TABLE(id bigint, code character varying, name character varying, is_active boolean, topic_id bigint, topic_name character varying, course_id bigint, course_name character varying, thumbnail text, created_at timestamp without time zone, total_use bigint, total bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_offset INTEGER;
BEGIN
    -- Validación de página mínima
    IF p_npage < 1 THEN p_npage := 1; END IF;

    v_offset := (p_npage - 1) * p_perpage;

    RETURN QUERY
    SELECT
        ek.id,
        ek.code,
        ek.name,
        ek.is_active,
        ek.topic_id,
        concat(t.code, ' - ', t.name)::varchar as topic_name,
        ek.course_id,
        concat(c.code, ' - ', c.name)::varchar as course_name,
        ek.thumbnail,
        ek.created_at,
        COUNT(ekq.id) AS total_use,
        COUNT(*) OVER() AS total
    FROM essential_knowledges ek
    JOIN topic t ON t.id = ek.topic_id
    JOIN course c ON c.id = ek.course_id
    LEFT JOIN essential_knowledge_questions ekq ON ekq.essential_knowledge_id = ek.id
        AND ekq.deleted_at IS NULL
    WHERE 1 = 1
        AND (p_is_active IS NULL OR ek.is_active = p_is_active)
        AND (p_course_id IS NULL OR ek.course_id = p_course_id)
        AND ek.course_id = ANY(p_user_course_ids)
        AND (p_topic_id IS NULL OR ek.topic_id = p_topic_id)
        AND (
            NULLIF(p_name_text, '') IS NULL
            OR unaccent(ek.name) ILIKE unaccent('%' || p_name_text || '%')
            OR ek.code ILIKE '%' || p_name_text || '%'
        )
        AND ek.deleted_at IS NULL
    GROUP BY ek.id, t.id, c.id
    ORDER BY ek.created_at DESC
    LIMIT p_perpage
    OFFSET v_offset;
END;
$$;


ALTER FUNCTION odiseo.fn_index_essential_knowledge(p_npage integer, p_perpage integer, p_name_text character varying, p_course_id bigint, p_user_course_ids bigint[], p_topic_id bigint, p_is_active boolean) OWNER TO postgres;

--
-- Name: fn_indexar_question(integer, integer, json, integer, integer, character varying, numeric, character varying, integer, character varying, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_indexar_question(p_id integer, p_topic_id integer, p_subtopics json, p_level_id integer, p_alternative_id integer, p_type character varying, p_ter numeric, p_editor_content character varying, p_updated_by integer, p_status character varying, p_employee_question_id integer DEFAULT NULL::integer) RETURNS TABLE(new_question_id integer, new_status character varying, v_url_pdf character varying)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_subtopic_id INT;
            v_new_subtopics_ids INT[];
            v_existing_subtopic_ids INT[];
            v_subtopics_delete INT[];
        BEGIN
            new_status := (SELECT status FROM odiseo.question WHERE id = p_id);

            v_new_subtopics_ids := ARRAY(SELECT json_array_elements_text(p_subtopics)::INT);

            -- Eliminar los subtemas que no encuentra
            UPDATE odiseo.question_subtopic
            SET fl_status = false, deleted_by = p_updated_by, deleted_at = now()
            WHERE question_id = p_id
            AND subtopic_id NOT IN (SELECT unnest(v_new_subtopics_ids));

            -- Consultar los IDs existentes en odiseo.question_subtopic
            v_existing_subtopic_ids := ARRAY(
                SELECT subtopic_id
                FROM odiseo.question_subtopic
                WHERE subtopic_id = ANY(v_new_subtopics_ids)
                AND question_id = p_id
                AND fl_status = true
            );

            -- Eliminar los IDs existentes de la lista de nuevos IDs
            v_new_subtopics_ids := ARRAY(
                SELECT unnest(v_new_subtopics_ids)
                EXCEPT
                SELECT unnest(v_existing_subtopic_ids)
            );

            -- Insertar los nuevos IDs que no están en la tabla
            FOREACH v_subtopic_id IN ARRAY v_new_subtopics_ids
            LOOP
                INSERT INTO odiseo.question_subtopic (question_id, subtopic_id, created_by, created_at)
                VALUES (p_id, v_subtopic_id, p_updated_by, now());
            END LOOP;

            IF p_topic_id IS NOT NULL AND
                p_level_id IS NOT NULL AND
                p_alternative_id IS NOT NULL AND
                p_type IS NOT NULL AND
                p_ter IS NOT NULL AND
                p_status = 'INDEX' THEN
                    new_status  := 'INDE';
            END IF;

            UPDATE odiseo.question
            SET
                topic_id = COALESCE(p_topic_id, topic_id),
                subtopic_id = null,
                level_id = COALESCE(p_level_id, level_id),
                answer_id = COALESCE(p_alternative_id, answer_id),
                type = COALESCE(p_type, type),
                ter = COALESCE(p_ter, ter),
                status = new_status,
                updated_by = p_updated_by,
                updated_at = now()
            WHERE
                id = p_id
                RETURNING id, status, url_pdf INTO new_question_id, new_status, v_url_pdf;
            
            IF p_editor_content IS NOT NULL AND p_employee_question_id IS NOT NULL THEN
                UPDATE odiseo.employee_question e_q
                SET editor_content = p_editor_content
                WHERE e_q.id = p_employee_question_id AND e_q.fl_status = true;
            END IF;

            RETURN NEXT;
        END;
        $$;


ALTER FUNCTION odiseo.fn_indexar_question(p_id integer, p_topic_id integer, p_subtopics json, p_level_id integer, p_alternative_id integer, p_type character varying, p_ter numeric, p_editor_content character varying, p_updated_by integer, p_status character varying, p_employee_question_id integer) OWNER TO postgres;

--
-- Name: fn_indexar_question_teacher(integer, integer, json, integer, integer, character varying, numeric, character varying, jsonb, integer, character varying, integer, jsonb, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_indexar_question_teacher(p_id integer, p_topic_id integer, p_subtopics json, p_level_id integer, p_alternative_id integer, p_type character varying, p_ter numeric, p_editor_content character varying, p_editor_images jsonb, p_updated_by integer, p_status character varying, p_course_id integer, p_question_attributes jsonb, p_essential_knowledges jsonb) RETURNS TABLE(new_question_id integer, new_status character varying, v_url_pdf character varying)
    LANGUAGE plpgsql
    AS $$
                    DECLARE
                        v_subtopic_id INT;
                        v_new_subtopics_ids INT[];
                        v_existing_subtopic_ids INT[];
                        v_subtopics_delete INT[];
                        v_employee_question_id INT;
                        v_editor_image JSONB;
                        v_parent_id INT;
                        v_type_text_template_id INT;
                        v_question_attributes jsonb;

                        v_current_course_id INT;
                        v_current_type character varying;
                        v_new_code character varying;
                        v_new_number character varying;
                        v_category character varying;
                        BEGIN
                            new_status := (SELECT status FROM question WHERE id = p_id);

                            SELECT c.type_text_template_id, q.parent_id INTO v_type_text_template_id, v_parent_id FROM question q
                            JOIN course c ON c.id = q.course_id
                            WHERE q.id = p_id;

                            SELECT course_id, type INTO v_current_course_id, v_current_type FROM question WHERE id = p_id;
                            
                            IF p_course_id IS NOT NULL AND p_course_id <> v_current_course_id THEN
                                IF v_current_type = 'TEXTO' THEN 
                                    v_category := 'T';
                                ELSE
                                    v_category := 'P';
                                END IF;
                                
                                SELECT full_code, number_str 
                                INTO v_new_code, v_new_number
                                FROM odiseo.fn_generate_question_code(p_course_id, v_category);
                            END IF;

                            v_new_subtopics_ids := ARRAY(SELECT json_array_elements_text(p_subtopics)::INT);


                            -- Eliminar los subtemas que no encuentra
                            UPDATE question_subtopic
                            SET fl_status = false, deleted_by = p_updated_by, deleted_at = now()
                            WHERE question_id = p_id
                            AND subtopic_id NOT IN (SELECT unnest(v_new_subtopics_ids));

                            SELECT eq.id
                            INTO v_employee_question_id
                            FROM employee_question eq
                            WHERE eq.fl_status = TRUE  AND eq.deleted_at  IS NULL AND eq.question_id = p_id;

                            -- Consultar los IDs existentes en question_subtopic
                            v_existing_subtopic_ids := ARRAY(
                                SELECT subtopic_id
                                FROM question_subtopic
                                WHERE subtopic_id = ANY(v_new_subtopics_ids)
                                AND question_id = p_id
                                AND fl_status = true
                            );

                            -- Eliminar los IDs existentes de la lista de nuevos IDs
                            v_new_subtopics_ids := ARRAY(
                                SELECT unnest(v_new_subtopics_ids)
                                EXCEPT
                                SELECT unnest(v_existing_subtopic_ids)
                            );

                            -- Insertar los nuevos IDs que no están en la tabla
                            FOREACH v_subtopic_id IN ARRAY v_new_subtopics_ids
                            LOOP
                                INSERT INTO question_subtopic (question_id, subtopic_id, created_by, created_at)
                                VALUES (p_id, v_subtopic_id, p_updated_by, now());
                            END LOOP;

                            IF v_parent_id IS NOT NULL THEN
                                IF v_type_text_template_id = 2 THEN
                                    new_status := 'INDE';
                                END IF;
                                IF v_type_text_template_id = 3 THEN
                                    IF p_topic_id IS NOT NULL AND
                                        p_alternative_id IS NOT NULL AND
                                        p_status = 'INDE' THEN
                                            new_status  := 'INDE';
                                    END IF;
                                END IF;
                            ELSE
                                IF p_topic_id IS NOT NULL AND
                                    p_alternative_id IS NOT NULL AND
                                    p_status = 'INDE' THEN
                                        new_status  := 'INDE';
                                END IF;
                            END IF;

                            UPDATE question
                            SET
                                topic_id = COALESCE(p_topic_id, topic_id),
                                subtopic_id = null,
                                level_id = COALESCE(p_level_id, level_id),
                                answer_id = COALESCE(p_alternative_id, answer_id),
                                type = COALESCE(p_type, type),
                                ter = COALESCE(p_ter, ter),
                                status = new_status,
                                updated_by = p_updated_by,
                                updated_at = now(),
                                course_id = p_course_id,
                                code = COALESCE(v_new_code, code),  
                                number = COALESCE(v_new_number, number)
                            WHERE
                                id = p_id
                                RETURNING id, status, url_pdf INTO new_question_id, new_status, v_url_pdf;

                            IF p_editor_content IS NOT NULL AND v_employee_question_id IS NOT NULL THEN
                                UPDATE employee_question e_q
                                SET editor_content = p_editor_content
                                WHERE e_q.id = v_employee_question_id AND e_q.fl_status = true;
                                IF p_editor_images IS NOT NULL THEN
                                    FOR v_editor_image IN SELECT * FROM jsonb_array_elements(p_editor_images) LOOP
                                        INSERT INTO employee_question_image (code, extension, image, employee_question_id, created_by, created_at)
                                        VALUES (v_editor_image->>'code', v_editor_image->>'extension', v_editor_image->>'image',v_employee_question_id, p_updated_by, now());
                                    END LOOP;
                                END IF;
                            END IF;

                            IF p_question_attributes IS NOT NULL THEN
                                p_question_attributes := COALESCE(p_question_attributes::jsonb, '[]'::jsonb);

                                -- Insertar atributos que no existen
                                INSERT INTO question_attributes (
                                    question_id,
                                    question_attributes_type_id,
                                    value,
                                    created_by,
                                    created_at
                                )
                                SELECT
                                    p_id,
                                    (attr->>'question_attribute_type_id')::INT,
                                    attr->>'value',
                                    p_updated_by,
                                    now()
                                FROM jsonb_array_elements(p_question_attributes) AS attr
                                WHERE NOT EXISTS (
                                    SELECT 1
                                    FROM question_attributes qa
                                    WHERE qa.question_id = p_id
                                    AND qa.question_attributes_type_id =
                                        (attr->>'question_attribute_type_id')::INT
                                    AND qa.deleted_at IS NULL
                                );

                                -- Actualizar si cambió el value
                                UPDATE question_attributes qa
                                SET
                                    value = attr->>'value',
                                    updated_by = p_updated_by,
                                    updated_at = now()
                                FROM jsonb_array_elements(p_question_attributes) AS attr
                                WHERE qa.question_id = p_id
                                AND qa.question_attributes_type_id =
                                    (attr->>'question_attributes_type_id')::INT
                                AND qa.deleted_at IS NULL
                                AND qa.value IS DISTINCT FROM attr->>'value';

                                -- Soft delete de atributos que ya no vienen
                                UPDATE question_attributes qa
                                SET
                                    deleted_by = p_updated_by,
                                    deleted_at = now()
                                WHERE qa.question_id = p_id
                                AND qa.deleted_at IS NULL
                                AND qa.question_attributes_type_id NOT IN (
                                    SELECT (attr->>'question_attributes_type_id')::INT
                                    FROM jsonb_array_elements(p_question_attributes) AS attr
                                );

                            END IF;

                            IF p_essential_knowledges IS NOT NULL THEN

                                WITH incoming_essential_knowledges AS (
                                    SELECT DISTINCT value::bigint AS id
                                    FROM jsonb_array_elements_text(
                                        COALESCE(p_essential_knowledges, '[]'::jsonb)
                                    ) AS items(value)
                                ),

                                restored_essential_knowledges AS (
                                    UPDATE essential_knowledge_questions ekq
                                    SET
                                        deleted_at = NULL,
                                        deleted_by = NULL,
                                        updated_at = now(),
                                        updated_by = p_updated_by
                                    FROM incoming_essential_knowledges incoming
                                    WHERE ekq.question_id = p_id
                                    AND ekq.essential_knowledge_id = incoming.id
                                    AND ekq.deleted_at IS NOT NULL
                                    RETURNING ekq.id
                                ),

                                new_essential_knowledges AS (
                                    INSERT INTO essential_knowledge_questions (
                                        question_id,
                                        essential_knowledge_id,
                                        created_by,
                                        created_at
                                    )
                                    SELECT
                                        p_id,
                                        incoming.id,
                                        p_updated_by,
                                        now()
                                    FROM incoming_essential_knowledges incoming
                                    WHERE NOT EXISTS (
                                        SELECT 1
                                        FROM essential_knowledge_questions ekq
                                        WHERE ekq.question_id = p_id
                                        AND ekq.essential_knowledge_id = incoming.id
                                    )
                                    RETURNING id
                                )

                                UPDATE essential_knowledge_questions ekq
                                SET
                                    deleted_at = now(),
                                    deleted_by = p_updated_by
                                WHERE ekq.question_id = p_id
                                AND ekq.deleted_at IS NULL
                                AND NOT EXISTS (
                                    SELECT 1
                                    FROM incoming_essential_knowledges incoming
                                    WHERE incoming.id = ekq.essential_knowledge_id
                                );

                            END IF;

                            RETURN NEXT;
                        END;
            $$;


ALTER FUNCTION odiseo.fn_indexar_question_teacher(p_id integer, p_topic_id integer, p_subtopics json, p_level_id integer, p_alternative_id integer, p_type character varying, p_ter numeric, p_editor_content character varying, p_editor_images jsonb, p_updated_by integer, p_status character varying, p_course_id integer, p_question_attributes jsonb, p_essential_knowledges jsonb) OWNER TO postgres;

--
-- Name: fn_insert_field_digitized_question(bigint, jsonb, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_insert_field_digitized_question(p_question_id bigint, p_field_diagram jsonb, p_image jsonb, p_user bigint) RETURNS TABLE(result_id bigint, result_employee_didi_question_id bigint, result_setting_diagrammed_course_id bigint, result_value text, result_created_by bigint, result_created_at timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_didi_question_id BIGINT;  -- Variable para almacenar el ID de employee_didi_question
            v_field JSONB;              -- Variable para cada elemento del JSONB array
            v_element JSONB;            -- Variable para iterar sobre p_image
        BEGIN
            -- Actualizar registro en la tabla employee_didi_question
            UPDATE odiseo.employee_didi_question
            SET updated_by = p_user, updated_at = NOW()
            WHERE question_id = p_question_id AND fl_status = true;
        
            -- Obtener el ID de la pregunta actualizada
            SELECT edq.id
            INTO v_didi_question_id
            FROM odiseo.employee_didi_question edq
            WHERE edq.question_id = p_question_id AND edq.fl_status = true;
        
            -- Iterar sobre el JSONB array p_image
            FOR v_element IN
                SELECT jsonb_array_elements(p_image)
            LOOP
                INSERT INTO odiseo.employee_didi_question_field_image (
                    employee_didi_question_id,
                    code,
                    extension,
                    image,
                    created_by,
                    created_at
                )
                VALUES (
                    v_didi_question_id,
                    v_element->>'code',        -- Extraer el valor de 'code'
                    v_element->>'extension',   -- Extraer el valor de 'extension'
                    v_element->>'image',       -- Extraer el valor de 'image'
                    p_user,                    -- Usuario que crea el registro
                    NOW()                      -- Fecha de creación
                );
            END LOOP;
        
            -- Insertar en employee_didi_question_field y retornar filas
            RETURN QUERY
            WITH inserted AS (
                INSERT INTO odiseo.employee_didi_question_field (
                    employee_didi_question_id,
                    setting_diagrammed_course_id,
                    value,
                    created_by,
                    created_at
                )
                SELECT 
                    v_didi_question_id,
                    (field->>'id')::bigint,
                    field->>'description',
                    p_user,
                    NOW()
                FROM jsonb_array_elements(p_field_diagram) AS field
                RETURNING 
                    id AS result_id,
                    employee_didi_question_id AS result_employee_didi_question_id,
                    setting_diagrammed_course_id AS result_setting_diagrammed_course_id,
                    value AS result_value,
                    created_by AS result_created_by,
                    created_at AS result_created_at
            )
            SELECT * FROM inserted;
        
        END;
        $$;


ALTER FUNCTION odiseo.fn_insert_field_digitized_question(p_question_id bigint, p_field_diagram jsonb, p_image jsonb, p_user bigint) OWNER TO postgres;

--
-- Name: fn_insert_history_syllabus(bigint, bigint, bigint, text, timestamp without time zone, timestamp without time zone, character varying, json, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_insert_history_syllabus(p_syllabus_id bigint, p_user_id bigint, p_role_id bigint, p_description text, p_created_at timestamp without time zone, p_updated_at timestamp without time zone, p_token character varying, p_weeks json, p_company_id bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

    DECLARE
    p_id_history_syllabus BIGINT;

    BEGIN

    IF(p_token IS NULL) THEN
        INSERT INTO history_syllabus (syllabus_id,user_id,role_id,correlative,description,created_at,updated_at, company_id) 
        VALUES (p_syllabus_id,p_user_id,p_role_id,
        (SELECT (COALESCE(MAX(correlative),0) + 1) FROM history_syllabus WHERE syllabus_id = p_syllabus_id LIMIT 1),
        p_description,p_created_at,p_updated_at, p_company_id)
        RETURNING id INTO p_id_history_syllabus;
        RETURN p_id_history_syllabus;
    END IF;

    p_id_history_syllabus:= NULL;

    IF(p_token IS NOT NULL) THEN
        SELECT id INTO p_id_history_syllabus FROM history_syllabus WHERE token = p_token LIMIT 1;
    END IF;

    IF(p_id_history_syllabus IS NULL) THEN
        INSERT INTO history_syllabus (syllabus_id,user_id,role_id,correlative,description,created_at,updated_at,token,weeks, company_id) 
        VALUES (p_syllabus_id,p_user_id,p_role_id,
        (SELECT (COALESCE(MAX(correlative),0) + 1) FROM history_syllabus WHERE syllabus_id = p_syllabus_id LIMIT 1),
        p_description,p_created_at,p_updated_at,p_token,p_weeks, p_company_id)
        RETURNING id INTO p_id_history_syllabus;
    ELSE
        UPDATE history_syllabus
        SET weeks = merge_json_array_except(weeks, p_weeks)
        WHERE id = p_id_history_syllabus AND company_id = p_company_id;
    END IF;

    RETURN p_id_history_syllabus;

    END;            
    $$;


ALTER FUNCTION odiseo.fn_insert_history_syllabus(p_syllabus_id bigint, p_user_id bigint, p_role_id bigint, p_description text, p_created_at timestamp without time zone, p_updated_at timestamp without time zone, p_token character varying, p_weeks json, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_insert_material_ballot_question(bigint, smallint, smallint, bigint, smallint, smallint, smallint, bigint, smallint, bigint, bigint, bigint, character varying, boolean, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_insert_material_ballot_question(p_material_id bigint, p_week smallint, p_type_material_id smallint, p_week_type_material_id bigint, p_course_id smallint, p_position smallint, p_position_initial smallint, p_subtopic_id bigint, p_topic_id smallint, p_level_id bigint, p_usage_level_id bigint, p_question_id bigint, p_type character varying, p_usage_status boolean, p_created_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        BEGIN
            INSERT INTO material_ballot_question (
                material_id,
                week,
                type_material_id,
                week_type_material_id,
                course_id,
                position,
                position_initial,
                subtopic_id,
                topic_id,
                level_id,
                usage_level_id,
                question_id,
                type,
                usage_status,
                created_by,
                created_at
            )
            VALUES (
                p_material_id,
                p_week,
                p_type_material_id,
                p_week_type_material_id,
                p_course_id,
                p_position,
                p_position_initial,
                p_subtopic_id,
                p_topic_id,
                p_level_id,
                p_usage_level_id,
                p_question_id,
                p_type,
                p_usage_status,
                p_created_by,
                NOW()
            );
        END;
        $$;


ALTER FUNCTION odiseo.fn_insert_material_ballot_question(p_material_id bigint, p_week smallint, p_type_material_id smallint, p_week_type_material_id bigint, p_course_id smallint, p_position smallint, p_position_initial smallint, p_subtopic_id bigint, p_topic_id smallint, p_level_id bigint, p_usage_level_id bigint, p_question_id bigint, p_type character varying, p_usage_status boolean, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_insert_material_distribution_ballot_parent_questions(bigint, smallint, smallint, bigint, smallint, smallint, smallint, bigint, smallint, bigint, jsonb, bigint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_insert_material_distribution_ballot_parent_questions(p_material_id bigint, p_week smallint, p_type_material_id smallint, p_week_type_material_id bigint, p_course_id smallint, p_position smallint, p_position_initial smallint, p_level_id bigint, p_usage_level_id smallint, p_parent_question_id bigint, p_subquestion jsonb, p_category_id bigint, p_subcategory_id bigint, p_created_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_material_ballot_question_id BIGINT;
            BEGIN
                INSERT INTO material_ballot_question (
                    material_id,
                    "week",
                    type_material_id,
                    week_type_material_id,
                    course_id,
                    position,
                    position_initial,
                    level_id,
                    usage_level_id,
                    parent_question_id,
                    type_text_id,
                    type_text_subcategory_id,
                    state,
                    created_by,
                    created_at
                )
                VALUES (
                    p_material_id,
                    p_week,
                    p_type_material_id,
                    p_week_type_material_id,
                    p_course_id,
                    p_position,
                    p_position_initial,
                    p_level_id,
                    p_usage_level_id,
                    p_parent_question_id,
                    p_category_id,
                    p_subcategory_id,
                    'GENERATED',
                    p_created_by,
                    NOW()
                )
                ON CONFLICT (week_type_material_id, (COALESCE(question_id, 0)), (COALESCE(parent_question_id, 0)))
                WHERE fl_status = TRUE AND deleted_at IS NULL AND (question_id IS NOT NULL OR parent_question_id IS NOT NULL)
                DO UPDATE SET
                    material_id = EXCLUDED.material_id,
                    "week" = EXCLUDED.week,
                    type_material_id = EXCLUDED.type_material_id,
                    course_id = EXCLUDED.course_id,
                    position = EXCLUDED.position,
                    position_initial = EXCLUDED.position_initial,
                    level_id = EXCLUDED.level_id,
                    usage_level_id = EXCLUDED.usage_level_id,
                    type_text_id = EXCLUDED.type_text_id,
                    type_text_subcategory_id = EXCLUDED.type_text_subcategory_id,
                    state = EXCLUDED.state,
                    updated_by = EXCLUDED.created_by,
                    updated_at = NOW()
                RETURNING id INTO v_material_ballot_question_id;

                -- Inhabilitar subpreguntas anteriores en caso de actualización
                UPDATE material_ballot_subquestions
                SET fl_status = FALSE, deleted_at = NOW()
                WHERE material_ballot_question_id = v_material_ballot_question_id AND fl_status = TRUE;

                -- Insertar nuevas subpreguntas
                IF p_subquestion IS NOT NULL AND jsonb_typeof(p_subquestion) = 'array' THEN
                    INSERT INTO odiseo.material_ballot_subquestions (
                        material_ballot_question_id,
                        question_id,
                        position,
                        state,
                        topic_id,
                        course_id,
                        subtopic_id
                    )
                    SELECT
                        v_material_ballot_question_id,
                        (elem->>'question_id')::BIGINT,
                        row_number() OVER(ORDER BY (elem->>'position')::INT2 NULLS LAST)::INT2,
                        CASE WHEN (elem->>'question_id') IS NOT NULL THEN 'GENERATED'::varchar ELSE 'MISSING'::varchar END,
                        (elem->>'topic_id')::SMALLINT,
                        (elem->>'course_id')::SMALLINT,
                        (elem->>'subtopic_id')::SMALLINT
                    FROM jsonb_array_elements(p_subquestion) AS elem;
                END IF;
            END;
        $$;


ALTER FUNCTION odiseo.fn_insert_material_distribution_ballot_parent_questions(p_material_id bigint, p_week smallint, p_type_material_id smallint, p_week_type_material_id bigint, p_course_id smallint, p_position smallint, p_position_initial smallint, p_level_id bigint, p_usage_level_id smallint, p_parent_question_id bigint, p_subquestion jsonb, p_category_id bigint, p_subcategory_id bigint, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_insert_material_distribution_ballot_questions(bigint, smallint, smallint, bigint, smallint, smallint, smallint, bigint, smallint, bigint, bigint, bigint, character varying, boolean, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_insert_material_distribution_ballot_questions(p_material_id bigint, p_week smallint, p_type_material_id smallint, p_week_type_material_id bigint, p_course_id smallint, p_position smallint, p_position_initial smallint, p_subtopic_id bigint, p_topic_id smallint, p_level_id bigint, p_usage_level_id bigint, p_question_id bigint, p_type character varying, p_usage_status boolean, p_created_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        BEGIN
            INSERT INTO material_distribution_ballot_questions (
                material_id,
                week,
                type_material_id,
                week_type_material_id,
                course_id,
                position,
                position_initial,
                subtopic_id,
                topic_id,
                level_id,
                usage_level_id,
                question_id,
                type,
                usage_status,
                created_by,
                created_at
            )
            VALUES (
                p_material_id,
                p_week,
                p_type_material_id,
                p_week_type_material_id,
                p_course_id,
                p_position,
                p_position_initial,
                p_subtopic_id,
                p_topic_id,
                p_level_id,
                p_usage_level_id,
                p_question_id,
                p_type,
                p_usage_status,
                p_created_by,
                NOW()
            );
        END;
        $$;


ALTER FUNCTION odiseo.fn_insert_material_distribution_ballot_questions(p_material_id bigint, p_week smallint, p_type_material_id smallint, p_week_type_material_id bigint, p_course_id smallint, p_position smallint, p_position_initial smallint, p_subtopic_id bigint, p_topic_id smallint, p_level_id bigint, p_usage_level_id bigint, p_question_id bigint, p_type character varying, p_usage_status boolean, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_insert_or_update_distribution_levels_exam(bigint, bigint, jsonb, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_insert_or_update_distribution_levels_exam(p_cycle_id bigint, p_type_material_id bigint, p_exam_materials jsonb, p_user bigint, p_company_id bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_exam_material JSONB;
            v_exam_area JSONB;
            v_exam_material_config_id BIGINT;
            v_exam_material_config_area_course_id BIGINT;
            v_amount_type_d INTEGER;
			vp_amount_type_d INTEGER;
            v_level JSONB;
            v_exam_material_config_area_course_level_id BIGINT;
        BEGIN
            -- Buscar configuración de material de examen existente
            SELECT
                emc.id INTO v_exam_material_config_id
            FROM exam_material_configurations emc
            WHERE emc.cycle_id = p_cycle_id
                AND emc.type_material_id = p_type_material_id
                AND emc.fl_status = TRUE
                AND emc.company_id = p_company_id
            LIMIT 1;

            -- Si no encuentra insertar nueva configuración de material de examen
            IF v_exam_material_config_id IS NULL THEN
                INSERT INTO exam_material_configurations (
                    type_material_id,
                    cycle_id,
                    company_id,
                    created_by,
                    created_at
                )
                VALUES (
                    p_type_material_id,
                    p_cycle_id,
                    p_company_id,
                    p_user,
                    NOW()
                )
                RETURNING id INTO v_exam_material_config_id;
            END IF;

            -- Iterar los cursos de distribución de niveles
            FOR v_exam_material IN SELECT * FROM jsonb_array_elements(p_exam_materials) LOOP
                -- Iterar sobre las áreas del examen
                FOR v_exam_area IN SELECT * FROM jsonb_array_elements(v_exam_material->'exam_area') LOOP
					vp_amount_type_d := (v_exam_area->>'amount_type_d')::INT;

                    -- Buscar configuración de área y curso existente
                    SELECT
                        emcac.id, emcac.amount_type_d INTO v_exam_material_config_area_course_id, v_amount_type_d
                    FROM exam_material_config_area_courses emcac
                    WHERE emcac.exam_material_config_id = v_exam_material_config_id
                        AND emcac.course_id = (v_exam_material->'course_id')::BIGINT
                        AND emcac.exam_area_id = (v_exam_area->>'exam_area_id')::BIGINT
                        AND emcac.fl_status IS TRUE
                    LIMIT 1;
                    
                    IF (v_exam_material->'apply_text')::BOOL IS TRUE THEN
                        FOR v_level IN SELECT * FROM jsonb_array_elements(v_exam_area->'levels') LOOP
                            INSERT INTO type_text_exam_material_configuration (
                                exam_material_config_id,
                                course_id,
                                area_id,
                                type_text_level_id,
                                text_amount,
                                created_at,
                                created_by
                            )
                            VALUES (
                                v_exam_material_config_id,
                                (v_exam_material->'course_id')::BIGINT,
                                (v_exam_area->>'exam_area_id')::BIGINT,
                                (v_level->'id')::SMALLINT,
                                (v_level->'amount_question')::SMALLINT,
                                NOW(),
                                p_user
                            )
                            ON CONFLICT (exam_material_config_id, course_id, area_id, type_text_level_id)
                            DO UPDATE SET
                                text_amount = (v_level->'amount_question')::SMALLINT,
                                updated_at = NOW(),
                                updated_by = p_user;
                        END LOOP;
                    ELSE
                        -- Si no existe insertar nueva configuración de área y curso
                        IF v_exam_material_config_area_course_id IS NULL THEN
                            INSERT INTO exam_material_config_area_courses (
                                exam_material_config_id,
                                course_id,
                                exam_area_id,
                                amount_type_d,
                                created_by,
                                created_at
                            )
                            VALUES (
                                v_exam_material_config_id,
                                (v_exam_material->'course_id')::BIGINT,
                                (v_exam_area->>'exam_area_id')::BIGINT,
                                vp_amount_type_d,
                                p_user,
                                NOW()
                            )
                            RETURNING id INTO v_exam_material_config_area_course_id;
                        ELSE
                            IF v_amount_type_d IS DISTINCT FROM vp_amount_type_d THEN
                                UPDATE exam_material_config_area_courses
                                SET
                                    amount_type_d = vp_amount_type_d,
                                    updated_by = p_user,
                                    updated_at = NOW()
                                WHERE id = v_exam_material_config_area_course_id;
                            END IF;
                        END IF;
    
                        -- Procesar niveles del JSONB
                        FOR v_level IN SELECT * FROM jsonb_array_elements(v_exam_area->'levels') LOOP
                            -- Buscar configuración de nivel existente
                            SELECT
                                emcacl.id INTO v_exam_material_config_area_course_level_id
                            FROM exam_material_config_area_course_levels emcacl
                            WHERE emcacl.exam_material_config_area_course_id = v_exam_material_config_area_course_id
                                AND emcacl.level_id = (v_level->'id')::BIGINT
                                AND emcacl.fl_status = TRUE
                            LIMIT 1;
    
                            -- Insertar nueva configuración de nivel si tiene preguntas
                            IF v_exam_material_config_area_course_level_id IS NULL THEN
                                IF COALESCE((v_level->'amount_question')::INTEGER, 0) > 0 THEN
                                    INSERT INTO exam_material_config_area_course_levels (
                                        exam_material_config_area_course_id,
                                        level_id,
                                        amount_question,
                                        created_by,
                                        created_at
                                    )
                                    VALUES (
                                        v_exam_material_config_area_course_id,
                                        (v_level->'id')::BIGINT,
                                        (v_level->'amount_question')::INTEGER,
                                        p_user,
                                        NOW()
                                    );
                                END IF;
                            ELSE
                                -- Actualizar configuración de nivel existente
                                UPDATE exam_material_config_area_course_levels
                                SET
                                    amount_question = (v_level->'amount_question')::INTEGER,
                                    updated_by = p_user,
                                    updated_at = NOW()
                                WHERE id = v_exam_material_config_area_course_level_id
                                    AND fl_status = TRUE;
    
                                IF COALESCE((v_level->'amount_question')::INTEGER, 0) = 0 THEN
                                    UPDATE exam_material_config_area_course_levels
                                    SET deleted_at = NOW(), deleted_by = p_user, fl_status = false where id = v_exam_material_config_area_course_level_id;
                                END IF;
                            END IF;
                        END LOOP;
                    END IF;
                END LOOP;
            END LOOP;

            RETURN;
        END;
        $$;


ALTER FUNCTION odiseo.fn_insert_or_update_distribution_levels_exam(p_cycle_id bigint, p_type_material_id bigint, p_exam_materials jsonb, p_user bigint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_insert_or_update_field_digitized_question(bigint, jsonb, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_insert_or_update_field_digitized_question(p_question_id bigint, p_field_diagram jsonb, p_image jsonb, p_user bigint) RETURNS TABLE(result_id bigint, result_employee_didi_question_id bigint, result_diagram_id bigint, result_value text, result_created_by bigint, result_updated_at timestamp without time zone, result_type character varying)
    LANGUAGE plpgsql
    AS $$
                DECLARE
                    v_didi_question_id BIGINT;  -- Variable para almacenar el ID de employee_didi_question
                    v_field JSONB;              -- Variable para cada elemento del JSONB array
                    v_element JSONB;            -- Variable para iterar sobre p_image
                BEGIN

                    PERFORM 1 FROM odiseo.question WHERE id = p_question_id FOR UPDATE;

                    -- Actualizar registro en la tabla employee_didi_question
                    UPDATE employee_didi_question
                    SET updated_by = p_user, updated_at = NOW()
                    WHERE question_id = p_question_id AND fl_status = true;
                
                    -- Obtener el ID de la pregunta actualizada
                    SELECT edq.id
                    INTO v_didi_question_id
                    FROM employee_didi_question edq
                    WHERE edq.question_id = p_question_id AND edq.fl_status = true;

                    -- Eliminar formulas matemáticas de la diagramación
                    WITH updated_rows_didi_maths AS (
                        SELECT dm.id
                        FROM didi_maths dm
                        INNER JOIN employee_didi_question_field edqf ON edqf.id = dm.didi_question_id
                        WHERE 1 = 1 
                        AND edqf.employee_didi_question_id = v_didi_question_id
                        AND dm.fl_status = true
                    )
                    UPDATE didi_maths dm
                    SET fl_status = false, 
                        deleted_by = p_user,
                        deleted_at = now()
                    FROM updated_rows_didi_maths urdm
                    WHERE dm.id = urdm.id;


                    -- Eliminar imágenes de diagramación
                    UPDATE employee_didi_question_field_image edqfi
                    SET fl_status = FALSE, deleted_by = p_user, deleted_at = NOW()
                    WHERE edqfi.employee_didi_question_id = v_didi_question_id;
                
                    -- Iterar sobre el JSONB array p_image
                    FOR v_element IN
                        SELECT jsonb_array_elements(p_image)
                    LOOP
                        INSERT INTO employee_didi_question_field_image (
                            employee_didi_question_id,
                            code,
                            extension,
                            image,
                            created_by,
                            created_at
                        )
                        VALUES (
                            v_didi_question_id,
                            v_element->>'code',        -- Extraer el valor de 'code'
                            v_element->>'extension',   -- Extraer el valor de 'extension'
                            v_element->>'image',       -- Extraer el valor de 'image'
                            p_user,                    -- Usuario que crea el registro
                            NOW()                      -- Fecha de creación
                        );
                    END LOOP;
                
                    -- Insertar o actualizar en employee_didi_question_field y retornar filas
                    RETURN QUERY
                    WITH new_diagrammed_didi_fields AS (
                        INSERT INTO employee_didi_question_field (
                            employee_didi_question_id,
                            setting_diagrammed_course_id,
                            value,
                            created_by,
                            created_at,
                            updated_at
                        ) SELECT
                            v_didi_question_id,
                            ( field->>'id' )::bigint,
                            field->>'description',
                            p_user,
                            NOW(),
                            NOW()
                        FROM JSONB_ARRAY_ELEMENTS( p_field_diagram ) AS field
                        WHERE 1 = 1
                        AND NOT EXISTS( -- Solo inserta si no existen aún campos de diagramación con el mismo id de atributo de diagramación
                            SELECT
                                1
                            FROM employee_didi_question_field
                            WHERE 1 = 1
                            AND employee_didi_question_id = v_didi_question_id
                            AND setting_diagrammed_course_id = ( field->>'id' )::BIGINT
                        )
                        RETURNING 
                            id AS result_id,
                            employee_didi_question_id AS result_employee_didi_question_id,
                            setting_diagrammed_course_id AS diagram_id,
                            value AS result_value,
                            created_by AS result_created_by,
                            created_at AS result_created_at,
                            'create'::CHARACTER varying AS result_type
                    ), updated_diagrammed_didi_field AS (
                        UPDATE employee_didi_question_field edqfu
                            SET
                                value = field->>'description',
                                updated_by = p_user,
                                updated_at = NOW()
                            FROM JSONB_ARRAY_ELEMENTS( p_field_diagram ) AS field
                            WHERE 1 = 1
                            AND edqfu.setting_diagrammed_course_id = ( field->>'id' )::BIGINT
                            AND edqfu.employee_didi_question_id = v_didi_question_id
                            RETURNING 
                                edqfu.id AS result_id,
                                edqfu.employee_didi_question_id AS result_employee_didi_question_id,
                                edqfu.setting_diagrammed_course_id AS result_setting_diagrammed_course_id,
                                edqfu.value AS result_value,
                                edqfu.created_by AS result_created_by,
                                edqfu.updated_at AS updated_at,
                                'update'::CHARACTER varying AS result_type
                    )
                    SELECT * FROM updated_diagrammed_didi_field
                    UNION ALL
                    SELECT * FROM new_diagrammed_didi_fields;
                END;
            $$;


ALTER FUNCTION odiseo.fn_insert_or_update_field_digitized_question(p_question_id bigint, p_field_diagram jsonb, p_image jsonb, p_user bigint) OWNER TO postgres;

--
-- Name: fn_insert_or_update_period_course(bigint, smallint, character varying, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_insert_or_update_period_course(p_material_per_period_ballot_id bigint, p_course_id smallint, p_type character varying, p_job_id character varying, p_created_by bigint) RETURNS TABLE(id bigint, material_per_period_ballot_id bigint, weeks jsonb, type_material_template_id bigint, type_material_template character varying, type_template_id bigint)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                WITH insert_or_update_course AS (
                    INSERT INTO material_per_period_course AS mwc (
                        material_per_period_ballot_id,
                        course_id,
                        type,
                        job_id,
                        created_by
                    )
                    VALUES (
                        p_material_per_period_ballot_id,
                        p_course_id,
                        p_type,
                        p_job_id,
                        p_created_by
                    )
                    ON CONFLICT ON CONSTRAINT period_id_course_type
                    DO UPDATE
                    SET
                        url = NULL,
                        job_id = p_job_id,
                        job_status = 'unprocessed',
                        pages = 0, -- <-- Version 1.1,
                        retries = 0, -- <-- Version 1.1,
                        updated_by = p_created_by,
                        updated_at = NOW(),
                        deleted_by = NULL,
                        deleted_at = NULL
                    RETURNING mwc.id
                )
                SELECT
                    iouc.id,
                    mppb.id AS material_per_period_ballot_id,
                    (
                        SELECT JSONB_AGG(JSONB_BUILD_OBJECT('week', gs))
                        FROM generate_series(mppb.start_week::INT, mppb.end_week::INT) gs
                    ) AS weeks,
                    tm.type_material_template_id,
                    tmt.name AS type_material_template,
                    c.type_template_id
                FROM material_per_period_ballot mppb
                JOIN insert_or_update_course iouc ON 1 = 1
                JOIN material_per_period mpp ON mppb.material_per_period_id = mpp.id
                JOIN type_material tm ON mpp.type_material_id = tm.id
                JOIN cycle c ON tm.cycle_id = c.id
                JOIN type_material_template tmt ON tm.type_material_template_id = tmt.id
                WHERE mppb.id = p_material_per_period_ballot_id;
            END;
            $$;


ALTER FUNCTION odiseo.fn_insert_or_update_period_course(p_material_per_period_ballot_id bigint, p_course_id smallint, p_type character varying, p_job_id character varying, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_insert_or_update_period_week_course(bigint, smallint, smallint, character varying, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_insert_or_update_period_week_course(p_material_per_period_ballot_id bigint, p_course_id smallint, p_week smallint, p_type character varying, p_job_id character varying, p_created_by bigint) RETURNS TABLE(id bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    INSERT INTO material_per_period_week_course AS mwc (material_per_period_ballot_id, course_id, week, job_id, type, created_by)
        VALUES (p_material_per_period_ballot_id, p_course_id, p_week, p_job_id, p_type, p_created_by)
        ON CONFLICT ON CONSTRAINT period_id_course_type_week
        DO UPDATE
            SET
                url = NULL,
                job_id = p_job_id,
                job_status = 'unprocessed',
                updated_by = p_created_by,
                updated_at = NOW(),
                deleted_by = NULL,
                deleted_at = NULL
    RETURNING mwc.id;
END;
$$;


ALTER FUNCTION odiseo.fn_insert_or_update_period_week_course(p_material_per_period_ballot_id bigint, p_course_id smallint, p_week smallint, p_type character varying, p_job_id character varying, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_insert_parent_question(character varying, character varying, text, text, text, text, jsonb, jsonb, character varying, boolean, bigint, integer, text, text, integer, integer, character, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_insert_parent_question(p_code_course character varying, p_num_problem character varying, p_question_text text, p_short_question_text text, p_question_traduction_text text, p_short_question_traduction_text text, p_question_images jsonb, p_origin jsonb, p_authorship character varying, p_diagrammed boolean, p_created_by bigint, p_type_text integer, p_description_b text, p_description_short_b text, p_level integer, p_type_text_subcategory_id integer, p_status character, p_priority smallint) RETURNS TABLE(parent_id bigint, description text, short_description text, code character varying, status character varying, course_id smallint)
    LANGUAGE plpgsql
    AS $$
                                DECLARE
                                    parent_question_id bigint;
                                    v_course_id bigint;
                                    v_last_number TEXT;
                                    v_new_number TEXT;
                                    v_new_code TEXT;
                                    origin JSONB;
                                    v_similary_text TEXT;
                                    v_final_status CHAR(4);
                                    v_codes_list TEXT;
                                    v_obs_desc TEXT;
                                BEGIN
                                    -- Obteniendo el id del curso
                                    SELECT id
                                    INTO v_course_id
                                    FROM course c
                                    WHERE c.code = p_code_course;

                                    -- 1.1 GENERAR CÓDIGO NUEVO
                                    -- *********************************************************
                                    SELECT full_code, number_str 
                                    INTO v_new_code, v_new_number
                                    FROM fn_generate_question_code(v_course_id::INTEGER,'T'::VARCHAR);
                                    -- *********************************************************

                                    --	Verificar si la pregunta tiene duplicados
                                    WITH similarity_question AS (
                                        SELECT fsp.id, (fsp.score * 100)::NUMERIC(10,2) as percentage, fsp.code
                                        FROM fn_search_similar_parent_questions(p_short_question_text, v_course_id) fsp
                                    )
                                    SELECT 
                                        COALESCE(jsonb_agg(jsonb_build_object('id', sq.id, 'percentage', sq.percentage))::TEXT, '[]'),
                                        CASE WHEN EXISTS (SELECT 1 FROM similarity_question) THEN 'DUPL' ELSE p_status END,
                                        string_agg(sq.code, ', ' ORDER BY sq.code ASC)
                                    INTO v_similary_text, v_final_status, v_codes_list
                                    FROM similarity_question sq;

                                    IF v_final_status = 'DUPL' THEN
                                        v_obs_desc := 'Tiene similitud con una o varias preguntas: ' || v_codes_list;
                                    END IF;

                                    -- Insertar la pregunta
                                    INSERT INTO parent_question (
                                        code,
                                        description,
                                        short_description,
                                        text_traduction,
                                        short_text_traduction,
                                        number_question,
                                        number,
                                        course_id,
                                        status,
                                        authorship,
                                        fl_diagrammed,
                                        created_by,
                                        created_at,
                                        type_text_id,
                                        description_b,
                                        short_description_b,
                                        level_id,
                                        type_text_subcategory_id,
                                        priority
                                    )
                                    VALUES (
                                        v_new_code,
                                        p_question_text,
                                        p_short_question_text,
                                        p_question_traduction_text,
                                        p_short_question_traduction_text,
                                        p_num_problem,
                                        v_new_number,
                                        v_course_id,
                                        v_final_status,
                                        p_authorship,
                                        p_diagrammed,
                                        p_created_by,
                                        now(),
                                        p_type_text,
                                        p_description_b,
                                        p_description_short_b,
                                        p_level,
                                        p_type_text_subcategory_id,
                                        p_priority
                                    )
                                    RETURNING id INTO parent_question_id;

                                    -- Insertar las imágenes de la pregunta
                                    INSERT INTO parent_image (code, extension, image, parent_id, created_by, created_at)
                                    SELECT image_question->>'code', image_question->>'extension', image_question->>'image', parent_question_id, p_created_by, now()
                                    FROM jsonb_array_elements(p_question_images) AS image_question;

                                    -- Insertar observación si p_observation no es NULL ni vacío
                                    IF v_final_status = 'DUPL' THEN
                                        INSERT INTO parent_observation (
                                            description,
                                            similitaries,
                                            parent_id,
                                            type,
                                            fl_status,
                                            created_by,
                                            created_at
                                        )
                                        VALUES (
                                            v_obs_desc,
                                            v_similary_text,
                                            parent_question_id,
                                            'DUPL',
                                            true,
                                            p_created_by, now()
                                        );
                                        --	Si es que el padre esta duplicado en este caso los hijos tambien
                                        UPDATE question set status = v_final_status WHERE question.parent_id = parent_question_id;
                                    END IF;

                                    -- Insertar los origenes de la pregunta
                                    FOR origin IN SELECT * FROM jsonb_array_elements(p_origin) LOOP
                                        INSERT INTO origin_parent_question (
                                            parent_id,
                                            year,
                                            region_id,
                                            modality_option_id,
                                            areas,
                                            version,
                                            created_by,
                                            created_at
                                        )
                                        VALUES (
                                            parent_question_id,
                                            (origin->>'year')::VARCHAR,
                                            (origin->>'region_id')::BIGINT,
                                            (origin->>'modality_id')::SMALLINT,
                                            (origin->>'areas')::VARCHAR,
                                            (origin->>'version')::SMALLINT,
                                            p_created_by,
                                            now()
                                        );
                                    END LOOP;

                                    RETURN QUERY 
                                    SELECT pq.id parent_id, pq.description, pq.short_description, pq.code, pq.status, pq.course_id
                                    FROM parent_question pq WHERE pq.id = parent_question_id;
                                END;
                                $$;


ALTER FUNCTION odiseo.fn_insert_parent_question(p_code_course character varying, p_num_problem character varying, p_question_text text, p_short_question_text text, p_question_traduction_text text, p_short_question_traduction_text text, p_question_images jsonb, p_origin jsonb, p_authorship character varying, p_diagrammed boolean, p_created_by bigint, p_type_text integer, p_description_b text, p_description_short_b text, p_level integer, p_type_text_subcategory_id integer, p_status character, p_priority smallint) OWNER TO postgres;

--
-- Name: fn_insert_question_gpt(text, text, smallint, jsonb, jsonb, smallint, smallint, smallint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_insert_question_gpt(p_question_text text, p_question_short text, p_course_id smallint, p_alternatives jsonb, p_solutions jsonb, p_topic_id smallint, p_subtopic_id smallint, p_level_id smallint, p_config_alternative_id bigint, p_created_by bigint) RETURNS TABLE(question_id bigint, question_code character varying)
    LANGUAGE plpgsql
    AS $$
			DECLARE
                v_question_id BIGINT;
                v_teacher_id BIGINT;
                v_didi_id BIGINT;
                v_number TEXT;
                v_code_course TEXT;
                v_alternative JSONB;
                v_alternative_id BIGINT;
                v_answer_id BIGINT;
                v_week INT;
                v_year INT;
                v_employee_question_id BIGINT;
                v_employee_didi_question_id BIGINT;
                v_solution JSONB;
            BEGIN
                -- Almacenar semana y año
                v_week := EXTRACT(WEEK FROM CURRENT_DATE);
                v_year := EXTRACT(YEAR FROM CURRENT_DATE);

                -- Obtener datos del docente
                SELECT id INTO v_teacher_id FROM odiseo.employees WHERE document = '11111111' AND charge_id = 2 LIMIT 1;

                -- Obtener datos del didi
                SELECT id INTO v_didi_id FROM odiseo.employees WHERE document = '22222222' AND charge_id = 3 LIMIT 1;

                -- Obtener código de curso
                SELECT code INTO v_code_course FROM odiseo.course WHERE id = p_course_id LIMIT 1;

                -- Obtener numero de pregunta
                SELECT LPAD(CAST(COALESCE(CAST(MAX(number) AS INTEGER) + 1, 1) AS TEXT), 7, '0') INTO v_number FROM odiseo.question WHERE course_id = p_course_id AND fl_status = true LIMIT 1;

                -- Insertar pregunta
                INSERT INTO odiseo.question
                (code, description, short_description, course_id, topic_id, level_id, type, ter, status, number, fl_diagrammed, config_alternative_id, created_by, created_at)
                VALUES (CONCAT(v_code_course::VARCHAR, '-', v_number)::VARCHAR, p_question_text, p_question_short, p_course_id, p_topic_id, p_level_id, 'T', 0, 'VERI', v_number, false, p_config_alternative_id, p_created_by, now())
                RETURNING id INTO v_question_id;

                -- Insertar subtema de la pregunta
                INSERT INTO odiseo.question_subtopic (question_id, subtopic_id, created_by, created_at)
                VALUES (v_question_id, p_subtopic_id, p_created_by, now());

                -- Se almacenan las alternativas
                FOR v_alternative IN SELECT jsonb_array_elements(p_alternatives) LOOP
                    INSERT INTO odiseo.alternative (description, question_id, created_by, created_at) VALUES ((v_alternative->>'text')::TEXT, v_question_id, p_created_by, now())
                    RETURNING id INTO v_alternative_id;

                    -- Si encuentra la alternativa correcta se actualiza ese registro
                    IF ((v_alternative->>'answer')::BOOLEAN IS TRUE) THEN
                        v_answer_id := v_alternative_id;

                        UPDATE odiseo.question SET answer_id = v_answer_id WHERE id = v_question_id;
                    END IF;
                END LOOP;

                -- Insertar estado de pregunta
                INSERT INTO odiseo.question_status (question_id, status, process, description, created_by, created_at)
                VALUES (v_question_id, 'VERI', 'VERIFICADO', 'La pregunta ha sido verificada por el usuario <span class="text-teacher">Didi</span> por GPT', p_created_by, now());

                -- Insertar relación de docente
                INSERT INTO odiseo.employee_question (teacher_id, question_id, alternative_id, type, week, year, solved, created_by, created_at)
                VALUES (v_teacher_id, v_question_id, v_answer_id, 'MANUAL', v_week, v_year, true, p_created_by, now())
                RETURNING id INTO v_employee_question_id;

                -- Insertar relación con el didi
                INSERT INTO odiseo.employee_didi_question (employee_id, question_id, week, year, diagrammed, created_by, created_at)
                VALUES (v_didi_id, v_question_id, v_week, v_year, true, p_created_by, now())
                RETURNING id INTO v_employee_didi_question_id;

                -- Insertar solución
                FOR v_solution IN SELECT jsonb_array_elements(p_solutions) LOOP
                    INSERT INTO odiseo.employee_didi_question_field (employee_didi_question_id, setting_diagrammed_course_id, value, created_by, created_at)
                    VALUES (v_employee_didi_question_id, (v_solution->>'setting_diagrammed_id')::BIGINT, (v_solution->>'text')::TEXT, p_created_by, now());
                END LOOP;

                RETURN QUERY SELECT v_question_id, CONCAT(v_code_course::VARCHAR, '-', v_number)::VARCHAR;
            END;
            $$;


ALTER FUNCTION odiseo.fn_insert_question_gpt(p_question_text text, p_question_short text, p_course_id smallint, p_alternatives jsonb, p_solutions jsonb, p_topic_id smallint, p_subtopic_id smallint, p_level_id smallint, p_config_alternative_id bigint, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_insert_question_shares(bigint, smallint, integer, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_insert_question_shares(p_question_id bigint, p_subtopic_id smallint, p_course_id integer, p_created_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_uuids      UUID[];
    v_record     RECORD;
    v_new_code   TEXT;
    v_new_number TEXT;
BEGIN
    -- Obtener todos los UUIDs compartidos
    SELECT array_agg(uuid)
    INTO v_uuids
    FROM network_course_topic_subtopic
    WHERE subtopic_id = p_subtopic_id
      AND course_id = p_course_id
      AND deleted_at IS NULL;

    -- Si no hay UUIDs
    IF v_uuids IS NULL OR array_length(v_uuids, 1) IS NULL THEN
        RETURN;
    END IF;

    -- Buscar cursos relacionados
    FOR v_record IN
        SELECT course_id, topic_id, subtopic_id
        FROM network_course_topic_subtopic
        WHERE uuid = ANY(v_uuids)
          AND course_id <> p_course_id
          AND deleted_at IS NULL
    LOOP

        SELECT full_code, number_str
        INTO v_new_code, v_new_number
        FROM fn_generate_question_code(
            v_record.course_id::INTEGER,
            'P'::VARCHAR
        );

        INSERT INTO question_shares (
            question_id,
            course_id,
            code,
            topic_id,
            subtopic_id,
            created_by,
            created_at
        )
        VALUES (
            p_question_id,
            v_record.course_id,
            v_new_code,
            v_record.topic_id,
            v_record.subtopic_id,
            p_created_by,
            NOW()
        );

    END LOOP;
END;
$$;


ALTER FUNCTION odiseo.fn_insert_question_shares(p_question_id bigint, p_subtopic_id smallint, p_course_id integer, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_insert_question_status(integer, character varying, character varying, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_insert_question_status(p_question_id integer, p_status character varying, process character varying, description character varying, p_created_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
            BEGIN
                UPDATE odiseo.question_status
                SET fl_active = false
                WHERE question_id = p_question_id;

                INSERT INTO odiseo.question_status (question_id, status, process, description, created_by, created_at)
                VALUES (p_question_id, p_status, process, description, p_created_by, now());
            END;
            $$;


ALTER FUNCTION odiseo.fn_insert_question_status(p_question_id integer, p_status character varying, process character varying, description character varying, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_insert_question_with_alternatives(character varying, character varying, character varying, character varying, smallint, text, text, integer, jsonb, jsonb, jsonb, bigint, character varying, text, character varying, character varying, integer, character varying, integer, integer, character varying, character varying, character varying, boolean, bigint, integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_insert_question_with_alternatives(p_code character varying, p_code_course character varying, p_num_problem character varying, p_num character varying, p_topic_id smallint, p_question_text text, p_question_short text, p_parent_id integer, p_question_images jsonb, p_alternatives jsonb, p_alternative_images jsonb, p_config_alternative_id bigint, p_observation character varying, p_similary text, p_status character varying, p_region character varying, p_university integer, p_year character varying, p_option integer, p_modality integer, p_version character varying, p_area character varying, p_authorship character varying, p_diagrammed boolean, p_created_by bigint, p_cycle_id integer, p_week_id integer, p_type_material_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
            DECLARE
                question_id bigint;
                alternative_id bigint;
                course_id bigint;
                image_question JSONB;
                image_alternative JSONB;
                alternative JSONB;
            BEGIN
                -- Obteniendo el id del curso
                SELECT id
                INTO course_id
                FROM odiseo.course c
                WHERE c.code = p_code_course;
                -- Insertar la pregunta
                INSERT INTO odiseo.question (code, description, short_description, number_question, number, course_id, topic_id, parent_id, status, region, university_id, year, option_id, modality_id, config_alternative_id, version, area, authorship, fl_diagrammed, created_by, created_at)
                VALUES (p_code, p_question_text, p_question_short, p_num_problem, p_num, course_id, p_topic_id, p_parent_id, p_status, p_region, p_university, p_year, p_option,  p_modality, p_config_alternative_id, p_version, p_area, p_authorship, p_diagrammed, p_created_by, now())
                RETURNING id INTO question_id;
                -- Insertar las imágenes de la pregunta
                FOR image_question IN SELECT * FROM jsonb_array_elements(p_question_images) LOOP
                    INSERT INTO odiseo.question_image (code, extension, image, question_id, created_by, created_at)
                    VALUES (image_question->>'code', image_question->>'extension', image_question->>'image', question_id, p_created_by, now());
                END LOOP;
                -- Insertar las imágenes de alternativas
                FOR image_alternative IN SELECT * FROM jsonb_array_elements(p_alternative_images) LOOP
                    INSERT INTO odiseo.question_image (code, extension, image, question_id, created_by, created_at)
                    VALUES (image_alternative->>'code', image_alternative->>'extension', image_alternative->>'image', question_id, p_created_by, now());
                END LOOP;

                -- Insertar las alternativas y actualizar el ID de la respuesta si es 100
                FOR alternative IN SELECT * FROM jsonb_array_elements(p_alternatives) LOOP
                    INSERT INTO odiseo.alternative (description, question_id, created_by, created_at)
                    VALUES (alternative->>'value', question_id, p_created_by, now())
                    RETURNING id INTO alternative_id;

                    -- Si el answer es igual a 100, almacenar el ID de la alternativa en la pregunta
                    IF alternative->>'answer' = '100' THEN
                        UPDATE odiseo.question
                        SET answer_id = alternative_id
                        WHERE id = question_id;
                    END IF;
                END LOOP;

                -- Insertar observación si p_observation no es NULL ni vacío
                IF p_observation IS NOT NULL AND p_observation <> '' THEN
                    INSERT INTO odiseo.question_observation (description, similitaries, question_id, type, fl_status, created_by, created_at)
                    VALUES (p_observation, p_similary, question_id, 'DUPL', true, p_created_by, now());
                END IF;

                -- Insertar data temporal cycly, week and type_material
                IF p_cycle_id IS NOT NULL OR p_week_id IS NOT NULL OR p_type_material_id IS NOT NULL THEN
                    INSERT INTO odiseo.question_temporary (question_id, cycle_id, week_id, type_material_id, created_by, created_at)
                    VALUES (question_id, p_cycle_id, p_week_id, p_type_material_id, p_created_by, now());
                END IF;

                RETURN question_id;
            END;
            $$;


ALTER FUNCTION odiseo.fn_insert_question_with_alternatives(p_code character varying, p_code_course character varying, p_num_problem character varying, p_num character varying, p_topic_id smallint, p_question_text text, p_question_short text, p_parent_id integer, p_question_images jsonb, p_alternatives jsonb, p_alternative_images jsonb, p_config_alternative_id bigint, p_observation character varying, p_similary text, p_status character varying, p_region character varying, p_university integer, p_year character varying, p_option integer, p_modality integer, p_version character varying, p_area character varying, p_authorship character varying, p_diagrammed boolean, p_created_by bigint, p_cycle_id integer, p_week_id integer, p_type_material_id integer) OWNER TO postgres;

--
-- Name: fn_insert_question_with_alternatives_v2(character varying, character varying, smallint, smallint, text, text, integer, jsonb, jsonb, jsonb, bigint, jsonb, character varying, boolean, bigint, integer, integer, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_insert_question_with_alternatives_v2(p_code_course character varying, p_num_problem character varying, p_topic_id smallint, p_question_columns smallint, p_question_text text, p_question_short text, p_parent_id integer, p_question_images jsonb, p_alternatives jsonb, p_alternative_images jsonb, p_config_alternative_id bigint, p_origin jsonb, p_authorship character varying, p_diagrammed boolean, p_created_by bigint, p_week_id integer, p_type_material_template_id integer, p_priority smallint) RETURNS TABLE(question_id bigint, description text, short_description text, code character varying, status character varying, course_id smallint, parent_id bigint, alternatives jsonb)
    LANGUAGE plpgsql
    AS $$
                    DECLARE
                        v_question_id bigint;
                        alternative_id bigint;
                        v_course_id bigint;
                        image_question JSONB;
                        image_alternative JSONB;
                        alternative JSONB;
                        origin JSONB;
                        v_last_number TEXT;
                        v_new_number TEXT;
                        v_new_code TEXT;
                        v_similary_text TEXT;
                        v_final_status CHAR(4);
                        v_codes_list TEXT;
                        v_obs_desc TEXT;
                        v_status_parent CHAR(4);
                    BEGIN
                        -- Obteniendo el id del curso
                        SELECT id
                        INTO v_course_id
                        FROM course c
                        WHERE c.code = p_code_course LIMIT 1;

                        -- 1.1 GENERAR CÓDIGO NUEVO
                        -- *********************************************************
                        SELECT full_code, number_str 
                        INTO v_new_code, v_new_number
                        FROM fn_generate_question_code(v_course_id::INTEGER,'P'::VARCHAR);
                        -- *********************************************************

                        --	Verificar si la pregunta tiene duplicados
                        WITH similarity_question AS (
                            SELECT fsq.id, (fsq.score * 100)::NUMERIC(10,2) as percentage, fsq.code
                            FROM fn_search_similar_questions(p_question_short, v_course_id) fsq
                        )
                        SELECT
                            COALESCE(jsonb_agg(jsonb_build_object('id', sq.id, 'percentage', percentage))::TEXT, '[]'),
                            CASE WHEN EXISTS (SELECT 1 FROM similarity_question) THEN 'DUPL' ELSE 'SASI' END,
                            string_agg(sq.code, ', ' ORDER BY sq.code ASC)
                        INTO v_similary_text, v_final_status, v_codes_list
                        FROM similarity_question sq;

                        IF v_final_status = 'DUPL' THEN
                            v_obs_desc := 'Tiene similitud con una o varias preguntas: ' || v_codes_list;
                        END IF;

                        -- Insertar la pregunta
                        INSERT INTO question (
                            code,
                            description,
                            short_description,
                            number_question,
                            number,
                            course_id,
                            topic_id,
                            columns,
                            parent_id,
                            status,
                            config_alternative_id,
                            authorship,
                            fl_diagrammed,
                            priority,
                            created_by,
                            created_at
                        )
                        VALUES (
                            v_new_code,
                            p_question_text,
                            p_question_short,
                            p_num_problem,
                            v_new_number,
                            v_course_id,
                            p_topic_id,
                            p_question_columns,
                            p_parent_id,
                            v_final_status,
                            p_config_alternative_id,
                            p_authorship,
                            p_diagrammed,
                            p_priority,
                            p_created_by,
                            now()
                        )
                        RETURNING id INTO v_question_id;

                        IF p_parent_id IS NOT NULL THEN
                            -- Si el estado del padre ya es duplicado ya no es necesario validar las subpreguntas
                            SELECT pq.status INTO v_status_parent FROM parent_question pq WHERE pq.id = p_parent_id;

                            IF v_status_parent = 'DUPL' THEN
                                UPDATE question set status = v_status_parent WHERE id = v_question_id;
                            ELSE --	Verificar si la subpregunta tiene duplicados
                                WITH similarity_question AS (
                                    SELECT fsq.id, (fsq.score * 100)::NUMERIC(10,2) as percentage, fsq.code
                                    FROM fn_search_similar_sub_question(p_question_short, p_parent_id, v_question_id) fsq
                                )
                                SELECT 
                                    COALESCE(jsonb_agg(jsonb_build_object('id', sq.id, 'percentage', percentage))::TEXT, '[]'),
                                    CASE WHEN EXISTS (SELECT 1 FROM similarity_question) THEN 'DUPL' ELSE 'SASI' END,
                                    string_agg(sq.code, ', ' ORDER BY sq.code ASC)
                                INTO v_similary_text, v_final_status, v_codes_list
                                FROM similarity_question sq;

                                IF v_final_status = 'DUPL' THEN
                                    v_obs_desc := 'Tiene similitud con una o varias preguntas: ' || v_codes_list;
                                    -- Si existen subpreguntas duplicadas entonces el texto tambien pasa a duplicado
                                    UPDATE parent_question SET status = v_final_status WHERE id = p_parent_id;
                                    -- Tambien actualizar la pregunta actual
                                    UPDATE question set status = v_final_status WHERE id = v_question_id;	
                                ELSE
                                    UPDATE question set status = v_final_status WHERE id = v_question_id;
                                END IF;
                            END IF;

                        END IF;

                        -- Insertar las imágenes de la pregunta
                        FOR image_question IN SELECT * FROM jsonb_array_elements(p_question_images) LOOP
                            INSERT INTO question_image (
                                code,
                                extension,
                                image,
                                question_id,
                                created_by,
                                created_at
                            )
                            VALUES (
                                image_question->>'code',
                                image_question->>'extension',
                                image_question->>'image',
                                v_question_id,
                                p_created_by,
                                now()
                            );
                        END LOOP;

                        -- Insertar las imágenes de alternativas
                        FOR image_alternative IN SELECT * FROM jsonb_array_elements(p_alternative_images) LOOP
                            INSERT INTO question_image (
                                code,
                                extension,
                                image,
                                question_id,
                                created_by,
                                created_at
                            )
                            VALUES (
                                image_alternative->>'code',
                                image_alternative->>'extension',
                                image_alternative->>'image',
                                v_question_id,
                                p_created_by,
                                now()
                            );
                        END LOOP;

                        -- Insertar las alternativas y actualizar el ID de la respuesta si es 100
                        FOR alternative IN SELECT * FROM jsonb_array_elements(p_alternatives) LOOP
                            INSERT INTO alternative (
                                description,
                                question_id,
                                created_by,
                                created_at
                            )
                            VALUES (
                                alternative->>'value',
                                v_question_id,
                                p_created_by,
                                now()
                            )
                            RETURNING id INTO alternative_id;

                            -- Si el answer es igual a 100, almacenar el ID de la alternativa en la pregunta
                            IF alternative->>'answer' = '100' THEN
                                UPDATE question
                                SET answer_id = alternative_id
                                WHERE id = v_question_id;
                            END IF;
                        END LOOP;

                        -- Insertar observación si p_observation no es NULL ni vacío
                        IF v_final_status = 'DUPL' THEN
                            INSERT INTO question_observation (
                                description,
                                similitaries,
                                question_id,
                                type,
                                fl_status,
                                created_by,
                                created_at
                            )
                            VALUES (
                                v_obs_desc,
                                v_similary_text,
                                v_question_id,
                                'DUPL',
                                true,
                                p_created_by, now()
                            );
                        END IF;
               
                        -- Insertar los origenes de la pregunta
                        FOR origin IN SELECT * FROM jsonb_array_elements(p_origin) LOOP
                            INSERT INTO origin_question (
                                question_id,
                                year,
                                region_id,
                                modality_option_id,
                                areas,
                                version,
                                created_by,
                                created_at
                            )
                            VALUES (
                                v_question_id,
                                (origin->>'year')::VARCHAR,
                                (origin->>'region_id')::BIGINT,
                                (origin->>'modality_id')::SMALLINT,
                                (origin->>'areas')::VARCHAR,
                                (origin->>'version')::SMALLINT,
                                p_created_by,
                                now()
                            );
                        END LOOP;

                        RETURN QUERY
                        SELECT
                            q.id AS question_id,
                            q.description,
                            q.short_description,
                            q.code,
                            q.status,
                            q.course_id,
                            q.parent_id,
                            COALESCE(
                                (SELECT JSONB_AGG(
                                    JSONB_BUILD_OBJECT(
                                        'id', a.id,
                                        'description', a.description,
                                        'question_id', a.question_id
                                    )
                                )
                                FROM alternative a
                                WHERE a.question_id = q.id
                                    AND a.fl_status = true),
                                '[]'::JSONB
                            ) as alternatives
                        FROM question q
                        WHERE q.id = v_question_id;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_insert_question_with_alternatives_v2(p_code_course character varying, p_num_problem character varying, p_topic_id smallint, p_question_columns smallint, p_question_text text, p_question_short text, p_parent_id integer, p_question_images jsonb, p_alternatives jsonb, p_alternative_images jsonb, p_config_alternative_id bigint, p_origin jsonb, p_authorship character varying, p_diagrammed boolean, p_created_by bigint, p_week_id integer, p_type_material_template_id integer, p_priority smallint) OWNER TO postgres;

--
-- Name: fn_insert_questions_missing_exam(jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_insert_questions_missing_exam(p_missing_exam jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
        BEGIN
            WITH get_missing_question AS (
                SELECT
                    (me->>'exam_area_id')::SMALLINT AS exam_area_id,
                    (me->>'detail_week_mat')::BIGINT AS detail_week_mat,
                    (me->>'course_id')::BIGINT AS course_id,
                    (me->>'level_id')::BIGINT AS level_id,
                    (me->>'user_id')::BIGINT AS user_id
                FROM jsonb_array_elements(p_missing_exam) AS me
            ), get_material_exam_area_week AS (
                SELECT
                    gmq.*,
                    FALSE::BOOLEAN AS fl_is_manual,
                    NOW() AS created_at,
                    meaw.id AS material_exam_area_week_id
                FROM get_missing_question gmq
                JOIN material_exam_area_week meaw ON gmq.detail_week_mat = meaw.week_type_material_id
                    AND gmq.exam_area_id = meaw.area_id
                    AND meaw.fl_status = true
            )
            INSERT INTO material_exam_question (
                material_exam_area_week_id,
                course_id,
                level_id,
                fl_is_manual,
                created_by,
                created_at
            )
            SELECT
                gmeaw.material_exam_area_week_id,
                gmeaw.course_id,
                gmeaw.level_id,
                gmeaw.fl_is_manual,
                gmeaw.user_id,
                gmeaw.created_at
            FROM get_material_exam_area_week gmeaw;
        END;
        $$;


ALTER FUNCTION odiseo.fn_insert_questions_missing_exam(p_missing_exam jsonb) OWNER TO postgres;

--
-- Name: question; Type: TABLE; Schema: odiseo; Owner: postgres
--

CREATE TABLE odiseo.question (
    id bigint NOT NULL,
    code character varying(25),
    description text NOT NULL,
    short_description text NOT NULL,
    number_question character varying(255),
    course_id smallint NOT NULL,
    topic_id smallint,
    subtopic_id smallint,
    level_id smallint,
    teacher_id bigint,
    answer_id bigint,
    type character varying(255),
    ter numeric(10,2),
    status character varying(5) NOT NULL,
    fl_status boolean DEFAULT true NOT NULL,
    created_by bigint,
    updated_by bigint,
    deleted_by bigint,
    created_at timestamp(0) without time zone,
    updated_at timestamp(0) without time zone,
    deleted_at timestamp(0) without time zone,
    number character varying(255),
    parent_id bigint,
    year character varying(4),
    authorship character varying(255),
    fl_diagrammed boolean DEFAULT false NOT NULL,
    url_pdf character varying(255),
    region character varying(255),
    area character varying(255),
    config_alternative_id bigint DEFAULT '1'::bigint NOT NULL,
    resv_to_veri_at timestamp(0) without time zone,
    columns smallint DEFAULT '2'::smallint NOT NULL,
    math_migration_status character varying(255) DEFAULT 'NOT_MIGRATED'::character varying NOT NULL,
    migrated_updated_at timestamp(0) without time zone,
    url_pdf_updated_at timestamp(0) without time zone,
    status_changed_at timestamp(0) without time zone,
    ia_generated boolean DEFAULT false NOT NULL,
    priority integer,
    is_migrated boolean DEFAULT false NOT NULL,
    search_text text GENERATED ALWAYS AS (lower(odiseo.fn_immutable_unaccent((((COALESCE(code, ''::character varying))::text || ' '::text) || COALESCE(short_description, ''::text))))) STORED,
    CONSTRAINT question_math_migration_status_check CHECK (((math_migration_status)::text = ANY (ARRAY[('NOT_MIGRATED'::character varying)::text, ('MIGRATING'::character varying)::text, ('MIGRATED'::character varying)::text, ('NOT_MIGRATABLE'::character varying)::text, ('MIGRATION_FAILURE'::character varying)::text]))),
    CONSTRAINT question_type_check CHECK (((type)::text = ANY (ARRAY[('T'::character varying)::text, ('D'::character varying)::text])))
);


ALTER TABLE odiseo.question OWNER TO postgres;

--
-- Name: TABLE question; Type: SECURITY LABEL; Schema: odiseo; Owner: postgres
--

SECURITY LABEL FOR anon ON COLUMN odiseo.question.description IS 'MASKED WITH FUNCTION anon.html_math_aware_mask(description)';


--
-- Name: fn_insert_verified_question_with_alternatives(integer, character varying, jsonb, integer, integer, character varying, boolean, smallint, smallint, jsonb, integer, integer, integer, character varying, numeric, text, text, jsonb, jsonb, jsonb, bigint, bigint, integer, boolean, jsonb, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_insert_verified_question_with_alternatives(pf_course_id integer, p_authorship character varying, p_origin jsonb, p_year integer, pf_parent_id integer, p_question_number character varying, p_diagrammed boolean, pf_topic_id smallint, pf_question_columns smallint, pf_subtopic_ids jsonb, p_type_material_template_id integer, p_week_id integer, pf_level_id integer, p_type_id character varying, p_ter numeric, p_question_text text, p_question_short text, p_question_images jsonb, p_alternatives jsonb, p_alternative_images jsonb, pf_config_alternative_id bigint, pf_created_by bigint, p_teacher_id integer, p_is_from_text boolean, p_question_attributes jsonb, p_priority smallint) RETURNS odiseo.question
    LANGUAGE plpgsql
    AS $$
                            DECLARE
                                v_teacher_id BIGINT;
                                v_question_id question.id%TYPE;
                                v_alternative_id bigint;
                                v_image_question JSONB;
                                v_image_alternative JSONB;
                                v_alternative JSONB;
                                v_subtopic_id INT;
                                v_employee_didi_question_id BIGINT;
                                v_employee_id INT;
                                v_last_number TEXT;
                                v_new_number TEXT;
                                v_new_code TEXT;
                                v_code_course TEXT;
                                v_fl_status TEXT;
                                result question%ROWTYPE;
                                origin JSONB;
                                v_modality_ids SMALLINT[] := ARRAY[]::SMALLINT[]; 
                                v_university_ids SMALLINT[] := ARRAY[]::SMALLINT[]; 
                                v_similary_text TEXT;
                                v_final_status CHAR(4);
                                v_codes_list TEXT;
                                v_obs_desc TEXT;
                                v_status_parent CHAR(4);
                            BEGIN

                                -- Asignación a VARIABLES
                                SELECT code INTO v_code_course FROM course
                                WHERE id = pf_course_id;

                                SELECT e.id INTO v_employee_id
                                FROM employees e
                                INNER JOIN users u
                                ON e.user_id = u.id
                                WHERE u.id = pf_created_by;

                                -- 1.1 GENERAR CÓDIGO NUEVO
                                -- *********************************************************
                                SELECT full_code, number_str 
                                INTO v_new_code, v_new_number
                                FROM fn_generate_question_code(pf_course_id,'P'::VARCHAR);
                                -- *********************************************************

                                --	Verificar si la pregunta tiene duplicados
                                WITH similarity_question AS (
                                    SELECT fsq.id, (fsq.score * 100)::NUMERIC(10,2) as percentage, fsq.code
                                    FROM fn_search_similar_questions(p_question_short, pf_course_id) fsq
                                )
                                SELECT 
                                    COALESCE(jsonb_agg(jsonb_build_object('id', sq.id, 'percentage', percentage))::TEXT, '[]'),
                                    CASE WHEN EXISTS (SELECT 1 FROM similarity_question) THEN 'DUPL' ELSE 'PEND' END,
                                    string_agg(sq.code, ', ' ORDER BY sq.code ASC)
                                INTO v_similary_text, v_final_status, v_codes_list
                                FROM similarity_question sq;

                                IF v_final_status = 'DUPL' THEN
                                    v_obs_desc := 'Tiene similitud con una o varias preguntas: ' || v_codes_list;
                                END IF;

                                IF v_final_status <> 'DUPL' AND v_final_status <> 'PEND' THEN
                                    RAISE EXCEPTION 'Estado inválido. Debe ser PEND o DUPL. Recibió %', v_final_status;
                                END IF;

                                -- Insertar la pregunta
                                INSERT INTO question (
                                    code,
                                    number,
                                    description,
                                    short_description,
                                    number_question,
                                    course_id,
                                    topic_id,
                                    columns,
                                    level_id,
                                    type,
                                    ter,
                                    parent_id,
                                    status,
                                    config_alternative_id,
                                    authorship,
                                    fl_diagrammed,
                                    priority,
                                    created_by,
                                    created_at
                                )
                                VALUES (
                                    v_new_code,
                                    v_new_number,
                                    p_question_text,
                                    p_question_short,
                                    p_question_number,
                                    pf_course_id,
                                    pf_topic_id,
                                    pf_question_columns,
                                    pf_level_id,
                                    p_type_id,
                                    p_ter,
                                    pf_parent_id,
                                    v_final_status,
                                    pf_config_alternative_id,
                                    p_authorship,
                                    p_diagrammed,
                                    p_priority,
                                    pf_created_by,
                                    NOW()
                                )
                                RETURNING id INTO v_question_id;

                                -- Asignar a Employee (Didi, GM o Admin)
                                INSERT INTO employee_didi_question (employee_id, question_id, week, year, created_by, created_at, diagrammed)
                                VALUES (v_employee_id, v_question_id, p_week_id, p_year,
                                        pf_created_by, NOW(), true)
                                RETURNING id INTO v_employee_didi_question_id;

                                -- Asignación a Docente Ghost
                                INSERT INTO employee_question (teacher_id, question_id, week, year, created_by, created_at, solved)
                                VALUES (p_teacher_id, v_question_id, p_week_id, p_year, pf_created_by, NOW(), true);

                                -- Insertar origines de preguntas
                                FOR origin IN SELECT * FROM jsonb_array_elements(p_origin) LOOP

                                    v_modality_ids := array_append(
                                        v_modality_ids,
                                        (origin->>'modality_id')::SMALLINT
                                    );

                                    v_university_ids := array_append(
                                        v_university_ids,
                                        (origin->>'university_id')::SMALLINT
                                    );


                                    INSERT INTO origin_question (
                                        question_id,
                                        year,
                                        region_id,
                                        modality_option_id,
                                        areas,
                                        version,
                                        created_by,
                                        created_at
                                    )
                                    VALUES (
                                        v_question_id,
                                        (origin->>'year')::VARCHAR,
                                        (origin->>'region_id')::BIGINT,
                                        (origin->>'modality_id')::SMALLINT,
                                        (origin->>'areas')::VARCHAR,
                                        (origin->>'version')::SMALLINT,
                                        pf_created_by,
                                        now()
                                    );
                                END LOOP;

                                -- SubTopics
                                FOR v_subtopic_id IN SELECT * FROM jsonb_array_elements(pf_subtopic_ids)
                                LOOP
                                    INSERT INTO question_subtopic (question_id, subtopic_id, created_by, created_at)
                                    VALUES (v_question_id, v_subtopic_id, pf_created_by, now());
                                END LOOP;
                                -- remover duplicados
                                v_modality_ids   := (SELECT ARRAY(SELECT DISTINCT unnest(v_modality_ids)));
                                v_university_ids := (SELECT ARRAY(SELECT DISTINCT unnest(v_university_ids)));

                                PERFORM odiseo.fn_change_subtopic_frequent_status(
                                    uc.university_id::int,
                                    uc.subtopic_id::int,
                                    pf_created_by::int,
                                    true,
                                    'system'
                                )
                                FROM (
                                    SELECT DISTINCT 
                                        u.university_id,
                                        s.subtopic_id::INTEGER AS subtopic_id
                                    FROM unnest(v_modality_ids) AS m(modality_id)  
                                    JOIN modality mo 
                                        ON mo.id = m.modality_id
                                    AND mo.fl_allows_mark_frequent_topic = TRUE
                                    CROSS JOIN unnest(v_university_ids) AS u(university_id)
                                    CROSS JOIN jsonb_array_elements(pf_subtopic_ids) AS s(subtopic_id)
                                ) AS uc;

                                -- Insertar las imágenes de la pregunta
                                FOR v_image_question IN SELECT * FROM jsonb_array_elements(p_question_images) LOOP
                                    INSERT INTO question_image (code, extension, image, question_id, created_by, created_at)
                                    VALUES (
                                        v_image_question->>'code',
                                        v_image_question->>'extension',
                                        v_image_question->>'image',
                                        v_question_id,
                                        pf_created_by,
                                        NOW()
                                    );
                                END LOOP;
                                --
                                -- Insertar las imágenes de alternativas
                                FOR v_image_alternative IN SELECT * FROM jsonb_array_elements(p_alternative_images) LOOP
                                    INSERT INTO question_image (code, extension, image, question_id, created_by, created_at)
                                    VALUES (
                                        v_image_alternative->>'code',
                                        v_image_alternative->>'extension',
                                        v_image_alternative->>'image',
                                        v_question_id,
                                        pf_created_by,
                                        NOW()
                                    );
                                END LOOP;
                                --
                                -- Insertar las alternativas y actualizar el ID de la respuesta si es 100
                                FOR v_alternative IN SELECT * FROM jsonb_array_elements(p_alternatives) LOOP
                                    INSERT INTO alternative (description, question_id, created_by, created_at)
                                    VALUES (v_alternative->>'value', v_question_id, pf_created_by, now())
                                    RETURNING id INTO v_alternative_id;

                                    -- Si el answer es igual a 100, almacenar el ID de la alternativa en la pregunta
                                    IF v_alternative->>'answer' = '100' THEN
                                        UPDATE question
                                        SET answer_id = v_alternative_id
                                        WHERE id = v_question_id;
                                    END IF;
                                END LOOP;
                                --
                                IF pf_parent_id IS NOT NULL THEN
                                    -- Si el estado del padre ya es duplicado ya no es necesario validar las subpreguntas
                                    SELECT pq.status INTO v_status_parent FROM parent_question pq WHERE pq.id = pf_parent_id;
                                        IF v_status_parent = 'DUPL' THEN	
                                            UPDATE question set status = v_status_parent WHERE id = v_question_id;
                                        ELSE
                                            --	Verificar si la subpregunta tiene duplicados
                                            WITH similarity_question AS (
                                                SELECT fsq.id, (fsq.score * 100)::NUMERIC(10,2) as percentage, fsq.code
                                                FROM fn_search_similar_sub_question(p_question_short, pf_parent_id, v_question_id) fsq
                                            )
                                            SELECT 
                                                COALESCE(jsonb_agg(jsonb_build_object('id', sq.id, 'percentage', percentage))::TEXT, '[]'),
                                                CASE WHEN EXISTS (SELECT 1 FROM similarity_question) THEN 'DUPL' ELSE 'PEND' END,
                                                string_agg(sq.code, ', ' ORDER BY sq.code ASC)
                                            INTO v_similary_text, v_final_status, v_codes_list
                                            FROM similarity_question sq;
                            
                                            IF v_final_status = 'DUPL' THEN
                                                v_obs_desc := 'Tiene similitud con una o varias preguntas: ' || v_codes_list;
                                                -- Si existen subpreguntas duplicadas entonces el texto tambien pasa a duplicado
                                                UPDATE parent_question SET status = v_final_status WHERE id = pf_parent_id;	
                                                -- Tambien actualizar la pregunta actual
                                                UPDATE question set status = v_final_status WHERE id = v_question_id;	
                                            ELSE
                                                UPDATE question set status = v_final_status WHERE id = v_question_id;
                                            END IF;
                                        END IF;
                                END IF;

                                IF p_question_attributes IS NOT NULL THEN
                                    p_question_attributes := COALESCE(p_question_attributes::jsonb, '[]'::jsonb);

                                    -- Insertar atributos que no existen
                                    INSERT INTO question_attributes (
                                        question_id,
                                        question_attributes_type_id,
                                        value,
                                        created_by,
                                        created_at
                                    )
                                    SELECT
                                        v_question_id,
                                        (attr->>'question_attribute_type_id')::INT,
                                        attr->>'value',
                                        pf_created_by,
                                        now()
                                    FROM jsonb_array_elements(p_question_attributes) AS attr
                                    WHERE NOT EXISTS (
                                        SELECT 1
                                        FROM question_attributes qa
                                        WHERE qa.question_id = v_question_id
                                        AND qa.question_attributes_type_id =
                                            (attr->>'question_attribute_type_id')::INT
                                        AND qa.deleted_at IS NULL
                                    );

                                    -- Actualizar si cambió el value
                                    UPDATE question_attributes qa
                                    SET
                                        value = attr->>'value',
                                        updated_by = pf_created_by,
                                        updated_at = now()
                                    FROM jsonb_array_elements(p_question_attributes) AS attr
                                    WHERE qa.question_id = v_question_id
                                    AND qa.question_attributes_type_id =
                                        (attr->>'question_attribute_type_id')::INT
                                    AND qa.deleted_at IS NULL
                                    AND qa.value IS DISTINCT FROM attr->>'value';

                                    -- Soft delete de atributos que ya no vienen
                                    UPDATE question_attributes qa
                                    SET
                                        deleted_by = pf_created_by,
                                        deleted_at = now()
                                    WHERE qa.question_id = v_question_id
                                    AND qa.deleted_at IS NULL
                                    AND qa.question_attributes_type_id NOT IN (
                                        SELECT (attr->>'question_attribute_type_id')::INT
                                        FROM jsonb_array_elements(p_question_attributes) AS attr
                                    );

                                END IF;

                                -- Insertar observación si p_observation no es NULL ni vacío
                                IF v_final_status = 'DUPL' THEN
                                    INSERT INTO question_observation
                                    (description, similitaries, question_id, type, fl_status, created_by, created_at)
                                    VALUES
                                    (v_obs_desc, v_similary_text, v_question_id, 'DUPL', true, pf_created_by, now());
                                END IF;
                                --

                                SELECT * INTO result FROM question WHERE id = v_question_id LIMIT 1;

                                IF (
                                    1 = 1
                                    AND result.topic_id IS NOT NULL
                                    AND EXISTS (SELECT 1 FROM jsonb_array_elements(pf_subtopic_ids))
                                    AND result.level_id IS NOT NULL
                                    AND result.answer_id IS NOT NULL
                                    AND result.status = 'PEND'
                                ) THEN
                                    UPDATE question
                                    SET status = CASE 
                                                    WHEN p_is_from_text IS TRUE THEN 'VERI'
                                                    ELSE 'DIGI'
                                                END
                                    WHERE id = v_question_id;
                                END IF;

                                SELECT * INTO result FROM question WHERE id = v_question_id LIMIT 1;

                                RETURN result;
                            END;
                            $$;


ALTER FUNCTION odiseo.fn_insert_verified_question_with_alternatives(pf_course_id integer, p_authorship character varying, p_origin jsonb, p_year integer, pf_parent_id integer, p_question_number character varying, p_diagrammed boolean, pf_topic_id smallint, pf_question_columns smallint, pf_subtopic_ids jsonb, p_type_material_template_id integer, p_week_id integer, pf_level_id integer, p_type_id character varying, p_ter numeric, p_question_text text, p_question_short text, p_question_images jsonb, p_alternatives jsonb, p_alternative_images jsonb, pf_config_alternative_id bigint, pf_created_by bigint, p_teacher_id integer, p_is_from_text boolean, p_question_attributes jsonb, p_priority smallint) OWNER TO postgres;

--
-- Name: fn_invalidate_token_user(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_invalidate_token_user(p_user_id bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
            BEGIN
                UPDATE odiseo.personal_access_tokens SET revoked = true, updated_at = now() WHERE tokenable_id = p_user_id AND revoked = false;
                RETURN p_user_id;
            END;
            $$;


ALTER FUNCTION odiseo.fn_invalidate_token_user(p_user_id bigint) OWNER TO postgres;

--
-- Name: fn_level(integer, integer, character varying, smallint, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_level(p_perpage integer, p_npage integer, p_search character varying, p_course_id smallint, f_status boolean) RETURNS TABLE(id bigint, name character varying, description character varying, courses json, fl_status boolean, created_by bigint, updated_by bigint, deleted_by bigint, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone, user_name character varying, user_email odiseo.email_citext, total bigint)
    LANGUAGE plpgsql
    AS $$
                        DECLARE
                            offset_val INTEGER;
                        BEGIN
                            offset_val := p_perpage * (p_npage - 1);

                            RETURN QUERY
                            WITH tbl_level AS (
                                SELECT
                                    l.id,
                                    l.name,
                                    l.description,
                                    CASE
                                        WHEN count(cl.id) > 0 THEN json_agg(json_build_object(
                                            'id', cl.id,
                                            'level_id', cl.level_id,
                                            'code', cl.code,
                                            'course_id', cl.course_id,
                                            'code_course', c.code,
                                            'name', c.name
                                        ))
                                        ELSE '[]'::json
                                    END AS courses,
                                    l.fl_status,
                                    l.created_by,
                                    l.updated_by,
                                    l.deleted_by,
                                    l.created_at,
                                    l.updated_at,
                                    l.deleted_at,
                                    u.user AS user_name,
                                    u.email AS user_email
                                FROM level l
                                LEFT JOIN users u ON l.created_by = u.id
                                LEFT JOIN course_level cl ON l.id = cl.level_id AND cl.fl_status = true
                                LEFT JOIN course c ON cl.course_id = c.id
                                WHERE l.fl_status = f_status
                                AND l.deleted_at IS NULL
                                AND (
                                    p_search IS NULL
                                    OR (LOWER(l.name) LIKE '%' || LOWER(p_search) || '%'
                                    OR LOWER(l.description) LIKE '%' || LOWER(p_search) || '%')
                                )
                                GROUP BY
                                    l.id,
                                    l.name,
                                    l.description,
                                    l.fl_status,
                                    l.created_by,
                                    l.updated_by,
                                    l.deleted_by,
                                    l.created_at,
                                    l.updated_at,
                                    l.deleted_at,
                                    u.user,
                                    u.email
                                HAVING (
                                    p_course_id IS NULL
                                    OR EXISTS (
                                        SELECT 1
                                        FROM course_level cl2
                                        WHERE cl2.level_id = l.id
                                        AND cl2.course_id = p_course_id
                                        AND cl2.fl_status = true
                                    )
                                )
                                ORDER BY l.id ASC
                            )

                            SELECT *, count(*) OVER () AS total
                            FROM tbl_level
                            LIMIT p_perpage
                            OFFSET offset_val;
                        END;
                        $$;


ALTER FUNCTION odiseo.fn_level(p_perpage integer, p_npage integer, p_search character varying, p_course_id smallint, f_status boolean) OWNER TO postgres;

--
-- Name: fn_level_all(character varying, smallint, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_level_all(p_search character varying, p_course_id smallint, f_status boolean) RETURNS TABLE(id bigint, name character varying, description character varying, courses json, fl_status boolean, created_by bigint, updated_by bigint, deleted_by bigint, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone, user_name character varying, user_email odiseo.email_citext)
    LANGUAGE plpgsql
    AS $$
                        BEGIN
                            RETURN QUERY
                            SELECT
                                l.id,
                                l.name,
                                l.description,
                                CASE
                                    WHEN count(cl.id) > 0 THEN json_agg(json_build_object(
                                        'id', cl.id,
                                        'level_id', cl.level_id,
                                        'code', cl.code,
                                        'course_id', cl.course_id,
                                        'code_course', c.code,
                                        'name', c.name
                                    ))
                                    ELSE '[]'::json
                                END AS courses,
                                l.fl_status,
                                l.created_by,
                                l.updated_by,
                                l.deleted_by,
                                l.created_at,
                                l.updated_at,
                                l.deleted_at,
                                u.user AS user_name,
                                u.email AS user_email
                            FROM level l
                            LEFT JOIN users u ON l.created_by = u.id
                            LEFT JOIN course_level cl ON l.id = cl.level_id AND cl.fl_status = true
                            LEFT JOIN course c ON cl.course_id = c.id
                            WHERE l.fl_status = f_status
                            AND l.deleted_at IS NULL
                            AND (
                                p_search IS NULL
                                OR (LOWER(l.name) LIKE '%' || LOWER(p_search) || '%'
                                OR LOWER(l.description) LIKE '%' || LOWER(p_search) || '%')
                            )
                            GROUP BY
                                l.id,
                                l.name,
                                l.description,
                                l.fl_status,
                                l.created_by,
                                l.updated_by,
                                l.deleted_by,
                                l.created_at,
                                l.updated_at,
                                l.deleted_at,
                                u.user,
                                u.email
                            HAVING (
                                p_course_id IS NULL
                                OR EXISTS (
                                    SELECT 1
                                    FROM course_level cl2
                                    WHERE cl2.level_id = l.id
                                    AND cl2.course_id = p_course_id
                                    AND cl2.fl_status = true
                                )
                            )
                            ORDER BY l.id ASC;
                        END;
                        $$;


ALTER FUNCTION odiseo.fn_level_all(p_search character varying, p_course_id smallint, f_status boolean) OWNER TO postgres;

--
-- Name: fn_list_courses_and_pseudo_courses_by_universities(jsonb, integer, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_list_courses_and_pseudo_courses_by_universities(f_university_ids jsonb, p_company_id integer, f_courses_employee jsonb) RETURNS TABLE(id smallint, code character varying, name character varying, exist_some boolean, fl_pseudo boolean, children jsonb)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_university_ids INT[];
        BEGIN
            /*
                ------------------------------------------------------------------------------------
                -- HISTORIAL DE CAMBIOS
                ------------------------------------------------------------------------------------

                Versión: 1.1
                Fecha: 2025-11-17
                Autor: Junior Alcarraz
                Descripción:
                    Se filtra por el id de la compañia del usuario logueado
            */

            v_university_ids := ARRAY(SELECT jsonb_array_elements_text(f_university_ids)::INT);

            RETURN QUERY
            WITH tbl_courses AS (
                SELECT
                    c.id,
                    c.code,
                    c.name,
                    CASE
                        WHEN st.id IS NULL
                            THEN FALSE
                        ELSE TRUE
                    END AS exist_some,
                    c.fl_pseudo_course AS fl_pseudo,
                    COALESCE(
                        to_jsonb(
                            ARRAY(
                                SELECT cpc.course_id FROM course_pseudo_courses cpc
                                WHERE cpc.pseudo_course_id = c.id AND cpc.fl_status = TRUE
                            )
                        ), '[]'::jsonb
                    ) AS children
                FROM course c
                LEFT JOIN syllabus_template st ON c.id = st.course_id
                    AND st.university_id = ANY(v_university_ids)
                    AND st.fl_status = TRUE
                    AND st.company_id = p_company_id
                WHERE c.fl_status = TRUE
                    AND (f_courses_employee IS NULL OR c.id = ANY(ARRAY(SELECT jsonb_array_elements_text(f_courses_employee)::INT)))
            )
            SELECT tbl_courses.* FROM tbl_courses
            ORDER BY tbl_courses.code;
        END;
        $$;


ALTER FUNCTION odiseo.fn_list_courses_and_pseudo_courses_by_universities(f_university_ids jsonb, p_company_id integer, f_courses_employee jsonb) OWNER TO postgres;

--
-- Name: fn_list_courses_user(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_list_courses_user(p_user_id bigint) RETURNS TABLE(id smallint, name character varying)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                WITH validate_admin_user AS (
                    SELECT
                        u.id,
                        r.fl_administrator,
                        rp.permission_id
                    FROM users u
                    JOIN users_roles ur ON u.id = ur.user_id
                    JOIN roles r ON ur.rol_id = r.id
                    LEFT JOIN roles_permissions rp ON r.id = rp.rol_id
                        AND rp.permission_id = 133 -- 'admin.admin'
                    WHERE u.id = p_user_id
                ), get_courses_employees AS (
                    SELECT DISTINCT
                        ec.course_id
                    FROM employees e
                    JOIN employee_course ec ON e.id = ec.teacher_id
                    WHERE e.user_id = p_user_id
                        AND ec.fl_status = true
                        AND NOT EXISTS (
                            SELECT 1
                            FROM validate_admin_user vau
                            WHERE vau.permission_id = 133
                        )

                    UNION ALL

                    SELECT
                        c.id AS course_id
                    FROM course c
                    WHERE c.fl_status = true
                    AND EXISTS (
                            SELECT 1
                            FROM validate_admin_user vau
                            WHERE vau.permission_id = 133
                        )
                )
                SELECT
                    gce.course_id::SMALLINT AS id,
                    c.name
                FROM get_courses_employees gce
                JOIN course c ON gce.course_id = c.id
                ORDER BY c.id;
            END;
            $$;


ALTER FUNCTION odiseo.fn_list_courses_user(p_user_id bigint) OWNER TO postgres;

--
-- Name: fn_list_cycles(character varying, character varying, character varying, boolean, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_list_cycles(p_search character varying, p_code character varying, p_description character varying, p_status boolean, p_company_id integer) RETURNS TABLE(id bigint, description character varying, weeks smallint)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        c.id,
        c.description,
        c.weeks
    FROM cycle c
    WHERE c.fl_status = p_status
        AND (p_code IS NULL OR c.code ILIKE '%' || p_code || '%')
        AND (p_description IS NULL OR c.description ILIKE '%' || p_description || '%')
        AND (p_search IS NULL OR (c.code ILIKE '%' || p_search || '%' OR c.description ILIKE '%' || p_search || '%'))
        AND c.company_id = p_company_id
    ORDER BY c.id ASC;
END;
$$;


ALTER FUNCTION odiseo.fn_list_cycles(p_search character varying, p_code character varying, p_description character varying, p_status boolean, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_list_digitalized_question(integer, integer, character varying, integer, integer, integer, character varying, character varying, smallint, smallint, smallint, smallint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_list_digitalized_question(p_perpage integer, p_npage integer, p_name_text character varying, p_employee_didi_id integer, p_teacher_id integer, p_course_id integer, p_status character varying, p_type character varying, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_version smallint, p_year character varying) RETURNS TABLE(id bigint, key_question text, type_question text, code character varying, parent_id bigint, short_description text, subquestions jsonb, course_id smallint, course character varying, status character varying, teacher_id bigint, teacher text, didi_id bigint, didi text, date_status timestamp without time zone, observation text, origin_question jsonb, type_text_template_id smallint, type_text_template_name character varying, description_text character varying, description_subquestion character varying, text_attributes character varying, subquestion_attributes character varying, priority integer, is_missing_question boolean, subtopic_id integer, total_count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    offset_val integer;
BEGIN
    -- Calculate the offset
    offset_val := p_perpage * (p_npage - 1);
    RETURN QUERY
    -- Obtiene toda las preguntas de tipo P Y T
    WITH all_digitalized_questions AS (
        SELECT
            dq.id,
            dq.code,
            dq.status,
            dq.short_description,
            dq.parent_id,
            dq.course_id,
            c.name AS course,
            qn.question_origin,
            qn.university_id,
            qn.option_id,
            qn.modality_id,
            qn."version",
            qn."year",
            dq.priority,
            CASE WHEN mmqd.question_id IS NOT NULL THEN
                TRUE
            ELSE
                FALSE
            END AS is_missing_question
        FROM
            question dq
        LEFT JOIN v_all_question_origins qn ON qn.question_id = dq.id
        LEFT JOIN course c ON dq.course_id = c.id
        LEFT JOIN material_missing_question_detail mmqd ON mmqd.question_id = dq.id
    WHERE
        1 = 1
        AND dq.fl_status = TRUE
        AND dq.deleted_at IS NULL
        AND (p_type IS NULL
            OR p_type = 'P')
        AND (p_course_id IS NULL
            OR dq.course_id = p_course_id)
        AND (((p_status IS NULL
                    OR p_status = '')
                AND dq.status IN ('DIGI', 'OBSE'))
            OR (p_status IS NOT NULL
                AND p_status <> ''
                AND dq.status = p_status))
        AND (p_name_text IS NULL
            OR LOWER(dq.code)
            LIKE '%' || LOWER(p_name_text) || '%'
            OR unaccent(LOWER(dq.short_description))
            LIKE '%' || LOWER(p_name_text) || '%')
        AND (p_university_id IS NULL
            OR qn.university_id = p_university_id)
        AND (p_option_id IS NULL
            OR qn.option_id = p_option_id)
        AND (p_modality_id IS NULL
            OR qn.modality_id = p_modality_id)
        AND (p_version IS NULL
            OR qn."version" = p_version)
        AND (p_year IS NULL
            OR qn."year" = p_year)
),
tbl_questions AS (
    SELECT
        -- preguntas digitalizadas de tipo P
        q.id AS id,
        'p_' || q.id AS key_question,
        'P' AS type_question,
        q.code AS code,
        q.parent_id AS parent_id,
        q.short_description AS short_description,
        NULL AS subquestions,
        q.course_id,
        q.course,
        q.status AS status,
        e1.id AS teacher_id,
        CONCAT(e1.first_surname, ' ', e1.second_surname, ' ', e1.first_name) AS teacher,
        e2.id AS didi_id,
        CONCAT(e2.first_surname, ' ', e2.second_surname, ' ', e2.first_name) AS didi,
        qs.created_at AS date_status,
        qo.description AS observation,
        q.question_origin AS origin_question,
        NULL AS type_text_template_id,
        NULL AS type_text_template_name,
        NULL AS description_text,
        NULL AS description_subquestion,
        NULL AS text_attributes,
        NULL AS subquestion_attributes,
        q.priority,
        q.is_missing_question,
        qspt.subtopic_id
    FROM
        all_digitalized_questions q
        LEFT JOIN employee_question eq ON eq.question_id = q.id
        LEFT JOIN question_status qs ON q.id = qs.question_id
            AND q.status = qs.status
            AND qs.fl_active = TRUE
        LEFT JOIN employees e1 ON eq.teacher_id = e1.id
        LEFT JOIN employee_didi_question edq ON edq.question_id = q.id
            AND edq.fl_status = TRUE
        LEFT JOIN employees e2 ON edq.employee_id = e2.id
        LEFT JOIN question_observation qo ON qo.question_id = q.id
            AND qo.fl_status = TRUE
            AND qo."type" IN ('DIGI', 'OBSE')
        LEFT JOIN question_subtopic qspt ON qspt.question_id = q.id AND qspt.fl_status = TRUE
    WHERE
        1 = 1
        AND q.parent_id IS NULL
        AND eq.fl_status = TRUE
        AND (p_teacher_id IS NULL
            OR e1.id = p_teacher_id)
        AND (p_employee_didi_id IS NULL
            OR e2.id = p_employee_didi_id)
    UNION ALL
    SELECT
        -- Preguntas digitalizadas de tipo T
        pq.id AS id,
        't_' || pq.id AS key_question,
        'T' AS type_question,
        pq.code AS code,
        pq.id AS parent_id,
        pq.short_description AS short_description,
        JSONB_AGG(
            JSONB_BUILD_OBJECT(
                'id', dq.id, 
                'key_question', 's_' || dq.id, 
                'type_question', 'S', 
                'code', dq.code, 
                'subtopic_id', qs2.subtopic_id,
                'parent_id', dq.parent_id, 
                'short_description', dq.short_description, 
                'course_id', c.id, 
                'course', c.name, 
                'status', dq.status, 
                'teacher_id', es1.id, 
                'teacher', CONCAT(es1.first_surname, ' ', es1.second_surname, ' ', es1.first_name), 
                'didi_id', es2.id, 
                'didi', CONCAT(es2.first_surname, ' ', es2.second_surname, ' ', es2.first_name), 
                'date_status', qs1.created_at, 
                'observation', qo.description, 
                'origin_question', qn.question_origin
            )) AS subquestions,
        pq.course_id,
        c.name AS course,
        pq.status AS status,
        0::bigint AS teacher_id,
        '' AS teacher,
        0::bigint AS didi_id,
        '' AS didi,
        pq.created_at AS date_status,
        '' AS observation,
        opq.question_origin,
        c.type_text_template_id,
        ttt.name AS type_text_template_name,
        ttt.description_text,
        ttt.description_subquestion,
        ttt.text_attributes,
        ttt.subquestion_attributes,
        pq.priority,
        FALSE AS is_missing_question,
        NULL::integer AS subtopic_id
    FROM
        parent_question pq
        INNER JOIN question dq ON pq.status IN ('DIGI', 'OBSE')
            AND dq.parent_id = pq.id
        LEFT JOIN v_all_question_origins qn ON qn.question_id = dq.id
        LEFT JOIN odiseo.v_all_parent_origins opq ON opq.parent_id = pq.id
        INNER JOIN course c ON pq.course_id = c.id
        LEFT JOIN type_text_templates ttt ON ttt.id = c.type_text_template_id
        LEFT JOIN question_status qs1 ON dq.id = qs1.question_id
            AND dq.status = qs1.status
            AND qs1.fl_active = TRUE
        INNER JOIN question_subtopic qs2 ON dq.id = qs2.question_id
            AND qs2.fl_status = TRUE AND  qs2.fl_status = TRUE
        LEFT JOIN employee_question eoq ON eoq.question_id = dq.id
            AND eoq.fl_status = TRUE
        LEFT JOIN employees es1 ON eoq.teacher_id = es1.id
        LEFT JOIN employee_didi_question edq ON edq.question_id = dq.id
            AND edq.fl_status = TRUE
        LEFT JOIN employees es2 ON edq.employee_id = es2.id
        LEFT JOIN question_observation qo ON qo.question_id = dq.id
            AND qo.fl_status = TRUE
            AND qo."type" IN ('DIGI', 'OBSE')
    WHERE
        1 = 1
        AND (p_status IS NULL
            OR p_status = ''
            OR pq.status = p_status)
        AND (p_course_id IS NULL
            OR pq.course_id = p_course_id)
        AND (p_teacher_id IS NULL
            OR es1.id = p_teacher_id)
        AND (p_employee_didi_id IS NULL
            OR es2.id = p_employee_didi_id)
        AND (p_university_id IS NULL
            OR opq.university_id = p_university_id
            OR qn.university_id = p_university_id)
        AND (p_option_id IS NULL
            OR opq.option_id = p_option_id
            OR qn.option_id = p_option_id)
        AND (p_modality_id IS NULL
            OR opq.modality_id = p_modality_id
            OR qn.modality_id = p_modality_id)
        AND (p_version IS NULL
            OR opq."version" = p_version
            OR qn."version" = p_version)
        AND (p_year IS NULL
            OR opq."year" = p_year
            OR qn."year" = p_year)
    GROUP BY
        pq.id,
        c.id,
        opq.question_origin,
        ttt.id
    HAVING
        1 = 1
        AND (p_name_text IS NULL
            OR p_name_text = ''
            OR LOWER(pq.number_question)
            ILIKE '%' || LOWER(p_name_text) || '%'
            OR LOWER(pq.code)
            ILIKE '%' || LOWER(p_name_text) || '%'
            OR BOOL_OR(LOWER(dq.number_question)
                ILIKE '%' || LOWER(p_name_text) || '%')
            OR BOOL_OR(LOWER(dq.code)
                ILIKE '%' || LOWER(p_name_text) || '%'))
),
counted_questions AS (
    SELECT
        *,
        COUNT(*) OVER () AS total_count
    FROM
        tbl_questions fq
)
SELECT
    *
FROM
    counted_questions AS cq
ORDER BY
    cq.priority DESC NULLS LAST,
    CASE
        WHEN cq.status = 'OBSE' THEN 0
        ELSE 1
    END,
    cq.date_status ASC
LIMIT p_perpage OFFSET offset_val;
END;
$$;


ALTER FUNCTION odiseo.fn_list_digitalized_question(p_perpage integer, p_npage integer, p_name_text character varying, p_employee_didi_id integer, p_teacher_id integer, p_course_id integer, p_status character varying, p_type character varying, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_version smallint, p_year character varying) OWNER TO postgres;

--
-- Name: fn_list_eligible_teachers_for_missing_questions(); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_list_eligible_teachers_for_missing_questions() RETURNS TABLE(employee_id integer, limit_missing_questions integer, teacher_name text, courses json)
    LANGUAGE plpgsql STABLE
    AS $$
            BEGIN
                RETURN QUERY
                WITH active_eligible_teachers AS (
                    SELECT 
                        t.employee_id,
                        t.limit_missing_questions,
                        TRIM(CONCAT_WS(' ', e.first_name, e.first_surname, e.second_surname)) AS teacher_name,
                        e.first_name,
                        e.first_surname,
                        e.second_surname
                    FROM teachers t
                    JOIN employees e ON e.id = t.employee_id
                    JOIN users u ON u.id = e.user_id
                    WHERE t.fl_active = true
                      AND e.fl_status = true
                      AND t.fl_resolve_missing_questions = true
                      AND u.fl_status = true
                      AND u.fl_suspended = false
                      AND u.deleted_at IS NULL
                ),
                eligible_courses AS (
                    SELECT 
                        ec.teacher_id, 
                        ec.course_id
                    FROM employee_course ec
                    JOIN active_eligible_teachers aet ON aet.employee_id = ec.teacher_id
                    WHERE ec.fl_status = true 
                      AND ec.deleted_at IS NULL
                      AND NOT EXISTS (
                          SELECT 1
                          FROM material_missing_question_detail mmqd
                          JOIN material_ballot_question mdbq 
                            ON mdbq.id = mmqd.material_ballot_question_id
                          WHERE mmqd.employee_id = ec.teacher_id
                            AND mmqd.question_id IS NULL
                            AND mmqd.deleted_at IS NULL
                            AND mdbq.course_id = ec.course_id
                      )
                ),
                teacher_courses AS (
                    SELECT 
                        ec.teacher_id, 
                        json_agg(ec.course_id) AS courses_array
                    FROM eligible_courses ec
                    GROUP BY ec.teacher_id
                ),
                tracking_summary AS (
                    SELECT 
                        trk.employee_id, 
                        MAX(trk.created_at) AS last_assigned_at
                    FROM material_missing_question_tracking trk
                    WHERE trk.action = 'assigned'
                    GROUP BY trk.employee_id
                )
                SELECT
                    aet.employee_id::integer,
                    aet.limit_missing_questions::integer,
                    aet.teacher_name::text,
                    tc.courses_array::json AS courses
                FROM active_eligible_teachers aet
                JOIN teacher_courses tc ON tc.teacher_id = aet.employee_id
                LEFT JOIN tracking_summary ts ON ts.employee_id = aet.employee_id
                ORDER BY ts.last_assigned_at ASC NULLS FIRST,
                         aet.first_name ASC,
                         aet.first_surname ASC,
                         aet.second_surname ASC;
            END;
            $$;


ALTER FUNCTION odiseo.fn_list_eligible_teachers_for_missing_questions() OWNER TO postgres;

--
-- Name: fn_list_essential_knowledge(integer, integer, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_list_essential_knowledge(p_perpage integer, p_npage integer, p_course_id bigint, p_topic_id bigint) RETURNS TABLE(id bigint, code character varying, name character varying, course_id bigint, topic_id bigint, image text, total bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    offset_val integer := p_perpage * (p_npage - 1);
BEGIN
    -- Listar los conocimientos esenciales asociados a un curso y tema específicos
    RETURN QUERY
    WITH essential_knowledges AS (
        SELECT
            ek.id,
            ek.code,
            ek.name,
            ek.course_id,
            ek.topic_id,
            eki.image
        FROM essential_knowledges ek
        INNER JOIN essential_knowledge_image eki ON ek.id = eki.essential_knowledge_id
        WHERE 1 = 1
          AND ek.course_id = p_course_id
          AND ( p_topic_id IS NULL OR ek.topic_id = p_topic_id )
          AND ek.is_active is true
          AND ek.deleted_at IS NULL
          AND eki.deleted_at IS NULL
    ), counted_essential_knowledges AS (
        SELECT
            *,
            count(*) OVER () AS total
        FROM essential_knowledges
    )
    SELECT
        *
    FROM
        counted_essential_knowledges cek
    ORDER BY
        split_part(cek.code, '-', 1) ASC,
        split_part(cek.code, '-', 2) ASC,
        split_part(cek.code, '-', 3) ASC
    LIMIT p_perpage OFFSET offset_val;

END;
$$;


ALTER FUNCTION odiseo.fn_list_essential_knowledge(p_perpage integer, p_npage integer, p_course_id bigint, p_topic_id bigint) OWNER TO postgres;

--
-- Name: fn_list_index_question(integer, integer, character varying, integer, integer, integer, boolean, character varying, character varying, smallint, smallint, smallint, smallint, character varying, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_list_index_question(p_perpage integer, p_npage integer, p_name_text character varying, p_teacher_id integer, p_course_id integer, p_didi_id integer, p_fl_diagrammed boolean, p_type character varying, p_status character varying, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_version smallint, p_year character varying, p_is_secondary boolean) RETURNS TABLE(id bigint, key_question text, type_question text, code character varying, parent_id bigint, short_description text, subquestions jsonb, course_id smallint, course character varying, status character varying, teacher_id bigint, teacher text, didi_id bigint, didi text, type_text_id bigint, date_status timestamp without time zone, origin_question jsonb, is_secondary boolean, priority integer, is_missing_question boolean, total_count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    offset_val integer;
BEGIN
    offset_val := p_perpage * (p_npage - 1);
    RETURN QUERY
    -- Obtiene toda las preguntas de tipo P Y T
    WITH all_index_questions AS (
        SELECT
            vq.id,
            vq.code,
            vq.status,
            vq.short_description,
            vq.parent_id,
            vq.course_id,
            c.name AS course,
            qn.question_origin,
            qn.university_id,
            qn.option_id,
            qn.modality_id,
            qn."version",
            qn."year",
            vq.priority,
            CASE WHEN mmqd.question_id IS NOT NULL THEN
                TRUE
            ELSE
                FALSE
            END AS is_missing_question
        FROM
            question vq
        LEFT JOIN course c ON vq.course_id = c.id
        LEFT JOIN v_all_question_origins qn ON qn.question_id = vq.id
        LEFT JOIN material_missing_question_detail mmqd ON mmqd.question_id = vq.id
    WHERE
        1 = 1
        AND vq.fl_status = TRUE
        AND vq.parent_id IS NULL
        AND vq.deleted_at IS NULL
        AND CASE WHEN p_status IS NULL THEN
            vq.status IN ('RECH', 'DASI')
        ELSE
            vq.status = p_status
        END
        AND ((p_type IS NULL)
            OR (p_type = 'T'
                AND vq.parent_id IS NOT NULL)
            OR (p_type = 'P'
                AND vq.parent_id IS NULL))
        AND (p_course_id IS NULL
            OR vq.course_id = p_course_id)
        AND (p_fl_diagrammed IS NULL
            OR vq.fl_diagrammed = p_fl_diagrammed)
        AND (p_university_id IS NULL
            OR qn.university_id = p_university_id)
        AND (p_option_id IS NULL
            OR qn.option_id = p_option_id)
        AND (p_modality_id IS NULL
            OR qn.modality_id = p_modality_id)
        AND (p_version IS NULL
            OR qn."version" = p_version)
        AND (p_year IS NULL
            OR qn."year" = p_year)
),
tbl_primary AS (
    SELECT
        -- index P questions
        q.id AS id,
        'p_' || q.id AS key_question,
        'P' type_question,
        q.code AS code,
        q.parent_id AS parent_id,
        q.short_description short_description,
        '[]'::jsonb AS subquestions,
        q.course_id,
        q.course,
        q.status AS status,
        e1.id AS teacher_id,
        CONCAT(e1.first_surname, ' ', e1.second_surname, ' ', e1.first_name) AS teacher,
        e2.id AS didi_id,
        CONCAT(e2.first_surname, ' ', e2.second_surname, ' ', e2.first_name) AS didi,
        NULL::bigint AS type_text_id,
        qs.created_at AS date_status,
        q.question_origin,
        FALSE AS is_secondary,
        q.priority,
        q.is_missing_question
    FROM
        all_index_questions q
        LEFT JOIN employee_question eq ON eq.question_id = q.id
        LEFT JOIN question_status qs ON q.id = qs.question_id
            AND q.status = qs.status
            AND qs.fl_active = TRUE
        LEFT JOIN employees e1 ON eq.teacher_id = e1.id
        LEFT JOIN employee_didi_question edq ON edq.question_id = q.id
            AND edq.fl_status = TRUE
        LEFT JOIN employees e2 ON edq.employee_id = e2.id
    WHERE
        1 = 1
        AND (p_is_secondary IS NULL
            OR p_is_secondary IS FALSE)
        AND (p_type IS NULL
            OR p_type = 'P')
        AND q.parent_id IS NULL
        AND eq.fl_status = TRUE
        AND (p_teacher_id IS NULL
            OR e1.id = p_teacher_id)
        AND (p_didi_id IS NULL
            OR e2.id = p_didi_id)
        AND (p_name_text IS NULL
            OR LOWER(q.code)
            LIKE '%' || LOWER(p_name_text) || '%'
            OR unaccent(LOWER(q.short_description))
            LIKE '%' || LOWER(p_name_text) || '%')
    UNION ALL
    SELECT
        -- Index T questions
        pq.id AS id,
        't_' || pq.id AS key_question,
        'T' type_question,
        pq.code AS code,
        pq.id AS parent_id,
        pq.short_description short_description,
        JSONB_AGG(JSONB_BUILD_OBJECT('id', oq.id, 'key_question', 's_' || oq.id, 'type_question', 'S', 'code', oq.code, 'parent_id', oq.parent_id, 'short_description', oq.short_description, 'course_id', c.id, 'course', c.name, 'status', oq.status, 'teacher_id', es1.id, 'teacher', CONCAT(es1.first_surname, ' ', es1.second_surname, ' ', es1.first_name), 'didi_id', es2.id, 'didi', CONCAT(es2.first_surname, ' ', es2.second_surname, ' ', es2.first_name), 'date_status', qs1.created_at, 'origin_question', qn.question_origin)) AS subquestions,
        pq.course_id,
        c.name AS course,
        pq.status AS status,
        0::bigint AS teacher_id,
        '' AS teacher,
        0::bigint AS didi_id,
        '' AS didi,
        pq.type_text_id,
        pq.created_at AS date_status,
        opq.question_origin,
        FALSE AS is_secondary,
        pq.priority,
        FALSE AS is_missing_question
    FROM
        parent_question pq
        INNER JOIN question oq ON pq.status IN ('RECH', 'DASI')
            AND oq.parent_id = pq.id
        LEFT JOIN v_all_question_origins qn ON qn.question_id = oq.id
        LEFT JOIN v_all_parent_origins opq ON opq.parent_id = pq.id
        LEFT JOIN question_status qs1 ON oq.id = qs1.question_id
            AND oq.status = qs1.status
            AND qs1.fl_active IS TRUE
        LEFT JOIN employee_question eoq ON eoq.question_id = oq.id
            AND eoq.fl_status IS TRUE
        LEFT JOIN employees es1 ON eoq.teacher_id = es1.id
        LEFT JOIN employee_didi_question edq ON edq.question_id = oq.id
            AND edq.fl_status = TRUE
        LEFT JOIN employees es2 ON edq.employee_id = es2.id
        INNER JOIN course c ON pq.course_id = c.id
    WHERE
        1 = 1
        AND (p_is_secondary IS NULL
            OR p_is_secondary IS FALSE)
        AND (p_teacher_id IS NULL
            OR es1.id = p_teacher_id)
        AND (p_didi_id IS NULL
            OR edq.employee_id = p_didi_id)
        AND (p_type IS NULL
            OR p_type = 'T')
        AND oq.fl_status IS TRUE
        AND (p_course_id IS NULL
            OR c.id = p_course_id)
        AND (p_fl_diagrammed IS NULL
            OR oq.fl_diagrammed = p_fl_diagrammed)
        AND (p_university_id IS NULL
            OR qn.university_id = p_university_id)
        AND (p_option_id IS NULL
            OR qn.option_id = p_option_id)
        AND (p_modality_id IS NULL
            OR qn.modality_id = p_modality_id)
        AND (p_version IS NULL
            OR qn."version" = p_version)
        AND (p_year IS NULL
            OR qn."year" = p_year)
    GROUP BY
        pq.id,
        c.id,
        opq.question_origin
    HAVING
        COUNT(oq.*) > 0
        AND (p_name_text IS NULL
            OR LOWER(pq.code)
            LIKE '%' || LOWER(p_name_text) || '%'
            OR unaccent(LOWER(pq.short_description))
            LIKE '%' || LOWER(p_name_text) || '%'
            OR BOOL_OR(LOWER(oq.code)
                LIKE '%' || LOWER(p_name_text) || '%'
                OR LOWER(oq.code)
                LIKE '%' || LOWER(p_name_text) || '%'
                OR unaccent(LOWER(oq.short_description))
                LIKE '%' || LOWER(p_name_text) || '%'))
),
tbl_secondary AS (
    SELECT
        q.id AS id,
        'sec_' || sec.id AS key_question,
        'P' type_question,
        sec.code AS code,
        q.parent_id AS parent_id,
        q.short_description short_description,
        '[]'::jsonb AS subquestions,
        sec.course_id::smallint,
        c.name AS course,
        q.status AS status,
        e1.id AS teacher_id,
        CONCAT(e1.first_surname, ' ', e1.second_surname, ' ', e1.first_name) AS teacher,
        e2.id AS didi_id,
        CONCAT(e2.first_surname, ' ', e2.second_surname, ' ', e2.first_name) AS didi,
        NULL::bigint AS type_text_id,
        qs.created_at AS date_status,
        qn.question_origin,
        TRUE AS is_secondary,
        q.priority,
        FALSE AS is_missing_question
    FROM
        question_secondary sec
        JOIN question q ON sec.question_id = q.id
        LEFT JOIN course c ON sec.course_id = c.id
        LEFT JOIN v_all_question_origins qn ON qn.question_id = q.id
        LEFT JOIN employee_question eq ON eq.question_id = q.id
        LEFT JOIN employees e1 ON eq.teacher_id = e1.id
        LEFT JOIN employee_didi_question edq ON edq.question_id = q.id
            AND edq.fl_status = TRUE
        LEFT JOIN employees e2 ON edq.employee_id = e2.id
        LEFT JOIN question_status qs ON q.id = qs.question_id
            AND q.status = qs.status
            AND qs.fl_active = TRUE
    WHERE
        1 = 1
        AND (p_is_secondary IS NULL
            OR p_is_secondary IS TRUE)
        AND q.fl_status = TRUE
        AND q.parent_id IS NULL
        AND q.deleted_at IS NULL
        AND CASE WHEN p_status IS NULL THEN
            q.status IN ('RECH', 'DASI')
        ELSE
            q.status = p_status
        END
        AND (p_type IS NULL
            OR p_type = 'P')
        AND (p_course_id IS NULL
            OR sec.course_id = p_course_id)
        AND (p_fl_diagrammed IS NULL
            OR q.fl_diagrammed = p_fl_diagrammed)
        AND (p_university_id IS NULL
            OR qn.university_id = p_university_id)
        AND (p_option_id IS NULL
            OR qn.option_id = p_option_id)
        AND (p_modality_id IS NULL
            OR qn.modality_id = p_modality_id)
        AND (p_version IS NULL
            OR qn."version" = p_version)
        AND (p_year IS NULL
            OR qn."year" = p_year)
        AND eq.fl_status = TRUE
        AND (p_teacher_id IS NULL
            OR e1.id = p_teacher_id)
        AND (p_didi_id IS NULL
            OR e2.id = p_didi_id)
        AND (p_name_text IS NULL
            OR LOWER(sec.code)
            LIKE '%' || LOWER(p_name_text) || '%'
            OR unaccent(LOWER(q.short_description))
            LIKE '%' || LOWER(p_name_text) || '%')
),
combined_questions AS (
    SELECT
        *
    FROM
        tbl_primary
    UNION ALL
    SELECT
        *
    FROM
        tbl_secondary
),
counted_questions AS (
    SELECT
        fq.*,
        count(*) OVER () AS total_count
FROM
    combined_questions fq
)
SELECT DISTINCT
    cq.*
FROM
    counted_questions cq
ORDER BY
    cq.priority DESC,
    cq.date_status ASC,
    cq.id ASC
LIMIT p_perpage OFFSET offset_val;
END;
$$;


ALTER FUNCTION odiseo.fn_list_index_question(p_perpage integer, p_npage integer, p_name_text character varying, p_teacher_id integer, p_course_id integer, p_didi_id integer, p_fl_diagrammed boolean, p_type character varying, p_status character varying, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_version smallint, p_year character varying, p_is_secondary boolean) OWNER TO postgres;

--
-- Name: fn_list_index_question_by_teacher(integer, integer, character varying, integer[], integer, boolean, character varying, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_list_index_question_by_teacher(p_perpage integer, p_npage integer, p_name_text character varying, f_course_ids integer[], f_teacher_id integer, f_fl_diagrammed boolean, f_type character varying, f_status character varying) RETURNS TABLE(id bigint, key_question text, parent_id bigint, subquestions jsonb, type_question text, code character varying, short_description text, course_id smallint, course character varying, teacher_id bigint, teacher text, status character varying, date_status timestamp without time zone, observation text, total_refuzed bigint, pdf_status text, priority integer, is_missing_question boolean, total_count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    offset_val integer;
BEGIN
    -- Calculate the offset
    offset_val := p_perpage * (p_npage - 1);
    RETURN QUERY WITH all_indexed_questions AS (
        SELECT
            iq.id,
            iq.code,
            iq.short_description,
            iq.parent_id,
            iq.course_id,
            iq.status,
            c.name AS course,
            iq.priority,
            CASE WHEN mmqd.question_id IS NOT NULL THEN
                TRUE
            ELSE
                FALSE
            END AS is_missing_question
        FROM
            question iq
        LEFT JOIN course c ON iq.course_id = c.id
        LEFT JOIN material_missing_question_detail mmqd ON mmqd.question_id = iq.id
    WHERE
        1 = 1
        AND iq.fl_status IS TRUE
        AND iq.deleted_at IS NULL
        AND ((f_status IS NULL
                AND iq.status IN ('DASI', 'INDE'))
            OR (iq.status = f_status))
        AND (f_fl_diagrammed IS NULL
            OR iq.fl_diagrammed = f_fl_diagrammed)
        AND (f_type IS NULL
            OR (f_type = 'T'
                AND iq.parent_id IS NOT NULL)
            OR (f_type = 'P'
                AND iq.parent_id IS NULL))
        AND (f_course_ids IS NULL
            OR iq.course_id = ANY (f_course_ids)) -- Cambio: Filtrado por array de course_ids
),
tbl_question AS (
    SELECT
        -- Indexed P questions
        q.id AS id,
        'p_' || q.id AS key_question,
        q.parent_id AS parent_id,
        NULL AS subquestions,
        'P' AS type_question,
        q.code AS code,
        q.short_description AS short_description,
        q.course_id,
        q.course,
        eq.teacher_id,
        CONCAT(e.first_surname, ' ', e.second_surname, ' ', e.first_name) AS teacher,
        q.status AS status,
        qs.created_at AS date_status,
        '' AS observation,
        (
            SELECT
                COUNT(*)
            FROM
                question_refuzed qr2
            WHERE
                qr2.question_id = q.id) AS total_refuzed,
        CASE WHEN eq.url_pdf_question_solution IS NULL THEN
            'pending'
        ELSE
            'completed'
        END AS pdf_status,
        q.priority,
        q.is_missing_question
    FROM
        all_indexed_questions q
        LEFT JOIN employee_question eq ON eq.question_id = q.id
        LEFT JOIN question_status qs ON q.id = qs.question_id
            AND q.status = qs.status
            AND qs.fl_active = TRUE
        LEFT JOIN employees e ON eq.teacher_id = e.id
    WHERE
        1 = 1
        AND (f_type IS NULL
            OR f_type = 'P')
        AND q.parent_id IS NULL
        AND eq.fl_status = TRUE
        AND (f_teacher_id IS NULL
            OR eq.teacher_id = f_teacher_id)
        AND (p_name_text IS NULL
            OR LOWER(q.code)
            LIKE '%' || LOWER(p_name_text) || '%'
            OR unaccent(LOWER(q.short_description))
            LIKE '%' || LOWER(p_name_text) || '%')
    UNION ALL
    SELECT
        -- Indexed T questions
        pq.id AS id,
        't_' || pq.id AS key_question,
        pq.id AS parent_id,
        JSONB_AGG(JSONB_BUILD_OBJECT('id', q.id, 'key_question', 's_' || q.id, 'code', q.code, 'course', c.name, 'status', q.status, 'teacher_id', es.id, 'teacher', CONCAT(initcap(split_part(es.first_name, ' ', 1)), ' ', upper(
                    LEFT (es.first_surname, 1)), '.', ' ', initcap(es.second_surname)), 'date_status', qs1.created_at, 'type_question', 'S', 'parent_id', q.parent_id, 'short_description', q.short_description, 'total_refuzed', (
                SELECT
                    COUNT(*)
                FROM question_refuzed qr
                WHERE
                    qr.question_id = q.id))) AS subquestions,
        'T' AS type_question,
        pq.code AS code,
        pq.short_description AS short_description,
        pq.course_id,
        c.name AS course,
        - 1::bigint AS teacher_id,
        '' AS teacher,
        pq.status AS status,
        pq.created_at AS date_status,
        '' AS observation,
        0::bigint AS total_refuzed,
        NULL AS pdf_status,
        pq.priority,
        FALSE AS is_missing_question
    FROM
        parent_question pq
        JOIN question q ON pq.status IN ('DASI', 'INDE')
            AND pq.id = q.parent_id
        INNER JOIN course c ON pq.course_id = c.id
        LEFT JOIN question_status qs1 ON q.id = qs1.question_id
            AND q.status = qs1.status
            AND qs1.fl_active IS TRUE
        LEFT JOIN employee_question eoq ON eoq.question_id = q.id
            AND eoq.fl_status IS TRUE
        LEFT JOIN employees es ON eoq.teacher_id = es.id
    WHERE
        1 = 1
        AND (f_type IS NULL
            OR f_type = 'T')
        AND (f_teacher_id IS NULL
            OR eoq.teacher_id = f_teacher_id)
        AND (f_course_ids IS NULL
            OR pq.course_id = ANY (f_course_ids))
        AND ((f_status IS NULL
                AND pq.status IN ('DASI', 'INDE'))
            OR (pq.status = f_status))
    GROUP BY
        pq.id,
        c.id
    HAVING
        p_name_text IS NULL
        OR LOWER(pq.code)
        LIKE '%' || LOWER(p_name_text) || '%'
        OR unaccent(LOWER(pq.short_description))
        LIKE '%' || LOWER(p_name_text) || '%'
        OR BOOL_OR(LOWER(q.code)
            LIKE '%' || LOWER(p_name_text) || '%'
            OR LOWER(q.code)
            LIKE '%' || LOWER(p_name_text) || '%'
            OR LOWER(q.short_description)
            LIKE '%' || LOWER(p_name_text) || '%')
),
counted_questions AS (
    SELECT
        *,
        count(*) OVER () AS total_count
    FROM
        tbl_question fq
    WHERE (f_type IS NULL
        OR fq.type_question = f_type))
SELECT
    *
FROM
    counted_questions AS cq
ORDER BY
    cq.priority DESC,
    CASE WHEN cq.status = 'DASI' THEN
        1
    WHEN cq.status = 'INDE' THEN
        2
    ELSE
        3
    END ASC,
    CASE WHEN cq.status = 'DASI' THEN
        cq.date_status
    ELSE
        NULL
    END ASC,
    CASE WHEN cq.status = 'INDE' THEN
        cq.date_status
    ELSE
        NULL
    END ASC,
    cq.date_status ASC,
    cq.id ASC
LIMIT p_perpage OFFSET offset_val;
END;
$$;


ALTER FUNCTION odiseo.fn_list_index_question_by_teacher(p_perpage integer, p_npage integer, p_name_text character varying, f_course_ids integer[], f_teacher_id integer, f_fl_diagrammed boolean, f_type character varying, f_status character varying) OWNER TO postgres;

--
-- Name: fn_list_material_per_period_level_limit_config(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_list_material_per_period_level_limit_config(p_material_per_period_id bigint DEFAULT NULL::bigint) RETURNS TABLE(id bigint, material_per_period_id bigint, material_id bigint, type_material_id smallint, period_start_week smallint, period_end_week smallint, start_week smallint, end_week smallint, lower_level_limit smallint, upper_level_limit smallint, created_by integer, created_by_name character varying, updated_by integer, updated_by_name character varying, deleted_by integer, deleted_by_name character varying, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        mpllc.id,
        mpllc.material_per_period_id,
        mpp.material_id,
        mpp.type_material_id,
        mpp.start_week AS period_start_week,
        mpp.end_week AS period_end_week,
        mpllc.start_week,
        mpllc.end_week,
        mpllc.lower_level_limit,
        mpllc.upper_level_limit,
        mpllc.created_by,
        uc."user" AS created_by_name,
        mpllc.updated_by,
        uu."user" AS updated_by_name,
        mpllc.deleted_by,
        ud."user" AS deleted_by_name,
        mpllc.created_at,
        mpllc.updated_at,
        mpllc.deleted_at
    FROM material_per_period_level_limit_config mpllc
    JOIN material_per_period mpp ON mpp.id = mpllc.material_per_period_id
    LEFT JOIN users uc ON uc.id = mpllc.created_by
    LEFT JOIN users uu ON uu.id = mpllc.updated_by
    LEFT JOIN users ud ON ud.id = mpllc.deleted_by
    WHERE mpllc.deleted_at IS NULL
      AND (
          p_material_per_period_id IS NULL
          OR mpllc.material_per_period_id = p_material_per_period_id
      )
    ORDER BY mpllc.start_week ASC, mpllc.end_week ASC, mpllc.id ASC;
END;
$$;


ALTER FUNCTION odiseo.fn_list_material_per_period_level_limit_config(p_material_per_period_id bigint) OWNER TO postgres;

--
-- Name: fn_list_pagination_type_material_templates(integer, integer, text, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_list_pagination_type_material_templates(p_per_page integer, p_n_page integer, p_name text, p_fl_exam boolean) RETURNS TABLE(id bigint, name character varying, fl_exam boolean, child_type_material_templates jsonb, created_at timestamp without time zone, total integer, is_children boolean, type_exam_name character varying, type_exam_id bigint, fl_revision boolean)
    LANGUAGE plpgsql
    AS $$
                DECLARE
                    total_count INTEGER;
                    offset_val INTEGER;
                BEGIN
                    offset_val := p_per_page * (p_n_page - 1);

                    SELECT COUNT(*)
                    INTO total_count
                    FROM type_material_template tmt
                    WHERE 1 = 1
                        AND (p_name IS NULL OR tmt.name ILIKE CONCAT('%', p_name, '%'))
                        AND tmt.deleted_at IS NULL AND tmt.fl_status
                        AND (p_fl_exam IS NULL OR tmt.fl_exam = p_fl_exam);

                    RETURN QUERY
                    SELECT
                        tmt.id,
                        tmt.name,
                        tmt.fl_exam,
                        COALESCE(
                            jsonb_agg(
                                DISTINCT
                                jsonb_build_object( 
                                    'id', tmt2.id,
                                    'name', tmt2.name
                                )
                            ) FILTER (WHERE tmt2.id IS NOT NULL),
                            '[]'::JSONB
                        ) AS child_type_material_templates,
                        tmt.created_at,
                        total_count AS total,
                        exists(select 1 from type_material_bound tmb2 where tmb2.type_material_template_extra_id = tmt.id  and tmb2.fl_status = true) as is_children,
                        te.name as type_exam_name,
                        te.id as type_exam_id,
                        tmt.fl_revision
                    FROM type_material_template tmt
                    LEFT JOIN type_material_bound tmb
                        ON tmb.type_material_template_id = tmt.id AND tmb.fl_status = true
                    LEFT JOIN type_material_template tmt2
                        ON tmb.type_material_template_extra_id = tmt2.id
                    LEFT JOIN type_exams te
                        ON te.id = tmt.type_exam_id
                    WHERE 1 = 1
                    AND (p_name IS NULL OR tmt.name ILIKE CONCAT('%', p_name, '%'))
                    AND tmt.deleted_at IS NULL AND tmt.fl_status = true
                    AND (p_fl_exam IS NULL OR tmt.fl_exam = p_fl_exam)
                    GROUP BY
                        tmt.id,
                        tmt.name,
                        tmt.fl_exam,
                        tmt.created_at,
                        te.id
                    ORDER BY tmt.created_at DESC, tmt.name ASC
                    LIMIT p_per_page
                    OFFSET offset_val;
                END;
                $$;


ALTER FUNCTION odiseo.fn_list_pagination_type_material_templates(p_per_page integer, p_n_page integer, p_name text, p_fl_exam boolean) OWNER TO postgres;

--
-- Name: fn_list_questions_verified_and_not_excluded(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_list_questions_verified_and_not_excluded(p_material_id bigint) RETURNS TABLE(id bigint, code character varying, course_id smallint, topic_id smallint, level_id smallint, level smallint, type character varying, status character varying, subtopic_id integer, frequent_subtopic boolean, cycle_id integer, week smallint, type_material_id smallint, history jsonb)
    LANGUAGE sql STABLE
    AS $$
    WITH material_data AS (
        SELECT
            m.university_id,
            m.company_id
        FROM material m
        WHERE m.id = p_material_id
    ), 
    ballot_questions AS (
        SELECT DISTINCT mbq.question_id 
        FROM material m
        INNER JOIN detail_week_type_mat wt ON m.id = wt.material_id AND wt.fl_status = true
        INNER JOIN material_ballot_question mbq ON wt.id = mbq.week_type_material_id AND mbq.fl_status = true
        WHERE m.id = p_material_id
    ), 
    exam_questions AS (
        SELECT DISTINCT meq.question_id 
        FROM material_exam_question meq
        INNER JOIN material_exam_area_week meaw ON meq.material_exam_area_week_id = meaw.id AND meaw.fl_status = true
        INNER JOIN detail_week_type_mat wt ON meaw.week_type_material_id = wt.id
        WHERE wt.material_id = p_material_id
        AND wt.fl_status = true
        AND meaw.fl_status = true
        AND meq.fl_status = true
        AND meq.question_id IS NOT NULL -- Optimización: Filtro de nulos
    ), 
    max_start_per_question AS (
        SELECT
            qh.question_id,
            MAX(c.start_date) AS max_start_date
        FROM question_history_cycle qh
        INNER JOIN cycle c ON qh.cycle_id = c.id
        WHERE qh.fl_status = true
            AND qh.university_id IN (SELECT md.university_id FROM material_data md)
            AND c.company_id IN (SELECT md.company_id FROM material_data md)
        GROUP BY qh.question_id
    ), 
    questions_history AS (
        SELECT DISTINCT
            qh.question_id,
            qh.cycle_id,
            c.description,
            c.start_date,
            c.end_date
        FROM question_history_cycle qh
        INNER JOIN cycle c ON qh.cycle_id = c.id
        INNER JOIN max_start_per_question mx ON qh.question_id = mx.question_id
        WHERE qh.fl_status = true
            AND qh.university_id IN (SELECT md.university_id FROM material_data md)
            AND c.start_date BETWEEN mx.max_start_date - INTERVAL '21 days' AND mx.max_start_date
            AND c.company_id IN (SELECT md.company_id FROM material_data md)
    ),
    -- Optimización: Pre-agregamos el JSON en su propio CTE
    history_aggregated AS (
        SELECT 
            question_id,
            JSONB_AGG(
                JSONB_BUILD_OBJECT(
                    'cycle_id', cycle_id,
                    'description', description,
                    'start_date', start_date,
                    'end_date', end_date
                ) ORDER BY start_date DESC
            ) AS history_json
        FROM questions_history
        GROUP BY question_id
    ),
    final_questions AS (
        SELECT
            q.id,
            q.code,
            q.course_id,
            q.topic_id,
            q.level_id,
            l.name::SMALLINT AS level,
            q.type,
            q.status,
            qs.subtopic_id,
            COALESCE(fus.is_frequent, false) AS frequent_subtopic,
            qt.cycle_id,
            qt.week_id AS week,
            qt.type_material_id,
            -- Usamos el JSON pre-armado
            COALESCE(ha.history_json, '[]'::JSONB) AS history
        FROM question q
        LEFT JOIN question_subtopic qs ON qs.question_id = q.id AND qs.fl_status = true
        LEFT JOIN question_temporary qt ON qt.question_id = q.id AND qt.fl_status = true
        LEFT JOIN level l ON l.id = q.level_id
        -- Hacemos JOIN directamente al JSON pre-armado
        LEFT JOIN history_aggregated ha ON q.id = ha.question_id
        LEFT JOIN frequent_university_subtopic fus ON fus.university_id IN (SELECT md.university_id FROM material_data md) AND fus.subtopic_id = qs.subtopic_id AND fus.fl_status = true
        WHERE q.status IN ('VERI', 'APRB')
        AND q.fl_status = true
        AND l.fl_status = true
        AND q.parent_id IS NULL
        AND NOT EXISTS (
            SELECT 1 FROM (
                SELECT question_id FROM ballot_questions
                UNION ALL
                SELECT question_id FROM exam_questions
            ) gpm
            WHERE gpm.question_id = q.id
        )
        AND NOT EXISTS (
            SELECT 1
                FROM question_excluded_material qem
                WHERE qem.question_id = q.id
                AND qem.material_id = p_material_id
                AND qem.deleted_at IS NULL
        )
        AND ( 
            q.number_question IS NULL
            OR q.number_question NOT LIKE 'D%'
        )

        UNION ALL 

        SELECT
            q.id,
            qs2.code,
            qs2.course_id,
            qs2.topic_id,
            q.level_id,
            l.name::SMALLINT AS level,
            q.type,
            q.status,
            qs2.subtopic_id,
            COALESCE(fus.is_frequent, false) AS frequent_subtopic,
            qt.cycle_id,
            qt.week_id AS week,
            qt.type_material_id,
            -- Usamos el JSON pre-armado
            COALESCE(ha.history_json, '[]'::JSONB) AS history
        FROM question q
        INNER JOIN question_shares qs2 ON qs2.question_id = q.id AND qs2.deleted_at IS NULL
        LEFT JOIN question_subtopic qs ON qs.question_id = q.id AND qs.fl_status = true
        LEFT JOIN question_temporary qt ON qt.question_id = q.id AND qt.fl_status = true
        LEFT JOIN level l ON l.id = q.level_id
        -- Hacemos JOIN directamente al JSON pre-armado
        LEFT JOIN history_aggregated ha ON q.id = ha.question_id
        LEFT JOIN frequent_university_subtopic fus ON fus.university_id IN (SELECT md.university_id FROM material_data md) AND fus.subtopic_id = qs.subtopic_id AND fus.fl_status = true
        WHERE q.status IN ('VERI', 'APRB')
        AND q.fl_status = true
        AND l.fl_status = true
        AND q.parent_id IS NULL
        AND NOT EXISTS (
            SELECT 1 FROM (
                SELECT question_id FROM ballot_questions
                UNION ALL
                SELECT question_id FROM exam_questions
            ) gpm
            WHERE gpm.question_id = q.id
        )
        AND NOT EXISTS (
            SELECT 1
                FROM question_excluded_material qem
                WHERE qem.question_id = q.id
                AND qem.material_id = p_material_id
                AND qem.deleted_at IS NULL
        )
        AND ( 
            q.number_question IS NULL
            OR q.number_question NOT LIKE 'D%'
        )

    )
    SELECT fq.* FROM final_questions fq
    ORDER BY fq.id DESC, fq.topic_id ASC, fq.subtopic_id ASC;
$$;


ALTER FUNCTION odiseo.fn_list_questions_verified_and_not_excluded(p_material_id bigint) OWNER TO postgres;

--
-- Name: fn_list_search_revised_question(integer, integer, integer, character varying, bigint, integer, character varying, smallint, smallint, smallint, smallint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_list_search_revised_question(p_perpage integer, p_npage integer, p_employee_id integer, p_name_text character varying, p_employee_didi_id bigint, p_course_id integer, p_type character varying, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_version smallint, p_year character varying) RETURNS TABLE(key_question text, id bigint, code character varying, short_description text, number_question character varying, number character varying, course_id smallint, code_course character varying, course character varying, status character varying, fl_status boolean, parent_id bigint, type_question text, subquestions jsonb, created_by bigint, created_at timestamp without time zone, user_name character varying, user_email odiseo.email_citext, date_status timestamp without time zone, employee_id bigint, name_employee text, observation text, similitaries text, origin_question jsonb, priority integer, is_missing_question boolean, subtopic_id integer, total bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    offset_val integer := p_perpage * (p_npage - 1);
BEGIN
    RETURN QUERY WITH employee_course AS (
        SELECT
            ec.course_id
        FROM
            employee_course ec
        WHERE (p_employee_id IS NULL
            OR ec.teacher_id = p_employee_id)
),
dupl_questions AS (
    SELECT
        q.*,
        qn.question_origin,
        qn.university_id,
        qn.option_id,
        qn.modality_id,
        qn."version",
        qn."year"
    FROM
        question q
        LEFT JOIN v_all_question_origins qn ON qn.question_id = q.id
    WHERE
        1 = 1
        AND q.fl_status = TRUE
        AND q.status = 'DUPL'
        AND q.deleted_at IS NULL
        AND (p_university_id IS NULL
            OR qn.university_id = p_university_id)
        AND (p_option_id IS NULL
            OR qn.option_id = p_option_id)
        AND (p_modality_id IS NULL
            OR qn.modality_id = p_modality_id)
        AND (p_version IS NULL
            OR qn."version" = p_version)
        AND (p_year IS NULL
            OR qn."year" = p_year)
),
questions AS (
    SELECT
        concat('p_', q.id) AS key_question,
        q.id,
        q.code,
        q.short_description,
        q.number_question,
        q.number,
        q.course_id,
        c.code AS code_course,
        c.name AS course,
        q.status,
        q.fl_status,
        q.parent_id,
        CASE WHEN q.parent_id IS NULL THEN
            'P'
        ELSE
            'S'
        END AS type_question,
        q.created_by,
        qs.created_at AS created_at,
        u.user AS user_name,
        u.email AS user_email,
        COALESCE(qs.created_at, q.created_at) AS date_status,
        e.id AS employee_id,
        CONCAT(e.first_surname, ' ', e.second_surname, ' ', e.first_name) AS name_employee,
        qo.description AS observation,
        qo.similitaries,
        q.question_origin,
        q.priority,
        CASE WHEN mmqd.question_id IS NOT NULL THEN
            TRUE
        ELSE
            FALSE
        END AS is_missing_question
    FROM
        dupl_questions q
        INNER JOIN course c ON q.course_id = c.id
        LEFT JOIN users u ON q.created_by = u.id
        LEFT JOIN employees e ON u.id = e.user_id
        LEFT JOIN question_status qs ON q.id = qs.question_id
            AND q.status = qs.status
            AND qs.fl_active = TRUE
        LEFT JOIN question_observation qo ON q.id = qo.question_id
            AND q.status = qo.type
            AND qo.fl_status = TRUE
        LEFT JOIN material_missing_question_detail mmqd ON mmqd.question_id = q.id
    WHERE
        q.deleted_at IS NULL
        AND (p_employee_didi_id IS NULL
            OR e.id = p_employee_didi_id)
),
sub_questions AS (
    SELECT
        pq.id AS parent_id,
        JSONB_AGG(
            JSONB_BUILD_OBJECT(
            'key_question', concat('s_', q.id), 
            'id', q.id, 
            'code', q.code, 
            'short_description', q.short_description, 
            'number_question', q.number_question, 
            'number', q.number, 
            'course_id', q.course_id, 
            'code_course', c.code, 
            'course', c.name, 
            'status', q.status, 
            'fl_status', q.fl_status, 
            'parent_id', q.parent_id, 
            'type_question', 'S', 
            'created_by', q.created_by, 
            'created_at', qs.created_at, 
            'user_name', u.user, 
            'user_email', u.email, 
            'date_status', COALESCE(qs.created_at, q.created_at), 
            'employee_id', e.id, 
            'name_employee', CONCAT(e.first_surname, ' ', e.second_surname, ' ', e.first_name), 
            'observation', qo.description, 
            'similitaries', qo.similitaries,
            'subtopic_id', qspt.subtopic_id,
            'origin_question', q.question_origin)) AS subquestions
    FROM
        dupl_questions q
        INNER JOIN parent_question pq ON q.parent_id = pq.id
        INNER JOIN course c ON q.course_id = c.id
        LEFT JOIN users u ON q.created_by = u.id
        LEFT JOIN employees e ON u.id = e.user_id
        LEFT JOIN question_subtopic qspt ON q.id = qspt.question_id
        LEFT JOIN question_status qs ON q.id = qs.question_id
            AND q.status = qs.status
            AND qs.fl_active = TRUE
        LEFT JOIN question_observation qo ON q.id = qo.question_id
            AND q.status = qo.type
            AND qo.fl_status = TRUE
    WHERE
        1 = 1
        AND q.deleted_at IS NULL
        AND (p_employee_didi_id IS NULL
            OR e.id = p_employee_didi_id)
    GROUP BY
        pq.id
),
tbl_question AS (
    SELECT
        concat('p_', q.id) AS key_question,
        q.id,
        q.code,
        q.short_description,
        q.number_question,
        q.number,
        q.course_id,
        q.code_course,
        q.course,
        q.status,
        q.fl_status,
        q.parent_id,
        q.type_question,
        COALESCE(sq.subquestions, '[]'::jsonb) AS subquestions,
        q.created_by,
        q.created_at,
        q.user_name,
        q.user_email,
        q.date_status,
        q.employee_id,
        q.name_employee,
        q.observation,
        q.similitaries,
        q.question_origin,
        q.priority,
        q.is_missing_question,
        qspt.subtopic_id::integer AS subtopic_id
    FROM
        questions q
        LEFT JOIN sub_questions sq ON q.parent_id = sq.parent_id
        LEFT JOIN question_subtopic qspt ON q.id = qspt.question_id
    WHERE
        q.parent_id IS NULL
    UNION ALL SELECT DISTINCT
        concat('t_', pq.id) AS key_question,
        pq.id,
        pq.code,
        pq.short_description,
        pq.number_question,
        pq.number,
        pq.course_id,
        c.code AS code_course,
        c.name AS course,
        pq.status,
        pq.fl_status,
        pq.id AS parent_id,
        'T' AS type_question,
        COALESCE(sq.subquestions, '[]'::jsonb) AS subquestions,
        pq.created_by,
        pq.created_at AS created_at,
        u.user AS user_name,
        u.email AS user_email,
        pq.created_at AS date_status,
        e.id AS employee_id,
        CONCAT(e.first_surname, ' ', e.second_surname, ' ', e.first_name) AS name_employee,
        po.description AS observation,
        po.similitaries,
        opq.question_origin,
        pq.priority,
        FALSE AS is_missing_question,
        NULL::integer AS subtopic_id
    FROM
        parent_question pq
        INNER JOIN course c ON pq.course_id = c.id
        LEFT JOIN users u ON pq.created_by = u.id
        LEFT JOIN employees e ON u.id = e.user_id
        LEFT JOIN parent_observation po ON pq.id = po.parent_id
            AND po.fl_status = TRUE
            AND po.type = 'DUPL'
        LEFT JOIN sub_questions sq ON pq.id = sq.parent_id
            AND sq.parent_id IS NOT NULL
        LEFT JOIN v_all_parent_origins opq ON opq.parent_id = pq.id
    WHERE
        pq.fl_status = TRUE
        AND pq.deleted_at IS NULL
        AND (p_employee_didi_id IS NULL
            OR e.id = p_employee_didi_id)
        AND (pq.status = 'DUPL'
            OR EXISTS (
                SELECT
                    1
                FROM
                    question q
                WHERE
                    q.parent_id = pq.id
                    AND q.deleted_at IS NULL
                    AND q.status = 'DUPL'))
            AND (sq.subquestions IS NOT NULL
                AND sq.subquestions <> '[]')
            AND (p_university_id IS NULL
                OR opq.university_id = p_university_id)
            AND (p_option_id IS NULL
                OR opq.option_id = p_option_id)
            AND (p_modality_id IS NULL
                OR opq.modality_id = p_modality_id)
            AND (p_version IS NULL
                OR opq."version" = p_version)
            AND (p_year IS NULL
                OR opq."year" = p_year)
),
filtered_questions AS (
    SELECT
        *
    FROM
        tbl_question
    WHERE (p_course_id IS NULL
        OR tbl_question.course_id = p_course_id)
    AND (p_type IS NULL
        OR tbl_question.type_question = p_type)
    AND (p_employee_id IS NULL
        OR tbl_question.course_id IN (
            SELECT
                ec.course_id
            FROM
                employee_course ec))
        AND (p_name_text IS NULL
            OR unaccent(LOWER(tbl_question.short_description))
            LIKE '%' || LOWER(p_name_text) || '%'
            OR LOWER(tbl_question.number_question)
            LIKE '%' || LOWER(p_name_text) || '%'
            OR LOWER(tbl_question.number)
            LIKE '%' || LOWER(p_name_text) || '%'
            OR LOWER(tbl_question.code)
            LIKE '%' || LOWER(p_name_text) || '%'
            OR EXISTS (
                SELECT
                    1
                FROM
                    jsonb_array_elements(tbl_question.subquestions) AS sq
                WHERE
                    unaccent(LOWER(sq ->> 'short_description'))
                    LIKE '%' || LOWER(p_name_text) || '%'
                    OR LOWER(sq ->> 'number_question')
                    LIKE '%' || LOWER(p_name_text) || '%'
                    OR LOWER(sq ->> 'number')
                    LIKE '%' || LOWER(p_name_text) || '%'
                    OR LOWER(sq ->> 'code')
                    LIKE '%' || LOWER(p_name_text) || '%'))
),
counted_questions AS (
    SELECT
        *,
        count(*) OVER () AS total
FROM
    filtered_questions
)
SELECT
    *
FROM
    counted_questions
ORDER BY
    priority DESC,
    created_at ASC,
    date_status ASC,
    key_question ASC
LIMIT p_perpage OFFSET offset_val;
END;
$$;


ALTER FUNCTION odiseo.fn_list_search_revised_question(p_perpage integer, p_npage integer, p_employee_id integer, p_name_text character varying, p_employee_didi_id bigint, p_course_id integer, p_type character varying, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_version smallint, p_year character varying) OWNER TO postgres;

--
-- Name: fn_list_subtopics_by_universities_and_topic_and_course(jsonb, smallint, smallint, boolean, bigint, integer, integer, jsonb, integer, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_list_subtopics_by_universities_and_topic_and_course(f_university_ids jsonb, f_course_id smallint, f_topic_id smallint, p_fl_pseudo boolean, p_option_id bigint, p_start_year integer, p_end_year integer, p_areas jsonb, p_company_id integer, p_show_frequent boolean DEFAULT true) RETURNS TABLE(id smallint, code character varying, name character varying, exist_subtopics boolean, pseuodo_course_id bigint, course_id smallint, is_frequent boolean, frecuency_intensity text, details jsonb, total_detail bigint, method character varying)
    LANGUAGE plpgsql
    AS $$
                            DECLARE
                                v_courses_ids SMALLINT[];
                                v_university_ids SMALLINT[];
                            BEGIN
                                v_university_ids := ARRAY(SELECT jsonb_array_elements_text(f_university_ids)::SMALLINT);

                                IF p_fl_pseudo IS TRUE THEN
                                    SELECT ARRAY(
                                        SELECT cpc.course_id AS id_course
                                        FROM course_pseudo_courses cpc
                                        WHERE 1 = 1
                                        AND cpc.fl_status IS TRUE
                                        AND cpc.pseudo_course_id = f_course_id
                                        ORDER BY cpc.order
                                    ) INTO v_courses_ids;
                                ELSE
                                    SELECT ARRAY[f_course_id] INTO v_courses_ids;
                                END IF;

                                RETURN QUERY
                                WITH modality_options_cte as (
                                    SELECT
                                        mo.id,
                                        mo.fl_allows_mark_frequent_topic,
                                        ou.id as option_university_id
                                    FROM modality_options mo
                                    INNER JOIN option_university ou ON mo.option_university_id = ou.id AND ou.university_id = ANY(v_university_ids) 
                                    WHERE mo.deleted_at IS NULL
                                    AND (
                                        p_option_id IS NULL
                                        OR ou.id = p_option_id
                                    )
                                ), frecuency_details AS (
                                    SELECT
                                        s.id subtopic_id,
                                        JSONB_AGG(
                                            JSON_BUILD_OBJECT(
                                                'year', oq."year",
                                                'version', fn_number_to_roman(oq."version"),
                                                'areas', (
                                                    SELECT array_to_string(
                                                        ARRAY(
                                                            SELECT json_array_elements_text(oq.areas::json)
                                                        ),
                                                        ' - '
                                                    )
                                                )
                                            )  ORDER BY oq.year DESC
                                        ) AS details,
                                        COUNT(*) total_detail
                                    FROM origin_question oq
                                    JOIN question q ON q.id = oq.question_id
                                    JOIN question_subtopic qs ON qs.question_id = q.id AND qs.fl_status = true
                                    JOIN subtopic s ON s.id = qs.subtopic_id
                                    JOIN modality_options_cte m ON m.id = oq.modality_option_id
                                    JOIN option_university ou ON ou.id = m.option_university_id
                                    WHERE ou.university_id = ANY(v_university_ids)
                                    AND m.fl_allows_mark_frequent_topic = true
                                    AND (p_start_year IS NULL OR oq.year::integer >= p_start_year)
                                    AND (p_end_year IS NULL OR oq.year::integer <= p_end_year)
                                    AND (p_areas IS NULL OR p_areas = '[]' OR oq.areas::jsonb ?| array(SELECT jsonb_array_elements_text(p_areas)))
                                    AND oq.fl_status = true
                                    GROUP BY s.id
                                )
                                SELECT
                                    s.id,
                                    s.code,
                                    s.name,
                                    CASE WHEN tbl_template_subtopics.subtopic_id IS NULL THEN FALSE ELSE TRUE END AS exist_subtopics,
                                    tbl_template_subtopics.course_id AS pseuodo_course_id,
                                    t.course_id,
                                    COALESCE(fuc.is_frequent, FALSE) is_frequent,
                                    CASE
                                            WHEN p_show_frequent = FALSE THEN NULL
                                            WHEN fd.total_detail >= 1 AND fd.total_detail <= 2 THEN 'low_frequency'
                                            WHEN fd.total_detail > 2 AND fd.total_detail <= 4 THEN 'medium_frequency'
                                            WHEN fd.total_detail > 4 THEN 'high_frequency'
                                        END AS frecuency_intensity,
                                    fd.details,
                                    fd.total_detail,
                                    fuc.method
                                FROM subtopic s
                                LEFT JOIN (
                                    SELECT stts.subtopic_id, st.course_id
                                    FROM syllabus_template_topic_subtopic stts
                                    INNER JOIN syllabus_template_topic stt ON stts.syllabus_template_topic_id = stt.id AND stt.company_id = p_company_id
                                    INNER JOIN syllabus_template st ON stt.syllabus_template_id = st.id  AND st.company_id = p_company_id
                                    WHERE 1 = 1
                                    AND stts.fl_status IS TRUE
                                    AND stt.fl_status IS TRUE
                                    AND st.fl_status IS TRUE
                                    AND st.university_id = ANY(v_university_ids)
                                    AND stt.topic_id = f_topic_id
                                    AND st.course_id = f_course_id
                                    AND stts.company_id = p_company_id
                                ) AS tbl_template_subtopics ON s.id = tbl_template_subtopics.subtopic_id
                                LEFT JOIN frequent_university_subtopic fuc ON fuc.subtopic_id = s.id AND fuc.university_id = ANY(v_university_ids) AND fuc.fl_status IS TRUE
                                JOIN topic t ON s.topic_id  = t.id
                                LEFT JOIN frecuency_details fd ON fd.subtopic_id = s.id
                                WHERE 1 = 1
                                AND t.course_id = ANY(v_courses_ids)
                                AND s.fl_status
                                AND t.id = f_topic_id
                                AND t.fl_status
                                ORDER BY exist_subtopics DESC, unaccent(t.name);
                            END;
                            $$;


ALTER FUNCTION odiseo.fn_list_subtopics_by_universities_and_topic_and_course(f_university_ids jsonb, f_course_id smallint, f_topic_id smallint, p_fl_pseudo boolean, p_option_id bigint, p_start_year integer, p_end_year integer, p_areas jsonb, p_company_id integer, p_show_frequent boolean) OWNER TO postgres;

--
-- Name: fn_list_teachers_by_company(bigint, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_list_teachers_by_company(p_company_id bigint, p_courses jsonb) RETURNS TABLE(id bigint, value text, courses jsonb, fl_status boolean)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        e.id,
        CONCAT(e.code, ' - ', e.first_name, ' ', e.first_surname, ' ', e.second_surname)::TEXT AS value,
        COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    'id', c.id,
                    'code', c.code,
                    'name', c.name,
                    'fl_status', c.fl_status
                ) ORDER BY c.id ASC
            ),
            '[]'::jsonb
        ) AS courses,
        e.fl_status
    FROM teachers t
    INNER JOIN employees e ON e.id = t.employee_id
    INNER JOIN employee_course ec ON e.id = ec.teacher_id AND ec.fl_status = true
    INNER JOIN users u ON e.user_id = u.id AND u.fl_status = true AND u.fl_suspended = false
    INNER JOIN users_roles ur ON e.user_id = ur.user_id AND ur.fl_status = true
    INNER JOIN course c ON ec.course_id = c.id AND c.fl_status = true
    WHERE e.company_id = p_company_id
        AND e.fl_status = true
        AND ec.course_id = ANY (
            SELECT (jsonb_array_elements_text(p_courses))::SMALLINT
        )
        AND e.fl_resolve_missing_questions IS TRUE
    GROUP BY
        e.id,
        e.code,
        e.first_name,
        e.first_surname,
        e.second_surname,
        e.fl_status
    ORDER BY e.id ASC;
END;
$$;


ALTER FUNCTION odiseo.fn_list_teachers_by_company(p_company_id bigint, p_courses jsonb) OWNER TO postgres;

--
-- Name: fn_list_topics_by_universities_and_course_or_pseudo(jsonb, bigint, boolean, bigint, integer, integer, jsonb, integer, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_list_topics_by_universities_and_course_or_pseudo(f_university_ids jsonb, f_course_id bigint, p_fl_pseudo boolean, p_option_id bigint, p_start_year integer, p_end_year integer, p_areas jsonb, p_company_id integer, p_show_frequent boolean DEFAULT true) RETURNS TABLE(id smallint, code character varying, name character varying, exist_topic boolean, course_id smallint, frecuency_intensity text, details jsonb, total_detail bigint)
    LANGUAGE plpgsql
    AS $$
                            DECLARE
                                v_courses_ids BIGINT[];
                                v_university_ids BIGINT[];
                            BEGIN
                                v_university_ids := ARRAY(SELECT jsonb_array_elements_text(f_university_ids)::BIGINT);

                                IF p_fl_pseudo IS TRUE THEN
                                    SELECT ARRAY(
                                        SELECT cpc.course_id AS id_course
                                        FROM course_pseudo_courses cpc
                                        WHERE 1 = 1
                                        AND cpc.fl_status IS TRUE
                                        AND cpc.pseudo_course_id = f_course_id
                                        ORDER BY cpc.order
                                    ) INTO v_courses_ids;
                                ELSE
                                    SELECT ARRAY[f_course_id] INTO v_courses_ids;
                                END IF;

                                RETURN QUERY
                                WITH modality_options_cte as (
                                    SELECT
                                        mo.id,
                                        mo.fl_allows_mark_frequent_topic,
                                        ou.id as option_university_id
                                    FROM modality_options mo
                                    INNER JOIN option_university ou ON mo.option_university_id = ou.id AND ou.university_id = ANY(v_university_ids) 
                                    WHERE mo.deleted_at IS NULL
                                    AND (
                                        p_option_id IS NULL
                                        OR ou.id = p_option_id
                                    )
                                ),frecuency_details AS (
                                    SELECT
                                        t.id topic_id,
                                        JSONB_AGG(
                                            JSON_BUILD_OBJECT(
                                                'year', oq."year",
                                                'version', fn_number_to_roman(oq."version"),
                                                'areas', (
                                                    SELECT array_to_string(
                                                        ARRAY(
                                                            SELECT json_array_elements_text(oq.areas::json)
                                                        ),
                                                        ' - '
                                                    )
                                                )
                                            ) ORDER BY oq.year DESC
                                        ) AS details,
                                        COUNT(*) total_detail
                                    FROM origin_question oq
                                    JOIN question q ON q.id = oq.question_id
                                    JOIN question_subtopic qs ON qs.question_id = q.id AND qs.fl_status = true
                                    JOIN subtopic s ON s.id = qs.subtopic_id
                                    JOIN topic t ON t.id = s.topic_id
                                    JOIN modality_options_cte m ON m.id = oq.modality_option_id
                                    JOIN option_university ou ON ou.id = m.option_university_id
                                    WHERE ou.university_id = ANY(v_university_ids)
                                    AND m.fl_allows_mark_frequent_topic = true
                                    AND (p_start_year IS NULL OR oq.year::integer >= p_start_year)
                                    AND (p_end_year IS NULL OR oq.year::integer <= p_end_year)
                                    AND (p_areas IS NULL OR p_areas = '[]' OR oq.areas::jsonb ?| array(SELECT jsonb_array_elements_text(p_areas)))
                                    AND oq.fl_status = true
                                    GROUP BY t.id
                                )
                                SELECT
                                    t.id,
                                    t.code,
                                    t.name,
                                    CASE
                                        WHEN tbl_template_topic.topic_id IS NULL
                                            THEN FALSE
                                        ELSE TRUE
                                    END AS exist_topic,
                                    t.course_id,
                                    CASE
                                        WHEN p_show_frequent = FALSE THEN NULL
                                        WHEN fd.total_detail >= 1 AND fd.total_detail <= 2 THEN 'low_frequency'
                                        WHEN fd.total_detail > 2 AND fd.total_detail <= 4 THEN 'medium_frequency'
                                        WHEN fd.total_detail > 4 THEN 'high_frequency'
                                    END AS frecuency_intensity,
                                    fd.details,
                                    fd.total_detail
                                FROM topic t
                                LEFT JOIN
                                (
                                    SELECT
                                        stt.topic_id
                                    FROM syllabus_template_topic stt
                                    LEFT JOIN syllabus_template st ON stt.syllabus_template_id = st.id AND st.company_id = p_company_id
                                    WHERE 1 = 1
                                    AND st.university_id = ANY(v_university_ids)
                                    AND st.course_id = f_course_id
                                    AND stt.fl_status IS TRUE
                                    AND st.fl_status IS TRUE
                                    AND stt.company_id = p_company_id
                                ) AS tbl_template_topic ON tbl_template_topic.topic_id = t.id
                                LEFT JOIN frecuency_details fd ON fd.topic_id = t.id
                                WHERE 1 = 1
                                AND t.course_id = ANY(v_courses_ids)
                                AND t.fl_status = TRUE
                                AND t.deleted_at IS NULL
                                GROUP BY
                                    t.id,
                                    t.code,
                                    t.name,
                                    t.course_id,
                                    exist_topic,
                                    fd.details,
                                    fd.total_detail
                                ORDER BY t.course_id, t.code, exist_topic DESC, unaccent(t.name) ASC;
                            END;
                            $$;


ALTER FUNCTION odiseo.fn_list_topics_by_universities_and_course_or_pseudo(f_university_ids jsonb, f_course_id bigint, p_fl_pseudo boolean, p_option_id bigint, p_start_year integer, p_end_year integer, p_areas jsonb, p_company_id integer, p_show_frequent boolean) OWNER TO postgres;

--
-- Name: fn_list_universities_by_region(smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_list_universities_by_region(p_region_id smallint) RETURNS TABLE(id smallint, code character varying, name character varying, slug character varying, type smallint, region_id smallint, region character varying, options jsonb, areas text, versions jsonb)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                    SELECT
                        u.id, u.code, u.name, u.slug, u.type, u.region_id,
                        r.name AS region,
                        (
                            -- Subconsulta de Opciones (Mapeado a option_university)
                            SELECT COALESCE(jsonb_agg(option_data), '[]'::jsonb)
                            FROM (
                                SELECT ou.id, ou.name,
                                    (
                                        -- Subconsulta de Modalidades (Mapeado a modality_options)
                                        SELECT COALESCE(jsonb_agg(modality_data), '[]'::jsonb)
                                        FROM (
                                            SELECT mo.id, mo.name
                                            FROM modality_options mo
                                            WHERE mo.option_university_id = ou.id
                                            AND mo.deleted_at IS NULL
                                            ORDER BY mo.id ASC
                                        ) modality_data
                                    ) AS modalities
                                FROM option_university ou
                                WHERE ou.university_id = u.id
                                AND ou.deleted_at IS NULL
                                ORDER BY ou.id ASC
                            ) option_data
                        ) AS options,
                        u.areas,
                        (
                            SELECT JSONB_AGG(JSONB_BUILD_OBJECT('order', e->>'order', 'version', fn_number_to_roman((e->>'version')::SMALLINT)))
                            FROM JSONB_ARRAY_ELEMENTS(u.versions::JSONB) e
                        ) AS versions
                    FROM origin_university u
                    LEFT JOIN region r ON u.region_id = r.id
                    WHERE u.deleted_by IS NULL
                    AND u.fl_active = true
                    AND (p_region_id IS NULL OR u.region_id = p_region_id)
                    ORDER BY u.name ASC;
            END;
            $$;


ALTER FUNCTION odiseo.fn_list_universities_by_region(p_region_id smallint) OWNER TO postgres;

--
-- Name: fn_list_uses_essential_knowledge(integer, integer, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_list_uses_essential_knowledge(p_perpage integer, p_npage integer, p_search character varying, p_essential_knowledge_id bigint) RETURNS TABLE(id bigint, question_id bigint, code character varying, status character varying, total bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    offset_val integer := p_perpage * (p_npage - 1);
BEGIN
    -- Listar los conocimientos esenciales asociados a un curso y tema específicos
    RETURN QUERY
    WITH tbl_essential_knowledges_questions AS (
        SELECT
            ek.id,
            q.id AS question_id,
            q.code,
            q.status
        FROM essential_knowledges ek
        JOIN essential_knowledge_image eki ON ek.id = eki.essential_knowledge_id
        JOIN essential_knowledge_questions ekq ON ek.id = ekq.essential_knowledge_id
        JOIN question q ON ekq.question_id = q.id
            AND q.fl_status = true
        WHERE 1 = 1
            AND ek.id = p_essential_knowledge_id
            AND (p_search IS NULL OR q.code ILIKE '%' || p_search || '%')
            AND ek.is_active is true
            AND ek.deleted_at IS NULL
            AND eki.deleted_at IS NULL
            AND ekq.deleted_at IS NULL
    ), counted_essential_knowledges AS (
        SELECT
            *,
            count(*) OVER () AS total
        FROM tbl_essential_knowledges_questions
    )
    SELECT
        *
    FROM
        counted_essential_knowledges cek
    ORDER BY
        cek.code DESC
    LIMIT p_perpage OFFSET offset_val;

END;
$$;


ALTER FUNCTION odiseo.fn_list_uses_essential_knowledge(p_perpage integer, p_npage integer, p_search character varying, p_essential_knowledge_id bigint) OWNER TO postgres;

--
-- Name: fn_list_verified_question(character varying, integer, integer, integer, character varying, json, json, json, integer, integer, integer, integer, character varying, integer[], smallint, smallint, smallint, smallint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_list_verified_question(f_name_text character varying, f_employee_id integer, f_course_id integer, f_teacher_id integer, f_type character varying, f_topics_id json, f_subtopics_id json, f_status json, f_cycle_id integer, f_week_id integer, f_type_material_id integer, f_level_id integer, f_number_question character varying, f_array_courses integer[], f_university_id smallint, f_option_id smallint, f_modality_id smallint, f_version smallint, f_year character varying) RETURNS TABLE(id bigint, key_question text, parent_id bigint, subquestions jsonb, type_question text, code character varying, number_question character varying, short_description text, course_id smallint, course character varying, teacher_id bigint, subtopic_id bigint, teacher text, status character varying, date_status timestamp without time zone, observation text, level_id smallint, level_question character varying, origin_question jsonb, shared_status text, total_count bigint)
    LANGUAGE plpgsql
    AS $$
                DECLARE status_array VARCHAR[];
                BEGIN
                    IF f_status IS NULL THEN
                        status_array := ARRAY['DIGI', 'VERI', 'PEND', 'RESV','APRB'];
                    ELSIF jsonb_typeof(f_status::jsonb) = 'array' AND jsonb_array_length(f_status::jsonb) = 0 THEN
                        status_array := ARRAY['DIGI', 'VERI', 'PEND', 'RESV','APRB'];
                    ELSIF jsonb_typeof(f_status::jsonb) = 'array' THEN
                        SELECT array_agg(value::text)
                        INTO status_array
                        FROM jsonb_array_elements_text(f_status::jsonb);
                    ELSIF jsonb_typeof(f_status::jsonb) = 'string' THEN
                        status_array := ARRAY[f_status::text];
                    ELSE
                        status_array := ARRAY['DIGI', 'VERI', 'PEND', 'RESV','APRB'];
                    END IF;

                    RETURN QUERY
                    WITH first_verified_date AS (
                        SELECT
                            qss.question_id,
                            MIN(qss.created_at) date_status
                        FROM question_status qss
                        WHERE qss.status = 'VERI'
                        GROUP BY qss.question_id
                    ), verified_p_questions AS (
                        SELECT
                            vf.id,
                            vf.code,
                            vf.status,
                            vf.short_description,
                            vf.parent_id,
                            vf.course_id,
                            vf.fl_status,
                            vf.topic_id,
                            vf.number_question,
                            fvd.date_status,
                            vf.level_id,
                            CASE
                                WHEN l.name IS NOT NULL THEN l.name
                                ELSE l.description
                            END AS level_question,
                            qn.question_origin,
                            qn.university_id,
                            qn.option_id,
                            qn.modality_id,
                            qn."version",
                            qn."year"
                        FROM question vf
                        LEFT JOIN v_all_question_origins qn ON qn.question_id = vf.id
                        LEFT JOIN first_verified_date fvd ON fvd.question_id = vf.id
                        LEFT JOIN level l ON l.id = vf.level_id
                        WHERE 1 = 1
                        AND vf.fl_status = TRUE
                        AND vf.deleted_at IS NULL
                        AND vf.status = ANY(status_array)
                        AND (f_number_question IS NULL OR vf.number_question ILIKE CONCAT('%', f_number_question, '%'))
                        AND ( f_university_id IS NULL OR qn.university_id = f_university_id )
                        AND ( f_option_id IS NULL OR qn.option_id = f_option_id )
                        AND ( f_modality_id IS NULL OR qn.modality_id = f_modality_id )
                        AND ( f_version IS NULL OR qn."version" = f_version )
                        AND ( f_year IS NULL OR qn."year" = f_year )
                    ),
                    shared_status_cte AS (
                        SELECT DISTINCT
                            qsh.question_id,
                            qsh.subtopic_id,
                            'shared'::TEXT AS shared_status
                        FROM question_shares qsh
                        WHERE qsh.deleted_at IS NULL
                    ),
                    verified_p_questions_expanded AS (

                    /* Preguntas normales */
                    SELECT
                        q.id,
                        q.code,
                        q.status,
                        q.short_description,
                        q.parent_id,
                        q.course_id,
                        q.fl_status,
                        q.topic_id,
                        NULL::BIGINT AS share_id,
                        qs.subtopic_id::BIGINT AS subtopic_id,
                        FALSE AS is_shared,
                        q.number_question,
                        q.date_status,
                        q.level_id,
                        q.level_question,
                        q.question_origin,
                        q.university_id,
                        q.option_id,
                        q.modality_id,
                        q."version",
                        q."year",

                        COALESCE(
                            ss.shared_status,
                            'not_shared'
                        ) AS shared_status

                    FROM verified_p_questions q

                    INNER JOIN question_subtopic qs
                        ON qs.question_id = q.id
                        AND qs.fl_status = TRUE

                    LEFT JOIN shared_status_cte ss
                        ON ss.question_id = q.id
                        AND ss.subtopic_id = qs.subtopic_id


                    UNION ALL


                    /* Preguntas compartidas */
                    SELECT
                        q.id,
                        qs.code,
                        q.status,
                        q.short_description,
                        q.parent_id,
                        t.course_id,
                        q.fl_status,
                        qs.topic_id,
                        qs.id AS share_id,
                        qs.subtopic_id,
                        TRUE AS is_shared,
                        q.number_question,
                        q.date_status,
                        q.level_id,
                        q.level_question,
                        q.question_origin,
                        q.university_id,
                        q.option_id,
                        q.modality_id,
                        q."version",
                        q."year",

                        COALESCE(
                            ss.shared_status,
                            'not_shared'
                        ) AS shared_status

                    FROM verified_p_questions q

                    INNER JOIN question_shares qs
                        ON qs.question_id = q.id
                        AND qs.deleted_at IS NULL

                    INNER JOIN topic t
                        ON t.id = qs.topic_id

                    LEFT JOIN shared_status_cte ss
                        ON ss.question_id = q.id
                        AND ss.subtopic_id = qs.subtopic_id
                ),filtered_questions AS (
                        /* P questions */
                        SELECT
                            DISTINCT q.id AS id,
                            CASE
                                WHEN q.is_shared THEN 'f_' || q.id || '_s_' || q.share_id
                                ELSE 'f_' || q.id
                            END AS key_question,
                            pq.id AS parent_id,
                            NULL::JSONB AS subquestions,
                            'P' AS type_question,
                            q.code AS code,
                            q.number_question AS number_question,
                            q.short_description AS short_description,
                            q.course_id,
                            c.name AS course,
                            eq.teacher_id,
                            q.subtopic_id,
                            CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name) AS teacher,
                            q.status status,
                            q.date_status AS date_status,
                            '' AS observation,
                            q.level_id::SMALLINT AS level_id,
                            q.level_question AS level_question,
                            q.question_origin,
                            q.shared_status
                        FROM employee_didi_question edq
                        INNER JOIN verified_p_questions_expanded q ON edq.question_id = q.id
                        LEFT JOIN parent_question pq ON q.parent_id = pq.id
                        LEFT JOIN course c ON q.course_id = c.id
                        LEFT JOIN employee_question eq ON eq.question_id = q.id AND eq.fl_status = true
                        LEFT JOIN employees e ON eq.teacher_id = e.id
                        LEFT JOIN question_subtopic qsub ON edq.question_id = qsub.question_id AND qsub.fl_status = TRUE AND q.is_shared = FALSE
                        WHERE 1 = 1
                        AND ( ( f_type IS NULL OR f_type = 'P' ) AND q.parent_id IS NULL )
                        AND (f_employee_id IS NULL OR q.course_id = ANY(f_array_courses))
                        AND (f_teacher_id IS NULL OR e.id = f_teacher_id)
                        AND q.status = ANY(status_array)
                        AND (f_level_id IS NULL OR q.level_id = f_level_id)
                        AND (f_topics_id IS NULL OR q.topic_id = ANY (SELECT jsonb_array_elements_text(f_topics_id::jsonb)::int))
                        AND (f_course_id IS NULL OR q.course_id = f_course_id)
                        AND (f_number_question IS NULL OR q.number_question ILIKE CONCAT('%', f_number_question, '%'))
                        AND (
                            f_subtopics_id IS NULL
                            OR (
                                COALESCE(q.subtopic_id, qsub.subtopic_id) IS NOT NULL
                                AND COALESCE(q.subtopic_id, qsub.subtopic_id) = ANY (SELECT jsonb_array_elements_text(f_subtopics_id::jsonb)::int)
                            )
                        )
                        AND (
                            f_name_text IS NULL
                            OR LOWER(translate(q.code, E'\u00A0', ' ')) ILIKE '%' || LOWER(f_name_text) || '%'
                            OR LOWER(translate(q.number_question, E'\u00A0', ' ')) ILIKE '%' || LOWER(f_name_text) || '%'
                            OR unaccent(LOWER(translate(q.short_description, E'\u00A0', ' '))) ILIKE '%' || LOWER(f_name_text) || '%'
                        )

                        UNION ALL

                        /* T questions */
                        SELECT
                            pq.id AS id,
                            't_' || pq.id AS key_question,
                            pq.id AS parent_id,
                            JSONB_AGG(
                                JSONB_BUILD_OBJECT(
                                    'key_question', CASE
                                        WHEN q.is_shared THEN CONCAT('s_', q.id, '_', q.share_id)
                                        ELSE CONCAT('s_', q.id)
                                    END,
                                    'id', q.id,
                                    'code', q.code,
                                    'course_id', q.course_id,
                                    'course', cq.name,
                                    'status', q.status,
                                    'teacher', CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name),
                                    'subtopic_id', q.subtopic_id,
                                    'date_status', q.date_status,
                                    'short_description', q.short_description,
                                    'type_question', 'S',
                                    'parent_id', q.parent_id,
                                    'number_question', q.number_question,
                                    'level_id', q.level_id,
                                    'level_question', q.level_question,
                                    'origin_question', q.question_origin
                                )
                            ) AS subquestions,
                            'T' AS type_question,
                            pq.code AS code,
                            pq.number_question AS number_question,
                            pq.short_description AS short_description,
                            pq.course_id,
                            c.name AS course,
                            NULL::BIGINT AS teacher_id,
                            NULL::INTEGER AS subtopic_id,
                            NULL::TEXT AS teacher,
                            pq.status status,
                            MIN(q.date_status) AS date_status,
                            '' AS observation,
                            pq.level_id::SMALLINT AS level_id,
                            CASE
                                WHEN l.name IS NOT NULL THEN l.name
                                ELSE l.description
                            END AS level_question,
                            opq.question_origin,
                            NULL::TEXT AS shared_status
                        FROM parent_question pq
                                                JOIN verified_p_questions_expanded q ON pq.status = ANY(status_array) AND pq.id = q.parent_id AND q.fl_status IS TRUE
                        LEFT JOIN course c ON pq.course_id = c.id
                                                LEFT JOIN course cq ON q.course_id = cq.id
                        LEFT JOIN level l ON l.id = pq.level_id
                        LEFT JOIN odiseo.v_all_parent_origins opq ON opq.parent_id = pq.id
                        LEFT JOIN employee_question eq ON eq.question_id = q.id AND eq.fl_status = true
                        LEFT JOIN employees e ON eq.teacher_id = e.id
                        WHERE 1 = 1
                                                    AND ( f_type IS NULL OR f_type = 'T' )
                          AND ( f_teacher_id IS NULL OR e.id = f_teacher_id )
                          AND ( f_level_id IS NULL OR q.level_id = f_level_id )
                          AND ( f_topics_id IS NULL OR q.topic_id = ANY(SELECT jsonb_array_elements_text(f_topics_id::jsonb)::int) )
                                                    AND ( f_course_id IS NULL OR q.course_id = f_course_id )
                          AND ( f_employee_id IS NULL OR q.course_id = ANY(f_array_courses) )
                          AND ( f_number_question IS NULL OR q.number_question ILIKE CONCAT('%', f_number_question, '%') )
                                                    AND ( f_university_id IS NULL OR opq.university_id = f_university_id OR q.university_id = f_university_id )
                                                    AND ( f_option_id IS NULL OR opq.option_id = f_option_id OR q.option_id = f_option_id )
                                                    AND ( f_modality_id IS NULL OR opq.modality_id = f_modality_id OR q.modality_id = f_modality_id )
                                                    AND ( f_version IS NULL OR opq."version" = f_version OR q."version" = f_version )
                                                    AND ( f_year IS NULL OR opq."year" = f_year OR q."year" = f_year )
                          AND ( f_number_question IS NULL OR (f_number_question IS NOT NULL AND (q.number_question ILIKE CONCAT('%', f_number_question,'%' ))) )
                        GROUP BY
                            pq.id,
                            c.id,
                            l.id,
                            opq.question_origin
                        HAVING 1 = 1
                           AND (
                                f_name_text IS NULL
                                OR f_name_text = ''
                                OR LOWER(pq.number_question) ILIKE '%' || LOWER(f_name_text) || '%'
                                OR LOWER(pq.code) ILIKE '%' || LOWER(f_name_text) || '%'
                                OR BOOL_OR(LOWER(q.number_question) ILIKE '%' || LOWER(f_name_text) || '%')
                                OR BOOL_OR(LOWER(q.code) ILIKE '%' || LOWER(f_name_text) || '%')
                           )
                    ),
                   counted_questions AS (
                        SELECT COUNT(*) AS total_count
                        FROM filtered_questions
                    )

                    SELECT
                        fq.id,
                        fq.key_question,
                        fq.parent_id,
                        fq.subquestions,
                        fq.type_question,
                        fq.code,
                        fq.number_question,
                        fq.short_description,
                        fq.course_id,
                        fq.course,
                        fq.teacher_id,
                        fq.subtopic_id,
                        fq.teacher,
                        fq.status,
                        fq.date_status,
                        fq.observation,
                        fq.level_id,
                        fq.level_question,
                        fq.question_origin AS origin_question,
                        fq.shared_status,
                        cq.total_count
                    FROM filtered_questions fq
                    CROSS JOIN counted_questions cq
                    ORDER BY
                        CASE
                            WHEN fq.status = 'VERI' THEN 1
                            WHEN fq.status = 'DIGI' THEN 2
                            ELSE 3
                        END,
                        CASE
                            WHEN fq.status = 'VERI' THEN fq.date_status
                        END,
                        CASE
                            WHEN fq.status = 'DIGI' THEN fq.date_status
                        END,
                        fq.id ASC;
                END;
                $$;


ALTER FUNCTION odiseo.fn_list_verified_question(f_name_text character varying, f_employee_id integer, f_course_id integer, f_teacher_id integer, f_type character varying, f_topics_id json, f_subtopics_id json, f_status json, f_cycle_id integer, f_week_id integer, f_type_material_id integer, f_level_id integer, f_number_question character varying, f_array_courses integer[], f_university_id smallint, f_option_id smallint, f_modality_id smallint, f_version smallint, f_year character varying) OWNER TO postgres;

--
-- Name: fn_list_verified_questions_co(integer, integer, character varying, integer, integer[], jsonb, jsonb, integer, character varying, json); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_list_verified_questions_co(p_perpage integer, p_npage integer, p_name_text character varying, f_teacher_id integer, f_course_id integer[], f_topics_id jsonb, f_subtopics_id jsonb, f_didi_id integer, f_type character varying, f_status json) RETURNS TABLE(id bigint, key_question text, type_question text, code character varying, parent_id bigint, short_description text, subquestions jsonb, course_id smallint, course character varying, status character varying, teacher_id bigint, teacher text, didi_id bigint, didi text, date_status timestamp without time zone, level_id bigint, subtopic_id bigint, shared_status text, total_count bigint)
    LANGUAGE plpgsql
    AS $$
            DECLARE
                offset_val INTEGER;
                v_cut_off_date INTEGER;
                status_array varchar[];
            BEGIN
                -- Obtener la fecha de corte
                SELECT ads.cut_off_date INTO v_cut_off_date
                FROM advanced_settings AS ads
                WHERE ads.fl_status = TRUE
                LIMIT 1;

                offset_val := p_perpage * (p_npage - 1);

                IF f_status IS NULL THEN
                    status_array := ARRAY['VERI','PEND','RESV','APRB'];
                ELSIF jsonb_typeof(f_status::jsonb) = 'array' AND jsonb_array_length(f_status::jsonb) = 0 THEN
                    status_array := ARRAY['VERI','PEND','RESV','APRB'];
                ELSIF jsonb_typeof(f_status::jsonb) = 'array' THEN
                    SELECT array_agg(value::text)
                    INTO status_array
                    FROM jsonb_array_elements_text(f_status::jsonb);
                ELSIF jsonb_typeof(f_status::jsonb) = 'string' THEN
                    status_array := ARRAY[f_status::text];
                ELSE
                    status_array := ARRAY['VERI','PEND','RESV','APRB'];
                END IF;

                RETURN QUERY
                WITH first_verified AS (
                    SELECT qs.question_id, MIN(qs.created_at) as first_verified_at
                    FROM question_status qs
                    WHERE qs.status = 'VERI'
                    GROUP BY qs.question_id
                ),
                all_verified_questions AS (
                    SELECT
                        vq.id,
                        vq.code,
                        vq.status,
                        vq.short_description,
                        vq.parent_id,
                        vq.course_id,
                        c.name as course,
                        fv.first_verified_at as status_date,
                        vq.level_id,
                        vq.topic_id
                    FROM question vq
                    LEFT JOIN course c ON vq.course_id = c.id
                    LEFT JOIN first_verified fv ON fv.question_id = vq.id
                    WHERE vq.fl_status = TRUE
                    AND vq.deleted_at IS NULL
                    AND vq.status = ANY(status_array)
                    AND (
                        f_type IS NULL OR
                        (f_type = 'T' AND vq.parent_id IS NOT NULL) OR
                        (f_type = 'P' AND vq.parent_id IS NULL)
                    )
                ),
                verified_p_questions_expanded AS (
                    SELECT
                        q.id,
                        q.code,
                        q.status,
                        q.short_description,
                        q.parent_id,
                        q.course_id,
                        c.name AS course,
                        q.status_date,
                        q.level_id,
                        q.topic_id,
                        NULL::BIGINT AS share_id,
                        qs.subtopic_id::bigint AS subtopic_id,
                        FALSE AS is_shared,
                        get_shared_status(q.id, qs.subtopic_id) AS shared_status
                    FROM all_verified_questions q
                    INNER JOIN question_subtopic qs ON qs.question_id = q.id AND qs.fl_status = TRUE
                    INNER JOIN course c ON q.course_id = c.id
                    WHERE (f_course_id IS NULL OR q.course_id = ANY(f_course_id))
                    AND (f_topics_id IS NULL OR q.topic_id IN (
                        SELECT jsonb_array_elements_text(f_topics_id)::int
                    ))
                    AND (
                        f_subtopics_id IS NULL
                        OR (
                            qs.subtopic_id IN (
                                SELECT jsonb_array_elements_text(f_subtopics_id)::int
                            )
                            AND qs.deleted_at IS NULL
                        )
                    )

                    UNION ALL

                    SELECT
                        q.id,
                        qs.code,
                        q.status,
                        q.short_description,
                        q.parent_id,
                        t.course_id,
                        c.name AS course,
                        q.status_date,
                        q.level_id,
                        qs.topic_id,
                        qs.id AS share_id,
                        qs.subtopic_id,
                        TRUE AS is_shared,
                        get_shared_status(q.id, qs.subtopic_id) AS shared_status
                    FROM all_verified_questions q
                    INNER JOIN question_shares qs ON qs.question_id = q.id AND qs.deleted_at IS NULL
                    INNER JOIN topic t ON t.id = qs.topic_id
                    INNER JOIN course c ON t.course_id = c.id
                    WHERE (f_course_id IS NULL OR t.course_id = ANY(f_course_id))
                    AND (f_topics_id IS NULL OR qs.topic_id IN (
                        SELECT jsonb_array_elements_text(f_topics_id)::int
                    ))
                    AND (
                        f_subtopics_id IS NULL
                        OR (
                            qs.subtopic_id IN (
                                SELECT jsonb_array_elements_text(f_subtopics_id)::int
                            )
                            AND qs.deleted_at IS NULL
                        )
                    )
                ),
                verified_s_subquestions AS (
                    SELECT
                        oq.parent_id,
                        JSONB_AGG(
                            JSONB_BUILD_OBJECT(
                                'id', oq.id,
                                'key_question', CASE
                                    WHEN oq.is_shared THEN CONCAT('s_', oq.id, '_', oq.share_id)
                                    ELSE CONCAT('s_', oq.id)
                                END,
                                'type_question', 'S',
                                'code', oq.code,
                                'parent_id', oq.parent_id,
                                'short_description', oq.short_description,
                                'course_id', oq.course_id,
                                'course', oq.course,
                                'status', oq.status,
                                'teacher_id', es1.id,
                                'teacher', CONCAT(es1.first_surname, ' ', es1.second_surname, ' ', es1.first_name),
                                'didi_id', es2.id,
                                'didi', CONCAT(es2.first_surname, ' ', es2.second_surname, ' ', es2.first_name),
                                'date_status', oq.status_date
                            )
                        ) AS subquestions
                    FROM verified_p_questions_expanded oq
                    LEFT JOIN employee_question eoq ON eoq.question_id = oq.id AND eoq.fl_status = TRUE
                    LEFT JOIN employees es1 ON eoq.teacher_id = es1.id
                    LEFT JOIN employee_didi_question edq ON edq.question_id = oq.id AND edq.fl_status = TRUE
                    LEFT JOIN employees es2 ON edq.employee_id = es2.id
                    WHERE oq.parent_id IS NOT NULL
                    AND (f_type IS NULL OR f_type = 'T')
                    AND (f_teacher_id IS NULL OR es1.id = f_teacher_id)
                    AND (f_didi_id IS NULL OR es2.id = f_didi_id)
                    AND (
                        p_name_text IS NULL
                        OR LOWER(oq.code) LIKE '%' || LOWER(p_name_text) || '%'
                        OR unaccent(LOWER(oq.short_description)) LIKE '%' || LOWER(p_name_text) || '%'
                    )
                    GROUP BY oq.parent_id
                ),
                tbl_questions AS (
                    SELECT
                        q.id,
                        CASE
                            WHEN q.is_shared THEN 'p_' || q.id || '_s_' || q.share_id
                            ELSE 'p_' || q.id
                        END AS key_question,
                        'P' AS type_question,
                        q.code,
                        q.parent_id,
                        q.short_description,
                        NULL AS subquestions,
                        q.course_id,
                        q.course,
                        q.status,
                        e1.id AS teacher_id,
                        CONCAT(e1.first_surname, ' ', e1.second_surname, ' ', e1.first_name) AS teacher,
                        e2.id AS didi_id,
                        CONCAT(e2.first_surname, ' ', e2.second_surname, ' ', e2.first_name) AS didi,
                        q.status_date AS date_status,
                        q.level_id,
                        q.subtopic_id,
                        q.shared_status
                    FROM verified_p_questions_expanded q
                    LEFT JOIN employee_question eq ON eq.question_id = q.id AND eq.fl_status = TRUE
                    LEFT JOIN employees e1 ON eq.teacher_id = e1.id
                    LEFT JOIN employee_didi_question edq ON edq.question_id = q.id AND edq.fl_status = TRUE
                    LEFT JOIN employees e2 ON edq.employee_id = e2.id
                    WHERE (f_type IS NULL OR f_type = 'P')
                    AND q.parent_id IS NULL
                    AND (f_teacher_id IS NULL OR e1.id = f_teacher_id)
                    AND (f_didi_id IS NULL OR e2.id = f_didi_id)
                    AND (
                        p_name_text IS NULL
                        OR LOWER(q.code) LIKE '%' || LOWER(p_name_text) || '%'
                        OR unaccent(LOWER(q.short_description)) LIKE '%' || LOWER(p_name_text) || '%'
                    )
                    UNION ALL
                    SELECT
                        pq.id,
                        't_' || pq.id AS key_question,
                        'T' AS type_question,
                        pq.code,
                        pq.id AS parent_id,
                        pq.short_description,
                        COALESCE(vq.subquestions, '[]'::jsonb),
                        pq.course_id,
                        c.name,
                        pq.status,
                        0::BIGINT,
                        '',
                        0::BIGINT,
                        '',
                        pq.created_at,
                        pq.level_id,
                        NULL::BIGINT AS subtopic_id,
                        NULL::TEXT AS shared_status
                    FROM parent_question pq
                    INNER JOIN verified_s_subquestions vq ON vq.parent_id = pq.id
                    INNER JOIN course c ON pq.course_id = c.id
                    WHERE 1 = 1
                    AND EXISTS (
                        SELECT 1 FROM verified_p_questions_expanded avq
                        WHERE avq.parent_id = pq.id
                    )
                ),
                counted_questions AS (
                    SELECT *, count(*) OVER () AS total_count
                    FROM tbl_questions
                )
                SELECT *
                FROM counted_questions
                ORDER BY date_status DESC NULLS LAST
                LIMIT p_perpage
                OFFSET offset_val;
            END;
            $$;


ALTER FUNCTION odiseo.fn_list_verified_questions_co(p_perpage integer, p_npage integer, p_name_text character varying, f_teacher_id integer, f_course_id integer[], f_topics_id jsonb, f_subtopics_id jsonb, f_didi_id integer, f_type character varying, f_status json) OWNER TO postgres;

--
-- Name: fn_list_verified_questions_teacher(integer, integer, character varying, integer, integer[], integer, character varying, character varying[]); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_list_verified_questions_teacher(p_perpage integer, p_npage integer, p_name_text character varying, p_teacher_id integer, p_course_id integer[], p_didi_id integer, p_type character varying, p_status character varying[]) RETURNS TABLE(id bigint, key_question text, type_question text, code character varying, parent_id bigint, short_description text, subquestions jsonb, course_id smallint, course character varying, subtopic_id integer, status character varying, teacher_id bigint, teacher text, didi_id bigint, didi text, date_status timestamp without time zone, shared_status text, total_count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    offset_val     integer;
    v_cut_off_date integer;
BEGIN
    SELECT ads.cut_off_date INTO v_cut_off_date
    FROM advanced_settings AS ads
    WHERE ads.fl_status = TRUE
    LIMIT 1;

    offset_val := p_perpage * (p_npage - 1);

    RETURN QUERY
    WITH date_range AS (
        SELECT
            CURRENT_TIMESTAMP - INTERVAL '30 days' AS start_date,
            CURRENT_TIMESTAMP                       AS end_date
    ),
    first_verified_date AS (
        SELECT
            qss.question_id,
            MIN(qss.created_at) AS created_at
        FROM question_status qss
        WHERE qss.status = 'VERI'
        GROUP BY qss.question_id
    ),
    latest_statuses AS (
        SELECT *
        FROM first_verified_date fvd
        WHERE fvd.created_at >= (SELECT start_date FROM date_range)
    ),
    all_verified_questions AS (
        -- Preguntas propias
        SELECT
            vq.id,
            vq.code,
            vq.status,
            vq.short_description,
            vq.parent_id,
            vq.course_id,
            qst.subtopic_id,
            c.name        AS course,
            ls.created_at AS status_date,
            NULL::bigint  AS share_id,
            FALSE         AS is_shared,
            get_shared_status(vq.id, qst.subtopic_id) AS shared_status
        FROM question vq
        LEFT JOIN course c           ON c.id  = vq.course_id
        LEFT JOIN question_subtopic qst ON qst.question_id = vq.id
                                      AND qst.deleted_at IS NULL
        JOIN  latest_statuses ls     ON ls.question_id = vq.id
        WHERE vq.fl_status   = TRUE
          AND vq.deleted_at  IS NULL
          AND (
              (p_status IS NULL AND vq.status IN ('VERI', 'PEND', 'RESV', 'APRB'))
              OR vq.status = ANY(p_status)
          )
          AND (
              p_type IS NULL
              OR (p_type = 'T' AND vq.parent_id IS NOT NULL)
              OR (p_type = 'P' AND vq.parent_id IS NULL)
          )
          AND (p_course_id IS NULL OR vq.course_id = ANY(p_course_id))

        UNION ALL

        -- Preguntas compartidas (question_shares)
        SELECT
            vq.id,
            qs.code,
            vq.status,
            vq.short_description,
            vq.parent_id,
            t.course_id,
            qs.subtopic_id,
            c.name        AS course,
            ls.created_at AS status_date,
            qs.id         AS share_id,
            TRUE          AS is_shared,
            get_shared_status(vq.id, qs.subtopic_id) AS shared_status
        FROM question vq
        JOIN  question_shares qs ON qs.question_id = vq.id
                                AND qs.deleted_at IS NULL
        JOIN  topic t            ON t.id = qs.topic_id
        LEFT JOIN course c       ON c.id = t.course_id
        JOIN  latest_statuses ls ON ls.question_id = vq.id
        WHERE vq.fl_status  = TRUE
          AND vq.deleted_at IS NULL
          AND (
              (p_status IS NULL AND vq.status IN ('VERI', 'PEND', 'RESV', 'APRB'))
              OR vq.status = ANY(p_status)
          )
          AND (
              p_type IS NULL
              OR (p_type = 'T' AND vq.parent_id IS NOT NULL)
              OR (p_type = 'P' AND vq.parent_id IS NULL)
          )
          AND (p_course_id IS NULL OR t.course_id = ANY(p_course_id))
    ),
    verified_s_subquestions AS (
        SELECT
            oq.parent_id,
            JSONB_AGG(
                JSONB_BUILD_OBJECT(
                    'id',                oq.id,
                    'key_question',      CASE
                                             WHEN oq.is_shared THEN 's_' || oq.id || '_' || oq.share_id
                                             ELSE 's_' || oq.id
                                         END,
                    'type_question',     'S',
                    'code',              oq.code,
                    'parent_id',         oq.parent_id,
                    'short_description', oq.short_description,
                    'course_id',         oq.course_id,
                    'course',            oq.course,
                    'subtopic_id',       oq.subtopic_id,
                    'status',            oq.status,
                    'teacher_id',        es1.id,
                    'teacher',           CONCAT(es1.first_surname, ' ', es1.second_surname, ' ', es1.first_name),
                    'didi_id',           es2.id,
                    'didi',              CONCAT(es2.first_surname, ' ', es2.second_surname, ' ', es2.first_name),
                    'date_status',       oq.status_date
                )
            ) AS subquestions
        FROM all_verified_questions oq
        LEFT JOIN employee_question      eoq ON eoq.question_id = oq.id AND eoq.fl_status = TRUE
        LEFT JOIN employees              es1 ON es1.id = eoq.teacher_id
        LEFT JOIN employee_didi_question edq ON edq.question_id = oq.id AND edq.fl_status = TRUE
        LEFT JOIN employees              es2 ON es2.id = edq.employee_id
        WHERE oq.parent_id IS NOT NULL
          AND (p_type IS NULL OR p_type = 'T')
          AND (p_teacher_id IS NULL OR es1.id = p_teacher_id)
          AND (p_didi_id    IS NULL OR es2.id = p_didi_id)
          AND (
              p_name_text IS NULL
              OR LOWER(oq.code)              LIKE '%' || LOWER(p_name_text) || '%'
              OR unaccent(LOWER(oq.short_description)) LIKE '%' || LOWER(p_name_text) || '%'
              OR EXISTS (
                  SELECT 1
                  FROM parent_question pp
                  WHERE pp.id = oq.parent_id
                    AND LOWER(pp.code) LIKE '%' || LOWER(p_name_text) || '%'
              )
          )
        GROUP BY oq.parent_id
    ),
    tbl_questions AS (
        -- Preguntas tipo P
        SELECT
            q.id,
            CASE
                WHEN q.is_shared THEN 'f_' || q.id || '_s_' || q.share_id
                ELSE 'p_' || q.id
            END                                                                   AS key_question,
            'P'                                                                   AS type_question,
            q.code,
            q.parent_id,
            q.short_description,
            NULL::jsonb                                                           AS subquestions,
            q.course_id,
            q.course,
            q.subtopic_id,
            q.status,
            e1.id                                                                 AS teacher_id,
            CONCAT(e1.first_surname, ' ', e1.second_surname, ' ', e1.first_name)  AS teacher,
            e2.id                                                                 AS didi_id,
            CONCAT(e2.first_surname, ' ', e2.second_surname, ' ', e2.first_name)  AS didi,
            q.status_date                                                         AS date_status,
            q.shared_status                                                       AS shared_status
        FROM all_verified_questions q
        LEFT JOIN employee_question      eq  ON eq.question_id  = q.id AND eq.fl_status  = TRUE
        LEFT JOIN employees              e1  ON e1.id = eq.teacher_id
        LEFT JOIN employee_didi_question edq ON edq.question_id = q.id AND edq.fl_status = TRUE
        LEFT JOIN employees              e2  ON e2.id = edq.employee_id
        WHERE (p_type IS NULL OR p_type = 'P')
          AND q.parent_id IS NULL
          AND (p_teacher_id IS NULL OR e1.id = p_teacher_id)
          AND (p_didi_id    IS NULL OR e2.id = p_didi_id)
          AND (
              p_name_text IS NULL
              OR LOWER(q.code)              LIKE '%' || LOWER(p_name_text) || '%'
              OR unaccent(LOWER(q.short_description)) LIKE '%' || LOWER(p_name_text) || '%'
          )

        UNION ALL

        -- Preguntas tipo T (compuestas)
        SELECT
            pq.id,
            't_' || pq.id AS key_question,
            'T'           AS type_question,
            pq.code,
            pq.id         AS parent_id,
            pq.short_description,
            COALESCE(vq.subquestions, '[]'::jsonb),
            pq.course_id,
            c.name,
            NULL::integer AS subtopic_id,
            pq.status,
            0::bigint,
            '',
            0::bigint,
            '',
            pq.created_at,
            NULL::text    AS shared_status
        FROM parent_question pq
        INNER JOIN verified_s_subquestions vq ON vq.parent_id = pq.id
                                              AND pq.status IN ('VERI', 'PEND', 'RESV', 'APRB')
        INNER JOIN course c                   ON c.id = pq.course_id
        WHERE (
            (p_status IS NOT NULL AND pq.status = ANY(p_status))
            OR (p_status IS NULL  AND pq.status IN ('VERI', 'PEND', 'RESV', 'APRB'))
        )
          AND EXISTS (
              SELECT 1
              FROM all_verified_questions avq
              WHERE avq.parent_id = pq.id
          )
    ),
    counted_questions AS (
        SELECT
            *,
            count(*) OVER () AS total_count
        FROM tbl_questions
    )
    SELECT *
    FROM counted_questions
    ORDER BY date_status DESC
    LIMIT p_perpage
    OFFSET offset_val;

END;
$$;


ALTER FUNCTION odiseo.fn_list_verified_questions_teacher(p_perpage integer, p_npage integer, p_name_text character varying, p_teacher_id integer, p_course_id integer[], p_didi_id integer, p_type character varying, p_status character varying[]) OWNER TO postgres;

--
-- Name: fn_material(integer, integer, smallint, smallint, bigint, boolean, smallint, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_material(p_perpage integer, p_npage integer, p_university_id smallint, p_headquarters_id smallint, p_cycle_id bigint, p_cycle_active boolean, p_classroom_id smallint, p_company_id integer) RETURNS TABLE(id bigint, cycle_id bigint, code_cycle character varying, cycle character varying, university_id smallint, university character varying, headquarte_id smallint, code_headquarters character varying, headquarters character varying, headquarters_classroom_id smallint, classroom_id smallint, code_classroom character varying, classroom character varying, start_date date, created_at timestamp without time zone, company_id bigint, total bigint, has_inconsistencies text, last_update timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
            DECLARE
                offset_val INTEGER;
            BEGIN
                offset_val := p_perpage * (p_npage - 1);

                RETURN QUERY
                WITH base_materials AS (
                    SELECT
                        m.id,
                        m.cycle_id,
                        c.code AS code_cycle,
                        c.description AS cycle,
                        m.university_id,
                        u.name AS university,
                        m.headquarte_id,
                        h.code AS code_headquarters,
                        h.name AS headquarters,
                        m.headquarters_classroom_id,
                        cl.id AS classroom_id,
                        cl.code AS code_classroom,
                        cl.number AS classroom,
                        c.start_date,
                        m.created_at,
                        co.id AS company_id,
                        COUNT(*) OVER () AS total
                    FROM material m
                    INNER JOIN cycle c ON m.cycle_id = c.id
                    INNER JOIN origin_university u ON m.university_id = u.id
                    INNER JOIN headquarters h ON m.headquarte_id = h.id
                    INNER JOIN headquarters_classroom hc ON m.headquarters_classroom_id = hc.id
                    INNER JOIN classroom cl ON hc.classroom_id = cl.id
                    INNER JOIN companies co ON co.id = m.company_id 
                    WHERE 1 = 1
                    AND m.fl_status = true
                    AND (p_company_id IS NULL OR m.company_id = p_company_id)
                    AND (p_university_id IS NULL OR m.university_id = p_university_id)
                    AND (p_headquarters_id IS NULL OR m.headquarte_id = p_headquarters_id)
                    AND (p_classroom_id IS NULL OR cl.id = p_classroom_id)
                    AND (p_cycle_id IS NULL OR m.cycle_id = p_cycle_id)
                    AND (p_cycle_active IS NULL OR c.active = p_cycle_active)
                    ORDER BY m.created_at DESC, m.university_id ASC, c.start_date ASC, m.headquarte_id ASC, m.headquarters_classroom_id ASC
                    LIMIT p_perpage 
                    OFFSET offset_val
                )
                SELECT 
                    bm.id,
                    bm.cycle_id,
                    bm.code_cycle,
                    bm.cycle,
                    bm.university_id,
                    bm.university,
                    bm.headquarte_id,
                    bm.code_headquarters,
                    bm.headquarters,
                    bm.headquarters_classroom_id,
                    bm.classroom_id,
                    bm.code_classroom,
                    bm.classroom,
                    bm.start_date,
                    bm.created_at,
                    bm.company_id,
                    bm.total,
                    CASE 
                        WHEN val.mat_status = 'with-observations' OR val.exam_status = 'with-observations' THEN 'with-observations'
                        WHEN val.mat_status = 'without-observations' OR val.exam_status = 'without-observations' THEN 'without-observations'
                        ELSE 'without-type-material'
                    END AS has_inconsistencies,
                    now() AS last_update
                    FROM base_materials bm
                    CROSS JOIN LATERAL (
                        SELECT 
                            fn_get_material_inconsistency_status(bm.headquarte_id, bm.cycle_id, bm.university_id, bm.company_id) AS mat_status,
                            fn_get_exam_inconsistency_status(bm.cycle_id, bm.university_id, bm.company_id) AS exam_status
                    ) val
                ORDER BY bm.created_at DESC, bm.university_id ASC, bm.start_date ASC, bm.headquarte_id ASC, bm.headquarters_classroom_id ASC;

            END;
            $$;


ALTER FUNCTION odiseo.fn_material(p_perpage integer, p_npage integer, p_university_id smallint, p_headquarters_id smallint, p_cycle_id bigint, p_cycle_active boolean, p_classroom_id smallint, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_material_amount_level_exam(bigint, smallint, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_material_amount_level_exam(p_material_id bigint, p_type_material_id smallint, p_courses jsonb) RETURNS TABLE(id smallint, type_material_id bigint, exam_area_id bigint, exam_area character varying, amount_type_mat integer, level_id bigint, level_description character varying, level_name character varying, course_id bigint, code_course character varying, course character varying, amount_type_d integer)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_cycle_id BIGINT;
            v_university_id SMALLINT;
            v_exam_area_id SMALLINT;
            v_exam_areas SMALLINT[] := ARRAY[]::SMALLINT[];
        BEGIN
            -- Obtener ciclo y universidad del material mandado
            SELECT m.cycle_id, m.university_id INTO v_cycle_id, v_university_id FROM material m WHERE m.id = p_material_id LIMIT 1;

            -- Obtener areas del tipo material
            FOR v_exam_area_id IN
                SELECT tma.area_id FROM type_material_area tma WHERE tma.type_material_id = p_type_material_id AND tma.fl_status = true
            LOOP
                v_exam_areas := array_append(v_exam_areas, v_exam_area_id);
            END LOOP;


            RETURN QUERY
            SELECT
                cacl.id,
                emc.type_material_id,
                cac.exam_area_id,
                ea.description AS exam_area,
                cacl.amount_question AS amount_type_mat,
                cacl.level_id,
                l.description AS level_description,
                l.name AS level_name,
                cac.course_id,
                c.code AS code_course,
                c.name AS course,
                cac.amount_type_d
            FROM exam_material_config_area_course_levels cacl
            INNER JOIN exam_material_config_area_courses cac ON cacl.exam_material_config_area_course_id = cac.id AND cac.fl_status = true
            INNER JOIN exam_material_configurations emc ON cac.exam_material_config_id = emc.id AND emc.fl_status = true
            INNER JOIN course c ON cac.course_id = c.id
            INNER JOIN level l ON cacl.level_id = l.id
            INNER JOIN exam_area ea ON cac.exam_area_id = ea.id
            WHERE emc.type_material_id = p_type_material_id
            AND cacl.fl_status = true
            AND emc.cycle_id = v_cycle_id
            AND cac.course_id IN (SELECT jsonb_array_elements_text(p_courses)::BIGINT)
            AND cac.exam_area_id = ANY(v_exam_areas)
            ORDER BY cac.exam_area_id ASC, cac.course_id ASC, cacl.level_id ASC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_material_amount_level_exam(p_material_id bigint, p_type_material_id smallint, p_courses jsonb) OWNER TO postgres;

--
-- Name: fn_material_amount_question_level_week(bigint, smallint, smallint, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_material_amount_question_level_week(p_material_id bigint, p_type_material_id smallint, p_week smallint, p_courses jsonb) RETURNS TABLE(num bigint, type_material_id bigint, amount_type_mat integer, level_id bigint, level_description character varying, level_name character varying, type_question character varying, week smallint, headquarter_id bigint, course_id bigint, code_course character varying, course character varying)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_cycle_id BIGINT;
            v_university_id SMALLINT;
            v_headquarte_id BIGINT;
        BEGIN
            -- Obtener ciclo y universidad del material mandado
            SELECT m.cycle_id, m.university_id, m.headquarte_id INTO v_cycle_id, v_university_id, v_headquarte_id FROM odiseo.material m WHERE m.id = p_material_id LIMIT 1;

            RETURN QUERY
            SELECT
                ROW_NUMBER() OVER (PARTITION BY subquery.amount_type_mat) AS num,
                subquery.type_material_id,
                subquery.amount_type_mat,
                subquery.level_id,
                subquery.level_description,
                subquery.level_name,
                subquery.type_question,
                subquery.week,
                subquery.headquarter_id,
                subquery.course_id,
                subquery.code_course,
                subquery.course
            FROM (
                SELECT
                    dlsw.type_material_id,
                    dlsw.number_questions AS amount_type_mat,
                    dlsw.level_id,
                    l.description AS level_description,
                    l.name AS level_name,
                    dlsw.type_question,
                    lsw.week,
                    ls.headquarter_id,
                    ls.course_id,
                    c.code AS code_course,
                    c.name AS course
                FROM odiseo.detail_level_syllabus_weeks dlsw
                INNER JOIN odiseo.level_syllabus_weeks lsw
                    ON dlsw.level_syllabus_weeks_id = lsw.id AND lsw.fl_status = true
                INNER JOIN odiseo.level_syllabus ls
                    ON lsw.level_syllabus_id = ls.id
                INNER JOIN odiseo.course c
                    ON ls.course_id = c.id
                INNER JOIN odiseo.level l
                    ON dlsw.level_id = l.id
                WHERE dlsw.fl_status = true
                    AND ls.fl_status = true
                    AND dlsw.type_material_id = p_type_material_id
                    AND ls.headquarter_id = v_headquarte_id
                    AND ls.cycle_id = v_cycle_id
                    AND ls.university_id = v_university_id
                    AND ls.course_id IN (SELECT jsonb_array_elements_text(p_courses)::smallint)
                    AND lsw.week = p_week
                    AND dlsw.number_questions > 0
                    AND dlsw.number_questions = 1 -- Solo las filas originales con number_questions = 1
                UNION ALL
                SELECT
                    dlsw.type_material_id,
                    1 AS amount_type_mat, -- Replicamos cada fila con un amount_type_mat de 1
                    dlsw.level_id,
                    l.description AS level_description,
                    l.name AS level_name,
                    dlsw.type_question,
                    lsw.week,
                    ls.headquarter_id,
                    ls.course_id,
                    c.code AS code_course,
                    c.name AS course
                FROM odiseo.detail_level_syllabus_weeks dlsw
                INNER JOIN odiseo.level_syllabus_weeks lsw
                    ON dlsw.level_syllabus_weeks_id = lsw.id AND lsw.fl_status = true
                INNER JOIN odiseo.level_syllabus ls
                    ON lsw.level_syllabus_id = ls.id
                INNER JOIN odiseo.course c
                    ON ls.course_id = c.id
                INNER JOIN odiseo.level l
                    ON dlsw.level_id = l.id
                CROSS JOIN generate_series(0, dlsw.number_questions - 1) AS gs -- Generamos series para replicar filas
                WHERE dlsw.fl_status = true
                    AND ls.fl_status = true
                    AND dlsw.type_material_id = p_type_material_id
                    AND ls.headquarter_id = v_headquarte_id
                    AND ls.cycle_id = v_cycle_id
                    AND ls.university_id = v_university_id
                    AND ls.course_id IN (SELECT jsonb_array_elements_text(p_courses)::smallint)
                    AND lsw.week = p_week
                    AND dlsw.number_questions > 1 -- Solo replicamos filas con number_questions > 1
            ) AS subquery
            ORDER BY subquery.course_id ASC, subquery.level_id ASC, subquery.type_question ASC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_material_amount_question_level_week(p_material_id bigint, p_type_material_id smallint, p_week smallint, p_courses jsonb) OWNER TO postgres;

--
-- Name: fn_material_amount_question_level_week_v2(bigint, smallint, smallint, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_material_amount_question_level_week_v2(p_material_id bigint, p_type_material_id smallint, p_week smallint, p_courses jsonb) RETURNS TABLE(type_material_id bigint, amount_type_mat integer, level_id bigint, level_description character varying, level_name character varying, type_question character varying, week smallint, headquarter_id bigint, course_id bigint, code_course character varying, course character varying)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_cycle_id BIGINT;
            v_university_id SMALLINT;
            v_headquarte_id BIGINT;
        BEGIN
            -- Obtener ciclo y universidad del material mandado
            SELECT m.cycle_id, m.university_id, m.headquarte_id INTO v_cycle_id, v_university_id, v_headquarte_id FROM odiseo.material m WHERE m.id = p_material_id LIMIT 1;

            RETURN QUERY
            SELECT
                dlsw.type_material_id,
                dlsw.number_questions AS amount_type_mat,
                dlsw.level_id,
                l.description AS level_description,
                l.name AS level_name,
                dlsw.type_question,
                lsw.week,
                ls.headquarter_id,
                ls.course_id,
                c.code AS code_course,
                c.name AS course
            FROM odiseo.detail_level_syllabus_weeks dlsw
            INNER JOIN odiseo.level_syllabus_weeks lsw
                ON dlsw.level_syllabus_weeks_id = lsw.id AND lsw.fl_status = true
            INNER JOIN odiseo.level_syllabus ls
                ON lsw.level_syllabus_id = ls.id
            INNER JOIN odiseo.course c
                ON ls.course_id = c.id
            INNER JOIN odiseo.level l
                ON dlsw.level_id = l.id
            WHERE dlsw.fl_status = true
                AND ls.fl_status = true
                AND dlsw.type_material_id = p_type_material_id
                AND ls.headquarter_id = v_headquarte_id
                AND ls.cycle_id = v_cycle_id
                AND ls.university_id = v_university_id
                AND ls.course_id IN (SELECT jsonb_array_elements_text(p_courses)::smallint)
                AND lsw.week = p_week
            ORDER BY ls.course_id ASC, dlsw.level_id ASC, dlsw.type_question ASC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_material_amount_question_level_week_v2(p_material_id bigint, p_type_material_id smallint, p_week smallint, p_courses jsonb) OWNER TO postgres;

--
-- Name: fn_material_amount_question_subtopic_examen_v2(bigint, jsonb, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_material_amount_question_subtopic_examen_v2(p_material_id bigint, p_weeks jsonb, p_courses jsonb) RETURNS TABLE(course_id bigint, code_course character varying, course character varying, topic_id smallint, code_topic character varying, topic character varying, subtopic_id smallint, code_subtopic character varying, subtopic character varying, week smallint, frequent_subtopic boolean, type_week_id bigint, type_week character varying)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
			WITH tbl_material AS (
                SELECT
                    m.cycle_id,
                    m.university_id,
                    m.headquarte_id
                FROM material m
                WHERE m.id = p_material_id
            ), tbl_subtopics AS (
				SELECT DISTINCT ON (ds.subtopic_id)
	                s.course_id,
	                co.code AS code_course,
	                co.name AS course,
	                st.topic_id,
	                top.code AS code_topic,
	                top.name AS topic,
	                ds.subtopic_id,
	                su.code AS code_subtopic,
	                su.name AS subtopic,
	                tw.week,
                    COALESCE(fus.is_frequent, false) AS frequent_subtopic,
					cw.type_week_id,
					twe.description AS type_week
	            FROM syllabus_subtopic_type_material stm
	            INNER JOIN syllabus_detail_subtopic ds ON stm.syllabus_detail_subtopic_id = ds.id AND ds.fl_status = true
	            INNER JOIN syllabus_topic_week tw ON ds.syllabus_topic_week_id = tw.id AND tw.fl_status = true
	            INNER JOIN syllabus_topic st ON tw.syllabus_topic_id = st.id AND st.fl_status = true
	            INNER JOIN syllabus s ON st.syllabus_id = s.id
	            INNER JOIN course co ON s.course_id = co.id
	            INNER JOIN topic top ON st.topic_id = top.id
	            INNER JOIN subtopic su ON ds.subtopic_id = su.id
                LEFT JOIN frequent_university_subtopic fus ON ds.subtopic_id = fus.subtopic_id
                    AND fus.is_frequent = true
                    AND fus.university_id IN (SELECT tm.university_id FROM tbl_material tm)
                    AND fus.fl_status = true
				LEFT JOIN cycle_weeks cw ON s.cycle_id = cw.cycle_id AND tw.week = cw.week AND cw.fl_status IS TRUE
				LEFT JOIN type_week twe ON cw.type_week_id = twe.id
	            WHERE s.cycle_id IN (SELECT tm.cycle_id FROM tbl_material tm)
		            AND stm.fl_status = true
		            AND s.university_id IN (SELECT tm.university_id FROM tbl_material tm)
		            AND s.course_id IN (SELECT jsonb_array_elements_text(p_courses)::SMALLINT)
		            AND (
	                    p_weeks IS NULL
	                    OR p_weeks = '[]'
	                    OR tw.week IN (SELECT jsonb_array_elements_text(p_weeks)::SMALLINT)
	                )
	            ORDER BY ds.subtopic_id ASC, tw.week DESC
			)
			SELECT * FROM tbl_subtopics
			ORDER BY course_id ASC, topic_id ASC, subtopic_id ASC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_material_amount_question_subtopic_examen_v2(p_material_id bigint, p_weeks jsonb, p_courses jsonb) OWNER TO postgres;

--
-- Name: fn_material_amount_question_subtopic_week(bigint, smallint, smallint, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_material_amount_question_subtopic_week(p_material_id bigint, p_type_material_id smallint, p_week smallint, p_courses jsonb) RETURNS TABLE(id bigint, type_material_id smallint, amount_type_mat smallint, subtopic_id smallint, code_subtopic character varying, subtopic character varying, week smallint, topic_id smallint, code_topic character varying, topic character varying, course_id bigint, code_course character varying, course character varying, syllabus_id bigint)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_cycle_id BIGINT;
            v_university_id SMALLINT;
        BEGIN
            -- Obtener ciclo y universidad del material mandado
            SELECT m.cycle_id, m.university_id INTO v_cycle_id, v_university_id FROM material m WHERE m.id = p_material_id LIMIT 1;

            RETURN QUERY
            SELECT
	            stm.id,
                stm.type_material_id,
                stm.questions_amount AS amount_type_mat,
                sds.subtopic_id,
                su.code AS code_subtopic,
                su.name AS subtopic,
                stw.week,
                st.topic_id,
                top.code AS code_topic,
                top.name AS topic,
                s.course_id,
                co.code AS code_course,
                co.name AS course,
                s.id AS syllabus_id
            FROM syllabus_subtopic_type_material stm
            INNER JOIN syllabus_detail_subtopic sds ON stm.syllabus_detail_subtopic_id = sds.id AND sds.fl_status = true
            INNER JOIN syllabus_topic_week stw ON sds.syllabus_topic_week_id = stw.id AND stw.fl_status = true
            INNER JOIN syllabus_topic st ON stw.syllabus_topic_id = st.id AND st.fl_status = true
            INNER JOIN syllabus s ON st.syllabus_id = s.id
            INNER JOIN course co ON s.course_id = co.id
            INNER JOIN topic top ON st.topic_id = top.id
            INNER JOIN subtopic su ON sds.subtopic_id = su.id
            WHERE stm.fl_status = true
            AND s.fl_status = true
            AND s.course_id IN (SELECT jsonb_array_elements_text(p_courses)::BIGINT)
            AND stm.type_material_id = p_type_material_id
            AND s.university_id = v_university_id
            AND s.cycle_id = v_cycle_id
            AND stw.week = p_week
            AND stm.questions_amount > 0
            ORDER BY s.course_id ASC, st.topic_id ASC, sds.subtopic_id ASC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_material_amount_question_subtopic_week(p_material_id bigint, p_type_material_id smallint, p_week smallint, p_courses jsonb) OWNER TO postgres;

--
-- Name: fn_material_ballot_question(bigint, smallint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_material_ballot_question(p_material_id bigint, p_week smallint, p_type_material_id smallint, p_week_type_material_id bigint) RETURNS TABLE(id bigint, material_id bigint, week smallint, type_material_id smallint, week_type_material_id bigint, course_id smallint, code_course character varying, course character varying, "position" smallint, position_initial smallint, subtopic_id smallint, code_subtopic character varying, subtopic character varying, topic_id smallint, code_topic character varying, topic character varying, level_id bigint, level_description character varying, level_name character varying, usage_level_id bigint, question_id bigint, type character varying, usage_status boolean)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            SELECT
                mbq.id,
                mbq.material_id,
                mbq.week,
                mbq.type_material_id,
                mbq.week_type_material_id,
                mbq.course_id,
                c.code AS course_code,
                c.name AS course,
                mbq.position,
                mbq.position_initial,
                mbq.subtopic_id,
                st.code AS subtopic_code,
                st.name AS subtopic,
                mbq.topic_id,
                t.code AS topic_code,
                t.name AS topic,
                mbq.level_id,
                l.description AS level_description,
                l.name AS level_name,
                mbq.usage_level_id,
                mbq.question_id,
                mbq.type,
                mbq.usage_status
            FROM odiseo.material_ballot_question AS mbq
            INNER JOIN odiseo.course AS c ON mbq.course_id = c.id
            LEFT JOIN odiseo.topic AS t ON mbq.topic_id = t.id
            LEFT JOIN odiseo.subtopic AS st ON mbq.subtopic_id = st.id
            LEFT JOIN odiseo.level AS l ON mbq.level_id = l.id
            WHERE
                mbq.material_id = p_material_id
                AND mbq.week = p_week
                AND mbq.type_material_id = p_type_material_id
                AND mbq.week_type_material_id = p_week_type_material_id
                AND mbq.fl_status = true
            ORDER BY mbq.course_id ASC, mbq.position ASC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_material_ballot_question(p_material_id bigint, p_week smallint, p_type_material_id smallint, p_week_type_material_id bigint) OWNER TO postgres;

--
-- Name: fn_material_class_week(bigint, bigint, jsonb, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_material_class_week(p_material_id bigint, p_type_material_id bigint, p_detail_week_type_mat jsonb, p_week smallint) RETURNS TABLE(id bigint, material_id bigint, type_material_id smallint, type_material character varying, week_type_material_ids character varying, week smallint, course_id smallint, code_course character varying, name_course character varying, fl_process_status smallint, url_material_class character varying, job_id character varying)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_detail_week_type_mat_id BIGINT[];
        BEGIN
            -- v_detail_week_type_mat_id := ARRAY(SELECT jsonb_array_elements_text(p_detail_week_type_mat)::BIGINT);

            SELECT ARRAY(
                SELECT jsonb_array_elements_text(p_detail_week_type_mat)::BIGINT
            ) INTO v_detail_week_type_mat_id;

            RETURN QUERY
            SELECT
                mcw.id,
                mcw.material_id,
                mcw.type_material_id,
                tm.description as type_material,
                mcw.week_type_material_ids,
                mcw.week,
                mcw.course_id,
                c.code AS code_course,
                c.name AS name_course,
                mcw.fl_process_status,
                mcw.url_material_class,
                mcw.job_id
            FROM odiseo.material_class_week mcw
            INNER JOIN odiseo.course c ON mcw.course_id = c.id
            INNER JOIN odiseo.type_material tm ON mcw.type_material_id = tm.id
            WHERE mcw.material_id = p_material_id
            AND mcw.type_material_id = p_type_material_id
            AND mcw.week = p_week
            -- AND mcw.week_type_material_ids = v_detail_week_type_mat_id::VARCHAR
            AND mcw.fl_status = true;
        END;
        $$;


ALTER FUNCTION odiseo.fn_material_class_week(p_material_id bigint, p_type_material_id bigint, p_detail_week_type_mat jsonb, p_week smallint) OWNER TO postgres;

--
-- Name: fn_material_detail_generation(integer, integer, smallint, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_material_detail_generation(p_material_id integer, p_type_material_id integer, p_week smallint, p_cycle integer) RETURNS TABLE(solution boolean, quality boolean, material_progress integer, is_material_class boolean, process_status smallint, url character varying, type_material_id integer, solution_type_name text, week smallint, quality_type_name text, children_type_material_ids json, questions_are_completed boolean, config_level boolean, config_type boolean, lower_limit smallint, upper_limit smallint, total_processing bigint, lock_status boolean, locked_by_id bigint, locked_at timestamp without time zone, has_distribution boolean, locked_by_name text)
    LANGUAGE plpgsql
    AS $$
                BEGIN
--					DROP TABLE IF EXISTS material_variants;
--					
--                  CREATE TEMPORARY TABLE material_variants (
--                        solution BOOLEAN,
--                        quality BOOLEAN
--                  );
--            
--                  INSERT INTO material_variants (solution, quality)
--                  VALUES
--                        (TRUE, FALSE),
--                        (TRUE, TRUE),
--                        (FALSE, TRUE),
--                        (FALSE, FALSE);
                        
                    RETURN QUERY
                    
                    WITH material_variants AS (
                        SELECT *
						FROM (
						    VALUES
						        (TRUE, FALSE),
						        (TRUE, TRUE),
						        (FALSE, TRUE),
						        (FALSE, FALSE)
						) AS material_variants(solution, quality)
					),
                    type_materials_ids	AS (
                        SELECT
                            tm.id single_id,
                            tpm.id children_id
                        FROM type_material_template tmt
                        JOIN type_material tm ON tm.type_material_template_id = tmt.id
                        LEFT JOIN cycle c ON c.id = p_cycle
                        LEFT JOIN cycle_templates cs ON cs.id = c.cycle_template_id
                        LEFT JOIN type_material_bound tmb ON tmb.type_material_template_id = tmt.id AND tmb.deleted_at IS NULL
                        LEFT JOIN type_material tpm ON tpm.type_material_template_id = tmb.type_material_template_extra_id AND tpm.fl_status IS TRUE AND cs.id = tpm.id_cycle_template
                        WHERE tm.id = p_type_material_id
                    ), material_class AS (
                        SELECT
                            CASE WHEN COUNT(*) > 1 THEN 'children_material' ELSE 'single_type_material' END AS type_material_class
                        FROM type_materials_ids
                    ), material_class_to_retrieve AS (
                        SELECT 
                            CASE
                                WHEN (SELECT type_material_class FROM material_class) = 'children_material'
                                THEN children_id
                                ELSE single_id
                            END AS id
                        FROM type_materials_ids
                    ), material_unrepeated AS (
                        SELECT
                            DISTINCT smw.id,
                            mv.solution::BOOLEAN AS solution,
                            mv.quality::BOOLEAN AS quality,
                            CASE
                                WHEN dwtm.id IS NULL THEN 0
                                ELSE smw.fl_process_status
                            END AS fl_process_status,
                            smw.type_material_id,
                            CASE 
                                WHEN ( mv.quality IS FALSE AND mv.solution IS TRUE ) THEN dwtm.fl_process_status
                                WHEN ( mv.quality IS FALSE AND mv.solution IS FALSE ) THEN dwtm.fl_process_status_without
                                WHEN ( mv.quality IS TRUE AND mv.solution IS TRUE ) THEN dwtm.fl_process_quality
                                WHEN ( mv.quality IS TRUE AND mv.solution IS FALSE ) THEN dwtm.fl_process_without_quality
                            END AS process_status,
                            CASE 
                                WHEN mv.quality IS FALSE AND mv.solution IS TRUE THEN dwtm.url_solution
                                WHEN mv.quality IS FALSE AND mv.solution IS FALSE THEN dwtm.url_without_solution
                                WHEN mv.quality IS TRUE AND mv.solution IS TRUE THEN dwtm.url_quality
                                WHEN mv.quality IS TRUE AND mv.solution IS FALSE THEN dwtm.url_without_quality
                            END AS url,
                            (dwtm.fl_complete_questions AND dwtm.data_missing_course_config IS NULL) AS questions_are_completed,
                            dwtm.fl_config_level::BOOLEAN AS config_level,
                            dwtm.fl_config_type::BOOLEAN AS config_type,
                            dwtm.limit_lower_question AS lower_limit,
                            dwtm.limit_upper_question AS upper_limit,
                            dwtm.locked AS locked_status,
                            dwtm.locked_by AS locked_by,
                            dwtm.locked_at AS locked_at,
                            CASE
                                WHEN dwtm.id IS NULL THEN FALSE
                                ELSE EXISTS(SELECT * FROM material_distribution_ballot_questions mmd WHERE mmd.week_type_material_id = dwtm.id AND fl_status IS TRUE)
                            END AS has_distribution
                        FROM material_variants mv
                        LEFT JOIN detail_week_type_mat dwtm ON dwtm.week = p_week AND dwtm.type_material_id IN ( SELECT * FROM material_class_to_retrieve) AND dwtm.material_id = p_material_id
                        LEFT JOIN separated_material_week smw
                            ON dwtm.material_id = smw.material_id
                            AND smw.type_material_id IN ( SELECT single_id FROM type_materials_ids )
                            AND smw.fl_status IS TRUE
                            AND smw.week = p_week
                            AND mv.solution = smw.fl_solution
                            AND mv.quality = smw.fl_quality
                    ), regular_material AS (
                        SELECT
                            mu.solution,
                            mu.quality,
                            SUM( CASE WHEN mu.id IS NOT NULL THEN 1 ELSE 0 END ) total_material_courses,
                            SUM( CASE WHEN mu.fl_process_status = 3 THEN 1 ELSE 0 END ) AS total_completed_material_courses,
							SUM( CASE WHEN mu.fl_process_status = 2 THEN 1 ELSE 0 END ) AS total_processing_material_courses, -- Agregué
                            FALSE AS is_material_class,
                            COALESCE(mu.process_status, 0)::SMALLINT AS process_status,
                            mu.url,
                            mu.questions_are_completed,
                            mu.config_level AS config_level,
                            mu.config_type AS config_type,
                            mu.lower_limit AS lower_limit,
                            mu.upper_limit AS upper_limit,
                            mu.locked_status AS locked_status,
                            mu.locked_by AS locked_by,
                            mu.locked_at AS locked_at,
                            BOOL_AND(mu.has_distribution) has_distribution
                        FROM material_unrepeated mu
                        GROUP BY
                            mu.solution,
                            mu.quality,
                            mu.process_status,
                            mu.url,
                            mu.questions_are_completed,
                            mu.config_level,
                            mu.config_type,
                            mu.lower_limit,
                            mu.upper_limit,
                            mu.locked_status,
                            mu.locked_by,
                            mu.locked_at
                    ), class_material_percentages AS (
                        SELECT
                            NULL::BOOLEAN AS solution,
                            NULL::BOOLEAN AS quality,
                            COUNT(mcw.*) AS total_material_courses,
                            SUM( CASE WHEN mcw.fl_process_status = 3 THEN 1 ELSE 0 END ) AS total_completed_material_courses,
							SUM( CASE WHEN mcw.fl_process_status = 2 THEN 1 ELSE 0 END ) AS total_processing_material_courses, -- Agregué
                            TRUE AS is_material_class
                        FROM material_class_week mcw
                        WHERE mcw.type_material_id = p_type_material_id
                            AND mcw.week = p_week
                            AND mcw.fl_status IS TRUE
                        GROUP BY mcw.type_material_id
                    ), class_material_resources AS (
                    	SELECT
                    		dwtt.url_zip_class_mat AS url,
                    		dwtt.fl_process_class_mat AS process_status,
                    	    (dwtt.fl_complete_questions AND dwtt.data_missing_course_config IS NULL) AS questions_are_completed,
                    		dwtt.fl_config_level AS config_level,
                    		dwtt.fl_config_type AS config_type,
                            dwtt.limit_lower_question AS lower_limit,
                            dwtt.limit_upper_question AS upper_limit,
                            dwtt.locked AS locked_status,
                            dwtt.locked_by AS locked_by,
                            dwtt.locked_at AS locked_at
                    	FROM class_material_percentages cmp
                    	LEFT JOIN detail_week_type_mat dwtt ON dwtt.week = p_week AND dwtt.type_material_id IN ( SELECT id FROM material_class_to_retrieve ) AND dwtt.material_id = p_material_id
                    	GROUP BY
                    	    dwtt.url_zip_class_mat,
                    	    dwtt.fl_process_class_mat,
                    	    dwtt.fl_complete_questions,
                    	    dwtt.data_missing_course_config,
                    	    dwtt.fl_config_level,
                    	    dwtt.fl_config_type,
                            dwtt.limit_lower_question,
                            dwtt.limit_upper_question,
                            dwtt.locked,
                            dwtt.locked_by,
                            dwtt.locked_at
                    ), class_material AS (
                        SELECT
                            cmp.solution AS solution,
                            cmp.quality AS quality,
                            cmp.total_material_courses AS total_material_courses,
                            cmp.total_completed_material_courses AS total_completed_material_courses,
							cmp.total_processing_material_courses AS total_processing_material_courses, -- Agregué
                            cmp.is_material_class AS is_material_class,
                            cmr.process_status AS process_status,
                            cmr.url AS url,
                            cmr.questions_are_completed AS questions_are_completed,
                            cmr.config_level AS config_level,
                            cmr.config_type AS config_type,
                            cmr.lower_limit AS lower_limit,
                            cmr.upper_limit AS upper_limit,
                            cmr.locked_status AS locked_status,
                            cmr.locked_by AS locked_by,
                            cmr.locked_at AS locked_at,
                            FALSE AS has_distribution
                        FROM class_material_percentages cmp
                        LEFT JOIN class_material_resources cmr ON 1 = 1
                    ), all_materials AS (
                        SELECT * FROM regular_material
                        UNION
                        SELECT * FROM class_material
                    ), complete_materials AS (
                        SELECT
                            m.solution,
                            m.quality,
                            CASE
                                WHEN m.total_material_courses = 0 THEN 0::INTEGER
                                ELSE COALESCE((( m.total_completed_material_courses::DECIMAL / m.total_material_courses ) * 100 ), 0)::INTEGER
                            END AS material_progress,
                            m.is_material_class,
                            m.process_status AS process_status,
                            m.url AS url,
                            p_type_material_id AS type_material_id,
                            CASE
                                WHEN m.solution IS TRUE THEN 'Con solución'
                                WHEN m.solution IS FALSE THEN 'Sin solución'
                                ELSE 'Material de clases'
                            END AS solution_type_name,
                            p_week AS week,
                            CASE
                                WHEN m.quality IS FALSE THEN 'Oficial'
                                WHEN m.quality IS TRUE THEN 'Revisión'
                                ELSE 'Material de Clases'
                            END AS quality_type_name,
                            ( SELECT
                                JSON_AGG(id)
                                FROM material_class_to_retrieve
                            ) children_type_material_ids,
                            BOOL_AND(m.questions_are_completed) AS questions_are_completed,
                            m.config_level AS config_level,
                            m.config_type AS config_type,
                            m.lower_limit AS lower_limit,
                            m.upper_limit AS upper_limit,
                            m.total_processing_material_courses as total_processing,
                            m.locked_status AS lock_status,
                            m.locked_by AS locked_by,
                            m.locked_at AS locked_at,
                            BOOL_OR(m.has_distribution) AS has_distribution
                        FROM all_materials m
                        GROUP BY
                            m.solution,
                            m.quality,
                            m.is_material_class,
                            m.process_status,
                            m.url,
                            m.config_level,
                            m.config_type,
                            m.lower_limit,
                            m.upper_limit,
                            m.total_material_courses,
                            m.total_completed_material_courses,
                            m.total_processing_material_courses,
                            m.locked_status,
                            m.locked_by,
                            m.locked_at
                        ORDER BY
                            CASE
                                WHEN m.quality IS FALSE THEN 1
                                WHEN m.quality IS TRUE  THEN 2
                                ELSE 3
                            END DESC,
						    m.solution ASC
                    ) SELECT
                        cpm.*,
                        CASE
                            WHEN locked_by IS NULL THEN 'Sin acciones registradas'
                            WHEN locked_by IN (1, 2) THEN 'Administrador'
                            ELSE CONCAT( e.first_surname, ' ', e.second_surname, ' ', e.first_name )
                        END AS locked_by_name
                    FROM complete_materials cpm
                    LEFT JOIN employees e ON e.user_id = cpm.locked_by;
                END;
            $$;


ALTER FUNCTION odiseo.fn_material_detail_generation(p_material_id integer, p_type_material_id integer, p_week smallint, p_cycle integer) OWNER TO postgres;

--
-- Name: fn_material_distribution_ballot_questions(bigint, smallint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_material_distribution_ballot_questions(p_material_id bigint, p_week smallint, p_type_material_id smallint, p_week_type_material_id bigint) RETURNS TABLE(id bigint, material_id bigint, week smallint, type_material_id smallint, week_type_material_id bigint, course_id smallint, code_course character varying, course character varying, "position" smallint, position_initial smallint, subtopic_id bigint, code_subtopic character varying, subtopic character varying, topic_id smallint, code_topic character varying, topic character varying, level_id bigint, level_description character varying, level_name character varying, usage_level_id bigint, question_id bigint, type character varying, usage_status boolean)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            SELECT
                mdqb.id,
                mdqb.material_id,
                mdqb.week,
                mdqb.type_material_id,
                mdqb.week_type_material_id,
                mdqb.course_id,
                c.code AS course_code,
                c.name AS course,
                mdqb.position,
                mdqb.position_initial,
                mdqb.subtopic_id,
                st.code AS subtopic_code,
                st.name AS subtopic,
                mdqb.topic_id,
                t.code AS topic_code,
                t.name AS topic,
                mdqb.level_id,
                l.description AS level_description,
                l.name AS level_name,
                mdqb.usage_level_id,
                mdqb.question_id,
                mdqb.type,
                mdqb.usage_status
            FROM odiseo.material_distribution_ballot_questions AS mdqb
            INNER JOIN odiseo.course AS c ON mdqb.course_id = c.id
            LEFT JOIN odiseo.topic AS t ON mdqb.topic_id = t.id
            LEFT JOIN odiseo.subtopic AS st ON mdqb.subtopic_id = st.id
            LEFT JOIN odiseo.level AS l ON mdqb.level_id = l.id
            WHERE
                mdqb.material_id = p_material_id
                AND mdqb.week = p_week
                AND mdqb.type_material_id = p_type_material_id
                AND mdqb.week_type_material_id = p_week_type_material_id
                AND mdqb.fl_status = true
            ORDER BY mdqb.course_id ASC, mdqb.position ASC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_material_distribution_ballot_questions(p_material_id bigint, p_week smallint, p_type_material_id smallint, p_week_type_material_id bigint) OWNER TO postgres;

--
-- Name: fn_material_distribution_ballot_text(bigint, smallint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_material_distribution_ballot_text(p_material_id bigint, p_week smallint, p_type_material_id smallint, p_week_type_material_id bigint) RETURNS TABLE(id bigint, material_id bigint, week smallint, type_material_id smallint, week_type_material_id bigint, course_id smallint, code_course character varying, course character varying, "position" smallint, position_initial smallint, category_id bigint, category character varying, subcategory_id bigint, subcategory character varying, level_id bigint, level_description character varying, level_name character varying, usage_level_id bigint, question_id bigint, type character varying, usage_status boolean, subquestion jsonb, parent_question_id integer)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY
                    SELECT
                        mdqb.id,
                        mdqb.material_id,
                        mdqb.week,
                        mdqb.type_material_id,
                        mdqb.week_type_material_id,
                        mdqb.course_id,
                        c.code AS course_code,
                        c.name AS course,
                        mdqb.position,
                        mdqb.position_initial,
                        tt.id category_id,
                        tt.name AS category,
                        tts.id AS subcategory_id,
                        tts.name AS subcategory,
                        mdqb.level_id,
                        l.description AS level_description,
                        l.name AS level_name,
                        mdqb.usage_level_id,
                        mdqb.question_id,
                        mdqb.type,
                        mdqb.usage_status,
                        (
                            SELECT JSONB_AGG(
                                JSONB_BUILD_OBJECT(
                                    'question_id', mbs.question_id,
                                    'position', mbs.position
                                ) ORDER BY mbs.position ASC
                            )
                            FROM material_ballot_subquestions mbs
                            WHERE mbs.material_ballot_question_id = mdqb.id
                              AND mbs.fl_status = TRUE
                        ) AS subquestion,
                        mdqb.parent_question_id
                    FROM material_ballot_question AS mdqb
                    JOIN course AS c ON mdqb.course_id = c.id
                    JOIN level AS l ON mdqb.level_id = l.id
                    JOIN type_text tt ON tt.id = mdqb.type_text_id
                    JOIN type_text_subcategories tts ON tts.id = mdqb.type_text_subcategory_id 
                    WHERE
                        mdqb.material_id = p_material_id
                        AND mdqb.week = p_week
                        AND mdqb.type_material_id = p_type_material_id
                        AND mdqb.week_type_material_id = p_week_type_material_id
                        AND mdqb.fl_status = true
                    ORDER BY mdqb.course_id ASC, mdqb.position ASC;
                END;
            $$;


ALTER FUNCTION odiseo.fn_material_distribution_ballot_text(p_material_id bigint, p_week smallint, p_type_material_id smallint, p_week_type_material_id bigint) OWNER TO postgres;

--
-- Name: fn_material_exam_area_week(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_material_exam_area_week(p_detail_id bigint) RETURNS TABLE(id bigint, type_material character varying, area_id smallint, exam_area character varying, url_solution character varying, url_without_solution character varying, fl_process_status smallint, fl_process_status_without smallint, url_quality character varying, url_without_quality character varying, fl_process_quality smallint, fl_process_without_quality smallint, fl_complete_questions boolean, data_incomplete_questions character varying, missing_config_message character varying, data_missing_course_config character varying, filename character varying, fl_frequent boolean, type_exam_id bigint)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            SELECT
                meaw.id,
                tm.description AS type_material,
                meaw.area_id,
                ea.description AS exam_area,
                meaw.url_solution,
                meaw.url_without_solution,
                meaw.fl_process_status,
                meaw.fl_process_status_without,
                meaw.url_quality,
                meaw.url_without_quality,
                meaw.fl_process_quality,
                meaw.fl_process_without_quality,
                meaw.fl_complete_questions,
                meaw.data_incomplete_questions,
                meaw.missing_config_message,
                meaw.data_missing_course_config,
                meaw.filename,
                CASE
                    WHEN tmt.type_exam_id = '4' THEN TRUE
                    ELSE FALSE
                END AS fl_frequent,
                tmt.type_exam_id
            FROM material_exam_area_week meaw
            INNER JOIN exam_area ea ON meaw.area_id = ea.id
            INNER JOIN detail_week_type_mat dwtm ON meaw.week_type_material_id = dwtm.id AND dwtm.fl_status IS TRUE
            INNER JOIN type_material tm ON dwtm.type_material_id = tm.id
            INNER JOIN type_material_template tmt ON tm.type_material_template_id = tmt.id
            WHERE meaw.week_type_material_id = p_detail_id
            AND meaw.fl_status = true
            ORDER BY meaw.area_id ASC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_material_exam_area_week(p_detail_id bigint) OWNER TO postgres;

--
-- Name: fn_migrate_diagrammed_fields(); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_migrate_diagrammed_fields() RETURNS TABLE(question_id bigint, question_code character varying, employee_didi_question_id bigint, deactivated_field_id bigint, created_field_id bigint)
    LANGUAGE plpgsql
    AS $$
                    DECLARE
                        v_user_id INTEGER := 2; -- ID del usuario que realiza la migración
                    BEGIN
                        RETURN QUERY
                        WITH 
                        courses_apply_text AS (
                            SELECT c.id FROM course c WHERE c.apply_text 
                        ), 
                        active_employee_didi_question AS (
                            SELECT
                                edq.id AS id, q.course_id, pq.type_text_id AS category_id,
                                q.id as question_id, q.code as question_code
                            FROM employee_didi_question edq
                            JOIN question q ON q.id = edq.question_id JOIN parent_question pq ON pq.id = q.parent_id 
                            WHERE edq.fl_status IS TRUE AND q.course_id IN (SELECT * FROM courses_apply_text) AND pq.type_text_id IS NOT NULL
                        ),
                        fields_to_migrate AS (
                            SELECT 
                                edqf.id AS original_field_id,
                                edqf.employee_didi_question_id AS edq_id,
                                edqf.value,
                                (
                                    SELECT sdc.id 
                                    FROM setting_diagrammed_courses sdc 
                                    WHERE sdc.course_id = aedq.course_id AND sdc.category_text_id = aedq.category_id
                                    AND sdc.fl_status = true AND sdc.field_diagram_id = sdc1.field_diagram_id
                                    LIMIT 1
                                ) AS new_setting_diagrammed_course_id,
                                aedq.question_code,
                                aedq.question_id,
                                edqf.created_by,
                                edqf.updated_by,
                                edqf.migrated_updated_at,
                                edqf.math_migration_status,
                                edqf.fl_status
                            FROM active_employee_didi_question aedq
                            JOIN employee_didi_question_field edqf ON edqf.employee_didi_question_id = aedq.id
                            JOIN setting_diagrammed_courses sdc1 ON sdc1.id = edqf.setting_diagrammed_course_id 
                            WHERE edqf.fl_status = true
                            AND sdc1.category_text_id IS NULL
                        ),
                        valid_migrations AS (
                            SELECT * FROM fields_to_migrate WHERE new_setting_diagrammed_course_id IS NOT NULL
                        ),
                        updated_rows AS (
                            UPDATE employee_didi_question_field
                            SET 
                                fl_status = false,
                                deleted_at = NOW(),
                                deleted_by = v_user_id
                            WHERE id IN (SELECT original_field_id FROM valid_migrations)
                        ),
                        inserted_rows AS (
                            INSERT INTO employee_didi_question_field (
                                employee_didi_question_id, 
                                setting_diagrammed_course_id, 
                                value,
                                fl_status, 
                                created_at, 
                                created_by, 
                                updated_by,
                                migrated_updated_at,
                                math_migration_status
                            )
                            SELECT
                                vm.edq_id, 
                                vm.new_setting_diagrammed_course_id, 
                                vm.value,
                                vm.fl_status, 
                                NOW(), 
                                vm.created_by,
                                vm.updated_by,
                                vm.migrated_updated_at,
                                vm.math_migration_status
                            FROM valid_migrations vm
                            RETURNING id, employee_didi_question_field.employee_didi_question_id
                        )
                        SELECT
                            vm.question_id,
                            vm.question_code,
                            vm.edq_id AS employee_didi_question_id,
                            vm.original_field_id AS deactivated_field_id,
                            ir.id AS created_field_id
                        FROM valid_migrations vm
                        JOIN inserted_rows ir ON vm.edq_id = ir.employee_didi_question_id;

                    END;
                    $$;


ALTER FUNCTION odiseo.fn_migrate_diagrammed_fields() OWNER TO postgres;

--
-- Name: fn_missing_text_exam(integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_missing_text_exam(p_material_id integer, p_type_material_id integer, p_week integer) RETURNS TABLE(course_id smallint, material_exam_id bigint, type_report text, description text)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY
                    WITH material_data AS (
                        SELECT m.cycle_id, m.university_id 
                        FROM material m
                        WHERE m.id = p_material_id
                    ),
                    all_areas AS (
                        SELECT meaw.id material_exam_id, ea.description area 
                        FROM odiseo.detail_week_type_mat AS dwtm
                        JOIN material_exam_area_week meaw ON meaw.week_type_material_id = dwtm.id
                        JOIN exam_area ea ON ea.id = meaw.area_id 
                        WHERE dwtm.type_material_id = p_type_material_id and dwtm.week = p_week
                        AND dwtm.material_id = p_material_id
                    ),
                    missing_text AS (
                        SELECT 
                            mepq.course_id,
                            aa.area,
                            aa.material_exam_id ,
                            jsonb_array_length(mepq.subquestion) total_subquestion,
                            mepq.expected_level 
                        FROM material_exam_parent_question mepq 
                        LEFT JOIN parent_question pq ON pq.id = mepq.parent_question_id 
                        JOIN all_areas aa ON aa.material_exam_id = mepq.material_exam_area_week_id
                        WHERE mepq.deleted_at IS NULL AND mepq.parent_question_id IS NULL
                    ),
                    report_levels AS (
                        SELECT 
                            'by_level' as type_report,
                            'Falta ' || COUNT(*) || ' texto(s) nivel ' || mt.expected_level as description,
                            mt.course_id,
                            mt.material_exam_id
                        FROM missing_text mt
                        GROUP BY mt.course_id, mt.material_exam_id, mt.expected_level
                    ),
                    report_subquestions AS (
                        SELECT 
                            'by_subquestion' as type_report,
                            'Falta ' || COUNT(*) || ' texto(s) con ' || mt.total_subquestion || ' subpreguntas' as description,
                            mt.course_id,
                            mt.material_exam_id
                        FROM missing_text mt
                        GROUP BY mt.course_id, mt.material_exam_id, mt.total_subquestion
                    )
                    SELECT rl.course_id, rl.material_exam_id, rl.type_report, rl.description
                    FROM report_levels rl
                    UNION ALL
                    SELECT rs.course_id, rs.material_exam_id, rs.type_report, rs.description
                    FROM report_subquestions rs
                    ORDER BY course_id, material_exam_id, type_report;
                END;
            $$;


ALTER FUNCTION odiseo.fn_missing_text_exam(p_material_id integer, p_type_material_id integer, p_week integer) OWNER TO postgres;

--
-- Name: fn_modalities_university(integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_modalities_university(p_options integer, p_university integer) RETURNS TABLE(id integer, name character varying, option_ids jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        mo.id::INT,
        mo.name::VARCHAR,
        (
            -- Subconsulta: Trae todas las opciones de la universidad (igual que tu lógica anterior)
            SELECT COALESCE(jsonb_agg(jsonb_build_object('id', ou_sub.id, 'name', ou_sub.name)), '[]'::jsonb)
            FROM option_university ou_sub
            WHERE ou_sub.deleted_at IS NULL
              AND (p_university IS NULL OR ou_sub.university_id = p_university)
        ) AS option_ids
    FROM modality_options mo
    INNER JOIN option_university ou ON mo.option_university_id = ou.id
    WHERE mo.deleted_at IS NULL
      AND ou.deleted_at IS NULL
      -- Filtrar por opción si se envía el parámetro
      AND (p_options IS NULL OR ou.id = p_options)
      -- Filtrar por universidad si se envía el parámetro
      AND (p_university IS NULL OR ou.university_id = p_university)
    ORDER BY mo.id ASC;
END;
$$;


ALTER FUNCTION odiseo.fn_modalities_university(p_options integer, p_university integer) OWNER TO postgres;

--
-- Name: fn_name_employee(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_name_employee(p_user_id bigint) RETURNS TABLE(user_name text)
    LANGUAGE plpgsql
    AS $$
            DECLARE
                user_name TEXT;
            BEGIN
                IF p_user_id = 1 OR p_user_id = 2 THEN
                    RETURN QUERY SELECT 'SISTEMA'::text;
                ELSE
					RETURN QUERY
                    SELECT
                        concat(split_part(e.first_name, ' ', 1), ' ', upper(left(e.first_surname, 1)), '. ', e.second_surname) as user_name
                    FROM odiseo.employees e
                    WHERE e.user_id = p_user_id;
                END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_name_employee(p_user_id bigint) OWNER TO postgres;

--
-- Name: fn_nq_create_user_token(uuid, character varying, character varying, timestamp with time zone, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_nq_create_user_token(p_user_uuid uuid, p_nq_user character varying, p_nq_token character varying, p_nq_token_expiration_date timestamp with time zone, p_created_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
    DECLARE v_user_id BIGINT;
    BEGIN
        SELECT id INTO v_user_id FROM users WHERE uuid = p_user_uuid;

        PERFORM fn_revoke_user_token(p_user_uuid, p_created_by);
                
        INSERT INTO nq_user_request(user_id, request_status, created_by, created_at)
        VALUES(v_user_id, 'delivered', p_created_by, NOW())
        ON CONFLICT ON CONSTRAINT nq_req_user_id
        DO UPDATE
            SET
                request_status = 'delivered',
                updated_at = NOW(),
                deleted_at = NULL,
                deleted_by = NULL;
                            
        INSERT INTO nq_user_token(user_id, nq_user, nq_token, nq_expiration_date, created_by, created_at)
        VALUES(v_user_id, p_nq_user, p_nq_token, p_nq_token_expiration_date, p_created_by, NOW());
    END;
    $$;


ALTER FUNCTION odiseo.fn_nq_create_user_token(p_user_uuid uuid, p_nq_user character varying, p_nq_token character varying, p_nq_token_expiration_date timestamp with time zone, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_number_to_roman(smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_number_to_roman(num smallint) RETURNS character varying
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    result VARCHAR(10) := '';
    value INTEGER := num;
    roman_values INTEGER[] := ARRAY[1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
    roman_symbols VARCHAR[] := ARRAY['M', 'CM', 'D', 'CD', 'C', 'XC', 'L', 'XL', 'X', 'IX', 'V', 'IV', 'I'];
    i INTEGER;
BEGIN
    IF num <= 0 OR num > 3999 THEN
        RAISE EXCEPTION 'Input % is out of range for Roman numerals (1 to 3999)', num;
    END IF;

    FOR i IN 1..array_length(roman_values, 1) LOOP
        WHILE value >= roman_values[i] LOOP
            result := result || roman_symbols[i];
            value := value - roman_values[i];
        END LOOP;
    END LOOP;

    RETURN result;
END;
$$;


ALTER FUNCTION odiseo.fn_number_to_roman(num smallint) OWNER TO postgres;

--
-- Name: fn_options_university(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_options_university(p_university integer) RETURNS TABLE(id integer, name character varying, university_ids integer[])
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    ou.id::INT,
                    ou.name::VARCHAR,
                    ARRAY[ou.university_id]::INT[] AS university_ids
                FROM option_university ou
                WHERE ou.deleted_at IS NULL
                  AND (p_university IS NULL OR ou.university_id = p_university)
                ORDER BY ou.id ASC;
            END;
            $$;


ALTER FUNCTION odiseo.fn_options_university(p_university integer) OWNER TO postgres;

--
-- Name: fn_order_by_list_verified_question(integer, integer, character varying, integer, integer, integer, character varying, json, json, json, integer, integer, integer, integer, character varying, integer[], text, text, smallint, smallint, smallint, smallint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_order_by_list_verified_question(p_perpage integer, p_npage integer, p_name_text character varying, p_employee_id integer, f_course_id integer, f_teacher_id integer, f_type character varying, f_topics_id json, f_subtopics_id json, f_status json, f_cycle_id integer, f_week_id integer, f_type_material_id integer, f_level_id integer, p_number_question character varying, p_array_courses integer[], p_order_column text, p_order_direction text, f_university_id smallint, f_option_id smallint, f_modality_id smallint, f_version smallint, f_year character varying) RETURNS TABLE(id bigint, key_question text, parent_id bigint, subquestions jsonb, type_question text, code character varying, number_question character varying, short_description text, course_id smallint, course character varying, teacher_id bigint, subtopic_id bigint, teacher text, status character varying, date_status timestamp without time zone, observation text, level_id smallint, level_question character varying, origin_question jsonb, shared_status text, total_count bigint)
    LANGUAGE plpgsql
    AS $$
    DECLARE
    order_clause TEXT;
    sql_query TEXT;
    BEGIN
        -- Validamos el nombre de la columna permitida
        IF p_order_column IS NULL OR p_order_column NOT IN ('code', 'level_question', 'course', 'teacher', 'date_status') THEN
            p_order_column := NULL::TEXT;
        END IF;

        -- Validamos la dirección del orden
        IF UPPER(p_order_direction) NOT IN ('ASC', 'DESC') THEN
            p_order_direction := 'ASC';
        END IF;

        -- Construimos cláusula ORDER BY segura
        IF p_order_column IS NULL THEN
            order_clause := NULL::TEXT;
        ELSE
            -- Si es por fecha no usar unaccent
            IF p_order_column = 'date_status' THEN
                order_clause := format('ORDER BY %I %s', p_order_column, p_order_direction);
            -- Si es docente mandar al final los vacios cuando es ASC y viceversa
            ELSIF p_order_column = 'teacher' THEN
                IF UPPER(p_order_direction) = 'ASC' THEN
                    order_clause := 'ORDER BY CASE WHEN teacher IS NULL OR teacher = '''' THEN 1 ELSE 0 END, unaccent(teacher) ASC';
                ELSE
                    order_clause := 'ORDER BY CASE WHEN teacher IS NULL OR teacher = '''' THEN 0 ELSE 1 END, unaccent(teacher) DESC';
                END IF;
            -- Usar los filtro siguientes
            ELSE
                order_clause := format('ORDER BY unaccent(%I) %s', p_order_column, p_order_direction);
            END IF;
        END IF;

        sql_query := 'SELECT * FROM fn_list_verified_question(';

        sql_query := sql_query || COALESCE(format('%L', p_name_text), 'NULL') || ', ';
        sql_query := sql_query || COALESCE(format('%L', p_employee_id), 'NULL') || ', ';
        sql_query := sql_query || COALESCE(format('%L', f_course_id), 'NULL') || ', ';
        sql_query := sql_query || COALESCE(format('%L', f_teacher_id), 'NULL') || ', ';
        sql_query := sql_query || COALESCE(format('%L', f_type), 'NULL') || ', ';
        sql_query := sql_query || COALESCE(format('%L', f_topics_id), 'NULL') || ', ';
        sql_query := sql_query || COALESCE(format('%L', f_subtopics_id), 'NULL') || ', ';
        sql_query := sql_query || COALESCE(format('%L', f_status), 'NULL') || ', ';
        sql_query := sql_query || COALESCE(format('%L', f_cycle_id), 'NULL') || ', ';
        sql_query := sql_query || COALESCE(format('%L', f_week_id), 'NULL') || ', ';
        sql_query := sql_query || COALESCE(format('%L', f_type_material_id), 'NULL') || ', ';
        sql_query := sql_query || COALESCE(format('%L', f_level_id), 'NULL') || ', ';
        sql_query := sql_query || COALESCE(format('%L', p_number_question), 'NULL') || ', ';
        sql_query := sql_query || COALESCE(format('%L', p_array_courses), 'NULL') || ', ';
        sql_query := sql_query || COALESCE(format('%L', f_university_id), 'NULL') || ', ';
        sql_query := sql_query || COALESCE(format('%L', f_option_id), 'NULL') || ', ';
        sql_query := sql_query || COALESCE(format('%L', f_modality_id), 'NULL') || ', ';
        sql_query := sql_query || COALESCE(format('%L', f_version), 'NULL') || ', ';
        sql_query := sql_query || COALESCE(format('%L', f_year), 'NULL') || ') ';

        -- Agregar el ORDER BY
        IF p_order_column IS NOT NULL THEN
            sql_query := sql_query || order_clause || ', date_status ASC';
        END IF;

        -- Agregar LIMIT y OFFSET
        sql_query := sql_query || format(' LIMIT %s OFFSET %s', p_perpage, (p_npage - 1) * p_perpage);

        -- Ejecutar la consulta dinámica
        RETURN QUERY EXECUTE sql_query;
    END;
    $$;


ALTER FUNCTION odiseo.fn_order_by_list_verified_question(p_perpage integer, p_npage integer, p_name_text character varying, p_employee_id integer, f_course_id integer, f_teacher_id integer, f_type character varying, f_topics_id json, f_subtopics_id json, f_status json, f_cycle_id integer, f_week_id integer, f_type_material_id integer, f_level_id integer, p_number_question character varying, p_array_courses integer[], p_order_column text, p_order_direction text, f_university_id smallint, f_option_id smallint, f_modality_id smallint, f_version smallint, f_year character varying) OWNER TO postgres;

--
-- Name: fn_order_list_material_per_period(bigint, smallint, smallint, smallint, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_order_list_material_per_period(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint, p_distribution_orders jsonb, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
            BEGIN
                WITH get_material_per_period_ballot AS (
                    SELECT
                        mpp.id AS material_per_period_id,
                        mppb.id AS material_per_period_ballot_id
                    FROM material_per_period mpp
                    JOIN material_per_period_ballot mppb ON mpp.id = mppb.material_per_period_id
                    WHERE mpp.material_id = p_material_id
                        AND mpp.type_material_id = p_type_material_id
                        AND mppb.start_week = p_start_week
                        AND mppb.end_week = p_end_week
                        AND mppb.deleted_by IS NULL
                        AND mpp.deleted_by IS NULL
                    LIMIT 1
                ), update_order_date AS (
                    UPDATE material_per_period_ballot mppb
                    SET order_date = NOW(),
                        order_by_user_id = p_updated_by
                    WHERE mppb.id IN (
                        SELECT gmppb.material_per_period_ballot_id FROM get_material_per_period_ballot gmppb
                    )
                ), get_distribution_orders AS (
                    SELECT
                        COALESCE((dist->>'material_ballot_question_id')::BIGINT, (dist->>'id')::BIGINT) AS id,
                        (dist->>'absolute_position')::SMALLINT AS absolute_position,
                        (dist->>'random')::BOOLEAN AS random,
                        (dist->>'order')::SMALLINT AS order
                    FROM jsonb_array_elements(p_distribution_orders) dist
                )
                UPDATE material_ballot_question mbq
                SET absolute_position = gdo.absolute_position,
                    random = gdo.random,
                    "position" = gdo.order
                FROM get_distribution_orders gdo
                WHERE mbq.id = gdo.id;
            END;
            $$;


ALTER FUNCTION odiseo.fn_order_list_material_per_period(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint, p_distribution_orders jsonb, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_origin_parent_question(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_origin_parent_question(p_parent_question_id bigint) RETURNS TABLE(id bigint, parent_id bigint, year character varying, region_id bigint, region character varying, university_id bigint, university character varying, option_id bigint, option character varying, modality_id bigint, modality character varying, areas character varying, version character varying, order_version integer)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                WITH tlb_versions AS (
                    SELECT
                        ou.id AS university_id,
                        (v.value->>'order')::INT AS order,
                        (v.value->>'version')::SMALLINT AS version
                    FROM origin_university ou,
                        LATERAL jsonb_array_elements(ou.versions::jsonb) AS v(value)
                    WHERE ou.versions IS NOT NULL
                    AND ou.versions::text <> '[]'
                ), tbl_origin_questions AS (
                    SELECT
                        oq.id,
                        oq.parent_id,
                        oq.year,
                        oq.region_id,
                        r.name AS region,
                        op_u.university_id,
                        ou.name AS university,
                        op_u.id as option_id,
                        op_u.name AS option,
                        mo.id as modality_id,
                        mo.name AS modality,
                        oq.areas,
                        fn_number_to_roman(oq.version::smallint)::varchar AS version,
                        tv.order AS order_version
                    FROM origin_parent_question oq
                    LEFT JOIN region r ON oq.region_id = r.id
                    LEFT JOIN modality_options mo ON mo.id = oq.modality_option_id
                        AND mo.deleted_at IS NULL
                    
                    LEFT JOIN option_university op_u ON op_u.id = mo.option_university_id 
                        AND op_u.deleted_at IS NULL
					
                    LEFT JOIN origin_university ou ON op_u.university_id = ou.id

                    LEFT JOIN tlb_versions tv ON ou.id = tv.university_id
                        AND oq.version::smallint = tv.version
                    WHERE oq.parent_id = p_parent_question_id
                        AND oq.fl_status = true
                    ORDER BY public.unaccent(ou.name) ASC, oq.year DESC, tv.order ASC
                )
                SELECT toq.* FROM tbl_origin_questions toq;
            END;
            $$;


ALTER FUNCTION odiseo.fn_origin_parent_question(p_parent_question_id bigint) OWNER TO postgres;

--
-- Name: fn_origin_question(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_origin_question(p_question_id bigint) RETURNS TABLE(id bigint, question_id bigint, year character varying, region_id bigint, region character varying, university_id bigint, university character varying, option_id bigint, option character varying, modality_id bigint, modality character varying, areas character varying, version character varying, order_version integer)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                WITH tlb_versions AS (
                    SELECT
                        ou.id AS university_id,
                        (v.value->>'order')::INT AS order,
                        (v.value->>'version')::SMALLINT AS version
                    FROM origin_university ou,
                        LATERAL jsonb_array_elements(ou.versions::jsonb) AS v(value)
                    WHERE ou.versions IS NOT NULL
                    AND ou.versions::text <> '[]'
                ), tbl_origin_questions AS (
                    SELECT
                        oq.id,
                        oq.question_id,
                        oq.year,
                        oq.region_id,
                        r.name AS region,
                        op_u.university_id,
                        ou.name AS university,
                        op_u.id as option_id, -- ID de la opción desde la nueva tabla option_university
                        op_u.name AS option, -- Nombre desde la nueva tabla option_university
                        mo.id as modality_id, -- ID de la modality_id para no romper nada
                        mo.name AS modality, -- Nombre desde la nueva tabla modality_options
                        oq.areas,
                        fn_number_to_roman(oq.version::smallint)::varchar AS version,
                        tv.order AS order_version
                    FROM origin_question oq
                    LEFT JOIN region r ON oq.region_id = r.id
                    -- NUEVO: JOIN a modality_options usando global modality_id y el pivote de la opción
                    LEFT JOIN modality_options mo ON mo.id = oq.modality_option_id
                        AND mo.deleted_at IS NULL
                    
                    -- NUEVO: JOIN a option_university usando el global option_id y university_id
                    LEFT JOIN option_university op_u ON op_u.id = mo.option_university_id 
                        AND op_u.deleted_at IS NULL
					
                    LEFT JOIN origin_university ou ON op_u.university_id = ou.id
                        
                    LEFT JOIN tlb_versions tv ON ou.id = tv.university_id
                        AND oq.version::smallint = tv.version
                    WHERE oq.question_id = p_question_id
                        AND oq.fl_status = true
                    ORDER BY public.unaccent(ou.name) ASC, oq.year DESC, tv.order ASC
                )
                SELECT toq.* FROM tbl_origin_questions toq;
            END;
            $$;


ALTER FUNCTION odiseo.fn_origin_question(p_question_id bigint) OWNER TO postgres;

--
-- Name: fn_origin_university(integer, integer, smallint, character varying, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_origin_university(p_perpage integer, p_npage integer, p_type smallint, p_name_text character varying, p_fl_active boolean) RETURNS TABLE(id smallint, code character varying, name character varying, slug character varying, type smallint, region_id smallint, fl_active boolean, region character varying, options jsonb, areas text, versions jsonb, total integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total_count   integer;
    v_offset        integer;
BEGIN
    v_offset := p_perpage * (p_npage - 1);

    -- 1. Conteo total
    SELECT COUNT(*) INTO v_total_count
    FROM origin_university u
    WHERE u.deleted_by IS NULL
      AND (p_fl_active IS NULL OR u.fl_active = p_fl_active)
      AND (p_type      IS NULL OR u.type      = p_type) -- Usando p_type
      AND (
            p_name_text IS NULL
            OR LOWER(u.name) LIKE '%' || LOWER(p_name_text) || '%'
            OR LOWER(u.slug) LIKE '%' || LOWER(p_name_text) || '%'
          );

    RETURN QUERY
    WITH
    -- 2. Universidades filtradas y paginadas
    filtered_universities AS (
        SELECT u.*
        FROM origin_university u
        WHERE u.deleted_by IS NULL
          AND (p_fl_active IS NULL OR u.fl_active = p_fl_active)
          AND (p_type      IS NULL OR u.type      = p_type) -- Usando p_type
          AND (
                p_name_text IS NULL
                OR LOWER(u.name) LIKE '%' || LOWER(p_name_text) || '%'
                OR LOWER(u.slug) LIKE '%' || LOWER(p_name_text) || '%'
              )
        ORDER BY u.id
        LIMIT  p_perpage
        OFFSET v_offset
    ),

    -- 3. Agrupamos modalidades por cada 'option_university'
    modalities_grouped AS (
        SELECT 
            mo.option_university_id,
            JSONB_AGG(
                JSONB_BUILD_OBJECT(
                    'id',   mo.id, 
                    'name', mo.name,
                    'fl_allows_mark_frequent_topic', mo.fl_allows_mark_frequent_topic
                ) ORDER BY mo.id
            ) AS modalities_list
        FROM modality_options mo
        WHERE mo.deleted_at IS NULL
        GROUP BY mo.option_university_id
    ),

    -- 4. Agrupamos las opciones por universidad e inyectamos sus modalidades
    university_options AS (
        SELECT
            ou.university_id,
            JSONB_AGG(
                JSONB_BUILD_OBJECT(
                    'id',         ou.id,
                    'name',        ou.name,
                    'modalities', COALESCE(mg.modalities_list, '[]'::jsonb)
                ) ORDER BY ou.id
            ) AS options_list
        FROM option_university ou
        LEFT JOIN modalities_grouped mg ON mg.option_university_id = ou.id
        WHERE ou.university_id IN (SELECT f.id FROM filtered_universities f)
        AND ou.deleted_at IS NULL
        GROUP BY ou.university_id
    ),

    -- 5. Procesamos versiones
    university_versions AS (
        SELECT
            u.id AS university_id,
            JSONB_AGG(
                JSONB_BUILD_OBJECT(
                    'order',   e ->> 'order',
                    'version', fn_number_to_roman((e ->> 'version')::smallint)
                )
            ) AS versions_list
        FROM filtered_universities u,
             JSONB_ARRAY_ELEMENTS(u.versions::jsonb) e
        GROUP BY u.id
    )

    -- 6. Resultado final uniendo todo
    SELECT
        u.id,
        u.code,
        u.name,
        u.slug,
        u.type,
        u.region_id,
        u.fl_active,
        r.name AS region,
        COALESCE(uo.options_list, '[]'::jsonb),
        u.areas,
        COALESCE(uv.versions_list, '[]'::jsonb),
        v_total_count
    FROM filtered_universities u
    LEFT JOIN region r ON r.id = u.region_id
    LEFT JOIN university_options uo ON uo.university_id = u.id
    LEFT JOIN university_versions uv ON uv.university_id = u.id
    ORDER BY u.id;

END;
$$;


ALTER FUNCTION odiseo.fn_origin_university(p_perpage integer, p_npage integer, p_type smallint, p_name_text character varying, p_fl_active boolean) OWNER TO postgres;

--
-- Name: fn_origin_university_all(smallint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_origin_university_all(f_type smallint, p_name_text character varying) RETURNS TABLE(id smallint, code character varying, name character varying, slug character varying, type smallint, region_id smallint, region character varying, options jsonb, areas text, versions jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        u.id, u.code, u.name, u.slug, u.type, u.region_id,
        r.name AS region,
        (
            -- Subconsulta de Opciones usando la tabla pivote
            SELECT COALESCE(jsonb_agg(option_data), '[]'::jsonb)
            FROM (
                SELECT ou.id AS id, ou.name,
                    (
                        -- Subconsulta de Modalidades usando la tabla pivote
                        SELECT COALESCE(jsonb_agg(modality_data), '[]'::jsonb)
                        FROM (
                            SELECT mo.id AS id, mo.name
                            FROM modality_options mo
                            WHERE mo.option_university_id = ou.id
                                AND mo.deleted_at IS NULL
                            ORDER BY mo.id ASC
                        ) modality_data
                    ) AS modalities
                FROM option_university ou
                WHERE ou.university_id = u.id
                    AND ou.deleted_at IS NULL
                ORDER BY ou.id ASC
            ) option_data
        ) AS options,
        u.areas,
        (
            SELECT JSONB_AGG(JSONB_BUILD_OBJECT('order', e->>'order', 'version', fn_number_to_roman((e->>'version')::SMALLINT)))
            FROM JSONB_ARRAY_ELEMENTS(u.versions::JSONB) e
        ) AS versions
    FROM origin_university u
    LEFT JOIN region r ON u.region_id = r.id
    WHERE u.deleted_by IS NULL
        AND u.fl_active = true
        AND (f_type IS NULL OR u.type = f_type)
        AND (
            p_name_text IS NULL
            OR LOWER(u.name) LIKE '%' || LOWER(p_name_text) || '%'
            OR LOWER(u.slug) LIKE '%' || LOWER(p_name_text) || '%'
        )
    ORDER BY u.id ASC;
END;
$$;


ALTER FUNCTION odiseo.fn_origin_university_all(f_type smallint, p_name_text character varying) OWNER TO postgres;

--
-- Name: fn_origin_university_with_cycle(character varying, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_origin_university_with_cycle(p_name_text character varying, p_company_id integer) RETURNS TABLE(id smallint, code character varying, name character varying)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        SELECT u.id, u.code, u.name
        FROM origin_university u
        INNER JOIN material m ON u.id = m.university_id AND m.fl_status = TRUE
        INNER JOIN cycle c ON m.cycle_id = c.id AND c.fl_status = TRUE
        INNER JOIN detail_week_type_mat dwtm ON m.id = dwtm.material_id AND dwtm.fl_status = TRUE
        INNER JOIN material_exam_area_week meaw ON dwtm.id = meaw.week_type_material_id AND meaw.fl_status = TRUE
        WHERE u.deleted_by IS NULL
        AND u.fl_active = true
        AND m.company_id = p_company_id
        AND (
            p_name_text IS NULL
            OR LOWER(u.name) LIKE '%' || LOWER(p_name_text) || '%'
            OR LOWER(u.slug) LIKE '%' || LOWER(p_name_text) || '%'
        )
        GROUP BY u.id, u.code, u.name
        ORDER BY u.id ASC;
    END;
    $$;


ALTER FUNCTION odiseo.fn_origin_university_with_cycle(p_name_text character varying, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_paginate_compatible_questions(bigint, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_paginate_compatible_questions(p_material_ballot_question_id bigint, p_per_page integer DEFAULT 3, p_page integer DEFAULT 1) RETURNS TABLE(id bigint, total bigint)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_offset INTEGER;
    v_max_questions INTEGER;
BEGIN
    IF p_page < 1 THEN
        p_page := 1;
    END IF;

    v_offset := p_per_page * (p_page - 1);

    SELECT amount_questions_alternatives INTO v_max_questions 
    FROM advanced_settings 
    LIMIT 1;

    RETURN QUERY
    WITH question_attribute AS (
        SELECT 
            mbq.course_id, 
            mbq.topic_id, 
            mbq.subtopic_id, 
            mbq.level_id,
            dwtm.material_id 
        FROM material_ballot_question mbq 
        INNER JOIN detail_week_type_mat dwtm ON dwtm.id = mbq.week_type_material_id 
        WHERE mbq.id = p_material_ballot_question_id
    ),
    matching_questions AS (
        SELECT 
            flq.id,
            flq.status,
            q.updated_at
        FROM question_attribute qa
        CROSS JOIN LATERAL fn_list_questions_verified_and_not_excluded(qa.material_id) flq
        INNER JOIN question q ON q.id = flq.id
        WHERE flq.course_id = qa.course_id 
          AND flq.level_id = qa.level_id 
          AND flq.subtopic_id = qa.subtopic_id
          AND flq.topic_id = qa.topic_id
        ORDER BY 
            flq.status ASC,
            q.updated_at DESC,
            flq.id DESC
        LIMIT v_max_questions
    )
    SELECT 
        mq.id,
        COUNT(*) OVER()::BIGINT AS total 
    FROM matching_questions mq
    ORDER BY 
        mq.status ASC,
        mq.updated_at DESC,
        mq.id DESC
    LIMIT p_per_page 
    OFFSET v_offset;
END;
$$;


ALTER FUNCTION odiseo.fn_paginate_compatible_questions(p_material_ballot_question_id bigint, p_per_page integer, p_page integer) OWNER TO postgres;

--
-- Name: fn_paginate_cycles(integer, integer, character varying, boolean, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_paginate_cycles(p_perpage integer, p_npage integer, p_name_text character varying, p_active boolean, p_company_id integer) RETURNS TABLE(id bigint, code character varying, description character varying, month smallint, year smallint, weeks smallint, start_date date, end_date date, active boolean, cycle_type_id bigint, cycle_type character varying, created_by text, created_at timestamp without time zone, total_count bigint)
    LANGUAGE plpgsql STABLE
    AS $$
        DECLARE
            v_offset INTEGER;
        BEGIN
            -- Calcular el offset para la paginación
            v_offset := p_perpage * (p_npage - 1);

            RETURN QUERY
            WITH tbl_cycle as (
                SELECT
                    c.id,
                    c.code,
                    c.description,
                    c.month,
                    c.year,
                    c.weeks,
                    c.start_date,
                    c.end_date,
                    c.active,
                    c.cycle_type_id,
                    ct.name AS cycle_type,
                    CASE
                        WHEN e.first_name IS NOT NULL AND e.first_surname IS NOT NULL THEN
                            CONCAT(initcap(split_part(e.first_name, ' ', 1)), ' ',
                                upper(left(e.first_surname, 1)), '. ',
                                initcap(e.second_surname))
                        ELSE
                            NULL
                    END AS created_by,
                    c.created_at
                FROM "cycle" c
                LEFT JOIN cycle_types ct ON c.cycle_type_id = ct.id
                LEFT JOIN users u ON c.created_by = u.id
                LEFT JOIN employees e ON u.id = e.user_id
                WHERE c.fl_status = true and c.deleted_at is null
                    AND (
                        p_name_text IS NULL
                        OR c.description ILIKE '%' || p_name_text || '%'
                        OR c.code ILIKE '%' || p_name_text || '%'
                    )
                    AND (p_active IS NULL OR c.active = p_active)
                    AND c.company_id = p_company_id
            ), counted_cycles AS (
                SELECT *, COUNT(*) OVER () AS total_count
                FROM tbl_cycle
            )
            SELECT *
            FROM counted_cycles
            ORDER BY created_at DESC
            LIMIT p_perpage
            OFFSET v_offset;
        END;
        $$;


ALTER FUNCTION odiseo.fn_paginate_cycles(p_perpage integer, p_npage integer, p_name_text character varying, p_active boolean, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_paginate_cycles_simple(character varying, character varying, character varying, boolean, boolean, integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_paginate_cycles_simple(p_search character varying, p_code character varying, p_description character varying, f_status boolean, p_active boolean, p_perpage integer, p_npage integer, p_company_id integer) RETURNS TABLE(id bigint, description character varying, weeks smallint, created_at timestamp without time zone, total bigint)
    LANGUAGE plpgsql STABLE
    AS $$
        DECLARE
            v_offset INT;
        BEGIN
            v_offset := p_perpage * (p_npage - 1);

            RETURN QUERY
            WITH cycles AS (
                SELECT
                    c.id,
                    c.description,
                    c.weeks,
                    c.created_at
                FROM cycle c
                WHERE c.fl_status = f_status
                    AND (p_active IS NULL OR c.active = p_active)
                    AND c.deleted_at IS NULL
                    AND (p_code IS NULL OR c.code ILIKE '%' || p_code || '%')
                    AND (p_description IS NULL OR c.description ILIKE '%' || p_description || '%')
                    AND (p_search IS NULL OR (c.code ILIKE '%' || p_search || '%' OR c.description ILIKE '%' || p_search || '%'))
                    AND c.company_id = p_company_id
            ), counted_cycles AS (
                SELECT
                    *,
                    COUNT(*) OVER () AS total_count
                FROM cycles
            )
            SELECT
                *
            FROM counted_cycles
            ORDER BY created_at DESC
            LIMIT p_perpage
            OFFSET v_offset;
        END;
        $$;


ALTER FUNCTION odiseo.fn_paginate_cycles_simple(p_search character varying, p_code character varying, p_description character varying, f_status boolean, p_active boolean, p_perpage integer, p_npage integer, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_paginate_material_generated(integer, integer, integer, integer, integer, date, date); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_paginate_material_generated(p_perpage integer, p_npage integer, p_company_id integer, p_cycle_id integer, p_type_material_template_id integer, p_start_date date, p_end_date date) RETURNS TABLE(material_id bigint, cycle_id bigint, cycle character varying, type_material_id smallint, type_material_description character varying, start_week smallint, end_week smallint, status character varying, created_at date, initial_total_questions bigint, initial_missing_questions bigint, completed_by_system bigint, completed_manually bigint, manually_removed bigint, current_total_questions bigint, current_missing_questions bigint, total_count bigint)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_offset integer;
BEGIN
    v_offset := p_perpage * (p_npage - 1);

    RETURN QUERY
    WITH unified_questions AS (
        SELECT 
            mbq.material_id,
            COALESCE(dwtm.parent_type_material_id, mbq.type_material_id) AS root_type_material_id,
            mbq.week,
            mbq.entity_type,
            COALESCE(mbs.state, mbq.state) AS effective_state,
            COALESCE(dwtm.updated_at::date, dwtm.created_at::date) AS created_at
        FROM material_ballot_question mbq
        JOIN material m ON m.id = mbq.material_id AND m.fl_status = true AND m.deleted_at IS NULL
        JOIN cycle c ON c.id = m.cycle_id AND c.fl_status = true AND c.deleted_at IS NULL
        JOIN detail_week_type_mat dwtm 
            ON dwtm.id = mbq.week_type_material_id 
           AND dwtm.fl_status = true 
           AND dwtm.deleted_at IS NULL
        JOIN type_material tm ON tm.id = COALESCE(dwtm.parent_type_material_id, mbq.type_material_id)
        JOIN type_material_template tmt ON tmt.id = tm.type_material_template_id
        LEFT JOIN material_ballot_subquestions mbs 
            ON mbs.material_ballot_question_id = mbq.id
           AND mbs.fl_status = true 
           AND mbs.deleted_at IS NULL
        WHERE 
            (p_type_material_template_id IS NULL OR tmt.id = p_type_material_template_id)
            AND (p_cycle_id IS NULL OR m.cycle_id = p_cycle_id)
            AND (p_company_id IS NULL OR c.company_id = p_company_id)
            AND (p_start_date IS NULL OR COALESCE(dwtm.updated_at::date, dwtm.created_at::date) >= p_start_date)
            AND (p_end_date IS NULL OR COALESCE(dwtm.updated_at::date, dwtm.created_at::date) <= p_end_date)
            AND mbq.fl_status = true 
            AND mbq.deleted_at IS NULL
            AND (
                mbq.entity_type = 'QUESTION' 
                OR mbs.id IS NOT NULL
            )
    ),
    report_data AS (
        SELECT 
            m.id AS material_id,
            c.id AS cycle_id,
            c.description::varchar AS cycle,
            tm_root.id AS type_material_id,
            tm_root.description::varchar AS type_material_description,
            mppb.start_week,
            mppb.end_week,
            mr.status::varchar AS status,
            uq.created_at,
            COUNT(*) FILTER (WHERE uq.effective_state IN ('GENERATED', 'MANUAL_REMOVED')) AS initial_total_questions,
            COUNT(*) FILTER (WHERE uq.effective_state IN ('AUTO_COMPLETED', 'MANUAL_COMPLETED', 'MISSING')) AS initial_missing_questions,
            COUNT(*) FILTER (WHERE uq.effective_state = 'AUTO_COMPLETED') AS completed_by_system,
            COUNT(*) FILTER (WHERE uq.effective_state = 'MANUAL_COMPLETED') AS completed_manually,
            COUNT(*) FILTER (WHERE uq.effective_state = 'MANUAL_REMOVED') AS manually_removed,
            COUNT(*) FILTER (WHERE uq.effective_state NOT IN ('MISSING', 'MANUAL_REMOVED')) AS current_total_questions,
            COUNT(*) FILTER (WHERE uq.effective_state IN ('MISSING', 'MANUAL_REMOVED')) AS current_missing_questions
        FROM unified_questions uq
        JOIN material m ON m.id = uq.material_id
        JOIN cycle c ON c.id = m.cycle_id
        JOIN type_material tm_root ON tm_root.id = uq.root_type_material_id
        JOIN material_per_period mpp 
            ON mpp.material_id = m.id 
            AND mpp.type_material_id = uq.root_type_material_id
            AND mpp.deleted_at IS NULL
        JOIN material_per_period_ballot mppb 
            ON mppb.material_per_period_id = mpp.id
            AND uq.week BETWEEN mppb.start_week AND mppb.end_week
            AND mppb.deleted_at IS NULL
        LEFT JOIN material_revisions mr 
            ON mr.material_id = m.id
            AND tm_root.id = mr.type_material_id
            AND mppb.start_week = mr.start_week
            AND mppb.end_week = mr.end_week
        GROUP BY 
            m.id, 
            c.id, 
            c.description, 
            tm_root.id, 
            tm_root.description, 
            mppb.start_week, 
            mppb.end_week, 
            mr.status, 
            uq.created_at
    ),
    counted_data AS (
        SELECT *, COUNT(*) OVER () AS total_count
        FROM report_data
    )
    SELECT 
        cd.material_id,
        cd.cycle_id,
        cd.cycle,
        cd.type_material_id,
        cd.type_material_description,
        cd.start_week,
        cd.end_week,
        cd.status,
        cd.created_at,
        cd.initial_total_questions,
        cd.initial_missing_questions,
        cd.completed_by_system,
        cd.completed_manually,
        cd.manually_removed,
        cd.current_total_questions,
        cd.current_missing_questions,
        cd.total_count
    FROM counted_data cd
    ORDER BY cd.created_at DESC, cd.cycle, cd.type_material_description, cd.start_week
    LIMIT p_perpage
    OFFSET v_offset;
END;
$$;


ALTER FUNCTION odiseo.fn_paginate_material_generated(p_perpage integer, p_npage integer, p_company_id integer, p_cycle_id integer, p_type_material_template_id integer, p_start_date date, p_end_date date) OWNER TO postgres;

--
-- Name: fn_paginate_material_questions_detail(integer, integer, jsonb, bigint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_paginate_material_questions_detail(p_perpage integer, p_npage integer, p_courses jsonb, p_employee_id bigint DEFAULT NULL::bigint, p_course_id smallint DEFAULT NULL::smallint) RETURNS TABLE(id bigint, topic_id smallint, topic text, subtopic_id smallint, subtopic text, level_id bigint, level character varying, question_id bigint, question_code character varying, question_status character varying, type_question character varying, status character varying, employee_id bigint, employee character varying, course text, course_id smallint, request_date timestamp without time zone, total bigint)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    offset_val integer;
BEGIN
    offset_val := p_perpage * (p_npage - 1);

    RETURN QUERY
    WITH filtered_data AS (
        SELECT
            mmqd.id,
            mdbq.topic_id,
            CONCAT_WS(' - ', t.code, t."name") topic,
            mdbq.subtopic_id,
            CONCAT_WS(' - ', s.code, s."name") subtopic,
            mdbq.level_id,
            l.name level,
            q.id question_id,
            q.code question_code,
            q.status question_status,
            mdbq.type type_question,
            mmqd.status,
            mmqd.employee_id,
            TRIM(CONCAT_WS(' ', e.first_name, e.first_surname, e.second_surname))::character varying AS employee,
            CONCAT_WS(' - ', c.code, c."name") course,
            c.id course_id,
            mmq.request_date
        FROM
            material_missing_question_detail mmqd
            JOIN material_missing_question mmq ON mmq.id = mmqd.material_missing_question_id
            JOIN material_ballot_question mdbq ON mdbq.id = mmqd.material_ballot_question_id
            JOIN topic t ON t.id = mdbq.topic_id
            JOIN subtopic s ON s.id = mdbq.subtopic_id
            JOIN "level" l ON l.id = mdbq.level_id
            JOIN course c ON c.id = mdbq.course_id
            LEFT JOIN question q ON q.id = mmqd.question_id
            LEFT JOIN employees e ON e.id = mmqd.employee_id
        WHERE
            (p_employee_id IS NULL OR mmqd.employee_id = p_employee_id)
            AND mdbq.course_id = ANY (
                SELECT (jsonb_array_elements_text(p_courses))::SMALLINT
            )
            AND mmqd.deleted_at IS NULL
        ORDER BY
            mmq.request_date,
            mdbq.topic_id,
            mdbq.subtopic_id,
            mdbq.level_id,
            mmqd.id DESC
    ),
    data_with_total AS (
        SELECT
            fd.id,
            fd.topic_id,
            fd.topic,
            fd.subtopic_id,
            fd.subtopic,
            fd.level_id,
            fd.level,
            fd.question_id,
            fd.question_code,
            fd.question_status,
            fd.type_question,
            fd.status,
            fd.employee_id,
            fd.employee,
            fd.course,
            fd.course_id,
            fd.request_date,
            COUNT(*) OVER () AS total
        FROM
            filtered_data fd
        WHERE (p_course_id IS NULL OR fd.course_id = p_course_id)
    )
    SELECT
        *
    FROM
        data_with_total
    LIMIT p_perpage OFFSET offset_val;
END;
$$;


ALTER FUNCTION odiseo.fn_paginate_material_questions_detail(p_perpage integer, p_npage integer, p_courses jsonb, p_employee_id bigint, p_course_id smallint) OWNER TO postgres;

--
-- Name: fn_paginate_material_revision_questions(integer, integer, integer, character varying, integer, integer, integer, integer, integer, integer, character varying, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_paginate_material_revision_questions(p_detail_course_id integer, p_per_page integer, p_page integer, p_search character varying DEFAULT NULL::character varying, p_topic_id integer DEFAULT NULL::integer, p_subtopic_id integer DEFAULT NULL::integer, p_week integer DEFAULT NULL::integer, p_university_id integer DEFAULT NULL::integer, p_option_id integer DEFAULT NULL::integer, p_modality_id integer DEFAULT NULL::integer, p_year character varying DEFAULT NULL::character varying, p_version integer DEFAULT NULL::integer) RETURNS TABLE(detail_course_id bigint, material_ballot_question_id bigint, question_id bigint, type_material character varying, level smallint, code character varying, type character varying, status character varying, topic_code character varying, subtopic_code character varying, topic character varying, subtopic character varying, origin_question jsonb, updated_at timestamp without time zone, week smallint, amount_questions_changed smallint, reason text, correlative text, total bigint)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_offset INTEGER;
BEGIN
    v_offset := p_per_page * (p_page - 1);

    RETURN QUERY
    WITH all_week_type_material AS (
        SELECT 
            mrc.id AS detail_course_id,
            mri.detail_week_type_mat_id, 
            mrc.course_id,
            mrc.amount_questions_changed
        FROM material_revision_courses mrc
        JOIN material_revisions mr ON mr.id = mrc.material_revision_id 
        JOIN material_revision_items mri ON mri.material_revision_id = mr.id
        WHERE mrc.id = p_detail_course_id
    ),
    filtered_questions AS (
        SELECT 
            awtm.detail_course_id,
            mbq.id AS material_ballot_question_id,
            mbq.question_id,
            tm.description AS type_material,
            l.name::smallint AS level,
            q.code,
            q.type,
            q.status,
            t.code AS topic_code,
            s.code AS subtopic_code,
            t.name AS topic,
            s.name AS subtopic,
            mbq.updated_at,
            dwtm.week::smallint,
            m.university_id AS material_university_id,
            awtm.amount_questions_changed,
            mqcr.reason,
            CONCAT_WS('-', UPPER(LEFT(tm.description, 4)), mbq.position + 1) AS correlative
        FROM material_ballot_question mbq
        JOIN all_week_type_material awtm ON awtm.detail_week_type_mat_id = mbq.week_type_material_id AND awtm.course_id = mbq.course_id
        JOIN question q ON q.id = mbq.question_id
        JOIN detail_week_type_mat dwtm ON dwtm.id = mbq.week_type_material_id
        JOIN type_material tm ON tm.id = dwtm.type_material_id
        JOIN material m ON m.id = dwtm.material_id
        LEFT JOIN "level" l ON l.id = mbq.level_id
        LEFT JOIN topic t ON t.id = mbq.topic_id
        LEFT JOIN subtopic s ON s.id = mbq.subtopic_id
        LEFT JOIN material_question_change_reason mqcr ON mqcr.material_ballot_question_id = mbq.id AND mqcr.material_revision_course_id = awtm.detail_course_id
        WHERE mbq.fl_status = true
        AND (p_topic_id IS NULL OR mbq.topic_id = p_topic_id)
        AND (p_subtopic_id IS NULL OR mbq.subtopic_id = p_subtopic_id)
        AND (p_week IS NULL OR dwtm.week = p_week)
        AND (p_search IS NULL OR q.code ILIKE '%' || p_search || '%')
        AND (
            p_university_id IS NULL AND p_option_id IS NULL AND p_modality_id IS NULL AND p_version IS NULL AND p_year IS NULL 
            OR EXISTS (
                SELECT 1
                FROM v_all_question_origins_by_university vq
                WHERE vq.question_id = mbq.question_id
                AND vq.university_id = m.university_id
                AND (p_university_id IS NULL OR vq.university_id = p_university_id)
                AND (p_option_id IS NULL OR vq.option_id = p_option_id)
                AND (p_modality_id IS NULL OR vq.modality_id = p_modality_id)
                AND (p_version IS NULL OR vq.version::integer = p_version)
                AND (p_year IS NULL OR vq.year = p_year)
            )
        )
        ORDER BY dwtm.week, LEFT(tm.description, 1), mbq.position
    )
    SELECT
        fq.detail_course_id,
        fq.material_ballot_question_id,
        fq.question_id,
        fq.type_material,
        fq.level,
        fq.code,
        fq.type,
        fq.status,
        fq.topic_code,
        fq.subtopic_code,
        fq.topic,
        fq.subtopic,
        (
            SELECT vo.question_origin
            FROM v_all_question_origins_by_university vo
            WHERE vo.question_id = fq.question_id 
            AND vo.university_id = fq.material_university_id
            LIMIT 1
        ) AS origin_question,
        fq.updated_at,
        fq.week,
        fq.amount_questions_changed,
        fq.reason,
        fq.correlative,
        COUNT(*) OVER() AS total 
    FROM filtered_questions fq
    LIMIT p_per_page OFFSET v_offset;
END;
$$;


ALTER FUNCTION odiseo.fn_paginate_material_revision_questions(p_detail_course_id integer, p_per_page integer, p_page integer, p_search character varying, p_topic_id integer, p_subtopic_id integer, p_week integer, p_university_id integer, p_option_id integer, p_modality_id integer, p_year character varying, p_version integer) OWNER TO postgres;

--
-- Name: fn_paginate_type_materials(integer, integer, character varying, bigint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_paginate_type_materials(p_perpage integer, p_npage integer, p_search character varying, p_company_id bigint, p_type_material_template_id bigint DEFAULT NULL::bigint, p_cycle_id bigint DEFAULT NULL::bigint) RETURNS TABLE(id bigint, code character varying, description character varying, amount_question integer, fl_status boolean, areas jsonb, cycle_id bigint, name_cycle character varying, fl_exam boolean, fl_class_material boolean, childrens jsonb, thread smallint, percentage numeric, type_material_template_id bigint, total bigint)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_offset INTEGER;
    v_tmt_name_1 TEXT;
    v_tmt_name_2 TEXT;
    v_tmt_name_3 TEXT;
BEGIN
    -- Obtener nombres de plantillas para el ordenamiento lógico
    SELECT tmt.name INTO v_tmt_name_1 FROM type_material_template tmt WHERE tmt.id = 1;
    SELECT tmt.name INTO v_tmt_name_2 FROM type_material_template tmt WHERE tmt.id = 2;
    SELECT tmt.name INTO v_tmt_name_3 FROM type_material_template tmt WHERE tmt.id = 3;

    v_offset := p_perpage * (p_npage - 1);

    RETURN QUERY
    WITH tbl_type_material_base AS (
        SELECT
            coalesce(t.parent_id, t.id) AS id,
            MAX(coalesce(tp.code, t.code))::VARCHAR AS code,
            MAX(coalesce(tp.description, t.description))::VARCHAR AS description,
            MAX(coalesce(tp.amount_question, t.amount_question)) AS amount_question,
            COALESCE(BOOL_OR(tp.fl_status), FALSE) AS fl_status,
            jsonb_agg(DISTINCT jsonb_build_object('area_id', tma.area_id, 'description', a.description))::JSONB AS areas,
            MAX(coalesce(tp.cycle_id, t.cycle_id)) AS cycle_id,
            MAX(c.description)::VARCHAR AS name_cycle,
            COALESCE(BOOL_OR(tp.fl_exam), FALSE) AS fl_exam,
            COALESCE(BOOL_OR(tp.fl_class_material), FALSE) AS fl_class_material,
            jsonb_agg(DISTINCT jsonb_build_object(
                'material_id', t.id,
                'amount', t.amount_question,
                'name', t.description
            )) FILTER (WHERE t.parent_id IS NOT NULL)::JSONB AS childrens,
            MAX(COALESCE(tp.thread, t.thread))::SMALLINT AS thread,
            MAX(COALESCE(tp.percentage, t.percentage))::NUMERIC AS percentage,
            MAX(COALESCE(tp.type_material_template_id, t.type_material_template_id)) AS type_material_template_id
        FROM type_material t
        LEFT JOIN type_material_area tma ON tma.type_material_id = t.id
        LEFT JOIN exam_area a ON a.id = tma.area_id
        JOIN cycle c ON t.cycle_id = c.id AND c.fl_status = true
        LEFT JOIN type_material tp ON tp.id = t.parent_id
        WHERE t.fl_status = true
          AND c.active IS TRUE
          AND (p_search IS NULL OR (t.code ILIKE '%' || p_search || '%' OR t.description ILIKE '%' || p_search || '%'))
          AND (p_cycle_id IS NULL OR t.cycle_id = p_cycle_id)
          AND t.company_id = p_company_id
        GROUP BY coalesce(t.parent_id, t.id)
    ),
    filtered_materials AS (
        SELECT * FROM tbl_type_material_base ttmb
        WHERE (p_type_material_template_id IS NULL OR ttmb.type_material_template_id = p_type_material_template_id)
    ),
    paginated_results AS (
        SELECT *, COUNT(*) OVER() AS total_count
        FROM filtered_materials fm
        ORDER BY
            fm.cycle_id DESC,
            CASE
                WHEN fm.description = v_tmt_name_1 THEN 0
                WHEN fm.description = v_tmt_name_2 THEN 1
                WHEN fm.description = v_tmt_name_3 THEN 2
                ELSE 3
            END,
            fm.description ASC
        LIMIT p_perpage
        OFFSET v_offset
    )
    SELECT 
        pr.id, pr.code, pr.description, pr.amount_question, pr.fl_status,
        pr.areas, pr.cycle_id, pr.name_cycle, pr.fl_exam, pr.fl_class_material, pr.childrens, 
        pr.thread, pr.percentage, pr.type_material_template_id, pr.total_count 
    FROM paginated_results pr;
END;
$$;


ALTER FUNCTION odiseo.fn_paginate_type_materials(p_perpage integer, p_npage integer, p_search character varying, p_company_id bigint, p_type_material_template_id bigint, p_cycle_id bigint) OWNER TO postgres;

--
-- Name: fn_params_index(bigint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_params_index(p_question_id bigint, p_subtopic_id smallint DEFAULT NULL::smallint) RETURNS TABLE(id bigint, course_id smallint, code_course character varying, course character varying, topic_id smallint, code_topic character varying, topic character varying, subtopics jsonb, level_id smallint, level character varying, type character varying, ter numeric, type_question text, status character varying, type_text_template_id smallint, type_text_template_name character varying, description_text character varying, description_subquestion character varying, text_attributes character varying, subquestion_attributes character varying, question_attributes jsonb, shared_status text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH context_data AS (
        SELECT
            q.id AS question_id,
            COALESCE(qsh.course_id, q.course_id) AS course_id,
            COALESCE(qsh.topic_id, q.topic_id) AS topic_id,
            qsh.subtopic_id,
            (qsh.id IS NOT NULL) AS has_share
        FROM question q
        LEFT JOIN question_shares qsh 
            ON qsh.question_id = q.id 
            AND qsh.subtopic_id = p_subtopic_id 
            AND qsh.deleted_at IS NULL
        WHERE q.id = p_question_id
    ),

    course_question AS (
        SELECT
            cd.course_id,
            CASE WHEN q.parent_id IS NULL THEN 'P' ELSE 'S' END AS type
        FROM context_data cd
        JOIN question q ON q.id = cd.question_id
    ),

    attributes_course AS (
        SELECT
            qatc.course_id,
            qat.id AS question_attribute_type_id,
            qat.name,
            qatv.label,
            qatv.description,
            qatv.value
        FROM question_attributes_type_course qatc
        JOIN course_question cq ON cq.course_id = qatc.course_id
        JOIN question_attributes_type qat 
            ON qatc.question_attributes_type_id = qat.id
            AND qat.deleted_at IS NULL
        LEFT JOIN question_attributes qa 
            ON qatc.id = qa.question_attributes_type_id
            AND qa.deleted_at IS NULL
            AND qa.question_id = p_question_id
        LEFT JOIN question_attributes_types_values qatv 
            ON qat.id = qatv.question_attributes_type_id
            AND qatv.deleted_at IS NULL
            AND qatv.value = qa.value
        WHERE qatc.types_questions ILIKE '%' || cq.type || '%'
          AND qatc.deleted_at IS NULL
    )

    SELECT
        q.id,
        cd.course_id::SMALLINT,
        c.code AS code_course,
        c.name AS course,
        cd.topic_id::SMALLINT,
        t.code AS code_topic,
        t.name AS topic,

        CASE 
            WHEN cd.has_share THEN
                JSONB_BUILD_ARRAY(
                    JSONB_BUILD_OBJECT(
                        'subtopic_id', s_override.id,
                        'code_subtopic', s_override.code,
                        'subtopic', s_override.name
                    )
                )
            ELSE
                COALESCE(
                    JSONB_AGG(
                        DISTINCT JSONB_BUILD_OBJECT (
                            'subtopic_id', qs.subtopic_id,
                            'code_subtopic', s.code,
                            'subtopic', s.name
                        )
                    ) FILTER (WHERE qs.subtopic_id IS NOT NULL), '[]'
                )
        END AS subtopics,

        q.level_id,
        l.description AS level,
        q.type,
        q.ter,

        CASE WHEN q.parent_id IS NOT NULL THEN 'S' ELSE 'P' END AS type_question,

        q.status,

        c.type_text_template_id,
        ttt.name,
        ttt.description_text,
        ttt.description_subquestion,
        ttt.text_attributes,
        ttt.subquestion_attributes,

        COALESCE(
            JSONB_AGG(
                DISTINCT JSONB_BUILD_OBJECT (
                    'question_attribute_type_id', ac.question_attribute_type_id,
                    'name', ac.name,
                    'label', ac.label,
                    'description', ac.description,
                    'value', ac.value
                )
            ) FILTER (WHERE ac.question_attribute_type_id IS NOT NULL), '[]'
        ) AS question_attributes,
        CASE 
            WHEN cd.has_share THEN get_shared_status(q.id, cd.subtopic_id)
            ELSE get_shared_status(q.id, qs.subtopic_id)
        END AS shared_status
    FROM context_data cd
    JOIN question q ON q.id = cd.question_id

    LEFT JOIN course c ON c.id = cd.course_id
    LEFT JOIN topic t ON t.id = cd.topic_id
    LEFT JOIN level l ON l.id = q.level_id

    LEFT JOIN question_subtopic qs 
        ON q.id = qs.question_id 
        AND qs.fl_status = true
        AND cd.has_share = false

    LEFT JOIN subtopic s ON s.id = qs.subtopic_id
    LEFT JOIN subtopic s_override ON s_override.id = cd.subtopic_id

    LEFT JOIN type_text_templates ttt ON ttt.id = c.type_text_template_id

    LEFT JOIN attributes_course ac ON ac.course_id = cd.course_id

    GROUP BY 
        q.id,
        cd.course_id,
        c.code,
        c.name,
        cd.topic_id,
        t.code,
        t.name,
        l.description,
        c.type_text_template_id,
        ttt.id,
        cd.has_share,
        s_override.id,
        s_override.code,
        qs.subtopic_id,
        cd.subtopic_id,
        s_override.name;
END;
$$;


ALTER FUNCTION odiseo.fn_params_index(p_question_id bigint, p_subtopic_id smallint) OWNER TO postgres;

--
-- Name: fn_parent_question_detail(); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_parent_question_detail() RETURNS TABLE(id bigint, code character varying, course_id smallint, status character varying, fl_status boolean, questions json)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    pq.id,
                    pq.code,
					pq.course_id,
                    pq.status,
                    pq.fl_status,
                    CASE
                        WHEN count(q.id) > 0 THEN json_agg(q.* ORDER BY
                            CASE
                                WHEN q.type_material_id = 3 THEN 1
                                WHEN q.type_material_id = 2 THEN 2
                                WHEN q.type_material_id = 1 THEN 3
                                WHEN q.type_material_id IS NOT NULL THEN 4
                                ELSE 5
                            END,
                            q.type_material_id ASC,
                            q.id ASC
                        )
                        ELSE '[]'::json
                    END AS questions
                FROM odiseo.parent_question pq
                LEFT JOIN (
                    SELECT q.id, q.code, q.course_id, q.status, q.parent_id, q.fl_status, qt.type_material_id, t.description
                    FROM odiseo.question q
					LEFT JOIN odiseo.question_temporary qt ON qt.question_id = q.id
					LEFT JOIN odiseo.type_material t ON qt.type_material_id = t.id
                    WHERE q.status IN ('SASI', 'DUPL')
                    AND q.fl_status IS TRUE
                    AND (
                        q.number_question IS NULL OR
                        q.number_question NOT ILIKE 'D%'
                    )
                ) q ON pq.id = q.parent_id
                WHERE pq.fl_status IS TRUE
                AND pq.status IN ('SASI', 'ASIG')
                AND (
                    pq.number_question IS NULL OR
                    pq.number_question NOT ILIKE 'D%'
                )
                GROUP BY
                    pq.id,
                    pq.code,
					pq.course_id,
                    pq.status,
                    pq.fl_status
                HAVING jsonb_array_length(CASE
                    WHEN count(q.id) > 0 THEN json_agg(q.*)::jsonb
                    ELSE '[]'::jsonb
                    END) <> 0
                ORDER BY pq.id ASC;
            END;
            $$;


ALTER FUNCTION odiseo.fn_parent_question_detail() OWNER TO postgres;

--
-- Name: fn_parent_question_detail_index(); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_parent_question_detail_index() RETURNS TABLE(id bigint, code character varying, course_id smallint, status character varying, fl_status boolean, employee_id bigint, questions json)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        SELECT
            pq.id,
            pq.code,
            pq.course_id,
            pq.status,
            pq.fl_status,
            e.id as employee_id,
            json_agg(q.*) AS questions
        FROM parent_question pq
        JOIN (
            SELECT q.id, q.code, q.course_id, q.status, q.parent_id, q.fl_status
            FROM question q
            WHERE q.status = 'INDE' AND q.fl_status IS TRUE
        ) q ON pq.id = q.parent_id
        JOIN users u
            ON u.id = pq.created_by 
        JOIN employees e
            ON e.user_id  = u.id
        WHERE pq.fl_status IS TRUE
        AND pq.status IN ('INDE')
        AND NOT EXISTS (
            SELECT 1
            FROM question q2
            WHERE q2.parent_id = pq.id
                AND q2.status != 'INDE'
                AND q2.fl_status IS TRUE
        )
        GROUP BY
            pq.id,
            pq.code,
            pq.course_id,
            u.id ,
            e.id,
            pq.status,
            pq.fl_status
        HAVING jsonb_array_length(json_agg(q.*)::jsonb) > 0
        ORDER BY pq.id ASC;
    END;
    $$;


ALTER FUNCTION odiseo.fn_parent_question_detail_index() OWNER TO postgres;

--
-- Name: fn_parent_question_verified_material(bigint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_parent_question_verified_material(p_material_id bigint, p_type_question character varying) RETURNS TABLE(subquestion jsonb, parent_id bigint, category_id bigint, category character varying, subcategory_id bigint, subcategory character varying, level_id bigint, course_id smallint, history jsonb, code character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH tbl_material AS ( -- Obtener ciclo y universidad del material mandado
        SELECT
            m.university_id
        FROM material m
        WHERE m.id = p_material_id
    ), tbl_questions_ballot_material AS ( -- Se lista las preguntas de la tabla de balotarios
        SELECT DISTINCT mbq.parent_question_id FROM material m
        INNER JOIN detail_week_type_mat wt ON m.id = wt.material_id AND wt.fl_status = true
        INNER JOIN material_ballot_question mbq ON wt.id = mbq.week_type_material_id AND mbq.fl_status = true
        WHERE m.id = p_material_id
    ), max_start_per_question AS ( -- Se lista la fecha de inicio más reciente para cada pregunta
        SELECT
            qh.parent_question_id,
            MAX(c.start_date) AS max_start_date
        FROM question_history_cycle qh
        INNER JOIN cycle c ON qh.cycle_id = c.id
        WHERE qh.fl_status = true
        AND qh.university_id = (SELECT tm.university_id FROM tbl_material tm)
        GROUP BY qh.parent_question_id
    ), tbl_questions_history AS ( -- Se trae le historial de cada pregunta
        SELECT DISTINCT
            qh.parent_question_id,
            qh.cycle_id,
            c.description,
            c.start_date,
            c.end_date
        FROM question_history_cycle qh
        INNER JOIN cycle c ON qh.cycle_id = c.id
        INNER JOIN max_start_per_question mx ON qh.parent_question_id = mx.parent_question_id
        WHERE qh.fl_status = true
        AND qh.university_id = (SELECT tm.university_id FROM tbl_material tm)
        -- AND c.start_date BETWEEN mx.max_start_date - INTERVAL '21 days' AND mx.max_start_date
    ), 	cte_question_verified AS (
        SELECT
            pq.id AS parent_id,
            q.id question_id,
            ROW_NUMBER () OVER (
                PARTITION BY
                    q.parent_id,
                    CASE
                        WHEN q.status = 'APRB' THEN 'VERI'
                        ELSE q.status
                    END
            ) AS total_veri,
            pq.type_text_id,
            pq.type_text_subcategory_id,
            pq.level_id,
            pq.course_id,
            pq.code,
            tt.name category,
            tts.name subcategory
        FROM parent_question pq
        JOIN question q ON q.parent_id = pq.id
        JOIN type_text tt ON tt.id = pq.type_text_id
        JOIN type_text_subcategories tts ON tts.id = pq.type_text_subcategory_id
        WHERE q.status IN ('VERI', 'APRB')
        AND pq.status NOT IN ('ARCH', 'DUPL')
        ORDER BY pq.id
    ), cte_validate_min_verified AS (
    SELECT
        cqv.parent_id,
        cqv.type_text_id category_id,
        cqv.type_text_subcategory_id subcategory_id,
        cqv.level_id,
        cqv.course_id,
        cqv.code,
        cqv.category,
        cqv.subcategory
    FROM cte_question_verified cqv
    WHERE cqv.total_veri >= 2
    AND cqv.type_text_id IS NOT NULL
    AND cqv.type_text_subcategory_id IS NOT NULL
    GROUP BY
    cqv.parent_id,
    cqv.type_text_id,
    cqv.type_text_subcategory_id,
    cqv.level_id,
    cqv.course_id,
    cqv.code,
    cqv.category,
    cqv.subcategory
    ), subtopics_agg AS (
        SELECT
            qs.question_id,
            JSONB_AGG(JSONB_BUILD_OBJECT('id', qs.subtopic_id)) AS subtopics_json
        FROM question_subtopic qs
        WHERE qs.fl_status = true
        GROUP BY qs.question_id
    ), history_agg AS (
        SELECT
            qh.parent_question_id,
            JSONB_AGG(
                JSONB_BUILD_OBJECT(
                    'cycle_id', qh.cycle_id,
                'description', qh.description,
                'start_date', qh.start_date,
                'end_date', qh.end_date
                )
                ORDER BY qh.start_date DESC
            ) AS history_json
        FROM tbl_questions_history qh
        WHERE qh.cycle_id IS NOT NULL
        GROUP BY qh.parent_question_id
    )
    SELECT
        JSONB_AGG(
            JSONB_BUILD_OBJECT(
                'code', q.code,
                'question_id', q.id,
                'topic_id', q.topic_id,
                'code_topic', t.code,
                'course_id', q.course_id,
                'level_id', q.level_id,
                'subtopics', COALESCE(sa.subtopics_json, '[]'::jsonb)
            )
            ORDER BY q.course_id, t.code
        ) AS subquestion,
        cvmv.parent_id,
        cvmv.category_id,
        cvmv.category,
        cvmv.subcategory_id,
        cvmv.subcategory,
        cvmv.level_id,
        cvmv.course_id,
        COALESCE(ha.history_json, '[]'::jsonb) AS history,
        cvmv.code
    FROM cte_validate_min_verified cvmv
    JOIN question q ON q.parent_id = cvmv.parent_id
    JOIN topic t ON q.topic_id = t.id
    LEFT JOIN subtopics_agg sa ON q.id = sa.question_id
    LEFT JOIN history_agg ha ON q.parent_id = ha.parent_question_id
    WHERE q.status IN ('VERI', 'APRB')
    AND NOT EXISTS (
        SELECT 1
        FROM tbl_questions_ballot_material gpm
        WHERE
        CASE
            WHEN p_type_question = 'T' THEN gpm.parent_question_id = q.parent_id
            ELSE FALSE
        END
    )
    GROUP BY
        cvmv.parent_id,
        cvmv.category_id,
        cvmv.subcategory_id,
        cvmv.level_id,
        cvmv.course_id,
        cvmv.code,
        cvmv.category,
        cvmv.subcategory,
        ha.history_json;

    END;
    $$;


ALTER FUNCTION odiseo.fn_parent_question_verified_material(p_material_id bigint, p_type_question character varying) OWNER TO postgres;

--
-- Name: fn_permissions(integer, integer, integer, boolean, boolean, character varying, integer, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_permissions(p_perpage integer, p_npage integer, f_permission_id integer, p_administrator boolean, f_status boolean, p_name_text character varying, p_company_id integer, p_can_filter_companies boolean) RETURNS TABLE(id bigint, name character varying, fl_status boolean, created_by bigint, updated_by bigint, deleted_by bigint, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone, module character varying, fl_administrator boolean, roles json, user_name character varying, user_email odiseo.email_citext, total integer)
    LANGUAGE plpgsql
    AS $$
                        DECLARE
                            total_count INTEGER;
                            offset_val INTEGER;
                        BEGIN
                            offset_val := p_perpage * (p_npage - 1);

                           SELECT COUNT(*)
                            INTO total_count
                            FROM permissions p
                            LEFT JOIN users u ON p.created_by = u.id
                            WHERE 1 = 1
                            AND p.fl_status = f_status
                            AND (f_permission_id IS NULL OR p.id = f_permission_id)
                            AND (p_name_text IS NULL OR LOWER(p.name) LIKE '%' || LOWER(p_name_text) || '%');

                            RETURN QUERY
                            SELECT
                                p.id,
                                p.name,
                                p.fl_status,
                                p.created_by,
                                p.updated_by,
                                p.deleted_by,
                                p.created_at,
                                p.updated_at,
                                p.deleted_at,
                                p.module,
                                p.fl_administrator,
                                COALESCE(json_agg(r.*) FILTER (WHERE r.id IS NOT NULL), '[]'::json) AS roles,
                                u.user as user_name,
                                u.email as user_email,
                                total_count AS total
                            FROM permissions p
                            LEFT JOIN (
                                SELECT rp.id, rp.rol_id, rp.permission_id, rp.fl_status
                                FROM roles_permissions rp
                                WHERE rp.fl_status = true
                            ) rp ON p.id = rp.permission_id 
                            LEFT JOIN (
                                SELECT r.id, r.name, r.slug, r.fl_status, r.fl_administrator
                                FROM roles r
                                WHERE r.fl_status = true
                                AND r.company_id = p_company_id
                            ) r ON rp.rol_id = r.id
                            LEFT JOIN users u ON p.created_by = u.id
                            WHERE 1 = 1
                            AND p.fl_status = f_status
                            AND (p_administrator = true OR p.fl_administrator = false)
                            AND (f_permission_id IS NULL OR p.id = f_permission_id)
                            AND (p_name_text IS NULL OR LOWER(p.name) LIKE '%' || LOWER(p_name_text) || '%')
                            AND (p_can_filter_companies = true OR p.fl_to_use_client = true)
                            GROUP BY
                                p.id,
                                p.name,
                                p.fl_status,
                                p.created_by,
                                p.updated_by,
                                p.deleted_by,
                                p.created_at,
                                p.updated_at,
                                p.deleted_at,
                                p.module,
                                p.fl_administrator,
                                u.user,
                                u.email
                            ORDER BY p.id ASC
                            LIMIT p_perpage
                            OFFSET offset_val;
                        END;
                        $$;


ALTER FUNCTION odiseo.fn_permissions(p_perpage integer, p_npage integer, f_permission_id integer, p_administrator boolean, f_status boolean, p_name_text character varying, p_company_id integer, p_can_filter_companies boolean) OWNER TO postgres;

--
-- Name: fn_permissions_all(boolean, boolean, character varying, integer, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_permissions_all(p_administrator boolean, f_status boolean, p_name_text character varying, p_company_id integer, p_can_filter_companies boolean) RETURNS TABLE(id bigint, name character varying, fl_status boolean, created_by bigint, updated_by bigint, deleted_by bigint, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone, module character varying, fl_administrator boolean, roles json, user_name character varying, user_email odiseo.email_citext)
    LANGUAGE plpgsql
    AS $$
                        BEGIN

                           RETURN QUERY
                            SELECT
                                p.id,
                                p.name,
                                p.fl_status,
                                p.created_by,
                                p.updated_by,
                                p.deleted_by,
                                p.created_at,
                                p.updated_at,
                                p.deleted_at,
                                p.module,
                                p.fl_administrator,
                                COALESCE(json_agg(r.*) FILTER (WHERE r.id IS NOT NULL), '[]'::json) AS roles,
                                u.user as user_name,
                                u.email as user_email
                            FROM permissions p
                            LEFT JOIN (
                                SELECT rp.id, rp.rol_id, rp.permission_id, rp.fl_status
                                FROM roles_permissions rp
                                WHERE rp.fl_status = true
                            ) rp ON p.id = rp.permission_id
                            LEFT JOIN (
                                SELECT r.id, r.name, r.slug, r.fl_status, r.fl_administrator,r.company_id
                                FROM roles r
                                WHERE r.fl_status = true
                            ) r ON rp.rol_id = r.id AND r.company_id = p_company_id
                            LEFT JOIN users u ON p.created_by = u.id
                            WHERE p.fl_status = f_status
                            AND (p_administrator = true OR p.fl_administrator = false)
                            AND (p_name_text IS NULL OR LOWER(p.name) LIKE '%' || LOWER(p_name_text) || '%')
                            AND (p_can_filter_companies = true OR p.fl_to_use_client = true)
                            GROUP BY
                                p.id,
                                p.name,
                                p.fl_status,
                                p.created_by,
                                p.updated_by,
                                p.deleted_by,
                                p.created_at,
                                p.updated_at,
                                p.deleted_at,
                                p.module,
                                p.fl_administrator,
                                u.user,
                                u.email
                            ORDER BY p.id ASC;
                        END;
                        $$;


ALTER FUNCTION odiseo.fn_permissions_all(p_administrator boolean, f_status boolean, p_name_text character varying, p_company_id integer, p_can_filter_companies boolean) OWNER TO postgres;

