--
-- Name: fn_process_change_subtopic_frequent(integer, integer, integer, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_process_change_subtopic_frequent(p_question_id integer, p_new_subtopic_id integer, p_user_id integer, p_method_origin character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
                                DECLARE
                                    v_old_subtopic_id INT;
                                    v_is_subtopic_equal BOOLEAN;
                                    rec RECORD;
                                BEGIN
                                    SELECT qs.subtopic_id 
                                    INTO v_old_subtopic_id
                                    FROM question q
                                    LEFT JOIN question_subtopic qs ON qs.question_id = q.id AND qs.fl_status = true
                                    WHERE q.id = p_question_id
                                    LIMIT 1;

                                    v_is_subtopic_equal := (COALESCE(v_old_subtopic_id, -1) = COALESCE(p_new_subtopic_id, -1));

                                    IF NOT v_is_subtopic_equal THEN
                                        UPDATE frequent_university_subtopic fus
                                        SET fl_status = false,
                                            is_frequent = false
                                        FROM origin_question oq
                                        JOIN modality_options mo ON mo.id = oq.modality_option_id AND mo.deleted_at IS NULL
                                        JOIN option_university ou ON ou.university_id = oq.university_id AND ou.deleted_at IS NULL
                                        WHERE oq.question_id = p_question_id
                                        AND oq.fl_status = true
                                        AND fus.university_id = ou.university_id
                                        AND fus.subtopic_id = v_old_subtopic_id;
                                    END IF;

                                    FOR rec IN 
                                        SELECT DISTINCT ou.university_id
                                        FROM origin_question oq
                                        JOIN question q ON oq.question_id = q.id
                                        JOIN modality_options mo ON mo.id = oq.modality_option_id AND mo.deleted_at IS NULL
                                        JOIN option_university ou ON ou.university_id = oq.university_id AND ou.deleted_at IS NULL
                                        WHERE oq.question_id = p_question_id
                                        AND oq.fl_status = true
                                        AND q.fl_status = true
                                    LOOP
                                        PERFORM fn_change_subtopic_frequent_status(
                                            rec.university_id::int,
                                            p_new_subtopic_id::int,
                                            p_user_id::int,
                                            TRUE,
                                            p_method_origin
                                        );
                                    END LOOP;

                                END;
                                $$;


ALTER FUNCTION odiseo.fn_process_change_subtopic_frequent(p_question_id integer, p_new_subtopic_id integer, p_user_id integer, p_method_origin character varying) OWNER TO postgres;

--
-- Name: fn_process_material_ballot_by_courses(bigint, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_process_material_ballot_by_courses(p_material_per_period_ballot_id bigint, p_courses jsonb) RETURNS TABLE(course_id smallint, detail_ids jsonb, week smallint, questions jsonb)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        WITH details_weeks AS (
            SELECT dw.week, dw.detail_ids
            FROM fn_get_available_weeks_per_period(p_material_per_period_ballot_id) dw
        ), courses_generate_material AS (
            SELECT DISTINCT
                mbq.course_id
            FROM detail_week_type_mat dwtm
            JOIN details_weeks dw
                ON dwtm.id = ANY (
                    SELECT value::BIGINT
                    FROM jsonb_array_elements_text(dw.detail_ids::jsonb) value
                )
            JOIN material_ballot_question mbq ON dwtm.id = mbq.week_type_material_id
                AND mbq.fl_status = true
        ), courses AS (
            SELECT
                cgm.course_id
            FROM courses_generate_material cgm
            WHERE (p_courses IS NULL OR
                cgm.course_id = ANY (
                    SELECT value::SMALLINT FROM jsonb_array_elements_text(p_courses::jsonb)
                )
            )
        )
        SELECT
            c.course_id,
            d.detail_ids,
            d.week,
            q.questions
        FROM courses c
        CROSS JOIN details_weeks d
        CROSS JOIN LATERAL (
            SELECT jsonb_agg(row_to_json(t)) AS questions
            FROM fn_question_material_ballot_pdf(
                d.detail_ids::jsonb,
                c.course_id::int2
            ) t
        ) q;
    END;
    $$;


ALTER FUNCTION odiseo.fn_process_material_ballot_by_courses(p_material_per_period_ballot_id bigint, p_courses jsonb) OWNER TO postgres;

--
-- Name: fn_process_material_class_week(bigint, smallint, smallint, smallint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_process_material_class_week(p_material_id bigint, p_type_material_id smallint, p_type_material_template_id smallint, p_week smallint, p_cycle_id bigint, p_created_by bigint) RETURNS TABLE(id bigint, material_id bigint, type_material_id smallint, type_material character varying, week_type_material_ids character varying, week smallint, course_id smallint, code_course character varying, name_course character varying, fl_process_status smallint, url_material_class character varying, job_id character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_type_material_id SMALLINT[];
    v_type_material_validate_id SMALLINT[];
    v_detail_week_type_mat_id BIGINT[];
    v_course_id SMALLINT;
    v_material_class_week_id BIGINT;
    v_count_course BIGINT;
BEGIN
    IF p_type_material_template_id IS NOT NULL THEN
        -- Buscar hijos del tipo material
        SELECT ARRAY(
            SELECT tm.id FROM type_material_bound tmb
            INNER JOIN type_material_template tmt ON tmb.type_material_template_extra_id = tmt.id
            INNER JOIN type_material tm ON tmt.id = tm.type_material_template_id
            WHERE tmb.type_material_template_id = p_type_material_template_id
            AND tm.cycle_id = p_cycle_id
        ) INTO v_type_material_id;
    END IF;

    -- Validar si el tipo de material es un tipo de material padre
    IF array_length(v_type_material_id, 1) IS NULL THEN
        SELECT ARRAY(SELECT tm.id FROM type_material tm WHERE tm.id = p_type_material_id) INTO v_type_material_id;
    END IF;

    -- Traer los materiales validados // Por ahora no hace nada
    SELECT ARRAY(
        SELECT dwtm.type_material_id
        FROM detail_week_type_mat dwtm
        WHERE dwtm.material_id = p_material_id
        AND dwtm.week = p_week
        AND dwtm.type_material_id = ANY(v_type_material_id)
        AND dwtm.fl_status = true
    ) INTO v_type_material_validate_id;

    -- Traer los detalles de la tabla detail_week_type_mat
    SELECT ARRAY(
        SELECT dwtm.id
        FROM detail_week_type_mat dwtm
        WHERE dwtm.material_id = p_material_id
        AND dwtm.week = p_week
        AND dwtm.type_material_id = ANY(v_type_material_id)
        AND dwtm.fl_status = true
    ) INTO v_detail_week_type_mat_id;

    FOR v_course_id IN
        SELECT tmc.course_id FROM type_material_course tmc
        WHERE tmc.type_material_id = ANY(v_type_material_id)
        AND tmc.fl_status = true
        AND tmc.amount_question > 0
        GROUP BY tmc.course_id
        ORDER BY tmc.course_id
    LOOP
        -- Se busca si hay registro de los cursos ya creados o no
        SELECT macw.id INTO v_material_class_week_id FROM material_class_week macw
        WHERE macw.material_id = p_material_id AND macw.type_material_id = p_type_material_id
        AND macw.week = p_week
        AND macw.course_id = v_course_id AND macw.fl_status = true LIMIT 1;

        -- Si busca si hay preguntas registradas con el curso
        SELECT COUNT(mbq.*) INTO v_count_course FROM material_ballot_question mbq
        INNER JOIN detail_week_type_mat dwtm ON mbq.week_type_material_id = dwtm.id
        WHERE mbq.fl_status = true
        AND dwtm.fl_status = true
        AND dwtm.material_id = p_material_id
        AND dwtm.type_material_id = ANY(v_type_material_id)
        AND dwtm.week = p_week
        AND mbq.course_id = v_course_id;

        IF v_material_class_week_id IS NULL THEN
            IF v_count_course > 0 THEN
                INSERT INTO material_class_week (material_id, type_material_id, week_type_material_ids, week, course_id, created_by, created_at)
                VALUES (p_material_id, p_type_material_id, v_detail_week_type_mat_id, p_week, v_course_id, p_created_by, NOW());
            END IF;
        ELSE
            IF v_count_course > 0 THEN
                UPDATE material_class_week maclw
                SET fl_process_status = 1, url_material_class = null, job_id = null, week_type_material_ids = v_detail_week_type_mat_id,
                    updated_by = p_created_by, updated_at = NOW()
                WHERE maclw.material_id = p_material_id AND maclw.type_material_id = p_type_material_id
                AND maclw.week = p_week
                AND maclw.course_id = v_course_id AND maclw.fl_status = true;
            ELSE
                UPDATE material_class_week maclw
                SET fl_status = false, deleted_by = p_created_by, deleted_at = NOW()
                WHERE maclw.material_id = p_material_id AND maclw.type_material_id = p_type_material_id
                AND maclw.week = p_week
                AND maclw.course_id = v_course_id AND maclw.fl_status = true;
            END IF;
        END IF;
    END LOOP;

    RETURN QUERY
    SELECT
        mcw.id,
        mcw.material_id,
        mcw.type_material_id,
        tm.description as type_material,
        mcw.week_type_material_ids,
        mcw.week,
        mcw.course_id,
        cou.code AS code_course,
        cou.name AS name_course,
        mcw.fl_process_status,
        mcw.url_material_class,
        mcw.job_id
    FROM material_class_week mcw
    INNER JOIN material m ON mcw.material_id = m.id
    INNER JOIN cycle c ON m.cycle_id = c.id
    INNER JOIN course cou ON mcw.course_id = cou.id
    INNER JOIN type_material tm ON mcw.type_material_id = tm.id
    WHERE mcw.material_id = p_material_id
    AND mcw.type_material_id = p_type_material_id
    AND mcw.week = p_week
    AND mcw.week_type_material_ids = v_detail_week_type_mat_id::VARCHAR
    AND mcw.fl_status = true
    ORDER BY mcw.course_id;
END;
$$;


ALTER FUNCTION odiseo.fn_process_material_class_week(p_material_id bigint, p_type_material_id smallint, p_type_material_template_id smallint, p_week smallint, p_cycle_id bigint, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_process_material_question_replacement(bigint, bigint, bigint, text, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_process_material_question_replacement(p_material_revision_course_id bigint, p_material_ballot_question_id bigint, p_new_question_id bigint, p_reason text, p_created_by bigint) RETURNS TABLE(last_code character varying, new_code character varying, pending_change integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_old_question_id BIGINT;
    v_cycle_id BIGINT;
    v_university_id SMALLINT;
    v_headquarters_id BIGINT;
    v_question_history_id BIGINT;
    v_week_type_material_id BIGINT;
    v_new_material_ballot_question_id BIGINT;
    
    v_last_code CHARACTER VARYING;
    v_new_code CHARACTER VARYING;
    v_limit_questions INTEGER;
    v_current_changes INTEGER;
BEGIN
    -- 1. Obtener la configuración del límite de cambios permitidos
    SELECT limit_questions_to_change INTO v_limit_questions 
    FROM advanced_settings 
    LIMIT 1;

    -- 2. Incrementar y obtener el conteo de cambios actuales en la revisión
    UPDATE material_revision_courses
    SET amount_questions_changed = COALESCE(amount_questions_changed, 0) + 1,
        updated_at = NOW()
    WHERE id = p_material_revision_course_id
    RETURNING amount_questions_changed INTO v_current_changes;


    -- 3. Obtener la pregunta actual, sus metadatos de material y su código
    SELECT 
        mbq.question_id,
        q_old.code, 
        m.cycle_id, 
        m.university_id, 
        m.headquarte_id,
        dwtm.id
    INTO 
        v_old_question_id,
        v_last_code, 
        v_cycle_id, 
        v_university_id, 
        v_headquarters_id,
        v_week_type_material_id
    FROM material_ballot_question mbq
    INNER JOIN detail_week_type_mat dwtm ON dwtm.id = mbq.week_type_material_id
    INNER JOIN material m ON m.id = dwtm.material_id
    INNER JOIN question q_old ON q_old.id = mbq.question_id
    WHERE mbq.id = p_material_ballot_question_id;

    -- 4. Obtener el código de la NUEVA pregunta
    SELECT code INTO v_new_code 
    FROM question 
    WHERE id = p_new_question_id;

    -- 5. Traer o registrar historial para la NUEVA pregunta
    SELECT qhc.id INTO v_question_history_id
    FROM question_history_cycle qhc
    WHERE qhc.question_id = p_new_question_id
      AND qhc.cycle_id = v_cycle_id
      AND qhc.university_id = v_university_id
      AND qhc.headquarters_id = v_headquarters_id
      AND qhc.fl_status = TRUE
    LIMIT 1;

    IF v_question_history_id IS NULL THEN
        -- Replicar de la antigua pregunta, ya que siempre tendrá historial
        INSERT INTO question_history_cycle (
            question_id, cycle_id, university_id, headquarters_id, fl_status, 
            created_by, created_at, updated_at, automatic, parent_question_id, subquestion
        )
        SELECT
            p_new_question_id, cycle_id, university_id, headquarters_id, TRUE, 
            p_created_by, NOW(), NOW(), automatic, parent_question_id, subquestion
        FROM question_history_cycle
        WHERE question_id = v_old_question_id
          AND cycle_id = v_cycle_id
          AND university_id = v_university_id
          AND headquarters_id = v_headquarters_id
          AND fl_status = TRUE
        LIMIT 1
        RETURNING id INTO v_question_history_id;
    END IF;

    -- 5.1. Marcar como eliminado el historial de la pregunta antigua
    UPDATE question_history_cycle
    SET fl_status = FALSE,
        deleted_at = NOW(),
        deleted_by = p_created_by
    WHERE question_id = v_old_question_id
      AND cycle_id = v_cycle_id
      AND university_id = v_university_id
      AND headquarters_id = v_headquarters_id;

    -- 6. Insertar nueva pregunta en el balotario replicando los campos (UNIFICADO)
    INSERT INTO material_ballot_question (
        week_type_material_id, course_id, topic_id, subtopic_id, level_id, type, 
        question_id, fl_status, created_by, created_at, updated_at, 
        question_history_id, position, random, fl_is_manual, parent_question_id, 
        type_text_id, type_text_subcategory_id,
        material_id, week, type_material_id, position_initial, usage_level_id,
        usage_status, absolute_position, added_in_completion, removed_in_completion, state
    )
    SELECT 
        week_type_material_id, course_id, topic_id, subtopic_id, level_id, type, 
        p_new_question_id, TRUE, p_created_by, NOW(), NOW(), 
        v_question_history_id, position, random, fl_is_manual, parent_question_id, 
        type_text_id, type_text_subcategory_id,
        material_id, week, type_material_id, position_initial, usage_level_id,
        usage_status, absolute_position, added_in_completion, removed_in_completion, state
    FROM material_ballot_question
    WHERE id = p_material_ballot_question_id
    RETURNING id INTO v_new_material_ballot_question_id;

    -- 6.1. Eliminar lógicamente la pregunta antigua en el balotario
    UPDATE material_ballot_question
    SET fl_status = FALSE,
        deleted_at = NOW(),
        deleted_by = p_created_by
    WHERE id = p_material_ballot_question_id;

    -- 6.2. Eliminar lógicamente sus subpreguntas asociadas
    UPDATE material_ballot_subquestions
    SET fl_status = FALSE,
        deleted_at = NOW()
    WHERE material_ballot_question_id = p_material_ballot_question_id;

    -- 8. Registrar el motivo del cambio en la nueva tabla
    INSERT INTO material_question_change_reason (
        material_revision_course_id,
        material_ballot_question_id,
        old_question_id,
        new_question_id,
        reason,
        created_by,
        created_at,
        updated_at
    ) VALUES (
        p_material_revision_course_id,
        v_new_material_ballot_question_id,
        v_old_question_id,
        p_new_question_id,
        p_reason,
        p_created_by,
        NOW(),
        NOW()
    );

    -- 9. Limpiar la url del material a nivel del curso
    PERFORM fn_deactive_ballot_per_course_url(
        p_material_revision_course_id,
        p_created_by
    );

    -- 10. Retornar los datos solicitados
    RETURN QUERY 
    SELECT 
        v_last_code, 
        v_new_code, 
        (v_limit_questions - v_current_changes)::INTEGER AS pending_change;

END;
$$;


ALTER FUNCTION odiseo.fn_process_material_question_replacement(p_material_revision_course_id bigint, p_material_ballot_question_id bigint, p_new_question_id bigint, p_reason text, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_process_separated_material_exam_week(bigint, smallint, bigint, smallint, smallint, boolean, boolean, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_process_separated_material_exam_week(p_material_id bigint, p_type_material_id smallint, p_material_exam_area_week_id bigint, p_exam_area_id smallint, p_week smallint, p_fl_solution boolean, p_fl_quality boolean, p_created_by bigint) RETURNS TABLE(id bigint, material_id bigint, type_material_id smallint, type_material character varying, material_exam_area_week_id smallint, exam_area_id smallint, week smallint, fl_solution boolean, fl_quality boolean, course_id smallint, code_course character varying, name_course character varying, fl_process_status smallint, url_material_class character varying, job_id character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_separated_material_exam_week_id BIGINT;
    v_course_id SMALLINT;
    v_count_course BIGINT;
BEGIN
    FOR v_course_id IN
        SELECT tmc.course_id FROM type_material_course tmc
        WHERE tmc.type_material_id = p_type_material_id
        AND tmc.fl_status = true
        AND tmc.amount_question > 0
        GROUP BY tmc.course_id
        ORDER BY tmc.course_id
    LOOP
        -- Se busca si hay registro de los cursos ya creados o no
        SELECT smew.id INTO v_separated_material_exam_week_id FROM separated_material_exam_week smew
        WHERE smew.material_id = p_material_id AND smew.material_exam_area_week_id = p_material_exam_area_week_id
        AND smew.fl_solution = p_fl_solution AND smew.fl_quality = p_fl_quality
        AND smew.week = p_week AND smew.course_id = v_course_id AND smew.fl_status = true LIMIT 1;

        -- Si busca si hay preguntas registradas con el curso
        -- Elegir preguntas de examen
        SELECT COUNT(meq.*) INTO v_count_course FROM material_exam_question meq
        INNER JOIN material_exam_area_week meaw ON meq.material_exam_area_week_id = meaw.id
        INNER JOIN detail_week_type_mat dwtm ON meaw.week_type_material_id = dwtm.id
        WHERE meq.fl_status = true
        AND meaw.fl_status = true
        AND dwtm.fl_status = true
        AND dwtm.material_id = p_material_id
        AND dwtm.type_material_id = p_type_material_id
        AND meaw.area_id = p_exam_area_id
        AND dwtm.week = p_week
        AND meq.course_id = v_course_id;

        IF v_separated_material_exam_week_id IS NULL THEN
            IF v_count_course > 0 THEN
                INSERT INTO separated_material_exam_week (material_id, material_exam_area_week_id, week, fl_solution, fl_quality, course_id, created_by, created_at)
                VALUES (p_material_id, p_material_exam_area_week_id, p_week, p_fl_solution, p_fl_quality, v_course_id, p_created_by, NOW());
            END IF;
        ELSE
            IF v_count_course > 0 THEN
                UPDATE separated_material_exam_week smew
                SET fl_process_status = 1, url_material = null, job_id = null, updated_by = p_created_by, updated_at = NOW()
                WHERE smew.material_id = p_material_id AND smew.material_exam_area_week_id = p_material_exam_area_week_id
                AND smew.week = p_week AND smew.fl_solution = p_fl_solution AND smew.fl_quality = p_fl_quality
                AND smew.course_id = v_course_id AND smew.fl_status = true;
            ELSE
                UPDATE separated_material_exam_week smew
                SET fl_status = false, deleted_by = p_created_by, deleted_at = NOW()
                WHERE smew.material_id = p_material_id AND smew.material_exam_area_week_id = p_material_exam_area_week_id
                AND smew.week = p_week AND smew.fl_solution = p_fl_solution AND smew.fl_quality = p_fl_quality
                AND smew.course_id = v_course_id AND smew.fl_status = true;
            END IF;
        END IF;
    END LOOP;

    RETURN QUERY
    SELECT
        smw.id,
        smw.material_id,
        dwtm.type_material_id,
        tm.description as type_material,
        smw.material_exam_area_week_id,
        meaw.area_id AS exam_area_id,
        smw.week,
        smw.fl_solution,
        smw.fl_quality,
        smw.course_id,
        cou.code AS code_course,
        cou.name AS name_course,
        smw.fl_process_status,
        smw.url_material,
        smw.job_id
    FROM separated_material_exam_week smw
    INNER JOIN material_exam_area_week meaw ON smw.material_exam_area_week_id = meaw.id
    INNER JOIN detail_week_type_mat dwtm ON meaw.week_type_material_id = dwtm.id
    INNER JOIN material m ON smw.material_id = m.id
    INNER JOIN cycle c ON m.cycle_id = c.id
    INNER JOIN course cou ON smw.course_id = cou.id
    INNER JOIN type_material tm ON dwtm.type_material_id = tm.id
    WHERE dwtm.material_id = p_material_id
    AND smw.material_exam_area_week_id = p_material_exam_area_week_id
    AND smw.week = p_week
    AND smw.fl_solution = p_fl_solution
    AND smw.fl_quality = p_fl_quality
    AND smw.fl_status = true
    AND meaw.fl_status = true
    AND dwtm.fl_status = true
    ORDER BY smw.course_id;
END;
$$;


ALTER FUNCTION odiseo.fn_process_separated_material_exam_week(p_material_id bigint, p_type_material_id smallint, p_material_exam_area_week_id bigint, p_exam_area_id smallint, p_week smallint, p_fl_solution boolean, p_fl_quality boolean, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_process_separated_material_week(bigint, smallint, jsonb, bigint[], smallint, boolean, boolean, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_process_separated_material_week(p_material_id bigint, p_type_material_id smallint, p_type_material_jsonb jsonb, p_week_type_material_ids bigint[], p_week smallint, p_fl_solution boolean, p_fl_quality boolean, p_created_by bigint) RETURNS TABLE(id bigint, material_id bigint, type_material_template_id bigint, type_material_template character varying, type_material_id smallint, type_material character varying, week_type_material_ids character varying, week smallint, fl_solution boolean, fl_quality boolean, course_id smallint, code_course character varying, name_course character varying, fl_process_status smallint, url_material_class character varying, job_id character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_separated_material_week_id BIGINT;
    v_course_id SMALLINT;
    v_count_course BIGINT;
BEGIN
    FOR v_course_id IN
        SELECT tmc.course_id FROM type_material_course tmc
        WHERE tmc.type_material_id = ANY(SELECT jsonb_array_elements_text(p_type_material_jsonb)::BIGINT)
        AND tmc.fl_status = true
        AND (tmc.amount_question > 0 OR tmc.amount_text > 0)
        GROUP BY tmc.course_id
        ORDER BY tmc.course_id
    LOOP
        -- Se busca si hay registro de los cursos ya creados o no
        SELECT smw.id INTO v_separated_material_week_id FROM separated_material_week smw
        WHERE smw.material_id = p_material_id AND smw.type_material_id = p_type_material_id
        AND smw.fl_solution = p_fl_solution AND smw.fl_quality = p_fl_quality
        AND smw.week = p_week AND smw.course_id = v_course_id AND smw.fl_status = true LIMIT 1;

        -- Si busca si hay preguntas registradas con el curso
        -- Elegir preguntas de balotario
        SELECT COUNT(mbq.*) INTO v_count_course FROM material_ballot_question mbq
        INNER JOIN detail_week_type_mat dwtm ON mbq.week_type_material_id = dwtm.id
        WHERE mbq.fl_status = true
        AND dwtm.fl_status = true
        AND dwtm.material_id = p_material_id
        AND dwtm.type_material_id = ANY(SELECT jsonb_array_elements_text(p_type_material_jsonb)::BIGINT)
        AND dwtm.week = p_week
        AND mbq.course_id = v_course_id;

        IF v_separated_material_week_id IS NULL THEN
            IF v_count_course > 0 THEN
                INSERT INTO separated_material_week (material_id, type_material_id, week, fl_solution, fl_quality, week_type_material_ids, course_id, created_by, created_at)
                VALUES (p_material_id, p_type_material_id, p_week, p_fl_solution, p_fl_quality, p_week_type_material_ids, v_course_id, p_created_by, NOW());
            END IF;
        ELSE
            IF v_count_course > 0 THEN
                UPDATE separated_material_week smw
                SET fl_process_status = 1, url_material = null, job_id = null, week_type_material_ids = p_week_type_material_ids,
                    updated_by = p_created_by, updated_at = NOW()
                WHERE smw.material_id = p_material_id AND smw.type_material_id = p_type_material_id
                AND smw.week = p_week AND smw.fl_solution = p_fl_solution AND smw.fl_quality = p_fl_quality
                AND smw.course_id = v_course_id AND smw.fl_status = true;
            ELSE
                UPDATE separated_material_week smw
                SET fl_status = false, deleted_by = p_created_by, deleted_at = NOW()
                WHERE smw.material_id = p_material_id AND smw.type_material_id = p_type_material_id
                AND smw.week = p_week AND smw.fl_solution = p_fl_solution AND smw.fl_quality = p_fl_quality
                AND smw.course_id = v_course_id AND smw.fl_status = true;
            END IF;
        END IF;
    END LOOP;

    RETURN QUERY
    SELECT
        smw.id,
        smw.material_id,
        tmt.id as type_material_template_id,
        tmt.name as type_material_template,
        smw.type_material_id,
        tm.description as type_material,
        smw.week_type_material_ids,
        smw.week,
        smw.fl_solution,
        smw.fl_quality,
        smw.course_id,
        cou.code AS code_course,
        cou.name AS name_course,
        smw.fl_process_status,
        smw.url_material,
        smw.job_id
    FROM separated_material_week smw
    INNER JOIN material m ON smw.material_id = m.id
    INNER JOIN cycle c ON m.cycle_id = c.id
    INNER JOIN course cou ON smw.course_id = cou.id
    INNER JOIN type_material tm ON smw.type_material_id = tm.id
    INNER JOIN type_material_template tmt ON tmt.id = tm.type_material_template_id
    WHERE smw.material_id = p_material_id
    AND smw.type_material_id = p_type_material_id
    AND smw.week = p_week
    AND smw.fl_solution = p_fl_solution
    AND smw.fl_quality = p_fl_quality
    AND smw.fl_status = true
    ORDER BY smw.course_id;
END;
$$;


ALTER FUNCTION odiseo.fn_process_separated_material_week(p_material_id bigint, p_type_material_id smallint, p_type_material_jsonb jsonb, p_week_type_material_ids bigint[], p_week smallint, p_fl_solution boolean, p_fl_quality boolean, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_prospect(integer, integer, boolean, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_prospect(p_perpage integer, p_npage integer, f_fl_validate boolean, p_text character varying) RETURNS TABLE(id bigint, name character varying, charge character varying, type_company character varying, name_institute character varying, document_number character varying, code_id bigint, code character varying, fl_validate boolean, fl_status boolean, total integer)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            total_count INTEGER;
            offset_val INTEGER;
        begin

            offset_val := p_perpage * (p_npage - 1);

            SELECT COUNT(*)
            INTO total_count
            FROM odiseo.prospect p
            LEFT JOIN odiseo.code_prospect c ON p.code_id = c.id
            WHERE
                p.deleted_at IS null
                AND (f_fl_validate IS NULL OR p.fl_validate = f_fl_validate)
                AND (p_text IS NULL
                OR unaccent(p.name) ILIKE '%' || unaccent(p_text) || '%'
                OR unaccent(p.name_institute) ILIKE '%' || unaccent(p_text) || '%'
                OR unaccent(p.document_number) ILIKE '%' || unaccent(p_text) || '%');

            RETURN QUERY
            SELECT
                p.id,
                p.name,
                p.charge,
                p.type_company,
                p.name_institute,
                p.document_number,
                p.code_id,
                c.code,
                p.fl_validate,
                p.fl_status,
                total_count AS total
            FROM odiseo.prospect p
            LEFT JOIN odiseo.code_prospect c ON p.code_id = c.id
            WHERE
                p.deleted_at IS null
                AND (f_fl_validate IS NULL OR p.fl_validate = f_fl_validate)
                AND (p_text IS NULL
                OR unaccent(p.name) ILIKE '%' || unaccent(p_text) || '%'
                OR unaccent(p.name_institute) ILIKE '%' || unaccent(p_text) || '%'
                OR unaccent(p.document_number) ILIKE '%' || unaccent(p_text) || '%')
            ORDER by p.name ASC, p.name_institute ASC
            LIMIT p_perpage
            OFFSET offset_val;
        END;
        $$;


ALTER FUNCTION odiseo.fn_prospect(p_perpage integer, p_npage integer, f_fl_validate boolean, p_text character varying) OWNER TO postgres;

--
-- Name: fn_question(integer, integer, character varying, character varying, integer, integer, integer, integer, integer, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_question(p_perpage integer, p_npage integer, f_status character varying, p_name_text character varying, f_course_id integer, f_topic_id integer, f_subtopic_id integer, f_level_id integer, f_teacher_id integer, f_type character varying) RETURNS TABLE(id bigint, code character varying, description text, short_description text, number_question character varying, number character varying, course_id smallint, code_course character varying, course character varying, topic_id smallint, code_topic character varying, topic character varying, subtopic_id smallint, code_subtopic character varying, subtopic character varying, level_id smallint, level character varying, teacher_id bigint, code_teacher character varying, first_name character varying, first_surname character varying, second_surname character varying, answer_id bigint, status character varying, fl_status boolean, observation text, similitaries text, created_by bigint, updated_by bigint, deleted_by bigint, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone, url_pdf character varying, user_name character varying, user_email odiseo.email_citext, total integer)
    LANGUAGE plpgsql
    AS $$
                                DECLARE
                                    total_count INTEGER;
                                    offset_val INTEGER;
                                BEGIN
                                    offset_val := p_perpage * (p_npage - 1);

                                    SELECT COUNT(*)
                                    INTO total_count
                                    FROM question q
                                    LEFT JOIN course c ON q.course_id = c.id
                                    LEFT JOIN topic t ON q.topic_id = t.id
                                    LEFT JOIN subtopic s ON q.subtopic_id = s.id
                                    LEFT JOIN level l ON q.level_id = l.id
                                    LEFT JOIN employees e ON q.teacher_id = e.id
                                    AND q.fl_status = true
                                    AND q.deleted_at IS NULL
                                    AND (f_status IS NULL OR q.status = f_status)
                                    AND (f_course_id IS NULL OR q.course_id = f_course_id)
                                    AND (f_topic_id IS NULL OR q.topic_id = f_topic_id)
                                    AND (f_subtopic_id IS NULL OR q.subtopic_id = f_subtopic_id)
                                    AND (f_level_id IS NULL OR q.level_id = f_level_id)
                                    AND (f_teacher_id IS NULL OR q.teacher_id = f_teacher_id)
                                    AND (f_type IS NULL OR q.type = f_type)
                                    AND (
                                        p_name_text IS NULL
                                        OR LOWER(unaccent(q.short_description)) LIKE '%' || LOWER(unaccent(p_name_text)) || '%'
                                        OR LOWER(q.number_question) LIKE '%' || LOWER(p_name_text) || '%'
                                        OR LOWER(q.number) LIKE '%' || LOWER(p_name_text) || '%'
                                    );

                                    RETURN QUERY
                                    SELECT
                                        q.id,
                                        q.code,
                                        q.description,
                                        q.short_description,
                                        q.number_question,
                                        q.number,
                                        q.course_id,
                                        c.code AS code_course,
                                        c.name AS course,
                                        q.topic_id,
                                        t.code AS code_topic,
                                        t.name AS topic,
                                        q.subtopic_id,
                                        s.code AS code_subtopic,
                                        s.name AS subtopic,
                                        q.level_id,
                                        l.description AS level,
                                        q.teacher_id,
                                        e.code AS code_teacher,
                                        e.first_name,
                                        e.first_surname,
                                        e.second_surname,
                                        q.answer_id,
                                        q.status,
                                        q.fl_status,
                                        qo.description as observation,
                                        qo.similitaries,
                                        q.created_by,
                                        q.updated_by,
                                        q.deleted_by,
                                        q.created_at,
                                        q.updated_at,
                                        q.deleted_at,
                                        q.url_pdf,
                                        u.user as user_name,
                                        u.email as user_email,
                                        total_count AS total
                                    FROM question q
                                    LEFT JOIN course c ON q.course_id = c.id
                                    LEFT JOIN question_observation qo ON q.id = qo.question_id AND q.status = qo.type
                                    LEFT JOIN topic t ON q.topic_id = t.id
                                    LEFT JOIN subtopic s ON q.subtopic_id = s.id
                                    LEFT JOIN level l ON q.level_id = l.id
                                    LEFT JOIN employees e ON q.teacher_id = e.id
                                    LEFT JOIN users u ON q.created_by = u.id
                                    AND q.fl_status = true
                                                                        AND q.deleted_at IS NULL
                                                                        AND (f_type IS NULL OR q.type = f_type)
                                                                        AND (
                                                                            p_name_text IS NULL
                                                                            OR LOWER(unaccent(q.short_description)) LIKE '%' || LOWER(unaccent(p_name_text)) || '%'
                                                                                                                OR LOWER(q.number_question) LIKE '%' || LOWER(p_name_text) || '%'
                                                                                                                OR LOWER(q.number) LIKE '%' || LOWER(p_name_text) || '%'
                                                                        )
                                                                        ORDER BY q.id ASC
                                                                        LIMIT p_perpage
                                                                        OFFSET offset_val;

                                END;
                                $$;


ALTER FUNCTION odiseo.fn_question(p_perpage integer, p_npage integer, f_status character varying, p_name_text character varying, f_course_id integer, f_topic_id integer, f_subtopic_id integer, f_level_id integer, f_teacher_id integer, f_type character varying) OWNER TO postgres;

--
-- Name: fn_question_configuration_comparison(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_question_configuration_comparison(p_syllabus_id bigint, p_company_id bigint) RETURNS TABLE(syllabus_id bigint, course_amount_question integer, course_id smallint, course_name character varying, type_material_id smallint, type_material character varying, week_number smallint, amount_used integer, type text, status text, cycle_description character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_cycle_id int;
    v_university_id int;
    v_company_id int;
BEGIN
    SELECT 
        sy.cycle_id,
        sy.university_id,
        sy.company_id
    INTO v_cycle_id, v_university_id, v_company_id
    FROM syllabus sy
    WHERE sy.id = p_syllabus_id;

    RETURN QUERY
    SELECT 
        fgmc.syllabus_id, 
        fgmc.expected_amount course_amount_question, 
        fgmc.course_id,
        fgmc.course_name,
        fgmc.type_material_id,
        fgmc.type_material_name type_material,
        fgmc.week_number,
        fgmc.syllabus_actual_amount amount_used,
        fgmc.record_type type,
        CASE
            WHEN fgmc.has_configuration IS FALSE THEN 'not_configurable'
            WHEN fgmc.has_syllabus_configuration IS FALSE THEN 'empty'
            WHEN fgmc.has_syllabus_mismatch IS TRUE THEN 'inconsistent'
            WHEN fgmc.has_syllabus_mismatch IS FALSE THEN 'complete'
        END status,
        fgmc.cycle_description
    FROM fn_get_material_configuration_inconsistencies(null, v_cycle_id, v_university_id, v_company_id) fgmc
    WHERE fgmc.syllabus_id = p_syllabus_id
    ORDER BY fgmc.week_number;
END;
$$;


ALTER FUNCTION odiseo.fn_question_configuration_comparison(p_syllabus_id bigint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_question_diagram(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_question_diagram(p_id bigint) RETURNS TABLE(id bigint, code character varying, description text, course_id smallint, code_course character varying, course character varying, document_solution text, answer_id bigint, answer text, editor_content text, editor_content_images jsonb, alternatives jsonb, images jsonb, file_solution jsonb, topic_name character varying, subtopic_name character varying, subtopics jsonb, diagrammed jsonb, diagrammed_images jsonb, config_alternative_id bigint, columns smallint, question_columns smallint, url_pdf character varying, type_text_id bigint, type_text_template_id smallint, type_text_template_name character varying, description_text character varying, description_subquestion character varying, text_attributes character varying, subquestion_attributes character varying, topic_code character varying, subtopic_code character varying)
    LANGUAGE plpgsql
    AS $$
                        BEGIN
                            RETURN QUERY
                            WITH tbl_diagrammed AS (
                                SELECT
                                    ed.question_id,
                                    jsonb_agg(jsonb_build_object(
                                        'id', edf.id,
                                        'question_id', ed.question_id,
                                        'setting_diagrammed_course_id', edf.setting_diagrammed_course_id,
                                        'value', edf.value,
                                        'position', sd.position,
                                        'diagram_id', sd.id,
                                        'field_diagram', fd.name,
                                        'updated_at', edf.updated_at,
                                        'fl_optional', sd.fl_optional
                                    ))::TEXT AS diagrammed
                                FROM employee_didi_question ed
                                INNER JOIN question q ON ed.question_id = q.id AND q.fl_status IS TRUE
                                INNER JOIN employee_didi_question_field edf ON ed.id = edf.employee_didi_question_id AND edf.fl_status = true
                                INNER JOIN setting_diagrammed_courses sd ON edf.setting_diagrammed_course_id = sd.id
                                INNER JOIN field_diagrammed fd ON sd.field_diagram_id = fd.id
                                WHERE ed.fl_status = true
                                GROUP BY ed.question_id
                            ), tbl_diagrammed_image AS (
                                SELECT
                                    ed.question_id,
                                    jsonb_agg(jsonb_build_object(
                                        'id', edfi.id,
                                        'question_id', ed.question_id,
                                        'code', edfi.code,
                                        'image', edfi.image,
                                        'extension', edfi.extension
                                    ))::TEXT AS diagrammed_images
                                FROM employee_didi_question ed
                                INNER JOIN question q ON ed.question_id = q.id AND q.fl_status IS TRUE
                                INNER JOIN employee_didi_question_field_image edfi ON ed.id = edfi.employee_didi_question_id AND edfi.fl_status = true
                                WHERE ed.fl_status = true
                                GROUP BY ed.question_id
                            )

                            SELECT
                                q.id,
                                q.code,
                                q.description,
                                q.course_id,
                                c.code AS code_course,
                                c.name AS course,
                                eq.document_solution,
                                q.answer_id,
                                a.description AS answer,
                                eq.editor_content,
                                COALESCE((
                                    SELECT jsonb_agg(DISTINCT eqi.*)
                                    FROM employee_question_image eqi
                                    WHERE eqi.employee_question_id = eq.id AND eqi.fl_status = TRUE
                                ), '[]'::jsonb) AS editor_content_images,
                                COALESCE((
                                    SELECT jsonb_agg(at.* ORDER BY at.id ASC)
                                    FROM alternative at
                                    WHERE at.question_id = q.id
                                ), '[]'::jsonb) AS alternatives,
                                COALESCE((
                                    SELECT jsonb_agg(DISTINCT qi.*)
                                    FROM question_image qi
                                    WHERE qi.question_id = q.id
                                    AND qi.fl_status = true
                                ), '[]'::jsonb) AS images,
                                COALESCE((
                                    SELECT jsonb_agg(DISTINCT eqd.*)
                                    FROM employee_question_document eqd
                                    WHERE eqd.employee_question_id = eq.id
                                    AND eqd.fl_status = true
                                ), '[]'::jsonb) AS file_solution,
                                t.name AS topic_name,
                                st.name AS subtopic_name,
                                COALESCE((
                                    SELECT jsonb_agg(
                                        DISTINCT JSONB_BUILD_OBJECT(
                                            'name', st.name,
                                            'code', st.code
                                        )
                                    )
                                    FROM subtopic st
                                    JOIN question_subtopic qst ON qst.subtopic_id = st.id
                                    WHERE qst.question_id = q.id
                                    AND qst.fl_status = true
                                    AND st.fl_status = true
                                ), '[]'::jsonb) AS subtopics,
                                COALESCE(td.diagrammed::JSONB, '[]'::JSONB),
                                COALESCE(tdi.diagrammed_images::JSONB, '[]'::JSONB),
                                q.config_alternative_id,
                                ca.columns,
                                q.columns AS question_columns,
                                q.url_pdf,
                                pq.type_text_id,
                                c.type_text_template_id,
                                ttt.name as type_text_template_name,
                                ttt.description_text,
                                ttt.description_subquestion,
                                ttt.text_attributes,
                                ttt.subquestion_attributes,
                                t.code AS topic_code,
                                st.code AS subtopic_code
                            FROM question q
                            LEFT JOIN alternative a ON q.answer_id = a.id
                            LEFT JOIN course c ON q.course_id = c.id
                            LEFT JOIN type_text_templates ttt on ttt.id = c.type_text_template_id
                            LEFT JOIN employee_question eq ON q.id = eq.question_id AND eq.fl_status = true
                            LEFT JOIN topic t ON t.id = q.topic_id AND t.fl_status = true
                            LEFT JOIN question_subtopic qst ON qst.question_id = q.id AND qst.fl_status = true
                            LEFT JOIN subtopic st ON qst.subtopic_id = st.id AND st.fl_status = true
                            INNER JOIN configuration_alternative ca ON q.config_alternative_id = ca.id
                            LEFT JOIN tbl_diagrammed td ON q.id = td.question_id
                            LEFT JOIN tbl_diagrammed_image tdi ON q.id = tdi.question_id
                            LEFT JOIN parent_question pq ON pq.id = q.parent_id
                            WHERE q.id = p_id;
                        END;
                    $$;


ALTER FUNCTION odiseo.fn_question_diagram(p_id bigint) OWNER TO postgres;

--
-- Name: fn_question_material_ballot_pdf(jsonb, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_question_material_ballot_pdf(p_week_type_materials jsonb, p_course_id smallint) RETURNS TABLE(id bigint, type_material_id smallint, type_material character varying, order_course smallint, parent_type_material_id smallint, area_id bigint, area character varying, course_id smallint, course character varying, topic_id smallint, topic_code character varying, topic character varying, subtopic_id smallint, subtopic_code character varying, subtopic character varying, level_id bigint, level character varying, type character varying, question_id bigint, absolute_position smallint, position_question smallint, code character varying, description_question text, answer_id bigint, parent_id bigint, config_alternative_id bigint, columns smallint, styles text, column_count_topic bigint, column_width_topic numeric, column_spacing_topic numeric, layout_format_topic character varying, number_format_topic character varying, fl_image_conf_alter boolean, diagrammed json, diagrammed_images json, images json, alternatives json, question_maths json, alternative_maths json, didi_maths json, column_question smallint, course_code character varying, ter numeric, parent_img json, type_question text, text_traduction text, description_parent_question text, subquestion json, description_b text, category character varying, subcategory character varying, text_origin text, status character varying, fl_show_in_material_with_solution boolean, fl_show_in_material_without_solution boolean)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_type_materials BIGINT[];
        BEGIN
            SELECT ARRAY(SELECT jsonb_array_elements_text(p_week_type_materials)::BIGINT) INTO v_type_materials;

            RETURN QUERY
            WITH tlb_question_materials AS (
                SELECT
                    mbq.id,
                    dwt.type_material_id,
                    tm.description AS type_material,
                    course_order.position AS order_course,
                    dwt.parent_type_material_id,
                    c.area_id,
                    a.description AS area,
                    mbq.course_id,
                    c.name AS course,
                    mbq.topic_id,
                    t.code as topic_code,
                    t.name AS topic,
                    mbq.subtopic_id::SMALLINT,
                    s.code AS subtopic_code,
                    s.name AS subtopic,
                    COALESCE(mbq.usage_level_id, mbq.level_id) AS level_id,
                    l.name as level,
                    mbq.type,
                    mbq.question_id,
                    mbq.position AS position_question,
                    mbq.absolute_position,
                    COALESCE(qsh.code, q.code, pq.code) AS code,
                    COALESCE(q.description, pq.description) AS description_question,
                    q.answer_id,
                    q.parent_id,
                    q.config_alternative_id,
                    ca.columns,
                    ca.styles,
                    COALESCE(mcc.column_count, 2)  AS column_count_topic,
                    mcc.column_width AS column_width_topic,
                    mcc.column_spacing AS column_spacing_topic,
                    mcc.layout_format AS layout_format_topic,
                    mcc.number_format AS number_format_topic,
                    ca.fl_image AS fl_image_conf_alter,
                    diag.diagrammed::JSON,
                    vqdi.diagrammed_images::JSON,
                    img.images::JSON,
                    COALESCE(alt.alternatives::JSON, '[]'::JSON) AS alternatives,
                    math.question_maths::JSON,
                    vam.alternative_maths::JSON,
                    vdm.didi_maths::JSON,
                    COALESCE(q.columns, pq.columns) AS column_question,
                    c.code AS course_code,
                    q.ter,
                    vpdm.parent_img::JSON,
                    CASE WHEN pq.id IS NULL THEN 'P' ELSE 'T' END AS type_question,
                    pq.text_traduction,
                    pq.description description_parent_question,
                    (
                        SELECT
                        json_agg(
                            jsonb_build_object(
                                'topic_name', t.name,
                                'subtopic_name', st.name,
                                'question_id', mbs.question_id,
                                'column_question', q.columns,
                                'code', q.code,
                                'course', c.name,
                                'topic_code', t.code,
                                'subtopic_code', st.code,
                                'course_code', c.code,
                                'description_question', q.description,
                                'alternatives', COALESCE(vqa.alternatives, '[]'::jsonb),
                                'diagrammed', vqd.diagrammed,
                                'answer_id', q.answer_id
                            )
                        )
                        FROM
                        material_ballot_subquestions mbs
                        JOIN question q ON mbs.question_id = q.id
                        JOIN topic AS t ON mbs.topic_id = t.id
                        JOIN subtopic AS st ON mbs.subtopic_id = st.id
                        JOIN course c ON mbs.course_id = c.id
                        LEFT JOIN LATERAL (
                            SELECT jsonb_agg(jsonb_build_object('id', a.id, 'description', a.description) ORDER BY a.id) AS alternatives
                            FROM odiseo.alternative a WHERE a.question_id = mbs.question_id AND a.fl_status = true
                        ) vqa ON TRUE
                        LEFT JOIN LATERAL (
                            SELECT jsonb_agg(jsonb_build_object('id', edf.id, 'value', edf.value, 'position', sd."position", 'field_diagram', fd.name) ORDER BY sd.position) AS diagrammed
                            FROM odiseo.employee_didi_question ed
                            JOIN odiseo.employee_didi_question_field edf ON ed.id = edf.employee_didi_question_id AND edf.fl_status = true
                            JOIN odiseo.setting_diagrammed_courses sd ON edf.setting_diagrammed_course_id = sd.id AND sd.fl_active = true AND sd.fl_status = true
                            JOIN odiseo.field_diagrammed fd ON sd.field_diagram_id = fd.id
                            WHERE ed.question_id = mbs.question_id AND ed.fl_status = true AND edf.value IS NOT NULL
                        ) vqd ON TRUE
                        WHERE mbs.material_ballot_question_id = mbq.id
                          AND mbs.fl_status = TRUE
                          AND mbs.deleted_at IS NULL
                          AND mbs.question_id IS NOT NULL
                    ) subquestion,
                    pq.description_b,
                    tt.name category,
                    tts.name subcategory,
                    COALESCE(vaqo.question_origin_text, vapo.question_origin_text) text_origin,
                    q.status,
                    ctcs.fl_show_in_material_with_solution,
                    ctcs.fl_show_in_material_without_solution
                FROM detail_week_type_mat dwt
                INNER JOIN material m ON dwt.material_id = m.id
            
                INNER JOIN material_ballot_question mbq
                    ON dwt.id = mbq.week_type_material_id
                    AND mbq.fl_status = TRUE
                    AND mbq.week_type_material_id = ANY(v_type_materials)
                    AND (p_course_id IS NULL OR mbq.course_id = p_course_id)
                    AND COALESCE(mbq.question_id, mbq.parent_question_id) IS NOT NULL
                LEFT JOIN question q ON mbq.question_id = q.id
                LEFT JOIN LATERAL (
                    SELECT qs.code
                    FROM question_shares qs
                    WHERE qs.question_id = q.id
                    AND qs.course_id = mbq.course_id
                    AND qs.topic_id = mbq.topic_id
                    AND qs.subtopic_id = mbq.subtopic_id
                    AND qs.deleted_at IS NULL
                    ORDER BY qs.updated_at DESC NULLS LAST
                    LIMIT 1
                ) qsh ON TRUE
                LEFT JOIN parent_question pq ON pq.id = mbq.parent_question_id
                INNER JOIN course c ON mbq.course_id = c.id
                
                LEFT JOIN topic t ON mbq.topic_id = t.id
                LEFT JOIN subtopic s ON mbq.subtopic_id = s.id
                INNER JOIN level l ON COALESCE(mbq.usage_level_id, mbq.level_id) = l.id
                INNER JOIN type_material tm ON dwt.type_material_id = tm.id
                LEFT JOIN configuration_alternative ca ON q.config_alternative_id = ca.id
                INNER JOIN area a ON c.area_id = a.id
                LEFT JOIN material_column_configurations mcc ON mbq.topic_id = mcc.topic_id
                LEFT JOIN (
                    SELECT ttmco.course_id, tm.id AS type_material_id, ttmco.position, ttmco.university_id
                    FROM template_type_material_courses_order ttmco
                    JOIN type_material tm ON tm.type_material_template_id = ttmco.template_type_material_id
                ) AS course_order ON course_order.type_material_id = COALESCE(dwt.parent_type_material_id, dwt.type_material_id)
                    AND course_order.course_id = mbq.course_id
                LEFT JOIN LATERAL (
                    SELECT jsonb_agg(jsonb_build_object('id', a.id, 'description', a.description) ORDER BY a.id) AS alternatives
                    FROM odiseo.alternative a WHERE a.question_id = q.id AND a.fl_status = true
                ) alt ON TRUE
                LEFT JOIN LATERAL (
                    SELECT jsonb_agg(jsonb_build_object('id', edf.id, 'value', edf.value, 'position', sd."position", 'field_diagram', fd.name) ORDER BY sd.position) AS diagrammed
                    FROM odiseo.employee_didi_question ed
                    JOIN odiseo.employee_didi_question_field edf ON ed.id = edf.employee_didi_question_id AND edf.fl_status = true
                    JOIN odiseo.setting_diagrammed_courses sd ON edf.setting_diagrammed_course_id = sd.id AND sd.fl_active = true AND sd.fl_status = true
                    JOIN odiseo.field_diagrammed fd ON sd.field_diagram_id = fd.id
                    WHERE ed.question_id = q.id AND ed.fl_status = true AND edf.value IS NOT NULL
                ) diag ON TRUE
                LEFT JOIN LATERAL (
                    SELECT jsonb_agg(jsonb_build_object('id', edfi.id, 'question_id', ed.question_id, 'code', edfi.code, 'image', edfi.image, 'extension', edfi.extension)) AS diagrammed_images
                    FROM odiseo.employee_didi_question ed
                    JOIN odiseo.employee_didi_question_field_image edfi ON ed.id = edfi.employee_didi_question_id AND edfi.fl_status = true
                    WHERE ed.question_id = q.id AND ed.fl_status = true
                ) vqdi ON TRUE
                LEFT JOIN LATERAL (
                    SELECT jsonb_agg(jsonb_build_object('id', qi.id, 'code', qi.code, 'image', qi.image, 'extension', qi.extension)) AS images
                    FROM odiseo.question_image qi WHERE qi.question_id = q.id AND qi.fl_status = true
                ) img ON TRUE
                LEFT JOIN LATERAL (
                    SELECT jsonb_agg(jsonb_build_object('id', qm.id, 'code', qm.code, 'path', qm.path, 'properties', qm.properties)) AS question_maths
                    FROM odiseo.question_maths qm WHERE qm.question_id = q.id AND qm.fl_status = true
                ) math ON TRUE
                LEFT JOIN LATERAL (
                    SELECT jsonb_agg(jsonb_build_object('id', am.id, 'code', am.code, 'path', am.path, 'properties', am.properties)) AS alternative_maths
                    FROM odiseo.alternative a
                    JOIN odiseo.alternative_maths am ON a.id = am.alternative_id AND am.fl_status = true
                    WHERE a.question_id = q.id AND a.fl_status = true
                ) vam ON TRUE
                LEFT JOIN LATERAL (
                    SELECT jsonb_agg(jsonb_build_object('id', dm.id, 'code', dm.code, 'path', dm.path, 'properties', dm.properties)) AS didi_maths
                    FROM odiseo.employee_didi_question ed
                    JOIN odiseo.employee_didi_question_field edf ON ed.id = edf.employee_didi_question_id AND edf.fl_status = true
                    JOIN odiseo.didi_maths dm ON edf.id = dm.didi_question_id AND dm.fl_status = true
                    WHERE ed.question_id = q.id AND ed.fl_status = true
                ) vdm ON TRUE
                LEFT JOIN LATERAL (
                    SELECT jsonb_agg(jsonb_build_object('id', pi.id, 'code', pi.code, 'image', pi.image)) AS parent_img
                    FROM odiseo.parent_image pi WHERE pi.parent_id = pq.id AND pi.fl_status = true
                ) vpdm ON TRUE
                LEFT JOIN type_text tt ON tt.id = pq.type_text_id
                LEFT JOIN course_text_category_settings ctcs on ctcs.course_id = c.id and ctcs.type_text_id = tt.id
                LEFT JOIN type_text_subcategories tts ON tts.id = pq.type_text_subcategory_id
                LEFT JOIN v_all_question_origins_by_university vaqo ON mbq.question_id = vaqo.question_id
                    AND vaqo.university_id = m.university_id
                LEFT JOIN v_all_parent_origins vapo ON mbq.parent_question_id = vapo.parent_id
                    AND vapo.university_id = m.university_id
                WHERE 1 = 1
                AND course_order.university_id IS NULL
                ORDER BY
                    order_course,
                    area DESC,
                    mbq.course_id,
                    type_material_id,
                    mbq.absolute_position,
                    mbq.position,
                    s.code,
                    l.name,
                    q.parent_id,
                    mbq.type,
                    mbq.question_id
            )
            SELECT * FROM tlb_question_materials;
        END;
        $$;


ALTER FUNCTION odiseo.fn_question_material_ballot_pdf(p_week_type_materials jsonb, p_course_id smallint) OWNER TO postgres;

--
-- Name: fn_question_material_class_pdf(jsonb, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_question_material_class_pdf(p_week_type_materials jsonb, p_course_id smallint) RETURNS TABLE(id bigint, type_material_id smallint, type_material character varying, order_course smallint, parent_type_material_id smallint, area_id bigint, area character varying, course_id smallint, course character varying, topic_id smallint, topic_code character varying, topic character varying, subtopic_id smallint, subtopic_code character varying, subtopic character varying, level_id bigint, level character varying, type character varying, question_id bigint, code character varying, description_question text, answer_id bigint, parent_id bigint, config_alternative_id bigint, columns smallint, styles text, column_count_topic bigint, column_width_topic numeric, column_spacing_topic numeric, layout_format_topic character varying, number_format_topic character varying, fl_image_conf_alter boolean, diagrammed json, diagrammed_images json, images json, alternatives json, question_maths json, alternative_maths json, didi_maths json, column_question smallint, position_question smallint, absolute_position smallint, status character varying, origin jsonb)
    LANGUAGE plpgsql
    AS $$
                DECLARE
                    v_type_materials JSONB;
                BEGIN
                    RETURN QUERY
                    WITH tlb_versions AS (
                        SELECT
                            ou.id AS university_id,
                            (v.value->>'order')::INT AS "order",
                            (v->>'version')::SMALLINT AS version
                        FROM origin_university ou,
                            LATERAL jsonb_array_elements(ou.versions::jsonb) AS v(value)
                        WHERE ou.versions IS NOT NULL
                        AND ou.versions <> '[]'
                    ), tbl_diagrammed AS (
                        SELECT
                            ed.question_id,
                            json_agg(json_build_object(
                                'id', edf.id,
                                'question_id', ed.question_id,
                                'setting_diagrammed_course_id', edf.setting_diagrammed_course_id,
                                'value', edf.value,
                                'position', sd.position,
                                'field_diagram', fd.name
                            ))::TEXT AS diagrammed
                        FROM employee_didi_question ed
                        INNER JOIN question q ON ed.question_id = q.id
                        INNER JOIN employee_didi_question_field edf ON ed.id = edf.employee_didi_question_id AND edf.fl_status = true
                        INNER JOIN setting_diagrammed_courses sd ON edf.setting_diagrammed_course_id = sd.id
                        INNER JOIN field_diagrammed fd ON sd.field_diagram_id = fd.id
                        WHERE ed.fl_status = true
                        AND q.status = 'VERI'
                        AND q.fl_status = true
                        GROUP BY ed.question_id
                    ), tbl_diagrammed_image AS (
                        SELECT
                            ed.question_id,
                            json_agg(json_build_object(
                                'id', edfi.id,
                                'question_id', ed.question_id,
                                'code', edfi.code,
                                'image', edfi.image,
                                'extension', edfi.extension
                            ))::TEXT AS diagrammed_images
                        FROM employee_didi_question ed
                        INNER JOIN question q ON ed.question_id = q.id
                        INNER JOIN employee_didi_question_field_image edfi ON ed.id = edfi.employee_didi_question_id AND edfi.fl_status = true
                        WHERE ed.fl_status = true
                        AND q.status = 'VERI'
                        AND q.fl_status = true
                        GROUP BY ed.question_id
                    ), tbl_question_image AS (
                        SELECT
                            q.id AS question_id,
                            json_agg(json_build_object(
                                'id', qi.id,
                                'question_id', qi.question_id,
                                'code', qi.code,
                                'image', qi.image,
                                'extension', qi.extension
                            ))::TEXT  AS images
                        FROM question q
                        INNER JOIN question_image qi ON q.id = qi.question_id AND qi.fl_status
                        where q.fl_status = true
                        GROUP BY q.id
                    ), tbl_question_math AS (
                        SELECT 
                            qm.question_id,
                            jsonb_agg(json_build_object(
                                'id', qm.id,
                                'code', qm.code,
                                'path', qm.path,
                                'properties', qm.properties
                            ))::TEXT AS question_maths
                        FROM question_maths qm
                        JOIN question q ON q.id = qm.question_id
                        WHERE q.fl_status = TRUE
                        AND qm.fl_status = TRUE
                        GROUP BY qm.question_id
                    ), tbl_alternative_maths AS (
                        SELECT
                            a.question_id,
                            jsonb_agg(json_build_object(
                                'id', am.id,
                                'code', am.code,
                                'path', am.path,
                                'properties', am.properties
                            ))::TEXT AS alternative_maths
                        FROM alternative_maths am
                        join alternative a on a.id = am.alternative_id
                        JOIN question q on q.id = a.question_id
                        GROUP BY a.question_id
                    ), tbl_didi_maths AS (
                        SELECT
                            edq.question_id,
                            jsonb_agg(json_build_object(
                                'id', dm.id,
                                'code', dm.code,
                                'path', dm.path,
                                'properties', dm.properties
                            ))::TEXT AS didi_maths
                        FROM didi_maths dm 
                        LEFT JOIN employee_didi_question_field edqf on edqf.id = dm.didi_question_id
                        LEFT JOIN employee_didi_question edq on edq.id = edqf.employee_didi_question_id
                        LEFT JOIN question q on q.id = edq.question_id
                        GROUP BY edq.question_id
                    ), tbl_active_ballot_questions AS (
                        SELECT
                            mbq.id AS mbq_id,
                            mbq.week_type_material_id,
                            mbq.course_id,
                            mbq.topic_id,
                            mbq.subtopic_id,
                            mbq.level_id,
                            mbq.type,
                            COALESCE(mbq.position, 0) AS position,
                            COALESCE(mbq.absolute_position, 0) AS absolute_position,
                            q.id AS question_id,
                            q.code,
                            q.description AS description_question,
                            q.answer_id,
                            q.parent_id,
                            q.config_alternative_id,
                            q.columns,
                            q.status
                        FROM odiseo.material_ballot_question mbq
                        JOIN odiseo.question q ON q.id = mbq.question_id AND q.fl_status IS TRUE
                        WHERE mbq.fl_status IS TRUE AND mbq.deleted_at IS NULL

                        UNION ALL

                        SELECT
                            mbq.id AS mbq_id,
                            mbq.week_type_material_id,
                            mbq.course_id,
                            mbq.topic_id,
                            mbq.subtopic_id,
                            mbq.level_id,
                            'T' AS type,
                            COALESCE(mbq.position, 0) AS position,
                            COALESCE(mbq.absolute_position, 0) AS absolute_position,
                            subq.id AS question_id,
                            subq.code,
                            subq.description AS description_question,
                            subq.answer_id,
                            subq.parent_id,
                            subq.config_alternative_id,
                            subq.columns,
                            subq.status
                        FROM odiseo.material_ballot_question mbq
                        JOIN odiseo.material_ballot_subquestions mbs ON mbs.material_ballot_question_id = mbq.id AND mbs.fl_status IS TRUE AND mbs.deleted_at IS NULL
                        JOIN odiseo.question subq ON subq.id = mbs.question_id AND subq.fl_status IS TRUE
                        WHERE mbq.fl_status IS TRUE AND mbq.deleted_at IS NULL
                    ), tbl_questions_material AS (
                        SELECT
                            abq.mbq_id AS id,
                            dwt.type_material_id,
                            tm.description AS type_material,
                            course_ordering.position AS order_course,
                            dwt.parent_type_material_id,
                            c.area_id,
                            a.description AS area,
                            abq.course_id,
                            c.name AS course,
                            abq.topic_id,
                            t.code as topic_code,
                            t.name AS topic,
                            abq.subtopic_id::smallint,
                            s.code AS subtopic_code,
                            s.name AS subtopic,
                            abq.level_id,
                            l.name as level,
                            abq.type,
                            abq.question_id,
                            abq.code,
                            abq.description_question,
                            abq.answer_id,
                            abq.parent_id,
                            abq.config_alternative_id,
                            ca.columns,
                            ca.styles,
                            mcc.column_count AS column_count_topic,
                            mcc.column_width AS column_width_topic,
                            mcc.column_spacing AS column_spacing_topic,
                            mcc.layout_format AS layout_format_topic,
                            mcc.number_format AS number_format_topic,
                            ca.fl_image AS fl_image_conf_alter,
                            td.diagrammed::JSON,
                            tdi.diagrammed_images::JSON,
                            qi.images::JSON,
                            CASE
                                WHEN count(al.id) > 0 THEN json_agg(
                                    json_build_object(
                                        'id', al.id,
                                        'question_id', al.question_id,
                                        'description', al.description
                                    ) ORDER BY al.id
                                )
                                ELSE '[]'::json
                            END AS alternatives,
                            tqma.question_maths::JSON,
                            tam.alternative_maths::JSON,
                            tdm.didi_maths::JSON,
                            abq.columns AS column_question,
                            abq.position::smallint AS position_question,
                            abq.absolute_position::smallint AS absolute_position,
                            abq.status,
                            CASE
                                WHEN count(oqu.id) > 0 THEN jsonb_agg(DISTINCT jsonb_build_object(
                                        'id', oqu.id,
                                        'year', oqu.year,
                                        'region_id', oqu.region_id,
                                        'region', oqu.region,
                                        'university_id', oqu.university_id,
                                        'university', oqu.university,
                                        'university_slug', oqu.university_slug,
                                        'option_id', oqu.option_id,
                                        'option', oqu.option,
                                        'modality_id', oqu.modality_id,
                                        'modality', oqu.modality,
                                        'areas', oqu.areas,
                                        'version', fn_number_to_roman(oqu.version),
                                        'order_version', oqu.order_version
                                    )
                                )
                                ELSE '[]'::JSONB
                            END AS origin
                        FROM detail_week_type_mat dwt
                        INNER JOIN material m ON dwt.material_id = m.id
                        JOIN tbl_active_ballot_questions abq ON abq.week_type_material_id = dwt.id
                        INNER JOIN course c ON abq.course_id = c.id
                        INNER JOIN topic t ON abq.topic_id = t.id
                        INNER JOIN subtopic s ON abq.subtopic_id = s.id
                        INNER JOIN level l ON abq.level_id = l.id
                        INNER JOIN type_material tm ON dwt.type_material_id = tm.id
                        INNER JOIN configuration_alternative ca ON abq.config_alternative_id = ca.id
                        INNER JOIN area a ON c.area_id = a.id
                        LEFT JOIN material_column_configurations mcc ON abq.topic_id = mcc.topic_id
                        LEFT JOIN tbl_question_math tqma ON tqma.question_id = abq.question_id
                        LEFT JOIN tbl_alternative_maths tam ON tam.question_id = abq.question_id
                        LEFT JOIN tbl_didi_maths tdm ON tdm.question_id = abq.question_id
                        LEFT JOIN (
                            SELECT
                                ttmco.course_id,
                                tm.id AS type_material_id,
                                ttmco.position
                            FROM template_type_material_courses_order ttmco
                            INNER JOIN type_material tm
                                ON tm.type_material_template_id = ttmco.template_type_material_id
                            WHERE ttmco.university_id IS NULL
                        ) AS course_ordering
                        ON course_ordering.type_material_id = COALESCE(dwt.parent_type_material_id, dwt.type_material_id)
                        AND course_ordering.course_id = abq.course_id
                        -- images
                        LEFT JOIN alternative al ON abq.question_id = al.question_id
                        LEFT JOIN tbl_diagrammed td ON abq.question_id = td.question_id
                        LEFT JOIN tbl_diagrammed_image tdi ON abq.question_id = tdi.question_id
                        LEFT JOIN tbl_question_image qi ON abq.question_id = qi.question_id
                        LEFT JOIN (
                            SELECT DISTINCT
                                oq.id,
                                oq.question_id,
                                oq.year,
                                oq.region_id,
                                r.name AS region,
                                oq.university_id,
                                ou.name AS university,
                                ou.slug AS university_slug,
                                oq.option_id,
                                o.name AS option,
                                oq.modality_id,
                                m.name AS modality,
                                oq.areas,
                                oq.version,
                                tv.order AS order_version
                            FROM origin_question oq
                            LEFT JOIN region r ON oq.region_id = r.id
                            LEFT JOIN origin_university ou ON oq.university_id = ou.id
                            LEFT JOIN option o ON oq.option_id = o.id
                            LEFT JOIN modality m ON oq.modality_id = m.id
                            LEFT JOIN tlb_versions tv ON ou.id = tv.university_id
                                AND oq.version = tv.version
                            WHERE oq.fl_status = TRUE
                            ORDER BY oq.university_id, oq.question_id, oq.year DESC, tv.order ASC
                        ) oqu ON abq.question_id = oqu.question_id
                            AND m.university_id = oqu.university_id
                        WHERE 1 = 1
                        AND abq.week_type_material_id = ANY(SELECT jsonb_array_elements_text(p_week_type_materials)::BIGINT)
                        AND abq.course_id = p_course_id
                        GROUP BY abq.mbq_id,
                            abq.level_id,
                            abq.type,
                            abq.question_id,
                            abq.course_id,
                            abq.topic_id,
                            abq.subtopic_id,
                            dwt.type_material_id,
                            dwt.parent_type_material_id,
                            course_ordering.position,
                            tm.description,
                            c.area_id,
                            c.name,
                            a.description,
                            t.name,
                            t.code,
                            s.name,
                            s.code,
                            l.name,
                            abq.code,
                            abq.description_question,
                            abq.answer_id,
                            abq.parent_id,
                            abq.config_alternative_id,
                            ca.columns,
                            ca.styles,
                            ca.fl_image,
                            mcc.column_count,
                            mcc.column_width,
                            mcc.column_spacing,
                            mcc.layout_format,
                            mcc.number_format,
                            td.diagrammed,
                            tdi.diagrammed_images,
                            qi.images,
                            tdm.didi_maths,
                            tqma.question_maths,
                            tam.alternative_maths,
                            abq.columns,
                            abq.position,
                            abq.absolute_position,
                            abq.status
                    )
                    SELECT tqm.* FROM tbl_questions_material tqm
                    ORDER BY
                        tqm.course,
                        tqm.area,
                        tqm.type_material_id,
                        tqm.absolute_position,
                        tqm.topic_code,
                        tqm.position_question,
                        tqm.subtopic_code,
                        tqm.level,
                        tqm.parent_id,
                        tqm.type,
                        tqm.question_id;
                END;
                $$;


ALTER FUNCTION odiseo.fn_question_material_class_pdf(p_week_type_materials jsonb, p_course_id smallint) OWNER TO postgres;

--
-- Name: fn_question_material_exam_pdf(jsonb, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_question_material_exam_pdf(p_week_exam_areas jsonb, p_course_id smallint) RETURNS TABLE(id bigint, type_material_id smallint, type_material character varying, order_course smallint, parent_type_material_id smallint, area_id bigint, area character varying, course_id smallint, course character varying, course_code character varying, topic_id smallint, topic_code character varying, topic character varying, subtopic_id smallint, subtopic_code character varying, subtopic character varying, level_id bigint, level character varying, type_question text, question_id bigint, code character varying, description_question text, description_parent_question text, answer_id bigint, parent_id bigint, config_alternative_id bigint, columns smallint, column_question smallint, column_count_topic bigint, column_width_topic numeric, column_spacing_topic numeric, layout_format_topic character varying, number_format_topic character varying, fl_image_conf_alter boolean, diagrammed json, diagrammed_images json, images json, alternatives json, question_maths json, alternative_maths json, didi_maths json, area_exam_id smallint, exam_area character varying, "position" smallint, status character varying, text_origin text, fl_is_manual boolean, category character varying, description_b text, text_traduction text, subquestion jsonb, parent_img jsonb, fl_show_in_material_with_solution boolean, fl_show_in_material_without_solution boolean)
    LANGUAGE plpgsql
    AS $$
    DECLARE
        v_type_materials JSONB;
        v_university_id SMALLINT;
    BEGIN
        SELECT
            CASE
                WHEN m.university_id = 16 THEN m.university_id
                ELSE NULL::SMALLINT
            END
        INTO v_university_id
        FROM material_exam_area_week meaw
        JOIN detail_week_type_mat dwtm ON meaw.week_type_material_id = dwtm.id
        JOIN material m ON dwtm.material_id = m.id
        WHERE meaw.id IN (SELECT jsonb_array_elements_text(p_week_exam_areas)::BIGINT)
        LIMIT 1;

        RETURN QUERY
        WITH tlb_versions AS (
            SELECT
                ou.id AS university_id,
                (v.value->>'order')::INT AS "order",
                (v->>'version')::SMALLINT AS version
            FROM origin_university ou,
                LATERAL jsonb_array_elements(ou.versions::jsonb) AS v(value)
            WHERE ou.versions IS NOT NULL
            AND ou.versions <> '[]'
        ), area_ids AS ( -- Filtro de areas
            SELECT jsonb_array_elements_text(p_week_exam_areas)::BIGINT AS exam_area_id
        ), parents_questions_and_subquestions_to_extract AS ( -- <-- Version 1.1
            SELECT
                mepq.material_exam_area_week_id AS material_exam_area_week_id,
                mepq.id AS material_exam_parent_question_id,
                mepq.parent_question_id AS parent_question_id,
                mepq.position AS text_position,
                mepq.course_id AS course_id,
                JSONB_ARRAY_ELEMENTS(mepq.subquestion) AS subquestion
            FROM material_exam_parent_question mepq
            WHERE 1 = 1
            AND mepq.deleted_at IS NULL
            AND mepq.parent_question_id IS NOT NULL
            AND mepq.material_exam_area_week_id IN ( SELECT xd.exam_area_id FROM area_ids xd )
        ), subquestions_extracted AS ( -- <-- Version 1.1
            SELECT 
                pet.material_exam_area_week_id,
                pet.material_exam_parent_question_id,
                pet.parent_question_id,
                pet.text_position,
                pet.course_id,
                (pet.subquestion->>'question_id')::INTEGER AS question_id,
                (pet.subquestion->>'topic_id')::INTEGER AS topic_id,
                (pet.subquestion->>'subtopic_id')::INTEGER AS subtopic_id
            FROM parents_questions_and_subquestions_to_extract pet
            WHERE 1 = 1
            AND (pet.subquestion->>'question_id')::INTEGER IS NOT NULL
        ), tbl_question_exam_initial AS (
            SELECT meq.question_id
            FROM detail_week_type_mat dwt
            INNER JOIN material_exam_area_week meaw ON dwt.id = meaw.week_type_material_id AND meaw.fl_status = true
            INNER JOIN material_exam_question meq ON meaw.id = meq.material_exam_area_week_id AND meq.fl_status = true
            WHERE dwt.fl_status = true
            AND meaw.id IN (SELECT exam_area_id FROM area_ids)

            UNION

            SELECT
                sbs.question_id
            FROM subquestions_extracted sbs -- <-- Version 1.1
        ), tbl_diagrammed AS (
            SELECT
                ed.question_id,
                json_agg(json_build_object(
                    'id', edf.id,
                    'question_id', ed.question_id,
                    'setting_diagrammed_course_id', edf.setting_diagrammed_course_id,
                    'value', edf.value,
                    'position', sd.position,
                    'field_diagram', fd.name
                ))::TEXT AS diagrammed
            FROM employee_didi_question ed
            INNER JOIN question q ON ed.question_id = q.id
            INNER JOIN employee_didi_question_field edf ON ed.id = edf.employee_didi_question_id AND edf.fl_status = true
            INNER JOIN setting_diagrammed_courses sd ON edf.setting_diagrammed_course_id = sd.id
            INNER JOIN field_diagrammed fd ON sd.field_diagram_id = fd.id
            INNER JOIN tbl_question_exam_initial tqei ON q.id = tqei.question_id
            WHERE ed.fl_status = true
            AND q.fl_status = true
            GROUP BY ed.question_id
        ), tbl_diagrammed_image AS (
            SELECT
                ed.question_id,
                json_agg(json_build_object(
                    'id', edfi.id,
                    'question_id', ed.question_id,
                    'code', edfi.code,
                    'image', edfi.image,
                    'extension', edfi.extension
                ))::TEXT AS diagrammed_images
            FROM employee_didi_question ed
            INNER JOIN question q ON ed.question_id = q.id
            INNER JOIN employee_didi_question_field_image edfi ON ed.id = edfi.employee_didi_question_id AND edfi.fl_status = true
            INNER JOIN tbl_question_exam_initial tqei ON q.id = tqei.question_id
            WHERE ed.fl_status = true
            AND q.fl_status = true
            GROUP BY ed.question_id
        ), tbl_question_math AS (
            SELECT
                qm.question_id,
                jsonb_agg(json_build_object(
                    'id', qm.id,
                    'code', qm.code,
                    'path', qm.path,
                    'properties', qm.properties
                ))::TEXT AS question_maths
            FROM question_maths qm
            JOIN question q ON q.id = qm.question_id
            INNER JOIN tbl_question_exam_initial tqei ON q.id = tqei.question_id
            WHERE q.fl_status = TRUE
            AND qm.fl_status = TRUE
            GROUP BY qm.question_id
        ), tbl_alternative_maths AS (
            SELECT
                a.question_id,
                jsonb_agg(json_build_object(
                    'id', am.id,
                    'code', am.code,
                    'path', am.path,
                    'properties', am.properties
                ))::TEXT AS alternative_maths
            FROM alternative_maths am
            JOIN alternative a on a.id = am.alternative_id
            JOIN question q on q.id = a.question_id
            INNER JOIN tbl_question_exam_initial tqei ON q.id = tqei.question_id
            GROUP BY a.question_id
        ), tbl_didi_maths AS (
            SELECT
                edq.question_id,
                jsonb_agg(json_build_object(
                    'id', dm.id,
                    'code', dm.code,
                    'path', dm.path,
                    'properties', dm.properties
                ))::TEXT AS didi_maths
            FROM didi_maths dm
            LEFT JOIN employee_didi_question_field edqf on edqf.id = dm.didi_question_id
            LEFT JOIN employee_didi_question edq on edq.id = edqf.employee_didi_question_id
            LEFT JOIN question q on q.id = edq.question_id
            INNER JOIN tbl_question_exam_initial tqei ON q.id = tqei.question_id
            GROUP BY edq.question_id
        ), tbl_question_image AS (
            SELECT
                q.id AS question_id,
                JSON_AGG(
                    JSONB_BUILD_OBJECT(
                        'id', qi.id,
                        'question_id', qi.question_id,
                        'code', qi.code,
                        'image', qi.image,
                        'extension', qi.extension
                    )
                )::TEXT  AS images
            FROM question q
            INNER JOIN question_image qi ON q.id = qi.question_id AND qi.fl_status
            INNER JOIN tbl_question_exam_initial tqei ON q.id = tqei.question_id
            WHERE q.fl_status = true
            GROUP BY q.id
        ), subquestions_and_parents AS ( -- <-- Version 1.1
            SELECT
                se.material_exam_area_week_id AS material_exam_area_week_id,
                se.material_exam_parent_question_id AS material_exam_parent_question_id,
                se.parent_question_id,
                se.text_position,
                c.name AS course,
                se.course_id,
                c.code AS course_code,
                pqn.code AS code,
                tt.name AS category,
                tts.name AS subcategory,
                t.name AS topic,
                t.code AS topic_code,
                st.name AS subtopic,
                st.code AS subtopic_code,
                pqn.columns AS column_parent_question,
                COALESCE(mcc.column_count, 2) AS column_count_topic,
                mcc.column_width AS column_width_topic,
                mcc.column_spacing AS column_spacing_topic,
                mcc.layout_format AS layout_format_topic,
                mcc.number_format AS number_format_topic,
                ca.fl_image AS fl_image_conf_alter,
                pl.name AS parent_question_level,
                pqn.description AS description_parent_question,
                pqn.description_b AS description_b,
                pqn.text_traduction AS text_traduction,
                dd.diagrammed::JSON AS diagrammed,
                q.columns AS column_question,
                q.answer_id,
                q.code AS question_code,
                q.id AS question_id,
                q.config_alternative_id AS config_alternative_id,
                q.description AS description_question,
                ca.columns,
                ctcs.fl_show_in_material_with_solution,
                ctcs.fl_show_in_material_without_solution
            FROM subquestions_extracted se
            LEFT JOIN parent_question pqn ON pqn.id = se.parent_question_id
            LEFT JOIN level pl ON pl.id = pqn.level_id
            LEFT JOIN question q ON q.id = se.question_id
            LEFT JOIN configuration_alternative ca ON q.config_alternative_id = ca.id
            LEFT JOIN tbl_diagrammed dd ON dd.question_id = se.question_id
            LEFT JOIN type_text tt ON tt.id = pqn.type_text_id
            LEFT JOIN type_text_subcategories tts ON tts.id = pqn.type_text_subcategory_id
            LEFT JOIN course c ON c.id = se.course_id
            LEFT JOIN topic t ON t.id = se.topic_id
            LEFT JOIN material_column_configurations mcc ON mcc.topic_id = se.topic_id /* 1.11 */
            LEFT JOIN subtopic st ON st.id = se.subtopic_id
            LEFT JOIN alternative al ON al.question_id = se.question_id
            LEFT JOIN course_text_category_settings ctcs ON ctcs.course_id = pqn.course_id AND pqn.type_text_id = ctcs.type_text_id
            WHERE 1 = 1
            AND ( p_course_id IS NULL OR se.course_id = p_course_id )
            GROUP BY
                se.material_exam_area_week_id,
                se.material_exam_parent_question_id,
                se.parent_question_id,
                se.text_position,
                pqn.code,
                pqn.columns,
                pqn.description,
                pqn.description_b,
                pqn.text_traduction,
                c.name,
                se.course_id,
                c.code,
                tt.name,
                tts.name,
                t.name,
                t.code,
                st.name,
                st.code,
                mcc.column_count,
                mcc.column_width,
                mcc.column_spacing,
                mcc.layout_format,
                mcc.number_format,
                ca.fl_image,
                pl.name,
                dd.diagrammed,
                q.columns,
                q.answer_id,
                q.code,
                q.id,
                q.config_alternative_id,
                q.description,
                ca.columns,
        ctcs.fl_show_in_material_with_solution,
        ctcs.fl_show_in_material_without_solution
        ), alternatives_on_subquestions AS ( -- <-- Version 1.1
            SELECT
                ssp.question_id,
                CASE
                    WHEN COUNT(al.id) > 0 THEN
                        JSON_AGG(
                            JSON_BUILD_OBJECT(
                                'id', al.id,
                                'question_id', al.question_id,
                                'description', al.description,
                                'value', CASE WHEN ssp.answer_id = al.id THEN TRUE ELSE FALSE END
                            ) ORDER BY al.id
                        )
                    ELSE '[]'::JSON
                END AS alternatives
            FROM subquestions_and_parents ssp
            LEFT JOIN alternative al ON al.question_id = ssp.question_id
            GROUP BY ssp.question_id
        ), subquestions_and_parents_with_alternatives AS ( -- <-- Version 1.1
            SELECT
                sas.*,
                aos.alternatives
            FROM subquestions_and_parents sas
            LEFT JOIN alternatives_on_subquestions aos ON aos.question_id = sas.question_id
        ), tbl_t_questions_material AS ( -- <-- Version 1.1
            SELECT
                sap.material_exam_parent_question_id AS id,
                NULL::smallint AS type_material_id,
                NULL::character varying AS type_material,
                ttmco.position AS order_course,
                NULL::smallint AS parent_type_material_id,
                NULL::bigint AS area_id,
                NULL::character varying AS area,
                sap.course_id::smallint AS course_id,
                sap.course AS course,
                sap.course_code AS course_code,
                NULL::smallint AS topic_id,
                NULL::character varying AS topic_code,
                NULL::character varying AS topic,
                NULL::smallint AS subtopic_id,
                NULL::character varying AS subtopic_code,
                NULL::character varying AS subtopic,
                NULL::bigint AS level_id,
                NULL::character varying AS level,
                'T'::text AS type_question,
                sap.parent_question_id AS question_id,
                sap.code AS code,
                sap.description_parent_question AS description_question,
                sap.description_parent_question AS description_parent_question,
                NULL::bigint AS answer_id,
                sap.parent_question_id AS parent_id,
                NULL::bigint AS config_alternative_id,
                NULL::smallint AS columns,
                sap.column_parent_question AS columns_question,
                sap.column_count_topic AS column_count_topic,
                sap.column_width_topic AS column_width_topic,
                sap.column_spacing_topic AS column_spacing_topic,
                sap.layout_format_topic AS layout_format_topic,
                sap.number_format_topic AS number_format_topic,
                sap.fl_image_conf_alter AS fl_image_conf_alter,
                NULL::json AS diagrammed,
                NULL::json AS diagrammed_images,
                NULL::json AS images,
                NULL::json AS alternatives,
                NULL::json AS question_maths,
                NULL::json AS alternative_maths,
                NULL::json AS didi_maths,
                NULL::smallint AS area_exam_id,
                NULL::character varying AS exam_area,
                sap.text_position AS position,
                NULL::character varying AS status,
                opq.question_origin_text AS text_origin,
                NULL::boolean AS fl_is_manual,
                sap.category AS text_category,
                sap.description_b AS description_b,
                sap.text_traduction AS text_traduction,
                JSONB_AGG(
                    JSONB_BUILD_OBJECT(
                        'topic_name', sap.topic,
                        'subtopic_name', sap.subtopic,
                        'question_id', sap.question_id,
                        'column_question', sap.column_question,
                        'code', sap.question_code,
                        'course', sap.course,
                        'topic_code', sap.topic_code,
                        'subtopic_code', sap.subtopic_code,
                        'course_code', sap.course_code,
                        'description_question', sap.description_question,
                        'alternatives', sap.alternatives,
                        'diagrammed', sap.diagrammed,
                        'answer_id', sap.answer_id,
                        'config_alternative_id', sap.config_alternative_id,
                        'columns', sap.columns
                    )
                ) AS subquestion,
                vpq.parent_img::jsonb AS parent_img,
                sap.fl_show_in_material_with_solution,
                sap.fl_show_in_material_without_solution
            FROM subquestions_and_parents_with_alternatives sap
            LEFT JOIN vm_parent_question_images vpq ON vpq.parent_question_id = sap.parent_question_id
            JOIN material_exam_area_week mek ON mek.id = sap.material_exam_area_week_id
            JOIN detail_week_type_mat dwt ON dwt.id = mek.week_type_material_id
            JOIN material m ON m.id = dwt.material_id
            JOIN type_material tm ON tm.id = COALESCE(dwt.parent_type_material_id, dwt.type_material_id)
            JOIN template_type_material_courses_order ttmco ON ttmco.template_type_material_id = tm.type_material_template_id AND ttmco.course_id = sap.course_id
                AND ttmco.university_id IS NOT DISTINCT FROM v_university_id
            LEFT JOIN v_all_parent_origins_by_university opq ON opq.parent_id = sap.parent_question_id
                AND opq.university_id = m.university_id
            WHERE 1 = 1
            GROUP BY
                sap.material_exam_parent_question_id,
                sap.parent_question_id,
                sap.code,
                sap.category,
                sap.subcategory,
                sap.course,
                sap.course_code,
                sap.course_id,
                sap.parent_question_level,
                sap.material_exam_area_week_id,
                sap.text_position,
                sap.description_parent_question,
                sap.description_b,
                sap.text_traduction,
                sap.column_parent_question,
                sap.column_count_topic,
                sap.column_width_topic,
                sap.column_spacing_topic,
                sap.layout_format_topic,
                sap.number_format_topic,
                sap.fl_image_conf_alter,
                ttmco.position,
                vpq.parent_img::JSONB,
                opq.question_origin_text,
                sap.fl_show_in_material_with_solution,
                sap.fl_show_in_material_without_solution
        ),
        tbl_p_questions_material AS (
            SELECT
                meq.id AS id,
                dwt.type_material_id AS type_material_id,
                tm.description AS type_material,
                ttmco.position AS order_course,
                dwt.parent_type_material_id AS parent_type_material_id,
                c.area_id AS area_id,
                a.description AS area,
                meq.course_id AS course_id,
                c.name AS course,
                c.code AS course_code,
                meq.topic_id AS topic_id,
                t.code AS topic_code,
                t.name AS topic,
                meq.subtopic_id AS subtopic_id,
                s.code AS subtopic_code,
                s.name AS subtopic,
                meq.level_id AS level_id,
                l.name AS level,
                'P'::text AS type_question,
                meq.question_id AS question_id,
                COALESCE(qsh.code, q.code) AS code,
                q.description AS description_question,
                NULL AS description_parent_question,
                q.answer_id AS answer_id,
                q.parent_id AS parent_id,
                q.config_alternative_id AS config_alternative_id,
                ca.columns AS columns,
                q.columns AS columns_question,
                COALESCE(mcc.column_count, 2) AS column_count_topic,
                mcc.column_width AS column_width_topic,
                mcc.column_spacing AS column_spacing_topic,
                mcc.layout_format AS layout_format_topic,
                mcc.number_format AS number_format_topic,
                ca.fl_image AS fl_image_conf_alter,
                td.diagrammed::json AS diagrammed,
                tdi.diagrammed_images::json AS diagrammed_images,
                qi.images::json AS images,
                CASE
                    WHEN count(al.id) > 0 THEN json_agg(
                        json_build_object(
                            'id', al.id,
                            'question_id', al.question_id,
                            'description', al.description,
                            'value', CASE WHEN q.answer_id = al.id THEN TRUE ELSE FALSE END
                        ) ORDER BY al.id
                    )
                    ELSE '[]'::json
                END AS alternatives,
                tqma.question_maths::json,
                tam.alternative_maths::json,
                tdm.didi_maths::json,
                ea.id AS area_exam_id,
                ea.description AS exam_area,
                meq.position AS position,
                q.status AS status,
                oqu.question_origin_text AS text_origin,
                meq.fl_is_manual AS fl_is_manual,
                NULL AS text_category,
                NULL AS description_b,
                NULL AS text_traduction,
                NULL::jsonb AS subquestion,
                NULL::jsonb AS parent_img,
                NULL::boolean fl_show_in_material_with_solution,
                NULL::boolean fl_show_in_material_without_solution
            FROM detail_week_type_mat dwt
            INNER JOIN material m ON dwt.material_id = m.id
            INNER JOIN material_exam_area_week meaw ON dwt.id = meaw.week_type_material_id
            INNER JOIN material_exam_question meq ON meaw.id = meq.material_exam_area_week_id AND meq.fl_status = true
            LEFT JOIN question_shares qsh ON qsh.question_id = meq.question_id AND qsh.deleted_at IS NULL
            INNER JOIN question q ON meq.question_id = q.id
            INNER JOIN course c ON meq.course_id = c.id
            INNER JOIN topic t ON meq.topic_id = t.id
            INNER JOIN subtopic s ON meq.subtopic_id = s.id
            INNER JOIN level l ON meq.level_id = l.id
            INNER JOIN type_material tm ON dwt.type_material_id = tm.id
            INNER JOIN configuration_alternative ca ON q.config_alternative_id = ca.id
            INNER JOIN area a ON c.area_id = a.id
            LEFT JOIN material_column_configurations mcc ON meq.topic_id = mcc.topic_id
            LEFT JOIN template_type_material_courses_order ttmco ON tm.type_material_template_id = ttmco.template_type_material_id
                AND ttmco.course_id = meq.course_id
                AND ttmco.university_id IS NOT DISTINCT FROM v_university_id
            LEFT JOIN alternative al ON q.id = al.question_id
            LEFT JOIN tbl_diagrammed td ON q.id = td.question_id
            LEFT JOIN tbl_diagrammed_image tdi ON q.id = tdi.question_id
            LEFT JOIN tbl_question_image qi ON q.id = qi.question_id
            LEFT JOIN tbl_question_math tqma ON tqma.question_id = q.id
            LEFT JOIN tbl_alternative_maths tam ON tam.question_id = q.id
            LEFT JOIN exam_area ea ON ea.id = meaw.area_id AND ea.fl_status = true
            LEFT JOIN tbl_didi_maths tdm ON tdm.question_id = q.id
            LEFT JOIN v_all_question_origins_by_university oqu ON meq.question_id = oqu.question_id
                AND oqu.university_id = m.university_id
            WHERE 1 = 1 
            AND meaw.id IN ( SELECT xe.exam_area_id FROM area_ids xe )
            AND ( p_course_id IS NULL OR meq.course_id = p_course_id )
            GROUP BY
                meq.id,
                dwt.type_material_id,
                dwt.parent_type_material_id,
                ttmco.position,
                tm.description,
                c.area_id,
                a.description,
                meq.course_id,
                c.name,
                c.code,
                meq.topic_id,
                t.name,
                meq.subtopic_id,
                s.name,
                meq.level_id,
                meq.question_id,
                COALESCE(qsh.code, q.code),
                q.description,
                q.answer_id,
                q.parent_id,
                q.config_alternative_id,
                mcc.column_count,
                mcc.column_width,
                mcc.column_spacing,
                mcc.layout_format,
                mcc.number_format,
                ca.fl_image,
                td.diagrammed,
                tdi.diagrammed_images,
                qi.images,
                t.code,
                s.code,
                l.name,
                tdm.didi_maths,
                tqma.question_maths,
                tam.alternative_maths,
                q.columns,
                ea.id,
                meq.position,
                q.status,
                ca.columns,
                oqu.question_origin_text
        ), text_with_subquestions_and_questions AS  (
            SELECT * FROM tbl_t_questions_material -- <-- Version 1.1
            UNION ALL
            SELECT * FROM tbl_p_questions_material
        )
        SELECT tqm.* FROM text_with_subquestions_and_questions tqm
        ORDER BY
            tqm.order_course,
            tqm.position,
            tqm.type_question DESC,
            tqm.topic_code,
            tqm.subtopic_code,
            tqm.level,
            tqm.parent_id,
            tqm.question_id;
    END;
    $$;


ALTER FUNCTION odiseo.fn_question_material_exam_pdf(p_week_exam_areas jsonb, p_course_id smallint) OWNER TO postgres;

--
-- Name: fn_question_parent_with_image(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_question_parent_with_image(p_parent_question_id integer) RETURNS TABLE(id bigint, code character varying, description text, text_traduction text, description_b text, type_text_id bigint, type_text_subcategory_id bigint, parent_img jsonb)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY 
                        select 
                        pq.id,
                        pq.code,
                        pq.description,
                        pq.text_traduction,
						pq.description_b,
						pq.type_text_id,
						pq.type_text_subcategory_id,
                        (
                            SELECT jsonb_agg(jsonb_build_object(
                            'id',pi.id,
                            'code',pi.code,
                            'image',pi.image))
                            from odiseo.parent_image pi
                            where pi.parent_id = pq.id
                            and pi.fl_status = true
                        ) as parent_img
                        from odiseo.parent_question pq 
                        where pq.id = p_parent_question_id;
                END;
            
$$;


ALTER FUNCTION odiseo.fn_question_parent_with_image(p_parent_question_id integer) OWNER TO postgres;

--
-- Name: fn_question_teacher_ia_by_id(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_question_teacher_ia_by_id(p_id bigint) RETURNS TABLE(id bigint, description text, description_short text, course_id smallint, course_code character varying, course character varying, area_id bigint, course_alias_nq character varying, topic_id smallint, topic_code character varying, topic character varying, subtopic_id smallint, subtopic_code character varying, subtopic character varying, microtopic character varying, level_id bigint, level character varying, description_level character varying, answer_id bigint, answer_description text, answer_option character varying, theoretical_basis text, argumentation text, format character varying, type character varying, content character varying, teacher_id bigint, teacher character varying, status_revised boolean, date_revised timestamp without time zone, alternatives json, images json, images_solution json, version smallint, chat_feedback_id bigint, diagram_params json)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        SELECT
            qtia.id,
            qtia.description,
            qtia.description_short,
            qtia.course_id,
            c.code AS course_code,
            c.name AS course,
            c.area_id,
            c.alias_nq AS course_alias_nq,
            qtia.topic_id,
            t.code AS topic_code,
            t.name AS topic,
            qtia.subtopic_id,
            st.code AS subtopic_code,
            st.name AS subtopic,
            qtia.microtopic,
            qtia.level_id,
            l.name AS level,
            l.description AS description_level,
            qtia.answer_id,
            qtia.answer_description,
            answer_aqia.option AS answer_option,
            qtia.theoretical_basis,
            qtia.argumentation,
            qtia.format,
            qtia.type,
            qtia.content,
            qtia.teacher_id,
            CONCAT(e.first_name, ' ', e.first_surname, ' ', e.second_surname)::VARCHAR AS teacher,
            qtia.status_revised,
            oqnq.date_revised,
            (
                SELECT json_agg(row_to_json(a))
                FROM (
                    SELECT aqia.id, aqia.description, aqia.option,
                    (
                        SELECT json_agg(row_to_json(alt_img))
                        FROM (
                            SELECT aimg.code, aimg.extension, aimg.image, aimg.alternative_ia_id
                            FROM alternative_ia_images aimg
                            WHERE aimg.alternative_ia_id = aqia.id
                                AND aimg.fl_status = true
                            ORDER BY aimg.id ASC
                        ) AS alt_img
                    ) AS images
                    FROM alternative_questions_ia aqia
                    WHERE aqia.question_ia_id = qtia.id
                        AND aqia.fl_status = true
                    ORDER BY aqia.option ASC
                ) AS a
            ) AS alternatives,
            (
                SELECT json_agg(row_to_json(img))
                FROM (
                    SELECT qimg.code, qimg.extension, qimg.image, qimg.question_ia_id
                    FROM question_ia_images qimg
                    WHERE qimg.question_ia_id = qtia.id
                        AND qimg.fl_status = true
                    ORDER BY qimg.id ASC
                ) AS img
            ) AS images,
            (
                SELECT json_agg(row_to_json(sol_img))
                FROM (
                    SELECT simg.code, simg.extension, simg.image, simg.solution_ia_id
                    FROM solution_ia_images simg
                    WHERE simg.solution_ia_id = qtia.id
                        AND simg.fl_status = true
                    ORDER BY simg.id ASC
                ) AS sol_img
            ) AS images_solution,
            qtia.version,
            qtia.chat_feedback_id,
            (
                SELECT json_agg(
                    json_build_object(
                        'field',    fd.name_nq,
                        'name',     fd.name,
                        'field_diagrammed_id', fd.id,
                        'value',    qfdn.content
                    ) ORDER BY qfdn.position
                )
                FROM question_field_diagrammed_nq qfdn
                JOIN field_diagrammed fd ON fd.id = qfdn.field_diagrammed_id
                WHERE qfdn.question_teacher_ia_id = qtia.id
            ) AS diagram_params
        FROM question_teacher_ia qtia
        JOIN course c ON c.id = qtia.course_id
        JOIN topic t ON t.id = qtia.topic_id
        JOIN subtopic st ON st.id = qtia.subtopic_id
        JOIN level l ON l.id = qtia.level_id
        LEFT JOIN employees e ON e.id = qtia.teacher_id
        JOIN alternative_questions_ia answer_aqia ON answer_aqia.question_ia_id = qtia.id
            AND answer_aqia.id = qtia.answer_id
        LEFT JOIN origin_question_nq oqnq ON qtia.id = oqnq.question_ia_id
        WHERE qtia.id = p_id
            AND qtia.fl_status = true
            AND qtia.fl_parent = false;
    END;
    $$;


ALTER FUNCTION odiseo.fn_question_teacher_ia_by_id(p_id bigint) OWNER TO postgres;

--
-- Name: fn_question_verified_and_not_excluded_material(bigint, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_question_verified_and_not_excluded_material(p_material_id bigint, p_fl_validate_code boolean) RETURNS TABLE(id bigint, code character varying, course_id smallint, topic_id smallint, level_id smallint, level smallint, type character varying, status character varying, subtopic_id integer, frequent_subtopic boolean, cycle_id integer, week smallint, type_material_id smallint, history jsonb)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY
                    WITH tbl_material AS (
                        SELECT
                            m.university_id,
                            m.company_id
                        FROM material m
                        WHERE m.id = p_material_id
                    ), tbl_questions_ballot_material AS (
                        SELECT DISTINCT mbq.question_id FROM material m
                        INNER JOIN detail_week_type_mat wt ON m.id = wt.material_id AND wt.fl_status = true
                        INNER JOIN material_ballot_question mbq ON wt.id = mbq.week_type_material_id AND mbq.fl_status = true
                        WHERE m.id = p_material_id
                    ), tbl_questions_exam AS (
                        SELECT DISTINCT meq.question_id FROM material_exam_question meq
                        INNER JOIN material_exam_area_week meaw ON meq.material_exam_area_week_id = meaw.id AND meaw.fl_status = true
                        INNER JOIN detail_week_type_mat wt ON meaw.week_type_material_id = wt.id
                        WHERE wt.material_id = p_material_id
                        AND wt.fl_status = true
                        AND meaw.fl_status = true
                        AND meq.fl_status = true
                    ), max_start_per_question AS (
                        SELECT
                            qh.question_id,
                            MAX(c.start_date) AS max_start_date
                        FROM question_history_cycle qh
                        INNER JOIN cycle c ON qh.cycle_id = c.id
                        WHERE qh.fl_status = true
                            AND qh.university_id IN (SELECT tm.university_id FROM tbl_material tm)
                            AND c.company_id IN (SELECT tm.company_id FROM tbl_material tm)
                        GROUP BY qh.question_id
                    ), tbl_questions_history AS (
                        SELECT DISTINCT
                            qh.question_id,
                            qh.cycle_id,
                            c.description,
                            c.start_date,
                            c.end_date
                        FROM question_history_cycle qh
                        INNER JOIN cycle c ON qh.cycle_id = c.id
                        INNER JOIN max_start_per_question mx ON qh.question_id = mx.question_id
                        WHERE qh.fl_status = true
                            AND qh.university_id IN (SELECT tm.university_id FROM tbl_material tm)
                            AND c.start_date BETWEEN mx.max_start_date - INTERVAL '21 days' AND mx.max_start_date
                            AND c.company_id IN (SELECT tm.company_id FROM tbl_material tm)
                    ), tbl_questions AS (
                        SELECT
                            q.id,
                            q.code,
                            q.course_id,
                            q.topic_id,
                            q.level_id,
                            l.name::SMALLINT AS level,
                            q.type,
                            q.status,
                            qs.subtopic_id,
                            COALESCE(fus.is_frequent, false) AS frequent_subtopic,
                            qt.cycle_id,
                            qt.week_id AS week,
                            qt.type_material_id,
                            COALESCE(
                                JSON_AGG(
                                    JSONB_BUILD_OBJECT(
                                        'cycle_id', qh.cycle_id,
                                        'description', qh.description,
                                        'start_date', qh.start_date,
                                        'end_date', qh.end_date
                                    )
                                    ORDER BY qh.start_date DESC
                                ) FILTER (WHERE qh.cycle_id IS NOT NULL)::JSONB, '[]'::JSONB
                            ) AS history
                        FROM question q
                        LEFT JOIN question_subtopic qs ON qs.question_id = q.id AND qs.fl_status = true
                        LEFT JOIN question_temporary qt ON qt.question_id = q.id AND qt.fl_status = true
                        LEFT JOIN level l ON l.id = q.level_id
                        LEFT JOIN tbl_questions_history qh ON q.id = qh.question_id
                        LEFT JOIN frequent_university_subtopic fus ON fus.university_id IN (SELECT tm.university_id FROM tbl_material tm) AND fus.subtopic_id = qs.subtopic_id AND fus.fl_status = true
                        WHERE q.status IN ('VERI', 'APRB')
                        AND q.fl_status = true
                        AND l.fl_status = true
                        AND q.parent_id IS NULL
                        AND NOT EXISTS (
                            SELECT 1 FROM (
                                SELECT question_id FROM tbl_questions_ballot_material
                                UNION ALL
                                SELECT question_id FROM tbl_questions_exam
                            ) gpm
                            WHERE gpm.question_id = q.id
                        )
                        AND NOT EXISTS (
                            SELECT 1
                                FROM question_excluded_material qem
                                WHERE qem.question_id = q.id
                                AND qem.material_id = p_material_id
                                AND qem.deleted_at IS NULL
                        )
                        AND ( -- Filtra si es examen o tienen la validación en true deberia de no usar los codigos que empiezan con 'D'
                            -- Se quito la validación por codigo, ahora no toma en cuenta el codigo o que empiezan con 'D'
                            q.number_question IS NULL
                            OR q.number_question NOT LIKE 'D%'
                        )
                        GROUP BY
                            q.id,
                            q.code,
                            q.course_id,
                            q.topic_id,
                            q.level_id,
                            l.name,
                            q.type,
                            q.status,
                            qs.subtopic_id,
                            fus.is_frequent,
                            qt.cycle_id,
                            qt.week_id,
                            qt.type_material_id
                    )
                    SELECT tq.* FROM tbl_questions tq
                    ORDER BY tq.id DESC, tq.topic_id ASC, tq.subtopic_id ASC;
                END;
                $$;


ALTER FUNCTION odiseo.fn_question_verified_and_not_excluded_material(p_material_id bigint, p_fl_validate_code boolean) OWNER TO postgres;

--
-- Name: fn_question_verified_duplicate(smallint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_question_verified_duplicate(p_course_id smallint, p_parent_id bigint, p_question_id bigint) RETURNS TABLE(id bigint, code character varying, description text, short_description text, course_id smallint, parent_id bigint)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        SELECT
            q.id,
            q.code,
            q.description,
            q.short_description,
            q.course_id,
            q.parent_id
        FROM question q
        WHERE q.fl_status = true
        AND q.course_id = p_course_id
        AND q.short_description IS NOT NULL
        AND q.status NOT IN ('DUPL', 'ARCH')
        AND (
            (p_parent_id IS NULL AND q.parent_id IS NULL)
            OR (p_parent_id IS NOT NULL AND q.parent_id = p_parent_id)
        )
        AND q.id <> p_question_id
        ORDER BY q.id ASC;
    END;
    $$;


ALTER FUNCTION odiseo.fn_question_verified_duplicate(p_course_id smallint, p_parent_id bigint, p_question_id bigint) OWNER TO postgres;

--
-- Name: fn_question_verified_material(bigint, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_question_verified_material(p_material_id bigint, p_fl_validate_code boolean) RETURNS TABLE(id bigint, code character varying, course_id smallint, topic_id smallint, level_id smallint, level smallint, type character varying, status character varying, subtopic_id integer, frequent_subtopic boolean, cycle_id integer, week smallint, type_material_id smallint, history jsonb)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            WITH tbl_material AS ( -- Obtener ciclo y universidad del material mandado
                SELECT
                    m.university_id,
                    m.company_id
                FROM material m
                WHERE m.id = p_material_id
            ), tbl_questions_ballot_material AS ( -- Se lista las preguntas de la tabla de balotarios
                SELECT DISTINCT mbq.question_id FROM material m
                INNER JOIN detail_week_type_mat wt ON m.id = wt.material_id AND wt.fl_status = true
                INNER JOIN material_ballot_question mbq ON wt.id = mbq.week_type_material_id AND mbq.fl_status = true
                WHERE m.id = p_material_id
            ), tbl_questions_exam AS ( -- Se lista las preguntas de la tabla de examenes
                SELECT DISTINCT meq.question_id FROM material_exam_question meq
                INNER JOIN material_exam_area_week meaw ON meq.material_exam_area_week_id = meaw.id AND meaw.fl_status = true
                INNER JOIN detail_week_type_mat wt ON meaw.week_type_material_id = wt.id
                WHERE wt.material_id = p_material_id
                AND wt.fl_status = true
                AND meaw.fl_status = true
                AND meq.fl_status = true
            ), max_start_per_question AS ( -- Se lista la fecha de inicio más reciente para cada pregunta
                SELECT
                    qh.question_id,
                    MAX(c.start_date) AS max_start_date
                FROM question_history_cycle qh
                INNER JOIN cycle c ON qh.cycle_id = c.id
                WHERE qh.fl_status = true
                AND qh.university_id = (SELECT tm.university_id FROM tbl_material tm)
                AND c.company_id = (SELECT tm.company_id FROM tbl_material tm)
                GROUP BY qh.question_id
            ), tbl_questions_history AS ( -- Se trae le historial de cada pregunta
                SELECT DISTINCT
                    qh.question_id,
                    qh.cycle_id,
                    c.description,
                    c.start_date,
                    c.end_date
                FROM question_history_cycle qh
                INNER JOIN cycle c ON qh.cycle_id = c.id
                INNER JOIN max_start_per_question mx ON qh.question_id = mx.question_id
                WHERE qh.fl_status = true
                AND qh.university_id = (SELECT tm.university_id FROM tbl_material tm)
                AND c.company_id = (SELECT tm.company_id FROM tbl_material tm)
                AND c.start_date BETWEEN mx.max_start_date - INTERVAL '21 days' AND mx.max_start_date
            ), tbl_questions_history_agg AS (
                SELECT
                    th.question_id,
                    COALESCE(
                        JSON_AGG(
                            JSONB_BUILD_OBJECT(
                                'cycle_id', th.cycle_id,
                                'description', th.description,
                                'start_date', th.start_date,
                                'end_date', th.end_date
                            )
                            ORDER BY th.start_date DESC
                        ) FILTER (WHERE th.cycle_id IS NOT NULL)::JSONB, '[]'::JSONB
                    ) AS history
                FROM tbl_questions_history th
                GROUP BY th.question_id
            ), tbl_questions AS ( -- Se lista todas las preguntas verificadas y/o aprobadas
                SELECT
                    q.id,
                    q.code,
                    q.course_id,
                    q.topic_id,
                    q.level_id,
                    l.name::SMALLINT AS level,
                    q.type,
                    q.status,
                    qs.subtopic_id,
                    COALESCE(fus.is_frequent, false) AS frequent_subtopic,
                    NULL::INT AS cycle_id,
                    NULL::SMALLINT AS week,
                    NULL::SMALLINT AS type_material_id,
                    COALESCE(qha.history, '[]'::JSONB) AS history
                FROM question q
                LEFT JOIN question_subtopic qs ON qs.question_id = q.id AND qs.fl_status = true
                LEFT JOIN level l ON l.id = q.level_id
                LEFT JOIN tbl_questions_history_agg qha ON q.id = qha.question_id
                LEFT JOIN frequent_university_subtopic fus ON fus.university_id = (SELECT tm.university_id FROM tbl_material tm) AND fus.subtopic_id = qs.subtopic_id AND fus.fl_status = true
                WHERE q.status IN ('VERI', 'APRB')
                AND q.fl_status = true
                AND l.fl_status = true
                AND q.parent_id IS NULL
                AND NOT EXISTS (
                    SELECT 1 FROM (
                        SELECT question_id FROM tbl_questions_ballot_material
                        UNION ALL
                        SELECT question_id FROM tbl_questions_exam
                    ) gpm
                    WHERE gpm.question_id = q.id
                )
                AND ( -- Filtra si es examen o tienen la validación en true deberia de no usar los codigos que empiezan con 'D'
                    -- Se quito la validación por codigo, ahora no toma en cuenta el codigo o que empiezan con 'D'
                    q.number_question IS NULL
                    OR q.number_question NOT LIKE 'D%'
				)

                UNION ALL

                SELECT
                    q.id,
                    qs2.code,
                    qs2.course_id::smallint,
                    qs2.topic_id,
                    q.level_id,
                    l.name::SMALLINT AS level,
                    q.type,
                    q.status,
                    qs2.subtopic_id,
                    COALESCE(fus.is_frequent, false) AS frequent_subtopic,
                    NULL::INT AS cycle_id,
                    NULL::SMALLINT AS week,
                    NULL::SMALLINT AS type_material_id,
                    COALESCE(qha.history, '[]'::JSONB) AS history
                FROM question q
                INNER JOIN question_shares qs2 ON qs2.question_id = q.id AND qs2.deleted_at IS NULL
                LEFT JOIN question_subtopic qs ON qs.question_id = q.id AND qs.fl_status = true
                LEFT JOIN level l ON l.id = q.level_id
                LEFT JOIN tbl_questions_history_agg qha ON q.id = qha.question_id
                LEFT JOIN frequent_university_subtopic fus ON fus.university_id = (SELECT tm.university_id FROM tbl_material tm) AND fus.subtopic_id = qs.subtopic_id AND fus.fl_status = true
                WHERE q.status IN ('VERI', 'APRB')
                AND q.fl_status = true
                AND l.fl_status = true
                AND q.parent_id IS NULL
                AND NOT EXISTS (
                    SELECT 1 FROM (
                        SELECT question_id FROM tbl_questions_ballot_material
                        UNION ALL
                        SELECT question_id FROM tbl_questions_exam
                    ) gpm
                    WHERE gpm.question_id = q.id
                )
                AND ( -- Filtra si es examen o tienen la validación en true deberia de no usar los codigos que empiezan con 'D'
                    -- Se quito la validación por codigo, ahora no toma en cuenta el codigo o que empiezan con 'D'
                    q.number_question IS NULL
                    OR q.number_question NOT LIKE 'D%'
				)
            )
            SELECT tq.* FROM tbl_questions tq
            ORDER BY tq.id DESC, tq.topic_id ASC, tq.subtopic_id ASC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_question_verified_material(p_material_id bigint, p_fl_validate_code boolean) OWNER TO postgres;

--
-- Name: fn_question_verified_material_pagination(integer, integer, jsonb, character varying, smallint, smallint, bigint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_question_verified_material_pagination(p_perpage integer, p_npage integer, p_subtopics_filter jsonb, p_search character varying, p_course_id smallint, p_topic_id smallint, p_subtopic_id bigint, p_level_id smallint, p_material_id bigint) RETURNS TABLE(id bigint, code character varying, course_id smallint, course text, topic_id smallint, topic text, level_id smallint, level smallint, type character varying, status character varying, subtopic_id integer, subtopic text, frequent_subtopic boolean, cycle_id integer, week smallint, type_material_id smallint, history jsonb, total_count bigint)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            offset_val INTEGER;
        BEGIN
            offset_val := p_perpage * (p_npage - 1);

            RETURN QUERY
            WITH tbl_questions_verified AS (
                SELECT
                   	fqvm.id,
                   	fqvm.code,
                   	fqvm.course_id,
					CONCAT(c.code, '-', c.name) AS course,
                   	fqvm.topic_id,
					CONCAT(t.code, '-', t.name) AS topic,
                   	fqvm.level_id,
                   	fqvm.level,
                   	fqvm.type,
                   	fqvm.status,
                   	fqvm.subtopic_id,
					CONCAT(s.code, '-', s.name) AS subtopic,
                   	fqvm.frequent_subtopic,
                   	fqvm.cycle_id,
                   	fqvm.week,
                   	fqvm.type_material_id,
                   	fqvm.history
               	FROM fn_question_verified_material(p_material_id) fqvm
				INNER JOIN course c ON fqvm.course_id = c.id
				INNER JOIN topic t ON fqvm.topic_id = t.id
				INNER JOIN subtopic s ON fqvm.subtopic_id = s.id
                WHERE fqvm.subtopic_id IN (
                    SELECT value::INT FROM jsonb_each_text(p_subtopics_filter)
                )
            ), tbl_questions_filtered AS (
                SELECT tqv.* FROM tbl_questions_verified tqv
				WHERE 1 = 1
                    AND (p_search IS NULL OR tqv.code ILIKE '%' || p_search || '%')
                    AND (p_course_id IS NULL OR tqv.course_id = p_course_id)
                    AND (p_topic_id IS NULL OR tqv.topic_id = p_topic_id)
                    AND (p_subtopic_id IS NULL OR tqv.subtopic_id = p_subtopic_id)
                    AND (p_level_id IS NULL OR tqv.level_id = p_level_id)
			)
            SELECT *, count(*) OVER () AS total_count
            FROM tbl_questions_filtered as tqv
            ORDER BY tqv.course_id ASC, tqv.topic ASC, tqv.subtopic ASC, tqv.id ASC
            LIMIT p_perpage
            OFFSET offset_val;
        END;
        $$;


ALTER FUNCTION odiseo.fn_question_verified_material_pagination(p_perpage integer, p_npage integer, p_subtopics_filter jsonb, p_search character varying, p_course_id smallint, p_topic_id smallint, p_subtopic_id bigint, p_level_id smallint, p_material_id bigint) OWNER TO postgres;

--
-- Name: fn_questions_area_deleted(bigint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_questions_area_deleted(p_material_id bigint, p_week smallint, p_type_material_id bigint) RETURNS TABLE(id bigint, code character varying, course_id smallint, topic_id smallint, level_id smallint, level smallint, type character varying, status character varying, subtopic_id integer, frequent_subtopic boolean, cycle_id integer, week smallint, type_material_id smallint, history jsonb)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_university_id SMALLINT;
        BEGIN
            SELECT m.university_id INTO v_university_id
            FROM material m WHERE m.id = p_material_id LIMIT 1;

            RETURN QUERY
            WITH tbl_questions_area AS (
                SELECT
                    meq.question_id,
                    COUNT(meq.question_id) AS total
                FROM material_exam_question meq
				INNER JOIN material_exam_area_week meaw ON meq.material_exam_area_week_id = meaw.id
				INNER JOIN detail_week_type_mat dwtm ON meaw.week_type_material_id = dwtm.id
				WHERE dwtm.material_id = p_material_id
                    AND dwtm.week = p_week
                    AND dwtm.type_material_id = p_type_material_id
                    AND dwtm.fl_status = true
                    AND meaw.fl_status = true
                    AND meq.fl_status = true
				GROUP BY meq.question_id
				HAVING COUNT(meq.question_id) > 1
				ORDER BY total DESC, meq.question_id ASC
            ), tbl_question AS (
                SELECT
                    q.id,
                    q.code,
                    q.course_id,
                    q.topic_id,
                    q.level_id,
                    l.name::SMALLINT AS level,
                    q.type,
                    q.status,
                    qs.subtopic_id,
                    COALESCE(fus.is_frequent, false) AS frequent_subtopic,
                    qt.cycle_id,
                    qt.week_id AS week,
                    qt.type_material_id,
                    '[]'::JSONB AS history
                FROM question q
                LEFT JOIN question_subtopic qs ON qs.question_id = q.id AND qs.fl_status = true
                LEFT JOIN question_temporary qt ON qt.question_id = q.id AND qt.fl_status = true
                LEFT JOIN level l ON l.id = q.level_id
                LEFT JOIN frequent_university_subtopic fus ON fus.university_id = v_university_id AND fus.subtopic_id = qs.subtopic_id AND fus.fl_status = true
                INNER JOIN (
                    SELECT meq.question_id, COUNT(meq.question_id) AS total FROM material_exam_question meq
                    INNER JOIN material_exam_area_week meaw ON meq.material_exam_area_week_id = meaw.id
                    INNER JOIN detail_week_type_mat dwtm ON meaw.week_type_material_id = dwtm.id
                    WHERE dwtm.material_id = p_material_id
                    AND dwtm.week = p_week
                    AND dwtm.type_material_id = p_type_material_id
                    AND dwtm.fl_status = true
                    AND meaw.fl_status = true
                    AND meq.fl_status = true
                    GROUP BY meq.question_id
                    HAVING COUNT(meq.question_id) > 1
                    ORDER BY total DESC, meq.question_id ASC
                ) question_area ON q.id = question_area.question_id
                WHERE q.status = 'VERI'
                AND q.fl_status = true
                AND l.fl_status = true
                AND (
                    q.number_question IS NULL
                    OR q.number_question NOT ILIKE 'D%'
                )
            ), tbl_question_final AS (
                SELECT tbl.* FROM tbl_question tbl
                INNER JOIN tbl_questions_area tba ON tbl.id = tba.question_id
            )
            SELECT * FROM tbl_question_final ORDER BY topic_id ASC, subtopic_id ASC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_questions_area_deleted(p_material_id bigint, p_week smallint, p_type_material_id bigint) OWNER TO postgres;

--
-- Name: fn_questions_verified_by_type_material_week(bigint, smallint, smallint, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_questions_verified_by_type_material_week(p_material_id bigint, p_type_material_id smallint, p_week smallint, p_area_id smallint) RETURNS TABLE(id bigint, code character varying, course_id smallint, course text, topic_id smallint, topic text, level_id smallint, level smallint, type character varying, status character varying, subtopic_id integer, subtopic text, frequent_subtopic boolean, cycle_id integer, week smallint, type_material_id smallint, history jsonb)
    LANGUAGE plpgsql
    AS $$
                    DECLARE
                        v_fl_exam BOOLEAN;
                    BEGIN
                        IF p_area_id IS NULL THEN
                            v_fl_exam := FALSE;
                        ELSE
                            v_fl_exam := TRUE;
                        END IF;

                        RETURN QUERY
                        WITH tbl_material AS ( -- Se traen los datos del material
                            SELECT
                                m.cycle_id, m.university_id
                            FROM material m
                            LEFT JOIN cycle c ON m.cycle_id = c.id
                            WHERE m.id = p_material_id
                        ), tbl_type_material AS ( -- Se traen los datos del tipo de material
                            SELECT
                                tm.id, tmt.fl_exam, tmt.type_exam_id, tm.type_material_template_id, tm.cycle_id
                            FROM type_material tm
                            INNER JOIN type_material_template tmt ON tm.type_material_template_id = tmt.id
                            WHERE tm.id = p_type_material_id
                        ), children_type_material AS ( -- Se lista los hijos del tipo material si es que los tiene
                            SELECT DISTINCT
                                tm.id,
                                tm.fl_exam
                            FROM type_material_bound tmb
                            INNER JOIN type_material tm
                            ON tmb.type_material_template_extra_id = tm.type_material_template_id
                            WHERE 1 = 1
                            AND tmb.fl_status = true
                            AND tmb.type_material_template_id IN (SELECT type_material_template_id FROM tbl_type_material)
                            AND tm.cycle_id IN (SELECT tm2.cycle_id FROM tbl_material tm2)
                        ), has_children AS ( -- Verifica si existen hijos del tipo material
                            SELECT COUNT(*) > 0 AS has_data FROM children_type_material
                        ), type_material_chosen AS ( -- Se selecciona el tipo material si tiene hijos o no
                            SELECT tmc.*
                            FROM (
                                SELECT ctm.id, ctm.fl_exam FROM children_type_material ctm
                                WHERE (SELECT has_data FROM has_children)
                                UNION ALL
                                SELECT ctm.id, ctm.fl_exam FROM tbl_type_material ctm
                                WHERE NOT (SELECT has_data FROM has_children)
                            ) tmc
                            WHERE tmc.fl_exam = FALSE
                        ), weeks AS ( -- Se seleccionan las semanas del tipo material
                            SELECT generate_series(1, p_week) AS week
                        ), week_chosen AS ( -- Se aplica validacion a usar las semanas
                            SELECT
                                ws.week,
                                ttm.fl_exam,
                                ttm.type_exam_id,
                                CASE
                                    WHEN ttm.fl_exam IS FALSE AND ws.week = p_week THEN TRUE
                                    WHEN ttm.fl_exam IS TRUE AND ttm.type_exam_id = 3 THEN TRUE
                                    WHEN ttm.fl_exam IS TRUE AND ttm.type_exam_id <> 4 AND ws.week = p_week THEN TRUE
                                    ELSE FALSE
                                END AS week_value
                            FROM weeks ws
                            LEFT JOIN tbl_type_material ttm ON 1 = 1
                        ), tbl_syllabus AS ( -- Se listar los subtemas del syllabus
                            SELECT DISTINCT
                                sds.subtopic_id
                            FROM syllabus_subtopic_type_material stm
                            INNER JOIN syllabus_detail_subtopic sds ON stm.syllabus_detail_subtopic_id = sds.id AND sds.fl_status = true
                            INNER JOIN syllabus_topic_week stw ON sds.syllabus_topic_week_id = stw.id AND stw.fl_status = true
                            INNER JOIN syllabus_topic st ON stw.syllabus_topic_id = st.id AND st.fl_status = true
                            INNER JOIN syllabus s ON st.syllabus_id = s.id
                            INNER JOIN course co ON s.course_id = co.id
                            INNER JOIN topic top ON st.topic_id = top.id
                            INNER JOIN subtopic su ON sds.subtopic_id = su.id
                            WHERE stm.fl_status = true
                            AND s.fl_status = true
                            AND s.university_id IN (SELECT tm.university_id FROM tbl_material tm)
                            AND s.cycle_id IN (SELECT tm.cycle_id FROM tbl_material tm)
                            AND (
                                NOT EXISTS (SELECT wc.week FROM week_chosen wc WHERE wc.week_value = TRUE)
                                OR stw.week IN (SELECT wc.week FROM week_chosen wc WHERE wc.week_value = TRUE)
                            )
                            AND stm.questions_amount > 0
                            ORDER BY sds.subtopic_id ASC
                        ), tbl_questions_verified_filter AS ( -- Se listan las preguntas verificadas a usar
                            SELECT
                                fqvm.id,
                                fqvm.code,
                                fqvm.course_id,
                                CONCAT(c.code, '-', c.name) AS course,
                                fqvm.topic_id,
                                CONCAT(t.code, '-', t.name) AS topic,
                                fqvm.level_id,
                                fqvm.level,
                                fqvm.type,
                                fqvm.status,
                                fqvm.subtopic_id,
                                CONCAT(s.code, '-', s.name) AS subtopic,
                                fqvm.frequent_subtopic,
                                fqvm.cycle_id,
                                fqvm.week,
                                fqvm.type_material_id,
                                fqvm.history
                            FROM fn_question_verified_material(p_material_id, v_fl_exam) fqvm
                            INNER JOIN course c ON fqvm.course_id = c.id
                            INNER JOIN topic t ON fqvm.topic_id = t.id
                            INNER JOIN subtopic s ON fqvm.subtopic_id = s.id
                            WHERE fqvm.subtopic_id IN (SELECT tb.subtopic_id FROM tbl_syllabus tb)
                        ), tbl_questions_area AS (
                            SELECT DISTINCT
                                meq.question_id
                            FROM material_exam_question meq
                            INNER JOIN material_exam_area_week meaw ON meq.material_exam_area_week_id = meaw.id AND meaw.fl_status = true
                            INNER JOIN detail_week_type_mat dwtm ON meaw.week_type_material_id = dwtm.id AND dwtm.fl_status = true
                            WHERE dwtm.material_id = p_material_id
                                AND dwtm.week = p_week
                                AND dwtm.type_material_id = p_type_material_id
                                AND meq.fl_status = true
                                AND meaw.area_id = p_area_id
                                AND meq.question_id IS NOT NULL
                        ), tbl_questions_area_repeat AS ( -- Se listan las preguntas repetidas en otras areas
                            SELECT DISTINCT
                                meq.question_id
                            FROM material_exam_question meq
                            INNER JOIN material_exam_area_week meaw ON meq.material_exam_area_week_id = meaw.id AND meaw.fl_status = true
                            INNER JOIN detail_week_type_mat dwtm ON meaw.week_type_material_id = dwtm.id AND dwtm.fl_status = true
                            WHERE dwtm.material_id = p_material_id
                                AND dwtm.week = p_week
                                AND dwtm.type_material_id = p_type_material_id
                                AND meq.fl_status = true
                                AND (p_area_id IS NULL OR meaw.area_id <> p_area_id)
                                AND meq.question_id NOT IN (
                                    SELECT * FROM tbl_questions_area
                                )
                        ), tbl_questions_areas AS ( -- Se listan las preguntas de las areas seleccionadas
                            SELECT
                                q.id,
                                q.code,
                                q.course_id,
                                CONCAT(c.code, '-', c.name) AS course,
                                q.topic_id,
                                CONCAT(t.code, '-', t.name) AS topic,
                                q.level_id,
                                l.name::SMALLINT AS level,
                                q.type,
                                q.status,
                                qs.subtopic_id,
                                CONCAT(s.code, '-', s.name) AS subtopic,
                                COALESCE(fus.is_frequent, false) AS frequent_subtopic,
                                qt.cycle_id,
                                qt.week_id AS week,
                                qt.type_material_id,
                                '[]'::JSONB AS history
                            FROM question q
                            INNER JOIN course c ON q.course_id = c.id
                            INNER JOIN topic t ON q.topic_id = t.id
                            LEFT JOIN question_subtopic qs ON qs.question_id = q.id AND qs.fl_status = true
                            LEFT JOIN question_temporary qt ON qt.question_id = q.id AND qt.fl_status = true
                            LEFT JOIN subtopic s ON qs.subtopic_id = s.id
                            LEFT JOIN level l ON l.id = q.level_id
                            LEFT JOIN frequent_university_subtopic fus ON fus.university_id = 1 AND fus.subtopic_id = qs.subtopic_id AND fus.fl_status = true
                            WHERE 1= 1
                                AND q.id IN (SELECT * FROM tbl_questions_area_repeat)
                                AND q.status IN ('VERI', 'APRB')
                                AND q.fl_status = true
                                AND l.fl_status = true
                                AND ( -- Filtra si es examen o tienen la validación en true deberia de no usar los codigos que empiezan con 'D'
                                    -- Se quito la validación por codigo, ahora no toma en cuenta el codigo o que empiezan con 'D'
                                    q.number_question IS NULL
                                    OR q.number_question NOT LIKE 'D%'
                                )
                            ORDER BY q.id ASC
                        ), tbl_questions AS ( -- Se unen las preguntas verificadas y las de las areas
                            SELECT * FROM tbl_questions_verified_filter
                            UNION ALL
                            SELECT * FROM tbl_questions_areas
                        )
                        SELECT tq.*
                        FROM tbl_questions as tq
                        ORDER BY tq.course_id ASC, tq.topic ASC, tq.subtopic ASC, tq.id ASC;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_questions_verified_by_type_material_week(p_material_id bigint, p_type_material_id smallint, p_week smallint, p_area_id smallint) OWNER TO postgres;

--
-- Name: fn_reassign_missing_question(bigint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_reassign_missing_question(p_detail_id bigint, p_new_employee_id bigint, p_created_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_old_employee_id BIGINT;
BEGIN
    SELECT employee_id INTO v_old_employee_id
    FROM material_missing_question_detail
    WHERE id = p_detail_id;

    UPDATE material_missing_question_detail
    SET employee_id = p_new_employee_id,
        assignment_type = 'manual',
        status = 'assigned',
        updated_at = now()
    WHERE id = p_detail_id;

    -- Tracking: unassigned del empleado anterior
    INSERT INTO material_missing_question_tracking (
        material_missing_question_detail_id,
        employee_id,
        action,
        assignment_type,
        created_by,
        created_at,
        updated_at
    ) VALUES (
        p_detail_id,
        v_old_employee_id,
        'unassigned',
        NULL,
        p_created_by,
        now(),
        now()
    );

    -- Tracking: reassigned al nuevo empleado
    INSERT INTO material_missing_question_tracking (
        material_missing_question_detail_id,
        employee_id,
        action,
        assignment_type,
        created_by,
        created_at,
        updated_at
    ) VALUES (
        p_detail_id,
        p_new_employee_id,
        'reassigned',
        'manual',
        p_created_by,
        now(),
        now()
    );
END;
$$;


ALTER FUNCTION odiseo.fn_reassign_missing_question(p_detail_id bigint, p_new_employee_id bigint, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_rebuild_parent_search_text(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_rebuild_parent_search_text(v_parent_id bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'odiseo', 'public'
    AS $$
                    DECLARE
                        v_new_search_text TEXT;
                    BEGIN
                        SELECT 
                            COALESCE(pq_alias.code, '') || ' ' || 
                            COALESCE(pq_alias.number_question, '') || ' ' || 
                            COALESCE(pq_alias.short_description, '') || ' ' ||
                            STRING_AGG(COALESCE(sub.search_text, ''), ' ')
                        INTO
                            v_new_search_text
                        FROM parent_question pq_alias
                        LEFT JOIN question sub ON pq_alias.id = sub.parent_id
                        WHERE pq_alias.id = v_parent_id
                        GROUP BY pq_alias.id;

                        UPDATE parent_question pq
                        SET 
                            search_text = v_new_search_text
                        WHERE 
                            pq.id = v_parent_id
                            AND COALESCE(pq.search_text, '') <> COALESCE(v_new_search_text, '');

                    END;
                    $$;


ALTER FUNCTION odiseo.fn_rebuild_parent_search_text(v_parent_id bigint) OWNER TO postgres;

--
-- Name: fn_region(character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_region(p_name_text character varying) RETURNS TABLE(id bigint, name character varying)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    r.id,
                    r.name
                FROM odiseo.region r
                WHERE r.fl_status = true
				AND (
                    p_name_text IS NULL
                    OR LOWER(r.name) LIKE '%' || LOWER(p_name_text) || '%'
                )
				ORDER BY r.id ASC;
            END;
            $$;


ALTER FUNCTION odiseo.fn_region(p_name_text character varying) OWNER TO postgres;

--
-- Name: fn_register_material_ballot_per_period(bigint, bigint, smallint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_register_material_ballot_per_period(p_material_id bigint, p_type_material_id bigint, p_start_week smallint, p_end_week smallint, p_created_by bigint) RETURNS TABLE(id bigint, type_material character varying)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_material_per_period_id BIGINT;
            v_material_per_period_ballot_id BIGINT;
            v_type_material VARCHAR;
        BEGIN
            -- Traer el nombre del tipo material
            SELECT
                tm.description INTO v_type_material
            FROM type_material tm
            WHERE tm.id = p_type_material_id;

            -- Obtener el id del material por period
            SELECT
                mpp.id INTO v_material_per_period_id
            FROM material_per_period mpp
            WHERE mpp.material_id = p_material_id
                AND mpp.type_material_id = p_type_material_id
                AND mpp.deleted_by IS NULL
            LIMIT 1;

            -- Insertar si no lo encuentra
            IF v_material_per_period_id IS NULL THEN
                INSERT INTO material_per_period AS mpp2 (
                    material_id,
                    type_material_id,
                    created_by,
                    created_at
                )
                VALUES (
                    p_material_id,
                    p_type_material_id,
                    p_created_by,
                    NOW()
                )
                RETURNING mpp2.id INTO v_material_per_period_id;
            END IF;

            -- Se elimina los periodos del tipo material que esten dentro del rango para evitar duplicados
            UPDATE material_per_period_ballot_url mppbu
            SET deleted_by = p_created_by,
                deleted_at = NOW()
            WHERE mppbu.material_per_period_ballot_id IN (
                SELECT mppb.id
                FROM material_per_period_ballot mppb
                WHERE mppb.material_per_period_id = v_material_per_period_id
                AND (
                    mppb.start_week BETWEEN p_start_week AND p_end_week
                    OR mppb.end_week BETWEEN p_start_week AND p_end_week
                )
                AND NOT (mppb.start_week = p_start_week AND mppb.end_week = p_end_week)
            );

            UPDATE material_per_period_ballot mppb2
            SET deleted_by = p_created_by,
                deleted_at = NOW()
            WHERE mppb2.material_per_period_id = v_material_per_period_id
                AND (
                    mppb2.start_week BETWEEN p_start_week AND p_end_week
                    OR mppb2.end_week BETWEEN p_start_week AND p_end_week
                )
                AND NOT (mppb2.start_week = p_start_week AND mppb2.end_week = p_end_week);

            -- Validar si existe
            SELECT
                mppb3.id INTO v_material_per_period_ballot_id
            FROM material_per_period_ballot mppb3
            WHERE mppb3.material_per_period_id = v_material_per_period_id
                AND mppb3.start_week = p_start_week
                AND mppb3.end_week = p_end_week
                AND mppb3.deleted_by IS NULL
            LIMIT 1;

            IF v_material_per_period_ballot_id IS NULL THEN
                INSERT INTO material_per_period_ballot AS mppb4 (
                    material_per_period_id,
                    start_week,
                    end_week,
                    fl_config_type,
                    lower_level_limit,
                    upper_level_limit,
                    created_by,
                    created_at
                )
                VALUES (
                    v_material_per_period_id,
                    p_start_week,
                    p_end_week,
                    true,
                    0,
                    0,
                    p_created_by,
                    NOW()
                )
                RETURNING mppb4.id INTO v_material_per_period_ballot_id;
            END IF;

            RETURN QUERY
            SELECT v_material_per_period_ballot_id, v_type_material;
        END;
        $$;


ALTER FUNCTION odiseo.fn_register_material_ballot_per_period(p_material_id bigint, p_type_material_id bigint, p_start_week smallint, p_end_week smallint, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_register_questions_ballot(bigint, smallint, boolean, boolean, boolean, jsonb, jsonb, jsonb, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_register_questions_ballot(p_material_per_period_ballot_id bigint, p_week_type_material_id smallint, p_fl_missing_questions boolean, p_fl_missing_courses boolean, p_fl_missing_text boolean, p_save_questions jsonb, p_distribution_questions jsonb, p_register_and_completed_question_ids jsonb, p_register_and_completed_parent_ids jsonb, p_created_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_material_id bigint;
    v_week smallint;
    v_cycle_id bigint;
    v_university_id smallint;
    v_headquarters_id bigint;
    v_type_material_id smallint;
    v_parent_type_material_id smallint;
    v_record_found boolean;
    v_request_date timestamp;
    v_material_distribution_ballot_questions_ids bigint[];
BEGIN
    -- 1. Obtener datos de contexto.
    SELECT
        m.id,
        dwtm.week,
        m.cycle_id,
        m.university_id,
        m.headquarte_id,
        dwtm.type_material_id,
        dwtm.parent_type_material_id,
        COALESCE(dwtm.updated_at, NOW())
        INTO 
        v_material_id,
        v_week,
        v_cycle_id,
        v_university_id,
        v_headquarters_id,
        v_type_material_id,
        v_parent_type_material_id,
        v_request_date
    FROM
        detail_week_type_mat dwtm
        JOIN material m ON dwtm.material_id = m.id
    WHERE
        dwtm.id = p_week_type_material_id;
    GET DIAGNOSTICS v_record_found = ROW_COUNT;

    IF NOT v_record_found THEN
        RAISE EXCEPTION 'No hay data en la tabla week_type_material_id: %', p_week_type_material_id;
    END IF;
    
    -- 2. Actualizar las flags del balotario.
    UPDATE
        material_per_period_ballot mppb
    SET
        fl_missing_questions = mppb.fl_missing_questions
        OR p_fl_missing_questions,
        fl_missing_courses = mppb.fl_missing_courses
        OR p_fl_missing_courses,
        fl_missing_text = mppb.fl_missing_text
        OR p_fl_missing_text
    WHERE
        mppb.id = p_material_per_period_ballot_id;
        
    -- 3. Limpiar y crear la tabla temporal.
    DROP TABLE IF EXISTS temp_input_questions;
    CREATE TEMP TABLE temp_input_questions (
        question_id bigint,
        course_id smallint,
        topic_id smallint,
        subtopic_id smallint,
        level_id bigint,
        type VARCHAR,
        position bigint,
        parent_question_id bigint,
        category_id bigint,
        sub_category_id bigint,
        subquestion jsonb
    ) ON COMMIT DROP;
    
    INSERT INTO temp_input_questions
    SELECT
        (q ->> 'question_id')::bigint,
        (q ->> 'course_id')::smallint,
        (q ->> 'topic_id')::smallint,
        (q ->> 'subtopic_id')::smallint,
        (q ->> 'level_id')::bigint,
        (q ->> 'type')::varchar,
        (q ->> 'position')::bigint,
        (q ->> 'parent_question_id')::bigint,
        (q ->> 'category_id')::bigint,
        (q ->> 'sub_category_id')::bigint,
        (q ->> 'subquestion')::jsonb
    FROM
        jsonb_array_elements(p_save_questions) AS q;
        
    -- 4. MERGE en question_history_cycle (insertar solo si no existe).
    MERGE INTO question_history_cycle AS target
    USING temp_input_questions AS source ON COALESCE(target.question_id, target.parent_question_id) = COALESCE(source.question_id, source.parent_question_id)
            AND target.cycle_id = v_cycle_id
            AND target.university_id = v_university_id
            AND target.headquarters_id = v_headquarters_id
            AND target.fl_status = TRUE
    WHEN NOT MATCHED THEN
        INSERT (question_id, cycle_id, university_id, headquarters_id, created_by, created_at, parent_question_id)
            VALUES (source.question_id, v_cycle_id, v_university_id, v_headquarters_id, p_created_by, NOW(), source.parent_question_id);
            
    -- 5. Crear tabla temporal para la distribución y preparar datos
    DROP TABLE IF EXISTS temp_distribution_questions;
    CREATE TEMP TABLE temp_distribution_questions AS
    SELECT
        (dist ->> 'course_id')::smallint AS course_id,
        (dist ->> 'topic_id')::smallint AS topic_id,
        (dist ->> 'subtopic_id')::smallint AS subtopic_id,
        (dist ->> 'level_id')::bigint AS level_id,
        (dist ->> 'usage_level_id')::bigint AS usage_level_id,
        (dist ->> 'type')::varchar AS type,
        (dist ->> 'question_id')::bigint AS question_id,
        (dist ->> 'parent_question_id')::bigint AS parent_question_id,
        (dist ->> 'position')::bigint AS position,
        (dist ->> 'position_initial')::bigint AS position_initial,
        (dist ->> 'status_usage')::boolean AS status_usage,
        (dist ->> 'absolute_position')::smallint AS absolute_position,
        (dist ->> 'category_id')::smallint AS type_text_id,
        (dist ->> 'sub_category_id')::smallint AS type_text_subcategory_id,
        (dist ->> 'subquestion')::jsonb AS subquestion
    FROM
        jsonb_array_elements(p_distribution_questions) dist;

    -- 6. Insertar en material_ballot_question todo el esqueleto y preguntas
    DROP TABLE IF EXISTS temp_inserted_mbq;
    CREATE TEMP TABLE temp_inserted_mbq AS
    WITH inserted_mbq AS (
        INSERT INTO material_ballot_question (
            week_type_material_id, material_id, week, type_material_id,
            course_id, topic_id, subtopic_id, level_id, usage_level_id, type,
            question_id, parent_question_id, question_history_id, position,
            position_initial, absolute_position, usage_status,
            type_text_id, type_text_subcategory_id, state,
            created_by, created_at
        )
        SELECT
            p_week_type_material_id, v_material_id, v_week, v_type_material_id,
            dist.course_id, dist.topic_id, dist.subtopic_id, dist.level_id,
            dist.usage_level_id, dist.type, dist.question_id, dist.parent_question_id,
            qhc.id, dist.position, dist.position_initial, dist.absolute_position, dist.status_usage,
            dist.type_text_id, dist.type_text_subcategory_id,
            CASE 
                WHEN dist.question_id IS NULL AND dist.parent_question_id IS NULL THEN 'MISSING'::varchar
                ELSE 'GENERATED'::varchar
            END AS state,
            p_created_by, NOW()
        FROM temp_distribution_questions dist
        LEFT JOIN question_history_cycle qhc 
            ON COALESCE(qhc.question_id, qhc.parent_question_id) = COALESCE(dist.question_id, dist.parent_question_id)
            AND qhc.cycle_id = v_cycle_id
            AND qhc.university_id = v_university_id
            AND qhc.headquarters_id = v_headquarters_id
            AND qhc.fl_status = TRUE
        ON CONFLICT (week_type_material_id, (COALESCE(question_id, 0)), (COALESCE(parent_question_id, 0))) 
        WHERE fl_status = TRUE AND deleted_at IS NULL AND (question_id IS NOT NULL OR parent_question_id IS NOT NULL)
        DO UPDATE SET
            material_id = EXCLUDED.material_id,
            week = EXCLUDED.week,
            type_material_id = EXCLUDED.type_material_id,
            course_id = EXCLUDED.course_id,
            topic_id = EXCLUDED.topic_id,
            subtopic_id = EXCLUDED.subtopic_id,
            level_id = EXCLUDED.level_id,
            usage_level_id = EXCLUDED.usage_level_id,
            type = EXCLUDED.type,
            question_history_id = EXCLUDED.question_history_id,
            position = EXCLUDED.position,
            position_initial = EXCLUDED.position_initial,
            absolute_position = EXCLUDED.absolute_position,
            usage_status = EXCLUDED.usage_status,
            type_text_id = EXCLUDED.type_text_id,
            type_text_subcategory_id = EXCLUDED.type_text_subcategory_id,
            state = EXCLUDED.state,
            updated_by = EXCLUDED.created_by,
            updated_at = NOW()
        RETURNING id, COALESCE(question_id, 0) AS q_key, COALESCE(parent_question_id, 0) AS pq_key
    )
    SELECT imbq.id, dist.subquestion
    FROM inserted_mbq imbq
    LEFT JOIN temp_distribution_questions dist
      ON COALESCE(dist.question_id, 0) = imbq.q_key
      AND COALESCE(dist.parent_question_id, 0) = imbq.pq_key;

    -- Guardamos los IDs insertados/actualizados para las completadas
    SELECT array_agg(id)
    INTO v_material_distribution_ballot_questions_ids
    FROM temp_inserted_mbq;

    -- 7. Actualizar eliminados lógicos de subpreguntas e insertar las nuevas
    UPDATE material_ballot_subquestions
    SET fl_status = FALSE, deleted_at = NOW()
    WHERE material_ballot_question_id IN (SELECT id FROM temp_inserted_mbq)
      AND fl_status = TRUE;

    INSERT INTO material_ballot_subquestions (material_ballot_question_id, question_id, position, state, topic_id, course_id, subtopic_id, created_by)
    SELECT
        mbq.id,
        (elem->>'question_id')::BIGINT,
        row_number() OVER(PARTITION BY mbq.id ORDER BY (elem->>'position')::INT2 NULLS LAST)::INT2,
        CASE WHEN (elem->>'question_id') IS NOT NULL THEN 'GENERATED'::varchar ELSE 'MISSING'::varchar END,
        (elem->>'topic_id')::SMALLINT,
        (elem->>'course_id')::SMALLINT,
        (elem->>'subtopic_id')::SMALLINT,
        p_created_by
    FROM temp_inserted_mbq mbq
    CROSS JOIN LATERAL jsonb_array_elements(mbq.subquestion) AS elem
    WHERE mbq.subquestion IS NOT NULL 
      AND jsonb_typeof(mbq.subquestion) = 'array'
    ON CONFLICT DO NOTHING;

    -- ==========================================================================
    -- 8. Actualizar el valor de las completadas (ahora sobre material_ballot_question)
    -- ==========================================================================
    UPDATE material_ballot_question mbq
    SET added_in_completion = true,
        state = 'AUTO_COMPLETED',
        updated_at = NOW(),
        updated_by = p_created_by
    WHERE mbq.id = ANY(v_material_distribution_ballot_questions_ids)
        AND mbq.question_id IN (
            SELECT value::BIGINT
            FROM jsonb_array_elements_text(p_register_and_completed_question_ids)
        );

    UPDATE material_ballot_question mbq
    SET added_in_completion = true,
        completed_subquestion = true,
        state = 'AUTO_COMPLETED',
        updated_at = NOW(),
        updated_by = p_created_by
    WHERE mbq.id = ANY(v_material_distribution_ballot_questions_ids)
        AND mbq.parent_question_id IN (
            SELECT value::BIGINT
            FROM jsonb_array_elements_text(p_register_and_completed_parent_ids)
        );
END;
$$;


ALTER FUNCTION odiseo.fn_register_questions_ballot(p_material_per_period_ballot_id bigint, p_week_type_material_id smallint, p_fl_missing_questions boolean, p_fl_missing_courses boolean, p_fl_missing_text boolean, p_save_questions jsonb, p_distribution_questions jsonb, p_register_and_completed_question_ids jsonb, p_register_and_completed_parent_ids jsonb, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_remove_question_all_areas_from_material_exam(bigint, bigint, smallint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_remove_question_all_areas_from_material_exam(p_question_id bigint, p_material_id bigint, p_type_material_id smallint, p_week smallint, p_updated_by bigint) RETURNS TABLE(id bigint, question_id bigint, question_history_id bigint, type_material_id smallint, type_material character varying, week smallint, course_id smallint, code_course character varying, course character varying, topic_id smallint, code_topic character varying, topic character varying, subtopic_id smallint, code_subtopic character varying, subtopic character varying, level_id bigint, level_description character varying, level_name character varying, area_id smallint, exam_area character varying, data_incomplete_questions character varying, material_exam_area_week_id bigint, week_type_material_id bigint, type character varying)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        WITH context_material AS (
            SELECT
                meaw.id as material_exam_area_week_id,
                meaw.week_type_material_id,
                meaw.area_id
            FROM detail_week_type_mat dwtm
            JOIN material_exam_area_week meaw ON dwtm.id = meaw.week_type_material_id
            WHERE dwtm.material_id = p_material_id
                AND dwtm.type_material_id = p_type_material_id
                AND dwtm.week = p_week
                AND meaw.fl_status = TRUE
        ), week_type_material AS (
            SELECT
                cm.week_type_material_id
            FROM context_material cm
        ), all_occurrences_to_delete AS (
            SELECT
                meq.id,
                meq.question_id,
                meq.question_history_id
            FROM material_exam_question meq
            JOIN material_exam_area_week meaw ON meq.material_exam_area_week_id = meaw.id
            WHERE meq.fl_status = TRUE
                AND meq.question_id = p_question_id
                AND meaw.week_type_material_id IN (SELECT cm.week_type_material_id FROM context_material cm)
        ), get_questions_deleted AS (
            SELECT
                meq.id,
                meq.question_id,
                meq.question_history_id,
                dwtm.type_material_id,
                tm.description AS type_material,
                dwtm.week,
                meq.course_id,
                c.code AS code_course,
                c.name AS course,
                meq.topic_id,
                t.code AS code_topic,
                t.name AS topic,
                meq.subtopic_id,
                st.code AS code_subtopic,
                st.name AS subtopic,
                meq.level_id,
                l.description AS level_description,
                l.name AS level_name,
                meaw.area_id,
                ea.description AS exam_area,
                meaw.data_incomplete_questions,
                meaw.id AS material_exam_area_week_id,
                dwtm.id AS week_type_material_id,
                meq.type
            FROM material_exam_question meq
            JOIN material_exam_area_week meaw ON meq.material_exam_area_week_id = meaw.id
            JOIN detail_week_type_mat dwtm ON meaw.week_type_material_id = dwtm.id
            JOIN exam_area ea ON meaw.area_id = ea.id
            JOIN type_material tm ON dwtm.type_material_id = tm.id
            JOIN course c ON meq.course_id = c.id
            LEFT JOIN topic t ON meq.topic_id = t.id
            LEFT JOIN subtopic st ON meq.subtopic_id = st.id
            LEFT JOIN level l ON meq.level_id = l.id
            WHERE meq.fl_status = TRUE
                AND meq.question_id = p_question_id
                AND meaw.week_type_material_id IN (SELECT cm.week_type_material_id FROM context_material cm)
        ), exam_update_result AS (
            UPDATE material_exam_question meq
            SET
                topic_id = null,
                subtopic_id = null,
                question_id = null,
                question_history_id = null,
                fl_is_manual = true,
                type = null,
                updated_by = p_updated_by,
                updated_at = now()
            FROM all_occurrences_to_delete aod
            WHERE meq.id = aod.id
            RETURNING
                meq.id, meq.question_id, meq.question_history_id,
                meq.material_exam_area_week_id, meq.course_id,
                meq.subtopic_id, meq.topic_id, meq.level_id
        ), update_history AS (
            UPDATE question_history_cycle qhc
            SET
                fl_status = FALSE,
                deleted_by = p_updated_by,
                deleted_at = NOW()
            WHERE qhc.id IN (SELECT actd.question_history_id FROM all_occurrences_to_delete actd)
            AND NOT EXISTS (
                SELECT 1 FROM material_ballot_question mbq
                WHERE mbq.question_history_id = qhc.id AND mbq.fl_status = TRUE
            )
            AND NOT EXISTS (
                SELECT 1 FROM material_exam_question meq
                WHERE meq.question_history_id = qhc.id AND meq.fl_status = TRUE
                    AND meq.id NOT IN (SELECT actd.id FROM all_occurrences_to_delete actd)
            )
        )
        SELECT
            gqd.*
        FROM get_questions_deleted gqd;
    END;
    $$;


ALTER FUNCTION odiseo.fn_remove_question_all_areas_from_material_exam(p_question_id bigint, p_material_id bigint, p_type_material_id smallint, p_week smallint, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_remove_question_from_material_ballot(integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_remove_question_from_material_ballot(p_week_type_material_id integer, p_deleted_by integer, p_question_id integer) RETURNS TABLE(id bigint, material_distribution_id bigint, type_material_id smallint, week smallint, course_id smallint, code_course character varying, course character varying, subtopic_id smallint, code_subtopic character varying, subtopic character varying, topic_id smallint, code_topic character varying, topic character varying, level_id bigint, level_description character varying, level_name character varying, question_id bigint, type character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH ballot_with_questions AS (
        SELECT
            mbq.id AS id,
            mbq.id AS material_distribution_id,
            mbq.type_material_id,
            mbq.week,
            mbq.course_id,
            c.code::character varying AS course_code,
            c.name::character varying AS course,
            mbq.subtopic_id,
            st.code::character varying AS subtopic_code,
            st.name::character varying AS subtopic,
            mbq.topic_id,
            t.code::character varying AS topic_code,
            t.name::character varying AS topic,
            mbq.level_id,
            l.description::character varying AS level_description,
            l.name::character varying AS level_name,
            q.id AS question_id,
            (CASE WHEN mbq.parent_question_id IS NOT NULL THEN 'T'::varchar ELSE 'D'::varchar END)::character varying AS type,
            mbq.question_history_id
        FROM odiseo.material_ballot_question mbq
        INNER JOIN odiseo.detail_week_type_mat dwtm ON mbq.week_type_material_id = dwtm.id
        LEFT JOIN odiseo.question q ON q.id = mbq.question_id
        INNER JOIN odiseo.course c ON mbq.course_id = c.id
        LEFT JOIN odiseo.topic t ON t.id = mbq.topic_id
        LEFT JOIN odiseo.subtopic st ON st.id = mbq.subtopic_id
        LEFT JOIN odiseo.level l ON mbq.level_id = l.id
        WHERE mbq.fl_status IS TRUE
        AND mbq.week_type_material_id = p_week_type_material_id
        AND mbq.question_id = p_question_id
    ),
    slot_to_update AS (
        UPDATE odiseo.material_ballot_question mbqu
        SET
            usage_level_id = NULL,
            usage_status = TRUE,
            question_id = NULL,
            parent_question_id = NULL,
            state = 'MISSING',
            updated_by = p_deleted_by,
            updated_at = NOW(),
            added_in_completion = FALSE,
            removed_in_completion = FALSE
        WHERE mbqu.id IN (SELECT bq.id FROM ballot_with_questions bq)
        RETURNING mbqu.id
    ),
    subquestions_to_delete AS (
        UPDATE odiseo.material_ballot_subquestions mbs
        SET
            fl_status = FALSE,
            deleted_at = NOW()
        WHERE mbs.material_ballot_question_id IN (SELECT su.id FROM slot_to_update su)
          AND mbs.fl_status = TRUE
        RETURNING mbs.id
    ),
    question_history_cycle_to_update AS (
        UPDATE odiseo.question_history_cycle qhc
        SET
            fl_status = FALSE,
            deleted_by = p_deleted_by,
            deleted_at = NOW()
        WHERE qhc.id IN (SELECT bq.question_history_id FROM ballot_with_questions bq WHERE bq.question_history_id IS NOT NULL)
        AND NOT EXISTS ( 
            SELECT 1 FROM odiseo.material_ballot_question mqq
            WHERE mqq.fl_status IS TRUE
            AND mqq.question_history_id = qhc.id
            AND mqq.id NOT IN (SELECT su.id FROM slot_to_update su)
        )
        AND NOT EXISTS ( 
            SELECT 1 FROM odiseo.material_exam_question meq
            WHERE meq.fl_status IS TRUE
            AND meq.question_history_id = qhc.id
        )
        RETURNING qhc.id
    )
    SELECT
        bq.id,
        bq.material_distribution_id,
        bq.type_material_id,
        bq.week,
        bq.course_id,
        bq.course_code,
        bq.course,
        bq.subtopic_id,
        bq.subtopic_code,
        bq.subtopic,
        bq.topic_id,
        bq.topic_code,
        bq.topic,
        bq.level_id,
        bq.level_description,
        bq.level_name,
        bq.question_id,
        bq.type
    FROM ballot_with_questions bq;
END;
$$;


ALTER FUNCTION odiseo.fn_remove_question_from_material_ballot(p_week_type_material_id integer, p_deleted_by integer, p_question_id integer) OWNER TO postgres;

--
-- Name: fn_remove_text_material_exam(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_remove_text_material_exam(p_material_exam_parent_question_id bigint, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
    BEGIN
    /*
        Creación de función en base de datos
        Función para remover textos en examen de un area dada

        ------------------------------------------------------------------------------------
        -- HISTORIAL DE CAMBIOS
        ------------------------------------------------------------------------------------

        Versión: 1.1
        Fecha: 2025-11-03
        Autor: Anderson Vallejo
        Descripción:
            Remover el texto seleccionado y sus subpreguntas en una de
            las filas de la tabla material_exam_parent_question
            
    */
        WITH exam_parent_question AS (
            SELECT
                material_exam_area_week_id,
                parent_question_id,
                question_history_id,
                COALESCE(
                    (
                        SELECT JSONB_AGG(
                            (
                                SELECT JSONB_OBJECT_AGG(k, NULL)
                                FROM JSONB_OBJECT_KEYS(elem) AS k
                            )
                        )
                        FROM JSONB_ARRAY_ELEMENTS(subquestion) AS elem
                    ),
                    '[]'::JSONB
                ) AS empty_subquestion
            FROM material_exam_parent_question
            WHERE id = p_material_exam_parent_question_id
            LIMIT 1
        ), deactive_question_history_in_text_exam AS (
            UPDATE question_history_usage_exam_parent_question
               SET
                  updated_at = NOW(),
                  updated_by = p_updated_by
            WHERE 1 = 1
              AND updated_at IS NULL
              AND material_exam_area_week_id IN ( SELECT material_exam_area_week_id FROM exam_parent_question )
              AND parent_question_id IN ( SELECT parent_question_id FROM exam_parent_question )
        )
        UPDATE material_exam_parent_question
            SET
                parent_question_id = NULL,
                position = NULL,
                random = NULL,
                subquestion = ( SELECT empty_subquestion FROM exam_parent_question ),
                question_history_id = NULL,
                updated_at = NOW(),
                updated_by = p_updated_by
        WHERE id = p_material_exam_parent_question_id;
    END;
$$;


ALTER FUNCTION odiseo.fn_remove_text_material_exam(p_material_exam_parent_question_id bigint, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_remove_type_material_template(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_remove_type_material_template(p_type_material_template_id bigint, p_deleted_by bigint) RETURNS json
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_deleted_id odiseo.type_material_template.id%TYPE;
            BEGIN
                -- Verificar si hay tipos de material asociados al template
                IF EXISTS (
                    SELECT 1 FROM odiseo.type_material
                    WHERE type_material_template_id = p_type_material_template_id
                    AND fl_status = TRUE
                    AND deleted_at IS NULL
                ) THEN
                    RETURN json_build_object(
                        'status', 409,
                        'message', 'No se puede eliminar el template debido a que tiene tipos de material asociados'
                    );
                END IF;

                -- Intentar eliminar el template
                UPDATE odiseo.type_material_template
                SET deleted_at = NOW(),
                    deleted_by = p_deleted_by,
                    fl_status = FALSE
                WHERE id = p_type_material_template_id
                RETURNING id INTO v_deleted_id;

                -- Retornar respuesta según resultado de eliminación
                IF v_deleted_id IS NULL THEN
                    RETURN json_build_object(
                        'status', 404,
                        'message', 'No se encontró el template a eliminar en la base de datos'
                    );
                ELSE
                    RETURN json_build_object(
                        'status', 200,
                        'message', 'Template eliminado exitosamente'
                    );
                END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_remove_type_material_template(p_type_material_template_id bigint, p_deleted_by bigint) OWNER TO postgres;

--
-- Name: fn_report_didi_gm_question(timestamp without time zone, timestamp without time zone, bigint, bigint, bigint[], boolean, character varying, character varying, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_report_didi_gm_question(p_start_date timestamp without time zone, p_end_date timestamp without time zone, p_course_id bigint, p_charge_id bigint, p_employee_didi_gm_id bigint[], p_fl_status boolean, p_order_column character varying, p_order_direction character varying, p_per_page integer, p_n_page integer) RETURNS TABLE(id bigint, collaborator text, charge_id bigint, charge character varying, fl_status_user boolean, course_id bigint, course character varying, uploads bigint, dasi bigint, obse bigint, digi bigint, dupl bigint, veri bigint, type_document_id bigint, type_document_name character varying, document character varying, total bigint)
    LANGUAGE plpgsql
    SET jit TO 'off'
    AS $$
            BEGIN
                RETURN QUERY
                WITH
                tbl_scope_employees AS MATERIALIZED (
                    SELECT e.id, e.user_id, e.charge_id, e.first_surname, e.second_surname, e.first_name, e.type_document_id, e.document
                    FROM employees e
                    WHERE e.charge_id IN (3, 4)
                    AND (p_charge_id IS NULL OR e.charge_id = p_charge_id)
                    AND (p_employee_didi_gm_id IS NULL OR e.id = ANY(p_employee_didi_gm_id))
                ),
                tbl_user_validated AS MATERIALIZED (
                    SELECT u.id, u.fl_status
                    FROM users u
                    JOIN tbl_scope_employees e ON u.id = e.user_id
                    WHERE (p_fl_status IS NULL OR u.fl_status = p_fl_status)
                ),

                -- 1. UPLOADS
                tbl_question_created_didi_gm AS (
                    SELECT DISTINCT
                        e.id AS employee_id,
                        CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name) AS collaborator,
                        e.charge_id, ch.name AS charge, u.fl_status AS fl_status_user,
                        ec.course_id, c.name AS course, q.id AS question_id,
                        q.status AS status_question,
                        CASE WHEN q.id IS NULL THEN null ELSE 'up'::VARCHAR(5) END AS status_history,
                        q.created_at AS create_status
                    FROM tbl_scope_employees e
                    INNER JOIN tbl_user_validated u ON e.user_id = u.id
                    INNER JOIN charge ch ON e.charge_id = ch.id
                    INNER JOIN employee_course ec ON e.id = ec.teacher_id AND ec.fl_status = TRUE
                    LEFT JOIN course c ON ec.course_id = c.id
                    LEFT JOIN question q ON e.user_id = q.created_by
                                        AND ec.course_id = q.course_id
                                        AND q.status NOT IN ('ARCH', 'DUPL')
                                        AND q.created_at BETWEEN p_start_date AND p_end_date
                    WHERE (p_course_id IS NULL OR ec.course_id = p_course_id)
                ),
                -- 2. DIGI (HUB CENTRAL: Esta tabla define las preguntas base para las demás)
                order_first_digitization AS (
                    SELECT qs.question_id, MIN(qs.created_at) AS first_digi_date
                    FROM question_status qs
                    WHERE qs.status = 'DIGI'
                    GROUP BY qs.question_id
                ), tbl_valid_employee_digi_total AS (
                    SELECT DISTINCT fde.question_id, fde.first_digi_date, e.id AS employee_id
                    FROM order_first_digitization fde
                    -- Unimos directo con question_status para validar autoría
                    JOIN question_status qs ON qs.question_id = fde.question_id
                        AND qs.created_at = fde.first_digi_date
                    JOIN users u ON qs.created_by = u.id
                    JOIN tbl_scope_employees e ON e.user_id = u.id
                ),
                tbl_first_digi_ever AS (
                    SELECT ofd.question_id, ofd.first_digi_date
                    FROM order_first_digitization ofd
                    WHERE ofd.first_digi_date BETWEEN p_start_date AND p_end_date
                ),
                tbl_valid_employee_digi AS MATERIALIZED (
                    SELECT DISTINCT fde.question_id, fde.first_digi_date, e.id AS employee_id
                    FROM tbl_first_digi_ever fde
                    -- Unimos directo con question_status para validar autoría
                    JOIN question_status qs ON qs.question_id = fde.question_id
                        AND qs.created_at = fde.first_digi_date
                    JOIN users u ON qs.created_by = u.id
                    JOIN tbl_scope_employees e ON e.user_id = u.id
                ),
                tbl_question_digi_didi AS (
                    SELECT e.id AS employee_id, CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name) AS collaborator,
                        e.charge_id, ch.name AS charge, u.fl_status AS fl_status_user,
                        q.course_id, c.name AS course, ved.question_id, q.status AS status_question,
                        'DIGI'::varchar AS status_history, ved.first_digi_date AS create_status
                    FROM tbl_valid_employee_digi ved
                    INNER JOIN question q ON q.id = ved.question_id
                    INNER JOIN tbl_scope_employees e ON ved.employee_id = e.id
                    INNER JOIN tbl_user_validated u ON e.user_id = u.id
                    INNER JOIN charge ch ON e.charge_id = ch.id
                    LEFT JOIN course c ON q.course_id = c.id
                    WHERE q.fl_status IS TRUE
                    AND (p_course_id IS NULL OR q.course_id = p_course_id)
                ),

                -- Observadas
                 tbl_question_obse_didi_initial AS (
                    SELECT DISTINCT
                        vedt.employee_id,
                        CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name) AS collaborator,
                        e.charge_id, ch.name AS charge, u.fl_status AS fl_status_user,
                        q.course_id, c.name AS course, vedt.question_id, q.status AS status_question,
                        'OBSE'::varchar AS status_history,
                        MIN(qs.created_at) OVER(PARTITION BY qs.question_id) AS create_status
                    FROM tbl_valid_employee_digi_total vedt
                    INNER JOIN question_status qs ON qs.question_id = vedt.question_id
                    INNER JOIN question q ON q.id = vedt.question_id
                    INNER JOIN tbl_scope_employees e ON vedt.employee_id = e.id
                    INNER JOIN tbl_user_validated u ON e.user_id = u.id
                    INNER JOIN charge ch ON e.charge_id = ch.id
                    LEFT JOIN course c ON q.course_id = c.id
                    WHERE qs.status = 'OBSE'
                    AND (p_course_id IS NULL OR q.course_id = p_course_id)
                ),

                tbl_question_obse_didi AS (
                    SELECT DISTINCT
                        qodi.employee_id,
                        qodi.collaborator,
                        qodi.charge_id, qodi.charge, qodi.fl_status_user,
                        qodi.course_id, qodi.course, qodi.question_id, qodi.status_question,
                        qodi.status_history,
                        qodi.create_status
                    FROM tbl_question_obse_didi_initial qodi
                    WHERE qodi.create_status BETWEEN p_start_date AND p_end_date
                ),

                -- 4. VERI/APRB (OPTIMIZADO: Misma estrategia)
                tbl_question_veri_aprob_initial AS (
                    SELECT DISTINCT
                        ved.employee_id,
                        CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name) AS collaborator,
                        e.charge_id, ch.name AS charge, u.fl_status AS fl_status_user,
                        q.course_id, c.name AS course, ved.question_id, q.status AS status_question,
                        'VERI'::varchar AS status_history,
                        MIN(qs.created_at) OVER(PARTITION BY qs.question_id) AS create_status
                    FROM tbl_valid_employee_digi_total ved
                    INNER JOIN question_status qs ON qs.question_id = ved.question_id
                    INNER JOIN question q ON q.id = ved.question_id
                    INNER JOIN tbl_scope_employees e ON ved.employee_id = e.id
                    INNER JOIN tbl_user_validated u ON e.user_id = u.id
                    INNER JOIN charge ch ON e.charge_id = ch.id
                    LEFT JOIN course c ON q.course_id = c.id
                    WHERE qs.status IN ('VERI', 'APRB')
                    AND (p_course_id IS NULL OR q.course_id = p_course_id)
                ),
                tbl_question_veri_aprb AS (
                    SELECT
                        vedt.employee_id,
                        vedt.collaborator,
                        vedt.charge_id,
                        vedt.charge,
                        vedt.fl_status_user,
                        vedt.course_id,
                        vedt.course,
                        vedt.question_id,
                        vedt.status_question,
                        vedt.status_history,
                        vedt.create_status
                    FROM tbl_question_veri_aprob_initial vedt
                    WHERE vedt.create_status BETWEEN p_start_date AND p_end_date
                ),

                -- 5. DASI
                tbl_question_dasi_didi_initial AS (
                    SELECT DISTINCT
                        e.id AS employee_id,
                        CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name) AS collaborator,
                        e.charge_id,
                        ch.name AS charge,
                        u.fl_status AS fl_status_user,
                        q.course_id,
                        c.name AS course,
                        edq.question_id,
                        q.status AS status_question,
                        'DASI'::varchar AS status_history,
                        MIN(qs.created_at) OVER(PARTITION BY qs.question_id) AS create_status
                    FROM employee_didi_question edq
                    INNER JOIN question q ON q.id = edq.question_id
                    INNER JOIN question_status qs ON qs.question_id = q.id
                    INNER JOIN tbl_scope_employees e ON e.id = edq.employee_id
                    INNER JOIN tbl_user_validated u ON e.user_id = u.id
                    INNER JOIN charge ch ON e.charge_id = ch.id
                    LEFT JOIN course c ON q.course_id = c.id
                    WHERE qs.status = 'DASI'
                        AND q.fl_status IS TRUE
                        AND qs.created_at BETWEEN p_start_date AND p_end_date
                        AND (p_course_id IS NULL OR q.course_id = p_course_id)
                ),
                tbl_question_dasi_didi AS (
                    SELECT
                        tqddi.*
                    FROM tbl_question_dasi_didi_initial tqddi
                    WHERE tqddi.create_status BETWEEN p_start_date AND p_end_date
                ),

                -- 6. DUPL
                tbl_question_dupl_initial AS (
                    SELECT DISTINCT
                        e.id AS employee_id,
                        CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name) AS collaborator,
                        e.charge_id,
                        ch.name AS charge,
                        u.fl_status AS fl_status_user,
                        q.course_id,
                        c.name AS course,
                        qs.question_id,
                        q.status AS status_question,
                        'DUPL'::varchar AS status_history,
                        MIN(qs.created_at) OVER(PARTITION BY qs.question_id) AS create_status
                    FROM question_status qs
                    INNER JOIN question q ON q.id = qs.question_id
                    INNER JOIN users u_stat ON qs.created_by = u_stat.id
                    INNER JOIN tbl_scope_employees e ON e.user_id = u_stat.id
                    INNER JOIN tbl_user_validated u ON e.user_id = u.id
                    INNER JOIN charge ch ON e.charge_id = ch.id
                    LEFT JOIN course c ON q.course_id = c.id
                    WHERE qs.status = 'DUPL'
                        AND q.fl_status = true
                        AND (p_course_id IS NULL OR q.course_id = p_course_id)
                ),
                tbl_question_dupl AS (
                    SELECT
                        tqdi.*
                    FROM tbl_question_dupl_initial tqdi
                    WHERE tqdi.create_status BETWEEN p_start_date AND p_end_date
                ),

                -- UNION FINAL
                tbl_group_question_didi AS (
                    SELECT
                        cq.employee_id, cq.collaborator, cq.charge_id, cq.charge, cq.fl_status_user, cq.course_id, cq.course,
                        COALESCE(SUM(CASE WHEN cq.status_history = 'up' THEN 1 ELSE 0 END), 0) AS uploads,
                        COALESCE(SUM(CASE WHEN cq.status_history = 'DASI' THEN 1 ELSE 0 END), 0) AS dasi,
                        COALESCE(SUM(CASE WHEN cq.status_history = 'OBSE' THEN 1 ELSE 0 END), 0) AS obse,
                        COALESCE(SUM(CASE WHEN cq.status_history = 'DIGI' THEN 1 ELSE 0 END), 0) AS digi,
                        COALESCE(SUM(CASE WHEN cq.status_history = 'DUPL' THEN 1 ELSE 0 END), 0) AS dupl,
                        COALESCE(SUM(CASE WHEN cq.status_history = 'VERI' THEN 1 ELSE 0 END), 0) AS veri,
                        o_e.type_document_id, p_td.name as type_document_name, o_e.document
                    FROM (
                        SELECT * FROM tbl_question_created_didi_gm UNION ALL
                        SELECT * FROM tbl_question_dasi_didi UNION ALL
                        SELECT * FROM tbl_question_obse_didi UNION ALL
                        SELECT * FROM tbl_question_digi_didi UNION ALL
                        SELECT * FROM tbl_question_dupl UNION ALL
                        SELECT * FROM tbl_question_veri_aprb
                    ) AS cq
                    LEFT JOIN tbl_scope_employees o_e ON cq.employee_id = o_e.id
                    LEFT JOIN public.type_documents p_td ON o_e.type_document_id = p_td.id
                    GROUP BY cq.employee_id, cq.collaborator, cq.charge_id, cq.charge,
                            cq.fl_status_user, cq.course_id, cq.course, o_e.type_document_id, p_td.name, o_e.document
                )
                SELECT
                    q.*,
                    COUNT(*) OVER()::bigint AS total
                FROM tbl_group_question_didi q
                ORDER BY
                    CASE WHEN p_order_column = 'uploads' AND p_order_direction = 'asc' THEN q.uploads END ASC,
                    CASE WHEN p_order_column = 'uploads' AND p_order_direction = 'desc' THEN q.uploads END DESC,
                    CASE WHEN p_order_column = 'dasi' AND p_order_direction = 'asc' THEN q.dasi END ASC,
                    CASE WHEN p_order_column = 'dasi' AND p_order_direction = 'desc' THEN q.dasi END DESC,
                    CASE WHEN p_order_column = 'obse' AND p_order_direction = 'asc' THEN q.obse END ASC,
                    CASE WHEN p_order_column = 'obse' AND p_order_direction = 'desc' THEN q.obse END DESC,
                    CASE WHEN p_order_column = 'digi' AND p_order_direction = 'asc' THEN q.digi END ASC,
                    CASE WHEN p_order_column = 'digi' AND p_order_direction = 'desc' THEN q.digi END DESC,
                    CASE WHEN p_order_column = 'dupl' AND p_order_direction = 'asc' THEN q.dupl END ASC,
                    CASE WHEN p_order_column = 'dupl' AND p_order_direction = 'desc' THEN q.dupl END DESC,
                    CASE WHEN p_order_column = 'veri' AND p_order_direction = 'asc' THEN q.veri END ASC,
                    CASE WHEN p_order_column = 'veri' AND p_order_direction = 'desc' THEN q.veri END DESC,
                    q.collaborator ASC, q.course ASC
                LIMIT p_per_page
                OFFSET COALESCE((p_n_page - 1) * p_per_page, 0);
            END;
            $$;


ALTER FUNCTION odiseo.fn_report_didi_gm_question(p_start_date timestamp without time zone, p_end_date timestamp without time zone, p_course_id bigint, p_charge_id bigint, p_employee_didi_gm_id bigint[], p_fl_status boolean, p_order_column character varying, p_order_direction character varying, p_per_page integer, p_n_page integer) OWNER TO postgres;

--
-- Name: fn_report_exam_key_generation_v2(jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_report_exam_key_generation_v2(p_ids jsonb) RETURNS TABLE(material_exam_area_week_id bigint, area character varying, area_id smallint, cycle character varying, cycle_type character varying, exam_type character varying, formated_date character varying, integer_date integer, type_material_id smallint, week smallint, keys json, university_id smallint)
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_university_id smallint;
            BEGIN
                SELECT
                    CASE
                        WHEN m.university_id = 16 THEN m.university_id
                        ELSE NULL::SMALLINT
                    END
                INTO v_university_id
                FROM material_exam_area_week meaw
                JOIN detail_week_type_mat dwtm ON dwtm.id = meaw.week_type_material_id
                JOIN material m ON m.id = dwtm.material_id
                WHERE meaw.id = ANY(SELECT (JSONB_ARRAY_ELEMENTS_TEXT(p_ids))::BIGINT)
                LIMIT 1;

                RETURN QUERY
                WITH question_per_material_exam_area_week AS (
                    SELECT
                        meq.material_exam_area_week_id,
                        meq.course_id,
                        meq.question_id,
                        q.code,
                        q.answer_id,
                        meq.position AS relative_position,
                        meq.topic_id,
                        meq.subtopic_id,
                        l.name AS level_name,
                        ea.short_description AS area,
                        ea.id AS area_id,
                        c.code AS cycle,
                        c.description AS cycle_name,
                        ct.name AS cycle_type,
                        COALESCE(
                            UPPER(
                                CASE
                                    WHEN POSITION(' ' IN tm.description) > 0 THEN SUBSTRING(SPLIT_PART(tm.description, ' ', 1) FROM LENGTH(SPLIT_PART(tm.description, ' ', 1)) - 1 FOR 2)
                                    ELSE SUBSTRING(tm.description FROM LENGTH(tm.description) - 1 FOR 2) 
                                END), ''
                        )::VARCHAR AS exam_type,
                        TO_CHAR(meaw.created_at, 'DD/MM/YYYY')::VARCHAR AS formated_date,
                        (EXTRACT(DAY FROM meaw.created_at - '1900-01-01'::TIMESTAMP) + 2)::INTEGER AS integer_date,
                        tm.id AS type_material_id,
                        dwtm.week AS week,
                        RANK() OVER (
                            PARTITION BY meq.material_exam_area_week_id
                                ORDER BY
                                    co.position,
                                    meq.position,
                                    t.code ASC,
                                    st.code ASC,
                                    l.name ASC,
                                    q.id
                        ) AS absolute_position,
                        'P' AS type_question,
                        NULL::JSONB AS subquestions,
                        m.university_id
                    FROM odiseo.material_exam_question AS meq
                    LEFT JOIN odiseo.topic AS t ON meq.topic_id = t.id
                    LEFT JOIN odiseo.subtopic AS st ON st.id = meq.subtopic_id
                    JOIN odiseo.question AS q ON q.id = meq.question_id AND meq.fl_status IS TRUE
                    LEFT JOIN odiseo.material_exam_area_week AS meaw ON meaw.id = meq.material_exam_area_week_id
                    LEFT JOIN odiseo.exam_area AS ea ON ea.id = meaw.area_id
                    LEFT JOIN odiseo.detail_week_type_mat AS dwtm ON dwtm.id = meaw.week_type_material_id
                    LEFT JOIN odiseo.material AS m ON m.id = dwtm.material_id
                    LEFT JOIN odiseo.cycle AS c ON c.id = m.cycle_id
                    LEFT JOIN odiseo.cycle_types ct ON ct.id = c.cycle_type_id
                    LEFT JOIN odiseo.type_material AS tm ON tm.id = dwtm.type_material_id
                    LEFT JOIN odiseo.type_material_template AS tmt ON tmt.id = tm.type_material_template_id
                    LEFT JOIN odiseo.template_type_material_courses_order AS co ON co.template_type_material_id = tmt.id AND meq.course_id = co.course_id
                        AND co.university_id IS NOT DISTINCT FROM v_university_id
                    LEFT JOIN odiseo.level AS l ON l.id = meq.level_id
                    WHERE 1 = 1
                      AND meq.material_exam_area_week_id = ANY(SELECT (JSONB_ARRAY_ELEMENTS_TEXT(p_ids))::BIGINT)
                ), parent_questions_with_subquestions AS (
                    SELECT
                        mepq.material_exam_area_week_id,
                        mepq.course_id,
                        mepq.parent_question_id AS question_id,
                        pq.code,
                        NULL::INTEGER AS answer_id,
                        mepq.position AS relative_position,
                        NULL::INTEGER AS topic_id,
                        NULL::INTEGER AS subtopic_id,
                        NULL::VARCHAR AS level_name,
                        ea.short_description AS area,
                        ea.id AS area_id,
                        c.code AS cycle,
                        c.description AS cycle_name,
                        ct.name AS cycle_type,
                        COALESCE(
                            UPPER(
                                CASE
                                    WHEN POSITION(' ' IN tm.description) > 0 THEN SUBSTRING(SPLIT_PART(tm.description, ' ', 1) FROM LENGTH(SPLIT_PART(tm.description, ' ', 1)) - 1 FOR 2)
                                    ELSE SUBSTRING(tm.description FROM LENGTH(tm.description) - 1 FOR 2) 
                                END), ''
                        )::VARCHAR AS exam_type,
                        TO_CHAR(meaw.created_at, 'DD/MM/YYYY')::VARCHAR AS formated_date,
                        (EXTRACT(DAY FROM meaw.created_at - '1900-01-01'::TIMESTAMP) + 2)::INTEGER AS integer_date,
                        tm.id AS type_material_id,
                        dwtm.week AS week,
                        RANK() OVER (
                            PARTITION BY mepq.material_exam_area_week_id
                                ORDER BY
                                    co.position,
                                    mepq.position,
                                    pq.id
                        ) AS absolute_position,
                        'T' AS type_question,
                        mepq.subquestion AS subquestions,
                        m.university_id
                    FROM odiseo.material_exam_parent_question AS mepq
                    JOIN odiseo.parent_question AS pq ON pq.id = mepq.parent_question_id
                    LEFT JOIN odiseo.material_exam_area_week AS meaw ON meaw.id = mepq.material_exam_area_week_id
                    LEFT JOIN odiseo.exam_area AS ea ON ea.id = meaw.area_id
                    LEFT JOIN odiseo.detail_week_type_mat AS dwtm ON dwtm.id = meaw.week_type_material_id
                    LEFT JOIN odiseo.material AS m ON m.id = dwtm.material_id
                    LEFT JOIN odiseo.cycle AS c ON c.id = m.cycle_id
                    LEFT JOIN odiseo.cycle_types ct ON ct.id = c.cycle_type_id
                    LEFT JOIN odiseo.type_material AS tm ON tm.id = dwtm.type_material_id
                    LEFT JOIN odiseo.type_material_template AS tmt ON tmt.id = tm.type_material_template_id
                    LEFT JOIN odiseo.template_type_material_courses_order AS co ON co.template_type_material_id = tmt.id AND mepq.course_id = co.course_id
                        AND co.university_id IS NOT DISTINCT FROM v_university_id
                    WHERE 1 = 1
                      AND mepq.deleted_at IS NULL
                      AND mepq.material_exam_area_week_id = ANY(SELECT (JSONB_ARRAY_ELEMENTS_TEXT(p_ids))::BIGINT)
                ), all_questions_and_texts AS (
                    SELECT * FROM question_per_material_exam_area_week
                    UNION ALL
                    SELECT * FROM parent_questions_with_subquestions
                ), question_alternatives AS (
                    SELECT
                        qn.question_id,
                        qn.answer_id,
                        al.id AS alternative_id,
                        qn.answer_id = al.id AS correct_answer,
                        CHR(64 + (ROW_NUMBER() OVER ( PARTITION BY qn.material_exam_area_week_id, qn.question_id ORDER BY al.id ))::INT)::CHARACTER AS answer_position,
                        qn.material_exam_area_week_id,
                        qn.type_question
                    FROM all_questions_and_texts qn
                    LEFT JOIN odiseo.alternative AS al ON al.question_id = qn.question_id AND al.fl_status IS TRUE
                    WHERE qn.type_question = 'P'
                    ORDER BY qn.question_id, al.id
                ), subquestion_alternatives AS (
                    SELECT
                        qn.question_id AS parent_question_id,
                        (sq.value->>'question_id')::BIGINT AS question_id,
                        q.answer_id,
                        al.id AS alternative_id,
                        q.answer_id = al.id AS correct_answer,
                        CHR(64 + (ROW_NUMBER() OVER ( PARTITION BY q.id ORDER BY al.id ))::INT)::CHARACTER AS answer_position,
                        qn.material_exam_area_week_id
                    FROM all_questions_and_texts qn
                    CROSS JOIN LATERAL JSONB_ARRAY_ELEMENTS(qn.subquestions) AS sq(value)
                    JOIN odiseo.question AS q ON q.id = (sq.value->>'question_id')::BIGINT
                    LEFT JOIN odiseo.alternative AS al ON al.question_id = q.id AND al.fl_status IS TRUE
                    WHERE qn.type_question = 'T'
                      AND qn.subquestions IS NOT NULL
                    ORDER BY q.id, al.id
                )
                SELECT
                    qw.material_exam_area_week_id,
                    qw.area,
                    qw.area_id,
                    qw.cycle,
                    qw.cycle_type,
                    qw.exam_type,
                    qw.formated_date,
                    qw.integer_date,
                    qw.type_material_id,
                    qw.week,
                    JSON_AGG(
                        JSON_BUILD_OBJECT(
                            'id', qw.question_id,
                            'question_id', qw.question_id,
                            'question_code', qw.code,
                            'course_id', qw.course_id,
                            'description', CASE 
                                WHEN qw.type_question = 'P' THEN qal.answer_position
                                ELSE NULL
                            END,
                            'code', qw.code,
                            'absolute_position', qw.absolute_position,
                            'material_exam_area_week_id', qw.material_exam_area_week_id,
                            'type_question', qw.type_question,
                            'subquestions', CASE 
                                WHEN qw.type_question = 'T' THEN (
                                    SELECT JSON_AGG(
                                        JSON_BUILD_OBJECT(
                                            'question_id', sqa.question_id,
                                            'answer_position', sqa.answer_position
                                        )
                                        ORDER BY sqa.question_id
                                    )
                                    FROM subquestion_alternatives sqa
                                    WHERE sqa.parent_question_id = qw.question_id
                                      AND sqa.material_exam_area_week_id = qw.material_exam_area_week_id
                                      AND sqa.correct_answer IS TRUE
                                )
                                ELSE NULL
                            END
                        )
                        ORDER BY qw.absolute_position
                    ) AS questions,
                    qw.university_id
                FROM all_questions_and_texts AS qw
                LEFT JOIN question_alternatives AS qal ON qw.question_id = qal.question_id 
                    AND qal.material_exam_area_week_id = qw.material_exam_area_week_id 
                    AND qal.correct_answer IS TRUE
                    AND qw.type_question = 'P'
                GROUP BY
                    qw.material_exam_area_week_id,
                    qw.area,
                    qw.area_id,
                    qw.cycle,
                    qw.cycle_type,
                    qw.exam_type,
                    qw.formated_date,
                    qw.integer_date,
                    qw.type_material_id,
                    qw.week,
                    qw.university_id;
            END;
            $$;


ALTER FUNCTION odiseo.fn_report_exam_key_generation_v2(p_ids jsonb) OWNER TO postgres;

--
-- Name: fn_report_missing_questions(integer, integer, integer, integer[]); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_report_missing_questions(p_course_id integer, p_topic_id integer, p_subtopic_id integer, p_level_id integer[]) RETURNS TABLE(correlativo bigint, course_name character varying, topic_name character varying, subtopic_name character varying, level character varying)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY 
            SELECT 
			    ROW_NUMBER() OVER (ORDER BY c.name ASC, t.name ASC, s.name ASC, l.name ASC)::bigint AS correlativo, 
			    c.name AS course_name, 
			    t.name AS topic_name, 
			    s.name AS subtopic_name, 
			    l.description AS level
			FROM odiseo.course c
			JOIN odiseo.topic t ON t.course_id = c.id
			JOIN odiseo.subtopic s ON s.topic_id = t.id
			JOIN odiseo.level l ON 1 = 1  AND l.deleted_at IS NULL
			WHERE NOT EXISTS (
			    SELECT 1
			    FROM odiseo.question q
			    JOIN odiseo.question_subtopic qs ON qs.question_id = q.id
			    WHERE q.course_id = c.id
			      AND q.topic_id = t.id
			      AND qs.subtopic_id = s.id
			      AND q.level_id = l.id
			)
            AND (p_course_id IS NULL OR c.id = p_course_id) 
            AND (p_topic_id IS NULL OR t.id = p_topic_id) 
            AND (p_subtopic_id IS NULL OR s.id = p_subtopic_id) 
            AND (p_level_id IS NULL OR l.id = ANY (p_level_id)) 
			ORDER BY c.name ASC, t.name ASC, s.name ASC, l.name ASC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_report_missing_questions(p_course_id integer, p_topic_id integer, p_subtopic_id integer, p_level_id integer[]) OWNER TO postgres;

--
-- Name: fn_report_teacher_question_v3(timestamp without time zone, timestamp without time zone, bigint, bigint[], boolean, character varying, character varying, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_report_teacher_question_v3(p_start_date timestamp without time zone, p_end_date timestamp without time zone, p_course_id bigint, p_employee_id bigint[], p_fl_status boolean, p_order_column character varying, p_order_direction character varying, p_per_page integer, p_n_page integer) RETURNS TABLE(id bigint, code character varying, collaborator text, fl_status_user boolean, limit_assigned_questions smallint, fl_unlimit_questions boolean, course_id bigint, course character varying, asig bigint, inde bigint, veri_nq bigint, veri bigint, aprb bigint, obse bigint, type_document_id bigint, type_document_name character varying, document character varying, total bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    
    -- [PRE-PROCESAMIENTO]: Identificación del Indexador Original
    -- Necesario para validar que quien verifica/aprueba sea el autor original en flujos manuales.
    WITH tbl_indexador_original AS (
        SELECT DISTINCT ON (qs.question_id)
            qs.question_id,
            e.id AS employee_id
        FROM question_status qs
        INNER JOIN users u ON qs.created_by = u.id
        INNER JOIN employees e ON e.user_id = u.id
        WHERE qs.status = 'INDE'
        ORDER BY qs.question_id, qs.created_at ASC
    ),

    -- [ESTADO: VERIFICACIÓN (VERI)]
    -- Lógica dual: Valida autoría para humanos y permite conteo directo para IA (NQ).
    tbl_first_veri_ever AS (
        SELECT DISTINCT ON (qs.question_id)
            qs.question_id,
            qs.id,
            qs.created_at AS first_veri_date,
            qs.created_by
        FROM question_status qs
        JOIN question q ON q.id = qs.question_id
        WHERE qs.status = 'VERI'
        AND q.fl_status IS TRUE
        ORDER BY qs.question_id, qs.created_at
    ),
    tbl_valid_employee_veri AS (
        SELECT
            fve.question_id,
            fve.first_veri_date,
            e.id AS employee_id
        FROM tbl_first_veri_ever fve
        JOIN users u ON fve.created_by = u.id
        JOIN employees e ON e.user_id = u.id
    ),
    tbl_status_veri_std AS (
        -- Verificación Estándar: Requiere que verificador = indexador original.
        SELECT vev.employee_id, vev.question_id, q.course_id, q.status AS status_question,
               'VERI' AS status_history, vev.first_veri_date AS create_status, q.ia_generated
        FROM tbl_valid_employee_veri vev
        INNER JOIN question q ON q.id = vev.question_id
        INNER JOIN tbl_indexador_original io ON io.question_id = vev.question_id 
            AND io.employee_id = vev.employee_id
        WHERE (q.ia_generated IS FALSE OR q.ia_generated IS NULL)
        AND DATE_TRUNC('minute', vev.first_veri_date) BETWEEN DATE_TRUNC('minute', p_start_date) AND DATE_TRUNC('minute', p_end_date)
        AND q.status <> 'ARCH'
    ),
    tbl_status_veri_nq AS (
        -- Verificación NQ/IA: No requiere validación de autoría previa.
        SELECT vev.employee_id, vev.question_id, q.course_id, q.status AS status_question,
               'VERI' AS status_history, vev.first_veri_date AS create_status, q.ia_generated
        FROM tbl_valid_employee_veri vev
        INNER JOIN question q ON q.id = vev.question_id
        WHERE q.ia_generated IS TRUE
        AND DATE_TRUNC('minute', vev.first_veri_date) BETWEEN DATE_TRUNC('minute', p_start_date) AND DATE_TRUNC('minute', p_end_date)
        AND q.status <> 'ARCH'
    ),
    tbl_status_veri_digi AS (
        SELECT 
            eq.teacher_id AS employee_id,
            fve.question_id, 
            q.course_id, 
            q.status AS status_question,
            'VERI' AS status_history, 
            fve.first_veri_date AS create_status, 
            q.ia_generated
        FROM tbl_first_veri_ever fve
        INNER JOIN question q ON q.id = fve.question_id
        INNER JOIN employee_question eq 
            ON eq.question_id = fve.question_id 
            AND eq.fl_status IS TRUE
        INNER JOIN question_status qs_veri 
            ON qs_veri.question_id = fve.question_id
            AND DATE_TRUNC('second', qs_veri.created_at) = DATE_TRUNC('second', fve.first_veri_date)
            AND qs_veri.status = 'VERI'
        INNER JOIN users u_veri 
            ON u_veri.id = qs_veri.created_by
        INNER JOIN employees e_veri 
            ON e_veri.user_id = u_veri.id
            AND e_veri.id = eq.teacher_id
        WHERE NOT EXISTS (
            SELECT 1 FROM tbl_indexador_original io 
            WHERE io.question_id = fve.question_id
        )
        AND (q.ia_generated IS FALSE OR q.ia_generated IS NULL)
        AND DATE_TRUNC('minute', fve.first_veri_date) 
            BETWEEN DATE_TRUNC('minute', p_start_date) AND DATE_TRUNC('minute', p_end_date)
        AND q.status <> 'ARCH'
    ),
    tbl_question_veri_teacher AS (
        SELECT DISTINCT e.id AS employee_id, e.code AS code_employee,
            CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name) AS collaborator,
            u.fl_status AS fl_status_user, e.limit_assigned_questions, e.fl_unlimit_questions,
            qs.course_id, c.name AS course, qs.question_id, qs.status_question, 
            qs.status_history, qs.create_status, qs.ia_generated
        FROM (
            SELECT * FROM tbl_status_veri_std 
            UNION ALL SELECT * FROM tbl_status_veri_nq
            UNION ALL SELECT * FROM tbl_status_veri_digi
        ) qs
        INNER JOIN employees e ON qs.employee_id = e.id
        INNER JOIN users u ON e.user_id = u.id
        LEFT JOIN course c ON qs.course_id = c.id
    ),

    -- [ESTADO: ASIGNACIÓN (ASIG)]
    -- Mide las preguntas asignadas a un docente en el rango de tiempo.
    tbl_question_status_asig AS (
        SELECT qs.question_id, q.course_id, q.status AS status_question, qs.status AS status_history,
               qs.created_at AS create_status, eq.teacher_id AS employee_id, q.ia_generated,
               ROW_NUMBER() OVER (PARTITION BY qs.question_id ORDER BY qs.created_at DESC) AS rn
        FROM employee_question eq
        INNER JOIN question q ON eq.question_id = q.id
        INNER JOIN question_status qs ON eq.question_id = qs.question_id AND qs.created_at >= eq.created_at
        WHERE qs.status = 'ASIG' AND eq.fl_status IS TRUE
        AND DATE_TRUNC('minute', qs.created_at) BETWEEN DATE_TRUNC('minute', p_start_date) AND DATE_TRUNC('minute', p_end_date)
    ),
    tbl_question_asig_teacher AS (
        SELECT DISTINCT e.id AS employee_id, e.code AS code_employee,
               CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name) AS collaborator,
               u.fl_status AS fl_status_user, e.limit_assigned_questions, e.fl_unlimit_questions,
               qs.course_id, c.name AS course, qs.question_id, qs.status_question, qs.status_history, qs.create_status, qs.ia_generated
        FROM tbl_question_status_asig qs
        INNER JOIN employees e ON qs.employee_id = e.id
        INNER JOIN users u ON e.user_id = u.id
        LEFT JOIN course c ON qs.course_id = c.id
        WHERE qs.rn = 1 AND qs.status_question <> 'ARCH'
    ),

    -- [ESTADO: INDEXACIÓN (INDE)]
    -- Mide la primera vez que una pregunta fue indexada.
    tbl_first_inde_ever AS (
        SELECT qs.question_id, MIN(qs.created_at) AS first_inde_date
        FROM question_status qs
        INNER JOIN question q ON q.id = qs.question_id
        WHERE qs.status = 'INDE' AND q.fl_status IS TRUE
        GROUP BY qs.question_id
    ),
    tbl_question_status_inde AS (
        SELECT io.employee_id, fie.question_id, q.course_id, q.status AS status_question,
               'INDE' AS status_history, fie.first_inde_date AS create_status, q.ia_generated
        FROM tbl_first_inde_ever fie
        INNER JOIN tbl_indexador_original io ON fie.question_id = io.question_id
        INNER JOIN question q ON q.id = fie.question_id
        WHERE DATE_TRUNC('minute', fie.first_inde_date) BETWEEN DATE_TRUNC('minute', p_start_date) AND DATE_TRUNC('minute', p_end_date)
        AND q.status <> 'ARCH'
    ),
    tbl_question_inde_teacher AS (
        SELECT DISTINCT e.id AS employee_id, e.code AS code_employee,
               CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name) AS collaborator,
               u.fl_status AS fl_status_user, e.limit_assigned_questions, e.fl_unlimit_questions,
               qs.course_id, c.name AS course, qs.question_id, qs.status_question, qs.status_history, qs.create_status, qs.ia_generated
        FROM tbl_question_status_inde qs
        INNER JOIN employees e ON qs.employee_id = e.id
        INNER JOIN users u ON e.user_id = u.id
        LEFT JOIN course c ON qs.course_id = c.id
    ),

    -- [ESTADO: APROBACIÓN (APRB)]
    -- Se atribuye la aprobación al indexador original de la pregunta.
    tbl_first_aprb_ever AS (
        SELECT qs.question_id, MIN(qs.created_at) AS first_aprb_date
        FROM question_status qs
        INNER JOIN question q ON q.id = qs.question_id
        WHERE qs.status = 'APRB' AND q.fl_status IS TRUE
        GROUP BY qs.question_id
    ),
    tbl_valid_employee_aprb AS (
        SELECT DISTINCT fae.question_id, fae.first_aprb_date, e.id AS employee_id
        FROM tbl_first_aprb_ever fae
        INNER JOIN question_status qs ON qs.question_id = fae.question_id 
            AND DATE_TRUNC('second', qs.created_at) = DATE_TRUNC('second', fae.first_aprb_date)
            AND qs.status = 'APRB'
        INNER JOIN users u ON qs.created_by = u.id
        INNER JOIN employees e ON e.user_id = u.id
    ),
    tbl_question_status_aprb AS (
        SELECT vea.employee_id, vea.question_id, q.course_id, q.status AS status_question,
               'APRB' AS status_history, vea.first_aprb_date AS create_status, q.ia_generated
        FROM tbl_valid_employee_aprb vea
        INNER JOIN question q ON q.id = vea.question_id
        WHERE DATE_TRUNC('minute', vea.first_aprb_date) BETWEEN DATE_TRUNC('minute', p_start_date) AND DATE_TRUNC('minute', p_end_date)
        AND q.status <> 'ARCH'
    ),
    tbl_question_aprb_teacher AS (
        SELECT DISTINCT e.id AS employee_id, e.code AS code_employee,
               CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name) AS collaborator,
               u.fl_status AS fl_status_user, e.limit_assigned_questions, e.fl_unlimit_questions,
               qs.course_id, c.name AS course, qs.question_id, qs.status_question, qs.status_history, qs.create_status, qs.ia_generated
        FROM tbl_question_status_aprb qs
        INNER JOIN employees e ON qs.employee_id = e.id
        INNER JOIN users u ON e.user_id = u.id
        LEFT JOIN course c ON qs.course_id = c.id
    ),
    -- [ESTADO: OBSERVACIÓN (OBSE)]
    -- Mide las observaciones realizadas por el docente a las preguntas.
    tbl_first_obse_ever AS (
        SELECT qs.question_id, MIN(qs.created_at) AS first_obse_date
        FROM question_status qs
        INNER JOIN question q ON q.id = qs.question_id
        WHERE qs.status = 'OBSE' AND q.fl_status IS TRUE
        GROUP BY qs.question_id
    ),
    tbl_valid_employee_obse AS (
        SELECT DISTINCT foe.question_id, foe.first_obse_date, e.id AS employee_id
        FROM tbl_first_obse_ever foe
        INNER JOIN question_status qs ON qs.question_id = foe.question_id 
            AND DATE_TRUNC('second', qs.created_at) = DATE_TRUNC('second', foe.first_obse_date)
        INNER JOIN users u ON qs.created_by = u.id
        INNER JOIN employees e ON e.user_id = u.id
    ),
    tbl_question_status_obse AS (
        SELECT veo.employee_id, veo.question_id, q.course_id, q.status AS status_question,
               'OBSE' AS status_history, veo.first_obse_date AS create_status, q.ia_generated
        FROM tbl_valid_employee_obse veo
        INNER JOIN question q ON q.id = veo.question_id
        WHERE DATE_TRUNC('minute', veo.first_obse_date) BETWEEN DATE_TRUNC('minute', p_start_date) AND DATE_TRUNC('minute', p_end_date)
        AND q.status <> 'ARCH'
    ),
    tbl_question_obse_teacher AS (
        SELECT DISTINCT e.id AS employee_id, e.code AS code_employee,
               CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name) AS collaborator,
               u.fl_status AS fl_status_user, e.limit_assigned_questions, e.fl_unlimit_questions,
               qs.course_id, c.name AS course, qs.question_id, qs.status_question, qs.status_history, qs.create_status, qs.ia_generated
        FROM tbl_question_status_obse qs
        INNER JOIN employees e ON qs.employee_id = e.id
        INNER JOIN users u ON e.user_id = u.id
        LEFT JOIN course c ON qs.course_id = c.id
    ),
    
    -- [PROCESAMIENTO FINAL]: Agrupación, Filtros de Entrada y Conteo por Columnas
    tbl_group_question_teacher AS (
        SELECT
            cq.employee_id, cq.code_employee, cq.collaborator, cq.fl_status_user,
            cq.limit_assigned_questions, cq.fl_unlimit_questions, cq.course_id::BIGINT, cq.course,
            COALESCE(SUM(CASE WHEN cq.status_history = 'ASIG' THEN 1 ELSE 0 END), 0) AS asig,
            COALESCE(SUM(CASE WHEN cq.status_history = 'INDE' THEN 1 ELSE 0 END), 0) AS inde,
            COALESCE(SUM(CASE WHEN cq.status_history = 'VERI' AND cq.ia_generated IS TRUE THEN 1 ELSE 0 END), 0) AS veri_nq,
            COALESCE(SUM(CASE WHEN cq.status_history = 'VERI' AND (cq.ia_generated IS FALSE OR cq.ia_generated IS NULL) THEN 1 ELSE 0 END), 0) AS veri,
            COALESCE(SUM(CASE WHEN cq.status_history = 'APRB' THEN 1 ELSE 0 END), 0) AS aprb,
            COALESCE(SUM(CASE WHEN cq.status_history = 'OBSE' THEN 1 ELSE 0 END), 0) AS obse,
            o_e.type_document_id, p_td.name as type_document_name, o_e.document
        FROM (
            SELECT * FROM tbl_question_asig_teacher UNION ALL
            SELECT * FROM tbl_question_inde_teacher UNION ALL
            SELECT * FROM tbl_question_veri_teacher UNION ALL
            SELECT * FROM tbl_question_aprb_teacher UNION ALL
            SELECT * FROM tbl_question_obse_teacher
        ) AS cq
        LEFT JOIN employees o_e ON cq.employee_id = o_e.id
        LEFT JOIN public.type_documents p_td ON o_e.type_document_id = p_td.id
        GROUP BY
            cq.employee_id, cq.code_employee, cq.collaborator,
            cq.fl_status_user, cq.limit_assigned_questions,
            cq.fl_unlimit_questions, cq.course_id, cq.course,
            o_e.id, p_td.name
        HAVING (p_course_id IS NULL OR cq.course_id = p_course_id)
        AND (p_employee_id IS NULL OR cq.employee_id = ANY(p_employee_id))
    )

    -- [SALIDA]: Aplicación de Ordenamiento y Paginación
    SELECT q.*, COUNT(*) OVER()::bigint AS total
    FROM tbl_group_question_teacher q
    ORDER BY
        CASE WHEN p_order_column IN ('asig','inde','veri','veri_nq','aprb','obse')
            THEN (
                CASE p_order_column
                    WHEN 'asig'    THEN q.asig
                    WHEN 'inde'    THEN q.inde
                    WHEN 'veri'    THEN q.veri
                    WHEN 'veri_nq' THEN q.veri_nq
                    WHEN 'aprb'    THEN q.aprb
                    WHEN 'obse'    THEN q.obse
                END * CASE p_order_direction WHEN 'desc' THEN -1 ELSE 1 END
            )
        END,
        q.employee_id ASC, q.course_id ASC
    LIMIT p_per_page
    OFFSET COALESCE((p_n_page - 1) * p_per_page, 0);
END;
$$;


ALTER FUNCTION odiseo.fn_report_teacher_question_v3(p_start_date timestamp without time zone, p_end_date timestamp without time zone, p_course_id bigint, p_employee_id bigint[], p_fl_status boolean, p_order_column character varying, p_order_direction character varying, p_per_page integer, p_n_page integer) OWNER TO postgres;

--
-- Name: fn_report_verified_questions(integer, integer, integer, integer[]); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_report_verified_questions(p_course_id integer, p_topic_id integer, p_subtopic_id integer, p_level_id integer[]) RETURNS TABLE(correlativo bigint, course_name character varying, topic_name character varying, subtopic_name character varying, level character varying, total_question bigint)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY 
            SELECT 
                ROW_NUMBER() OVER (ORDER BY c.name ASC, t.name ASC, s.name ASC, l.name ASC)::bigint AS correlativo, 
                c.name AS course_name, 
                t.name AS topic_name, 
                s.name AS subtopic_name, 
                l.description AS level, 
                COUNT(q.id) AS total_question 
            FROM odiseo.question q 
            LEFT JOIN odiseo.course c ON q.course_id = c.id 
            LEFT JOIN odiseo.topic t ON q.topic_id = t.id 
            LEFT JOIN odiseo.question_subtopic qs ON qs.question_id = q.id 
            LEFT JOIN odiseo.subtopic s ON s.id = qs.subtopic_id 
            LEFT JOIN odiseo.level l ON q.level_id = l.id 
            WHERE q.status = 'VERI' 
            AND (p_course_id IS NULL OR c.id = p_course_id) 
            AND (p_topic_id IS NULL OR t.id = p_topic_id) 
            AND (p_subtopic_id IS NULL OR s.id = p_subtopic_id) 
            AND (p_level_id IS NULL OR l.id = ANY (p_level_id)) 
            GROUP BY c.name, t.name, s.name, l.name, l.description 
            ORDER BY c.name ASC, t.name ASC, s.name ASC, l.name ASC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_report_verified_questions(p_course_id integer, p_topic_id integer, p_subtopic_id integer, p_level_id integer[]) OWNER TO postgres;

--
-- Name: fn_report_verified_questions_total(integer, integer, integer, integer[]); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_report_verified_questions_total(p_course_id integer, p_topic_id integer, p_subtopic_id integer, p_level_id integer[]) RETURNS TABLE(records_verified_questions_total bigint)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            SELECT COUNT(*) AS records_verified_questions_total 
            FROM odiseo.question q 
            LEFT JOIN odiseo.course c ON q.course_id = c.id 
            LEFT JOIN odiseo.topic t ON q.topic_id = t.id 
            LEFT JOIN odiseo.question_subtopic qs ON qs.question_id = q.id 
            LEFT JOIN odiseo.subtopic s ON s.id = qs.subtopic_id 
            LEFT JOIN odiseo.level l ON q.level_id = l.id 
            WHERE q.status = 'VERI' 
            AND (p_course_id IS NULL OR c.id = p_course_id) 
            AND (p_topic_id IS NULL OR t.id = p_topic_id) 
            AND (p_subtopic_id IS NULL OR s.id = p_subtopic_id) 
            AND (p_level_id IS NULL OR l.id = ANY (p_level_id));
        END;
        $$;


ALTER FUNCTION odiseo.fn_report_verified_questions_total(p_course_id integer, p_topic_id integer, p_subtopic_id integer, p_level_id integer[]) OWNER TO postgres;

--
-- Name: fn_reset_material_per_period_ballot(bigint, smallint, smallint, smallint, boolean, smallint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_reset_material_per_period_ballot(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint, p_fl_config_type boolean, p_lower_level_limit smallint, p_upper_level_limit smallint, p_created_by bigint) RETURNS TABLE(id bigint, material_per_period_ballot_id bigint, week smallint, cycle_id bigint, start_date date, type_material_id smallint, type_material character varying, exists_per_period boolean, has_questions boolean, parent_type_material_id smallint, fl_exam boolean, courses jsonb, courses_for_text jsonb, university_id smallint, headquarte_id smallint)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                WITH type_material_ids AS (
                    SELECT
                        CASE
                            WHEN EXISTS ( SELECT 1 FROM type_material tmx WHERE tmx.parent_id = p_type_material_id AND tmx.fl_status = true )
                            THEN ARRAY( SELECT tmy.id FROM type_material tmy WHERE tmy.parent_id = p_type_material_id AND tmy.fl_status = true )
                            ELSE ARRAY[p_type_material_id]
                        END AS ids
                ), insert_material_per_period AS (
                    INSERT INTO material_per_period AS plmm ( material_id, type_material_id, created_at, created_by )
                    VALUES( p_material_id, p_type_material_id, NOW(), p_created_by )
                    ON CONFLICT ON CONSTRAINT per_material_and_type_id
                    DO UPDATE
                        SET
                            updated_by = p_created_by,
                            deleted_by = NULL,
                            updated_at = NOW(),
                            deleted_at = NULL
                    RETURNING plmm.id, plmm.updated_at IS NULL AS is_new
                ), insert_material_per_period_ballot AS (
                    INSERT INTO material_per_period_ballot AS mpt(
                        material_per_period_id,
                        start_week,
                        end_week,
                        fl_config_type,
                        lower_level_limit,
                        upper_level_limit,
                        date_completed,
                        user_completed_id,
                        order_date,
                        order_by_user_id,
                        created_by,
                        created_at
                    )
                    VALUES(
                        ( SELECT im.id FROM insert_material_per_period AS im ),
                        p_start_week,
                        p_end_week,
                        p_fl_config_type,
                        p_lower_level_limit,
                        p_upper_level_limit,
                        NULL,
                        NULL,
                        NULL,
                        NULL,
                        p_created_by,
                        NOW()
                    )
                     ON CONFLICT (material_per_period_id, start_week, end_week) WHERE deleted_at IS NULL
                        DO UPDATE
                            SET
                                fl_config_type = p_fl_config_type,
                                lower_level_limit = p_lower_level_limit,
                                upper_level_limit = p_upper_level_limit,
                                date_completed = NULL,
                                user_completed_id = NULL,
                                order_date = NULL,
                                order_by_user_id = NULL,
                                updated_by = p_created_by,
                                deleted_by = NULL,
                                updated_at = NOW(),
                                deleted_at = NULL
                        RETURNING mpt.id, mpt.updated_at IS NULL AS is_new
                ), remove_overlapping_periods_in_ballot AS (
                    UPDATE material_per_period_ballot mppb
                    SET
                        deleted_by = p_created_by,
                        deleted_at = NOW()
                    WHERE 1 = 1
                    AND mppb.material_per_period_id IN ( SELECT ip.id FROM insert_material_per_period AS ip WHERE is_new IS FALSE )
                    AND ( mppb.start_week BETWEEN p_start_week AND p_end_week OR mppb.end_week BETWEEN p_start_week AND p_end_week )
                    AND NOT ( mppb.start_week = p_start_week AND mppb.end_week = p_end_week )
                    RETURNING mppb.id AS material_period_id
                ), remove_urls_in_overlapping AS (
                    UPDATE material_per_period_ballot_url mbppbu
                        SET
                        deleted_by = p_created_by,
                        deleted_at = NOW()
                    WHERE mbppbu.material_per_period_ballot_id IN ( SELECT rmv.material_period_id FROM remove_overlapping_periods_in_ballot rmv )
                    RETURNING mbppbu.id AS material_period_url_id
                ), remove_class_urls_in_overlapping AS (
                    UPDATE material_per_period_ballot_class class_urls
                        SET
                            deleted_by = p_created_by,
                            deleted_at = NOW()
                    WHERE class_urls.material_per_period_ballot_url_id IN ( SELECT rmu.material_period_url_id FROM remove_urls_in_overlapping rmu )
                ), weeks_in_type_material_ids AS (
                    SELECT
                        tmdt.week,
                        ttm.id AS child_type_material_id,
                        ttm.parent_id AS parent_type_material_id
                    FROM type_material_detail_template tmdt
                    LEFT JOIN (
                        SELECT tm.id, tm.parent_id FROM type_material tm
                        WHERE tm.id IN ( SELECT UNNEST(ids) FROM type_material_ids )
                    ) ttm ON 1 = 1
                    WHERE 1 = 1
                    AND tmdt.type_material_id = p_type_material_id
                    AND tmdt.week BETWEEN p_start_week AND p_end_week
                    AND tmdt.fl_status = true
                    ORDER BY tmdt.week ASC, ttm.id ASC
                ), insert_or_update_detail_week_type AS (
                    INSERT INTO detail_week_type_mat AS dwtm (
                        material_id,
                        week,
                        type_material_id,
                        parent_type_material_id,
                        fl_config_type,
                        limit_lower_question,
                        limit_upper_question,
                        created_by,
                        created_at
                    )
                    SELECT
                        p_material_id,
                        wt.week,
                        wt.child_type_material_id,
                        wt.parent_type_material_id,
                        p_fl_config_type,
                        p_lower_level_limit,
                        p_upper_level_limit,
                        p_created_by,
                        NOW()
                    FROM weeks_in_type_material_ids wt
                    ON CONFLICT ON CONSTRAINT ux_detail_week_type_mat
                    DO UPDATE
                        SET
                            parent_type_material_id = EXCLUDED.parent_type_material_id,
                            fl_config_type = EXCLUDED.fl_config_type,
                            limit_lower_question = EXCLUDED.limit_lower_question,
                            limit_upper_question = EXCLUDED.limit_upper_question,
                            updated_by = p_created_by,
                            updated_at = NOW(),
                            fl_status = TRUE,
                            deleted_by = NULL,
                            deleted_at = NULL
                    RETURNING
                        dwtm.id,
                        dwtm.week,
                        dwtm.type_material_id,
                        dwtm.parent_type_material_id,
                        dwtm.data_incomplete_questions IS NOT NULL AS incomplete_questions,
                        dwtm.data_missing_course_config IS NOT NULL AS incomplete_course_config,
                        dwtm.data_missing_text IS NOT NULL AS incomplete_missing_text,
                        dwtm.updated_at IS NULL AS is_new
                ), incomplete_fields_in_material_per_period AS (
                    UPDATE material_per_period_ballot mb
                        SET
                            date_completed = NULL,
                            user_completed_id = NULL,
                            order_date = NULL,
                            order_by_user_id = NULL,
                            fl_missing_questions = EXISTS( SELECT 1 FROM insert_or_update_detail_week_type WHERE incomplete_questions IS TRUE ),
                            fl_missing_courses = EXISTS( SELECT 1 FROM insert_or_update_detail_week_type WHERE incomplete_course_config IS TRUE ),
                            fl_missing_text = EXISTS( SELECT 1 FROM insert_or_update_detail_week_type WHERE incomplete_missing_text IS TRUE )
                    WHERE mb.id IN ( SELECT pp.id FROM insert_material_per_period_ballot AS pp )
                ), get_courses_generic AS (
                    SELECT DISTINCT
                        tmc.course_id,
                        tmc.type_material_id
                    FROM type_material_course tmc
                    WHERE tmc.type_material_id IN (SELECT UNNEST(ids) FROM type_material_ids)
                        AND tmc.is_generic = true
                        AND tmc.fl_status = true
                        AND tmc.amount_question > 0
                ), get_courses_text_generic AS (
                    SELECT DISTINCT
                        tmc.course_id,
                        tmc.type_material_id
                    FROM type_material_course tmc
                    WHERE tmc.type_material_id IN (SELECT UNNEST(ids) FROM type_material_ids)
                        AND tmc.is_generic_text = true
                        AND tmc.amount_text > 0
                        AND tmc.fl_status = true
                ), get_courses_not_generic AS (
                    SELECT DISTINCT
                        tmc.course_id,
                        tm.id AS type_material_id
                    FROM odiseo.type_material tm
                    JOIN odiseo.type_material_detail_template tmdt ON tmdt.type_material_id = tm.id
                        AND tmdt.fl_status = true
                    JOIN odiseo.type_material_course tmc ON tmc.type_material_id = tm.id
                    LEFT JOIN odiseo.type_material_detail_courses tmdc ON tmdc.type_material_course_id = tmc.id
                        AND tmdc.type_material_detail_template_id = tmdt.id
                    WHERE tm.id IN (SELECT UNNEST(ids) FROM type_material_ids)
                        AND tmc.is_generic = false
                        AND tmdt.week BETWEEN p_start_week AND p_end_week
                        AND tmdc.amount_question > 0
                ), get_courses_text_not_generic AS (
                    SELECT DISTINCT
                        tmc.course_id,
                        tm.id AS type_material_id
                    FROM odiseo.type_material tm
                    JOIN odiseo.type_material_detail_template tmdt ON tmdt.type_material_id = tm.id
                        AND tmdt.fl_status = true
                    JOIN odiseo.type_material_course tmc ON tmc.type_material_id = tm.id
                    LEFT JOIN odiseo.type_material_detail_course_texts tmdct ON tmdct.type_material_course_id = tmc.id
                        AND tmdct.type_material_detail_template_id = tmdt.id
                    WHERE tm.id IN (SELECT UNNEST(ids) FROM type_material_ids)
                        AND tmc.is_generic_text = false
                        AND tmdt.week BETWEEN p_start_week AND p_end_week
                        AND tmdct.amount_text > 0
                ), get_courses AS (
                    SELECT
                        gcg.course_id,
                        gcg.type_material_id
                    FROM get_courses_generic gcg
                    UNION ALL
                    SELECT
                        gcng.course_id,
                        gcng.type_material_id
                    FROM get_courses_not_generic gcng
                ), get_courses_text AS (
                    SELECT
                        gcg.course_id,
                        gcg.type_material_id
                    FROM get_courses_text_generic gcg
                    UNION ALL
                    SELECT
                        gcng.course_id,
                        gcng.type_material_id
                    FROM get_courses_text_not_generic gcng
                )
                SELECT
                    io.id,
                    ( SELECT z.id FROM insert_material_per_period_ballot AS z ) AS material_per_period_ballot_id,
                    io.week,
                    m.cycle_id,
                    c.start_date,
                    io.type_material_id,
                    tm.description AS type_material,
                    FALSE AS exists_per_period,
                    FALSE AS has_questions,
                    io.parent_type_material_id,
                    FALSE AS fl_exam,
                    COALESCE((
                        SELECT jsonb_agg(gc.course_id ORDER BY gc.course_id ASC)
                        FROM get_courses gc
                        WHERE gc.type_material_id = io.type_material_id
                    ), '[]'::JSONB) AS courses,
                    COALESCE((
                        SELECT jsonb_agg(gc.course_id ORDER BY gc.course_id ASC)
                        FROM get_courses_text gc
                        WHERE gc.type_material_id = io.type_material_id
                    ), '[]'::JSONB) AS courses_for_text,
                    m.university_id,
                    m.headquarte_id
                FROM insert_or_update_detail_week_type io
                LEFT JOIN material m ON m.id = p_material_id
                LEFT JOIN type_material tm ON io.type_material_id = tm.id
                LEFT JOIN cycle c ON c.id = m.cycle_id
                ORDER BY LEFT(tm.description, 1);
            END;
            $$;


ALTER FUNCTION odiseo.fn_reset_material_per_period_ballot(p_material_id bigint, p_type_material_id smallint, p_start_week smallint, p_end_week smallint, p_fl_config_type boolean, p_lower_level_limit smallint, p_upper_level_limit smallint, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_revised_diagrammed_question(integer, integer, character varying, jsonb, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_revised_diagrammed_question(p_id_question integer, p_field_diagram_id integer, p_content character varying, p_images jsonb, p_user integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_didi_question_id BIGINT;
                element JSONB;
            BEGIN
                    UPDATE odiseo.employee_didi_question_field
                    SET value = p_content, updated_by = p_user, updated_at = NOW()
                    WHERE id = p_field_diagram_id;

                    SELECT edq.id
                    INTO v_didi_question_id
                    FROM odiseo.employee_didi_question edq
                    WHERE edq.question_id = p_id_question
                    AND fl_status = TRUE
                    AND deleted_at IS NULL;

                    FOR element IN SELECT jsonb_array_elements(p_images) LOOP
                        INSERT INTO odiseo.employee_didi_question_field_image (
                            employee_didi_question_id, code, "extension", image, created_by, created_at
                        )
                        VALUES (
                            v_didi_question_id,
                            element->>'code',
                            element->>'extension',
                            element->>'image',
                            p_user,
                            NOW()
                        );
                    END LOOP;
                END;
            $$;


ALTER FUNCTION odiseo.fn_revised_diagrammed_question(p_id_question integer, p_field_diagram_id integer, p_content character varying, p_images jsonb, p_user integer) OWNER TO postgres;

--
-- Name: fn_revised_question_digitalized(bigint, jsonb, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_revised_question_digitalized(p_question_id bigint, p_data_diagram jsonb, p_images jsonb, p_user bigint) RETURNS TABLE(result_id bigint, result_value text, result_updated_by bigint, result_updated_at timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
                                        DECLARE
                                            v_employee_didi_question_id bigint;
                                            v_diagram jsonb;
                                            v_image jsonb;
                                        BEGIN
                                            -- Obtener el ID del employee_didi_question correspondiente a la pregunta
                                            SELECT edq.id
                                            INTO v_employee_didi_question_id
                                            FROM employee_didi_question edq
                                            WHERE edq.question_id = p_question_id AND edq.fl_status = true;

                                            -- Eliminar las imágenes antiguas
                                            UPDATE employee_didi_question_field_image
                                            SET fl_status = false,
                                                deleted_by = p_user,
                                                deleted_at = now()
                                            WHERE employee_didi_question_id = v_employee_didi_question_id;

                                            -- Insertar las nuevas imágenes
                                            FOR v_image IN
                                                SELECT * FROM jsonb_array_elements(p_images)
                                            LOOP
                                                INSERT INTO employee_didi_question_field_image(
                                                    employee_didi_question_id,
                                                    code,
                                                    image,
                                                    extension,
                                                    created_by,
                                                    created_at
                                                )
                                                VALUES (
                                                    v_employee_didi_question_id,
                                                    v_image->>'code',
                                                    v_image->>'image',
                                                    v_image->>'extension',
                                                    p_user,
                                                    now()
                                                );
                                            END LOOP;

                                            -- Se inserta los diagramas que no tengan id, ya que son nuevos
                                            WITH diagrams_to_insert AS (
                                                SELECT
                                                    diagram_element->>'value' AS value,
                                                    (diagram_element->>'setting_diagrammed_course_id')::BIGINT AS setting_diagrammed_course_id
                                                FROM jsonb_array_elements(p_data_diagram) AS diagram_element
                                                WHERE diagram_element->>'id' IS NULL
                                            )
                                            INSERT INTO employee_didi_question_field(
                                                employee_didi_question_id, 
                                                setting_diagrammed_course_id, 
                                                value, 
                                                created_by, 
                                                created_at
                                            )
                                            SELECT
                                                v_employee_didi_question_id,
                                                dti.setting_diagrammed_course_id,
                                                dti.value,
                                                p_user,
                                                now()
                                            FROM diagrams_to_insert dti;

                                            -- Eliminar el employee_didi_question que no se enviaron en el array de diagramas
                                            WITH diagrams_to_update AS (
                                                SELECT
                                                    (diagram_element->>'id')::bigint AS id
                                                FROM jsonb_array_elements(p_data_diagram) AS diagram_element
                                            ), existing_diagrams AS (
                                                SELECT edqf.id  
                                                FROM employee_didi_question_field edqf 
                                                WHERE edqf.employee_didi_question_id = v_employee_didi_question_id
                                                AND edqf.fl_status = true
                                            ) UPDATE employee_didi_question_field AS edqf
                                            SET fl_status = false,
                                                deleted_at = now(),
                                                deleted_by = p_user
                                            FROM existing_diagrams ed
                                            WHERE ed.id = edqf.id AND ed.id NOT IN (SELECT id FROM diagrams_to_update);

                                            -- Se actualiza los que tengan id
                                            RETURN QUERY
                                            WITH updated AS (
                                                UPDATE employee_didi_question_field AS edqf
                                                SET value = diagram_element->>'value',
                                                    updated_by = p_user,
                                                    updated_at = now()
                                                FROM jsonb_array_elements(p_data_diagram) AS diagram_element
                                                WHERE edqf.id = (diagram_element->>'id')::bigint
                                                RETURNING edqf.id, edqf.value, edqf.updated_by, edqf.updated_at
                                            )
                                            SELECT * FROM updated;
                                        END;
                                    $$;


ALTER FUNCTION odiseo.fn_revised_question_digitalized(p_question_id bigint, p_data_diagram jsonb, p_images jsonb, p_user bigint) OWNER TO postgres;

--
-- Name: fn_revoke_user_token(uuid, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_revoke_user_token(p_user_uuid uuid, p_created_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
    DECLARE v_user_id BIGINT;
    BEGIN
        SELECT id INTO v_user_id FROM users WHERE uuid = p_user_uuid;

        UPDATE nq_user_request
            SET request_status = 'to_be_requested'
        WHERE user_id = v_user_id;

        UPDATE nq_user_token
            SET
                deleted_at = NOW(),
                deleted_by = p_created_by
        WHERE 1 = 1
          AND deleted_at IS NULL
          AND user_id = v_user_id;
    END;
    $$;


ALTER FUNCTION odiseo.fn_revoke_user_token(p_user_uuid uuid, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_rol(integer, integer, boolean, character varying, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_rol(p_perpage integer, p_npage integer, f_status boolean, p_name_text character varying, p_company_id integer) RETURNS TABLE(id bigint, name character varying, slug character varying, description text, fl_status boolean, created_by bigint, updated_by bigint, deleted_by bigint, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone, total bigint)
    LANGUAGE plpgsql
    AS $$
    DECLARE 
        offset_val INTEGER;
    BEGIN
        offset_val := p_perpage * (p_npage - 1);

        RETURN QUERY
        WITH roles_filtrados AS (
            SELECT r.id,
                r.name,
                r.slug,
                r.description,
                r.fl_status,
                r.created_by,
                r.updated_by,
                r.deleted_by,
                r.created_at,
                r.updated_at,
                r.deleted_at
            FROM roles r
            WHERE r.fl_status = f_status
            AND r.deleted_at IS NULL
            AND r.company_id = COALESCE(p_company_id, 1)
            AND (
                p_name_text IS NULL
                OR LOWER(r.name) LIKE '%' || LOWER(p_name_text) || '%'
                OR LOWER(r.slug) LIKE '%' || LOWER(p_name_text) || '%'
            )
        ),
        total_rows AS (
            SELECT COUNT(*) AS total FROM roles_filtrados
        )
        SELECT rf.*, tr.total
        FROM roles_filtrados rf
        CROSS JOIN total_rows tr
        ORDER BY rf.id ASC
        LIMIT p_perpage
        OFFSET offset_val;

    END;
    $$;


ALTER FUNCTION odiseo.fn_rol(p_perpage integer, p_npage integer, f_status boolean, p_name_text character varying, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_rol_users(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_rol_users(p_company_id bigint) RETURNS TABLE(id bigint, num_users bigint, name character varying, slug character varying, users json)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        SELECT
            r.id,
            count(u.id) AS num_users,
            r.name,
            r.slug,
            CASE
                WHEN count(u.id) > 0 THEN json_agg(u.*)
                ELSE '[]'::json
            END AS users
        FROM
            roles r
        LEFT JOIN
            users_roles rp ON r.id = rp.rol_id
        LEFT JOIN (
            SELECT
                u.id, u.uuid, u.user, u.email, u.image, u.fl_status
            FROM
                users u
            WHERE
                u.fl_status = true
        ) u ON rp.user_id = u.id
        WHERE
            r.fl_status = true
            AND r.fl_admin = false
            AND r.fl_administrator = false
            AND r.company_id = p_company_id
        GROUP BY
            r.id, r.name, r.slug
        ORDER BY
            r.id;
    END;
    $$;


ALTER FUNCTION odiseo.fn_rol_users(p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_save_course_category(bigint, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_course_category(p_course_id bigint, p_category_name character varying, p_user_id bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$ 
            DECLARE
                v_type_id INT;
                v_assigned_cat_id BIGINT;
            BEGIN
                INSERT INTO type_text (name, created_at, created_by) VALUES (p_category_name, CURRENT_TIMESTAMP, p_user_id) RETURNING id INTO v_type_id;

                INSERT INTO course_assigned_categories (
                    course_id, type_text_id, created_by, created_at, updated_at
                )
                VALUES (
                    p_course_id, v_type_id, p_user_id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
                )
                RETURNING id INTO v_assigned_cat_id;

                RETURN v_assigned_cat_id;
            END;
            $$;


ALTER FUNCTION odiseo.fn_save_course_category(p_course_id bigint, p_category_name character varying, p_user_id bigint) OWNER TO postgres;

--
-- Name: fn_save_course_subcategory(bigint, character varying, integer, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_course_subcategory(p_assigned_cat_id bigint, p_subcategory_name character varying, p_subcategory_id integer, p_user_id bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_sub_id INT;
                v_assigned_sub_id BIGINT;
            BEGIN
                IF p_subcategory_id IS NOT NULL THEN
                    v_sub_id := p_subcategory_id;
                ELSE
                    INSERT INTO type_text_subcategories (name, created_at, created_by) 
                    VALUES (p_subcategory_name, CURRENT_TIMESTAMP, p_user_id) 
                    RETURNING id INTO v_sub_id;
                END IF;

                INSERT INTO course_assigned_subcategories (
                    course_assigned_category_id, subcategory_id, created_by, created_at, updated_at
                ) VALUES (
                    p_assigned_cat_id, v_sub_id, p_user_id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
                )
                RETURNING id INTO v_assigned_sub_id;

                RETURN v_assigned_sub_id;
            END;
            $$;


ALTER FUNCTION odiseo.fn_save_course_subcategory(p_assigned_cat_id bigint, p_subcategory_name character varying, p_subcategory_id integer, p_user_id bigint) OWNER TO postgres;

--
-- Name: fn_save_courses_template_syllabus(jsonb, jsonb, integer, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_courses_template_syllabus(p_university_ids jsonb, p_courses jsonb, p_company_id integer, p_user bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_university_id BIGINT;
    v_p_course_ids BIGINT[]; -- [1,3]
    v_existing_course_ids BIGINT[];
    v_new_course_ids BIGINT[];
BEGIN
    /*
        ------------------------------------------------------------------------------------
        -- HISTORIAL DE CAMBIOS
        ------------------------------------------------------------------------------------

        Versión: 1.1
        Fecha: 2025-11-17
        Autor: Junior Alcarraz
        Descripción:
            Se agrega el campo de id de compañia al registrar cursos al syllabus template
    */

    -- Se guarda en una variable los IDs de los curso mandados
    SELECT array_agg((elem->>'id')::BIGINT)
    INTO v_p_course_ids
    FROM jsonb_array_elements(p_courses) elem;

    -- Iterar sobre cada universidad en el JSONB
    FOR v_university_id IN SELECT (value)::BIGINT FROM jsonb_array_elements_text(p_university_ids) AS value
    LOOP
        -- Eliminar los cursos que no se mandaron
        UPDATE syllabus_template ste
        SET fl_status = FALSE, updated_at = NOW(), updated_by = p_user
        WHERE ste.course_id NOT IN (SELECT * FROM UNNEST(v_p_course_ids))
            AND ste.university_id = v_university_id
            AND ste.fl_status IS TRUE
            AND ste.company_id = p_company_id;

        -- Obtener los cursos existentes en la universidad
        SELECT ARRAY(
            SELECT st.course_id
            FROM syllabus_template st
            WHERE st.university_id = v_university_id
                AND st.fl_status = TRUE
                AND st.course_id IS NOT NULL
                AND st.company_id = p_company_id
        ) INTO v_existing_course_ids;

        -- Identificar los cursos nuevos que no están en la base de datos
        SELECT ARRAY(
            SELECT (value)::BIGINT FROM unnest(v_p_course_ids) AS value
            EXCEPT
            SELECT unnest(v_existing_course_ids)
        ) INTO v_new_course_ids;

        -- Insertar los cursos nuevos
        IF v_new_course_ids IS NOT NULL THEN
            INSERT INTO syllabus_template (
                university_id,
                course_id,
                fl_status,
                company_id,
                created_at,
                created_by
            )
            SELECT
                v_university_id,
                unnest(v_new_course_ids),
                TRUE,
                p_company_id,
                NOW(),
                p_user;
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION odiseo.fn_save_courses_template_syllabus(p_university_ids jsonb, p_courses jsonb, p_company_id integer, p_user bigint) OWNER TO postgres;

--
-- Name: fn_save_image_gallery(jsonb, jsonb, character varying, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_image_gallery(p_topics jsonb, p_images jsonb, p_description character varying, p_user integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
            DECLARE
                image_element JSONB;
                topic_element INTEGER;
                new_id INTEGER;
            BEGIN
                BEGIN
                    FOR image_element IN
                        SELECT * FROM jsonb_array_elements(p_images)
                    LOOP
                        INSERT INTO odiseo.image_gallery(name,extension, image, width, height,path_full_version,path_short_version,created_by, created_at)
                        VALUES (
                        	p_description,
                            image_element->>'extension',
                            image_element->>'name',
                            (image_element->>'width')::INTEGER,
                            (image_element->>'height')::INTEGER,
                            image_element->>'path_full_version',
                            image_element->>'path_short_version',
                            p_user,
                            now()
                        )
                        RETURNING id INTO new_id;
                        FOR topic_element IN
                            SELECT (jsonb_array_elements_text(p_topics))::INTEGER
                        LOOP
                            INSERT INTO odiseo.image_galery_topic (image_gallery_id, topic_id, created_by, created_at)
                            VALUES (new_id, topic_element, p_user, now());
                        END LOOP;
                    END LOOP;

                END;
            END;
            $$;


ALTER FUNCTION odiseo.fn_save_image_gallery(p_topics jsonb, p_images jsonb, p_description character varying, p_user integer) OWNER TO postgres;

--
-- Name: fn_save_incomplete_questions(bigint, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_incomplete_questions(p_detail_week_type_mat_id bigint, p_url_json character varying, p_updated_by bigint) RETURNS TABLE(id bigint, material_id bigint, week smallint, type_material_id smallint, parent_type_material_id smallint)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            WITH updated_incomplete_questions AS (
                UPDATE detail_week_type_mat dwtm
                SET
                    fl_complete_questions = CASE
                        WHEN p_url_json IS NULL THEN TRUE
                        ELSE FALSE
                    END,
                    data_incomplete_questions = p_url_json,
                    updated_by = p_updated_by,
                    updated_at = NOW()
                WHERE 1 = 1
                  AND dwtm.id = p_detail_week_type_mat_id
                  AND dwtm.fl_status IS TRUE
                RETURNING
                    dwtm.id AS detail_week_type_mat_id,
                    dwtm.type_material_id,
                    dwtm.parent_type_material_id,
                    dwtm.material_id,
                    dwtm.week
            ), validate_type_material AS (
                SELECT
                    DISTINCT dwtm2.id AS detail_week_type_mat_id
                FROM detail_week_type_mat dwtm2
                WHERE dwtm2.fl_status = TRUE
                    AND dwtm2.material_id IN (SELECT uiq.material_id FROM updated_incomplete_questions uiq)
                    AND dwtm2.week = (SELECT uiq.week FROM updated_incomplete_questions uiq)
                    AND COALESCE(dwtm2.parent_type_material_id, dwtm2.type_material_id) = COALESCE(
                        (SELECT uiq.parent_type_material_id FROM updated_incomplete_questions uiq),
                        (SELECT uiq.type_material_id FROM updated_incomplete_questions uiq)
                    )
            ), updated_clean_pdf_url AS (
                UPDATE detail_week_type_mat dwtmupd
                SET
                    url_solution = null,
                    fl_process_status = 1,
                    url_without_solution = null,
                    fl_process_status_without = 1,
                    url_zip_class_mat = null,
                    fl_process_class_mat = 1,
                    url_quality = null,
                    fl_process_quality = 1,
                    url_without_quality = null,
                    fl_process_without_quality = 1,
                    updated_by = p_updated_by,
                    updated_at = now()
                WHERE 1 = 1
                  AND dwtmupd.fl_status IS TRUE
                  AND dwtmupd.id IN (SELECT vtm.detail_week_type_mat_id FROM validate_type_material vtm)
                RETURNING
                    dwtmupd.id,
                    dwtmupd.material_id,
                    dwtmupd.week,
                    dwtmupd.type_material_id,
                    dwtmupd.parent_type_material_id
            )
            SELECT * FROM updated_clean_pdf_url;
        END;
        $$;


ALTER FUNCTION odiseo.fn_save_incomplete_questions(p_detail_week_type_mat_id bigint, p_url_json character varying, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_save_incomplete_questions_area(bigint, smallint, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_incomplete_questions_area(p_week_type_material_id bigint, p_exam_area_id smallint, p_url_json character varying, p_updated_by bigint) RETURNS TABLE(material_id bigint, week smallint, type_material_id smallint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH update_material_exam_area_week AS (
        UPDATE material_exam_area_week meaw
        SET
            fl_complete_questions = CASE
                WHEN p_url_json IS NULL THEN TRUE
                ELSE FALSE
            END,
            data_incomplete_questions = p_url_json,
            url_solution = null,
            fl_process_status = 1,
            url_without_solution = null,
            fl_process_status_without = 1,
            url_quality = null,
            fl_process_quality = 1,
            url_without_quality = null,
            fl_process_without_quality = 1,
            updated_by = p_updated_by,
            updated_at = NOW()
        WHERE meaw.week_type_material_id = p_week_type_material_id
            AND meaw.area_id = p_exam_area_id
        RETURNING
            meaw.id,
            meaw.area_id,
            meaw.week_type_material_id
    ), clean_url_pdfs AS (
        SELECT
            fsiq.id,
            fsiq.material_id,
            fsiq.week,
            fsiq.type_material_id
        FROM fn_save_incomplete_questions(
            p_week_type_material_id,
            ''::VARCHAR,
            p_updated_by
        ) fsiq
        LIMIT 1
    )
    SELECT
        dwtm.material_id,
        dwtm.week,
        dwtm.type_material_id
    FROM detail_week_type_mat dwtm
    WHERE dwtm.id = p_week_type_material_id
    LIMIT 1;
END;
$$;


ALTER FUNCTION odiseo.fn_save_incomplete_questions_area(p_week_type_material_id bigint, p_exam_area_id smallint, p_url_json character varying, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_save_incomplete_text(bigint, json, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_incomplete_text(p_detail_week_type_mat_id bigint, p_missing_text json, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        BEGIN
            WITH updated_incomplete_text AS (
            UPDATE
                detail_week_type_mat dwtm
            SET
                data_missing_text = p_missing_text,
                updated_by = p_updated_by,
                updated_at = NOW()
            WHERE 1 = 1
            AND fl_status IS TRUE 
            AND id = p_detail_week_type_mat_id
            RETURNING
                dwtm.id AS detail_week_type_mat_id,
                dwtm.type_material_id,
                dwtm.parent_type_material_id,
                dwtm.material_id,
                dwtm.week
            ), validate_type_material AS (
                SELECT
                    DISTINCT dwtm2.id AS detail_week_type_mat_id
                FROM detail_week_type_mat dwtm2
                WHERE dwtm2.fl_status = TRUE
                    AND dwtm2.material_id IN (SELECT uiq.material_id FROM updated_incomplete_text uiq)
                    AND dwtm2.week = (SELECT uiq.week FROM updated_incomplete_text uiq)
                    AND COALESCE(dwtm2.parent_type_material_id, dwtm2.type_material_id) = COALESCE(
                        (SELECT uiq.parent_type_material_id FROM updated_incomplete_text uiq),
                        (SELECT uiq.type_material_id FROM updated_incomplete_text uiq)
                    )
            )  UPDATE detail_week_type_mat dwtmupd
                SET
                    url_solution = null,
                    fl_process_status = 1,
                    url_without_solution = null,
                    fl_process_status_without = 1,
                    url_zip_class_mat = null,
                    fl_process_class_mat = 1,
                    url_quality = null,
                    fl_process_quality = 1,
                    url_without_quality = null,
                    fl_process_without_quality = 1,
                    updated_by = p_updated_by,
                    updated_at = now()
                WHERE 1 = 1
                AND dwtmupd.fl_status IS TRUE
                AND dwtmupd.id IN (SELECT vtm.detail_week_type_mat_id FROM validate_type_material vtm);
        END;
    $$;


ALTER FUNCTION odiseo.fn_save_incomplete_text(p_detail_week_type_mat_id bigint, p_missing_text json, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_save_level_syllabus(smallint, bigint, jsonb, jsonb, jsonb, jsonb, jsonb, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_level_syllabus(p_university_id smallint, p_cycle_id bigint, p_week_ids jsonb, p_headquarters_ids jsonb, p_course_ids jsonb, p_detail_level_syllabus jsonb, p_detail_level_syllabus_parent jsonb, p_created_by bigint, p_company_id bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_level_syllabus_id BIGINT;
                v_level_syllabus_week_id BIGINT;
                v_headquarter JSONB;
                v_course JSONB;
                v_week_id JSONB;
                v_detail_level_syllabus JSONB;
				v_detail_level_syllabus_parent JSONB;
				v_detail_type_text_syllabus JSONB;
                v_detail_level_syllabus_weeks_id BIGINT;
				v_detail_level_syllabus_weeks_parent_id BIGINT;
            BEGIN
                -- Itera sobre cada sede en el array JSONB de sedes
                FOR v_headquarter IN SELECT * FROM jsonb_array_elements(p_headquarters_ids) LOOP
                    -- Itera sobre cada curso en el array JSONB de cursos
                    FOR v_course IN SELECT * FROM jsonb_array_elements(p_course_ids) LOOP
                        -- Itera sobre cada semana en el array JSONB de semanas
                        FOR v_week_id IN SELECT * FROM jsonb_array_elements(p_week_ids) LOOP                      

							-- Verificar si ya existe un level_syllabus con el university_id, cycle_id, course_id y headquarter_id
                            SELECT ls.id
                            INTO v_level_syllabus_id
                            FROM level_syllabus ls
                            WHERE ls.university_id = p_university_id
                            AND ls.cycle_id = p_cycle_id
                            AND ls.course_id = (v_course::TEXT)::SMALLINT
                            AND ls.headquarter_id = (v_headquarter::TEXT)::SMALLINT
                            AND ls.fl_status = TRUE;

                            -- Si no existe, inserta en level_syllabus y obtiene el id
                            IF v_level_syllabus_id IS NULL THEN
                                INSERT INTO level_syllabus (university_id, cycle_id, course_id, headquarter_id, created_by, created_at, company_id)
                                VALUES (p_university_id, p_cycle_id, (v_course::TEXT)::SMALLINT, (v_headquarter::TEXT)::SMALLINT, p_created_by, now(), p_company_id)
                                RETURNING id INTO v_level_syllabus_id;
                            END IF;

                            -- Verifica si ya existe un level_syllabus_week con el level_syllabus_id y week
                            SELECT lsw.id
                            INTO v_level_syllabus_week_id
                            FROM level_syllabus_weeks lsw
                            WHERE lsw.level_syllabus_id = v_level_syllabus_id
                            AND lsw.week = (v_week_id::TEXT)::SMALLINT
                            AND lsw.fl_status = TRUE
                            AND lsw.deleted_at IS NULL;

                            -- Si no existe, inserta en level_syllabus_weeks y obtiene el id
                            IF v_level_syllabus_week_id IS NULL THEN
                                INSERT INTO level_syllabus_weeks (level_syllabus_id, week, created_by, created_at, company_id)
                                VALUES (v_level_syllabus_id, (v_week_id::TEXT)::SMALLINT, p_created_by, now(), p_company_id)
                                RETURNING id INTO v_level_syllabus_week_id;
                            END IF;

							
                            -- Marcar como eliminados los registros que no están en p_detail_level_syllabus
                            UPDATE detail_level_syllabus_weeks
                            SET fl_status = FALSE,
                                deleted_by = p_created_by,
                                deleted_at = now()
                            WHERE level_syllabus_weeks_id = v_level_syllabus_week_id
                            AND fl_status = TRUE
                            AND (type_material_id, level_id, type_question) NOT IN (
                                SELECT (value->>'type_material_id')::SMALLINT,
                                        (value->>'level_id')::SMALLINT,
                                        value->>'type_question'
                                FROM jsonb_array_elements(p_detail_level_syllabus)
                            );

                            -- Itera sobre el detalle de nivel del syllabus
                            FOR v_detail_level_syllabus IN SELECT * FROM jsonb_array_elements(p_detail_level_syllabus) LOOP
                                -- Verificar si ya existe ese registro de detail_level_syllabus_weeks
                                SELECT dlsw.id
                                INTO v_detail_level_syllabus_weeks_id
                                FROM detail_level_syllabus_weeks dlsw
                                WHERE dlsw.level_syllabus_weeks_id = v_level_syllabus_week_id
                                AND dlsw.type_material_id = (v_detail_level_syllabus->>'type_material_id')::SMALLINT
                                AND dlsw.level_id = (v_detail_level_syllabus->>'level_id')::SMALLINT
                                AND dlsw.type_question = v_detail_level_syllabus->>'type_question'
                                AND dlsw.fl_status = TRUE;

                                -- Si no existe, insertar
                                IF v_detail_level_syllabus_weeks_id IS NULL THEN
                                    IF COALESCE((v_detail_level_syllabus->>'total_questions')::INTEGER, 0) > 0 THEN
                                        INSERT INTO detail_level_syllabus_weeks (
                                            level_syllabus_weeks_id, type_material_id, level_id, type_question, number_questions, created_by, created_at, company_id
                                        )
                                        VALUES (
                                            v_level_syllabus_week_id,
                                            (v_detail_level_syllabus->>'type_material_id')::SMALLINT,
                                            (v_detail_level_syllabus->>'level_id')::SMALLINT,
                                            v_detail_level_syllabus->>'type_question',
                                            (v_detail_level_syllabus->>'total_questions')::INTEGER,
                                            p_created_by,
                                            now(),
											p_company_id
                                        );
                                    END IF;
                                ELSE
                                    -- Si existe, actualizar
                                    UPDATE detail_level_syllabus_weeks
                                    SET number_questions = (v_detail_level_syllabus->>'total_questions')::INTEGER,
                                        updated_by = p_created_by,
                                        updated_at = now()
                                    WHERE id = v_detail_level_syllabus_weeks_id;
                                END IF;
                            END LOOP;


							--	NIVELES PARA LOS TEXTOS						
							UPDATE detail_level_syllabus_weeks_parents
                            SET fl_status = FALSE,
                                deleted_by = p_created_by,
                                deleted_at = now()
                            WHERE level_syllabus_weeks_id = v_level_syllabus_week_id
                            AND fl_status = TRUE
                            AND (level_id, type_material_id) NOT IN (
                                SELECT (value->>'level_id')::SMALLINT,
									   (value->>'type_material_id')::SMALLINT
                                FROM jsonb_array_elements(p_detail_level_syllabus_parent)
                            );

							FOR v_detail_level_syllabus_parent IN SELECT * FROM jsonb_array_elements(p_detail_level_syllabus_parent) LOOP
                                -- Verificar si ya existe ese registro de detail_level_syllabus_weeks
                                 	SELECT dlswp.id
									INTO v_detail_level_syllabus_weeks_parent_id
									FROM detail_level_syllabus_weeks_parents dlswp
									WHERE dlswp.level_syllabus_weeks_id = v_level_syllabus_week_id
									AND dlswp.level_id = (v_detail_level_syllabus_parent->>'level_id')::SMALLINT
									AND dlswp.type_material_id = (v_detail_level_syllabus_parent->>'type_material_id')::SMALLINT
									AND dlswp.fl_status = TRUE;

                                -- Si no existe, insertar
                                IF v_detail_level_syllabus_weeks_parent_id IS NULL THEN
                                    IF COALESCE((v_detail_level_syllabus_parent->>'total_text')::INTEGER, 0) > 0 THEN
										INSERT INTO detail_level_syllabus_weeks_parents (
                                            level_syllabus_weeks_id,
											level_id,
											number_of_passages,
											type_material_id,
											created_by, 
											created_at,
											company_id
                                        )
                                        VALUES (
                                            v_level_syllabus_week_id,
                                            (v_detail_level_syllabus_parent->>'level_id')::SMALLINT,
                                            (v_detail_level_syllabus_parent->>'total_text')::INTEGER,
											(v_detail_level_syllabus_parent->>'type_material_id')::INTEGER,
                                            p_created_by,
                                            now(),
											p_company_id
                                        );
                                    END IF;
                                ELSE
                                    -- Si existe, actualizar
                                    UPDATE detail_level_syllabus_weeks_parents
                                    SET number_of_passages = (v_detail_level_syllabus_parent->>'total_text')::INTEGER,
                                        updated_by = p_created_by,
                                        updated_at = now()
                                    WHERE id = v_detail_level_syllabus_weeks_parent_id;
                                END IF;
                            END LOOP;


                        END LOOP;
                    END LOOP;
                END LOOP;
            END;
        $$;


ALTER FUNCTION odiseo.fn_save_level_syllabus(p_university_id smallint, p_cycle_id bigint, p_week_ids jsonb, p_headquarters_ids jsonb, p_course_ids jsonb, p_detail_level_syllabus jsonb, p_detail_level_syllabus_parent jsonb, p_created_by bigint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_save_material(bigint, smallint, jsonb, boolean, character varying, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_material(p_material_id bigint, p_week smallint, p_type_materials jsonb, p_solution boolean, p_url_pdf character varying, p_fl_process_status smallint, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_type_material_id SMALLINT;
        BEGIN
            IF p_solution IS TRUE THEN
                FOR v_type_material_id IN SELECT * FROM jsonb_array_elements(p_type_materials) LOOP
                    UPDATE odiseo.detail_week_type_mat
                    SET url_solution = p_url_pdf, updated_by = p_updated_by, updated_at = now(), fl_process_status = p_fl_process_status
                    WHERE material_id = p_material_id AND week = p_week AND type_material_id = v_type_material_id AND fl_status = true;
                END LOOP;
            ELSE
                FOR v_type_material_id IN SELECT * FROM jsonb_array_elements(p_type_materials) LOOP
                    UPDATE odiseo.detail_week_type_mat
                    SET url_without_solution = p_url_pdf, updated_by = p_updated_by, updated_at = now(), fl_process_status_without = p_fl_process_status
                    WHERE material_id = p_material_id AND week = p_week AND type_material_id = v_type_material_id AND fl_status = true;
                END LOOP;
            END IF;
        END;
        $$;


ALTER FUNCTION odiseo.fn_save_material(p_material_id bigint, p_week smallint, p_type_materials jsonb, p_solution boolean, p_url_pdf character varying, p_fl_process_status smallint, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_save_material_exam(bigint, smallint, smallint, boolean, character varying, character varying, smallint, smallint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_material_exam(p_material_id bigint, p_week smallint, p_type_material_id smallint, p_solution boolean, p_filename character varying, p_url_pdf character varying, p_exam_area_id smallint, p_fl_process_status smallint, p_number_pages smallint, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_type_material_id SMALLINT;
    v_detail_week_type_mat_id BIGINT;
BEGIN
    SELECT dwtm.id INTO v_detail_week_type_mat_id FROM detail_week_type_mat dwtm
    WHERE dwtm.material_id = p_material_id AND dwtm.week = p_week AND dwtm.type_material_id = p_type_material_id AND dwtm.fl_status = true;

    IF p_solution IS TRUE THEN
        UPDATE material_exam_area_week
        SET url_solution = p_url_pdf,
            filename = p_filename,
            updated_by = p_updated_by,
            updated_at = now(),
            fl_process_status = p_fl_process_status
        WHERE week_type_material_id = v_detail_week_type_mat_id AND area_id = p_exam_area_id AND fl_status = true;
    ELSE
        UPDATE material_exam_area_week
        SET url_without_solution = p_url_pdf,
            filename = p_filename,
            updated_by = p_updated_by,
            updated_at = now(),
            fl_process_status_without = p_fl_process_status,
            number_pages = p_number_pages
        WHERE week_type_material_id = v_detail_week_type_mat_id AND area_id = p_exam_area_id AND fl_status = true;
    END IF;
END;
$$;


ALTER FUNCTION odiseo.fn_save_material_exam(p_material_id bigint, p_week smallint, p_type_material_id smallint, p_solution boolean, p_filename character varying, p_url_pdf character varying, p_exam_area_id smallint, p_fl_process_status smallint, p_number_pages smallint, p_updated_by bigint) OWNER TO postgres;

