--
-- Name: fn_save_origin_university(character varying, character varying, smallint, smallint, jsonb, text, text, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_origin_university(p_name character varying, p_slug character varying, p_type smallint, p_region_id smallint, p_options jsonb, p_areas text, p_versions text, p_created_by bigint) RETURNS TABLE(v_validated boolean, v_type integer, v_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_exists_id SMALLINT;
    v_option_item JSONB;
    v_modality_item JSONB;
    v_new_id BIGINT;
    v_ou_id INT;
    v_code_uni VARCHAR;
BEGIN
    SELECT id INTO v_exists_id FROM origin_university
    WHERE LOWER(name) = LOWER(p_name) AND deleted_at IS NULL LIMIT 1;

    IF v_exists_id IS NOT NULL THEN
        RETURN QUERY SELECT FALSE, 1, 0::BIGINT;
        RETURN;
    END IF;

    SELECT LPAD(COALESCE(COUNT(id) + 1, 1)::TEXT, 3, '0') INTO v_code_uni FROM origin_university;

    INSERT INTO origin_university (
        code, name, slug, type, region_id, areas, versions, created_by, created_at
    )
    VALUES (
        v_code_uni, p_name, p_slug, p_type, p_region_id, p_areas, p_versions::jsonb, p_created_by, now()
    )
    RETURNING id INTO v_new_id;

    FOR v_option_item IN SELECT * FROM jsonb_array_elements(p_options) LOOP
        
        INSERT INTO option_university (
            university_id, 
            name, 
            created_at, 
            created_by
        )
        VALUES (
            v_new_id, 
            v_option_item->>'name', 
            now(), 
            p_created_by
        )
        RETURNING id INTO v_ou_id;

        FOR v_modality_item IN SELECT * FROM jsonb_array_elements(v_option_item->'modalities') LOOP
            
            INSERT INTO modality_options (
                option_university_id, 
                name, 
                fl_allows_mark_frequent_topic, 
                created_at, 
                created_by
            )
            VALUES (
                v_ou_id,
                v_modality_item->>'name',
                COALESCE((v_modality_item->>'fl_allows_mark_frequent_topic')::BOOLEAN, false),
                now(),
                p_created_by
            );

        END LOOP;
    END LOOP;

    -- Retornar éxito
    RETURN QUERY SELECT TRUE, 0, v_new_id;
END;
$$;


ALTER FUNCTION odiseo.fn_save_origin_university(p_name character varying, p_slug character varying, p_type smallint, p_region_id smallint, p_options jsonb, p_areas text, p_versions text, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_save_plan(character varying, character varying, numeric, character varying, integer, integer, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_plan(p_name character varying, p_description character varying, p_cost numeric, p_benefits character varying, p_number_users integer, p_number_questions integer, p_created_by bigint) RETURNS TABLE(v_validated boolean, v_id bigint)
    LANGUAGE plpgsql
    AS $$
			DECLARE
				v_exits_id BIGINT;
            BEGIN
				SELECT id INTO v_exits_id
				FROM odiseo."plans"
				WHERE LOWER(name) = LOWER(p_name)
				LIMIT 1;

				IF v_exits_id IS NULL THEN
					INSERT INTO odiseo."plans" (name, description, cost, benefits, number_users, number_questions, created_by, created_at)
					VALUES(p_name, p_description, p_cost, p_benefits, p_number_users, p_number_questions, p_created_by, now())
					RETURNING id INTO v_id;

					RETURN QUERY SELECT TRUE, v_id;
				ELSE
					RETURN QUERY SELECT FALSE, 0::BIGINT;
				END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_save_plan(p_name character varying, p_description character varying, p_cost numeric, p_benefits character varying, p_number_users integer, p_number_questions integer, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_save_prospect(character varying, character varying, character varying, character varying, character varying, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_prospect(p_code character varying, p_name character varying, p_charge character varying, p_type_company character varying, p_name_institute character varying, p_document_number character varying, p_created_by bigint) RETURNS TABLE(v_validated boolean, v_new_prospect_id bigint)
    LANGUAGE plpgsql
    AS $$
			DECLARE
				v_code_id BIGINT;
				v_new_id BIGINT;
            BEGIN
                SELECT cp.id INTO v_code_id
                FROM odiseo.code_prospect cp
				WHERE code = p_code
				AND fl_status = true
				LIMIT 1;

				IF v_code_id IS NOT NULL THEN
					INSERT INTO odiseo.prospect (name, charge, type_company, name_institute, document_number, code_id, created_by, created_at)
					VALUES(p_name, p_charge, p_type_company, p_name_institute, p_document_number, v_code_id, p_created_by, now())
					RETURNING id INTO v_new_id;

					UPDATE odiseo.code_prospect
					SET fl_status = false, deleted_by = created_by, deleted_at = now()
					WHERE code = p_code AND fl_status = true;

					RETURN QUERY SELECT TRUE, v_new_id;
				ELSE
					RETURN QUERY SELECT FALSE, 0::BIGINT;
				END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_save_prospect(p_code character varying, p_name character varying, p_charge character varying, p_type_company character varying, p_name_institute character varying, p_document_number character varying, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_save_question_material_ballot(smallint, bigint, smallint, smallint, smallint, bigint, smallint, bigint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_question_material_ballot(p_week smallint, p_question_id bigint, p_subtopic_id smallint, p_level_id smallint, p_position smallint, p_week_type_material_id bigint, p_type_material_id smallint, p_material_id bigint, p_material_distribution_id bigint, p_created_by bigint) RETURNS TABLE(id bigint, material_id bigint, week smallint, type_material_id smallint, week_type_material_id bigint, course_id smallint, code_course character varying, course character varying, "position" smallint, position_initial smallint, subtopic_id smallint, code_subtopic character varying, subtopic character varying, topic_id smallint, code_topic character varying, topic character varying, level_id bigint, level_description character varying, level_name character varying, usage_level_id bigint, question_id bigint, type character varying, usage_status boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_cycle_id bigint;
    v_cycle_start_date date;
    v_university_id smallint;
    v_headquarters_id bigint;
    v_course_id smallint;
    v_topic_id smallint;
    v_type varchar;
    v_history jsonb;
    v_question_history_id bigint;
    v_parent_type_material_id smallint;
BEGIN
    -- Obtener ciclo y universidad del material
    SELECT
        m.cycle_id,
        c.start_date,
        m.university_id,
        m.headquarte_id INTO v_cycle_id,
        v_cycle_start_date,
        v_university_id,
        v_headquarters_id
    FROM
        material m
            INNER JOIN CYCLE c ON m.cycle_id = c.id
        WHERE
            m.id = p_material_id
        LIMIT 1;
    -- Obtener los campos de pregunta
    SELECT
        fqvm.course_id,
        fqvm.topic_id,
        fqvm.type,
        fqvm.history INTO v_course_id,
        v_topic_id,
        v_type,
        v_history
    FROM
        fn_question_verified_material(p_material_id, FALSE) fqvm
WHERE
    fqvm.id = p_question_id
        AND fqvm.subtopic_id = p_subtopic_id
        AND fqvm.level_id = p_level_id
    LIMIT 1;
    -- Traer o registrar historial
    SELECT
        qhc.id INTO v_question_history_id
    FROM
        question_history_cycle qhc
    WHERE
        qhc.question_id = p_question_id
        AND qhc.cycle_id = v_cycle_id
        AND qhc.university_id = v_university_id
        AND qhc.headquarters_id = v_headquarters_id
        AND qhc.fl_status = TRUE
    LIMIT 1;
    -- Si no hay historial se registra
    IF v_question_history_id IS NULL THEN
        INSERT INTO question_history_cycle AS qhc(question_id, cycle_id, university_id, headquarters_id, created_by, created_at, automatic)
            VALUES (p_question_id, v_cycle_id, v_university_id, v_headquarters_id, p_created_by, now(), FALSE)
        RETURNING
            qhc.id INTO v_question_history_id;
    END IF;
    -- Insertar pregunta de balotario & Actualizar distribución (UNIFICADO)
    IF p_material_distribution_id IS NOT NULL THEN
        UPDATE
            odiseo.material_ballot_question mdbq
        SET
            course_id = v_course_id,
            topic_id = v_topic_id,
            subtopic_id = p_subtopic_id,
            level_id = p_level_id,
            usage_level_id = p_level_id,
            question_id = p_question_id,
            question_history_id = v_question_history_id,
            usage_status = FALSE,
            added_in_completion = TRUE,
            fl_is_manual = TRUE,
            state = 'MANUAL_COMPLETED',
            type = v_type,
            updated_by = p_created_by,
            updated_at = NOW()
        WHERE
            mdbq.id = p_material_distribution_id;
    ELSE
        INSERT INTO odiseo.material_ballot_question(
            week_type_material_id, course_id, topic_id, subtopic_id, level_id,
            type, question_id, question_history_id, position, fl_is_manual, state,
            added_in_completion, created_by, created_at
        )
        VALUES (
            p_week_type_material_id, v_course_id, v_topic_id, p_subtopic_id, p_level_id,
            v_type, p_question_id, v_question_history_id, p_position, TRUE, 'MANUAL_COMPLETED',
            TRUE, p_created_by, NOW()
        );
    END IF;
    -- Quitar pregunta de la distribución si está en el balotario
    UPDATE
        detail_week_type_mat dwtmupd
    SET
        url_solution = NULL,
        url_without_solution = NULL,
        fl_process_status = 1,
        fl_process_status_without = 1,
        url_zip_class_mat = NULL,
        fl_process_class_mat = 1,
        fl_process_quality = 1,
        url_quality = NULL,
        fl_process_without_quality = 1,
        url_without_quality = NULL,
        updated_by = p_created_by,
        updated_at = now()
    WHERE
        dwtmupd.id =(
            SELECT
                dwtmupdcp.id
            FROM
                detail_week_type_mat dwtmupdcp
            WHERE
                dwtmupdcp.material_id = p_material_id
                AND dwtmupdcp.week = p_week
                AND dwtmupdcp.type_material_id = p_type_material_id)
    RETURNING
        dwtmupd.parent_type_material_id INTO v_parent_type_material_id;

    RETURN QUERY
    SELECT
        fmdbq.id,
        fmdbq.material_id,
        fmdbq.week,
        fmdbq.type_material_id,
        fmdbq.week_type_material_id,
        fmdbq.course_id,
        fmdbq.code_course,
        fmdbq.course,
        fmdbq.position,
        fmdbq.position_initial,
        fmdbq.subtopic_id,
        fmdbq.code_subtopic,
        fmdbq.subtopic,
        fmdbq.topic_id,
        fmdbq.code_topic,
        fmdbq.topic,
        fmdbq.level_id,
        fmdbq.level_description,
        fmdbq.level_name,
        fmdbq.usage_level_id,
        fmdbq.question_id,
        fmdbq.type,
        fmdbq.usage_status
    FROM
        fn_material_ballot_question(p_material_id, p_week, p_type_material_id, p_week_type_material_id) AS fmdbq;
END;
$$;


ALTER FUNCTION odiseo.fn_save_question_material_ballot(p_week smallint, p_question_id bigint, p_subtopic_id smallint, p_level_id smallint, p_position smallint, p_week_type_material_id bigint, p_type_material_id smallint, p_material_id bigint, p_material_distribution_id bigint, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_save_question_material_exam(bigint, bigint, smallint, smallint, smallint, bigint, smallint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_question_material_exam(p_id bigint, p_material_id bigint, p_type_material_id smallint, p_week smallint, p_area_id smallint, p_question_id bigint, p_subtopic_id smallint, p_level_id smallint, p_created_by bigint) RETURNS TABLE(id bigint, question_id bigint, question_history_id bigint, type_material_id smallint, type_material character varying, week smallint, course_id smallint, code_course character varying, course character varying, topic_id smallint, code_topic character varying, topic character varying, subtopic_id smallint, code_subtopic character varying, subtopic character varying, level_id bigint, level_description character varying, level_name character varying, area_id smallint, exam_area character varying, data_incomplete_questions character varying, material_exam_area_week_id bigint, week_type_material_id bigint, type character varying, "position" smallint, fl_is_manual boolean)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        WITH tbl_material AS (
            SELECT
                dwtm.material_id,
                m.cycle_id,
                m.university_id,
                m.headquarte_id,
                dwtm.type_material_id,
                dwtm.week,
                meaw.area_id,
                meaw.id AS material_exam_area_week_id
            FROM material m
            JOIN detail_week_type_mat dwtm ON m.id = dwtm.material_id
            JOIN material_exam_area_week meaw ON dwtm.id = meaw.week_type_material_id
            WHERE dwtm.material_id = p_material_id
                AND dwtm.type_material_id = p_type_material_id
                AND dwtm.week = p_week
                AND dwtm.fl_status = true
                AND meaw.area_id = p_area_id
                AND meaw.fl_status = true
            LIMIT 1
        ), tbl_question_data AS (
            SELECT
                fqvtmw.course_id,
                fqvtmw.topic_id,
                fqvtmw.subtopic_id,
                fqvtmw.level_id,
                fqvtmw.type,
                fqvtmw.history
            FROM tbl_material tm
            CROSS JOIN LATERAL fn_questions_verified_by_type_material_week(
                tm.material_id,
                tm.type_material_id,
                tm.week,
                tm.area_id
            ) fqvtmw
            WHERE fqvtmw.id = p_question_id
                AND fqvtmw.subtopic_id = p_subtopic_id
                AND fqvtmw.level_id = p_level_id
            LIMIT 1
        ), find_history AS (
            SELECT
                qhc.id AS question_history_id
            FROM question_history_cycle qhc, tbl_material tm
            WHERE qhc.question_id = p_question_id
                AND qhc.cycle_id = tm.cycle_id
                AND qhc.university_id = tm.university_id
                AND qhc.headquarters_id = tm.headquarte_id
                AND qhc.fl_status = true
            LIMIT 1
        ), insert_history_if_not_exists AS (
            INSERT INTO question_history_cycle AS qhc (
                question_id,
                cycle_id,
                university_id,
                headquarters_id,
                created_by,
                created_at
            )
            SELECT
                p_question_id,
                tm.cycle_id,
                tm.university_id,
                tm.headquarte_id,
                p_created_by,
                NOW()
            FROM tbl_material tm
            WHERE NOT EXISTS (SELECT 1 FROM find_history)
            RETURNING qhc.id AS question_history_id
        ), history_data AS (
            SELECT fh.question_history_id FROM find_history fh
            UNION ALL
            SELECT ih.question_history_id FROM insert_history_if_not_exists ih
            LIMIT 1
        ), tbl_position_final AS (
            SELECT COALESCE(MAX(meqpos.position), 0) AS position_final
            FROM material_exam_question meqpos
            WHERE meqpos.material_exam_area_week_id IN (SELECT tm.material_exam_area_week_id FROM tbl_material tm)
                AND meqpos.course_id IN (SELECT tqd.course_id FROM tbl_question_data tqd)
                AND meqpos.fl_status = true
        ), update_question_exam AS (
            UPDATE material_exam_question meq
            SET
                course_id = tqd.course_id,
                topic_id = tqd.topic_id,
                subtopic_id = p_subtopic_id,
                level_id = p_level_id,
                type = tqd.type,
                question_id = p_question_id,
                question_history_id = hd.question_history_id,
                position = tpf.position_final + 1,
                fl_is_manual = true,
                updated_by = p_created_by,
                updated_at = NOW()
            FROM tbl_question_data tqd,
                history_data hd,
                tbl_position_final tpf
            WHERE meq.id = p_id
            RETURNING
                meq.id,
                meq.course_id,
                meq.topic_id,
                meq.subtopic_id,
                meq.level_id,
                meq.type,
                meq.question_id,
                meq.question_history_id,
                meq.position,
                meq.fl_is_manual,
                meq.material_exam_area_week_id
        )
        SELECT
            uqe.id,
            uqe.question_id,
            uqe.question_history_id,
            dwtm.type_material_id,
            tm.description AS type_material,
            dwtm.week,
            uqe.course_id,
            c.code AS code_course,
            c.name AS course,
            uqe.topic_id,
            t.code AS code_topic,
            t.name AS topic,
            uqe.subtopic_id,
            st.code AS code_subtopic,
            st.name AS subtopic,
            uqe.level_id,
            l.description AS level_description,
            l.name AS level_name,
            meaw.area_id,
            ea.description AS exam_area,
            meaw.data_incomplete_questions,
            meaw.id AS material_exam_area_week_id,
            dwtm.id AS week_type_material_id,
            uqe.type,
            uqe.position,
            uqe.fl_is_manual
        FROM update_question_exam uqe
        JOIN material_exam_area_week meaw ON uqe.material_exam_area_week_id = meaw.id
        JOIN detail_week_type_mat dwtm ON meaw.week_type_material_id = dwtm.id
        JOIN course c ON uqe.course_id = c.id
        JOIN type_material tm ON dwtm.type_material_id = tm.id
        JOIN exam_area ea ON meaw.area_id = ea.id
        LEFT JOIN topic t ON uqe.topic_id = t.id
        LEFT JOIN subtopic st ON uqe.subtopic_id = st.id
        LEFT JOIN level l ON uqe.level_id = l.id;
    END;
    $$;


ALTER FUNCTION odiseo.fn_save_question_material_exam(p_id bigint, p_material_id bigint, p_type_material_id smallint, p_week smallint, p_area_id smallint, p_question_id bigint, p_subtopic_id smallint, p_level_id smallint, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_save_subquestion_material_ballot(bigint, bigint, bigint, bigint, json); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_subquestion_material_ballot(p_parent_question_id bigint, p_material_id bigint, p_material_distribution_id bigint, p_created_by bigint, p_subquestion json) RETURNS void
    LANGUAGE plpgsql
    AS $$
                DECLARE
                v_cycle_id BIGINT;
                v_cycle_start_date DATE;
                v_university_id SMALLINT;
                v_headquarters_id BIGINT;
                v_question_history_id BIGINT;
                v_week_type_material_id BIGINT;
                BEGIN

                SELECT
                    m.cycle_id, c.start_date, m.university_id, m.headquarte_id
                    INTO v_cycle_id, v_cycle_start_date, v_university_id, v_headquarters_id
                FROM material m
                INNER JOIN cycle c ON m.cycle_id = c.id
                WHERE m.id = p_material_id
                LIMIT 1;

                -- Traer o registrar historial
                SELECT
                    qhc.id INTO v_question_history_id
                FROM question_history_cycle qhc
                WHERE qhc.parent_question_id = p_parent_question_id
                    AND qhc.cycle_id = v_cycle_id
                    AND qhc.university_id = v_university_id
                    AND qhc.headquarters_id = v_headquarters_id
                    AND qhc.fl_status = true
                LIMIT 1;

                -- Si no hay historial se registra
                IF v_question_history_id IS NULL THEN
                    INSERT INTO question_history_cycle AS qhc (
                        question_id,
                        cycle_id,
                        university_id,
                        headquarters_id,
                        created_by,
                        created_at,
                        automatic,
                        subquestion
                    )
                    VALUES (
                        p_parent_question_id,
                        v_cycle_id,
                        v_university_id,
                        v_headquarters_id,
                        p_created_by,
                        now(),
                        false,
                        p_subquestion
                    )
                    RETURNING qhc.id INTO v_question_history_id;
                END IF;

                UPDATE material_ballot_question mdbq
                SET
                    updated_by = p_created_by,
                    updated_at = NOW()
                WHERE mdbq.id = p_material_distribution_id
                RETURNING mdbq.week_type_material_id into v_week_type_material_id;

                -- Soft-delete subpreguntas anteriores
                UPDATE material_ballot_subquestions
                SET fl_status = FALSE, deleted_at = NOW(), deleted_by = p_created_by
                WHERE material_ballot_question_id = p_material_distribution_id AND fl_status = TRUE;

                -- Insertar nuevas subpreguntas desde el JSON
                INSERT INTO material_ballot_subquestions (material_ballot_question_id, question_id, position, state, topic_id, course_id, subtopic_id, fl_is_manual, added_in_completion, created_by, created_at)
                SELECT
                    p_material_distribution_id,
                    (sub.obj->>'question_id')::bigint,
                    sub.ord::int,
                    CASE WHEN (sub.obj->>'question_id') IS NOT NULL THEN 'MANUAL_COMPLETED' ELSE 'MISSING' END,
                    (sub.obj->>'topic_id')::smallint,
                    (sub.obj->>'course_id')::smallint,
                    (sub.obj->>'subtopic_id')::smallint,
                    TRUE,
                    TRUE,
                    p_created_by,
                    NOW()
                FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_subquestion::jsonb) = 'array' THEN p_subquestion::jsonb ELSE '[]'::jsonb END) WITH ORDINALITY AS sub(obj, ord);

                END;
            $$;


ALTER FUNCTION odiseo.fn_save_subquestion_material_ballot(p_parent_question_id bigint, p_material_id bigint, p_material_distribution_id bigint, p_created_by bigint, p_subquestion json) OWNER TO postgres;

--
-- Name: fn_save_subtopics_template_syllabus(jsonb, smallint, smallint, jsonb, integer, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_subtopics_template_syllabus(p_university_ids jsonb, p_course_id smallint, p_topic_id smallint, p_subtopic_ids jsonb, p_company_id integer, p_user bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_p_subtopic_ids SMALLINT[];
    v_university_id BIGINT;
    v_topic_syllabus_template_id BIGINT;
    v_existing_subtopics_ids BIGINT[];
    v_new_subtopic_ids BIGINT[];
BEGIN
    /*
        ------------------------------------------------------------------------------------
        -- HISTORIAL DE CAMBIOS
        ------------------------------------------------------------------------------------

        Versión: 1.1
        Fecha: 2025-11-17
        Autor: Junior Alcarraz
        Descripción:
            Se agrega el campo de id de compañia al registrar subtemas al syllabus template
    */

    -- Se guarda en una variable los IDs de los temas mandados
    SELECT array_agg(value::BIGINT) INTO v_p_subtopic_ids
    FROM jsonb_array_elements(p_subtopic_ids);

    -- Iterar sobre cada universidad en el JSONB
    FOR v_university_id IN SELECT (value)::BIGINT FROM jsonb_array_elements_text(p_university_ids)
    LOOP
        -- Obtener el ID del syllabus_template_topic
        SELECT stt.id INTO v_topic_syllabus_template_id
        FROM syllabus_template_topic stt
        JOIN syllabus_template st ON stt.syllabus_template_id = st.id
            AND st.company_id = p_company_id
        WHERE st.university_id = v_university_id
            AND st.course_id = p_course_id
            AND stt.topic_id = p_topic_id
            AND st.fl_status = TRUE
            AND stt.fl_status = TRUE
            AND stt.company_id = p_company_id
        LIMIT 1;

        IF v_topic_syllabus_template_id IS NOT NULL THEN
            -- Eliminar los subtemas que no se mandaron
            UPDATE syllabus_template_topic_subtopic stts_1
            SET fl_status = FALSE, updated_at = NOW(), updated_by = p_user
            WHERE stts_1.subtopic_id NOT IN (SELECT * FROM UNNEST(v_p_subtopic_ids))
                AND stts_1.syllabus_template_topic_id = v_topic_syllabus_template_id
                AND stts_1.fl_status = TRUE
                AND stts_1.company_id = p_company_id;

            -- Obtener los subtemas existentes en el tema de la universidad
            SELECT ARRAY(
                SELECT stts.subtopic_id
                FROM syllabus_template_topic_subtopic stts
                WHERE stts.syllabus_template_topic_id = v_topic_syllabus_template_id
                    AND stts.fl_status = TRUE
                    AND stts.company_id = p_company_id
            ) INTO v_existing_subtopics_ids;

            -- Identificar los cursos nuevos que no están en la base de datos
            SELECT ARRAY(
                SELECT (value)::BIGINT FROM unnest(v_p_subtopic_ids) AS value
                EXCEPT
                SELECT unnest(v_existing_subtopics_ids)
            ) INTO v_new_subtopic_ids;

            -- Insertar los subtemas nuevos
            IF v_new_subtopic_ids IS NOT NULL THEN
                INSERT INTO syllabus_template_topic_subtopic(
                    syllabus_template_topic_id,
                    subtopic_id,
                    company_id,
                    created_by,
                    created_at
                )
                SELECT
                    v_topic_syllabus_template_id,
                    unnest(v_new_subtopic_ids),
                    p_company_id,
                    p_user,
                    NOW();
            END IF;
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION odiseo.fn_save_subtopics_template_syllabus(p_university_ids jsonb, p_course_id smallint, p_topic_id smallint, p_subtopic_ids jsonb, p_company_id integer, p_user bigint) OWNER TO postgres;

--
-- Name: fn_save_syllabus(smallint, smallint, smallint, bigint, jsonb, jsonb, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_syllabus(p_university_id smallint, p_course_id smallint, p_pseudo_course_id smallint, p_cycle_id bigint, p_syllabus_week_titles jsonb, p_syllabus jsonb, p_created_by bigint, p_company_id bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_syllabus_id BIGINT;
            v_syllabus JSONB;
            v_syllabus_week_title JSONB;
            v_syllabus_topic_id BIGINT;
            v_weeks JSONB;
            v_syllabus_topic_week_id BIGINT;
            v_subtopics JSONB;
            v_syllabus_detail_subtopic_id BIGINT;
            v_type_materials JSONB;
            v_total_type_material_amount INT;
            v_total_questions_amount INT;

        BEGIN
            INSERT INTO syllabus (university_id, course_id, pseudo_course_id, cycle_id, created_by, created_at, company_id)
            VALUES (p_university_id, p_course_id, p_pseudo_course_id, p_cycle_id, p_created_by, now(), p_company_id)
            RETURNING id INTO v_syllabus_id;

            IF p_syllabus_week_titles IS NOT NULL OR jsonb_array_length(p_syllabus_week_titles) > 0 THEN
                FOR v_syllabus_week_title IN SELECT jsonb_array_elements(p_syllabus_week_titles) LOOP
                        INSERT INTO syllabus_week_titles (syllabus_id, week, title, created_by, created_at, company_id)
                        VALUES (v_syllabus_id, (v_syllabus_week_title->>'week_id')::SMALLINT, (v_syllabus_week_title->>'title'), p_created_by, now(), p_company_id);
                END LOOP;
            END IF;


            FOR v_syllabus IN SELECT jsonb_array_elements(p_syllabus) LOOP
                INSERT INTO syllabus_topic (syllabus_id, topic_id, created_by, created_at, company_id)
                VALUES (v_syllabus_id, (v_syllabus->>'topic_id')::SMALLINT, p_created_by, now(), p_company_id)
                RETURNING id INTO v_syllabus_topic_id;

                FOR v_weeks IN SELECT jsonb_array_elements(v_syllabus->'weeks') LOOP
                    IF jsonb_typeof(v_weeks->'subtopics') = 'array' AND jsonb_array_length(v_weeks->'subtopics') > 0 THEN
                        INSERT INTO syllabus_topic_week (syllabus_topic_id, week, created_by, created_at, company_id)
                        VALUES (v_syllabus_topic_id, (v_weeks->>'week_id')::SMALLINT, p_created_by, now(), p_company_id)
                        RETURNING id INTO v_syllabus_topic_week_id;

                        FOR v_subtopics IN SELECT jsonb_array_elements(v_weeks->'subtopics') LOOP
                            INSERT INTO syllabus_detail_subtopic (syllabus_topic_week_id, subtopic_id, questions_amount, created_by, created_at, company_id)
                            VALUES (v_syllabus_topic_week_id, (v_subtopics->>'id')::SMALLINT, 0, p_created_by, now(), p_company_id)
                            RETURNING id INTO v_syllabus_detail_subtopic_id;

                            FOR v_type_materials IN SELECT jsonb_array_elements(v_subtopics->'questions_amount') LOOP
                                INSERT INTO syllabus_subtopic_type_material (syllabus_detail_subtopic_id, type_material_id, questions_amount, created_by, created_at, company_id)
                                VALUES (v_syllabus_detail_subtopic_id, (v_type_materials->>'type_material_id')::SMALLINT, (v_type_materials->>'amount')::SMALLINT, p_created_by, now(), p_company_id);
                            END LOOP;

                            SELECT COALESCE(SUM(questions_amount), 0) INTO v_total_type_material_amount
                            FROM syllabus_subtopic_type_material
                            WHERE syllabus_detail_subtopic_id = v_syllabus_detail_subtopic_id AND fl_status = true AND company_id = p_company_id;

                            UPDATE syllabus_detail_subtopic SET questions_amount = v_total_type_material_amount WHERE id = v_syllabus_detail_subtopic_id;
                        END LOOP;

                        SELECT COALESCE(SUM(questions_amount), 0) INTO v_total_questions_amount FROM syllabus_detail_subtopic WHERE syllabus_topic_week_id = v_syllabus_topic_week_id AND fl_status = true AND company_id = p_company_id;

                        UPDATE syllabus_topic_week SET total_questions_amount = v_total_questions_amount WHERE id = v_syllabus_topic_week_id AND company_id = p_company_id;
                    END IF;
                END LOOP;
            END LOOP;

            RETURN v_syllabus_id;
        END;
    $$;


ALTER FUNCTION odiseo.fn_save_syllabus(p_university_id smallint, p_course_id smallint, p_pseudo_course_id smallint, p_cycle_id bigint, p_syllabus_week_titles jsonb, p_syllabus jsonb, p_created_by bigint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_save_syllabus_texts(smallint, smallint, smallint, bigint, jsonb, jsonb, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_syllabus_texts(p_university_id smallint, p_course_id smallint, p_pseudo_course_id smallint, p_cycle_id bigint, p_syllabus jsonb, p_syllabus_week_titles jsonb, p_created_by bigint, p_company_id bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
    DECLARE
        v_syllabus_id BIGINT;
        v_week_config RECORD;
        v_text_week_id BIGINT;
        v_distribution RECORD;
        v_distribution_id BIGINT;
        v_text RECORD;
        v_text_id BIGINT;
        v_subtopic RECORD;
        v_syllabus_week_title JSONB;
    BEGIN
        -- PASO 1: CREAR EL REGISTRO PRINCIPAL EN LA TABLA SYLLABUS
        INSERT INTO syllabus (university_id, course_id, pseudo_course_id, cycle_id, created_by, created_at, company_id)
        VALUES (p_university_id, p_course_id, p_pseudo_course_id, p_cycle_id, p_created_by, now(), p_company_id)
        RETURNING id INTO v_syllabus_id;

        IF p_syllabus_week_titles IS NOT NULL OR jsonb_array_length(p_syllabus_week_titles) > 0 THEN
            FOR v_syllabus_week_title IN SELECT jsonb_array_elements(p_syllabus_week_titles) LOOP
                    INSERT INTO syllabus_week_titles (syllabus_id, week, title, created_by, created_at, company_id)
                    VALUES (v_syllabus_id, (v_syllabus_week_title->>'week_id')::SMALLINT, (v_syllabus_week_title->>'title'), p_created_by, now(), p_company_id);
            END LOOP;
        END IF;

        -- PASO 2: Recorrer el payload para insertar las configuraciones de texto,
        FOR v_week_config IN SELECT * FROM jsonb_to_recordset(p_syllabus) AS w(week INT, distributions JSONB)
        LOOP
            -- Insertar la configuración de la semana
            INSERT INTO syllabus_text_weeks(syllabus_id, week, created_by, created_at, company_id)
            VALUES (v_syllabus_id, v_week_config.week, p_created_by, now(), p_company_id)
            RETURNING id INTO v_text_week_id;

            -- Recorrer las distribuciones (materiales) de esa semana
            FOR v_distribution IN SELECT * FROM jsonb_to_recordset(v_week_config.distributions) AS d(material_id INT, texts JSONB)
            LOOP
                INSERT INTO syllabus_text_distributions(syllabus_text_week_id, type_material_id, created_by, created_at, company_id)
                VALUES (v_text_week_id, v_distribution.material_id, p_created_by, now(), p_company_id)
                RETURNING id INTO v_distribution_id;

                -- Recorrer los textos (instancias) de esa distribución
                FOR v_text IN SELECT * FROM jsonb_to_recordset(v_distribution.texts) AS t(category_id INT, subcategory_id INT, position INT, style_type VARCHAR,quantity INT, subtopics JSONB)
                LOOP
                    INSERT INTO syllabus_texts(syllabus_text_distribution_id, type_text_id, type_text_subcategory_id, "position", created_by, created_at, company_id)
                    VALUES (v_distribution_id, v_text.category_id, v_text.subcategory_id, v_text.position, p_created_by, now(), p_company_id)
                    RETURNING id INTO v_text_id;

                    IF v_text.quantity IS NOT NULL 
                        AND v_text.style_type IS NOT NULL 
                        AND TRIM(v_text.style_type) <> '' THEN

                        INSERT INTO syllabus_text_detail(
                            syllabus_text_id,
                            quantity,
                            style_type,
                            created_at,
                            created_by
                        )
                        VALUES (
                            v_text_id,
                            v_text.quantity,
                            v_text.style_type,
                            now(),
                            p_created_by
                        );

                    END IF;

                    -- Recorrer el contenido (subtemas) de ese texto
                    FOR v_subtopic IN SELECT * FROM jsonb_to_recordset(v_text.subtopics) AS s(subtopic_id INT, quantity INT)
                    LOOP
                        INSERT INTO syllabus_text_content(syllabus_text_id, subtopic_id, quantity, created_by, created_at, company_id)
                        VALUES (v_text_id, v_subtopic.subtopic_id, v_subtopic.quantity, p_created_by, now(), p_company_id);
                    END LOOP;
                END LOOP;
            END LOOP;
        END LOOP;

        RETURN v_syllabus_id;
    END;
$$;


ALTER FUNCTION odiseo.fn_save_syllabus_texts(p_university_id smallint, p_course_id smallint, p_pseudo_course_id smallint, p_cycle_id bigint, p_syllabus jsonb, p_syllabus_week_titles jsonb, p_created_by bigint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_save_text_material_ballot(smallint, bigint, smallint, smallint, smallint, smallint, smallint, bigint, smallint, bigint, bigint, bigint, json); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_text_material_ballot(p_week smallint, p_parent_question_id bigint, p_category_id smallint, p_subcategory_id smallint, p_course_id smallint, p_level_id smallint, p_position smallint, p_week_type_material_id bigint, p_type_material_id smallint, p_material_id bigint, p_material_distribution_id bigint, p_created_by bigint, p_subquestion json) RETURNS TABLE(id bigint, material_id bigint, week smallint, type_material_id smallint, week_type_material_id bigint, course_id smallint, code_course character varying, course character varying, "position" smallint, position_initial smallint, subtopic_id bigint, code_subtopic character varying, subtopic character varying, topic_id smallint, code_topic character varying, topic character varying, level_id bigint, level_description character varying, level_name character varying, usage_level_id bigint, question_id bigint, type character varying, usage_status boolean)
    LANGUAGE plpgsql
    AS $$
                DECLARE
                v_cycle_id BIGINT;
                v_cycle_start_date DATE;
                v_university_id SMALLINT;
                v_headquarters_id BIGINT;
                v_question_history_id BIGINT;
                v_ballot_question_id BIGINT;
                BEGIN
                -- Obtener ciclo y universidad del material
                SELECT
                    m.cycle_id, c.start_date, m.university_id, m.headquarte_id
                    INTO v_cycle_id, v_cycle_start_date, v_university_id, v_headquarters_id
                FROM material m
                INNER JOIN cycle c ON m.cycle_id = c.id
                WHERE m.id = p_material_id
                LIMIT 1;

                -- Traer o registrar historial
                SELECT
                    qhc.id INTO v_question_history_id
                FROM question_history_cycle qhc
                WHERE qhc.parent_question_id = p_parent_question_id
                    AND qhc.cycle_id = v_cycle_id
                    AND qhc.university_id = v_university_id
                    AND qhc.headquarters_id = v_headquarters_id
                    AND qhc.fl_status = true
                LIMIT 1;

                -- Si no hay historial se registra
                IF v_question_history_id IS NULL THEN
                    INSERT INTO question_history_cycle AS qhc (
                        parent_question_id,
                        cycle_id,
                        university_id,
                        headquarters_id,
                        created_by,
                        created_at,
                        automatic,
                        subquestion
                    )
                    VALUES (
                        p_parent_question_id,
                        v_cycle_id,
                        v_university_id,
                        v_headquarters_id,
                        p_created_by,
                        now(),
                        false,
                        p_subquestion
                    )
                    RETURNING qhc.id INTO v_question_history_id;
                END IF;

                -- Insertar o actualizar pregunta de balotario (UNIFICADO)
                IF p_material_distribution_id IS NOT NULL THEN
                    v_ballot_question_id := p_material_distribution_id;

                    UPDATE material_ballot_question mdbq
                    SET
                        type_text_id = p_category_id,
                        type_text_subcategory_id = p_subcategory_id,
                        level_id = p_level_id,
                        usage_level_id = p_level_id,
                        parent_question_id = p_parent_question_id,
                        question_history_id = v_question_history_id,
                        usage_status = FALSE,
                        added_in_completion = TRUE,
                        fl_is_manual = TRUE,
                        state = 'MANUAL_COMPLETED',
                        updated_by = p_created_by,
                        updated_at = NOW()
                    WHERE mdbq.id = p_material_distribution_id;
                ELSE
                    INSERT INTO material_ballot_question (
                        week_type_material_id,
                        material_id,
                        week,
                        type_material_id,
                        course_id,
                        type_text_id,
                        type_text_subcategory_id,
                        level_id,
                        parent_question_id,
                        question_history_id,
                        "position",
                        fl_is_manual,
                        created_by,
                        created_at,
                        state,
                        fl_status
                    )
                    VALUES (
                        p_week_type_material_id,
                        p_material_id,
                        p_week,
                        p_type_material_id,
                        p_course_id,
                        p_category_id,
                        p_subcategory_id,
                        p_level_id,
                        p_parent_question_id,
                        v_question_history_id,
                        p_position,
                        TRUE,
                        p_created_by,
                        NOW(),
                        'MANUAL_COMPLETED',
                        TRUE
                    )
                    RETURNING id INTO v_ballot_question_id;
                END IF;

                -- Desactivar subpreguntas anteriores
                UPDATE material_ballot_subquestions
                SET fl_status = FALSE, deleted_at = NOW(), deleted_by = p_created_by
                WHERE material_ballot_question_id = v_ballot_question_id AND fl_status = TRUE;

                -- Insertar nuevas subpreguntas (incluye faltantes con question_id NULL)
                INSERT INTO material_ballot_subquestions (material_ballot_question_id, question_id, position, state, topic_id, course_id, subtopic_id, fl_is_manual, added_in_completion, created_by, created_at)
                SELECT 
                    v_ballot_question_id,
                    (sub.obj->>'question_id')::bigint,
                    sub.ord::int,
                    CASE WHEN (sub.obj->>'question_id') IS NOT NULL THEN 'MANUAL_COMPLETED' ELSE 'MISSING' END,
                    (sub.obj->>'topic_id')::smallint,
                    (sub.obj->>'course_id')::smallint,
                    (sub.obj->>'subtopic_id')::smallint,
                    TRUE,
                    TRUE,
                    p_created_by,
                    NOW()
                FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_subquestion::jsonb) = 'array' THEN p_subquestion::jsonb ELSE '[]'::jsonb END) WITH ORDINALITY AS sub(obj, ord);

                -- Actualizar distribución
                UPDATE detail_week_type_mat dwtmupd
                SET
                    url_solution = null,
                    url_without_solution = null,
                    fl_process_status = 1,
                    fl_process_status_without = 1,
                    url_zip_class_mat = null,
                    fl_process_class_mat = 1,
                    fl_process_quality = 1,
                    url_quality = null,
                    fl_process_without_quality = 1,
                    url_without_quality = null,
                    updated_by = p_created_by,
                    updated_at = now()
                WHERE dwtmupd.id = (SELECT dwtmupdcp.id FROM detail_week_type_mat dwtmupdcp WHERE dwtmupdcp.material_id = p_material_id
                    AND dwtmupdcp.week = p_week AND dwtmupdcp.type_material_id = p_type_material_id);

                RETURN QUERY
                SELECT
                    fmdbq.id,
                    fmdbq.material_id,
                    fmdbq.week,
                    fmdbq.type_material_id,
                    fmdbq.week_type_material_id,
                    fmdbq.course_id,
                    fmdbq.code_course,
                    fmdbq.course,
                    fmdbq.position,
                    fmdbq.position_initial,
                    fmdbq.subtopic_id::bigint,
                    fmdbq.code_subtopic,
                    fmdbq.subtopic,
                    fmdbq.topic_id,
                    fmdbq.code_topic,
                    fmdbq.topic,
                    fmdbq.level_id,
                    fmdbq.level_description,
                    fmdbq.level_name,
                    fmdbq.usage_level_id,
                    fmdbq.question_id,
                    fmdbq.type,
                    fmdbq.usage_status
                FROM
                    fn_material_ballot_question(p_material_id, p_week, p_type_material_id, p_week_type_material_id) AS fmdbq;

                END;
            $$;


ALTER FUNCTION odiseo.fn_save_text_material_ballot(p_week smallint, p_parent_question_id bigint, p_category_id smallint, p_subcategory_id smallint, p_course_id smallint, p_level_id smallint, p_position smallint, p_week_type_material_id bigint, p_type_material_id smallint, p_material_id bigint, p_material_distribution_id bigint, p_created_by bigint, p_subquestion json) OWNER TO postgres;

--
-- Name: fn_save_text_material_exam(bigint, bigint, bigint, bigint, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_text_material_exam(p_material_id bigint, p_parent_question_id bigint, p_level_id bigint, p_material_exam_parent_question_id bigint, p_subquestions jsonb, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
    BEGIN
        /*
            Creación de función en base de datos
            Función para agregar textos en examen de un area dada

        ---------------------------------------------------------------------
        ------------------------ HISTORIAL DE CAMBIOS------------------------
        ---------------------------------------------------------------------

            Versión: 1.2
            Fecha: 2025-11-04
            Autor: Anderson Vallejo
            Descripción:
                Se guarda la pregunta en base al nuevo historico
                
        */
        UPDATE material_exam_parent_question
            SET
                parent_question_id = p_parent_question_id,
                current_level = p_level_id,
                subquestion = p_subquestions,
                updated_by = p_updated_by,
                updated_at = NOW()
        WHERE id = p_material_exam_parent_question_id;

        EXECUTE 'REFRESH MATERIALIZED VIEW odiseo.vm_material_exam_parent_question_with_subquestions';

        WITH current_exam_area_week AS (
            SELECT
                material_exam_area_week_id
            FROM material_exam_parent_question
            WHERE id = p_material_exam_parent_question_id
            LIMIT 1
        )
        INSERT INTO question_history_usage_exam_parent_question( material_exam_area_week_id, course_id, parent_question_id, question_id, automatic, created_at, created_by )
        SELECT material_exam_area_week_id, course_id, parent_question_id, question_id, FALSE, NOW(), p_updated_by
          FROM vm_material_exam_parent_question_with_subquestions
        WHERE 1 = 1
          AND material_exam_area_week_id IN ( SELECT material_exam_area_week_id FROM current_exam_area_week )
          AND parent_question_id = p_parent_question_id;
    END;
$$;


ALTER FUNCTION odiseo.fn_save_text_material_exam(p_material_id bigint, p_parent_question_id bigint, p_level_id bigint, p_material_exam_parent_question_id bigint, p_subquestions jsonb, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_save_topics_template_syllabus(jsonb, smallint, jsonb, integer, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_topics_template_syllabus(p_university_ids jsonb, p_course_id smallint, p_topic_ids jsonb, p_company_id integer, p_user bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_p_topic_ids SMALLINT[];
    v_university_id BIGINT;
    v_syllabus_template_id BIGINT;
    v_existing_topics_ids BIGINT[];
    v_not_exist_topics_ids BIGINT[];
    v_new_topic_ids BIGINT[];
BEGIN
    /*
        ------------------------------------------------------------------------------------
        -- HISTORIAL DE CAMBIOS
        ------------------------------------------------------------------------------------

        Versión: 1.1
        Fecha: 2025-11-17
        Autor: Junior Alcarraz
        Descripción:
            Se agrega el campo de id de compañia al registrar temas al syllabus template
    */

    -- Se guarda en una variable los IDs de los temas mandados
    SELECT array_agg(value::BIGINT) INTO v_p_topic_ids
    FROM jsonb_array_elements(p_topic_ids);

    -- Iterar sobre cada universidad en el JSONB
    FOR v_university_id IN SELECT (value)::BIGINT FROM jsonb_array_elements_text(p_university_ids)
    LOOP
        -- Obtener el ID del syllabus asociado a la universidad y curso
        SELECT st.id INTO v_syllabus_template_id
        FROM syllabus_template st
        WHERE st.university_id = v_university_id
            AND st.course_id = p_course_id
            AND st.fl_status IS TRUE
            AND st.company_id = p_company_id
        LIMIT 1;

        -- Verificar si el syllabus existe
        IF v_syllabus_template_id IS NOT NULL THEN
            -- Eliminar los temas que no se mandaron
            UPDATE syllabus_template_topic stt_1
            SET fl_status = FALSE, updated_at = NOW(), updated_by = p_user
            WHERE stt_1.topic_id NOT IN (SELECT * FROM UNNEST(v_p_topic_ids))
                AND stt_1.syllabus_template_id = v_syllabus_template_id
                AND stt_1.fl_status IS TRUE
                AND stt_1.company_id = p_company_id;

            -- Obtener los temas existentes en la universidad
            SELECT ARRAY(
                SELECT stt.topic_id
                FROM syllabus_template_topic stt
                WHERE stt.syllabus_template_id = v_syllabus_template_id
                    AND stt.fl_status IS TRUE
                    AND stt.company_id = p_company_id
            ) INTO v_existing_topics_ids;

            -- Identificar los cursos nuevos que no están en la base de datos
            SELECT ARRAY(
                SELECT (value)::BIGINT FROM unnest(v_p_topic_ids) AS value
                EXCEPT
                SELECT unnest(v_existing_topics_ids)
            ) INTO v_new_topic_ids;

            -- Insertar los temas nuevos
            IF v_new_topic_ids IS NOT NULL THEN
                INSERT INTO syllabus_template_topic(
                    syllabus_template_id,
                    topic_id,
                    company_id,
                    created_by,
                    created_at
                )
                SELECT
                    v_syllabus_template_id,
                    unnest(v_new_topic_ids),
                    p_company_id,
                    p_user,
                    NOW();
            END IF;
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION odiseo.fn_save_topics_template_syllabus(p_university_ids jsonb, p_course_id smallint, p_topic_ids jsonb, p_company_id integer, p_user bigint) OWNER TO postgres;

--
-- Name: fn_save_type_material_template(bigint, character varying, jsonb, boolean, bigint, bigint, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_save_type_material_template(p_id bigint, p_name character varying, p_children_template_ids jsonb, p_fl_exam boolean, p_user_id bigint, p_type_exam_id bigint, p_settings jsonb) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_new_type_material_template_id bigint;
    v_type_material_template_child_id bigint;
BEGIN
    IF p_id IS NOT NULL THEN
        RETURN json_build_object('status', 409, 'message', 'No se puede actualizar una plantilla con la función de registro');
    END IF;

    p_settings := NULLIF(p_settings, '{}'::jsonb);

    IF TRIM(UPPER(p_name)) IN (
        SELECT
            TRIM(UPPER(name))
        FROM
            type_material_template
        WHERE
            fl_status = TRUE) THEN
        RETURN json_build_object('status', 409, 'message', 'No se puede crear esta plantilla porque ya existe una plantilla con el mismo nombre');
    END IF;
    -- Insertar nueva plantilla
    INSERT INTO type_material_template(name, fl_exam, created_at, created_by, type_exam_id)
        VALUES (p_name, p_fl_exam, NOW(), p_user_id, p_type_exam_id)
    RETURNING
        id INTO v_new_type_material_template_id;

    -- Si hay hijos, insertarlos
    IF p_children_template_ids IS NOT NULL THEN
        FOR v_type_material_template_child_id IN
        SELECT
            value::bigint
        FROM
            jsonb_array_elements_text(p_children_template_ids)
            LOOP
                -- Validar que los hijos de template no tengan sus propios hijos
                IF EXISTS (
                    SELECT
                        1
                    FROM
                        type_material_bound tmb
                    WHERE
                        tmb.type_material_template_id = v_type_material_template_child_id
                        AND tmb.fl_status = TRUE) THEN
                RETURN json_build_object('status', 409, 'message', 'No se puede asociar hijos que ya tienen sus propios hijos');
            END IF;
        -- Insertar relación
        INSERT INTO type_material_bound(type_material_template_id, type_material_template_extra_id, fl_status, created_by, created_at)
            VALUES (v_new_type_material_template_id, v_type_material_template_child_id, TRUE, p_user_id, NOW());
    END LOOP;
END IF;

    PERFORM fn_sync_type_material_template_configuration_columns(
        v_new_type_material_template_id,
        p_user_id,
        p_settings
    );

    RETURN json_build_object('status', 200, 'message', 'Se creó la plantilla exitosamente');
END;
$$;


ALTER FUNCTION odiseo.fn_save_type_material_template(p_id bigint, p_name character varying, p_children_template_ids jsonb, p_fl_exam boolean, p_user_id bigint, p_type_exam_id bigint, p_settings jsonb) OWNER TO postgres;

