--
-- Name: fn_search_configuration_alternative(integer, integer, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_search_configuration_alternative(p_perpage integer, p_npage integer, p_search character varying) RETURNS TABLE(id bigint, name character varying, columns smallint, styles text, fl_image boolean, fl_default boolean, fl_status boolean, created_by bigint, updated_by bigint, deleted_by bigint, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone, total integer)
    LANGUAGE plpgsql
    AS $$
                DECLARE
                    total_count INTEGER;
                    offset_val INTEGER;
                BEGIN
                    offset_val := p_perpage * (p_npage - 1);

                    SELECT COUNT(*)
                    INTO total_count
                    FROM odiseo.configuration_alternative altern
                    WHERE altern.fl_status = true
                    AND (p_search IS NULL OR (LOWER(altern.name) LIKE '%' || LOWER(p_search) || '%'));

                    RETURN QUERY
                    SELECT
                        altern.id,
                        altern.name,
                        altern.columns,
                        altern.styles,
                        altern.fl_image,
                        altern.fl_default,
                        altern.fl_status,
                        altern.created_by,
                        altern.updated_by,
                        altern.deleted_by,
                        altern.created_at,
                        altern.updated_at,
                        altern.deleted_at,
                        total_count AS total
                    FROM odiseo.configuration_alternative altern
                    WHERE altern.fl_status = true
                    AND (p_search IS NULL OR (LOWER(altern.name) LIKE '%' || LOWER(p_search) || '%'))
                    ORDER BY altern.created_at DESC
                    LIMIT p_perpage
                    OFFSET offset_val;
                END;
            $$;


ALTER FUNCTION odiseo.fn_search_configuration_alternative(p_perpage integer, p_npage integer, p_search character varying) OWNER TO postgres;

--
-- Name: fn_search_configuration_diagrammed_course(character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_search_configuration_diagrammed_course(p_text character varying) RETURNS TABLE(course_id bigint, name_course character varying, category_text_id bigint, category_text character varying)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                    RETURN QUERY

                    WITH course_configurations AS (
                    SELECT
                        sdc.course_id,
                        c."name" name_course,
                        null category_text_id,
                        null category_text
                    FROM setting_diagrammed_courses sdc
                    JOIN course c ON c.id = sdc.course_id
                    WHERE sdc.category_text_id IS NULL
                    AND sdc.fl_status = TRUE
                    GROUP BY sdc.course_id, c.name
                    UNION ALL
                    SELECT 
                        sdc.course_id,
                        c."name" name_course,
                        tt.id category_text_id,
                        tt."name" category_text
                    FROM setting_diagrammed_courses sdc
                    JOIN course c ON c.id = sdc.course_id
                    JOIN type_text tt ON tt.id = sdc.category_text_id
                    WHERE sdc.fl_status = TRUE
                    GROUP BY sdc.course_id, c.name, tt."name", tt.id
                    ORDER BY course_id
                    )
                    SELECT * FROM course_configurations cc WHERE (
                        p_text IS NULL OR
                        UNACCENT(cc.name_course) ILIKE '%' || UNACCENT(p_text) || '%'
                    );

                    END;
                    $$;


ALTER FUNCTION odiseo.fn_search_configuration_diagrammed_course(p_text character varying) OWNER TO postgres;

--
-- Name: fn_search_course(integer, integer, character varying, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_search_course(p_perpage integer, p_npage integer, p_text character varying, p_area_id integer) RETURNS TABLE(id smallint, code character varying, name text, area_id bigint, area_code character varying, area character varying, fl_status boolean, total_setting_diagrammed_course bigint, created_by character varying, created_at timestamp without time zone, updated_by character varying, updated_at timestamp without time zone, total bigint, children jsonb, type_text_template_id smallint, type_text_template_name character varying)
    LANGUAGE plpgsql
    AS $$
                        DECLARE
                            offset_val INTEGER;
                        BEGIN
                            -- Calcular el offset para la paginación
                            offset_val := p_perpage * (p_npage - 1);

                            RETURN QUERY
                            WITH tbl_courses AS (
                                -- Listado de cursos principales
                                SELECT
                                    c.id AS id,
                                    c.code AS code,
                                    UPPER(c.name) AS name,
                                    c.area_id AS area_id,
                                    a.code AS area_code,
                                    a.description AS area,
                                    c.fl_status AS fl_status,
                                    (
                                        SELECT COUNT(*)
                                        FROM setting_diagrammed_courses sdc
                                        WHERE sdc.course_id = c.id AND sdc.fl_status = TRUE
                                    ) AS total_setting_diagrammed_course,
                                    u.user AS created_by,
                                    c.created_at AS created_at,
                                    u2.user AS updated_by,
                                    c.updated_at AS updated_at,
                                    COALESCE(
                                        (SELECT jsonb_agg(jsonb_build_object(
                                            'id', ch.id,
                                            'code', ch.code,
                                            'name', ch.name,
                                            'area_id', ch.area_id
                                        ))
                                        FROM course_pseudo_courses cpc
                                        INNER JOIN course ch ON ch.id = cpc.course_id
                                        WHERE cpc.pseudo_course_id = c.id
                                        AND cpc.fl_status = TRUE
                                        AND ch.fl_status = TRUE),
                                        '[]'::jsonb
                                    ) AS children,
                                    ttt.id type_text_template_id,
                                    ttt.name type_text_template_name
                                FROM course c
                                LEFT JOIN users u ON c.created_by = u.id
                                LEFT JOIN users u2 ON c.updated_by = u2.id
                                LEFT JOIN area a ON c.area_id = a.id
                                LEFT JOIN type_text_templates ttt ON ttt.id = c.type_text_template_id
                                WHERE
                                    c.deleted_at IS NULL
                                    AND (p_text IS NULL
                                        OR LOWER(c.name) LIKE '%' || LOWER(p_text) || '%'
                                        OR LOWER(c.code) LIKE '%' || LOWER(p_text) || '%')
                                    AND (p_area_id IS NULL OR c.area_id = p_area_id)
                                AND c.fl_status  IS TRUE
                                ORDER BY c.id ASC
                            ), tbl_courses_with_total AS (
                                -- Agregar el total de registros
                                SELECT
                                    *,
                                    COUNT(*) OVER () AS total
                                FROM tbl_courses
                            )
                            -- Aplicar paginación
                            SELECT
                                tbl.id,
                                tbl.code,
                                tbl.name,
                                tbl.area_id,
                                tbl.area_code,
                                tbl.area,
                                tbl.fl_status,
                                tbl.total_setting_diagrammed_course,
                                tbl.created_by,
                                tbl.created_at,
                                tbl.updated_by,
                                tbl.updated_at,
                                tbl.total,
                                tbl.children,
                                tbl.type_text_template_id,
                                tbl.type_text_template_name
                            FROM tbl_courses_with_total tbl
                            LIMIT p_perpage
                            OFFSET offset_val;
                        END;
                        $$;


ALTER FUNCTION odiseo.fn_search_course(p_perpage integer, p_npage integer, p_text character varying, p_area_id integer) OWNER TO postgres;

--
-- Name: fn_search_cycle(integer, integer, character varying, boolean, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_search_cycle(p_perpage integer, p_npage integer, p_name_text character varying, p_active boolean, p_company_id integer) RETURNS TABLE(id bigint, code character varying, description character varying, month smallint, year smallint, weeks smallint, start_date date, end_date date, active boolean, cycle_template_id bigint, cycle_type_id bigint, cycle_type character varying, created_by text, created_at timestamp without time zone, total_count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    offset_val INTEGER;
BEGIN
    /*
        ------------------------------------------------------------------------------------
        -- HISTORIAL DE CAMBIOS
        ------------------------------------------------------------------------------------

        Versión: 1.0
        Fecha: 2025-11-14
        Autor: Junior Alcarraz
        Descripción:
            Se filtra por el id de la compañia del usuario logueado
    */

    -- Calcular el offset para la paginación
    offset_val := p_perpage * (p_npage - 1);

    RETURN QUERY
    WITH tbl_cycle as (
        SELECT
            c.id,
            c.code,
            c.description,
            c.month,
            c.year,
            c.weeks,
            c.start_date,
            c.end_date,
            c.active,
            c.cycle_template_id,
            c.cycle_type_id,
            ct.name AS cycle_type,
            CASE
                WHEN e.first_name IS NOT NULL AND e.first_surname IS NOT NULL THEN
                    CONCAT(initcap(split_part(e.first_name, ' ', 1)), ' ',
                        upper(left(e.first_surname, 1)), '. ',
                        initcap(e.second_surname))
                ELSE
                    NULL
            END AS created_by,
            c.created_at
        FROM "cycle" c
        LEFT JOIN cycle_types ct ON c.cycle_type_id = ct.id
        LEFT JOIN users u ON c.created_by = u.id
        LEFT JOIN employees e ON u.id = e.user_id
        WHERE c.fl_status = true and c.deleted_at is null
            AND (
                p_name_text IS NULL
                OR c.description ILIKE '%' || p_name_text || '%'
                OR c.code ILIKE '%' || p_name_text || '%'
            )
            AND (p_active IS NULL OR c.active = p_active)
            AND c.company_id = p_company_id
    ), counted_cycles AS (
        SELECT *, COUNT(*) OVER () AS total_count
        FROM tbl_cycle
    )
    SELECT *
    FROM counted_cycles
    ORDER BY created_at DESC
    LIMIT p_perpage
    OFFSET offset_val;
END;
$$;


ALTER FUNCTION odiseo.fn_search_cycle(p_perpage integer, p_npage integer, p_name_text character varying, p_active boolean, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_search_exam_area(integer, integer, character varying, integer, boolean, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_search_exam_area(p_perpage integer, p_npage integer, p_name_text character varying, f_cycle_id integer, f_cycle_active boolean, f_type_material_id integer, p_company_id integer) RETURNS TABLE(id smallint, cycle_id bigint, cycle character varying, type_material_id smallint, type_material character varying, created_at timestamp without time zone, created_by text, is_exam_material_configured boolean, total_count bigint)
    LANGUAGE plpgsql
    AS $$
    DECLARE
        offset_val INTEGER;
    BEGIN
        -- Calcula el offset para la paginación
        offset_val := p_perpage * (p_npage - 1);

        RETURN QUERY
        WITH tbl_exam_material_configurations AS (
            SELECT emc.id , c.id as cycle_id, c.description as cycle, tm.id as type_material_id, tm.description as type_material,
            tm.created_at,
            CASE
                WHEN e.first_name IS NOT NULL AND e.first_surname IS NOT NULL THEN
                    CONCAT(
                        initcap(split_part(e.first_name, ' ', 1)), ' ',
                        upper(left(e.first_surname, 1)), '. ',
                        initcap(e.second_surname)
                    )
                ELSE
                    NULL
            END AS created_by,
            CASE
                WHEN (
                    SELECT COUNT(*)
                    FROM course c2
                    WHERE c2.fl_status = true AND c2.deleted_at is NULL
                ) = (
                    SELECT count(*)
                    FROM exam_material_config_area_courses emcac2
                    LEFT JOIN exam_material_configurations emc2
                    on emcac2.exam_material_config_id = emc2.id
                    WHERE emc2.id = emc.id
                ) THEN TRUE
                ELSE FALSE
            END AS is_exam_material_configured
            FROM exam_material_configurations emc
            LEFT JOIN cycle c
            on emc.cycle_id = c.id
            LEFT JOIN type_material tm
            on emc.type_material_id = tm.id
            LEFT JOIN users u on emc.created_by = u.id
            LEFT JOIN employees e ON e.user_id = u.id
            WHERE emc.fl_status = true
            AND emc.company_id = p_company_id
            AND emc.deleted_at is NULL
            AND (
                p_name_text IS NULL
                OR LOWER(c.description) LIKE '%' || LOWER(p_name_text) || '%'
                OR LOWER(tm.description) LIKE '%' || LOWER(p_name_text) || '%'
            )
            AND (f_type_material_id IS NULL OR tm.id = f_type_material_id)
            AND (f_cycle_id IS NULL OR c.id = f_cycle_id)
            AND (f_cycle_active IS NULL OR c.active = f_cycle_active)
        )
        SELECT *, count(*) OVER () AS total_count
        FROM tbl_exam_material_configurations
        ORDER BY created_at DESC, type_material ASC
        LIMIT p_perpage
        OFFSET offset_val;
    END;
    $$;


ALTER FUNCTION odiseo.fn_search_exam_area(p_perpage integer, p_npage integer, p_name_text character varying, f_cycle_id integer, f_cycle_active boolean, f_type_material_id integer, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_search_field_diagrammed(integer, integer, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_search_field_diagrammed(p_perpage integer, p_npage integer, p_name_text character varying) RETURNS TABLE(id bigint, name character varying, created_by bigint, created_at timestamp without time zone, total_count bigint)
    LANGUAGE plpgsql
    AS $$
            DECLARE
                offset_val INTEGER;
            BEGIN
                -- Calculate the offset
                offset_val := p_perpage * (p_npage - 1);

                RETURN QUERY
                WITH tbl_field_diagrammed AS (
                    SELECT
                    fd.id,
                    fd.name,
                    fd.created_by,
                    fd.created_at
                    from odiseo.field_diagrammed fd
                    WHERE fd.fl_status = TRUE
                    AND fd.deleted_at IS NULL
                    AND (p_name_text IS NULL
                        OR unaccent(LOWER(fd.name)) LIKE '%' || unaccent(LOWER(p_name_text)) || '%'
                    )
                )
                SELECT *, count(*) OVER () AS total_count
                FROM tbl_field_diagrammed
                ORDER BY name ASC, id ASC, created_at DESC
                LIMIT p_perpage
                OFFSET offset_val;
            END;
            $$;


ALTER FUNCTION odiseo.fn_search_field_diagrammed(p_perpage integer, p_npage integer, p_name_text character varying) OWNER TO postgres;

--
-- Name: fn_search_image_gallery(integer, integer, character varying, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_search_image_gallery(p_perpage integer, p_npage integer, p_name_text character varying, f_course_id integer, f_topic_id integer) RETURNS TABLE(id bigint, name character varying, image character varying, width integer, height integer, path_short_version character varying, path_full_version character varying, created_by bigint, created_at timestamp without time zone, topics jsonb, total_count bigint)
    LANGUAGE plpgsql
    AS $$
            DECLARE
                offset_val INTEGER;
            BEGIN
                -- Calculate the offset
                offset_val := p_perpage * (p_npage - 1);

                RETURN QUERY
                WITH filtered_image_gallery AS (
                    SELECT
                        ig.id,
                        ig.name,
                        ig.image,
                        ig.width,
                        ig.height,
                        ig.path_short_version,
                        ig.path_full_version,
                        ig.created_by,
                        ig.created_at,
                        (
                            SELECT jsonb_agg(
                                json_build_object(
                                    'topic_id', t.id,
                                    'topic', t.name,
                                    'course_id', c.id,
                                    'course', c.name
                                )
                            )
                            FROM odiseo.image_galery_topic igt
                            LEFT JOIN odiseo.topic t ON igt.topic_id = t.id
                            LEFT JOIN odiseo.course c ON t.course_id = c.id
                            WHERE igt.image_gallery_id = ig.id
                            AND igt.fl_status = TRUE
                            AND (f_course_id IS NULL OR c.id = f_course_id)
                            AND (f_topic_id IS NULL OR t.id = f_topic_id)
                        ) AS topics
                    FROM odiseo.image_gallery ig
                    WHERE ig.fl_status = TRUE
                    AND ig.deleted_at IS NULL
                    AND (p_name_text IS NULL
                        OR LOWER(ig.name) LIKE '%' || LOWER(p_name_text) || '%'
                    )
                    AND EXISTS (
                        SELECT 1
                        FROM odiseo.image_galery_topic igt
                        LEFT JOIN odiseo.topic t ON igt.topic_id = t.id
                        LEFT JOIN odiseo.course c ON t.course_id = c.id
                        WHERE igt.image_gallery_id = ig.id
                            AND igt.fl_status = TRUE
                            AND (f_course_id IS NULL OR c.id = f_course_id)
                            AND (f_topic_id IS NULL OR t.id = f_topic_id)
                    )
                )
                SELECT *, count(*) OVER () AS total_count
                FROM filtered_image_gallery
                ORDER BY created_at DESC, id ASC
                LIMIT p_perpage
                OFFSET offset_val;
            END;
            $$;


ALTER FUNCTION odiseo.fn_search_image_gallery(p_perpage integer, p_npage integer, p_name_text character varying, f_course_id integer, f_topic_id integer) OWNER TO postgres;

--
-- Name: fn_search_level_syllabus(integer, integer, character varying, bigint, integer, integer, integer, boolean, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_search_level_syllabus(p_perpage integer, p_npage integer, p_name_text character varying, p_employee_id bigint, p_course_id integer, p_university_id integer, p_cycle_id integer, p_cycle_active boolean, p_headquarter_id integer, p_company_id integer) RETURNS TABLE(id bigint, university_id smallint, university character varying, headquarter_id smallint, headquarter character varying, cycle_id bigint, cycle character varying, course_id smallint, course character varying, created_at timestamp without time zone, created_by text, is_weeks_configured boolean, total_count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_offset_val INTEGER := p_perpage * (p_npage - 1);
BEGIN
    RETURN QUERY
    WITH filtered_level_syllabus AS (
        SELECT
            ls.id,
            ou.id AS university_id,
            ou."name" AS university,
            h.id AS headquarter_id,
            h.name AS headquarter,
            c2.id AS cycle_id,
            c2.description AS cycle,
            c.id AS course_id,
            c.name AS course,
            ls.created_at,
            CASE
                WHEN e.first_name IS NOT NULL AND e.first_surname IS NOT NULL THEN
                    CONCAT(
                        initcap(split_part(e.first_name, ' ', 1)), ' ',
                        upper(left(e.first_surname, 1)), '. ',
                        initcap(e.second_surname)
                    )
                ELSE NULL
            END AS created_by
        FROM level_syllabus ls
        LEFT JOIN course c ON ls.course_id = c.id
        LEFT JOIN origin_university ou ON ls.university_id = ou.id
        LEFT JOIN headquarters h ON ls.headquarter_id = h.id
        INNER JOIN "cycle" c2 ON ls.cycle_id = c2.id
        LEFT JOIN users u ON ls.created_by = u.id
        LEFT JOIN employees e ON e.user_id = u.id
        WHERE ls.fl_status = true
          AND ls.deleted_at IS NULL
          AND (p_company_id IS NULL OR ls.company_id = p_company_id)
          AND (p_employee_id IS NULL OR e.id = p_employee_id)
          AND (p_course_id IS NULL OR c.id = p_course_id)
          AND (p_university_id IS NULL OR ou.id = p_university_id)
          AND (p_cycle_id IS NULL OR c2.id = p_cycle_id)
          AND (p_cycle_active IS NULL OR c2.active = p_cycle_active)
          AND (p_headquarter_id IS NULL OR h.id = p_headquarter_id)
          AND (
              p_name_text IS NULL
              OR c2.description ILIKE '%' || p_name_text || '%'
              OR ou."name" ILIKE '%' || p_name_text || '%'
              OR h.name ILIKE '%' || p_name_text || '%'
          )
    ),
    paginated_results AS (
        SELECT *, count(*) OVER () AS total_count_window
        FROM filtered_level_syllabus
        ORDER BY created_at DESC, university_id ASC
        LIMIT p_perpage
        OFFSET v_offset_val
    )
    SELECT 
        pr.id,
        pr.university_id,
        pr.university,
        pr.headquarter_id,
        pr.headquarter,
        pr.cycle_id,
        pr.cycle,
        pr.course_id,
        pr.course,
        pr.created_at,
        pr.created_by,
        -- El resultado del JOIN LATERAL
        chk.is_configured AS is_weeks_configured,
        pr.total_count_window AS total_count
    FROM paginated_results pr
    CROSS JOIN LATERAL (
        SELECT NOT EXISTS (
            WITH expected_raw AS (
                SELECT 
                    tmdt.week,
                    tm.id AS material_type_id,
                    SUM(CASE WHEN tmc.is_generic = true THEN tmc.amount_question ELSE COALESCE(tmdc.amount_question, 0) END) AS total_question,
                    SUM(CASE WHEN tmc.is_generic_text = true THEN tmc.amount_text ELSE COALESCE(tmdct.amount_text, 0) END) AS total_text
                FROM type_material tm
                JOIN type_material_detail_template tmdt ON tmdt.type_material_id = tm.id AND tmdt.fl_status = true AND tmdt.deleted_at IS NULL
                JOIN type_material_template tmt ON tmt.id = tm.type_material_template_id 
                JOIN type_material_course tmc ON tmc.type_material_id = tm.id
                LEFT JOIN type_material_detail_courses tmdc ON tmdc.type_material_course_id = tmc.id AND tmdc.type_material_detail_template_id = tmdt.id
                LEFT JOIN type_material_detail_course_texts tmdct ON tmdct.type_material_course_id = tmc.id AND tmdct.type_material_detail_template_id = tmdt.id
                WHERE tm.cycle_id = pr.cycle_id
                  AND tmc.course_id = pr.course_id
                  AND tm.fl_exam = false
                  AND tm.fl_status = true
                  AND (
                      tm.parent_id IS NOT NULL
                      OR tm.id NOT IN (SELECT parent_id FROM type_material tm2 WHERE tm2.cycle_id = tm.cycle_id AND parent_id IS NOT NULL)
                  )
                GROUP BY tmdt.week, tm.id
            ),
            expected AS (
                SELECT week, material_type_id, 'P' AS type, total_question AS total FROM expected_raw 
                UNION ALL
                SELECT week, material_type_id, 'T' AS type, total_text AS total FROM expected_raw 
            ),
            actual_materials AS (
                SELECT level_syllabus_weeks_id, type_material_id, 'P' AS type, COALESCE(number_questions, 0) AS total
                FROM detail_level_syllabus_weeks
                WHERE fl_status = true AND deleted_at IS NULL AND COALESCE(number_questions, 0) > 0
                UNION ALL
                SELECT level_syllabus_weeks_id, type_material_id, 'T' AS type, COALESCE(number_of_passages, 0) AS total
                FROM detail_level_syllabus_weeks_parents
                WHERE fl_status = true AND deleted_at IS NULL AND COALESCE(number_of_passages, 0) > 0
            ),
            actual AS (
                SELECT 
                    lsw.week, 
                    am.type_material_id AS material_type_id, 
                    am.type,
                    SUM(am.total) AS total
                FROM level_syllabus_weeks lsw 
                JOIN actual_materials am ON am.level_syllabus_weeks_id = lsw.id 
                WHERE lsw.level_syllabus_id = pr.id 
                  AND lsw.fl_status = true 
                GROUP BY lsw.id, lsw.week, am.type_material_id, am.type
            )
            SELECT 1
            FROM expected e
            FULL OUTER JOIN actual a 
                ON e.week = a.week 
               AND e.material_type_id = a.material_type_id
               AND e.type = a.type
            WHERE COALESCE(e.total, 0) != COALESCE(a.total, 0)
        ) AS is_configured
    ) chk;
END;
$$;


ALTER FUNCTION odiseo.fn_search_level_syllabus(p_perpage integer, p_npage integer, p_name_text character varying, p_employee_id bigint, p_course_id integer, p_university_id integer, p_cycle_id integer, p_cycle_active boolean, p_headquarter_id integer, p_company_id integer) OWNER TO postgres;

