--
-- Name: fn_search_similar_parent_questions(text, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_search_similar_parent_questions(p_search text, p_course_id bigint) RETURNS TABLE(id bigint, short_description text, score real, code character varying)
    LANGUAGE plpgsql
    AS $$
                    DECLARE
                        v_umbral_final FLOAT;
                    BEGIN
                        SELECT ase.similarity_percentage::float / 100.0 INTO v_umbral_final 
                        FROM advanced_settings ase 
                        WHERE ase.company_id = 1
                        LIMIT 1;

                        v_umbral_final := GREATEST(0.0, LEAST(1.0, v_umbral_final));

                        EXECUTE format('SET LOCAL pg_trgm.similarity_threshold = %L', v_umbral_final);

                        RETURN QUERY
                        SELECT 
                            pq.id,
                            pq.short_description,
                            extensions.similarity(
                                lower(fn_immutable_unaccent(pq.short_description)), 
                                lower(fn_immutable_unaccent(p_search))
                            ) AS score,
                            pq.code
                        FROM parent_question pq
                        WHERE 
                            pq.course_id = p_course_id AND
                            lower(fn_immutable_unaccent(pq.short_description)) OPERATOR(extensions.%) lower(fn_immutable_unaccent(p_search))
                        ORDER BY score DESC;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_search_similar_parent_questions(p_search text, p_course_id bigint) OWNER TO postgres;

--
-- Name: fn_search_similar_questions(text, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_search_similar_questions(p_search text, p_course_id bigint) RETURNS TABLE(id bigint, short_description text, score real, code character varying)
    LANGUAGE plpgsql
    AS $$
                                DECLARE
                                    v_umbral_final FLOAT;
                                BEGIN
                                    SELECT ase.similarity_percentage::float / 100.0 INTO v_umbral_final 
                                    FROM advanced_settings ase 
                                    WHERE ase.company_id = 1
                                    LIMIT 1;

                                    v_umbral_final := GREATEST(0.0, LEAST(1.0, v_umbral_final));

                                    EXECUTE format('SET LOCAL pg_trgm.similarity_threshold = %L', v_umbral_final);

                                    RETURN QUERY
                                    SELECT 
                                        q.id,
                                        q.short_description,
                                        extensions.similarity(
                                            lower(fn_immutable_unaccent(q.short_description)), 
                                            lower(fn_immutable_unaccent(p_search))
                                        ) AS score,
                                        q.code
                                    FROM question q
                                    WHERE
                                        q.course_id = p_course_id AND
                                        lower(fn_immutable_unaccent(q.short_description)) OPERATOR(extensions.%) lower(fn_immutable_unaccent(p_search)) AND
                                        q.parent_id IS NULL AND
                                        q.status NOT IN ('ARCH')
                                    ORDER BY score DESC;
                                END;
                                $$;


ALTER FUNCTION odiseo.fn_search_similar_questions(p_search text, p_course_id bigint) OWNER TO postgres;

--
-- Name: fn_search_similar_sub_question(text, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_search_similar_sub_question(p_search text, p_parent_question_id bigint, p_question_id bigint) RETURNS TABLE(id bigint, short_description text, score real, code character varying)
    LANGUAGE plpgsql
    AS $$
                    DECLARE
                        v_umbral_final FLOAT;
                    BEGIN
                        SELECT ase.similarity_percentage::float / 100.0 INTO v_umbral_final 
                        FROM advanced_settings ase 
                        WHERE ase.company_id = 1
                        LIMIT 1;

                        v_umbral_final := GREATEST(0.0, LEAST(1.0, v_umbral_final));

                        EXECUTE format('SET LOCAL pg_trgm.similarity_threshold = %L', v_umbral_final);

                        RETURN QUERY
                        SELECT 
                            q.id,
                            q.short_description,
                            extensions.similarity(
                                lower(fn_immutable_unaccent(q.short_description)), 
                                lower(fn_immutable_unaccent(p_search))
                            ) AS score,
                            q.code
                        FROM question q
                        WHERE
                            q.parent_id = p_parent_question_id AND
                            q.id != p_question_id AND
                            lower(fn_immutable_unaccent(q.short_description)) OPERATOR(extensions.%) lower(fn_immutable_unaccent(p_search))
                        ORDER BY score DESC;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_search_similar_sub_question(p_search text, p_parent_question_id bigint, p_question_id bigint) OWNER TO postgres;

--
-- Name: fn_search_subtopic(integer, integer, bigint, bigint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_search_subtopic(p_perpage integer, p_npage integer, f_topic_id bigint, f_course_id bigint, p_text character varying) RETURNS TABLE(id smallint, code character varying, name character varying, topic_id smallint, topic character varying, course_id smallint, code_course character varying, course character varying, fl_status boolean, total integer, created_by character varying, created_at timestamp without time zone, updated_by character varying, updated_at timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            total_count INTEGER;
            offset_val INTEGER;
        BEGIN
            -- Calculate offset value for pagination
            offset_val := p_perpage * (p_npage - 1);

            -- Calculate total count of subtopics matching the search criteria
            SELECT COUNT(*)
            INTO total_count
            FROM odiseo.subtopic s
            LEFT JOIN odiseo.topic t ON s.topic_id = t.id
            LEFT JOIN odiseo.users u ON s.created_by = u.id
            LEFT JOIN odiseo.users u2 ON s.updated_by = u2.id
            WHERE
                s.deleted_at IS NULL
                AND (f_topic_id IS NULL OR s.topic_id = f_topic_id)
                AND (f_course_id IS NULL OR t.course_id = f_course_id)
                AND (p_text IS NULL
                OR LOWER(s."name") LIKE '%' || LOWER(p_text) || '%'
                OR LOWER(s.code) LIKE '%' || LOWER(p_text) || '%');

            -- Return the paginated subtopics matching the search criteria
            RETURN QUERY
            SELECT
                s.id,
                s.code,
                s."name",
                t.id AS topic_id,
                t."name" AS topic,
				t.course_id,
				c.code AS code_course,
				c.name AS course,
                s.fl_status,
                total_count AS total,
                u."user" AS created_by,
                s.created_at,
                u2."user" AS updated_by,
                s.updated_at
            FROM odiseo.subtopic s
            LEFT JOIN odiseo.topic t ON s.topic_id = t.id
			LEFT JOIN odiseo.course c ON t.course_id = c.id
            LEFT JOIN odiseo.users u ON s.created_by = u.id
            LEFT JOIN odiseo.users u2 ON s.updated_by = u2.id
            WHERE
                s.deleted_at IS NULL
                AND (f_topic_id IS NULL OR s.topic_id = f_topic_id)
                AND (f_course_id IS NULL OR t.course_id = f_course_id)
                AND (p_text IS NULL
                OR LOWER(s."name") LIKE '%' || LOWER(p_text) || '%'
                OR LOWER(s.code) LIKE '%' || LOWER(p_text) || '%')
            ORDER BY
                  topic_id asc, s.code asc, s."name" asc
            LIMIT p_perpage
            OFFSET offset_val;
        END;
        $$;


ALTER FUNCTION odiseo.fn_search_subtopic(p_perpage integer, p_npage integer, f_topic_id bigint, f_course_id bigint, p_text character varying) OWNER TO postgres;

--
-- Name: fn_search_template_syllabus(integer, integer, character varying, integer, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_search_template_syllabus(p_perpage integer, p_npage integer, p_search character varying, p_company_id integer, p_employee_id bigint) RETURNS TABLE(university_id smallint, university character varying, slug character varying, total bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    offset_val INTEGER;
BEGIN
    /*
        ------------------------------------------------------------------------------------
        -- HISTORIAL DE CAMBIOS
        ------------------------------------------------------------------------------------

        Versión: 1.1
        Fecha: 2025-11-17
        Autor: Junior Alcarraz
        Descripción:
            Se filtra por el id de la compañia del usuario logueado
    */

    -- Calcular el offset para la paginación
    offset_val := p_perpage * (p_npage - 1);

    RETURN QUERY
    WITH tbl_template_syllabus AS (
        SELECT DISTINCT
            st.university_id AS university_id,
            ou.name AS university,
            ou.slug
        FROM syllabus_template st
        LEFT JOIN origin_university ou ON st.university_id = ou.id
        LEFT JOIN employee_university eu ON st.university_id = eu.university_id
            AND eu.fl_status IS true
        WHERE st.fl_status = TRUE
            AND (p_search IS NULL OR ou.name ILIKE '%' || p_search || '%')
            AND st.company_id = p_company_id
            AND (p_employee_id IS null OR eu.employee_id = p_employee_id)
    )
    SELECT *,  COUNT(*) OVER () AS total
    FROM  tbl_template_syllabus
    ORDER BY university ASC
    LIMIT p_perpage
    OFFSET  offset_val;
END;
$$;


ALTER FUNCTION odiseo.fn_search_template_syllabus(p_perpage integer, p_npage integer, p_search character varying, p_company_id integer, p_employee_id bigint) OWNER TO postgres;

--
-- Name: fn_search_topic(integer, integer, bigint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_search_topic(p_perpage integer, p_npage integer, f_course_id bigint, p_text character varying) RETURNS TABLE(id smallint, code character varying, name character varying, couse_id smallint, course character varying, fl_status boolean, total integer, created_by character varying, created_at timestamp without time zone, updated_by character varying, updated_at timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            total_count INTEGER;
            offset_val INTEGER;
        begin
            
            offset_val := p_perpage * (p_npage - 1);
        
            SELECT COUNT(*) 
            INTO total_count
            FROM odiseo.topic t 
            LEFT JOIN odiseo.course c ON t.course_id = c.id
            LEFT JOIN odiseo.users u ON t.created_by = u.id
            LEFT JOIN odiseo.users u2 ON t.updated_by = u2.id
            WHERE 
                t.deleted_at IS null
                AND (f_course_id IS NULL OR t.course_id = f_course_id)
                AND (p_text IS NULL 
                OR LOWER(t."name") LIKE '%' || LOWER(p_text) || '%'  
                OR LOWER(t.code) LIKE '%' || LOWER(p_text) || '%');
        
            -- Return the paginated topics matching the search criteria
            RETURN QUERY 
            SELECT 
                t.id,
                t.code,
                t."name",
                c.id AS course_id,
                c."name" AS course,
                t.fl_status,
                total_count AS total,
                u."user" AS created_by,
                t.created_at,
                u2."user" AS updated_by,
                t.updated_at
            FROM odiseo.topic t 
            LEFT JOIN odiseo.course c ON t.course_id = c.id
            LEFT JOIN odiseo.users u ON t.created_by = u.id
            LEFT JOIN odiseo.users u2 ON t.updated_by = u2.id
            WHERE 
                t.deleted_at IS null
                AND (f_course_id IS NULL OR t.course_id = f_course_id)
                AND (p_text IS NULL 
                OR LOWER(t."name") LIKE '%' || LOWER(p_text) || '%'  
                OR LOWER(t.code) LIKE '%' || LOWER(p_text) || '%')
            ORDER by  c."name" ASC, t.code ASC
            LIMIT p_perpage
            OFFSET offset_val;
        END;
        $$;


ALTER FUNCTION odiseo.fn_search_topic(p_perpage integer, p_npage integer, f_course_id bigint, p_text character varying) OWNER TO postgres;

--
-- Name: fn_search_tracking_question(integer, integer, character varying, integer, integer, integer, character varying, integer, character varying, smallint, smallint, smallint, smallint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_search_tracking_question(p_perpage integer, p_npage integer, p_name_text character varying, p_course_id integer, p_teacher_id integer, p_employee_didi_id integer, p_status character varying, p_created_by integer, p_type character varying, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_version smallint, p_year character varying) RETURNS TABLE(id bigint, key_question text, type_question text, parent_id bigint, code character varying, number_question character varying, short_description text, course_id smallint, course character varying, subtopic_id bigint, topic_id bigint, area_id bigint, area character varying, subquestions jsonb, status character varying, date_status timestamp without time zone, created_at timestamp without time zone, created_by_id bigint, created_by text, teacher_id bigint, teacher text, employee_didi_id bigint, employee_didi text, origin_question jsonb, search_text text, user_deleted_at timestamp without time zone, user_suspended boolean, shared_status text, total_count bigint)
    LANGUAGE plpgsql
    SET jit TO 'off'
    AS $$
DECLARE
    offset_val INTEGER := p_perpage * (p_npage - 1);
BEGIN
    RETURN QUERY
    with questions AS (
        SELECT
            concat('p_',q.id) as  key_question,
            q.id,
            q.code,
            q.short_description,
            q.number_question,
            q.number,
            q.course_id,
            c.code AS code_course,
            c.name AS course,
            qs.subtopic_id,
            q.topic_id,
            a.id as area_id,
            a.description as area,
            q.status,
            q.fl_status,
            q.parent_id,
            CASE
                WHEN q.parent_id IS NULL THEN 'P'
                ELSE 'S'
            END AS type_question,
            q.created_by,
            q.status_changed_at created_at,
            u.user AS user_name,
            u.email AS user_email,
            e.id as employee_id,
            CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name) AS name_employee,
            e1.id as teacher_id,
            CONCAT(e1.first_surname,' ', e1.second_surname,' ', e1.first_name) AS teacher,
            e2.id as employee_didi_id,
            CONCAT(e2.first_surname,' ', e2.second_surname,' ', e2.first_name) AS employee_didi,
            q.search_text,
            u.deleted_at as user_deleted_at,
            u.fl_suspended as user_suspended,
            get_shared_status(q.id, qs.subtopic_id) AS shared_status,
            qn.question_origin,
            qn.university_id,
            qn.option_id,
            qn.modality_id,
            qn."version",
            qn."year"
        FROM question q
        INNER JOIN course c ON q.course_id = c.id
        LEFT JOIN area a ON c.area_id = a.id
        LEFT JOIN users u ON q.created_by = u.id
        LEFT JOIN employees e on u.id = e.user_id
        LEFT JOIN employee_question eoq ON eoq.question_id = q.id AND eoq.fl_status = true
        LEFT JOIN employees e1 ON eoq.teacher_id = e1.id
        LEFT JOIN employee_didi_question oedq ON q.id = oedq.question_id AND oedq.fl_status = true
        LEFT JOIN employees e2 ON oedq.employee_id = e2.id
        LEFT JOIN question_subtopic qs ON qs.question_id = q.id
        LEFT JOIN v_all_question_origins qn ON qn.question_id = q.id
        WHERE 1 = 1
            AND q.fl_status = true
            AND q.deleted_at IS NULL
            AND q.code IS NOT NULL
            AND q.status <> 'ARCH'
            AND ( p_university_id IS NULL OR qn.university_id = p_university_id )
            AND ( p_option_id IS NULL OR qn.option_id = p_option_id )
            AND ( p_modality_id IS NULL OR qn.modality_id = p_modality_id )
            AND ( p_version IS NULL OR qn."version" = p_version )
            AND ( p_year IS NULL OR qn."year" = p_year )
            AND ( p_name_text IS NULL OR q.search_text LIKE '%' || p_name_text || '%' )
            AND (p_course_id IS NULL OR q.course_id = p_course_id)
            AND (p_status IS NULL OR q.status = p_status)
            AND (p_employee_didi_id is null or e2.id = p_employee_didi_id)

        UNION ALL

        SELECT
            concat('p_',q.id) as  key_question,
            q.id,
            qsh.code,
            q.short_description,
            q.number_question,
            q.number,
            c.id as course_id,
            c.code AS code_course,
            c.name AS course,
            qsh.subtopic_id,
            qsh.topic_id,
            a.id as area_id,
            a.description as area,
            q.status,
            q.fl_status,
            q.parent_id,
            CASE
                WHEN q.parent_id IS NULL THEN 'P'
                ELSE 'S'
            END AS type_question,
            q.created_by,
            q.status_changed_at created_at,
            u.user AS user_name,
            u.email AS user_email,
            e.id as employee_id,
            CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name) AS name_employee,
            e1.id as teacher_id,
            CONCAT(e1.first_surname,' ', e1.second_surname,' ', e1.first_name) AS teacher,
            e2.id as employee_didi_id,
            CONCAT(e2.first_surname,' ', e2.second_surname,' ', e2.first_name) AS employee_didi,
            q.search_text,
            u.deleted_at as user_deleted_at,
            u.fl_suspended as user_suspended,
            get_shared_status(q.id, qsh.subtopic_id) AS shared_status,
            qn.question_origin,
            qn.university_id,
            qn.option_id,
            qn.modality_id,
            qn."version",
            qn."year"
        FROM question q
        LEFT JOIN users u ON q.created_by = u.id
        LEFT JOIN employees e on u.id = e.user_id
        LEFT JOIN employee_question eoq ON eoq.question_id = q.id AND eoq.fl_status = true
        LEFT JOIN employees e1 ON eoq.teacher_id = e1.id
        LEFT JOIN employee_didi_question oedq ON q.id = oedq.question_id AND oedq.fl_status = true
        LEFT JOIN employees e2 ON oedq.employee_id = e2.id
        INNER JOIN question_shares qsh ON qsh.question_id = q.id AND qsh.deleted_at IS NULL
        LEFT JOIN subtopic st ON qsh.subtopic_id = st.id
        LEFT JOIN topic t ON qsh.topic_id = t.id
        LEFT JOIN course c ON c.id = t.course_id
        LEFT JOIN area a ON c.area_id = a.id
        LEFT JOIN v_all_question_origins qn ON qn.question_id = q.id
        WHERE 1 = 1
            AND q.fl_status = true
            AND q.deleted_at IS NULL
            AND qsh.code IS NOT NULL
            AND q.status <> 'ARCH'
            AND ( p_university_id IS NULL OR qn.university_id = p_university_id )
            AND ( p_option_id IS NULL OR qn.option_id = p_option_id )
            AND ( p_modality_id IS NULL OR qn.modality_id = p_modality_id )
            AND ( p_version IS NULL OR qn."version" = p_version )
            AND ( p_year IS NULL OR qn."year" = p_year )
            AND ( p_name_text IS NULL OR qsh.code LIKE '%' || p_name_text || '%' OR q.search_text LIKE '%' || p_name_text || '%' )
            AND (p_course_id IS NULL OR t.course_id = p_course_id)
            AND (p_status IS NULL OR q.status = p_status)
            AND (p_employee_didi_id is null or e2.id = p_employee_didi_id)

    ), sub_questions AS (
        SELECT
            pq.id AS parent_id,
            JSONB_AGG(
                JSONB_BUILD_OBJECT(
                    'id', q.id,
                    'key_question', CONCAT('s_', q.id),
                    'type_question', 'S',
                    'parent_id', q.parent_id,
                    'code', q.code,
                    'number_question', q.number_question,
                    'short_description', q.short_description,
                    'course_id', q.course_id,
                    'course', c.name,
                    'area_id', a.id,
                    'area', a.description,
                    'status', q.status,
                    'date_status', q.status_changed_at,
                    'created_at', q.created_at,
                    'created_by_id', q.created_by,
                    'created_by', CONCAT(e.first_surname, ' ', e.second_surname, ' ', e.first_name),
                    'teacher_id', e1.id,
                    'teacher', CONCAT(e1.first_surname, ' ', e1.second_surname, ' ', e1.first_name),
                    'employee_didi_id', e2.id,
                    'employee_didi', CONCAT(e2.first_surname, ' ', e2.second_surname, ' ', e2.first_name),
                    'origin_question', qn.question_origin
                )
            ) AS subquestions
        FROM question q
        INNER JOIN parent_question pq ON q.parent_id = pq.id
        INNER JOIN course c ON q.course_id = c.id
        LEFT JOIN users u ON q.created_by = u.id
        LEFT JOIN employees e ON u.id = e.user_id
        LEFT JOIN area a ON c.area_id = a.id
        LEFT JOIN employee_question eoq ON eoq.question_id = q.id AND eoq.fl_status = true
        LEFT JOIN employees e1 ON eoq.teacher_id = e1.id
        LEFT JOIN employee_didi_question oedq ON q.id = oedq.question_id AND oedq.fl_status = true
        LEFT JOIN employees e2 ON oedq.employee_id = e2.id
        LEFT JOIN v_all_question_origins qn ON qn.question_id = q.id
        WHERE q.fl_status = true
        AND q.deleted_at IS NULL
        AND q.code IS NOT NULL
        AND q.status <> 'ARCH'
        AND (p_type IS NULL OR p_type = 'T')
        AND (p_status IS NULL OR q.status = p_status)
        AND (p_course_id IS NULL OR q.course_id = p_course_id)
        GROUP BY pq.id
    ),
    tbl_question AS (
        SELECT
            q.id,
            q.key_question,
            q.type_question,
            q.parent_id,
            q.code,
            q.number_question,
            q.short_description,
            q.course_id,
            q.course,
            q.subtopic_id,
            q.topic_id,
            q.area_id,
            q.area,
            COALESCE(sq.subquestions, '[]'::jsonb) AS subquestions,
            q.status,
            q.created_at as date_status,
            q.created_at,
            q.created_by as created_by_id,
            q.name_employee as created_by,
            q.teacher_id,
            q.teacher,
            q.employee_didi_id,
            q.employee_didi,
            q.question_origin,
            q.search_text,
            q.user_deleted_at,
            q.user_suspended,
            q.shared_status
        FROM questions q
        LEFT JOIN sub_questions sq ON q.parent_id = sq.parent_id
        -- WHERE q.parent_id IS NULL

        UNION ALL

        SELECT DISTINCT
            pq.id,
            concat('t_', pq.id) AS key_question,
            'T' AS type_question,
            pq.id as parent_id,
            pq.code,
            pq.number_question,
            pq.short_description,
            pq.course_id,
            c.name AS course,
            NULL::BIGINT AS subtopic_id,
            NULL::BIGINT AS topic_id,
            a.id as area_id,
            a.description as area,
            COALESCE(sq.subquestions, '[]'::jsonb) AS subquestions,
            pq.status,
            NULL::TIMESTAMP as date_status,
            pq.created_at,
            pq.created_by as created_by_id,
            CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name) AS created_by,
            NULL::BIGINT as teacher_id,
            NULL::TEXT as teacher,
            e.id as employee_didi_id,
            CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name) AS employee_didi,
            opq.question_origin,
            pq.search_text,
            u.deleted_at as user_deleted_at,
            u.fl_suspended as user_suspended,
            NULL::TEXT AS shared_status
        FROM parent_question pq
        INNER JOIN course c ON pq.course_id = c.id
        LEFT JOIN area a ON c.area_id = a.id
        LEFT JOIN users u ON pq.created_by = u.id
        LEFT JOIN employees e on u.id = e.user_id
        LEFT JOIN sub_questions sq ON pq.id = sq.parent_id and sq.parent_id is not null
        LEFT JOIN v_all_parent_origins opq ON opq.parent_id = pq.id
        WHERE pq.fl_status = true
        AND pq.deleted_at IS null
        AND pq.code IS NOT NULL
        AND pq.status <> 'ARCH'
        AND (p_employee_didi_id is null or e.id = p_employee_didi_id)
        AND (sq.subquestions <> '[]')
        AND ( p_university_id IS NULL OR opq.university_id = p_university_id )
        AND ( p_option_id IS NULL OR opq.option_id = p_option_id )
        AND ( p_modality_id IS NULL OR opq.modality_id = p_modality_id )
        AND ( p_version IS NULL OR opq."version" = p_version )
        AND ( p_year IS NULL OR opq."year" = p_year )
        AND ( p_name_text IS NULL OR pq.search_text LIKE '%' || p_name_text || '%' )
    ),
    filtered_questions AS (
        SELECT *
        FROM tbl_question
        WHERE (p_course_id IS NULL OR tbl_question.course_id = p_course_id)
        AND (p_created_by IS NULL OR tbl_question.created_by_id = p_created_by)
        AND (p_type IS NULL OR tbl_question.type_question = p_type)
        AND (p_teacher_id IS NULL OR tbl_question.teacher_id = p_teacher_id OR EXISTS (
            SELECT 1
            FROM jsonb_array_elements(tbl_question.subquestions) AS sq
            WHERE (sq->>'teacher_id')::BIGINT = p_teacher_id
        ))
        AND (p_employee_didi_id IS NULL OR tbl_question.employee_didi_id = p_employee_didi_id OR EXISTS (
            SELECT 1
            FROM jsonb_array_elements(tbl_question.subquestions) AS sq
            WHERE (sq->>'employee_didi_id')::BIGINT = p_employee_didi_id
        ))
    ),
    counted_questions AS (
        SELECT *, COUNT(*) OVER () AS total_count
        FROM filtered_questions
        ORDER BY created_at DESC
    )
    SELECT *
    FROM counted_questions
    LIMIT p_perpage
    OFFSET offset_val;
END;
$$;


ALTER FUNCTION odiseo.fn_search_tracking_question(p_perpage integer, p_npage integer, p_name_text character varying, p_course_id integer, p_teacher_id integer, p_employee_didi_id integer, p_status character varying, p_created_by integer, p_type character varying, p_university_id smallint, p_option_id smallint, p_modality_id smallint, p_version smallint, p_year character varying) OWNER TO postgres;

--
-- Name: fn_search_university(character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_search_university(p_name character varying) RETURNS TABLE(id smallint, name character varying, slug character varying, type smallint, region_id smallint, region character varying, areas text, versions text, fl_status boolean, created_by bigint, created_at timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    u.id,
                    u.name,
                    u.slug,
                    u.type,
                    u.region_id,
                    r.name AS region,
                    u.areas,
                    u.versions,
                    u.fl_status,
                    u.created_by,
                    u.created_at
                FROM
                    odiseo.origin_university u
                LEFT JOIN odiseo.region r
                    ON u.region_id = r.id
                WHERE
                    unaccent(lower(u.name)) = unaccent(lower(p_name))
                    OR unaccent(lower(u.slug)) = unaccent(lower(p_name));
            END;
            $$;


ALTER FUNCTION odiseo.fn_search_university(p_name character varying) OWNER TO postgres;

--
-- Name: fn_search_users(integer, integer, bigint, smallint, boolean, character varying, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_search_users(p_perpage integer, p_npage integer, f_rol_id bigint, f_charge_id smallint, f_status boolean, p_name_text character varying, p_company_id integer) RETURNS TABLE(id bigint, uuid uuid, username character varying, employee_id bigint, code character varying, usuario text, email odiseo.email_citext, image character varying, document character varying, type_document character varying, rol character varying, status boolean, suspended boolean, phone character varying, total integer, created_at timestamp without time zone, nq_status character varying, name_charge character varying, level_name character varying, level bigint, cost_per_question numeric, goal integer, courses jsonb)
    LANGUAGE plpgsql
    AS $$
    DECLARE
        total_count INTEGER;
        offset_val INTEGER;
    BEGIN
        offset_val := p_perpage * (p_npage - 1);

        SELECT COUNT(*)
        INTO total_count
        FROM users u
        LEFT JOIN users_roles ur ON ur.user_id = u.id
        LEFT JOIN roles r ON ur.rol_id = r.id
        LEFT JOIN employees e ON e.user_id = u.id
        WHERE 1 = 1 
        AND r.fl_admin = false AND r.fl_administrator = false
        AND (f_status IS NULL OR u.fl_suspended = f_status)
        AND u.fl_status IS TRUE
        AND (p_company_id IS NULL OR u.company_id = p_company_id)
        AND (f_rol_id IS NULL OR r.id = f_rol_id)
        AND (f_charge_id IS NULL OR e.charge_id = f_charge_id)
        AND (
            p_name_text IS NULL
            OR CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name) ILIKE '%' || p_name_text || '%'
            OR u."user" ILIKE '%' || p_name_text || '%'
            OR e.document ILIKE '%' || p_name_text || '%'
            );

        RETURN QUERY
        SELECT
            u.id AS id,
            u.uuid,
            u."user" AS username,
            e.id AS employee_id,
            e.code AS code,
            CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name) AS usuario,
            u.email,
            u.image,
            e.document,
            typ_doc.name as type_document,
            r.name AS rol,
            u.fl_status AS status,
            u.fl_suspended as suspended,
            e.phone,
            total_count AS total,
            u.created_at,
            CASE
                WHEN NOT fn_user_has_permission(u.id, 'neuro-quest.generar-pregunta-ia') OR NOT fn_has_user_nq_courses(u.id) THEN 'not_available'
                WHEN nur.id IS NULL THEN 'to_be_requested'
                ELSE nur.request_status
            END AS nq_status,
            c.name as name_charge,
            lr.level_name,
            lr.id,
            lr.cost_per_question,
            e.goal,
            coalesce(
            jsonb_agg(
                jsonb_build_object(
                    'id', cu.id,
                    'name', cu.name
                )
            )
            , '[]' ::jsonb) as courses
        FROM users u
        LEFT JOIN users_roles ur ON ur.user_id = u.id
        LEFT JOIN roles r ON ur.rol_id = r.id
        LEFT JOIN employees e ON e.user_id = u.id
        LEFT JOIN public.type_documents typ_doc ON typ_doc.id = e.type_document_id
        LEFT JOIN nq_user_request nur ON nur.user_id = u.id AND nur.deleted_at IS NULL
        LEFT JOIN charge c ON c.id = e.charge_id AND c.fl_status = true
        LEFT JOIN employee_course ec ON ec.teacher_id  = e.id AND ec.fl_status = true
        LEFT JOIN course cu ON cu.id = ec.course_id AND cu.fl_status = true
        LEFT JOIN level_rates lr ON lr.id = e.level_id
        WHERE 1 = 1
        AND r.fl_admin = false AND r.fl_administrator = false
        AND (f_status IS NULL OR u.fl_suspended = f_status)
        AND u.fl_status IS TRUE
        AND (p_company_id IS NULL OR u.company_id = p_company_id)
        AND (f_rol_id IS NULL OR r.id = f_rol_id)
        AND (f_charge_id IS NULL OR e.charge_id = f_charge_id)
        AND (
            p_name_text IS NULL
            OR CONCAT(e.first_surname,' ', e.second_surname,' ', e.first_name) ILIKE '%' || p_name_text || '%'
            OR u."user" ILIKE '%' || p_name_text || '%'
            OR e.document ILIKE '%' || p_name_text || '%'
        )
        GROUP BY u.id, e.id, typ_doc.id,r.id, nur.id, c.id, lr.id
        ORDER BY u."user" ASC
        LIMIT p_perpage
        OFFSET offset_val;
    END;
    $$;


ALTER FUNCTION odiseo.fn_search_users(p_perpage integer, p_npage integer, f_rol_id bigint, f_charge_id smallint, f_status boolean, p_name_text character varying, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_set_lock_status_on_material(integer, integer, integer, boolean, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_set_lock_status_on_material(p_material_id integer, p_type_material_id integer, p_week integer, p_locked_status boolean, p_locker_user integer) RETURNS TABLE(lock_status boolean, locked_at timestamp without time zone, locked_by_id integer, locked_by_name text)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    UPDATE odiseo.detail_week_type_mat
                        SET locked = p_locked_status,
                            locked_by = p_locker_user,
                            locked_at = NOW()
                        WHERE 1 = 1
                          AND material_id = p_material_id
                          AND week = p_week
                          AND type_material_id = p_type_material_id;
                          
                    RETURN QUERY
                    
                    WITH lock_status AS (
                        SELECT
                            p_locked_status AS lock_status,
                            p_locker_user AS locked_by_id
                    )
                    SELECT
                        ls.lock_status,
                        NOW()::TIMESTAMP WITHOUT TIME ZONE AS locked_at,
                        ls.locked_by_id,
                        CASE
                            WHEN ls.locked_by_id IN (1, 2) THEN 'Administrador'
                            ELSE CONCAT( e.first_surname, ' ', e.second_surname, ' ', e.first_name )
                        END AS locked_by_name
                    FROM lock_status ls
                    LEFT JOIN odiseo.employees e ON e.user_id = ls.locked_by_id;
                END;
            $$;


ALTER FUNCTION odiseo.fn_set_lock_status_on_material(p_material_id integer, p_type_material_id integer, p_week integer, p_locked_status boolean, p_locker_user integer) OWNER TO postgres;

--
-- Name: fn_show_user(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_show_user(p_user_id integer) RETURNS TABLE(id bigint, "user" character varying, email odiseo.email_citext, fl_status boolean, rol_id bigint)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY

                    select u.id, u."user", u.email , u.fl_status,ur.rol_id
                    from users u
                    left join users_roles ur  on u.id = ur.user_id
                    WHERE u.id = p_user_id   ;
                END;
                $$;


ALTER FUNCTION odiseo.fn_show_user(p_user_id integer) OWNER TO postgres;

--
-- Name: fn_show_user_uuid(uuid, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_show_user_uuid(p_uuid uuid, p_company_id bigint) RETURNS TABLE(uuid uuid, user_name character varying, email character varying, rol_id bigint, employee_uuid uuid, first_name character varying, first_surname character varying, second_surname character varying, personal_email character varying, phone character varying, charge_id bigint, type_document_id bigint, document character varying, company_id integer, data_universities jsonb, courses jsonb, data_teacher json)
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                        RETURN QUERY
                        WITH exists_employee AS (
                            SELECT
                                u.uuid,
                                e.id AS employee_id
                            FROM users u
                            JOIN employees e ON u.id = e.user_id
                            WHERE u.uuid = p_uuid
                                AND u.company_id = p_company_id
                        ), get_courses AS (
                            SELECT
                                ec.course_id AS id,
                                c.name,
                                ec.created_at
                            FROM employee_course ec
                            JOIN course c ON ec.course_id = c.id
                            WHERE ec.teacher_id IN (SELECT ee.employee_id FROM exists_employee ee)
                                AND ec.fl_status = true
                        ), get_universities AS (
                            SELECT
                                eu.university_id AS id,
                                ou.name,
                                eu.created_at
                            FROM employee_university eu
                            JOIN origin_university ou ON eu.university_id = ou.id
                            WHERE eu.employee_id IN (SELECT ee.employee_id FROM exists_employee ee)
                                AND eu.fl_status = true
                        ), get_data_teacher AS (
                            SELECT
                                e.fl_unlimit_questions,
                                e.goal,
                                e.lot,
                                e.level_id,
                                lr.level_name,
                                e.fl_resolve_missing_questions,
                                e.limit_missing_questions
                            FROM employees e
                            LEFT JOIN level_rates lr ON e.level_id = lr.id
                            WHERE e.id IN (SELECT ee.employee_id FROM exists_employee ee)
                                AND e.charge_id = 2
                        )
                        SELECT
                            u.uuid,
                            u.user AS user_name,
                            u.email::varchar,
                            ur.rol_id,
                            e.uuid AS employee_uuid,
                            e.first_name,
                            e.first_surname,
                            e.second_surname,
                            e.email::varchar AS personal_email,
                            e.phone,
                            e.charge_id,
                            e.type_document_id,
                            e.document,
                            u.company_id,
                            (
                                SELECT JSONB_AGG(gu.id ORDER BY gu.id)
                                FROM get_universities gu
                            ) data_universities,
                            (
                                SELECT JSONB_AGG(gc.id ORDER BY gc.id)
                                FROM get_courses gc
                            ) courses,
                            (
                                SELECT JSON_BUILD_OBJECT(
                                    'fl_unlimit_questions', gdt.fl_unlimit_questions,
                                    'goal', gdt.goal,
                                    'lot', gdt.lot,
                                    'level_id', gdt.level_id,
                                    'level_name', gdt.level_name,
                                    'fl_resolve_missing_questions', gdt.fl_resolve_missing_questions,
                                    'missing_questions_lot', gdt.limit_missing_questions
                                )
                                FROM get_data_teacher gdt
                                LIMIT 1
                            ) AS data_teacher
                        FROM employees e
                        JOIN users u ON e.user_id = u.id
                        JOIN users_roles ur ON u.id = ur.user_id
                        WHERE e.id IN (SELECT ee.employee_id FROM exists_employee ee);
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_show_user_uuid(p_uuid uuid, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_source_layers_on_subtopic(integer, integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_source_layers_on_subtopic(p_perpage integer, p_n_page integer, p_university_id integer, p_subtopic_id integer) RETURNS TABLE(year character varying, option_name character varying, area_name text, total bigint)
    LANGUAGE plpgsql
    AS $$
                                DECLARE
                                    total_count INTEGER;
                                    offset_val INTEGER;
                                BEGIN
                                    offset_val := p_perpage * (p_n_page - 1);
                        
                                    RETURN QUERY
                                        WITH source_layers_list AS (
                                            SELECT 
                                                oq."year",
                                                o.name AS option_name,
                                                array_to_string(
                                                    ARRAY(
                                                        SELECT json_array_elements_text(oq.areas::json)
                                                    ),
                                                    ' - '
                                                ) AS area_name
                                            FROM origin_question oq 
                                            JOIN question q ON q.id = oq.question_id
                                            JOIN question_subtopic qs ON qs.question_id = q.id AND qs.fl_status = true
                                            JOIN subtopic s ON s.id = qs.subtopic_id
                                            JOIN modality_options m ON m.id = oq.modality_option_id
                                            JOIN option_university o ON o.id = m.option_university_id 
                                            WHERE oq.fl_status = true
                                            AND s.id = p_subtopic_id
                                            AND o.university_id = p_university_id
                                            ORDER BY s.id
                                        ), counted_source_layers_list AS (
                                            SELECT
                                                *,
                                                COUNT(*) OVER () AS total
                                            FROM source_layers_list
                                        )
                                        SELECT
                                            *
                                        FROM counted_source_layers_list
                                        LIMIT p_perpage OFFSET offset_val;
                                END;
                            $$;


ALTER FUNCTION odiseo.fn_source_layers_on_subtopic(p_perpage integer, p_n_page integer, p_university_id integer, p_subtopic_id integer) OWNER TO postgres;

--
-- Name: fn_store_exam_parent_question(bigint, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_store_exam_parent_question(p_week_type_material_id bigint, p_parent_questions jsonb, p_created_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
    BEGIN
        DROP TABLE IF EXISTS temp_cycle_and_university_in_material;
        CREATE TEMP TABLE temp_cycle_and_university_in_material (
            cycle_id BIGINT,
            university_id BIGINT,
            headquarte_id BIGINT
        ) ON COMMIT DROP;
        WITH get_material_id AS (
            SELECT
                dtw.material_id
            FROM detail_week_type_mat dtw
            WHERE dtw.id = p_week_type_material_id
            GROUP BY dtw.material_id
        ), cycle_and_university_in_material AS (
            SELECT
                m.cycle_id,
                m.university_id,
                m.headquarte_id
            FROM material m
            WHERE m.id IN (SELECT material_id FROM get_material_id)
        )
        INSERT INTO temp_cycle_and_university_in_material
        SELECT * FROM cycle_and_university_in_material;
        
        DROP TABLE IF EXISTS temp_parent_questions;
        CREATE TEMP TABLE temp_parent_questions (
            area_id SMALLINT,
            course_id SMALLINT,
            parent_question_id INTEGER,
            absolute_position SMALLINT,
            expected_level SMALLINT,
            current_level SMALLINT,
            random BOOLEAN,
            subquestions JSONB,
            created_by BIGINT,
            created_at TIMESTAMP
        ) ON COMMIT DROP;
        WITH parent_questions AS (
            SELECT
                (e->>'area_id')::SMALLINT AS area_id,
                (e->>'course_id')::SMALLINT AS course_id,
                (e->>'parent_question_id')::INT AS parent_question_id,
                (e->>'position')::SMALLINT AS absolute_position, 
                (e->>'level')::INT AS expected_level,
                CASE
                    WHEN (e->>'parent_question_id')::INT IS NULL THEN NULL
                    ELSE (e->>'level')::INT
                END AS current_level,
                (e->>'random')::BOOLEAN AS random,
                (e->>'subquestions')::JSONB AS subquestions,
                p_created_by AS created_by,
                NOW() AS created_at
            FROM JSONB_ARRAY_ELEMENTS(p_parent_questions) AS e
        ) 
        INSERT INTO temp_parent_questions
        SELECT * FROM parent_questions;
    
        DROP TABLE IF EXISTS temp_register_material_exam_area_weeks;
        CREATE TEMP TABLE temp_register_material_exam_area_weeks (
            id BIGINT,
            area_id SMALLINT,
            created_by BIGINT,
            created_at TIMESTAMP
        ) ON COMMIT DROP;
        WITH register_material_exam_area_week AS (
            INSERT INTO material_exam_area_week AS meaw( week_type_material_id, area_id, created_by, created_at )
            SELECT p_week_type_material_id, area_id, p_created_by, NOW() FROM temp_parent_questions GROUP BY area_id
            ON CONFLICT ON CONSTRAINT uq_week_ty_mat_id_area_id
            DO UPDATE
                SET
                    week_type_material_id = EXCLUDED.week_type_material_id,
                    area_id = EXCLUDED.area_id
            RETURNING meaw.id, meaw.area_id
        )
        INSERT INTO temp_register_material_exam_area_weeks
        SELECT * FROM register_material_exam_area_week;

        DROP TABLE IF EXISTS temp_subquestions_extracted;
        CREATE TEMP TABLE temp_subquestions_extracted (
            question_id BIGINT
        ) ON COMMIT DROP;
        WITH subquestions_to_extract AS (
            SELECT
                JSONB_ARRAY_ELEMENTS(pss.subquestions) AS subquestion
            FROM temp_parent_questions pss
            WHERE pss.parent_question_id IS NOT NULL
        ), subquestions_extracted AS (
            SELECT
                (pet.subquestion->>'question_id')::INTEGER AS question_id
            FROM subquestions_to_extract pet
            WHERE (pet.subquestion->>'question_id')::INTEGER IS NOT NULL
        )
        INSERT INTO temp_subquestions_extracted
        SELECT * FROM subquestions_extracted;

        UPDATE material_exam_parent_question epq
           SET question_history_id = NULL
        WHERE 1 = 1
          AND epq.id IN  ( SELECT rg.id FROM temp_register_material_exam_area_weeks rg )
          AND question_history_id IS NOT NULL;

        DROP TABLE IF EXISTS temp_insert_parent_questions;
        CREATE TEMP TABLE temp_insert_parent_questions (
            id BIGINT
        ) ON COMMIT DROP;
        WITH insert_parent_questions AS (
            INSERT INTO
                material_exam_parent_question AS mepq
                (
                    material_exam_area_week_id,
                    course_id,
                    parent_question_id,
                    position,
                    expected_level,
                    current_level, 
                    random, 
                    subquestion,
                    created_by,
                    created_at
                )
            SELECT
                ta.id,
                pmh.course_id,
                pmh.parent_question_id,
                pmh.absolute_position, 
                pmh.expected_level,
                pmh.current_level,
                pmh.random, 
                pmh.subquestions,
                p_created_by,
                NOW()
            FROM temp_parent_questions pmh
            JOIN temp_register_material_exam_area_weeks ta ON ta.area_id = pmh.area_id
            ON CONFLICT ON CONSTRAINT uq_parent_question_in_area
            DO UPDATE
                SET
                    material_exam_area_week_id = EXCLUDED.material_exam_area_week_id,
                    course_id = EXCLUDED.course_id,
                    parent_question_id = EXCLUDED.parent_question_id,
                    position = EXCLUDED.position, 
                    random = EXCLUDED.random,
                    expected_level = EXCLUDED.expected_level,
                    current_level = EXCLUDED.current_level,
                    subquestion = EXCLUDED.subquestion,
                    created_by = p_created_by,
                    created_at = NOW(),
                    updated_by = NULL,
                    updated_at = NULL,
                    deleted_by = NULL,
                    deleted_at = NULL
            RETURNING mepq.id
        )
        INSERT INTO temp_insert_parent_questions
        SELECT id FROM insert_parent_questions;

        /* Desactivar las fila de material_exam_parent_question que ya no se usaran */
        UPDATE material_exam_parent_question mn
            SET
                parent_question_id = NULL,
                subquestion = NULL,
                question_history_id = NULL,
                deleted_at = NOW(),
                deleted_by = p_created_by
        WHERE 1 = 1
          AND material_exam_area_week_id IN ( SELECT rk.id FROM temp_register_material_exam_area_weeks rk )
          AND mn.id NOT IN (SELECT iqs.id FROM temp_insert_parent_questions iqs);

        /* Borrar historico */
        UPDATE question_history_usage_exam_parent_question
            SET
                updated_at = NOW(),
                updated_by = p_created_by
        WHERE 1 = 1
          AND material_exam_area_week_id IN ( SELECT rk.id FROM temp_register_material_exam_area_weeks rk )
          AND updated_at IS NULL;

        EXECUTE 'REFRESH MATERIALIZED VIEW odiseo.vm_material_exam_parent_question_with_subquestions';

        /* Crear historico */
        INSERT INTO question_history_usage_exam_parent_question( material_exam_area_week_id, course_id, parent_question_id, question_id, created_at, created_by )
        SELECT material_exam_area_week_id, course_id, parent_question_id, question_id, NOW(), p_created_by
        FROM vm_material_exam_parent_question_with_subquestions
        WHERE 1 = 1
          AND material_exam_area_week_id IN ( SELECT rm.id FROM temp_register_material_exam_area_weeks rm );
    END;
$$;


ALTER FUNCTION odiseo.fn_store_exam_parent_question(p_week_type_material_id bigint, p_parent_questions jsonb, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_store_question_material(boolean, jsonb, bigint, smallint, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_store_question_material(p_fl_exam boolean, p_questions jsonb, p_material_id bigint, p_week_type_material_id smallint, p_areas jsonb, p_created_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_data_question JSONB;
            v_question_history_id BIGINT;
            v_cycle_id BIGINT;
            v_university_id SMALLINT;
            v_headquarters_id BIGINT;
            v_headquarters_classroom_id BIGINT;
            v_exam_area_key TEXT;
            v_exam_area_value BIGINT;
            v_material_exam_area_week BIGINT;
            v_week SMALLINT;
            v_type_material_id SMALLINT;
        BEGIN
            -- Obtener ciclo y universidad del material mandado
            SELECT
                m.cycle_id, m.university_id, m.headquarte_id, m.headquarters_classroom_id
                INTO v_cycle_id, v_university_id, v_headquarters_id, v_headquarters_classroom_id
            FROM material m WHERE id = p_material_id LIMIT 1;

            -- Obtener week y type_material_id
            SELECT
                week, type_material_id
                INTO v_week, v_type_material_id
            FROM detail_week_type_mat WHERE id = p_week_type_material_id LIMIT 1;

            IF p_fl_exam IS FALSE THEN
                FOR v_data_question IN SELECT * FROM jsonb_array_elements(p_questions) LOOP
                    SELECT qhc.id INTO v_question_history_id FROM question_history_cycle qhc
                    WHERE qhc.question_id = (v_data_question->>'question_id')::BIGINT
                    AND qhc.cycle_id = v_cycle_id
                    AND qhc.university_id = v_university_id
                    AND qhc.headquarters_id = v_headquarters_id
                    AND qhc.fl_status = true
                    LIMIT 1;

                    IF v_question_history_id IS NULL THEN
                        INSERT INTO question_history_cycle(question_id, cycle_id, university_id, headquarters_id, created_by, created_at)
                        VALUES ((v_data_question->>'question_id')::BIGINT, v_cycle_id, v_university_id, v_headquarters_id, p_created_by, now())
                        RETURNING id INTO v_question_history_id;
                    END IF;

                    INSERT INTO material_ballot_question (
                        week_type_material_id,
                        material_id,
                        week,
                        type_material_id,
                        course_id,
                        topic_id,
                        subtopic_id,
                        level_id,
                        type,
                        question_id,
                        question_history_id,
                        position,
                        state,
                        created_by,
                        created_at
                    )
                    VALUES (
                        (v_data_question->>'week_type_material_id')::BIGINT,
                        p_material_id,
                        v_week,
                        v_type_material_id,
                        (v_data_question->>'course_id')::SMALLINT,
                        (v_data_question->>'topic_id')::SMALLINT,
                        (v_data_question->>'subtopic_id')::SMALLINT,
                        (v_data_question->>'level_id')::BIGINT,
                        (v_data_question->>'type')::VARCHAR,
                        (v_data_question->>'question_id')::BIGINT,
                        v_question_history_id,
                        (v_data_question->>'order')::BIGINT,
                        'GENERATED',
                        p_created_by,
                        NOW()
                    )
                    ON CONFLICT (week_type_material_id, (COALESCE(question_id, 0)), (COALESCE(parent_question_id, 0)))
                    WHERE fl_status = TRUE AND deleted_at IS NULL AND (question_id IS NOT NULL OR parent_question_id IS NOT NULL)
                    DO UPDATE SET
                        course_id = EXCLUDED.course_id,
                        topic_id = EXCLUDED.topic_id,
                        subtopic_id = EXCLUDED.subtopic_id,
                        level_id = EXCLUDED.level_id,
                        type = EXCLUDED.type,
                        question_history_id = EXCLUDED.question_history_id,
                        position = EXCLUDED.position,
                        state = EXCLUDED.state,
                        updated_by = EXCLUDED.created_by,
                        updated_at = NOW();
                END LOOP;
            ELSE
                FOR v_exam_area_value IN SELECT * FROM jsonb_array_elements(p_areas) LOOP
                    SELECT meaw.id INTO v_material_exam_area_week
                    FROM material_exam_area_week meaw
                    WHERE meaw.week_type_material_id = p_week_type_material_id
                    AND meaw.area_id = v_exam_area_value AND meaw.fl_status = true LIMIT 1;

                    IF v_material_exam_area_week IS NULL THEN
                        INSERT INTO material_exam_area_week (week_type_material_id, area_id, created_by, created_at)
                        VALUES (p_week_type_material_id, v_exam_area_value, p_created_by, NOW())
                        RETURNING id INTO v_material_exam_area_week;
                    END IF;

                    FOR v_data_question IN
                        SELECT q.* FROM jsonb_array_elements(p_questions) AS q WHERE q->>'exam_area_id' = v_exam_area_value::TEXT
                    LOOP
                        SELECT qhc.id INTO v_question_history_id FROM question_history_cycle qhc
                        WHERE qhc.question_id = (v_data_question->>'question_id')::BIGINT
                        AND qhc.cycle_id = v_cycle_id
                        AND qhc.university_id = v_university_id
                        AND qhc.headquarters_id = v_headquarters_id
                        AND qhc.fl_status = true
                        LIMIT 1;

                        IF v_question_history_id IS NULL THEN
                            INSERT INTO question_history_cycle(question_id, cycle_id, university_id, headquarters_id, created_by, created_at)
                            VALUES ((v_data_question->>'question_id')::BIGINT, v_cycle_id, v_university_id, v_headquarters_id, p_created_by, now())
                            RETURNING id INTO v_question_history_id;
                        END IF;

                        INSERT INTO material_exam_question (
                            material_exam_area_week_id,
                            course_id,
                            topic_id,
                            subtopic_id,
                            level_id,
                            question_id,
                            question_history_id,
                            type,
                            created_by,
                            created_at
                        )
                        VALUES (
                            v_material_exam_area_week,
                            (v_data_question->>'course_id')::SMALLINT,
                            (v_data_question->>'topic_id')::SMALLINT,
                            (v_data_question->>'subtopic_id')::SMALLINT,
                            (v_data_question->>'level_id')::BIGINT,
                            (v_data_question->>'question_id')::BIGINT,
                            v_question_history_id,
                            (v_data_question->>'type')::VARCHAR,
                            p_created_by,
                            NOW()
                        );
                    END LOOP;
                END LOOP;
            END IF;
        END;
        $$;


ALTER FUNCTION odiseo.fn_store_question_material(p_fl_exam boolean, p_questions jsonb, p_material_id bigint, p_week_type_material_id smallint, p_areas jsonb, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_store_text_material(boolean, jsonb, bigint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_store_text_material(p_fl_exam boolean, p_text jsonb, p_material_id bigint, p_week_type_material_id smallint, p_created_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
	DECLARE
            v_data_question JSONB;
            v_question_history_id BIGINT;
            v_cycle_id BIGINT;
            v_university_id SMALLINT;
            v_headquarters_id BIGINT;
            v_headquarters_classroom_id BIGINT;
            v_material_exam_area_week BIGINT;
            v_week SMALLINT;
            v_type_material_id SMALLINT;
	BEGIN
			-- Obtener ciclo y universidad del material mandado
            SELECT
                m.cycle_id, m.university_id, m.headquarte_id, m.headquarters_classroom_id
                INTO v_cycle_id, v_university_id, v_headquarters_id, v_headquarters_classroom_id
            FROM material m WHERE id = p_material_id LIMIT 1;

            -- Obtener week y type_material_id para la nueva estructura
            SELECT
                week, type_material_id
                INTO v_week, v_type_material_id
            FROM detail_week_type_mat WHERE id = p_week_type_material_id LIMIT 1;

			 FOR v_data_question IN SELECT * FROM jsonb_array_elements(p_text) LOOP
                    SELECT qhc.id INTO v_question_history_id FROM question_history_cycle qhc
                    WHERE qhc.parent_question_id = (v_data_question->>'parent_id')::BIGINT
                    AND qhc.cycle_id = v_cycle_id
                    AND qhc.university_id = v_university_id
                    AND qhc.headquarters_id = v_headquarters_id
                    AND qhc.fl_status = true
                    LIMIT 1;

                    IF v_question_history_id IS NULL THEN
                        INSERT INTO question_history_cycle(
							parent_question_id, cycle_id,
							university_id,
 							headquarters_id,
                            subquestion,
							created_by,
 							created_at
						)
                        VALUES (
							(v_data_question->>'parent_id')::BIGINT,
 							v_cycle_id, v_university_id,
 							v_headquarters_id,
                            (v_data_question->>'selected_subquestions')::JSONB,
 							p_created_by,
 							now()
						)
                        RETURNING id INTO v_question_history_id;
                    END IF;

                    WITH inserted_mbq AS (
                        INSERT INTO material_ballot_question (
                            week_type_material_id,
                            material_id,
                            week,
                            type_material_id,
                            course_id,
                            level_id,
                            parent_question_id,
                            question_history_id,
                            type_text_id,
                            type_text_subcategory_id,
                            state,
                            created_by,
                            created_at
                        )
                        VALUES (
                            (v_data_question->>'week_type_material_id')::BIGINT,
                            p_material_id,
                            v_week,
                            v_type_material_id,
                            (v_data_question->>'course_id')::SMALLINT,
                            (v_data_question->>'level_id')::BIGINT,
                            (v_data_question->>'parent_id')::BIGINT,
                            v_question_history_id,
                            (v_data_question->>'category_id')::BIGINT,
                            (v_data_question->>'subcategory_id')::BIGINT,
                            'GENERATED',
                            p_created_by,
                            NOW()
                        )
                        ON CONFLICT (week_type_material_id, (COALESCE(question_id, 0)), (COALESCE(parent_question_id, 0)))
                        WHERE fl_status = TRUE AND deleted_at IS NULL AND (question_id IS NOT NULL OR parent_question_id IS NOT NULL)
                        DO UPDATE SET
                            course_id = EXCLUDED.course_id,
                            level_id = EXCLUDED.level_id,
                            question_history_id = EXCLUDED.question_history_id,
                            type_text_id = EXCLUDED.type_text_id,
                            type_text_subcategory_id = EXCLUDED.type_text_subcategory_id,
                            state = EXCLUDED.state,
                            updated_by = EXCLUDED.created_by,
                            updated_at = NOW()
                        RETURNING id
                    ),
                    deleted_subquestions AS (
                        UPDATE material_ballot_subquestions
                        SET fl_status = FALSE, deleted_at = NOW()
                        WHERE material_ballot_question_id IN (SELECT id FROM inserted_mbq)
                          AND fl_status = TRUE
                    )
                    INSERT INTO odiseo.material_ballot_subquestions (material_ballot_question_id, question_id, position, state, topic_id, course_id, subtopic_id)
                    SELECT
                        mbq.id,
                        (elem->>'question_id')::BIGINT,
                        row_number() OVER(PARTITION BY mbq.id ORDER BY (elem->>'position')::INT2 NULLS LAST)::INT2,
                        CASE WHEN (elem->>'question_id') IS NOT NULL THEN 'GENERATED'::varchar ELSE 'MISSING'::varchar END,
                        (elem->>'topic_id')::SMALLINT,
                        (elem->>'course_id')::SMALLINT,
                        (elem->>'subtopic_id')::SMALLINT
                    FROM inserted_mbq mbq
                    CROSS JOIN LATERAL jsonb_array_elements(
                        CASE WHEN jsonb_typeof((v_data_question->>'selected_subquestions')::jsonb) = 'array'
                        THEN (v_data_question->>'selected_subquestions')::jsonb
                        ELSE '[]'::jsonb END
                    ) AS elem
                    WHERE (v_data_question->>'selected_subquestions') IS NOT NULL;
                END LOOP;

	END;
$$;


ALTER FUNCTION odiseo.fn_store_text_material(p_fl_exam boolean, p_text jsonb, p_material_id bigint, p_week_type_material_id smallint, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_subtopics_count_questions(smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_subtopics_count_questions(f_topic_id smallint) RETURNS TABLE(id smallint, code character varying, name character varying, topic_id smallint, count_questions bigint)
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                        RETURN QUERY
                        WITH tbl_question_veri AS (
                            SELECT
                                qs.subtopic_id,
                                count(q.id) AS count_questions
                            FROM question q
                            INNER JOIN question_subtopic qs ON q.id = qs.question_id AND qs.fl_status = true
                            WHERE q.status IN ('VERI', 'APRB')
                            GROUP BY qs.subtopic_id
                        ), tbl_subtopic AS (
                            SELECT
                                s.id, s.code, s.name, s.topic_id, COALESCE(qs.count_questions, 0) AS count_questions
                            FROM subtopic s
                            LEFT JOIN tbl_question_veri qs ON s.id = qs.subtopic_id
                            WHERE s.fl_status = true
                        )
                        SELECT ts.* FROM tbl_subtopic ts
                        WHERE (f_topic_id IS NULL OR ts.topic_id = f_topic_id)
                        ORDER BY ts.code ASC;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_subtopics_count_questions(f_topic_id smallint) OWNER TO postgres;

--
-- Name: fn_syllabus(integer, integer, jsonb, jsonb, bigint, boolean, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_syllabus(p_perpage integer, p_npage integer, f_course_ids jsonb, f_university_ids jsonb, f_cycle_id bigint, f_cycle_active boolean, p_company_id bigint) RETURNS TABLE(id bigint, university_id smallint, code_university character varying, slug_university character varying, university character varying, course_id bigint, code_course character varying, course character varying, cycle_id bigint, code_cycle character varying, cycle character varying, start_date date, end_date date, is_topic_modified boolean, is_disabled boolean, is_deleteable boolean, created_at timestamp without time zone, is_inconsistent boolean, total bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    offset_val INTEGER;
BEGIN
    offset_val := p_perpage * (p_npage - 1);
    
    RETURN QUERY
    WITH tbl_syllabus AS (
        SELECT
            s.id, s.university_id, u.code AS code_university, u.slug AS slug_university, u.name AS university,
            s.course_id, co.code AS code_course, co.name AS course, s.cycle_id, cy.code AS code_cycle,
            cy.description AS cycle, cy.start_date, cy.end_date, false AS is_topic_modified,
            s.is_disabled, s.is_deleteable, s.created_at
        FROM syllabus s
        INNER JOIN origin_university u ON s.university_id = u.id
        LEFT JOIN course co ON s.course_id = co.id
        INNER JOIN cycle cy ON s.cycle_id = cy.id
        WHERE s.fl_status = TRUE
        AND s.course_id IN (SELECT value::BIGINT FROM jsonb_array_elements_text(f_course_ids) AS value)
        AND s.university_id IN ( SELECT value::BIGINT FROM jsonb_array_elements_text(f_university_ids) AS value)
        AND (f_cycle_id IS NULL OR s.cycle_id = f_cycle_id)
        AND (f_cycle_active IS NULL OR cy.active = f_cycle_active)
        AND s.company_id = p_company_id
    ),

    counted_syllabus AS (
        SELECT *, COUNT(*) OVER () AS total_rows
        FROM tbl_syllabus
        ORDER BY
            tbl_syllabus.created_at DESC,
            tbl_syllabus.university_id ASC,
            tbl_syllabus.start_date DESC,
            tbl_syllabus.cycle_id DESC
    ),
    paginated_syllabus AS (
        SELECT * FROM counted_syllabus
        LIMIT p_perpage OFFSET offset_val
    ),
    cycle_active_weeks AS (
        SELECT DISTINCT cw.cycle_id, cw.week
        FROM cycle_weeks cw
        JOIN type_week tw ON tw.id = cw.type_week_id
        WHERE cw.cycle_id IN (SELECT DISTINCT ps2.cycle_id FROM paginated_syllabus ps2)
        AND cw.fl_status = true
        AND tw.description != 'Inactiva'
        AND cw.week IS NOT NULL
    ),
    all_type_materials AS (
        SELECT DISTINCT
            tmc.course_id,
            tm.cycle_id,
            tm.id AS type_material_id
        FROM type_material tm
        JOIN type_material_course tmc ON tmc.type_material_id = tm.id
        WHERE tm.cycle_id IN (SELECT DISTINCT ps2.cycle_id FROM paginated_syllabus ps2)
        AND tmc.course_id IN (SELECT DISTINCT ps2.course_id FROM paginated_syllabus ps2)
        AND tm.fl_exam = false
        AND tm.fl_status = true
        AND (
            tm.parent_id IS NOT NULL
            OR tm.id NOT IN (
                SELECT sub_tm.parent_id FROM type_material sub_tm
                WHERE sub_tm.cycle_id = tm.cycle_id AND sub_tm.parent_id IS NOT NULL
            )
        )
    ),
    all_combinations AS (
        SELECT
            atm.course_id,
            atm.cycle_id,
            caw.week,
            atm.type_material_id
        FROM all_type_materials atm
        JOIN cycle_active_weeks caw ON caw.cycle_id = atm.cycle_id
    ),
    expected_config AS (
        SELECT
            tmc.course_id,
            tm.cycle_id,
            tmdt.week,
            tm.id AS type_material_id,
            'P'::text AS type,
            SUM(CASE WHEN tmc.is_generic = true THEN tmc.amount_question ELSE COALESCE(tmdc.amount_question, 0) END) AS expected_amount
        FROM type_material tm
        JOIN type_material_detail_template tmdt ON tmdt.type_material_id = tm.id AND tmdt.fl_status = true
        JOIN type_material_course tmc ON tmc.type_material_id = tm.id
        LEFT JOIN type_material_detail_courses tmdc ON tmdc.type_material_course_id = tmc.id AND tmdc.type_material_detail_template_id = tmdt.id
        WHERE tm.cycle_id IN (SELECT DISTINCT ps2.cycle_id FROM paginated_syllabus ps2)
        AND tmc.course_id IN (SELECT DISTINCT ps2.course_id FROM paginated_syllabus ps2)
        AND tm.fl_exam = false AND tm.fl_status = true
        AND (
            tm.parent_id IS NOT NULL
            OR tm.id NOT IN (
                SELECT sub_tm.parent_id FROM type_material sub_tm
                WHERE sub_tm.cycle_id = tm.cycle_id AND sub_tm.parent_id IS NOT NULL
            )
        )
        GROUP BY tmc.course_id, tm.cycle_id, tmdt.week, tm.id
        HAVING SUM(CASE WHEN tmc.is_generic = true THEN tmc.amount_question ELSE COALESCE(tmdc.amount_question, 0) END) > 0

        UNION ALL

        SELECT
            tmc.course_id,
            tm.cycle_id,
            tmdt.week,
            tm.id AS type_material_id,
            'T'::text AS type,
            SUM(CASE WHEN tmc.is_generic_text = true THEN tmc.amount_text ELSE COALESCE(tmdct.amount_text, 0) END) AS expected_amount
        FROM type_material tm
        JOIN type_material_detail_template tmdt ON tmdt.type_material_id = tm.id AND tmdt.fl_status = true
        JOIN type_material_course tmc ON tmc.type_material_id = tm.id
        LEFT JOIN type_material_detail_course_texts tmdct ON tmdct.type_material_course_id = tmc.id AND tmdct.type_material_detail_template_id = tmdt.id
        WHERE tm.cycle_id IN (SELECT DISTINCT ps2.cycle_id FROM paginated_syllabus ps2)
        AND tmc.course_id IN (SELECT DISTINCT ps2.course_id FROM paginated_syllabus ps2)
        AND tm.fl_exam = false AND tm.fl_status = true
        AND (
            tm.parent_id IS NOT NULL
            OR tm.id NOT IN (
                SELECT sub_tm.parent_id FROM type_material sub_tm
                WHERE sub_tm.cycle_id = tm.cycle_id AND sub_tm.parent_id IS NOT NULL
            )
        )
        GROUP BY tmc.course_id, tm.cycle_id, tmdt.week, tm.id
        HAVING SUM(CASE WHEN tmc.is_generic_text = true THEN tmc.amount_text ELSE COALESCE(tmdct.amount_text, 0) END) > 0
    ),
    actual_syllabus AS (
        SELECT
            st.syllabus_id,
            stw.week,
            sstm.type_material_id,
            'P'::text AS type,
            SUM(sstm.questions_amount) AS actual_amount
        FROM syllabus_subtopic_type_material sstm
        JOIN syllabus_detail_subtopic sds ON sds.id = sstm.syllabus_detail_subtopic_id
        JOIN syllabus_topic_week stw ON stw.id = sds.syllabus_topic_week_id
        JOIN syllabus_topic st ON st.id = stw.syllabus_topic_id
        WHERE st.syllabus_id IN (SELECT ps2.id FROM paginated_syllabus ps2)
        AND sstm.fl_status = true AND sds.fl_status = true AND stw.fl_status = true AND st.fl_status = true
        GROUP BY st.syllabus_id, stw.week, sstm.type_material_id

        UNION ALL

        SELECT
            stw.syllabus_id,
            stw.week,
            std.type_material_id,
            'T'::text AS type,
            COUNT(stx.id) AS actual_amount
        FROM syllabus_text_weeks stw
        JOIN syllabus_text_distributions std ON std.syllabus_text_week_id = stw.id AND std.fl_status = true
        JOIN syllabus_texts stx ON stx.syllabus_text_distribution_id = std.id AND stx.fl_status = true
        WHERE stw.syllabus_id IN (SELECT ps2.id FROM paginated_syllabus ps2)
        AND stw.fl_status = true
        GROUP BY stw.syllabus_id, stw.week, std.type_material_id
    ),
    syllabus_inconsistencies AS (
        SELECT DISTINCT ps2.id AS syllabus_id
        FROM paginated_syllabus ps2
        JOIN all_combinations ac ON ac.course_id = ps2.course_id AND ac.cycle_id = ps2.cycle_id
        LEFT JOIN expected_config ec
            ON ec.course_id = ac.course_id
            AND ec.cycle_id = ac.cycle_id
            AND ec.week = ac.week
            AND ec.type_material_id = ac.type_material_id
        LEFT JOIN actual_syllabus asy
            ON asy.syllabus_id = ps2.id
            AND asy.week = ac.week
            AND asy.type_material_id = ac.type_material_id
            AND asy.type = ec.type
        WHERE
            (ec.expected_amount IS NOT NULL AND asy.actual_amount IS NULL)
            -- inconsistent: las cantidades no coinciden
            OR ec.expected_amount != COALESCE(asy.actual_amount, 0)
    )
    SELECT 
        ps.id, ps.university_id, ps.code_university, ps.slug_university, ps.university,
        ps.course_id, ps.code_course, ps.course, ps.cycle_id, ps.code_cycle, ps.cycle,
        ps.start_date, ps.end_date, ps.is_topic_modified, ps.is_disabled, ps.is_deleteable, ps.created_at,
        (si.syllabus_id IS NOT NULL) AS is_inconsistent,
        ps.total_rows AS total
    FROM paginated_syllabus ps
    LEFT JOIN syllabus_inconsistencies si ON si.syllabus_id = ps.id;
END;
$$;


ALTER FUNCTION odiseo.fn_syllabus(p_perpage integer, p_npage integer, f_course_ids jsonb, f_university_ids jsonb, f_cycle_id bigint, f_cycle_active boolean, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_syllabus_all(smallint, smallint, bigint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_syllabus_all(f_university_id smallint, f_course_id smallint, f_cycle_id bigint, f_type_material_id smallint, p_company_id bigint) RETURNS TABLE(id bigint, university_id smallint, university character varying, course_id bigint, course character varying, cycle_id bigint, cycle character varying)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        SELECT DISTINCT
            s.id, s.university_id, u.name AS university,
            s.course_id, co.name AS course,
            s.cycle_id, cy.description AS cycle
        FROM syllabus s
        INNER JOIN origin_university u ON s.university_id = u.id
        INNER JOIN course co ON s.course_id = co.id
        INNER JOIN cycle cy ON s.cycle_id = cy.id
        LEFT JOIN syllabus_topic st ON s.id = st.syllabus_id AND st.fl_status = true
        LEFT JOIN syllabus_topic_week tw ON st.id = tw.syllabus_topic_id AND tw.fl_status = true
        LEFT JOIN syllabus_detail_subtopic ds ON tw.id = ds.syllabus_topic_week_id AND ds.fl_status = true
        LEFT JOIN syllabus_subtopic_type_material stm ON ds.id = stm.syllabus_detail_subtopic_id AND stm.fl_status = true
        WHERE u.deleted_by IS NULL
        AND u.fl_active = true
        AND (f_university_id IS NULL OR s.university_id = f_university_id)
        AND (f_course_id IS NULL OR s.course_id = f_course_id)
        AND (f_cycle_id IS NULL OR s.cycle_id = f_cycle_id)
        AND (f_type_material_id IS NULL OR stm.type_material_id = f_type_material_id)
        AND s.company_id = p_company_id
        ORDER BY s.university_id ASC;
    END;
    $$;


ALTER FUNCTION odiseo.fn_syllabus_all(f_university_id smallint, f_course_id smallint, f_cycle_id bigint, f_type_material_id smallint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_syllabus_categories_weeks(bigint, smallint, smallint, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_syllabus_categories_weeks(p_material_id bigint, p_type_material_id smallint, p_week smallint, p_course_id integer, p_company_id integer) RETURNS TABLE(category_id bigint, subcategory_id bigint, category character varying, subcategory character varying, position_type_text smallint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    C_STARTING_WEEK  CONSTANT SMALLINT := 1;
    C_EXAM_TYPE_TWO  CONSTANT VARCHAR  := 'Tipo 2';
    C_EXAM_TYPE_THREE CONSTANT VARCHAR := 'Tipo 3';
BEGIN
    RETURN QUERY
    WITH
    -- ─── 1. Contexto base del material ────────────────────────────────────────
    material_context AS (
        SELECT
            m.cycle_id,
            m.university_id
        FROM material m
        WHERE m.id = p_material_id
        LIMIT 1
    ),

    -- ─── 2. Clasificación del tipo de material ────────────────────────────────
    material_type_children AS (
        SELECT material_ids::JSONB
        FROM fn_get_children_material_type_ids(
            p_type_material_id,
            (SELECT mc.cycle_id FROM material_context mc)
        )
        LIMIT 1
    ),
    material_type_is_exam AS (
        SELECT tm.fl_exam AS is_exam
        FROM type_material tm
        JOIN type_material_template tmt
            ON tmt.id = tm.type_material_template_id
           AND tm.id  = p_type_material_id
    ),
    material_type_exam_label AS (
        SELECT txs.name AS exam_type_name
        FROM type_material tm
        JOIN type_material_template tmt
            ON tmt.id = tm.type_material_template_id
           AND tm.id  = p_type_material_id
        JOIN type_exams txs ON txs.id = tmt.type_exam_id
    ),

    -- ─── 3. Rango de semanas del sílabo ───────────────────────────────────────
    syllabus_max_week AS (
        SELECT MAX(stw.week) AS week
        FROM syllabus s
        JOIN syllabus_text_weeks stw ON stw.syllabus_id = s.id
        WHERE s.university_id = (SELECT mc.university_id FROM material_context mc)
          AND s.cycle_id      = (SELECT mc.cycle_id      FROM material_context mc)
          AND (p_course_id IS NULL OR s.course_id = p_course_id)
          AND stw.fl_status IS TRUE
    ),

    -- ─── 4. Resolución del rango efectivo de semanas ──────────────────────────
    --   Centraliza la lógica condicional que antes vivía en el WHERE final,
    effective_week_range AS (
        SELECT
            C_STARTING_WEEK AS week_from,
            CASE
                WHEN EXISTS (SELECT 1 FROM material_type_exam_label WHERE exam_type_name = C_EXAM_TYPE_THREE)
                    THEN (SELECT week FROM syllabus_max_week)
                WHEN EXISTS (SELECT 1 FROM material_type_exam_label WHERE exam_type_name = C_EXAM_TYPE_TWO)
                    THEN p_week
                ELSE
                    p_week
            END AS week_to
        -- Nota: para el caso default (ni Tipo 2 ni Tipo 3),
        -- week_from = week_to = p_week → filtra exactamente esa semana.
    )

    -- ─── 5. Consulta principal ────────────────────────────────────────────────
    SELECT
        s4.type_text_id             AS category_id,
        s4.type_text_subcategory_id AS subcategory_id,
        t.name                      AS category,
        t2.name                     AS subcategory,
        t.position                  AS position_type_text
    FROM syllabus s
    JOIN syllabus_text_weeks        s2  ON s2.syllabus_id              = s.id  AND s2.fl_status IS TRUE
    JOIN syllabus_text_distributions s3 ON s3.syllabus_text_week_id    = s2.id AND s3.fl_status IS TRUE
    JOIN type_material              tm  ON tm.id                       = s3.type_material_id
    JOIN type_material_template     tmt ON tmt.id                      = tm.type_material_template_id
    JOIN syllabus_texts             s4  ON s4.syllabus_text_distribution_id = s3.id AND s4.fl_status IS TRUE
    JOIN type_text                  t   ON t.id                        = s4.type_text_id
    JOIN type_text_subcategories    t2  ON t2.id                       = s4.type_text_subcategory_id
    JOIN course_assigned_categories cac ON cac.type_text_id            = t.id AND cac.course_id = s.course_id and cac.deleted_at is null
    JOIN material_type_is_exam      te  ON TRUE
    WHERE s.fl_status IS TRUE
      AND s.university_id = (SELECT mc.university_id FROM material_context mc)
      AND s.cycle_id      = (SELECT mc.cycle_id      FROM material_context mc)
      AND s.course_id     = p_course_id
      AND s.company_id    = p_company_id
      AND s2.week BETWEEN (SELECT week_from FROM effective_week_range)
                      AND (SELECT week_to   FROM effective_week_range)
      AND (
              (te.is_exam IS TRUE AND tmt.fl_use_syllabus_exam IS TRUE)
          OR  NOT EXISTS (SELECT material_ids FROM material_type_children)
          OR  s3.type_material_id IN (
                  SELECT JSONB_ARRAY_ELEMENTS_TEXT(
                      (SELECT material_ids FROM material_type_children)
                  )::SMALLINT
              )
      );
END;
$$;


ALTER FUNCTION odiseo.fn_syllabus_categories_weeks(p_material_id bigint, p_type_material_id smallint, p_week smallint, p_course_id integer, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_syllabus_subtopics_weeks(bigint, smallint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_syllabus_subtopics_weeks(p_material_id bigint, p_type_material_id smallint, p_week smallint, p_company_id bigint) RETURNS TABLE(id bigint, type_material_id smallint, amount_type_mat smallint, subtopic_id smallint, code_subtopic character varying, subtopic character varying, week smallint, topic_id smallint, code_topic character varying, topic character varying, course_id bigint, code_course character varying, course character varying, syllabus_id bigint)
    LANGUAGE plpgsql
    AS $$
                    DECLARE
                        v_cycle_id BIGINT;
                        v_university_id SMALLINT;
                        v_fl_exam BOOLEAN;
                        v_type_exam_id BIGINT;
                        v_weeks JSONB;
                        v_type_material_ids JSONB;
                    BEGIN
                        -- Obtener ciclo y universidad del material mandado
                        SELECT
                            m.cycle_id, m.university_id INTO v_cycle_id, v_university_id
                        FROM material m
                        LEFT JOIN cycle c ON m.cycle_id = c.id
                        WHERE m.id = p_material_id
                        LIMIT 1;

                        -- Obtener data del tipo material
                        SELECT
                            tmt.fl_exam, tmt.type_exam_id INTO v_fl_exam, v_type_exam_id
                        FROM type_material tm
                        INNER JOIN type_material_template tmt ON tm.type_material_template_id = tmt.id
                        WHERE tm.id = p_type_material_id
                        LIMIT 1;

                        IF v_fl_exam IS FALSE THEN
                            SELECT
                                material_ids INTO v_type_material_ids
                            FROM fn_get_children_material_type_ids(p_type_material_id, v_cycle_id)
                            LIMIT 1;
                        END IF;

                        IF v_fl_exam IS TRUE AND v_type_exam_id = 3 THEN
                            v_weeks := '[]'::jsonb;
                            FOR i IN 1..p_week LOOP
                                v_weeks := v_weeks || to_jsonb(i);
                            END LOOP;
                        ELSIF v_fl_exam IS TRUE AND v_type_exam_id = 4 THEN
                            v_weeks := NULL;
                        ELSE
                            v_weeks := jsonb_build_array(p_week);
                        END IF;

                        RETURN QUERY
                        SELECT
                            stm.id,
                            stm.type_material_id,
                            stm.questions_amount AS amount_type_mat,
                            sds.subtopic_id,
                            su.code AS code_subtopic,
                            su.name AS subtopic,
                            stw.week,
                            st.topic_id,
                            top.code AS code_topic,
                            top.name AS topic,
                            s.course_id,
                            co.code AS code_course,
                            co.name AS course,
                            s.id AS syllabus_id
                        FROM syllabus_subtopic_type_material stm
                        INNER JOIN syllabus_detail_subtopic sds ON stm.syllabus_detail_subtopic_id = sds.id
                            AND sds.fl_status = true
                            AND sds.company_id = p_company_id
                        INNER JOIN syllabus_topic_week stw ON sds.syllabus_topic_week_id = stw.id
                            AND stw.fl_status = true
                            AND stw.company_id = p_company_id
                        INNER JOIN syllabus_topic st ON stw.syllabus_topic_id = st.id
                            AND st.fl_status = true
                            AND st.company_id = p_company_id
                        INNER JOIN syllabus s ON st.syllabus_id = s.id
                            AND s.company_id = p_company_id
                        INNER JOIN course co ON s.course_id = co.id
                        INNER JOIN topic top ON st.topic_id = top.id
                        INNER JOIN subtopic su ON sds.subtopic_id = su.id
                        WHERE stm.fl_status = true
                            AND s.fl_status = true
                            AND (
                                v_type_material_ids IS NULL
                                OR stm.type_material_id IN (
                                    SELECT jsonb_array_elements_text(v_type_material_ids)::SMALLINT
                                )
                            )
                            AND s.university_id = v_university_id
                            AND s.cycle_id = v_cycle_id
                            AND (
                                v_weeks IS NULL
                                OR stw.week IN (
                                    SELECT jsonb_array_elements_text(v_weeks)::SMALLINT
                                )
                            )
                            AND stm.questions_amount > 0
                            AND stm.company_id = p_company_id
                        ORDER BY s.course_id ASC, st.topic_id ASC, sds.subtopic_id ASC;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_syllabus_subtopics_weeks(p_material_id bigint, p_type_material_id smallint, p_week smallint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_sync_employees_to_teachers(); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_sync_employees_to_teachers() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                        -- El cargo_id 2 corresponde a docentes
                        IF NEW.charge_id = 2 THEN
                            INSERT INTO teachers (
                                employee_id,
                                code,
                                limit_assigned_questions,
                                limit_assigned_questions_initial,
                                fl_unlimit_questions,
                                level_rate_id,
                                goal,
                                lot,
                                fl_active,
                                company_id,
                                fl_resolve_missing_questions,
                                limit_missing_questions,
                                created_by,
                                updated_by,
                                deleted_by,
                                created_at,
                                updated_at,
                                deleted_at
                            )
                            VALUES (
                                NEW.id,
                                NEW.code,
                                NEW.limit_assigned_questions,
                                NEW.limit_assigned_questions_initial,
                                NEW.fl_unlimit_questions,
                                NEW.level_id,
                                NEW.goal,
                                NEW.lot,
                                NEW.fl_status,
                                NEW.company_id,
                                NEW.fl_resolve_missing_questions,
                                NEW.limit_missing_questions,
                                NEW.created_by,
                                NEW.updated_by,
                                NEW.deleted_by,
                                NEW.created_at,
                                NEW.updated_at,
                                NEW.deleted_at
                            )
                            ON CONFLICT (employee_id) DO UPDATE SET
                                code = EXCLUDED.code,
                                limit_assigned_questions = EXCLUDED.limit_assigned_questions,
                                limit_assigned_questions_initial = EXCLUDED.limit_assigned_questions_initial,
                                fl_unlimit_questions = EXCLUDED.fl_unlimit_questions,
                                level_rate_id = EXCLUDED.level_rate_id,
                                goal = EXCLUDED.goal,
                                lot = EXCLUDED.lot,
                                fl_active = EXCLUDED.fl_active,
                                company_id = EXCLUDED.company_id,
                                fl_resolve_missing_questions = EXCLUDED.fl_resolve_missing_questions,
                                limit_missing_questions = EXCLUDED.limit_missing_questions,
                                updated_by = EXCLUDED.updated_by,
                                deleted_by = EXCLUDED.deleted_by,
                                updated_at = EXCLUDED.updated_at,
                                deleted_at = EXCLUDED.deleted_at;
                        ELSE
                            -- Si es que el docente estaba antes y ahora ya no es docente, eliminarlo logicamente.
                            UPDATE teachers
                            SET deleted_at = NOW(),
                            deleted_by = NEW.updated_by
                            WHERE employee_id = NEW.id
                            AND deleted_at IS NULL;
                        END IF;

                        RETURN NEW;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_sync_employees_to_teachers() OWNER TO postgres;

--
-- Name: fn_sync_material_revision_status(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_sync_material_revision_status(p_revision_id bigint, p_user_id bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total_slots  integer;
    v_filled_slots integer;
    v_current_status varchar;
    v_new_status     varchar;
BEGIN
    -- 1. Obtener estado actual
    SELECT status INTO v_current_status
    FROM material_revisions
    WHERE id = p_revision_id;

    IF NOT FOUND THEN RETURN; END IF;

    -- 2. Contar slots de preguntas para este material/semanas
    -- Buscamos en base a los items (detail_week_type_mat) registrados en la revisión
    SELECT 
        COUNT(*),
        COUNT(*) FILTER (WHERE question_id IS NOT NULL OR parent_question_id IS NOT NULL)
    INTO v_total_slots, v_filled_slots
    FROM material_ballot_question
    WHERE week_type_material_id IN (
        SELECT detail_week_type_mat_id 
        FROM material_revision_items 
        WHERE material_revision_id = p_revision_id 
          AND deleted_at IS NULL
    )
    AND fl_status = true;

    -- 3. Determinar nuevo estado
    -- Si no hay slots (caso raro), lo consideramos completo
    IF v_total_slots = 0 OR v_total_slots = v_filled_slots THEN
        v_new_status := 'pdf_delivered';
    ELSE
        v_new_status := 'generating';
    END IF;

    -- 4. Actualizar si hay cambio
    -- Regla: Si ya está en 'material_delivered', no retrocedemos automáticamente? 
    -- El usuario dice: "quiten una pregunta y este deberia de cambiar de estado"
    -- Así que si cambia de completo a incompleto, retrocedemos siempre.
    -- Si cambia de incompleto a completo, avanzamos solo si no estaba ya verificado/entregado.
    
    IF v_new_status = 'generating' AND v_current_status IN ('pdf_delivered', 'verified', 'material_delivered') THEN
        -- Retroceso por falta de preguntas
        UPDATE material_revisions
        SET status = v_new_status,
            updated_at = NOW(),
            updated_by = p_user_id
        WHERE id = p_revision_id;

        INSERT INTO material_revision_histories (
            material_revision_id, old_status, new_status, changed_by, changed_at
        ) VALUES (
            p_revision_id, v_current_status, v_new_status, p_user_id, NOW()
        );
    ELSIF v_new_status = 'pdf_delivered' AND v_current_status IN ('queued', 'generating') THEN
        -- Avance automático por completitud
        UPDATE material_revisions
        SET status = v_new_status,
            updated_at = NOW(),
            updated_by = p_user_id
        WHERE id = p_revision_id;

        INSERT INTO material_revision_histories (
            material_revision_id, old_status, new_status, changed_by, changed_at
        ) VALUES (
            p_revision_id, v_current_status, v_new_status, p_user_id, NOW()
        );
    END IF;
END;
$$;


ALTER FUNCTION odiseo.fn_sync_material_revision_status(p_revision_id bigint, p_user_id bigint) OWNER TO postgres;

--
-- Name: fn_sync_parent_question_with_subquestions_status(bigint, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_sync_parent_question_with_subquestions_status(p_question_id bigint, p_status character varying, p_updated_by bigint) RETURNS TABLE(parent_question_id bigint, code character varying, status character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_parent_id BIGINT;
BEGIN
    /*
        Función para sincronizar el estado del texto padre
        cuando todas las subpreguntas tienen el mismo estado.
    */

    -- Obtener parent_id del hijo
    SELECT q.parent_id
      INTO v_parent_id
    FROM question q
    WHERE q.id = p_question_id;

    -- Si no tiene padre, salir
    IF v_parent_id IS NULL THEN
        RETURN;
    END IF;

    RETURN QUERY
    UPDATE parent_question pq
       SET status = p_status,
           updated_by = p_updated_by,
           updated_at = NOW()
     WHERE pq.id = v_parent_id
       -- Solo actualizar si el estado actual es diferente
       AND pq.status <> p_status
       -- Validar que TODOS los hijos tengan el estado esperado
       AND NOT EXISTS (
            SELECT 1
            FROM question q
            WHERE q.parent_id = v_parent_id
              AND q.status <> p_status
       )
    RETURNING pq.id, pq.code, pq.status;
END;
$$;


ALTER FUNCTION odiseo.fn_sync_parent_question_with_subquestions_status(p_question_id bigint, p_status character varying, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_sync_type_material_template_configuration_columns(bigint, bigint, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_sync_type_material_template_configuration_columns(p_type_material_template_id bigint, p_user_id bigint, p_settings jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_now  timestamp := NOW();
    v_role text;
BEGIN

    SELECT CASE
        WHEN EXISTS (SELECT 1 FROM type_material_bound tmb
                     WHERE tmb.type_material_template_id       = p_type_material_template_id AND tmb.fl_status = true) THEN 'PARENT'
        WHEN EXISTS (SELECT 1 FROM type_material_bound tmb
                     WHERE tmb.type_material_template_extra_id = p_type_material_template_id AND tmb.fl_status = true) THEN 'CHILD'
        ELSE 'UNIQUE'
    END INTO v_role;

    IF v_role = 'CHILD' THEN
        UPDATE type_material_template_configuration_columns
           SET deleted_at = v_now, deleted_by = p_user_id
         WHERE type_material_template_id = p_type_material_template_id
           AND deleted_at IS NULL;

        UPDATE type_material_template
           SET has_config_column = false, updated_at = v_now, updated_by = p_user_id
         WHERE id = p_type_material_template_id;
        RETURN;
    END IF;

    IF v_role = 'PARENT' THEN
        UPDATE type_material_template_configuration_columns t
           SET deleted_at = v_now, deleted_by = p_user_id
         WHERE t.deleted_at IS NULL
           AND EXISTS (SELECT 1 FROM type_material_bound b
                       WHERE b.type_material_template_extra_id = t.type_material_template_id
                         AND b.type_material_template_id       = p_type_material_template_id
                         AND b.fl_status = true);

        UPDATE type_material_template t
           SET has_config_column = false, updated_at = v_now, updated_by = p_user_id
         WHERE EXISTS (SELECT 1 FROM type_material_bound b
                       WHERE b.type_material_template_extra_id = t.id
                         AND b.type_material_template_id       = p_type_material_template_id
                         AND b.fl_status = true);
    END IF;

    WITH settings AS (
        SELECT
            NULLIF(col->>'type_solution', '')                    AS type_solution,
            COALESCE(NULLIF(col->>'number_columns', '')::int, 1) AS number_columns
        FROM jsonb_array_elements(
            CASE
                WHEN p_settings IS NULL                      THEN '[]'::jsonb
                WHEN jsonb_typeof(p_settings) = 'array'      THEN p_settings
                ELSE '[]'::jsonb
            END
        ) col
        WHERE COALESCE((col->>'has_config_columns')::boolean, FALSE) = TRUE
    ),

    deleted AS (
        UPDATE type_material_template_configuration_columns t
           SET deleted_at = v_now, deleted_by = p_user_id
         WHERE t.type_material_template_id = p_type_material_template_id
           AND t.deleted_at IS NULL
           AND NOT EXISTS (SELECT 1 FROM settings s
                           WHERE s.type_solution IS NOT DISTINCT FROM t.type_solution
                             AND s.number_columns = t.number_columns)
        RETURNING 1
    ),

    restored AS (
        UPDATE type_material_template_configuration_columns t
           SET deleted_at = NULL,
               deleted_by = NULL,
               updated_at = v_now,
               updated_by = p_user_id
         WHERE t.type_material_template_id = p_type_material_template_id
           AND t.deleted_at IS NOT NULL
           AND EXISTS (SELECT 1 FROM settings s
                       WHERE s.type_solution IS NOT DISTINCT FROM t.type_solution
                         AND s.number_columns = t.number_columns)
        RETURNING 1
    ),

    inserted AS (
        INSERT INTO type_material_template_configuration_columns
            (type_material_template_id, type_solution, number_columns, created_at, created_by)
        SELECT p_type_material_template_id, s.type_solution, s.number_columns, v_now, p_user_id
        FROM settings s
        WHERE NOT EXISTS (
            SELECT 1 FROM type_material_template_configuration_columns t
             WHERE t.type_material_template_id = p_type_material_template_id
               AND t.type_solution IS NOT DISTINCT FROM s.type_solution
               AND t.number_columns = s.number_columns
        )
    )

    UPDATE type_material_template
       SET has_config_column = EXISTS (SELECT 1 FROM settings),
           updated_at = v_now, updated_by = p_user_id
     WHERE id = p_type_material_template_id;

END;
$$;


ALTER FUNCTION odiseo.fn_sync_type_material_template_configuration_columns(p_type_material_template_id bigint, p_user_id bigint, p_settings jsonb) OWNER TO postgres;

--
-- Name: fn_teacher_all(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_teacher_all(p_company_id bigint) RETURNS TABLE(id bigint, value text, courses json, fl_status boolean)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    e.id,
                    CONCAT(e.code, ' - ', e.first_name, ' ', e.first_surname, ' ', e.second_surname) as value,
                    CASE
                        WHEN count(c.id) > 0 THEN json_agg(c.*)
                        ELSE '[]'::json
                    END AS courses,
                    e.fl_status
                FROM employees e
                INNER JOIN employee_course ec ON e.id = ec.teacher_id AND ec.fl_status = true
                INNER JOIN users u ON e.user_id = u.id AND u.fl_status = true and u.fl_suspended = false
                INNER JOIN users_roles ur ON e.user_id = ur.user_id AND ur.fl_status = true
                INNER JOIN (SELECT c.id, c.code, c.name, c.fl_status FROM course c WHERE c.fl_status = true ORDER BY c.id ASC) c ON ec.course_id = c.id
                WHERE e.fl_status = true
                    AND (ur.rol_id = 11 OR charge_id = 2)
                    AND e.company_id = p_company_id
                GROUP BY
                    e.id,
                    value,
                    e.fl_status
                ORDER BY e.id ASC;
            END;
            $$;


ALTER FUNCTION odiseo.fn_teacher_all(p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_teacher_assigned_question(integer, integer, character varying, bigint, character varying, smallint, smallint, smallint, smallint, smallint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_teacher_assigned_question(p_perpage integer, p_npage integer, p_name_text character varying, p_employee_id bigint, f_status character varying, f_course_id smallint, f_university_id smallint, f_option_id smallint, f_modality_id smallint, f_version smallint, f_year character varying) RETURNS TABLE(key_question text, id bigint, code character varying, short_description text, number_question character varying, number character varying, course_id smallint, code_course character varying, course character varying, status character varying, parent_id bigint, type_question text, teacher_id bigint, code_teacher character varying, teacher text, date_status timestamp without time zone, total_refuzed bigint, subquestions jsonb, question_origin jsonb, priority integer, is_missing_question boolean, total_observed bigint, total bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    C_MORE_RECENT_VERSION smallint DEFAULT 1;
    C_FORWARD_STATUS varchar[] := ARRAY['INDE', 'DASI', 'OBSE', 'DIG', 'VERI', 'APRB', 'PEND', 'RESV'];
    offset_val integer := p_perpage * (p_npage - 1);
    status_array varchar[];
BEGIN
    -- Manejo del parámetro f_status
    IF f_status IS NULL OR f_status = '' OR f_status NOT IN ('ASIG', 'RESO', 'SSOL', 'RECH') THEN
        status_array := ARRAY['ASIG', 'RESO', 'SSOL', 'RECH'];
    ELSE
        status_array := ARRAY[f_status];
    END IF;
    RETURN QUERY WITH employee_course AS (
        SELECT
            ec.course_id
        FROM
            employee_course ec
        WHERE (p_employee_id IS NULL
            OR ec.teacher_id = p_employee_id)
),
asig_questions AS (
    SELECT
        q.*,
        qn.question_origin,
        qn.university_id,
        qn.option_id,
        qn.modality_id,
        qn."version",
        qn."year"
    FROM
        question q
        LEFT JOIN v_all_question_origins qn ON qn.question_id = q.id
    WHERE
        1 = 1
        AND q.fl_status = TRUE
        AND (q.parent_id IS NULL
            AND q.status = ANY (ARRAY[status_array])
            OR q.parent_id IS NOT NULL
            AND (q.status = ANY (ARRAY[status_array])
                OR q.status = ANY (ARRAY[C_FORWARD_STATUS])))
        AND q.deleted_at IS NULL
        AND (f_university_id IS NULL
            OR qn.university_id = f_university_id)
        AND (f_option_id IS NULL
            OR qn.option_id = f_option_id)
        AND (f_modality_id IS NULL
            OR qn.modality_id = f_modality_id)
        AND (f_version IS NULL
            OR qn."version" = f_version)
        AND (f_year IS NULL
            OR qn."year" = f_year)
),
questions AS (
    SELECT
        concat('p_', q.id) AS key_question,
        q.id,
        q.code,
        q.short_description,
        q.number_question,
        q.number,
        q.course_id,
        c.code AS code_course,
        c.name AS course,
        q.status,
        q.parent_id,
        CASE WHEN q.parent_id IS NULL THEN
            'P'
        ELSE
            'S'
        END AS type_question,
        es1.id AS teacher_id,
        es1.code AS code_teacher,
        CONCAT(es1.first_surname, ' ', es1.second_surname, ' ', es1.first_name) AS teacher,
        qs.created_at AS date_status,
        (
            SELECT
                COUNT(*)
            FROM
                question_refuzed qr2
            WHERE
                qr2.question_id = q.id
                AND qr2.fl_status = TRUE) AS total_refuzed,
            q.question_origin,
            q.priority,
            CASE WHEN mmqd.question_id IS NOT NULL THEN
                TRUE
            ELSE
                FALSE
            END AS is_missing_question
        FROM
            asig_questions q
            INNER JOIN course c ON q.course_id = c.id
            LEFT JOIN question_status qs ON qs.fl_active = TRUE
                AND q.id = qs.question_id
                AND q.status = qs.status
            INNER JOIN employee_question eq ON eq.question_id = q.id
                AND eq.fl_status = TRUE
            INNER JOIN employees es1 ON eq.teacher_id = es1.id
            LEFT JOIN material_missing_question_detail mmqd ON mmqd.question_id = q.id
        WHERE
            1 = 1
            AND (p_employee_id IS NULL
                OR es1.id = p_employee_id)
),
sub_questions AS (
    SELECT
        pq.id AS parent_id,
        jsonb_agg(jsonb_build_object('key_question', concat('s_', q.id), 'id', q.id, 'code', q.code, 'short_description', q.short_description, 'number_question', q.number_question, 'number', q.number, 'course_id', q.course_id, 'code_course', c.code, 'course', c.name, 'status', q.status, 'parent_id', q.parent_id, 'type_question', 'S', 'teacher_id', es1.id, 'code_teacher', es1.code, 'teacher', CONCAT(es1.first_surname, ' ', es1.second_surname, ' ', es1.first_name), 'date_status', qs.created_at, 'total_refuzed', (
                    SELECT
                        COUNT(*)
                    FROM question_refuzed qr
                    WHERE
                        qr.question_id = q.id
                        AND qr.fl_status = TRUE), 'origin_question', q.question_origin)) AS subquestions
    FROM
        asig_questions q
        INNER JOIN parent_question pq ON q.parent_id = pq.id
            AND pq.status = ANY (ARRAY[status_array])
            INNER JOIN course c ON q.course_id = c.id
            LEFT JOIN question_status qs ON q.id = qs.question_id
                AND q.status = qs.status
                AND qs.fl_active = TRUE
            INNER JOIN employee_question eq ON eq.question_id = q.id
                AND eq.fl_status = TRUE
            INNER JOIN employees es1 ON eq.teacher_id = es1.id
        WHERE
            1 = 1
            AND (p_employee_id IS NULL
                OR es1.id = p_employee_id)
        GROUP BY
            pq.id
),
tbl_question AS (
    SELECT
        concat('p_', q.id) AS key_question,
        q.id,
        q.code,
        q.short_description,
        q.number_question,
        q.number,
        q.course_id,
        q.code_course,
        q.course,
        q.status,
        q.parent_id,
        q.type_question,
        q.teacher_id,
        q.code_teacher,
        q.teacher,
        q.date_status,
        q.total_refuzed,
        COALESCE(sq.subquestions, '[]'::jsonb) AS subquestions,
        q.question_origin,
        q.priority,
        q.is_missing_question
    FROM
        questions q
        LEFT JOIN sub_questions sq ON q.parent_id = sq.parent_id
    WHERE
        q.parent_id IS NULL
    UNION ALL SELECT DISTINCT
        concat('t_', pq.id) AS key_question,
        pq.id,
        pq.code,
        pq.short_description,
        pq.number_question,
        pq.number,
        pq.course_id,
        c.code AS code_course,
        c.name AS course,
        pq.status,
        pq.id AS parent_id,
        'T' AS type_question,
        NULL::bigint AS teacher_id,
        NULL::varchar AS code_teacher,
        NULL::text AS teacher,
        pq.created_at AS date_status,
        0::bigint AS total_refuzed,
        COALESCE(sq.subquestions, '[]'::jsonb) AS subquestions,
        opq.question_origin,
        pq.priority,
        FALSE AS is_missing_question
    FROM
        parent_question pq
        INNER JOIN course c ON pq.course_id = c.id
        LEFT JOIN sub_questions sq ON pq.id = sq.parent_id
            AND sq.parent_id IS NOT NULL
        LEFT JOIN v_all_parent_origins opq ON opq.parent_id = pq.id
    WHERE
        pq.fl_status = TRUE
        AND pq.status <> 'DUPL'
        AND pq.deleted_at IS NULL
        AND (sq.subquestions <> '[]')
        AND (f_university_id IS NULL
            OR opq.university_id = f_university_id)
        AND (f_option_id IS NULL
            OR opq.option_id = f_option_id)
        AND (f_modality_id IS NULL
            OR opq.modality_id = f_modality_id)
        AND (f_version IS NULL
            OR opq."version" = f_version)
        AND (f_year IS NULL
            OR opq."year" = f_year)
),
observed_questions AS (
    SELECT
        q.id,
        COUNT(*) total_observed
    FROM
        question q
        JOIN question_status qs ON qs.question_id = q.id
    WHERE
        q.status = 'DIGI'
        AND qs.status = 'OBSE'
    GROUP BY
        q.id
),
filtered_questions AS (
    SELECT
        tq.*,
        oq.total_observed
    FROM
        tbl_question tq
        LEFT JOIN observed_questions oq ON oq.id = tq.id
    WHERE (f_course_id IS NULL
        OR tq.course_id = f_course_id)
    AND (p_employee_id IS NULL
        OR tq.course_id IN (
            SELECT
                *
            FROM
                employee_course))
        AND (p_name_text IS NULL
            OR unaccent(LOWER(tq.short_description))
            LIKE '%' || LOWER(p_name_text) || '%'
            OR LOWER(tq.number_question)
            LIKE '%' || LOWER(p_name_text) || '%'
            OR LOWER(tq.number)
            LIKE '%' || LOWER(p_name_text) || '%'
            OR LOWER(tq.code)
            LIKE '%' || LOWER(p_name_text) || '%'
            OR EXISTS (
                SELECT
                    1
                FROM
                    jsonb_array_elements(tq.subquestions) AS sq
                WHERE
                    unaccent(LOWER(sq ->> 'short_description'))
                    LIKE '%' || LOWER(p_name_text) || '%'
                    OR LOWER(sq ->> 'number_question')
                    LIKE '%' || LOWER(p_name_text) || '%'
                    OR LOWER(sq ->> 'number')
                    LIKE '%' || LOWER(p_name_text) || '%'
                    OR LOWER(sq ->> 'code')
                    LIKE '%' || LOWER(p_name_text) || '%'))
),
counted_questions AS (
    SELECT
        *,
        count(*) OVER () AS total
    FROM
        filtered_questions
)
SELECT
    *
FROM
    counted_questions
ORDER BY
    priority DESC,
    date_status ASC,
    key_question ASC
LIMIT p_perpage OFFSET offset_val;
END;
$$;


ALTER FUNCTION odiseo.fn_teacher_assigned_question(p_perpage integer, p_npage integer, p_name_text character varying, p_employee_id bigint, f_status character varying, f_course_id smallint, f_university_id smallint, f_option_id smallint, f_modality_id smallint, f_version smallint, f_year character varying) OWNER TO postgres;

--
-- Name: fn_teacher_digitalized_questions(integer, integer, character varying, bigint, character varying, smallint, smallint, smallint, smallint, smallint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_teacher_digitalized_questions(p_perpage integer, p_npage integer, p_name_text character varying, p_employee_id bigint, f_status character varying, f_course_id smallint, f_university_id smallint, f_option_id smallint, f_modality_id smallint, f_version smallint, f_year character varying) RETURNS TABLE(key_question text, id bigint, code character varying, short_description text, number_question character varying, number character varying, course_id smallint, code_course character varying, course character varying, status character varying, parent_id bigint, type_question text, teacher_id bigint, teacher text, didi_id bigint, didi text, url_pdf_index character varying, url_pdf_digitalized character varying, date_status timestamp without time zone, observation text, subquestions jsonb, origin_question jsonb, priority integer, is_missing_question boolean, total_observed bigint, total bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    offset_val integer := p_perpage * (p_npage - 1);
BEGIN
    RETURN QUERY WITH employee_course AS (
        SELECT DISTINCT
            ec.course_id
        FROM
            employee_course ec
        WHERE (p_employee_id IS NULL
            OR ec.teacher_id = p_employee_id)
    ORDER BY
        ec.course_id ASC
),
digi_questions AS (
    SELECT
        q.id,
        q.code,
        q.short_description,
        q.number_question,
        q.number,
        q.course_id,
        q.status,
        q.parent_id,
        qn.question_origin,
        qn.university_id,
        qn.option_id,
        qn.modality_id,
        qn."version",
        qn."year",
        q.priority,
        CASE WHEN mmqd.question_id IS NOT NULL THEN
            TRUE
        ELSE
            FALSE
        END AS is_missing_question
    FROM
        question q
        LEFT JOIN v_all_question_origins qn ON qn.question_id = q.id
        LEFT JOIN material_missing_question_detail mmqd ON mmqd.question_id = q.id
    WHERE
        1 = 1
        AND q.fl_status = TRUE
        AND q.parent_id IS NULL
        AND q.status IN ('DIGI', 'OBSE')
        AND q.deleted_at IS NULL
        AND (f_university_id IS NULL
            OR qn.university_id = f_university_id)
        AND (f_option_id IS NULL
            OR qn.option_id = f_option_id)
        AND (f_modality_id IS NULL
            OR qn.modality_id = f_modality_id)
        AND (f_version IS NULL
            OR qn."version" = f_version)
        AND (f_year IS NULL
            OR qn."year" = f_year)
),
questions AS (
    SELECT
        concat('p_', q.id) AS key_question,
        q.id,
        q.code,
        q.short_description,
        q.number_question,
        q.number,
        q.course_id,
        c.code AS code_course,
        c.name AS course,
        q.status,
        q.parent_id,
        CASE WHEN q.parent_id IS NULL THEN
            'P'
        ELSE
            'S'
        END AS type_question,
        es1.id AS teacher_id,
        CONCAT(es1.first_surname, ' ', es1.second_surname, ' ', es1.first_name) AS teacher,
        es2.id AS didi_id,
        CONCAT(es2.first_surname, ' ', es2.second_surname, ' ', es2.first_name) AS didi,
        eq.url_pdf_question_solution AS url_pdf_index,
        edq.url_file_digitalized_solution AS url_pdf_digitalized,
        qs.created_at AS date_status,
        qo.description AS observation,
        q.question_origin,
        q.priority,
        q.is_missing_question
    FROM
        digi_questions q
        INNER JOIN course c ON q.course_id = c.id
        LEFT JOIN question_status qs ON qs.fl_active = TRUE
            AND q.id = qs.question_id
            AND q.status = qs.status
        INNER JOIN employee_question eq ON eq.question_id = q.id
            AND eq.fl_status = TRUE
        LEFT JOIN employees es1 ON eq.teacher_id = es1.id
        INNER JOIN employee_didi_question edq ON edq.question_id = q.id
            AND edq.fl_status = TRUE
        LEFT JOIN employees es2 ON edq.employee_id = es2.id
        LEFT JOIN question_observation qo ON qo.question_id = q.id
            AND qo.fl_status = TRUE
            AND qo.type IN ('DIGI', 'OBSE')
    WHERE
        1 = 1
        AND (p_employee_id IS NULL
            OR es1.id = p_employee_id)
        AND q.parent_id IS NULL
),
tbl_question AS (
    SELECT
        concat('p_', q.id) AS key_question,
        q.id,
        q.code,
        q.short_description,
        q.number_question,
        q.number,
        q.course_id,
        q.code_course,
        q.course,
        q.status,
        q.parent_id,
        q.type_question,
        q.teacher_id,
        q.teacher,
        q.didi_id,
        q.didi,
        q.url_pdf_index,
        q.url_pdf_digitalized,
        q.date_status,
        q.observation,
        '[]'::jsonb AS subquestions,
        q.question_origin,
        q.priority,
        q.is_missing_question
    FROM
        questions q
    UNION ALL SELECT DISTINCT
        concat('t_', pq.id) AS key_question,
        pq.id,
        pq.code,
        pq.short_description,
        pq.number_question,
        pq.number,
        pq.course_id,
        c.code AS code_course,
        c.name AS course,
        pq.status,
        pq.id AS parent_id,
        'T' AS type_question,
        NULL::bigint AS teacher_id,
        NULL::text AS teacher,
        NULL::bigint AS didi_id,
        NULL::text AS didi,
        NULL::text AS url_pdf_index,
        NULL::text AS url_pdf_digitalized,
        pq.created_at AS date_status,
        NULL::text AS observation,
        JSONB_AGG(JSONB_BUILD_OBJECT('key_question', concat('s_', q.id), 'id', q.id, 'code', q.code, 'short_description', q.short_description, 'number_question', q.number_question, 'number', q.number, 'course_id', q.course_id, 'code_course', c.code, 'course', c.name, 'status', q.status, 'parent_id', q.parent_id, 'type_question', 'S', 'teacher_id', es1.id, 'teacher', CONCAT(es1.first_surname, ' ', es1.second_surname, ' ', es1.first_name), 'didi_id', es2.id, 'didi', CONCAT(es2.first_surname, ' ', es2.second_surname, ' ', es2.first_name), 'url_pdf_index', eq.url_pdf_question_solution, 'url_pdf_digitalized', edq.url_file_digitalized_solution, 'date_status', qs.created_at, 'observation', qo.description, 'origin_question', qn.question_origin)) AS subquestions,
        opq.question_origin,
        pq.priority,
        FALSE AS is_missing_question
    FROM
        parent_question pq
        JOIN question q ON pq.status IN ('DIGI', 'OBSE')
            AND pq.status <> 'DUPL'
            AND pq.id = q.parent_id
        LEFT JOIN question_status qs ON q.id = qs.question_id
            AND q.status = qs.status
            AND qs.fl_active IS TRUE
        INNER JOIN employee_question eq ON eq.question_id = q.id
            AND eq.fl_status IS TRUE
        LEFT JOIN employees es1 ON eq.teacher_id = es1.id
        INNER JOIN employee_didi_question edq ON edq.question_id = q.id
            AND edq.fl_status IS TRUE
        LEFT JOIN employees es2 ON edq.employee_id = es2.id
        LEFT JOIN question_observation qo ON qo.question_id = q.id
            AND qo.fl_status IS TRUE
        INNER JOIN course c ON pq.course_id = c.id
        LEFT JOIN v_all_question_origins qn ON qn.question_id = q.id
        LEFT JOIN v_all_parent_origins opq ON opq.parent_id = pq.id
    WHERE
        1 = 1
        AND pq.fl_status IS TRUE
        AND pq.deleted_at IS NULL
        AND (p_employee_id IS NULL
            OR es1.id = p_employee_id)
        AND (f_university_id IS NULL
            OR opq.university_id = f_university_id
            OR qn.university_id = f_university_id)
        AND (f_option_id IS NULL
            OR opq.option_id = f_option_id
            OR qn.option_id = f_option_id)
        AND (f_modality_id IS NULL
            OR opq.modality_id = f_modality_id
            OR qn.modality_id = f_modality_id)
        AND (f_version IS NULL
            OR opq."version" = f_version
            OR qn."version" = f_version)
        AND (f_year IS NULL
            OR opq."year" = f_year
            OR qn."year" = f_year)
    GROUP BY
        pq.id,
        opq.question_origin,
        c.id
    HAVING
        COUNT(q.*) > 0
),
observed_questions AS (
    SELECT
        q.id,
        COUNT(*) total_observed
    FROM
        question q
        JOIN question_status qs ON qs.question_id = q.id
    WHERE
        q.status = 'DIGI'
        AND qs.status = 'OBSE'
    GROUP BY
        q.id
),
filtered_questions AS (
    SELECT
        tbl_question.*,
        oq.total_observed
    FROM
        tbl_question
        LEFT JOIN observed_questions oq ON oq.id = tbl_question.id
    WHERE (f_course_id IS NULL
        OR tbl_question.course_id = f_course_id)
    AND (p_employee_id IS NULL
        OR tbl_question.course_id IN (
            SELECT
                *
            FROM
                employee_course))
        AND (p_name_text IS NULL
            OR unaccent(LOWER(tbl_question.short_description))
            LIKE '%' || LOWER(p_name_text) || '%'
            OR LOWER(tbl_question.number_question)
            LIKE '%' || LOWER(p_name_text) || '%'
            OR LOWER(tbl_question.number)
            LIKE '%' || LOWER(p_name_text) || '%'
            OR LOWER(tbl_question.code)
            LIKE '%' || LOWER(p_name_text) || '%'
            OR EXISTS (
                SELECT
                    1
                FROM
                    jsonb_array_elements(tbl_question.subquestions) AS sq
                WHERE
                    unaccent(LOWER(sq ->> 'short_description'))
                    LIKE '%' || LOWER(p_name_text) || '%'
                    OR LOWER(sq ->> 'number_question')
                    LIKE '%' || LOWER(p_name_text) || '%'
                    OR LOWER(sq ->> 'number')
                    LIKE '%' || LOWER(p_name_text) || '%'
                    OR LOWER(sq ->> 'code')
                    LIKE '%' || LOWER(p_name_text) || '%'))
            AND (f_status IS NULL
                OR tbl_question.status = f_status)
),
counted_questions AS (
    SELECT
        *,
        count(*) OVER () AS total
    FROM
        filtered_questions
)
SELECT
    *
FROM
    counted_questions
ORDER BY
    priority DESC NULLS LAST,
    date_status ASC,
    key_question ASC
LIMIT p_perpage OFFSET offset_val;
END;
$$;


ALTER FUNCTION odiseo.fn_teacher_digitalized_questions(p_perpage integer, p_npage integer, p_name_text character varying, p_employee_id bigint, f_status character varying, f_course_id smallint, f_university_id smallint, f_option_id smallint, f_modality_id smallint, f_version smallint, f_year character varying) OWNER TO postgres;

--
-- Name: fn_teacher_questions_notification(bigint, integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_teacher_questions_notification(p_teacher_id bigint, p_week integer, p_year integer, p_company_id integer) RETURNS TABLE(not_exist_questions_available boolean, total_question_week bigint, limit_assigned_questions bigint)
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_total_available_question INT;
                v_limit_assigned_questions INT;
                v_question_last_week INT;
                v_total_question_week INT;
                v_total_question_assigned INT;
                v_not_exist_questions_available BOOL;
                v_block_assigned_questions INT;
            BEGIN
                -- Obtener la cantidad de preguntas sin asignar
                SELECT COUNT(*)
                INTO v_total_available_question
                FROM odiseo.question q
                WHERE q.status = 'SASI'
                AND q.fl_status = TRUE
                AND q.course_id IN (
                    SELECT ec.course_id
                    FROM odiseo.employee_course ec
                    WHERE ec.teacher_id = p_teacher_id
                        AND ec.fl_status = TRUE
                );

               SELECT e.limit_assigned_questions
               INTO v_limit_assigned_questions
               FROM odiseo.employees e
               WHERE e.id = p_teacher_id;

               SELECT as2.block_assigned_questions
               INTO v_block_assigned_questions
               FROM odiseo.advanced_settings as2
               WHERE as2.company_id = p_company_id;

              SELECT COUNT(*)
              INTO v_total_question_assigned
              FROM odiseo.employee_question eq
              WHERE eq.teacher_id  = p_teacher_id AND eq.solved = false AND eq.fl_status = TRUE;

             IF v_total_question_assigned = 0 THEN
             	-- Verificar si existen preguntas para asignar al profesor
                not_exist_questions_available := v_total_available_question < v_block_assigned_questions;

             ELSE
             	not_exist_questions_available := false;
             END IF;

            -- Cuantas preguntas tiene el profesor con respecto de la semana actual
                SELECT COUNT(*)
                INTO v_total_question_week
                FROM odiseo.employee_question eq
                INNER JOIN odiseo.question q ON eq.question_id = q.id
                WHERE eq.teacher_id = p_teacher_id
				AND eq.week = p_week
				AND eq.year = p_year
                AND q.status NOT IN('ARCH', 'DUPL');

                total_question_week := v_total_question_week;
                limit_assigned_questions := v_limit_assigned_questions;


                -- Retornar los valores calculados
                RETURN QUERY SELECT not_exist_questions_available, total_question_week, limit_assigned_questions ;
            END;
            $$;


ALTER FUNCTION odiseo.fn_teacher_questions_notification(p_teacher_id bigint, p_week integer, p_year integer, p_company_id integer) OWNER TO postgres;

--
-- Name: fn_teacher_questions_totals(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_teacher_questions_totals(p_teacher_id bigint) RETURNS TABLE(assigned bigint, indexed bigint, revised bigint, verified bigint)
    LANGUAGE plpgsql
    AS $$
    DECLARE 
        v_total_verified BIGINT;
    BEGIN

        -- Calcular total verificado (VERI + APRB) usando 30 días fijos
        WITH date_range AS (
            SELECT
                CURRENT_TIMESTAMP - INTERVAL '30 days' AS start_date,
                NOW() AS end_date
        ),
        -- Primera fecha de verificación desde question_status
        first_verified_date AS (
            SELECT
                qs.question_id,
                MIN(qs.created_at) AS first_veri_date
            FROM question_status qs
            WHERE qs.status = 'VERI'
            GROUP BY qs.question_id
        ),
        -- Preguntas válidas en rango (verificadas en los últimos 30 días)
        valid_questions_in_range AS (
            SELECT
                vq.id,
                vq.parent_id,
                vq.status
            FROM question vq
            INNER JOIN first_verified_date fvd ON fvd.question_id = vq.id
            CROSS JOIN date_range dr
            WHERE vq.fl_status = TRUE
                AND vq.deleted_at IS NULL
                AND fvd.first_veri_date >= dr.start_date
        ),
        -- Filtrar por profesor
        teacher_questions AS (
            SELECT 
                vqr.id,
                vqr.parent_id,
                vqr.status
            FROM valid_questions_in_range vqr
            INNER JOIN employee_question eq ON eq.question_id = vqr.id
            WHERE (p_teacher_id IS NULL OR eq.teacher_id = p_teacher_id)
                AND eq.fl_status = TRUE
        ),
        -- Contar standalone (VERI + APRB)
        standalone_counts AS (
            SELECT COUNT(*) AS total
            FROM teacher_questions tq
            WHERE tq.parent_id IS NULL
                AND tq.status IN ('VERI', 'APRB')
        ),
        -- Contar parents (VERI + APRB)
        parent_counts AS (
            SELECT COUNT(DISTINCT pq.id) AS total
            FROM parent_question pq
            WHERE pq.id IN (
                SELECT DISTINCT parent_id 
                FROM teacher_questions 
                WHERE parent_id IS NOT NULL
            )
            AND pq.status IN ('VERI', 'APRB')
        )
        SELECT COALESCE(
            (SELECT total FROM standalone_counts) + (SELECT total FROM parent_counts), 
            0
        ) INTO v_total_verified;

        -- Retornar totales
        RETURN QUERY 
        WITH base_questions AS (
            SELECT 
                CONCAT('S', q.id) AS id,
                'S' AS type,
                ARRAY[]::TEXT[] AS children_status,
                q.status AS status
            FROM employee_question eq
            INNER JOIN question q ON eq.question_id = q.id
            WHERE (p_teacher_id IS NULL OR eq.teacher_id = p_teacher_id)
                AND q.fl_status IS TRUE
                AND q.deleted_at IS NULL
                AND eq.fl_status IS TRUE
                AND eq.deleted_at IS NULL
                AND q.status NOT IN ('SASI', 'ARCH')
                AND q.parent_id IS NULL
        ),
        parents AS (
            SELECT 
                CONCAT('T', pq.id) AS id,
                'T' AS type,
                ARRAY_AGG(child_q.status) AS children_status,
                NULL AS status
            FROM parent_question pq
            INNER JOIN question child_q ON child_q.parent_id = pq.id
            WHERE EXISTS (
                SELECT 1
                FROM employee_question eq2
                JOIN question q2 ON eq2.question_id = q2.id
                WHERE q2.parent_id = pq.id
                    AND (p_teacher_id IS NULL OR eq2.teacher_id = p_teacher_id)
                    AND q2.fl_status IS TRUE
                    AND q2.deleted_at IS NULL
                    AND eq2.fl_status IS TRUE
                    AND eq2.deleted_at IS NULL
                    AND q2.status NOT IN ('SASI', 'ARCH')
            )
            AND pq.status <> 'DUPL'
            GROUP BY pq.id
        ),
        all_questions_status AS (
            SELECT * FROM base_questions
            UNION ALL
            SELECT DISTINCT id, type, children_status, status
            FROM parents
        )
        SELECT 
            COALESCE(SUM(
                CASE
                    WHEN type = 'S' AND status IN ('ASIG', 'RESO', 'SSOL', 'RECH') THEN 1
                    WHEN type = 'T' AND children_status && ARRAY['ASIG', 'RESO', 'SSOL', 'RECH']::TEXT[] THEN 1
                    ELSE 0
                END
            ), 0) AS assigned,
            COALESCE(SUM(
                CASE
                    WHEN type = 'S' AND status IN ('DASI', 'INDE') THEN 1
                    WHEN type = 'T' AND children_status && ARRAY['DASI', 'INDE']::TEXT[] THEN 1
                    ELSE 0
                END
            ), 0) AS indexed,
            COALESCE(SUM(
                CASE
                    WHEN type = 'S' AND status IN ('DIGI', 'OBSE') THEN 1
                    WHEN type = 'T' AND children_status && ARRAY['DIGI', 'OBSE']::TEXT[] THEN 1
                    ELSE 0
                END
            ), 0) AS revised,
            v_total_verified AS verified
        FROM all_questions_status;
    END;
    $$;


ALTER FUNCTION odiseo.fn_teacher_questions_totals(p_teacher_id bigint) OWNER TO postgres;

--
-- Name: fn_topics_count_questions(smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_topics_count_questions(f_course_id smallint) RETURNS TABLE(id smallint, code character varying, name character varying, course_id smallint, count_questions bigint)
    LANGUAGE plpgsql
    AS $$
                    DECLARE
                    v_course_id SMALLINT;
                    v_fl_pseudo_course BOOLEAN;
                        v_courses_pseudo SMALLINT[];
                        v_order_pseudo SMALLINT[];
                    BEGIN
                        -- Validar si es pseudocurso o no
                        SELECT co.id, co.fl_pseudo_course INTO v_course_id, v_fl_pseudo_course
                        FROM course co
                        WHERE co.id = f_course_id
                        AND co.fl_status = true;

                        -- Si es pseudocurso, no se cuenta las preguntas verificadas
                        IF v_fl_pseudo_course IS TRUE THEN
                            SELECT ARRAY(
                                SELECT pc.course_id
                                FROM course_pseudo_courses pc
                                WHERE pc.pseudo_course_id = f_course_id
                                AND pc.fl_status = true
                                ORDER BY pc.order ASC
                            ) INTO v_courses_pseudo;
                        ELSE
                            SELECT ARRAY[f_course_id] INTO v_courses_pseudo;
                        END IF;

                        RETURN QUERY
                        WITH tbl_question_veri AS (
                            SELECT
                                q.topic_id,
                                count(q.id) AS count_questions
                            FROM question q
                            WHERE q.status IN ('VERI', 'APRB')
                            GROUP BY q.topic_id
                        ), tbl_topic AS (
                            SELECT
                                t.id, t.code, t.name, t.course_id, COALESCE(qv.count_questions, 0) AS count_questions
                            FROM topic t
                            LEFT JOIN tbl_question_veri qv ON t.id = qv.topic_id
                            WHERE t.fl_status = true
                        )
                        SELECT tt.* FROM tbl_topic tt
                        WHERE tt.course_id = ANY(v_courses_pseudo)
                        ORDER BY array_position(v_courses_pseudo, tt.course_id) ASC, tt.code ASC;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_topics_count_questions(f_course_id smallint) OWNER TO postgres;

--
-- Name: fn_total_text_by_courses_levels(integer, integer, integer, integer, integer, integer[]); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_total_text_by_courses_levels(p_university_id integer, p_cycle_id integer, p_headquarter_id integer, p_week integer, p_type_material_id integer, p_courses integer[]) RETURNS TABLE(total_passages_levels bigint, levels_total bigint, course_id smallint, course_name character varying, type_config text)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    SUM(COALESCE(dlswp.number_of_passages, 0)) AS total_passages_levels,
                    SUM(COALESCE(dlswp.number_of_passages, 0)) AS levels_total,
                    c.id AS course_id,
                    c.name AS course_name,
                    'level' AS type_config
                FROM
                    course c
                LEFT JOIN level_syllabus ls
                    ON ls.course_id = c.id
                    AND ls.fl_status = TRUE
                    AND ls.headquarter_id = p_headquarter_id
                    AND ls.cycle_id = p_cycle_id
                    AND ls.university_id = p_university_id
                LEFT JOIN level_syllabus_weeks lsw
                    ON lsw.level_syllabus_id = ls.id
                    AND lsw.week = p_week
                LEFT JOIN detail_level_syllabus_weeks_parents dlswp
                    ON dlswp.level_syllabus_weeks_id = lsw.id
                    AND dlswp.fl_status = TRUE
                    AND dlswp.type_material_id = p_type_material_id
                WHERE
                    c.id = ANY(p_courses)
                GROUP BY
                    c.id, c.name;
            END;
            $$;


ALTER FUNCTION odiseo.fn_total_text_by_courses_levels(p_university_id integer, p_cycle_id integer, p_headquarter_id integer, p_week integer, p_type_material_id integer, p_courses integer[]) OWNER TO postgres;

--
-- Name: fn_total_text_by_courses_syllabus(integer, integer, integer, integer, integer[]); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_total_text_by_courses_syllabus(p_university_id integer, p_cycle_id integer, p_week integer, p_type_material_id integer, p_courses integer[]) RETURNS TABLE(total_passages_syllabus bigint, syllabus_total bigint, course_id smallint, course_name character varying, type_config text)
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                        RETURN QUERY
                        SELECT
                            COUNT(st.id) AS total_passages_syllabus,
                            COUNT(st.id) AS syllabus_total,
                            c.id AS course_id,
                            c.name AS course_name,
                            'syllabus' AS type_config
                        FROM
                            course c
                        LEFT JOIN syllabus s
                            ON s.course_id = c.id
                            AND s.university_id = p_university_id
                            AND s.cycle_id = p_cycle_id
                        LEFT JOIN syllabus_text_weeks stw
                            ON stw.syllabus_id = s.id
                            AND stw.week = p_week AND stw.fl_status = true
                        LEFT JOIN syllabus_text_distributions std
                            ON std.syllabus_text_week_id = stw.id
                            AND std.type_material_id = p_type_material_id 
                            AND std.fl_status = true
                        LEFT JOIN syllabus_texts st
                            ON st.syllabus_text_distribution_id = std.id
                            AND st.fl_status = true
                        WHERE
                            c.id = ANY(p_courses)
                        GROUP BY
                            c.id, c.name;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_total_text_by_courses_syllabus(p_university_id integer, p_cycle_id integer, p_week integer, p_type_material_id integer, p_courses integer[]) OWNER TO postgres;

