--
-- Name: fn_type_material_all(bigint, boolean, bigint, bigint, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_type_material_all(p_cycle_id bigint DEFAULT NULL::bigint, p_fl_exam boolean DEFAULT NULL::boolean, p_course_id bigint DEFAULT NULL::bigint, p_week bigint DEFAULT NULL::bigint, p_all_weeks boolean DEFAULT NULL::boolean) RETURNS TABLE(id smallint, code character varying, description text, is_generic boolean, is_generic_text boolean, amount_question integer, course_amount_question integer, course_amount_text integer, course_amount_subquestion integer, subquestions_detail jsonb, thread smallint, percentage numeric, course_id smallint, material_name character varying, week_number integer)
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_type_material_id SMALLINT;
                v_type_materials   SMALLINT[] := ARRAY[]::SMALLINT[];
                v_total_weeks      INTEGER := 0;
                v_current_week     INTEGER;
            BEGIN
                -- Recopilar type_materials excluidos cuando p_fl_exam no es null
                IF p_fl_exam IS NOT NULL THEN
                    FOR v_type_material_id IN
                        SELECT DISTINCT tm.id
                        FROM type_material tm
                        INNER JOIN type_material_bound tmb
                            ON tm.type_material_template_id = tmb.type_material_template_id
                            AND tmb.fl_status = true
                        WHERE tm.fl_status = true
                    LOOP
                        v_type_materials := array_append(v_type_materials, v_type_material_id);
                    END LOOP;
                END IF;

                -- Obtener total de semanas si p_all_weeks es true
                IF p_all_weeks IS TRUE AND p_cycle_id IS NOT NULL THEN
                    SELECT c.weeks INTO v_total_weeks
                    FROM cycle c
                    WHERE c.id = p_cycle_id
                    LIMIT 1;
                END IF;

                -- ---------------------------------------------------------------
                -- Modo p_all_weeks = true: iterar por cada semana
                -- ---------------------------------------------------------------
                IF p_all_weeks IS TRUE AND v_total_weeks > 0 THEN
                    FOR v_current_week IN 1..v_total_weeks LOOP
                        RETURN QUERY
                        WITH tbl_type_material_course AS (
                            SELECT
                                tm.id,
                                tm.code,
                                CONCAT(tm.description, ', ', c.description) AS description,

                                COALESCE(details.is_generic, tmc.is_generic)           AS is_generic,
                                COALESCE(details.is_generic_text, tmc.is_generic_text) AS is_generic_text,

                                tm.amount_question,

                                COALESCE(details.amount_question, tmc.amount_question) AS course_amount_question,
                                COALESCE(details.amount_text, tmc.amount_text)         AS course_amount_text,

                                COALESCE(
                                    (SELECT SUM((elem->>'subquestion_amount')::int)
                                     FROM jsonb_array_elements(COALESCE(details.subquestions, '[]'::jsonb)) elem),
                                    0
                                )::integer AS course_amount_subquestion,

                                COALESCE(details.subquestions, '[]'::jsonb) AS subquestions_detail,

                                tm.thread,
                                tm.percentage,
                                tmc.course_id,
                                tm.description AS material_name,
                                v_current_week::integer AS week_number

                            FROM type_material tm
                            LEFT JOIN type_material_course tmc ON tmc.type_material_id = tm.id
                            LEFT JOIN cycle c ON c.id = tm.cycle_id

                            LEFT JOIN fn_get_course_material_details(
                                p_course_id::SMALLINT,
                                v_current_week::INTEGER,
                                p_cycle_id::INTEGER
                            ) details ON details.type_material_id = tm.id

                            WHERE 1 = 1
                            AND (p_cycle_id IS NULL OR tm.cycle_id = p_cycle_id)
                            AND (p_fl_exam IS NULL OR tm.fl_exam = p_fl_exam)
                            AND (p_course_id IS NULL OR tmc.course_id = p_course_id)
                            AND (v_type_materials IS NULL OR v_type_materials = '{}' OR tm.id <> ANY(v_type_materials))
                            AND tm.fl_status IS TRUE
                            AND tmc.fl_status IS TRUE
                        )
                        SELECT
                            tbl.id,
                            tbl.code,
                            tbl.description,
                            tbl.is_generic,
                            tbl.is_generic_text,
                            tbl.amount_question,
                            tbl.course_amount_question,
                            tbl.course_amount_text,
                            tbl.course_amount_subquestion,
                            tbl.subquestions_detail,
                            tbl.thread,
                            tbl.percentage,
                            tbl.course_id,
                            tbl.material_name,
                            tbl.week_number
                        FROM tbl_type_material_course tbl
                        ORDER BY tbl.week_number,
                            CASE
                                WHEN tbl.description = 'ECO' THEN 1
                                WHEN tbl.description = 'Guía de clases' THEN 2
                                WHEN tbl.description = 'Homework' THEN 3
                                ELSE 4
                            END,
                            tbl.description,
                            tbl.code;
                    END LOOP;

                -- ---------------------------------------------------------------
                -- Modo normal (p_all_weeks = false / null): comportamiento original
                -- ---------------------------------------------------------------
                ELSE
                    RETURN QUERY
                    WITH tbl_type_material_course AS (
                        SELECT
                            tm.id,
                            tm.code,
                            CONCAT(tm.description, ', ', c.description) AS description,

                            COALESCE(details.is_generic, tmc.is_generic)           AS is_generic,
                            COALESCE(details.is_generic_text, tmc.is_generic_text) AS is_generic_text,

                            tm.amount_question,

                            COALESCE(details.amount_question, tmc.amount_question) AS course_amount_question,
                            COALESCE(details.amount_text, tmc.amount_text)         AS course_amount_text,

                            COALESCE(
                                (SELECT SUM((elem->>'subquestion_amount')::int)
                                 FROM jsonb_array_elements(COALESCE(details.subquestions, '[]'::jsonb)) elem),
                                0
                            )::integer AS course_amount_subquestion,

                            COALESCE(details.subquestions, '[]'::jsonb) AS subquestions_detail,

                            tm.thread,
                            tm.percentage,
                            tmc.course_id,
                            tm.description AS material_name,
                            NULL::integer AS week_number

                        FROM type_material tm
                        JOIN cycle c ON c.id = tm.cycle_id
                        LEFT JOIN type_material_course tmc ON tmc.type_material_id = tm.id

                        LEFT JOIN fn_get_course_material_details(
                            p_course_id::SMALLINT,
                            p_week::INTEGER,
                            p_cycle_id::INTEGER
                        ) details ON details.type_material_id = tm.id

                        WHERE 1 = 1
                        AND (p_cycle_id IS NULL OR tm.cycle_id = p_cycle_id)
                        AND (p_fl_exam IS NULL OR tm.fl_exam = p_fl_exam)
                        AND (p_course_id IS NULL OR tmc.course_id = p_course_id)
                        AND (v_type_materials IS NULL OR v_type_materials = '{}' OR tm.id <> ANY(v_type_materials))
                        AND tm.fl_status IS TRUE
                        AND tmc.fl_status IS TRUE
                        ORDER BY tm.code ASC
                    )
                    SELECT
                        tbl.id,
                        tbl.code,
                        tbl.description,
                        tbl.is_generic,
                        tbl.is_generic_text,
                        tbl.amount_question,
                        tbl.course_amount_question,
                        tbl.course_amount_text,
                        tbl.course_amount_subquestion,
                        tbl.subquestions_detail,
                        tbl.thread,
                        tbl.percentage,
                        tbl.course_id,
                        tbl.material_name,
                        tbl.week_number
                    FROM tbl_type_material_course tbl
                    ORDER BY CASE
                        WHEN tbl.description = 'ECO' THEN 1
                        WHEN tbl.description = 'Guía de clases' THEN 2
                        WHEN tbl.description = 'Homework' THEN 3
                        ELSE 4
                    END,
                    tbl.description,
                    tbl.code;
                END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_type_material_all(p_cycle_id bigint, p_fl_exam boolean, p_course_id bigint, p_week bigint, p_all_weeks boolean) OWNER TO postgres;

--
-- Name: fn_type_material_course(integer, integer, smallint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_type_material_course(p_perpage integer, p_npage integer, p_type_material_id smallint, p_search character varying) RETURNS TABLE(id bigint, course_id smallint, code_course character varying, course character varying, type_material_id smallint, code_type_material character varying, type_material character varying, amount_question integer, fl_status boolean, total bigint)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            offset_val INTEGER;
        BEGIN
            -- Calculate the offset
            offset_val := p_perpage * (p_npage - 1);
            RETURN QUERY
            WITH tbl_type_material_course AS (
                SELECT
                    tc.id,
                    tc.course_id,
                    c.code AS code_course,
                    c.name AS course,
                    tc.type_material_id,
                    t.code AS code_type_material,
                    t.description AS type_material,
                    tc.amount_question,
                    tc.fl_status
                FROM odiseo.type_material_course tc
                INNER JOIN odiseo.course c ON c.id = tc.course_id
                INNER JOIN odiseo.type_material t ON t.id = tc.type_material_id
                WHERE t.fl_status = true AND tc.type_material_id = p_type_material_id
                AND (
                    p_search IS NULL
                    OR (c.code ILIKE '%' || p_search || '%'
                    OR c.name ILIKE '%' || p_search || '%')
                )
            ),
            counted_type_material AS (
                SELECT *, COUNT(*) OVER () AS total
                FROM tbl_type_material_course
                ORDER BY tbl_type_material_course.code_course ASC, tbl_type_material_course.course ASC
            )
            SELECT * FROM counted_type_material
            LIMIT p_perpage
            OFFSET offset_val;
        END;
        $$;


ALTER FUNCTION odiseo.fn_type_material_course(p_perpage integer, p_npage integer, p_type_material_id smallint, p_search character varying) OWNER TO postgres;

--
-- Name: fn_type_material_periodicity(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_type_material_periodicity(p_id integer) RETURNS TABLE(id smallint, code character varying, description character varying, type_material_template_id bigint, type_material_template character varying, fl_status boolean, fl_exam boolean, periodicity_id smallint, periodicity character varying, quantity smallint, start_week smallint, group_previous_week boolean, group_remaining_week boolean, weeks jsonb)
    LANGUAGE plpgsql
    AS $$
		DECLARE
            v_cycle_id BIGINT;
		    v_ids_children INT[];
        BEGIN
            RETURN QUERY
            SELECT
                t.id,
                t.code,
                t.description,
                t.type_material_template_id,
                tmt.name AS type_material_template,
                t.fl_status,
                t.fl_exam,
                tmp.periodicity_id,
                p.name AS periodicity,
                COALESCE(p.quantity, tmp.quantity_week, 1::SMALLINT) AS quantity,
                tmp.start_week,
                tmp.group_previous_week,
                tmp.group_remaining_week,
                COALESCE((
                    SELECT jsonb_agg(tmdt.week ORDER BY tmdt.week ASC)
                    FROM type_material_detail_template tmdt
                    WHERE tmdt.type_material_id = t.id
                        AND tmdt.fl_status = true
                ), '[]'::JSONB) AS weeks
            FROM type_material t
            LEFT JOIN type_material_template tmt
                ON tmt.id = t.type_material_template_id
            LEFT JOIN type_material_periodicity tmp
                ON t.id = tmp.type_material_id AND tmp.fl_status = true
            LEFT JOIN periodicity p
                ON tmp.periodicity_id = p.id
            WHERE t.id = p_id;
        END;
        $$;


ALTER FUNCTION odiseo.fn_type_material_periodicity(p_id integer) OWNER TO postgres;

--
-- Name: fn_unassign_missing_question(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_unassign_missing_question(p_detail_id bigint, p_created_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_employee_id BIGINT;
BEGIN
    SELECT employee_id INTO v_employee_id
    FROM material_missing_question_detail
    WHERE id = p_detail_id;

    UPDATE material_missing_question_detail
    SET employee_id = NULL,
        assignment_type = NULL,
        status = 'pending',
        updated_at = now()
    WHERE id = p_detail_id;

    INSERT INTO material_missing_question_tracking (
        material_missing_question_detail_id,
        employee_id,
        action,
        assignment_type,
        created_by,
        created_at,
        updated_at
    ) VALUES (
        p_detail_id,
        v_employee_id,
        'unassigned',
        NULL,
        p_created_by,
        now(),
        now()
    );
END;
$$;


ALTER FUNCTION odiseo.fn_unassign_missing_question(p_detail_id bigint, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_unassign_missing_question_by_employee(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_unassign_missing_question_by_employee(p_employee_id bigint, p_created_by bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    WITH unassigned_details AS (
        UPDATE material_missing_question_detail
        SET employee_id = NULL,
            assignment_type = NULL,
            status = 'pending',
            updated_at = now()
        WHERE employee_id = p_employee_id
          AND status = 'assigned'
        RETURNING id
    )
    INSERT INTO material_missing_question_tracking (
        material_missing_question_detail_id,
        employee_id,
        action,
        assignment_type,
        created_by,
        created_at,
        updated_at
    )
    SELECT
        ud.id,
        p_employee_id,
        'unassigned',
        NULL,
        p_created_by,
        now(),
        now()
    FROM unassigned_details ud;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


ALTER FUNCTION odiseo.fn_unassign_missing_question_by_employee(p_employee_id bigint, p_created_by bigint) OWNER TO postgres;

--
-- Name: fn_unassigned_question(integer, integer, integer, character varying, bigint, integer, character varying, integer, smallint, smallint, smallint, smallint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_unassigned_question(p_perpage integer, p_npage integer, p_employee_id integer, p_name_text character varying, p_employee_didi_id bigint, f_course_id integer, f_type character varying, f_week_id integer, f_university_id smallint, f_option_id smallint, f_modality_id smallint, f_version smallint, f_year character varying) RETURNS TABLE(key_question text, id bigint, code character varying, short_description text, number_question character varying, number character varying, course_id smallint, code_course character varying, course character varying, status character varying, fl_status boolean, parent_id bigint, type_question text, subquestions jsonb, created_by bigint, created_at timestamp without time zone, user_name character varying, user_email odiseo.email_citext, employee_id bigint, name_employee text, origin_question jsonb, type_text_template_id smallint, priority integer, is_missing_question boolean, total bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    offset_val integer := p_perpage * (p_npage - 1);
    C_MORE_RECENT_VERSION smallint DEFAULT 1;
BEGIN
    RETURN QUERY WITH employee_course AS (
        SELECT
            ec.course_id
        FROM
            employee_course ec
        WHERE (p_employee_id IS NULL
            OR ec.teacher_id = p_employee_id)
),
sasi_questions AS (
    SELECT
        q.*,
        qn.question_origin,
        qn.university_id,
        qn.option_id,
        qn.modality_id,
        qn."version",
        qn."year"
    FROM
        question q
        LEFT JOIN v_all_question_origins qn ON qn.question_id = q.id
    WHERE
        1 = 1
        AND q.fl_status = TRUE
        AND q.status = 'SASI'
        AND q.deleted_at IS NULL
        AND (f_university_id IS NULL
            OR qn.university_id = f_university_id)
        AND (f_option_id IS NULL
            OR qn.option_id = f_option_id)
        AND (f_modality_id IS NULL
            OR qn.modality_id = f_modality_id)
        AND (f_version IS NULL
            OR qn."version" = f_version)
        AND (f_year IS NULL
            OR qn."year" = f_year)
),
p_s_questions AS (
    SELECT
        concat('p_', q.id) AS key_question,
        q.id,
        q.code,
        q.short_description,
        q.number_question,
        q.number,
        q.course_id,
        c.code AS code_course,
        c.name AS course,
        q.status,
        q.fl_status,
        q.parent_id,
        CASE WHEN q.parent_id IS NULL THEN
            'P'
        ELSE
            'S'
        END AS type_question,
        q.created_by,
        qs.created_at created_at,
        u.user AS user_name,
        u.email AS user_email,
        e.id AS employee_id,
        CONCAT(e.first_surname, ' ', e.second_surname, ' ', e.first_name) AS name_employee,
        q.question_origin,
        c.type_text_template_id,
        q.priority,
        CASE WHEN mmqd.question_id IS NOT NULL THEN
            TRUE
        ELSE
            FALSE
        END AS is_missing_question
    FROM
        sasi_questions q
        INNER JOIN course c ON q.course_id = c.id
        LEFT JOIN question_status qs ON qs.fl_active = TRUE
            AND q.id = qs.question_id
            AND q.status = qs.status
        LEFT JOIN users u ON q.created_by = u.id
        LEFT JOIN employees e ON u.id = e.user_id
        LEFT JOIN material_missing_question_detail mmqd ON mmqd.question_id = q.id
    WHERE
        1 = 1
        AND (p_employee_didi_id IS NULL
            OR e.id = p_employee_didi_id)
),
sub_questions AS (
    SELECT
        pq.id AS parent_id,
        jsonb_agg(jsonb_build_object('key_question', concat('s_', q.id), 'id', q.id, 'code', q.code, 'short_description', q.short_description, 'number_question', q.number_question, 'number', q.number, 'course_id', q.course_id, 'code_course', c.code, 'course', c.name, 'status', q.status, 'fl_status', q.fl_status, 'parent_id', q.parent_id, 'type_question', 'S', 'created_by', q.created_by, 'created_at', qs.created_at, 'user_name', u.user, 'user_email', u.email, 'employee_id', e.id, 'name_employee', CONCAT(e.first_surname, ' ', e.second_surname, ' ', e.first_name), 'origin_question', q.question_origin)) AS subquestions
    FROM
        sasi_questions q
        INNER JOIN parent_question pq ON q.parent_id = pq.id
        INNER JOIN course c ON q.course_id = c.id
        LEFT JOIN users u ON q.created_by = u.id
        LEFT JOIN employees e ON u.id = e.user_id
        LEFT JOIN question_status qs ON q.id = qs.question_id
            AND q.status = qs.status
            AND qs.fl_active = TRUE
    WHERE
        1 = 1
        AND (p_employee_didi_id IS NULL
            OR e.id = p_employee_didi_id)
    GROUP BY
        pq.id
),
tbl_question AS (
    SELECT
        concat('p_', q.id) AS key_question,
        q.id,
        q.code,
        q.short_description,
        q.number_question,
        q.number,
        q.course_id,
        q.code_course,
        q.course,
        q.status,
        q.fl_status,
        q.parent_id,
        q.type_question,
        COALESCE(sq.subquestions, '[]'::jsonb) AS subquestions,
        q.created_by,
        q.created_at,
        q.user_name,
        q.user_email,
        q.employee_id,
        q.name_employee,
        q.question_origin,
        NULL AS type_text_template_id,
        q.priority,
        q.is_missing_question
    FROM
        p_s_questions q
        LEFT JOIN sub_questions sq ON q.parent_id = sq.parent_id
    WHERE
        q.parent_id IS NULL
    UNION ALL SELECT DISTINCT
        concat('t_', pq.id) AS key_question,
        pq.id,
        pq.code,
        pq.short_description,
        pq.number_question,
        pq.number,
        pq.course_id,
        c.code AS code_course,
        c.name AS course,
        pq.status,
        pq.fl_status,
        pq.id AS parent_id,
        'T' AS type_question,
        COALESCE(sq.subquestions, '[]'::jsonb) AS subquestions,
        pq.created_by,
        pq.created_at AS created_at,
        u.user AS user_name,
        u.email AS user_email,
        e.id AS employee_id,
        CONCAT(e.first_surname, ' ', e.second_surname, ' ', e.first_name) AS name_employee,
        opq.question_origin,
        c.type_text_template_id,
        pq.priority,
        FALSE AS is_missing_question
    FROM
        parent_question pq
        INNER JOIN course c ON pq.course_id = c.id
        LEFT JOIN type_text_templates ttt ON ttt.id = c.type_text_template_id
        LEFT JOIN users u ON pq.created_by = u.id
        LEFT JOIN employees e ON u.id = e.user_id
        LEFT JOIN sub_questions sq ON pq.id = sq.parent_id
            AND sq.parent_id IS NOT NULL
        LEFT JOIN v_all_parent_origins opq ON opq.parent_id = pq.id
    WHERE
        pq.fl_status = TRUE
        AND pq.status <> 'DUPL'
        AND pq.deleted_at IS NULL
        AND (p_employee_didi_id IS NULL
            OR e.id = p_employee_didi_id)
        AND (sq.subquestions <> '[]')
        AND (f_university_id IS NULL
            OR opq.university_id = f_university_id)
        AND (f_option_id IS NULL
            OR opq.option_id = f_option_id)
        AND (f_modality_id IS NULL
            OR opq.modality_id = f_modality_id)
        AND (f_version IS NULL
            OR opq."version" = f_version)
        AND (f_year IS NULL
            OR opq."year" = f_year)
),
filtered_questions AS (
    SELECT
        *
    FROM
        tbl_question
    WHERE (f_course_id IS NULL
        OR tbl_question.course_id = f_course_id)
    AND (f_type IS NULL
        OR tbl_question.type_question = f_type)
    AND (p_employee_id IS NULL
        OR tbl_question.course_id IN (
            SELECT
                *
            FROM
                employee_course))
        AND (p_name_text IS NULL
            OR unaccent(LOWER(tbl_question.short_description))
            ILIKE '%' || LOWER(p_name_text) || '%'
            OR LOWER(tbl_question.number_question)
            ILIKE '%' || LOWER(p_name_text) || '%'
            OR LOWER(tbl_question.number)
            ILIKE '%' || LOWER(p_name_text) || '%'
            OR LOWER(tbl_question.code)
            ILIKE '%' || LOWER(p_name_text) || '%'
            OR EXISTS (
                SELECT
                    1
                FROM
                    jsonb_array_elements(tbl_question.subquestions) AS sq
                WHERE
                    unaccent(LOWER(sq ->> 'short_description'))
                    ILIKE '%' || LOWER(p_name_text) || '%'
                    OR LOWER(sq ->> 'number_question')
                    ILIKE '%' || LOWER(p_name_text) || '%'
                    OR LOWER(sq ->> 'number')
                    ILIKE '%' || LOWER(p_name_text) || '%'
                    OR LOWER(sq ->> 'code')
                    ILIKE '%' || LOWER(p_name_text) || '%'))
),
counted_questions AS (
    SELECT
        *,
        count(*) OVER () AS total
FROM
    filtered_questions
)
SELECT
    *
FROM
    counted_questions
ORDER BY
    priority DESC,
    created_at ASC,
    key_question ASC
LIMIT p_perpage OFFSET offset_val;
END;
$$;


ALTER FUNCTION odiseo.fn_unassigned_question(p_perpage integer, p_npage integer, p_employee_id integer, p_name_text character varying, p_employee_didi_id bigint, f_course_id integer, f_type character varying, f_week_id integer, f_university_id smallint, f_option_id smallint, f_modality_id smallint, f_version smallint, f_year character varying) OWNER TO postgres;

--
-- Name: fn_unify_topic_suptopic(jsonb, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_unify_topic_suptopic(p_detail jsonb, p_user_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
    BEGIN
        WITH 
        groups_layer AS (
            SELECT value AS group_data
            FROM jsonb_array_elements(p_detail)
        ),

        flat_items AS (
            SELECT 
                sub.ordinality AS pair_index,
                (g.group_data->>'course_id')::INT as final_course,
                (g.group_data->>'topic_id')::INT as final_topic,
                (g.group_data->>'new_name_topic') as new_name_topic,
                (g.group_data->>'last_name_topic') as last_name_topic,
                (sub.value->>'subtopic_id')::INT as final_subtopic,
                (sub.value->>'new_name_subtopic') as new_name_subtopic,
                (sub.value->>'last_name_subtopic') as last_name_subtopic
            FROM groups_layer g,
                jsonb_array_elements(g.group_data->'subtopic') WITH ORDINALITY sub
        ),

        existing_rows AS (
            SELECT 
                f.pair_index,
                n.uuid
            FROM flat_items f
            JOIN network_course_topic_subtopic n
                ON n.course_id = f.final_course
                AND n.topic_id = f.final_topic
                AND n.subtopic_id = f.final_subtopic
        ),

        pair_uuid_map AS (
            SELECT 
                p.pair_index,
                COALESCE(
                    (
                        SELECT er.uuid
                        FROM existing_rows er
                        WHERE er.pair_index = p.pair_index
                        AND er.uuid IS NOT NULL
                        LIMIT 1
                    ),
                    gen_random_uuid()
                ) as pair_uuid
            FROM (
                SELECT DISTINCT pair_index
                FROM flat_items
            ) p
        ),

        new_records AS (
            SELECT 
                m.pair_uuid,
                f.final_course,
                f.final_topic,
                f.final_subtopic,
                f.new_name_topic,
                f.last_name_topic,
                f.new_name_subtopic,
                f.last_name_subtopic
            FROM flat_items f
            JOIN pair_uuid_map m ON m.pair_index = f.pair_index
            WHERE NOT EXISTS (
                SELECT 1
                FROM network_course_topic_subtopic n
                WHERE n.course_id = f.final_course
                AND n.topic_id = f.final_topic
                AND n.subtopic_id = f.final_subtopic
            )
        ),

        inserted AS (
            INSERT INTO network_course_topic_subtopic (
                uuid, course_id, topic_id, subtopic_id, created_by, created_at,
                new_name_topic, last_name_topic, new_name_subtopic, last_name_subtopic
            )
            SELECT 
                pair_uuid,
                final_course,
                final_topic,
                final_subtopic,
                p_user_id,
                NOW(),
                new_name_topic,
                last_name_topic,
                new_name_subtopic,
                last_name_subtopic
            FROM new_records
            RETURNING topic_id, subtopic_id, new_name_topic, new_name_subtopic
        ),

        topics_to_update AS (
            SELECT DISTINCT topic_id, new_name_topic
            FROM inserted
            WHERE new_name_topic IS NOT NULL
            AND new_name_topic <> ''
        ),

        subtopics_to_update AS (
            SELECT DISTINCT subtopic_id, new_name_subtopic
            FROM inserted
            WHERE new_name_subtopic IS NOT NULL
            AND new_name_subtopic <> ''
        ),

        update_topics AS (
            UPDATE topic t
            SET name = u.new_name_topic,
                updated_at = NOW(),
                updated_by = p_user_id
            FROM topics_to_update u
            WHERE t.id = u.topic_id
            RETURNING t.id
        )

        UPDATE subtopic s
        SET name = u.new_name_subtopic,
            updated_at = NOW(),
            updated_by = p_user_id
        FROM subtopics_to_update u
        WHERE s.id = u.subtopic_id;

    END;
    $$;


ALTER FUNCTION odiseo.fn_unify_topic_suptopic(p_detail jsonb, p_user_id integer) OWNER TO postgres;

--
-- Name: fn_universities_syllabus_template(integer, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_universities_syllabus_template(p_company_id integer, p_employee_id bigint) RETURNS TABLE(id smallint, name character varying, slug character varying)
    LANGUAGE plpgsql
    AS $$
    DECLARE
        offset_val INTEGER;
    BEGIN
        RETURN QUERY
        SELECT DISTINCT * FROM (
            SELECT
                ou.id,
                ou.name,
                ou.slug
            FROM origin_university ou
            LEFT JOIN syllabus_template st ON ou.id = st.university_id
                AND st.fl_status = TRUE
                AND st.deleted_at IS NULL
                AND st.company_id = p_company_id
            LEFT JOIN employee_university eu ON eu.university_id = ou.id
                AND eu.fl_status IS true
            WHERE st.id IS NULL
                AND ou.fl_active = true
                AND (p_employee_id IS null OR eu.employee_id = p_employee_id)
            ORDER BY public.unaccent(ou.name) ASC
        ) AS tbl_universities;
    END;
    $$;


ALTER FUNCTION odiseo.fn_universities_syllabus_template(p_company_id integer, p_employee_id bigint) OWNER TO postgres;

--
-- Name: fn_update_alternative(bigint, bigint, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_alternative(p_id bigint, p_question bigint, p_alternative character varying, p_updated_by bigint) RETURNS TABLE(v_id bigint, v_description character varying, v_question_id bigint)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                UPDATE odiseo.alternative
                SET description = p_alternative, updated_at = now(), updated_by = p_updated_by
                WHERE id = p_id AND question_id = p_question
                RETURNING id, description::character varying, question_id;
            END;
            $$;


ALTER FUNCTION odiseo.fn_update_alternative(p_id bigint, p_question bigint, p_alternative character varying, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_update_and_find_excluded_questions(integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_and_find_excluded_questions(p_week_type_material_id integer, p_deleted_by integer) RETURNS TABLE(id bigint, material_distribution_id bigint, type_material_id smallint, week smallint, course_id smallint, code_course character varying, course character varying, subtopic_id smallint, code_subtopic character varying, subtopic character varying, topic_id smallint, code_topic character varying, topic character varying, level_id bigint, level_description character varying, level_name character varying, question_id bigint, type character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_material_id bigint;
    v_week smallint;
    v_type_material_id smallint;
    v_parent_type_material_id smallint;
    v_request_date timestamp;
    v_course_id smallint;
BEGIN
    -- 1. Obtener datos de contexto para la función de faltantes
    SELECT
        m.id,
        dwtm.week,
        dwtm.type_material_id,
        dwtm.parent_type_material_id,
        COALESCE(dwtm.updated_at, NOW()) INTO v_material_id,
        v_week,
        v_type_material_id,
        v_parent_type_material_id,
        v_request_date
    FROM
        detail_week_type_mat dwtm
        JOIN material m ON dwtm.material_id = m.id
    WHERE
        dwtm.id = p_week_type_material_id;
    -- 2. Ejecutar la lógica original con CTEs y guardar resultados en tabla temporal
    DROP TABLE IF EXISTS temp_excluded_questions_result;
    CREATE TEMP TABLE temp_excluded_questions_result AS
    WITH ballot_with_questions AS (
        SELECT
            mbq.id AS id,
            mbq.id AS material_distribution_id,
            dwtm.type_material_id,
            dwtm.week,
            mbq.course_id,
            c.code AS course_code,
            c.name AS course,
            mbq.subtopic_id,
            st.code AS subtopic_code,
            st.name AS subtopic,
            mbq.topic_id,
            t.code AS topic_code,
            t.name AS topic,
            mbq.level_id,
            l.description AS level_description,
            l.name AS level_name,
            q.id AS question_id,
            mbq.type AS type,
            mbq.question_history_id
        FROM
            material_ballot_question mbq
            INNER JOIN detail_week_type_mat dwtm ON mbq.week_type_material_id = dwtm.id
            LEFT JOIN question q ON q.id = mbq.question_id
            INNER JOIN course c ON mbq.course_id = c.id
            LEFT JOIN topic t ON t.id = mbq.topic_id
            LEFT JOIN subtopic st ON mbq.subtopic_id = st.id
            LEFT JOIN level l ON mbq.level_id = l.id
        WHERE
            1 = 1
            AND mbq.fl_status IS TRUE
            AND mbq.week_type_material_id = p_week_type_material_id
            AND EXISTS (
                SELECT
                    1
                FROM
                    question_excluded_material qem
                WHERE
                    qem.question_id = mbq.question_id
                    AND qem.material_id = dwtm.material_id
                    AND qem.deleted_at IS NULL)
),
slot_to_update AS (
    UPDATE
        material_ballot_question mbqu
    SET
        usage_level_id = NULL,
        usage_status = TRUE,
        question_id = NULL,
        parent_question_id = NULL,
        state = 'MISSING',
        updated_by = p_deleted_by,
        updated_at = NOW(),
        added_in_completion = FALSE,
        removed_in_completion = FALSE
    WHERE
        1 = 1
        AND mbqu.fl_status IS TRUE
        AND mbqu.id IN (
            SELECT
                bbd.id
            FROM
                ballot_with_questions bbd)
        RETURNING mbqu.id
),
subquestions_to_delete AS (
    UPDATE material_ballot_subquestions mbs
    SET
        fl_status = FALSE,
        deleted_at = NOW()
    WHERE mbs.material_ballot_question_id IN (SELECT su.id FROM slot_to_update su)
      AND mbs.fl_status = TRUE
    RETURNING mbs.id
),
question_history_cycle_to_update AS (
    UPDATE
        question_history_cycle qhc
    SET
        fl_status = FALSE,
        deleted_by = p_deleted_by,
        deleted_at = NOW()
    WHERE
        1 = 1
        AND qhc.id IN (
            SELECT
                question_history_id
            FROM
                ballot_with_questions WHERE question_history_id IS NOT NULL)
            AND NOT EXISTS (
                SELECT
                    1
                FROM
                    material_ballot_question mqq
                WHERE
                    1 = 1
                    AND mqq.fl_status IS TRUE
                    AND mqq.question_history_id = qhc.id
                    AND (mqq.id NOT IN (
                            SELECT
                                stu.id
                            FROM
                                slot_to_update stu)))
                    AND NOT EXISTS (
                        SELECT
                            1
                        FROM
                            material_exam_question meq
                        WHERE
                            1 = 1
                            AND meq.fl_status IS TRUE
                            AND meq.question_history_id = qhc.id)
)
SELECT
    bwq.id,
    bwq.material_distribution_id,
    bwq.type_material_id,
    bwq.week,
    bwq.course_id,
    bwq.course_code,
    bwq.course,
    bwq.subtopic_id,
    bwq.subtopic_code,
    bwq.subtopic,
    bwq.topic_id,
    bwq.topic_code,
    bwq.topic,
    bwq.level_id,
    bwq.level_description,
    bwq.level_name,
    bwq.question_id,
    bwq.type
FROM
    ballot_with_questions bwq;

    RETURN QUERY
    SELECT
        *
    FROM
        temp_excluded_questions_result;
END;
$$;


ALTER FUNCTION odiseo.fn_update_and_find_excluded_questions(p_week_type_material_id integer, p_deleted_by integer) OWNER TO postgres;

--
-- Name: fn_update_and_find_excluded_questions_exam(bigint, bigint, smallint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_and_find_excluded_questions_exam(p_question_id bigint, p_material_id bigint, p_type_material_id smallint, p_week smallint, p_deleted_by bigint) RETURNS TABLE(id bigint, question_id bigint, question_history_id bigint, type_material_id smallint, type_material character varying, week smallint, course_id smallint, code_course character varying, course character varying, topic_id smallint, code_topic character varying, topic character varying, subtopic_id smallint, code_subtopic character varying, subtopic character varying, level_id bigint, level_description character varying, level_name character varying, area_id smallint, exam_area character varying, data_incomplete_questions character varying, material_exam_area_week_id bigint, week_type_material_id bigint, type character varying)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                WITH context_material AS (
                    SELECT
                        meaw.id as material_exam_area_week_id,
                        meaw.week_type_material_id,
                        meaw.area_id
                    FROM detail_week_type_mat dwtm
                    JOIN material_exam_area_week meaw ON dwtm.id = meaw.week_type_material_id
                    WHERE dwtm.material_id = p_material_id
                        AND dwtm.type_material_id = p_type_material_id
                        AND dwtm.week = p_week
                        AND meaw.fl_status = TRUE
                ), excluded_questions_source AS (
                    SELECT
                        meq.id,
                        meq.question_id,
                        meq.question_history_id,
                        dwtm.type_material_id,
                        tm.description AS type_material,
                        dwtm.week,
                        meq.course_id,
                        c.code AS code_course,
                        c.name AS course,
                        meq.topic_id,
                        t.code AS code_topic,
                        t.name AS topic,
                        meq.subtopic_id,
                        st.code AS code_subtopic,
                        st.name AS subtopic,
                        meq.level_id,
                        l.description AS level_description,
                        l.name AS level_name,
                        meaw.area_id,
                        ea.description AS exam_area,
                        meaw.data_incomplete_questions,
                        meaw.id AS material_exam_area_week_id,
                        dwtm.id AS week_type_material_id,
                        meq.type
                    FROM material_exam_question meq
                    JOIN material_exam_area_week meaw ON meq.material_exam_area_week_id = meaw.id
                    JOIN detail_week_type_mat dwtm ON meaw.week_type_material_id = dwtm.id
                    JOIN exam_area ea ON meaw.area_id = ea.id
                    JOIN type_material tm ON dwtm.type_material_id = tm.id
                    JOIN course c ON meq.course_id = c.id
                    LEFT JOIN topic t ON meq.topic_id = t.id
                    LEFT JOIN subtopic st ON meq.subtopic_id = st.id
                    LEFT JOIN level l ON meq.level_id = l.id
                    WHERE meq.fl_status = TRUE
                        AND meq.question_id = p_question_id
                        AND meaw.week_type_material_id IN (SELECT cm.week_type_material_id FROM context_material cm)
                        AND EXISTS (
                            SELECT 1
                            FROM question_excluded_material qem
                            WHERE qem.question_id = p_question_id
                            AND qem.material_id = p_material_id
                            AND qem.deleted_at IS NULL
                        )
                ), all_occurrences_to_delete AS (
                    SELECT
                        meq.id,
                        meq.question_id,
                        meq.question_history_id
                    FROM material_exam_question meq
                    JOIN material_exam_area_week meaw ON meq.material_exam_area_week_id = meaw.id
                    WHERE meq.fl_status = TRUE
                        AND meq.question_id IN (SELECT eqs.question_id FROM excluded_questions_source eqs)
                        AND meaw.week_type_material_id IN (SELECT cm.week_type_material_id FROM context_material cm)
                ), exam_update_result AS (
                    UPDATE material_exam_question meq
                    SET
                        topic_id = null,
                        subtopic_id = null,
                        question_id = null,
                        question_history_id = null,
                        fl_is_manual = true,
                        type = null,
                        updated_by = p_deleted_by,
                        updated_at = now()
                    FROM all_occurrences_to_delete aod
                    WHERE meq.id = aod.id
                ), update_history AS (
                    UPDATE question_history_cycle qhc
                    SET
                        fl_status = FALSE,
                        deleted_by = p_deleted_by,
                        deleted_at = NOW()
                    WHERE qhc.id IN (SELECT actd.question_history_id FROM all_occurrences_to_delete actd)
                    AND NOT EXISTS (
                        SELECT 1 FROM material_ballot_question mbq
                        WHERE mbq.question_history_id = qhc.id AND mbq.fl_status = TRUE
                    )
                    AND NOT EXISTS (
                        SELECT 1 FROM material_exam_question meq
                        WHERE meq.question_history_id = qhc.id AND meq.fl_status = TRUE
                            AND meq.id NOT IN (SELECT actd.id FROM all_occurrences_to_delete actd)
                    )
                )
                SELECT
                    eqs.*
                FROM excluded_questions_source eqs;
            END;
            $$;


ALTER FUNCTION odiseo.fn_update_and_find_excluded_questions_exam(p_question_id bigint, p_material_id bigint, p_type_material_id smallint, p_week smallint, p_deleted_by bigint) OWNER TO postgres;

--
-- Name: fn_update_and_find_unverified_questions(integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_and_find_unverified_questions(p_week_type_material_id integer, p_deleted_by integer) RETURNS TABLE(id bigint, material_distribution_id bigint, type_material_id smallint, week smallint, course_id smallint, code_course character varying, course character varying, subtopic_id smallint, code_subtopic character varying, subtopic character varying, topic_id smallint, code_topic character varying, topic character varying, level_id bigint, level_description character varying, level_name character varying, question_id bigint, type character varying)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            WITH unverified_slots AS (
                SELECT
                    mbq.id AS id,
                    dwtm.type_material_id,
                    dwtm.week,
                    mbq.course_id,
                    c.code AS course_code,
                    c.name AS course,
                    mbq.subtopic_id,
                    st.code AS subtopic_code,
                    st.name AS subtopic,
                    mbq.topic_id,
                    t.code AS topic_code,
                    t.name AS topic,
                    mbq.level_id,
                    l.description AS level_description,
                    l.name AS level_name,
                    q.id AS question_id,
                    mbq.type AS type,
                    mbq.question_history_id
                FROM material_ballot_question mbq
                INNER JOIN detail_week_type_mat dwtm ON mbq.week_type_material_id = dwtm.id
                LEFT JOIN question q ON q.id = COALESCE(mbq.question_id, mbq.parent_question_id)
                INNER JOIN course c ON mbq.course_id = c.id
                LEFT JOIN topic t ON t.id = mbq.topic_id
                LEFT JOIN subtopic st ON mbq.subtopic_id = st.id
                LEFT JOIN level l ON mbq.level_id = l.id
                WHERE 1 = 1
                  AND mbq.fl_status IS TRUE
                  AND mbq.week_type_material_id = p_week_type_material_id
                  AND q.status NOT IN ('VERI', 'APRB')
            ), slot_to_update AS (
                UPDATE material_ballot_question mbqu
                   SET
                    usage_level_id = NULL,
                    usage_status = TRUE,
                    question_id = NULL,
                    parent_question_id = NULL,
                    state = 'MISSING',
                    updated_by = p_deleted_by,
                    updated_at = NOW()
                WHERE 1 = 1
                  AND mbqu.fl_status IS TRUE
                  AND mbqu.id IN ( SELECT us.id FROM unverified_slots us )
                RETURNING mbqu.id, mbqu.question_history_id
            ), subquestions_to_delete AS (
                UPDATE material_ballot_subquestions mbs
                SET fl_status = FALSE, deleted_at = NOW()
                WHERE material_ballot_question_id IN ( SELECT id FROM slot_to_update )
                  AND fl_status = TRUE
            ), question_history_cycle_to_update AS (
                UPDATE question_history_cycle qhc
                  SET
                    fl_status = FALSE,
                    deleted_by = p_deleted_by,
                    deleted_at = NOW()
                WHERE 1 = 1
                  AND qhc.id IN ( SELECT us.question_history_id FROM unverified_slots us WHERE us.question_history_id IS NOT NULL )
                  AND NOT EXISTS( -- Que no existan question_history_id en preguntas activas de materiales balotario distintas a las que han salido en esta operación
                    SELECT 1 FROM material_ballot_question mqq
                    WHERE 1 = 1 
                      AND mqq.fl_status IS TRUE
                      AND mqq.question_history_id = qhc.id
                      AND ( mqq.id NOT IN ( SELECT id FROM slot_to_update ) )
                  )
                  AND NOT EXISTS( -- Que no existan question_history_id en preguntas activas de materiales examen distintas a las que han salido en esta operación
                    SELECT 1 FROM material_exam_question meq
                    WHERE 1 = 1
                      AND meq.fl_status IS TRUE
                      AND meq.question_history_id = qhc.id
                  )
            )
            SELECT
                us.id,
                us.id AS material_distribution_id,
                us.type_material_id,
                us.week,
                us.course_id,
                us.course_code,
                us.course,
                us.subtopic_id,
                us.subtopic_code,
                us.subtopic,
                us.topic_id,
                us.topic_code,
                us.topic,
                us.level_id,
                us.level_description,
                us.level_name,
                us.question_id,
                us.type
            FROM unverified_slots us;
        END;
        $$;


ALTER FUNCTION odiseo.fn_update_and_find_unverified_questions(p_week_type_material_id integer, p_deleted_by integer) OWNER TO postgres;

--
-- Name: fn_update_and_find_unverified_subquestion_ballot(integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_and_find_unverified_subquestion_ballot(p_week_type_material_id integer, p_deleted_by integer) RETURNS TABLE(id bigint, material_distribution_id bigint, type_material_id smallint, week smallint, course_id smallint, code_course character varying, course character varying, subtopic_id smallint, code_subtopic character varying, subtopic character varying, topic_id smallint, code_topic character varying, topic character varying, question_id bigint)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY
                    WITH ballot_question_unverified AS (
                        SELECT 
                            mbs.id AS id,
                            mbq.id AS material_distribution_id,
                            dwtm.type_material_id,
                            dwtm.week,
                            mbq.course_id,
                            c.code AS code_course,
                            c.name AS course,
                            mbq.subtopic_id,
                            st.code AS code_subtopic,
                            st.name AS subtopic,
                            mbq.topic_id,
                            t.code AS code_topic,
                            t.name AS topic,
                            q.id AS question_id
                        FROM odiseo.material_ballot_subquestions mbs
                        JOIN odiseo.material_ballot_question mbq ON mbq.id = mbs.material_ballot_question_id AND mbq.fl_status IS TRUE
                        INNER JOIN odiseo.detail_week_type_mat dwtm ON mbq.week_type_material_id = dwtm.id
                        JOIN odiseo.question q ON q.id = mbs.question_id AND q.fl_status IS TRUE
                        JOIN odiseo.course c ON mbq.course_id = c.id
                        JOIN odiseo.topic t ON mbq.topic_id = t.id
                        JOIN odiseo.subtopic st ON mbq.subtopic_id = st.id
                        WHERE mbs.fl_status IS TRUE
                        AND mbq.week_type_material_id = p_week_type_material_id
                        AND q.status NOT IN ('VERI', 'APRB')
                    ), 
                    distribution_to_update AS (
                        UPDATE odiseo.material_ballot_question mbq
                        SET
                        updated_at = NOW(),
                        updated_by = p_deleted_by
                        WHERE mbq.id IN (SELECT bbd.material_distribution_id FROM ballot_question_unverified bbd)
                    ), 
                    ballot_to_update AS (
                        UPDATE odiseo.material_ballot_subquestions mbs
                        SET fl_status = FALSE,
                            deleted_at = NOW()
                        WHERE mbs.id IN ( SELECT bbq.id FROM ballot_question_unverified bbq )
                        RETURNING mbs.id
                    ), 
                    question_history_cycle_to_update AS (
                        UPDATE odiseo.question_history_cycle qhc
                        SET
                            fl_status = FALSE,
                            deleted_by = p_deleted_by,
                            deleted_at = NOW()
                        WHERE qhc.question_id IN ( SELECT bbd.question_id FROM ballot_question_unverified bbd )
                          AND qhc.cycle_id = (SELECT m.cycle_id FROM odiseo.material m JOIN odiseo.detail_week_type_mat d ON d.material_id = m.id WHERE d.id = p_week_type_material_id LIMIT 1)
                          AND qhc.university_id = (SELECT m.university_id FROM odiseo.material m JOIN odiseo.detail_week_type_mat d ON d.material_id = m.id WHERE d.id = p_week_type_material_id LIMIT 1)
                          AND qhc.headquarters_id = (SELECT m.headquarte_id FROM odiseo.material m JOIN odiseo.detail_week_type_mat d ON d.material_id = m.id WHERE d.id = p_week_type_material_id LIMIT 1)
                          AND qhc.fl_status = TRUE
                    )
                    SELECT
                        *
                    FROM ballot_question_unverified;

                END;
            $$;


ALTER FUNCTION odiseo.fn_update_and_find_unverified_subquestion_ballot(p_week_type_material_id integer, p_deleted_by integer) OWNER TO postgres;

--
-- Name: fn_update_answer_correct_ia(bigint, bigint, boolean, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_answer_correct_ia(p_question_ia_id bigint, p_answer_id bigint, p_fl_text boolean, p_updated_by bigint) RETURNS TABLE(question_ia_id bigint)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            WITH get_alternative_correct AS ( -- Trae la data de la alternativa correcta
                SELECT
                    aqia.description
                FROM alternative_questions_ia aqia
                WHERE aqia.id = p_answer_id
                    AND aqia.question_ia_id = p_question_ia_id
            ), update_alternative AS ( -- Editar la alternativa correcta
                UPDATE question_teacher_ia qtia
                SET
                    answer_id = p_answer_id,
                    answer_description = CASE
                        WHEN p_fl_text IS TRUE THEN (SELECT gac.description FROM get_alternative_correct gac)
                        ELSE qtia.description
                    END,
                    updated_by = p_updated_by,
                    updated_at = NOW()
                WHERE qtia.id = p_question_ia_id
                RETURNING qtia.id AS question_ia_id
            )
            SELECT ua.question_ia_id FROM update_alternative ua;
        END;
        $$;


ALTER FUNCTION odiseo.fn_update_answer_correct_ia(p_question_ia_id bigint, p_answer_id bigint, p_fl_text boolean, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_update_area(integer, character varying, character varying, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_area(p_id integer, p_slug character varying, p_description character varying, p_updated_by integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_area_id INTEGER;
                v_count INTEGER;
            BEGIN
                SELECT COUNT(*)
                INTO v_count
                FROM odiseo.area
                WHERE LOWER(description) = LOWER(p_description) AND id <> p_id;

                IF v_count = 0 THEN
                    UPDATE odiseo.area
                    SET
                    slug = p_slug,
                    description = p_description,
                    updated_by = p_updated_by,
                    updated_at = now()
                    WHERE
                        id = p_id
                    RETURNING id INTO v_area_id;

                    RETURN v_area_id;
                ELSE
                    RETURN NULL;
                END IF;

            END;
            $$;


ALTER FUNCTION odiseo.fn_update_area(p_id integer, p_slug character varying, p_description character varying, p_updated_by integer) OWNER TO postgres;

--
-- Name: fn_update_company(bigint, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_company(p_id bigint, p_social_reason character varying, p_commercial_name character varying, p_type_company character varying, p_document_number character varying, p_domain_email character varying, p_address character varying, p_city character varying, p_state character varying, p_main_number character varying, p_other_number character varying, p_updated_by bigint) RETURNS TABLE(v_validated boolean, v_type integer, v_id bigint)
    LANGUAGE plpgsql
    AS $$
			DECLARE
				v_exists_social_reason BIGINT;
				v_exists_document_number BIGINT;
				v_new_id BIGINT;
            BEGIN
                -- Validar si existe la misma razon social
                SELECT id INTO v_exists_social_reason
                FROM odiseo.companies
                WHERE social_reason = p_social_reason
                AND id <> p_id
                AND fl_status = true
                LIMIT 1;

                IF v_exists_social_reason IS NULL THEN
                    -- Validar si existe el mismo nro de documento
                    SELECT id INTO v_exists_document_number
                    FROM odiseo.companies
                    WHERE document_number = p_document_number
                    AND id <> p_id
                    AND fl_status = true
                    LIMIT 1;

                    IF v_exists_document_number IS NULL THEN
                        UPDATE odiseo.companies
                        SET
                            social_reason = COALESCE(p_social_reason, social_reason),
                            commercial_name = COALESCE(p_commercial_name, commercial_name),
                            type_company = COALESCE(p_type_company, type_company),
                            document_number = COALESCE(p_document_number, document_number),
                            domain_email = COALESCE(p_domain_email, domain_email),
                            address = COALESCE(p_address, address),
                            city = COALESCE(p_city, city),
                            state = COALESCE(p_state, state),
                            main_number = COALESCE(p_main_number, main_number),
                            other_number = COALESCE(p_other_number, other_number),
                            updated_by = p_updated_by, updated_at = now()
                        WHERE id = p_id
                        RETURNING id INTO v_new_id;

                        RETURN QUERY SELECT TRUE, 0, v_new_id;
                        RETURN;
                    ELSE
                        RETURN QUERY SELECT FALSE, 2, 0::BIGINT;
                        RETURN;
                    END IF;
                ELSE
					RETURN QUERY SELECT FALSE, 1, 0::BIGINT;
                    RETURN;
                END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_update_company(p_id bigint, p_social_reason character varying, p_commercial_name character varying, p_type_company character varying, p_document_number character varying, p_domain_email character varying, p_address character varying, p_city character varying, p_state character varying, p_main_number character varying, p_other_number character varying, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_update_configuration_diagrammed_course(bigint, jsonb, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_configuration_diagrammed_course(p_course_id bigint, p_setting_diagram_course jsonb, p_category_text_id bigint, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                        IF EXISTS (
                            SELECT 1
                            FROM setting_diagrammed_courses sdc
                            WHERE sdc.course_id = p_course_id
                                AND (
                                    (p_category_text_id IS NULL AND sdc.category_text_id IS NULL) OR
                                    (p_category_text_id IS NOT NULL AND sdc.category_text_id = p_category_text_id)
                                )
                                AND sdc.fl_status = true
                        ) THEN
                            -- Se elimina loss diagramas de cursos que no se mandaron
                            UPDATE setting_diagrammed_courses
                            SET fl_status = false,
                                fl_optional = true,
                                updated_by = p_updated_by,
                                updated_at = NOW()
                            WHERE course_id = p_course_id
                                AND (
                                    (p_category_text_id IS NULL AND setting_diagrammed_courses.category_text_id IS NULL) OR
                                    (p_category_text_id IS NOT NULL AND setting_diagrammed_courses.category_text_id = p_category_text_id)
                                )
                                AND fl_status = true
                                AND field_diagram_id NOT IN (
                                    SELECT
                                        (sdc->>'field_diagram_id')::BIGINT
                                    FROM jsonb_array_elements(p_setting_diagram_course) AS sdc
                                    WHERE (sdc->>'field_diagram_id') IS NOT NULL
                                );

                            -- Se actualiza la posicion de los diagramas de cursos mandados y existentes
                            UPDATE setting_diagrammed_courses
                            SET position = (sdc->>'position')::INT,
                                fl_active = (sdc->>'fl_active')::BOOL,
                                fl_optional = (sdc->>'fl_optional')::BOOL,
                                fl_status = true,
                                updated_by = p_updated_by,
                                updated_at = now()
                            FROM jsonb_array_elements(p_setting_diagram_course) AS sdc
                            WHERE course_id = p_course_id
                                AND fl_status = true
                                AND (sdc->>'field_diagram_id')::BIGINT = setting_diagrammed_courses.field_diagram_id
                                AND (
                                    (p_category_text_id IS NULL AND setting_diagrammed_courses.category_text_id IS NULL) OR
                                    (p_category_text_id IS NOT NULL AND p_category_text_id = setting_diagrammed_courses.category_text_id)
                                );

                            -- Insertamos los nuevos registros que no están en la base de datos
                            INSERT INTO setting_diagrammed_courses (
                                course_id,
                                field_diagram_id,
                                "position",
                                category_text_id,
                                fl_active,
                                fl_optional,
                                created_by,
                                created_at
                            )
                            SELECT
                                p_course_id,
                                (sdc->>'field_diagram_id')::BIGINT AS field_diagram_id,
                                (sdc->>'position')::INT AS position,
                                p_category_text_id AS category_text_id,
                                (sdc->>'fl_active')::BOOL AS fl_active,
                                (sdc->>'fl_optional')::BOOL AS fl_optional,
                                p_updated_by AS created_by,
                                NOW() AS created_at
                            FROM jsonb_array_elements(p_setting_diagram_course) AS sdc
                            WHERE (sdc->>'field_diagram_id')::BIGINT NOT IN (
                                SELECT field_diagram_id
                                FROM setting_diagrammed_courses
                                WHERE course_id = p_course_id
                                    AND fl_status = true
                                    AND (
                                    (p_category_text_id IS NULL AND setting_diagrammed_courses.category_text_id IS NULL) OR
                                    (p_category_text_id IS NOT NULL AND setting_diagrammed_courses.category_text_id = p_category_text_id)
                                )
                            );
                        END IF;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_update_configuration_diagrammed_course(p_course_id bigint, p_setting_diagram_course jsonb, p_category_text_id bigint, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_update_course_category(bigint, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_course_category(p_assigned_cat_id bigint, p_new_category_name character varying, p_user_id bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_type_text_id INT;
            BEGIN
                SELECT type_text_id INTO v_type_text_id 
                FROM course_assigned_categories 
                WHERE id = p_assigned_cat_id;

                UPDATE type_text 
                SET name = p_new_category_name 
                WHERE id = v_type_text_id;

                UPDATE course_assigned_categories 
                SET updated_by = p_user_id, 
                    updated_at = CURRENT_TIMESTAMP 
                WHERE id = p_assigned_cat_id;

                RETURN p_assigned_cat_id;
            END;
            $$;


ALTER FUNCTION odiseo.fn_update_course_category(p_assigned_cat_id bigint, p_new_category_name character varying, p_user_id bigint) OWNER TO postgres;

--
-- Name: fn_update_course_subcategory(bigint, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_course_subcategory(p_assigned_sub_id bigint, p_new_subcategory_name character varying, p_user_id bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_subcategory_id INT;
            BEGIN
                SELECT subcategory_id INTO v_subcategory_id 
                FROM course_assigned_subcategories 
                WHERE id = p_assigned_sub_id;

                UPDATE type_text_subcategories 
                SET name = p_new_subcategory_name 
                WHERE id = v_subcategory_id;

                UPDATE course_assigned_subcategories 
                SET updated_by = p_user_id, 
                    updated_at = CURRENT_TIMESTAMP 
                WHERE id = p_assigned_sub_id;

                RETURN p_assigned_sub_id;
            END;
            $$;


ALTER FUNCTION odiseo.fn_update_course_subcategory(p_assigned_sub_id bigint, p_new_subcategory_name character varying, p_user_id bigint) OWNER TO postgres;

--
-- Name: fn_update_cycle(bigint, character varying, character varying, smallint, smallint, date, date, smallint, smallint, smallint, bigint, jsonb, boolean, integer, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_cycle(p_id bigint, p_code character varying, p_description character varying, p_month smallint, p_year smallint, p_start_date date, p_end_date date, p_weeks smallint, p_cycle_type_id smallint, p_days smallint, p_type_template_id bigint, p_cycle_weeks jsonb, p_active boolean, p_company_id integer, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                        -- 1. Actualización del Ciclo Principal
                        UPDATE cycle
                        SET code = p_code,
                            description = p_description,
                            month = p_month,
                            year = p_year,
                            cycle_type_id = p_cycle_type_id,
                            start_date = p_start_date,
                            end_date = p_end_date,
                            weeks = p_weeks,
                            days = p_days,
                            active = p_active,
                            type_template_id = p_type_template_id,
                            updated_by = p_updated_by,
                            updated_at = now()
                        WHERE id = p_id;

                        -- 2. Upsert Masivo de Semanas
                        INSERT INTO cycle_weeks (week, type_week_id, cycle_id, start_date, end_date, created_by, created_at)
                        SELECT 
                            (w->>'week')::smallint,
                            (w->>'type_week_id')::bigint,
                            p_id,
                            (w->>'start_date')::date,
                            (w->>'end_date')::date,
                            p_updated_by,
                            now()
                        FROM jsonb_array_elements(p_cycle_weeks) AS w
                        ON CONFLICT (cycle_id, start_date) WHERE (fl_status IS TRUE)
                        DO UPDATE SET 
                            week = EXCLUDED.week,
                            type_week_id = EXCLUDED.type_week_id,
                            end_date = EXCLUDED.end_date,
                            updated_by = EXCLUDED.created_by,
                            updated_at = now();

                        -- 3. Desactivar semanas que no están en el JSON
                         UPDATE cycle_weeks
                        SET fl_status = FALSE,
                            updated_by = p_updated_by,
                            updated_at = now()
                        WHERE cycle_id = p_id 
                        AND fl_status IS TRUE
                        AND start_date NOT IN (
                            SELECT (w->>'start_date')::date 
                            FROM jsonb_array_elements(p_cycle_weeks) AS w
                            WHERE (w->>'start_date') IS NOT NULL
                        );

                        -- 4. Eliminar configuraciones posteriores si se reducen las semanas
                        PERFORM fn_clean_cycle_posterior_weeks(
                            p_id, 
                            (SELECT MAX((w->>'week')::smallint) FROM jsonb_array_elements(p_cycle_weeks) AS w)
                        );

                    END;
                    $$;


ALTER FUNCTION odiseo.fn_update_cycle(p_id bigint, p_code character varying, p_description character varying, p_month smallint, p_year smallint, p_start_date date, p_end_date date, p_weeks smallint, p_cycle_type_id smallint, p_days smallint, p_type_template_id bigint, p_cycle_weeks jsonb, p_active boolean, p_company_id integer, p_updated_by bigint) OWNER TO postgres;

