--
-- Name: fn_update_essential_knowledge(bigint, character varying, character varying, bigint, bigint, text, text, text, character varying, bigint, timestamp without time zone); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_essential_knowledge(p_id bigint, p_code character varying, p_name character varying, p_topic_id bigint, p_course_id bigint, p_editor_content text, p_thumbnail text, p_filename text, p_extension character varying, p_updated_by bigint, p_updated_at timestamp without time zone) RETURNS TABLE(topic_id bigint, course_id bigint, name character varying, file_name text, code character varying, id bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE essential_knowledges
    SET 
        code = p_code,
        name = p_name,
        topic_id = p_topic_id,
        course_id = p_course_id,
        editor_content = p_editor_content,
        thumbnail = p_thumbnail,
        updated_by = p_updated_by,
        updated_at = p_updated_at
    WHERE essential_knowledges.id = p_id;

    UPDATE essential_knowledge_image
    SET 
        deleted_at = p_updated_at,
        deleted_by = p_updated_by
    WHERE essential_knowledge_id = p_id AND deleted_at IS NULL;

    INSERT INTO essential_knowledge_image (essential_knowledge_id, image, extension, created_by, updated_at)
    VALUES (p_id, p_filename, p_extension, p_updated_by, p_updated_at);

    RETURN QUERY
    SELECT
        p_topic_id,
        p_course_id,
        p_name,
        p_filename,
        p_code,
        p_id;
END;
$$;


ALTER FUNCTION odiseo.fn_update_essential_knowledge(p_id bigint, p_code character varying, p_name character varying, p_topic_id bigint, p_course_id bigint, p_editor_content text, p_thumbnail text, p_filename text, p_extension character varying, p_updated_by bigint, p_updated_at timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_update_essential_knowledge_by_question(bigint, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_essential_knowledge_by_question(p_question_id bigint, p_essential_knowledge_ids jsonb, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN

    -- Si viene null, lo tratamos como array vacío
    p_essential_knowledge_ids := COALESCE(p_essential_knowledge_ids, '[]'::jsonb);

    WITH incoming_essential_knowledges AS (
        SELECT DISTINCT value::bigint AS id
        FROM jsonb_array_elements_text(p_essential_knowledge_ids) AS items(value)
    ),

    -- Restaurar (soft delete revertido)
    restored AS (
        UPDATE essential_knowledge_questions ekq
        SET
            deleted_at = NULL,
            deleted_by = NULL,
            updated_at = now(),
            updated_by = p_updated_by
        FROM incoming_essential_knowledges incoming
        WHERE ekq.question_id = p_question_id
          AND ekq.essential_knowledge_id = incoming.id
          AND ekq.deleted_at IS NOT NULL
        RETURNING ekq.id
    ),

    -- Insertar nuevos
    inserted AS (
        INSERT INTO essential_knowledge_questions (
            question_id,
            essential_knowledge_id,
            created_by,
            created_at
        )
        SELECT
            p_question_id,
            incoming.id,
            p_updated_by,
            now()
        FROM incoming_essential_knowledges incoming
        WHERE NOT EXISTS (
            SELECT 1
            FROM essential_knowledge_questions ekq
            WHERE ekq.question_id = p_question_id
              AND ekq.essential_knowledge_id = incoming.id
        )
        RETURNING id
    )

    -- Soft delete de los que ya no vienen
    UPDATE essential_knowledge_questions ekq
    SET
        deleted_at = now(),
        deleted_by = p_updated_by
    WHERE ekq.question_id = p_question_id
      AND ekq.deleted_at IS NULL
      AND NOT EXISTS (
          SELECT 1
          FROM incoming_essential_knowledges incoming
          WHERE incoming.id = ekq.essential_knowledge_id
      );

END;
$$;


ALTER FUNCTION odiseo.fn_update_essential_knowledge_by_question(p_question_id bigint, p_essential_knowledge_ids jsonb, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_update_file_document_solution(bigint, bigint, character varying, smallint, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_file_document_solution(p_question_id bigint, p_document_id bigint, p_path character varying, p_type_archive_id smallint, p_user integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_employee_question_id INT;

        BEGIN
            SELECT eq.id
            INTO v_employee_question_id
            FROM odiseo.employee_question eq
            WHERE eq.question_id = p_question_id
            AND eq.fl_status = TRUE
            AND eq.deleted_at IS NULL;

            IF p_document_id IS NULL THEN
                INSERT INTO odiseo.employee_question_document (
                    employee_question_id,
                    type_archive_id,
                    "document",
                    created_by,
                    created_at
                )
                VALUES (
                    v_employee_question_id,
                    p_type_archive_id,
                    p_path,
                    p_user,
                    NOW()
                );
            ELSE
                UPDATE odiseo.employee_question_document
                SET type_archive_id = p_type_archive_id,
                    "document" = p_path,
                    document_refuzed = NULL,
                    fl_refuzed = FALSE,
                    updated_by = p_user,
                    updated_at = NOW()
                WHERE employee_question_id = v_employee_question_id
                AND id = p_document_id;
            END IF;
        END;
        $$;


