CREATE FUNCTION odiseo.fn_update_material_ballot_question(p_distribution_id bigint, p_position smallint, p_position_initial smallint, p_topic_id smallint, p_subtopic_id bigint, p_level_id bigint, p_usage_level_id bigint, p_question_id bigint, p_type character varying, p_usage_status boolean, p_updated_by bigint) RETURNS void
