--
-- Name: fn_update_material_per_period_level_limit_config(bigint, smallint, smallint, smallint, smallint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_material_per_period_level_limit_config(p_material_per_period_id bigint, p_start_week smallint, p_end_week smallint, p_lower_level_limit smallint DEFAULT 1, p_upper_level_limit smallint DEFAULT 1, p_updated_by bigint DEFAULT NULL::bigint) RETURNS TABLE(id bigint, material_per_period_id bigint, material_id bigint, type_material_id smallint, period_start_week smallint, period_end_week smallint, start_week smallint, end_week smallint, lower_level_limit smallint, upper_level_limit smallint, created_by integer, created_by_name character varying, updated_by integer, updated_by_name character varying, deleted_by integer, deleted_by_name character varying, created_at timestamp without time zone, updated_at timestamp without time zone, deleted_at timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id BIGINT;
BEGIN
    UPDATE material_per_period_level_limit_config
    SET
        lower_level_limit = COALESCE(p_lower_level_limit, 1),
        upper_level_limit = COALESCE(p_upper_level_limit, 1),
        updated_by = p_updated_by,
        updated_at = NOW()
    WHERE material_per_period_level_limit_config.material_per_period_id = p_material_per_period_id
      AND material_per_period_level_limit_config.start_week = p_start_week
      AND material_per_period_level_limit_config.end_week = p_end_week
      AND material_per_period_level_limit_config.deleted_at IS NULL
    RETURNING material_per_period_level_limit_config.id INTO v_id;

    RETURN QUERY
    SELECT
        mpllc.id,
        mpllc.material_per_period_id,
        mpp.material_id,
        mpp.type_material_id,
        mpp.start_week AS period_start_week,
        mpp.end_week AS period_end_week,
        mpllc.start_week,
        mpllc.end_week,
        mpllc.lower_level_limit,
        mpllc.upper_level_limit,
        mpllc.created_by,
        uc."user" AS created_by_name,
        mpllc.updated_by,
        uu."user" AS updated_by_name,
        mpllc.deleted_by,
        ud."user" AS deleted_by_name,
        mpllc.created_at,
        mpllc.updated_at,
        mpllc.deleted_at
    FROM material_per_period_level_limit_config mpllc
    JOIN material_per_period mpp ON mpp.id = mpllc.material_per_period_id
    LEFT JOIN users uc ON uc.id = mpllc.created_by
    LEFT JOIN users uu ON uu.id = mpllc.updated_by
    LEFT JOIN users ud ON ud.id = mpllc.deleted_by
    WHERE mpllc.id = v_id;
END;
$$;


ALTER FUNCTION odiseo.fn_update_material_per_period_level_limit_config(p_material_per_period_id bigint, p_start_week smallint, p_end_week smallint, p_lower_level_limit smallint, p_upper_level_limit smallint, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_update_material_revision_course_status(bigint, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_material_revision_course_status(p_id bigint, p_new_status character varying, p_user_id bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_old_status varchar;
    v_revision_id bigint;
    v_course_id smallint;
BEGIN
    -- Fetch current state and lock for update
    SELECT status, material_revision_id, course_id 
    INTO v_old_status, v_revision_id, v_course_id
    FROM material_revision_courses
    WHERE id = p_id AND deleted_at IS NULL
    FOR UPDATE;

    IF v_old_status IS DISTINCT FROM p_new_status THEN
        -- Update the course record
        UPDATE material_revision_courses
        SET status = p_new_status,
            updated_at = NOW(),
            updated_by = p_user_id,
            verify_date = CASE WHEN p_new_status = 'verified' THEN NOW() ELSE verify_date END,
            verified_by = CASE WHEN p_new_status = 'verified' THEN p_user_id ELSE verified_by END
        WHERE id = p_id;

        -- Check if all courses for this revision are now verified
        IF p_new_status = 'verified' THEN
            IF NOT EXISTS (
                SELECT 1 
                FROM material_revision_courses 
                WHERE material_revision_id = v_revision_id 
                  AND status != 'verified' 
                  AND deleted_at IS NULL
            ) THEN
                -- Update parent revision
                UPDATE material_revisions
                SET status = 'verified',
                    verify_date = NOW(),
                    verified_by = p_user_id,
                    updated_at = NOW(),
                    updated_by = p_user_id
                WHERE id = v_revision_id;

                -- Record parent history
                INSERT INTO material_revision_histories (
                    material_revision_id, old_status, new_status, changed_by, changed_at
                ) VALUES (
                    v_revision_id, 'pdf_delivered', 'verified', p_user_id, NOW()
                );
            END IF;
        END IF;
    END IF;
END;
$$;


ALTER FUNCTION odiseo.fn_update_material_revision_course_status(p_id bigint, p_new_status character varying, p_user_id bigint) OWNER TO postgres;

--
-- Name: fn_update_material_revision_status(bigint, character varying, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_material_revision_status(p_revision_id bigint, p_new_status character varying, p_user_id bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_old_status varchar;
    v_course_rec record;
BEGIN
    SELECT status INTO v_old_status
    FROM material_revisions
    WHERE id = p_revision_id AND deleted_at IS NULL
    FOR UPDATE;

    IF v_old_status IS DISTINCT FROM p_new_status THEN
        UPDATE material_revisions
        SET status = p_new_status,
            updated_at = NOW(),
            updated_by = p_user_id,
            verify_date = CASE WHEN p_new_status = 'verified' THEN NOW() ELSE verify_date END,
            verified_by = CASE WHEN p_new_status = 'verified' THEN p_user_id ELSE verified_by END
        WHERE id = p_revision_id;

        INSERT INTO material_revision_histories (
            material_revision_id, old_status, new_status, changed_by, changed_at
        ) VALUES (
            p_revision_id, v_old_status, p_new_status, p_user_id, NOW()
        );
    END IF;

    -- Propagación a hijos "Confirmar Todo"
    IF p_new_status = 'verified' THEN
        FOR v_course_rec IN 
            SELECT id, status, course_id
            FROM material_revision_courses
            WHERE material_revision_id = p_revision_id 
              AND status != 'verified' 
              AND deleted_at IS NULL
            FOR UPDATE
        LOOP
            UPDATE material_revision_courses
            SET status = 'verified',
                verify_date = NOW(),
                verified_by = p_user_id,
                updated_at = NOW(),
                updated_by = p_user_id
            WHERE id = v_course_rec.id;
        END LOOP;
    END IF;
END;
$$;


ALTER FUNCTION odiseo.fn_update_material_revision_status(p_revision_id bigint, p_new_status character varying, p_user_id bigint) OWNER TO postgres;

--
-- Name: fn_update_parent_question(bigint, text, text, text, text, integer, integer, integer, text, text, bigint, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_parent_question(p_id bigint, p_description text, p_short_description text, p_text_traduction text, p_short_text_traduction text, p_type_text_id integer, p_level_id integer, p_type_text_subcategory_id integer, p_description_b text, p_short_description_b text, p_updated_by bigint, p_question_columns integer, p_priority integer) RETURNS TABLE(id bigint, message boolean, status character, process character varying)
    LANGUAGE plpgsql
    AS $$
    DECLARE
        v_similary_text TEXT;
        v_final_status CHAR(4);
        v_codes_list TEXT;
        v_obs_desc TEXT;
        v_process VARCHAR;
        v_type_text_id INTEGER;
    BEGIN
            --	Verificar si la pregunta tiene duplicados
            WITH subquestion_status AS (
                SELECT
                    q.id,
                    q.parent_id,
                    qs.status,
                    qs.description,
                    qs.process
                FROM question q
                JOIN parent_question pq ON q.parent_id = pq.id
                JOIN (
                    SELECT DISTINCT ON (qs.question_id) *
                    FROM question_status qs
                    WHERE qs.status <> 'DUPL'
                    ORDER BY qs.question_id, qs.created_at DESC
                ) qs ON qs.question_id = q.id
                WHERE q.parent_id = p_id
                ORDER BY qs.status ASC
            )
            SELECT
                qs.status, qs.process
                INTO
                v_final_status, v_process
            FROM subquestion_status qs
            LIMIT 1;

            WITH data_parent_question AS (
                SELECT
                    pq.course_id
                FROM parent_question pq
                WHERE pq.id = p_id
            ), similarity_question AS (
                SELECT fsp.id, (fsp.score * 100)::NUMERIC(10,2) as percentage, fsp.code
                FROM fn_search_similar_parent_questions(
                    p_short_description,
                    (SELECT dpq.course_id FROM data_parent_question dpq)
                ) fsp
                WHERE fsp.id != p_id
            )
            SELECT
                COALESCE(
                    jsonb_agg(jsonb_build_object('id', sq.id, 'percentage', sq.percentage))::TEXT,
                    '[]'
                ),
                CASE
                    WHEN EXISTS (SELECT 1 FROM similarity_question)
                        THEN 'DUPL'
                    ELSE v_final_status
                END,
                string_agg(sq.code, ', ' ORDER BY sq.code ASC),
                CASE
                    WHEN EXISTS (SELECT 1 FROM similarity_question)
                        THEN 'DUPLICADO'
                    ELSE v_process
                END
            INTO v_similary_text, v_final_status, v_codes_list, v_process
            FROM similarity_question sq;

            IF v_final_status = 'DUPL' AND v_codes_list IS NOT NULL THEN
                v_obs_desc := 'Tiene similitud con una o varias preguntas: ' || v_codes_list;
            END IF;

            -- obtener la categoria que tenia la pregunta T antes de cambiarlo.
            SELECT pq.type_text_id INTO v_type_text_id FROM parent_question pq WHERE pq.id = p_id;

            UPDATE parent_question as pq
            SET
                description = p_description,
                short_description = p_short_description,
                text_traduction = p_text_traduction,
                short_text_traduction = p_short_text_traduction,
                type_text_id = COALESCE(p_type_text_id, pq.type_text_id),
                level_id = COALESCE(p_level_id, pq.level_id),
                type_text_subcategory_id = COALESCE( p_type_text_subcategory_id, pq.type_text_subcategory_id),
                description_b = p_description_b,
                short_description_b = p_short_description_b,
                updated_by = p_updated_by,
                updated_at = now(),
                columns = p_question_columns,
                status = v_final_status,
                priority = COALESCE(p_priority, pq.priority)
            WHERE pq.id = p_id;

            -- Deshabilita los parametros de diagramación de las preguntas S si la pregunta T cambió de categoría
            IF v_type_text_id <> p_type_text_id THEN
                WITH subquestions_diagrams AS (SELECT edqf.id FROM parent_question pq  
                JOIN question q
                    ON q.parent_id  = pq.id
                JOIN employee_didi_question edq 
                    ON edq.question_id  = q.id 
                JOIN employee_didi_question_field edqf 
                    ON edqf.employee_didi_question_id = edq.id
                WHERE pq.id = p_id
                )
                UPDATE
                employee_didi_question_field AS edqf
                SET fl_status = false,
                    deleted_at = NOW(),
                    deleted_by = p_updated_by
                WHERE edqf.id IN (SELECT sd.id FROM subquestions_diagrams sd);
            END IF;

            -- Insertar observación si p_observation no es NULL ni vacío
            IF v_final_status = 'DUPL' AND v_codes_list IS NOT NULL THEN
                -- Se elimina las observaciones anteriores
                UPDATE parent_observation as po
                SET fl_status = false,
                    deleted_at = now(),
                    deleted_by = p_updated_by
                WHERE po.parent_id = p_id
                    AND po.fl_status = true
                    AND po.type = 'DUPL';

                INSERT INTO parent_observation (
                    description,
                    similitaries,
                    parent_id,
                    type,
                    fl_status,
                    created_by,
                    created_at
                )
                VALUES (
                    v_obs_desc,
                    v_similary_text,
                    p_id,
                    'DUPL',
                    true,
                    p_updated_by, now()
                );
                --	Si es que el padre esta duplicado en este caso los hijos tambien
                UPDATE question set status = v_final_status WHERE question.parent_id = p_id;

                WITH user_created AS (
                    SELECT
                        CASE WHEN e.id IS NULL
                            THEN 'Administrador'
                            ELSE concat(
                                split_part(e.first_name, ' ', 1),
                                ' ',
                                upper(left(e.first_surname, 1)),
                                '. ',
                                e.second_surname
                            )
                            END user_name,
                            COALESCE(r.name, 'usuario') rol
                    FROM users u
                    JOIN users_roles ur ON u.id = ur.user_id
                        AND ur.fl_status = true
                    JOIN roles r ON ur.rol_id = r.id
                    LEFT JOIN employees e ON u.id = e.user_id
                    WHERE u.id = p_updated_by
                ), desription_archived AS (
                    SELECT
                        CONCAT(
                            'La pregunta se cambió a duplicado por el ',
                            uc.rol,
                            ' <span class="text-user">',
                            uc.user_name,
                            '</span>'
                        )::VARCHAR description,
                        'DUPLICADO' process,
                        'DUPL' status
                    FROM user_created uc
                    LIMIT 1
                ), subquestion AS (
                    SELECT
                        q.id,
                        da.description,
                        da.process,
                        da.status
                    FROM question q, desription_archived da
                    WHERE q.parent_id = p_id
                    AND q.fl_status = true
                ), desactive_status AS (
                    UPDATE question_status
                    SET fl_active = false
                    WHERE question_id IN (
                        SELECT sq.id
                        FROM subquestion sq
                    )
                ), delete_observations_subquestion AS (
                    UPDATE question_observation
                    SET fl_status = false,
                        deleted_at = now(),
                        deleted_by = p_updated_by
                    WHERE question_id IN (
                        SELECT sq.id
                        FROM subquestion sq
                    )
                        AND type = 'DUPL'
                        AND fl_status = true
                )
                INSERT INTO question_status (
                    question_id,
                    status,
                    process,
                    description,
                    created_by,
                    created_at
                )
                SELECT
                    q.id,
                    q.status,
                    q.process,
                    q.description,
                    p_updated_by,
                    NOW()
                FROM subquestion q;
            ELSE
                WITH delete_observation_parent AS (
                    UPDATE parent_observation po
                    SET fl_status = false,
                        deleted_at = now(),
                        deleted_by = p_updated_by
                    WHERE po.parent_id = p_id
                        AND po.type = 'DUPL'
                        AND po.fl_status = true
                ), user_created AS (
                    SELECT
                        CASE WHEN e.id IS NULL
                            THEN 'Administrador'
                            ELSE concat(
                                split_part(e.first_name, ' ', 1),
                                ' ',
                                upper(left(e.first_surname, 1)),
                                '. ',
                                e.second_surname
                            )
                            END user_name,
                            COALESCE(r.name, 'usuario') rol
                    FROM users u
                    JOIN users_roles ur ON u.id = ur.user_id
                        AND ur.fl_status = true
                    JOIN roles r ON ur.rol_id = r.id
                    LEFT JOIN employees e ON u.id = e.user_id
                    WHERE u.id = p_updated_by
                ), desription_archived AS (
                    SELECT
                        CONCAT(
                            'La pregunta se cambió a',
                            LOWER(v_process),
                            ' por el ',
                            uc.rol,
                            ' <span class="text-user">',
                            uc.user_name,
                            '</span>'
                        )::VARCHAR description,
                        v_process AS process,
                        v_final_status AS status
                    FROM user_created uc
                    LIMIT 1
                ), subquestion AS (
                    SELECT
                        q.id,
                        da.description,
                        da.process,
                        da.status
                    FROM question q, desription_archived da
                    WHERE q.parent_id = p_id
                    AND q.fl_status = true
                ), desactive_status AS (
                    UPDATE question_status
                    SET fl_active = false
                    WHERE question_id IN (
                        SELECT s.id
                        FROM subquestion s
                    )
                ), delete_observations_subquestion AS (
                    UPDATE question_observation qo
                    SET fl_status = false,
                        deleted_at = now(),
                        deleted_by = p_updated_by
                    WHERE qo.question_id IN (
                        SELECT sq.id
                        FROM subquestion sq
                    )
                        AND qo.type = 'DUPL'
                        AND qo.fl_status = true
                )
                INSERT INTO question_status (
                    question_id,
                    status,
                    process,
                    description,
                    created_by,
                    created_at
                )
                SELECT
                    q.id,
                    q.status,
                    q.process,
                    q.description,
                    p_updated_by,
                    NOW()
                FROM subquestion q;
            END IF;

            RETURN QUERY
            SELECT
                p_id,
                CASE WHEN v_final_status = 'DUPL' THEN FALSE ELSE TRUE END,
                v_final_status,
                LOWER(v_process)::VARCHAR;
        END;
    $$;


ALTER FUNCTION odiseo.fn_update_parent_question(p_id bigint, p_description text, p_short_description text, p_text_traduction text, p_short_text_traduction text, p_type_text_id integer, p_level_id integer, p_type_text_subcategory_id integer, p_description_b text, p_short_description_b text, p_updated_by bigint, p_question_columns integer, p_priority integer) OWNER TO postgres;

--
-- Name: fn_update_plan(bigint, character varying, character varying, numeric, character varying, integer, integer, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_plan(p_id bigint, p_name character varying, p_description character varying, p_cost numeric, p_benefits character varying, p_number_users integer, p_number_questions integer, p_updated_by bigint) RETURNS TABLE(v_validated boolean, v_id bigint)
    LANGUAGE plpgsql
    AS $$
			DECLARE
				v_exits_id BIGINT;
            BEGIN
				SELECT id INTO v_exits_id
				FROM odiseo."plans"
				WHERE LOWER(name) = LOWER(p_name)
                AND id <> p_id
				LIMIT 1;

				IF v_exits_id IS NULL THEN
                    UPDATE odiseo."plans"
                    SET
                        name = COALESCE(p_name, name),
                        description = COALESCE(p_description, description),
                        cost = COALESCE(p_cost, cost),
                        benefits = COALESCE(p_benefits, benefits),
                        number_users = COALESCE(p_number_users, number_users),
                        number_questions = COALESCE(p_number_questions, number_questions),
                        updated_by = p_updated_by, updated_at = now()
                    WHERE id = p_id
					RETURNING id INTO v_id;

					RETURN QUERY SELECT TRUE, v_id;
				ELSE
					RETURN QUERY SELECT FALSE, 0::BIGINT;
				END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_update_plan(p_id bigint, p_name character varying, p_description character varying, p_cost numeric, p_benefits character varying, p_number_users integer, p_number_questions integer, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_update_question_simple(integer, text, text, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_question_simple(p_id integer, p_description text, p_short_description text, p_updated_by integer, p_course_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
                    DECLARE
                        v_question_id INTEGER;
                        v_count INTEGER;
                    BEGIN
                        UPDATE odiseo.question
                        SET
                            description = p_description,
                            short_description = p_short_description,
                            updated_by = p_updated_by,
                            updated_at = now(),
                            course_id = CASE
                                WHEN p_course_id IS NOT NULL THEN p_course_id
                                ELSE course_id
                            END
                        WHERE
                            id = p_id
                        RETURNING id INTO v_question_id;

                        RETURN v_question_id;
                    END;
                $$;


ALTER FUNCTION odiseo.fn_update_question_simple(p_id integer, p_description text, p_short_description text, p_updated_by integer, p_course_id integer) OWNER TO postgres;

--
-- Name: fn_update_rol_with_permission(bigint, character varying, character varying, character varying, jsonb, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_rol_with_permission(p_id bigint, p_name character varying, p_slug character varying, p_description character varying, p_permissions jsonb, p_updated_by bigint, p_company_id bigint) RETURNS TABLE(id bigint)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        WITH get_rol_user_edit AS (
            SELECT
                ur.rol_id,
                r.fl_administrator
            FROM users_roles ur
            JOIN roles r ON ur.rol_id = r.id
            WHERE ur.user_id = p_updated_by
            AND r.company_id = p_company_id
        ), update_rol AS (
            UPDATE roles as r
            SET
                name = p_name,
                slug = p_slug,
                description = p_description,
                updated_by = p_updated_by,
                company_id = p_company_id
            WHERE r.id = p_id
            RETURNING r.id
        ), deleted_permission AS (
            UPDATE roles_permissions rp
            SET
                fl_status = false
            FROM permissions p
            WHERE rp.permission_id = p.id
                AND rp.rol_id = p_id
                AND rp.fl_status = true
                AND rp.company_id = p_company_id
                AND rp.permission_id NOT IN (
                    SELECT (p.value)::BIGINT
                    FROM jsonb_array_elements(p_permissions) p(value)
                )
                AND (
                    (p.fl_administrator = true and EXISTS (
                        SELECT 1
                        FROM get_rol_user_edit grue
                        WHERE grue.fl_administrator = true
                    )
               ) OR p.fl_administrator = false )
        ), insert_new_permissions AS (
            INSERT INTO roles_permissions (
                rol_id,
                permission_id,
                created_by,
                company_id
            )
            SELECT
                p_id,
                (p.value)::BIGINT,
                p_updated_by,
                p_company_id
            FROM jsonb_array_elements(p_permissions) p(value)
            WHERE NOT EXISTS (
                SELECT 1
                FROM roles_permissions
                WHERE rol_id = p_id
                    AND permission_id = (p.value)::BIGINT
                    AND company_id = p_company_id
                    AND fl_status = true
            )
        )
        SELECT ur.id FROM update_rol ur;

    END;
    $$;


ALTER FUNCTION odiseo.fn_update_rol_with_permission(p_id bigint, p_name character varying, p_slug character varying, p_description character varying, p_permissions jsonb, p_updated_by bigint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_update_set_massive_attributes(jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_set_massive_attributes(p_questions jsonb, f_user_id bigint) RETURNS TABLE(question_code character varying, question_status character varying, error text)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_question JSONB;
            v_row_question odiseo.question%ROWTYPE;
            v_result odiseo.massive_attribute_result;
            v_results odiseo.massive_attribute_result[];

            v_course_id odiseo.course.id%TYPE;
            v_question_ter odiseo.question.ter%TYPE;
            v_question_type odiseo.question.type%TYPE;
            v_topic_id odiseo.topic.id%TYPE;
            v_level_id odiseo.level.id%TYPE;
            v_subtopic_id odiseo.subtopic.id%TYPE;
            v_question_subtopic_id odiseo.question_subtopic.id%TYPE;
            v_alternative_id odiseo.alternative.id%TYPE;
            v_alternative_id_loop odiseo.alternative.id%TYPE;
            v_alternative_index_loop INTEGER := 0;
            v_alternative_letter_loop VARCHAR;
            v_history_status TEXT;
            v_history_process TEXT;
            v_history_description TEXT;
            v_user_name TEXT;
            v_ghost_teacher_id SMALLINT;
            v_ghost_didi_id INTEGER;
            v_is_question_assigned_to_teacher BOOLEAN;
            v_is_question_assigned_to_didi BOOLEAN;
        BEGIN
            SELECT  CASE WHEN e.id IS NOT NULL THEN CONCAT(e.first_name,' ', left(e.first_surname, 1), '. ',' ', e.second_surname) ELSE 'Administrador' END as user
            INTO v_user_name
            FROM  odiseo.users u
            LEFT JOIN odiseo.employees e
            ON u.id = e.user_id
            WHERE u.id = f_user_id;

            SELECT e.id
            INTO v_ghost_teacher_id
            FROM odiseo.employees e
            WHERE e."document" = '33333333' AND e.charge_id = 2;

            SELECT e.id
            INTO v_ghost_didi_id
            FROM odiseo.employees e
            WHERE e."document" = '44444444' AND e.charge_id = 3;


            FOR v_question IN SELECT * FROM jsonb_array_elements_text(p_questions)
            LOOP
                BEGIN
                    SELECT id INTO v_course_id FROM odiseo.course
                        WHERE code = (v_question->>'data')::JSONB->>'course_code'
                        AND fl_status AND deleted_at IS NULL;

                    IF v_course_id IS NOT NULL THEN
                        SELECT id INTO v_topic_id FROM odiseo.topic
                            WHERE code = (v_question->>'data')::JSONB->>'topic_code'
                                AND course_id = v_course_id
                                AND fl_status AND deleted_at IS NULL;
                    ELSE
                        RAISE EXCEPTION 'No se encontró ese curso';
                    END IF;

                    IF v_topic_id IS NULL THEN
                        RAISE EXCEPTION 'No se encontró ese tema de ese curso';
                    END IF;

                    SELECT * INTO v_row_question FROM odiseo.question
                    WHERE number_question = v_question->>'code'
                        AND status != 'ARCH'
                        AND fl_status
                        AND course_id = v_course_id
                        AND deleted_at IS NULL;

                    IF v_row_question IS NULL THEN
                        RAISE EXCEPTION 'No se encontró la pregunta con ese número de problema y curso';
                    END IF;

                    SELECT id INTO v_level_id FROM odiseo.level
                        WHERE name = (v_question->>'data')::JSONB->>'level_name'
                        AND fl_status AND deleted_at IS NULL;
                    v_question_ter := ((v_question->>'data')::JSONB->>'ter');
                    v_question_type := ((v_question->>'data')::JSONB->>'type');

                    FOR v_alternative_id_loop IN
                        SELECT * FROM odiseo.alternative
                        WHERE question_id = v_row_question.id AND fl_status AND deleted_at IS NULL
                        ORDER BY created_at
                    LOOP
                        v_alternative_index_loop := v_alternative_index_loop + 1;

                        IF (v_alternative_index_loop = 1) THEN
                            v_alternative_letter_loop := 'A';
                        ELSIF (v_alternative_index_loop = 2) THEN
                            v_alternative_letter_loop := 'B';
                        ELSIF (v_alternative_index_loop = 3) THEN
                            v_alternative_letter_loop := 'C';
                        ELSIF (v_alternative_index_loop = 4) THEN
                            v_alternative_letter_loop := 'D';
                        ELSIF (v_alternative_index_loop = 5) THEN
                            v_alternative_letter_loop := 'E';
                        END IF;

                        IF (v_alternative_letter_loop) = ((v_question->>'data')::JSONB->>'alternative_correct') THEN
                            v_alternative_id := v_alternative_id_loop;
                            EXIT;
                        END IF;
                    END LOOP;


                    IF v_row_question.status <> 'DUPL' THEN
                        -- Verificar si ya se asigno la pregunta a un docente
                        SELECT CASE WHEN count(*) > 0 THEN true ELSE false END  AS is_question_assigned_to_teacher
                        INTO v_is_question_assigned_to_teacher
                        FROM odiseo.employee_question eq
                        WHERE eq.question_id = v_row_question.id
                        AND eq.fl_status = true;

                        IF v_is_question_assigned_to_teacher = false THEN
                            -- Asignando la pregunta a un docente Ghost
                            INSERT INTO odiseo.employee_question (teacher_id, question_id, created_by, created_at)
                            VALUES (v_ghost_teacher_id, v_row_question.id, f_user_id, NOW());

                            -- Guardar en el historial
                            INSERT INTO odiseo.question_status (question_id, status, process, description, created_by, created_at)
                            VALUES (v_row_question.id, 'ASIG', 'ASIGNACIÓN', 'La pregunta fue asignada al docente <span class=''text-teacher''>Docente Ghost</span> por el usuario <span class=''text-user''> ' || v_user_name || '</span>', f_user_id, NOW());
                        END IF;

                        -- Verificar si ya se asigno la pregunta a un DIDI
                        SELECT CASE WHEN count(*) > 0 THEN true ELSE false END  AS is_question_assigned_to_didi
                        INTO v_is_question_assigned_to_didi
                        FROM odiseo.employee_didi_question edq
                        WHERE edq.question_id = v_row_question.id
                        AND edq.fl_status = true;

                        IF v_is_question_assigned_to_didi = false THEN
                            -- Asignando la pregunta a un DIDI
                            INSERT INTO odiseo.employee_didi_question (employee_id, question_id, created_by, created_at)
                            VALUES (v_ghost_didi_id, v_row_question.id, f_user_id, NOW());

                            -- Guardar en el historial
                            INSERT INTO odiseo.question_status (question_id, status, process, description, created_by, created_at)
                            VALUES (v_row_question.id, 'DASI', 'ASIGNADO', 'La pregunta fue asignada al DiDi <span class=''text-teacher''>DIDI GHOST</span> por el usuario <span class=''text-user''> ' || v_user_name || '</span>', f_user_id, NOW());
                        END IF;

                    END IF;


                    UPDATE odiseo.question
                    SET
                        ter = COALESCE(v_question_ter, v_row_question.ter),
                        topic_id = COALESCE(v_topic_id, v_row_question.topic_id),
                        level_id = COALESCE(v_level_id, v_row_question.level_id),
                        answer_id = COALESCE(v_alternative_id, v_row_question.answer_id),
                        type = COALESCE(v_question_type, v_row_question.type)
                    WHERE id = v_row_question.id;


                    IF v_topic_id IS NOT NULL THEN
                        SELECT id INTO v_subtopic_id FROM odiseo.subtopic
                            WHERE code = (v_question->>'data')::JSONB->>'subtopic_code'
                                AND topic_id = v_topic_id
                                AND fl_status AND deleted_at IS NULL;
                    ELSE
                        RAISE NOTICE 'No existe ese tema %', (v_question->>'data')::JSONB->>'topic_code';
                    END IF;

                    RAISE NOTICE 'v_subtopic_id: %', v_subtopic_id;

                    IF v_subtopic_id IS NOT NULL THEN
                        UPDATE odiseo.question_subtopic
                        SET fl_status = FALSE, deleted_at = NOW()
                        WHERE question_id = v_row_question.id;

                        SELECT id INTO v_question_subtopic_id FROM odiseo.question_subtopic
                        WHERE question_id = v_row_question.id AND subtopic_id = v_subtopic_id;

                        IF v_question_subtopic_id IS NOT NULL THEN
                            UPDATE odiseo.question_subtopic
                            SET fl_status = TRUE, deleted_at = NULL,
                                updated_by = f_user_id, updated_at = NOW()
                            WHERE id = v_question_subtopic_id;
                        ELSE
                            INSERT INTO odiseo.question_subtopic
                                (question_id, subtopic_id, fl_status, created_at, created_by)
                            VALUES
                                (v_row_question.id, v_subtopic_id, TRUE, NOW(), f_user_id);
                        END IF;
                    ELSE
                        RAISE NOTICE 'No existe el subtema % del tema %', (v_question->>'data')::JSONB->>'subtopic_code', (v_question->>'data')::JSONB->>'topic_code';
                    END IF;

                    IF v_course_id IS NULL THEN
                        RAISE NOTICE 'No existe el curso %', (v_question->>'data')::JSONB->>'course_code';
                    END IF;

                    IF v_level_id IS NULL THEN
                        RAISE NOTICE 'No existe el nivel %', (v_question->>'data')::JSONB->>'level_name';
                    END IF;

                    IF v_alternative_id IS NULL THEN
                        RAISE NOTICE 'No existe la alternativa  %', (v_question->>'data')::JSONB->>'alternative_correct';
                    END IF;

                    -- Actualizamos la variable v_row_question para traer los datos actualizados
                    SELECT * INTO v_row_question FROM odiseo.question q WHERE q.id = v_row_question.id LIMIT 1;


                    IF(
                        1 = 1
                        AND v_row_question.status NOT IN ('VERI','DUPL', 'ARCH')
                    ) THEN -- si la pregunta ya esta verificada no es necesario actualizar su estado a verificada
                        IF (
                            1 = 1
                            AND v_row_question.topic_id IS NOT NULL
                            AND EXISTS (
                                SELECT 1 FROM odiseo.question_subtopic qs1
                                WHERE qs1.question_id = v_row_question.id AND qs1.fl_status AND qs1.deleted_at IS NULL
                            )
                            AND v_row_question.level_id IS NOT NULL
                            AND v_row_question.answer_id IS NOT NULL
                            AND v_row_question.type IS NOT NULL
                            AND v_row_question.ter IS NOT NULL
                            AND v_row_question.status NOT IN ('DUPL', 'ARCH')
                        ) THEN
                            v_history_status := 'VERI';
                            v_history_process := 'VERIFICADO';
                            v_history_description :=  'La pregunta se cambió al estado verificado  por el usuario <span class=''text-user''>' || v_user_name || '</span>';

                            UPDATE odiseo.question
                            SET status = 'VERI'
                            WHERE id = v_row_question.id;
                        ELSE
                            v_history_status := 'PEND';
                            v_history_process := 'PENDIENTE';
                            v_history_description :=  'La pregunta se cambió al estado pendiente  por el usuario <span class=''text-user''>' || v_user_name || '</span>';

                            UPDATE odiseo.question
                            SET status = 'PEND'
                            WHERE id = v_row_question.id;
                        END IF;

                        UPDATE odiseo.question_status
                        SET fl_active = false
                        WHERE question_id = v_row_question.id;

                        INSERT INTO odiseo.question_status (question_id, status, process, description, created_by, created_at,fl_active)
                        VALUES (v_row_question.id, v_history_status, v_history_process, v_history_description, f_user_id, NOW(), true);
                    END IF;

                    SELECT * INTO v_row_question FROM odiseo.question q WHERE q.id = v_row_question.id LIMIT 1;

                    v_result := ROW(v_question->>'code', v_row_question.status, NULL);

                    v_results := array_append(v_results, v_result);

                    v_course_id := NULL;
                    v_question_ter := NULL;
                    v_question_type := NULL;
                    v_topic_id := NULL;
                    v_level_id := NULL;
                    v_subtopic_id := NULL;
                    v_question_subtopic_id := NULL;
                    v_alternative_id := NULL;
                    v_alternative_id_loop := NULL;
                    v_alternative_index_loop := 0;
                    v_alternative_letter_loop := NULL;
                    v_history_status := NULL;
                    v_history_process := NULL;
                    v_history_description := NULL;
                EXCEPTION
                    WHEN no_data_found THEN
                        v_result := ROW(v_question->>'code', NULL, 'No se encontró la pregunta con ese number_question');
                    WHEN OTHERS THEN
                        v_result := ROW(v_question->>'code', NULL, SQLERRM);

                    v_results := array_append(v_results, v_result);
                    v_course_id := NULL;
                    v_question_ter := NULL;
                    v_question_type := NULL;
                    v_topic_id := NULL;
                    v_level_id := NULL;
                    v_subtopic_id := NULL;
                    v_question_subtopic_id := NULL;
                    v_alternative_id := NULL;
                    v_alternative_id_loop := NULL;
                    v_alternative_index_loop := 0;
                    v_alternative_letter_loop := NULL;
                    v_history_status := NULL;
                    v_history_process := NULL;
                    v_history_description := NULL;
                END;
            END LOOP;

            RETURN QUERY SELECT * FROM unnest(v_results);
        END;
        $$;


ALTER FUNCTION odiseo.fn_update_set_massive_attributes(p_questions jsonb, f_user_id bigint) OWNER TO postgres;

--
-- Name: fn_update_status_parent_question(jsonb, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_status_parent_question(p_sub_question_ids jsonb, p_question_id bigint, p_user bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
            BEGIN
                -- Actualiza las subpreguntas en la tabla 'question'
                UPDATE odiseo.question
                SET
                    status = 'ARCH',
                    updated_by = p_user,
                    updated_at = NOW()
                WHERE id = ANY(SELECT jsonb_array_elements_text(p_sub_question_ids)::bigint);

                -- Actualiza la pregunta principal en la tabla 'parent_question'
                UPDATE odiseo.parent_question
                SET
                    status = 'ARCH', 
                    updated_by = p_user, 
                    updated_at = NOW()
                WHERE id = p_question_id;
            END;
            $$;


ALTER FUNCTION odiseo.fn_update_status_parent_question(p_sub_question_ids jsonb, p_question_id bigint, p_user bigint) OWNER TO postgres;

--
-- Name: fn_update_subtopic_syllabus(bigint, bigint, bigint, boolean, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_subtopic_syllabus(p_syllabus_id bigint, p_subtopic_id bigint, p_new_topic_id bigint, p_is_modified boolean, p_user bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_syllabus_detail_subtopics_ids BIGINT[];
                v_syllabus_topic_week_id BIGINT;
                v_week BIGINT;
               	v_new_syllabus_topic_week_id BIGINT;
                v_total_questions_amount BIGINT;
               	v_subtopic_id BIGINT;
                v_syllabus_subtopic_id BIGINT;
                v_syllabus_topic_id BIGINT;
             BEGIN
                -- Obtener los IDs de los subtemas del syllabus
                SELECT ARRAY(
                    SELECT sds.id
                    FROM syllabus s
                    LEFT JOIN syllabus_topic st ON st.syllabus_id = s.id
                    LEFT JOIN syllabus_topic_week stw ON stw.syllabus_topic_id = st.id
                    LEFT JOIN syllabus_detail_subtopic sds ON sds.syllabus_topic_week_id = stw.id
                    WHERE st.fl_status = TRUE
                    AND stw.fl_status = TRUE
                    AND sds.fl_status = TRUE
                    AND s.id = p_syllabus_id
                    AND sds.subtopic_id = p_subtopic_id
                ) INTO v_syllabus_detail_subtopics_ids;

                -- Actualizar el estado de los subtemas relacionados
                IF p_is_modified THEN
			      -- Iterar sobre cada subtopic ID
       				 FOR v_syllabus_subtopic_id IN SELECT  UNNEST(v_syllabus_detail_subtopics_ids) LOOP

                       -- Obtener la semana y la cantidad de preguntas
	                	SELECT  stw.week, stw.total_questions_amount
	                	INTO  v_week , v_total_questions_amount
	                	FROM syllabus_detail_subtopic sds
	                	JOIN syllabus_topic_week stw
	                	ON sds.syllabus_topic_week_id = stw.id
	                	WHERE sds.id = v_syllabus_subtopic_id;

	                    -- Obtener el ID del sylllabus_topic
	                    SELECT st.id
	                    INTO v_syllabus_topic_id
	                    FROM syllabus_topic st
	                    WHERE st.fl_status = TRUE
	                    AND st.syllabus_id = p_syllabus_id
	                    AND st.topic_id = p_new_topic_id;

	                   IF v_syllabus_topic_id IS NULL THEN
						    -- Insertar un nuevo registro en la tabla topic y obtener su ID
						    INSERT INTO topic(syllabus_id, topic_id, created_by, created_at)
						    VALUES (p_syllabus_id, p_new_topic_id, p_user, NOW())
						    RETURNING id INTO v_syllabus_topic_id;
						END IF;
	                   -- Insertando un nuevo registro de la configuracion de esa semana con el nuevo topic_id
	                    INSERT INTO syllabus_topic_week(syllabus_topic_id,week,total_questions_amount,created_by,created_at)
	                    VALUES (v_syllabus_topic_id,v_week,v_total_questions_amount,p_user, now()) RETURNING id INTO v_new_syllabus_topic_week_id;

	                    UPDATE syllabus_detail_subtopic
	                    SET is_topic_modified = FALSE, syllabus_topic_week_id = v_new_syllabus_topic_week_id
	                    WHERE id = v_syllabus_subtopic_id;
	                 END LOOP;
                ELSE
                    UPDATE syllabus_detail_subtopic
                    SET fl_status = FALSE,
                        is_topic_modified = FALSE,
                        deleted_by = p_user,
                        deleted_at = NOW()
                    WHERE id = ANY(v_syllabus_detail_subtopics_ids);
                END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_update_subtopic_syllabus(p_syllabus_id bigint, p_subtopic_id bigint, p_new_topic_id bigint, p_is_modified boolean, p_user bigint) OWNER TO postgres;

--
-- Name: fn_update_subtopic_syllabus(bigint, bigint, bigint, boolean, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_subtopic_syllabus(p_syllabus_id bigint, p_subtopic_id bigint, p_new_topic_id bigint, p_is_modified boolean, p_company_id bigint, p_user bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_syllabus_detail_subtopics_ids BIGINT[];
            v_syllabus_topic_week_id BIGINT;
            v_week BIGINT;
            v_new_syllabus_topic_week_id BIGINT;
            v_total_questions_amount BIGINT;
            v_subtopic_id BIGINT;
            v_syllabus_subtopic_id BIGINT;
            v_syllabus_topic_id BIGINT;
        BEGIN
            -- Obtener los IDs de los subtemas del syllabus
            SELECT ARRAY(
                SELECT sds.id
                FROM syllabus s
                LEFT JOIN syllabus_topic st ON st.syllabus_id = s.id
                LEFT JOIN syllabus_topic_week stw ON stw.syllabus_topic_id = st.id
                LEFT JOIN syllabus_detail_subtopic sds ON sds.syllabus_topic_week_id = stw.id
                WHERE st.fl_status = TRUE
                AND stw.fl_status = TRUE
                AND sds.fl_status = TRUE
                AND s.id = p_syllabus_id
                AND sds.subtopic_id = p_subtopic_id
            ) INTO v_syllabus_detail_subtopics_ids;

            -- Actualizar el estado de los subtemas relacionados
            IF p_is_modified THEN
            -- Iterar sobre cada subtopic ID
                FOR v_syllabus_subtopic_id IN SELECT  UNNEST(v_syllabus_detail_subtopics_ids) LOOP

                -- Obtener la semana y la cantidad de preguntas
                    SELECT  stw.week, stw.total_questions_amount
                    INTO  v_week , v_total_questions_amount
                    FROM syllabus_detail_subtopic sds
                    JOIN syllabus_topic_week stw
                    ON sds.syllabus_topic_week_id = stw.id
                    WHERE sds.id = v_syllabus_subtopic_id;

                    -- Obtener el ID del sylllabus_topic
                    SELECT st.id
                    INTO v_syllabus_topic_id
                    FROM syllabus_topic st
                    WHERE st.fl_status = TRUE
                    AND st.syllabus_id = p_syllabus_id
                    AND st.topic_id = p_new_topic_id;

                IF v_syllabus_topic_id IS NULL THEN
                        -- Insertar un nuevo registro en la tabla topic y obtener su ID
                        INSERT INTO syllabus_topic(syllabus_id, topic_id, created_by, created_at)
                        VALUES (p_syllabus_id, p_new_topic_id, p_user, NOW())
                        RETURNING id INTO v_syllabus_topic_id;
                    END IF;
                -- Insertando un nuevo registro de la configuracion de esa semana con el nuevo topic_id
                    INSERT INTO syllabus_topic_week(syllabus_topic_id,week,total_questions_amount,created_by,created_at)
                    VALUES (v_syllabus_topic_id,v_week,v_total_questions_amount,p_user, now()) RETURNING id INTO v_new_syllabus_topic_week_id;

                    UPDATE syllabus_detail_subtopic
                    SET is_topic_modified = FALSE, syllabus_topic_week_id = v_new_syllabus_topic_week_id
                    WHERE id = v_syllabus_subtopic_id;
                END LOOP;
            ELSE
                UPDATE syllabus_detail_subtopic
                SET fl_status = FALSE,
                    is_topic_modified = FALSE,
                    deleted_by = p_user,
                    deleted_at = NOW()
                WHERE id = ANY(v_syllabus_detail_subtopics_ids);
            END IF;
        END;
        $$;


ALTER FUNCTION odiseo.fn_update_subtopic_syllabus(p_syllabus_id bigint, p_subtopic_id bigint, p_new_topic_id bigint, p_is_modified boolean, p_company_id bigint, p_user bigint) OWNER TO postgres;

--
-- Name: fn_update_syllabus_week_title(bigint, integer, character varying, bigint, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_syllabus_week_title(p_syllabus_id bigint, p_week integer, p_title character varying, p_company_id bigint, p_user_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_syllabus_week_title_id INT;
        BEGIN
            -- Buscar el ID del syllabus_week_title
            SELECT swt.id
            INTO v_syllabus_week_title_id
            FROM syllabus_week_titles swt
            WHERE swt.syllabus_id = p_syllabus_id
            AND swt.company_id = p_company_id
            AND swt.week = p_week
            AND swt.fl_status = TRUE;

            -- Si no existe un registro, insertamos uno nuevo
            IF v_syllabus_week_title_id IS NULL THEN
                INSERT INTO syllabus_week_titles(syllabus_id, title, week, created_by, created_at, company_id)
                VALUES (p_syllabus_id, p_title, p_week, p_user_id, now(), p_company_id);
            ELSE
                -- Si ya existe, actualizamos el título
                UPDATE syllabus_week_titles
                SET title = p_title
                WHERE syllabus_id = p_syllabus_id
                AND company_id = p_company_id
                AND week = p_week
                AND fl_status = TRUE;
            END IF;
        END;
$$;


ALTER FUNCTION odiseo.fn_update_syllabus_week_title(p_syllabus_id bigint, p_week integer, p_title character varying, p_company_id bigint, p_user_id integer) OWNER TO postgres;

--
-- Name: fn_update_type_material(smallint, bigint, bigint, character varying, boolean, boolean, smallint, boolean, numeric, character varying, jsonb, jsonb, smallint, smallint, smallint, boolean, boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_type_material(p_id smallint, p_f_type_material_template_id bigint, p_updated_by bigint, p_ids_area character varying, p_fl_exam boolean, p_fl_class_material boolean, p_thread smallint, p_level_order boolean, p_percentage numeric, p_courses character varying, p_weeks jsonb, p_ids_children jsonb, p_periodicity_id smallint, p_quantity_week smallint, p_start_week smallint, p_group_previous_week boolean, p_group_remaining_week boolean) RETURNS TABLE(v_validate integer, type_material_id smallint)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_validate                       SMALLINT;
            v_type_material_id               SMALLINT;
            v_ids_area_length                INT;
            v_ids_area                       BIGINT[];
            v_amount_question                INT     := 0;
            v_course_item                    JSONB;
            v_course_id                      BIGINT;
            v_course_amount_question         INT;
            v_course_amount_text             INT;
            v_type_material_course_id        INT;
            v_type_material_area_id          INT;
            v_type_material_area_course_id   INT;
            v_new_type_material_course_id    INT;
            v_weeks_from_cycle_template      INT;
            v_weeks                          BIGINT[];
            v_week                           SMALLINT;
            v_area_id                        SMALLINT;
            v_not_exist_week                 BOOLEAN;
            v_week_fl_status                 BOOLEAN;
            v_type_material_template_description VARCHAR;
            v_not_exist_area_ids             INT[];
            v_children_id			  		 BIGINT;
            v_type_material_periodicity      SMALLINT;
            v_type_text_material_type_course INT;
            v_subquestion_item               JSONB;
            v_subquestion_position           SMALLINT;
            v_subquestion_amount             SMALLINT;
        BEGIN

            -- Convertir el JSONB p_weeks en un array de BIGINT
            v_weeks := ARRAY(
                SELECT jsonb_array_elements_text(p_weeks::JSONB)::BIGINT
            );

            -- Convertir el JSONB p_ids_area en un array de BIGINT
            v_ids_area := ARRAY(
                SELECT jsonb_array_elements_text(p_ids_area::JSONB)::BIGINT
            );

            -- Validar si es examen, debe tener una o mas áreas
            IF p_fl_exam THEN
                v_ids_area_length := array_length(v_ids_area, 1);
                IF v_ids_area_length IS NULL OR v_ids_area_length < 1 THEN
                    RETURN QUERY SELECT 0::INT, 0::SMALLINT;
                END IF;
            ELSE
                v_ids_area_length := array_length(v_ids_area, 1);
                IF v_ids_area_length IS NOT NULL AND v_ids_area_length > 0 THEN
                    RETURN QUERY SELECT 0::INT, 0::SMALLINT;
                END IF;
            END IF;
            
            -- Actualizar tipo de material
            UPDATE type_material
            SET description = COALESCE(v_type_material_template_description, description),
                updated_by = p_updated_by,
                updated_at = now(),
                fl_exam = p_fl_exam,
                fl_class_material = COALESCE(p_fl_class_material, fl_class_material),
                percentage = p_percentage,
                thread = p_thread,
                level_order = p_level_order,
                type_material_template_id = p_f_type_material_template_id,
                order_date = CASE
                    WHEN p_level_order IS DISTINCT FROM level_order
                      OR p_thread IS DISTINCT FROM thread
                      OR p_percentage IS DISTINCT FROM percentage
                    THEN NOW()
                    ELSE order_date
                END
            WHERE id = p_id;

            -- Limpiar TYPE MATERIAL DETAIL TEMPLATE si es un examen
            UPDATE type_material_detail_template AS tmdt
            SET fl_status = false,
                updated_by = p_updated_by,
                updated_at = now()
            WHERE tmdt.type_material_id = p_id;

            -- Procesar semanas
            FOR v_week IN
                SELECT unnest(v_weeks)
            LOOP
                IF v_week > 0 THEN
                    -- Actualizar o insertar semanas
                    UPDATE type_material_detail_template AS tmdt
                    SET fl_status = true
                    WHERE 1 = 1
                        AND tmdt.type_material_id = p_id
                        AND tmdt.week = v_week;

                    IF NOT FOUND THEN
                        INSERT INTO type_material_detail_template (type_material_id, week, created_at, created_by)
                        VALUES (p_id, v_week, now(), p_updated_by);
                    END IF;
                END IF;
            END LOOP;

            IF NOT p_fl_exam THEN
                -- Si no es un examen:
                IF p_ids_children IS NULL OR jsonb_array_length(p_ids_children) = 0 THEN
                    -- Limpiar áreas si no es un examen
                    UPDATE type_material_area AS tma
                    SET fl_status = false,
                        deleted_by = p_updated_by,
                        deleted_at = now()
                    WHERE tma.type_material_id = p_id;

                    -- Procesar cursos
                    FOR v_course_item IN
                        SELECT * FROM jsonb_array_elements(p_courses::JSONB)
                    LOOP
                        v_course_id := (v_course_item ->> 'course_id')::BIGINT;
                        v_course_amount_question := (v_course_item ->> 'amount_question')::INT;
                        v_course_amount_text := (v_course_item ->> 'amount_text')::INT;

                        -- Verificar si el curso ya existe
                        SELECT id INTO v_type_material_course_id
                        FROM type_material_course AS tmc
                        WHERE 1 = 1
                            AND tmc.type_material_id = p_id
                            AND tmc.course_id = v_course_id;

                        IF v_type_material_course_id IS NOT NULL THEN
                            -- Actualizar curso existente
                            UPDATE type_material_course
                            SET fl_status = true,
                                updated_by = p_updated_by,
                                updated_at = now(),
                                amount_question = v_course_amount_question,
                                amount_text = v_course_amount_text
                            WHERE id = v_type_material_course_id;

                        ELSE
                            -- Insertar nuevo curso
                            IF ( v_course_amount_question > 0 OR v_course_amount_text > 0 ) THEN
                                INSERT INTO type_material_course (type_material_id, course_id, created_by, created_at, amount_question, amount_text)
                                VALUES (p_id, v_course_id, p_updated_by, now(), v_course_amount_question, v_course_amount_text);
                            END IF;
                        END IF;

                        IF (v_course_item ->>'apply_text')::BOOL IS TRUE THEN
                           WITH insert_or_update_subquestions_in_text AS (
                               INSERT INTO type_text_material_type_course (type_material_id, course_id, subquestion_amount, position, created_by, created_at)
                               SELECT
                                    p_id,
                                    v_course_id,
                                    (subquestion->>'subquestion_amount')::SMALLINT AS subquestion_amount,
                                    (subquestion->>'position')::SMALLINT AS position,
                                    p_updated_by,
                                    NOW()
                               FROM JSONB_ARRAY_ELEMENTS(COALESCE(v_course_item->'subquestions', '[]'::JSONB)) AS subquestion
                               ON CONFLICT ON CONSTRAINT unique_type_material_course_pos
                               DO UPDATE
                                   SET
                                       subquestion_amount = EXCLUDED.subquestion_amount,
                                       updated_at = NOW(),
                                       updated_by = p_updated_by,
                                       deleted_by = NULL,
                                       deleted_at = NULL
                               RETURNING id
                           ) UPDATE type_text_material_type_course AS ty
                           SET
                               deleted_by = p_updated_by,
                               deleted_at = NOW()
                           WHERE 1 = 1
                             AND ty.type_material_id = p_id
                             AND ty.course_id = v_course_id
                             AND ty.id NOT IN (SELECT id FROM insert_or_update_subquestions_in_text);
                        END IF;

                        v_amount_question := v_amount_question + v_course_amount_question + v_course_amount_text;
                    END LOOP;

                    -- Actualizar la cantidad total de preguntas
                    UPDATE type_material AS tm
                    SET amount_question = v_amount_question,
                        updated_by = p_updated_by,
                        updated_at = now()
                    WHERE tm.id = p_id;
                ELSE
                    FOR v_children_id IN
                        SELECT id
                        FROM type_material
                        WHERE 1 = 1
                            AND fl_status = true
                            AND id = ANY(ARRAY(SELECT jsonb_array_elements_text(p_ids_children)::INT))
                    LOOP
                        v_amount_question := 0;

                        -- Procesar cursos
                        FOR v_course_item IN
                            SELECT * FROM jsonb_array_elements(p_courses::JSONB) AS courses
                            WHERE (courses->>'type_material_id')::BIGINT = v_children_id
                        LOOP
                            v_course_id := (v_course_item ->> 'course_id')::BIGINT;
                            v_course_amount_question := (v_course_item ->> 'amount_question')::INT;
                            v_course_amount_text := (v_course_item ->> 'amount_text')::INT;
                            -- Limpiar las semanas del hijo antes de actualizar
                            UPDATE type_material_detail_template AS tmdt
                                SET fl_status = false,
                                    updated_by = p_updated_by,
                                    updated_at = now()
                                WHERE 1 = 1
                                    AND tmdt.type_material_id = v_children_id;

                            -- Verificar si el curso ya existe
                            SELECT id INTO v_type_material_course_id
                            FROM type_material_course AS tmc
                            WHERE tmc.type_material_id = v_children_id
                            AND tmc.course_id = v_course_id;

                            -- Actualizar las semanas del hijo
                            FOR v_week IN
                                SELECT unnest(v_weeks)
                            LOOP
                                IF v_week > 0 THEN
                                    UPDATE type_material_detail_template AS tmdt
                                    SET fl_status = true
                                    WHERE 1 = 1
                                        AND tmdt.type_material_id = v_children_id
                                        AND tmdt.week = v_week;

                                    IF NOT FOUND THEN
                                        INSERT INTO type_material_detail_template (type_material_id, week, created_at, created_by)
                                        VALUES (v_children_id, v_week, now(), p_updated_by);
                                    END IF;
                                END IF;
                            END LOOP;

                            IF v_type_material_course_id IS NOT NULL THEN
                                -- Actualizar curso existente
                                UPDATE type_material_course
                                SET fl_status = true,
                                    updated_by = p_updated_by,
                                    updated_at = now(),
                                    amount_question = v_course_amount_question,
                                    amount_text = v_course_amount_text
                                WHERE id = v_type_material_course_id;
                            ELSE
                                -- Insertar nuevo curso
                                IF (  v_course_amount_question > 0 OR v_course_amount_text > 0 ) THEN
                                    INSERT INTO type_material_course (type_material_id, course_id, created_by, created_at, amount_question, amount_text)
                                    VALUES (p_id, v_course_id, p_updated_by, now(), v_course_amount_question, v_course_amount_text);
                                END IF;
                            END IF;

                            IF (v_course_item ->>'apply_text')::BOOL IS TRUE AND JSONB_ARRAY_LENGTH(COALESCE(v_course_item->'subquestions', '[]'::JSONB)) > 0 THEN
                                WITH insert_or_update_subquestions_in_text AS (
                                    INSERT INTO type_text_material_type_course (type_material_id, course_id, subquestion_amount, position, created_by, created_at)
                                    SELECT 
                                        v_children_id,
                                        v_course_id,
                                        (subquestion->>'subquestion_amount')::SMALLINT AS subquestion_amount,
                                        (subquestion->>'position')::SMALLINT AS position,
                                        p_updated_by,
                                        NOW()
                                    FROM JSONB_ARRAY_ELEMENTS(COALESCE(v_course_item->'subquestions', '[]'::JSONB)) AS subquestion
                                    ON CONFLICT ON CONSTRAINT unique_type_material_course_pos
                                    DO UPDATE
                                        SET
                                            subquestion_amount = EXCLUDED.subquestion_amount,
                                            updated_at = NOW(),
                                            updated_by = p_updated_by,
                                            deleted_by = NULL,
                                            deleted_at = NULL
                                    RETURNING id
                                ) UPDATE type_text_material_type_course AS ty
                                  SET
                                    deleted_by = p_updated_by,
                                    deleted_at = NOW()
                                  WHERE 1 = 1
                                    AND ty.type_material_id = v_children_id
                                    AND ty.course_id = v_course_id
                                    AND ty.id NOT IN (SELECT id FROM insert_or_update_subquestions_in_text); 
                            END IF;

                            v_amount_question := v_amount_question + v_course_amount_question + v_course_amount_text;

                        END LOOP;

                        RAISE NOTICE 'v_amount_question %', v_amount_question;
                        -- Actualizar la cantidad total de preguntas
                        UPDATE type_material AS tm
                        SET amount_question = v_amount_question,
                            updated_by = p_updated_by,
                            updated_at = now(),
                            percentage = p_percentage,
                            thread = p_thread,
                            level_order = p_level_order,
                            order_date = CASE
                                WHEN p_level_order IS DISTINCT FROM level_order
                                OR p_thread IS DISTINCT FROM thread
                                OR p_percentage IS DISTINCT FROM percentage
                                THEN NOW()
                                ELSE order_date
                            END
                        WHERE tm.id = v_children_id;
                    END LOOP;

                    UPDATE type_material
                    SET amount_question = (
                            SELECT COALESCE(SUM(amount_question), 0)
                            FROM type_material
                            WHERE id = ANY (ARRAY(SELECT jsonb_array_elements_text(p_ids_children)::INT)) -- Filtra los hijos usando p_ids_children
                        ),
                        updated_by = p_updated_by,
                        updated_at = now()
                    WHERE id = p_id; -- ID del padre
                END IF;
            ELSE
                -- Si es un examen:

                -- Obtenemos las areas que no se envian en v_ids_area
                SELECT ARRAY(
                    SELECT tma.area_id
                    FROM type_material_area tma
                    WHERE 1 = 1
                    AND tma.fl_status = TRUE
                    AND tma.area_id NOT IN (SELECT unnest(v_ids_area))
                ) INTO v_not_exist_area_ids;

                -- Eliminando los registros q no se encuentran en type_material_area
                UPDATE type_material_area AS tma
                SET fl_status = FALSE,
                    updated_by = p_updated_by,
                    updated_at = now()
                WHERE 1 = 1
                    AND tma.type_material_id = p_id
                    AND tma.area_id  IN (SELECT unnest(v_not_exist_area_ids));

                -- Actualizando los registros de los valores amount de la tabla: exam_material_config_area_course_levels
                WITH configurations_to_update AS (
                    SELECT emcacl2.id AS id
                    FROM exam_material_config_area_course_levels emcacl2
                    LEFT JOIN exam_material_config_area_courses emcac
                        ON emcacl2.exam_material_config_area_course_id = emcac.id
                    LEFT JOIN exam_material_configurations emc
                        ON emc.id = emcac.exam_material_config_id
                    WHERE TRUE
                    AND emc.type_material_id = p_id
                    AND emcacl2.fl_status = TRUE
                    AND emcac.exam_area_id IN (SELECT UNNEST(v_not_exist_area_ids))
                )
                UPDATE exam_material_config_area_course_levels exxl
                    SET amount_question = 0
                FROM configurations_to_update cup
                WHERE cup.id = exxl.id;

                -- Procesar áreas y cursos asociados
                FOR v_area_id IN
                    SELECT unnest(v_ids_area)
                LOOP
                    IF v_area_id > 0 THEN
                        -- Desactivar cursos que ya no están en p_courses
                        WITH current_courses AS (
                            SELECT tmc.id AS course_id
                            FROM type_material_area_courses tmac
                            JOIN type_material_area tma ON tmac.type_material_area_id = tma.id
                            JOIN type_material_course tmc ON tmac.type_material_course_id = tmc.id
                            WHERE 1 = 1
                                AND tma.type_material_id = p_id
                                AND tma.area_id = v_area_id
                        )
                        UPDATE type_material_course
                        SET fl_status = false,
                            updated_by = p_updated_by,
                            updated_at = now()
                        WHERE id IN (
                            SELECT course_id FROM current_courses
                            EXCEPT
                            SELECT (course->>'course_id')::BIGINT
                            FROM jsonb_array_elements(p_courses::JSONB) AS course
                            WHERE (course->>'area_id')::BIGINT = v_area_id
                        );

                        SELECT tma.id
                        INTO v_type_material_area_id
                        FROM type_material_area tma
                        WHERE  1 = 1
                            AND tma.type_material_id = p_id
                            AND tma.area_id = v_area_id;

                        IF v_type_material_area_id IS NULL THEN
                            INSERT INTO type_material_area (type_material_id, area_id, created_at, created_by)
                            VALUES (p_id, v_area_id, now(), p_updated_by)
                            RETURNING id INTO v_type_material_area_id;
                        ELSE
                            UPDATE  type_material_area
                            SET fl_status = TRUE, updated_by = p_updated_by, updated_at = now()
                            WHERE id = v_type_material_area_id ;
                        END IF;

                        -- Procesar cursos asociados a áreas
                        FOR v_course_item IN
                            SELECT *
                            FROM jsonb_array_elements(p_courses::JSONB) AS courses
                            WHERE (courses->>'area_id')::BIGINT = v_area_id
                        LOOP
                            v_course_id := (v_course_item ->> 'course_id')::BIGINT;
                            v_course_amount_question := (v_course_item ->> 'amount_question')::INT;
                            v_course_amount_text := (v_course_item ->> 'amount_text')::INT;

                            -- Verificar si el curso ya existe
                            SELECT tmc.id INTO v_type_material_course_id
                            FROM type_material_area_courses tmac
                            JOIN type_material_area tma ON tmac.type_material_area_id = tma.id
                            JOIN type_material_course tmc ON tmac.type_material_course_id = tmc.id
                            WHERE 1 = 1
                                AND tma.type_material_id = p_id
                                AND tma.area_id = v_area_id
                                AND tmc.course_id = v_course_id
                                AND tmac.fl_status = true;

                            IF v_type_material_course_id IS NOT NULL THEN
                                -- Actualizar curso existente
                                UPDATE type_material_course AS tmc
                                SET fl_status = true,
                                    updated_by = p_updated_by,
                                    updated_at = now(),
                                    amount_question = v_course_amount_question,
                                    amount_text = v_course_amount_text
                                WHERE tmc.id = v_type_material_course_id;

                                SELECT tmac.id
                                INTO v_type_material_area_course_id
                                FROM type_material_area_courses tmac
                                WHERE 1 = 1
                                    AND tmac.type_material_course_id = v_type_material_course_id
                                    AND tmac.type_material_area_id = v_type_material_area_id;

                                IF v_type_material_area_course_id IS NULL THEN
                                    INSERT INTO type_material_area_courses (type_material_course_id, type_material_area_id, created_by, created_at)
                                    VALUES (v_new_type_material_course_id, v_type_material_area_id, p_updated_by, now());
                                ELSE
                                    UPDATE type_material_area_courses
                                    SET fl_status = TRUE
                                    WHERE id = v_type_material_area_course_id;

                                    IF v_course_amount_question = 0 THEN
                                        UPDATE exam_material_config_area_course_levels emcacl
                                        SET amount_question = v_course_amount_question
                                        FROM exam_material_config_area_courses emc
                                        JOIN exam_material_configurations emc2 ON emc2.id = emc.exam_material_config_id
                                        WHERE emcacl.exam_material_config_area_course_id = emc.id
                                            AND emc.course_id = v_course_id
                                            AND emc.exam_area_id = v_area_id
                                            AND emc2.type_material_id = p_id;
                                    END IF;
                                END IF;
                            ELSE
                                -- Insertar nuevo curso y asociarlo al área
                                INSERT INTO type_material_course (type_material_id, course_id, created_by, created_at, amount_question, amount_text)
                                VALUES (p_id, v_course_id, p_updated_by, now(), v_course_amount_question, v_course_amount_text)
                                RETURNING id INTO v_new_type_material_course_id;

                                INSERT INTO type_material_area_courses (type_material_course_id, type_material_area_id, created_by, created_at)
                                VALUES (v_new_type_material_course_id, v_type_material_area_id, p_updated_by, now());
                            END IF;

                            IF (v_course_item ->>'apply_text')::BOOL IS TRUE AND JSONB_ARRAY_LENGTH(COALESCE(v_course_item->'subquestions', '[]'::JSONB)) > 0 THEN
                                WITH insert_or_update_area_subquestions_in_text AS (
                                   INSERT INTO type_text_material_type_course_area (type_material_id, course_id, exam_area_id, subquestion_amount, position, created_by, created_at)
                                   SELECT 
                                        p_id,
                                        v_course_id,
                                        v_area_id,
                                        (subquestion->>'subquestion_amount')::SMALLINT AS subquestion_amount,
                                        (subquestion->>'position')::SMALLINT AS position,
                                        p_updated_by,
                                        NOW()
                                   FROM JSONB_ARRAY_ELEMENTS(COALESCE(v_course_item->'subquestions', '[]'::JSONB)) AS subquestion
                                   ON CONFLICT ON CONSTRAINT unique_type_material_course_are_pos
                                   DO UPDATE
                                       SET
                                           subquestion_amount = EXCLUDED.subquestion_amount,
                                           updated_at = NOW(),
                                           updated_by = p_updated_by,
                                           deleted_by = NULL,
                                           deleted_at = NULL
                                   RETURNING id
                               ) UPDATE type_text_material_type_course_area AS ty
                               SET
                                   deleted_by = p_updated_by,
                                   deleted_at = NOW()
                               WHERE 1 = 1
                                 AND ty.type_material_id = p_id
                                 AND ty.course_id = v_course_id
                                 AND ty.exam_area_id = v_area_id
                                 AND ty.id NOT IN (SELECT id FROM insert_or_update_area_subquestions_in_text);
                            ELSE
                                WITH update_type_text_material_type_course_area AS (
                                    UPDATE type_text_material_type_course_area ttm
                                            SET
                                                deleted_by = p_updated_by,
                                                deleted_at = NOW()
                                        WHERE 1 = 1
                                          AND ttm.type_material_id = p_id
                                          AND ttm.course_id = v_course_id
                                          AND ttm.exam_area_id = v_area_id
                                    RETURNING ttm.id
                                )
                                INSERT INTO type_text_material_type_course_area (type_material_id, course_id, exam_area_id, subquestion_amount, position, created_at, created_by, deleted_at, deleted_by)
                                SELECT p_id, v_course_id, v_area_id, 0, 1, NOW(), p_updated_by, NOW(), p_updated_by WHERE NOT EXISTS ( SELECT 1 FROM update_type_text_material_type_course_area ); -- <--Version 1.3
                            END IF;

                            -- Acumular la cantidad de preguntas
                            v_amount_question := v_amount_question + v_course_amount_question + v_course_amount_text;
                        END LOOP;
                    END IF;
                END LOOP;

                -- Actualizando amount_question
                UPDATE type_material
                SET amount_question = v_amount_question,
                    updated_by = p_updated_by,
                    updated_at = now()
                WHERE id = p_id;
            END IF;

            -- Actualizar configuración de periodicidad y/o crear si no existe

            IF NOT p_fl_exam THEN -- <-- Se condicionó para que no se actualice o se registre periodicidad en el caso que sea examen
                UPDATE type_material_periodicity tmp
                SET periodicity_id = p_periodicity_id,
                    quantity_week = p_quantity_week,
                    start_week = p_start_week,
                    group_previous_week = p_group_previous_week,
                    group_remaining_week = p_group_remaining_week,
                    updated_by = p_updated_by,
                    updated_at = now()
                WHERE tmp.type_material_id = p_id
                    AND tmp.fl_status = true
                RETURNING tmp.id INTO v_type_material_periodicity;

                IF v_type_material_periodicity IS NULL THEN
                    INSERT INTO type_material_periodicity AS tmp (
                        type_material_id,
                        periodicity_id,
                        quantity_week,
                        start_week,
                        group_previous_week,
                        group_remaining_week,
                        created_by,
                        created_at
                    )
                    VALUES (
                        p_id,
                        p_periodicity_id,
                        p_quantity_week,
                        p_start_week,
                        p_group_previous_week,
                        p_group_remaining_week,
                        p_updated_by,
                        now()
                    );
                END IF;
            END IF;

            RETURN QUERY SELECT 1::INT, p_id;
        END;
        $$;


ALTER FUNCTION odiseo.fn_update_type_material(p_id smallint, p_f_type_material_template_id bigint, p_updated_by bigint, p_ids_area character varying, p_fl_exam boolean, p_fl_class_material boolean, p_thread smallint, p_level_order boolean, p_percentage numeric, p_courses character varying, p_weeks jsonb, p_ids_children jsonb, p_periodicity_id smallint, p_quantity_week smallint, p_start_week smallint, p_group_previous_week boolean, p_group_remaining_week boolean) OWNER TO postgres;

--
-- Name: fn_update_type_material_course_single(bigint, boolean, character, bigint, integer, integer, jsonb, jsonb, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_type_material_course_single(p_course_id bigint, p_is_generic boolean, p_type_question character, p_material_id bigint, p_amount integer, p_amount_text integer, p_subquestions jsonb, p_weeks_detail jsonb, p_updated_by bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_tmc_id           BIGINT; 
                v_tmdt_id          BIGINT; 
                v_detail_id        BIGINT; 
                r_week             JSONB;
                v_active_weeks     INT[] := ARRAY[]::INT[];
            BEGIN
                -- =========================================================================
                -- 1. UPSERT MAESTRO (type_material_course)
                -- =========================================================================
                SELECT id INTO v_tmc_id 
                FROM type_material_course 
                WHERE type_material_id = p_material_id AND course_id = p_course_id;

                IF v_tmc_id IS NULL THEN
                    INSERT INTO type_material_course (
                        type_material_id, course_id, amount_question, amount_text, 
                        is_generic, is_generic_text, fl_status, created_by, created_at
                    ) VALUES (
                        p_material_id, p_course_id, 0, 0, 
                        true, true, true, p_updated_by, NOW()
                    ) RETURNING id INTO v_tmc_id;
                END IF;

                -- Actualizamos la configuración Maestra según el tipo
                IF p_type_question = 'P' THEN
                    UPDATE type_material_course 
                    SET is_generic = p_is_generic,
                        amount_question = CASE WHEN p_is_generic THEN COALESCE(p_amount, 0) ELSE 0 END,
                        fl_status = true, updated_at = NOW(), updated_by = p_updated_by
                    WHERE id = v_tmc_id;
                ELSIF p_type_question = 'T' THEN
                    UPDATE type_material_course 
                    SET is_generic_text = p_is_generic,
                        amount_text = CASE WHEN p_is_generic THEN COALESCE(p_amount_text, 0) ELSE 0 END,
                        fl_status = true, updated_at = NOW(), updated_by = p_updated_by
                    WHERE id = v_tmc_id;
                END IF;

                -- =========================================================================
                -- 2. LÓGICA DE DETALLES
                -- =========================================================================
                
                -- CASO A: ES GENÉRICO
                IF p_is_generic IS TRUE THEN
                    
                    IF p_type_question = 'P' THEN
                        -- Limpiar detalles P
                        UPDATE type_material_detail_courses
                        SET fl_status = false, deleted_at = NOW(), deleted_by = p_updated_by
                        WHERE type_material_course_id = v_tmc_id AND fl_status = true;
                        
                    ELSIF p_type_question = 'T' THEN
                        -- Limpiar detalles T
                        UPDATE type_material_detail_course_texts
                        SET fl_status = false, deleted_at = NOW(), deleted_by = p_updated_by
                        WHERE type_material_course_id = v_tmc_id AND fl_status = true;

                        -- Guardar Subpreguntas MAESTRAS
                        UPDATE type_text_material_type_course 
                        SET deleted_at = NOW(), deleted_by = p_updated_by
                        WHERE type_material_id = p_material_id AND course_id = p_course_id;

                        IF p_subquestions IS NOT NULL AND jsonb_array_length(p_subquestions) > 0 THEN
                            INSERT INTO type_text_material_type_course (
                                type_material_id, course_id, subquestion_amount, position, created_by, created_at
                            )
                            SELECT 
                                p_material_id, p_course_id, 
                                (sq->>'subquestion_amount')::SMALLINT, 
                                (sq->>'position')::SMALLINT, 
                                p_updated_by, NOW()
                            FROM jsonb_array_elements(p_subquestions) sq
                            ON CONFLICT (type_material_id, course_id, position) 
                            DO UPDATE SET 
                                subquestion_amount = EXCLUDED.subquestion_amount, 
                                deleted_at = NULL,
                                updated_at = NOW(), updated_by = p_updated_by;
                        END IF;
                    END IF;

                -- CASO B: ES PERSONALIZADO
                ELSE
                    -- Limpiar subpreguntas maestras si es Tipo Texto
                    IF p_type_question = 'T' THEN
                        UPDATE type_text_material_type_course 
                        SET deleted_at = NOW(), deleted_by = p_updated_by
                        WHERE type_material_id = p_material_id AND course_id = p_course_id;
                    END IF;

                    IF p_weeks_detail IS NOT NULL THEN
                        FOR r_week IN SELECT * FROM jsonb_array_elements(p_weeks_detail)
                        LOOP
                            v_active_weeks := array_append(v_active_weeks, (r_week->>'week')::INT);

                            SELECT id INTO v_tmdt_id 
                            FROM type_material_detail_template 
                            WHERE type_material_id = p_material_id 
                            AND week = (r_week->>'week')::INT 
                            AND fl_status = true LIMIT 1;

                            IF v_tmdt_id IS NULL THEN
                                INSERT INTO type_material_detail_template (
                                    type_material_id, week, created_by, created_at
                                ) VALUES (
                                    p_material_id, (r_week->>'week')::INT, p_updated_by, NOW()
                                ) RETURNING id INTO v_tmdt_id;
                            END IF;

                            IF v_tmdt_id IS NOT NULL THEN
                                
                                -- TIPO PREGUNTA ('P')
                                IF p_type_question = 'P' THEN
                                    UPDATE type_material_detail_courses
                                    SET amount_question = COALESCE((r_week->>'amount')::INT, 0),
                                        fl_status = true, updated_at = NOW(), updated_by = p_updated_by
                                    WHERE type_material_detail_template_id = v_tmdt_id 
                                    AND course_id = p_course_id
                                    RETURNING id INTO v_detail_id;

                                    IF v_detail_id IS NULL THEN
                                        INSERT INTO type_material_detail_courses (
                                            type_material_detail_template_id, type_material_course_id, course_id,
                                            amount_question, fl_status, created_by, created_at
                                        ) VALUES (
                                            v_tmdt_id, v_tmc_id, p_course_id,
                                            COALESCE((r_week->>'amount')::INT, 0),
                                            true, p_updated_by, NOW()
                                        ) RETURNING id INTO v_detail_id;
                                    END IF;

                                -- TIPO TEXTO ('T')
                                ELSIF p_type_question = 'T' THEN
                                    UPDATE type_material_detail_course_texts
                                    SET amount_text = COALESCE((r_week->>'amount_text')::INT, 0),
                                        fl_status = true, updated_at = NOW(), updated_by = p_updated_by
                                    WHERE type_material_detail_template_id = v_tmdt_id 
                                    AND course_id = p_course_id
                                    RETURNING id INTO v_detail_id;

                                    IF v_detail_id IS NULL THEN
                                        INSERT INTO type_material_detail_course_texts (
                                            type_material_detail_template_id, type_material_course_id, course_id,
                                            amount_text, fl_status, created_by, created_at
                                        ) VALUES (
                                            v_tmdt_id, v_tmc_id, p_course_id,
                                            COALESCE((r_week->>'amount_text')::INT, 0),
                                            true, p_updated_by, NOW()
                                        ) RETURNING id INTO v_detail_id;
                                    END IF;

                                    -- SUBPREGUNTAS DE TEXTO (Detalle)
                                    UPDATE type_material_detail_text_subquestions
                                    SET deleted_at = NOW(), deleted_by = p_updated_by
                                    WHERE type_material_detail_course_text_id = v_detail_id;

                                    IF jsonb_array_length(r_week->'subquestions') > 0 THEN
                                        INSERT INTO type_material_detail_text_subquestions (
                                            type_material_detail_course_text_id,
                                            subquestion_amount,
                                            position,
                                            created_by, created_at
                                        )
                                        SELECT 
                                            v_detail_id,
                                            (sq->>'subquestion_amount')::SMALLINT,
                                            (sq->>'position')::SMALLINT,
                                            p_updated_by, NOW()
                                        FROM jsonb_array_elements(r_week->'subquestions') sq;
                                    END IF;
                                END IF;
                            END IF;
                        END LOOP;

                        -- LIMPIEZA FINAL
                        IF p_type_question = 'P' THEN
                            UPDATE type_material_detail_courses tmdc
                            SET fl_status = false, deleted_at = NOW(), deleted_by = p_updated_by
                            FROM type_material_detail_template tmdt
                            WHERE tmdc.type_material_detail_template_id = tmdt.id
                            AND tmdc.type_material_course_id = v_tmc_id
                            AND tmdt.week <> ALL(v_active_weeks)
                            AND tmdc.fl_status = true;
                        ELSIF p_type_question = 'T' THEN
                            UPDATE type_material_detail_course_texts tmdct
                            SET fl_status = false, deleted_at = NOW(), deleted_by = p_updated_by
                            FROM type_material_detail_template tmdt
                            WHERE tmdct.type_material_detail_template_id = tmdt.id
                            AND tmdct.type_material_course_id = v_tmc_id
                            AND tmdt.week <> ALL(v_active_weeks)
                            AND tmdct.fl_status = true;
                        END IF;
                    END IF;
                END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_update_type_material_course_single(p_course_id bigint, p_is_generic boolean, p_type_question character, p_material_id bigint, p_amount integer, p_amount_text integer, p_subquestions jsonb, p_weeks_detail jsonb, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_update_type_material_template(bigint, character varying, jsonb, boolean, bigint, bigint, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_type_material_template(p_id bigint, p_name character varying, p_children_template_ids jsonb, p_fl_exam boolean, p_user_id bigint, p_type_exam_id bigint, p_settings jsonb) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_old_is_exam bool;
    v_type_material_template_child_id bigint;
BEGIN
    p_settings := NULLIF(p_settings, '{}'::jsonb);
    
    SELECT
        tmt.fl_exam,
        tmt.name INTO v_old_is_exam
    FROM
        type_material_template tmt
    WHERE
        tmt.id = p_id
        AND tmt.fl_status = TRUE
    LIMIT 1;

    IF TRIM(UPPER(p_name)) IN (
        SELECT
            TRIM(UPPER(name))
        FROM
            type_material_template
        WHERE
            fl_status = TRUE AND id <> p_id) THEN
        RETURN json_build_object('status', 409, 'message', 'No se puede modificar esta plantilla porque ya existe una plantilla con el mismo nombre');
    END IF;

    IF v_old_is_exam <> p_fl_exam AND EXISTS (
        SELECT
            1
        FROM
            type_material tm
        WHERE
            tm.type_material_template_id = p_id AND tm.fl_status = TRUE) THEN
        RETURN json_build_object('status', 409, 'message', 'No se puede modificar esta plantilla porque ya tiene materiales asignados');
    END IF;

    UPDATE
        type_material_template
    SET
        name = COALESCE(p_name, name),
        fl_exam = COALESCE(p_fl_exam, fl_exam),
        updated_at = NOW(),
        updated_by = p_user_id,
        type_exam_id = p_type_exam_id,
        deleted_at = NULL,
        deleted_by = NULL,
        fl_status = TRUE
    WHERE
        id = p_id;
    WITH deleted_bounds AS (
        UPDATE
            type_material_bound tmb
        SET
            fl_status = FALSE,
            deleted_by = p_user_id,
            deleted_at = NOW()
        WHERE
            tmb.type_material_template_id = p_id
            AND tmb.type_material_template_extra_id NOT IN (
                SELECT
                    value::bigint
                FROM
                    jsonb_array_elements_text(p_children_template_ids))
                AND tmb.fl_status = TRUE
            RETURNING
                tmb.type_material_template_extra_id)
        UPDATE
            type_material tm
        SET
            fl_status = FALSE,
            updated_by = p_user_id,
            updated_at = NOW(),
            deleted_by = p_user_id,
            deleted_at = NOW()
        WHERE
            tm.parent_id IN (
                SELECT
                    id
                FROM
                    type_material
                WHERE
                    type_material_template_id = p_id)
            AND tm.type_material_template_id IN (
                SELECT
                    type_material_template_extra_id
                FROM
                    deleted_bounds);
    FOR v_type_material_template_child_id IN
    SELECT
        value::bigint
    FROM
        jsonb_array_elements_text(p_children_template_ids)
        LOOP
            IF EXISTS (
                SELECT
                    1
                FROM
                    type_material_bound tmb
                WHERE
                    tmb.type_material_template_id = v_type_material_template_child_id
                    AND tmb.fl_status = TRUE) THEN
            RETURN json_build_object('status', 409, 'message', 'No se puede asociar hijos que ya tienen sus propios hijos');
        END IF;
    INSERT INTO type_material_bound(type_material_template_id, type_material_template_extra_id, fl_status, created_by, created_at)
        VALUES (p_id, v_type_material_template_child_id, TRUE, p_user_id, NOW())
    ON CONFLICT (type_material_template_id, type_material_template_extra_id)
        DO UPDATE SET
            fl_status = TRUE,
            updated_by = p_user_id,
            updated_at = NOW(),
            deleted_by = NULL,
            deleted_at = NULL;
    UPDATE
        type_material tm_hijo
    SET
        fl_status = TRUE,
        updated_by = p_user_id,
        updated_at = NOW(),
        deleted_by = NULL,
        deleted_at = NULL
    FROM
        type_material tm_padre
    WHERE
        tm_padre.type_material_template_id = p_id
        AND tm_hijo.parent_id = tm_padre.id
        AND tm_hijo.type_material_template_id = v_type_material_template_child_id;
END LOOP;

    UPDATE
        type_material tm_padre
    SET
        amount_question = COALESCE((
            SELECT
                SUM(hijo.amount_question)
            FROM type_material hijo
            WHERE
                hijo.parent_id = tm_padre.id
                AND hijo.fl_status = TRUE), 0)
    WHERE
        tm_padre.type_material_template_id = p_id;

    PERFORM fn_sync_type_material_template_configuration_columns(
        p_id,
        p_user_id,
        p_settings
    );

    RETURN json_build_object('status', 200, 'message', 'Se actualizó la plantilla exitosamente');
END;
$$;


ALTER FUNCTION odiseo.fn_update_type_material_template(p_id bigint, p_name character varying, p_children_template_ids jsonb, p_fl_exam boolean, p_user_id bigint, p_type_exam_id bigint, p_settings jsonb) OWNER TO postgres;

--
-- Name: fn_update_user_by_uuid(uuid, character varying, bigint, integer, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_update_user_by_uuid(p_user_uuid uuid, p_email character varying, p_role_id bigint, p_company_id integer, p_update_by bigint) RETURNS TABLE(status boolean, data uuid)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        WITH get_user AS (
            SELECT
                u.id
            FROM users u
            WHERE u.uuid = p_user_uuid::UUID
            AND u.fl_status = true
        ), update_user AS (
            UPDATE users u
                set email = p_email,
                updated_by = p_update_by,
                updated_at = now()
            WHERE u.id IN (SELECT gu.id FROM get_user gu)
        ), update_rol AS (
            UPDATE users_roles
            SET rol_id = p_role_id,
            updated_by = p_update_by,
            updated_at = now()
            WHERE user_id IN (SELECT gu.id FROM get_user gu)
                AND fl_status = true
        ), validate_change_company_user AS (
            SELECT
                u.id,
                r.fl_administrator,
                rp.permission_id
            FROM users u
            JOIN users_roles ur ON u.id = ur.user_id
            JOIN roles r ON ur.rol_id = r.id
            LEFT JOIN roles_permissions rp ON r.id = rp.rol_id
                AND rp.permission_id = 219 -- 'admin.seleccionar-empresa-usuario'
            WHERE u.id = p_update_by
        ), update_company_user AS (
            UPDATE users u
                set company_id = p_company_id
            WHERE u.id IN (SELECT gu.id FROM get_user gu)
                AND EXISTS (
                    SELECT 1 FROM validate_change_company_user vcu
                )
        ), update_company_employee AS (
            UPDATE employees e
                set company_id = p_company_id
            WHERE e.user_id IN (SELECT gu.id FROM get_user gu)
                AND EXISTS (
                    SELECT 1 FROM validate_change_company_user vcu
                )
        )
        SELECT
            TRUE AS status,
            e.uuid AS data
        FROM employees e
        WHERE e.user_id IN (SELECT gu.id FROM get_user gu);
    END;
    $$;


ALTER FUNCTION odiseo.fn_update_user_by_uuid(p_user_uuid uuid, p_email character varying, p_role_id bigint, p_company_id integer, p_update_by bigint) OWNER TO postgres;

--
-- Name: fn_updated_course(bigint, character varying, bigint, jsonb, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_updated_course(p_id bigint, p_name character varying, p_area_id bigint, p_courses jsonb, p_type_text_template_id bigint, p_updated_by bigint) RETURNS TABLE(v_validated boolean, v_id bigint)
    LANGUAGE plpgsql
    AS $$
    DECLARE
        v_exists_id BIGINT;
        v_code VARCHAR;
        v_new_id BIGINT;
        v_fl_pseudo_course BOOLEAN;
        v_course_id SMALLINT;
        v_validate_course BIGINT;
        v_count SMALLINT := 1;
    BEGIN
        SELECT id INTO v_exists_id
        FROM course
        WHERE unaccent( name) = unaccent(p_name)
        AND id <> p_id
        AND fl_status = true
        LIMIT 1;

        IF v_exists_id IS NULL THEN
            UPDATE course
            SET name = p_name, area_id = COALESCE(p_area_id, area_id), updated_by = p_updated_by, updated_at = now(), type_text_template_id = p_type_text_template_id, apply_text = CASE 
                WHEN p_type_text_template_id IS NULL THEN FALSE
                ELSE TRUE
                END
            WHERE id = p_id
            RETURNING id, fl_pseudo_course INTO v_new_id, v_fl_pseudo_course;

            if v_fl_pseudo_course THEN
                -- Eliminar los que no se manda
                UPDATE course_pseudo_courses cpc
                SET fl_status = false, deleted_by = p_updated_by, deleted_at = NOW()
                WHERE cpc.course_id NOT IN (SELECT value::SMALLINT FROM jsonb_array_elements_text(p_courses))
                AND cpc.pseudo_course_id = p_id
                AND cpc.fl_status IS TRUE;

                FOR v_course_id IN
                    SELECT * FROM jsonb_array_elements(p_courses)
                LOOP
                    SELECT cpcv.id INTO v_validate_course
                    FROM course_pseudo_courses cpcv
                    WHERE cpcv.pseudo_course_id = p_id AND cpcv.course_id = v_course_id;

                    IF v_validate_course IS NULL THEN
                        INSERT INTO course_pseudo_courses
                        (pseudo_course_id, course_id, "order", created_by, created_at)
                        VALUES (v_new_id, v_course_id, v_count, p_updated_by, now());
                    ELSE
                        UPDATE course_pseudo_courses cpcu
                        SET fl_status = true, "order" = v_count, deleted_by = null, deleted_at = null
                        WHERE cpcu.id = v_validate_course;
                    END IF;

                    -- Incrementa el contador
                    v_count := v_count + 1;
                END LOOP;
            END IF;

            RETURN QUERY SELECT TRUE, v_new_id;
        ELSE
            RETURN QUERY SELECT FALSE, 0::BIGINT;
        END IF;
    END;     
    $$;


ALTER FUNCTION odiseo.fn_updated_course(p_id bigint, p_name character varying, p_area_id bigint, p_courses jsonb, p_type_text_template_id bigint, p_updated_by bigint) OWNER TO postgres;

--
-- Name: fn_upload_question_missing(bigint, smallint, character varying, bigint, bigint, smallint, integer, bigint, character varying, text, text, boolean, numeric, bigint, smallint, character varying, integer, jsonb, integer, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_upload_question_missing(p_detail_id bigint, p_course_id smallint, p_type_td character varying, p_employee_id bigint, p_created_by bigint, p_topic_id smallint, p_subtopic_id integer, p_level_id bigint, p_type_question character varying, p_description text, p_short_description text, p_fl_diagrammed boolean, p_ter numeric, p_config_alternative_id bigint, p_question_columns smallint, p_status character varying, p_priority integer, p_alternatives jsonb, p_question_mode integer DEFAULT NULL::integer, p_files jsonb DEFAULT NULL::jsonb, p_alternative_images jsonb DEFAULT NULL::jsonb, p_question_images jsonb DEFAULT NULL::jsonb) RETURNS TABLE(question_id bigint, question_code character varying, status character varying, description text, alternatives jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_question_id bigint;
    v_question_code varchar;
    v_mmqd material_missing_question_detail%ROWTYPE;
    v_mmq material_missing_question%ROWTYPE;
    v_alt jsonb;
    v_alt_id bigint;
    v_answer_id bigint;
    v_pending_count bigint;
    v_process varchar;
    v_new_code varchar;
    v_new_number text;
    v_employee_name varchar;
    v_employee_question_id bigint;
BEGIN
    -- 1. Verificar detalle pendiente
    SELECT
        mmqd.* INTO v_mmqd
    FROM
        material_missing_question_detail mmqd
    WHERE
        mmqd.id = p_detail_id
        AND mmqd.status = 'pending';

    -- 2. Obtener maestro
    SELECT
        mmq.* INTO v_mmq
    FROM
        material_missing_question mmq
    WHERE
        mmq.id = v_mmqd.material_missing_question_id;

    -- 3. Generar código
    SELECT
        fq.full_code,
        fq.number_str INTO v_new_code,
        v_new_number
    FROM
        fn_generate_question_code (p_course_id::integer, 'P'::varchar) fq;
    -- 4. Insertar pregunta
    INSERT INTO question (code, "number", course_id, topic_id, level_id, type, description, short_description, fl_diagrammed, ter, config_alternative_id, columns, status, priority, teacher_id, fl_status, created_by, created_at)
        VALUES (v_new_code, v_new_number, p_course_id, p_topic_id, p_level_id, p_type_td, p_description, p_short_description, p_fl_diagrammed, p_ter, p_config_alternative_id, p_question_columns, p_status, p_priority, p_employee_id, TRUE, p_created_by, NOW())
    RETURNING
        question.id, question.code INTO v_question_id, v_question_code;
    -- 5. Subtopic
    IF p_subtopic_id IS NOT NULL THEN
        INSERT INTO question_subtopic (question_id, subtopic_id, fl_status, created_by, created_at)
            VALUES (v_question_id, p_subtopic_id, TRUE, p_created_by, NOW());
    END IF;
    -- 6. Alternativas
    FOR v_alt IN
    SELECT
        value
    FROM
        jsonb_array_elements(p_alternatives)
        LOOP
            INSERT INTO alternative (question_id, description, created_by, created_at)
                VALUES (v_question_id, (v_alt ->> 'description')::text, p_created_by, NOW())
            RETURNING
                alternative.id INTO v_alt_id;
            IF (v_alt ->> 'answer') = 'true' OR (v_alt ->> 'answer') = '100' THEN
                v_answer_id := v_alt_id;
            END IF;
        END LOOP;
    -- 7. Update answer_id
    UPDATE
        question q
    SET
        answer_id = v_answer_id,
        updated_by = p_created_by,
        updated_at = NOW()
    WHERE
        q.id = v_question_id;
    -- 8. employee_question
    INSERT INTO employee_question (teacher_id, question_id, alternative_id, type, fl_status, week, year, created_by, created_at)
        VALUES (p_employee_id, v_question_id, v_answer_id, p_status, TRUE, EXTRACT(WEEK FROM NOW())::integer, EXTRACT(YEAR FROM NOW())::integer, p_created_by, NOW())
    RETURNING
        id INTO v_employee_question_id;
    -- 9. question_status
    v_process := CASE WHEN p_status = 'INDE' THEN
        'INDEXACIÓN'
    WHEN p_status = 'ASIG' THEN
        'ASIGNACIÓN'
    ELSE
        p_status
    END;

    -- Guardar las imagenes asociadas a la pregunta
    IF p_files IS NOT NULL AND jsonb_array_length(p_files) > 0 THEN
        INSERT INTO employee_question_document
        (
            employee_question_id, 
            type_archive_id, 
            document, 
            created_by, 
            created_at
        )
        SELECT 
            v_employee_question_id, 
            (elem->>'type_id')::integer,
            elem->>'path', 
            p_created_by, 
            NOW()
        FROM jsonb_array_elements(p_files) AS elem;
    END IF;

    -- Insertar imágenes de la pregunta (si existen)
    IF p_question_images IS NOT NULL AND jsonb_array_length(p_question_images) > 0 THEN
        INSERT INTO question_image (code, extension, image, question_id, created_by, created_at)
        SELECT code, extension, image, v_question_id, p_created_by, NOW()
        FROM jsonb_to_recordset(p_question_images) AS x(code varchar, extension varchar, image text);
    END IF;

    -- Insertar imágenes de las alternativas (si existen)
    IF p_alternative_images IS NOT NULL AND jsonb_array_length(p_alternative_images) > 0 THEN
        INSERT INTO question_image (code, extension, image, question_id, created_by, created_at)
        SELECT code, extension, image, v_question_id, p_created_by, NOW()
        FROM jsonb_to_recordset(p_alternative_images) AS x(code varchar, extension varchar, image text);
    END IF;

    SELECT
        CONCAT(split_part(e.first_name, ' ', 1), ' ', upper(
            LEFT (e.first_surname, 1)), '. ', e.second_surname) INTO v_employee_name
    FROM
        employees e
    WHERE
        e.id = p_employee_id;
    UPDATE
        question_status qs
    SET
        fl_active = FALSE
    WHERE
        qs.question_id = v_question_id;
    INSERT INTO question_status (question_id, status, process, description, created_by, created_at)
        VALUES (v_question_id, p_status, v_process, 'La pregunta fue registrada como faltante por el docente <span class=''text-teacher''>' || COALESCE(v_employee_name, 'Docente') || '</span>', p_created_by, NOW());
    -- 10. Actualizar detalle
    UPDATE
        material_missing_question_detail mmqd
    SET
        question_id = v_question_id,
        employee_id = p_employee_id,
        status = 'completed',
        updated_at = NOW()
    WHERE
        mmqd.id = p_detail_id;

    -- 12. Recalcular maestro
    SELECT
        COUNT(*) INTO v_pending_count
    FROM
        material_missing_question_detail mmqd
    WHERE
        mmqd.material_missing_question_id = v_mmq.id
        AND mmqd.status = 'pending';
        
    UPDATE
        material_missing_question mmq
    SET
        status = CASE WHEN v_pending_count = 0
            AND NOW() <= v_mmq.expiration_date THEN
            'completed'
        WHEN v_pending_count = 0
            AND NOW() > v_mmq.expiration_date THEN
            'completed_late'
        ELSE
            mmq.status
        END,
        updated_at = NOW()
    WHERE
        mmq.id = v_mmq.id;
    -- 13. Retorno (sin cambios)
    RETURN QUERY
    SELECT
        q.id,
        q.code,
        q.status,
        q.description,
        COALESCE(
            (SELECT JSONB_AGG(
                JSONB_BUILD_OBJECT(
                    'id', a.id,
                    'description', a.description
                )
            )
            FROM alternative a
            WHERE a.question_id = q.id
                AND a.fl_status = true),
            '[]'::JSONB
        ) as alternatives
    FROM question q
    WHERE q.id = v_question_id;
END;
$$;


ALTER FUNCTION odiseo.fn_upload_question_missing(p_detail_id bigint, p_course_id smallint, p_type_td character varying, p_employee_id bigint, p_created_by bigint, p_topic_id smallint, p_subtopic_id integer, p_level_id bigint, p_type_question character varying, p_description text, p_short_description text, p_fl_diagrammed boolean, p_ter numeric, p_config_alternative_id bigint, p_question_columns smallint, p_status character varying, p_priority integer, p_alternatives jsonb, p_question_mode integer, p_files jsonb, p_alternative_images jsonb, p_question_images jsonb) OWNER TO postgres;

--
-- Name: fn_upsert_material_missing_question(integer, bigint, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_upsert_material_missing_question(p_week_type_material_id integer, p_user_id bigint, p_course_ids jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_material_id bigint;
    v_week smallint;
    v_type_material_id smallint;
    v_date_request timestamp;
    v_course_id integer;
    
    v_active_mmq_id bigint;
    v_has_progress boolean;
    v_has_valid_details boolean;
    v_has_missing boolean; -- Rescatado de testing para la inserción masiva
BEGIN
    -- 1. Context Resolution
    SELECT 
        m.id,
        dwtm.week,
        COALESCE(dwtm.parent_type_material_id, dwtm.type_material_id),
        COALESCE(dwtm.created_at, now())
    INTO 
        v_material_id,
        v_week,
        v_type_material_id,
        v_date_request
    FROM detail_week_type_mat dwtm
    JOIN material m ON dwtm.material_id = m.id
    WHERE dwtm.id = p_week_type_material_id;

    IF v_material_id IS NULL THEN
        RETURN;
    END IF;

    -- 2. Identify Courses to process
    IF p_course_ids IS NULL THEN
        SELECT jsonb_agg(DISTINCT course_id)
        INTO p_course_ids
        -- [REFACTOR] Se usa la nueva tabla
        FROM material_ballot_question
        WHERE material_id = v_material_id
          AND week = v_week
          AND week_type_material_id = p_week_type_material_id
          AND fl_status = true;
    END IF;

    IF p_course_ids IS NULL OR jsonb_array_length(p_course_ids) = 0 THEN
        RETURN;
    END IF;

    -- Iterate over each course (typically 1-10 courses)
    FOR v_course_id IN 
        SELECT (value::text)::integer FROM jsonb_array_elements(p_course_ids)
    LOOP
        -- Find active Parent
        v_active_mmq_id := NULL;
        SELECT id INTO v_active_mmq_id
        FROM material_missing_question
        WHERE material_id = v_material_id
          AND type_material_id = v_type_material_id
          AND week = v_week
          AND course_id = v_course_id
          AND status IN ('pending', 'expired')
          AND deleted_at IS NULL
        LIMIT 1;

        IF v_active_mmq_id IS NOT NULL THEN
            -- Check for progress (assigned or completed)
            SELECT EXISTS (
                SELECT 1 
                FROM material_missing_question_detail
                WHERE material_missing_question_id = v_active_mmq_id
                  AND deleted_at IS NULL
                  AND status IN ('completed', 'assigned')
            ) INTO v_has_progress;

            IF v_has_progress THEN
                -- Rule 1: If there is progress, cancel the whole group (no logical deletes)
                UPDATE material_missing_question
                SET status = 'canceled',
                    updated_by = p_user_id,
                    updated_at = now()
                WHERE id = v_active_mmq_id;

                UPDATE material_missing_question_detail
                SET status = 'canceled',
                    updated_at = now()
                WHERE material_missing_question_id = v_active_mmq_id
                  AND status IN ('pending', 'expired')
                  AND deleted_at IS NULL;
                  
                v_active_mmq_id := NULL;
            ELSE
                -- Rule 2: If no progress, do a logical sweep (decrease/delete orphans)
                UPDATE material_missing_question_detail mmqd
                SET deleted_at = now()
                WHERE mmqd.material_missing_question_id = v_active_mmq_id
                  AND mmqd.status IN ('pending', 'expired')
                  AND mmqd.deleted_at IS NULL
                  AND NOT EXISTS (
                      -- [REFACTOR] Validando sobre la nueva tabla material_ballot_question
                      SELECT 1 FROM material_ballot_question mdbq
                      WHERE mdbq.id = mmqd.material_ballot_question_id
                        AND mdbq.question_id IS NULL
                        AND mdbq.fl_status = true
                        AND mdbq.deleted_at IS NULL
                  );

                -- Rule 3: Check if parent is empty now. If empty, delete logically.
                SELECT EXISTS (
                    SELECT 1 FROM material_missing_question_detail
                    WHERE material_missing_question_id = v_active_mmq_id
                      AND deleted_at IS NULL
                ) INTO v_has_valid_details;
                
                IF NOT v_has_valid_details THEN
                    -- Empty ticket with no progress. Delete it logically.
                    UPDATE material_missing_question
                    SET deleted_at = now(),
                        status = 'canceled',
                        updated_by = p_user_id,
                        updated_at = now()
                    WHERE id = v_active_mmq_id;
                    
                    v_active_mmq_id := NULL;
                ELSE
                    -- Keep it alive
                    UPDATE material_missing_question
                    SET request_date = v_date_request,
                        updated_by = p_user_id,
                        updated_at = now()
                    WHERE id = v_active_mmq_id;
                END IF;
            END IF;
        END IF;

        -- =========================================================================
        -- 3. Handle missing distributions (Optimized: Bulk insertion desde TESTING)
        -- =========================================================================
        IF v_active_mmq_id IS NULL THEN
            -- Check if there are any missing distributions for this course
            SELECT EXISTS (
                SELECT 1 
                FROM material_ballot_question
                WHERE material_id = v_material_id
                  AND week = v_week
                  AND course_id = v_course_id
                  AND fl_status = true
                  AND question_id IS NULL
                  AND type_text_id IS NULL
                  AND deleted_at IS NULL
            ) INTO v_has_missing;

            IF v_has_missing THEN
                INSERT INTO material_missing_question (
                    material_id, type_material_id, week, request_date, course_id, status, created_by, created_at
                ) VALUES (
                    v_material_id, v_type_material_id, v_week, v_date_request, v_course_id, 'pending', p_user_id, now()
                ) RETURNING id INTO v_active_mmq_id;
            END IF;
        END IF;

        -- Bulk insert details that do not exist yet (Sin usar el bucle lento)
        IF v_active_mmq_id IS NOT NULL THEN
            INSERT INTO material_missing_question_detail (
                material_missing_question_id, material_ballot_question_id, status, created_at
            )
            SELECT v_active_mmq_id, mdbq.id, 'pending', now()
            FROM material_ballot_question mdbq
            WHERE mdbq.material_id = v_material_id
              AND mdbq.week = v_week
              AND mdbq.course_id = v_course_id
              AND mdbq.fl_status = true
              AND mdbq.question_id IS NULL
              AND mdbq.type_text_id IS NULL
              AND mdbq.deleted_at IS NULL
              AND NOT EXISTS (
                  SELECT 1 FROM material_missing_question_detail mmqd
                  WHERE mmqd.material_missing_question_id = v_active_mmq_id
                    AND mmqd.material_ballot_question_id = mdbq.id
                    AND mmqd.status IN ('pending', 'expired', 'assigned', 'completed')
                    AND mmqd.deleted_at IS NULL
              );
        END IF;

    END LOOP;
END;
$$;


ALTER FUNCTION odiseo.fn_upsert_material_missing_question(p_week_type_material_id integer, p_user_id bigint, p_course_ids jsonb) OWNER TO postgres;

--
-- Name: fn_user_has_permission(bigint, character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_user_has_permission(p_user_id bigint, p_permission_name character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1
        FROM users_roles ur
        JOIN users u ON u.id = ur.user_id AND u.fl_status IS TRUE AND u.id = p_user_id
        JOIN roles_permissions rp ON ur.rol_id = rp.rol_id AND rp.fl_status IS TRUE
        JOIN permissions p ON p.id = rp.permission_id AND p.name = p_permission_name AND p.fl_status IS TRUE
        WHERE ur.fl_status IS TRUE
    );
END;
$$;


ALTER FUNCTION odiseo.fn_user_has_permission(p_user_id bigint, p_permission_name character varying) OWNER TO postgres;

--
-- Name: fn_valid_syllabus_cycle(smallint, bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_valid_syllabus_cycle(f_university_id smallint, f_cycle_id bigint, f_course_id bigint, f_pseudo_course_id bigint, p_company_id bigint) RETURNS TABLE(error_message text)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            IF EXISTS (
                SELECT 1 FROM syllabus s
                WHERE s.university_id = f_university_id
                    AND (f_pseudo_course_id IS NULL OR s.pseudo_course_id = f_pseudo_course_id)
                    AND (f_course_id IS NULL OR s.course_id = f_course_id)
                    AND s.company_id = p_company_id
                    AND s.cycle_id = f_cycle_id
                    AND s.fl_status = true
            ) THEN
                RETURN QUERY SELECT 'Ya existe el syllabus para este ciclo, curso y universidad.'::TEXT;
            ELSE
                RETURN QUERY SELECT NULL::TEXT;
            END IF;
        END;
        $$;


ALTER FUNCTION odiseo.fn_valid_syllabus_cycle(f_university_id smallint, f_cycle_id bigint, f_course_id bigint, f_pseudo_course_id bigint, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_validate_config_exam(integer, integer, integer, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_validate_config_exam(p_type_material_id integer, p_material_id integer, p_week integer, p_areas_ids jsonb) RETURNS TABLE(area text, detail jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_cycle_id integer;
    v_university_id integer;
    v_type_exam_id integer;
    v_areas_array integer[];
BEGIN
    SELECT m.cycle_id, m.university_id 
    INTO v_cycle_id, v_university_id
    FROM material m 
    WHERE m.id = p_material_id AND m.fl_status IS TRUE;

    SELECT te.id 
    INTO v_type_exam_id
    FROM type_material tm
    JOIN type_material_template tmt ON tm.type_material_template_id = tmt.id
    JOIN type_exams te ON tmt.type_exam_id = te.id
    WHERE tm.id = p_type_material_id AND tm.fl_status IS TRUE;

    SELECT ARRAY(SELECT jsonb_array_elements_text(p_areas_ids)::int) INTO v_areas_array;

    RETURN QUERY
    WITH cte_typ_material_area AS (
        SELECT tma.id, tma.area_id
        FROM type_material_area tma
        WHERE tma.type_material_id = p_type_material_id
          AND tma.fl_status IS TRUE
          AND tma.area_id = ANY(v_areas_array)
    ),

    cte_type_material_course AS (
        SELECT 
            tmc.id,
            tmc.course_id,
            v.generated_amount AS amount_question,
            v.generated_name AS course_name,
            v.is_text_record,
            s.id AS syllabus_id
        FROM type_material_course tmc
        JOIN course c ON tmc.course_id = c.id
        JOIN syllabus s ON s.course_id = c.id 
            AND s.cycle_id = v_cycle_id 
            AND s.university_id = v_university_id 
            AND s.fl_status IS TRUE
        CROSS JOIN LATERAL (
            VALUES 
                (tmc.amount_question, c.name, FALSE),
                (COALESCE(tmc.amount_text, 0), CONCAT(c.name, ' (Texto)'), TRUE)
        ) AS v(generated_amount, generated_name, is_text_record)
        WHERE tmc.type_material_id = p_type_material_id
          AND tmc.fl_status IS TRUE
          AND (v.is_text_record = FALSE OR c.apply_text = TRUE)
          AND v.generated_amount > 0
    ),

    cte_valid_syllabus_weeks AS (
        SELECT st.syllabus_id, stw.week, FALSE AS is_text_record
        FROM syllabus_topic st
        JOIN syllabus_topic_week stw ON stw.syllabus_topic_id = st.id
        WHERE st.fl_status IS TRUE 
          AND stw.fl_status IS TRUE 
          AND stw.total_questions_amount > 0
          AND st.syllabus_id IN (SELECT syllabus_id FROM cte_type_material_course WHERE is_text_record = FALSE)

        UNION ALL

        SELECT stw.syllabus_id, stw.week, TRUE AS is_text_record
        FROM syllabus_text_weeks stw
        JOIN syllabus_text_distributions std ON std.syllabus_text_week_id = stw.id
        JOIN type_material tm ON tm.id = std.type_material_id
        WHERE stw.fl_status IS TRUE 
          AND std.fl_status IS TRUE 
          AND tm.fl_status IS TRUE 
          AND tm.description <> 'ECO'
          AND stw.syllabus_id IN (SELECT syllabus_id FROM cte_type_material_course WHERE is_text_record = TRUE)
    ),

    cte_config_level_sums AS (
        SELECT
            emcac.exam_area_id,
            emcac.course_id,
            FALSE as config_is_text, 
            COALESCE(SUM(emcacl.amount_question), 0)::INTEGER as total_level_amount
        FROM exam_material_configurations emc
        INNER JOIN exam_material_config_area_courses emcac ON emc.id = emcac.exam_material_config_id
        INNER JOIN exam_material_config_area_course_levels emcacl ON emcac.id = emcacl.exam_material_config_area_course_id AND emcacl.fl_status = TRUE
        JOIN course_level cl ON cl.level_id = emcacl.level_id AND cl.course_id = emcac.course_id AND cl.fl_status = true
        WHERE emc.type_material_id = p_type_material_id
            AND emc.fl_status = TRUE
            AND emcac.fl_status = TRUE
            AND emc.cycle_id = v_cycle_id
        GROUP BY emcac.exam_area_id, emcac.course_id

        UNION ALL

        SELECT 
            ttemc.area_id, ttemc.course_id,
            TRUE as config_is_text, 
            COALESCE(SUM(ttemc.text_amount), 0)::INTEGER as total_level_amount 
        FROM exam_material_configurations emc
        INNER JOIN type_text_exam_material_configuration ttemc ON emc.id = ttemc.exam_material_config_id
        WHERE emc.type_material_id = p_type_material_id
            AND emc.fl_status = TRUE
            AND ttemc.deleted_at IS NULL
            AND emc.cycle_id = v_cycle_id
        GROUP BY ttemc.area_id, ttemc.course_id
    ),

    cte_periods AS (
        SELECT 
            ROW_NUMBER() OVER (ORDER BY starting_week) AS period_number,
            starting_week AS start_week,
            ending_week   AS end_week
        FROM fn_get_periods_weeks_on_type_material(p_type_material_id::bigint, p_week::smallint)
        WHERE ending_week <= p_week
          AND v_type_exam_id = 3
    ),

    type_material_area_course_relation AS (
        SELECT DISTINCT
            tma.area_id::INTEGER,
            tmc.course_id::INTEGER,
            tmc.course_name::VARCHAR,
            tmc.amount_question::INTEGER, 
            tmc.is_text_record,
            COALESCE(cls.total_level_amount, 0)::INTEGER as amount_level_question,

            CASE 
                WHEN v_type_exam_id = 3 THEN COALESCE(p_data.config_syllabus, FALSE)
                WHEN v_type_exam_id = 2 THEN 
                    EXISTS (
                        SELECT 1 FROM cte_valid_syllabus_weeks vw 
                        WHERE vw.syllabus_id = tmc.syllabus_id 
                          AND vw.is_text_record = tmc.is_text_record
                          AND vw.week = p_week
                    )
                WHEN v_type_exam_id = 4 THEN 
                    EXISTS (
                        SELECT 1 FROM cte_valid_syllabus_weeks vw 
                        WHERE vw.syllabus_id = tmc.syllabus_id 
                          AND vw.is_text_record = tmc.is_text_record
                    )
                ELSE FALSE 
            END AS config_syllabus,

            CASE 
                WHEN v_type_exam_id = 3 THEN p_data.period_detail
                ELSE NULL
            END AS period_detail

        FROM type_material_area_courses tmac
        JOIN cte_typ_material_area tma ON tma.id = tmac.type_material_area_id
        JOIN cte_type_material_course tmc ON tmc.id = tmac.type_material_course_id
        LEFT JOIN cte_config_level_sums cls 
            ON cls.exam_area_id = tma.area_id 
            AND cls.course_id = tmc.course_id
            AND cls.config_is_text = tmc.is_text_record
        
        LEFT JOIN LATERAL (
            SELECT 
                BOOL_AND(p.has_data) AS config_syllabus,
                jsonb_agg(
                    jsonb_build_object(
                        'period', p.period_number,
                        'start_week', p.start_week,
                        'end_week', p.end_week,
                        'has_data', p.has_data
                    ) ORDER BY p.period_number
                ) AS period_detail
            FROM (
                SELECT 
                    cp.period_number, cp.start_week, cp.end_week,
                    EXISTS (
                        SELECT 1 FROM cte_valid_syllabus_weeks vw 
                        WHERE vw.syllabus_id = tmc.syllabus_id 
                          AND vw.is_text_record = tmc.is_text_record
                          AND vw.week BETWEEN cp.start_week AND cp.end_week
                    ) AS has_data
                FROM cte_periods cp
            ) p
        ) p_data ON v_type_exam_id = 3
        
        WHERE tmac.fl_status = TRUE
    )

    SELECT
        a.description::TEXT as area,
        jsonb_agg(
            jsonb_build_object(
                'course', tmacr.course_name,
                'config_syllabus', tmacr.config_syllabus,
                'config_level', tmacr.amount_level_question,
                'config_type_material', tmacr.amount_question,
                'period_detail', tmacr.period_detail
            ) ORDER BY tmacr.course_id, tmacr.is_text_record
        ) as detail
    FROM type_material_area_course_relation tmacr
    JOIN exam_area a ON a.id = tmacr.area_id 
    GROUP BY a.id, a.description;

END;
$$;


ALTER FUNCTION odiseo.fn_validate_config_exam(p_type_material_id integer, p_material_id integer, p_week integer, p_areas_ids jsonb) OWNER TO postgres;

--
-- Name: fn_validate_frequent_university_subtopic(integer, smallint, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_validate_frequent_university_subtopic(p_question_id integer, p_university smallint, p_updated_by integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_subtopic_id INTEGER;
            v_subtopic_has_more_source_layer_completed_questions BOOLEAN DEFAULT FALSE;
        BEGIN
            DROP TABLE IF EXISTS current_question_subtopics;
            CREATE TEMP TABLE current_question_subtopics AS
            SELECT
                subtopic_id
            FROM question_subtopic qs
            WHERE qs.question_id = p_question_id
                AND qs.fl_status IS TRUE
                AND qs.deleted_at IS NULL;

            DROP TABLE IF EXISTS previous_question_subtopics;
            CREATE TEMP TABLE previous_question_subtopics AS
            SELECT
                qs.subtopic_id
            FROM question_subtopic qs
            WHERE qs.question_id = p_question_id
                AND ( qs.fl_status IS FALSE OR qs.deleted_at IS NOT NULL )
                AND qs.subtopic_id NOT IN (SELECT subtopic_id FROM current_question_subtopics)
            GROUP BY qs.subtopic_id;

            FOR v_subtopic_id IN (SELECT pqs.subtopic_id FROM previous_question_subtopics pqs)
            LOOP
                SELECT EXISTS (
                    SELECT
                        q.id
                    FROM question q
                    JOIN question_subtopic qs ON q.id = qs.question_id AND qs.fl_status IS TRUE AND qs.deleted_at IS NULL
                    JOIN frequent_university_subtopic fus ON fus.subtopic_id = qs.subtopic_id
                        AND fus.subtopic_id = v_subtopic_id
                        AND fus.university_id = p_university
                    WHERE 1 = 1
                        AND qs.deleted_at IS NULL
                        AND qs.fl_status IS TRUE
                        AND fus.is_frequent IS TRUE
                        AND fus.fl_status IS TRUE
                        AND q.id != p_question_id
                        AND q.region IS NOT NULL
                        AND q.year IS NOT NULL
                        AND q.option_id IS NOT NULL
                        AND q.modality_id IS NOT NULL
                        AND q.area IS NOT NULL
                        AND q.version IS NOT NULL
                )
                INTO v_subtopic_has_more_source_layer_completed_questions;

                IF v_subtopic_has_more_source_layer_completed_questions IS FALSE THEN
                    UPDATE frequent_university_subtopic
                        SET is_frequent = FALSE
                    WHERE 1 = 1
                        AND university_id = p_university
                        AND subtopic_id = v_subtopic_id
                        AND method = 'system';
                END IF;
            END LOOP;

            FOR v_subtopic_id IN (SELECT cqs.subtopic_id FROM current_question_subtopics cqs)
            LOOP
                INSERT INTO frequent_university_subtopic (
                    university_id,
                    subtopic_id,
                    created_at,
                    updated_by
                )
                VALUES (
                    p_university,
                    v_subtopic_id,
                    NOW(),
                    p_updated_by
                )
                ON CONFLICT (university_id, subtopic_id)
                DO UPDATE SET
                    is_frequent = TRUE,
                    fl_status = TRUE,
                    updated_at = NOW(),
                    updated_by = p_updated_by;
            END LOOP;
        END;
        $$;


ALTER FUNCTION odiseo.fn_validate_frequent_university_subtopic(p_question_id integer, p_university smallint, p_updated_by integer) OWNER TO postgres;

--
-- Name: fn_validate_history_question(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_validate_history_question(p_material_id bigint, p_question_id bigint) RETURNS TABLE(fl_validate boolean, v_message text)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_cycle_id BIGINT;
            v_cycle_description VARCHAR;
            v_cycle_start_date DATE;
            v_history JSONB;
            v_first_start_date DATE;
            v_last_start_date DATE;
            v_years_diff INTEGER;
            v_within_range BOOLEAN;
        BEGIN
            -- Obtener ciclo y universidad del material
            SELECT
                m.cycle_id, c.start_date
                INTO v_cycle_id, v_cycle_start_date
            FROM material m
            INNER JOIN cycle c ON m.cycle_id = c.id
            WHERE m.id = p_material_id
            LIMIT 1;

            -- Obtener los campos de pregunta
            SELECT
                fqvm.history INTO v_history
            FROM fn_question_verified_material(p_material_id) fqvm
            WHERE fqvm.id = p_question_id
            LIMIT 1;

            -- VALIDAR HISTORIAL
            IF v_history = '[]' THEN
                RETURN QUERY SELECT true, 'Si cumple, no tiene historial';
                RETURN;
            END IF;

            -- Obtener la fecha de inicio del primer historial
            SELECT (elem->>'start_date')::DATE
            INTO v_first_start_date
            FROM jsonb_array_elements(v_history) AS elem
            ORDER BY (elem->>'start_date')::DATE
            LIMIT 1;

            -- Validar si hay una diferencia de al menos 1 año
            SELECT DATE_PART('year', AGE(v_cycle_start_date, v_first_start_date))
            INTO v_years_diff;

            IF v_years_diff >= 1 THEN
                RETURN QUERY SELECT true, 'Si cumple, primera fecha tiene 1 año o más de diferencia';
                RETURN;
            END IF;

            -- Obtener la fecha de inicio del último historial
            SELECT
                (elem->>'start_date')::DATE, c.description
                INTO v_last_start_date, v_cycle_description
            FROM jsonb_array_elements(v_history) AS elem
            JOIN cycle c ON (elem->>'cycle_id')::INT = c.id
            ORDER BY (elem->>'start_date')::DATE DESC
            LIMIT 1;

            -- Calcular el rango de 3 semanas (21 días)
            v_within_range := CASE
                WHEN v_cycle_start_date < v_last_start_date THEN
                    v_cycle_start_date BETWEEN v_last_start_date - INTERVAL '21 days' AND v_last_start_date
                ELSE
                    v_last_start_date BETWEEN v_cycle_start_date - INTERVAL '21 days' AND v_cycle_start_date
            END;

            IF v_within_range THEN
                RETURN QUERY SELECT true, 'Si cumple, está dentro del rango de 21 días';
                RETURN;
            END IF;

            -- Si no cumplió ninguna condición anterior
            RETURN QUERY SELECT false, 'No cumple, esta siendo usado por el ciclo ' || v_cycle_description;
        END;
        $$;


ALTER FUNCTION odiseo.fn_validate_history_question(p_material_id bigint, p_question_id bigint) OWNER TO postgres;

--
-- Name: fn_validate_parent_type_mat(smallint, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_validate_parent_type_mat(p_parent_type_mat_id smallint, p_type_materials jsonb) RETURNS TABLE(not_type_materials smallint[])
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_type_material_id SMALLINT;
            v_p_type_material_template_id SMALLINT;
            v_type_material_template_id SMALLINT;
            v_validate_relation BIGINT;
            v_ids SMALLINT[] := ARRAY[]::SMALLINT[];
        BEGIN
            SELECT tmp.type_material_template_id INTO v_p_type_material_template_id
            FROM type_material tmp
            WHERE tmp.id = p_parent_type_mat_id LIMIT 1;

            FOR v_type_material_id IN SELECT * FROM jsonb_array_elements(p_type_materials) LOOP
                SELECT tm.type_material_template_id INTO v_type_material_template_id
                FROM type_material tm
                WHERE id = v_type_material_id LIMIT 1;

                IF p_parent_type_mat_id <> v_type_material_id THEN
                    SELECT id INTO v_validate_relation FROM type_material_bound
                    WHERE type_material_template_id = v_p_type_material_template_id
                    AND type_material_template_extra_id = v_type_material_template_id
                    AND fl_status = true LIMIT 1;

                    IF v_validate_relation IS NULL THEN
                        v_ids := array_append(v_ids, v_type_material_id);
                    END IF;
                END IF;
            END LOOP;

            RETURN QUERY SELECT v_ids;
        END;
        $$;


ALTER FUNCTION odiseo.fn_validate_parent_type_mat(p_parent_type_mat_id smallint, p_type_materials jsonb) OWNER TO postgres;

--
-- Name: fn_validate_save_code_prospect(character varying); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_validate_save_code_prospect(p_code character varying) RETURNS TABLE(v_validated boolean)
    LANGUAGE plpgsql
    AS $$
			DECLARE
				v_code_id BIGINT;
				v_new_id BIGINT;
            BEGIN
                SELECT cp.id INTO v_code_id
                FROM odiseo.code_prospect cp
				WHERE code = p_code
				LIMIT 1;

				IF v_code_id IS NULL THEN
					INSERT INTO odiseo.code_prospect (code, created_by, created_at)
					VALUES(p_code, 1, now())
					RETURNING id INTO v_new_id;

					RETURN QUERY SELECT TRUE;
				ELSE
					RETURN QUERY SELECT FALSE;
				END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_validate_save_code_prospect(p_code character varying) OWNER TO postgres;

--
-- Name: fn_verified_course_question(boolean, smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_verified_course_question(p_parent_val boolean, p_course_id smallint) RETURNS TABLE(id bigint, code character varying, description text, short_description text, course_id smallint, parent_id bigint)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    q.id,
                    q.code,
                    q.description,
                    q.short_description,
                    q.course_id,
                    q.parent_id
                FROM odiseo.question q
                WHERE q.fl_status = true
                AND q.course_id = p_course_id
                AND q.short_description IS NOT NULL
                AND q.status NOT IN ('DUPL', 'ARCH')
                AND (
                    p_parent_val IS TRUE AND q.parent_id IS NULL
                    OR p_parent_val IS NOT TRUE AND q.parent_id IS NOT NULL
                )
				ORDER BY q.id ASC;
            END;
            $$;


ALTER FUNCTION odiseo.fn_verified_course_question(p_parent_val boolean, p_course_id smallint) OWNER TO postgres;

--
-- Name: fn_verified_parent_question(); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_verified_parent_question() RETURNS TABLE(id bigint, code character varying, description text, short_description text, course_id smallint)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    pq.id,
                    pq.code,
                    pq.description,
                    pq.short_description,
                    pq.course_id
                FROM odiseo.parent_question pq
                WHERE pq.fl_status = true
                AND pq.short_description IS NOT NULL
				ORDER BY pq.id ASC;
            END;
            $$;


ALTER FUNCTION odiseo.fn_verified_parent_question() OWNER TO postgres;

--
-- Name: fn_verified_question(boolean); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_verified_question(p_parent_val boolean) RETURNS TABLE(id bigint, code character varying, description text, short_description text, course_id smallint, parent_id bigint)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    q.id,
                    q.code,
                    q.description,
                    q.short_description,
                    q.course_id,
                    q.parent_id
                FROM odiseo.question q
                WHERE q.fl_status = true
                AND q.short_description IS NOT NULL
                AND q.status NOT IN ('DUPL', 'ARCH')
                AND (
                    p_parent_val IS TRUE AND q.parent_id IS NULL
                    OR p_parent_val IS NOT TRUE AND q.parent_id IS NOT NULL
                )
				ORDER BY q.id ASC;
            END;
            $$;


ALTER FUNCTION odiseo.fn_verified_question(p_parent_val boolean) OWNER TO postgres;

--
-- Name: fn_verified_save_user_employee(uuid, character varying, character varying, text, integer, character varying, bigint, bigint, bigint, uuid, character varying, character varying, character varying, integer, character varying, character varying, character varying, integer, integer, boolean, character varying, integer, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_verified_save_user_employee(p_uuid uuid, p_user character varying, p_email character varying, p_password text, p_status_session integer, p_image character varying, p_created_by bigint, p_company_id bigint, p_rol_id bigint, p_uuid_e uuid, p_first_name character varying, p_first_surname character varying, p_second_surname character varying, p_type_document_id integer, p_document character varying, p_email_e character varying, p_phone character varying, p_limit_assigned_questions integer, p_limit_assigned_questions_initial integer, p_fl_unlimit_questions boolean, p_code character varying, p_charge_id integer, p_course jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
			DECLARE
				v_id BIGINT;
				v_new_user_id BIGINT;
				v_new_employee_id BIGINT;
            BEGIN
                SELECT u.id INTO v_id
                FROM odiseo.users u
				WHERE u.user = p_user
				LIMIT 1;

				IF v_id IS NULL THEN
					INSERT INTO odiseo.users (uuid, "user", email, password, status_session, image, created_by, created_at, company_id)
					VALUES(p_uuid, p_user, p_email, p_password, p_status_session, p_image, p_created_by, now(), p_company_id)
					RETURNING id INTO v_new_user_id;

					INSERT INTO odiseo.users_roles (user_id, rol_id, created_by, created_at)
					VALUES (v_new_user_id, p_rol_id, p_created_by, now());

					INSERT INTO odiseo.employees (uuid, user_id, first_name, first_surname, second_surname, type_document_id, "document", email, phone, created_by, created_at, code, limit_assigned_questions, limit_assigned_questions_initial, fl_unlimit_questions, charge_id)
					VALUES (p_uuid, v_new_user_id, p_first_name, p_first_surname, p_second_surname, p_type_document_id, p_document, p_email_e, p_phone, p_created_by, now(), p_code, p_limit_assigned_questions, p_limit_assigned_questions_initial, p_fl_unlimit_questions, p_charge_id)
					RETURNING id INTO v_new_employee_id;

					INSERT INTO odiseo.employee_course (teacher_id, course_id, created_by, created_at)
		            SELECT v_new_employee_id, value::bigint, p_created_by, now()
		            FROM jsonb_array_elements(p_course) AS value;
				END IF;
            END;
            $$;


ALTER FUNCTION odiseo.fn_verified_save_user_employee(p_uuid uuid, p_user character varying, p_email character varying, p_password text, p_status_session integer, p_image character varying, p_created_by bigint, p_company_id bigint, p_rol_id bigint, p_uuid_e uuid, p_first_name character varying, p_first_surname character varying, p_second_surname character varying, p_type_document_id integer, p_document character varying, p_email_e character varying, p_phone character varying, p_limit_assigned_questions integer, p_limit_assigned_questions_initial integer, p_fl_unlimit_questions boolean, p_code character varying, p_charge_id integer, p_course jsonb) OWNER TO postgres;

--
-- Name: fn_week_all(); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_week_all() RETURNS TABLE(id smallint, description character varying)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    week.id,
					week.description
                FROM odiseo.week
                WHERE week.fl_status IS TRUE
                ORDER BY week.id ASC;
            END;
            $$;


ALTER FUNCTION odiseo.fn_week_all() OWNER TO postgres;

--
-- Name: fn_week_subtopics(bigint, integer, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_week_subtopics(p_syllabus_id bigint, p_week integer, p_company_id bigint) RETURNS TABLE(syllabus_id bigint, week smallint, topic_id smallint, topic_name character varying, subtopic_id smallint, subtopic_name character varying, amount smallint, questions_amount jsonb)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            WITH tbl_syllabus_subtopic_type_material AS (
                SELECT
                    st.id,
                    st.type_material_id,
                    tm.description AS type_material,
                    st.questions_amount AS amount,
                    st.syllabus_detail_subtopic_id
                FROM syllabus_subtopic_type_material st
                LEFT JOIN type_material tm ON st.type_material_id = tm.id
                WHERE st.fl_status = true
                AND tm.fl_status = true
                AND st.company_id = p_company_id
                ORDER BY tm.description ASC
            ), tbl_syllabus_detail_subtopic AS (
                SELECT
                    ds.id,
                    ds.syllabus_topic_week_id,
                    ds.subtopic_id,
                    s.name AS subtopic_name,
                    ds.questions_amount AS amount,
                    COALESCE(
                        jsonb_agg(
                            jsonb_build_object(
                                'id', st.id,
                                'type_material_id', st.type_material_id,
                                'type_material', st.type_material,
                                'amount', st.amount
                            )
                        ),
                        '[]'::jsonb
                    ) as questions_amount
                FROM syllabus_detail_subtopic ds
                LEFT JOIN subtopic s ON ds.subtopic_id = s.id
                LEFT JOIN tbl_syllabus_subtopic_type_material st ON ds.id = st.syllabus_detail_subtopic_id
                WHERE ds.fl_status = true
                AND ds.company_id = p_company_id
                GROUP BY ds.id, ds.syllabus_topic_week_id, ds.subtopic_id, s.name, ds.questions_amount
            ), tbl_syllabus_topic_week AS (
                SELECT
                    st.syllabus_id,
                    tw.week,
                    st.topic_id,
                    t.name AS topic_name,
                    ds.subtopic_id,
                    ds.subtopic_name,
                    ds.amount,
                    ds.questions_amount
                FROM syllabus_topic_week tw
                INNER JOIN tbl_syllabus_detail_subtopic ds ON tw.id = ds.syllabus_topic_week_id
                INNER JOIN syllabus_topic st ON tw.syllabus_topic_id = st.id
                INNER JOIN topic t ON st.topic_id = t.id
                WHERE tw.fl_status = true
                AND st.fl_status = true
                AND tw.company_id = p_company_id
                AND tw.week = p_week
                AND st.syllabus_id = p_syllabus_id
            )
            SELECT * FROM tbl_syllabus_topic_week
            ORDER BY topic_name ASC, subtopic_name ASC;
        END;
        $$;


ALTER FUNCTION odiseo.fn_week_subtopics(p_syllabus_id bigint, p_week integer, p_company_id bigint) OWNER TO postgres;

--
-- Name: fn_weeks_syllabus_ids(jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.fn_weeks_syllabus_ids(p_syllabus_topic_ids jsonb) RETURNS TABLE(id bigint, syllabus_topic_id bigint, week smallint, total_questions_amount smallint, created_at timestamp without time zone, subtopics jsonb)
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                        RETURN QUERY
                        WITH get_syllabus_topics AS (
                            SELECT
                                value::BIGINT AS syballus_topic_id
                            FROM jsonb_array_elements(p_syllabus_topic_ids)
                        ), tbl_syllabus_subtopic_type_material AS (
                            SELECT
                                sstm.syllabus_detail_subtopic_id,
                                jsonb_agg(
                                    jsonb_build_object(
                                        'id',                 sstm.id,
                                        'type_material_id',   sstm.type_material_id,
                                        'type_material',      tm.description,
                                        'amount',             sstm.questions_amount
                                    ) ORDER BY
                                        CASE
                                            WHEN tm.description = 'ECO' THEN 1
                                            WHEN tm.description = 'Guía de clases' THEN 2
                                            WHEN tm.description = 'Homework' THEN 3
                                            ELSE 4
                                        END
                                )::TEXT AS questions_amount
                            FROM syllabus_subtopic_type_material sstm
                            JOIN type_material tm ON sstm.type_material_id = tm.id
                            JOIN syllabus_detail_subtopic sds ON sstm.syllabus_detail_subtopic_id = sds.id
                                AND sds.fl_status = true
                            JOIN syllabus_topic_week stw ON sds.syllabus_topic_week_id = stw.id
                                AND stw.fl_status = true
                            WHERE stw.syllabus_topic_id IN (SELECT gst.syballus_topic_id FROM get_syllabus_topics gst)
                                AND sstm.fl_status = true
                            GROUP BY sstm.syllabus_detail_subtopic_id
                        ), tbl_syllabus_detail_subtopic AS (
                            SELECT
                                ds.id,
                                ds.syllabus_topic_week_id,
                                ds.subtopic_id,
                                s.code        AS code_subtopic,
                                CONCAT(s.code, ' - ', s.name) AS name,
                                s.name       AS name_no_prefix,
                                ds.questions_amount AS amount,
                                ds.created_at,
                                st.questions_amount::jsonb
                            FROM syllabus_detail_subtopic ds
                            JOIN syllabus_topic_week stw ON ds.syllabus_topic_week_id = stw.id
                            JOIN subtopic s ON ds.subtopic_id = s.id
                            LEFT JOIN tbl_syllabus_subtopic_type_material st ON st.syllabus_detail_subtopic_id = ds.id
                            WHERE ds.fl_status
                                AND stw.syllabus_topic_id IN (SELECT gst.syballus_topic_id FROM get_syllabus_topics gst)
                            GROUP BY
                                ds.id, ds.syllabus_topic_week_id, ds.subtopic_id,
                                s.code, s.name, ds.questions_amount,
                                st.questions_amount
                        )
                        SELECT
                            tw.id,
                            tw.syllabus_topic_id,
                            tw.week,
                            tw.total_questions_amount,
                            tw.created_at,
                            COALESCE(
                            jsonb_agg(
                                jsonb_build_object(
                                'id',                         ds.subtopic_id,
                                'syllabus_topic_week_id',     ds.syllabus_topic_week_id,
                                'code_subtopic',              ds.code_subtopic,
                                'name',                       ds.name,
                                'name_no_prefix',             ds.name_no_prefix,
                                'amount',                     ds.amount,
                                'created_at',                 ds.created_at,
                                'questions_amount',           ds.questions_amount,
                                'syllabus_detail_subtopic_id',ds.id
                                ) ORDER BY ds.code_subtopic
                            ) FILTER (WHERE ds.id IS NOT NULL),
                            '[]'::jsonb
                            ) AS subtopics
                        FROM syllabus_topic_week tw
                        LEFT JOIN tbl_syllabus_detail_subtopic ds
                        ON tw.id = ds.syllabus_topic_week_id
                        WHERE tw.syllabus_topic_id IN (SELECT gst.syballus_topic_id FROM get_syllabus_topics gst)
                        AND tw.fl_status
                        GROUP BY
                        tw.id, tw.syllabus_topic_id, tw.week,
                        tw.total_questions_amount, tw.created_at
                        ORDER BY tw.week;
                    END;
                    $$;


ALTER FUNCTION odiseo.fn_weeks_syllabus_ids(p_syllabus_topic_ids jsonb) OWNER TO postgres;

--
-- Name: get_course_levels_totals(integer, integer, integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.get_course_levels_totals(p_cycle_id integer, p_week integer, p_type_material_id integer, p_university_id integer, p_headquarter_id integer) RETURNS TABLE(course_id bigint, levels_total numeric)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT
                    ls.course_id,
                    (
                        SUM(COALESCE(dlsw.number_questions, 0))::NUMERIC
                        /
                        NULLIF(COUNT(DISTINCT ls.headquarter_id), 0)
                    ) AS levels_total
                FROM
                    detail_level_syllabus_weeks dlsw
                JOIN level_syllabus_weeks lsw ON lsw.id = dlsw.level_syllabus_weeks_id
                JOIN level_syllabus ls ON ls.id = lsw.level_syllabus_id
                WHERE
                    ls.cycle_id = p_cycle_id
                    AND ls.university_id = p_university_id
                    AND ls.headquarter_id = p_headquarter_id
                    AND lsw.week = p_week
                    AND dlsw.type_material_id = p_type_material_id
                    AND dlsw.fl_status = TRUE
                    AND ls.fl_status = TRUE
                    AND ls.deleted_at IS NULL
                    AND lsw.deleted_at IS NULL
                    AND dlsw.deleted_at IS NULL
                GROUP BY
                    ls.course_id;
            END;
            $$;


ALTER FUNCTION odiseo.get_course_levels_totals(p_cycle_id integer, p_week integer, p_type_material_id integer, p_university_id integer, p_headquarter_id integer) OWNER TO postgres;

--
-- Name: get_detail_level_syllabus_week(integer, integer, integer, integer, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.get_detail_level_syllabus_week(p_university_id integer, p_cycle_id integer, p_week_id integer, p_course_id integer, p_headquarter_id jsonb) RETURNS TABLE(level_id bigint, name_level character varying, type_material_id smallint, name_type_material character varying, type_question text, total_questions integer)
    LANGUAGE plpgsql
    AS $$

        BEGIN

            RETURN QUERY
            SELECT
                tbl_detail_level_syllabus_week.level_id,
                tbl_detail_level_syllabus_week.name_level,
                tbl_detail_level_syllabus_week.type_material_id,
                tbl_detail_level_syllabus_week.name_type_material,
                tbl_detail_level_syllabus_week.type_question,
                COALESCE(tbl_value_detail_level_syllabus_week.number_questions, 0) AS number_questions
            FROM
                (
                    SELECT
                        l.id AS level_id,
                        l.description AS name_level,
                        tm.type_material_id,
                        tm.name_type_material,
                        tq.type_question,
                        cl.course_id
                    FROM
                        course_level cl
                    INNER JOIN
                        "level" l
                    ON
                        cl.level_id = l.id
                    CROSS JOIN
                        (SELECT 'T' AS type_question
                        UNION ALL
                        SELECT 'D' AS type_question) tq
                    CROSS JOIN
                        (SELECT
                            tm.id AS type_material_id,
                            tm.description AS name_type_material
                        FROM
                            type_material tm
                        WHERE
                            tm.fl_status = true
                            AND tm.deleted_at IS NULL
                            AND tm.cycle_id = p_cycle_id
                        ) AS tm
                    WHERE
                        cl.course_id = p_course_id
                        AND cl.fl_status = true
                        AND l.fl_status = true
                        AND l.deleted_at IS NULL
                ) AS tbl_detail_level_syllabus_week
            LEFT JOIN
                (
                    SELECT
                        DISTINCT dlsw.type_material_id,
                        dlsw.level_id,
                        dlsw.type_question,
                        dlsw.number_questions
                    FROM
                        level_syllabus ls
                    INNER JOIN
                        level_syllabus_weeks lsw
                    ON
                        ls.id = lsw.level_syllabus_id
                    INNER JOIN
                        detail_level_syllabus_weeks dlsw
                    ON
                        dlsw.level_syllabus_weeks_id = lsw.id
                    WHERE
                        ls.course_id = p_course_id
                        AND ls.university_id = p_university_id
                        AND ls.cycle_id = p_cycle_id
                        AND lsw.week  = p_week_id
                        AND ls.headquarter_id = ANY (SELECT jsonb_array_elements_text(p_headquarter_id)::INTEGER)
                        AND ls.fl_status = true
                        AND lsw.fl_status = true
                        AND dlsw.fl_status = true
                ) AS tbl_value_detail_level_syllabus_week
            ON
                tbl_detail_level_syllabus_week.level_id = tbl_value_detail_level_syllabus_week.level_id 
                AND tbl_detail_level_syllabus_week.type_question = tbl_value_detail_level_syllabus_week.type_question
                AND tbl_detail_level_syllabus_week.type_material_id = tbl_value_detail_level_syllabus_week.type_material_id
            ORDER BY
                tbl_detail_level_syllabus_week.name_level ASC,
                tbl_detail_level_syllabus_week.type_material_id ASC,
                tbl_detail_level_syllabus_week.type_question DESC;
        END;
        $$;


ALTER FUNCTION odiseo.get_detail_level_syllabus_week(p_university_id integer, p_cycle_id integer, p_week_id integer, p_course_id integer, p_headquarter_id jsonb) OWNER TO postgres;

--
-- Name: get_detail_level_syllabus_week_parent(integer, integer, integer, integer, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.get_detail_level_syllabus_week_parent(p_university_id integer, p_cycle_id integer, p_week_id integer, p_course_id integer, p_headquarter_id jsonb) RETURNS TABLE(level_id bigint, name_level character varying, type_material_id smallint, name_type_material character varying, total_text integer)
    LANGUAGE plpgsql
    AS $$
	BEGIN
		RETURN QUERY
		SELECT
		    tbl_detail_level_syllabus_week.level_id,
		    tbl_detail_level_syllabus_week.name_level,
		    tbl_detail_level_syllabus_week.type_material_id,
		    tbl_detail_level_syllabus_week.name_type_material,
		    COALESCE(tbl_value_detail_level_syllabus_week.number_of_passages, 0) AS number_of_passages
		FROM
		    (
		        SELECT
		            l.id AS level_id,
		            l.description AS name_level,
		            tm.type_material_id,
		            tm.name_type_material
		        FROM
		            course_level cl
		        INNER JOIN
		            "level" l
		        ON
		            cl.level_id = l.id
		        CROSS JOIN
		            (
		            SELECT
		                tm.id AS type_material_id,
		                tm.description AS name_type_material
					FROM
					    type_material tm
					JOIN "cycle" c ON c.id = tm.cycle_id
					WHERE
					    tm.fl_status = true
					    AND tm.deleted_at IS NULL
					    AND tm.fl_exam = false
					    AND c.id = p_cycle_id
					    AND tm.id NOT IN (
					        SELECT DISTINCT parent_id
					        FROM type_material
					        WHERE parent_id IS NOT NULL
					    )
		            ) AS tm
		        WHERE
		            cl.course_id = p_course_id
		            AND cl.fl_status = TRUE
		            AND l.fl_status = TRUE
		            AND l.deleted_at IS NULL
		    ) AS tbl_detail_level_syllabus_week
		LEFT JOIN
		    (
		        SELECT
		            DISTINCT dlsw.type_material_id,
		            dlsw.level_id,
		            l."name" level,
		            dlsw.number_of_passages
		        FROM
		            level_syllabus ls
		        INNER JOIN
		            level_syllabus_weeks lsw
		        ON
		            ls.id = lsw.level_syllabus_id
		        INNER JOIN
		            detail_level_syllabus_weeks_parents  dlsw
		        ON
		            dlsw.level_syllabus_weeks_id = lsw.id
		        INNER JOIN
		        	"level" l ON l.id = dlsw.level_id
		        WHERE
		            ls.course_id = p_course_id
		            AND ls.university_id = p_university_id
		            AND ls.cycle_id = p_cycle_id
		            AND lsw.week  = p_week_id
		            AND ls.headquarter_id = ANY (SELECT jsonb_array_elements_text(p_headquarter_id)::INTEGER)
		            AND ls.fl_status = true
		            AND lsw.fl_status = true
		            AND dlsw.fl_status = true
		    ) AS tbl_value_detail_level_syllabus_week
		ON
		    tbl_detail_level_syllabus_week.level_id = tbl_value_detail_level_syllabus_week.level_id 
		    AND tbl_detail_level_syllabus_week.type_material_id = tbl_value_detail_level_syllabus_week.type_material_id
		ORDER BY
		    tbl_detail_level_syllabus_week.name_level ASC,
		    tbl_detail_level_syllabus_week.type_material_id ASC;

	END;
$$;


ALTER FUNCTION odiseo.get_detail_level_syllabus_week_parent(p_university_id integer, p_cycle_id integer, p_week_id integer, p_course_id integer, p_headquarter_id jsonb) OWNER TO postgres;

--
-- Name: get_detail_question_digitalized_v2(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.get_detail_question_digitalized_v2(p_question_id integer) RETURNS TABLE(question_id bigint, diagram_fields jsonb, field_images jsonb)
    LANGUAGE plpgsql
    AS $$
                                    BEGIN
                                        RETURN QUERY
                                            WITH active_employee_didi_question  AS (
                                                SELECT
                                                    edq.id AS id,
                                                    edq.question_id AS question_id,
                                                    q.course_id,
                                                    pq.type_text_id category_id
                                                FROM employee_didi_question edq
                                                JOIN question q ON q.id = edq.question_id
                                                LEFT JOIN parent_question pq ON pq.id = q.parent_id 
                                                WHERE 1 = 1
                                                AND edq.question_id = p_question_id
                                                AND edq.fl_status IS TRUE
                                            ), didi_question_diagram_fields AS (
                                                SELECT
                                                    COALESCE(
                                                        JSONB_AGG(
                                                            JSONB_BUILD_OBJECT(
                                                                'id', edqf.id,
                                                                'value', edqf.value,
                                                                'created_at', edqf.created_at,
                                                                'field', fd.name,
                                                                'position', sdc.position,
                                                                'fl_optional', sdc.fl_optional,
                                                                'setting_diagrammed_course_id', sdc.id
                                                            ) ORDER BY sdc.position
                                                        ), '[]'::JSONB
                                                    ) AS diagram_fields
                                                FROM setting_diagrammed_courses sdc
                                                CROSS JOIN active_employee_didi_question aceq
                                                JOIN field_diagrammed fd ON sdc.field_diagram_id = fd.id
                                                LEFT JOIN employee_didi_question_field edqf
                                                    ON sdc.id = edqf.setting_diagrammed_course_id
                                                    AND edqf.employee_didi_question_id = aceq.id
                                                    AND edqf.fl_status IS TRUE
                                                WHERE
                                                    CASE 
                                                        WHEN aceq.category_id IS NULL THEN sdc.course_id = aceq.course_id AND sdc.category_text_id IS NULL
                                                        ELSE sdc.category_text_id = aceq.category_id AND sdc.course_id = aceq.course_id
                                                    END
                                                    AND fd.name IS NOT NULL
                                                    AND (sdc.fl_status = TRUE OR edqf.id IS NOT NULL)
                                                    AND sdc.fl_status = TRUE
                                            ), didi_question_field_images AS (
                                                SELECT
                                                    COALESCE(
                                                        JSONB_AGG(
                                                            JSONB_BUILD_OBJECT(
                                                                'id', edqfi.id,
                                                                'code', edqfi.code,
                                                                'image', edqfi.image
                                                            )
                                                        ), '[]'::JSONB
                                                    ) AS field_images
                                                FROM employee_didi_question_field_image edqfi
                                                JOIN active_employee_didi_question aceq
                                                ON aceq.id = edqfi.employee_didi_question_id
                                                AND edqfi.fl_status IS TRUE
                                                WHERE 1 = 1
                                                AND edqfi.id IS NOT NULL
                                            ) SELECT
                                                aedq.question_id,
                                                dqdf.diagram_fields,
                                                dfi.field_images
                                            FROM active_employee_didi_question aedq
                                            LEFT JOIN didi_question_diagram_fields dqdf ON 1 = 1
                                            LEFT JOIN didi_question_field_images dfi ON 1 = 1;
                                        END;
                                    $$;


ALTER FUNCTION odiseo.get_detail_question_digitalized_v2(p_question_id integer) OWNER TO postgres;

--
-- Name: get_detail_syllabus_subtopic(integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.get_detail_syllabus_subtopic(p_syllabus_id integer, p_company_id integer) RETURNS TABLE(subtopics_observations jsonb, topics_observations jsonb)
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_subtopic RECORD;
            v_topic RECORD;
            subtopics_array jsonb := '[]'; -- Array para subtopics
            topics_array jsonb := '[]';    -- Array para topics
        BEGIN
            -- Subtopics Observations
            FOR v_subtopic IN
                SELECT
                    DISTINCT
                    s.id AS syllabus_id,
                    s2.id AS subtopic_id,
                    s2.name AS subtopic_name,
                    t2.name AS old_topic_name,
                    t.id AS topic_id,
                    t.name AS new_topic_name,
                    CASE
                        WHEN sds.is_topic_modified THEN 'Modified'
                        WHEN sds.is_subtopic_deleted THEN 'Deleted'
                        ELSE 'No Change'
                    END AS action
                FROM syllabus s
                LEFT JOIN syllabus_topic st
                    ON st.syllabus_id = s.id
                    AND st.fl_status = TRUE
                    AND st.deleted_at IS NULL
                LEFT JOIN syllabus_topic_week stw
                    ON stw.syllabus_topic_id = st.id
                    AND stw.fl_status = TRUE
                    AND stw.deleted_at IS NULL
                LEFT JOIN syllabus_detail_subtopic sds
                    ON sds.syllabus_topic_week_id = stw.id
                    AND sds.fl_status = TRUE
                    AND sds.deleted_at IS NULL
                LEFT JOIN subtopic s2
                    ON s2.id = sds.subtopic_id
                LEFT JOIN topic t
                    ON s2.topic_id = t.id
                LEFT JOIN subtopic_history sh
                    ON sh.subtopic_id = s2.id
                LEFT JOIN topic t2
                    ON sh.topic_id = t2.id
                WHERE s.id = p_syllabus_id
                AND s.company_id = p_company_id
                AND (sds.is_topic_modified = TRUE OR sds.is_subtopic_deleted = TRUE)
            LOOP
                -- Agregar cada subtopic con observaciones al array
                subtopics_array := subtopics_array || jsonb_build_object(
                    'syllabus_id', v_subtopic.syllabus_id,
                    'subtopic_id', v_subtopic.subtopic_id,
                    'subtopic_name', v_subtopic.subtopic_name,
                    'old_topic_name', v_subtopic.old_topic_name,
                    'new_topic_name', v_subtopic.new_topic_name,
                    'new_topic_id', v_subtopic.topic_id,
                    'action', v_subtopic.action
                );
            END LOOP;

            -- Topics Observations
            FOR v_topic IN
                SELECT
                    st.syllabus_id,
                    st.topic_id AS topic_id,
                    t.name AS topic_name,
                    'Deleted' AS action
                FROM syllabus_topic st
                LEFT JOIN topic t
                ON st.topic_id = t.id
                WHERE st.syllabus_id = p_syllabus_id
                AND st.company_id = p_company_id
                AND st.is_topic_deleted = TRUE
                AND st.deleted_at IS NULL
            LOOP
                -- Agregar cada topic con observaciones al array
                topics_array := topics_array || jsonb_build_object(
                    'syllabus_id', v_topic.syllabus_id,
                    'topic_id', v_topic.topic_id,
                    'topic_name', v_topic.topic_name,
                    'action', v_topic.action
                );
            END LOOP;

            -- Devolver los resultados
            RETURN QUERY SELECT subtopics_array, topics_array;
        END;
        $$;


ALTER FUNCTION odiseo.get_detail_syllabus_subtopic(p_syllabus_id integer, p_company_id integer) OWNER TO postgres;

--
-- Name: get_didis_for_assignment(integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.get_didis_for_assignment(p_week integer, p_year integer, p_course_id integer) RETURNS TABLE(id bigint, assign_counts jsonb, name text)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        SELECT
            e.id,
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'course_id', sub.course_id,
                        'question_count', sub.question_count
                    )
                )
                FROM (
                    SELECT
                        q.course_id,
                        COUNT(CASE WHEN q.status = 'DASI' THEN 1 END) AS question_count
                    FROM employee_didi_question dq
                    JOIN question q ON q.id = dq.question_id
                    WHERE dq.employee_id = e.id
                    GROUP BY q.course_id
                ) sub
            ) AS assign_counts,
            CONCAT(split_part(e.first_name, ' ', 1), ' ', upper(left(e.first_surname, 1)), '. ', e.second_surname)  as name
        FROM employees e
        JOIN employee_course ec ON e.id = ec.teacher_id
        JOIN users u ON e.user_id = u.id
            AND u.fl_suspended = false
            AND u.fl_status = true
        WHERE ec.course_id = p_course_id
            AND e.fl_status = true
            AND ec.fl_status = true
            AND e.charge_id = 3
            AND e.gpt = false;
    END;
    $$;


ALTER FUNCTION odiseo.get_didis_for_assignment(p_week integer, p_year integer, p_course_id integer) OWNER TO postgres;

--
-- Name: get_employee_data(uuid); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.get_employee_data(p_uuid uuid) RETURNS TABLE(id bigint, uuid uuid, code character varying, user_id bigint, first_name character varying, first_surname character varying, second_surname character varying, type_document_id bigint, document character varying, work_email odiseo.email_citext, personal_email odiseo.email_citext, phone character varying, limit_assigned_questions smallint, limit_assigned_questions_initial smallint, goal integer, level_id bigint, level_name character varying, fl_unlimit_questions boolean, rol_id bigint, charge_id bigint, lot smallint, employee_course jsonb, employee_universities jsonb)
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                        RETURN QUERY
                        SELECT 
                            e.id, 
                            e.uuid,
                            e.code,
                            e.user_id,
                            e.first_name, 
                            e.first_surname, 
                            e.second_surname,
                            e.type_document_id,
                            e.document, 
                            u.email  as work_email,
                            e.email as personal_email, 
                            e.phone, 
                            e.limit_assigned_questions,
                            e.limit_assigned_questions_initial,
                            e.goal,
                            lr.id as level_id,
                            lr.level_name as level_name,
                            e.fl_unlimit_questions,
                            ur.rol_id  as rol_id,
                            e.charge_id,
                            e.lot,
                            COALESCE(
                                (SELECT jsonb_agg(jsonb_build_object(
                                    'id', ec.course_id,
                                    'name', c.name,
                                    'created_at', ec.created_at
                                ))
                                FROM employee_course ec
                                JOIN course c ON ec.course_id = c.id
                                WHERE ec.teacher_id = e.id AND ec.fl_status = true),
                                '[]'::jsonb
                            ) as employee_course,
                            COALESCE(
                                (SELECT jsonb_agg(jsonb_build_object(
                                    'id', eu.university_id,
                                    'name', ou.name,
                                    'created_at', eu.created_at
                                ))
                                FROM employee_university eu
                                JOIN origin_university ou ON ou.id = eu.university_id
                                WHERE eu.employee_id = e.id AND eu.fl_status = true),
                                '[]'::jsonb
                            ) as employee_universities
                        FROM 
                            employees e 
                        LEFT JOIN 
                            users u ON e.user_id = u.id
                        LEFT JOIN 
                            users_roles ur ON ur.user_id = u.id
                        LEFT JOIN
                            level_rates lr ON lr.id = e.level_id
                        WHERE 
                            e.uuid = p_uuid
                        GROUP BY 
                            e.id, 
                            e.uuid, 
                            e.code,
                            e.user_id,
                            e.first_name, 
                            e.first_surname, 
                            e.second_surname,
                            e.type_document_id, 
                            e.document, 
                            u.email,
                            e.email, 
                            e.phone, 
                            e.limit_assigned_questions,
                            e.limit_assigned_questions_initial,
                            lr.level_name,
                            lr.id,
                            e.goal,
                            e.fl_unlimit_questions,
                            ur.id,
                            e.charge_id,
                            e.lot;
                    END;
                    $$;


ALTER FUNCTION odiseo.get_employee_data(p_uuid uuid) OWNER TO postgres;

--
-- Name: get_employee_detail(integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.get_employee_detail(p_user_id integer) RETURNS TABLE(id bigint, user_id bigint, user_name character varying, first_name character varying, first_surname character varying, second_surname character varying, type_document_id bigint, document character varying, email odiseo.email_citext, phone character varying, fl_status boolean, image character varying)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY 
                SELECT e.id, 
                u.id as user_id,
                u.user as  user_name,
                e.first_name, 
                e.first_surname, 
                e.second_surname, e.type_document_id, e."document", e.email, e.phone, e.fl_status,u.image 
                FROM employees e
                left join users u 
                on e.user_id = u.id 
                WHERE e.user_id = p_user_id;
            END;
            $$;


