--
-- Name: get_limit_question_by_didi(integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.get_limit_question_by_didi(p_week integer, p_year integer, p_didi_id integer) RETURNS TABLE(id bigint, assign_counts jsonb, name text, limit_general integer, start_week date, end_week date, total_courses bigint, courses_assigned jsonb)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                SELECT e.id,
                (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'course_id', sub.course_id,
                            'total_dasi', sub.total_dasi,
                            'total_digi_by_week', sub.total_digi_by_week,
                            'course_name', sub.course_name,
                            'limit_question',  (SELECT as2.limit_assigned_questions_didi FROM odiseo.advanced_settings as2 WHERE as2.fl_status = true LIMIT 1)
                        )
                    )
                    FROM (
                        SELECT
                            q.course_id,
                            c.name as course_name,
                            COUNT(CASE
                                WHEN q.status = 'DASI'
                                THEN 1
                            END) AS total_dasi,
                            COUNT(CASE
                                WHEN EXTRACT(WEEK FROM qs.created_at) = p_week AND EXTRACT(YEAR FROM qs.created_at) = p_year
                                AND (q.status = 'DIGI' OR qs.status = 'DIGI')
                                THEN 1
                            END) AS total_digi_by_week
                        FROM
                            odiseo.employee_didi_question dq
                        JOIN
                            odiseo.question q ON q.id = dq.question_id
                       	LEFT JOIN
				        (
				            SELECT DISTINCT ON (qs.question_id) qs.question_id, qs.status, qs.created_at
				            FROM odiseo.question_status qs
				            WHERE qs.status = 'DIGI'
				            ORDER BY qs.question_id, qs.created_at DESC
				        ) AS qs ON qs.question_id = q.id
                        JOIN
                            odiseo.course c ON c.id = q.course_id
                        WHERE
                            dq.employee_id = e.id
							and dq.fl_status = true
                        GROUP BY
                            q.course_id,
                            c.name
                    ) sub
                ) AS assign_counts,
                CONCAT(SPLIT_PART(e.first_name, ' ', 1), ' ', UPPER(LEFT(e.first_surname, 1)), '. ', e.second_surname)  as name,
                (SELECT as2.limit_assigned_questions_didi FROM odiseo.advanced_settings as2 WHERE as2.fl_status = true LIMIT 1) limit_general,
                DATE_TRUNC('week', current_date)::DATE AS start_week,
                (DATE_TRUNC('week', current_date) + INTERVAL '6 days')::DATE AS end_week,
                COUNT(ec.*) total_courses,
				JSONB_AGG(
					JSONB_BUILD_OBJECT(
						'course_id', ec.course_id,
						'course_name', c.name
					)
				) courses_assigned
                FROM
                    odiseo.employees e
                JOIN
                    odiseo.employee_course ec ON e.id = ec.teacher_id
				JOIN 
					odiseo.course c ON c.id = ec.course_id
                WHERE
                e.fl_status = true
                    AND ec.fl_status = true
                    AND e.charge_id = 3
                    AND e.gpt = false
                AND e.id = p_didi_id
                GROUP BY e.id;
            END;
        $$;


ALTER FUNCTION odiseo.get_limit_question_by_didi(p_week integer, p_year integer, p_didi_id integer) OWNER TO postgres;

--
-- Name: get_material_column_configurations(integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.get_material_column_configurations(p_perpage integer, p_npage integer, f_course_id integer) RETURNS TABLE(course_id smallint, name_course character varying, topics jsonb, total_count bigint)
    LANGUAGE plpgsql
    AS $$
            DECLARE
                offset_val INTEGER;
            BEGIN
                -- Calcular el offset
                offset_val := p_perpage * (p_npage - 1);

                RETURN QUERY
                WITH filtered_configurations AS (
                    SELECT 
                        c.id AS course_id,
                        CONCAT(c.code, ' - ' , c.name)::VARCHAR AS name_course,
                        jsonb_agg(
                            jsonb_build_object(
                                'topic_id', t.id,
                                'material_id', mcc.id,  -- Cambiado de 'id' a 'material_id'
                                'topic_name', t.name,
                                'column', COALESCE(mcc.column_count, 2)
                            )
                        ) AS topics
                    FROM 
                        odiseo.course c
                    INNER JOIN 
                        odiseo.topic t 
                    ON 
                        t.course_id = c.id
                    LEFT JOIN 
                        odiseo.material_column_configurations mcc 
                    ON 
                        mcc.topic_id = t.id
                    WHERE
                        c.fl_status = true
                        AND (f_course_id IS NULL OR c.id = f_course_id)
                    GROUP BY 
                        c.id, c.name
                    ORDER BY c.code ASC, unaccent(c.name) ASC
                ),
                counted_questions AS (
                    SELECT *, count(*) OVER () AS total_count
                    FROM filtered_configurations
                )
                SELECT *
                FROM counted_questions
                LIMIT p_perpage
                OFFSET offset_val;
            END;
            $$;


ALTER FUNCTION odiseo.get_material_column_configurations(p_perpage integer, p_npage integer, f_course_id integer) OWNER TO postgres;

--
-- Name: get_material_configuration_details(integer, integer, integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.get_material_configuration_details(p_id integer, p_company_id integer, p_type_material_template_id integer, p_type_template_id integer, p_area_id integer) RETURNS TABLE(id bigint, name character varying, value text)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            SELECT
                mcd.id,
                mcd.name,
                COALESCE(
                    -- Verificar si p_type_material_template_id no es NULL
                    CASE
                        WHEN p_type_material_template_id IS NOT NULL THEN
                            (
                                SELECT mcdv1.value
                                FROM material_configuration_detail_value mcdv1
                                JOIN template_type_material_configurations ttmc1
                                    ON ttmc1.id = mcdv1.template_type_material_configuration_id
                                WHERE
                                    ttmc1.company_id = p_company_id
                                    AND ttmc1.type_material_template_id = p_type_material_template_id
                                    AND (p_type_template_id IS NULL OR ttmc1.type_template_id = p_type_template_id)
                                    AND mcdv1.material_configuration_detail_id = mcd.id
                                    AND mcdv1.fl_status = TRUE
                                    AND ttmc1.fl_status = TRUE
                                    AND (p_area_id IS NULL OR ttmc1.exam_area_id = p_area_id)
                                ORDER BY mcdv1.updated_at DESC -- Toma el registro más reciente
                                LIMIT 1
                            )
                    END,
                    -- Valor genérico (sin configuración específica)
                    (
                        SELECT mcdv2.value
                        FROM material_configuration_detail_value mcdv2
                        WHERE
                            mcdv2.material_configuration_detail_id = mcd.id
                            AND mcdv2.template_type_material_configuration_id IS NULL
                            AND mcdv2.fl_status = TRUE
                        ORDER BY mcdv2.updated_at DESC -- Toma el registro más reciente
                        LIMIT 1
                    )
                ) AS value
            FROM
                material_configurations mc
            INNER JOIN
                material_configuration_details mcd
                ON mcd.material_configuration_id = mc.id
            WHERE
                mc.id = p_id
                AND mc.fl_status = TRUE
                AND mcd.fl_status = TRUE;
        END;
        $$;


ALTER FUNCTION odiseo.get_material_configuration_details(p_id integer, p_company_id integer, p_type_material_template_id integer, p_type_template_id integer, p_area_id integer) OWNER TO postgres;

--
-- Name: get_question_alternatives_and_file_solution(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.get_question_alternatives_and_file_solution(p_question_id bigint) RETURNS TABLE(question_id bigint, question_description text, number character varying, code_course character varying, name_course character varying, topic character varying, subtopics jsonb, type_question character varying, ter numeric, level character varying, answer_id bigint, document_solution text, editor_content text, editor_images jsonb, url_pdf_question_solution character varying, alternatives jsonb, file_solution jsonb, question_image jsonb, config_alternative smallint, column_question smallint, description_observation text, boards_observation text, question_attributes jsonb)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                WITH
                alternatives_data AS (
                    SELECT
                        a.question_id,
                        jsonb_agg(
                            jsonb_build_object(
                            'id_answer', a.id,
                            'alternative_description', a.description
                            ) ORDER BY a.created_at ASC, a.id ASC
                        ) AS alternatives
                    FROM alternative a
                    WHERE a.question_id = p_question_id
                    GROUP BY a.question_id
                ),
                file_solution_data AS (
                    SELECT
                        eq2.question_id,
                        jsonb_agg(jsonb_build_object(
                            'question_id', eq2.question_id,
                            'file_document', eqc.document,
                            'document_solution', eq2.document_solution,
                            'type_archive_id', eqc.type_archive_id
                        )) AS file_solution
                    FROM employee_question eq2
                    INNER JOIN employee_question_document eqc
                        ON eqc.employee_question_id = eq2.id
                    WHERE eq2.question_id = p_question_id
                    GROUP BY eq2.question_id
                ),
                question_image_data AS (
                    SELECT
                        qi.question_id,
                        jsonb_agg(jsonb_build_object(
                            'code', qi.code,
                            'image', qi.image
                        )) AS question_image
                    FROM question_image qi
                    WHERE qi.question_id = p_question_id
                    GROUP BY qi.question_id
                ),
                observed_question AS (
                    SELECT qo.id, qo.question_id, qo.description, qo.boards_observation
                    FROM question_observation qo
                    LEFT JOIN users u  on qo.created_by = u.id
                    LEFT JOIN employees e on e.user_id = u.id
                    WHERE qo.question_id = p_question_id  and qo."type" = 'OBSE' and qo.fl_status = true
                    LIMIT 1
                )
                ,
                question_subtopic_data AS (
                    SELECT
                        q.id AS question_id,
                        jsonb_agg(jsonb_build_object(
                            'id', s.id,
                            'subtopic', s."name"
                        )) AS subtopics
                    FROM question q
                    LEFT JOIN question_subtopic qs
                        ON qs.question_id = q.id
                        AND qs.fl_status = true
                        AND qs.deleted_at IS null
                    LEFT JOIN subtopic s
                        ON qs.subtopic_id = s.id
                    AND q.fl_status = true
                    GROUP BY q.id
                ),
                editor_images_data AS (
                    SELECT
                        eqi.employee_question_id,
                        jsonb_agg(jsonb_build_object(
                            'code', eqi.code,
                            'extension', eqi.extension,
                            'image', eqi.image
                        )) AS editor_images
                    FROM employee_question_image eqi
                    GROUP BY eqi.employee_question_id
                ), course_question AS (
                    SELECT
                        q.course_id,
                        CASE
                            WHEN q.parent_id IS NULL THEN 'P'
                            ELSE 'S'
                        END type
                    FROM question q
                    WHERE q.id = p_question_id
                ), attributes_course AS (
                    SELECT
                        qatc.course_id,
                        qat.id AS question_attribute_type_id,
                        qat.name,
                        qatv.label,
                        qatv.description,
                        qatv.value
                    FROM question_attributes_type_course qatc
                    JOIN course_question cq ON cq.course_id = qatc.course_id
                    JOIN question_attributes_type qat ON qatc.question_attributes_type_id = qat.id
                        AND qat.deleted_at IS NULL
                    LEFT JOIN question_attributes qa ON qatc.id = qa.question_attributes_type_id
                        AND qa.deleted_at IS NULL
                        AND qa.question_id = p_question_id
                    LEFT JOIN question_attributes_types_values qatv ON qat.id = qatv.question_attributes_type_id
                        AND qatv.deleted_at IS NULL
                        AND qatv.value = qa.value
                    WHERE qatc.types_questions ILIKE '%' || cq.type || '%'
                        AND qatc.deleted_at IS NULL
                )
                SELECT
                    q.id AS question_id,
                    q.description AS question_description,
                    q.number,
                    c.code AS code_course,
                    c.name AS name_course,
                    t."name" AS topic,
                    qsd.subtopics AS subtopics,
                    q.type AS type_question,
                    q.ter AS ter,
                    l.description AS level,
                    q.answer_id,
                    eq.document_solution,
                    eq.editor_content::text,
                    eid.editor_images AS editor_images,
                    eq.url_pdf_question_solution,
                    alt.alternatives,
                    fs.file_solution,
                    qi.question_image,
                    ca."columns" AS config_alternative,
                    q."columns" AS column_question,
                    oq.description description_observation,
                    oq.boards_observation,
                    COALESCE(
                        JSONB_AGG(
                            JSONB_BUILD_OBJECT (
                                'question_attribute_type_id', ac.question_attribute_type_id,
                                'name', ac.name,
                                'label', ac.label,
                                'description', ac.description,
                                'value', ac.value
                            ) ORDER BY ac.question_attribute_type_id
                        ) FILTER (WHERE ac.question_attribute_type_id IS NOT NULL), '[]'::jsonb
                    ) AS question_attributes
                FROM employee_question eq
                LEFT JOIN editor_images_data eid
                    ON eid.employee_question_id = eq.id
                INNER JOIN question q
                    ON eq.question_id = q.id
                LEFT JOIN topic t
                    ON q.topic_id = t.id
                INNER JOIN course c
                    ON q.course_id = c.id
                LEFT JOIN level l
                    ON q.level_id = l.id
                LEFT JOIN configuration_alternative ca
                    ON q.config_alternative_id = ca.id
                LEFT JOIN alternatives_data alt
                    ON alt.question_id = q.id
                LEFT JOIN file_solution_data fs
                    ON fs.question_id = q.id
                LEFT JOIN question_image_data qi
                    ON qi.question_id = q.id
                LEFT JOIN question_subtopic_data qsd
                    ON qsd.question_id = q.id
                LEFT JOIN observed_question oq
                    ON oq.question_id = q.id
                LEFT JOIN attributes_course ac
                    ON ac.course_id = q.course_id
                WHERE eq.question_id = p_question_id
                AND eq.fl_status = TRUE
                GROUP BY q.id,
                    c.code, c.name,
                    t."name",
                    eq.document_solution, eq.editor_content,
                    eid.editor_images,
                    eq.url_pdf_question_solution,
                    ca."columns", alt.alternatives, fs.file_solution, qi.question_image, qsd.subtopics, l.description,
                    oq.description, oq.boards_observation;
            END;
            $$;


ALTER FUNCTION odiseo.get_question_alternatives_and_file_solution(p_question_id bigint) OWNER TO postgres;

--
-- Name: get_questions_by_teacher_pdf(integer[]); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.get_questions_by_teacher_pdf(question_ids integer[]) RETURNS TABLE(question_id bigint, course_id smallint, curso character varying, topic_id smallint, tema character varying, answer_id bigint, question_description text, alternatives jsonb)
    LANGUAGE plpgsql
    AS $$
        BEGIN
        RETURN QUERY
        SELECT
            q.id AS question_id,
            q.course_id,
            c."name" AS curso,
            q.topic_id,
            t."name" AS tema,
            q.answer_id,
            q.description AS question_description,
            jsonb_agg(jsonb_build_object('id', a.id, 'description', a.description)) AS alternatives
        FROM
            odiseo.question q
        LEFT JOIN
            odiseo.alternative a ON a.question_id = q.id
        LEFT JOIN
            odiseo.topic t ON q.topic_id = t.id
        LEFT JOIN
            odiseo.course c ON q.course_id = c.id
        WHERE
            q.id = ANY(question_ids)
        GROUP BY
            q.id,
            q.course_id,
            q.answer_id,
            t.name,
            c.name,
            q.topic_id,
            q.description
        ORDER BY
            t."name" ASC, 
            c."name" ASC;
        END;
        $$;


ALTER FUNCTION odiseo.get_questions_by_teacher_pdf(question_ids integer[]) OWNER TO postgres;

--
-- Name: get_shared_status(bigint, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.get_shared_status(p_question_id bigint, p_subtopic_id integer) RETURNS text
    LANGUAGE sql STABLE
    AS $$
    SELECT CASE
        WHEN EXISTS (
            SELECT 1 FROM question_shares qs
            WHERE qs.subtopic_id = p_subtopic_id
              AND qs.deleted_at IS NULL
        ) THEN 'shared'
        WHEN EXISTS (
            SELECT 1 FROM question_shares qs
            WHERE qs.question_id = p_question_id
              AND qs.deleted_at IS NULL
        ) THEN 'main'
        ELSE 'normal'
    END;
$$;


ALTER FUNCTION odiseo.get_shared_status(p_question_id bigint, p_subtopic_id integer) OWNER TO postgres;

--
-- Name: get_syllabus_export(bigint, bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.get_syllabus_export(p_cycle_id bigint, p_company_id bigint, p_course_id bigint DEFAULT NULL::bigint) RETURNS TABLE(syllabus_id bigint, course_name character varying, cycle_description character varying, week smallint, topics jsonb, subtopic_names text, subtopics jsonb)
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RETURN QUERY
        SELECT 
            syll.id AS syllabus_id,
            cour.name AS course_name,
            cycl.description AS cycle_description,
            stw.week AS week,
            jsonb_agg(DISTINCT jsonb_build_object('id', tp.id, 'name', tp.name)) AS topics,
            STRING_AGG(DISTINCT subt.name, ', ') AS subtopic_names,
            JSONB_AGG(
                JSONB_BUILD_OBJECT(
                    'id', subt.id,
                    'code', subt.code,
                    'name', subt.name,
                    'name_no_prefix', subt.name,
                    'amount', sds.questions_amount,
                    'questions_amount', COALESCE(sttm.questions_amount, '[]'::jsonb)
                ) ORDER BY subt.name
            ) AS subtopics
        FROM
            syllabus syll
        INNER JOIN course cour ON cour.id = syll.course_id
        INNER JOIN origin_university univ ON univ.id = syll.university_id
        INNER JOIN cycle cycl ON cycl.id = syll.cycle_id
        INNER JOIN syllabus_topic st ON st.syllabus_id = syll.id AND st.fl_status = true AND st.is_topic_deleted = false
        INNER JOIN syllabus_topic_week stw ON stw.syllabus_topic_id = st.id AND stw.fl_status = true
        INNER JOIN topic tp ON tp.id = st.topic_id
        INNER JOIN syllabus_detail_subtopic sds ON sds.syllabus_topic_week_id = stw.id AND sds.fl_status = true AND sds.is_subtopic_deleted = false
        INNER JOIN subtopic subt ON subt.id = sds.subtopic_id
        LEFT JOIN (
            SELECT 
                sst.syllabus_detail_subtopic_id,
                JSONB_AGG(
                    JSONB_BUILD_OBJECT(
                        'id', sst.id,
                        'type_material_id', sst.type_material_id,
                        'type_material', tm.description,
                        'amount', sst.questions_amount
                    ) 
                    ORDER BY 
                        CASE
                            WHEN tm.description = 'ECO' THEN 1
                            WHEN tm.description = 'Guía de clases' THEN 2
                            WHEN tm.description = 'Homework' THEN 3
                            ELSE 4
                        END
                ) AS questions_amount
            FROM syllabus_subtopic_type_material sst
            JOIN type_material tm 
              ON tm.id = sst.type_material_id 
             AND sst.company_id = p_company_id
             AND tm.fl_status IS TRUE 
             AND sst.fl_status IS TRUE
            GROUP BY sst.syllabus_detail_subtopic_id
        ) sttm ON sttm.syllabus_detail_subtopic_id = sds.id
        WHERE cycl.id = p_cycle_id
          AND syll.company_id = p_company_id
          AND syll.fl_status = true
          AND (p_course_id IS NULL OR cour.id = p_course_id)
        GROUP BY syll.id, cycl.id, cour.id, stw.week
        ORDER BY cour.id;
    END;
    $$;


ALTER FUNCTION odiseo.get_syllabus_export(p_cycle_id bigint, p_company_id bigint, p_course_id bigint) OWNER TO postgres;

--
-- Name: get_syllabus_export_by_topic(bigint, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.get_syllabus_export_by_topic(p_syllabus_id bigint, p_company_id bigint) RETURNS TABLE(syllabus_id bigint, course_name character varying, cycle_description character varying, week integer, topic_id smallint, week_name character varying, alternative_week_name text, topic_name character varying, subtopics jsonb)
    LANGUAGE plpgsql
    AS $$
     DECLARE v_weeks_amount INTEGER DEFAULT 0;
 BEGIN
     SELECT c.weeks INTO v_weeks_amount
     FROM odiseo.syllabus syll
     JOIN odiseo.cycle c ON c.id = syll.cycle_id
     WHERE syll.id = p_syllabus_id
     AND syll.company_id = p_company_id;
     
     RETURN QUERY
         WITH syllabus_weeks AS (
             SELECT
                 *
             FROM generate_series(1, v_weeks_amount) AS week
         ), syllabus_general_content AS (
             SELECT
                 syll.id,
                 stw.week,
                 syll.course_id AS course_id,
                 st.topic_id AS topic_id,
                 sds.subtopic_id AS subtopic_id,
                 syll.cycle_id AS cycle_id,
                 stw.week AS syllabus_week,
                 sds.id AS syllabus_detail_subtopic_id,
                 sds.questions_amount
             FROM odiseo.syllabus syll
             INNER JOIN odiseo.syllabus_topic st ON st.syllabus_id = syll.id AND st.fl_status IS TRUE AND st.is_topic_deleted IS FALSE
             INNER JOIN odiseo.syllabus_topic_week stw ON stw.syllabus_topic_id = st.id AND stw.fl_status IS TRUE
             INNER JOIN odiseo.syllabus_detail_subtopic sds ON sds.syllabus_topic_week_id = stw.id AND sds.fl_status IS TRUE AND sds.is_subtopic_deleted IS FALSE
             WHERE syll.id = p_syllabus_id
             AND syll.company_id = p_company_id
         ), question_amount_per_material_type AS (
             SELECT
                 sst.syllabus_detail_subtopic_id,
                 JSONB_AGG(
                     JSONB_BUILD_OBJECT(
                         'id', sst.id,
                         'type_material_id', sst.type_material_id,
                         'type_material', tm.description,
                         'amount', sst.questions_amount
                     )
                     ORDER BY 
                         CASE
                             WHEN tm.description = 'ECO' THEN 1
                             WHEN tm.description = 'Guía de clases' THEN 2
                             WHEN tm.description = 'Homework' THEN 3
                             ELSE 4
                         END
                 ) AS questions_amount
             FROM syllabus_general_content sgc
             LEFT JOIN odiseo.syllabus_subtopic_type_material sst ON sst.syllabus_detail_subtopic_id = sgc.syllabus_detail_subtopic_id
             JOIN odiseo.type_material tm ON tm.id = sst.type_material_id 
              AND tm.fl_status IS TRUE 
              AND sst.fl_status IS TRUE
             GROUP BY sst.syllabus_detail_subtopic_id
         ), syllabus_with_topics AS (
             SELECT
                 slc.id,
                 slc.course_id,
                 slc.topic_id,
                 slc.cycle_id,
                 slc.week,
                 JSONB_AGG(
                     JSONB_BUILD_OBJECT(
                         'id', st.id,
                         'code', st.code,
                         'name', st.name,
                         'name_no_prefix', st.name,
                         'amount', slc.questions_amount,
                         'questions_amount', COALESCE(sqpm.questions_amount, '[]'::JSONB)
                     )
                     ORDER BY st.name
                 ) subtopics_amount
             FROM syllabus_general_content slc
             JOIN odiseo.subtopic st ON slc.subtopic_id = st.id
             LEFT JOIN question_amount_per_material_type sqpm ON sqpm.syllabus_detail_subtopic_id = slc.syllabus_detail_subtopic_id
             GROUP BY
                 slc.id,
                 slc.course_id,
                 slc.topic_id,
                 slc.cycle_id,
                 slc.week
         ), syllabus AS (
             SELECT
                 swt.id,
                 c.name AS course_name,
                 cy.description AS cycle_name,
                 swt.week AS week_id,
                 swt.topic_id,
                 stt.title AS week_name,
                 t.name AS topic_name,
                 swt.subtopics_amount
             FROM syllabus_with_topics swt
             JOIN odiseo.course c ON c.id = swt.course_id
             JOIN odiseo.topic t ON t.id = swt.topic_id
             JOIN odiseo.cycle cy ON cy.id = swt.cycle_id
             LEFT JOIN odiseo.syllabus_week_titles stt ON stt.syllabus_id = swt.id AND swt.week = stt.week AND stt.fl_status IS TRUE
         ), syllabus_with_filled_empty_weeks AS (
             SELECT
                 sss.id,
                 (SELECT DISTINCT s1.course_name FROM syllabus s1 LIMIT 1) AS course_name,
                 (SELECT DISTINCT s2.cycle_name FROM syllabus s2 LIMIT 1) AS cycle_name,
                 COALESCE(sss.week_id, sw.week) AS week_id,
                 sss.topic_id,
                 COALESCE(sss.week_name,'') AS week_name,
                 COALESCE(STRING_AGG(sss.topic_name, ', ') OVER (PARTITION BY week_id), '') AS alternative_week_name,
                 COALESCE(sss.topic_name, '') AS topic_name,
                 COALESCE(sss.subtopics_amount, '[]'::JSONB) AS subtopics_amount
             FROM syllabus_weeks sw
             LEFT JOIN syllabus sss ON sss.week_id = sw.week
         ) SELECT
             *
         FROM syllabus_with_filled_empty_weeks
         ORDER BY week_id ASC;
     END;
 $$;


ALTER FUNCTION odiseo.get_syllabus_export_by_topic(p_syllabus_id bigint, p_company_id bigint) OWNER TO postgres;

--
-- Name: get_syllabus_text(integer, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.get_syllabus_text(p_syllabus_id integer, p_week integer, p_company_id integer) RETURNS TABLE(material_id smallint, material character varying, categories jsonb)
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    RETURN QUERY
                    
                    WITH subtopic_details AS (
                        SELECT
                            stc.syllabus_text_id ,
                            jsonb_agg(
                                jsonb_build_object(
                                    'subtopic_id', stc.subtopic_id,
                                    'subtopic', CONCAT(s.code, ' - ', s.name),
                                    'quantity', stc.quantity,
                                    'topic_id', t.id,
                                    'topic_name', CONCAT(t.code, ' - ', t.name)
                                ) ORDER BY s.name
                            ) AS subtopics
                        FROM syllabus_text_content stc
                        JOIN subtopic s ON s.id = stc.subtopic_id
                        JOIN topic t ON t.id = s.topic_id
                        WHERE stc.fl_status = true
                            AND stc.company_id = p_company_id
                        GROUP BY stc.syllabus_text_id
                    ),
                    subcategory_details AS (
                        SELECT
                            st.syllabus_text_distribution_id,
                            st.type_text_id,
                            jsonb_agg(
                                jsonb_build_object(
                                    'subcategory_id', st.type_text_subcategory_id,
                                    'subcategory', tts.name,
                                    'position', st.position,
                                    'subtopics', COALESCE(sd.subtopics, '[]'::jsonb),
                                    'style_quantity',std.quantity,
                                    'style_type',std.style_type
                                ) ORDER BY st.position
                            ) AS subcategories
                        FROM syllabus_texts st
                        JOIN type_text_subcategories tts ON tts.id = st.type_text_subcategory_id
                        LEFT JOIN subtopic_details sd ON sd.syllabus_text_id = st.id
                        LEFT JOIN syllabus_text_detail std ON std.syllabus_text_id = st.id 
                        WHERE st.fl_status = true
                            AND st.company_id = p_company_id
                        GROUP BY st.syllabus_text_distribution_id, st.type_text_id
                    ),
                    categories_by_material AS (
                        SELECT
                            std.type_material_id,
                            jsonb_agg(
                                DISTINCT jsonb_build_object(
                                    'category_id', unique_texts.type_text_id,
                                    'category_name', tt.name,
                                    'subcategories', scd.subcategories
                                )
                            ) FILTER (
                                WHERE scd.subcategories IS NOT NULL
                                AND jsonb_array_length(scd.subcategories) > 0
                            ) AS categories
                        FROM syllabus_text_distributions std
                        JOIN (
                            SELECT DISTINCT
                                st.syllabus_text_distribution_id, st.type_text_id
                            FROM syllabus_texts st
                            JOIN syllabus_text_distributions std_filter ON std_filter.id = st.syllabus_text_distribution_id
                                AND std_filter.company_id = p_company_id
                            JOIN syllabus_text_weeks stw_filter ON stw_filter.id = std_filter.syllabus_text_week_id
                                AND stw_filter.company_id = p_company_id
                            WHERE stw_filter.syllabus_id = p_syllabus_id
                                AND stw_filter.week = p_week
                                AND st.company_id = p_company_id
                                AND stw_filter.fl_status = true
                        ) AS unique_texts ON unique_texts.syllabus_text_distribution_id = std.id
                        JOIN type_text tt ON tt.id = unique_texts.type_text_id
                        LEFT JOIN subcategory_details scd ON scd.syllabus_text_distribution_id = unique_texts.syllabus_text_distribution_id
                            AND scd.type_text_id = unique_texts.type_text_id
                        WHERE std.company_id = p_company_id
                        GROUP BY std.type_material_id
                    )
                    SELECT
                        tm.id AS material_id,
                        tm.description AS material,
                        COALESCE(cbm.categories, '[]'::jsonb) AS categories
                    FROM syllabus s
                    JOIN syllabus_text_weeks stw ON stw.syllabus_id = s.id
                        AND stw.company_id = p_company_id
                    JOIN syllabus_text_distributions std ON std.syllabus_text_week_id = stw.id
                        AND std.company_id = p_company_id
                    JOIN type_material tm ON tm.id = std.type_material_id
                    LEFT JOIN categories_by_material cbm ON cbm.type_material_id = tm.id
                    WHERE s.id = p_syllabus_id
                        AND stw.week = p_week
                        AND s.company_id = p_company_id
                    GROUP BY tm.id, tm.description, cbm.categories;

                END;
                $$;


ALTER FUNCTION odiseo.get_syllabus_text(p_syllabus_id integer, p_week integer, p_company_id integer) OWNER TO postgres;

--
-- Name: get_syllabus_text_weekly(integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.get_syllabus_text_weekly(p_syllabus_id integer, p_company_id integer) RETURNS TABLE(syllabus_text_payload jsonb)
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RETURN QUERY
                WITH
                    subtopics_agg AS (
                        SELECT
                            stc.syllabus_text_id,
                            jsonb_agg(jsonb_build_object('subtopic_id', stc.subtopic_id, 'quantity', stc.quantity) ORDER BY stc.id) AS subtopics
                        FROM syllabus_text_content stc
                        WHERE stc.fl_status = true
                        AND stc.company_id = p_company_id
                        GROUP BY stc.syllabus_text_id
                    ),
                    texts_agg AS (
                        SELECT
                            st.syllabus_text_distribution_id,
                            jsonb_agg(jsonb_build_object(
                            'category_id', st.type_text_id, 
                            'subcategory_id', st.type_text_subcategory_id, 
                            'position', st.position, 
                            'subtopics', COALESCE(sa.subtopics, '[]'::jsonb),
                            'style_type', std.style_type,
                            'style_quantity', std.quantity
                        ) ORDER BY st.position) AS texts
                        FROM syllabus_texts st
                        LEFT JOIN subtopics_agg sa ON sa.syllabus_text_id = st.id
                        LEFT JOIN syllabus_text_detail std ON std.syllabus_text_id = st.id
                        WHERE st.fl_status = true
                        AND st.company_id = p_company_id
                        GROUP BY st.syllabus_text_distribution_id
                    ),
                    distributions_agg AS (
                        SELECT
                            std.syllabus_text_week_id,
                            jsonb_agg(
                                jsonb_build_object(
                                    'material_id', std.type_material_id,
                                    'texts', COALESCE(ta.texts, '[]'::jsonb)
                                ) ORDER BY std.id
                            ) AS distributions
                        FROM syllabus_text_distributions std
                        LEFT JOIN texts_agg ta ON ta.syllabus_text_distribution_id = std.id
                        WHERE std.fl_status = true
                        AND std.company_id = p_company_id
                        GROUP BY std.syllabus_text_week_id
                    )
                SELECT
                    COALESCE(jsonb_agg(
                        jsonb_build_object(
                            'week', stw.week,
                            'distributions', COALESCE(da.distributions, '[]'::jsonb)
                        )
                    ), '[]'::jsonb) AS syllabus_text_payload
                FROM
                    syllabus_text_weeks stw
                    LEFT JOIN distributions_agg da ON da.syllabus_text_week_id = stw.id
                WHERE
                    stw.syllabus_id = p_syllabus_id AND stw.fl_status = true
                AND
                    stw.company_id = p_company_id;
            END;
        $$;


ALTER FUNCTION odiseo.get_syllabus_text_weekly(p_syllabus_id integer, p_company_id integer) OWNER TO postgres;

--
-- Name: type_material_template; Type: TABLE; Schema: odiseo; Owner: postgres
--

CREATE TABLE odiseo.type_material_template (
    id bigint NOT NULL,
    name character varying(255) NOT NULL,
    fl_status boolean DEFAULT true NOT NULL,
    created_by bigint,
    updated_by bigint,
    deleted_by bigint,
    created_at timestamp(0) without time zone,
    updated_at timestamp(0) without time zone,
    deleted_at timestamp(0) without time zone,
    fl_exam boolean DEFAULT false NOT NULL,
    type_exam_id bigint,
    fl_use_syllabus_exam boolean DEFAULT true NOT NULL,
    fl_revision boolean DEFAULT false NOT NULL,
    has_config_column boolean DEFAULT false NOT NULL
);


ALTER TABLE odiseo.type_material_template OWNER TO postgres;

--
-- Name: list_type_material_template_children(bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.list_type_material_template_children(p_type_material_template_id bigint) RETURNS SETOF odiseo.type_material_template
    LANGUAGE plpgsql
    AS $$
        DECLARE
        BEGIN
            RETURN QUERY SELECT distinct tmb_child.*
            FROM odiseo.type_material_bound as tmb
            LEFT JOIN odiseo.type_material_template as tmb_child
            ON tmb.type_material_template_extra_id = tmb_child.id
            AND tmb_child.fl_status AND tmb_child.deleted_at IS NULL
            WHERE tmb.type_material_template_id = p_type_material_template_id
            AND tmb.fl_status
            AND tmb.deleted_at IS NULL;
        END;
        $$;


ALTER FUNCTION odiseo.list_type_material_template_children(p_type_material_template_id bigint) OWNER TO postgres;

--
-- Name: merge_json_array_except(json, json); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.merge_json_array_except(existing json, incoming json) RETURNS json
    LANGUAGE plpgsql IMMUTABLE
    AS $$
        DECLARE
            existingb  jsonb := coalesce(existing, '[]'::json)::jsonb;
            incomingb  jsonb := coalesce(incoming, '[]'::json)::jsonb;
            elems_new  jsonb;
            mergedb    jsonb;
        BEGIN
            -- 1) Sacamos los elementos nuevos (incomingb − existingb)
            SELECT jsonb_agg(value) 
                INTO elems_new
            FROM (
                SELECT value
                FROM jsonb_array_elements(incomingb)
                EXCEPT
                SELECT value
                FROM jsonb_array_elements(existingb)
            ) sub;

            -- 2) Concatenamos existingb + elems_new (o solo existingb si no hay elems_new)
            IF elems_new IS NULL THEN
                mergedb := existingb;
            ELSE
                mergedb := existingb || elems_new;
            END IF;

            -- 3) Devolvemos como JSON puro
            RETURN mergedb::json;
        END;
        $$;


ALTER FUNCTION odiseo.merge_json_array_except(existing json, incoming json) OWNER TO postgres;

--
-- Name: save_config_material_question(jsonb, integer, bigint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.save_config_material_question(p_topics jsonb, p_column integer, p_user bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
                DECLARE
                    v_topic RECORD;
                    v_material_id INTEGER;
                    v_topic_id INTEGER;
                BEGIN
                    FOR v_topic IN
                        SELECT * FROM jsonb_array_elements(p_topics) AS t(topic)
                    LOOP
                        -- Extraer el ID del material del JSON
                        v_material_id := (v_topic.topic->>'material_id')::INTEGER;
                        v_topic_id := (v_topic.topic->>'topic_id')::INTEGER;

                        -- Comprobar si el ID del material es NULL
                        IF v_material_id IS NULL THEN
                            -- Insertar nuevo registro si material_id es NULL
                            INSERT INTO odiseo.material_column_configurations (
                                material_configuration_id,
                                topic_id,
                                column_count,
                                layout_format,
                                number_format,
                                created_by,
                                created_at
                            )
                            VALUES (
                                7,
                                (v_topic.topic->>'topic_id')::INTEGER,
                                p_column,
                                'one_column',
                                'sequential',
                                p_user,
                                NOW()
                            );
                        ELSE
                            -- Actualizar registro existente si material_id no es NULL
                            UPDATE odiseo.material_column_configurations
                            SET column_count = p_column,
                                updated_at = NOW(),
                                updated_by = p_user
                            WHERE id = v_material_id and topic_id = v_topic_id;
                        END IF;
                    END LOOP;
                END;
                $$;


ALTER FUNCTION odiseo.save_config_material_question(p_topics jsonb, p_column integer, p_user bigint) OWNER TO postgres;

--
-- Name: sp_change_syllabus_template_subtopics(bigint, bigint, bigint); Type: PROCEDURE; Schema: odiseo; Owner: postgres
--

CREATE PROCEDURE odiseo.sp_change_syllabus_template_subtopics(IN p_topic_id bigint, IN p_subtopic_id bigint, IN p_user bigint)
    LANGUAGE plpgsql
    AS $$
                DECLARE
                    v_syllabus_template_topic_ids BIGINT[];
                BEGIN
                    -- Iniciar bloque de excepción para capturar errores
                    BEGIN
                        -- Actualizar todos los subtopics en syllabus_template_topic_subtopic para marcarlos como eliminados
                        UPDATE odiseo.syllabus_template_topic_subtopic
                        SET fl_status = FALSE,
                            deleted_at = NOW(),
                            deleted_by = p_user
                        WHERE subtopic_id = p_subtopic_id;

                        -- Verificar si existen topics en syllabus_template_topic relacionados con el topic dado
                        SELECT ARRAY(
                            SELECT stt.id
                            FROM odiseo.syllabus_template_topic stt
                            JOIN odiseo.syllabus_template st
                            ON stt.syllabus_template_id = st.id
                            WHERE stt.fl_status = TRUE AND stt.deleted_at IS NULL
                            AND stt.topic_id = p_topic_id
                            AND st.fl_status = TRUE AND st.deleted_at IS NULL
                        )
                        INTO v_syllabus_template_topic_ids;

                        -- Si se encontraron topics, insertar los subtopics correspondientes
                        IF v_syllabus_template_topic_ids IS NOT NULL THEN
                            INSERT INTO odiseo.syllabus_template_topic_subtopic (syllabus_template_topic_id, subtopic_id, created_by, created_at)
                            SELECT
                                unnest(v_syllabus_template_topic_ids),
                                p_subtopic_id,
                                p_user,
                                NOW();
                        END IF;

                    EXCEPTION WHEN OTHERS THEN
                        RAISE NOTICE 'Error: %', SQLERRM;
                        RAISE; -- Propagar el error
                    END;
                END;
            $$;


ALTER PROCEDURE odiseo.sp_change_syllabus_template_subtopics(IN p_topic_id bigint, IN p_subtopic_id bigint, IN p_user bigint) OWNER TO postgres;

--
-- Name: sp_insert_didi_ghost_or_teacher_ghost(); Type: PROCEDURE; Schema: odiseo; Owner: postgres
--

CREATE PROCEDURE odiseo.sp_insert_didi_ghost_or_teacher_ghost()
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_question_ids INTEGER[];
                v_question_id INTEGER;
                v_is_question_assigned_to_teacher BOOLEAN;
                v_is_question_assigned_to_didi BOOLEAN;
                v_ghost_teacher_id INTEGER;
                v_ghost_didi_id INTEGER;
                v_user INTEGER;
                v_employee_didi_question_id INTEGER;
                v_last_id_question_status INTEGER;
                v_exist_field_diagrammed BOOLEAN;
                v_user_name TEXT;
            BEGIN
                -- Obtener IDs de Ghost Teacher y DIDI
                SELECT e.id
                INTO v_ghost_teacher_id
                FROM odiseo.employees e
                WHERE e."document" = '33333333' AND e.charge_id = 2;

                SELECT e.id
                INTO v_ghost_didi_id
                FROM odiseo.employees e
                WHERE e."document" = '44444444' AND e.charge_id = 3;

                -- Obtener preguntas no asignadas
                SELECT ARRAY(
                    SELECT q.id
                    FROM odiseo.question q
                    WHERE q.status = 'VERI'
                    AND NOT EXISTS (
                        SELECT 1
                        FROM (
                            SELECT question_id FROM odiseo.employee_question WHERE fl_status = TRUE
                            UNION
                            SELECT question_id FROM odiseo.employee_didi_question WHERE fl_status = TRUE
                        ) sub
                        WHERE sub.question_id = q.id
                    )
                ) INTO v_question_ids;

                -- Iterar sobre las preguntas
                FOREACH v_question_id IN ARRAY v_question_ids
                LOOP
                    -- Obtener último registro de question_status
                    SELECT qs.created_by, qs.id
                    INTO v_user, v_last_id_question_status
                    FROM odiseo.question_status qs
                    WHERE qs.question_id = v_question_id
                    ORDER BY qs.created_at DESC, qs.id DESC
                    LIMIT 1;

                    -- Obtener nombre del usuario
                    SELECT CASE
                            WHEN e.id IS NOT NULL
                            THEN CONCAT(e.first_name, ' ', LEFT(e.first_surname, 1), '. ', e.second_surname)
                            ELSE 'Administrador'
                        END AS user
                    INTO v_user_name
                    FROM odiseo.users u
                    LEFT JOIN odiseo.employees e ON u.id = e.user_id
                    WHERE u.id = v_user;

                -- Eliminar el ultimo registro de ese historial
                    DELETE FROM odiseo.question_status WHERE id = v_last_id_question_status ;

                    -- Verificar asignación a un docente
                    SELECT CASE WHEN COUNT(*) > 0 THEN true ELSE false END
                    INTO v_is_question_assigned_to_teacher
                    FROM odiseo.employee_question eq
                    WHERE eq.question_id = v_question_id AND eq.fl_status = TRUE;

                    IF NOT v_is_question_assigned_to_teacher THEN
                        INSERT INTO odiseo.employee_question (teacher_id, question_id, created_by, created_at)
                        VALUES (v_ghost_teacher_id, v_question_id, v_user, NOW());

                        INSERT INTO odiseo.question_status (question_id, status, fl_active, process, description, created_by, created_at)
                        VALUES (v_question_id, 'ASIG', false, 'ASIGNACIÓN',
                            'La pregunta fue asignada al docente <span class=''text-teacher''>Docente Ghost</span> por el usuario <span class=''text-user''>' || v_user_name || '</span>', 
                            v_user, NOW());
                    END IF;

                    -- Verificar asignación a un DIDI
                    SELECT CASE WHEN COUNT(*) > 0 THEN true ELSE false END
                    INTO v_is_question_assigned_to_didi
                    FROM odiseo.employee_didi_question edq
                    WHERE edq.question_id = v_question_id AND edq.fl_status = TRUE;

                    IF NOT v_is_question_assigned_to_didi THEN
                        INSERT INTO odiseo.employee_didi_question (employee_id, question_id, created_by, created_at)
                        VALUES (v_ghost_didi_id, v_question_id, v_user, NOW())
                        RETURNING id INTO v_employee_didi_question_id;

                        INSERT INTO odiseo.question_status (question_id, status, fl_active, process, description, created_by, created_at)
                        VALUES (v_question_id, 'DASI', false, 'ASIGNADO',
                            'La pregunta fue asignada al DiDi <span class=''text-teacher''>DIDI GHOST</span> por el usuario <span class=''text-user''>' || v_user_name || '</span>', 
                            v_user, NOW());

                        -- Diagramar la pregunta con campos en proceso
                        INSERT INTO odiseo.employee_didi_question_field (
                            employee_didi_question_id, setting_diagrammed_course_id, value, created_by, created_at
                        )
                        SELECT v_employee_didi_question_id, sdc.id, 'En proceso', v_user , NOW()
                        FROM odiseo.setting_diagrammed_courses sdc
                        WHERE sdc.course_id = (
                            SELECT oq.course_id
                            FROM odiseo.question oq
                            WHERE oq.id = v_question_id
                            LIMIT 1
                        )  AND sdc.fl_status = TRUE
                        ORDER BY sdc.position ASC;

                    ELSE
                        SELECT edq.id
                        INTO v_employee_didi_question_id
                        FROM odiseo.employee_didi_question edq
                        WHERE edq.question_id = v_question_id AND edq.fl_status = TRUE;

                        -- Verificar si tiene campos diagramados
                        SELECT CASE WHEN COUNT(*) > 0 THEN  TRUE ELSE FALSE END AS exist_field_diagrammed
                        INTO v_exist_field_diagrammed
                        FROM odiseo.employee_didi_question_field edqf
                        WHERE edqf.employee_didi_question_id = v_employee_didi_question_id;

                        IF NOT v_exist_field_diagrammed THEN
                            -- Diagramar la pregunta con campos en proceso
                            INSERT INTO odiseo.employee_didi_question_field (
                                employee_didi_question_id, setting_diagrammed_course_id, value, created_by, created_at
                            )
                            SELECT v_employee_didi_question_id, sdc.id, 'En proceso', v_user , NOW()
                            FROM odiseo.setting_diagrammed_courses sdc
                            WHERE sdc.course_id = (
                                SELECT oq.course_id
                                FROM odiseo.question oq
                                WHERE oq.id = v_question_id
                                LIMIT 1
                            )  AND sdc.fl_status = TRUE
                            ORDER BY sdc.position ASC;
                        END IF;
                    END IF;

                    -- Registrar estado VERIFICADO
                    INSERT INTO odiseo.question_status (question_id, status, process, description, created_by, created_at)
                    VALUES (v_question_id, 'VERI', 'VERIFICADO',
                        'La pregunta se cambió al estado verificado por el usuario <span class=''text-user''>' || v_user_name || '</span>', 
                        v_user, NOW());
                END LOOP;
            END;
            $$;


ALTER PROCEDURE odiseo.sp_insert_didi_ghost_or_teacher_ghost() OWNER TO postgres;

--
-- Name: subtopic_has_related_questions(smallint); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.subtopic_has_related_questions(p_subtopic_id smallint) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN EXISTS (
                SELECT 1
                FROM odiseo.question q
                INNER JOIN odiseo.question_subtopic qs
                ON q.id = qs.question_id AND qs.fl_status = true
                WHERE
                    qs.subtopic_id = p_subtopic_id
                    AND q.deleted_at IS NULL
                    AND q.fl_status
                    AND qs.deleted_at IS NULL
                    AND qs.fl_status
            );
        END;
        $$;


ALTER FUNCTION odiseo.subtopic_has_related_questions(p_subtopic_id smallint) OWNER TO postgres;

--
-- Name: trg_question_self_text(); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.trg_question_self_text() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
            BEGIN
                NEW.search_text = COALESCE(NEW.code, '') || ' ' || 
                                COALESCE(NEW.number_question, '') || ' ' || 
                                COALESCE(NEW.short_description, '');
                RETURN NEW;
            END;
            $$;


ALTER FUNCTION odiseo.trg_question_self_text() OWNER TO postgres;

--
-- Name: trg_update_parent_from_child(); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.trg_update_parent_from_child() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'odiseo', 'public'
    AS $$
            DECLARE
                v_parent_id BIGINT;
            BEGIN
                IF (TG_OP = 'DELETE') THEN
                    v_parent_id := OLD.parent_id;
                ELSE
                    v_parent_id := NEW.parent_id;
                END IF;

                IF v_parent_id IS NOT NULL THEN
                    PERFORM fn_rebuild_parent_search_text(v_parent_id);
                END IF;

                IF (TG_OP = 'UPDATE' AND OLD.parent_id IS NOT NULL AND OLD.parent_id <> NEW.parent_id) THEN
                    PERFORM fn_rebuild_parent_search_text(OLD.parent_id);
                END IF;
                
                RETURN NULL;
            END;
            $$;


ALTER FUNCTION odiseo.trg_update_parent_from_child() OWNER TO postgres;

--
-- Name: trg_update_parent_from_self(); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.trg_update_parent_from_self() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
            PERFORM fn_rebuild_parent_search_text(NEW.id);
            RETURN NULL;
        END;
        $$;


ALTER FUNCTION odiseo.trg_update_parent_from_self() OWNER TO postgres;

--
-- Name: trg_update_question_status_date(); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.trg_update_question_status_date() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    IF NEW.fl_active = true THEN
                        UPDATE question
                        SET
                            status_changed_at = NEW.created_at,
                            status = NEW.status
                        WHERE
                            id = NEW.question_id;
                    END IF;

                    RETURN NEW;
                END;
                $$;


ALTER FUNCTION odiseo.trg_update_question_status_date() OWNER TO postgres;

