--
-- Name: update_data_employee(uuid, bigint, character varying, character varying, character varying, integer, character varying, character varying, character varying, integer, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.update_data_employee(p_uuid uuid, p_charge_id bigint, p_first_name character varying, p_first_surname character varying, p_second_surname character varying, p_type_document_id integer, p_document character varying, p_email character varying, p_phone character varying, p_updated_by integer, p_data_docente jsonb) RETURNS TABLE(v_id_employee bigint, v_question_ids integer[])
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_id_employee BIGINT;
                v_charge_id BIGINT;
                v_course_id BIGINT;
                v_new_course_ids BIGINT[];
                v_existing_course_ids BIGINT[];
                v_limit_assigned_questions INTEGER;

                v_courses_delete BIGINT[];
                 v_question_ids INT[];
            BEGIN

               v_limit_assigned_questions := (p_data_docente->>'goal')::smallint + ((p_data_docente->>'goal')::smallint)/2;

                -- Obtener ID del empleado y ID del cargo
                SELECT id, charge_id
                INTO v_id_employee, v_charge_id
                FROM odiseo.employees e
                WHERE e.uuid = p_uuid;

                UPDATE odiseo.employees
                SET charge_id = p_charge_id,
                    first_name = p_first_name,
                    first_surname = p_first_surname,
                    second_surname = p_second_surname,
                    type_document_id = p_type_document_id,
                    "document" = p_document,
                    email = p_email,
                    phone = p_phone,
                    updated_by = p_updated_by,
                    updated_at = NOW(),
                    code = p_data_docente->>'code',
                    limit_assigned_questions = v_limit_assigned_questions,
                    fl_unlimit_questions = (p_data_docente->>'fl_unlimit_questions')::BOOLEAN,
                    goal  = (p_data_docente->>'goal')::smallint,
                    level_id = (p_data_docente->>'level')::smallint,
                    lot = (p_data_docente->>'lot')::smallint
                WHERE uuid = p_uuid;

                v_new_course_ids := ARRAY(SELECT jsonb_array_elements_text(p_data_docente->'course_id')::bigint);

                -- Eliminar los curso que no encuentra
                UPDATE odiseo.employee_course
                SET fl_status = false, deleted_by = p_updated_by, deleted_at = now()
                WHERE teacher_id = v_id_employee
                AND course_id NOT IN (SELECT unnest(v_new_course_ids));

                -- Consultar los IDs existentes en odiseo.employee_course
                v_existing_course_ids := ARRAY(
                    SELECT course_id
                    FROM odiseo.employee_course
                    WHERE course_id = ANY(v_new_course_ids)
                    AND teacher_id = v_id_employee
                    AND fl_status = true
                );

                -- Eliminar los IDs existentes de la lista de nuevos IDs
                v_new_course_ids := ARRAY(
                    SELECT unnest(v_new_course_ids)
                    EXCEPT
                    SELECT unnest(v_existing_course_ids)
                );

                -- Insertar los nuevos IDs que no están en la tabla
                FOREACH v_course_id IN ARRAY v_new_course_ids
                LOOP
                    INSERT INTO odiseo.employee_course (teacher_id, course_id, created_by, created_at)
                    VALUES (v_id_employee, v_course_id, p_updated_by, now());
                END LOOP;

                SELECT array_agg(ec.course_id)
                INTO v_courses_delete
                FROM odiseo.employee_course ec
                WHERE ec.teacher_id = v_id_employee
                AND ec.fl_status = false;

                IF array_length(v_courses_delete, 1) IS NOT NULL THEN
                    SELECT array_agg(eq.question_id)
                    INTO v_question_ids
                    FROM odiseo.employee_question eq
                    INNER JOIN odiseo.question q ON eq.question_id = q.id
                    WHERE eq.teacher_id = v_id_employee
                    AND q.status IN ('ASIG', 'RESO')
                    AND q.course_id = ANY(v_courses_delete)
                    AND eq.fl_status = true
                    AND q.fl_status = true;

                    IF array_length(v_question_ids, 1) IS NOT NULL THEN
                        UPDATE odiseo.employee_question
                        SET fl_status = false, deleted_by = 1, deleted_at = now()
                        WHERE question_id = ANY(v_question_ids)
                        AND teacher_id = v_id_employee;

                        UPDATE odiseo.question
                        SET status = 'SASI', updated_by = p_updated_by, updated_at = now()
                        WHERE id = ANY(v_question_ids)
                        AND fl_status = true;
                    END IF;
                END IF;

                -- Devolver el ID del empleado
                RETURN QUERY
                SELECT v_id_employee, v_question_ids;
            END;
            $$;


ALTER FUNCTION odiseo.update_data_employee(p_uuid uuid, p_charge_id bigint, p_first_name character varying, p_first_surname character varying, p_second_surname character varying, p_type_document_id integer, p_document character varying, p_email character varying, p_phone character varying, p_updated_by integer, p_data_docente jsonb) OWNER TO postgres;

--
-- Name: update_data_employee(uuid, bigint, character varying, character varying, character varying, integer, character varying, character varying, character varying, jsonb, integer, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.update_data_employee(p_uuid uuid, p_charge_id bigint, p_first_name character varying, p_first_surname character varying, p_second_surname character varying, p_type_document_id integer, p_document character varying, p_email character varying, p_phone character varying, p_course_ids jsonb, p_updated_by integer, p_data_docente jsonb) RETURNS TABLE(v_id_employee bigint, v_question_ids integer[])
    LANGUAGE plpgsql
    AS $$
            DECLARE
                v_id_employee BIGINT;
                v_charge_id BIGINT;
                v_course_id BIGINT;
                v_new_course_ids BIGINT[];
                v_existing_course_ids BIGINT[];
                v_limit_assigned_questions INTEGER;
                v_courses_delete BIGINT[];
                v_question_ids INT[];
            BEGIN

               v_limit_assigned_questions := (p_data_docente->>'goal')::smallint + ((p_data_docente->>'goal')::smallint)/2;

                -- Obtener ID del empleado y ID del cargo
                SELECT id, charge_id
                INTO v_id_employee, v_charge_id
                FROM employees e
                WHERE e.uuid = p_uuid;

                UPDATE employees
                SET charge_id = p_charge_id,
                    first_name = p_first_name,
                    first_surname = p_first_surname,
                    second_surname = p_second_surname,
                    type_document_id = p_type_document_id,
                    document = p_document,
                    email = p_email,
                    phone = p_phone,
                    updated_by = p_updated_by,
                    updated_at = NOW(),
                    code = p_data_docente->>'code',
                    limit_assigned_questions = v_limit_assigned_questions,
                    fl_unlimit_questions = (p_data_docente->>'fl_unlimit_questions')::BOOLEAN,
                    goal  = (p_data_docente->>'goal')::smallint,
                    level_id = (p_data_docente->>'level')::smallint,
                    lot = (p_data_docente->>'lot')::smallint,
                    fl_resolve_missing_questions = (p_data_docente->>'fl_resolve_missing_questions')::BOOLEAN,
                    limit_missing_questions = (p_data_docente->>'missing_questions_lot')::smallint
                WHERE uuid = p_uuid;

                v_new_course_ids := ARRAY(SELECT jsonb_array_elements_text(p_course_ids)::bigint);

                -- Eliminar los curso que no encuentra
                UPDATE employee_course
                SET fl_status = false, deleted_by = p_updated_by, deleted_at = now()
                WHERE teacher_id = v_id_employee
                AND course_id NOT IN (SELECT unnest(v_new_course_ids));

                -- Consultar los IDs existentes en employee_course
                v_existing_course_ids := ARRAY(
                    SELECT course_id
                    FROM employee_course
                    WHERE course_id = ANY(v_new_course_ids)
                    AND teacher_id = v_id_employee
                    AND fl_status = true
                );

                -- Eliminar los IDs existentes de la lista de nuevos IDs
                v_new_course_ids := ARRAY(
                    SELECT unnest(v_new_course_ids)
                    EXCEPT
                    SELECT unnest(v_existing_course_ids)
                );

                -- Insertar los nuevos IDs que no están en la tabla
                FOREACH v_course_id IN ARRAY v_new_course_ids
                LOOP
                    INSERT INTO employee_course (teacher_id, course_id, created_by, created_at)
                    VALUES (v_id_employee, v_course_id, p_updated_by, now());
                END LOOP;

                SELECT array_agg(ec.course_id)
                INTO v_courses_delete
                FROM employee_course ec
                WHERE ec.teacher_id = v_id_employee
                AND ec.fl_status = false;

                IF array_length(v_courses_delete, 1) IS NOT NULL THEN
                    SELECT array_agg(eq.question_id)
                    INTO v_question_ids
                    FROM employee_question eq
                    INNER JOIN question q ON eq.question_id = q.id
                    WHERE eq.teacher_id = v_id_employee
                    AND q.status IN ('ASIG', 'RESO')
                    AND q.course_id = ANY(v_courses_delete)
                    AND eq.fl_status = true
                    AND q.fl_status = true;

                    IF array_length(v_question_ids, 1) IS NOT NULL THEN
                        UPDATE employee_question
                        SET fl_status = false, deleted_by = 1, deleted_at = now()
                        WHERE question_id = ANY(v_question_ids)
                        AND teacher_id = v_id_employee;

                        UPDATE question
                        SET status = 'SASI', updated_by = p_updated_by, updated_at = now()
                        WHERE id = ANY(v_question_ids)
                        AND fl_status = true;
                    END IF;
                END IF;

                -- Devolver el ID del empleado
                RETURN QUERY
                SELECT v_id_employee, v_question_ids;
            END;
            $$;


ALTER FUNCTION odiseo.update_data_employee(p_uuid uuid, p_charge_id bigint, p_first_name character varying, p_first_surname character varying, p_second_surname character varying, p_type_document_id integer, p_document character varying, p_email character varying, p_phone character varying, p_course_ids jsonb, p_updated_by integer, p_data_docente jsonb) OWNER TO postgres;

--
-- Name: update_image_digitalized_by_id(bigint, bigint, jsonb); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.update_image_digitalized_by_id(p_id bigint, p_created_by bigint, p_image jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
                DECLARE 
                    v_employee_didi_question_id INT;
                    v_image JSONB;
                    v_code TEXT;
                    v_extension TEXT;
                    v_image_data TEXT;
                BEGIN
                    -- Obtener el ID de employee_didi_question
                    SELECT edq.id
                    INTO v_employee_didi_question_id
                    FROM odiseo.employee_didi_question edq
                    WHERE edq.question_id = p_id;

                    -- Iterar sobre cada elemento en el JSONB array
                    FOR v_image IN SELECT * FROM jsonb_array_elements(p_image)
                    LOOP
                        -- Extraer los valores del JSONB
                        v_code := v_image->>'code';
                        v_extension := v_image->>'extension';
                        v_image_data := v_image->>'image';

                        -- Insertar en employee_didi_question_image
                        INSERT INTO odiseo.employee_didi_question_image (
                            employee_didi_question_id,
                            code,
                            "extension",
                            image,
                            created_by,
                            created_at
                        ) VALUES (
                            v_employee_didi_question_id,
                            v_code,
                            v_extension,
                            v_image_data,
                            p_created_by,
                            NOW()
                        );
                    END LOOP;
                END;
                $$;


ALTER FUNCTION odiseo.update_image_digitalized_by_id(p_id bigint, p_created_by bigint, p_image jsonb) OWNER TO postgres;

--
-- Name: update_material_configuration_details(integer, integer, integer, text, integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.update_material_configuration_details(p_type_material_template_id integer, p_material_configuration_detail_id integer, p_company_id integer, p_value text, p_exam_area_id integer, p_user integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            v_material_configuration_detail_value_id INT;
            v_template_type_material_configuration_id INT;
        BEGIN
            -- Verificar si ya existe un detalle de configuración con los parámetros dados
            SELECT mcdv.id
            INTO v_material_configuration_detail_value_id
            FROM odiseo.material_configuration_detail_value mcdv
            JOIN odiseo.template_type_material_configurations ttmc
            ON mcdv.template_type_material_configuration_id = ttmc.id
            WHERE ttmc.type_material_template_id = p_type_material_template_id
            AND ttmc.company_id = p_company_id
            AND (p_exam_area_id IS NULL OR  ttmc.exam_area_id = p_exam_area_id )
            AND mcdv.material_configuration_detail_id = p_material_configuration_detail_id
            AND mcdv.fl_status = TRUE;

            -- Si no existe, insertar
            IF v_material_configuration_detail_value_id IS NULL THEN
                -- Obtener el ID de la configuración de la plantilla de material
                SELECT ttmc.id
                INTO v_template_type_material_configuration_id
                FROM odiseo.template_type_material_configurations ttmc
                WHERE ttmc.type_material_template_id = p_type_material_template_id
                AND (p_exam_area_id IS NULL OR  ttmc.exam_area_id = p_exam_area_id )
                AND ttmc.company_id = p_company_id
                AND ttmc.fl_status = TRUE;

                -- Si no existe, insertar nueva configuración
                IF v_template_type_material_configuration_id IS NULL THEN
                    INSERT INTO odiseo.template_type_material_configurations
                        (type_material_template_id, exam_area_id,company_id, created_by, created_at)
                    VALUES
                        (p_type_material_template_id, p_exam_area_id,p_company_id, p_user, now())
                    RETURNING id INTO v_template_type_material_configuration_id;
                END IF;

                -- Insertar un nuevo detalle de configuración
                INSERT INTO odiseo.material_configuration_detail_value
                    (material_configuration_detail_id, template_type_material_configuration_id, value, created_by, created_at)
                VALUES
                    (p_material_configuration_detail_id, v_template_type_material_configuration_id, p_value, p_user, now());

            ELSE
                -- Si ya existe, actualizar el valor
                UPDATE odiseo.material_configuration_detail_value
                SET value = p_value, updated_by = p_user, updated_at = now()
                WHERE id = v_material_configuration_detail_value_id;
            END IF;

        END;
        $$;


ALTER FUNCTION odiseo.update_material_configuration_details(p_type_material_template_id integer, p_material_configuration_detail_id integer, p_company_id integer, p_value text, p_exam_area_id integer, p_user integer) OWNER TO postgres;

--
-- Name: update_user_id_employee(integer, integer); Type: FUNCTION; Schema: odiseo; Owner: postgres
--

CREATE FUNCTION odiseo.update_user_id_employee(p_employee_id integer, p_user_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
            BEGIN
                UPDATE odiseo.employees
                SET user_id = p_user_id
                WHERE id = p_employee_id;
            END;
            $$;


ALTER FUNCTION odiseo.update_user_id_employee(p_employee_id integer, p_user_id integer) OWNER TO postgres;

--
-- Name: fn_get_type_documents(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_type_documents() RETURNS TABLE(id bigint, document character varying, description character varying, created_by bigint, updated_by bigint, created_at timestamp without time zone, updated_at timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
        BEGIN
            RETURN QUERY
            SELECT *
            FROM type_documents td;
        END;
        $$;


