--
-- Name: TABLE employees; Type: SECURITY LABEL; Schema: odiseo; Owner: postgres
--

SECURITY LABEL FOR anon ON COLUMN odiseo.employees.first_surname IS 'MASKED WITH FUNCTION anon.fake_last_name()';
SECURITY LABEL FOR anon ON COLUMN odiseo.employees.second_surname IS 'MASKED WITH FUNCTION anon.fake_last_name()';
SECURITY LABEL FOR anon ON COLUMN odiseo.employees.document IS 'MASKED WITH FUNCTION anon.partial(document, 3, ''XXXXX'', 0)';
SECURITY LABEL FOR anon ON COLUMN odiseo.employees.email IS 'MASKED WITH FUNCTION anon.fake_email()';
SECURITY LABEL FOR anon ON COLUMN odiseo.employees.phone IS 'MASKED WITH FUNCTION anon.partial(phone, 2, $$X-XXX-XX$$, 2)';


